<template>
    <div>
        <!-- Color preset -->
        <div class="flex gap-[9px] flex-wrap mb-3.5">
            <div v-for="(preset, index) in colorPresets" :key="index"
                class="border border-default rounded-full w-[30px] h-[30px] cursor-pointer hover:border-hover transition"
                :style="preset.style" @click="value = preset" />
        </div>
        <!-- Preview -->
        <div class="w-full h-24 mb-4 rounded shadow-gradient-preview"
            :class="{ 'bg-white  ': !positionsValidSorted.length }" :style="preview('')" />
        <!-- Color stop -->
        <div class="relative">
            <div class="text-xs font-[450] mb-2.5">Color stop</div>
            <div class="relative w-full h-6 mb-2.5 shadow-[inset_0_0_2px_1px_#939393] cursor-pointer rounded-2xl"
                @click="addColorStop">
                <div class="color-slider z-50 color-slider-horizontal rounded-2xl" :style="preview()">
                    <div ref="range">
                        <div v-for="pos in value.positions" :key="pos.index"
                            :style="{ left: `calc(${pos.index * 204 / 100}px)` }"
                            class="item absolute top-1/2 transform -translate-y-1/2 translate-x-1 w-4 h-4 border-2 border-white bg-transparent flex items-center justify-center rounded-full"
                            :class="[
                                selected == pos
                                    ? (isMove ? 'cursor-grabbing ' : 'cursor-pointer ') +
                                    'ring-2 ring-primary-500 z-1'
                                    : 'cursor-pointer',
                                { 'bg-empty': !pos.color }
                            ]" :data-tooltip="$t('click_to_select_color')" @mousedown="mouseDownItem(pos, $event)"
                            @click="openColorModal = true; this.$store.commit('builder/setIsPopupOpen', true)">
                            <span v-if="selected == pos"
                                class="absolute -bottom-3 left-1/2 transform -translate-x-1/2 p-0.5 rounded-full bg-primary-500" /><template
                                v-else />
                        </div>
                    </div>
                </div>
            </div>
            <BackDrop v-if="openColorModal" @click="openColorModal = false" class="outside-close-cursor"></BackDrop>
            <Teleport to="body" v-if="openColorModal">
                <transition enter-active-class="transition duration-200 ease-out"
                    enter-from-class="translate-y-1 opacity-0" enter-to-class="translate-y-0 opacity-100"
                    leave-active-class="transition duration-150 ease-in" leave-from-class="translate-y-0 opacity-100"
                    leave-to-class="translate-y-1 opacity-0">
                    <div
                        class="z-[62] fixed ecom-fields__popup rounded-xl translate-y-2 bg-white"
                        :id="idTeleport"
                        :style="{
                            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
                            top: popupColorPosition.top,
                            left: popupColorPosition.left,
                            bottom: popupColorPosition.bottom
                        }"
                    >
                        <Solid 
                            class="relative z-[2]" 
                            :value="selected.color" :global="{ type: 'colors' }"
                            :global-selected="selected?.color?.['global-colors']" @refeshColor="updateColor('')"
                            @update:value="updateColor($event)"
                            @update:global-selected="updateColor({ 'global-colors': $event })"
                            @update:delete="deleteColor" />
                    </div>
                </transition>
            </Teleport>
        </div>
        <div class="flex gap-2 mb-2 mt-4 w-full">
            <button class="border border-gray-200 rounded px-3 py-1 text-xs w-1/2 text-text-primary"
                :class="{ 'bg-primary !text-white': value.type === 'linear' }"
                @click="value.type = 'linear'">Linear</button>
            <button class="border border-gray-200 rounded px-3 py-1 text-xs w-1/2 text-text-primary"
                :class="{ 'bg-primary !text-white': value.type === 'radial' }"
                @click="value.type = 'radial'">Radial</button>
        </div>
        <!-- Color angle -->
        <div v-if="value.type == 'linear'">
            <div class="flex items-center w-full slider-number-wrp mb-2.5">
                <Number 
                    :data="value?.angle" 
                    @update:data="value.angle = $event" 
                    :field="angleField"
                    @update:delete="resetDataAngle"
                 />
            </div>
        </div>
        <!-- Color position -->
        <div v-if="value.type == 'radial'">
            <div class="text-xs font-[450] mb-1">Position</div>
            <div class="relative group">
                <select
                    class="w-full cursor-pointer border rounded-lg py-1.5 px-3 bg-white text-[13px] leading-5 font-[450]"
                    v-model="value.position">
                    <option v-for="(item, index) in positions" :value="item.id">{{ item.title }}</option>
                </select>
                <span class="absolute pointer-events-none top-2 right-3 flex items-center text-gray-500">
                    <Ecom-Icon :source="selectInputIcon" size="w-5"
                        color="text-icon-secondary group-hover:text-gray-600 transition" class="flex items-center" />
                </span>
            </div>
        </div>
    </div>
</template>
<script>
import { convertGradient } from "@/components/Builder/Helpers/Css";
import { selectInputIcon } from '@/assets/icons';
import Number from '../Spacing/Number.vue';
//import Solid from "./SolidColor.vue";
import Solid from '@/plugins/fields/components/molecules/ColorPicker/ColorPanel.vue';

export default {
    components: {
        Solid, Number
    },
    props: {
        data: {
            type: Object,
            default: () => ({})
        }
    },
    data() {
        return {
            popupColorPosition: { top: 0, left: '0px', bottom: 0 },
            idTeleport: "popup-gradient" + Date.now() + Math.random().toString(36).substr(2, 9),
            mutationObserver: null,
            popupElement: null,
            popupDimensions: { width: 265, height: 467 },
            value: {
                positions: [{ index: 0, color: "" }],
                type: 'linear',
                position: 'center center'
            },
            openColorModal: false,
            selectInputIcon,
            selected: null,
            positions: [
                {
                    id: 'center left',
                    title: 'Center left'
                },
                {
                    id: 'center center',
                    title: 'Center center'
                },
                {
                    id: 'center right',
                    title: 'Center right'
                },
                {
                    id: 'top left',
                    title: 'Top left'
                },
                {
                    id: 'top center',
                    title: 'Top center'
                },
                {
                    id: 'top right',
                    title: 'Top right'
                },
                {
                    id: 'bottom left',
                    title: 'Bottom left'
                },
                {
                    id: 'bottom center',
                    title: 'Bottom center'
                },
                {
                    id: 'bottom right',
                    title: 'Bottom right'
                }
            ],
            angleField: {
                label: 'Color angle',
                options: {
                    units: {
                        '': {
                            min: 0,
                            max: 360,
                            step: 1
                        }
                    },
                    default: 0
                }
            },
            colorPresets: [
                {
                style: "background: linear-gradient(135deg, #49f007 1%, #9D6A6C 33.33%, #49f007 65.67%, #49f007 67.67%, #9D6A6C 99%);",
                    positions: [
                        { index: 1, color: "#49f007" },
                        { index: 33.33, color: "#9D6A6C" },
                        { index: 65.67, color: "#49f007" },
                        { index: 67.67, color: "#49f007" },
                        { index: 99, color: "#9D6A6C" }
                    ],
                    angle: 135,
                    type: 'linear'
                },
                {
                style: "background: linear-gradient(135deg, #0575E6 1%, #00FF65 33.33%, #0575E6 65.67%, #0575E6 67.67%, #00FF65 99%);",
                    positions: [
                        { index: 1, color: "#0575E6" },
                        { index: 33.33, color: "#00FF65" },
                        { index: 65.67, color: "#0575E6" },
                        { index: 67.67, color: "#0575E6" },
                        { index: 99, color: "#00FF65" }
                    ],
                    angle: 135,
                    type: 'linear'
                },
                {
                style: "background: linear-gradient(135deg, #f00c0c 1%, #6C6D99 33.33%, #f00c0c 65.67%, #f00c0c 67.67%, #6C6D99 99%);",
                    positions: [
                        { index: 1, color: "#f00c0c" },
                        { index: 33.33, color: "#6C6D99" },
                        { index: 65.67, color: "#f00c0c" },
                        { index: 67.67, color: "#f00c0c" },
                        { index: 99, color: "#6C6D99" }
                    ],
                    angle: 135,
                    type: 'linear'
                },
                {
                    style: "background: linear-gradient(180deg, #3E9E54 0%, #17371D 100%);",
                    positions: [
                        { index: 0, color: "#3E9E54" },
                        { index: 100, color: "#17371D" }
                    ],
                    angle: 180,
                    type: 'linear'
                },
                {
                    style: "background: linear-gradient(180deg, #4A1416 0%, #B82F36 100%);",
                    positions: [
                        { index: 0, color: "#4A1416" },
                        { index: 100, color: "#B82F36" }
                    ],
                    angle: 180,
                    type: 'linear'
                },
                {
                    style: "background: linear-gradient(180deg, #874D97 0%, #29182E 100%);",
                    positions: [
                        { index: 0, color: "#874D97" },
                        { index: 100, color: "#29182E" }
                    ],
                    angle: 180,
                    type: 'linear'
                }
            ],
            isMove: false,
        };
    },
    computed: {
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        positionsSorted() {
            let poss = this.$helpers.copy(this.value.positions);
            poss.sort((a, b) => a.index - b.index);
            return poss;
        },
        positionsValidSorted() {
            let poss = this.$helpers.copy(this.positionsSorted);
            return poss.filter((pos) => pos.color);
        },
        output() {
            if (this.positionsValidSorted?.length > 0) {
                // eslint-disable-next-line no-unused-vars
                let { positions, ...agrs } = this.value;
                return {
                    positions: this.positionsValidSorted,
                    ...agrs
                };
            }
            return {};
        },
        hasAdd() {
            return this.positionsSorted.length < 10;
        },
    },
    methods: {
        preview(type = "linear") {
            let output = this.$helpers.copy(this.output);
            if (type == "linear") {
                output.type = "linear";
                output.angle = 90;
            }
            return convertGradient(output);
        },
        addColorStop(e) {
            this.isOpenPopupColor(e);
            if (e.target.closest(".item:not(.ecom-group-item)")) {
                return;
            }
            this.openColorModal = true;
            this.$store.commit("builder/setIsPopupOpen", true);
            let { x } = e,
                target = e.target,
                targetRect = target.getBoundingClientRect(),
                targetWidth = target.offsetWidth,
                percent = Math.round(((x - targetRect.x) / targetWidth) * 100);
            this.addNewColor(percent);
        },
        addNewColor(index, color = "") {
            if (!this.hasAdd) {
                return;
            }
            if (this.value.positions.length < 10) {
                let newItem = {
                    index,
                    color
                };
                this.selected = newItem;
                this.value.positions = this.value.positions.filter((pos) => pos.color != "");
                this.value.positions.push(newItem);
                this.showPicker = true;
                this.$store.commit("builder/setIsPopupOpen", true);
            }
        },
        mouseDownItem(pos, e) {
            this.isMove = false;
            this.selected = pos;
            this.x = e.x;
            document.onmousemove = this.mouseMove;
            document.onmouseup = this.mouseUp;
        },
        mouseMove(e) {
            if (Math.abs(this.x - e.x) > 3) {
                this.showPicker = false;
                this.isMove = true;
                let { x } = e;
                let rangeWidth = this.inputRange.offsetWidth,
                    rangeRect = this.inputRange.getBoundingClientRect();
                let per = Math.round(((x - rangeRect.x) / rangeWidth) * 100);
                if (this.selected) {
                    this.selected.index = this.intBetween(per, 0, 100);
                }
            }
        },
        mouseUp() {
            if (!this.isMove) {
                this.showPicker = true;
            }
            document.onmousemove = null;
            document.onmouseup = null;
            this.isMove = false;
            (this.x = null), (this.y = null);
        },
        intBetween(num, min, max) {
            if (num === undefined) {
                return num;
            }
            return Math.max(min, Math.min(max, num));
        },
        validValue(value) {
            let v = { positions: [] };
            ["first", "second"].forEach((t) => {
                if (value[t + "-color"]) {
                    v.positions.push({
                        index: value[t + "-location"] ?? 0,
                        color: value[t + "-color"]
                    });
                }
            });
            ["type", "angle", "position", "positions"].forEach((t) => {
                if (value[t]) {
                    v[t] = value[t];
                }
            });
            return v;
        },
        deleteColor() {
            let i = this.value.positions.findIndex((pos) => pos === this.selected);
            this.value.positions.splice(i, 1);
            this.showPicker = false;
        },
        updateColor(color) {
            if (this.selected) {
                this.selected.color = color;
            } else {
                let newItem = {
                    index: 0,
                    color
                };
                this.selected = newItem;
                this.value.positions.push(newItem);
            }
        },
        startObservingPopup() {
            this.stopObservingPopup();

            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === Node.ELEMENT_NODE) {
                                const element = node;
                                if (element.id === this.idTeleport) {
                                    this.popupElement = element;
                                    this.isOpenPopupColor(element);
                                    requestAnimationFrame(() => {
                                        this.updatePopupDimensions();
                                        this.isOpenPopupColor(element);
                                    });
                                }
                            }
                        });
                    }
                });
            });

            this.mutationObserver.observe(document.body, {
                childList: true,
                subtree: true
            });
        },
        stopObservingPopup() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },
        updatePopupDimensions() {
            if (this.popupElement) {
                this.popupDimensions = {
                    width: this.popupElement.offsetWidth || 267,
                    height: this.popupElement.offsetHeight || 468
                };
            }
        },
        isOpenPopupColor(event) {


            const targetElement = (event.target || event);
            if (!targetElement?.getBoundingClientRect) {
                return;
            }
            const range = targetElement.closest('.color-slider');

            if(!range) return;

            const rect = range.getBoundingClientRect();

            this.$nextTick(() => {
                const popupWidth = this.popupDimensions.width;
                const popupHeight = this.popupDimensions.height;

                const distanceToBottom = window.innerHeight - rect.top - rect.height;

                const fixedSelected = targetElement.closest('.ecom-library-popup') || targetElement.closest('.popup-container') || targetElement.closest('.fixed') || targetElement.closest('.absolute') || targetElement.closest('.relative') ;
                let left;
                if(fixedSelected) {
                    const fixedRect = fixedSelected.getBoundingClientRect();
                    const leftFixed = fixedRect.left;
                    const selectedWidth = fixedRect.width;
                    const distanceToRight = window.innerWidth - leftFixed - selectedWidth;

                    if(leftFixed >= popupWidth) {
                        const spaceRectToFixedRect = rect.left - leftFixed;
                        if(spaceRectToFixedRect > 50) {
                            left = rect.left - popupWidth - 20;
                        }else {
                            left = leftFixed - popupWidth;
                        }
                    }else if(distanceToRight >=  popupWidth) {
                        left = leftFixed + selectedWidth;
                    }else {
                        left = rect.left + rect.width;
                    }
                }else {
                    left = rect.left + rect.width;
                }

                let top, bottom;
                const fixedPopupGetter = targetElement.closest('.ecom-fields__background');
                const containerFly = targetElement.closest('.ecom-library-popup') || targetElement.closest('.popup-container');
                let bottomFixedSpace = 0;
                if(fixedPopupGetter) bottomFixedSpace = window.innerHeight - fixedPopupGetter.getBoundingClientRect().top;

                if(fixedPopupGetter && !containerFly && bottomFixedSpace >= popupHeight) {
                    top = fixedPopupGetter.getBoundingClientRect().top + window.scrollY + "px";
                    bottom = 'auto';
                }else if (distanceToBottom >= popupHeight) {
                    top = (rect.bottom + window.scrollY - rect.height - 15) + "px";
                    bottom = 'auto';
                } else {
                    top = (rect.bottom + window.scrollY) - (popupHeight - distanceToBottom) + "px";
                    bottom = 'auto';
                }

                this.popupColorPosition = {
                    top,
                    left: left + 'px',
                    bottom
                };
            });
        },
        resetDataAngle(val) {
            if (this.value) {
                this.value.angle = 0;
            }
        }
    },
    watch: {
        data: {
            deep: true,
            immediate: true,
            handler(val) {
                val = val.gradient
                
                if (val && JSON.stringify(val) !== JSON.stringify(this.output)) {
                    this.value = this.validValue(val);
                    this.selected = this.value.positions?.[0];
                } else if (!this.selected) {
                    this.selected = this.value.positions?.[0];
                }
            }
        },
        output: {
            deep: true,
            handler(val) {
                this.$emit("update", val);
            }
        },
        isPopupOpen(val) {
            if(val === false) {
                this.showPicker = false;
                this.openColorModal = false;
            }
        }
    },
    mounted() {
        this.inputRange = this.$refs["range"];
    }
};
</script>
