// SelectionResizeHandler.ts
import type {
  GridLayoutInstance,
  SelectionResizeOptions,
  SelectionResizeEvents,
  SelectionResizeEventData,
  SelectionResizeState
} from './SelectionTypes';
import { ensureNumericValue, isPercentWidth, handleSetHistorySelection } from '../../helpers/utils';

export class SelectionResizeHandler {
  private instance: GridLayoutInstance;
  private options: SelectionResizeOptions;
  private events: SelectionResizeEvents;
  private resizeState: SelectionResizeState;
  private _resizeMoveHandler: ((e: MouseEvent) => void) | null = null;
  private _resizeEndHandler: ((e: MouseEvent) => void) | null = null;

  constructor(instance: GridLayoutInstance, options: SelectionResizeOptions = {}, events: SelectionResizeEvents = {}) {
    this.instance = instance;
    this.options = {
      enableResize: true,
      resizeHandles: true,
      maintainAspectRatio: false,
      minSize: { width: 10, height: 10 },
      ...options
    };
    this.events = events;

    this.resizeState = {
      isResizingSelection: false,
      isResizingSelectionMove: false,
      selectionResizeStart: { x: 0, y: 0 },
      selectionResizeType: "",
      selectionResizeInitial: {
        minX: 0,
        minY: 0,
        maxX: 0,
        maxY: 0
      },
      selectionResizeRatio: 1,
      lastMouseX: 0,
      lastMouseY: 0,
      isResizingSelectionFlag: false,
      selectionRatio: false
    };

    this.bindMethods();
  }

  private bindMethods(): void {
    this.startSelectionResize = this.startSelectionResize.bind(this);
    this.handleSelectionResize = this.handleSelectionResize.bind(this);
    this.endSelectionResize = this.endSelectionResize.bind(this);
  }

  // Sync state with instance
  public syncStateToInstance(): void {
    this.instance.isResizingSelection = this.resizeState.isResizingSelection;
    this.instance.isResizingSelectionMove = this.resizeState.isResizingSelectionMove;
    this.instance.selectionResizeStart = this.resizeState.selectionResizeStart;
    this.instance.selectionResizeType = this.resizeState.selectionResizeType;
    this.instance.selectionResizeInitial = this.resizeState.selectionResizeInitial;
    this.instance.selectionResizeRatio = this.resizeState.selectionResizeRatio;
    this.instance.lastMouseX = this.resizeState.lastMouseX;
    this.instance.lastMouseY = this.resizeState.lastMouseY;
    this.instance.isResizingSelectionFlag = this.resizeState.isResizingSelectionFlag;
    this.instance.selectionRatio = this.resizeState.selectionRatio;
  }

  public syncStateFromInstance(): void {
    this.resizeState.isResizingSelection = this.instance.isResizingSelection;
    this.resizeState.isResizingSelectionMove = this.instance.isResizingSelectionMove;
    this.resizeState.selectionResizeStart = this.instance.selectionResizeStart;
    this.resizeState.selectionResizeType = this.instance.selectionResizeType;
    this.resizeState.selectionResizeInitial = this.instance.selectionResizeInitial;
    this.resizeState.selectionResizeRatio = this.instance.selectionResizeRatio;
    this.resizeState.lastMouseX = this.instance.lastMouseX;
    this.resizeState.lastMouseY = this.instance.lastMouseY;
    this.resizeState.isResizingSelectionFlag = this.instance.isResizingSelectionFlag;
    this.resizeState.selectionRatio = this.instance.selectionRatio;
  }

  public canStartResize(e: MouseEvent, type: string): boolean {
    if (!this.options.enableResize) return false;
    if (!this.instance.hasSelection || this.instance.selectedItems.length < 2) return false;

    // Kiểm tra xem có click vào resize handle không
    const isClickOnHandle = (e.target as HTMLElement).closest(".ecom-selection-resizable-handle") !== null;
    return isClickOnHandle;
  }

  public startSelectionResize(e: MouseEvent, type: string): void {
    if (!this.canStartResize(e, type)) return;

    // Sync state từ instance
    this.syncStateFromInstance();

    // Cập nhật selection area và borders
    this.instance.updateSelectionAreaFromItems();
    this.instance.updateSelectionBorders();
    this.syncStateFromInstance();

    this.resizeState.isResizingSelectionFlag = true;
    this.resizeState.selectionResizeType = type;

    // Lưu vị trí chuột ban đầu
    const rect = this.instance.$refs.item.getBoundingClientRect();
    this.resizeState.selectionResizeStart = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };

    // Lưu kích thước và vị trí ban đầu của selection
    this.resizeState.selectionResizeInitial = JSON.parse(JSON.stringify(this.instance.selectionArea));

    // Lưu vị trí ban đầu của tất cả các items
    this.instance.selectedItemsInitialPos = this.instance.selectedItems.map((item) => ({
      i: item.i,
      left: ensureNumericValue(item.left),
      top: ensureNumericValue(item.top),
      width: item.width, // Giữ nguyên định dạng gốc
      height: ensureNumericValue(item.height)
    }));

    // Kiểm tra xem có item nào cần maintain aspect ratio không
    this.resizeState.selectionRatio = this.instance.selectedItems.some(item =>
      item.options?.ratioSize || this.options.maintainAspectRatio
    );

    // Thêm event listeners
    this.instance.oldSection = JSON.parse(JSON.stringify(this.instance.sections.find((s) => s.id == this.instance.section_id)));

    this.syncStateToInstance();

    const iframeDoc = this.instance.idoc();
    this._resizeMoveHandler = this.handleSelectionResize.bind(this);
    this._resizeEndHandler = this.endSelectionResize.bind(this);
    iframeDoc.addEventListener("mousemove", this._resizeMoveHandler);
    iframeDoc.addEventListener("mouseup", this._resizeEndHandler);

    e.preventDefault();
    e.stopPropagation();

    // Emit event
    const eventData: SelectionResizeEventData = {
      eventType: 'selectionresizestart',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      resizeType: type,
      scaleX: 1,
      scaleY: 1,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onResizeStart) {
      this.events.onResizeStart(eventData);
    }
  }

  public handleSelectionResize(e: MouseEvent): void {
    if (this.instance.editorConfigs.locked) {
      this.instance.$store.commit("builder/setShowNoticeLockmode", true);
      return;
    }

    this.resizeState.isResizingSelection = true;
    if (!this.resizeState.isResizingSelection) return;

    const rect = this.instance.$refs.item.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Tính delta từ vị trí ban đầu
    const totalDeltaX = mouseX - this.resizeState.selectionResizeStart.x;
    const totalDeltaY = mouseY - this.resizeState.selectionResizeStart.y;

    // Lưu vị trí chuột hiện tại
    this.resizeState.lastMouseX = mouseX;
    this.resizeState.lastMouseY = mouseY;

    // Lấy kích thước container
    const containerWidth = rect.width / this.instance.scaleRatio;
    const containerHeight = this.instance.$refs.item.offsetHeight;

    // Hệ số giảm tốc để chuyển động mượt mà hơn
    const dampingFactor = 1.0;
    const scaledDeltaX = totalDeltaX * dampingFactor;
    const scaledDeltaY = totalDeltaY * dampingFactor;

    // Chuyển delta X từ pixel sang phần trăm
    const deltaXPercent = ((scaledDeltaX / containerWidth) * 100) / this.instance.scaleRatio;

    // Tính toán kích thước ban đầu của selection area
    const initialWidth =
      (this.resizeState.selectionResizeInitial.maxX - this.resizeState.selectionResizeInitial.minX) /
      this.instance.scaleRatio;
    const initialHeight =
      (this.resizeState.selectionResizeInitial.maxY - this.resizeState.selectionResizeInitial.minY) /
      this.instance.scaleRatio;

    // Tính toán tỷ lệ thay đổi kích thước dựa trên loại resize
    let newWidth = initialWidth;
    let newHeight = initialHeight;
    let offsetX = 0;
    let offsetY = 0;

    // Xác định hệ số scale và offset dựa trên loại resize
    switch (this.resizeState.selectionResizeType) {
      case "n": // Resize từ trên xuống
        newHeight = initialHeight - scaledDeltaY;
        offsetY = scaledDeltaY;
        break;
      case "s": // Resize từ dưới lên
        newHeight = initialHeight + scaledDeltaY;
        break;
      case "e": // Resize từ phải sang
        newWidth = initialWidth + deltaXPercent;
        break;
      case "w": // Resize từ trái sang
        newWidth = initialWidth - deltaXPercent;
        offsetX = deltaXPercent;
        break;
      case "nw": // Resize từ góc trên-trái
        newHeight = initialHeight - scaledDeltaY;
        if (this.resizeState.selectionRatio) {
          const aspectRatio = initialWidth / initialHeight;
          newWidth = newHeight * aspectRatio;
          offsetX = initialWidth - newWidth;
        } else {
          newWidth = initialWidth - deltaXPercent;
          offsetX = deltaXPercent;
        }
        offsetY = initialHeight - newHeight;
        break;
      case "ne": // Resize từ góc trên-phải
        newHeight = initialHeight - scaledDeltaY;
        if (this.resizeState.selectionRatio) {
          const aspectRatio = initialWidth / initialHeight;
          newWidth = newHeight * aspectRatio;
        } else {
          newWidth = initialWidth + deltaXPercent;
        }
        offsetY = initialHeight - newHeight;
        break;
      case "sw": // Resize từ góc dưới-trái
        newWidth = initialWidth - deltaXPercent;
        newHeight = initialHeight + scaledDeltaY;
        offsetX = deltaXPercent;
        break;
      case "se": // Resize từ góc dưới-phải
        newWidth = initialWidth + deltaXPercent;
        newHeight = initialHeight + scaledDeltaY;
        break;
    }

    // Xử lý aspect ratio nếu cần
    if (this.resizeState.selectionRatio) {
      const initialWidth = this.resizeState.selectionResizeInitial.maxX - this.resizeState.selectionResizeInitial.minX;
      const initialHeight = this.resizeState.selectionResizeInitial.maxY - this.resizeState.selectionResizeInitial.minY;
      const aspectRatio = initialWidth / initialHeight;

      const useWidth = this.resizeState.selectionResizeType.includes("e") || this.resizeState.selectionResizeType.includes("w");

      if (useWidth) {
        newHeight = newWidth / aspectRatio;
      } else {
        const calculatedWidth = newHeight * aspectRatio;
        newWidth = calculatedWidth;
      }
    }

    // Đảm bảo kích thước không nhỏ hơn minimum
    newWidth = Math.max(this.options.minSize!.width, newWidth);
    newHeight = Math.max(this.options.minSize!.height, newHeight);

    // Tính tỷ lệ mới
    let scaleX = newWidth / initialWidth;
    let scaleY = newHeight / initialHeight;

    // Đảm bảo tỷ lệ scale không quá nhỏ
    scaleX = Math.max(0.1, scaleX);
    scaleY = Math.max(0.1, scaleY);

    // Boundary checking
    this.applyBoundaryConstraints(scaleX, scaleY, offsetX, offsetY, containerWidth, containerHeight);

    // Áp dụng resize cho các items
    const groupItems: string[] = [];
    let maxY = 0;

    this.instance.selectedItems.forEach((item, index) => {
      const initialPos = this.instance.selectedItemsInitialPos[index];
      if (!initialPos) return;

      // Tính toán vị trí tương đối từ góc trái trên của selection
      const relativeX = initialPos.left - this.resizeState.selectionResizeInitial.minX;
      const relativeY = initialPos.top - this.resizeState.selectionResizeInitial.minY;

      // Áp dụng tỷ lệ scale vào vị trí tương đối
      let newRelativeX = relativeX * scaleX;
      let newRelativeY = relativeY * scaleY;

      // Tính toán vị trí mới sau khi scale
      let newLeft = this.resizeState.selectionResizeInitial.minX + offsetX + newRelativeX;
      let newTop = this.resizeState.selectionResizeInitial.minY + offsetY + newRelativeY;

      // Kiểm tra kiểu width
      const isPercentWidth = typeof initialPos.width === "string" && initialPos.width.includes("%");
      let widthValue;

      if (isPercentWidth) {
        widthValue = parseFloat(initialPos.width as string);
      } else {
        widthValue = ensureNumericValue(initialPos.width);
      }

      // Tính toán kích thước mới sau khi scale
      let newWidth = widthValue * scaleX;
      let newHeight = initialPos.height * scaleY;

      // Đảm bảo các giá trị không quá nhỏ
      if (isPercentWidth) {
        newWidth = Math.max(1, newWidth);
      } else {
        newWidth = Math.max(this.options.minSize!.width, newWidth);
      }
      newHeight = Math.max(this.options.minSize!.height, newHeight);

      // Cập nhật item
      item.left = newLeft;
      item.top = newTop;

      if (isPercentWidth) {
        item.width = `${newWidth}%`;
      } else {
        item.width = newWidth;
      }
      item.height = newHeight;

      // Cập nhật layout
      const layoutItemIndex = this.instance.layout.findIndex((li) => li.i === item.i);
      if (layoutItemIndex !== -1) {
        this.instance.layout[layoutItemIndex].left = newLeft;
        this.instance.layout[layoutItemIndex].top = newTop;
        this.instance.layout[layoutItemIndex].width = item.width;
        this.instance.layout[layoutItemIndex].height = newHeight;
        groupItems.push(this.instance.layout[layoutItemIndex].i);
      }

      // Emit sự kiện để cập nhật grid item trong DOM
      this.instance.eventBus.emit("update-grid-item", {
        id: item.i,
        left: newLeft,
        top: newTop,
        width: isPercentWidth ? `${newWidth}%` : newWidth,
        height: newHeight,
        direction: this.resizeState.selectionResizeType
      });
    });

    // Cập nhật selection area và borders
    this.instance.updateSelectionAreaFromItems();
    this.instance.updateSelectionBorders();

    // Cập nhật height section khi không có min-height
    if (!this.instance.data?.settings?.["min-height"]) {
      this.instance.layout.forEach((item) => {
        if (!groupItems.includes(item.i)) {
          const itemY = item.top + item.height;
          if (itemY > maxY) {
            maxY = itemY;
          }
        }
      });

      if (this.instance.selectionBorders.h[1].y > maxY) {
        this.instance.updateHeight(this.instance.selectionBorders.h[1].y);
      } else if (parseInt(this.instance.$refs.item.style.height) != parseInt(maxY.toString())) {
        this.instance.updateHeight(maxY);
      }
    }

    // Emit event
    const eventData: SelectionResizeEventData = {
      eventType: 'selectionresizemove',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      resizeType: this.resizeState.selectionResizeType,
      scaleX: scaleX,
      scaleY: scaleY,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onResizeMove) {
      this.events.onResizeMove(eventData);
    }
  }

  private applyBoundaryConstraints(scaleX: number, scaleY: number, offsetX: number, offsetY: number, containerWidth: number, containerHeight: number): void {
    // Kiểm tra boundary constraints cho từng item
    let hitRightBound = false;
    let hitLeftBound = false;
    let hitTopBound = false;
    let hitBottomBound = false;

    this.instance.selectedItemsInitialPos.forEach((initialPos) => {
      const relativeX = initialPos.left - this.resizeState.selectionResizeInitial.minX;
      const relativeY = initialPos.top - this.resizeState.selectionResizeInitial.minY;

      const newRelativeX = relativeX * scaleX;
      const newRelativeY = relativeY * scaleY;
      const newLeft = this.resizeState.selectionResizeInitial.minX + offsetX + newRelativeX;
      const newTop = this.resizeState.selectionResizeInitial.minY + offsetY + newRelativeY;

      let newWidthValue;
      const isPercentWidth = typeof initialPos.width === "string" && initialPos.width.includes("%");

      if (isPercentWidth) {
        newWidthValue = parseFloat(initialPos.width as string) * scaleX;
      } else {
        newWidthValue = ensureNumericValue(initialPos.width) * scaleX;
        newWidthValue = (newWidthValue / containerWidth) * 100;
      }

      const newHeightValue = initialPos.height * scaleY;

      // Kiểm tra các giới hạn
      if (newLeft < 0) hitLeftBound = true;
      if (newLeft + newWidthValue > 100) hitRightBound = true;
      if (newTop < 0) hitTopBound = true;
      if (newTop + newHeightValue > containerHeight) hitBottomBound = true;
    });

    // Áp dụng constraints nếu cần (có thể thêm logic điều chỉnh scaleX, scaleY ở đây)
  }

  public endSelectionResize(e: MouseEvent): void {
    this.resizeState.lastMouseX = 0;
    this.resizeState.lastMouseY = 0;

    // Gỡ bỏ event listeners
    const iframeDoc = this.instance.idoc();
    if (this._resizeMoveHandler) {
      iframeDoc.removeEventListener("mousemove", this._resizeMoveHandler);
    }
    if (this._resizeEndHandler) {
      iframeDoc.removeEventListener("mouseup", this._resizeEndHandler);
    }

    if (!this.resizeState.isResizingSelection) return;

    // Add history
    if (this.instance.oldSection) {
      handleSetHistorySelection(
        this.instance.oldSection,
        this.instance.selectedItems.map((item) => item.i),
        this.instance.screen,
        "resized"
      );
    }

    // Đặt lại trạng thái
    this.resizeState.isResizingSelection = false;
    this.resizeState.selectionResizeType = "";

    // Cập nhật layout từ selectedItems
    this.instance.selectedItems.forEach((item) => {
      const gridItem = this.instance.findGridItem(item.i);
      if (gridItem) {
        gridItem.$emit("resized", item.i, item.height, item.width, item.left, item.top);
        gridItem.updateGridSize && gridItem.updateGridSize();
      }
    });

    // Cập nhật thông tin cho GroupSettings
    const topBorderElement = iframeDoc.querySelector(".ecom-selection-active");
    if (topBorderElement) {
      this.instance.eventBus.emit("selectionResizeComplete", {
        el: topBorderElement,
        sectionId: this.instance.section_id
      });
    }

    // Tăng thời gian bảo vệ click để tránh sự kiện click lan truyền
    this.instance.lastSelectionTimestamp = Date.now() + 600;

    this.resizeState.isResizingSelectionFlag = false;
    this.instance.updateAllLayouts();

    this.syncStateToInstance();

    this.instance.$nextTick(() => {
      this.instance.updateSelectionAreaFromItems();
      this.instance.updateSelectionBorders();
    });

    // Ngăn sự kiện lan truyền và hành vi mặc định
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    // Emit event
    const eventData: SelectionResizeEventData = {
      eventType: 'selectionresizeend',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      resizeType: this.resizeState.selectionResizeType,
      scaleX: 1,
      scaleY: 1,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onResizeEnd) {
      this.events.onResizeEnd(eventData);
    }
  }

  public isResizing(): boolean {
    return this.resizeState.isResizingSelection;
  }

  public destroy(): void {
    // Dừng resize nếu đang diễn ra
    this.resizeState.isResizingSelection = false;

    // Xóa event listeners
    const iframeDoc = this.instance.idoc();
    if (this._resizeMoveHandler) {
      iframeDoc.removeEventListener("mousemove", this._resizeMoveHandler);
      this._resizeMoveHandler = null;
    }
    if (this._resizeEndHandler) {
      iframeDoc.removeEventListener("mouseup", this._resizeEndHandler);
      this._resizeEndHandler = null;
    }

    // Reset resize state
    this.resizeState = {
      isResizingSelection: false,
      isResizingSelectionMove: false,
      selectionResizeStart: { x: 0, y: 0 },
      selectionResizeType: "",
      selectionResizeInitial: {
        minX: 0,
        minY: 0,
        maxX: 0,
        maxY: 0
      },
      selectionResizeRatio: 1,
      lastMouseX: 0,
      lastMouseY: 0,
      isResizingSelectionFlag: false,
      selectionRatio: false
    };

    // Sync lại state về instance
    this.syncStateToInstance();
  }

  // Debug method
  public debugResize(): void {
    console.log('=== Resize Debug Info ===');
    console.log('isResizingSelection:', this.resizeState.isResizingSelection);
    console.log('selectionResizeType:', this.resizeState.selectionResizeType);
    console.log('selectionRatio:', this.resizeState.selectionRatio);
    console.log('resizeInitial:', this.resizeState.selectionResizeInitial);
    console.log('=== End Resize Debug Info ===');
  }
}