                } else {
                    this.selectedShapeName = null;
                }

            }
        }
    },
    computed: {
        shapesToShow() {
            // Return the first 9 shapes not type is line for the popup
            // Check type ! line và box-shadow
            let listShapes = this.shapes.filter(shape => shape.type !== 'line' && shape.type !== 'box-shadow');
            if(!this.field.options.getNoneBtn) {
                listShapes = listShapes.filter(shape => shape.dataName !== 'shape-none');
            }
            return listShapes.slice(0, 9);
        },
        shapesToShowPopup() {
            // Return the first 9 shapes not type is line for the popup
            // Check type ! line và box-shadow
            //return this.shapes.filter(shape => shape.type !== 'line' && shape.type !== 'box-shadow').slice(9);
            let shapes = this.shapes.filter(shape => shape.type !== 'line' && shape.type !== 'box-shadow');
            // Nếu getNoneBtn là false thì loại bỏ shape-none
            if (!this.field.options.getNoneBtn) {
                shapes = shapes.filter(shape => shape.dataName !== 'shape-none');
            }
            return shapes.slice(9);
        },
        linesToShow() {
            // Return the first 9 shapes not type is line for the popup
            return this.shapes.filter(shape => shape.type == 'line');
        },
        boxShadowToShow() {
            return this.shapes.filter(shape => shape.type == 'box-shadow');
        }
    },
    methods: {
        chooseShapeFromPopup(shape, shapeName) {
            this.selectedShapeName = shapeName;
            
            // If type is line, set strokeThickness to 4
            const updateData = {
                name: shape.dataName,
                type: shape.type,
                url: shape.elemetGet,
                shapeActive: shapeName,
            };
            
            this.$emit('update:data', updateData);
            this.showPopup = false;
        },
        chooseShadown(box_shadow) {
            this.$emit('update:data', {
                nameShadow: box_shadow.dataName,
                urlShadow: box_shadow.elementShadow,
                cssShadow: box_shadow.css
            });
        }
    },
    mounted() {
        if (this.data?.name) {
            this.selectedShapeName = this.data.name;
        }
    }

};
</script>

