<template>
    <div class="ecom__element ecom-element element__code exporting"  v-if="exporting === true" >
        <Liquid :data="data.settings.code" />
    </div>
    <div v-else-if="exporting === 'preview'" class="ecom__element ecom-element element__code no-exporting">
        <div v-html="liquid('code')" />
    </div>
    <div
        v-else
        class="ecom__element ecom-element element__code no-exporting"
        :class="{ 'code-invisible': isInvisibleCode }"
    >
        <div v-if="isInvisibleCode" class="code-placeholder">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <polyline points="16 18 22 12 16 6"></polyline>
                <polyline points="8 6 2 12 8 18"></polyline>
            </svg>
            <span>Custom Code, Click to edit</span>
        </div>
        <!-- Always render the code (hidden when placeholder shows) so styles are applied -->
        <div v-if="isInvisibleCode && hasStyleOrScript" v-html="liquid('code')" class="code-hidden-styles" />
        <div v-if="!isInvisibleCode" v-html="liquid('code')" />
    </div>
</template>

<script>
import { mapGetters } from 'vuex';
import {Element, Liquid} from '@/mixins';
export default {
    name: 'Code',
    docs: 'https://help.ecomposer.io/docs/elements/shopify-elements/code/',
    mixins: [Element, Liquid],
    props: {
        'data': {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        settings() {
            return [{
                params: [
                {
                    type: 'paragraph',
                    options: {
                        warnings: {
                            content: this.$t('you_can_add_html_javascript_css_and_shopify_liquid_code_here_but_do_not_include_html_head_or_body_tags_as_they_may_cause_conflicts_with_other_elements_on_the_page')
                        }
                    }
                },
                {
                    label: this.$t('custom_code'),
                    type: 'textarea',
                    description: this.$t('add_app_snippets_or_other_liquid_code'),
                    name: 'code',
                    options: {
                        update: 'onchange',
                        height: 350,
                        editor: true,
                        language: 'html'
                    }
                }]
            }];
        },

        code() {
            return this.data;
        },
        codevalue() {
            return this.data.settings.code;
        },
        isInvisibleCode() {
            if(this.exporting)
            {
                return false;
            }
            if (!this.codevalue) return true;
            // Remove script, style, comments, Liquid tags, and HTML tags to check if any visible text remains
            const visibleContent = this.codevalue
                .replace(/<script[\s\S]*?<\/script>/gi, '')
                .replace(/<style[\s\S]*?<\/style>/gi, '')
                .replace(/<!--[\s\S]*?-->/g, '')
                .replace(/{{[\s\S]*?}}/g, '') // Remove Liquid output tags
                .replace(/{%[\s\S]*?%}/g, '') // Remove Liquid logic tags
                .replace(/<[^>]*>/g, '') // Remove remaining HTML tags to get text content
                .trim();
            return visibleContent.length === 0;
        },
        hasStyleOrScript() {
            if (!this.codevalue) return false;
            // Check if code contains style or script tags
            return /<style[\s\S]*?<\/style>/gi.test(this.codevalue) ||
                   /<script[\s\S]*?<\/script>/gi.test(this.codevalue);
        },
        codePreiew(){
            if(!this.codevalue) {
                return '';
            }
            if (this.codevalue.match(/{{[\s\S]*|{%[\s\S]*/g)) {
                return `
                    <div class="ecom-skeleton-item">
                        <div class="ecom-skeleton-col-12">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-9 ecom-skeleton-big"></div>
                            </div>
                        </div>
                    </div>
                `;
            } else {
                return this.codevalue;
            }
        },
        codeliquid() {
            if (this.codevalue?.match(/{{[\s\S]*|{%[\s\S]*/g) === null) {
                return '';
            } else {
                return this.codevalue;
            }
        },
        liquids() {
            return {
                code: {
                    code: this.codeliquid,
                    preview: this.codePreiew
                }
            };
        },
        style() {
            return [
                {
                    group_alias: 'text',
                    options:{
                        group_title: this.$t('text'),
                    }

                }
            ]
        },
        ...mapGetters('builder', ['getLiquids']),

        default() {
            return {
                settings: {
                    code: "<div>Your custom code is here (HTML, JavaScript, CSS, Shopify Liquid)</div>"
                },
                style: {
                    text: {
                        textTextAlign: "left"
                    }
                }
            }
        }
    },
    watch: {
        codevalue(val) {
            if(this.exporting)
            {
                return false;
            }
            let myLiquid = this.getLiquids?.[this.data?.id] ?? {};
            if (
                this.data.id &&
                (myLiquid === undefined || myLiquid.content === undefined)
            ) {
                this.getLiquids[this.data.id] = { content: {} };
            }
            this.getLiquids[this.data.id].content.code = val;
        }
    },
    created() {
        if(this.exporting)
        {
            return false;
        }
        let myLiquid = this.getLiquids?.[this.data?.id] ?? {};
        if (
            this.data.id &&
            (myLiquid === undefined || myLiquid.content === undefined)
        ) {
            this.getLiquids[this.data.id] = { content: {} };
        }
       // this.getLiquids[this.data.id].content.code = {};
    },
};
</script>

<style scoped>
.code-hidden-styles {
    /* Hide the container but allow styles/scripts inside to still work */
    position: absolute;
    width: 0;
    height: 0;
    overflow: hidden;
    visibility: hidden;
    pointer-events: none;
}
</style>