<template>
  <div class="ecom-element ecom-shopify ecom-shopify__language-and-country-element">
    <div class="ecom-shopify__country-localization-switcher-wrapper" v-html="liquid('countryAndLocalization')">
    </div>
  </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
  name: 'shopifyLanguageAndCountrySwitcher',
  mixins: [Liquid, Element, Javascript],
  props: {
    data: {
      type: Object,
      default() {
        return {
        };

      }
    },
  },
  methods: {
    style() {
      let style = [
        {
          group_alias: 'button',
          options: {
            group_title: this.$t('selector'),
            group_name: 'button',
            selector: ' .ecom__element--button'
          },
          modify: {
            params: [
              {
                position: 0,
                fields: [
                  {
                    alias: 'justify-content',
                    options: {
                      label: this.$t('alignment'),
                      css: {
                        selector: 'root .ecom-button-default',
                      }
                    }
                  }
                ]
              },
              {
                position: 1,
                fields: [
                  {
                    alias: 'text-align',
                    options: {
                      label: this.$t('content_alignment'),
                      name: 'content_alignment',
                      liteMode: true,
                      css: {
                        selector: 'root .ecom__element--button, root .ecom__element--button span',
                        properties: {
                          'justify-content': '',
                          'text-align': '',
                          'align-items': ''
                        }
                      }
                    }
                  }
                ]
              },

            ]
          }
        },
        {
          group_alias: 'text:spacing',
          options: {
            group_title: this.$t('dropdown'),
            group_name: 'dropdown',
            selector: ' .ecom-disclosure__list-wrapper'
          },
          modify: {
            remove: [
              { index: 0, length: 1 },
              { index: 1, length: 2 },
            ],
            params: [
              {
                position: 5,
                fields: [
                  {
                    name: "background_color",
                    label: this.$t('background_color'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      global: {
                        type: "colors"
                      },
                    },
                    css: {
                      properties: {
                        "background-color": ""
                      }
                    }
                  },
                  {
                    name: "tab",
                    type: "tab",
                    value: "normal",
                    options: {
                      tabs: [
                        {
                          name: "normal",
                          title: this.$t('normal')
                        },
                        {
                          name: "hover",
                          title: this.$t('hover')
                        }
                      ]
                    },
                    css: {
                      isCss: false
                    }
                  },
                  {
                    name: "text_color",
                    label: this.$t('text_color'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      visible: {
                        keep_data: true,
                        condition: (data) => {
                          return data && data["tab"] == "normal";
                        }
                      },
                      global: {
                        type: "colors"
                      }
                    },
                    css: {
                      selector: ' .ecom-disclosure__item .ecom-link--text',
                      properties: {
                        color: ""
                      }
                    }
                  },
                  {
                    name: "item_color",
                    label: this.$t('item_color'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      global: {
                        type: "colors"
                      },
                      visible: {
                        keep_data: true,
                        condition: (data) => {
                          return data && data["tab"] == "normal";
                        }
                      },
                    },
                    css: {
                      selector: ' .ecom-disclosure__item',
                      properties: {
                        "background-color": ""
                      }
                    }
                  },
                  {
                    name: "text_color_hover",
                    label: this.$t('text_color'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      visible: {
                        keep_data: true,
                        condition: (data) => {
                          return data && data["tab"] == "hover";
                        }
                      },
                      global: {
                        type: "colors"
                      }
                    },
                    css: {
                      selector: ' .ecom-disclosure__item:hover .ecom-link--text',
                      properties: {
                        color: ""
                      }
                    }
                  },
                  {
                    name: "item_color_hover",
                    label: this.$t('item_color'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      global: {
                        type: "colors"
                      },
                      visible: {
                        keep_data: true,
                        condition: (data) => {
                          return data && data["tab"] == "hover";
                        }
                      },
                    },
                    css: {
                      selector: ' .ecom-disclosure__item:hover',
                      properties: {
                        "background-color": ""
                      }
                    }
                  },
                ]
              }

            ]
          },
        },
        {
          group_alias: 'input',
          options: {
            group_name: 'input_search',
            group_title: this.$t('search'),
            selector: ' .ecom-disclosure__list-wrapper .ecom-field__input'
          },
          modify: {
            remove: [
              { index: 5, length: 2 },
            ],
            params: [
              {
                position: 4,
                fields: [
                  {
                    name: "color_placeholder",
                    label: this.$t('color_placeholder'),
                    type: "color",
                    options: {
                      responsive: true,
                      oneline: true,
                      global: {
                        type: "colors"
                      }
                    },
                    css: {
                      selector: 'root  .ecom-disclosure__list-wrapper .field__label',
                      properties: {
                        color: ""
                      }
                    }
                  },
                ]
              }
            ]
          }
        },
      ]

      return style;
    }
  },
  computed: {
    settings() {
      return [{
        group_title: this.$t('general'),
        params: [
          {
              type: "paragraph",
              content: this.$t('show_switcher_of_language_and_country_currency_on_your_store')
          },
          {
            type: 'popup',
            name: 'enable_switcher',
            label: this.$t('enable_switcher'),
            value: 'both',
            options: {
              type: 'dropdown',
              preview: 'title',
              default: false,
              values: {
                language: this.$t('language_switcher'),
                country: this.$t('country_switcher'),
                both: this.$t('language_and_country_switcher')
              }
            }
          },
          {
            type: 'popup',
            name: 'dropdown_position',
            label: this.$t('dropdown_position'),
            options: {
              type: 'dropdown',
              preview: 'title',
              default: false,
              values: {
                bottom: this.$t('bottom'),
                top: this.$t('top')
              }
            }
          },
          {
            type: 'paragraph',
            options: {
              warnings: {
                content: this.$t('language_and_country_switcher_cannot_be_placed_in_product_section_cart_section')
              }
            }
          }
        ]
      }];
    },
    javascript() {
      return function () {
        let $el = this.$el;
        if (!$el) return;
        const isRTL = window.document.querySelector('html').getAttribute('dir') === 'rtl';
        const dropdown_wrapper = $el.querySelectorAll('.ecom-disclosure__list-wrapper');
        if (dropdown_wrapper && isRTL) {
          dropdown_wrapper.forEach((item) => {
            item.classList.add('ecom-rtl');
          });
        }
        const setIndexDropdown = isOpen =>{
            let parentSec = $el.closest('.ecom-section.ecom-row');
            let parentBlock = $el.closest('.ecom-block.ecom-core');
            if (parentSec) {
              isOpen ? parentSec.style.zIndex = '99' : parentSec.style.zIndex = 'inherit';
            }
            if (parentBlock) {
              isOpen ? parentBlock.style.zIndex = '99' : parentBlock.style.zIndex = 'inherit';
            }
        }
        if (!customElements.get('ecom-localization-form')) {
          customElements.define(
            'ecom-localization-form',
            class EcomLocalizationForm extends HTMLElement {
              constructor() {
                super();
                this.mql = window.matchMedia('(min-width: 750px)');
                this.elements = {
                  input: this.querySelector('input[name="locale_code"], input[name="country_code"]'),
                  button: this.querySelector('button.ecom-localization-form__select'),
                  panel: this.querySelector('.ecom-disclosure__list-wrapper'),
                  search: this.querySelector('input[name="country_filter"]'),
                  closeButton: this.querySelector('.country-selector__close-button'),
                  resetButton: this.querySelector('.ecom-country-filter__reset-button'),
                  searchIcon: this.querySelector('.ecom-country-filter__search-icon'),
                  liveRegion: this.querySelector('#sr-country-search-results'),
                };
                this.addEventListener('keyup', this.onContainerKeyUp.bind(this));
                this.addEventListener('keydown', this.onContainerKeyDown.bind(this));
                // this.addEventListener('click', this.closeSelector.bind(this));
                this.elements.button.addEventListener('click', this.openSelector.bind(this));

                if (this.elements.search) {
                  this.elements.search.addEventListener('keyup', this.filterCountries.bind(this));
                  this.elements.search.addEventListener('focus', this.onSearchFocus.bind(this));
                  this.elements.search.addEventListener('blur', this.onSearchBlur.bind(this));
                  this.elements.search.addEventListener('keydown', this.onSearchKeyDown.bind(this));
                }
                if (this.elements.closeButton) {
                  this.elements.closeButton.addEventListener('click', this.hidePanel.bind(this));
                }
                if (this.elements.resetButton) {
                  this.elements.resetButton.addEventListener('click', this.resetFilter.bind(this));
                  this.elements.resetButton.addEventListener('mousedown', (event) => event.preventDefault());
                }
                this.querySelectorAll('a').forEach((item) => item.addEventListener('click', this.onItemClick.bind(this)));
                this.handleClickOutside = (event) => {
                  if (event.target === this.elements.button) return;
                      const isSearchInput = event.target.classList.contains("ecom-country-filter__input");
                      (event.target.classList.contains("ecom-country-selector__overlay") || !isSearchInput) && this.closeSelector();
                };
              }

              hidePanel() {
                setIndexDropdown(false);
                this.elements.button.setAttribute('aria-expanded', 'false');
                this.elements.panel.setAttribute('hidden', true);
                if (this.elements.search) {
                  this.elements.search.value = '';
                  this.filterCountries();
                  this.elements.search.setAttribute('aria-activedescendant', '');
                }
                document.body.classList.remove('overflow-hidden-mobile');
                let menuDrawer = document.querySelector('.menu-drawer');
                if(menuDrawer){
                  menuDrawer.classList.remove('country-selector-open');
                  this.header.preventHide = false;
                }
              }

              onContainerKeyDown(event) {
                const focusableItems = Array.from(this.querySelectorAll('a')).filter(
                  (item) => !item.parentElement.classList.contains('hidden')
                );
                let focusedItemIndex = focusableItems.findIndex((item) => item === document.activeElement);
                let itemToFocus;

                switch (event.code.toUpperCase()) {
                  case 'ARROWUP':
                    event.preventDefault();
                    itemToFocus =
                      focusedItemIndex > 0 ? focusableItems[focusedItemIndex - 1] : focusableItems[focusableItems.length - 1];
                    itemToFocus.focus();
                    break;
                  case 'ARROWDOWN':
                    event.preventDefault();
                    itemToFocus =
                      focusedItemIndex < focusableItems.length - 1 ? focusableItems[focusedItemIndex + 1] : focusableItems[0];
                    itemToFocus.focus();
                    break;
                }

                if (!this.elements.search) return;

                setTimeout(() => {
                  focusedItemIndex = focusableItems.findIndex((item) => item === document.activeElement);
                  if (focusedItemIndex > -1) {
                    this.elements.search.setAttribute('aria-activedescendant', focusableItems[focusedItemIndex].id);
                  } else {
                    this.elements.search.setAttribute('aria-activedescendant', '');
                  }
                });
              }

              onContainerKeyUp(event) {
                event.preventDefault();

                switch (event.code.toUpperCase()) {
                  case 'ESCAPE':
                    if (this.elements.button.getAttribute('aria-expanded') == 'false') return;
                    this.hidePanel();
                    event.stopPropagation();
                    this.elements.button.focus();
                    break;
                  case 'SPACE':
                    if (this.elements.button.getAttribute('aria-expanded') == 'true') return;
                    this.openSelector();
                    break;
                }
              }

              onItemClick(event) {
                event.preventDefault();
                const value = event.currentTarget.dataset.value;
                const inputName = this.elements.input ? this.elements.input.name : '';
                
                if (inputName === 'locale_code') {
                  // Xử lý language code - POST đến /localization
                  this.changeLocalization(null, value);
                } else if (inputName === 'country_code') {
                  // Xử lý country code - POST đến /localization
                  this.changeLocalization(value, null);
                }
              }

              changeLocalization(countryCode, languageCode) {
                const formData = new FormData();
                
                
                formData.append("form_type", "localization");
                formData.append("utf8", "✓");
                formData.append("_method", "put");

                // Sử dụng field names chính xác như Shopify form
                if (languageCode) {
                  formData.append("locale_code", languageCode);
                }
                if (countryCode) {
                  formData.append("country_code", countryCode);
                }

                fetch("/localization", {
                  method: "POST",
                  body: formData,
                  headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                  }
                })
                .then(res => {
                  if (res.ok) {
                    // Thay vì reload, redirect đến URL được trả về
                    return res.text();
                  } else {
                    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
                  }
                })
                .then(responseText => {
                  // Lấy Shopify.routes.root từ response bằng regex
                  const routeRootMatch = responseText.match(/Shopify\.routes\.root\s*=\s*"([^"]+)"/);
                  const newRootPath = routeRootMatch ? routeRootMatch[1] : null;
                  
                  console.log('%cNew root path:', 'color: #FBAC19', newRootPath);
                  
                  if(languageCode && newRootPath) {
                    // Lấy current root và thay thế bằng new root trong URL hiện tại
                    const currentRoot = (window.Shopify && window.Shopify.routes && window.Shopify.routes.root) || '/';
                    const newUrl = window.location.href.replace(window.location.origin + currentRoot, window.location.origin + newRootPath);
                    
                    window.location.href = newUrl;
                  } else {
                    window.location.reload();
                  }
                })
                .catch(err => {
                  console.error("Localization change failed:", err);
                  // Fallback: vẫn reload page
                  window.location.reload();
                });
              }
              openSelector() {
                let isHidden = this.elements.panel.hasAttribute('hidden');
                if (isHidden) {
                    this.elements.button.focus();
                    this.elements.panel.removeAttribute('hidden');
                    this.elements.button.setAttribute(
                        'aria-expanded',
                        (this.elements.button.getAttribute('aria-expanded') === 'false').toString()
                    );

                    if (!document.body.classList.contains('overflow-hidden-tablet')) {
                        document.body.classList.add('overflow-hidden-mobile');
                    }

                    if (this.elements.search && this.mql.matches) {
                        this.elements.search.focus();
                    }

                    let menuDrawer = document.querySelector('.menu-drawer');
                    if (menuDrawer) {
                        menuDrawer.classList.add('country-selector-open');
                    }

                    setIndexDropdown(true);

                    setTimeout(() => {
                        document.addEventListener('click', this.handleClickOutside);
                    }, 10);
                } else {
                    this.closeSelector();
                }
            }
            
            closeSelector() {
                this.elements.panel.setAttribute('hidden', '');
                this.elements.button.setAttribute('aria-expanded',false);
                document.removeEventListener('click', this.handleClickOutside);
            }

              normalizeString(str) {
                return str
                  .normalize('NFD')
                  .replace(/\p{Diacritic}/gu, '')
                  .toLowerCase();
              }

              filterCountries() {
                const searchValue = this.normalizeString(this.elements.search.value);
                const popularCountries = this.querySelector('.popular-countries');
                const allCountries = this.querySelectorAll('a');
                let visibleCountries = allCountries.length;

                this.elements.resetButton.classList.toggle('hidden', !searchValue);

                if (popularCountries) {
                  popularCountries.classList.toggle('hidden', searchValue);
                }

                allCountries.forEach((item) => {
                  const countryName = this.normalizeString(item.querySelector('.country').textContent);
                  if (countryName.indexOf(searchValue) > -1) {
                    item.parentElement.classList.remove('hidden');
                    visibleCountries++;
                  } else {
                    item.parentElement.classList.add('hidden');
                    visibleCountries--;
                  }
                });
                if (this.elements.liveRegion && window.accessibilityStrings) {
                  this.elements.liveRegion.innerHTML = window.accessibilityStrings.countrySelectorSearchCount.replace(
                    '[count]',
                    visibleCountries
                  );
                }
                let country_selector =  this.querySelector('.country-selector');
                let country_selector_list =  this.querySelector('.country-selector__list');
                country_selector ? country_selector.scrollTop = 0 : "";
                country_selector_list ? country_selector_list.scrollTop = 0 : "";
              }

              resetFilter(event) {
                event.stopPropagation();
                this.elements.search.value = '';
                this.filterCountries();
                this.elements.search.focus();
              }

              onSearchFocus() {
                this.elements.searchIcon.classList.add('ecom-country-filter__search-icon--hidden');
              }

              onSearchBlur() {
                if (!this.elements.search.value) {
                  this.elements.searchIcon.classList.remove('ecom-country-filter__search-icon--hidden');
                }
              }

              onSearchKeyDown(event) {
                if (event.code.toUpperCase() === 'ENTER') {
                  event.preventDefault();
                }
              }
            }
          );
        }

      }
    },
    csrContext() {
      return {type: "localization"}
    },

    liquids() {
      return {
        countryAndLocalization: {
          code: `
              <div class="ecom-shopify__country-localization-switcher ecom-button-default ${!this.exporting ? 'ecom-placeholder-on-builder-mode ecom-element__placeholder': ''}" data-ecom-placeholder="
              {%- if ${!this.exporting} -%}
              {% assign language_count = localization.available_languages.size %}
              {% assign country_count = localization.available_countries.size %}

              {% unless language_count > 1 or country_count > 1 %}
              ${this.$t("the_location_and_language_features_are_not_enabled_please_enable_them_in_the_store_settings")}
              {% endunless %}
              {%- endif -%}
              ">
                
              {%- if localization.available_languages and localization.available_languages.size > 1 -%}
                <div class="ecom-hidden"></div>
                  {%- if ${this.data.settings.enable_switcher && this.data.settings.enable_switcher !== 'country'} -%}
                    <ecom-localization-form>
                      <div class="ecom-localization-form">
                      <div>
                        <h2 class="ecom-visually-hidden" id="HeaderLanguageLabel">${this.lang("Language","language_text")}</h2>
                        <div class="ecom-disclosure">
                        <button
                          type="button"
                          class="ecom-disclosure__button ecom-localization-form__select localization-selector ecom-link ecom-link--text caption-large ecom__element--button"
                          aria-expanded="false"
                          aria-controls="ecom-List"
                          aria-describedby="ecom-Label"
                        >
                          <span>{{ localization.language.endonym_name | capitalize }}</span>
                          <svg aria-hidden="true" focusable="false" class="ecom-icon icon-caret" viewBox="0 0 10 6"><path fill-rule="evenodd" clip-rule="evenodd" d="M9.354.646a.5.5 0 00-.708 0L5 4.293 1.354.646a.5.5 0 00-.708.708l4 4a.5.5 0 00.708 0l4-4a.5.5 0 000-.708z" fill="currentColor"></svg>
                        </button>
                        <div class="ecom-disclosure__list-wrapper lang-selector ${this.data?.settings && this.data.settings.dropdown_position === "bottom" ? "ecom-dropdown-position-bottom" : ""} ${this.data?.style?.button && this.data.style.button['justify-content'] === "flex-start" ? "ecom-dropdown-position-left" : ""}" hidden>
                          <ul id="ecom-List" role="list" class="ecom-disclosure__list list-unstyled">
                            {%- for language in localization.available_languages -%}
                              <li class="ecom-disclosure__item" tabindex="-1">
                                <a
                                  class="ecom-link ecom-link--text ecom-disclosure__link caption-large focus-inset"
                                  href="#"
                                  hreflang="{{ language.iso_code }}"
                                  lang="{{ language.iso_code }}"
                                  {%-if language.iso_code == localization.language.iso_code-%}
                                    aria-current="true"
                                  {%-endif-%}
                                  data-value="{{ language.iso_code }}"
                                >
                                  <span
                                    {% if language.iso_code != localization.language.iso_code %}
                                      class="ecom-visibility-hidden"
                                    {% endif %}
                                  >
                                    <svg
                                      class="ecom-icon icon-checkmark"
                                      aria-hidden="true"
                                      focusable="false"
                                      xmlns="http://www.w3.org/2000/svg"
                                      viewBox="0 0 12 9"
                                      fill="none"
                                    >
                                      <path fill-rule="evenodd" clip-rule="evenodd" d="M11.35.643a.5.5 0 01.006.707l-6.77 6.886a.5.5 0 01-.719-.006L.638 4.845a.5.5 0 11.724-.69l2.872 3.011 6.41-6.517a.5.5 0 01.707-.006h-.001z" fill="currentColor"/>
                                    </svg>

                                  </span>
                                  <span>
                                    {{ language.endonym_name | capitalize }}
                                  </span>
                                </a>
                              </li>
                            {%- endfor -%}
                          </ul>
                        </div>
                        </div>
                        <input type="hidden" name="locale_code" value="{{ localization.language.iso_code }}">
                      </div>
                      </div>
                  </ecom-localization-form>
                {%- endif -%}
              {%- endif -%}

                  {%- capture icon_checkmark -%}<svg class="ecom-icon icon-checkmark" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 9" fill="none"> <path fill-rule="evenodd" clip-rule="evenodd" d="M11.35.643a.5.5 0 01.006.707l-6.77 6.886a.5.5 0 01-.719-.006L.638 4.845a.5.5 0 11.724-.69l2.872 3.011 6.41-6.517a.5.5 0 01.707-.006h-.001z" fill="currentColor"/></svg>{%- endcapture -%}
                {%- if localization.available_countries and localization.available_countries.size > 1 -%}
                <div class="ecom-hidden"></div>
                  {%- if ${this.data.settings.enable_switcher && this.data.settings.enable_switcher !== 'language'}-%}
                    <ecom-localization-form>
                      <div class="ecom-localization-form">
                        <div>
                          <h2 class="ecom-visually-hidden" id="HeaderCountryMobileLabel">
                            ${this.lang("Country\/region","country_region_text")}
                          </h2>
                          {%- liquid
                            assign currencies = localization.available_countries | map: 'currency' | map: 'iso_code' | uniq
                            assign popular_countries = localization.available_countries | where: 'popular?' | sort: 'name'

                            assign show_country_filter = false
                            if localization.available_countries.size > 9
                              assign show_country_filter = true 
                            endif

                            assign show_popular_countries = false
                            if localization.available_countries.size > 9 and popular_countries.size > 1
                              assign show_popular_countries = true
                            endif

                            assign show_currencies = false
                            if currencies.size > 1
                              assign show_currencies = true
                            endif
                          -%}

                          <div class="ecom-disclosure">
                            <button
                              type="button"
                              class="ecom-disclosure__button ecom-localization-form__select localization-selector ecom-link ecom-link--text caption-large ecom__element--button"
                              aria-expanded="false"
                              aria-controls="ecom-country-results"
                              aria-describedby="ecom-Label"
                            >
                              <span>
                                {{- localization.country.name }} |
                                {{ localization.country.currency.iso_code }}
                                {{ localization.country.currency.symbol -}}
                              </span>
                              <svg aria-hidden="true" focusable="false" class="ecom-icon icon-caret" viewBox="0 0 10 6"><path fill-rule="evenodd" clip-rule="evenodd" d="M9.354.646a.5.5 0 00-.708 0L5 4.293 1.354.646a.5.5 0 00-.708.708l4 4a.5.5 0 00.708 0l4-4a.5.5 0 000-.708z" fill="currentColor"></svg>
                            </button>
                            <div class="ecom-disclosure__list-wrapper country-selector ${this.data?.settings && this.data.settings.dropdown_position === "bottom" ? "ecom-dropdown-position-bottom" : ""} ${this.data?.style?.button && this.data.style.button['justify-content'] === "flex-start" ? "ecom-dropdown-position-left" : ""}" hidden>
                              <div class="ecom-country-filter{%- unless show_country_filter -%} ecom-country-filter--no-padding{%- endunless -%}">
                                {%- if show_country_filter -%}
                                  <div class="field">
                                    <input
                                      class="ecom-country-filter__input ecom-field__input"
                                      id="ecom-country-filter-input"
                                      type="search"
                                      name="country_filter"
                                      value=""
                                      placeholder="${this.lang('Search','search_text')}"
                                      role="combobox"
                                      aria-owns="country-results"
                                      aria-controls="country-results"
                                      aria-haspopup="listbox"
                                      aria-autocomplete="list"
                                      autocorrect="off"
                                      autocomplete="off"
                                      autocapitalize="off"
                                      spellcheck="false"
                                    >
                                    <label class="field__label" for="ecom-country-filter-input">${this.lang('Search','search_text')}</label>
                                    <button
                                      type="reset"
                                      class="ecom-country-filter__reset-button field__button hidden"
                                      aria-label="${this.lang("Clear search term","clear_search_term_text")}"
                                    >
                                      <svg class="ecom-icon icon-close" aria-hidden="true" focusable="false">
                                        <use xlink:href="#icon-reset">
                                      </svg>
                                    </button>
                                    <div class="ecom-country-filter__search-icon field__button motion-reduce">
                                      <svg class="ecom-icon icon-search" aria-hidden="true" focusable="false" fill="none" viewBox="0 0 18 19">
                                        <path fill="currentColor" fill-rule="evenodd" d="M11.03 11.68A5.784 5.784 0 1 1 2.85 3.5a5.784 5.784 0 0 1 8.18 8.18m.26 1.12a6.78 6.78 0 1 1 .72-.7l5.4 5.4a.5.5 0 1 1-.71.7z" clip-rule="evenodd"></path>
                                      </svg>
                                    </div>
                                  </div>
                                {%- endif -%}
                                <button
                                  class="country-selector__close-button button--small ecom-link"
                                  type="button"
                                  aria-label="${this.lang("Close","close_text")}"
                                >
                                  <svg
                                    xmlns="http://www.w3.org/2000/svg"
                                    aria-hidden="true"
                                    focusable="false"
                                    class="ecom-icon icon-close"
                                    fill="none"
                                    viewBox="0 0 18 17"
                                  >
                                    <path d="M.865 15.978a.5.5 0 00.707.707l7.433-7.431 7.579 7.282a.501.501 0 00.846-.37.5.5 0 00-.153-.351L9.712 8.546l7.417-7.416a.5.5 0 10-.707-.708L8.991 7.853 1.413.573a.5.5 0 10-.693.72l7.563 7.268-7.418 7.417z" fill="currentColor">
                                  </svg>

                                </button>
                              </div>
                              <div id="sr-country-search-results" class="ecom-visually-hidden" aria-live="polite"></div>
                              <div
                                class="ecom-disclosure__list country-selector__list{%- if show_currencies -%} country-selector__list--with-multiple-currencies{%-endif-%}"
                                id="ecom-country-results"
                              >
                                {%-if show_popular_countries-%}
                                  <ul
                                    role="list"
                                    class="list-unstyled popular-countries"
                                    aria-label="${this.lang("Popular countries\/regions","close_text")}"
                                  >
                                    {%- for country in popular_countries -%}
                                      <li class="ecom-disclosure__item" tabindex="-1">
                                        <a
                                          class="ecom-link ecom-link--text ecom-disclosure__link caption-large focus-inset"
                                          href="#"
                                          {%- if country.iso_code == localization.country.iso_code -%}
                                            aria-current="true"
                                          {%- endif -%}
                                          data-value="{{ country.iso_code }}"
                                          id="{{ country.name }}"
                                        >
                                          <span
                                            {% if country.iso_code != localization.country.iso_code %}
                                              class="ecom-visibility-hidden"
                                            {% endif %}
                                          >
                                            {{icon_checkmark}}
                                          </span>
                                          <span class="country">{{- country.name }}</span>
                                          <span class="ecom-localization-form__currency motion-reduce{%-unless show_currencies-%} hidden{%-endunless-%}">
                                            {{ country.currency.iso_code }}
                                            {{ country.currency.symbol -}}
                                          </span>
                                        </a>
                                      </li>
                                    {%- endfor -%}
                                  </ul>
                                {%-endif-%}
                                <ul role="list" class="list-unstyled countries">
                                  {%- for country in localization.available_countries -%}
                                    <li class="ecom-disclosure__item" tabindex="-1">
                                      <a
                                        class="ecom-link ecom-link--text ecom-disclosure__link caption-large focus-inset"
                                        href="#"
                                        {%-if country.iso_code == localization.country.iso_code-%}
                                          aria-current="true"
                                        {%-endif-%}
                                        data-value="{{ country.iso_code }}"
                                        id="{{ country.name }}"
                                      >
                                        <span
                                          {% if country.iso_code != localization.country.iso_code %}
                                            class="ecom-visibility-hidden"
                                          {% endif %}
                                        >
                                          {{icon_checkmark}}
                                        </span>
                                        <span class="country">{{- country.name }}</span>
                                        <span class="ecom-localization-form__currency motion-reduce{%-unless show_currencies-%} hidden{%-endunless-%}">
                                          {{ country.currency.iso_code }}
                                          {{ country.currency.symbol -}}
                                        </span>
                                      </a>
                                    </li>
                                  {%- endfor -%}
                                </ul>
                              </div>
                            </div>
                            <div class="ecom-country-selector__overlay"></div>
                          </div>
                          <input type="hidden" name="country_code" value="{{ localization.country.iso_code }}">
                        </div>
                      </div>
                    </ecom-localization-form>
                  {%- endif -%}
                {%- endif -%}
              </div>
                `
        },
      };
    },
    css() {
      return `
