<template>
    <div
        v-if="message"
        class="w-full mt-1 mb-0.5 px-3 py-2 rounded text-xs leading-snug flex items-start gap-1.5 border"
        :class="boxClass"
    >
        <svg v-if="variant === 'error'" class="w-3.5 h-3.5 mt-0.5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clip-rule="evenodd"/>
        </svg>
        <svg v-else-if="variant === 'info'" class="w-3.5 h-3.5 mt-0.5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd"/>
        </svg>
        <svg v-else class="w-3.5 h-3.5 mt-0.5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/>
        </svg>
        <span>{{ message }}</span>
    </div>
</template>

<script lang="ts">
export default {
    name: 'Custom_statusField',
    props: {
        field: {
            type: Object,
            default() { return {}; }
        },
        fieldValues: {
            type: Object,
            default() { return {}; }
        }
    },
    computed: {
        statusKey(): string {
            return this.field?.options?.statusKey || '_qr_status';
        },
        errorKey(): string {
            return this.field?.options?.errorKey || '_qr_status_error';
        },
        message(): string {
            const staticMessage = this.field?.options?.message;
            if (staticMessage) {
                return staticMessage;
            }
            return this.fieldValues?.[this.statusKey] || '';
        },
        variant(): string {
            if (this.field?.options?.variant) {
                return this.field.options.variant;
            }
            return this.fieldValues?.[this.errorKey] ? 'error' : 'success';
        },
        boxClass(): string {
            if (this.variant === 'error') {
                return 'bg-red-50 text-red-600 border-red-200';
            }
            if (this.variant === 'info') {
                return 'bg-amber-50 text-amber-800 border-amber-200';
            }
            return 'bg-green-50 text-green-700 border-green-200';
        }
    }
};
</script>
