<template>
    <div v-show="show" class="w-full h-full">
        <!-- <template v-if="loading">
            <div class="relative flex items-center justify-center h-10">
                <Loading type="spin" />
            </div>
        </template>
        <template v-else>
        </template> -->
        <div class="flex items-center justify-between py-1 px-1 gap-1">
            <button
                type="button"
                class="
                    text-gray-600 text-sm
                    border-0
                    transition
                    hover:text-gray-800
                      
                    focus:outline-none
                    w-9
                    flex
                    justify-center
                "
                @click="show = false"
            >
                <span class="flex items-center">
                    <EcomIcon :source="icons.ChevronLeftMinor" :size="'w-5'"></EcomIcon>
                </span>

                <!-- <span>{{strResult(count)}}</span> -->
            </button>
            <div class="relative w-full flex-grow">
                <input
                    v-if="type != 'email' && type != 'phone'"
                    v-model="search"
                    type="text"
                    class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                    :placeholder="$t('search')"
                >
                <input v-else
                    type="text"
                    ref="email_or_phone"
                    v-on:keydown.enter="$emit('update:select', this.$refs.email_or_phone.value)"
                    class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                    :placeholder="type === 'email' ? $t('email') : $t('phone_number')"
                >
                
                <ecom-button v-if="type == 'email' || type == 'phone'" @click="$emit('update:select', this.$refs.email_or_phone.value)" :icon="icons.MobileAcceptMajor" class="absolute right-0 top-0 w-8 h-8 !bg-transparent !border-transparent"></ecom-button>
            </div>
        </div>

        <ul v-if="listData.length" ref="list" class="w-full">
            <ItemContent
                v-for="item in listData"
                :key="item.id"
                :item="item"
                :src="src"
                :offset-list="offsetList"
                @click="$emit('update:select', item.value)"
            />
            <li
                v-if="isNext && loadmore.loading"
                class="relative flex items-center justify-center h-10 text-center"
            >
                <Loading type="spin" />
            </li>
        </ul>
    </div>
</template>

<script>
import ItemContent from './ItemContent.vue';
import { mapGetters } from 'vuex';
import { ChevronLeftMinor, MobileAcceptMajor } from "@/assets/icons";
export default {
    name: 'ContentLink',
    components: {
        ItemContent,
    },
    props: {
        type: {
            type: String,
            default: 'collection'
        },
        src: {
            type: String,
            default: ''
        },
        scrolledBottom: {
            type: Boolean,
            default: false
        },
        offsetList: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    emits: ['update:select', 'hide', 'dispatchScroll'],
    data() {
        return {
            init: false,
            show: false,
            search: '',
            listData: [],
            count: 10,
            loading: true,
            loadmore: {
                loading: false
            },
            icons:{
                ChevronLeftMinor, MobileAcceptMajor
            }
        };
    },
    computed: {
        ...mapGetters('picker', { pickerData: 'data' }),
        ...mapGetters('picker', ['isLoadmore']),
        isNext() {
            return this.isLoadmore(this.type);
        }
    },
    watch: {
        type: function () {
            if (this.show) {
                this.listData = [];
                this.search = '';
                this.getData();
            }
        },
        show: function (val) {
            if (!val) {
                this.$emit('hide');
            }
        },
        search: function () {
            let itv = null;
            clearTimeout(itv);

            itv = setTimeout(() => {
                this.getData();
            }, 500)
        },
        scrolledBottom: function (val) {
            if (val && this.show && this.isNext && !this.loadmore.loading) {
                this.getData(true);
            }
        },
        loading: function (val) {
            !val && this.$emit('dispatchScroll');
        },
        'loadmore.loading': function (val) {
            !val && this.$emit('dispatchScroll');
        }
    },
    methods: {
        copy(obj) {
            return JSON.parse(JSON.stringify(obj));
        },
        strResult(count) {
            return count + ' '+ $t('result') + (count == 0 || count > 1 ? 's' : '');
        },
        getData(loadmore = false) {
            if (loadmore) {
                this.loadmore.loading = true;
            } else {
                this.loading = true;
            }
            if(this.type == 'email' || this.type == 'phone'){
                this.loading = false;
                return;
            }
            this.pickerData(this.type, '', this.search, loadmore).then((res) => {
                if (loadmore) {
                    this.listData = this.copy([...this.listData, ...res]);
                } else {
                    this.listData = this.copy(res);
                }
                this.loading = false;
                this.loadmore.loading = false;
                loadmore && (this.$parent.scroll.bottom = false);
            });
        }
    }
};
</script>

