<template>
    <div class="tab">
        <div class="tab__heading">
            <ul class="flex bg-surface-tertiary p-[3px] rounded-lg gap-[1px] h-8">
                <li
                    v-for="(tab, index) in options"
                    :key="tab.value"
                    class="flex items-center gap-[1px]"
                >
                    <button type="submit" class="flex overflow-hidden items-center justify-center w-full h-[26px] text-text-primary text-xs text-center align-middle font-normal px-3 whitespace-nowrap relative"
                        :class="[tabSelected === tab.value ? 'bg-white rounded shadow-tab' : 'hover:text-primary-700 transition-all ']" 
                        @click.prevent="tabSelected = tab.value"
                    >
                         
                        <span class="relative">{{ tab.text }}</span>
                    </button>
                    <div 
                        class="w-[1px] h-3 bg-tab-divider"
                        :class="index !== tabSelectedIndex && index !== options.length - 1 && tabSelectedIndex !== index + 1 ? 'opacity-100' : 'opacity-0'"
                    ></div>
                </li>
            </ul>
        </div>
    </div>
</template>

<script>
    import { WandCircleIcon } from '@/assets/icons';
    export default {
        name: 'Tabs',
        props: {
            options: {
                type: Array,
                default() {
                    return [];
                },
            },
            selectedTab: {
                type: String,
                default: '',
            }
        },
        data() {
            return {
                icons: {
                    WandCircleIcon
                }
            }
        },
        emits: ['update:selectedTab'],
        computed: {
            tabSelected: {
                get(){
                    return this.selectedTab && this.selectedTab !== '' ? this.selectedTab : (this.options[0]?.value ?? '');
                },
                set(val){
                    this.$emit('update:selectedTab', val);
                }
            },
            tabSelectedIndex(){
                return this.options.findIndex(tab => tab.value === this.tabSelected);
            }
        },
        mounted() {
            if (this.options.length > 0 && (!this.selectedTab || this.selectedTab === '')) {
                this.$emit('update:selectedTab', this.options[0].value);
            }
        }
    };
</script>
