export type LayoutItem = {
    i: string;
    left?: number;  // %
    top?: number;   // px
    width?: number; // px
    height?: number; // px
    rotation?: number;
    minW?: number;
    minH?: number;
    maxW?: number;
    maxH?: number;
    static?: boolean;
    moved?: boolean;
    isDraggable?: boolean;
    isResizable?: boolean;
    options?: any;
};
import { store } from "@/store";
export type Layout = Array<LayoutItem>;

/**
 * Trợ giúp lấy giá trị left từ item, ưu tiên sử dụng left, nếu không có thì dùng x
 */
function getItemLeft(item: LayoutItem): number {
    return item.left !== undefined ? item.left : (item.x || 0);
}

/**
 * Trợ giúp lấy giá trị top từ item, ưu tiên sử dụng top, nếu không có thì dùng y
 */
function getItemTop(item: LayoutItem): number {
    return item.top !== undefined ? item.top : (item.y || 0);
}

/**
 * Trợ giúp lấy giá trị width từ item, ưu tiên sử dụng width, nếu không có thì dùng w
 */
function getItemWidth(item: LayoutItem): number {
    return item.width !== undefined ? item.width : (item.w || 0);
}

/**
 * Trợ giúp lấy giá trị height từ item, ưu tiên sử dụng height, nếu không có thì dùng h
 */
function getItemHeight(item: LayoutItem): number {
    return item.height !== undefined ? item.height : (item.h || 0);
}

/**
 * Return the bottom coordinate of the layout.
 *
 * @param  {Array} layout Layout array.
 * @return {Number}       Bottom coordinate.
 */
export function bottom(layout: Layout): number {
    let max = 0, bottomY;
    for (let i = 0, len = layout.length; i < len; i++) {
        // Sử dụng top + height thay vì y + h
        bottomY = getItemTop(layout[i]) + getItemHeight(layout[i]);
        if (bottomY > max) max = bottomY;
    }
    return max;
}

export function cloneLayout(layout: Layout): Layout {
    const newLayout = Array(layout.length);
    for (let i = 0, len = layout.length; i < len; i++) {
        newLayout[i] = cloneLayoutItem(layout[i]);
    }
    return newLayout;
}

// Fast path to cloning, since this is monomorphic
export function cloneLayoutItem(layoutItem: LayoutItem): LayoutItem {
    return JSON.parse(JSON.stringify(layoutItem));
}

/**
 * Given two layoutitems, check if they collide.
 *
 * @return {Boolean}   True if colliding.
 */
export function collides(l1: LayoutItem, l2: LayoutItem): boolean {
    if (l1.i === l2.i) return false; // same element

    // Sử dụng left/width thay vì x/w
    const l1Left = getItemLeft(l1);
    const l1Width = getItemWidth(l1);
    const l2Left = getItemLeft(l2);
    const l2Width = getItemWidth(l2);

    // Sử dụng top/height thay vì y/h
    const l1Top = getItemTop(l1);
    const l1Height = getItemHeight(l1);
    const l2Top = getItemTop(l2);
    const l2Height = getItemHeight(l2);

    if (l1Left + l1Width <= l2Left) return false; // l1 is left of l2
    if (l1Left >= l2Left + l2Width) return false; // l1 is right of l2
    if (l1Top + l1Height <= l2Top) return false; // l1 is above l2
    if (l1Top >= l2Top + l2Height) return false; // l1 is below l2
    return true; // boxes overlap
}

/**
 * Given a layout, compact it. This involves going down each y coordinate and removing gaps
 * between items.
 *
 * @param  {Array} layout Layout.
 * @param  {Boolean} verticalCompact Whether or not to compact the layout
 *   vertically.
 * @return {Array}       Compacted Layout.
 */
export function compact(layout: Layout, verticalCompact: boolean): Layout {
    if (!verticalCompact) return [...layout];
    // Statics go in the compareWith array right away so items flow around them.
    const compareWith = getStatics(layout);
    // We go through the items by row and column.
    const sorted = sortLayoutItemsByRowCol(layout);
    // Holding for new items.
    const out = Array(layout.length);

    for (let i = 0, len = sorted.length; i < len; i++) {
        let l = sorted[i];

        // Don't move static elements
        if (!l.static) {
            l = compactItem(compareWith, l, verticalCompact);

            // Add to comparison array. We only collide with items before this one.
            // Statics are already in this array.
            compareWith.push(l);
        }

        // Add to output array to make sure they still come out in the right order.
        out[layout.indexOf(l)] = l;

        // Clear moved flag, if it exists.
        l.moved = false;
    }

    return out;
}

/**
 * Compact an item in the layout.
 */
export function compactItem(
    compareWith: Layout,
    l: LayoutItem,
    verticalCompact: boolean
): LayoutItem {
    if (verticalCompact) {
        // Move the element up as far as it can go without colliding.
        while (getItemTop(l) > 0 && !getFirstCollision(compareWith, l)) {
            // Cập nhật cả top và y để tương thích ngược
            if (l.top !== undefined) l.top--;
            if (l.y !== undefined) l.y--;
        }
    }

    // Move it down, and keep moving it down if it's colliding.
    let collides;
    while ((collides = getFirstCollision(compareWith, l))) {
        // Cập nhật cả top và y
        if (l.top !== undefined) l.top = getItemTop(collides) + getItemHeight(collides);
        if (l.y !== undefined) l.y = getItemTop(collides) + getItemHeight(collides);
    }
    return l;
}

/**
 * Given a layout, make sure all elements fit within its bounds.
 *
 * @param  {Array} layout Layout array.
 * @param  {Number} bounds Number of columns.
 */
export function correctBounds(layout: Layout, bounds: { cols: number }): Layout {
    const collidesWith = getStatics(layout);
    for (let i = 0, len = layout.length; i < len; i++) {
        const l = layout[i];

        // Lấy giá trị left và width
        const itemLeft = getItemLeft(l);
        const itemWidth = getItemWidth(l);

        // Overflows right
        if (itemLeft + itemWidth > bounds.cols) {
            // Cập nhật cả left và x
            if (l.left !== undefined) l.left = bounds.cols - itemWidth;
            if (l.x !== undefined) l.x = bounds.cols - itemWidth;
        }

        // Overflows left
        if (itemLeft < 0) {
            if (l.left !== undefined) l.left = 0;
            if (l.x !== undefined) l.x = 0;

            // Cập nhật cả width và w
            if (l.width !== undefined) l.width = bounds.cols;
            if (l.w !== undefined) l.w = bounds.cols;
        }

        if (!l.static) collidesWith.push(l);
        else {
            // If this is static and collides with other statics, we must move it down.
            // We have to do something nicer than just letting them overlap.
            while (getFirstCollision(collidesWith, l)) {
                if (l.top !== undefined) l.top++;
                if (l.y !== undefined) l.y++;
            }
        }
    }
    return layout;
}

/**
 * Get a layout item by ID. Used so we can override later on if necessary.
 *
 * @param  {Array}  layout Layout array.
 * @param  {String} id     ID
 * @return {LayoutItem}    Item at ID.
 */
export function getLayoutItem(layout: Layout, id: string): LayoutItem | undefined {
    for (let i = 0, len = layout.length; i < len; i++) {
        if (layout[i].i === id) return layout[i];
    }
}

/**
 * Returns the first item this layout collides with.
 * It doesn't appear to matter which order we approach this from, although
 * perhaps that is the wrong thing to do.
 *
 * @param  {Object} layoutItem Layout item.
 * @return {Object|undefined}  A colliding layout item, or undefined.
 */
export function getFirstCollision(layout: Layout, layoutItem: LayoutItem): LayoutItem | void {
    for (let i = 0, len = layout.length; i < len; i++) {
        if (collides(layout[i], layoutItem)) return layout[i];
    }
}

/**
 * Get layout items sorted from top left to right and down.
 *
 * @return {Array} Array of layout objects.
 * @return {Array}        Layout, sorted static items first.
 */
export function sortLayoutItemsByRowCol(layout: Layout): Layout {
    return [].concat(layout).sort(function (a, b) {
        // So sánh sử dụng top/left thay vì y/x
        const aTop = getItemTop(a);
        const aLeft = getItemLeft(a);
        const bTop = getItemTop(b);
        const bLeft = getItemLeft(b);

        if (aTop === bTop && aLeft === bLeft) {
            return 0;
        }

        if (aTop > bTop || (aTop === bTop && aLeft > bLeft)) {
            return 1;
        }

        return -1;
    });
}
/**
 * Convert string values to numeric values with optional unit extraction
 */
export function ensureNumericValue(value: any, returnUnit = false): any {
    if (typeof value === "string" && value !== "auto") {
        // Tìm đơn vị trong chuỗi (px, %, vv...)
        const match = value.match(/^([\d.-]+)(.*)$/);
        if (match) {
            const numValue = parseFloat(match[1]);
            const unit = match[2] || "px"; // Mặc định là px nếu không có đơn vị
            return returnUnit ? { value: numValue, unit } : numValue;
        }
    }
    return returnUnit ? { value, unit: "px" } : value;
}

/**
 * Add unit to values that don't have units
 */
export function addUnit(value: any, defaultUnit = "px"): string {
    if (value === undefined || value === null) return "0" + defaultUnit;

    // Nếu đã có đơn vị, trả về nguyên giá trị
    if (typeof value === "string" && /\d(px|%|rem|em|vh|vw)$/.test(value)) {
        return value;
    }

    // Thêm đơn vị mặc định vào giá trị số
    return value + defaultUnit;
}
/**
 * Checks if the provided width value is specified as a percentage.
 *
 * @param width - The width value to check
 * @returns `true` if the width is a string containing the '%' character, `false` otherwise
 */
export function isPercentWidth(width: any): boolean {
    return typeof width === "string" && width.includes("%");
}
/**
 * Converts a width value to pixels based on container width.
 * If the width is already expressed as a percentage string (e.g., '50%'),
 * it converts that percentage to equivalent pixels based on the container width.
 * Otherwise, returns the width value unchanged.
 *
 * @param width - The width value to convert (can be a percentage string or number)
 * @param containerWidth - The width of the container in pixels
 * @returns The width in pixels
 */
export function widthPxCalculate(width: any, containerWidth: number): number {
    if (isPercentWidth(width)) {
        return parseFloat(width) / 100 * containerWidth;
    }
    return width;
}
export function handleSetHistorySelection(section: any, dataIds: string[], screen: string, action: string) {
    let data = [];
    dataIds.forEach((id) => {
        const block = section.blocks.find((b) => b.id == id);
        if(block) {
            switch(action) {
                case "duplicated":
                case "deleted":
                    block.i = id;
                    data.push(block);
                    break;
                case "resized":
                case "moved":
                    const layouts = block.layouts[screen] || block.layouts.desktop;
                    data.push({
                        i: id,
                        left: layouts.left,
                        top: layouts.top,
                        width: layouts.width,
                        height: layouts.height,
                        rotation: layouts.rotation,
                        zindex: layouts.zindex,
                    });
                    break;
            }
        }
    });
    let payload = {
        type: "selection",
        data: data,
        section_id: section.id,
        action: action,
        screen: screen,
    };
    store.dispatch("history/addStack", payload);
}
export function handleSetHistoryGroup(section: any, dataIds: string[], screen: string, action: string, activeGroup: string, groupData = null) {
    let data = [];
    dataIds.forEach((id) => {
        const block = section.blocks.find((b) => b.id == id);
        if(block) {
            switch(action) {
                case "duplicated":
                case "deleted":
                    block.i = id;
                    data.push(block);
                break;
                case "grouped":
                    block.i = id;
                    data.push(block);
                    break;
                case "zindexed":
                case "resized":
                case "moved":
                    const layouts = block.layouts[screen] || block.layouts.desktop;
                    data.push({
                        i: id,
                        left: layouts.left,
                        top: layouts.top,
                        width: layouts.width,
                        height: layouts.height,
                        rotation: layouts.rotation,
                        zindex: layouts.zindex,
                    });
                    break;
            }
        }
    });
    let payload = {
        type: "group",
        data: data,
        section_id: section.id,
        action: action,
        screen: screen,
        activeGroup: activeGroup,
        groupData: groupData
    };
    store.dispatch("history/addStack", payload);
}