<template>
    <div class="ecom-element ecom-product-single ecom-product-single__description">
        <div class="ecom-product-single__description-wrapper">
            <div class="ecom-product-single__description-container" :data-show-type="type">
                <template v-if="contentType === 'text'">
                    <div v-if="type === 'short' || type === 'full'"
                        class="ecom-product-single__description--paragraph">
                        <div class="ecom-text-des" :class="{'ecom-view-more-enable': data.settings?.view_more}" v-html="liquid(description_short)" />
                        <div class="ecom-product-single__description--more-actions" v-if="type === 'short' && view_more" v-html="liquid('view_more_btn')" />
                    </div>
                    <div
                        v-if="type === 'short' && view_more"
                        style="display: none"
                        class="ecom-product-single__description--full"

                    >
                        <div class="ecom-product-single__description--full-content" v-html="liquid('description_text')" />
                        <div class="ecom-product-single__description--less-actions" v-if="type === 'short' && view_more" v-html="liquid('view_less_btn')" />
                    </div>
                    <div v-if="type === 'tab'"
                        class="ecom-product-description__tabs-wrapper"
                        v-html="liquid('tab')"
                    />
                    <div v-if="type === 'accordion'"
                        class="ecom-product-description__accordion-wrapper ecom-w__full"
                        v-html="liquid('accordion')"
                    >
                </div>
                </template>
                <template v-else>
                    <div v-if="data.settings?.type !== 'tab' && data.settings?.type !== 'accordion'"
                        class="ecom-product-single__description--paragraph"
                    >
                    <div class="ecom-html-des" :class="{'ecom-view-more-enable': data.settings?.view_more}" v-html="liquid(description_short)" :style="{ 'max-height': 'var(--ecom-description-height)' ,'--ecom-description-height': maxHeight}"/>
                    </div>
                    <div class="ecom-product-single__description--more-actions" v-if="type === 'short' && view_more" v-html="liquid('view_more_btn')" />
                    <div class="ecom-product-single__description--less-actions" v-if="type === 'short' && view_more" v-html="liquid('view_less_btn')" />
                    <div v-if="type === 'tab'"
                    class="ecom-product-description__tabs-wrapper"
                    v-html="liquid('tab')"
                    />
                    <div v-if="type === 'accordion'"
                    class="ecom-product-description__accordion-wrapper"
                    v-html="liquid('accordion')"
                    />
                </template>
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
import { addSwitch } from "@/plugins/fields/utils";
export default {
    name: 'productDescription',

    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data(){
        return {
            jsreactives: ['view_more_text','view_more','type','content_type','disable_auto_close', 'close_all', 'disable_effect']
        }
    },
    computed: {
        wrapper_class() {
            return `ecom-product-description__accordion ecom-w__full ${this.data.settings?.close_all ? 'ecom-accordion-close-all' : ''} ${this.data.settings.disable_effect ? 'ecom-product-description-accordion__body--auto-height' : ''}`;
        },
        splitDescription(){
            return `{%- capture tab_tag -%}${this.data.settings?.tag ? this.data.settings?.tag : 'h2'}{%- endcapture -%}
                    {%-liquid
                        assign tab = ''
                        assign des_content = ''
                        assign filter_before = tab_tag | prepend: '<' | append: '>'
                        assign filter_after = tab_tag | prepend: '</' | append: '>'
                        assign desciption_split = product.description | split: filter_before
                        assign desciption_split1 = product.description | split: filter_after
                        assign flag = 0
                        assign flag1 = 0
                        for content in desciption_split offset: 1
                            assign d_split = content | split : filter_after
                            if d_split[0] == blank and flag == 0
                                continue
                            endif
                            assign flag = 1
                            assign tab = tab | append: d_split[0] | strip ${this.contentType == 'text' ? '| strip_html' : ''}
                            assign tab = tab | append: '#ecomsplitparent#'
                        endfor
                        for content in desciption_split1 offset: 1
                            assign c_split = content | split : filter_before
                            assign des_content = des_content | append: c_split[0] | strip ${this.contentType == 'text' ? '| strip_html' : ''}
                            assign des_content = des_content | append: '#ecomsplitparent#'
                        endfor
                        assign contents = des_content | split: '#ecomsplitparent#'
                        assign tabs = tab | split: '#ecomsplitparent#'
                    -%}`
        },
        css() {
            return `
                .ecom-product-single__description--paragraph, .ecom-product-single__description-view-more-btn {
                    overflow: hidden;
                }
                .ecom-product-single__description--paragraph[style*="max-height"] {
                    position: relative;
                }
                .ecom-product-single__description-container[data-show-type="short"] .ecom-product-single__description--paragraph .ecom-text-des.ecom-view-more-enable{
                    position: relative;
                }
                .ecom-product-single__description-container[data-show-type="short"] .ecom-product-single__description--paragraph .ecom-text-des.ecom-view-more-enable:after {
                    content: '';
                    position: absolute;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    height: 150px;
                }
                .ecom-product-single__description-container[data-show-type="short"] .ecom-product-single__description--paragraph .ecom-html-des.ecom-view-more-enable[style*="max-height"]{
                    position: relative;
                }
                .ecom-product-single__description-container[data-show-type="short"] .ecom-product-single__description--paragraph .ecom-html-des.ecom-view-more-enable[style*="max-height"]:after {
                    content: '';
                    position: absolute;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    height: 150px;
                }
                .ecom-product-single__description-view-more-btn{
                    cursor:pointer;
                    display:block;
                }
                .ecom-product-single__description-container span {
                    display: inline;
                }
                .ecom-product-single__description--more-actions, .ecom-product-single__description--less-actions{
                    display: flex;
                    position: relative;
                    width: 100%;
                }
                .ecom-product-single__description--more-actions button, .ecom-product-single__description--less-actions button{
                    display: flex;
                    align-items: center;
                    align-content: center;
                }
                .ecom-product-description-tab__items .ecom-product-description-tab__item {
                    margin: 0;
                    list-style: none;
                    padding: 10px;
                    cursor: pointer;
                }
                .ecom-product-description__tabs-wrapper {
                    padding: 5px;
                }
                .ecom-product-description__tabs-wrapper .ecom-product-description-tab__content {
                    display: none;

                }
                .ecom-product-description__tabs-wrapper .ecom-product-description-tab__content.ecom-item-active {
                    display: block;
                }
                .ecom-product-description__accordion{
                    display: flex;
                    flex-direction: column;
                }
                .ecom-product-description__accordion-item{
                    display: flex;
                    flex-direction: column;
                }
                .ecom-product-description__accordion-title{
                    display: flex;
                    width: 100%;
                    flex-direction: row;
                    padding: 0px 32px 0px 32px;
                    margin-top: 16px;
                    align-items: center;
                    cursor: pointer;
                }
                .ecom-product-description__accordion-icon{
                    display: flex;
                    align-items: center;
                    color: #444;
                    margin-right: 25px;
                }
                .ecom-product-description__accordion-icon svg {
                    height: 13px;
                    width: 13px;
                }
                .ecom-product-description__accordion-title-text{
                    display: flex;
                    flex: 1;
                }
                .ecom-product-description__accordion .ecom-product-description__accordion-item {
                    width: 100%;
                    transition: all 500ms ease;
                }
                .ecom-product-description__accordion .ecom-product-description_accordion-content-wrapper{
                    display: flex;
                    width: 100%;
                    align-items: center;
                }
                .ecom-product-description__accordion .ecom-product-description_accordion-content{
                    padding: 0px 32px 0px 70px;
                }
                .ecom-product-description__accordion.ecom-product-description-accordion__body--auto-height .ecom-product-description__accordion-item.ecom-item-active .ecom-accordion__body{
                    height:auto;
                }
                .ecom-product-description__accordion .ecom-product-description__accordion-item.ecom-item-active .ecom-accordion__body{
                    opacity: 1;
                }
                .ecom-product-description__accordion .ecom-product-description__accordion-icon--active {
                    display: none;
                }
                .ecom-product-description__accordion .ecom-accordion__body{
                    display: block;
                    overflow: hidden;
                    margin: 0;
                    border: 0;
                    opacity: 0;
                    box-sizing: border-box;
                    transition:height 300ms ease-out;
                }
                .ecom-product-description__accordion-item.ecom-item-active .ecom-product-description__accordion-icon.ecom-product-description__accordion-icon--active{
                    display:flex;
                }
                .ecom-product-description__accordion-item.ecom-item-active .ecom-product-description__accordion-icon:not(.ecom-product-description__accordion-icon--active){
                    display:none;
                }
                .ecom-items--text>* {
                    font-family: inherit;
                    font-style: inherit;
                    font-weight: inherit;
                    letter-spacing: inherit;
                    color: inherit;
                    line-height: inherit;
                    word-break: inherit;
                    font-size: inherit;
                }
                .ecom-items--text {
                    color: #333;
                }
            `;
        },

        description_short() {
            return this.contentType === 'text'
                ? this.type === 'short'
                    ? 'short_description'
                    : 'description_text'
                : 'description';
        },
        maxHeight() {
            return this.contentType === 'html' && this.data?.settings?.type === 'short'
                ? this.data.settings['max-height']
                : null;
        },
        javascript() {
            return function () {
                /**
                 * this.settings.view_more
                 * this.settings.view_more_text
                 */
                if(!this.$el) {
                    return;
                }
                const $dom = this.$el.querySelector(
                    '.ecom-product-single__description-view-more-btn'
                );
                if(this.settings.type === 'tab') {
                    const tabs = this.$el.querySelectorAll('.ecom-product-description-tab__item'),
                        tabsBody = this.$el.querySelectorAll('.ecom-product-description-tab__content');
                    if(tabs.length) {
                        tabs.forEach((tab, index) => {
                            tab.onclick = function () {
                                if( this.classList && !this.classList.contains("ecom-item-active"))
                                {
                                    tabs.forEach((item) => item.classList.remove("ecom-item-active"));
                                    tabsBody.forEach((item) => item.classList.remove("ecom-item-active"));
                                    tab.classList.add("ecom-item-active");
                                    tabsBody[index].classList.add("ecom-item-active");
                                }
                            };
                        });
                    }
                }
                if(this.settings.type === 'accordion'){
                    const disable_auto_close = this.settings.disable_auto_close ?? false;
                    const disable_auto_close__tablet = this.settings.disable_auto_close__tablet ?? false;
                    const disable_auto_close__mobile = this.settings.disable_auto_close__mobile ?? false;
                    const disable_effect = this.settings.disable_effect ?? false;
                    const accordionTitles = this.$el.querySelectorAll('.ecom-product-description__accordion-item > .ecom-product-description__accordion-title');
                    function handleAccordionClosse(item) {
                        item.classList.remove("ecom-item-active");
                        item.querySelector(".ecom-accordion__body").style.height = "0";
                    }
                    function handle(accordionTitles) {
                        accordionTitles.forEach((accordion, index) => {
                            let parent = accordion.parentNode;
                            let accordionBody = parent.querySelector(".ecom-accordion__body");
                            if (!disable_effect && accordionBody) {
                                accordionBody.classList.add("ecom-effect-accodion");
                            }
                            if (index == 0 && parent.querySelector('.ecom-item-active')) {
                                accordionBody.style.height = !disable_effect ? accordionBody.clientHeight + "px": 'auto';
                            }else{
                                accordionBody.style.height = 0;
                            }
                            accordion.onclick = function (e) {
                                e.preventDefault();
                                let titleParent = this.parentNode;
                                let accWrapper = parent.parentNode;
                                let accordionItems =  accWrapper.querySelectorAll(".ecom-product-description__accordion-item");
                                let title = accWrapper.querySelectorAll(".ecom-product-description__accordion-title");
                                if (this.classList && this.classList.contains("ecom-item-active")) {
                                    if (
                                        (disable_auto_close__mobile && innerWidth < 768) ||
                                        (disable_auto_close__tablet &&
                                            innerWidth > 767 &&
                                            innerWidth < 1025) ||
                                        (disable_auto_close && innerWidth > 1024)
                                    ) {
                                        this.classList.remove("ecom-item-active");
                                        parent.querySelector(".ecom-accordion__body").style.height = "0px";
                                        parent.classList.remove("ecom-item-active");
                                    } else {
                                        accordionItems.forEach((item) => handleAccordionClosse(item));
                                        title.forEach((item) =>
                                            item.classList.remove("ecom-item-active")
                                        );
                                    }
                                }
                                else {
                                    if (
                                        !((disable_auto_close__mobile && innerWidth < 768) || (disable_auto_close__tablet && innerWidth > 767 &&innerWidth < 1025) ||(disable_auto_close && innerWidth > 1024))
                                    ) {
                                        accordionItems.forEach((item) => handleAccordionClosse(item));
                                        title.forEach((item) =>
                                            item.classList.remove("ecom-item-active")
                                        );
                                    }
                                    accordion.classList.add("ecom-item-active");
                                    titleParent.classList.add("ecom-item-active");
                                    let tmp = accordion.parentNode.querySelector(".ecom-accordion__body");
                                    let height = "auto";
                                    if (!disable_effect) {
                                        height = tmp.scrollHeight + "px";
                                        tmp.classList.add("ecom-effect-accodion");
                                    }
                                    setTimeout(()=>{
                                        tmp.style.height = height;

                                    },20);
                                }
                            }
                        })
                    }
                    handle(accordionTitles);
                }
                const contentType = this.settings.content_type;
                const $full = this.$el.querySelector('.ecom-product-single__description--full');
                const $less = this.$el.querySelector('.ecom-product-single__description-view-less-btn');
                const $short_text_des = this.$el.querySelector('.ecom-product-single__description--paragraph .ecom-text-des');
                const $short = this.$el.querySelector('.ecom-product-single__description--paragraph .ecom-html-des');
                if ($dom) {
                    $dom && $dom.addEventListener('click', function () {
                        if (contentType === 'text' && $full) {
                            $full.style.display = 'block';
                            $short_text_des.style.display = 'none';
                        } else {
                            $short.style.maxHeight = null;
                        }
                        this.style.display = 'none';
                        if($less)
                            $less.style.display = 'flex';
                    });
                    $less && $less.addEventListener('click', function(){
                        $dom.style.display = 'flex';
                        this.style.display = 'none';
                         if (contentType === 'text' && $full) {
                            if($full)
                                $full.style.display = 'none';

                            $short_text_des.style.display = 'block';
                        } else {
                            $short.style.maxHeight = 'var(--ecom-description-height)';
                        }
                    });
                }
            };
        },

        limit() {
            return  this.data?.settings?.limit && parseInt(this.data.settings.limit) > 0? parseInt(this.data.settings.limit): 50;
        },
        icon(){
            return this.data.settings?.show_icon && this.data.settings?.icon?.value ? this.data.settings.icon.value : (!this.data.settings?.show_icon ? '' : '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" fill=\"currentColor\"><path d=\"M 15 5 L 15 15 L 5 15 L 5 17 L 15 17 L 15 27 L 17 27 L 17 17 L 27 17 L 27 15 L 17 15 L 17 5 Z\"></path></svg>');
        },
        iconActive(){
            return this.data.settings?.show_icon && this.data.settings?.iconActive?.value ? this.data.settings.iconActive.value : (!this.data.settings?.show_icon ? '' : '<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"feather feather-minus\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>');
        },
        liquids() {
            return {
                accordion:{
                    code: `
                        ${this.splitDescription}
                        <div class="${this.wrapper_class}">
                            {%- if tabs.size > 0-%}
                                {%- for tab in tabs -%}
                                    <div class="ecom-product-description__accordion-item {% if forloop.first and ${!this.data.settings?.close_all} %}ecom-item-active {% endif %}">
                                        <div class="ecom-product-description__accordion-title  {% if forloop.first and ${!this.data.settings?.close_all} %}ecom-item-active {% endif %}">
                                            <div class="ecom-product-description__accordion-icon ecom-items--icon"
                                            style="order: ${this.data.settings?.iconPosition}">
                                                ${this.icon}
                                            </div>
                                            <div class="ecom-product-description__accordion-icon ecom-items--icon ecom-product-description__accordion-icon--active"
                                            style="order: ${this.data.settings?.iconPosition}">
                                                ${this.iconActive}
                                            </div>
                                            <div class="ecom-product-description__accordion-title-text ecom-items--text">
                                                    <${this.data.settings?.tag?.toLowerCase() || 'h3'}>{{tab}}</${this.data.settings?.tag?.toLowerCase() || 'h3'}>
                                            </div>
                                        </div>
                                        <div class="ecom-product-description_accordion-content-wrapper ecom-accordion__body">
                                            <div class="ecom-product-description_accordion-content">
                                                    {%- assign content_index = forloop.index0 -%}
                                                    {%- if content_index < contents.size -%}
                                                        {{ contents[content_index] }}
                                                    {%- else -%}
                                                        <p>No content available for this tab.</p>
                                                    {%- endif -%}
                                            </div>
                                        </div>
                                    </div>
                                {%- endfor -%}
                            {%- elsif tabs.size == 0 and EComBuilderMode-%}
                                <p>No navigator match {{ tab_tag }} HTML tag</p>
                            {%- endif -%}
                        </div>
                    `,
                    preview: `
                        <div class="ecom-skeleton-item ecom__row">
                            <div class="ecom-skeleton-col-12 ecom-col-12">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-12"></div>
                                    <div class="ecom-skeleton-col-2"></div>
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-big"></div>
                                    <div class="ecom-skeleton-col-4 ecom-skeleton-big ecom-skeleton-empty"></div>
                                </div>
                            </div>
                        </div>`
                },
                tab: {
                    code: `
                        ${this.splitDescription}
                        {%- if tabs.size > 0-%}
                            <div class="ecom-product-description-tab__items ecom-flex fl_wrap">
                            {%- for tab in tabs -%}
                                <div class="ecom-product-description-tab__item ecom-flex ecom-al_center ecom-fl_center {% if forloop.index == 1 %} ecom-item-active {% endif %}">
                                    <${this.data.settings?.tag?.toLowerCase() || 'h3'}> {{tab}} </${this.data.settings?.tag?.toLowerCase() || 'h3'}>
                                </div>
                            {%- endfor -%}
                            </div>
                            <div class="ecom-product-description_tab-content--items">
                                {% if contents.size > tabs.size %}
                                    {% assign start = contents.size | minus: tabs.size %}
                                    {% assign end = contents.size | minus: 1 %}
                                {% else %}
                                    {% assign start = 0 %}
                                    {% assign end = tabs.size | minus: 1 %}
                                {% endif %}
                                {%- for i in (start..end) -%}
                                    <div class="ecom-product-description-tab__content {% if forloop.index == 1 %} ecom-item-active {% endif %}">
                                        {{contents[i]}}
                                    </div>
                                {%- endfor -%}
                            </div>
                        {%- elsif tabs.size == 0 and EComBuilderMode-%}
                            <p>No navigator match {{ tab_tag }} HTML tag</p>
                        {%- endif -%}
                        `,
                    preview: `
                        <div class="ecom-skeleton-item ecom__row">
                            <div class="ecom-skeleton-col-12 ecom-col-12">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-12"></div>
                                    <div class="ecom-skeleton-col-2"></div>
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-big"></div>
                                    <div class="ecom-skeleton-col-4 ecom-skeleton-big ecom-skeleton-empty"></div>
                                </div>
                            </div>
                        </div>`
                },
                description: {
                    code: '{{product.description}}',
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-10 big"></div>
                                <div class="ecom-skeleton-col-2 ecom-skeleton-empty big"></div>
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-12"></div>
                            </div>
                        </div>
                    `
                },
                description_text: {
                    code: '{{product.description | strip_html }}',
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-10 big"></div>
                                <div class="ecom-skeleton-col-2 ecom-skeleton-empty big"></div>
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-12"></div>
                            </div>
                        </div>
                    `
                },
                short_description: {
                    code: `
                        <div>{{ product.description | strip_html | truncatewords: ${this.limit} }}</div>
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div>
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-4"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-6"></div>
                                    <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-2"></div>
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                                </div>
                            </div>
                        </div>
                    `
                },
                view_more_btn: {
                    code: `
                        {%- unless product.description == blank -%}
                            <button
                                type="button"
                                class="ecom-product-single__description-view-more-btn"
                            >
