<template>
    <Liquid v-if="conditionLiquid?.start && exporting" :data="conditionLiquid.start"></Liquid>
    <component
        :is="data?.settings?.tag ?? 'div'"
        v-bind="colAttrs"
        @mouseenter="overCol"
        @mouseleave="outCol"
        @contextmenu.stop="rightClickMenu"
        @click="activeCol"
    >
        <template v-if="displaySettings">
            <div
                class="core__column--settings"
                :style="styleattr.settings"
                @mousedown="startDrag"
                @click.prevent.stop="editCol"
            >
                <div class="core__column--settings-actions">
                    <span
                        v-if="over && isActive"
                        class="core--settings__back core__column--settings__back"
                        @click.prevent.stop="handleBack2Parent"
                        :title="$t('back_to_parent')"
                    >
                        <EcomIcon :source="icons.backIcon" class="icon-builder"></EcomIcon>
                    </span>
                    <span v-if="isResizing" class="core__column--resize-value">{{ scwidth }}</span>
                    <span :title="$t('edit_column')" class="core__column--settings__edit">
                        <span class="w-5 icon-builder">
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
                                <path
                                    d="M493.3 56.3l-37.5-37.5C443.3 6.3 426.9 0 410.5 0s-32.8 6.3-45.3 18.7L12.9 371.1 .2 485.3C-1.5 499.7 9.9 512 24 512c.9 0 1.8-.1 2.7-.2l114.1-12.6 352.5-352.5c25-25 25-65.5 0-90.5zM126.1 468.7l-93 10.3 10.4-93.2 263.9-263.9 82.8 82.8-264 264zm344.5-344.5l-57.9 57.9-82.8-82.8 57.9-57.9c6-6 14.1-9.4 22.6-9.4 8.6 0 16.6 3.3 22.6 9.4l37.5 37.5c12.5 12.5 12.5 32.8 0 45.3z"
                                />
                            </svg>
                        </span>
                    </span>
                    <!-- <svg class="core--settings__edit-icon" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg"><path fill-rule="evenodd" d="M15.655 4.344a2.695 2.695 0 0 0-3.81 0l-.599.599-.009-.009-1.06 1.06.008.01-5.88 5.88a2.75 2.75 0 0 0-.805 1.944v1.922a.75.75 0 0 0 .75.75h1.922a2.75 2.75 0 0 0 1.944-.806l7.54-7.539a2.695 2.695 0 0 0 0-3.81Zm-4.409 2.72-5.88 5.88a1.25 1.25 0 0 0-.366.884v1.172h1.172c.331 0 .65-.132.883-.366l5.88-5.88-1.689-1.69Zm2.75.629.599-.599a1.195 1.195 0 1 0-1.69-1.689l-.598.599 1.69 1.689Z" fill="currentColor"></path></svg> -->
                </div>
            </div>
        </template>
        <template v-if="displayDrag">
            <template v-if="canDrop">
                <div
                    class="placeholder__left"
                    :class="{
                        'drop__placeholder--column': dropPos == 'left' && dropToPlaceholder
                    }"
                    @mouseenter="placehover"
                    @mouseleave="outPlaceHover"
                />
                <div
                    class="placeholder__right"
                    :class="{
                        'drop__placeholder--column': dropPos == 'right' && dropToPlaceholder
                    }"
                    @mouseenter="placehover"
                    @mouseleave="outPlaceHover"
                />
            </template>
        </template>

        <div
            class="core__column--wrapper"
            :id="this.data.id"
            :class="[
                data.settings['align-content__mobile'] ? 'ecom__column-full-height' : '',
                needReplaceBg ? 'ecom-replace-notice-column' : ''
            ]"
        >
            <div v-if="is == 'column'" class="ecom-column__overlay">
                <video
                    v-if="
                        show_video_background &&
                        ['upload', 'external'].includes(data?.settings?.source)
                    "
                    class="ecom-video-background"
                    @loadeddata="handleLoadVideo"
                    v-bind="attrVideo"
                    :data-play-pause-inview="data.settings?.inview_playpause"
                    :src="video_url"
                    ref="video"
                />
                <div
                    class="ecom-video-background-youtube"
                    v-if="
                        show_video_background &&
                        ['youtube', 'vimeo'].includes(data?.settings?.source)
                    "
                >
                    <iframe
                        class="ecom-video-background"
                        frameborder="0"
                        allowfullscreen="1"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        style="border: 0; width: 100%; height: 100% !important"
                        :src="data?.settings?.source == 'vimeo' ? linkVimeo : linkYoutube"
                    />
                </div>
                <div class="ecom-overlay" />
            </div>
            <Blocks
                :data="colBlocks()"
                :deep="deep"
                :index="index"
                :section_id="section_id"
                :breadcrumb="`${breadcrumb}/${data?.id}`"
                :dragParent="dragColMe"
            />
        </div>
        <div
            v-if="!exporting"
            v-show="(!lastCol && screen == 'desktop' && $parent.over) || isResizing"
            class="core__column--resize"
            @mousedown.prevent.stop="startResize"
        />
    </component>
    {{ exporting === true && conditionLiquid?.start ? conditionLiquid?.end : "" }}
</template>

<script lang="ts">
import Blocks from "./Blocks.vue";
import { Core, Element, Liquid } from "@/mixins";
import { mapGetters } from "vuex";
import { backIcon } from "@/assets/icons";
import { getIdParentAndIndex } from "@/utils/helpers";
export default {
    name: "Column",
    components: { Blocks },
    mixins: [Core, Element, Liquid],
    props: {
        data: {
            type: Object,
            default() {
                return {
                    columns: []
                };
            }
        },
        deep: {
            type: Number,
            default: 0
        },
        section_id: {
            type: String,
            default: ""
        },
        index: {
            type: Number,
            default: 0
        },
        breadcrumb: {
            type: String,
            default: ""
        },
        dragParent: {
            type: Boolean,
            default: false
        },
        inGrid: {
            type: Boolean,
            default: false
        }
    },
    data() {
        return {
            is: "column",
            name: this.$t("column"),
            over: false,
            hovered: false,
            dragging: false,
            validElements: ["heading", "text", "image", "divi"],
            needReplaceBg: false,
            isResizing: false,
            mouseOver: false,
            timmer: 0
            // actionable: false
        };
    },
    computed: {
        locked() {
            return this.$store.getters["builder/editorConfigs"]?.locked;
        },
        icons() {
            return {
                backIcon
            };
        },
        conditionLiquid() {
            if (!this.condition) return {};
            let liquids = {
                start: `
                        {% assign condition = true %}
                        ${this.condition ? this.condition : ""}
                        {% if condition %}
                    `,
                end: `
                        {% endif %}
                    `
            };
            return liquids;
        },
        attrVideo() {
            return {
                controls: false,
                autoplay: this.data?.settings?.autoplay,
                loop: this.data?.settings?.loop,
                playsinline: this.data?.settings?.autoplay,
                preload: this.data?.settings?.autoplay ? true : false,
                "data-ecom-muted": this.exporting && this.data?.settings?.muted
            };
        },
        stack() {
            return this.$parent.columns;
        },

        blocks() {
            return this.column.blocks;
        },

        column() {
            return this.data;
        },

        width() {
            return this.column.width;
        },

        auwidth() {
            return this.column?.settings?.width ? this.column.settings.width : 0;
        },

        scwidth() {
            return (
                parseInt(
                    this.column?.settings?.[
                        "width" + (this.screen == "desktop" ? "" : "__" + this.screen)
                    ] ?? this.width
                ) + "%"
            );
        },

        firstCol() {
            return this.index == 0;
        },

        lastCol() {
            if (this.$parent?.row) {
                return this.index == this.$parent.row.columns.length - 1;
            }
            return false;
        },

        styleattr() {
            let bg = null;
            if(this.exporting && this.data?.settings?.dynamic_background && ['product','collection','article'].includes(this.params.page) )
            {
                bg = "{{"+this.params.page+" | image_url: width: 2048 }}";
                bg = 'url(\'liquid[['+ encodeURIComponent(bg)+']]\')';
            }
            const attrs = {
                wrapper: {
                    cursor: this.exporting || !this.inGrid ? "" : "move",
                    width:
                        this.exporting === false && this.screen == "desktop"
                            ? this.column.width + "%"
                            : ""
                },
                settings: `display:inline-block;z-index: 20`
                // settings: `display: ${
                //     this.over && !this.isDragging ? 'inline-block' : 'none'
                // };z-index: 20`
            };
            // console.log(this.data.id, this.isActive, this.stack.length > 1, this.width !== 100, !this.isDragging)
            if (this.isEditing) {
                attrs.wrapper.outline = "1px solid rgb(var(--primary-color-active))";
            } else if (this.displayBorder) {
                attrs.wrapper.outline = "1px dashed var(--color-line-v2-40)";
            }
            if (this.scrollingAnimation) {
                attrs["ecom-scrolling-animation"] = this.scrollingAnimation;
            }

            return attrs;
        },
        displaySettings() {
            return !this.exporting && (this.over || this.isEditing) && !this.isDragging;
        },
        displayBorder() {
            return !this.exporting && (this.hovered || this.over || this.isEditing);
        },
        isActive() {
            return (
                !this.isFullScreen &&
                this.exporting === false &&
                // this.over ||
                (this.activeElement?.data?.id === this.data.id ||
                    this.editingElement?.data?.id === this.data.id) &&
                (!this.dragCurrent || this.dragCurrent.is != "section")
            );
        },
        displayDrag() {
            return (
                !this.isFullScreen &&
                this.exporting === false &&
                (this.over ||
                    this.activeElement?.data?.id === this.data.id ||
                    this.editingElement?.data?.id === this.data.id) &&
                (!this.dragCurrent || this.dragCurrent.is != "section")
            );
        },
        isEditing() {
            return this.editingElement?.data?.id === this.data.id;
        },
        dragColMe() {
            return this.dragCurrent === this;
        },

        dropToPlaceholder() {
            return this.dropTo && this.canDrop;
        },

        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this);
        },

        show_video_background() {
            return (
                this.is === "column" &&
                ["upload", "external", "youtube", "vimeo"].includes(this.data.settings?.source)
            );
        },

        video_url() {
            let source = this.data?.settings?.source;
            if (!["upload", "external"].includes(source)) {
                return "";
            }
            if (source === "upload") {
                return this.data?.settings.video?.value ?? "";
            }
            return this.data?.settings?.url ?? "";
        },

        linkVimeo() {
            if (this.data?.settings?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.data?.settings?.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?controls=0&autoplay=${
                    this.data?.settings?.autoplay ? 1 : 0
                }&muted=${this.data?.settings?.muted || this.data?.settings?.autoplay ? 1 : 0}${
                    this.data?.settings?.start_time
                        ? "&byline=1#t=00h00m" + this.data?.settings?.start_time + "ss"
                        : ""
                }&showinfo=0&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&loop=${
                    this.data?.settings?.loop ? 1 : 0
                }`;
            } else {
                return "";
            }
        },

        linkYoutube() {
            if (this.data?.settings?.srcYoutube) {
                const regExpYt = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
                let val = this.data?.settings?.srcYoutube.match(regExpYt);
                let videoIdYt = val && val[2].length === 11 ? val[2] : null;
                return `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3?${
                    this.data?.settings?.start_time
                        ? "&start=" + this.data?.settings?.start_time
                        : ""
                }${
                    this.data?.settings?.end_time ? "&end=" + this.data?.settings?.end_time : ""
                }&controls=0&mute=${
                    this.data?.settings?.muted ? 1 : 0
                }&showinfo=0&iv_load_policy=3&playlist=${videoIdYt}&autoplay=${
                    this.data?.settings?.autoplay ? 1 : 0
                }&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },

        colAttrs() {
            let delayValue = null;
            if (this.data?.advanced?.animation_delay) {
                delayValue = this.data.advanced.animation_delay.toString().replace(/ms$/, '');
            }
            return {
                //id: this.data.id,
                style: this.styleattr.wrapper,
                ref: "wrapper",
                key: this.column.refresh,
                class: {
                    "ecom-column ecom-core": true,
                    "core__column--first": this.firstCol,
                    "core__column--last": this.lastCol,
                    "ecom-animated": !this.exporting,
                    "ecom-animation": this.data?.advanced?.animation_type,
                    ...this.classes
                },
                "ec-delay": delayValue,
                ...this.attributes
            };
        },
        settings() {
            let settings = [
                {
                    group_title: this.$t("general"),
                    params: [
                        {
                            type: "number",
                            label: this.$t("column_width"),
                            name: "width",
                            css: {
                                selector: "root"
                            },
                            value: this.column.width + "%",
                            options: {
                                responsive: true,
                                slider: true,
                                reset: true,
                                focus: true,
                                units: {
                                    "%": {
                                        min: 10,
                                        max: 100,
                                        step: 1
                                    }
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t("elements_space_span_class_lowercase_px_span"),
                            name: "margin-top",
                            css: {
                                selector:
                                    ">div.core__column--wrapper>div.core__blocks>div.core__blocks--body>div.ecom-block.elmspace ~ div.ecom-block.elmspace"
                            },
                            options: {
                                responsive: true,
                                slider: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    }
                                }
                            }
                        },
                        {
                            type: "line"
                        },
                        {
                            type: "paragraph",
                            content: "** " + this.$t("align_elements_inside") + " **"
                        },
                        {
                            type: "choose",
                            label: this.$t("align_items"),
                            name: "align-items",
                            css: {
                                selector:
                                    ">div.core__column--wrapper>div.core__blocks>div.core__blocks--body"
                            },
                            options: {
                                oneline: true,
                                responsive: true,
                                type: "align-items",
                                values: ["flex-start", "center", "flex-end", "baseline", "stretch"]
                            }
                        },
                        {
                            type: "choose",
                            label: this.$t("align_content"),
                            name: "align-content",
                            css: {
                                selector:
                                    ">div.core__column--wrapper>div.core__blocks>div.core__blocks--body"
                            },
                            options: {
                                type: "align-content",
                                oneline: true,
                                responsive: true,
                                values: [
                                    "flex-start",
                                    "center",
                                    "flex-end",
                                    "space-between",
                                    "space-around",
                                    "space-evenly"
                                ]
                            }
                        },
                        {
                            type: "choose",
                            label: this.$t("horizontal_align"),
                            name: "justify-content",
                            css: {
                                selector:
                                    ">div.core__column--wrapper>div.core__blocks>.core__blocks--body"
                            },
                            options: {
                                oneline: true,
                                responsive: true,
                                type: "align-x-full",
                                values: ["left", "center", "right"]
                            }
                        },
                        {
                            type: "line"
                        },
                        {
                            type: "popup",
                            label: this.$t("span_class_uppercase_html_span_tag"),
                            name: "tag",
                            options: {
                                values: {
                                    div: "div",
                                    header: "header",
                                    footer: "footer",
                                    main: "main",
                                    article: "article",
                                    section: "section",
                                    aside: "aside",
                                    nav: "nav"
                                },
                                type: "dropdown"
                            }
                        }
                    ]
                }
            ];

            if (this.is === "column") {
                settings.push({
                    group_title: this.$t("video_background"),
                    params: [
                        {
                            type: "popup",
                            name: "source",
                            label: this.$t("video_source"),
                            options: {
                                type: "dropdown",
                                default: false,
                                preview: "title",
                                values: {
                                    none: this.$t("none"),
                                    upload: this.$t("upload_video"),
                                    external: this.$t("custom_video_url"),
                                    youtube: this.$t("youtube"),
                                    vimeo: this.$t("vimeo")
                                }
                            }
                        },
                        {
                            type: "paragraph",
                            name: "para_notice",
                            options: {
                                visible: (data) => {
                                    return (
                                        data["source"] === "youtube" || data["source"] === "vimeo"
                                    );
                                },
                                warnings: {
                                    content: this.$t(
                                        "youtube_and_vimeo_videos_will_be_disabled_on_mobile"
                                    )
                                }
                            }
                        },
                        {
                            type: "picker",
                            label: this.$t("choose_video_i_maximum_10_mb_i"),
                            name: "video",
                            options: {
                                type: "video",
                                visible: function (data) {
                                    return data["source"] === "upload";
                                }
                            }
                        },
                        {
                            type: "text",
                            label: this.$t("enter_your_custom_video_url"),
                            name: "url",
                            placeholder: "https://the-domain.com/*/video.mp4",
                            options: {
                                visible: function (data) {
                                    return data["source"] === "external";
                                }
                            }
                        },
                        {
                            name: "srcYoutube",
                            label: this.$t("youtube_link"),
                            type: "text",
                            options: {
                                visible: function (data) {
                                    return data["source"] === "youtube";
                                }
                            }
                        },
                        {
                            name: "srcVimeo",
                            label: this.$t("vimeo_link"),
                            type: "text",
                            options: {
                                visible: function (data) {
                                    return data["source"] === "vimeo";
                                }
                            }
                        },
                        {
                            name: "start_time",
                            label: this.$t("start_time_s"),
                            type: "number",
                            options: {
                                half: true,
                                slider: false,
                                min: 0,
                                max: 1000,
                                visible: function (data) {
                                    return (
                                        data["source"] === "vimeo" || data["source"] === "youtube"
                                    );
                                }
                            }
                        },
                        {
                            name: "end_time",
                            label: this.$t("end_time"),
                            type: "number",
                            options: {
                                slider: false,
                                min: 0,
                                max: 1000,
                                half: true,
                                visible: function (data) {
                                    return data["source"] === "youtube";
                                }
                            }
                        },
                        {
                            type: "toggle",
                            name: "loop",
                            label: this.$t("loop"),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("on"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("off"),
                                        value: false
                                    }
                                }
                                //visible:function(data){ return data['source'] === 'external' || data['source'] === 'upload'}
                            }
                        },
                        {
                            type: "toggle",
                            name: "autoplay",
                            label: this.$t("autoplay"),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("on"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("off"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "paragraph",
                            content: this.$t(
                                "note_chromium_browsers_do_not_allow_autoplay_in_most_cases_however_muted_autoplay_is_always_allowed"
                            )
                        },
                        {
                            type: "toggle",
                            name: "muted",
                            label: this.$t("muted"),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                },
                                visible: function (data) {
                                    return data["source"] != "vimeo";
                                }
                            }
                        },
                        {
                            type: "toggle",
                            name: "inview_playpause",
                            label: this.$t("auto_play_pause_when_in_view"),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "paragraph",
                            content: this.$t("note_this_featured_not_working_on_safari")
                        }
                    ]
                });
                if (["collection", "product", "article"].includes(this.params.page)) {
                    settings.push({
                        group_title: this.$t("dynamic_background"),
                        params: [
                            {
                                type: "paragraph",
                                content: this.$t("show_current_page_featured", {
                                    page: this.params.page
                                })
                            },
                            {
                                type: "toggle",
                                label: this.$t("show_featured_image_as_background"),
                                name: "dynamic_background",
                                /*description: 'Stretch the section to the full width of the page using JS',*/
                                options: {
                                    values: {
                                        on: {
                                            label: this.$t("yes"),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t("no"),
                                            value: false
                                        }
                                    },
                                    oneline: true
                                }
                            }
                        ]
                    });
                }
            }

            return settings;
        },
        style() {
            return [
                {
                    group_alias: "background",
                    options: {
                        selector: ">.core__column--wrapper",
                        group_title: this.$t("background")
                    }
                },
                this.is == "column"
                    ? {
                          group_alias: "background:overlay",
                          options: {
                              group_title: this.$t("background_overlay"),
                              group_name: "backgroud_overlay",
                              selector: ">.core__column--wrapper div.ecom-column__overlay"
                          },
                          modify: {
                              remove: {
                                  index: 5,
                                  length: 1
                              },
                              params: [
                                  {
                                      position: 6,
                                      fields: [
                                          {
                                              type: "background",
                                              label: this.$t("background"),
                                              name: "columnBackgroundHover",
                                              options: {
                                                  oneline: true,
                                                  responsive: true,
                                                  types: ["classic", "gradient"],
                                                  visible: {
                                                      condition: (data) => {
                                                          return data["tab"] === "hover";
                                                      }
                                                  }
                                              },
                                              css: {
                                                  selector:
                                                      "root:hover>.core__column--wrapper div.ecom-column__overlay>.ecom-overlay",
                                                  properties: {
                                                      background: ""
                                                  }
                                              }
                                          }
                                      ]
                                  }
                              ]
                          }
                      }
                    : null,
                {
