            deep: true,
            handler() {
                if (
                    this.data.style?.background?.backgroundnormalmode?.classic &&
                    this.data.style?.background?.backgroundnormalmode?.classic["background-image"]
                ) {
                    const img_bg =
                        this.data.style.background.backgroundnormalmode.classic["background-image"];
                    if (img_bg.includes("ecom-need-replace")) {
                        this.needReplaceBg = true;
                    } else {
                        this.needReplaceBg = false;
                    }
                } else {
                    this.needReplaceBg = false;
                }
            }
        },
        width(val) {
            if (!this.column.settings.width) {
                this.column.settings.width = "100%";
            }

            // A non-finite width must not be written into settings ("NaN%") nor spread to siblings
            if (!Number.isFinite(parseFloat(val))) return;

            if (val < 10) {
                return (this.column.settings.width = "10%");
            }

            this.column.settings.width = val + "%";

            // auto change width of other columns in same row
            if (val && this.stack.length > 1) {
                let total = 0;
                this.stack.forEach((col) => {
                    total += col.width;
                });
                let sib = this.stack[this.index + (this.stack[this.index + 1] ? 1 : -1)];
                if (sib.width + (100 - total) > 10) {
                    sib.width += 100 - total;
                } else {
                    // sib.width = 10;
                }
            }
        },
        auwidth(val) {
            const parsed = parseFloat(parseFloat(val).toFixed(2).replace(".00", ""));
            if (val != this.width + "%" && Number.isFinite(parsed)) {
                this.column.width = parsed;
            }
        }
