    mounted() {
        if (this.exporting === false) {
            (this.instanceStore as any).register(this.data.id, this);
            //this.stacks[this.data.id] = this;
        }

        if (!this.column?.settings?.width) {
            this.column.settings.width = (this.data?.width ?? 100) + "%";
        }
        if (!this.column?.settings?.width__mobile) {
            this.column.settings.width__mobile = "100%";
        }
        if (
            this.data.style?.background?.backgroundnormalmode?.classic &&
            this.data.style?.background?.backgroundnormalmode?.classic["background-image"]
        ) {
            const img_bg =
                this.data.style.background.backgroundnormalmode.classic["background-image"];
            if (img_bg.includes("ecom-need-replace")) {
                this.needReplaceBg = true;
            }
        }
