        overCol() {
            // Track pure hover for border display (independent of editing state)
            if (!this.isFullScreen && this.exporting === false) {
                this.hovered = true;
            }
            // Original logic: only set `over` (for settings/drag UI) when actively editing
            if (
                !this.isFullScreen &&
                this.exporting === false &&
                this.editingElement &&
                this.breadcrumb.includes(this.$parent.data.id) /*&& !this.dragCurrent*/
