            ) {
                this.$store.commit("builder/setDragging", { timmer: new Date().getTime() });
                this.$store.commit("builder/setActiveElement", this);
                //this.$store.commit('builder/setEditingElement', this._row ? this._row : this._section);
                this.$store.dispatch("builder/setEditingElement", null);
                this.$store.commit("SET_TAB", "elements");
                this.$store.dispatch("UPDATE_IS_TEMP_HIDE", false);
                this.$store.commit("global/setSidebarTabActive", { id: "elements" });
                this.editCol();
            }
        },
        async insertCol() {
            if (this.stack.length >= 10) {
                this.notice({
                    message: "Can not insert more than 10 columns in a row",
                    type: "error"
                });
            } else {
                // Add visual feedback class before inserting
                if (this.$refs.wrapper) {
                    this.$refs.wrapper.classList.add("ecom-resizing-column");
                }
                const id = this.$helpers.randid();
                this.$store.commit('builder/setStatusDuplicate', true);
                await this.$nextTick();
                this.stack.splice(this.index + 1, 0, {
                    width: 50,
                    settings: {
                        width: "50%"
                    },
                    blocks: [],
                    id: id
                });
                
                let payload = {
                    type: 'column',
                    id: id,
                    section_id: this.section_id,
                    action: "insertColumn",
                    parent_id: this.parentColumn.data.id,
                }
                this.timmer = setTimeout(() => {
                    this.$store.commit('builder/setStatusDuplicate', false);
                }, 1000);
                this.$store.dispatch('history/addStack', payload);
                // Auto-adjust current column width to accommodate new column
                this.column.width = 25; // Current column becomes 25%
                this.column.settings.width = "25%";

                setTimeout(() => {
                    this.$parent.refreshCols();

                    // Remove visual feedback class after insertion is complete
                    if (this.$refs.wrapper) {
                        this.$refs.wrapper.classList.remove("ecom-resizing-column");
                    }

                    // Also add class to the newly inserted column if it exists
                    const newColumnWrapper = this.$refs.wrapper.nextElementSibling;
                    if (newColumnWrapper) {
                        newColumnWrapper.classList.add("ecom-resizing-column");

                        // Remove class after a short delay for visual feedback
                        setTimeout(() => {
                            newColumnWrapper.classList.remove("ecom-resizing-column");
                        }, 300);
                    }
                }, 50);
            }
        },

        duplicate() {
            if (this.stack.length >= 10) {
                this.notice({
                    message: "Can not insert more than 10 columns in a row",
                    type: "error"
                });
            } else {
                const clone = this.cloneData();
                const { parent_id, index } = getIdParentAndIndex(this);
                this.$store.commit('builder/setStatusDuplicate', true);
                let payload = {
                    type: 'Column',
                    data: clone,
                    section_id: this.section_id,
                    action: "duplicated",
                    parent_id: parent_id,
                    index: index
                }
                this.timmer = setTimeout(() => {
                    this.$store.commit('builder/setStatusDuplicate', false);
                }, 1000);
                this.$store.dispatch('history/addStack', payload);
                this.stack.splice(this.index + 1, 0, clone);
                setTimeout(() => {
                    this.$parent.refreshCols();
                }, 10);
            }
        },

        paste(clipboard) {
            if (!clipboard) {
                return;
            }
            let data = this.$helpers.copy(clipboard.data),
                sect;
            switch (clipboard.is) {
                case "section":
                case "grid":
                    sect = this.parent("section");
                    sect.stack.splice(sect.index + 1, 0, data);
                    this.$store.dispatch('history/addStack', {
                            type: 'section',
                            index: sect.index + 1,
                            data:  data,
                            section_id: sect.data.id,
                            action: 'add'
                        });
                    this.scroll(sect.$refs.wrapper.offsetHeight);
                    break;
                case "column":
                    if (this.stack.length >= 10) {
                        this.notice({
                            message: "Can not insert more than 10 columns in a " + this.$parent.is,
                            type: "error"
                        });
                    } else {
                        this.stack.splice(this.index + 1, 0, data);
                        this.$store.dispatch('history/addStack', {
                            type: 'Column',
                            index: this.index + 1,
                            data:  data,
                            section_id: this.section_id,
                            parent_id: this.parentColumn.data.id,
                            action: 'duplicated',
                        });
                        this.$parent.refreshCols();
                    }
                    break;
                case "block":
                case "blockFlex":
                    this.blocks.push(data);
                    this.$store.dispatch('history/addStack', {
                        type: 'block',
                        index: this.blocks.length - 1,
                        data:  data,
                        section_id: this.section_id,
                        parent_id: this.data.id,
                        action: 'duplicated',
                    });
                    this.scroll(this.$refs.wrapper.offsetHeight);
                    break;
            }
        },
        startResize(e) {
            e.preventDefault();
            e.stopPropagation();

            let nextCol = this.$parent.row.columns[this.index + 1];
            if (!nextCol) return; // Can't resize last column

            // Measure the actual columns container. `$parent.$el` is unreliable: Row's template
            // has multiple root nodes, so Vue treats it as a fragment and `$el` can point at the
            // v-if comment placeholder, whose offsetWidth is undefined -> deltaPercent = NaN.
            const columnsContainer =
                (this.$refs.wrapper as any)?.parentElement ??
                (this.$refs.wrapper as any)?.closest(".core__row--columns");
            const containerWidth =
                columnsContainer?.offsetWidth || (this.$parent as any)?.$el?.offsetWidth || 0;

            if (!containerWidth) return; // Can't compute a delta without a measurable container

            let current = {
                x: e.pageX,
                currentWidth: parseFloat(this.column.width) || 50, // Convert to number with fallback
                nextWidth: parseFloat(nextCol.width) || 50, // Convert to number with fallback
                minWidth: 10, // Minimum 10%
                containerWidth,
                nextColInstance: this.instanceStore.get(nextCol.id)
            };

            // Store combined width to maintain total
            const combinedWidth = current.currentWidth + current.nextWidth;

            // Prevent text selection and improve performance
            this.idoc().body.style.userSelect = "none";
            this.idoc().body.style.cursor = "col-resize";

            // Add visual feedback
            this.isResizing = true;

            // Add resizing class to the row container instead of individual wrappers
            const rowContainer = this.$refs.wrapper?.closest(".core__row--columns");
            if (rowContainer) {
                rowContainer.classList.add("ecom-resizing-column");
            }

            // Cache both elements once: querying/`nextElementSibling` per frame is wasted work
            const currentElement = this.$refs.wrapper as any;
            const nextElement = (current.nextColInstance?.$refs?.wrapper ??
                currentElement?.nextElementSibling) as any;

            // `flex: none` keeps the columns from growing; it is static, so it is set once here
            // instead of on every frame (each inline style write forces a style recalc).
            [currentElement, nextElement].forEach((el) => {
                el?.style.setProperty("flex", "none", "important");
            });

            // Visual feedback: also a one-off, not a per-frame reactive write
            this.over = true;
            if (current.nextColInstance) {
                current.nextColInstance.over = true;
            }

            // The drag itself is DOM-only. Writing width into the model on every frame makes
            // both columns run the deep `data.settings` watcher, which deep-copies settings,
            // JSON.stringifies them and regenerates their CSS ~60x/second — that is what made
            // resizing feel heavy. The model is committed once, on mouseup.
            const widths = { current: current.currentWidth, next: current.nextWidth };
            const label = { el: null as any };
            let pointerX = current.x;
            let frameId: number | null = null;

            const applyFrame = () => {
                frameId = null;

                // Positive deltaX means drag right
                const deltaPercent = ((pointerX - current.x) / current.containerWidth) * 100;

                // Drag right = current column gets wider, next gets narrower
                let newCurrentWidth = current.currentWidth + deltaPercent;
                let newNextWidth = current.nextWidth - deltaPercent;

                // Apply constraints while maintaining combined width
                if (newCurrentWidth < current.minWidth) {
                    newCurrentWidth = current.minWidth;
                    newNextWidth = combinedWidth - newCurrentWidth;
                } else if (newNextWidth < current.minWidth) {
                    newNextWidth = current.minWidth;
                    newCurrentWidth = combinedWidth - newNextWidth;
                }

                // Snap to 5% steps when close to one, so widths stay tidy
                const snapThreshold = 0.2;
                const mod = Math.abs(newCurrentWidth % 5);
                if (mod < snapThreshold || mod > 5 - snapThreshold) {
                    const snappedCurrent = Math.round(newCurrentWidth / 5) * 5;
                    const snappedNext = combinedWidth - snappedCurrent;

                    if (snappedCurrent >= current.minWidth && snappedNext >= current.minWidth) {
                        newCurrentWidth = snappedCurrent;
                        newNextWidth = snappedNext;
                    }
                }

                // Never let a bad measurement corrupt the model: NaN would propagate into
                // settings.width ("NaN%") and stick after the drag ends.
                if (!Number.isFinite(newCurrentWidth) || !Number.isFinite(newNextWidth)) return;

                // Nothing moved enough to be visible: skip the layout work entirely
                if (Math.abs(newCurrentWidth - widths.current) < 0.01) return;

                widths.current = newCurrentWidth;
                widths.next = newNextWidth;

                // Keep sub-percent precision while dragging (rounding to 0.1% made the columns
                // step in ~1px jumps on a wide canvas); the model is rounded on commit instead.
                if (currentElement) {
                    currentElement.style.setProperty(
                        "width",
                        `${newCurrentWidth.toFixed(3)}%`,
                        "important"
                    );
                }
                if (nextElement) {
                    nextElement.style.setProperty(
                        "width",
                        `${newNextWidth.toFixed(3)}%`,
                        "important"
                    );
                }

                // Live % badge, written straight to the DOM to avoid a re-render per frame
                if (!label.el && currentElement) {
                    label.el = currentElement.querySelector(
                        ":scope > .core__column--settings .core__column--resize-value"
                    );
                }
                if (label.el) {
                    label.el.textContent = `${Math.round(newCurrentWidth)}%`;
                }
            };

            const onMove = (moveEvent: any) => {
                // Always keep the newest position, then coalesce to one paint per frame.
                // The previous version dropped every move that arrived while a frame was
                // pending, so the handle lagged behind the cursor.
                pointerX = moveEvent.pageX;
                if (frameId === null) {
                    frameId = requestAnimationFrame(applyFrame);
                }
            };

            const stopResize = () => {
                if (frameId !== null) {
                    cancelAnimationFrame(frameId);
                    frameId = null;
                }

                // Cleanup event listeners
                this.idoc().onmousemove = null;
                this.idoc().onmouseup = null;
                this.idoc().removeEventListener("keydown", handleEscape);
                window.removeEventListener("mouseup", stopResize);

                // Restore styles
                this.idoc().body.style.userSelect = "";
                this.idoc().body.style.cursor = "";

                // Remove resizing class from row container
                if (rowContainer) {
                    rowContainer.classList.remove("ecom-resizing-column");
                }

                // Final cleanup
                this.finalizeResize(current, nextCol, combinedWidth, widths);
            };

            // Handle escape key to cancel resize
            const handleEscape = (e: any) => {
                if (e.key === "Escape") {
                    if (frameId !== null) {
                        cancelAnimationFrame(frameId);
                        frameId = null;
                    }
                    this.idoc().removeEventListener("keydown", handleEscape);
                    window.removeEventListener("mouseup", stopResize);
                    this.cancelResize(current, nextCol);
                }
            };

            this.idoc().onmousemove = onMove;
            this.idoc().onmouseup = stopResize;
            this.idoc().addEventListener("keydown", handleEscape);
            // Releasing the mouse outside the canvas must end the drag too, otherwise the
            // column keeps following the cursor after the button is already up.
            window.addEventListener("mouseup", stopResize);
        },

        // Helper method to finalize resize
        // `widths` holds the values the drag ended on; the model is untouched until here so
        // the whole drag costs a single CSS regeneration instead of one per frame.
        finalizeResize(current, nextCol, originalCombinedWidth, widths: any = null) {
            let finalCurrent = widths?.current ?? current.currentWidth;
            let finalNext = widths?.next ?? current.nextWidth;

            // Ensure exact combined width is maintained
            const currentCombined = finalCurrent + finalNext;
            if (currentCombined > 0 && Math.abs(currentCombined - originalCombinedWidth) > 0.01) {
                const ratio = originalCombinedWidth / currentCombined;
                finalCurrent *= ratio;
                finalNext *= ratio;
            }

            // Final precision cleanup, then commit both widths to the model
            this.column.width = Math.round(finalCurrent * 100) / 100;
            nextCol.width = Math.round(finalNext * 100) / 100;

            // Double-check total width of all columns
            let totalWidth = 0;
            this.$parent.columns.forEach((col) => {
                totalWidth += parseFloat(col.width) || 0; // Ensure numeric calculation
            });

            // If somehow total exceeds 100%, proportionally adjust all columns
            if (totalWidth > 100.01) {
                const factor = 100 / totalWidth;
                this.$parent.columns.forEach((col) => {
                    const currentWidth = parseFloat(col.width) || 0;
                    col.width = Math.round(currentWidth * factor * 10) / 10; // Keep 1 decimal place
                });
            }

            // Reset visual states
            this.isResizing = false;
            this.$parent.columns.forEach((col) => {
                const instance = this.instanceStore.get(col.id);
                if (instance) {
                    instance.over = false;
                }
            });

            // Update settings to reflect new widths
            this.column.settings.width = `${this.column.width}%`;
            nextCol.settings.width = `${nextCol.width}%`;

            // Clear any inline styles that might interfere. The DOM must be handed back to Vue,
            // which renders the committed width from the model.
            const wrapper = this.$refs.wrapper as any;
            [wrapper, wrapper?.nextElementSibling].forEach((el) => {
                if (!el) return;
                el.style.removeProperty("width");
                el.style.removeProperty("flex");
            });

            // Trigger resize event for other components
            this.dispatchResize();

            // Save state for undo/redo (optional)
            if (this.$store && this.$store.dispatch) {
                this.$store.dispatch("history/addStack", {
                    type: "column_resize",
                    data: {
                        columnId: this.data.id,
                        nextColumnId: nextCol.id,
                        oldWidths: {
                            current: current.currentWidth,
                            next: current.nextWidth
                        },
                        newWidths: {
                            current: this.column.width,
                            next: nextCol.width
                        }
                    }
                });
            }
        },

        // Helper method to cancel resize
        cancelResize(current, nextCol) {
            // Cleanup
            this.idoc().onmousemove = null;
            this.idoc().onmouseup = null;
            this.idoc().body.style.userSelect = "";
            this.idoc().body.style.cursor = "";

            // Remove resizing class from row container
            const rowContainer = this.$refs.wrapper?.closest(".core__row--columns");
            if (rowContainer) {
                rowContainer.classList.remove("ecom-resizing-column");
            }

            this.isResizing = false;

            // Commit the widths the drag started from, so Escape ends on a clean state
            this.finalizeResize(current, nextCol, current.currentWidth + current.nextWidth, {
                current: current.currentWidth,
                next: current.nextWidth
            });
        },
        outPlaceHover(e) {
            this.over = false;
            if (this.isDragging) {
                this.$store.commit("builder/setDropTo", null);
                this.$store.commit("builder/setDropPos", null);
            }
        },
        placehover(e) {
            if (
                !this.canDrop ||
                !this.editingElement ||
                !this.breadcrumb.includes(this.$parent.data.id)
            ) {
                return;
            }

            this.over = true;
            clearTimeout(this.timmer);
            if (!this.isDragging) {
                return;
            }
            let pos = e.target.classList.contains("placeholder__left") ? "left" : "right";
            if (this.dropTo !== this || this.dropPos != pos) {
                if (
                    this.dragCurrent.$parent !== this.$parent ||
                    (this.index - this.dragCurrent.index !== 1 && pos == "left") ||
                    (this.dragCurrent.index - this.index !== 1 && pos == "right")
                ) {
                    this.$store.commit("builder/setDropTo", this.data.id);
                    this.$store.commit("builder/setDropPos", pos);
                } else {
                    this.$store.commit("builder/setDropTo", this.dragCurrent?.data?.id);
                    this.$store.commit("builder/setDropPos", null);
                }
            }
        },

        dropOut() {
            setTimeout(
                (cur) => {
                    if (cur) {
                        this.$store.dispatch("builder/setEditingElement", null);
                    }
                    this.dispatchResize();
                },
                50,
                this.data.id == this.editingElement?.data?.id
            );
            let currentID = this.data.id;
            let realIndex = this.stack.findIndex((item) => {
                return item.id === currentID;
            });
            if (isNaN(realIndex)) {
                realIndex = this.index;
            }
            return this.stack.splice(realIndex, 1)[0];
        },

        dropIn(target, pos) {
            if (this.dragParent) return;
            if (this.section_id && this.sections) {
                const { parent_id, index } = getIdParentAndIndex(target);
                let payload = {
                    type: 'Column',
                    data: target.data,
                    section_id: this.section_id,
                    action: "moved",
                    parent_id: parent_id,
                    index: index
                }
                this.$store.dispatch('history/addStack', payload);
            }

            if (target.is == "column") {
                let row = target.$parent;
                this.stack.splice(this.index + pos, 0, target.dropOut());
                if (row.data.id !== this.$parent.data.id) {
                    this.$parent.refreshCols();
                    row.refreshCols();
                }
            } else {
                this.stack.push(target.dropOut());
            }
        }
    }
};
</script>
