<template>
    <teleport v-if="isReady" :to="teleportTarget">
        
            <transition name="slide-up">
                <div>
                    <PickerFrameChild
                        v-if="show"
                        :header="header"
                        :position="position"
                        :is-quick-tool-bar="isQuickToolBar"
                        @close="$emit('close')"
                        @back="$emit('back')"
                        @reload="$emit('reload')"
                        @loadFreeImg="$emit('loadFreeImg')"
                        @update:tabs="$emit('update:tabs', $event)"
                        @update:search="$emit('update:search', $event)"
                        @update:sort="$emit('update:sort', $event)"
                        @update:filter="$emit('update:filter', $event)"
                    >
                        <template v-for="(_, slot) of $slots" #[slot]="props">
                            <slot :name="slot" v-bind="props" />
                        </template>
                    </PickerFrameChild>
                </div>
        </transition>
        
    </teleport>
</template>
<script>
import PickerFrameChild from './PickerFrameChild.vue';
export default {
    name: 'PickerFrame',
    components: {
        PickerFrameChild
    },

    inject: ['teleport_id'],

    props: {
        show: {
            type: Boolean,
            default: false
        },
        header: {
            type: Object,
            default() {
                return {};
            }
        },
        position: {
            type: String,
            default: 'absolute'
        },
        isQuickToolBar: {
            type: Boolean,
            default: false
        }
    },

    emits: ['close', 'back', 'update:tabs', 'update:search', 'reload', 'loadFreeImg', 'update:sort', 'update:filter', 'toggleItem'],

    computed: {
        teleportTarget() {
            if (this.header.type === 'video' || this.header.type === 'image') {
                return 'body';
            }
            if (this.isQuickToolBar && this.header.type === 'icon') {
                return 'body';
            }
            return this.teleport_id;
        }
    },

    data() {
        return {
            isReady: false
        };
    },

    mounted() {
        this.isReady = true;
    }
};
</script>

<style>
.slide-up-enter-from,
.slide-up-leave-to {
    transform: translateY(25%);
    opacity: 0;
}
</style>
