export interface InstanceStore<T> {
  register(name: string, instance: T | null): symbol;
  get(name: string): T | null;
  unregister(name: string): void;
  getAll(): Map<string, T | null>;
}

// Biến singleton để lưu instance duy nhất
let singletonInstance: InstanceStore<any> | null = null;

// Detect Firefox
const isFirefox = typeof navigator !== 'undefined' && navigator.userAgent.toLowerCase().includes('firefox');

export default <T>(): InstanceStore<T> => {
  if (singletonInstance) {
    return singletonInstance as InstanceStore<T>;
  }

  // Sử dụng Map thay vì WeakMap cho Firefox
  const instances = isFirefox ? new Map<symbol, T | null>() : new WeakMap<symbol, T | null>();
  const keys = new Map<string, symbol>();

  singletonInstance = {
    register(name: string, instance: T | null): symbol {
      const key = Symbol(name);
      instances.set(key, instance);
      keys.set(name, key);
      return key;
    },

    get(name: string): T | null {
      const key = keys.get(name);
      return key ? instances.get(key) || null : null;
    },

    unregister(name: string): void {
      const key = keys.get(name);
      if (key) {
        instances.delete(key);
        keys.delete(name);
      }
    },

    getAll(): Map<string, T | null> {
      const result = new Map<string, T | null>();
      keys.forEach((key, name) => {
        result.set(name, instances.get(key) || null);
      });
      return result;
    }
  };

  return singletonInstance;
};