<i18n>
{
    "en": {
        "click_to_enter_number": "Click to enter number",
        "padding": "Padding",
        "margin": "Margin"
    },
    "fr": {
        "click_to_enter_number": "Cliquez pour entrer un nombre"
    },
    "de": {
        "click_to_enter_number": "Klicken Sie, um eine Zahl einzugeben"
    },
    "ja": {
        "click_to_enter_number": "数値を入力するにはクリックしてください",
        "padding": "パディング",
        "margin": "マージン"
    }
}
</i18n>
<template>
    <div class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-white   diagonal rounded text-gray-100 select-none  "
            :class="size === 'large' ? 'h-[200px] w-full' : options?.type !== 'radius' && !options?.simple ? 'h-[57%]' : 'h-32'"
        >
        <div v-if="size === 'small' && !options?.simple && options.type !== 'radius'" class="absolute inset-1 -m-1 rounded" />
        <div v-if="size === 'small' && !options?.simple && options.type !== 'radius'" class="absolute transform top-1/2 -translate-y-1/2 w-2.5 h-2.5 rounded-full z-10 bg-dark -left-[5px]" />
        <div v-if="size === 'small' && !options?.simple && options.type !== 'radius'" class="absolute transform top-1/2 -translate-y-1/2 w-2.5 h-2.5 rounded-full z-10 bg-dark -right-[5px]" />
        <div v-if="size === 'small' && !options?.simple && options.type !== 'radius'" class="absolute transform -top-[5px] -translate-x-1/2 w-2.5 h-2.5 rounded-full z-10 bg-dark left-1/2" />
        <div v-if="size === 'small' && !options?.simple && options.type !== 'radius'" class="absolute transform -bottom-[5px] -translate-x-1/2 w-2.5 h-2.5 rounded-full z-10 bg-dark left-1/2" />

        <span
            v-if="type"
            class="absolute text-xs text-text-primary pointer-events-none z-2 capitalize font-[550]"
            :class="type == 'padding' ? 'bottom-1 right-3' : 'top-[9px] left-4'"
            v-html="$t(type)"
        />
        <div 
            v-if="!options?.simple && options.type !== 'radius'"
            :class="[
                {
                    'absolute inset-0 border border-input rounded-[10px]': (type === 'padding' && size === 'small') || size === 'large',
                    'border-dashed': size === 'small'
                }
            ]"
        >
            <div
                v-for="name in names" :key="name"
                class="absolute rounded-[10px] inset-0 transition z-1"
                :class="[size === 'small' ? '' : '', classDirSpacing(name)]"
                :style="styleBgInput(name)"
                @mousedown.stop="mouseDown($event, name)"
            >
                <span
                    :data-tooltip="$t('click_to_enter_number')"
                    data-tooltip-location="left"
                    class="input-number absolute transform  p-4 z-5 cursor-pointer text-center focus:outline-none bg-transparent focus:ring-0 text-xs leading-none text-text-secondary flex justify-center items-center"
                    :class="[classInput(name), options?.simple ? 'w-8' : '', {'': !displayValue(name)}]"
                    v-html="displayValue(name)"
                />
            </div>
        </div>
        <div v-else
            class="absolute inset-0 border border-input rounded-[10px]"
        >
            <div
                v-for="name in names" :key="name"
                class="absolute rounded-[10px]  inset-0 transition z-1"
                :class="classDir(name)"
                :style="styleBgInput(name)"
                @mousedown.stop="mouseDown($event, name)"
            >
                <span
                    :data-tooltip="$t('click_to_enter_number')"
                    data-tooltip-location="left"
                    class="input-number absolute transform   z-5 p-4 cursor-pointer text-center focus:outline-none bg-transparent focus:ring-0 text-xs leading-none text-text-secondary flex justify-center items-center"
                    :class="[classInput(name), options?.simple ? 'w-8' : '', {'': !displayValue(name)}]"
                    v-html="displayValue(name)"
                />
                <span v-if="isRadius" class="absolute w-6 h-6 block transform" :class="[borderClass(name)]"></span>
            </div>
        </div>
    </div>
</template>

<script>

    import mixin from './mixin.js';
    export default {
        name: 'Box',
        mixins: [mixin],
        props: {
            type: {
                type: String,
                default: ''
            },
            current: {
                type: Object,
                default() {
                    return {};
                }
            },
            unit: {
                type: String,
                default: ''
            },
            size: {
                type: String,
                default: 'large'
            },
            data: {
                type: Object,
                default(){ return  {};}
            },
            unitConfigs: Object,
            linked: Boolean,
            responsiveData: Object,
            field: {
                type: Object,
                default() { return {} ;}
            }
        },
        emits: ['update:data', 'update:current', 'click-input', 'close-input', 'isWatch'],
        data() {
            return  {
                el: null,
                isDrag: false,
                p: 0,
                s: 0,
                oriValue: 0,
                values: {},
                isWatch: true,
                isEmit: false,
                itv: null,
                isFirst: true
            };
        },
        computed: {
            names() {
                return ['top','left','bottom', 'right'];
            },
            _current: {
                get() {
                    return this.current;
                },
                set(val){
                    this.$emit('update:current', val);
                }
            },
            options() {
                return this.field.options ?? {};
            },
            isRadius() {
                return this.options.type === 'radius';
            },
            isSimple() {
                return this.isRadius || this.options.simple;
            },
            dragDirection() {
                return (this._current?.name === 'top' || this._current.name === 'bottom' || this.isRadius) ? 'clientY' : 'clientX';
            },
            fieldName() {
                return Object.keys(this.field.css?.properties ?? {})[0] ?? this.field.name;
            },
            displayValue() {
                return (name) => {
                    if (this.responsiveData && this.responsiveData[name]) {
                        if (this.values[name] === 'auto' || this.responsiveData[name].toString() === 'auto') {
                            return this.$t('auto');
                        }
                        return this.responsiveData[name].toString().replace(/[a-zA-Z\%]+/g, '');
                    }
                    if (this.values[name] == undefined || this.values[name] == 'none') {
                        return '━';
                    }
                    return JSON.stringify(this.values[name]);
                };
            }
        },
        watch: {
            data: {
                deep: true,
                immediate: true,
                handler(val) {
                    if(this.isWatch){
                        this.isEmit = false;
                        this.values = this.$helpers.copy(val) ?? {};
                    }
                    this.isWatch = true;
                }
            },
            values: {
                deep: true,
                handler(val) {
                    if(this.isEmit){
                        this.isWatch = false;
                        this.$emit('update:data', this.$helpers.copy(val));
                    }
                    this.isEmit = true;
                    if(this.isFirst && this.isSimple) {
                        setTimeout(() => {
                            this.$emit('update:data', this.$helpers.copy(this.values));
                        }, 10);
                        this.isFirst = false;
                    }
                }
            },
            linked(val) {
                this.toggleLink();
            }
        },
        created () {
            this.names.forEach(name => {
                let _this = this;
                _this.$watch('values.' +name , function(val){
                    clearTimeout(_this.itv);
                    _this.itv = setTimeout(function(){
                        if(_this.linked){
                            _this.setValueLinked(val, true);
                        }
                        _this.$emit('update:data', _this.$helpers.copy(_this.values));
                    }, 10);

                });
            });
        },
        methods: {
            classDir(name) {
                if(this._current.name === name && this._current.type === this.type){
                    return 'bg-surface-secondary ';
                }
                switch(name) {
                    case 'top':
                    case 'bottom':
                        return 'bg-surface-secondary   hover:bg-gray-100';
                    default:
                        return 'bg-white   hover:bg-gray-100';
                }
            },
            classDirSpacing(name) {
                if(this._current.name === name && this._current.type === this.type){
                    return 'bg-surface-secondary ';
                }
                switch(name) {
                    case 'top':
                    case 'bottom':
                        return 'bg-surface-secondary  hover:bg-gray-100';
                    default:
                        return 'bg-white   hover:bg-gray-100';
                }
            },
            styleBgInput(name) {
                switch(name) {
                    case 'top':
                        return !this.isRadius ?
                                { 'clip-path': 'polygon(0 0, 100% 0, 50% 50%)', cursor: this.dragDir(this.type || this.fieldName, 'top').c  } :
                                { 'clip-path': 'polygon(0 0, 50% 0, 50% 50%, 0 50%)', cursor: 'n-resize' };
                    case 'left':
                        return !this.isRadius ?
                                { 'clip-path': 'polygon(0 0, 50% 50%, 0% 100%)', cursor: this.dragDir(this.type || this.fieldName, 'left').c  } :
                                { 'clip-path': 'polygon(0 50%, 50% 50%, 50% 100%, 0 100%)', cursor: 's-resize' };
                    case 'bottom':
                        return !this.isRadius ?
                                { 'clip-path': 'polygon(0 100%, 50% 50%, 100% 100%)', cursor: this.dragDir(this.type || this.fieldName, 'bottom').c  } :
                                { 'clip-path': 'polygon(50% 50%, 100% 50%, 100% 100%, 50% 100%)', cursor: 's-resize' };
                    case 'right':
                        return !this.isRadius ?
                                { 'clip-path': 'polygon(100% 0, 50% 50%, 100% 100%)', cursor: this.dragDir(this.type || this.fieldName, 'right').c  } :
                                { 'clip-path': 'polygon(50% 0, 100% 0, 100% 50%, 50% 50%)', cursor: 'n-resize' };
                }
            },
            classInput(name) {
                switch(name) {
                    case 'top':
                        return !this.isRadius ?
                                ((this.type === 'margin' ? 'top-5' : 'top-6') + ' left-1/2 -translate-x-1/2 -translate-y-1/2') :
                                'top-1/4 left-12 -translate-x-1/2 -translate-y-1/2';
                    case 'left':
                        return !this.isRadius ?
                                ((this.options?.simple ? 'left-12' : 'left-6') + ' top-1/2 -translate-y-1/2 -translate-x-1/2') :
                                'top-3/4 left-12 -translate-x-1/2 -translate-y-1/2';
                    case 'bottom':
                        return !this.isRadius ?
                                ((this.type === 'margin' ? 'bottom-5' : 'bottom-6') + ' left-1/2 -translate-x-1/2 translate-y-1/2') :
                                'top-3/4 right-12 translate-x-1/2 -translate-y-1/2';
                    case 'right':
                        return !this.isRadius ?
                                ((this.options?.simple ? 'right-12' : 'right-6') + ' top-1/2 -translate-y-1/2 translate-x-1/2') :
                                'top-1/4 right-12 translate-x-1/2 -translate-y-1/2';
                }
            },
            borderClass(name){
                switch(name) {
                    case 'top':
                        return 'top-1/4 left-24 -translate-x-1/2 -translate-y-1/2 border-t border-l border-input rounded-tl-[10px]';
                    case 'left':
                        return 'top-3/4 left-24 -translate-x-1/2 -translate-y-1/2 border-b border-l border-input rounded-bl-[10px]';
                    case 'bottom':
                        return 'top-3/4 right-24 translate-x-1/2 -translate-y-1/2 border-b border-r border-input rounded-br-[10px]';
                    case 'right':
                        return 'top-1/4 right-24 translate-x-1/2 -translate-y-1/2 border-t border-r border-input rounded-tr-[10px]';
                }
            },
            mouseDown(e, name) {
                this.isDrag = false;
                this.el = e.target;
                this._current = {name, type: this.type};
                this.oriValue = (this.values[name] !== undefined &&
                                    this.values[name] !== null &&
                                    this.values[name] !== 'auto') ?
                                        this.values[name] :
                                        0;
                this.p = e[name === 'top' || name === 'bottom' || this.isRadius ? 'clientY' : 'clientX'];
                document.onmouseup =  this.onMouseUp;
                document.onmousemove =  this.onMouseMove;
            },
            onMouseMove(e){
                let newP = e[this.dragDirection];
                this.s += Math.abs(newP - this.p);
                if(this.s > 3) {
                    this.isDrag = true;
                    this.el = null;
                    let v = !this.dragDir(this._current.type || this.fieldName, this._current.name).d ?
                            ((this.p - newP) * this.unitConfigs.step) :
                            ((newP - this.p) * this.unitConfigs.step);
                    v = Math.round(v * 0.8);
                    this.values[this._current.name] = this.oriValue +  Math.round(v * 100) / 100;
                    this.values[this._current.name] = Math.max(this.unitConfigs.min,
                        Math.min(this.unitConfigs.max, this.values[this._current.name])
                    );
                }

            },
            onMouseUp() {
                if(!this.isDrag && this.el && this.el.classList.contains('input-number')) {
                    this.$emit('click-input', { value: this.values[this._current.name], el: this.el});
                }
                else {
                    this._current = {};
                    this.$emit('close-input');
                }
                this.s = 0;
                this.el = null;
                document.onmouseup = null;
                document.onmousemove = null;
            },
            setValueLinked(val, overwrite = false){
                //if(val === undefined) {return ;}
                let values;
                this.names
                    .forEach(dir => {
                        values = this.values[dir];
                        if(overwrite || (!overwrite && values === undefined)){
                            this.values[dir] = val;
                        }

                    });
            },
            toggleLink(){
                if(this.linked){
                    const firstValue = (() => {
                        let v = undefined;
                        for(let i in this.names){
                            let vn = this.values[this.names[i]];
                            if(vn !== undefined && vn !== null && vn !== '') {
                                v = vn;
                                break;
                            }
                        }
                        return v;
                    })();
                    this.isEmit = true;
                    this.setValueLinked(firstValue, true);
                }
            }
        }
    };
</script>
