// SelectionDragHandler.ts
import type {
  GridLayoutInstance,
  SelectionDragOptions,
  SelectionDragEvents,
  SelectionDragEventData,
  SelectionDragState
} from './SelectionTypes';
import { ensureNumericValue, handleSetHistorySelection } from '../../helpers/utils';

export class SelectionDragHandler {
  private instance: GridLayoutInstance;
  private options: SelectionDragOptions;
  private events: SelectionDragEvents;
  private dragState: SelectionDragState;
  private _dragMoveHandler: ((e: MouseEvent) => void) | null = null;
  private _dragEndHandler: ((e: MouseEvent) => void) | null = null;

  constructor(instance: GridLayoutInstance, options: SelectionDragOptions = {}, events: SelectionDragEvents = {}) {
    this.instance = instance;
    this.options = {
      enableDrag: true,
      dragThreshold: 5,
      boundaryCheck: true,
      ...options
    };
    this.events = events;

    this.dragState = {
      isDraggingMultiple: false,
      dragStartPosition: null,
      dragStartOffsetPosition: null,
      dragStartBounds: null,
      selectedItemsInitialPos: []
    };

    this.bindMethods();
  }

  private bindMethods(): void {
    this.startDragSelection = this.startDragSelection.bind(this);
    this.dragSelectionMove = this.dragSelectionMove.bind(this);
    this.dragSelectionEnd = this.dragSelectionEnd.bind(this);
  }

  // Sync state with instance
  public syncStateToInstance(): void {
    this.instance.isDraggingMultiple = this.dragState.isDraggingMultiple;
    this.instance.dragStartPosition = this.dragState.dragStartPosition;
    this.instance.dragStartOffsetPosition = this.dragState.dragStartOffsetPosition;
    this.instance.dragStartBounds = this.dragState.dragStartBounds;
    this.instance.selectedItemsInitialPos = this.dragState.selectedItemsInitialPos;
  }

  public syncStateFromInstance(): void {
    this.dragState.isDraggingMultiple = this.instance.isDraggingMultiple;
    this.dragState.dragStartPosition = this.instance.dragStartPosition;
    this.dragState.dragStartOffsetPosition = this.instance.dragStartOffsetPosition;
    this.dragState.dragStartBounds = this.instance.dragStartBounds;
    this.dragState.selectedItemsInitialPos = this.instance.selectedItemsInitialPos;
  }

  public canStartDrag(e: MouseEvent): boolean {
    if (!this.options.enableDrag) return false;
    if (!this.instance.hasSelection || this.instance.selectedItems.length === 0) return false;

    // Kiểm tra xem click có nằm trong vùng selection không
    const rect = this.instance.$refs.item.getBoundingClientRect();
    const clickX = (e.clientX - rect.left) / this.instance.scaleRatio;
    const clickY = (e.clientY - rect.top) / this.instance.scaleRatio;

    return this.isPointInSelectionArea(clickX, clickY) || this.isClickOnSelectedItem(e);
  }

  private isPointInSelectionArea(clickX: number, clickY: number): boolean {
    if (!this.instance.hasSelection || !this.instance.selectionArea) return false;

    const containerRect = this.instance.$refs.item.getBoundingClientRect();
    const containerWidth = containerRect.width / this.instance.scaleRatio;
    const clickLeftPercent = (clickX / containerWidth) * 100;

    return (
      clickLeftPercent >= this.instance.selectionArea.minX &&
      clickLeftPercent <= this.instance.selectionArea.maxX &&
      clickY >= this.instance.selectionArea.minY &&
      clickY <= this.instance.selectionArea.maxY
    );
  }

  private isClickOnSelectedItem(e: MouseEvent): boolean {
    if (!this.instance.activeElements) return false;

    return Object.values(this.instance.activeElements).some((el: any) => {
      return el && el.$el && (el.$el === e.target || el.$el.contains(e.target));
    });
  }

  public startDragSelection(e: MouseEvent): void {
    if (!this.canStartDrag(e)) return;

    // Cập nhật scale ratio
    this.instance.updateScaleRatio();

    // Lấy rect của container
    const containerRect = this.instance.$refs.item.getBoundingClientRect();

    // Lưu vị trí ban đầu của chuột trong tọa độ viewport
    this.dragState.dragStartPosition = {
      x: e.clientX,
      y: e.clientY
    };

    // Lưu vị trí của điểm click tương đối với container (có scale)
    this.dragState.dragStartOffsetPosition = {
      x: (e.clientX - containerRect.left) / this.instance.scaleRatio,
      y: (e.clientY - containerRect.top) / this.instance.scaleRatio
    };

    // Lưu vùng chọn ban đầu
    this.dragState.dragStartBounds = {
      minX: this.instance.selectionArea.minX,
      minY: this.instance.selectionArea.minY,
      maxX: this.instance.selectionArea.maxX,
      maxY: this.instance.selectionArea.maxY
    };

    // Lưu trữ vị trí ban đầu của tất cả grid item trong vùng chọn
    this.dragState.selectedItemsInitialPos = this.instance.selectedItems.map((item) => {
      return {
        i: item.i,
        left: ensureNumericValue(item.left),
        top: ensureNumericValue(item.top),
        width: ensureNumericValue(item.width),
        height: ensureNumericValue(item.height),
        rotation: item.rotation,
        zindex: item.zindex || 'inherit'
      };
    });

    // Đánh dấu đang kéo vùng chọn
    this.dragState.isDraggingMultiple = true;
    //this.instance.isDraggingGrid = true;

    // Thêm class cho grid layout
    if (this.instance.$refs.item) {
      this.instance.$refs.item.classList.add("ecom-dragging-selection");
    }

    this.syncStateToInstance();

    // Thêm event listeners để xử lý kéo thả
    const iframeDoc = this.instance.idoc();
    this._dragMoveHandler = this.dragSelectionMove.bind(this);
    this._dragEndHandler = this.dragSelectionEnd.bind(this);
    iframeDoc.addEventListener("mousemove", this._dragMoveHandler);
    iframeDoc.addEventListener("mouseup", this._dragEndHandler);

    e.preventDefault();
    e.stopPropagation();

    // Emit event
    const eventData: SelectionDragEventData = {
      eventType: 'selectiondragstart',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      deltaX: 0,
      deltaY: 0,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onDragStart) {
      this.events.onDragStart(eventData);
    }
  }

  public dragSelectionMove(e: MouseEvent): void {
    if (this.instance.editorConfigs.locked) {
      this.instance.$store.commit("builder/setShowNoticeLockmode", true);
      return;
    }
    if (!this.dragState.isDraggingMultiple) return;

    // Kiểm tra dragStartPosition có tồn tại không
    if (!this.dragState.dragStartPosition) {
      console.warn('dragStartPosition is null in dragSelectionMove');
      return;
    }
    this.instance.eventBus.emit("groupSettingsClose");
    // Tính delta từ điểm bắt đầu drag
    const deltaX = e.clientX - this.dragState.dragStartPosition.x;
    const deltaY = e.clientY - this.dragState.dragStartPosition.y;

    // Lấy kích thước container (có scale)
    const containerRect = this.instance.$refs.item.getBoundingClientRect();
    const containerWidth = containerRect.width / this.instance.scaleRatio;
    const containerHeight = containerRect.height / this.instance.scaleRatio;

    // Tính toán delta % cho trục X (điều chỉnh theo scale)
    const deltaXPercent = (deltaX / this.instance.scaleRatio / containerWidth) * 100;
    const deltaYPixels = deltaY / this.instance.scaleRatio;

    // Tính các giới hạn delta cho từng item
    let minDeltaXPercent = -Infinity;
    let maxDeltaXPercent = Infinity;
    let minDeltaY = -Infinity;
    let maxDeltaY = Infinity;

    if (this.options.boundaryCheck) {
      for (const initialItem of this.dragState.selectedItemsInitialPos) {
        // Giới hạn trục X
        const leftLimit = -initialItem.left;
        minDeltaXPercent = Math.max(minDeltaXPercent, leftLimit);

        const rightLimit = 100 - initialItem.left - (initialItem.width / containerWidth) * 100;
        maxDeltaXPercent = Math.min(maxDeltaXPercent, rightLimit);

        // Giới hạn trục Y
        const topLimit = -initialItem.top;
        minDeltaY = Math.max(minDeltaY, topLimit);

        if (this.instance.data?.settings?.["min-height"]) {
          const bottomLimit = containerHeight - initialItem.top - initialItem.height;
          maxDeltaY = Math.min(maxDeltaY, bottomLimit);
        }
      }
    }

    // Giới hạn delta trong phạm vi cho phép
    const groupItems: string[] = [];
    const finalDeltaXPercent = this.options.boundaryCheck
      ? Math.max(minDeltaXPercent, Math.min(maxDeltaXPercent, deltaXPercent))
      : deltaXPercent;
    const finalDeltaY = this.options.boundaryCheck
      ? Math.max(minDeltaY, Math.min(maxDeltaY, deltaYPixels))
      : deltaYPixels;

    // Áp dụng di chuyển với delta đã giới hạn
    this.instance.selectedItems.forEach((item, index) => {
      const initialPos = this.dragState.selectedItemsInitialPos[index];
      if (!initialPos) return;

      // Tính vị trí mới dựa trên vị trí ban đầu và delta đã giới hạn
      const newLeft = initialPos.left + finalDeltaXPercent;
      const newTop = initialPos.top + finalDeltaY;

      // Cập nhật item trong selectedItems
      item.left = newLeft;
      item.top = newTop;

      // Cập nhật layout
      const layoutItemIndex = this.instance.layout.findIndex((li) => li.i === item.i);
      if (layoutItemIndex !== -1) {
        this.instance.layout[layoutItemIndex].left = newLeft;
        this.instance.layout[layoutItemIndex].top = newTop;
        groupItems.push(this.instance.layout[layoutItemIndex].i);
      }

      // Cập nhật DOM
      this.instance.eventBus.emit("update-grid-item", {
        id: item.i,
        left: newLeft,
        top: newTop,
        width: item.width,
        height: item.height,
        rotation: item.rotation,
        zindex: item.zindex
      });
    });

    let maxY = 0;
    if (!this.instance.data?.settings?.["min-height"]) {
      this.instance.layout.forEach((item) => {
        if (!groupItems.includes(item.i)) {
          const itemY = item.top + item.height;
          if (itemY > maxY) {
            maxY = itemY;
          }
        }
      });

      if (this.instance.selectionBorders.h[1].y > maxY) {
        this.instance.updateHeight(this.instance.selectionBorders.h[1].y);
      } else if (parseInt(this.instance.$refs.item.style.height) != maxY) {
        this.instance.updateHeight(maxY);
      }
    }

    // Cập nhật selection area
    this.instance.updateSelectionAreaFromItems();
    this.instance.updateSelectionBorders();

    // Emit sự kiện cập nhật
    this.instance.$nextTick(() => {
      this.instance.emitSelectionDragUpdate();
    });

    // Emit event
    const eventData: SelectionDragEventData = {
      eventType: 'selectiondragmove',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      deltaX: finalDeltaXPercent,
      deltaY: finalDeltaY,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onDragMove) {
      this.events.onDragMove(eventData);
    }
  }

  public dragSelectionEnd(e: MouseEvent): void {
    if (!this.dragState.isDraggingMultiple) return;

    // Kiểm tra dragStartPosition có tồn tại không
    if (!this.dragState.dragStartPosition) {
      console.warn('dragStartPosition is null in dragSelectionEnd');
      this.dragState.isDraggingMultiple = false;
      this.instance.isDraggingGrid = false;
      this.syncStateToInstance();
      return;
    }

    // Xóa class để hoàn tất hiệu ứng kéo thả
    if (this.instance.$refs.item) {
      this.instance.$refs.item.classList.remove("ecom-dragging-selection");
    }

    // Gỡ bỏ event listeners
    const iframeDoc = this.instance.idoc();
    if (this._dragMoveHandler) {
      iframeDoc.removeEventListener("mousemove", this._dragMoveHandler);
      this._dragMoveHandler = null;
    }
    if (this._dragEndHandler) {
      iframeDoc.removeEventListener("mouseup", this._dragEndHandler);
      this._dragEndHandler = null;
    }

    // Kiểm tra xem có phải là click đơn không thay vì kéo thả
    const deltaX = e.clientX - this.dragState.dragStartPosition.x;
    const deltaY = e.clientY - this.dragState.dragStartPosition.y;
    const isJustClick = Math.abs(deltaX) < this.options.dragThreshold! && Math.abs(deltaY) < this.options.dragThreshold!;

    // Nếu chỉ là click mà không kéo
    if (isJustClick) {
      // Đặt lại trạng thái
      this.dragState.isDraggingMultiple = false;
      this.instance.isDraggingGrid = false;
      this.dragState.dragStartPosition = null;
      this.syncStateToInstance();
      return;
    } else {
      // Add history selection
      const section = this.instance.sections.find((s) => s.id == this.instance.section_id);
      if (section) {
        const dataIds = this.instance.selectedItems.map((item) => item.i);
        handleSetHistorySelection(section, dataIds, this.instance.screen, "moved");
      }
    }

    this.instance.updateAllLayouts();

    // Đặt lại trạng thái
    this.dragState.isDraggingMultiple = false;
    this.instance.isDraggingGrid = false;
    this.dragState.dragStartPosition = null;

    this.syncStateToInstance();

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    // Tìm border element để làm anchor cho GroupSettings
    if (this.instance.hasSelection) {
      const topBorderElement = iframeDoc.querySelector(".ecom-selection-active");
      if (topBorderElement) {
        (topBorderElement as HTMLElement).setAttribute("data-drag-completed", "true");

        setTimeout(() => {
          this.instance.eventBus.emit("groupSettingsOpen", {
            el: topBorderElement,
            sectionId: this.instance.section_id,
            isSelection: true,
            fromDragComplete: true
          });

          setTimeout(() => {
            (topBorderElement as HTMLElement).removeAttribute("data-drag-completed");
          }, 300);
        }, 50);
      }
    }

    setTimeout(() => {
      this.instance.$parent.justSelected = false;
    }, 300);

    // Emit event
    const finalDeltaX = deltaX;
    const finalDeltaY = deltaY;

    const eventData: SelectionDragEventData = {
      eventType: 'selectiondragend',
      sectionId: this.instance.section_id,
      selectedItems: this.instance.selectedItems,
      selectionArea: this.instance.selectionArea,
      deltaX: finalDeltaX,
      deltaY: finalDeltaY,
      mousePosition: { x: e.clientX, y: e.clientY }
    };

    if (this.events.onDragEnd) {
      this.events.onDragEnd(eventData);
    }
  }

  public isDragging(): boolean {
    return this.dragState.isDraggingMultiple;
  }

  public destroy(): void {
    // Dừng drag nếu đang diễn ra
    this.dragState.isDraggingMultiple = false;

    // Xóa event listeners
    const iframeDoc = this.instance.idoc();
    if (this._dragMoveHandler) {
      iframeDoc.removeEventListener("mousemove", this._dragMoveHandler);
      this._dragMoveHandler = null;
    }
    if (this._dragEndHandler) {
      iframeDoc.removeEventListener("mouseup", this._dragEndHandler);
      this._dragEndHandler = null;
    }

    // Reset drag state
    this.dragState = {
      isDraggingMultiple: false,
      dragStartPosition: null,
      dragStartOffsetPosition: null,
      dragStartBounds: null,
      selectedItemsInitialPos: []
    };

    // Sync lại state về instance
    this.syncStateToInstance();
  }

  // Debug method
  public debugDrag(): void {
    console.log('=== Drag Debug Info ===');
    console.log('isDraggingMultiple:', this.dragState.isDraggingMultiple);
    console.log('dragStartPosition:', this.dragState.dragStartPosition);
    console.log('dragStartBounds:', this.dragState.dragStartBounds);
    console.log('selectedItemsInitialPos count:', this.dragState.selectedItemsInitialPos.length);
    console.log('=== End Drag Debug Info ===');
  }
}