// RotateHandler.ts
import type {
  GridItemInstance,
  RotateOptions,
  RotateEvents,
  RotateEventData,
  RotationData
} from './types';
import { ensureNumericValue } from '../../helpers/utils';

export class RotateHandler {
  private instance: GridItemInstance;
  private options: RotateOptions;
  private events: RotateEvents;
  private rotationData: RotationData | null = null;

  constructor(instance: GridItemInstance, options: RotateOptions = {}, events: RotateEvents = {}) {
    this.instance = instance;
    this.options = {
      enableRotate: true,
      snapToAngle: false,
      snapThreshold: 15,
      showRotationValue: true,
      ...options
    };
    this.events = events;

    this.bindMethods();
  }

  private bindMethods(): void {
    this.startRotate = this.startRotate.bind(this);
    this.handleRotateMove = this.handleRotateMove.bind(this);
    this.endRotate = this.endRotate.bind(this);
  }

  public startRotate(e: MouseEvent): void {
    if (this.instance.static || !this.instance.isNormalZoom || this.instance.isItemLocked) return;

    this.instance.isUpdatingFromResize = true;

    // Cập nhật tỷ lệ scale
    this.instance.updateScaleRatio();

    // Khởi tạo trạng thái quay
    this.instance.isRotating = true;
    if (this.options.showRotationValue) {
      this.instance.isShowingRotateValue = true;
    }

    // Lấy thông tin về vị trí và kích thước phần tử
    const rect = this.instance.$refs.item.getBoundingClientRect();

    // Tính toán tâm của phần tử trong tọa độ của viewport
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    // Tính góc ban đầu giữa vị trí chuột và tâm phần tử
    // Công thức: Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI)
    const initialAngle =
      Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);

    // Lưu trữ thông tin liên quan đến quay
    this.rotationData = {
      center: { x: centerX, y: centerY },
      initialMouseX: e.clientX,
      initialMouseY: e.clientY,
      initialRotation: this.instance.innerRotation || 0,
      initialAngle: initialAngle,
      scale: this.instance.scaleRatio
    };

    // Emit rotate start event
    const rotateEventData: RotateEventData = {
      eventType: 'rotatestart',
      i: this.instance.i,
      section_id: this.instance.sectionId,
      angle: this.instance.innerRotation,
      initialAngle: initialAngle
    };

    this.instance.eventBus.emit("rotateEvent", rotateEventData);

    if (this.events.onRotateStart) {
      this.events.onRotateStart(rotateEventData);
    }

    // Thêm sự kiện lắng nghe
    const iframeDoc = this.instance.idoc;
    iframeDoc.addEventListener("mousemove", this.handleRotateMove);
    iframeDoc.addEventListener("mouseup", this.endRotate);

    e.preventDefault();
    e.stopPropagation();
  }

  public handleRotateMove(e: MouseEvent): void {
    if (this.instance.locked) {
      this.instance.$store.commit("builder/setShowNoticeLockmode", true);
      return;
    }

    if (!this.instance.isRotating || !this.rotationData) return;

    // Lấy thông tin từ dữ liệu quay đã lưu
    const { center, initialAngle, initialRotation } = this.rotationData;

    // Tính góc hiện tại giữa vị trí chuột và tâm phần tử
    const currentAngle =
      Math.atan2(e.clientY - center.y, e.clientX - center.x) * (180 / Math.PI);

    // Tính sự thay đổi góc
    let angleDelta = currentAngle - initialAngle;

    // Tính góc quay mới
    // Đảm bảo góc nằm trong khoảng [0, 360)
    let newRotation = (((initialRotation + angleDelta) % 360) + 360) % 360;

    // Apply snap to angle if enabled
    if (this.options.snapToAngle && this.options.snapThreshold) {
      const snapAngles = [0, 45, 90, 135, 180, 225, 270, 315, 360];
      for (const snapAngle of snapAngles) {
        if (Math.abs(newRotation - snapAngle) <= this.options.snapThreshold) {
          newRotation = snapAngle % 360;
          break;
        }
      }
    }

    // Áp dụng góc quay mới
    this.instance.innerRotation = newRotation;
    this.instance.createStyle();

    // Phát sự kiện rotate move
    this.instance.$emit("rotate", this.instance.i, newRotation);

    const rotateEventData: RotateEventData = {
      eventType: 'rotatemove',
      i: this.instance.i,
      section_id: this.instance.sectionId,
      angle: newRotation,
      initialAngle: initialRotation
    };

    this.instance.eventBus.emit("rotateEvent", rotateEventData);

    if (this.events.onRotateMove) {
      this.events.onRotateMove(rotateEventData);
    }
  }

  public endRotate(e: MouseEvent): void {
    if (!this.instance.isRotating) return;

    // Gỡ bỏ sự kiện lắng nghe
    const iframeDoc = this.instance.idoc;
    iframeDoc.removeEventListener("mousemove", this.handleRotateMove);
    iframeDoc.removeEventListener("mouseup", this.endRotate);

    // Lưu rotation cuối cùng
    const finalRotation = this.instance.innerRotation;

    // Lưu initialRotation trước khi xóa rotationData
    const initialRotation = this.rotationData?.initialRotation || 0;

    // Cập nhật data trong store
    this.updateRotationInStore(finalRotation);

    // Đặt lại trạng thái
    this.instance.isRotating = false;
    this.rotationData = null; // Xóa dữ liệu quay

    setTimeout(() => {
      if (this.options.showRotationValue) {
        this.instance.isShowingRotateValue = false;
      }
      this.instance.isUpdatingFromResize = false;
    }, 1000);

    // Phát sự kiện final rotated
    this.instance.$emit("rotated", this.instance.i, finalRotation);

    const rotateEventData: RotateEventData = {
      eventType: 'rotateend',
      i: this.instance.i,
      section_id: this.instance.sectionId,
      angle: finalRotation,
      initialAngle: initialRotation
    };

    this.instance.eventBus.emit("rotateEvent", rotateEventData);

    if (this.events.onRotateEnd) {
      this.events.onRotateEnd(rotateEventData);
    }

    if (this.events.onRotated) {
      this.events.onRotated(this.instance.i, finalRotation);
    }

    e.preventDefault();
    e.stopPropagation();
  }

  private updateRotationInStore(rotation: number): void {
    const inst = this.instance.instanceStore.get(this.instance.i);
    let screen = this.instance.screen === "desktop" ? "" : "__" + this.instance.screen;

    if (inst) {
      const updateRotate = (target: any) => {
        if (!target.size_grid) target.size_grid = {};
        target.size_grid["rotate_grid" + screen] = Math.ceil(ensureNumericValue(rotation));
      };

      if (!inst?.data?.row) {
        if (inst?.data.group) {
          updateRotate(inst.data.group.style || (inst.data.group.style = {}));
        } else {
          updateRotate(inst.data.style || (inst.data.style = {}));
        }
      } else {
        updateRotate(inst.data.row.style || (inst.data.row.style = {}));
      }
    }
  }

  public destroy(): void {
    // Cleanup event listeners if needed
    if (this.instance.isRotating) {
      const iframeDoc = this.instance.idoc;
      iframeDoc.removeEventListener("mousemove", this.handleRotateMove);
      iframeDoc.removeEventListener("mouseup", this.endRotate);
    }

    // Reset rotation state
    this.instance.isRotating = false;
    this.instance.isShowingRotateValue = false;
    this.rotationData = null;
  }
}