<template>
    <div class="ecom-element ecom-base-gallery">
        <div class="ecom-gallery--container ecom-base-gallery-grid">
            <div
                v-for="image in images()"
                :key="image.id"
                class="ecom-gallery--item"
                :data-notice-content="!exporting ? $t('this_image_is_for_preview_only') : null"
                :class="{
                    'ecom-replace-notice': $helpers.isPreviewImage(image.value)
                }">
                <figure class="ecom-image-align">
                    <a
                        v-if="image.link"
                        v-bind="handleLink(image)"
                        class="ecom-image-default"
                        style="position:relative"
                    >
                        <img :src="image.value" :alt="image.alt" class="ecom-base-gallery-block" :loading="!data.settings?.disable_lazy_load ? 'lazy' : 'eager'">
                        <div v-if="data.settings.overlay_use === true" class="ecom-base-gallery-overlay ecom-overlay">
                            <span v-if="data.settings.overlay_title === 'alt'" class="ecom-overlay-text"
                                v-html="image.alt" />
                            <span v-if="data.settings.overlay_title === 'caption'" class="ecom-overlay-text"
                                v-html="image.caption" />
                            <span v-if="data.settings.overlay_title === 'custom'" class="ecom-overlay-text"
                                v-html="data.settings.overlay_title_custom" />
                        </div>
                    </a>
                    <div v-else class="ecom-relative ecom-image-default" style="position:relative">
                        <img :src="image.value" :alt="image.alt" class="ecom-base-gallery-block" :loading="!data.settings?.disable_lazy_load ? 'lazy' : 'eager'">
                        <div v-if="data.settings.overlay_use === true" class="ecom-base-gallery-overlay ecom-overlay">
                            <span v-if="data.settings.overlay_title === 'alt'" class="ecom-overlay-text"
                                v-html="image.alt" />
                            <span v-if="data.settings.overlay_title === 'caption'" class="ecom-overlay-text"
                                v-html="image.caption" />
                            <span v-if="data.settings.overlay_title === 'custom'" class="ecom-overlay-text"
                                v-html="data.settings.overlay_title_custom" />
                        </div>
                    </div>
                    <figcaption v-if="data.settings?.show_caption && image.caption" class="ecom-gallery--caption"
                        v-html="image.caption" />
                </figure>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import { Element, Javascript } from '@/mixins';

export default {
    name: 'Gallery',
    presets: true,
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/gallery/',
    linkVideo: 'https://www.youtube.com/watch?v=2lR-r7_5keY',
    mixins: [Element, Javascript],
    vendors: ['light_galerry','modal_js', 'modal_css'],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives: [
                'images'
            ]
        }
    },
    computed: {


        size() {
            let { size, size_custom } = this.data.settings;
            if (size === 'custom') {
                size = size_custom;
            }
            else if (size) {
                size = { width: size.split('x')[0], height: size.split('x')[1] };
            }
            return size;
        },
        settings() {
            return [
                {
                    group_title: this.$t('images'),
                    params: [
                        {
                            type: 'picker',
                            label: this.$t('choose_images'),
                            name: 'images',
                            options: {
                                type: 'image',
                                multiple: true,
                                modify: [
                                    {
                                        name: 'alt',
                                        label: this.$t('alt'),
                                        type: 'text'
                                    },
                                    {
                                        name: 'caption',
                                        label: this.$t('caption'),
                                        type: 'text'
                                    },
                                    {
                                        type: 'popup',
                                        name: 'link_type',
                                        label: this.$t('link'),
                                        options: {
                                            default: false,
                                            preview: 'title',
                                            values: {
                                                none: this.$t('none'),
                                                lightbox: this.$t('media_file'),
                                                custom: this.$t('custom_url')
                                            },
                                            type: 'dropdown'
                                        },
                                        css: {
                                            isCss: false
                                        }
                                    },
                                    {
                                        type: 'link',
                                        name: 'custom-link',
                                        options: {
                                            position: 'fixed',
                                            visible: (data) => {
                                                return data['link_type'] === 'custom';
                                            }
                                        }
                                    },
                                    {
                                        type: 'popup',
                                        name: 'lightbox',
                                        label: this.$t('click_open_in_lightbox'),
                                        options: {
                                            type: 'dropdown',
                                            default: false,
                                            preview: 'title',
                                            values: {
                                                yes: this.$t('yes'),
                                                no: this.$t('no')
                                            },
                                            visible: {
                                                keep_data: true,
                                                condition: (data) => {
                                                    return data['link_type'] === 'lightbox';
                                                }
                                            }
                                        }
                                    },
                                ]
                            }
                        },
                        {
                            type: 'popup',
                            name: 'lightbox',
                            label: this.$t('click_open_in_lightbox'),
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    yes: this.$t('yes'),
                                    no: this.$t('no')
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('crop_size'),
                            name: 'size',
                            value: '',
                            options: {
                                type: 'dropdown',
                                default: true,
                                preview: 'title',
                                values: {
                                    '400x300': '400 x 300px',
                                    '800x450': '800 x 450px',
                                    '500x500': '500 x 500px',
                                    custom: this.$t('custom')
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'size',
                            name: 'size_custom',
                            options: {
                                visible: (data: any) => {
                                    return data['size'] === 'custom';
                                },
                                warnings: {
                                    content: this.$t('you_can_crop_the_original_image_size_to_any_custom_size_you_can_also_set_a_single_value_for_height_or_width_in_order_to_keep_the_original_size_ratio')
                                }
                            }
                        },
                        {
                            name: 'gridTemplateColumns',
                            label: this.$t('images_per_row'),
                            type: 'number',
                            activeQuickToolBar: true,
                            options: {
                                min: 1,
                                max: 10,
                                responsive: true,
                                slider: true,

                            },
                            css: {
                                selector: ' .ecom-base-gallery .ecom-gallery--container',
                                properties: {
                                    'grid-template-columns': 'repeat(%value%, 1fr)'
                                }
                            }
                        },

                        {
                            type: 'number',
                            name: 'ecomGalleryGap',
                            label: this.$t('spacing_between'),
                            options: {
                                responsive: true,
                                units: {
                                    px: { min: 0, max: 100 }
                                }
                            },
                            css: {
                                selector: ' .ecom-base-gallery .ecom-gallery--container',
                                properties: {
                                    '--ecom-gallery-gap': ''
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_caption',
                            label: this.$t('show_caption'),
                            options: {
                                oneline: true,
                                values: {
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    },
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'disable_lazy_load',
                            label: this.$t('disable_lazy_load'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                    ]
                },
                {
                    group_title: this.$t('overlay'),
                    params: [
                        {
                            type: 'toggle',
                            name: 'overlay_use',
                            label: this.$t('enable_overlay'),
                            value: true,
                            options: {
                                oneline: true,
                                values: {
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    },
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('title_source'),
                            name: 'overlay_title',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    'none': this.$t('none'),
                                    alt: this.$t('alt'),
                                    caption: this.$t('caption'),
                                    custom: this.$t('custom')
                                },
                                visible: (data) => {
                                    return data['overlay_use'] === true;
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            name: 'overlay_title_custom',
                            label: this.$t('custom_title'),
                            type: 'text',
                            options: {
                                visible: (data) => {
                                    return (
                                        data['overlay_title'] == 'custom' &&
                                        data['overlay_use'] === true
                                    );
                                }
                            }
                        }
                    ]
                }
            ];
        },
        javascript(){
              return function () {
                  if(!this.$el || !window.EComModal) return;
                const isLive = this.isLive;
                  let arr =  this.$el.querySelectorAll('[ecom-modal]');
                  if(arr.length && isLive) {
                    new window.EComModal(arr, {
                        gallery: true,
                        cssClass: ['ecom-container-lightbox-' + this.id]
                    });
                }
            };
        },
        css() {
            return `
                .ecom-base-gallery .ecom-gallery--item .ecom-overlay-text{
                    width: 100%;
                    padding: 1rem;
                    word-break: break-word;
                }
                .ecom-base-gallery-grid {
                    display: grid
                }
                .ecom-base-gallery-block {
                    display: block
                }
                .ecom-gallery--container {
                    grid-gap: var(--ecom-gallery-gap, 30px) var(--ecom-gallery-gap, 30px);
                }
                .ecom-gallery--container{
                    grid-template-columns: repeat(4, 1fr);
                }

                .ecom-gallery--item figure {
                    display: flex;
                    flex-direction:column;
                }
                .ecom-gallery--item a{
                    position: relative;
                }
                .ecom-gallery--item img {
                    width: 100%;
                }
                .ecom-base-gallery-overlay.ecom-overlay {
                    position: absolute;
                    inset: 0;
                    z-index: 1;
                    align-items: center;
                    justify-content: center;
                    pointer-events: none;
                    display:flex;
                    text-align:center;
                }
                .ecom-base-gallery .ecom-gallery--caption, .ecom-base-gallery .ecom-image-default{
                    width:100%
                }
                `;
        },
        default() {
            return {
                settings: {
                    images: [
                        {
                            id: 1,
                            value: "/images/placeholder.png",
                            name: "Placeholder #1",
                            lightbox: "yes",
                            link_type: "media_file"
                        },
                        {
                            id: 2,
                            value: "/images/placeholder.png",
                            name: "Placeholder #2",
                            lightbox: "yes",
                            link_type: "media_file"
                        },
                        {
                            id: 3,
                            value: "/images/placeholder.png",
                            name: "Placeholder #3",
                            lightbox: "yes",
                            link_type: "media_file"
                        },
                        {
                            id: 4,
                            value: "/images/placeholder.png",
                            name: "Placeholder #4",
                            lightbox: "yes",
                            link_type: "media_file"
                        }
                    ],
                    " .ecom-base-gallery .ecom-gallery--container-child": {
                        "--ecom-gallery-gap": "30px",
                        "column-count": 4,
                        "grid-template-columns": "repeat(4, 1fr)"
                    },
                    size: "",
                    overlay_use: false,
                    overlay_title: "alt",
                    ecomGalleryGap: "10px",
                    gridTemplateColumns: 4
                },
                style: {
                    gallery_image: {
                        "align-items": "center",
                        imageOpacitynormalmode: 1,
                        imageOpacityhovermode: 1
                    },
                    overlay: {
                        opacity: 0,
                        opacityHover: 1,
                        backgroundhovermode: {
                            classic: {
                                "background-color": "rgba(17, 24, 39, 0.3)"
                            }
                        }
                    }
                }
            }
        }
    },
    methods: {
        quickToolBar() {
            return ['gridTemplateColumns', 'imageAlign', 'imageBorderRadius', 'items'];
        },
        images() {
            let images = this.$helpers.copy(this.data.settings?.images);
            if (images) {
                let id = this.$helpers.randid() + '-gallery';
                images.forEach((image) => {
                    image.value = this.$helpers.resizeImage(image.value, this.size);
                    image.alt = image.alt || image.name;
                    let link = null;
                    if (image.link_type === 'custom') {
                        link = image['custom-link'] ?? {};
                    } else if (image.link_type === 'lightbox') {
                        link = {
                            'data-ecom-modal-src': image.value,
                            'ecom-modal': 'image',
                            href: image.value
                        };
                        if (image.lightbox === 'yes') {
                            link['ecom-modal-source'] = image.value;
                        }
                    }
                    if(this.data.settings.lightbox == 'yes'){
                        link = {
                            'data-ecom-modal-src':image.value,
                            'ecom-modal': 'image',
                            href: image.value,
                            'ecom-modal-source': image.value
                        };
                    }
                    image.link = link;
                });
                return images;
            }
            return [];
        },
        isCaption() {
            return this.data.settings?.show_caption && this.images().some((x) => x.caption);
        },
        style() {
            let style = [];
            if (this.images().length) {
                style.push({
                    group_alias: 'image',
                    options: {
                        group_name: 'gallery_image',
                        group_title: this.$t('image'),
                        selector: ' .ecom-base-gallery .ecom-gallery--item .ecom-image-default',
                    },
                    modify: {
                        params: {
                            alias: 'align-items',
                            options: {
                                label: this.$t('align_items'),
                                css: {
                                    selector: 'root .ecom-image-align',
                                }
                            },
                        }
                    }
                });
            }
            if (this.isCaption()) {
                style.push({
                    group_alias: 'text',
                    options: {
                        group_name: 'gallery_caption',
                        group_title: this.$t('caption'),
                        selector: ' .ecom-base-gallery .ecom-gallery--caption'
                    },
                    modify: {
                        params:
                        {
                            position: 15,
                            fields: [
                                {
                                    alias: 'spacing'
                                }
                            ]
                        }
                    }
                });
            }
            // let checkOverlayText = this.data.settings?.overlay_title && (this.data.settings.overlay_title == 'alt' || this.data.settings.overlay_title_custom);
            if (this.data.settings?.overlay_use) {
                style.push({
                    group_alias: 'background:overlaytext',
                    options: {
                        group_name: 'overlay',
                        group_title: this.$t('overlay'),
                        selector: ' .ecom-base-gallery .ecom-image-default'
                    }
                });
            }

            return style;
        },
        handleLink(val){
            if(val.lightbox == 'yes' || this.data.settings.lightbox == 'yes'){
                return val.link;
            }
            else {
                return {
                    href: val.link.href,
                    target: val.link.target
                }
            }
        }
    }
};
</script>
