<template>
    <div class="ecom-start-library_started">
        <div class="relative ecom-start-library">
            <div :style="{display:'flex',flexWrap:'wrap',justifyContent:'center', alignItems: 'center',marginTop:'25px',marginBottom:'42px',gap:'12px'}">
                 <button
                    v-for="(source, i) in sources"
                    :key="i"
                    :class="source.id != 'ecom' ? 'ecom-button-secondary' : 'ecom-button-primary'"
                    @click="changeLibrary(source.id)"
                >
                    <span class="ecom-button-content">
                        <template v-if="source.id == 'ecom'">
                            <EcomIcon :source="icons.TemplateMajor" class="icon-builder"></EcomIcon>
                            <span class="icon-builder">{{ $t('explore_library') }}</span>
                        </template>
                        <img v-else :src="source.logo" :style="{height:'100%', padding:'10px'}"  />
                    </span>
                </button>
                 <!-- <button @click="openPageSetting" class="ecom-core-btn secondary">
                    <EcomIcon :source="icons.ExitMajor" class="icon-builder icon-color"></EcomIcon>
                    <span>Import</span>
                </button>
                <button @click="pasteClipBoard"  class="ecom-core-btn secondary" >
                    <EcomIcon :source="icons.ecClipboard" class="icon-builder icon-color"></EcomIcon>
                    <span>Paste from Clipboard</span>
                </button> -->

                <button  @click="pasteClipBoard" class="ecom-button-secondary">
                    <span class="ecom-button-content">
                        <EcomIcon :source="icons.DuplicateMinor" class="icon-builder"></EcomIcon>
                        <span class="icon-builder">{{ $t('paste_from_clipboard') }}</span>
                    </span>
                </button>
                <button @click="openPageSetting" class="ecom-button-secondary">
                    <span class="ecom-button-content">
                        <EcomIcon :source="icons.ImportMinor" class="icon-builder"></EcomIcon>
                        <span class="icon-builder">{{ $t('import_ecom_file') }}</span>
                    </span>
                </button>
            </div>
            <div v-if="loading == true" class="flex items-center justify-center -mt-10">
                <span>{{$t('loading')}}....</span>
            </div>
            <template v-else-if="layoutTrending && layoutTrending.length > 0">
                <div class="ecom-trending-items" :style="{display:'flex',width:'100%', flexDirection:'column',flexWrap:'wrap'}">
                    <h3 class="ecom-trending-items-title">{{ $t('trending_templates') }}</h3>
                    <p class="ecom-trending-items--desc">{{ $t('select_demo_and_get_started_in_no_time') }}</p>
                    <div
                        class="ecom-start-library--items"
                        :class="[
                            screen == 'tablet' ? 'ecom-screen_tablet' : '',
                            screen == 'mobile' ? 'ecom-screen_mobile' : '',
                        ]"
                    >
                        <div
                            v-for="(item, i) in layoutTrending"
                            :key="i"
                            class="ecom-start-library--item"
                        >
                            <div v-if="item.thumbnail_url" class="ecom-start-library--thumbnail" style="min-height: 180px; position: relative;" @click="insertPost(item)"  @mouseenter="thumbnSlide" @mouseleave="thumbnSlide">
                                <img :src="item.thumbnail_url" :alt="item.title" loading="lazy">
                            </div>
                            <div v-else class="ecom-start-library--thumbnail" style="min-height: 180px; height: 100%; display: flex; justify-content: center; align-items: center; position: relative;" @click="insertPost(item)" >
                                <img :src="defaultImg" :alt="item.title" loading="lazy">
                            </div>
                            <div class="ecom-core-group-bot">
                                <div class=" flex items-center justify-flex-start gap-1.5 ecom-start-library--item-title" style="gap: 6px;">
                                    <div class=" flex items-center justify-center ecom-start-library--badge--wrapper">
                                        <span v-if="item?.price > 0" class="flex items-center gap-1 ecom-start-library--badge-premium">
                                            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18" fill="none">
                                                <circle cx="9" cy="9" r="9" fill="#F43F5E" style="fill:#F43F5E;fill-opacity:1;"/>
                                                <path d="M13.9891 7.70575L13.0448 11.709C13.0261 11.7927 12.9775 11.8676 12.9075 11.9207C12.8374 11.9738 12.7502 12.0018 12.661 11.9999H5.30625C5.21699 12.0018 5.12982 11.9738 5.05976 11.9207C4.9897 11.8676 4.94112 11.7927 4.9224 11.709L4.00881 7.70575C3.99344 7.6381 3.99825 7.56767 4.02269 7.50253C4.04713 7.43739 4.09022 7.38018 4.147 7.33746C4.20394 7.29459 4.27236 7.26804 4.34435 7.26087C4.41635 7.25371 4.48899 7.26621 4.55389 7.29695L6.79562 8.33919L8.65349 5.1867C8.68697 5.13002 8.73552 5.08288 8.79419 5.05008C8.85286 5.01728 8.91955 5 8.98745 5C9.05535 5 9.12204 5.01728 9.18071 5.05008C9.23938 5.08288 9.28793 5.13002 9.3214 5.1867L11.1793 8.34287L13.4364 7.29327C13.5017 7.26003 13.5757 7.24561 13.6494 7.25177C13.7231 7.25792 13.7934 7.28438 13.8518 7.32796C13.9102 7.37154 13.9542 7.43038 13.9786 7.4974C14.003 7.56443 14.0066 7.63678 13.9891 7.70575Z" fill="white" style="fill:white;fill-opacity:1;"/>
                                            </svg>
                                        </span>
                                        <span v-else class="ecom-start-library--badge-free">Free</span>
                                    </div>
                                    <span class="ecom-post-title">{{ item.title }}</span>
                                </div>
                                <div class="ecom-core-freedom-btn-group">
                                    <button class="ecom-button-secondary" type="button" @click="insertPost(item)">
                                        <span class="ecom-button-content">
                                            {{ $t('insert_now') }}
                                        </span>
                                    </button>
                                    <button class="ecom-button-secondary ecom-button-secondary-square" :data-tooltip="$t('preview')" @click="previewTemplate(item)" type="button" title="Preview">
                                        <span class="ecom-button-content">
                                            <EcomIcon :source="icons.ViewMinor" class="icon-builder-big"></EcomIcon>
                                        </span>
                                    </button>
                                    <button
                                        class="ecom-button-heart"
                                        :title="favorites.includes(item.id) ? $t('remove_from_my_favorites') : $t('add_to_my_favorites')"
                                        @click.stop="handleFavorite(favorites.includes(item.id), item.id, i)"
                                    >
                                        <div class="ecom-button-icon-loader w-4" v-if="loadingFavorites[i]"></div>
                                        <EcomIcon :source="icons.ecHeartOutLine" v-else-if="!favorites.includes(item.id)" class="icon-builder-big"></EcomIcon>
                                        <EcomIcon :source="icons.ecHeart" v-else class="ecom-button-heart-active"></EcomIcon>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                    <button class="ecom-button-secondary ec-mx-auto" type="button" @click="changeLibrary('ecom')">
                        <span class="ecom-button-content">
                            {{ $t('view_all_templates') }}
                        </span>
                    </button>
                </div>
            </template>
            <p v-else>
                {{ $t('no_trending_templates') }}
            </p>

        </div>
    </div>
</template>

<script>
    // import { faFolders, faFileImport, faPaste } from '@fortawesome/pro-light-svg-icons';
    import { ROOT_STORE } from '@/store/constants';

    import { fields} from '@/constants/confirm';
    import { TemplateMajor, ExitMajor, ecClipboard, ImportMinor, DuplicateMinor, ecHeartOutLine, ViewMinor , ecHeart} from "@/assets/icons";
    export default {
        inject: ['instanceStore'],
        data () {
            return {
                defaultImg: '/images/placeholder.png',
                items: [],
                ready: false,
                // faFolders, faFileImport, faPaste,
                icons: {
                    TemplateMajor, ExitMajor, ecClipboard, ImportMinor, DuplicateMinor, ecHeartOutLine, ViewMinor , ecHeart
                },
                loadingFavorites: [],
            };
        },
        computed: {
            insert(){
                return this.$store.getters['library/insert'];
            },
            currentName(){
                return this.insert.current;
            },
            layoutTrending(){
                const layouts = this.instanceStore.get('layoutTrending');
                return layouts?.slice(0,4);
            },

            loading(){
                return this.$store.getters['page/loading'];
            },
            sources(){
                return this.$store.getters['library/sources'];
            },
            screen(){
                return this.$store.getters['builder/screen'];
            },
            favorites() {
                let favorites = this.$store.getters["library/favorites"];
                return favorites.toString().replace(/[\[\]]/g, '').split(',').map(Number);
            },
            params(){
                return this.$store.getters['page/params'];
            },
            idPageCat() {
                // let page =  this.params?.page;
                // let category_slugs = [
                //     // {
                //     //     title: 'product',
                //     //     id: 13 // Tren dev 13, live 6
                //     // },
                //     // {
                //     //     title: 'collection',
                //     //     id: 57 // Tren dev 57, live 9
                //     // },
                //     // {
                //     //     title: 'blog',
                //     //     id: 5 // Tren dev 5, live 10
                //     // },
                //     // {
                //     //     title: 'article',
                //     //     id: 12
                //     // },
                //     // {
                //     //     title: 'home',
                //     //     id: 11 // Tren dev 11, live 3
                //     // },
                //     // {
                //     //     title: 'footer',
                //     //     id: 87
                //     // },
                //     // {
                //     //     title: 'cart',
                //     //     id: 119
                //     // },
                //     // {
                //     //     title: 'page',
                //     //     id: 6
                //     // }
                //     {
                //         title: 'product',
                //         id: 6
                //     },
                //     {
                //         title: 'collection',
                //         id: 9
                //     },
                //     {
                //         title: 'blog',
                //         id: 10
                //     },
                //     {
                //         title: 'article',
                //         id: 12
                //     },
                //     {
                //         title: 'home',
                //         id: 3
                //     },
                //     {
                //         title: 'footer',
                //         id: 87
                //     },
                //     {
                //         title: 'cart',
                //         id: 119
                //     },
                //     {
                //         title: 'page',
                //         id: 86
                //     },
                //     {
                //         title: 'popup',
                //         id: 172
                //     }
                // ];
                // if(category_slugs.filter(el=>el.title === page)[0]?.id)
                // {
                //     let curentCat = category_slugs.filter(el=>el.title === page);
                //     return curentCat[0].id;
                // }
                // Luồng library mới dùng slug xuyên suốt (category_slug / currentCat),
                // không dùng id số để tránh lệch giữa các môi trường.
                const categories = this.$store.getters['library/categories'] || [];
                const isPageCat = (slug) => categories.some((c) => c.type === 'page' && c.slug === slug);

                // `start_building` = category slug merchant chọn ở backend (about-us,
                // contact-us, faqs…). Phải xét trước `params.page`: không có page_type nào
                // tên như vậy nên `params.page` luôn ra 'page' → rơi vào Landing Pages.
                // Giống cách TemplateExpand xử lý param này.
                const startBuilding = String(this.params?.start_building || '').trim().toLowerCase();
                if (startBuilding && isPageCat(startBuilding)) return startBuilding;

                const page = this.params?.page;
                if (!page) return '';
                return isPageCat(page) ? page : '';
            },
            currentLibrary(){
                return this.insert.metaData?.source || 'ecom';
            },
            user() {
                return this.$store.getters['global/user'] || {};
            },
            libraryVip() {
                const user = this.user;
                return user?.plan_permissions ? user.plan_permissions.permissions?.library_vip : false;
            },
        },
        methods: {
            isFlexbox(item) {
                return item?.tags?.find(tag => tag.name.toLowerCase() == 'flexbox');
            },
            async handleSwitchToFlexbox() {
                try {
                    this.$store.commit("builder/setPopup", {
                        show: true,
                        loading: true,
                        message: "Please wait while we process your request...",
                        closeable: false
                    });

                    const response = await this.$worker.fetch(
                        window.route("builder.switch-layout"),
                        { enable: true },
                        "POST"
                    );

                    if (response && response.data && response.data.status === "success") {
                        this.$store.commit("builder/setPopup", {
                            type: "warning",
                            title: "Congratulations",
                            show: true,
                            loading: false,
                            loading_btn: true,
                            message: "Welcome to the Flexbox Layout! <br />Your registration was successful. Simply reload the page to access and use Flexbox templates.",
                            closeable: true
                        });
                    } else {
                        this.$store.commit("builder/setPopup", {
                            show: true,
                            loading: false,
                            title: "Error",
                            message: response?.data?.message || "Failed to switch layout. Please try again.",
                            closeable: true
                        });
                    }
                } catch (error) {
                    console.error("Error switching to flexbox layout:", error);
                    this.$store.commit("builder/setPopup", {
                        show: true,
                        loading: false,
                        title: "Error",
                        message: "An error occurred while switching layout. Please try again.",
                        closeable: true,
                        action: {
                            title: "OK"
                        }
                    });
                }
            },
            handleFavorite (status, value, index) {
                status = status ? 'deactive' : 'active';
                this.loadingFavorites[index] = true;
                this.$store.dispatch('library/handleFavorite', {
                    status,
                    value
                });
            },
            changeLibrary(name) {
                this.$store.dispatch(ROOT_STORE.ACTIONS.SET_TAB, 'templateExpand');
                this.$store.dispatch(ROOT_STORE.ACTIONS.UPDATE_IS_TEMP_HIDE, false);
                this.$store.commit('global/setSidebarTabActive', {id: 'template'});
                this.$store.dispatch('library/setLoading', true);
                let metaData
                if(name == 'theme'){
                    metaData = {
                        ...this.insert.metaData,
                        category: '',
                        source: 'theme',
                        screen: 'theme'
                    }

                    // this.buttonTemplate.forEach(item => {
                    //     if (['my_templates', 'my_tasks', 'my_favorites'].includes(item.name)) {
                    //         item.show = false;
                    //     }
                    // });
                    this.$store.commit('library/setDetailScreen',{"title":"","id":`theme_pages`});
                    this.$store.commit('library/showSaveForm', false);
                    this.$store.dispatch('library/setInsert', {
                        current: 'pages',
                        metaData: metaData,
                    });


                    this.$store.dispatch('library/setInsert', {
                        current: 'pages',
                        metaData: metaData,
                    });
                }else{
                    this.$store.commit('library/setDetailScreen', null);
                    this.$store.commit('library/showSaveForm', false);
                    const pageSlug = name == 'ecom' ? (this.idPageCat || '') : '';
                    metaData = {
                        ...this.insert.metaData,
                        category: '',
                        category_slug: pageSlug || undefined,
                        source: name,
                    }
                    if(pageSlug){
                        let source = `pages-${this.currentLibrary}`;
                        let cat = {};
                        cat[source] = pageSlug;
                        this.$store.dispatch('library/setCurrentCat', cat);
                    }
                    // this.buttonTemplate.forEach(item => {
                    //     if (['my_templates', 'my_tasks', 'my_favorites'].includes(item.name)) {
                    //         item.show = true;
                    //     }
                    // });

                    this.$store.dispatch('library/setInsert', {
                        current: 'all_pages',
                        metaData: metaData,
                    });
                }
                // if(name == 'ecom') {
                //     this.$store.dispatch('library/setInsert', {current: 'sections'});
                // } else if(name == 'theme' && this.currentName != 'pages')  {
                //     this.$store.dispatch('library/setInsert', {current: 'pages'});
                // }

                // library/changeLibrary mặc định reset categoryId = null.
                // Với luồng mở từ StartLibrary -> Explore library, cần giữ page slug
                // để request đầu đã filter đúng page type hiện tại (vd: popup/product...).
                if (name === 'ecom') {
                    const pageSlug = this.idPageCat || '';
                    this.$store.commit('library/setContext', { sourceId: name });
                    this.$store.commit('library/setQuery', {
                        page: 1,
                        search: '',
                        nicheId: null,
                        tags: [],
                        detailKey: null,
                        categoryId: pageSlug || null,
                        pageContext: pageSlug || undefined,
                    });
                    this.$store.dispatch('library/load', { isChangeCat: true });
                } else {
                    this.$store.dispatch('library/changeLibrary', name);
                }
            },
            previewTemplate (item) {
                this.$store.dispatch('library/setInsert', {
                        isOpen: true,
                        type: 'library',
                    });
                this.$store.dispatch("library/setPreview", { open: true, ...item });
            },
            insertPost(item) {
                if (this.isFlexbox(item) && !this.user?.use_flexbox) {
                    let key = 'EComCallback' + new Date().getTime();
                    window[key] = (type) => {
                        if (type === 'reject') return true;
                        this.handleSwitchToFlexbox();
                    };
                    this.$store.commit('builder/setPopup', {
                        show: true,
                        type: 'warning',
                        loading: false,
                        closeable: true,
                        title: 'Flexbox Layout Required',
                        callback: key,
                        action: {
                            title: 'Switch to Flexbox Layout'
                        },
                        cancel: this.$t('cancel'),
                        message: 'This template requires Flexbox Layout. You need to switch to Flexbox Layout to use this template. <a href="https://help.ecomposer.io/docs/ecomposer-editor/flexbox-layout/" target="_blank" style="color: #2563eb; text-decoration: underline;">Learn more</a>',
                    });
                    return;
                }

                if(item?.price > 0 && !this.libraryVip) {
                    this.$store.dispatch('upgrade/showUpgradePopup', {
                        feature_key: 'library_vip',
                        source_location: 'start_library',
                        message: this.$t('this_template_is_only_available_in_paid_plans'),
                    }, { root: true });
                    return;
                }

                let key = 'EComCallback' + new Date().getTime();
                    window[key] = (type,params) => {
                        if(type === 'reject') return true;
                        this.$store.dispatch('library/insertPost', { id: item.id, type,params });
                    };
                    this.$store.commit('builder/setPopup',
                        {
                            show: true,
                            type: 'warning',
                            loading: false,
                            closeable: true,
                            title: this.$t('insert_this_template'),
                            callback: key,
                            action: {
                                title: this.$t('insert')
                            },
                            cancel: this.$t('cancel'),
                            fields:fields,
                            message: ``,
                            values:{
                                overwrite: false,
                                remove_typo: false
                            }
                    });
            },
            thumbnSlide(e) {
                let img = e.target.querySelector("img");
                if (e.type == "mouseenter") {
                    let top = img.offsetHeight - e.target.offsetHeight;
                    let slideTime = this.calculateSlideTime(img.offsetHeight);
                    img.style.transition = `top ${slideTime}s ease`;
                    img.style.top = -(top > 0 ? top : 0) + "px";
                } else {
                    img.style.transition = "top 0.8s ease";
                    img.style.top = "0px";
                }
            },

            calculateSlideTime(height) {
                let slideTime = height / 100 * 0.2;
                return slideTime;
            },

            openPageSetting(){
                this.$store.commit('page/setImportPopup', true);
            },
            pasteClipBoard(){
            if(!window.navigator.clipboard)
            {
                return this.$store.commit('global/setToast', {
                    isError: true,
                    message: this.$t('your_browser_not_support_clipboard'),
                    duration: 4000
                });

            }
            window.navigator.clipboard.readText().then((text)=>{
                if(!text)
                {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: this.$t('your_clipboard_empty'),
                        duration: 4000
                    });
                }
                else
                {
                    try{
                        let data = JSON.parse(text);
                        this.$store.commit('page/insertSections',  {sections: [data]}, { root: true });
                    }
                    catch(e)
                    {
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: this.$t('your_data_from_clipboard_invalid'),
                            duration: 4000
                        });
                    }
                }
            })
            .catch(e=>{
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: e.message,
                    data: e,
                    duration: 4000
                });
            })
        }

        },
        watch: {
            'favorites': {
                handler() {
                    this.loadingFavorites = this.loadingFavorites.map(() => false);
                },
                immediate: true
            },
        },
        mounted() {
            this.$store.dispatch('library/load', {isChangeCat: true});
        },

    };
</script>
<style>
    .loading {
        animation: loading 1.5s 0s infinite;
    }
    @keyframes loading {
        0% {
            opacity: 1;
            filter: contrast(1);
        }
        25% {
            opacity: 0.25;
        }
        50% {
            opacity: 0.75;
            filter: contrast(0);
        }
        75% {
            opacity: 0.25;
        }
        100% {
            opacity: 1;
            filter: contrast(1);
        }
    }
</style>
