<template>
    <div
        class="relative"
        :class="[field?.options?.oneline && isChooseOne ? 'ml-auto' : '', id]"
    >
        <button v-if="isChooseOne" type="button" class="relative flex h-8 w-8 items-center justify-center rounded-md border border-solid border-secondary bg-surface-tertiary text-text-primary" :data-tooltip="itemActive?.tooltip ?? null" @click="open">
            <EcomIcon v-if="preview.type === 'icon'" :source="icons[preview.icon]" :size="itemActive?.size?itemActive.size: sizeIcon" class="flex items-center justify-center" :class="type === 'align-y' || type === 'vertical-align' && itemActive?.icon ? 'rotate-90' : ''"></EcomIcon>
            <p v-else class="text-xs font-medium" v-html="preview.text" />
        </button>
        <transition
            enter-active-class="transition duration-200 ease-out"
            enter-from-class="transform scale-90 opacity-0"
            enter-to-class="transform scale-100 opacity-100"
            leave-active-class="transition duration-150 ease-in"
            leave-from-class="transform scale-100 opacity-100"
            leave-to-class="transform scale-90 opacity-0"
        >
            <template v-if="isChooseOne">
                <div v-if="isopen" class="absolute z-50 ecom-fields__popup"
                    :class="[popupPosition === 'bottom' ? 'top-full mt-3' : 'bottom-[calc(100%+12px)]']"
                    ref="popup_container"
                    :style="{marginLeft: '-' + moveLeftPoup+'px'}"
                    >

                    <div class="relative z-[2] inline-block p-1 bg-white text-white   rounded shadow-popup">
                        <!-- <svg
                            viewBox="0 0 213.3 213.3"
                            class="absolute w-4 h-4 mr-1 -mt-3 left-3 fill-current"
                            :class="[popupPosition === 'bottom' ? 'transform rotate-180 top-0' : '-bottom-[12px]']"
                        >
                            <polygon
                                class="shadow-xxl"
                                points="0,53.333 106.667,160 213.333,53.333"
                            />
                        </svg> -->
                        <div class="inline-flex gap-1 rounded p-1">
                            <a
                                v-for="(item, index) in types[type]"
                                :key="index"
                                href="javascript:;"
                                class="text-center"
                                :class="classButton(index)"
                                :data-tooltip="item.tooltip"
                                @click.prevent="selectedIndex = index"
                            >
                                <EcomIcon v-if="item.icon" :source="icons[item.icon]" :size="item.size? item.size : 'w-5'" class="flex items-center justify-center" :class="[type === 'align-y' || type === 'vertical-align' ? 'rotate-90' : '']"></EcomIcon>
                                <span v-else class="text-xs font-medium" v-html="item.text" />
                            </a>
                        </div>
                    </div>
                </div>
            </template>
            <template v-else>
                <div class="ecom-fields__popup bg-white "
                    :class="isQuickToolBar ? 'mt-0' : 'mt-2'"
                    >
                    <div class="relative z-[2] inline-flex items-center">
                        <div class="inline-flex gap-[7px] rounded">
                            <div v-for="(item, index) in types[type]" :key="index" class="relative flex items-center gap-px">
                                <a
                                    href="javascript:;"
                                    class="text-center"
                                    :class="classButton(index)"
                                    :data-tooltip="item.tooltip"
                                    @click.prevent="selectedIndex = index"
                                >
                                    <EcomIcon v-if="item.icon" :source="icons[item.icon]" :size="item.size? item.size : 'w-5'" class="flex items-center justify-center" :class="[type === 'align-y' || type === 'vertical-align' ? 'rotate-90' : '']"></EcomIcon>
                                    <span v-else class="text-xs font-medium" v-html="item.text" />
                                </a>
                                <!-- <div
                                    v-if="index !== types[type].length - 1"
                                    class="w-[1px] h-3 bg-tab-divider"
                                    :class="index !== types[type].length - 1 && selectedIndex !== index && selectedIndex !== index + 1 ? 'opacity-100' : 'opacity-0'"></div> -->
                            </div>
                        </div>
                    </div>
                </div>
            </template>
        </transition>
    </div>
</template>

<script>
    import { Popmenu } from '@/mixins';
    import {ecAlignLeft, ecAlignRight, ecAlignCenter, ecAlignTop, ecAlignBottom, ecAlignJustify,
         TemplateMajor, TitleMinor, FavoriteMajor, ecAlignMid, ecAlignmentJustify, ecBaseLine, ecStretch, ecSpaceBetween, ecSpaceAround,
          ecSpaceEvenly,ecAlignContentCenter,contentWidthDefault, contentBoxed, contentFullWidth, contentHeightDefault, contentFixToScreen, contentMinHeight, ecWrap, ecDotsVertical} from '@/assets/icons'
    import { choices } from '@/plugins/fields/constants/choices';
    export default {
        name: 'ChooseField',
        mixins: [ Popmenu ],
        props: {
            // eslint-disable-next-line vue/require-default-prop
            data: [String, Number],
            field: {
                type: Object,
                default(){
                    return {};
                }
            },
            isQuickToolBar: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:data'],
        data(){
            return {
                selectedIndex: -1,
                isWatch: true,
                isEmit: false,
                popupPosition: 'bottom',
                icons: {
                    'ecAlignLeft': ecAlignLeft,
                    'ecAlignRight': ecAlignRight,
                    'ecAlignCenter': ecAlignCenter,
                    'ecAlignTop': ecAlignTop,
                    'ecAlignBottom': ecAlignBottom,
                    'ecAlignJustify': ecAlignJustify,
                    'TemplateMajor': TemplateMajor,
                    'TitleMinor': TitleMinor,
                    'FavoriteMajor': FavoriteMajor,
                    'ecAlignMid': ecAlignMid,
                    'ecAlignmentJustify': ecAlignmentJustify,
                    'ecBaseLine':ecBaseLine,
                    'ecStretch':ecStretch,
                    'ecAlignContentCenter':ecAlignContentCenter,
                    'ecSpaceBetween':ecSpaceBetween,
                    'ecSpaceAround':ecSpaceAround,
                    'ecSpaceEvenly':ecSpaceEvenly,
                    'contentWidthDefault':contentWidthDefault,
                    'contentBoxed':contentBoxed,
                    'contentFullWidth':contentFullWidth,
                    'contentHeightDefault':contentHeightDefault,
                    'contentFixToScreen':contentFixToScreen,
                    'contentMinHeight':contentMinHeight,
                    'ecWrap':ecWrap,
                    'ecDotsVertical': ecDotsVertical
                },
                moveLeftPoup: 0
            };
        },
        computed: {
            isChooseOne(){
                return this.field?.options?.chooseOne;
            },
            keep() {
                return false;
            },
            type(){
                return this.field?.options?.type ?? 'align';
            },
            types(){
                let result = structuredClone(choices);
                if(this.type == 'heading' && this.field?.options?.link == false) {
                    const temp = result.heading.pop()
                }
                // note guide use modify
                // {
                //     type: 'choose',
                //     label: this.$t('span_class_uppercase_html_span_tag'),
                //     name: 'tag',
                //     options: {
                //         chooseOne:true,
                //         type: 'heading',
                //         modify: {
                //             add: [
                //                 {
                //                     text: 'P',
                //                     value: 'p'
                //                 }
                //             ],
                //             remove: [
                //                 {
                //                     value: 'a'
                //                 }
                //             ]
                //         }
                //     }
                // },
                if(this.type == 'heading' && this.field?.options?.modify) {
                    const adds = this.field?.options?.modify.add || [];
                    const removes = this.field?.options?.modify.remove || [];
                    if(adds.length > 0) {
                        adds.forEach((item) => {
                            result.heading.push(item);
                        })
                    }
                    if(removes.length > 0) {
                        const valuesRemove = removes.map(item => item.value);
                        const newHeadingTag = result.heading.filter(item => !valuesRemove.includes(item.value));
                        result.heading = newHeadingTag;
                    }

                }
                return result;
            },
            values(){
                if (this.field?.options?.values) {
                    return this.field.options.values;
                }
                let res = [];
                if (this.types?.[this.type]) {
                    this.types?.[this.type].forEach((item) => {
                        res.push(item?.value ?? '');
                    });
                }
                return res;
            },
            value(){
                return this.values?.[this.selectedIndex];
            },
            itemActive() {
                let t = this.types[this.type];
                return t?.[this.selectedIndex];
            },
            typeIcon() {
                let options = this.field.options, icon = '';
                let type = options?.type;
                switch (type)
                {
                    case 'vertical-align' :
                    case 'align-y' : {
                        icon = 'ecAlignCenter';
                        break;
                    }
                    case 'align-content':
                    case 'align-items':{
                        icon = 'ecAlignContentCenter';
                        break;
                    }
                    case 'align-y-full': {
                        icon = 'ecAlignMid';
                        break;
                    }
                    case 'content-width': {
                        icon = 'contentWidthDefault';
                        break;
                    }
                    case 'content-height': {
                        icon = 'contentHeightDefault';
                        break;
                    }
                    case 'layout' : {
                        icon = 'TemplateMajor';
                        break;
                    }
                    case 'heading' : {
                        icon = 'TitleMinor';
                        break;
                    }
                    case 'rating' : {
                        icon = 'FavoriteMajor';
                        break;
                    }
                    case 'flex-wrap': {
                        icon = 'ecWrap';
                        break;
                    }
                    default : {
                        icon = 'ecAlignRight';
                    }
                }
                return icon;
            },
            preview() {
                if(this.itemActive?.icon) {
                    return {
                        type: 'icon',
                        icon: this.itemActive.icon
                    };
                }
                else if (this.itemActive?.text) {
                    return {
                        type: 'text',
                        text: this.itemActive.text
                    };
                }
                else {
                    return {
                        type: 'icon',
                        icon: this.typeIcon
                    };
                }
            },
            sizeIcon(){
                let size = 'w-5';
                for (let i = 0; i < this.types[this.type].length; i++){
                    if (this.preview?.icon == this.types[this.type][i].icon ){
                        size = this.types[this.type][i]?.size;
                        break;
                    }
                }
                return size;
            }
        },
        watch: {
            data: {
                immediate: true,
                handler: function(val){
                    if(this.isWatch){
                        this.isEmit = false;
                        this.selectedIndex = this.values.indexOf(val ?? '');
                    }
                this.isWatch = true;

                }
            },
            value: {
                immediate: true,
                handler: function(val){
                    if(this.isEmit){
                        this.isWatch = false;
                        this.$emit('update:data', val);
                    }
                    this.isEmit = true;
                }
            },
            isopen: {
                handler: function(val){
                    if(val){
                        this.$nextTick(() => {
                            const idoc = window.EComposerBuilder?.contentDocument || document;
                            if (idoc.value) {
                                idoc.value.addEventListener("click", this.handleClickOutside);
                            }
                            document.addEventListener("click", this.handleClickOutside);
                            let checkWidthScreen = this.$refs['popup_container'].getBoundingClientRect().left + this.$refs['popup_container'].getBoundingClientRect().width;
                            const rect = this.$refs['popup_container'].getBoundingClientRect();
                            if(rect.y + rect.height > window.innerHeight - 100  && rect.y > rect.height + 100) {
                                this.popupPosition = 'top';
                            }
                            if((checkWidthScreen - window.innerWidth) > -15){
                                this.moveLeftPoup = (checkWidthScreen - window.innerWidth) + 20
                            }
                        })
                    }
                }
            }

        },
        methods: {
            classButton(index){
                const base = 'flex h-8 w-8 shrink-0 items-center justify-center rounded border border-solid border-secondary transition-all duration-300';
                if (this.selectedIndex === index) {
                    return `${base} bg-surface-tertiary text-text-primary`;
                }
                return `${base} bg-white text-[#3e3e3e]`;
            },
            doClose(){
                this.isopen = false;
                const idoc = window.EComposerBuilder?.contentDocument || document;
                if (idoc.value) {
                    idoc.value.removeEventListener("click", this.handleClickOutside);
                }
                document.removeEventListener("click", this.handleClickOutside);
            },
            handleClickOutside(event) {
                const modalButtonEl = this.$refs.btnModalChoose;
                const btnModalChoose = this.$refs.btnModalChoose;
                if (modalButtonEl && btnModalChoose && !modalButtonEl.contains(event.target) && !btnModalChoose.contains(event.target)) {
                    this.doClose();
                }
            }
        }
    };
</script>
