<i18n>
{
    "en": {
        "add_new_color": "Add more",
        "new_item": "New Item"
    },
    "fr": {
        "add_new_color": "Ajouter une nouvelle couleur",
        "new_item": "Nouvel élément"
    },
    "de": {
        "add_new_color": "Neue Farbe hinzufügen",
        "new_item": "Neues Element"
    },
    "ja": {
        "add_new_color": "新しい色を追加",
        "new_item": "新しいアイテム"
    }
}
</i18n>
<template>
<div :key="refresh" class="global-color-fields">
    <Fields
        :fields="fields"
        :data="valueField"
        :freeform="true"
        @update:label="updateLabel"
        @update:delete="updateDelete"
        @update:data="update"
    />
    <div class="flex flex-wrap justify-start items-center">
        <div class="w-[45%]"></div>
        <div class="flex-1 flex-wrap justify-start items-center">
            <button @click.prevent="addItem" type="button" class="inline-flex justify-start items-center h-9 border-0 font-normal text-[#005BD3] hover:text-gray-800 transition-all duration-300 rounded-md">
                <EcomIcon :source="icons.CirclePlusMajor" :size="'w-5'" class="inline-flex justify-start items-center mr-1.5"></EcomIcon>
                <span class="text-xs">{{ $t('add_new_color') }}</span>
            </button>
        </div>
    </div>
   
</div>
</template>

<script lang="ts">
    import { CirclePlusMajor } from "@/assets/icons";
    export default {
        name: 'Color',

        data() {
            return {
                refresh: true,
                itv: null,
                icons:{CirclePlusMajor},
                fields:[],

            };
        },
        computed: {

            values(){
                return this.$store.getters['settings/globalData']('colors');

            },
            valueField(){
                let vs = {};
                for(let k in this.values) {
                    vs[k] = this.values[k].value ?? '';
                }
                return vs;
            },

        },

        methods: {

           update(_field, values){
                if (!values || typeof values !== 'object') return;

                for (const id in this.values) {
                    const next = id in values ? values[id] : '';
                    if (this.values[id].value !== next) {
                        this.values[id].value = next;
                    }
                }
           },

            updateLabel([name, label]) {
                let handle = label.replace(/\s+/g, ' ').trim();
                const isDuplicate = Object.entries(this.values).some(([k, v]) => k !== name && v.title === handle);
                if (isDuplicate) {
                    let counter = 2;
                    let newTitle = handle + '-' + counter;
                    while (Object.entries(this.values).some(([k, v]) => k !== name && v.title === newTitle)) {
                        counter++;
                        newTitle = handle + '-' + counter;
                    }
                    this.values[name].title = newTitle;
                }else {
                    this.values[name].title = handle;
                }
                this.renderFields();

            },
            addItem(){
                this.values[this.$helpers.makeId(6)] = {
                    title: this.$t('new_item'),
                    value:''
                };
                this.renderFields();
            },
            updateDelete(name) {
                delete this.values[name];
                this.renderFields();
            },
            renderFields(){
                let params = [];
                let values = this.values ?? {};
                for (let id in values) {
                    let data = values[id];
                    let param = {
                        name: id,
                        label: data.title,
                        type: 'color',
                        class: 'ecom-global-color-field',
                        value: data.value,
                        options: {
                            oneline: true,
                            editLabel: !['primary','secondary','text','accent'].includes(id),
                            isdelete: true,
                            delete: !['primary','secondary','text','accent'].includes(id),

                        }
                    };
                    params.push(param);
                }
                return this.fields = params;
            }
        },
        mounted() {
            this.renderFields();
        },
        unmounted() {
        },

    };
</script>

