<template>
    <div
    class="ecom-elements ecom-base-element ecom-elements__simple-slider"
    :class="{'ecom-ingrid-full-height': data.inGrid}"
    :style="{'--ec-splide-content-transition':slider.settings?.sliderAnimationDuration + 'ms'}"
    >
        <GroupElement
            v-if="true"
            :data="data"
            :deep="deep"
            :index="index"
            :section_id="section_id"
            :breadcrumb="`${breadcrumb}/${data?.id}`"
            :inGrid="data.inGrid"
        >
            <template #items="payload">
                <div
                    class="ecom-simple-slider--container ec_splide ec-slider-hidden"
                    :data-ec-splide-option="attrSplide"

                    v-bind="classFullHeight"
                >
                    <!-- custom arrow -->
                    <div
                        v-if="slider.settings?.navigation?.enable_navigation"
                        class="ec_splide__arrows"
                        :data-position="slider.settings?.navigation?.navigation_position"
                        :data-position-tablet="
                            slider.settings?.navigation?.navigation_position__tablet
                        "
                        :data-position-mobile="
                            slider.settings?.navigation?.navigation_position__mobile
                        "
                    >
                        <button
                            type="button"
                            class="ec_splide__arrow ec_splide__arrow--prev"
                            v-html="slider.settings?.navigation?.slider_prev_icon"
                            :style="sliderNav"
                        ></button>
                        <button
                            type="button"
                            class="ec_splide__arrow ec_splide__arrow--next"
                            v-html="slider.settings?.navigation?.slider_next_icon"
                            :style="sliderNav"
                        ></button>
                    </div>
                    <div
                        class="ecom-element ec_splide__track"
                        :class="[
                            'ecom--simple-slider-' + data.settings?.imageHeight,
                            'ecom--simple-slider-tablet-' + data.settings?.imageHeight__tablet,
                            'ecom--simple-slider-mobile-' + data.settings?.imageHeight__mobile
                        ]"
                        v-bind="classFullHeight"
                    >
                        <div class="ec_splide__list" :style="splideListStyle">
                            <div
                                v-for="(item, i) in payload.items"
                                :key="item.id"
                                class="ec_splide__slide ecom-swiper-slide"
                                :style="sliderItemRatio(item.image, payload.items[0]?.image)"
                                :class="getAnimation()"
                                v-bind="classFullHeight"
                            >
                                <div class="ec-content-item" :style="backgroundHighlight(item)">
                                    <div
                                        v-if="item.image"
                                        class="ec-slider__image--wrapper"
                                        :class="{
                                            'ec-slider__has-link':
                                                item?.link?.href && item?.link?.href != ''
                                        }"
                                        :data-id="item.id"
                                        @click="editSlider(i)"
                                        v-bind="classFullHeight"
                                    >
                                        <picture
                                            class="ecom-image-background"
                                            v-bind="classFullHeight"
                                            :loading="item?.lazyload ? 'auto' : 'lazy'"
                                            v-html="
                                                $helpers.renImageResponsive(
                                                    {...item.image},
                                                    storeScreens,
                                                    !item?.lazyload,
                                                    img_style(item),
                                                    i,
                                                    item?.fetch_priority || '',
                                                    'ecom-ingrid-full-height'
                                                )
                                            "
                                        />
                                        <div v-if="item.overlay" class="ecom-overlay"></div>
                                    </div>
                                    <div
                                        class="ec-content-item__container"
                                        :class="[
                                            'ecom-transition-' + slider?.settings?.content_animation
                                        ]"
                                        :style="content_alignment(item)"
                                    >
                                        <Blocks
                                            :data="item.blocks"
                                            :deep="deep"
                                            :index="i"
                                            :section_id="section_id"
                                            :breadcrumb="`${breadcrumb}/${data?.id}`"
                                            :isFlexContainer="true"
                                        />
                                    </div>
                                    <a
                                        v-if="
                                            exporting && item?.link?.href && item?.link?.href != ''
                                        "
                                        :href="item.link.href"
                                        v-bind="item.link"
                                        class="ec-slider__image--link"
                                    />
                                </div>
                            </div>
                        </div>

                        <!-- Custom pagination -->
                    </div>
                    <ul
                        v-show="is_pagination_classic"
                        :data-pagination="is_pagination_classic"
                        class="ec_splide__pagination custom-pagination"
                        :data-position="slider.settings?.pagination?.pagination_position"
                        :data-position-tablet="
                            slider.settings?.pagination?.pagination_position__tablet
                        "
                        :data-position-mobile="
                            slider.settings?.pagination?.pagination_position__mobile
                        "
                    ></ul>

                    <div
                        v-show="isPaginationShow('progress')"
                        class="ec_splide__progress"
                        :data-position="slider.settings?.pagination?.pagination_position"
                        :data-position-tablet="
                            slider.settings?.pagination?.pagination_position__tablet
                        "
                        :data-position-mobile="
                            slider.settings?.pagination?.pagination_position__mobile
                        "
                    >
                        <div class="ec_splide__progress__paginate"></div>
                    </div>
                    <div v-if="data.settings?.show_progress_bar" class="ecom-autoplay-progress">
                        <svg viewBox="0 0 48 48" stroke="currentColor">
                            <circle cx="24" cy="24" r="20"></circle>
                        </svg>
                        <span></span>
                    </div>
                </div>
            </template>
        </GroupElement>
    </div>
</template>

<script>
import GroupElement from "../../Layout/Group.vue";
import { Element, Javascript } from "@/mixins";
export default {
    name: "simpleSlider",
    inject: ["instanceStore"],
    presets: true,
    linkVideo: "https://youtu.be/4M7jiEZybJw",
    docs: "https://help.ecomposer.io/docs/elements/basic-elements/slider/",
    vendors: ["simple_slider_js", "simple_slider_css"],
    components: { GroupElement },
    mixins: [Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        },
        index: {
            type: Number,
            default: 0
        },
        deep: {
            type: Number,
            default: 0
        },
        breadcrumb: {
            type: String,
            default: ""
        }
    },
    data() {
        return {
            is: "simple_slider",
            name: "Simple Slider",
            itv: null,
            jsreactives: [
                "items",
                "imageHeight",
                "imageHeight__tablet",
                "imageHeight__mobile",
                "height",
                "height__tablet",
                "height__mobile",
                "slider_pagination_style",
                "show_progress_bar",
                "slider_speed",
                "drag_mode",
                "slider_pause",
            ]
        };
    },
    computed: {
        classFullHeight() {
            const attrs = {
                class: {
                    'ecom-ingrid-full-height': this.data.inGrid,
                },
            };
            return attrs;
        },
        section_id() {
            return this?.$parent.section_id || "";
        },
        slider() {
            return this.data;
        },
        storeScreens() {
            return this.$store.getters["builder/screens"];
        },
        items() {
            return this.data?.settings?.items ?? [];
        },
        slider_pagination_style() {
            return this.data?.settings?.pagination?.slider_pagination_style;
        },
        is_pagination_classic() {
            return (
                this.data?.settings?.pagination?.enable_pagination &&
                this.data?.settings?.pagination?.slider_pagination_style !== "progress"
            );
        },
        drag_mode() {
            return this.data?.settings?.drag_mode;
        },
        slider_pause() {
            return this.data?.settings?.slider_pause;
        },
        lazyload() {
            return this.data.settings?.lazyload ? this.data.settings?.lazyload === false : true;
        },
        settings() {
            return [
                {
                    group_title: this.$t("slides"),
                    params: [
                        {
                            name: "items",
                            type: "group",
                            options: {
                                add_text: this.$t("add_new_slide"),
                                is_clear_all: false
                            },
                            params: [
                                {
                                    type: "text",
                                    label: this.$t("heading"),
                                    name: "title"
                                },
                                {
                                    type: "picker",
                                    label: this.$t("choose_background_image"),
                                    name: "image",
                                    options: {
                                        responsive: true,
                                        type: "image",
                                        editAlt: true
                                    }
                                },
                                {
                                    type: "background",
                                    label: this.$t("background_color"),
                                    name: "background_color",
                                    options: {
                                        image: false,
                                        classicColor: true,
                                        responsive: false,
                                        oneline: true,
                                        visible: function (data) {
                                            return !data["image"];
                                        }
                                    }
                                },
                                {
                                    type: "popup",
                                    name: "img_position",
                                    label: this.$t("image_position"),
                                    options: {
                                        responsive: true,
                                        type: "dropdown",
                                        default: false,
                                        values: {
                                            "center-center": this.$t("center_center"),
                                            "center-left": this.$t("center_left"),
                                            "center-right": this.$t("center_right"),
                                            "top-center": this.$t("top_center"),
                                            "top-left": this.$t("top_left"),
                                            "top-right": this.$t("top_right"),
                                            "bottom-center": this.$t("bottom_center"),
                                            "bottom-left": this.$t("bottom_left"),
                                            "bottom-right": this.$t("bottom_right")
                                        },
                                        visible: function (data) {
                                            return data["image"];
                                        }
                                    },
                                    css: {
                                        isCss: false
                                    }
                                },
                                {
                                    type: "popup",
                                    name: "img_size",
                                    label: this.$t("image_size"),
                                    value: "cover",
                                    options: {
                                        responsive: true,
                                        type: "dropdown",
                                        default: false,
                                        preview: "title",
                                        values: {
                                            cover: this.$t("cover"),
                                            contain: this.$t("contain"),
                                            inherit: this.$t("inherit"),
                                            revert: this.$t("revert"),
                                            fill: this.$t("fill"),
                                            none: this.$t("none"),
                                            unset: this.$t("unset")
                                        },
                                        visible: function (data) {
                                            return data["image"];
                                        }
                                    },
                                    css: {
                                        isCss: false
                                    }
                                },
                                {
                                    type: "choose",
                                    label: this.$t("content_alignment"),
                                    name: "content_alignment",
                                    options: {
                                        oneline: true,
                                        responsive: true,
                                        type: "align-x-full",
                                        values: ["flex-start", "center", "flex-end"],
                                        visible: {
                                            condition: (data, datas, values = this.data.settings) => {
                                                return values.newChange;
                                            }
                                        }
                                    }
                                },
                                {
                                    type: "link",
                                    label: this.$t("image_link"),
                                    name: "link",
                                    options: {
                                        visible: {
                                            keep_data: false,
                                            condition: (data) => {
                                                return data["image"];
                                            }
                                        }
                                    }
                                },
                                {
                                    type: "toggle",
                                    name: "overlay",
                                    label: this.$t("enable_overlay"),
                                    options: {
                                        oneline: true,
                                        values: {
                                            on: {
                                                label: this.$t("yes"),
                                                value: true
                                            },
                                            off: {
                                                label: this.$t("no"),
                                                value: false
                                            }
                                        },
                                        visible: function (data) {
                                            return data["image"];
                                        }
                                    }
                                },
                                {
                                    type: "toggle",
                                    label: this.$t("disable_lazy_load"),
                                    name: "lazyload",
                                    value: false,
                                    options: {
                                        oneline: true,
                                        values: {
                                            on: {
                                                label: this.$t("yes"),
                                                value: true
                                            },
                                            off: {
                                                label: this.$t("no"),
                                                value: false
                                            }
                                        }
                                    },
                                    css: {
                                        isCss: false
                                    }
                                },
                                {
                                    type: "popup",
                                    label: this.$t("fetch_priority"),
                                    name: "fetch_priority",
                                    value: "",
                                    options: {
                                        type: "dropdown",
                                        default: false,
                                        preview: "title",
                                        values: {
                                            auto: this.$t("auto"),
                                            low: this.$t("low"),
                                            high: this.$t("high")
                                        }
                                    },
                                    css: {
                                        isCss: false
                                    }
                                }
                            ]
                        },
                        {
                            type: "line"
                        },
                        {
                            name: "contentWidth",
                            label: this.$t("content_width"),
                            type: "number",
                            options: {
                                units: {
                                    "%": {
                                        min: 10,
                                        max: 100,
                                        step: 1
                                    }
                                },
                                responsive: true
                            },
                            css: {
                                selector: " .ec-content-item",
                                properties: {
                                    "padding-left": "calc((100% - %value%) / 2)",
                                    "padding-right": "calc((100% - %value%) / 2)"
                                }
                            }
                        },
                        {
                            type: "popup",
                            name: "imageHeight",
                            label: this.$t("image_height"),
                            options: {
                                type: "dropdown",
                                default: false,
                                value: "adapt_to_first_image",
                                preview: "title",
                                responsive: true,
                                values: {
                                    adapt_to_first_image: this.$t("adapt_to_first_image"),
                                    adapt_to_image: this.$t("adapt_to_image"),
                                    fill_screen_height: this.$t("fill_screen_height"),
                                    fixed_height: this.$t("fixed_height")
                                },
                                visible: {
                                    keep_data: false,
                                    condition: () => {
                                        return !this.data.inGrid
                                    }
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t("height"),
                            name: "height",
                            placeholder: "300",
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 100,
                                        max: 1500
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return (
                                            data["imageHeight"] === "fixed_height" ||
                                            data["imageHeight__tablet"] === "fixed_height" ||
                                            data["imageHeight__mobile"] === "fixed_height"
                                        );
                                    }
                                }
                            },
                            css: {
                                selector: " .ec_splide .ec_splide__list"
                            }
                        },
                        {
                            type: "choose",
                            label: this.$t("align_content"),
                            name: "verticalAlign",
                            options: {
                                type: "align-y-full",
                                reset: false,
                                values: ["flex-start", "center", "flex-end"]
                            },
                            css: {
                                selector: " .ec-content-item",
                                properties: {
                                    "align-content": "",
                                    "align-items": ""
                                }
                            }
                        }
                    ]
                },
                {
                    group_alias: "splide",
                    options: {
                        group_title: this.$t("settings_slider")
                    }
                },
                {
                    group_alias: "splide:splideNav",
                    options: {
                        group_title: this.$t("navigation")
                    }
                },
                {
                    group_alias: "splide:splidePag",
                    options: {
                        group_title: this.$t("pagination")
                    }
                },
                {
                    group_title: this.$t("animation"),
                    params: [
                        {
                            type: "popup",
                            name: "content_animation",
                            label: this.$t("content_animation"),
                            options: {
                                type: "dropdown",
                                default: false,
                                value: "none",
                                preview: "title",
                                values: {
                                    none: this.$t("none"),
                                    Bottom2Top: this.$t("bottom_to_top"),
                                    Top2Bottom: this.$t("top_to_bottom"),
                                    Left2Right: this.$t("left_to_right"),
                                    Right2Left: this.$t("right_to_left")
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t("slider_content_transition"),
                            name: "sliderAnimationDuration",
                            value: 300,
                            options: {
                                min: 0,
                                max: 5000,
                                step: 100
                            },
                        }
                    ]
                }
            ];
        },
        styleColumn () {
            const numItems = this.slider.settings.slider_items;
            const width = 100/Number(numItems) + '%';
            const gap = this.slider.settings.slider_spacing || 0;
            const modify = ((gap * (numItems - 1)) / numItems) + 'px';
            return `calc(${width} - ${modify})`
        },
        styleColumnTablet () {
            const numItems = this.slider.settings.slider_items__tablet;
            if(numItems) {
                const width = 100/Number(numItems) + '%';
                const gap = this.slider.settings.slider_spacing__tablet || 0;
                const modify = ((gap * (numItems - 1)) / numItems) + 'px';
                return `calc(${width} - ${modify})`
            }
            return ''
        },
        styleColumnMobile () {
            const numItems = this.slider.settings.slider_items__mobile;
            if(numItems) {
                const width = 100/Number(numItems) + '%';
                const gap = this.slider.settings.slider_spacing__mobile || 0;
                const modify = ((gap * (numItems - 1)) / numItems) + 'px';
                return `calc(${width} - ${modify})`
            }
            return ''
        },
        splideListStyle() {
            return {
              '--ecom-column': this.styleColumn,
              '--ecom-column__tablet': this.styleColumnTablet ? this.styleColumnTablet : this.styleColumn,
              '--ecom-column__mobile': this.styleColumnMobile ? this.styleColumnMobile : this.styleColumn,
          }
        },
        sliderNav(){
            const nav = this.slider.settings.navigation;
          if(!nav.navigation_position__tablet) {
            nav.navigation_position__tablet = nav.navigation_position;
          }
          if(!nav.navigation_position__mobile) {
            nav.navigation_position__mobile = nav.navigation_position;
          }
          return {
              '--ecom-position': nav.navigation_position !== 'center' ? 'unset' : 'absolute',
              '--ecom-position__tablet': nav.navigation_position__tablet !== 'center' ? 'unset' : 'absolute',
              '--ecom-position__mobile': nav.navigation_position__mobile !== 'center' ? 'unset' : 'absolute',
          }
      },
        javascript() {
            return function () {
                const $el = this.$el;
                if (!$el) return;
                const $container = $el.querySelector(".ec_splide");
                if (!$container) return;
                const domOptions = JSON.parse($container.dataset.ecSplideOption || "{}");
                // Keep loop behavior on storefront only, same as Slider element.
                if (!this.isLive && domOptions.type === "loop") {
                    domOptions.type = "slide";
                }
                const progressCircle = $el.querySelector(".ecom-autoplay-progress svg");
                const progressContent = $el.querySelector(".ecom-autoplay-progress span");
                const elPagination = $el.querySelector(".ec_splide__pagination");
                const isPagination = elPagination.getAttribute("data-pagination") == "true";
                const wWidth = window.innerWidth,
                    imageHeight = this.settings.imageHeight,
                    imageHeight__mobile = this.settings.imageHeight__mobile,
                    imageHeight__tablet = this.settings.imageHeight__tablet,
                    animation = this.settings.content_animation,
                    slider_autoplay_speed = this.settings.slider_autoplay_speed;

                const optionSplide = {
                    pagination: isPagination
                };

                if (window.EcSplide) {
                    let slider = null;
                    let isInit = false;
                    function initSlider() {
                        if (isInit) return;
                        slider = new EcSplide($container, Object.assign(optionSplide, domOptions));
                        /* Animation */
                        if (animation) {
                            slider.on("visible", function (item) {
                                setTimeout(item.slide.classList.add("ec_not_animation"), 300);
                            });
                            slider.on("hidden", function (item) {
                                item.slide.classList.remove("ec_not_animation");
                            });
                        }

                        /* Pagination */
                        if (optionSplide.pagination && optionSplide.paginationType === "number") {
                            slider.on("pagination:mounted", function (data) {
                                data.list.classList.add("splide__pagination--custom");
                                data.items.forEach(function (item) {
                                    item.button.textContent = String(item.page + 1);
                                });
                            });
                        }
                        let bar = slider.root.querySelector(".ec_splide__progress__paginate");
                        slider.on("mounted move", function () {
                            let end = slider.Components.Controller.getEnd() + 1;
                            let rate = Math.min((slider.index + 1) / end, 1);
                            bar.style.width = String(100 * rate) + "%";
                        });

                        /* Fix lỗi lần đầu init gây lỗi khung hình -> delay 300ms để cho mọi thứ load xong trước */
                        slider.on("mounted", function () {
                            setTimeout(() => {
                                slider.refresh();
                                $container.classList.remove('ec-slider-hidden');
                                $container.classList.add('ec-slider-ready');
                            }, 300);
                        });

                        slider.on("ready", function () {
                            const resizeHeight = ["adapt_to_first_image"];
                            if (
                                resizeHeight.includes(imageHeight) ||
                                (wWidth < 768 && resizeHeight.includes(imageHeight__mobile)) ||
                                (wWidth < 1025 &&
                                    wWidth > 767 &&
                                    resizeHeight.includes(imageHeight__tablet))
                            ) {
                                adaptToFirstImg();
                            }
                        });

                        if (slider.options.autoplay && progressCircle && progressContent) {
                            updateProgressBar(slider, 1);
                        }
                        slider.on("autoplay:play", () => {
                            if (progressCircle && progressContent) {
                                progressCircle.style.setProperty("--progress", 1);
                                progressContent.textContent = `${Math.ceil(
                                    slider_autoplay_speed / 1000
                                )}s`;
                            }
                        });
                        function updateProgressBar(slider, progress = 0) {
                            if (progressCircle && progressContent) {
                                progressCircle.style.setProperty("--progress", progress);
                                const autoplay = slider.Components.Autoplay;
                                if (autoplay) {
                                    const timeLeft = slider.options.interval * (1 - progress);
                                    progressContent.textContent = `${Math.ceil(timeLeft / 1000)}s`;
                                }
                            }
                        }

                        slider.on("autoplay:playing", (rate) => {
                            updateProgressBar(slider, rate);
                        });

                        slider.on("move", () => {
                            updateProgressBar(slider, 0);
                            // if(slider.options.autoplay){
                            //     slider.Components.Autoplay.pause();
                            //     slider.Components.Autoplay.play();
                            // }
                        });

                        slider.mount();
                        isInit = true;
                        $container.ec_splide = slider;
                        /* Auto height by Image */
                        const resizeHeight = ["adapt_to_image"];
                        if (
                            resizeHeight.includes(imageHeight) ||
                            (wWidth < 768 && resizeHeight.includes(imageHeight__mobile)) ||
                            (wWidth < 1025 &&
                                wWidth > 767 &&
                                resizeHeight.includes(imageHeight__tablet))
                        ) {
                            adaptToImg();
                            slider.on("move resize", adaptToImg);
                        }
                    }

                    initSlider();

                    function adaptToImg(newIndex) {
                        if (slider.Components && slider.Components.Slides) {
                            let slide = slider.Components.Slides.getAt(
                                typeof newIndex == "number" ? newIndex : slider.index
                            ).slide;
                            slide.parentElement.parentElement.style.height =
                                slide.querySelector("img").offsetHeight + "px";
                        }
                    }
                    function adaptToFirstImg() {
                        const image = $container.querySelector(
                            ".ec_splide__slide.is-active.is-visible img"
                        );
                        if (image) {
                            let imgHeight;
                            if (image.complete) {
                                imgHeight = image.offsetHeight;
                                slider.options = {
                                    height: imgHeight + "px"
                                };
                            } else {
                                image.addEventListener("load", function () {
                                    imgHeight = this.offsetHeight;
                                    slider.options = {
                                        height: imgHeight + "px"
                                    };
                                });
                            }
                        }
                    }

                    /*
                    function recalculateTranslateX() {
                        const track = $el.querySelector(".ec_splide__list");
                        if (track) {
                            requestAnimationFrame(() => {
                                slider.Components.Move.translate(-track.offsetWidth * slider.index);
                            });
                        }
                    }
                    const resizeObserver = new ResizeObserver(() => {
                        recalculateTranslateX();
                    });

                    resizeObserver.observe($container.querySelector(".ec_splide__list"));
                    */
                }
            };
        },
        css() {
            return `
                @keyframes ec-skeleton-loading {
                    0% {
