<template>
    <div :class="wrapperClass">
        <s-button
            :variant="variant"
            :outline="outline"
            :disabled="disabled"
            :icon="loading ? 'loading' : icon"
            :tone="tone"
            :accessibilityLabel="accessibilityLabel"
            :class="buttonClass"
            @click="!disabled && $emit('update:clicked', field.name)"
        >
            <span v-if="loading" class="flex items-center gap-1.5">
                <svg class="animate-spin h-3 w-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
                </svg>
                {{ text }}
            </span>
            <template v-else>{{ text }}</template>
        </s-button>
    </div>
</template>

<script lang="ts">
import { defaultProps } from '../../utils';

export default {
    name: 'Custom_buttonField',
    props: {
        ...defaultProps,
        fieldValues: {
            type: Object,
            default() { return {}; }
        }
    },
    emits: ['update:clicked'],
    computed: {
        opts() {
            return this.field?.options || {};
        },
        text() {
            const t = this.opts.text;
            if (typeof t === 'function') return t(this.fieldValues) ?? 'Button';
            return t ?? 'Button';
        },
        variant() {
            return this.opts.variant || 'primary';
        },
        outline() {
            return !!this.opts.outline;
        },
        disabled() {
            const d = this.opts.disabled;
            if (typeof d === 'function') return !!d(this.fieldValues);
            return !!d;
        },
        loading() {
            const l = this.opts.loading;
            if (typeof l === 'function') return !!l(this.fieldValues);
            return !!l;
        },
        icon() {
            return this.opts.icon || undefined;
        },
        tone() {
            return this.opts.tone || undefined;
        },
        accessibilityLabel() {
            return this.opts.accessibilityLabel || undefined;
        },
        buttonClass() {
            const extra = this.opts.class || '';
            return ['!text-xs px-3 w-full', extra].filter(Boolean).join(' ');
        },
        wrapperClass() {
            const w = this.opts.wrapperClass;
            if (typeof w === 'function') return w(this.fieldValues) || 'py-1 flex justify-start w-full';
            return w || 'py-1 flex justify-start w-full';
        }
    }
};
</script>
