<template>
  <div class="ecom-elements ecom-base-element ecom-elements-slider" :class="{'ecom-ingrid-full-height': data.inGrid}">
      <GroupElement v-if="true" :data="data" :deep="deep" :index="index" :section_id="section_id" :breadcrumb="`${breadcrumb}/${data?.id}`" :inGrid="data.inGrid">
          <template #items="payload">
              <div class="ecom-slider--container ecom-swiper-a11y-host">
                  <button
                      v-if="$helpers.hasAutoplayToggle(data.settings)"
                      type="button"
                      class="ecom-swiper-autoplay-toggle"
                      :data-position="data.settings?.a11y_autoplay_control_position || 'bottom-right'"
                      data-state="playing"
                      data-label-pause="Pause automatic slide show"
                      data-label-play="Start automatic slide show"
                      aria-label="Pause automatic slide show"
                  >
                      <svg class="ecom-swiper-autoplay-toggle__pause" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5h3v14H8zM13 5h3v14h-3z"/></svg>
                      <svg class="ecom-swiper-autoplay-toggle__play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5v14l11-7z"/></svg>
                  </button>
                  <div
                      class="ecom-element ecom-slider slider__body ecom-swiper-container"
                      :class="data.settings?.isCustomHeight ? '' : 'ecom-slider-not-custom-height'"
                  >
                      <div class="ecom-swiper-wrapper">
                          <div
                              v-for="(item, i) in payload.items"
                              :key="item.id"
                              class="ecom-swiper-slide"
                              :style="content_alignment(item)"
                          >
                              <div class="ecom-content-item" :style="backgroundHighlight(item)">
                                  <div
                                      v-if="item.image"
                                      class="ecom-slider__image--wrapper"
                                      :class="{'ecom-slider__has-link' : item?.link?.href && item?.link?.href != ''}"
                                      :data-id="item.id"
                                      @click="editSlider(i)"
                                  >
                                      <picture
                                          class="ecom-image-background"
                                          v-html="$helpers.renImageResponsive(item.image, storeScreens, data.settings?.disable_lazy === false, img_style(item), i)"
                                      />
                                      <div v-if="item.overlay" class="ecom-overlay"><span>overlay</span></div>
                                  </div>
                                  <div
                                      class="ecom-content-item__container"
                                      :class="['ecom-transition-' + slider?.settings?.content_animation]"
                                  >
                                      <Blocks :data="item.blocks" :deep="deep" :index="i" :section_id="section_id" :breadcrumb="`${breadcrumb}/${data?.id}`" :isFlexContainer="true"/>
                                  </div>
                                    <a
                                      v-if="exporting && item?.link?.href && item?.link?.href != ''"
                                      :href="item.link.href"
                                      v-bind="item.link"
                                      class="ecom-slider__image--link"
                                    />
                              </div>
                          </div>
                      </div>
                  </div>
                  <div
                      v-if="isNavigation && isCombined() == 'combine'"
                      class="ecom-swiper-navigation"
                      :data-navigator-type="isCombined() == 'combine'"
                  >
                      <div class="ecom-flex-center">
                          <button
                              type="button"
                              v-show="isArrow()"
                              class="ecom-swiper-button ecom-swiper-button-prev"
                              v-html="slider.settings.slider_prev_icon"
                              :data-ecnav-id="data?.id"
                          />
                          <div v-show="isPagination()" class="ecom-swiper-pagination" />
                          <button
                              type="button"
                              v-show="isArrow()"
                              class="ecom-swiper-button ecom-swiper-button-next"
                              :data-ecnav-id="data?.id"
                              v-html="slider.settings.slider_next_icon"
                          />
                      </div>
                  </div>
                  <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isArrow()" class="ecom-swiper-navigation-position" :data-position="data.settings.navigation_position">
                      <button
                          type="button"
                          class="ecom-swiper-button ecom-swiper-button-prev"
                          :style="sliderNav"
                           :data-ecnav-id="data?.id"
                          v-html="slider.settings.slider_prev_icon"
                      />
                      <button
                          type="button"
                          class="ecom-swiper-button ecom-swiper-button-next"
                          :style="sliderNav"
                           :data-ecnav-id="data?.id"
                          v-html="slider.settings.slider_next_icon"
                      />
                  </div>
                  <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isPagination()"
                    :data-position="data.settings?.pagination_position"
                    :data-position-tablet="data.settings?.pagination_position__tablet"
                    :data-position-mobile="data.settings?.pagination_position__mobile"
                    :data-ecnav-id="data?.id"
                    class="ecom-swiper-pagination-position ecom-swiper-pagination"
                    />
                  <div v-if="data.settings?.autoplay_progress"
                    class="ecom-autoplay-progress">
                    <svg viewBox="0 0 48 48" stroke="currentColor">
                      <circle cx="24" cy="24" r="20"></circle>
                    </svg>
                    <span></span>
                  </div>
              </div>
          </template>
      </GroupElement>
  </div>
</template>

<script>
import GroupElement from '../../Layout/Group.vue';
import { Element, Javascript } from '@/mixins';
export default {
  name: 'slider',
  inject: ['instanceStore'],
  presets:true,
  linkVideo: 'https://youtu.be/4M7jiEZybJw',
  docs: 'https://help.ecomposer.io/docs/elements/basic-elements/slider/',
  vendors: ['slider_js', 'slider_css'],
  components: { GroupElement },
  mixins: [Element, Javascript],
  props: {
      data: {
          type: Object,
          default() {
              return {};
          }
      },
      index: {
          type: Number,
          default: 0
      },
      deep: {
          type: Number,
          default: 0
      },
      'breadcrumb': {
          type: String,
          default: ''
      }
  },
  mounted() {
    //this.stacks[this.data.id] = this;
    this.instanceStore.register(this.data.id, this);
  },
  beforeUnmount() {
    this.instanceStore.unregister(this.data.id);
  },
  data() {
      return {
          is: 'slider',
          name: 'Slider',
          watchHeight: {},
          itv: null,
          // jsreactives:['slider_navigation_layout', 'slider_center', 'slider_center__tablet', 'slider_center__mobile','items', 'autoplay_progress', 'slider_style', 'slider_speed', 'slider_speed__tablet', 'slider_speed__mobile']
      };
  },
  computed: {
      section_id() {
        return this?.$parent.section_id || '';
      },
      slider() {
          return this.data;
      },
      storeScreens() {
        return this.$store.getters['builder/screens'];
      },
      items() {
        return this.data?.settings?.items ?? [];
      },
      isNavigation() {
        return this.slider.settings?.slider_navigation_layout;
      },
      optionSwiper() {
        return this.$helpers.optionSwiper(this.slider.settings);
      },
      paginationImages() {
        return this.items.map(item => item.slider_pagination_image);
      },
      sliderNav(){
        if(!this.slider.settings.navigation_position__tablet) {
          this.slider.settings.navigation_position__tablet = this.slider.settings.navigation_position;
        }
        if(!this.slider.settings.navigation_position__mobile) {
          this.slider.settings.navigation_position__mobile = this.slider.settings.navigation_position;
        }

        return {
            '--ecom-position': this.slider.settings.navigation_position !== 'center' ? 'unset' : 'absolute',
            '--ecom-position__tablet': this.slider.settings.navigation_position__tablet !== 'center' ? 'unset' : 'absolute',
            '--ecom-position__mobile': this.slider.settings.navigation_position__mobile !== 'center' ? 'unset' : 'absolute',
        }
      },

      settings() {
          return [
              {
                  group_title: this.$t('slides'),
                  params: [
                      {
                          name: 'items',
                          type: 'group',
                          options: {
                              add_text: this.$t('add_new_slide'),
                              is_clear_all:false
                          },
                          params: [
                              {
                                  type: 'text',
                                  label: this.$t('heading'),
                                  name: 'title'
                              },
                              {
                                  type: 'picker',
                                  label: this.$t('choose_background_image'),
                                  name: 'image',
                                  options: {
                                      responsive: true,
                                      type: 'image',
                                      editAlt: true
                                  }
                              },
                              {
                                  type: 'background',
                                  label: this.$t('background_color'),
                                  name: 'background_color',
                                  options: {
                                      image: false,
                                      classicColor: true,
                                      responsive: false,
                                      oneline: true,
                                      visible: function(data) {
                                        return !data['image']
                                      }
                                  }
                              },
                              {
                                  type: 'popup',
                                  name: 'img_position',
                                  label: this.$t('image_position'),
                                  options: {
                                      responsive: true,
                                      type: 'dropdown',
                                      default:false,
                                      values: {
                                          'center-center': this.$t('center_center'),
                                          'center-left': this.$t('center_left'),
                                          'center-right': this.$t('center_right'),
                                          'top-center': this.$t('top_center'),
                                          'top-left': this.$t('top_left'),
                                          'top-right': this.$t('top_right'),
                                          'bottom-center': this.$t('bottom_center'),
                                          'bottom-left': this.$t('bottom_left'),
                                          'bottom-right': this.$t('bottom_right'),
                                      },
                                      visible: function(data) {
                                        return data['image']
                                      }
                                  },
                                  css: {
                                      isCss: false
                                  }
                              },
                              {
                                  type: 'popup',
                                  name: 'img_size',
                                  label: this.$t('image_size'),
                                  value: 'cover',
                                  options: {
                                      responsive: true,
                                      type: 'dropdown',
                                      default:false,
                                      preview: "title",
                                      values: {
                                          'cover': this.$t('cover'),
                                          'contain': this.$t('contain'),
                                          'inherit': this.$t('inherit'),
                                          'revert': this.$t('revert'),
                                          'fill': this.$t('fill'),
                                          'none': this.$t('none'),
                                          'unset': this.$t('unset'),
                                      },
                                      visible: function(data) {
                                        return data['image']
                                      }
                                  },
                                  css: {
                                      isCss: false
                                  }
                              },
                              {
                                type: "choose",
                                label: this.$t("content_alignment"),
                                name: "content_alignment",
                                options: {
                                    oneline: true,
                                    responsive: true,
                                    type: "align-x-full",
                                    values: ["flex-start", "center", "flex-end"],
                                    visible: {
                                        keep_data: false,
                                        condition: (data, datas, values = this.data.settings) => {
                                            return values["newChange"] === true
                                      }
                                    }
                                }
                              },
                              {
                                  type: 'picker',
                                  label: this.$t('pagination_image'),
                                  name: 'slider_pagination_image',
                                  options: {
                                      type: 'image',
                                      output: 'value',
                                      visible: {
                                          keep_data: false,
                                          condition: (data, datas, values = this.data.settings) => {
                                              return (
                                                      values["slider_navigation_layout"] === "classic_full" ||
                                                      values["slider_navigation_layout"] === "neo_full" ||
                                                      values["slider_navigation_layout"] === "pagination"
                                                  ) && values['slider_pagination_style_have_image'] === 'images';
                                          }
                                      }
                                  }
                              },
                              {
                                  type: 'link',
                                  label: this.$t('image_link'),
                                  name: 'link',
                                  options: {
                                    visible: {
                                      keep_data: false,
                                      condition: (data) => {
                                        return data['image']
                                      }
                                    }
                                  }
                              },
                              {
                                  type: 'toggle',
                                  name: 'overlay',
                                  label: this.$t('enable_overlay'),
                                  options: {
                                      oneline: true,
                                      values: {
                                          on: {
                                              label: this.$t('yes'),
                                              value: true
                                          },
                                          off: {
                                              label: this.$t('no'),
                                              value: false
                                          }
                                      },
                                      visible: function(data) {
                                        return data['image']
                                      }
                                  }
                              },
                          ]
                      },
                      {
                          type: 'line'
                      },
                      {
                          name: 'contentWidth',
                          label: this.$t('content_width'),
                          type: 'number',
                          options: {
                              units: {
                                  '%': {
                                      min: 10,
                                      max: 100,
                                      step: 1
                                  }
                              },
                              responsive: true
                          },
                          css: {
                              selector: ' .ecom-slider--container',
                              properties: {
                                  'padding-left': 'calc((100% - %value%) / 2)',
                                  'padding-right': 'calc((100% - %value%) / 2)',
                              }
                          }
                      },
                      {
                          type: 'toggle',
                          name: 'isCustomHeight',
                          label: this.$t('custom_height'),
                          options: {
                              oneline: true,
                              values: {
                                  on: {
                                      label: this.$t('yes'),
                                      value: true
                                  },
                                  off: {
                                      label: this.$t('no'),
                                      value: false
                                  }
                              },
                              // visible: {
                              //   keep_data: false,
                              //   condition: () => {
                              //     return !this.data.inGrid
                              //   }
                              // }
                          }
                      },
                      {
                          type: 'number',
                          label: this.$t('height'),
                          name: 'height',
                          placeholder: '300',
                          options: {
                              responsive:true,
                              units: {
                                  px: {
                                      min: 100,
                                      max: 1500
                                  }
                              },
                              visible: {
                                  keep_data: false,
                                  condition: (data) => {
                                      return data['isCustomHeight'];
                                  }
                              }
                          },
                          css: {
                              selector: ' .ecom-slider--container .ecom-slider'
                          }
                      },
                      {
                          type: 'choose',
                          label: this.$t('vertical_align'),
                          name: 'verticalAlign',
                          activeQuickToolBar: true,
                          options: {
                              type: 'align-y-full',
                              reset: false,
                              values: [
                                'flex-start',
                                'center',
                                'flex-end'
                              ],
                              visible: (data) => {
                                  return data['isCustomHeight'];
                              }
                          },
                          css: {
                              selector: ' .ecom-content-item',
                              properties: {
                                  'align-content': '',
                                  'align-items': '',
                                  'display': 'return value ? "flex" : ""'
                              }
                          },
                      }
                  ]
              },
              {
                  group_alias: 'swiper',
                  options: {
                    group_title: this.$t('settings_slider'),
                  },
                  modify: {
                      params: [
                          {
                            position: 0,
                            fields: [
                              {
                                type: 'popup',
                                name: 'slider_style',
                                label: this.$t('slider_style'),
                                value: 'horizontal',
                                options: {
                                  type: 'dropdown',
                                  default: false,
                                  preview: 'title',
                                  values: {
                                    horizontal: this.$t('horizontal'),
                                    vertical: this.$t('vertical'),
                                  }
                                }
                              },
                              {
                                type: 'paragraph',
                                name: 'para_vertical',
                                options: {
                                  warnings: {
                                    content: this.$t('you_should_enable_custom_height_option')
                                  },
                                  visible: function(data) {
                                    return data && data['slider_style'] === 'vertical'
                                  }
                                }
                              },
                              {
                                type: 'popup',
                                name: 'slider_effect',
                                label: this.$t('transition_effect'),
                                options: {
                                  type: 'dropdown',
                                  preview: 'title',
                                  default: false,
                                  values: {
                                    fade: this.$t('fade'),
                                    slide: this.$t('slide'),
                                    // cube: this.$t('cube'),
                                    coverflow: this.$t('coverflow'),
                                    flip: this.$t('flip'),
                                    cards: this.$t('cards'),
                                    creative: this.$t('creative'),
                                    creative2: this.$t('creative_style_2'),
                                    creative3: this.$t('creative_style_3'),
                                    creative4: this.$t('creative_style_4'),
                                    creative5: this.$t('creative_style_5'),
                                    creative6: this.$t('creative_style_6'),
                                  }
                                }
                              },

                              {
                                type: 'toggle',
                                name: 'disable_touch_move',
                                label: this.$t('disable_touch_move_slide'),
                                value: true,
                                options: {
                                  values: {
                                    on: {
                                      label: this.$t('yes'),
                                      value: false
                                    },
                                    off: {
                                      label: this.$t('no'),
                                      value: true
                                    }
                                  }
                                }
                              },
                              {
                                type: 'toggle',
                                name: 'disable_lazy',
                                label: this.$t('disable_lazyload'),
                                value: false,
                                options: {
                                  values: {
                                    on: {
                                      label: this.$t('yes'),
                                      value: true
                                    },
                                    off: {
                                      label: this.$t('no'),
                                      value: false
                                    }
                                  }
                                }
                              }
                            ]
                          },
                          {
                            position: 10,
                            fields: [
                              {
                                name: 'autoplay_progress',
                                label: this.$t('autoplay_progress'),
                                type: 'toggle',
                                options: {
                                  visible: {
                                    keep_data: false,
                                    condition: (data) => data && data['slider_autoplay'] === true
                                  },
                                  online: true,
                                  values: {
                                    on: {
                                      label: this.$t('yes'),
                                      value: true
                                    },
                                    off: {
                                      label: this.$t('no'),
                                      value: false
                                    }
                                  }
                                }
                              },
                            ]
                          },
                          {
                              position: 20,
                              fields: [
                                  {
                                      type: 'toggle',
                                      name: 'paginitionAnimation',
                                      label: this.$t('pagination_animation'),
                                      options: {
                                          oneline: true,
                                          values: {
                                              on: {
                                                  label: this.$t('yes'),
                                                  value: true
                                              },
                                              off: {
                                                  label: this.$t('no'),
                                                  value: false
                                              }
                                          }
                                      },
                                      css: {
                                          selector: ' .ecom-swiper-pagination-bullet.ecom-swiper-pagination-bullet-active:after',
                                          properties: {
                                              'height': 'return value ? "100%" : "0"'
                                          }
                                      },
                                  },
                              ]
                          },
                          {
                            position: 32,
                            fields: [
                              {
                                type: "popup",
                                label: this.$t('style'),
                                name: "slider_pagination_style_have_image",
                                options: {
                                    type: "dropdown",
                                    preview: "title",
                                    values: {
                                        classic: this.$t('classic'),
                                        images: this.$t('images'),
                                        progress: this.$t('progress'),
                                    },
                                    default: false,
                                    visible: (data) =>
                                        (data.slider_navigation_layout === 'neo_full' ||
                                        data.slider_navigation_layout === 'classic_full' ||
                                        data.slider_navigation_layout === 'pagination')
                                },
                                css: false
                              },
                            ]
                          }
                      ],
                      remove: {
                        name: ['slider_pagination_style']
                      }
                  }
              },
              {
                  group_title: this.$t('animation'),
                  params: [
                      {
                          type: 'popup',
                          name: 'content_animation',
                          label: this.$t('content_animation'),
                          options: {
                              type: 'dropdown',
                              default: false,
                              value: 'none',
                              preview: 'title',
                              values: {
                                  none: this.$t('none'),
                                  Bottom2Top: this.$t('bottom_to_top'),
                                  Top2Bottom: this.$t('top_to_bottom'),
                                  Left2Right: this.$t('left_to_right'),
                                  Right2Left: this.$t('right_to_left'),
                              }
                          }
                      },
                  ]
              }
          ];
      },

      javascript() {

          return function () {
                // Nút pause autoplay (WCAG 2.2.2). Đọc $container.swiper lúc click
                // nên không phụ thuộc thứ tự init của slider bên dưới.
                var $ecomAptg = this.$el && this.$el.querySelector('.ecom-swiper-autoplay-toggle');
                if ($ecomAptg && !$ecomAptg.getAttribute('data-ecom-bound')) {
                    $ecomAptg.setAttribute('data-ecom-bound', '1');
                    var $ecomAptgBox = this.$el.querySelector('.ecom-swiper-container');
                    $ecomAptg.addEventListener('click', function () {
                        var sw = $ecomAptgBox && $ecomAptgBox.swiper;
                        if (!sw || !sw.autoplay) return;
                        if (sw.autoplay.running) {
                            // stop() chứ không pause(): pause() sẽ bị resume() của
                            // pauseOnMouseEnter bật lại, người dùng bấm dừng phải dừng hẳn.
                            sw.autoplay.stop();
                            $ecomAptg.setAttribute('data-state', 'paused');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-play'));
                        } else {
                            sw.autoplay.start();
                            $ecomAptg.setAttribute('data-state', 'playing');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-pause'));
                        }
                    });
                }
              const  $el = this.$el;
              if(!$el) return;
              const progressCircle = $el.querySelector(".ecom-autoplay-progress svg"),
                progressContent = $el.querySelector(".ecom-autoplay-progress span"),
                disable_lazy = this.settings.disable_lazy ?? false,
                settings = window.EComposer && typeof window.EComposer.normalizeSwiperSettings === 'function'
                  ? window.EComposer.normalizeSwiperSettings(this.settings)
                  : this.settings,
                slider_loop = settings.slider_loop,
                slider_center = settings.slider_center,
                slider_center__tablet = settings.slider_center__tablet ?? settings.slider_center,
                slider_center__mobile = settings.slider_center__mobile ?? settings.slider_center__tablet ?? settings.slider_center,
                slider_group = settings.slider_group,
                slider_items = settings.slider_items,
                slider_group__tablet = settings.slider_group__tablet ?? settings.slider_group,
                slider_items__tablet = settings.slider_items__tablet ?? settings.slider_items,
                slider_group__mobile = settings.slider_group__mobile ?? settings.slider_group__tablet ?? settings.slider_group,
                slider_items__mobile = settings.slider_items__mobile ?? settings.slider_items__tablet ?? settings.slider_items,
                slider_speed = settings.slider_speed,
                slider_speed__tablet = settings.slider_speed__tablet ?? settings.slider_speed,
                slider_speed__mobile = settings.slider_speed__mobile ?? settings.slider_speed;
              const buildSwiperConfig = function(settings) {
                if(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function') {
                  return window.EComposer.buildSwiperConfig(settings);
                }
                return null;
              }
              const handleResponsive = function(settings, optionSwiper = {}, option='') {
                if(option == 'loop') {
                  if(!settings.items) {
                    return optionSwiper;
                  }
                  // Swiper v11 đã fix bug loop + autoplay, chỉ cần disable loop khi số items không đủ
                  if(window.innerWidth > 1024 && (settings.items.length < slider_group + slider_items)) {
                    optionSwiper.loop = false;
                  }
                  else if((window.innerWidth <= 1024 && window.innerWidth > 768) && (settings.items.length < slider_group__tablet + slider_items__tablet)) {
                    optionSwiper.loop = false;
                  }
                  else if(settings.items.length < slider_group__mobile + slider_items__mobile) {
                    optionSwiper.loop = false;
                  }
                  return optionSwiper;
                }
                else {
                  if(window.innerWidth <= 1024 && window.innerWidth > 768 && settings[1]) {
                      optionSwiper[`${option}`] = settings[1];
                  }
                  else if (window.innerWidth < 768 && settings[2]) {
                      optionSwiper[`${option}`] = settings[2];
                  }
