  watch: {
      'data.settings.items.tabOpened': function(index){
          if(index >= 0)
          {
              this?.$el && this?.$el?.querySelector('.ecom-swiper-container')?.swiper?.slideTo(index);
          }
      },
      optionSwiper: {
          deep: true,
          handler: function () {
              this.slider.refresh = this.$helpers.randid();
          }
      },
      // fix bug load when change screen
      // screen: {
      //   handler: function () {
      //         setTimeout(() => {
      //           this.slider.refresh = this.$helpers.randid();
      //         }, 100);
      //     }
      // },
      items: {
          deep: true,
          handler: function () {
              setTimeout(() => {
                  this?.$el && this?.$el?.querySelector('.ecom-swiper-container')?.swiper?.update();
              }, 100);
          }
      },
      storeScreens: {
          deep: true,
          immediate: true,
          handler(val) {
            if(this.itv) clearTimeout(this.itv);
            this.itv = setTimeout(() => {
              let screens = Object.keys(val);
              screens.forEach(screen => {
                  if(!(screen in this.watchHeight)) {
                      let watch = this.$watch('data.settings.height' +(screen === 'desktop' ? '' : ('__' + screen)) , function(){
                          let itv = null;
                          clearTimeout(itv);

                          itv = setTimeout(() => {
                            this?.$el?.querySelector('.ecom-swiper-container')?.swiper?.update();
                          }, 100)

                      });
                      this.watchHeight[screen] = watch
                  }
              });
            }, 50);
          }
      },
      paginationImages: {
          deep: true,
          handler() {
              this.slider.refresh = this.$helpers.randid();
          }
      },
  },
  unmounted () {
      for(let k in this.watchHeight) {
          this.watchHeight[k]();
      }
  },
  methods: {
      exportedSettings() {
          const settings = JSON.parse(JSON.stringify(this.data.settings));
          if (settings.items) {
              settings.items = settings.items.map(item => {
                  return {
                      id: item.id,
                      slider_pagination_image: item.slider_pagination_image || null
                  };
              });
          }
          return settings;
      },
    quickToolBar() {
      return ['verticalAlign', 'items', 'slider_effect'];
    },
    backgroundHighlight(item){
        if(!item.background_color) return;
        let background = JSON.parse(JSON.stringify(item.background_color));
        if(background.classic) {
          if(typeof background.classic['background-color'] === 'object') {
            return `background-color: var(--ecom-global-colors-${background.classic['background-color']['global-colors']})`;
          }
          return background.classic;
        }
        if(background.gradient){
            let background_gradient = JSON.parse(JSON.stringify(background.gradient)) || "";
            let background_linear = background_gradient.positions||[];
            let background_css = '';
            let color = '';
            if(background_linear.length > 1) {
              background_linear.forEach(function(value,index){
                  if(index<background_linear.length-1){
                      if(typeof value.color === 'object') {
                        color += `var(--ecom-global-colors-${value.color['global-colors']}) ${value.index}%,`;
                      }
                      else {
                        color += `${value.color} ${value.index}%,`;
                      }
                  }
                  else{
                      if(typeof value.color === 'object') {
                        color += `var(--ecom-global-colors-${value.color['global-colors']}) ${value.index}%`;
                      }
                      else {
                        color += `${value.color} ${value.index}%`;
                      }
                  }
              });
            }
            else if(background_linear.length) {
              return `background-color: ${background_linear[0].color}`;
            }

            let background_type = background_gradient.type || 'linear';
            let background_position = background_gradient.position || 'center center';
            let angle = background_gradient.angle || '180';
            if(background_type === 'linear'){
                background_css = `background-image: linear-gradient(${angle}deg, ${color});`;
                return background_css;
            }
            else if(background_type === 'radial'){
                background_css = `background-image: radial-gradient(at ${background_position}, ${color});`;
                return background_css;
            }
        }
        return '';
      },
      isCombined() {
          let navigator = this.data?.settings?.slider_navigation_layout;
          return navigator === 'neo_full' ? 'combine' : 'classic';
      },
      isArrow() {
          return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                  this.data.settings?.slider_navigation_layout === 'navigation' ||
                  this.data.settings?.slider_navigation_layout === 'classic_full'
      },
      isPagination() {
          return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                  this.data.settings?.slider_navigation_layout === 'classic_full' ||
                  this.data.settings?.slider_navigation_layout === 'pagination';
      },
      editSlider (i) {
              this.$store.commit('builder/setActiveElement', this);
              this.$store.commit('builder/setEditingElement', this);
              if( !'tabOpened' in this.data.settings.items)
              {
                  Object.defineProperty( this.data.settings.items, "tabOpened", { enumerable: false, writable: true } );

              }
              this.data.settings.items.tabOpened = i;

      },
      content_alignment(item){
        let style = '';
        if(item?.content_alignment) {
            style += '--ec-align-ct: ' + item?.content_alignment + ';';
        }
        if(item?.content_alignment__tablet) {
            style += '--ec-align-ct-tb: ' + item?.content_alignment__tablet + ';';
        }
        if(item?.content_alignment__mobile) {
            style += '--ec-align-ct-mb: ' + item?.content_alignment__mobile + ';';
        }
        return style;
      },
      img_style(item) {
        const style = {};
        if(item?.img_position) {
          style['--ecom-object-position'] = item?.img_position;
          style['--ecom-object-position-tablet'] = item?.img_position;
          style['--ecom-object-position-mobile'] = item?.img_position;
        }
        if(item?.img_position__tablet) {
          style['--ecom-object-position-tablet'] = item?.img_position__tablet;
        }
        if(item?.img_position__mobile) {
          style['--ecom-object-position-mobile'] = item?.img_position__mobile;
        }

        if(item?.img_size) {
          style['--ecom-object-fit'] = item?.img_size;
          style['--ecom-object-fit-tablet'] = item?.img_size;
          style['--ecom-object-fit-mobile'] = item?.img_size;
        }
        if(item?.img_size__tablet) {
          style['--ecom-object-fit-tablet'] = item?.img_size__tablet;
        }
        if(item?.img_size__mobile) {
          style['--ecom-object-fit-mobile'] = item?.img_size__mobile;
        }
        // focal point
        let { image = {} } = item;
        if (Object.keys(image).length === 0) {
            return null;
        }
        if(image?.left && image?.top) {
          style['--ecom-object-position'] = `${image?.left}% ${image?.top}%`;
        }
        if(image?.left_tablet && image?.top_tablet) {
          style['--ecom-object-position-tablet'] = `${image?.left_tablet}% ${image?.top_tablet}%`;
        }
        if(image?.left_mobile && image?.top_mobile) {
          style['--ecom-object-position-mobile'] = `${image?.left_mobile}% ${image?.top_mobile}%`;
        }
          // end focal point
        return style;
      },

      style() {

          let checkNavPagination = [];
          if(this.isArrow()){
              checkNavPagination.push({
                  title: this.$t('navigation'),
                  type:'swiper:nav'
              });
          }
          if(this.isPagination()){
            checkNavPagination.push({
                title: this.$t('pagination'),
                type:'swiper:pagination'
            });
          }
          const style = [
              {
                  group_alias: 'box:active',
                  options: {
                      group_title: this.$t('slide'),
                      selector: ' .ecom-swiper-slide'
                  },
                  modify: {
                      params: [
                          {
                              position: 50,
                              fields: [
                                { type: 'line' },
                                {
                                  alias: 'spacing',
                                  optipn:{
                                    label: this.$t('spacing'),
                                  }
                                }
                              ]
                          },
                          {
                              position: 0,
                              fields: [
                                  {
                                      type: "popup",
                                      label: this.$t('slider_animation'),
                                      name: "sliderAnimation",
                                      selector: ' .ecom-swiper-slide',
                                      options: {
                                          preview: "title",
                                          type: "dropdown",
                                          values: {
                                              'grow': this.$t('grow'),
                                              'shrink': this.$t('shrink'),
                                              'pulse': this.$t('pulse'),
                                              'pulse-grow': this.$t('pulse_grow'),
                                              'pulse-shrink': this.$t('pulse_shrink'),
                                              'push': this.$t('push'),
                                              'pop': this.$t('pop'),
                                              'bounce-in': this.$t('bounce_in'),
