              }
          }
          let autoplay_progress = {
            group_title: this.$t('autoplay_progress'),
            params: [
              {
                type: 'number',
                name: 'size_progress',
                label: this.$t('size'),
                options: {
                  units: {
                      px: {
                          min: 0,
                          max: 200
                      }
                  },
                },
                css: {
                  properties: {
                    width: '%value%',
                    height: '%value%'
                  },
                  selector: 'root .ecom-autoplay-progress'
                }
              },
              {
                name: 'text_progress_color',
                label: this.$t('text_color'),
                type: 'color',
                options: {
                    oneline: true,
                    global: {
                        type: 'colors'
                    }
                },
                css: {
                    properties: {
                        'color': ''
                    },
                    selector: 'root  .ecom-autoplay-progress'
                }
              },
              {
                type: 'number',
                name: 'size_progress_stroke',
                label: this.$t('stroke_width'),
                options: {
                  units: {
                      px: {
                          min: 0,
                          max: 50
                      }
                  },
                },
                css: {
                  properties: {
                    'stroke-width':''
                  },
                  selector: 'root .ecom-autoplay-progress svg'
                }
              },
              {
                name: 'stroke_progress_color',
                label: this.$t('stroke_color'),
                type: 'color',
                options: {
                    oneline: true,
                    global: {
                        type: 'colors'
                    }
                },
                css: {
                    properties: {
                        'color': ''
                    },
                    selector: 'root  .ecom-autoplay-progress svg'
                }
              },
              {
                type: 'line'
              },
              {
                type: 'paragraph',
                content: this.$t('position')
              },
              {
                type: 'number',
                name: 'position_right',
