        javascript() {
            return () => {
                let $el = this.$el;
                if (!$el) {
                    return;
                }
                for (const item of $el.querySelectorAll('[data-ecom-el-role="item"]')) {
                    let copyBtn = item.querySelector('[data-ecom-el-role="copy"]'),
                        codeEl = item.querySelector('[data-ecom-el-role="code"]');
                    if (!copyBtn || !codeEl || !codeEl.textContent) {
                        continue;
                    }
                    let code = codeEl.textContent;
                    copyBtn.addEventListener('click', evt => {
                        evt.preventDefault();
                        copyBtn.disabled = 'disabled';
                        if (copyBtn.classList.contains('ecom-copied')) {
                            return;
                        }
                        (async () => {
                            try {
                                await navigator.clipboard.writeText(code);
                                copyBtn.classList.add('ecom-copied');
                                /*
                                setTimeout(function() {
                                    copyBtn.classList.remove('ecom-copied');
                                    copyBtn.removeAttribute('disabled');
                                }, 1000);
                                */
                            } catch (err) {
                                console.error('Failed to copy: ', err);
                                copyBtn.removeAttribute('disabled');
                            }
                        })();
                    });
                }
            }
