<template>
    <div :key="refresh" class="global-typography-fields">
        <Fields
            :fields="fields"
            :data="valueField"
            :freeform="true"
            @update:label="updateLabel"
            @update:delete="updateDelete"
            @update:data="update"
        />
        <div class="flex flex-wrap justify-start items-center">
            <div class="w-[41%]"></div>
            <div class="flex-1 flex-wrap justify-start items-center">
                <button @click.prevent="addItem" type="button" class="inline-flex justify-start items-center h-5 border-0 font-normal text-[#005BD3] hover:text-gray-800 transition-all duration-300 rounded-md">
                    <EcomIcon :source="icons.CirclePlusMajor" :size="'w-5'" class="inline-flex justify-start items-center mr-1"></EcomIcon>
                    <span class="text-xs">{{ $t('add_new_typography') }}</span>
                </button>
            </div>
        </div>
        <EcomText :size="'tiny'" class="mt-1">
            {{ $t('how_to_use_google_fonts_that_is_gdpr_compliant_get_our') }} <a href="#extensions/746" class="underline text-primary hover:text-secondary transition" @click="closeSetting">{{ $t('extension') }}</a>
        </EcomText>
        
    </div>
</template>

<script lang="ts">
    import { CirclePlusMajor } from "@/assets/icons";
    export default {
        name: 'TypographyGlobal',


        data() {
            return {
                refresh: true,
                itv: null,
                icons:{CirclePlusMajor},
                fields:[]
            };
        },
        computed: {

            values(){
                return this.$store.getters['settings/globalData']('typography');
            },
            valueField(){
                 let vs = {};
                for(let k in this.values) {
                    let v = this.values[k].value;
                    if(v) {
                        vs[k] = v;
                    }
                }
                return vs;
            },

        },

        methods: {

           update(f, values){
               if(!values) return false;
               let datas = {};
                for (let id in values) {
                    let data = this.values[id];
                    datas[id] = {
                        title: data?.title??'',
                        value: values[id],
                    };
                }
                if(JSON.stringify(datas) !== JSON.stringify(this.values)) {
                    this.$store.dispatch('settings/setDataGlobal', {
                        typography: datas
                    });
                }
           },
            titGlobal (title, name) {

                    let valueField = this.values[name]?.value ?? {};
                    // eslint-disable-next-line no-unused-vars
                    let { 'font-size': fontSize, 'line-height': lineHeight, ...valueNotFz } = valueField;

                    let css = Object.entries(valueNotFz)
                        .map(([key, value]) => {
                            return key + ':' + value;
                        }).join(';');
                    return '<span style="' + css + '">' + title + '</span>';

            },
            updateLabel([name, label]) {
                let handle = label.replace(/\s+/g, ' ').trim();
                const isDuplicate = Object.entries(this.values).some(([k, v]) => k !== name && v.title === handle);
                if (isDuplicate) {
                    let counter = 2;
                    let newTitle = handle + '-' + counter;
                    while (Object.entries(this.values).some(([k, v]) => k !== name && v.title === newTitle)) {
                        counter++;
                        newTitle = handle + '-' + counter;
                    }
                    this.values[name].title = newTitle;
                } else {
                    this.values[name].title = handle;
                }
                this.renderFields();
            },
            addItem(){
                this.values[this.$helpers.makeId(6)] = {
                    title: this.$t('new_item'),
                    value: {}
                };
                this.renderFields();
            },
            updateDelete(name) {
                delete this.values[name];
                this.renderFields();
            },
            renderFields() {
                let params = [];
                let values = this.values ?? {};
                for (let id in values) {
                    let data = values[id];
                    let param = {
                        name: id,
                        label: this.titGlobal(data.title, id),
                        rawLabel: data.title,
                        type:  'popup',
                        class: 'ecom-global-typography-field',
                        value: data.value,
                        options: {
                            editLabel: !['primary','secondary','text','accent'].includes(id),
                            isdelete: true,
                            delete: !['primary','secondary','text','accent'].includes(id),
                            type:'typography'
                        }
                    };

                    params.push(param);
                }
                // params.push( {type: 'line'},
                // {
                //     type: 'paragraph',
                //     content: `How to use Google Fonts that is GDPR compliant? Get our [extension](#extensions/746)`
                // })
                this.fields = params;
            },
            closeSetting(){
                this.$store.commit('settings/setStatus', false);
            }
        },
        mounted() {
            this.renderFields();
        },
    };
</script>

