<template>
    <div class="ecom-element ecom-shopify-elements ecom-shopify__newsletter-form" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-shopify__newsletter-form-wrapper ecom-w__full">
            <div class="ecom-shopify__newsletter-form-container" :class="{'ecom-newsletter-vertical': isVertical }">
                <div v-html="liquid('newsletter')" />
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
    name: 'NewsletterForm',
    presets:true,

    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        isVertical(){
            return this.data.settings?.layout === 'column';
        },
        width(){
            return this.data.style?.general?.width ? this.data.style.general.width: "100%" ;
        },
        formHtml() {
            let html = "";
            if (this.fields && Array.isArray(this.fields) && this.fields.length) {
                this.fields.forEach( (field, index) =>{
                    html += `
                    <div class="ecom__form-field ecom-html" style="${this.formWidth(field)}">
                        ${
                            ['first_name', 'last_name', 'note','email'].includes(field.type)? field.type === 'note'?
                            `
                                <label class="ecom-shopify__newsletter-form-field--label" for="ECom-NewsletterForm-${this.data.id}">${field.settings?.label ? field.settings.label : "" }</label>
                                <textarea
                                    type="${field.type}"
                                    id="${field.settings?.id || 'ecom-contact-'+field.type+'-'+index}"
                                    name="contact[${field.type}]"
                                    rows="${field.settings?.rows ?? 3}"
                                    class="ecom-shopify__newsletter-form-field--input ecom-shopify__newsletter-form-field--textarea"                                    
                                    placeholder="${ this.lang(field.settings?.placeholder, field.type+index+'_placeholder')}"
                                    aria-required="${field.type == 'email'? true : field.settings?.required}"
                                    autocorrect="off"
                                    autocapitalize="off"
                                    autocomplete="off"
                                    ${field.settings?.required ? 'required' : ''}
                                    {% if form.errors  %}
                                        aria-invalid="true"
                                    {% endif %}
                                >${ this.lang(field.settings?.value ? field.settings?.value : '', field.type+'_value')}</textarea>
                            `:
                            `
                                <label class="ecom-shopify__newsletter-form-field--label" for="ECom-NewsletterForm-${this.data.id}">${field.settings?.label ? field.settings.label : "" }</label>
                                <input
                                    type="${field.type}"
                                    id="${field.settings?.id || 'ecom-contact-'+field.type+'-'+index}"
                                    name="contact[${field.type}]"
                                    class="ecom-shopify__newsletter-form-field--input"                                    
                                    placeholder="${ this.lang(field.settings?.placeholder, field.type+index+'_placeholder')}"
                                    value="${ this.lang(field.settings?.value ? field.settings?.value : '', field.type+'_value')}"
                                    aria-required="${field.type == 'email'? true : field.settings?.required}"
                                    autocorrect="off"
                                    autocapitalize="off"
                                    autocomplete="${field.type == 'email' ? 'email': field.type == 'first_name'? 'given-name': field.type == 'last_name' ?'family-name': 'off'}"
                                    ${field.type == 'email'? 'required' : field.settings?.required ? 'required' : ''}
                                    {% if form.errors  %}
                                        aria-invalid="true"
                                    {% endif %}
                                />
                            `:""
                        }
                    </div>
                    `;
                })
            } else {
                html = `
                    <input
                    id="ECom-NewsletterForm-${this.data.id}"
                    type="email"
                    name="contact[email]"
                    class="ecom-shopify__newsletter-form-field--input"
                    value="{{ form.email }}"
                    aria-required="true"
                    autocorrect="off"
                    autocapitalize="off"
                    autocomplete="email"
                    {% if form.errors  %}
                        aria-invalid="true"
                    {% endif %}
                    placeholder="${this.lang(this.data.settings?.email_placeholder)}"
                    required
                    >
                `;
            }
            return html;
        },
        liquids() {
            const code = {
                start: `<form class="ecom-shopify__newsletter-form" id="ecom-shopify__newsletter-form-${this.data.id}" data-ecom-popup="${this.data.settings?.form_action_after_submit && this.data.settings?.form_action_after_submit === 'popup' ? this.data.settings?.popup_container?.id : null}">`,
                end: `</form>`
            }
            return {
                newsletter: {
                    code: `
                        ${this.canUseCustomLiquidForCSR ? code.start :`{% form 'customer', action:'/contact',  class: 'ecom-shopify__newsletter-form' ${this.data.settings?.tracking_id ? `,data-ec-tracking-id:'${this.data.settings?.tracking_id}'`:''},id:'newsletter-form-${ this.data.id }',data-ecom-popup:'${this.data?.settings?.form_action_after_submit && this.data?.settings?.form_action_after_submit === 'popup' ? this.data?.settings?.popup_container?.id : null}' %}`}
                        <input type="hidden" name="contact[tags]" value="${this.data.settings?.customer_tag || 'newsletter'}" />
                        <div class="ecom-newsletter-form-content-wrap">
                            <div class="ecom-newsletter-form-content ${this.data?.settings?.fields? `ecom-newsletter-content`: ''}">
                                ${this.isVertical
                                    ? this.formHtml 
                                    :`<input
                                    id="ECom-NewsletterForm-${this.data.id}"
                                    type="email"
                                    name="contact[email]"
                                    class="ecom-shopify__newsletter-form-field--input"
                                    value="{{ form.email }}"
                                    aria-required="true"
                                    autocorrect="off"
                                    autocapitalize="off"
                                    autocomplete="email"
                                    {% if form.errors  %}
                                        aria-invalid="true"
                                    {% endif %}
                                    placeholder="${this.lang(this.data.settings?.email_placeholder, 'email_placeholder')}"
                                    required
                                    >
                                `}
                                ${ this.data.settings?.show_checkbox && this.isVertical
                                    ? `<div class="ecom-shopify__newsletter__verify">
                                        <input type="checkbox" id="agree-${this.data.id}" class="ecom-shopify__newsletter__verify-checkbox" name="agree" value="true" required aria-required="true">
                                        <label for="agree-${this.data.id}" class="ecom-shopify__newsletter__verify-label">${this.lang(this.data.settings?.checkbox_label, 'checkbox_label')}</label>
                                    </div>`
                                    : ''
                                } 
                                ${this.isVertical
                                    ?`<div class="ecome-shopify__newsletter_button-submit-wrapper">
                                        <button type="submit" class="ecome-shopify__newsletter__button" name="commit">
                                            <span> ${this.lang(this.data.settings?.button_title, 'submit_title')} </span>
                                            <span class="ecom-shopify__newsletter__button-icon">${this.lang(this.data.settings?.icon)} </span>
                                        </button>
                                    </div>`
                                    : `<button type="submit" class="ecome-shopify__newsletter__button" name="commit">
                                        <span> ${this.lang(this.data.settings?.button_title, 'submit_title')} </span>
                                        <span class="ecom-shopify__newsletter__button-icon">${this.lang(this.data.settings?.icon)} </span>
                                    </button>
                                `}
                            </div>
                            ${ this.data.settings?.show_checkbox && !this.isVertical
                            ? `<div class="ecom-shopify__newsletter__verify">
                                <input type="checkbox" id="agree-${this.data.id}" class="ecom-shopify__newsletter__verify-checkbox" name="agree" value="true" required aria-required="true">
                                <label for="agree-${this.data.id}" class="ecom-shopify__newsletter__verify-label">${this.lang(this.data.settings?.checkbox_label, 'checkbox_label')}</label>
                            </div>`
                            : ''} 
                        </div>
                        ${ this.data.settings?.show_checkbox
                        ? `<p class="ecom-shopify__newsletter__verify-error ecom-shopify__newsletter-form-detail-error ecom-dn">
                        ${this.lang(this.data.settings?.uncheckbox_message ?? 'Please agree to the terms and conditions before subscribing.', 'uncheckbox_message')}
                            </p>`
                        : ''}
                        {%- if form.posted_successfully? or EComBuilderMode == true ${!this.data.settings.show_preview ? ' and false ' :''} -%}
                        <div class="ecom-shopify__newsletter-form-success" {% unless EComBuilderMode %}tabindex="-1"{% endunless %}>
                            ${this.lang(this.data.settings?.success_message, 'success_message')}
                        </div>
                        {%- endif -%}
                        {%- if form.errors or EComBuilderMode == true  ${!this.data.settings.show_preview ? ' and false ' :''}  -%}
                        <div class="ecom-shopify__newsletter-form-message">
                            <h2 class="ecom-shopify__newsletter-form-status-error" role="alert" {% unless EComBuilderMode %}tabindex="-1"{% endunless %}>
                              ${this.lang(this.data.settings?.error_title, 'error_title')}
                            </h2>
                            <p class="ecom-shopify__newsletter-form-detail-error">
                                {% if EComBuilderMode %}
                                    This is example error text when missing email field
                                {% endif %}
                                {{ form.errors.translated_fields['email'] | capitalize }} {{ form.errors.messages['email'] }}
                            </p>
                        </div>
                        {%- endif -%}
                        <div class="ecom-shopify__newsletter-form-message ecom-dn">
                            <p class="ecom-shopify__newsletter-form-detail-error">
                                ${this.lang(this.data.settings?.error_already ?? 'Email have already subscribed!', 'error_already')}
                            </p>
                        </div>
                    ${this.canUseCustomLiquidForCSR ? code.end : '{% endform %}'}
                    `,
                    preview: ''
                }
            };
        },
        javascript() {
            return function () {
                const $el = this.$el;
                const $this = this;
                if(!$el) return;
                const form = $el.querySelector('form');
                let link = this.settings.link_redirect;
                let url = window.location.href,
                    action = this.settings.form_action_after_submit;
                
                if(this.isLive) {
                    // Checkbox handle: must run before the popup branch below returns early,
                    // and before other submit listeners so they don't fire for a blocked submit.
                    const checkbox = $el.querySelector('.ecom-shopify__newsletter__verify-checkbox');
                    const checkbox_error = $el.querySelector('.ecom-shopify__newsletter__verify-error');
                    if(form && checkbox) {
                        const showCheckboxError = function(show) {
                            checkbox_error && checkbox_error.classList.toggle('ecom-dn', !show);
                        };
                        // The checkbox is `required`: replace the native bubble with our message.
                        checkbox.addEventListener('invalid', function(e) {
                            e.preventDefault();
                            showCheckboxError(true);
                        });
                        // Fallback when native validation is skipped (novalidate, formnovalidate).
                        form.addEventListener('submit', function(e) {
                            if(!checkbox.checked) {
                                e.preventDefault();
                                e.stopImmediatePropagation();
                                showCheckboxError(true);
                            }
                        });
                        checkbox.addEventListener('change', function() {
                            if(checkbox.checked) showCheckboxError(false);
                        });
                    }

                    // ===== GA4 tracking (gtag.js / GTM embedded in theme) =====
                    // Form 'customer' posts and reloads the page, so the conversion event is
                    // fired on the next page load instead of inside the submit handler.
                    const ga4EventName = this.settings.ga4_event_name;
                    if (this.isLive === true && form && ga4EventName) {
                        const ga4Store = 'ecom_nl_ga4_pending';
                        const ga4Payload = {
                            form_id: form.id,
                            form_name: this.settings.tracking_id || 'newsletter_form',
                            form_destination: 'shopify_customer'
                        };
                        const ga4Send = function (name, extra) {
                            const payload = Object.assign({}, ga4Payload, extra || {});
                            if (typeof window.gtag === 'function') {
                                window.gtag('event', name, payload);
                            }
                            if (window.dataLayer && typeof window.dataLayer.push === 'function') {
                                window.dataLayer.push(Object.assign({ event: name }, payload));
                            }
                        };

                        // Remember which form was submitted before the page navigates away.
                        form.addEventListener('submit', function () {
                            try {
                                sessionStorage.setItem(ga4Store, JSON.stringify({
                                    id: form.id, t: new Date().getTime()
                                }));
                            } catch (e) {}
                            ga4Send('form_submit');
                        });

                        // Shopify renders the success block on every customer form of the page,
                        // so only fire for the form that actually posted, and only once.
                        if ($el.querySelector('.ecom-shopify__newsletter-form-success')) {
                            let ga4Pending = null;
                            try {
                                ga4Pending = JSON.parse(sessionStorage.getItem(ga4Store) || 'null');
                            } catch (e) {}
                            if (ga4Pending && ga4Pending.id === form.id && new Date().getTime() - ga4Pending.t < 300000) {
                                try { sessionStorage.removeItem(ga4Store); } catch (e) {}
                                ga4Send(ga4EventName, { method: 'newsletter' });
                            }
                        }
                    }

                    if(action && action === 'popup') {
                        if(url.includes('customer_posted=true')){
                            if(form && form.hasAttribute("data-ecom-popup")) {
                                const id_popup = form.getAttribute("data-ecom-popup") || '';
                                const popupDataElement = document.querySelector('#ecom-popup-data');
                                if (!popupDataElement) {
                                    console.warn('Ecom popup data element not found');
                                    return;
                                }
                                const dataPopupContainer = JSON.parse(popupDataElement.innerHTML);
                                if (dataPopupContainer) {
                                    let popupItem = dataPopupContainer.find(item => item.id === id_popup);
                                    setTimeout(() => {
                                        if(popupItem && window.EComPopup.popupContainerHandler) {
                                            window.EComPopup.popupContainerHandler(popupItem);
                                        }
                                    },300);
                                }
                            }
                        }
                        return;
                    }
                    function ecomNewsletterRedirect(){
                        if(!link) return false;
                        let href = link.href;
                        if(href=='') return false;
                        let target = link.target;
                        let url = window.location.href;
                        if(url.includes('customer_posted=true')){
                            if(target === '_blank'){
                                window.open(href);
                            }
                            else{
                                window.location.href = href;
                            }
                        }
                    }
                    ecomNewsletterRedirect();
                    const regex = /(\?|&)contact%5Btags%5D=[^&]+&form_type=customer(&|$)/;
                    if(this.settings.scroll_in_view) {
                        if(window.location.pathname.includes('challenge')) {
                            setTimeout(function() {
                                var element = document.querySelector(".shopify-challenge__container");
                                element.scrollIntoView();
                            }, 100);
                        }
                        else {
                            setTimeout(function() {
                                if(regex.test(location.search) || window.location.href.includes('customer_posted=true')) {
                                    $el.scrollIntoView();
                                }
                            }, 300);
                        }
                    }

                    if (regex.test(location.search)) {

                        if(form) {
                            form.querySelector('.ecom-shopify__newsletter-form-message.ecom-dn')
                            && form.querySelector('.ecom-shopify__newsletter-form-message.ecom-dn').classList.remove('ecom-dn');
                        }
                    };
                    if(form && form.dataset.ecTrackingId)
                    {
                        form.addEventListener('submit', function(){
                            if(window.Shopify && window.Shopify.analytics)
                            {
                                Shopify.analytics.publish("ec_custom_events",{
                                    "button_id": form.id,
                                    "tracking_id": form.dataset.ecTrackingId
                                })
                            }
                        },{once: true});
                    }
                }
            }
        },
        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'paragraph',
                            name: 'warnings',
                            options: {
                                visible: {
                                    condition: (data) => {
                                    return data['layout'] === 'column' && this.data?.settings?.fields;
                                    }
                                },
                                warnings: {
                                    content: this.$t('the_form_can_only_work_when_it_contains_the_email_field_and_the_field_name_must_be_email')
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('layout'),
                            name: 'layout',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    row: this.$t('horizontal'),
                                    column: this.$t('vertical')
                                },
                                preview: 'title'
                            },
                            css:{
                                selector:' .ecom-newsletter-form-content',
                                properties:{
                                    'flex-direction':'',
                                }
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('placeholder_text'),
                            name: 'email_placeholder',
                            value: 'example@gmail.com',
                            placeholder: 'example@gmail.com',
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                    return data['layout'] !== 'column'
                                    }
                                }
                            },
                        },
                        {
                            type: 'group',
                            name: 'fields',
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                    return data['layout'] === 'column' && this.data?.settings?.fields;
                                    }
                                },
                                add_text: this.$t('add_field')
                            },
                            params: [
                                {
                                    type: 'first_name',
                                    name: this.$t('first_name'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: 'text',
                                            name: 'label',
                                            label: this.$t('label'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'placeholder',
                                            placeholder: 'First name',
                                            label: this.$t('placeholder'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'id',
                                            placeholder: 'first_name',
                                            label: this.$t('id'),
                                            description: this.$t('id_of_the_field'),
                                        },
                                        {
                                            type: 'toggle',
                                            name: 'required',
                                            label: this.$t('required_field'),
                                            options: {
                                                oneline: true,
                                                values: {
                                                    on: {
                                                        label: this.$t('yes'),
                                                        value: true
                                                    },
                                                    off: {
                                                        label: this.$t('no'),
                                                        value: false
                                                    }
                                                }
                                            }
                                        },
                                        {
                                            type: 'number',
                                            label: this.$t('field_width'),
                                            name: 'width',
                                            options: {
                                                units: {
                                                    '%': {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                },
                                                slider: true,
                                                input: true,
                                                min: 0,
                                                max: 100
                                            }
                                        }
                                    ]
                                },
                                {
                                    type: 'last_name',
                                    name: this.$t('last_name'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: 'text',
                                            name: 'label',
                                            label: this.$t('label'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'placeholder',
                                            placeholder: 'Last name',
                                            label: this.$t('placeholder'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'id',
                                            placeholder: 'last_name',
                                            label: this.$t('id'),
                                            description: this.$t('id_of_the_field'),
                                        },
                                        {
                                            type: 'toggle',
                                            name: 'required',
                                            label: this.$t('required_field'),
                                            options: {
                                                oneline: true,
                                                values: {
                                                    on: {
                                                        label: this.$t('yes'),
                                                        value: true
                                                    },
                                                    off: {
                                                        label: this.$t('no'),
                                                        value: false
                                                    }
                                                }
                                            }
                                        },
                                        {
                                            type: 'number',
                                            label: this.$t('field_width'),
                                            name: 'width',
                                            options: {
                                                units: {
                                                    '%': {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                },
                                                slider: true,
                                                input: true,
                                                min: 0,
                                                max: 100
                                            }
                                        }
                                    ]
                                },
                                {
                                    type: 'note',
                                    name: this.$t('Note'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: 'text',
                                            name: 'label',
                                            label: this.$t('label'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'placeholder',
                                            label: this.$t('placeholder'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'id',
                                            label: this.$t('id'),
                                            description: this.$t('id_of_the_field'),
                                            placeholder: 'note'
                                        },
                                        {
                                            type: 'toggle',
                                            name: 'required',
                                            label: this.$t('required_field'),
                                            options: {
                                                oneline: true,
                                                values: {
                                                    on: {
                                                        label: this.$t('yes'),
                                                        value: true
                                                    },
                                                    off: {
                                                        label: this.$t('no'),
                                                        value: false
                                                    }
                                                }
                                            }
                                        },
                                        {
                                            type: 'number',
                                            label: this.$t('field_width'),
                                            name: 'width',
                                            options: {
                                                units: {
                                                    '%': {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                },
                                                slider: true,
                                                input: true,
                                                min: 0,
                                                max: 100
                                            }
                                        },
                                        {
                                            type: 'number',
                                            label: this.$t('specifies_the_visible_number_of_lines_in_a_text_area'),
                                            name: 'rows',
                                            options: {
                                                slider: true,
                                                input: true,
                                                min: 1,
                                                max: 12
                                            }
                                        }
                                    ]
                                },
                                {
                                    type: 'email',
                                    name: this.$t('email_field'),
                                    max: 1,
                                    cantDelete: true,
                                    settings: [
                                        {
                                            type: 'text',
                                            name: 'label',
                                            label: this.$t('label'),
                                        },
                                        {
                                            type: 'text',
                                            name: 'placeholder',
                                            label: this.$t('placeholder'),
                                            value: 'example@gmail.com',
                                            placeholder: 'example@gmail.com'
                                        },
                                        {
                                            type: 'text',
                                            name: 'id',
                                            label: this.$t('id'),
                                            description: this.$t('id_of_the_field'),
                                            placeholder: 'email'
                                        },
                                        {
                                            type: 'number',
                                            label: this.$t('field_width'),
                                            name: 'width',
                                            options: {
                                                units: {
                                                    '%': {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                },
                                                slider: true,
                                                input: true,
                                                min: 0,
                                                max: 100
                                            }
                                        }
                                    ]
                                },
                            ]
                        },
                        {
                            type: 'text',
                            label: this.$t('submit_button_label'),
                            name: 'button_title',
                            value: 'Subscribe',
                            placeholder: this.$t('subscribe'),
                        },
                        {
                            type: 'picker',
                            label: this.$t('icon'),
                            name: 'icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['icon'];
                                    }
                                }
                            },
                            css:{
                                selector:' .ecom-shopify__newsletter__button-icon',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('icon_spacing'),
                            name: 'spacing',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 200
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['icon'];
                                    }
                                }
                            },
                            css:{
                                selector:' .ecome-shopify__newsletter__button',
                                properties:{

                                    gap:''
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_checkbox',
                            label: this.$t('show_checkbox_below_form'),
                            options:{
                                    values: {
                                        on: {
                                            label: this.$t('yes'),
