<i18n>
{
    "en": {
        "custom_language_code": "Custom {language} code",
        "discard": "Discard",
        "save": "Save",
        "open_editor": "Open editor"
    },
    "fr": {
        "custom_language_code": "Code de {language} personnalisé ",
        "discard": "Annuler",
        "save": "Enregistrer",
        "open_editor": "Ouvrir l'éditeur"
    },
    "de": {
        "custom_language_code": "Benutzerdefinierter {language}-Code",
        "discard": "Verwerfen",
        "save": "Speichern",
        "open_editor": "Editor öffnen"
    },
    "ja": {
        "custom_language_code": "カスタム {language} コード",
        "discard": "破棄",
        "save": "保存",
        "open_editor": "エディタを開く"
    }
}
</i18n>
<template>
    <textarea
        v-if="!isCodeEditor && (!field.options || (['full', 'short', true].indexOf(field.options.toolbar) === -1))"
        v-model="value"
        :placeholder="field?.options?.placeholder ?? null"
        class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
        :style="field.options && field.options.height ? 'min-height:'+field.options.height+'px' : 'min-height: 100px'"
        @change="onchange"
    />
    <EditorComponent
        v-else-if="!isCodeEditor"
        :data="value"
        :field="field"
        :type="1"
        @update:data="$emit('update:data', $event)"
    />
    <div v-else class="relative">
        <div
            ref="inlineHost"
            class="block w-full rounded-lg border border-input text-xs font-normal hover:border-input-hover focus-within:border-input-hover outline-offset-1 outline-none overflow-hidden"
            :style="'height:'+(field.options && field.options.height ? field.options.height : 150)+'px'"
        ></div>
        <button
            type="button"
            class="absolute top-1 right-1 flex items-center justify-center w-5 h-5 rounded hover:bg-fill-transparent-hover"
            @click="openPopup"
            :data-tooltip="$t('open_editor')"
        >
            <EcomIcon :source="ecFullScreen" :size="'w-3'" :color="'text-icon-secondary'" class="flex items-center justify-center"></EcomIcon>
        </button>
    </div>
    <template v-if="showPopup">
        <Teleport to="body">
            <Popup
                :width="1024"
                :height="600"
                :popclass="undefined"
                :wrpclass="'items-center my-5 bg-white   rounded-lg'"
                bodyclass="overflow-y-auto w-full"
                :closeClass="'mt-1.5'"
                @close="close"
            >
                <template #header>
                    <EcomText :as="'h4'" class="h-10 flex items-center text-xl font-semibold">{{ $t('custom_language_code', {language: field?.options?.language}) }}</EcomText>
                </template>
                <template #body>
                    <div class="h-full overflow-auto flex flex-col">
                        <div class="p-2 flex flex-grow flex-col w-full bg-white   shadow-custom">
                            <div ref="modalHost" class="flex-1 min-h-0 w-full"></div>
                        </div>
                    </div>
                </template>
                <template #footer>
                    <div class="flex w-full items-center gap-2 px-4 justify-end py-2">
                        <s-button
                            @click="discard"
                            variant="secondary"
                        >
                            {{ $t('discard') }}
                        </s-button>
                        <s-button
                            @click="close"
                            variant="primary"
                        >
                            {{ $t('save') }}
                        </s-button>
                    </div>
                </template>
            </Popup>
        </Teleport>
    </template>
</template>

<script lang="ts">
    import EditorComponent from '../../components/editor/Editor.vue';
    import { ecFullScreen } from '@/assets/icons';
    import { debounce } from '@/utils/helpers';
    import type { CodeEditorHandle } from './codeEditor/useCodeMirror';

    export default {
        name: 'EditorField',
        components: {
            EditorComponent
        },
        props: {
            data: {
                type: String,
                default: ''
            },
            field: {
                type: Object,
                default(){
                    return {};
                }
            }
        },
        emits: ['update:data'],
        data() {
            return {
                value: '',
                showPopup: false,
                ecFullScreen,
                editorHandle: null as CodeEditorHandle | null,
                snapshotValue: ''
            };
        },
        computed: {
            isCodeEditor(): boolean {
                return !!(this.field?.options?.editor && this.field?.options?.language);
            }
        },
        watch: {
            value(val) {
                if (this.field?.options?.update != 'onchange' || this.field.options.toolbar || this.field?.options?.editor) {
                    this.$emit('update:data', val);
                }
            },
            data(val) {
                this.value = val;
                if (this.editorHandle) {
                    this.editorHandle.setValue(val != '__empty__' ? val : '');
                }
            }
        },
        mounted() {
            this.value = this.data != '__empty__' ? this.data : '';
            if (this.isCodeEditor) {
                this.initEditor();
            }
        },
        beforeUnmount() {
            this.editorHandle?.destroy();
        },
        methods: {
            onchange() {
                if (this.field?.options?.update == 'onchange') {
                    this.$emit('update:data', this.value);
                }
            },
            async initEditor() {
                const { mountCodeEditor } = await import('./codeEditor/useCodeMirror');
                const emitChange = debounce((val: string) => {
                    this.value = val;
                }, 300);
                this.$nextTick(() => {
                    if (!this.$refs.inlineHost) return;
                    this.editorHandle = mountCodeEditor({
                        container: this.$refs.inlineHost as HTMLElement,
                        value: this.value,
                        language: this.field.options.language,
                        onChange: emitChange
                    });
                });
            },
            openPopup(){
                if (!this.isCodeEditor || !this.editorHandle) return;
                this.snapshotValue = this.value;
                this.showPopup = true;
                this.$nextTick(() => {
                    if (this.$refs.modalHost) {
                        this.editorHandle?.reparent(this.$refs.modalHost as HTMLElement);
                        this.editorHandle?.setLineNumbersVisible(true);
                    }
                });
            },
            close(){
                this.showPopup = false;
                this.$nextTick(() => {
                    if (this.$refs.inlineHost) {
                        this.editorHandle?.reparent(this.$refs.inlineHost as HTMLElement);
                        this.editorHandle?.setLineNumbersVisible(false);
                    }
                });
            },
            discard(){
                this.editorHandle?.setValue(this.snapshotValue);
                this.close();
            }
        }
    };
</script>
