<script lang="ts">
import { DeleteIcon, PlusIcon, SpinIcon, SelectIcon, XIcon } from '@/assets/icons/ai';
import { Toast } from '@/store/modules/global';
import { aiImagesCache } from '@/utils/ai-images-cache';
import AITokens from '@/components/SideBar/AI/AITokens.vue';

export default {
    name: 'PickerAIContent',
    emits: ['upload', 'switchTab'],
    components: {
        AITokens
    },
    props: {
        list: {
            type: Array,
            default: () => []
        },
        selectedImages: {
            type: Array,
            default: () => []
        },
        initialMode: {
            type: String,
            default: 'generate'
        }
    },
    data() {
        return {
            icons: {
                DeleteIcon,
                PlusIcon,
                SpinIcon,
                SelectIcon,
                XIcon
            },
            prompt: '' as string,
            style: 'realistic',
            size: 'auto',
            numberOfImages: 1,
            image:[],
            styles: [
                {
                    value: 'realistic',
                    text: 'Realistic'
                },
                {
                    value: 'artistic',
                    text: 'Artistic'
                },
                {
                    value: 'cartoon',
                    text: 'Cartoon'
                },
                {
                    value: 'custom',
                    text: 'Custom'
                }
            ],
            sizes: [
                {
                    value: 'auto',
                    text: 'Auto'
                },
                {
                    value: '1024x1024',
                    text: 'Square (1024x1024)'
                },
                {
                    value: '1536x1024',
                    text: 'Landscape (1536x1024)'
                },
                {
                    value: '1024x1536',
                    text: 'Portrait (1024x1536)'
                }
            ],
            customStyle: '',
            isGenerating: false,
            generatedImages: [] as {
                id: string,
                url: string,
                alt: string,
                mimeType: string,
                loading?: boolean,
                source?: string
            }[],
            mode: 'generate' as 'generate' | 'edit' | 'mask',
            uploadedImages: [] as {
                name: string,
                preview: string,
                file: File
            }[],
            originalImage: null as {
                name: string,
                preview: string,
                file: File
            } | null,
            maskImage: null as {
                name: string,
                preview: string,
                file: File
            } | null,
            // Drawing mask properties
            maskInputMode: 'draw' as 'upload' | 'draw',
            brushSize: 20,
            brushOpacity: 0.8,
            drawingMode: 'brush' as 'brush' | 'eraser',
            brushColor: '#ff0000',
            colorPresets: ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff', '#000000', '#ffffff'],
            canvasSize: { width: 400, height: 400 },
            isDrawing: false,
            lastX: 0,
            lastY: 0,
            updateMaskTimeout: null as number | null,
            // Modal properties
            showImageModal: false,
            modalImageUrl: '',
            modalImageName: '',
        }
    },
    computed: {
        aiTokens() {
            return this.$store.getters['ai/aiImageTokens'];
        },
        aiCosts() {
            return this.$store.getters['ai/aiCosts'];
        },
        tokenUsagePercentage() {
            return this.aiTokens.max > 0 ? this.aiTokens.used / this.aiTokens.max : 1;
        },
        canProcess() {
            if (!this.prompt.trim()) return false;
            if (this.isGenerating) return false;
            if (this.generatedImages.length >= 10) return false;
            if (this.style === 'custom' && !this.customStyle) return false;
            if (this.mode === 'edit' && this.uploadedImages.length === 0) return false;
            if (this.mode === 'mask') {
                if (!this.originalImage) return false;
                // In upload mode, mask image must be uploaded
                // In draw mode, mask will be auto-generated from canvas at submit time
                if (this.maskInputMode === 'upload' && !this.maskImage) return false;
            }
            return true;
        },
    },
    methods: {
        openPricing() {
            this.$store.dispatch('upgrade/showUpgradePopup', {
                feature_key: 'ai_credits',
                source_location: 'ai_image_picker',
            });
        },
        validateNumberOfImages(event: Event) {
            let value = Number((event.target as HTMLInputElement).value);
            if (value < 1) {
                value = 1;
            } else if (value > 10) {
                value = 10;
            }
            this.numberOfImages = value;
            (event.target as HTMLInputElement).value = value.toString();
        },
        getProcessButtonText() {
            if (this.isGenerating) {
                return this.mode === 'generate' ?
                 'Generating...' : this.mode === 'edit' ? 'Editing image...' : 'Mask Editing image...';
            }
            if (this.mode === 'edit') {
                return 'Edit image';
            }
            if (this.mode === 'mask') {
                return `Mask Edit image`;
            }
            return 'Generate Image';
        },
        async processImage() {
            if (!this.canProcess) return;
            const cost = this.aiCosts.generate_image * this.numberOfImages;
            const canProceed = await this.$store.dispatch('ai/checkCredits', cost);
            if (!canProceed) return;
            this.isGenerating = true;
            let defaultMessage = 'Error processing image, please try again later';

            /**
             * The response can be JSON (error, messages) or a blob (which is the image)
             * So we can not use the $worker.fetch method
             */
            const formData = new FormData();
            formData.append('query', this.prompt);
            formData.append('style', this.style === 'custom' ? this.customStyle : this.style);
            formData.append('size', this.size);
            formData.append('mode', this.mode);
            const n = this.mode === 'edit' ? Math.min(this.uploadedImages.length || 1, 10) : (this.numberOfImages > 10 ? 10 : this.numberOfImages);
            formData.append('n', n.toString());
            if (this.mode === 'edit' && this.uploadedImages.length > 0) {
                // Wait for any background file fetches to complete
                const pendingImages = this.uploadedImages.filter((img: any) => img._loading);
                if (pendingImages.length > 0) {
                    await new Promise<void>((resolve) => {
                        const checkInterval = setInterval(() => {
                            if (!this.uploadedImages.some((img: any) => img._loading)) {
                                clearInterval(checkInterval);
                                resolve();
                            }
                        }, 100);
                        setTimeout(() => { clearInterval(checkInterval); resolve(); }, 30000);
                    });
                }
                // Ensure all images have a valid File object
                for (const image of this.uploadedImages as any[]) {
                    if (!image.file && image.preview) {
                        image.file = await this.imageUrlToFile(image.preview, image.name);
                    }
                }
                const validImages = this.uploadedImages.filter((img: any) => img.file);
                if (validImages.length === 0) {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: 'Could not load the image file. Please try uploading the image manually.',
                        duration: 5000
                    } as Toast);
                    this.isGenerating = false;
                    return;
                }
                validImages.forEach((image: any) => {
                    formData.append('image', image.file);
                });
            } else if (this.mode === 'mask' && this.originalImage) {
                // Ensure originalImage has a valid File object
                if (!this.originalImage.file && this.originalImage.preview) {
                    this.originalImage.file = await this.imageUrlToFile(this.originalImage.preview, this.originalImage.name);
                }
                if (!this.originalImage.file) {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: 'Could not load the original image. Please try uploading it manually.',
                        duration: 5000
                    } as Toast);
                    this.isGenerating = false;
                    return;
                }
                formData.append('image', this.originalImage.file);

                // Generate mask: from canvas (draw mode) or from uploaded file
                if (this.maskInputMode === 'draw') {
                    // Auto-generate mask from canvas if not yet created
                    if (!this.maskImage) {
                        const maskFile = await this.generateMaskFromCanvas();
                        if (maskFile) {
                            formData.append('mask', maskFile);
                        } else {
                            this.$store.commit('global/setToast', {
                                isError: true,
                                message: 'Could not generate mask. Please draw on the canvas first.',
                                duration: 5000
                            } as Toast);
                            this.isGenerating = false;
                            return;
                        }
                    } else {
                        formData.append('mask', this.maskImage.file);
                    }
                } else if (this.maskImage?.file) {
                    formData.append('mask', this.maskImage.file);
                }
            }

            const apiEndpoint =  '/ai/api/generate-image'

            let processedImageCount = 0;

            window.fetch(
                window.location.origin + apiEndpoint,
                {
                    method: 'POST',
                    body: formData
                }
            )
                .then(response => {
                    if (!response.ok) {
                        throw new Error(response.status === 504
                            ? 'Request timed out. The image generation is taking too long, please try again.'
                            : `Server error (${response.status}), please try again later.`);
                    }
                    return response.json();
                })
                .then((response) => {
                    const images = Array.isArray(response.data) ? response.data : [];
                    const hasImageData = images.some((img: any) => img.b64_json && img.b64_json.length);

                    // Chỉ hiện toast lỗi khi không có data image nào trả về
                    if (response.status !== 'success' && !hasImageData) {
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: response.message || defaultMessage,
                            duration: 5000
                        } as Toast);
                        return;
                    }

                    // const { blob, token } = response as { blob: Blob, token: string };
                    const token = response.token;
                    for (let i = 0; i < images.length; i++) {
                        const image = images[i];
                        // if (image.url && image.url.length) {
                        //     const id = this.$helpers.makeId(16);

                        //     // Không cần cache blob nếu đã có URL
                        //     // aiImagesCache[id] = { ... }

                        //     if (!this.generatedImages.find(img => img.id == id)) {
                        //         this.generatedImages.push({
                        //             id,
                        //             url: image.url, // Dùng URL trực tiếp
                        //             alt: id,
                        //             mimeType: 'image/png',
                        //             source: 'url' // Đánh dấu nguồn để debug
                        //         });
                        //     }

                        //     continue; // Skip sang image tiếp theo
                        // }

                        if (image.b64_json && image.b64_json.length) {
                            processedImageCount++;
                            // convert base64 to blob
                            fetch(`data:image/png;base64,${image.b64_json}`)
                                .then(response => response.blob())
                                .then(blob => {
                                    const id = this.$helpers.makeId(16);
                                    aiImagesCache[id] = {
                                        blob,
                                        name: id,
                                        mimeType: blob.type || 'image/png'
                                    };
                                    if (!this.generatedImages.find(img => img.id == id)) {
                                        this.generatedImages.push({
                                            id,
                                            url: URL.createObjectURL(blob),
                                            alt: id,
                                            mimeType: blob.type || 'image/png'
                                        });
                                    }
                                })
                                .catch(err => {
                                    console.error('Failed to convert base64 to blob:', err);
                                });
                            continue;
                        }
                    }

                    // this.prompt = '';
                    // if (this.mode === 'edit') {
                    //     this.clearAllUploadedImages();
                    // } else if (this.mode === 'mask') {
                    //     this.removeOriginalImage();
                    //     this.removeMaskImage();
                    // }

                    // Wrap token processing in try-catch để không ảnh hưởng đến image đã xử lý
                    try {
                        const credits = response.credits || {};
                        let tokenData = {
                            used: credits.used,
                            max: credits.max
                        } as {
                            used?: number,
                            max?: number
                        };

                        if ('number' == typeof tokenData.used && tokenData.used >= 0) {
                            this.$store.commit('ai/setAIImageUsedTokens', tokenData.used);
                        }
                        if ('number' == typeof tokenData.max && tokenData.max >= 0) {
                            this.$store.commit('ai/setAIImageMaxTokens', tokenData.max);
                        }
                    } catch (tokenErr) {
                        console.error('Failed to process token data:', tokenErr);
                    }
                })
                .catch((e) => {
                    console.error('Image processing error:', e);
                    // Chỉ hiện toast lỗi khi không có ảnh nào đã được xử lý
                    if (processedImageCount === 0) {
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: defaultMessage,
                            duration: 5000
                        } as Toast);
                    }
                })
                .finally(() => {
                    this.isGenerating = false;
                });
        },
        async addToLibrary(id: string) {
            const imageIndex = this.generatedImages.findIndex(img => img.id == id);
            if (imageIndex < 0) {
                this.removeFromGenerated(id);
                return;
            }

            let entry = aiImagesCache[id];

            // Logic xử lý khi ảnh trả về dạng URL thay vì Base64
            if (!entry) {
                const generatedImage = this.generatedImages[imageIndex];
                if (generatedImage && generatedImage.url) {
                    this.setEntryLoading(id, true);
                    try {
                        // Tải ảnh từ URL về bộ nhớ tạm (ngầm)
                        const response = await window.fetch(generatedImage.url);
                        if (!response.ok) throw new Error("Could not fetch image from URL");

                        const blob = await response.blob();
                        aiImagesCache[id] = {
                            blob,
                            name: id,
                            mimeType: blob.type || 'image/png'
                        };
                        entry = aiImagesCache[id];
                    } catch (err) {
                        console.error('Fetch error:', err);
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: 'Could not prepare image for upload. Please try again.',
                            duration: 3000
                        });
                        this.setEntryLoading(id, false);
                        return;
                    }
                }
            }

            if (!entry || entry.loading) {
                return;
            }
            const file = new File([entry.blob], `${id}.png`, { type: entry.mimeType || 'image/png' });
            this.setEntryLoading(id, true);
            aiImagesCache[id].loading = true;

            /**
             * Mimic the event with proper parameters
             * @see src/plugins/fields/components/picker/PickerContent.vue methods/upload
             */
            this.$emit('upload', {
                dest: null,
                target: {
                    files: [file]
                },
                value: ''
            }, {
                id,
                from: 'ai'
            }, () => {
                this.setEntryLoading(id, false);
                this.removeFromGenerated(id);

                // Add timeout to reload picker and switch to Uploaded tab
                setTimeout(() => {
                    this.triggerReload();
                    this.$emit('switchTab', 'uploaded');
                }, 1000);
            }, () => {
                this.setEntryLoading(id, false);
            });
        },
        triggerReload() {
            // Access the parent component's reload functionality
            // Based on PickerPopup.vue structure, we need to call the parent's reloadPicker method
            if (this.$parent && typeof (this.$parent as any).reload === 'function') {
                this.$store.dispatch('picker/reload', {
                    type: 'image',
                    subtype: 'uploaded'
                });
                (this.$parent as any).reload();
            }
        },
        setEntryLoading(id: string, loading: boolean) {
            let entry = this.generatedImages.find(img => img.id == id);
            if (aiImagesCache[id]) {
                aiImagesCache[id].loading = loading;
            }
            if (entry) {
                entry.loading = loading;
            }
        },
        removeFromGenerated(id: string) {
            const imageIndex = this.generatedImages.findIndex(img => img.id == id);
            if (imageIndex < 0 || this.generatedImages[imageIndex].loading) {
                return;
            }
            delete aiImagesCache[id];
            this.generatedImages.splice(imageIndex, 1);
        },
        triggerFileInput() {
            const fileInput = this.$refs.fileInput as HTMLInputElement;
            if (fileInput) {
                fileInput.click();
            }
        },
        handleFileSelect(event: Event) {
            const target = event.target as HTMLInputElement;
            if (target.files && target.files.length > 0) {
                const files = Array.from(target.files);
                this.processSelectedFiles(files);
            }
        },
        handleFileDrop(event: DragEvent) {
            event.preventDefault();
            if (event.dataTransfer?.files && event.dataTransfer.files.length > 0) {
                const files = Array.from(event.dataTransfer.files);
                this.processSelectedFiles(files);
            }
        },
        processSelectedFiles(files: File[]) {
            const maxFileSize = 10 * 1024 * 1024; // 10MB
            const allowedTypes = ['image/png', 'image/jpeg', 'image/webp'];
            let validFiles = files.filter(file => {
                if (!allowedTypes.includes(file.type)) {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: `${file.name} is not supported. Only PNG, JPG, WebP are allowed.`,
                        duration: 3000
                    });
                    return false;
                }
                if (file.size > maxFileSize) {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: `${file.name} is too large. Maximum size is 10MB.`,
                        duration: 3000
                    });
                    return false;
                }
                return true;
            });

            if (validFiles.length > 0) {
                // Only keep the first file (single image edit)
                const file = validFiles[0];
                // Clean up previous image preview URL
                if (this.uploadedImages.length > 0 && this.uploadedImages[0].preview) {
                    URL.revokeObjectURL(this.uploadedImages[0].preview);
                }
                this.uploadedImages = [{
                    name: file.name,
                    preview: URL.createObjectURL(file),
                    file: file
                }];
            }
        },
        removeUploadedImage(index: number) {
            // Clean up preview URL
            if (this.uploadedImages[index].preview) {
                URL.revokeObjectURL(this.uploadedImages[index].preview);
            }

            this.uploadedImages.splice(index, 1);

            // Reset file input if no images left
            if (this.uploadedImages.length === 0) {
                const fileInput = this.$refs.fileInput as HTMLInputElement;
                if (fileInput) {
                    fileInput.value = '';
                }
            }
        },
        clearAllUploadedImages() {
            // Clean up all preview URLs
            this.uploadedImages.forEach(image => {
                if (image.preview) {
                    URL.revokeObjectURL(image.preview);
                }
            });

            this.uploadedImages = [];

            // Reset file input
            const fileInput = this.$refs.fileInput as HTMLInputElement;
            if (fileInput) {
                fileInput.value = '';
            }
        },
