        processMaskImageFile(file: File) {
            const maxFileSize = 10 * 1024 * 1024; // 10MB
            const allowedTypes = ['image/png', 'image/jpeg', 'image/webp'];
            if (!allowedTypes.includes(file.type)) {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: `${file.name} is not supported. Only PNG, JPG, WebP are allowed.`,
                    duration: 3000
                });
                return;
            }
            if (file.size > maxFileSize) {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: `${file.name} is too large. Maximum size is 10MB.`,
                    duration: 3000
                });
                return;
            }

            if (!this.originalImage) {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: 'Please upload an original image first.',
                    duration: 3000
                });
                return;
            }

            // Validate mask dimensions match original image
            const img = new Image();
            const originalImg = new Image();

            img.onload = () => {
                originalImg.onload = () => {
                    if (img.naturalWidth !== originalImg.naturalWidth || img.naturalHeight !== originalImg.naturalHeight) {
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: `Mask image dimensions (${img.naturalWidth}x${img.naturalHeight}) must match original image dimensions (${originalImg.naturalWidth}x${originalImg.naturalHeight}).`,
                            duration: 5000
                        });
                        return;
                    }

                    // Clean up existing preview
                    if (this.maskImage && this.maskImage.preview) {
                        URL.revokeObjectURL(this.maskImage.preview);
                    }

                    this.maskImage = {
                        name: file.name,
                        preview: URL.createObjectURL(file),
                        file: file
                    };
                };
                if (this.originalImage && this.originalImage.preview) {
                    originalImg.src = this.originalImage.preview;
                }
            };

            img.onerror = () => {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: 'Unable to load mask image for validation.',
                    duration: 3000
                });
            };

            originalImg.onerror = () => {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: 'Unable to load original image for validation.',
                    duration: 3000
                });
            };

            img.src = URL.createObjectURL(file);
        },
        removeMaskImage() {
            if (this.maskImage?.preview) {
                URL.revokeObjectURL(this.maskImage.preview);
            }
            this.maskImage = null;

            // Reset file input
            const fileInput = this.$refs.maskImageInput as HTMLInputElement;
            if (fileInput) {
                fileInput.value = '';
            }
        },
        // Canvas drawing methods
        setupCanvas() {
            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            const img = this.$refs.backgroundImage as HTMLImageElement;
            if (!canvas || !img) return;

            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            // Wait for image to load to get accurate dimensions
            if (img.complete && img.naturalWidth > 0) {
                this.setCanvasSize(canvas, img);
            } else {
                img.onload = () => {
                    this.setCanvasSize(canvas, img);
                };
            }
        },
        setCanvasSize(canvas: HTMLCanvasElement, img: HTMLImageElement) {
            // Set maximum display size constraints
            const maxWidth = 600;
            const maxHeight = 400;

            // Get natural image dimensions
            const naturalAspectRatio = img.naturalWidth / img.naturalHeight;

            let canvasWidth, canvasHeight;

            // Calculate canvas size maintaining aspect ratio and respecting max constraints
            if (naturalAspectRatio > maxWidth / maxHeight) {
                // Image is wider relative to max constraints
                canvasWidth = Math.min(maxWidth, img.naturalWidth);
                canvasHeight = canvasWidth / naturalAspectRatio;
            } else {
                // Image is taller relative to max constraints
                canvasHeight = Math.min(maxHeight, img.naturalHeight);
                canvasWidth = canvasHeight * naturalAspectRatio;
            }

            // Ensure minimum size for usability
            const minSize = 200;
            if (canvasWidth < minSize || canvasHeight < minSize) {
                if (naturalAspectRatio > 1) {
                    canvasWidth = minSize;
                    canvasHeight = minSize / naturalAspectRatio;
                } else {
                    canvasHeight = minSize;
                    canvasWidth = minSize * naturalAspectRatio;
                }
            }

            this.canvasSize.width = Math.round(canvasWidth);
            this.canvasSize.height = Math.round(canvasHeight);

            // Clear canvas
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
            }
        },
        startDrawing(event: MouseEvent | TouchEvent) {
            this.isDrawing = true;

            // Get initial position
            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            if (!canvas) return;

            const rect = canvas.getBoundingClientRect();
            let clientX: number, clientY: number;

            if (event instanceof MouseEvent) {
                clientX = event.clientX;
                clientY = event.clientY;
            } else {
                clientX = event.touches[0].clientX;
                clientY = event.touches[0].clientY;
            }

            this.lastX = clientX - rect.left;
            this.lastY = clientY - rect.top;

            this.draw(event);
        },
        draw(event: MouseEvent | TouchEvent) {
            if (!this.isDrawing) return;

            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            if (!canvas) return;

            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            const rect = canvas.getBoundingClientRect();
            let clientX: number, clientY: number;

            if (event instanceof MouseEvent) {
                clientX = event.clientX;
                clientY = event.clientY;
            } else {
                clientX = event.touches[0].clientX;
                clientY = event.touches[0].clientY;
            }

            const x = clientX - rect.left;
            const y = clientY - rect.top;

            if (this.drawingMode === 'brush') {
                // Brush mode: add colored overlay
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = this.brushOpacity;
                const colorWithAlpha = this.hexToRgba(this.brushColor, this.brushOpacity);
                ctx.strokeStyle = colorWithAlpha;
                ctx.fillStyle = colorWithAlpha;
            } else {
                // Eraser mode: remove existing pixels
                ctx.globalCompositeOperation = 'destination-out';
                ctx.globalAlpha = 1;
                ctx.strokeStyle = 'rgba(0, 0, 0, 1)';
                ctx.fillStyle = 'rgba(0, 0, 0, 1)';
            }

            ctx.lineWidth = this.brushSize;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            // Draw line from last position to current position for smooth drawing
            ctx.beginPath();
            ctx.moveTo(this.lastX, this.lastY);
            ctx.lineTo(x, y);
            ctx.stroke();

            // Also draw a circle at current position to ensure coverage
            ctx.beginPath();
            ctx.arc(x, y, this.brushSize / 2, 0, Math.PI * 2);
            ctx.fill();

            // Update last position
            this.lastX = x;
            this.lastY = y;

            // Update mask image with canvas data (debounced for performance)
            this.debouncedUpdateMask();
        },
        stopDrawing() {
            this.isDrawing = false;
            // Force immediate update when user stops drawing
            if (this.updateMaskTimeout) {
                clearTimeout(this.updateMaskTimeout);
                this.updateMaskTimeout = null;
            }
            this.updateMaskFromCanvas();
        },
        clearCanvas() {
            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            if (!canvas) return;

            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            this.updateMaskFromCanvas();
        },
        updateMaskFromCanvas() {
            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            const backgroundImg = this.$refs.backgroundImage as HTMLImageElement;
            if (!canvas || !backgroundImg || !this.originalImage) return;

            // Create a temporary canvas to composite the original image with the mask
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');
            if (!tempCtx) return;

            // Set canvas size to match the original image actual size
            const img = new Image();
            let blobUrl = '';

            // Use blob URL from file (same-origin, no CORS issues)
            // Falls back to CDN URL with crossOrigin if file not available
            if (this.originalImage.file) {
                blobUrl = URL.createObjectURL(this.originalImage.file);
                img.src = blobUrl;
            } else if (this.originalImage.preview) {
                img.crossOrigin = 'anonymous';
                img.src = this.originalImage.preview;
            } else {
                return;
            }

            img.onload = () => {
                tempCanvas.width = img.naturalWidth;
                tempCanvas.height = img.naturalHeight;

                // Draw the original image as background
                tempCtx.drawImage(img, 0, 0, tempCanvas.width, tempCanvas.height);

                // Calculate the correct scale factors for the mask overlay
                // The canvas might be smaller than the natural image size, so we need to scale properly
                const scaleX = img.naturalWidth / this.canvasSize.width;
                const scaleY = img.naturalHeight / this.canvasSize.height;

                // Create ImageData from the mask canvas and scale it correctly
                const maskCtx = canvas.getContext('2d');
                if (maskCtx) {
                    // Create a properly scaled mask canvas
                    const scaledMaskCanvas = document.createElement('canvas');
                    scaledMaskCanvas.width = img.naturalWidth;
                    scaledMaskCanvas.height = img.naturalHeight;
                    const scaledMaskCtx = scaledMaskCanvas.getContext('2d');

                    if (scaledMaskCtx) {
                        // Scale the mask drawing to match the original image size exactly
                        // Use high-quality scaling for better mask accuracy
                        scaledMaskCtx.imageSmoothingEnabled = true;
                        scaledMaskCtx.imageSmoothingQuality = 'high';

                        // Draw the mask canvas scaled to the original image dimensions
                        scaledMaskCtx.drawImage(
                            canvas,
                            0, 0, canvas.width, canvas.height,  // Source dimensions (canvas)
                            0, 0, scaledMaskCanvas.width, scaledMaskCanvas.height  // Destination dimensions (original image size)
                        );

                        // Composite the scaled mask on top of the original image
                        tempCtx.globalCompositeOperation = 'source-over';
                        tempCtx.drawImage(scaledMaskCanvas, 0, 0);
                    }
                }

                // Convert to blob and create mask image
                tempCanvas.toBlob((blob) => {
                    if (blob) {
                        // Clean up existing mask image
                        if (this.maskImage?.preview) {
                            URL.revokeObjectURL(this.maskImage.preview);
                        }

                        // Create new mask image from composite canvas
                        const file = new File([blob], 'mask.png', { type: 'image/png' });
                        this.maskImage = {
                            name: 'mask.png',
                            preview: URL.createObjectURL(blob),
                            file: file
                        };
                    }
                }, 'image/png');

                // Clean up blob URL
                if (blobUrl) {
                    URL.revokeObjectURL(blobUrl);
                }
            };
        },
        async imageUrlToFile(url: string, name: string): Promise<File | null> {

            // Try 1: direct fetch
            try {
                const resp = await window.fetch(url);
                if (resp.ok) {
                    const blob = await resp.blob();
                    if (blob.size > 0) {
                        const file = new File([blob], name || 'image.png', { type: blob.type || 'image/png' });
                        return file;
                    }
                }
            } catch (e) {
                console.warn('[imageUrlToFile] Try 1 FAILED:', e);
            }

            // Try 2: load via <img crossOrigin="anonymous"> + canvas
            // Add cache-buster to avoid browser serving cached non-CORS response
            const corsUrl = url + (url.includes('?') ? '&' : '?') + '_cors=' + Date.now();
            const canvasResult = await new Promise<File | null>((resolve) => {
                const img = new Image();
                img.crossOrigin = 'anonymous';
                img.onload = () => {
                    try {
                        const canvas = document.createElement('canvas');
                        canvas.width = img.naturalWidth;
                        canvas.height = img.naturalHeight;
                        const ctx = canvas.getContext('2d');
                        if (!ctx) { console.error('[imageUrlToFile] no canvas context'); resolve(null); return; }
                        ctx.drawImage(img, 0, 0);
                        canvas.toBlob((blob) => {
                            if (blob && blob.size > 0) {
                                resolve(new File([blob], name || 'image.png', { type: 'image/png' }));
                            } else {
                                resolve(null);
                            }
                        }, 'image/png');
                    } catch (e) {
                        console.error('[imageUrlToFile] Try 2 canvas FAILED (tainted):', e);
                        resolve(null);
                    }
                };
                img.onerror = (e) => {
                    console.error('[imageUrlToFile] Try 2 img.onerror:', e);
                    resolve(null);
                };
                img.src = corsUrl;
            });
            if (canvasResult) {
                return canvasResult;
            }

            console.error('[imageUrlToFile] ALL methods FAILED for:', url);
            return null;
        },
        async generateMaskFromCanvas(): Promise<File | null> {
            const canvas = this.$refs.maskCanvas as HTMLCanvasElement;
            if (!canvas || !this.originalImage) return null;

            return new Promise<File | null>((resolve) => {
                const tempCanvas = document.createElement('canvas');
                const tempCtx = tempCanvas.getContext('2d');
                if (!tempCtx) { resolve(null); return; }

                const img = new Image();
                let blobUrl = '';

                if (this.originalImage.file) {
                    blobUrl = URL.createObjectURL(this.originalImage.file);
                    img.src = blobUrl;
                } else if (this.originalImage.preview) {
                    img.crossOrigin = 'anonymous';
                    img.src = this.originalImage.preview;
                } else {
                    resolve(null);
                    return;
                }

                img.onerror = () => {
                    if (blobUrl) URL.revokeObjectURL(blobUrl);
                    resolve(null);
                };

                img.onload = () => {
                    tempCanvas.width = img.naturalWidth;
                    tempCanvas.height = img.naturalHeight;
                    tempCtx.drawImage(img, 0, 0, tempCanvas.width, tempCanvas.height);

                    const maskCtx = canvas.getContext('2d');
                    if (maskCtx) {
                        const scaledMaskCanvas = document.createElement('canvas');
                        scaledMaskCanvas.width = img.naturalWidth;
                        scaledMaskCanvas.height = img.naturalHeight;
                        const scaledMaskCtx = scaledMaskCanvas.getContext('2d');
                        if (scaledMaskCtx) {
                            scaledMaskCtx.imageSmoothingEnabled = true;
                            scaledMaskCtx.imageSmoothingQuality = 'high';
                            scaledMaskCtx.drawImage(canvas, 0, 0, canvas.width, canvas.height, 0, 0, scaledMaskCanvas.width, scaledMaskCanvas.height);
                            tempCtx.globalCompositeOperation = 'source-over';
                            tempCtx.drawImage(scaledMaskCanvas, 0, 0);
                        }
                    }

                    tempCanvas.toBlob((blob) => {
                        if (blobUrl) URL.revokeObjectURL(blobUrl);
                        if (blob) {
                            const file = new File([blob], 'mask.png', { type: 'image/png' });
                            // Also update maskImage state
                            if (this.maskImage?.preview) {
                                URL.revokeObjectURL(this.maskImage.preview);
                            }
                            this.maskImage = {
                                name: 'mask.png',
                                preview: URL.createObjectURL(blob),
                                file: file
                            };
                            resolve(file);
                        } else {
                            resolve(null);
                        }
                    }, 'image/png');
                };
            });
        },
        debouncedUpdateMask() {
            // Clear existing timeout
            if (this.updateMaskTimeout) {
                clearTimeout(this.updateMaskTimeout);
            }

            // Set new timeout to update mask after user stops drawing
            this.updateMaskTimeout = setTimeout(() => {
                this.updateMaskFromCanvas();
            }, 300) as any;
        },
        hexToRgba(hex: string, alpha: number = 1): string {
            // Remove the # if present
            hex = hex.replace('#', '');

            // Parse hex values
            const r = parseInt(hex.substr(0, 2), 16);
            const g = parseInt(hex.substr(2, 2), 16);
            const b = parseInt(hex.substr(4, 2), 16);

            return `rgba(${r}, ${g}, ${b}, ${alpha})`;
        },
        // Modal methods
        openImageModal(imageUrl: string, imageName: string) {
            this.modalImageUrl = imageUrl;
            this.modalImageName = imageName;
            this.showImageModal = true;

            // Add escape key listener
            document.addEventListener('keydown', this.handleEscapeKey);
        },
        closeImageModal() {
            this.showImageModal = false;
            this.modalImageUrl = '';
            this.modalImageName = '';

            // Remove escape key listener
            document.removeEventListener('keydown', this.handleEscapeKey);
        },
        handleEscapeKey(event: KeyboardEvent) {
            if (event.key === 'Escape') {
                this.closeImageModal();
            }
        },
        downloadImage() {
            if (!this.modalImageUrl) return;

            // Create a temporary link element and trigger download
            const link = document.createElement('a');
            link.href = this.modalImageUrl;
            link.download = this.modalImageName || 'image.png';
            link.target = '_blank';

            // Append to body, click, and remove
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        },
        async initFromSelection() {
            if (!this.selectedImages || this.selectedImages.length === 0) return;

            const imagesToProcess = this.selectedImages.slice(0, 10);

            // Step 1: Show preview immediately using CDN URL (no fetch needed)
            this.uploadedImages = imagesToProcess
                .map((item: any) => {
                    const imageUrl = item.value || item.thumbnail;
                    if (!imageUrl) return null;
                    const fileName = item.name || 'image.png';
                    return {
                        name: fileName,
                        preview: imageUrl, // Use CDN URL directly for instant preview
                        file: null as File | null, // Will be fetched in background
                        _loading: true // Flag to track background fetch status
                    };
                })
                .filter(img => img !== null) as any;

            // Step 2: Fetch blobs in background (non-blocking)
            this.uploadedImages.forEach(async (image: any, index: number) => {
                try {
                    const response = await window.fetch(image.preview);
                    const blob = await response.blob();
                    image.file = new File([blob], image.name, { type: blob.type || 'image/png' });
                    // Update preview to blob URL (avoids CORS issues)
                    image.preview = URL.createObjectURL(blob);
                } catch (e) {
                    console.error('Failed to fetch image:', image.preview, e);
                    // Keep the image in list but file stays null - processImage will handle this
                } finally {
                    image._loading = false;
                }
            });
        },
        async initMaskFromSelection() {
            if (!this.selectedImages || this.selectedImages.length === 0) return;

            const item = this.selectedImages[0] as any;
            const imageUrl = item.value || item.thumbnail;
            if (!imageUrl) return;

            const fileName = item.name || 'image.png';

            // Show preview immediately using CDN URL
            this.originalImage = {
                name: fileName,
                preview: imageUrl,
                file: null as any
            };

            // Fetch blob in background
            try {
                const response = await window.fetch(imageUrl);
                const blob = await response.blob();
                this.originalImage.file = new File([blob], fileName, { type: blob.type || 'image/png' });
                // Update preview to blob URL (avoids CORS issues)
                this.originalImage.preview = URL.createObjectURL(blob);
            } catch (e) {
                console.error('Failed to fetch image for mask:', imageUrl, e);
            }
        },
    },
    watch: {
        maskInputMode(newMode: 'upload' | 'draw') {
            // Clean up when switching between upload and draw modes
            if (newMode === 'upload') {
                // Clear canvas when switching to upload mode
                this.clearCanvas();
            } else if (newMode === 'draw') {
                // Clear uploaded mask when switching to draw mode
                if (this.maskImage?.preview) {
                    URL.revokeObjectURL(this.maskImage.preview);
                }
                this.maskImage = null;
                const fileInput = this.$refs.maskImageInput as HTMLInputElement;
                if (fileInput) {
                    fileInput.value = '';
                }
            }
        },
        mode(newMode: string) {
            // Sync images between edit and mask modes
            if (newMode === 'edit') {
                if (this.originalImage?.file) {
                    this.uploadedImages = [{
                        name: this.originalImage.name,
                        preview: this.originalImage.preview,
                        file: this.originalImage.file
                    }];
                } else if (this.uploadedImages.length === 0 && this.selectedImages?.length > 0) {
                    this.initFromSelection();
                }
            } else if (newMode === 'mask') {
                if (this.uploadedImages.length > 0 && this.uploadedImages[0].file) {
                    this.originalImage = {
                        name: this.uploadedImages[0].name,
                        preview: this.uploadedImages[0].preview,
                        file: this.uploadedImages[0].file
                    };
                } else if (!this.originalImage && this.selectedImages?.length > 0) {
                    this.initMaskFromSelection();
                }
            }
        }
    },

    mounted() {
        if (this.initialMode) {
            this.mode = this.initialMode as any;
        }

        if (this.mode === 'edit' && this.selectedImages && this.selectedImages.length > 0) {
            this.initFromSelection();
        } else if (this.mode === 'mask' && this.selectedImages && this.selectedImages.length > 0) {
            this.initMaskFromSelection();
        }

        this.generatedImages = Object.entries(aiImagesCache).map(([id, data]) => ({
            id,
            alt: data.name,
            mimeType: data.mimeType,
            url: URL.createObjectURL(data.blob),
            loading: !!data.loading
        }));
        this.$nextTick(() => {
            this.$store.dispatch('ai/init');
        });
    },
    beforeUnmount() {
        // Clean up preview URL to prevent memory leaks
        this.uploadedImages.forEach(image => {
            if (image.preview) {
                URL.revokeObjectURL(image.preview);
            }
        });

        // Clean up mask image previews
        if (this.originalImage?.preview) {
            URL.revokeObjectURL(this.originalImage.preview);
        }
        if (this.maskImage?.preview) {
            URL.revokeObjectURL(this.maskImage.preview);
        }

        // Clean up generated image URLs
        this.generatedImages.forEach(image => {
            if (image.url) {
                URL.revokeObjectURL(image.url);
            }
        });

        // Clean up timeout
        if (this.updateMaskTimeout) {
            clearTimeout(this.updateMaskTimeout);
        }
    }
}
</script>
