// KeyboardHandler.ts
import type {
  GridItemInstance,
  KeyboardOptions,
  KeyboardEvents,
  KeyboardEventData,
  KeyboardState
} from './types';
import { ensureNumericValue } from '../../helpers/utils';

export class KeyboardHandler {
  private instance: GridItemInstance;
  private options: KeyboardOptions;
  private events: KeyboardEvents;
  private keyboardState: KeyboardState;
  private _keydownHandler: ((e: KeyboardEvent) => void) | null = null;
  private _keyupHandler: ((e: KeyboardEvent) => void) | null = null;

  constructor(instance: GridItemInstance, options: KeyboardOptions = {}, events: KeyboardEvents = {}) {
    this.instance = instance;
    this.options = {
      enableKeyboard: true,
      initialDelay: 500,
      repeatDelay: 50,
      shiftMultiplier: 5,
      normalStep: 1,
      ...options
    };
    this.events = events;

    this.keyboardState = {
      isKeyPressed: false,
      currentKey: null,
      moveInterval: null,
      moveTimeout: null,
      initialDelay: this.options.initialDelay!,
      repeatDelay: this.options.repeatDelay!,
      isListening: false
    };

    this.bindMethods();
  }

  private bindMethods(): void {
    this.handleKeyDown = this.handleKeyDown.bind(this);
    this.handleKeyUp = this.handleKeyUp.bind(this);
    this.moveByKeyboard = this.moveByKeyboard.bind(this);
    this.startContinuousMove = this.startContinuousMove.bind(this);
    this.stopKeyboardMove = this.stopKeyboardMove.bind(this);
  }

  public handleKeyDown(e: KeyboardEvent): void {
    try {
      // Chỉ xử lý khi element này đang được active
      if (!this.instance.isEditing && !this.instance.gridActive) {
        return;
      }

      // Kiểm tra các phím mũi tên
      const arrowKeys = ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"];
      if (!arrowKeys.includes(e.key)) {
        return;
      }

      // Ngăn chặn event bubbling để tránh xung đột với extension
      if(this.instance.inGroup) return;
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      // Nếu phím đang được nhấn, không xử lý lại
      if (this.keyboardState.isKeyPressed && this.keyboardState.currentKey === e.key) {
        return;
      }

      // Dừng di chuyển hiện tại nếu có
      this.stopKeyboardMove();

      // Cập nhật trạng thái phím
      this.keyboardState.isKeyPressed = true;
      this.keyboardState.currentKey = e.key;

      // Di chuyển ngay lập tức
      this.moveByKeyboard(e.key, e.shiftKey);

      // Thiết lập di chuyển liên tục sau một khoảng thời gian
      this.keyboardState.moveTimeout = setTimeout(() => {
        this.startContinuousMove(e.key, e.shiftKey);
      }, this.keyboardState.initialDelay);

      // Emit keyboard start event
      const keyboardEventData: KeyboardEventData = {
        eventType: 'keyboardstart',
        i: this.instance.i,
        section_id: this.instance.sectionId,
        key: e.key,
        shiftKey: e.shiftKey,
        x: ensureNumericValue(this.instance.innerLeft),
        y: ensureNumericValue(this.instance.innerTop)
      };

      this.instance.eventBus.emit("keyboardEvent", keyboardEventData);

      if (this.events.onKeyboardStart) {
        this.events.onKeyboardStart(keyboardEventData);
      }
    } catch (error) {
      console.warn("Keyboard navigation error:", error);
      // Dừng di chuyển nếu có lỗi
      this.stopKeyboardMove();
    }
  }

  public handleKeyUp(e: KeyboardEvent): void {
    try {
      // Chỉ xử lý khi element này đang được active
      if (!this.instance.isEditing && !this.instance.gridActive) return;

      const arrowKeys = ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"];
      if (!arrowKeys.includes(e.key)) return;

      // Nếu không phải phím hiện tại, bỏ qua
      if (this.keyboardState.currentKey !== e.key) return;

      // Ngăn chặn event bubbling
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      // Dừng di chuyển
      this.stopKeyboardMove();

      // Emit sự kiện moved để lưu vị trí mới
      this.instance.$emit("moved", this.instance.i, this.instance.innerLeft, this.instance.innerTop);

      // Emit dragend event để đồng bộ với hệ thống drag drop
      this.instance.emitDragEvent("dragend", ensureNumericValue(this.instance.innerLeft), ensureNumericValue(this.instance.innerTop));

      // Emit keyboard end event
      const keyboardEventData: KeyboardEventData = {
        eventType: 'keyboardend',
        i: this.instance.i,
        section_id: this.instance.sectionId,
        key: e.key,
        shiftKey: e.shiftKey,
        x: ensureNumericValue(this.instance.innerLeft),
        y: ensureNumericValue(this.instance.innerTop)
      };

      this.instance.eventBus.emit("keyboardEvent", keyboardEventData);

      if (this.events.onKeyboardEnd) {
        this.events.onKeyboardEnd(keyboardEventData);
      }
    } catch (error) {
      console.warn("Keyboard navigation keyup error:", error);
      this.stopKeyboardMove();
    }
  }

  public moveByKeyboard(key: string, isShiftPressed: boolean): void {
    try {
      // Khoảng cách di chuyển
      const step = isShiftPressed ? this.options.shiftMultiplier! : this.options.normalStep!;

      // Tính toán vị trí mới
      let newLeft = ensureNumericValue(this.instance.innerLeft);
      let newTop = ensureNumericValue(this.instance.innerTop);

      // Lấy kích thước container để tính toán giới hạn
      const containerWidth = this.instance.gridContainerWidth;
      const itemWidth = this.instance.isPercentWidth
        ? ensureNumericValue(this.instance.innerWidth)
        : (ensureNumericValue(this.instance.innerWidth) / containerWidth) * 100;

      switch (key) {
        case "ArrowLeft":
          newLeft = Math.max(0, newLeft - (step / containerWidth) * 100);
          break;
        case "ArrowRight":
          newLeft = Math.min(
            100 - itemWidth,
            newLeft + (step / containerWidth) * 100
          );
          break;
        case "ArrowUp":
          newTop = Math.max(0, newTop - step);
          break;
        case "ArrowDown":
          newTop = newTop + step;
          break;
      }

      // Cập nhật vị trí
      this.instance.innerLeft = newLeft;
      this.instance.innerTop = newTop;

      // Emit sự kiện move
      this.instance.$emit("move", this.instance.i, newLeft, newTop);
      this.instance.emitDragEvent("dragmove", newLeft, newTop);

      // Emit keyboard move event
      const keyboardEventData: KeyboardEventData = {
        eventType: 'keyboardmove',
        i: this.instance.i,
        section_id: this.instance.sectionId,
        key: key,
        shiftKey: isShiftPressed,
        x: newLeft,
        y: newTop
      };

      this.instance.eventBus.emit("keyboardEvent", keyboardEventData);

      if (this.events.onKeyboardMove) {
        this.events.onKeyboardMove(keyboardEventData);
      }
    } catch (error) {
      console.warn("Move by keyboard error:", error);
      this.stopKeyboardMove();
    }
  }

  public startContinuousMove(key: string, isShiftPressed: boolean): void {
    try {
      this.keyboardState.moveInterval = setInterval(() => {
        if (this.keyboardState.isKeyPressed && this.keyboardState.currentKey === key) {
          this.moveByKeyboard(key, isShiftPressed);
        } else {
          this.stopKeyboardMove();
        }
      }, this.keyboardState.repeatDelay);
    } catch (error) {
      console.warn("Continuous move error:", error);
      this.stopKeyboardMove();
    }
  }

  public stopKeyboardMove(): void {
    try {
      // Clear timeout và interval
      if (this.keyboardState.moveTimeout) {
        clearTimeout(this.keyboardState.moveTimeout);
        this.keyboardState.moveTimeout = null;
      }

      if (this.keyboardState.moveInterval) {
        clearInterval(this.keyboardState.moveInterval);
        this.keyboardState.moveInterval = null;
      }

      // Reset trạng thái
      this.keyboardState.isKeyPressed = false;
      this.keyboardState.currentKey = null;
    } catch (error) {
      console.warn("Stop keyboard move error:", error);
    }
  }

  public addKeyboardListeners(): void {
    try {
      // Tránh thêm listeners duplicate
      if (this.keyboardState.isListening) {
        return;
      }

      // Sử dụng document của iframe nếu có, nếu không thì dùng document chính
      const iframeDoc = this.instance.idoc;

      // Tạo wrapper functions
      this._keydownHandler = this.handleKeyDown.bind(this);
      this._keyupHandler = this.handleKeyUp.bind(this);

      // Thêm listeners vào iframe document
      const docs = [iframeDoc];
      docs.forEach((doc) => {
        if (doc) {
          doc.addEventListener("keydown", this._keydownHandler!, {
            passive: false,
            capture: true
          });

          doc.addEventListener("keyup", this._keyupHandler!, {
            passive: false,
            capture: true
          });
        }
      });

      // Thử focus vào iframe document nếu cần
      if (iframeDoc && iframeDoc.body) {
        iframeDoc.body.setAttribute("tabindex", "-1");
        setTimeout(() => {
          iframeDoc.body.focus();
        }, 100);
      }

      this.keyboardState.isListening = true;
    } catch (error) {
      console.warn(`[GridItem ${this.instance.i}] Add keyboard listeners error:`, error);
    }
  }

  public removeKeyboardListeners(): void {
    try {
      if (!this.keyboardState.isListening) return;

      const iframeDoc = this.instance.idoc;
      const mainDoc = document;
      const docs = [iframeDoc, mainDoc];

      docs.forEach((doc) => {
        if (doc) {
          if (this._keydownHandler) {
            doc.removeEventListener("keydown", this._keydownHandler, {
              capture: true
            });
          }

          if (this._keyupHandler) {
            doc.removeEventListener("keyup", this._keyupHandler, {
              capture: true
            });
          }
        }
      });

      this._keydownHandler = null;
      this._keyupHandler = null;
      this.keyboardState.isListening = false;
    } catch (error) {
      console.warn("Remove keyboard listeners error:", error);
    }
  }

  public ensureKeyboardListeners(): void {
    try {
      if (!this.instance.exporting && (this.instance.isEditing || this.instance.gridActive)) {
        if (!this.keyboardState.isListening) {
          this.addKeyboardListeners();
        }
      } else {
        if (this.keyboardState.isListening) {
          this.removeKeyboardListeners();
          this.stopKeyboardMove();
        }
      }
    } catch (error) {
      console.warn("Ensure keyboard listeners error:", error);
    }
  }

  public destroy(): void {
    // Dừng di chuyển keyboard nếu đang diễn ra
    this.stopKeyboardMove();

    // Xóa keyboard listeners
    this.removeKeyboardListeners();

    // Reset keyboard state
    this.keyboardState = {
      isKeyPressed: false,
      currentKey: null,
      moveInterval: null,
      moveTimeout: null,
      initialDelay: 500,
      repeatDelay: 50,
      isListening: false
    };
  }
}