<template>
    <div class="ecom-element ecom-product-single ecom-product-single__buy_now_btn" :data-preview-mode="exporting.toString()" v-bind="classFullHeight">
        <div class="ecom-product-single__buy_now_btn-wrapper"  v-bind="classFullHeight">
            <div class="ecom-product-single__buy_now_btn-container"  v-bind="classFullHeight">
                <div class="ecom-product-single__buy_now_btn-buttons"  v-bind="classFullHeight">
                    <div class="ecom-product-single__buy_now_btn-buttons-wrapper"  v-bind="classFullHeight">
                    <div
                        class="ecom-product-single__buy_now_btn--dynamic-checkout"
                         v-bind="classFullHeight"
                        :class="animatedClass"
                        v-html="liquid('dynamic_checkout')"
                    />
                </div>
            </div>
        </div>
    </div>
  </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'productBuyItNow',
    linkVideo: 'https://www.youtube.com/watch?v=HSVQBHA7l00',
    mixins: [Liquid, Javascript, Element],
    props: {

        data: {
            type: Object,
            default() {
                return {
                };
            }
        }
    },
    data(){
        return {
            jsreactives: [
                'animation_loop_time', 'animation'
            ]
        }
    },
    computed: {
        classFullHeight() {
            const attrs = {
                class: {
                    'ecom-ingrid-full-height': this.data.inGrid,
                },
            };
            return attrs;
        },
        javascript() {
            return function () {
                if(!this.$el)
                {
                    return false;
                }

                const $el = this.$el;
                const $wrapper = $el.closest('.ecom-product-form--single');

                if (!$wrapper) {
                    return false;
                }

                if (!this.isLive ||  $wrapper.dataset.previewMode === 'preview' || window.EComposer.hasOwnProperty('DEMO')) {
                    const checkoutBtn = $el.querySelector(
                        '.shopify-payment-button__button'
                    );
                    if (checkoutBtn) {
                        checkoutBtn.innerText = 'Buy it now';
                        checkoutBtn.classList.remove('shopify-payment-button__button--hidden');
                        checkoutBtn.removeAttribute('disabled');
                    }

                }

                const product_id = $wrapper.dataset.product_id;
                    if(!product_id) return;
                    let product = null;
                    const json = $wrapper.querySelector('[id^=product-json-' + product_id + ']');
                    if (!json) {
                        return;
                    }
                    try {
                        product = JSON.parse(json.innerHTML);
                    } catch (e) {

                    }

                if(this.isLive)
                {
                    const buyNowBtn = $el.querySelector('.ecom-product-single__buy_now_btn--dynamic-checkout .shopify-payment-button');
                    if(buyNowBtn) {
                        buyNowBtn.addEventListener('click', function(){
                            let quantity = 1;
                            if($wrapper.querySelector('[name=quantity]')){
                                quantity = $wrapper.querySelector('[name=quantity]').value;
                            }
                            let id = $wrapper.querySelector('[name=id]').value;
                            const variantCount = $wrapper.querySelector('[name=id]') ? parseInt($wrapper.querySelector('[name=id]').getAttribute('ec-variants')) : 0;
                            const isHighVariantProduct = variantCount > 250 || $wrapper.querySelector('[data-high-variant-product]');


                            let variant = null;
                            if(isHighVariantProduct) {
                                variant = product;
                            }
                            else {
                                variant = product.variants.find(variant => variant.id == id);
                            }
                            if(!variant || variant.available === false){
                                return;
                            }
                            if(window.omegaCallBackCheckout && typeof window.omegaCallBackCheckout == "function")  { window.omegaCallBackCheckout(); }

                            if(window.Shopify.analytics)
                            {
                                Shopify.analytics.publish("ec_buy_now",   {
                                    "cartLine": {
                                        "cost": {
                                            "totalAmount": {
                                                "amount": variant.price * quantity,
                                                "currencyCode": window.Shopify.currency.active
                                            }
                                        },
                                        "merchandise": {
                                            "id": variant.id,
                                            "image": variant.image,
                                            "price": {
                                                "amount": variant.price,
                                                "currencyCode": window.Shopify.currency.active
                                            },
                                            "product": {
                                                "id":  product.id,
                                                "title":  product.title,
                                                "vendor": product.vendor
                                            },
                                            "sku": variant.sku,
                                            "title": variant.title
                                        },
                                        "quantity": quantity
                                    }
                                })
                            }
                        });


                    }
                }

                const handleAnimation = function(_this) {
                  if (!$el) return;

                  const $btn_wrapper = $el.querySelector('.ecom-product-single__buy_now_btn--dynamic-checkout');
                   if (!$btn_wrapper) return;

                  let intervalTime = parseInt(_this.settings.animation_loop_time) * 1000 || 6000,
                      animTime = 1000;

                  setInterval(function() {
                      $btn_wrapper.classList.add('animated');
                      setTimeout(function(){
                        $btn_wrapper.classList.remove('animated');
                      }, animTime);
                  }, intervalTime);
                }

                if (this.settings.animation) {
                  handleAnimation(this);
                }
            };
        },
        animatedClass() {
          return this.data?.settings?.animation ? 'animated' : '';
        },
        liquids() {
            return {
                dynamic_checkout: {
                    code: `${this.exporting === true ? `{{ form | payment_button }}` : `<div data-shopify="payment-button" class="shopify-payment-button">
                            <button class="shopify-payment-button__button shopify-payment-button__button--unbranded shopify-payment-button__button--hidden ${this.data.inGrid ? 'ecom-ingrid-full-height' : ''}" aria-hidden="true">Buy it now</button>
                            <button class="shopify-payment-button__more-options shopify-payment-button__button--hidden" disabled="disabled" aria-hidden="true">&nbsp;</button>
                        </div>`}
                        `,
                    preview: `
                        <div data-shopify="payment-button" class="shopify-payment-button">
                            <button class="shopify-payment-button__button shopify-payment-button__button--unbranded shopify-payment-button__button--hidden ${this.data.inGrid ? 'ecom-ingrid-full-height' : ''}" aria-hidden="true">Buy it now</button>
                            <button class="shopify-payment-button__more-options shopify-payment-button__button--hidden" disabled="disabled" aria-hidden="true">&nbsp;</button>
                        </div>
                        `
                }
            };
        },
        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },
        css() {
          return `
            .ecom-product-single__buy_now_btn .shopify-payment-button__button--unbranded:after,
            .shopify-payment-button__more-options.shopify-payment-button__button--hidden {
              display: none;
            }
            .shopify-payment-button > button {
                width: 100%;
            }
            .ecom-product-single__buy_now_btn--dynamic-checkout {
                display: flex;
            }
            .ecom-ingrid-full-height > .shopify-payment-button {
                width: 100%;
                height: 100%;
            }
          `;
        },
        settings() {
            return [
                {
                    params: [
                        {
                            type: 'paragraph',
                            options: {
                                warnings: {
                                    content: this.$t('the_element_will_not_work_with_the_subscription_options_and_the_properties_product_element')
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'animation',
                            label: this.$t('button_animation'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('enable'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('disable'),
                                        value: false
                                    }
                                }
                            },
                        },
                        {
                          type: "number",
                          label: this.$t('loop_time_span_class_lowercase_s_span'),
                          name: "animation_loop_time",
                          options: {
                              min: 2,
                              default: 6,
                              max: 10,
                              visible: function (data) {
                                  return data.animation == true;
                              }
                          }
                      },
                      {
                            type:'line'
                        },
                        {
                            type:'paragraph',
                            content: this.$t('integrated_with_omega_facebook_pixel_https_apps_shopify_com_facebook_multi_pixels_surface_detail_e_catc_surface_type_partner')

                        }
                    ]
                }
            ];
        },
        default() {
            return {
                "settings": {
                    "animation": true,
                    "animation_loop_time": 3
                },
                "style": {
                    "dynamic_checkout_button": {
                        "tab": "normal",
                        "spacing": {
                            "padding": {
                                "top": "12.5px",
                                "left": "50px",
                                "bottom": "12.5px",
                                "right": "50px"
                            }
                        },
                        "buttonTypography": {
                            "text-transform": "uppercase"
                        },
                        "buttonColornormalmode": "#FFF",
                        "buttonBackgroundnormalmode": {
                            "classic": {
                                "background-color": "#0691b1"
                            }
                        },
                        "buttonBordernormalmode": {
                            "border-style": "none"
                        },
                        "buttonBackgroundhovermode": {
                            "classic": {
                                "background-color": "#12bbe0"
                            }
                        },
                        "transition": {
                            "transition": {
                                "duration": "300ms",
                                "timing": "ease"
                            }
                        },
                        "align-items": "center",
                        "buttonBorderRadiushovermode": {
                            "top": "3px",
                            "left": "3px",
                            "bottom": "3px",
                            "right": "3px"
                        },
                        "buttonBorderRadiusnormalmode": {
                            "right": "3px",
                            "top": "3px",
                            "left": "3px",
                            "bottom": "3px"
                        }
                    },
                    "button_animation": {
                        "animation": "shake"
                    }
                }
            }
        }
    },
    methods: {
        style() {
            const inGrid = this.data.inGrid || false;
            const params = [
                {
                    group_alias: `button${inGrid ? ':grid' : ''}`,
                    options:{
                        group_title: this.$t('button'),
                        group_name: 'dynamic_checkout_button',
                        selector:' .ecom-product-single__buy_now_btn .shopify-payment-button .shopify-payment-button__button--unbranded, .ecom-product-single__buy_now_btn .shopify-payment-button__skeleton',
                    },
                    modify:{
                        remove:  !inGrid ?[
                            {index: 6, length: 1},
                            {index: 11, length: 1}
                        ] : [],
                        params: !inGrid ?[
                            {
                                position:0,
                                fields: [

                                    {
                                        alias: 'width',
                                        options: {
                                            label: this.$t('width'),
                                            css: {
                                                selector: 'root .shopify-payment-button'
                                            }
                                        }
                                    },
                                    {
                                        alias:'align-items',
                                        options:{
                                            label: this.$t('alignment'),
                                            css:{
                                                selector:'root .ecom-product-single__buy_now_btn--dynamic-checkout',
                                                properties:{
                                                    'align-items':'',
                                                    'justify-content':''
                                                }
                                            }
                                        }
                                    }
                                ]
                            },
                        ] : []
                    }
                },
                {
                  group_name: 'button_animation',
                  group_title: this.$t('animation_effect'),
                  selector: ' .ecom-product-single__buy_now_btn--dynamic-checkout',
                  params: [
                      {
                        name: "animation",
                        label: this.$t('animation'),
                        type: "popup",
                        options: {
                            type: "dropdown",
                            prevew: 'title',
                            values: {
                                'fading': this.$t('fading'),
                                'fade-in': this.$t('fade_in'),
                                'fade-in-down': this.$t('fade_in_down'),
                                'fade-in-left': this.$t('fade_in_left'),
                                'fade-in-right': this.$t('fade_in_right'),
                                'fade-in-up': this.$t('fade_in_up'),
                                'zooming': this.$t('zooming'),
                                'zoom-in': this.$t('zoom_in'),
                                'zoom-in-down': this.$t('zoom_in_down'),
                                'zoom-in-left': this.$t('zoom_in_left'),
                                'zoom-in-right': this.$t('zoom_in_right'),
                                'zoom-in-up': this.$t('zoom_in_up'),
                                'bouncing': this.$t('bouncing'),
                                'bounce-in': this.$t('bounce_in'),
                                'bounce-in-down': this.$t('bounce_in_down'),
                                'bounce-in-left': this.$t('bounce_in_left'),
                                'bounce-in-right': this.$t('bounce_in_right'),
                                'bounce-in-up': this.$t('bounce_in_up'),
                                'sliding': this.$t('sliding'),
                                'sliding-in': this.$t('sliding_in'),
                                'sliding-in-down': this.$t('sliding_in_down'),
                                'sliding-in-left': this.$t('sliding_in_left'),
                                'sliding-in-right': this.$t('sliding_in_right'),
                                'sliding-in-up': this.$t('sliding_in_up'),
                                'rotate': this.$t('rotate'),
                                'rotate-in': this.$t('rotate_in'),
                                'rotate-in-down': this.$t('rotate_in_down'),
                                'rotate-in-left': this.$t('rotate_in_left'),
                                'rotate-in-right': this.$t('rotate_in_right'),
                                'rotate-in-up': this.$t('rotate_in_up'),
                                'attention-seekers': this.$t('attention_seekers'),
                                'bounce': this.$t('bounce'),
                                'flash': this.$t('flash'),
                                'pulse': this.$t('pulse'),
                                'rubber-band': this.$t('rubber_band'),
                                'shake': this.$t('shake'),
                                'head-shake': this.$t('head_shake'),
                                'heart-beat': this.$t('heart_beat'),
                                'swing': this.$t('swing'),
                                'tada': this.$t('tada'),
                                'wobble': this.$t('wobble'),
                                'jello': this.$t('jello'),
                                'light-speed ': this.$t('light_speed'),
                                'light-speed-in': this.$t('light_speed_in'),
                                'specials': this.$t('specials'),
                                'roll-in': this.$t('roll_in'),
                                'shake-y': this.$t('shake_y'),
                                'back-in-down': this.$t('back_in_down'),
                                'back-in-left': this.$t('back_in_left'),
                                'back-in-right': this.$t('back_in_right'),
                                'back-in-up': this.$t('back_in_up'),
                                'flip': this.$t('flip'),
                                'flip-x': this.$t('flip_x'),
                                'flip-y': this.$t('flip_y'),
                                'light-speed-in-right': this.$t('light_speed_in_right'),
                                'light-speed-in-left': this.$t('light_speed_in_left'),
                                'roll': this.$t('roll'),
                            },
                            size: "small",
                        },
                        css: {
                            selector: ".animated",
                            properties: {
                                'entrance-animation': ""
                            }
                        }
                    },
                  ]
              }
            ];

            return params;
        }

    }
};
</script>
