// GuidelineUtils.ts
import { ensureNumericValue } from '../../../helpers/utils';
import type { GridLayoutInstance } from '../types/GridLayoutTypes';

export interface GuidelineState {
  centerV: boolean;
  centerH: boolean;
  sameV: Array<{
    i: string;
    x: number;
    y: number;
    w: number;
    h: number;
    type: string;
  }>;
  sameH: Array<{
    i: string;
    x: number;
    y: number;
    w: number;
    h: number;
    type: string;
  }>;
  guideLineLeft: number;
  guideLineRight: number;
  guideLineX: {
    x: number;
    y: number;
    w: number;
    direction?: string;
  };
  guideLineY: {
    x: number;
    y: number;
    h: number;
    direction?: string;
  };
  guideLineXDistance: number;
  guideLineYDistance: number;
  nearbyItems: {
    left: any;
    right: any;
    top: any;
    bottom: any;
  };
  distanceGuides: {
    left: { x: number; y: number; w: number; h: number; distance: number; visible: boolean };
    right: { x: number; y: number; w: number; h: number; distance: number; visible: boolean };
    top: { x: number; y: number; w: number; h: number; distance: number; visible: boolean };
    bottom: { x: number; y: number; w: number; h: number; distance: number; visible: boolean };
  };
  maxGuideDistance: number;
}

export interface PlaceholderItem {
  i: string;
  left: number;
  top: number;
  width: number;
  height: number;
  rotation?: number;
  dirX?: string;
  dirY?: string;
  snapEdge?: string;
  snapEdgeRight?: string;
  snapColIndex?: number;
  snapColIndexRight?: number;
}

export class GuidelineUtils {
  private instance: GridLayoutInstance;
  private state: GuidelineState;
  private _guideUpdateRAF: number | null = null;

  constructor(instance: GridLayoutInstance) {
    this.instance = instance;
    this.state = this.initializeState();
  }

  private initializeState(): GuidelineState {
    return {
      centerV: false,
      centerH: false,
      sameV: [],
      sameH: [],
      guideLineLeft: 0,
      guideLineRight: 0,
      guideLineX: { x: 0, y: 0, w: 0 },
      guideLineY: { x: 0, y: 0, h: 0 },
      guideLineXDistance: 0,
      guideLineYDistance: 0,
      nearbyItems: { left: null, right: null, top: null, bottom: null },
      distanceGuides: {
        left: { x: 0, y: 0, w: 0, h: 0, distance: 0, visible: false },
        right: { x: 0, y: 0, w: 0, h: 0, distance: 0, visible: false },
        top: { x: 0, y: 0, w: 0, h: 0, distance: 0, visible: false },
        bottom: { x: 0, y: 0, w: 0, h: 0, distance: 0, visible: false }
      },
      maxGuideDistance: 100
    };
  }

  // Getter methods để component có thể access state
  get centerV(): boolean { return this.state.centerV; }
  get centerH(): boolean { return this.state.centerH; }
  get sameV(): typeof this.state.sameV { return this.state.sameV; }
  get sameH(): typeof this.state.sameH { return this.state.sameH; }
  get guideLineLeft(): number { return this.state.guideLineLeft; }
  get guideLineRight(): number { return this.state.guideLineRight; }
  get guideLineX(): typeof this.state.guideLineX { return this.state.guideLineX; }
  get guideLineY(): typeof this.state.guideLineY { return this.state.guideLineY; }
  get guideLineXDistance(): number { return this.state.guideLineXDistance; }
  get guideLineYDistance(): number { return this.state.guideLineYDistance; }
  get nearbyItems(): typeof this.state.nearbyItems { return this.state.nearbyItems; }
  get distanceGuides(): typeof this.state.distanceGuides { return this.state.distanceGuides; }

  /**
   * Main method để update tất cả guidelines dựa trên placeholder hiện tại
   */
  public updateGuidelines(placeholder: PlaceholderItem): void {
    // Validation - đảm bảo placeholder có đủ properties cần thiết
    if (!placeholder ||
        placeholder.left === undefined ||
        placeholder.top === undefined ||
        placeholder.width === undefined ||
        placeholder.height === undefined) {
      return;
    }

    const isDraggingOrResizing = this.instance.isDraggingGrid || this.instance.isResizing || this.instance.isGroupDragging;

    if (isDraggingOrResizing && !this.instance.isDraggingMultiple) {
      if (this._guideUpdateRAF) {
        cancelAnimationFrame(this._guideUpdateRAF);
      }

      this._guideUpdateRAF = requestAnimationFrame(() => {
        this.performGuidelineUpdates(placeholder);
        this._guideUpdateRAF = null;
      });
    } else {
      this.performGuidelineUpdates(placeholder);
    }
  }

  private performGuidelineUpdates(placeholder: PlaceholderItem): void {
    // Double check validation
    if (!placeholder ||
        placeholder.left === undefined ||
        placeholder.top === undefined ||
        placeholder.width === undefined ||
        placeholder.height === undefined) {
      return;
    }

    const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
    const containerHeight = this.getGridHeight();

    // 1. Update center alignment
    this.updateCenterAlignment(placeholder, containerWidth, containerHeight);

    // 2. Update alignment guides với other items
    if (this.instance.isDragDifferent !== true) {
      this.updateAlignmentGuides(placeholder, containerWidth);
      this.updateDistanceGuideLines(placeholder);

      if (this.instance.isDraggingGrid) {
        this.findNearbyItems(placeholder);
      }
    }

    // 3. Update column snap guides
    if (this.instance.isDraggingGrid || this.instance.isResizing) {
      this.updateColumnSnapGuides(placeholder);
    }
  }

  /**
   * Update center alignment guides
   */
  private updateCenterAlignment(placeholder: PlaceholderItem, containerWidth: number, containerHeight: number): void {
    const leftPx = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const topPx = ensureNumericValue(placeholder.top);
    const heightPx = ensureNumericValue(placeholder.height);

    const centerXItemPx = leftPx + widthPx / 2;
    const centerYItemPx = topPx + heightPx / 2;
    const centerXPx = containerWidth / 2;
    const centerYPx = containerHeight / 2;

    this.state.centerV = this.between(centerXItemPx, centerXPx, 5);
    this.state.centerH = this.between(centerYItemPx, centerYPx, 5);
  }

  /**
   * Update alignment guides với other items
   */
  public updateAlignmentGuides(placeholder: PlaceholderItem, containerWidth: number): void {
    let sameH: typeof this.state.sameH = [];
    let sameV: typeof this.state.sameV = [];

    if (!placeholder || !this.instance.layout || this.instance.layout.length === 0) {
      this.state.sameH = sameH;
      this.state.sameV = sameV;
      return;
    }

    // Check if this is group placeholder
    const isGroupPlaceholder = placeholder.i && placeholder.i.startsWith("group-");
    let groupItems: string[] = [];

    if (isGroupPlaceholder) {
      const groupId = placeholder.i.replace("group-", "");
      const section = this.instance.sections.find((s: any) => s.id === this.instance.section_id);
      const group = section?.groups?.[groupId];
      if (group && group.blocks) {
        groupItems = group.blocks;
      }
    }

    const tolerance = 3;
    const leftPx = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const rightPx = leftPx + widthPx;
    const topPx = ensureNumericValue(placeholder.top);
    const heightPx = ensureNumericValue(placeholder.height);
    const bottomPx = topPx + heightPx;
    const centerXPx = leftPx + widthPx / 2;
    const centerYPx = topPx + heightPx / 2;

    this.instance.layout.forEach((l: any) => {
      if (placeholder.i === l.i) return;
      if (isGroupPlaceholder && groupItems.includes(l.i)) return;

      const itemLeftPx = (ensureNumericValue(l.left) / 100) * containerWidth;
      let itemWidthPx;
      if (typeof l.width === "string" && l.width.endsWith("%")) {
        itemWidthPx = (parseFloat(l.width) / 100) * containerWidth;
      } else {
        itemWidthPx = ensureNumericValue(l.width);
      }
      const itemRightPx = itemLeftPx + itemWidthPx;
      const itemTopPx = ensureNumericValue(l.top);
      const itemHeightPx = ensureNumericValue(l.height);
      const itemBottomPx = itemTopPx + itemHeightPx;
      const itemCenterXPx = itemLeftPx + itemWidthPx / 2;
      const itemCenterYPx = itemTopPx + itemHeightPx / 2;

      // Basic edge alignment
      this.checkEdgeAlignment(
        { leftPx, rightPx, topPx, bottomPx, centerXPx, centerYPx },
        { itemLeftPx, itemRightPx, itemTopPx, itemBottomPx, itemCenterXPx, itemCenterYPx },
        l.i, tolerance, containerWidth, sameH, sameV
      );
    });

    this.state.sameH = sameH;
    this.state.sameV = sameV;
  }

  private checkEdgeAlignment(
    current: { leftPx: number; rightPx: number; topPx: number; bottomPx: number; centerXPx: number; centerYPx: number },
    item: { itemLeftPx: number; itemRightPx: number; itemTopPx: number; itemBottomPx: number; itemCenterXPx: number; itemCenterYPx: number },
    itemId: string,
    tolerance: number,
    containerWidth: number,
    sameH: any[],
    sameV: any[]
  ): void {
    const { leftPx, rightPx, topPx, bottomPx, centerXPx, centerYPx } = current;
    const { itemLeftPx, itemRightPx, itemTopPx, itemBottomPx, itemCenterXPx, itemCenterYPx } = item;

    // Top alignment
    if (this.between(topPx, itemTopPx, tolerance)) {
      const minLeft = Math.min(leftPx, itemLeftPx);
      const maxRight = Math.max(rightPx, itemRightPx);
      sameH.push({
        i: itemId,
        y: itemTopPx,
        h: 1,
        x: (minLeft / containerWidth) * 100,
        w: ((maxRight - minLeft) / containerWidth) * 100,
        type: "top"
      });
    }

    // Bottom alignment
    if (this.between(bottomPx, itemBottomPx, tolerance)) {
      const minLeft = Math.min(leftPx, itemLeftPx);
      const maxRight = Math.max(rightPx, itemRightPx);
      sameH.push({
        i: itemId,
        y: itemBottomPx,
        h: 1,
        x: (minLeft / containerWidth) * 100,
        w: ((maxRight - minLeft) / containerWidth) * 100,
        type: "bottom"
      });
    }

    // Left alignment
    if (this.between(leftPx, itemLeftPx, tolerance)) {
      const minTop = Math.min(topPx, itemTopPx);
      const maxBottom = Math.max(bottomPx, itemBottomPx);
      sameV.push({
        i: itemId,
        x: (itemLeftPx / containerWidth) * 100,
        w: 1,
        y: minTop,
        h: maxBottom - minTop,
        type: "left"
      });
    }

    // Right alignment
    if (this.between(rightPx, itemRightPx, tolerance)) {
      const minTop = Math.min(topPx, itemTopPx);
      const maxBottom = Math.max(bottomPx, itemBottomPx);
      sameV.push({
        i: itemId,
        x: (itemRightPx / containerWidth) * 100,
        w: 1,
        y: minTop,
        h: maxBottom - minTop,
        type: "right"
      });
    }

    // Center alignments (10 more cases as in original code)
    this.checkCenterAlignments(current, item, itemId, tolerance, containerWidth, sameH, sameV);
  }

  private checkCenterAlignments(
    current: { leftPx: number; rightPx: number; topPx: number; bottomPx: number; centerXPx: number; centerYPx: number },
    item: { itemLeftPx: number; itemRightPx: number; itemTopPx: number; itemBottomPx: number; itemCenterXPx: number; itemCenterYPx: number },
    itemId: string,
    tolerance: number,
    containerWidth: number,
    sameH: any[],
    sameV: any[]
  ): void {
    const { leftPx, rightPx, topPx, bottomPx, centerXPx, centerYPx } = current;
    const { itemLeftPx, itemRightPx, itemTopPx, itemBottomPx, itemCenterXPx, itemCenterYPx } = item;

    // Center to edges (4 cases)
    if (this.between(centerXPx, itemLeftPx, tolerance)) {
      sameV.push({
        i: itemId,
        x: (itemLeftPx / containerWidth) * 100,
        w: 1,
        y: Math.min(topPx, itemTopPx),
        h: Math.max(bottomPx, itemBottomPx) - Math.min(topPx, itemTopPx),
        type: "center-to-left"
      });
    }

    if (this.between(centerXPx, itemRightPx, tolerance)) {
      sameV.push({
        i: itemId,
        x: (itemRightPx / containerWidth) * 100,
        w: 1,
        y: Math.min(topPx, itemTopPx),
        h: Math.max(bottomPx, itemBottomPx) - Math.min(topPx, itemTopPx),
        type: "center-to-right"
      });
    }

    if (this.between(centerYPx, itemTopPx, tolerance)) {
      sameH.push({
        i: itemId,
        y: itemTopPx,
        h: 1,
        x: (Math.min(leftPx, itemLeftPx) / containerWidth) * 100,
        w: ((Math.max(rightPx, itemRightPx) - Math.min(leftPx, itemLeftPx)) / containerWidth) * 100,
        type: "center-to-top"
      });
    }

    if (this.between(centerYPx, itemBottomPx, tolerance)) {
      sameH.push({
        i: itemId,
        y: itemBottomPx,
        h: 1,
        x: (Math.min(leftPx, itemLeftPx) / containerWidth) * 100,
        w: ((Math.max(rightPx, itemRightPx) - Math.min(leftPx, itemLeftPx)) / containerWidth) * 100,
        type: "center-to-bottom"
      });
    }

    // Edges to center (4 cases)
    if (this.between(leftPx, itemCenterXPx, tolerance)) {
      sameV.push({
        i: itemId,
        x: (itemCenterXPx / containerWidth) * 100,
        w: 1,
        y: Math.min(topPx, itemTopPx),
        h: Math.max(bottomPx, itemBottomPx) - Math.min(topPx, itemTopPx),
        type: "left-to-center"
      });
    }

    if (this.between(rightPx, itemCenterXPx, tolerance)) {
      sameV.push({
        i: itemId,
        x: (itemCenterXPx / containerWidth) * 100,
        w: 1,
        y: Math.min(topPx, itemTopPx),
        h: Math.max(bottomPx, itemBottomPx) - Math.min(topPx, itemTopPx),
        type: "right-to-center"
      });
    }

    if (this.between(topPx, itemCenterYPx, tolerance)) {
      sameH.push({
        i: itemId,
        y: itemCenterYPx,
        h: 1,
        x: (Math.min(leftPx, itemLeftPx) / containerWidth) * 100,
        w: ((Math.max(rightPx, itemRightPx) - Math.min(leftPx, itemLeftPx)) / containerWidth) * 100,
        type: "top-to-center"
      });
    }

    if (this.between(bottomPx, itemCenterYPx, tolerance)) {
      sameH.push({
        i: itemId,
        y: itemCenterYPx,
        h: 1,
        x: (Math.min(leftPx, itemLeftPx) / containerWidth) * 100,
        w: ((Math.max(rightPx, itemRightPx) - Math.min(leftPx, itemLeftPx)) / containerWidth) * 100,
        type: "bottom-to-center"
      });
    }

    // Center to center (2 cases)
    if (this.between(centerXPx, itemCenterXPx, tolerance)) {
      sameV.push({
        i: itemId,
        x: (itemCenterXPx / containerWidth) * 100,
        w: 1,
        y: Math.min(topPx, itemTopPx),
        h: Math.max(bottomPx, itemBottomPx) - Math.min(topPx, itemTopPx),
        type: "center-to-center-h"
      });
    }

    if (this.between(centerYPx, itemCenterYPx, tolerance)) {
      sameH.push({
        i: itemId,
        y: itemCenterYPx,
        h: 1,
        x: (Math.min(leftPx, itemLeftPx) / containerWidth) * 100,
        w: ((Math.max(rightPx, itemRightPx) - Math.min(leftPx, itemLeftPx)) / containerWidth) * 100,
        type: "center-to-center-v"
      });
    }
  }

  /**
   * Update distance guide lines (khoảng cách từ container edges)
   */
  public updateDistanceGuideLines(placeholder: PlaceholderItem): void {
    if (!this.instance.isDraggingGrid && !this.instance.isResizing) {
      this.state.guideLineXDistance = 0;
      this.state.guideLineYDistance = 0;
      return;
    }

    if (this._guideUpdateRAF) cancelAnimationFrame(this._guideUpdateRAF);

    this._guideUpdateRAF = requestAnimationFrame(() => {
      this.instance.updateScaleRatio();

      const rect = this.instance.$refs.item?.getBoundingClientRect();
      if (!rect) return;

      const containerWidth = rect.width / this.instance.scaleRatio;
      const containerHeight = rect.height / this.instance.scaleRatio;

      // Safe parsing với fallback values
      const itemLeft = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
      const itemWidth = ensureNumericValue(placeholder.width);
      const itemRight = itemLeft + itemWidth;
      const itemTop = ensureNumericValue(placeholder.top);
      const itemHeight = ensureNumericValue(placeholder.height);
      const itemBottom = itemTop + itemHeight;

      const leftDistance = Math.round(itemLeft);
      const rightDistance = Math.round(containerWidth - itemRight);
      const topDistance = Math.round(itemTop);
      const bottomDistance = Math.round(containerHeight - itemBottom);

      const itemCenterY = itemTop + itemHeight / 2;
      const itemCenterX = itemLeft + itemWidth / 2;

      // X-axis guide
      if (leftDistance <= rightDistance) {
        this.state.guideLineX = {
          x: 0,
          y: itemCenterY,
          w: itemLeft,
          direction: "left"
        };
        this.state.guideLineXDistance = leftDistance;
      } else {
        this.state.guideLineX = {
          x: (itemRight / containerWidth) * 100,
          y: itemCenterY,
          w: rightDistance,
          direction: "right"
        };
        this.state.guideLineXDistance = rightDistance;
      }

      // Y-axis guide
      if (topDistance <= bottomDistance) {
        this.state.guideLineY = {
          x: (itemCenterX / containerWidth) * 100,
          y: 0,
          h: itemTop,
          direction: "top"
        };
        this.state.guideLineYDistance = topDistance;
      } else {
        this.state.guideLineY = {
          x: (itemCenterX / containerWidth) * 100,
          y: itemBottom,
          h: bottomDistance,
          direction: "bottom"
        };
        this.state.guideLineYDistance = bottomDistance;
      }

      this._guideUpdateRAF = null;
    });
  }

  /**
   * Find nearby items for distance guides
   */
  public findNearbyItems(placeholder: PlaceholderItem): void {
    if (!placeholder || !this.instance.layout.length) return;

    this.instance.updateScaleRatio();

    const result = { left: null, right: null, top: null, bottom: null };
    let distances = { left: Infinity, right: Infinity, top: Infinity, bottom: Infinity };

    const containerRect = this.instance.$refs.item?.getBoundingClientRect();
    if (!containerRect) return;

    const containerWidth = containerRect.width / this.instance.scaleRatio;
    const leftPx = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const rightPx = leftPx + widthPx;
    const topPx = ensureNumericValue(placeholder.top);
    const heightPx = ensureNumericValue(placeholder.height);
    const bottomPx = topPx + heightPx;

    // Check if this is a group
    const isGroup = placeholder.i && placeholder.i.startsWith("group-");
    let groupItems: string[] = [];

    if (isGroup) {
      const groupId = placeholder.i.replace("group-", "");
      const section = this.instance.sections.find((s: any) => s.id === this.instance.section_id);
      const group = section?.groups?.[groupId];
      if (group) {
        groupItems = group.blocks || [];
      }
    }

    this.instance.layout.forEach((item: any) => {
      if (
        item.i === placeholder.i ||
        !item.i ||
        item.i.startsWith("selection-") ||
        item.i.startsWith("ecom-grid-placeholder")
      ) return;

      if (isGroup && groupItems.includes(item.i)) return;

      const itemLeftPx = (ensureNumericValue(item.left) / 100) * containerWidth;
      const itemWidthPx = ensureNumericValue(item.width);
      const itemRightPx = itemLeftPx + itemWidthPx;
      const itemTopPx = ensureNumericValue(item.top);
      const itemHeightPx = ensureNumericValue(item.height);
      const itemBottomPx = itemTopPx + itemHeightPx;

      // Check left
      if (itemRightPx <= leftPx) {
        const distance = leftPx - itemRightPx;
        if (distance < distances.left && distance <= this.state.maxGuideDistance &&
            this.hasVerticalOverlap(topPx, bottomPx, itemTopPx, itemBottomPx)) {
          distances.left = distance;
          result.left = item;
        }
      }

      // Check right
      if (itemLeftPx > rightPx) {
        const distance = itemLeftPx - rightPx;
        if (distance < distances.right && distance <= this.state.maxGuideDistance &&
            this.hasVerticalOverlap(topPx, bottomPx, itemTopPx, itemBottomPx)) {
          distances.right = distance;
          result.right = item;
        }
      }

      // Check top
      if (itemBottomPx <= topPx) {
        const distance = topPx - itemBottomPx;
        if (distance < distances.top && distance <= this.state.maxGuideDistance &&
            this.hasHorizontalOverlap(leftPx, rightPx, itemLeftPx, itemRightPx)) {
          distances.top = distance;
          result.top = item;
        }
      }

      // Check bottom
      if (itemTopPx >= bottomPx) {
        const distance = itemTopPx - bottomPx;
        if (distance < distances.bottom && distance <= this.state.maxGuideDistance &&
            this.hasHorizontalOverlap(leftPx, rightPx, itemLeftPx, itemRightPx)) {
          distances.bottom = distance;
          result.bottom = item;
        }
      }
    });

    this.state.nearbyItems = result;
    this.updateDistanceGuides(placeholder, distances);
  }

  /**
   * Update distance guides between items
   */
  private updateDistanceGuides(placeholder: PlaceholderItem, distances: any): void {
    this.instance.updateScaleRatio();

    const containerRect = this.instance.$refs.item?.getBoundingClientRect();
    if (!containerRect) return;

    const containerWidth = containerRect.width / this.instance.scaleRatio;
    const maxDistance = this.state.maxGuideDistance || 100;

    const leftPx = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const rightPx = leftPx + widthPx;
    const topPx = ensureNumericValue(placeholder.top);
    const heightPx = ensureNumericValue(placeholder.height);
    const bottomPx = topPx + heightPx;
    const centerYPx = topPx + heightPx / 2;
    const centerXPx = leftPx + widthPx / 2;

    // Update left guide
    if (this.state.nearbyItems.left && distances.left <= maxDistance) {
      const item = this.state.nearbyItems.left;
      const itemRightPx = (ensureNumericValue(item.left) / 100) * containerWidth + ensureNumericValue(item.width);
      const itemTopPx = ensureNumericValue(item.top);
      const itemHeightPx = ensureNumericValue(item.height);
      const itemCenterYPx = itemTopPx + itemHeightPx / 2;
      const midYPx = (centerYPx + itemCenterYPx) / 2;

      this.state.distanceGuides.left = {
        x: (itemRightPx / containerWidth) * 100,
        y: midYPx,
        w: distances.left,
        h: 1,
        distance: Math.round(distances.left),
        visible: true
      };
    } else {
      this.state.distanceGuides.left.visible = false;
    }

    // Update right guide
    if (this.state.nearbyItems.right && distances.right <= maxDistance) {
      const item = this.state.nearbyItems.right;
      let itemLeftPx, itemCenterYPx;

      if (item.i === "container-right") {
        itemLeftPx = containerWidth;
        itemCenterYPx = centerYPx;
      } else {
        itemLeftPx = (ensureNumericValue(item.left) / 100) * containerWidth;
        const itemTopPx = ensureNumericValue(item.top);
        const itemHeightPx = ensureNumericValue(item.height);
        itemCenterYPx = itemTopPx + itemHeightPx / 2;
      }

      const midYPx = (centerYPx + itemCenterYPx) / 2;
      const exactDistance = itemLeftPx - rightPx;

      this.state.distanceGuides.right = {
        x: (rightPx / containerWidth) * 100,
        y: midYPx,
        w: exactDistance,
        h: 1,
        distance: Math.round(exactDistance),
        visible: true
      };
    } else {
      this.state.distanceGuides.right.visible = false;
    }

    // Update top guide
    if (this.state.nearbyItems.top && distances.top <= maxDistance) {
      const item = this.state.nearbyItems.top;
      const itemLeftPx = (ensureNumericValue(item.left) / 100) * containerWidth;
      const itemWidthPx = ensureNumericValue(item.width);
      const itemCenterXPx = itemLeftPx + itemWidthPx / 2;
      const itemBottomPx = ensureNumericValue(item.top) + ensureNumericValue(item.height);
      const midXPx = (centerXPx + itemCenterXPx) / 2;

      this.state.distanceGuides.top = {
        x: (midXPx / containerWidth) * 100,
        y: itemBottomPx,
        w: 1,
        h: distances.top,
        distance: Math.round(distances.top),
        visible: true
      };
    } else {
      this.state.distanceGuides.top.visible = false;
    }

    // Update bottom guide
    if (this.state.nearbyItems.bottom && distances.bottom <= maxDistance) {
      const item = this.state.nearbyItems.bottom;
      const itemLeftPx = (ensureNumericValue(item.left) / 100) * containerWidth;
      const itemWidthPx = ensureNumericValue(item.width);
      const itemCenterXPx = itemLeftPx + itemWidthPx / 2;
      const itemTopPx = ensureNumericValue(item.top);
      const midXPx = (centerXPx + itemCenterXPx) / 2;

      this.state.distanceGuides.bottom = {
        x: (midXPx / containerWidth) * 100,
        y: bottomPx,
        w: 1,
        h: distances.bottom,
        distance: Math.round(distances.bottom),
        visible: true
      };
    } else {
      this.state.distanceGuides.bottom.visible = false;
    }
  }

  /**
   * Update column snap guides
   */
  private updateColumnSnapGuides(placeholder: PlaceholderItem): void {
    this.updateLeftColumnSnap(placeholder);
    this.updateRightColumnSnap(placeholder);
  }

  /**
   * Check if left edge snaps to column
   */
  private updateLeftColumnSnap(placeholder: PlaceholderItem): boolean {
    const leftNum = ensureNumericValue(placeholder.left);
    const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
    const leftPx = (leftNum / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const rightPx = leftPx + widthPx;

    // Don't snap if width is almost full container
    if (Math.abs(widthPx - containerWidth) < 5) {
      placeholder.snapEdge = "";
      placeholder.snapColIndex = -1;
      return false;
    }

    const numCols = this.getResponsiveColumnCount();
    const gutter = this.getResponsiveGutter();
    const totalGutterWidth = gutter * (numCols - 1);
    const columnWidth = (containerWidth - totalGutterWidth) / numCols;
    const tolerance = 5;

    // Check each column left edge
    for (let i = 0; i <= numCols; i++) {
      const colLeftEdge = i * (columnWidth + gutter);

      // Check left edge of grid item with left edge of column
      if (Math.abs(leftPx - colLeftEdge) <= tolerance) {
        const guideLineLeftPercent = Math.min(100, (colLeftEdge / containerWidth) * 100);
        this.state.guideLineLeft = guideLineLeftPercent;
        placeholder.snapEdge = "left";
        placeholder.snapColIndex = i;
        return true;
      }

      // Check right edge of grid item with left edge of column
      if (Math.abs(rightPx - colLeftEdge) <= tolerance) {
        const guideLineLeftPercent = Math.min(100, (colLeftEdge / containerWidth) * 100);
        this.state.guideLineLeft = guideLineLeftPercent;
        placeholder.snapEdge = "right";
        placeholder.snapColIndex = i;
        return true;
      }
    }

    placeholder.snapEdge = "";
    placeholder.snapColIndex = -1;
    return false;
  }

  /**
   * Check if right edge snaps to column
   */
  private updateRightColumnSnap(placeholder: PlaceholderItem): boolean {
    const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
    const leftPx = (ensureNumericValue(placeholder.left) / 100) * containerWidth;
    const widthPx = ensureNumericValue(placeholder.width);
    const rightPx = leftPx + widthPx;

    // Don't snap if width is almost full container
    if (Math.abs(widthPx - containerWidth) < 5) {
      placeholder.snapEdgeRight = "";
      placeholder.snapColIndexRight = -1;
      return false;
    }

    const numCols = this.getResponsiveColumnCount();
    const gutter = this.getResponsiveGutter();
    const totalGutterWidth = gutter * (numCols - 1);
    const columnWidth = (containerWidth - totalGutterWidth) / numCols;
    const tolerance = 5;

    // Check each column right edge
    for (let i = 1; i <= numCols; i++) {
      const colLeftEdge = (i - 1) * (columnWidth + gutter);
      const colRightEdge = colLeftEdge + columnWidth;

      // Check right edge of grid item with right edge of column
      if (Math.abs(rightPx - colRightEdge) <= tolerance) {
        const guideLineRightPercent = Math.min(100, (colRightEdge / containerWidth) * 100);
        this.state.guideLineRight = guideLineRightPercent;
        placeholder.snapEdgeRight = "right";
        placeholder.snapColIndexRight = i;
        return true;
      }

      // Check left edge of grid item with right edge of column
      if (Math.abs(leftPx - colRightEdge) <= tolerance) {
        const guideLineRightPercent = Math.min(100, (colRightEdge / containerWidth) * 100);
        this.state.guideLineRight = guideLineRightPercent;
        placeholder.snapEdgeRight = "left";
        placeholder.snapColIndexRight = i;
        return true;
      }
    }

    placeholder.snapEdgeRight = "";
    placeholder.snapColIndexRight = -1;
    return false;
  }

  /**
   * Snap position to column left edge
   */
  public snapToColLeft(leftPercent: number, widthPercent?: number): number {
    if (widthPercent === undefined && this.instance.placeholder) {
      const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
      widthPercent = (this.instance.placeholder.width / containerWidth) * 100;
    }

    const leftGuideVisible = this.instance.placeholder?.snapEdge &&
                            this.state.guideLineLeft >= 0 &&
                            (this.instance.isDraggingGrid || this.instance.isResizing) &&
                            this.instance.over &&
                            !this.instance.isDraggingMultiple;

    if (leftGuideVisible && this.instance.placeholder?.snapColIndex !== undefined && this.instance.placeholder.snapColIndex >= 0) {
      const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
      const numCols = this.getResponsiveColumnCount();
      const gutter = this.getResponsiveGutter();
      const totalGutterWidth = gutter * (numCols - 1);
      const columnWidth = (containerWidth - totalGutterWidth) / numCols;

      const colLeftEdge = this.instance.placeholder.snapColIndex * (columnWidth + gutter);
      const snapLeftPosition = (colLeftEdge / containerWidth) * 100;

      if (this.instance.placeholder.snapEdge === "left") {
        return snapLeftPosition;
      } else if (this.instance.placeholder.snapEdge === "right" && widthPercent !== undefined) {
        return snapLeftPosition - widthPercent;
      }
    }

    return leftPercent;
  }

  /**
   * Snap position to column right edge
   */
  public snapToColRight(rightPercent: number, widthPercent?: number): number {
    const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;

    if (widthPercent === undefined && this.instance.placeholder) {
      widthPercent = (this.instance.placeholder.width / containerWidth) * 100;
    }

    const rightGuideVisible = this.instance.placeholder?.snapEdgeRight &&
                             this.state.guideLineRight > 0 &&
                             (this.instance.isDraggingGrid || this.instance.isResizing) &&
                             this.instance.over &&
                             !this.instance.isDraggingMultiple;

    if (rightGuideVisible && this.instance.placeholder?.snapColIndexRight !== undefined && this.instance.placeholder.snapColIndexRight >= 0) {
      const numCols = this.getResponsiveColumnCount();
      const gutter = this.getResponsiveGutter();
      const totalGutterWidth = gutter * (numCols - 1);
      const columnWidth = (containerWidth - totalGutterWidth) / numCols;

      const colIndex = this.instance.placeholder.snapColIndexRight - 1;
      const colLeftEdge = colIndex * (columnWidth + gutter);
      const colRightEdge = colLeftEdge + columnWidth;
      const snapRightPosition = (colRightEdge / containerWidth) * 100;

      if (this.instance.placeholder.snapEdgeRight === "right" && widthPercent !== undefined) {
        return snapRightPosition - widthPercent;
      } else if (this.instance.placeholder.snapEdgeRight === "left") {
        return snapRightPosition;
      }
    }

    return rightPercent;
  }

  /**
   * Apply snap to item position
   */
  public applySnapToItem(itemId: string, position: { left: number; top: number }): { left: number; top: number } {
    const layoutItem = this.instance.layout.find((item: any) => item.i === itemId);
    if (!layoutItem) return position;

    const snapPosition = { ...position };
    const containerWidth = this.instance.$el?.offsetWidth || this.instance.width || 1200;
    const itemWidth = layoutItem.width;
    const itemWidthPercent = (itemWidth / containerWidth) * 100;

    // 1. Snap to center guides
    if (this.state.centerV && (this.instance.isDraggingGrid || this.instance.isResizing) && !this.instance.isDraggingMultiple) {
      snapPosition.left = (100 - itemWidthPercent) / 2;
    }

    if (this.state.centerH && (this.instance.isDraggingGrid || this.instance.isResizing) && !this.instance.isDraggingMultiple) {
      const containerHeight = this.getGridHeight();
      snapPosition.top = (containerHeight - layoutItem.height) / 2;
    }

    // 2. Snap to column edges
    if (this.instance.placeholder?.snapEdge && (this.instance.isDraggingGrid || this.instance.isResizing) && !this.instance.isDraggingMultiple) {
      snapPosition.left = this.snapToColLeft(snapPosition.left);
    }

    if (this.instance.placeholder?.snapEdgeRight && (this.instance.isDraggingGrid || this.instance.isResizing) && !this.instance.isDraggingMultiple) {
      const rightEdge = snapPosition.left + itemWidthPercent;
      const snapRightPosition = this.snapToColRight(rightEdge);

      if (this.instance.placeholder.snapEdgeRight === "right") {
        snapPosition.left = snapRightPosition - itemWidthPercent;
      } else if (this.instance.placeholder.snapEdgeRight === "left") {
        snapPosition.left = snapRightPosition;
      }
    }

    // 3. Snap to other items
    if (this.state.sameV.length > 0 && (this.instance.isDraggingGrid || this.instance.isResizing) && !this.instance.isDraggingMultiple) {
      let closestGuide = null;
      let minDistance = Infinity;

      for (const guide of this.state.sameV) {
        const leftPercent = (guide.x / 100) * containerWidth;
        const distance = Math.abs((snapPosition.left / 100) * containerWidth - leftPercent);
        if (distance < minDistance) {
          minDistance = distance;
          closestGuide = guide;
          (closestGuide as any).isRight = false;
        }

        const rightDistance = Math.abs(((snapPosition.left + itemWidthPercent) / 100) * containerWidth - leftPercent);
        if (rightDistance < minDistance) {
          minDistance = rightDistance;
          closestGuide = { ...guide, isRight: true };
        }
      }

      if (closestGuide && minDistance <= 5 * (containerWidth / 100)) {
        const guideLeftPercent = closestGuide.x;

        if ((closestGuide as any).isRight) {
          snapPosition.left = guideLeftPercent - itemWidthPercent;
        } else {
          snapPosition.left = guideLeftPercent;
        }
      }
    }

    return snapPosition;
  }

  /**
   * Clear all guidelines
   */
  public clearAllGuides(): void {
    this.state.sameH = [];
    this.state.sameV = [];
    this.state.centerH = false;
    this.state.centerV = false;
    this.state.guideLineLeft = 0;
    this.state.guideLineRight = 0;

    if (this.instance.placeholder) {
      this.instance.placeholder.snapEdge = "";
      this.instance.placeholder.snapEdgeRight = "";
      this.instance.placeholder.snapColIndex = -1;
      this.instance.placeholder.snapColIndexRight = -1;
    }

    Object.keys(this.state.distanceGuides).forEach((key) => {
      (this.state.distanceGuides as any)[key].visible = false;
    });

    this.state.guideLineXDistance = 0;
    this.state.guideLineYDistance = 0;
  }

  /**
   * Utility methods
   */
  private between(a: number, b: number, tolerance: number = 3): boolean {
    const numA = ensureNumericValue(a);
    const numB = ensureNumericValue(b);
    return numA >= numB - tolerance && numA <= numB + tolerance;
  }

  private hasVerticalOverlap(top1: number, bottom1: number, top2: number, bottom2: number): boolean {
    return top1 < bottom2 && bottom1 > top2;
  }

  private hasHorizontalOverlap(left1: number, right1: number, left2: number, right2: number): boolean {
    return left1 < right2 && right1 > left2;
  }

  private getGridHeight(): number {
    if (this.instance.$refs.item) {
      return this.instance.$refs.item.offsetHeight;
    }
    return this.instance.data?.settings?.["min-height"] ?
           parseInt(this.instance.data.settings["min-height"]) : 300;
  }

  private getResponsiveColumnCount(): number {
    const currentScreen = this.instance.currentScreen || this.instance.screen;
    switch (currentScreen) {
      case "mobile": return 4;
      case "tablet": return 8;
      default: return 12;
    }
  }

  private getResponsiveGutter(): number {
    const currentScreen = this.instance.currentScreen || this.instance.screen;
    switch (currentScreen) {
      case "mobile": return 5;
      case "tablet": return 8;
      default: return this.instance.gutter || 20;
    }
  }

  /**
   * Destroy method để cleanup
   */
  public destroy(): void {
    if (this._guideUpdateRAF) {
      cancelAnimationFrame(this._guideUpdateRAF);
      this._guideUpdateRAF = null;
    }
  }
}