export default {
    data() {
        return {
            id: this.$helpers.randid(),
            isopen: false,
            canClose: false,
            popupPosition: 'bottom',
            isShowPopup: false,
        }
    },
    computed: {
        settingOpen(){
            return this.$store.getters['settings/open'];
        }
    },
    methods: {
        open(e) {
            if (this.isopen) {
                return this.isopen = false;
            }
            this.isopen = true;

            this.$nextTick(() => {
                const popupWrapper = this.$refs['ecom-fields__popup'];
                if(popupWrapper) {
                    if(this.field?.options?.type === "typography"){
                        this.popupPosition = 'bottom';
                        this.isShowPopup = true;
                        return;
                    }
                    const rect = popupWrapper.getBoundingClientRect();
                    const elementPanel = document.getElementById('ecom-element-panel');
                    const elementPanelRect = elementPanel?.getBoundingClientRect();
                    
                    if(rect.y + rect.height > window.innerHeight && rect.y > rect.height + 100) {
                        // Kiểm tra xem chiều cao của popup có vượt quá khoảng cách từ popup đến rìa trên của element panel không
                        const isTop = rect.top - elementPanelRect?.top - 32 - 12 - rect.height - 20; // 20 là khoảng cách cộng trừ thêm tránh popup bị đè vào rìa trên panel
                        if(!this.settingOpen && isTop > 0)
                        this.popupPosition = 'top';
                    }

                    this.isShowPopup = true;
                }
            })

            this.isShowPopup = false;
            this.popupPosition = 'bottom';

            // document.addEventListener('mousedown', this.doClose);
            // document.addEventListener('click', this.doClose);
        },
        updatePopupPosition() {
            if (this.popupPosition = 'bottom') return;
            this.$nextTick(() => {
                const popupWrapper = this.$refs['ecom-fields__popup'];
                if (popupWrapper) {
                    const rect = popupWrapper.getBoundingClientRect();
                    if (rect.y + rect.height > window.innerHeight && rect.y > rect.height + 100) {
                        if (!this.settingOpen)
                            this.popupPosition = 'top';
                    }
                }
            })
            this.popupPosition = 'bottom';
        },
        doClose(e) {
            if (e && e.type == 'mousedown') {
                this.canClose = (!e.target.closest('.'+this.id) || this.keep === false);
                if (this.canClose) {
                    // document.removeEventListener('mousedown', this.doClose);
                }
            } else if (
                e === undefined || this.canClose
            ) {
                this.isopen = false;
                this.canClose = false;
                // document.removeEventListener('click', this.doClose);
                // document.removeEventListener('mousedown', this.doClose);
            }
        }
    }
}