<i18n>
{
    "en": {
        "click_to_change": "Click to change",
        "reset_to_default": "Reset to default",
        "add_global_color_success": "Add Global Color Success",
        "add_global_typography_success": "Add Global Typography Success",
        "typography": "Typography"
    },
    "fr": {
        "click_to_change": "Cliquez pour changer",
        "reset_to_default": "Réinitialiser aux valeurs par défaut",
        "add_global_color_success": "Ajout de la Couleur Globale Réussi",
        "add_global_typography_success": "Ajout de la Typographie Globale Réussi"
    },
    "de": {
        "click_to_change": "Klicken Sie zum Ändern",
        "reset_to_default": "Zurücksetzen auf Standard",
        "add_global_color_success": "Globale Farbe erfolgreich hinzugefügt",
        "add_global_typography_success": "Globale Typografie erfolgreich hinzugefügt"
    },
    "ja": {
        "click_to_change": "変更するにはクリック",
        "reset_to_default": "デフォルトにリセット",
        "add_global_color_success": "グローバルカラーの追加に成功しました",
        "add_global_typography_success": "グローバルタイポグラフィの追加に成功しました",
        "typography": "タイポグラフィ"
    }
}
</i18n>
<template>
    <div class="relative flex items-center justify-end -space-x-px" :class="id">
        <button
            class="relative flex items-center justify-center w-8 h-8 text-gray-600  popupBtn"
            :class="[
                { 'bg-gray-200 hover:bg-gray-200': isPanelOpen },
                isPopup ? 'select-none border hover:bg-gray-100 active:bg-gray-300 border-light' : '',
                isGlobalTypographyPopup ? 'ecom-global-typography-popup-btn' : 'rounded bg-[#F3F3F3]'
            ]"
            :data-tooltip="titlePopup ?? globalTitle ?? $t('click_to_change')"
            @click="open($event), $emit('update:isPanelOpen', !isPanelOpen)"
            data-tooltip-location="top"
            type="button"
            ref="popupBtn">
            <EcomIcon 
                v-if="typeIcon" 
                :source="typeIcon" 
                :size="'w-5'" 
                :color="'text-icon-primary '"
                class="flex items-center"
            ></EcomIcon>
        </button>
        <Teleport to="body" v-if="isopen">
            <transition enter-active-class="transition duration-200 ease-out"
                enter-from-class="transform scale-90 opacity-0" enter-to-class="transform scale-100 opacity-100"
                leave-active-class="transition duration-150 ease-in" leave-from-class="transform scale-100 opacity-100"
                leave-to-class="transform scale-90 opacity-0">
                <div ref="ecom-fields__popup" class="fixed left-0 ecom-fields__popup flex"
                    :class="[
                        popupPosition === 'bottom' ? 'top-full mt-3 pb-5' : 'top-full mt-3 pb-5',
                        isShowPopup || isPopup ? 'visible' : 'invisible',
                        isPopup ? 'transform -translate-x-1/2' : ''
                    ]"
                    :style="{
                        top: popupColorPosition.top,
                        left: popupColorPosition.left,
                        bottom: popupColorPosition.bottom,
                        zIndex: zIndex || 61
                    }"
                    :id="idTeleport">
                    <BackDrop v-if="isopen && !isPopup" @click="doClose" class="z-[1] outside-close-cursor"></BackDrop>
                    <div class="relative z-[2] inline-block bg-white rounded-xl ec-shadow-popup-3 border border-popup popup-field"
                        :class="[type === 'dropdown' ? 'w-max min-w-40 max-w-68' : 'w-68 3xl:w-[260px]']">
                        <!-- <svg
                        viewBox="0 0 213.3 213.3"
                        class="absolute w-4 h-4 mr-1 left-4 fill-current text-white  z-[1]"
                        :class="popupPosition === 'bottom' ? 'top-0 transform rotate-180 -mt-3' : 'bottom-[-11px]'"
                    >
                        <polygon
                            class="shadow-xxl"
                            points="0,53.333 106.667,160 213.333,53.333"
                        />
                    </svg> -->
                        <Tabs v-if="global" :tabs="['global', 'customize']" :title="translateTitle" :type="global?.type"
                            :value="values" :selected="dGlobal.selected" @addglobal="addNewGlobal"
                            @refesh="backToDefault" @selectedTab="handleSelectedTab"
                            class="overflow-y-auto"
                            :style="popupBodyStyle">
                            <template #global>
                                <Global v-model:selected="dGlobal.selected" :global="global" />
                            </template>
                            <template #customize>
                                <Fields :fields="fields" :deep="1" :data="valuesType ?? {}" :ispop="true"
                                    class="relative" @update:data="updateData" />
                            </template>
                        </Tabs>
                        <div v-else>
                            <div v-if="type !== 'dropdown'"
                                data-popup-header
                                class="flex items-center justify-between px-4 py-2 bg-surface-tertiary rounded-t-xl">
                                <span class="text-xs font-[550] text-text-primary  truncate w-full"
                                    v-html="field?.label" />
                                <span class="flex items-center">
                                    <button type="button"
                                        class="transition rounded text-icon hover:bg-gray-200 hover:text-gray-500  "
                                        :class="{ 'hidden': Object.keys(values).length === 0 }"
                                        :data-tooltip="$t('reset_to_default')" data-tooltip-location="bottom"
                                        @click="backToDefault">
                                        <EcomIcon :source="icons.resetIcon" :color="'text-text-primary'"
                                            class="flex items-center"></EcomIcon>
                                    </button>
                                </span>
                            </div>
                            <PopupDropdown v-if="type === 'dropdown'" :data="data" :values="optionsValues"
                                :preview-animation="isEntranceAnimationDropdown"
                                :preview-scrolling-presets="isScrollingPresetDropdown"
                                class="overflow-y-auto" :style="popupBodyStyle"
                                @update:data="$emit('update:data', $event)" @close="doClose" />
                            <template v-else>
                                <!-- ANIM-04: mini-viewport, chỉ cho 5 field scrolling.
                                     Cố ý là SIBLING của <Fields> chứ không bọc quanh nó —
                                     <Fields> giữ nguyên class + popupBodyStyle, nên các
                                     field popup khác (typography, border, box-shadow…)
                                     không đổi một pixel nào. -->
                                <ScrollingPreview
                                    v-if="isScrollingPopup"
                                    :value="valuesType"
                                    :type="options?.type"
                                    class="px-3 pt-3"
                                />
                                <Fields :fields="fields" :deep="1" :data="valuesType" :ispop="true"
                                    class="relative p-3 overflow-y-auto" :style="popupBodyStyle"
                                    @update:data="updateData" />
                            </template>
                        </div>
                    </div>
                </div>
            </transition>
        </Teleport>
    </div>
</template>

<script lang="ts">
// import { faFontCase, faFiles, faPen, faBox, faArrowsRotate, faBorderAll, faAngleDown, faFaceSmilePlus, faArrowsLeftRight, faScaleBalanced, faItalic, faTextSlash, faTableLayout, faCrosshairs, faPercent, faTags, faPersonRunning, faStarShooting, faW, faH, faDistributeSpacingHorizontal, faAlignJustify, faFilter, faPaperclip, faCrop, faImage, faArrowsUpDown, faArrowPointer } from '@fortawesome/pro-light-svg-icons';
import { computed } from 'vue';
import Tabs from '../../components/molecules/Tabs/Tabs.vue';
import PopupDropdown from '../../components/molecules/DropdownOptions/DropdownOptions.vue';
import ScrollingPreview from '../../components/molecules/ScrollingPreview/ScrollingPreview.vue';
import { SCROLLING_PREVIEW_TYPES } from '@/utils/scrolling-animation';
import Global from '../../components/molecules/GlobalPanel/GlobalPanel.vue';
import { dropdownTypes, popupTypes } from '../../constants';
import { Popmenu } from '@/mixins';
import {
        GlobalTextMajor, 
        TextMajor,
        TextFont,
        TypeMajor, 
        ecTextShadown, 
        ecBoxShadow, 
        ecBorder, 
        EditMajor, 
        ecAlignCenter,
        resetIcon, 
        TitleMinor, 
        ProductsMajor, 
        TemplateMajor, 
        ecCrosshairs, 
        FavoriteMajor, 
        ViewportWideMajor, 
        ViewportTallMajor, 
        ViewportNarrowMajor, 
        TextAlignmentCenterMajor, 
        AttachmentMajor, 
        ecCropSize, 
        ImageMajor, 
        TaxMajor, 
        ColumnWithTextMajor, 
        LinkMinor, 
        ecTransform, 
        WandMajor, 
        SortMinor, 
        FilterMajor, 
        DiscountCodeMajor 
    } from '@/assets/icons';

interface PopupPosition {
    top: string | number;
    left: string;
    bottom: string | number;
    maxHeight?: string;
}

interface PopupDimensions {
    width: number;
    height: number;
}

export default {
    name: 'PopupGroup',
    components: {
        Tabs,
        Global,
        PopupDropdown,
        ScrollingPreview,
    },
    provide() {
        return {
            'teleport_id': computed(() => '#' + this.idTeleport)
        }
    },
    mixins: [Popmenu],
    props: {
        field: {
            type: Object,
            default() {
                return {};
            }
        },
        // eslint-disable-next-line vue/require-default-prop
        data: [Object, String, Number, Boolean],
        isPanelOpen: {
            type: Boolean,
            default: false
        },
        titlePopup: {
            type: String,
            default: ''
        },
        isPopup: {
            type: Boolean,
            default: false
        },
        zIndex: {
            type: [String, Number],
            default: 61
        }
    },
    emits: ['update:data', 'close', 'update:isPanelOpen'],
    data() {
        return {
            popupColorPosition: { top: 0, left: '0px', bottom: 0, maxHeight: '' } as PopupPosition,
            idTeleport: "ecom-popup-" + Date.now() + Math.random().toString(36).substr(2, 9),
            values: this.data ?? {},
            dGlobal: {
                selected: null,
            },
            isWatch: true,
            isEmit: false,
            icons: {
                // faFontCase, faFiles, faPen, faBox, faArrowsRotate, faBorderAll, faAngleDown, faFaceSmilePlus, faArrowsLeftRight, faScaleBalanced, faItalic, faTextSlash, faTableLayout, faCrosshairs, faPercent, faTags, faPersonRunning, faStarShooting, faW, faH, faDistributeSpacingHorizontal, faAlignJustify, faFilter, faPaperclip, faCrop, faImage, faArrowsUpDown, faArrowPointer,

                GlobalTextMajor, 
                TextMajor, 
                TextFont,
                TypeMajor, 
                ecTextShadown, 
                ecBoxShadow, 
                ecBorder, 
                EditMajor, 
                ecAlignCenter, 
                resetIcon, 
                TitleMinor, 
                ProductsMajor, 
                TemplateMajor, 
                ecCrosshairs, 
                FavoriteMajor, 
                ViewportWideMajor, 
                ViewportTallMajor, 
                ViewportNarrowMajor, 
                TextAlignmentCenterMajor, 
                AttachmentMajor, 
                ecCropSize, 
                ImageMajor, 
                TaxMajor, 
                ColumnWithTextMajor, 
                LinkMinor, 
                ecTransform, 
                WandMajor, 
                SortMinor, 
                FilterMajor, 
                DiscountCodeMajor
            },
            mutationObserver: null as MutationObserver | null,
            popupElement: null as HTMLElement | null,
            popupDimensions: { width: 270, height: 468 } as PopupDimensions
        };
    },
    computed: {
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        currentPopup() {
            return this.$store.getters["builder/popup"];
        },
        translateTitle() {
            if (this.field?.options?.global?.type && this.field.options.global.type === "typography") {
                return this.$t("typography");
            }
            return this.field?.options?.global?.type;
        },
        globalTitle() {
            if (this.dGlobal) {
                return this.$store.getters['settings/globalTitle'](this.global?.type, this.dGlobal.selected);
            }
            return '';
        },
        activeStatus() {
            return 'bg-' + (this.dGlobal.selected ? 'green-600' :
                (Object.values(this.values).filter((v) => {
                    return v !== null ? (typeof v != 'object' || Object.keys(v).length > 0) : false;
                }).length > 0 ?
                    'blue-600' :
                    'transparent'
                )
            );
        },
        global() {
            return this?.field?.options?.global ?? false;
        },
        title() {
            return this?.field?.options?.type ?? 'Untilted';
        },
        isGlobalTypographyPopup() {
            return this?.field?.class === 'ecom-global-typography-field' &&
                this?.field?.options?.type === 'typography';
        },
        /**
         * ANIM-03: bật ô preview cho đúng 3 field Entrance/Hover/Click.
         *
         * Bắt theo `values === 'entrance-animation'` chứ KHÔNG theo `icon_type === 'animation'`:
         * hệ hover LEGACY (`alias/button.ts`, `icon.ts`, `text.ts`…) cũng khai
         * `icon_type: 'animation'` nhưng danh sách của nó tra bảng `animations` (grow/shrink/
         * pulse…) — toàn `transform:` thuần, KHÔNG có `@keyframes` nào để preview. Bắt theo
         * icon_type thì các field đó hiện ô preview đứng im.
         */
        isEntranceAnimationDropdown() {
            return this.field?.options?.values === 'entrance-animation';
        },
        /**
         * Bật tooltip preview cho dropdown preset Scrolling.
         *
         * Nhận diện bằng CỜ TƯỜNG MINH `options.previewScrollingPresets` do
         * `Animation_preset.vue` đặt, chứ không đoán theo `field.name` và cũng không nới
         * `isEntranceAnimationDropdown` ở trên — `values` của preset là OBJECT nên không
         * rơi vào nhánh đó, và nới ra sẽ kéo theo hệ hover legacy dùng chung
         * `icon_type: 'animation'`.
         */
        isScrollingPresetDropdown() {
            return this.field?.options?.previewScrollingPresets === true;
        },
        /**
         * ANIM-04: bật mini-viewport cho đúng 5 field tab Scrolling, nhận diện qua
         * `options.type` (`scrolling-animation-px` / `-deg` / `-opacity` / `-scale` / `-blur`
         * — định nghĩa ở `constants/popup-scolling-animation.ts`). Popup.vue dùng chung cho
         * rất nhiều field nên điều kiện phải hẹp.
         */
        isScrollingPopup() {
            return SCROLLING_PREVIEW_TYPES.includes(this.field?.options?.type);
        },
        typeIcon() {
            let options = this.field.options,
                type = options?.icon_type ?? options?.type,
                icon = '',
                className = this?.field?.class;
       
            switch (type) {
                case 'typography': {
                    if(className === 'ecom-global-typography-field'){
                        icon = this.icons.GlobalTextMajor;
                    }else{
                        icon = this.icons.TextFont;  
                    }
                    break;
                }
                case 'text-shadow': {
                    icon = this.icons.ecTextShadown;
                    break;
                }
                case 'box-shadow': {
                    icon = this.icons.ecBoxShadow;
                    break;
                }
                case 'border': {
                    icon = this.icons.ecBorder;
                    break;
                }
                case 'icon': {
                    icon = this.icons.EditMajor;
                    break;
                }
                case 'alignment': {
                    icon = this.icons.ecAlignCenter;
                    break;
                }
                case 'transitions': {
                    icon = this.icons.ecTransform;
                    break;
                }
                case 'dropdown': {
                    icon = this.dropdownIcon
                    break;
                }
                case 'popup': {
                    icon = this.popupIcon
                    break;
                }
                case 'filter': {
                    icon = this.icons.FilterMajor
                    break;
                }
                case 'sorting':
                    icon = this.icons.SortMinor;
                    break;
                case 'percent':
                    icon = this.icons.DiscountCodeMajor;
                    break;
                case 'animation':
                    icon = this.icons.WandMajor;
                    break;
                case 'cursor':
                    icon = this.icons.EditMajor;
                    break;
                default: {
                    icon = this.icons.EditMajor;
                }
            }
            return icon;
        },
        dropdownIcon() {
            let name = this.field.name, icon = '';
            switch (name) {
                case 'font-weight': {
                    icon = this.icons.TypeMajor;
                    break;
                }
                case 'text-transform': {
                    icon = this.icons.ecTransform;
                    break;
                }
                case 'font-style': {
                    icon = this.icons.TitleMinor;
                    break;
                }
                case 'text-decoration': {
                    icon = this.icons.TitleMinor;
                    break;
                }
                case 'product_source': {
                    icon = this.icons.ProductsMajor;
                    break;
                }
                case 'layout': {
                    icon = this.icons.TemplateMajor;
                    break;
                }
                case 'heading': {
                    icon = this.icons.TitleMinor;
                    break;
                }
                case 'position':
                case 'image_position': {
                    icon = this.icons.ecCrosshairs;
                    break;
                }
                case 'image_ratio': {
                    icon = this.icons.EditMajor;
                    break;
                }
                case 'transition': {
                    icon = this.icons.EditMajor;
                    break;
                }
                case 'timing': {
                    icon = this.icons.FavoriteMajor;
                    break;
                }
                case 'width':
                case 'width-max':
                case 'content-width': {
                    icon = this.icons.ViewportWideMajor
                    break;
                }
                case 'height': {
                    icon = this.icons.ViewportTallMajor
                    break;
                }
                case 'align-content': {
                    icon = this.icons.ViewportNarrowMajor
                    break;
                }
                case 'padding': {
                    icon = this.icons.ColumnWithTextMajor
                    break;
                }
                case 'link': {
                    icon = this.icons.AttachmentMajor
                    break;
                }
                case 'size': {
                    icon = this.icons.ecCropSize
                    break;
                }
                case 'imageObjectFit': {
                    icon = this.icons.ImageMajor
                    break;
                }
                case 'aspect_ratio': {
                    icon = this.icons.TaxMajor
                    break;
                }
                case 'source': {
                    icon = this.icons.LinkMinor
                    break;
                }

                default: {
                    icon = this.icons.EditMajor;
                }
            }

            return icon;
        },
        popupIcon() {
            let name = this.field.name, icon = '';
            switch (name) {
                default: {
                    icon = this.icons.EditMajor;
                }
            }

            return icon;
        },
        type() {
            let options = this.field.options;
            let type = options?.type;
            if ((type &&
                (type === 'typography' ||
                    type === 'border-offset' ||
                    type === 'border')) ||
                (!type && options.fields)) {
                return '';
            }
            return type;
        },
        options() {
            return this.field?.options ?? {};
        },
        fields() {
            return popupTypes[this.options?.type] ?? (this.options?.fields ?? []);
        },
        valuesType() {
            if (this.type) {
                return this.values?.[this.type];
            }
            return this.values;
        },
        optionsValues() {
            let values = this.options?.values;
            const add = (arr, obj) => {
                if (obj.constructor === Object) {
                    let k;
                    for (k in obj) {
                        arr.push({
                            name: k,
                            title: obj[k]
                        });
                    }
                }
            };
            if (typeof values === 'string') {

                let ts = dropdownTypes[values] ?? [];
                if (ts.constructor === Object) {
                    let tss = [];
                    add(tss, ts);
                    ts = tss;
                }
                if (
                    ts.findIndex(x => x.name === '__delete__') === -1 &&
                    ts.findIndex(x => x.title === this.$t('default')) === -1 &&
                    this.options.default !== false
                ) {
                    ts.splice(0, 0, { name: '__delete__', title: this.$t('default') });
                }
                return ts;
            }
            let type = [],
                k,
                value;
            if (values.constructor === Object) {
                add(type, values);
            }
            else if (values.constructor === Array) {
                for (k in values) {
                    value = values[k];
                    if (value.constructor === Object) {
                        type.push({
                            name: value.title,
                            title: value.title,
                            disabled: true
                        });
                        if (value.values.constructor === Object) {
                            add(type, value.values);
                        }
                    }
                    else {
                        type.push({ name: value, title: value });
                    }
                }
            }
            if (this.options.default !== false &&
                type.findIndex(x => x.name === '__delete__') === -1 &&
                type.findIndex(x => x.title === this.$t('default')) === -1) {
                type.splice(0, 0, { name: '__delete__', title: this.$t('default') });
            }
            return type;
        },
        popupBodyStyle() {
            if (!this.popupColorPosition.maxHeight) {
                return undefined;
            }
            return { maxHeight: this.popupColorPosition.maxHeight };
        },
    },
    watch: {
        //refresh value when change screen
        isopen(val) {
            if (val === true) {
                this.isEmit = false;
                this.values = this.$helpers.copy(this.data) ?? {};
            }
            if (this.isopen) {
                this.$store.commit("builder/setIsPopupOpen", true);
                this.startObservingPopup();
                //window.addEventListener('click', this.closePopupSelection);
            } else {
                this.stopObservingPopup();
            }
        },
        isPopupOpen(val) {
            if(val === false) {
                this.isopen = false;
            }
        },
        isPanelOpen(val) {
            this.isopen = val;
        },
        data: {
            immediate: true,
            deep: true,
            handler: function (val) {
                if (this.isWatch) {
                    this.isEmit = false;
                    this.values = this.$helpers.copy(val) ?? {};
                }
                if (
                    this.type === 'dropdown' &&
                    this.data === undefined &&
                    this.field.value
                ) {
                    this.$emit('update:data', this.field.value);
                }
                this.isWatch = true;
                this.dGlobal.selected = this.global?.value ?? '';
            }
        },
        values: {
            immediate: true,
            deep: true,
            handler: function (val) {

                if (this.isEmit) {
                    if (this.type && typeof val?.[this.type] === 'object' &&
                        Object.keys(val[this.type]).length === 0) {
                        delete val[this.type];
                    }
                    this.isWatch = false;
                    if(this.type == 'text-shadow' && val?.['text-shadow']) {
                        val.type = this.type;
                    }
                    this.$emit('update:data', val);
                }
                this.isEmit = true;
                this.$nextTick(() => {
                    const wrapper = this.$refs?.['ecom-fields__popup'] as HTMLElement;
                    if(wrapper) {
                        this.updatePopupDimensions();
                        this.calculatePopupPosition();
                    }
                });
            }
        },
        'dGlobal.selected': function (val) {
            if (val && this.global) {
                this.$emit('update:data', {
                    ['global-' + this.global.type]: val
                });
            }
        }
    },
    methods: {
        handleSelectedTab(tabName) {
            this.$nextTick(() => {
                this.updatePopupDimensions();
                this.calculatePopupPosition();
            });
        },
        doClose() {
            this.isopen = false;
        },
        closePopupSelection(e: any) {
            const getPopupParent = e.target.closest('button') || e.target.closest('.ecom-fields__popup') ;
            if(!getPopupParent){
                this.isopen = false;
                window.removeEventListener('click', this.closePopupSelection);
            }
        },
        backToDefault() {
            this.values = {};
        },
        addNewGlobal(title) {
            let key = this.$helpers.makeId(8);
            this.$store.dispatch('settings/addDataGlobal', {
                key,
                type: this.global?.type,
                data: {
                    title: title,
                    value: this.$helpers.copy(this.values)
                }
            });
            this.dGlobal.selected = key;
            this.$store.commit('global/setToast', {
                message: this.global?.type === 'colors' ? this.$t('add_global_color_success') : this.$t('add_global_typography_success'),
                duration: 4000
            }, { root: true });
        },
        updateData(f, val) {
            if (val) {
                if (this.type) {
                    this.values[this.type] = val;
                }
                else {
                    this.values = val;
                }
            }
        },
        startObservingPopup() {
            this.stopObservingPopup();

            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === Node.ELEMENT_NODE) {
                                const element = node as HTMLElement;
                                if (element.id === this.idTeleport) {
                                    this.popupElement = element as HTMLElement;
                                    this.updatePopupDimensions();
                                    this.calculatePopupPosition();

                                    requestAnimationFrame(() => {
                                        this.updatePopupDimensions();
                                        this.calculatePopupPosition();
                                    });
                                }
                            }
                        });
                    }
                });
            });

            this.mutationObserver.observe(document.body, {
                childList: true,
                subtree: true
            });
        },
        stopObservingPopup() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },
        updatePopupDimensions() {
            if (this.popupElement) {
                const card = this.popupElement.querySelector('.popup-field') as HTMLElement | null;
                const target = card || this.popupElement;
                // Use offsetHeight (rendered size after max-height on body), not scrollHeight
                // which can still report unconstrained child content and skew position.
                this.popupDimensions = {
                    width: target.offsetWidth || 270,
                    height: target.offsetHeight || 468
                };
            }
        },
        calculatePopupPosition() {
            if (!this.popupElement || !this.$refs.popupBtn) return;

            const rect = this.$refs.popupBtn.getBoundingClientRect();
            const { width: popupWidth, height: popupHeight } = this.popupDimensions;
            const VIEWPORT_MARGIN = 8;
            // Fixed elements use viewport coords — do not add scrollY
            const viewportHeight = window.innerHeight;
            const maxPopupHeight = Math.max(120, viewportHeight - VIEWPORT_MARGIN * 2);

            // Body scroll area = full popup max minus everything that sits OUTSIDE the
            // scrollable body: the title header, and the scrolling mini-viewport (ANIM-04).
            //
            // The preview is deliberately a sibling of <Fields> rather than inside it, so it
            // stays pinned while the fields scroll. That also means its height is NOT covered
            // by `maxHeight` — forget to subtract it and the popup grows past the viewport,
            // cutting off the last field (reported: "End from" missing on small screens).
            const headerEl = this.popupElement.querySelector('[data-popup-header]') as HTMLElement | null;
            const headerHeight = headerEl?.offsetHeight || 0;
            const previewEl = this.popupElement.querySelector('.ecom-scroll-preview') as HTMLElement | null;
            const previewHeight = previewEl?.offsetHeight || 0;
            const maxBodyHeight = Math.max(80, maxPopupHeight - headerHeight - previewHeight);

            const distanceToBottom = viewportHeight - rect.top - rect.height;

            const fixedSelected = this.$refs.popupBtn.closest('.popup-container') as HTMLElement || this.$refs.popupBtn.closest('.fixed') as HTMLElement || this.$refs.popupBtn.closest('.absolute') as HTMLElement;
            const fixedRect = fixedSelected?.getBoundingClientRect();

            let left: number;
            if(fixedSelected && fixedRect && this.type !== 'dropdown' && this.isPopup === false) {
                const {left: leftFixed, width: selectedWidth} = fixedRect;
                const distanceToRight = window.innerWidth - leftFixed - selectedWidth;

                if(leftFixed >= popupWidth) {
                    const spaceRectToFixedRect = rect.left - leftFixed;
                    if(spaceRectToFixedRect > 50) {
                        left = rect.left - popupWidth - 20;
                    }else {
                        left = leftFixed - popupWidth;
                    }
                }else if(distanceToRight >=  popupWidth) {
                    left = leftFixed + selectedWidth;
                }else {
                    left = rect.left + rect.width;
                }
            }else {
                left = rect.left + rect.width;
            }

            // Clamp horizontal so popup stays in viewport.
            // Skip when isPopup: CSS `-translate-x-1/2` makes `left` the center axis, not the left edge.
            if (!this.isPopup) {
                left = Math.max(
                    VIEWPORT_MARGIN,
                    Math.min(left, window.innerWidth - popupWidth - VIEWPORT_MARGIN)
                );
            }

            let topNum: number;
            const fixedPopupGetter = this.$refs.popupBtn.closest('.fixed') as HTMLElement;
            const containerFly = this.$refs.popupBtn.closest('.popup-container') as HTMLElement;
            let bottomFixedSpace = 0;
            if(fixedPopupGetter) bottomFixedSpace = viewportHeight - fixedPopupGetter.getBoundingClientRect().top;

            // Cap by viewport; if content is still unconstrained (first paint), next RAF will remeasure
            const effectiveHeight = Math.min(popupHeight || maxPopupHeight, maxPopupHeight);

            if(fixedPopupGetter && this.type !== 'dropdown' && !containerFly && bottomFixedSpace >= effectiveHeight && this.isPopup === false) {
                topNum = fixedPopupGetter.getBoundingClientRect().top;
            }else if (distanceToBottom >= effectiveHeight && this.type !== 'dropdown' && this.isPopup === false) {
                topNum = rect.top - 15;
            }
            else if(distanceToBottom >= effectiveHeight && this.isPopup === true) {
                topNum = rect.bottom;
            }
            else if(distanceToBottom >= effectiveHeight) {
                topNum = rect.bottom - 15;
            }else {
                // Not enough space below — shift up so bottom aligns with viewport
                topNum = rect.bottom - (effectiveHeight - distanceToBottom);
            }

            // Keep popup fully inside viewport (with scrollable overflow when taller)
            topNum = Math.max(
                VIEWPORT_MARGIN,
                Math.min(topNum, viewportHeight - VIEWPORT_MARGIN - effectiveHeight)
            );

            this.popupColorPosition = {
                top: topNum + 'px',
                left: left + 'px',
                bottom: 'auto',
                // Applied to Fields / Tabs / Dropdown body — already subtracts header height
                maxHeight: maxBodyHeight + 'px'
            };
        },
    },
    mounted() {
        // Nếu cần, có thể thêm logic khởi tạo ở đây
    },
    beforeUnmount() {
        this.stopObservingPopup();
        //window.removeEventListener('click', this.closePopupSelection);
    }
};
</script>

