<template>
    <div class="ecom-element ecom-shopify__search-and-filter ecom-search-and-filter">
        <div class="ecom-shopify__search-and-filter-inner">
            <form class="ecom-filter-form">
                <ul class="ecom-iconlist--list" :data-layout="data.settings?.layout">
                    <li
                        v-for="(field, index) in data.settings.filters"
                        :key="index"
                        class="ecom-filter-search--item ecom-html"
                    >
                        <label class="ecom__form-field-label" v-text="lang(field?.settings.label, field?.type + '_label_' + index)" />
                        <template v-if="field?.type === 'custom_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="field?.settings.customName"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        value="all"
                                        :placeholder="field?.settings.placeholder"
                                        v-html="getCustomOptions(field)"
                                    />
                                </div>
                            </div>
                        </template>
                        <!-- Collection -->
                        <template v-if="field?.type === 'collection_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="`${field?.type.split('_')[0]}`"
                                        :required="field?.required"
                                        :class="
                                            'ecom__filter-select' +
                                            ` ecom__filter-${field?.type}`
                                        "
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        :collection_source="field?.settings?.source_collection"
                                        :specific_collections="getCollections(field)"
                                        :collections="liquid('collections')"
                                        :vendors="liquid('collection_vendors')"
                                        :product_types="liquid('collection_product_types')"
                                        :tags="liquid('collection_tags')"
                                        value="all"
                                        v-html="getCollectionOptions(field)"
                                        :placeholder="field?.settings.placeholder"
                                        :disabled="!field?.settings.placeholder"
                                    />
                                </div>
                            </div>
                        </template>
                        <!-- Availability -->
                        <template v-if="field?.type === 'availability_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="`${field?.type.split('_')[0]}`"
                                        :required="field?.required"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        :data="liquid('vendors')"
                                        value="all"
                                        :disabled="!field?.settings.placeholder"
                                    >
                                        <option
                                            value="all"
                                            selected
                                            v-text="lang(field?.settings.placeholder, field?.type + '_select_all_' + index)"
                                        />
                                        <option value="1" v-text="lang(this.$t('product_in_stock'), 'product_filter_in_stock')"/>
                                        <option value="0" v-text="lang(this.$t('product_out_of_stock'), 'product_filter_out_of_stock')"/>
                                    </select>
                                </div>
                            </div>
                        </template>
                        <!-- Vendor -->
                        <template v-if="field?.type === 'vendor_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="`${field?.type.split('_')[0]}`"
                                        :required="field?.required"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        :data="liquid('vendors')"
                                        value="all"
                                        :disabled="!field?.settings.placeholder"
                                    >
                                        <option
                                            value="all"
                                            selected
                                            v-text="lang(field?.settings.placeholder, field?.type + '_select_all_' + index)"
                                        />
                                         <option
                                            v-if="canUseCustomLiquidForCSR"
                                            v-for="(option, i) in liquid('vendors').split(',')"
                                            :key="option"
                                            :value="option.split('|')[0]"
                                            v-text="
                                                lang(
                                                    option.split('|').pop(),
                                                    field?.type + '_' + i
                                                )
                                            "
                                        />
                                    </select>
                                </div>
                            </div>
                        </template>
                        <!-- Tag -->
                        <template v-if="field?.type === 'tag_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="`${field?.type.split('_')[0]}`"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        :data="liquid('tags')"
                                        value="all"
                                        :placeholder="field?.settings.placeholder"
                                        :disabled="!field?.settings.placeholder"
                                    >
                                        <option
                                            value="all"
                                            selected
                                            v-text="lang(field?.settings.placeholder, field?.type + '_select_all_' + index)"
                                        />
                                        <option
                                            v-for="(option, i) in liquid('tags').split(',')"
                                            :key="option"
                                            :selected="i == 0"
                                            :value="option.split('|')[0]"
                                            v-text="
                                                lang(
                                                    option.split('|').pop(),
                                                    field?.type + '_' + i
                                                )
                                            "
                                        />
                                    </select>
                                </div>
                            </div>
                        </template>
                        <!-- Product Type -->
                        <template v-if="field?.type === 'product_type_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        name="product_type"
                                        :required="field?.required"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        :data="liquid('product_types')"
                                        value="all"
                                        :placeholder="field?.settings.placeholder"
                                    >
                                        <option
                                            value="all"
                                            selected
                                            v-text="lang(field?.settings.placeholder, field?.type + '_select_all_' + index)"
                                            :disabled="!field?.settings.placeholder"
                                        />
                                        <option
                                            v-for="(option, i) in liquid('product_types').split(',')"
                                            :key="option"
                                            :selected="i == 0"
                                            :value="option.split('|')[0]"
                                            v-text="
                                                lang(
                                                    option.split('|').pop(),
                                                    field?.type + '_' + i
                                                )
                                            "
                                        />
                                    </select>
                                </div>
                            </div>
                        </template>
                        <!-- Price -->
                        <template v-if="field?.type === 'price_select'">
                            <div class="ecom-filter-search--container">
                                <div class="ecom-filter-search-content">
                                    <select
                                        :name="`${field?.type.split('_')[0]}`"
                                        class="ecom__filter-select"
                                        :id="
                                            field?.id ||
                                            `ecom-select-filter-search-${field?.type}-${index}`
                                        "
                                        value="all"
                                        v-html="liquid('price_options')"
                                        :placeholder="field?.settings.placeholder"
                                        :disabled="!field?.settings.placeholder"
                                    />
                                </div>
                            </div>
                        </template>
                        <label v-show="!field?.settings.placeholder">
                            <small style="color: red;" v-text="lang(this.$t('required_field_to_enable'), 'product_filter_required_field')"/>
                        </label>
                        <label v-show="checkSelectExist(field)">
                            <small style="color: red;" v-text="lang('* Custom name must be unique', 'notice_custom_name_must_unique')"></small>
                        </label>
                    </li>
                    <li ecom-filter-search--item ecom-html>
                        <div class="ecom__form-action">
                            <button
                                type="button"
                                class="ecom__form-filter-search-button"
                                :data="data.settings?.open_new_tab ? '_bank' : '_self'"
                            >
                                <span
                                    class="ecom_form-filter-search-submit--icon"
                                    v-if="data.settings.submit_icon"
                                    v-html="data.settings.submit_icon"
                                />
                                <span
                                    :id="data.settings?.tracking_id"
                                    class="ecom_form-filter-search-submit--text"
                                    v-html="lang(data.settings?.button_title, 'button_title')"
                                />
                            </button>
                        </div>
                    </li>
                </ul>
            </form>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from "@/mixins";
import liquid from "@/mixins/liquid";
import { data } from "autoprefixer";
export default {
    name: "ProductFilter",           // product filter
    presets: true,
    docs: "https://help.ecomposer.io/docs/editor-elements/shopify-elements/product-filter",
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },

    computed: {
        csrContext() {
            return {
                type: "product-filter"
            }
        },
        getUser() {
            return this.$store.getters['global/user'];
        },
        get_all_vendors() {
            return `{%- for vendor in shop.vendors -%}
                        {{-vendor-}}
                        {%- unless forloop.last -%}
                            ,
                        {%- endunless -%}
                    {%- endfor -%}
            `;
        },
        get_all_product_types() {
            return `
                    {%- assign all_product_types = '' -%}
                    {%- for collection in collections -%}
                        {%-for product in collection.products-%}
                            {%-unless all_product_types contains product.type-%}
                                {%-assign all_product_types = all_product_types | append: product.type | append: ','-%}
                            {%-endunless-%}
                        {%-endfor-%}
                    {%-endfor-%}
                    {%-assign unique_product_types = all_product_types | split: ',' | uniq-%}
                    {%-for product_type in unique_product_types-%}
                        {{- product_type -}}
                        {%-unless forloop.last-%}
                            ,
                        {%-endunless-%}
                    {%-endfor-%}
                    `;
        },
        get_all_tags() {
            return `
                    {%-assign all_tags = ''-%}
                    {%-for collection in collections-%}
                        {%-for product in collection.products-%}
                            {%-for tag in product.tags-%}
                            {%-unless all_tags contains tag-%}
                                {%-assign all_tags = all_tags | append: tag | append: ','-%}
                            {%-endunless-%}
                            {%-endfor-%}
                        {%-endfor-%}
                    {%-endfor-%}
                    {%-assign unique_tags = all_tags | split: ',' | uniq-%}
                    {%-for tag in unique_tags-%}
                        {{- tag -}}
                        {%-unless forloop.last-%}
                            ,
                        {%-endunless-%}
                    {%-endfor-%}
            `;
        },
        get_segment_price() {
            let segment_step = 5;
            let price_for_segment = 200;
            let price_filter_type = "segment";
            let placeholder = "";
            if (!this.data.settings?.filters) return;
            for (const field of this.data.settings?.filters) {
                if (field?.type === "price_select") {
                    placeholder = field?.settings.placeholder ?? placeholder;
                    price_filter_type = field?.settings?.price_filter_type ?? price_filter_type;
                    if (field?.settings?.price_filter_type === "segment") {
                        segment_step = field?.settings?.segment_steps ?? segment_step;
                    } else {
                        price_for_segment = field?.settings?.price_for_segment ?? price_for_segment;
                    }
                }
            }
            return `
                {% assign segment_step = ${segment_step} %}
                {% assign price_for_segment = ${price_for_segment * 100} %}
                {% assign price_filter_type = "${price_filter_type}" %}
                {% assign placeholder = "${placeholder}" %}
            `;
        },
        get_price_options() {
            return `
            ${this.get_segment_price}
            {% assign max_price_for_step = 0 %}
            {% for collection in collections %}
                {% for product in collection.products %}
                    {% if product.price_max > max_price_for_step %}
                        {% assign max_price_for_step = product.price_max %}
                    {% endif %}
                {% endfor %}
            {% endfor %}
            {% if price_filter_type == 'segment' %}
                {% assign price_step = max_price_for_step | divided_by: segment_step | ceil %}
            {% else %}
                {% assign price_step = price_for_segment %}
                {% assign segment_step = max_price_for_step | divided_by: price_step | ceil | plus: 1%}
            {% endif %}
                <option selected value="all">{{-placeholder-}}</option>
                {% for i in (0..segment_step) %}
                    {% if i < segment_step %}
                        {% assign price_range_start = i | times: price_step %}
                        {% assign price_range_end = price_range_start | plus: price_step | ceil %}
                        {% if price_range_end > max_price_for_step %}
                            {% assign price_range_end = max_price_for_step %}
                        {% endif %}
                        <option value="{{ price_range_start | divided_by: 100 }}-{{ price_range_end | divided_by: 100 }}">
                            {{ price_range_start | money }} - {{ price_range_end | money }}
                        </option>
                        {% if price_range_end == max_price_for_step %}
                            {% break %}
                        {% endif %}
                    {% endif %}
                {% endfor %}
            `;
        },

        liquids() {
            return {
                metafields: {
                    code: `
                    {%- for collection in collections -%}
                        {%- for filter in collection.filters -%}
                                <p>{{- filter.type -}}</p>
                        {%- endfor -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                collections: {
                    code: `
                    {%- for collection in collections -%}
                        {{-collection.handle}}|{{collection.title-}}
                        {%- unless forloop.last -%}
                            ,
                        {%- endunless -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                vendors: {
                    code: `
                    {%- for vendor in shop.vendors -%}
                        {{-vendor-}}
                        {%- unless forloop.last -%}
                            ,
                        {%- endunless -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                collection_vendors: {
                    code: `
                    {%- assign all_vendors = 'all' -%}
                    {{- all_vendors -}}:{%- for vendor in shop.vendors -%}
                            {{-vendor-}}
                            {%- unless forloop.last -%}
                                ,
                            {%- endunless -%}
                        {%- endfor -%}|
                    {%- for collection in collections -%}
                        {{-collection.handle-}}:
                        {%- for vendor in collection.all_vendors -%}
                            {{-vendor-}}
                            {%- unless forloop.last -%}
                                ,
                            {%- endunless -%}
                        {%- endfor -%}
                        {%- unless forloop.last -%}
                            |
                        {%- endunless -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                tags: {
                    code: `
                    {%-assign all_tags = ''-%}
                    {%-for collection in collections-%}
                        {%-for product in collection.products-%}
                            {%-for tag in product.tags-%}
                            {%-unless all_tags contains tag-%}
                                {%-assign all_tags = all_tags | append: tag | append: ','-%}
                            {%-endunless-%}
                            {%-endfor-%}
                        {%-endfor-%}
                    {%-endfor-%}
                    {%-assign unique_tags = all_tags | split: ',' | uniq-%}
                    {%-for tag in unique_tags-%}
                        {{- tag -}}
                        {%-unless forloop.last-%}
                            ,
                        {%-endunless-%}
                    {%-endfor-%}
                    `,
                    preview: ``
                },
                collection_tags: {
                    code: `
                    {%- assign all_select_title = 'all'-%}
                    {{- all_select_title -}}:${this.get_all_tags}|
                    {%- for collection in collections -%}
                        {{-collection.handle-}}:
                        {%- for tag in collection.all_tags -%}
                            {{-tag-}}
                            {%- unless forloop.last -%}
                                ,
                            {%- endunless -%}
                        {%- endfor -%}
                        {%- unless forloop.last -%}
                            |
                        {%- endunless -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                product_types: {
                    code: this.get_all_product_types,
                    preview: ``
                },
                collection_product_types: {
                    code: `
                    {%- assign all_product_types = '' -%}
                    {%- assign first_product_type = true -%}
                    {%- assign all_select_title = 'all'-%}
                    {{- all_select_title -}}:${this.get_all_product_types}|
                    {%- for collection in collections -%}
                        {{-collection.handle-}}:
                        {%- for product_type in collection.all_types -%}
                            {{-product_type-}}
                            {%- unless forloop.last -%}
                                ,
                            {%- endunless -%}
                        {%- endfor -%}
                        {%- unless forloop.last -%}
                            |
                        {%- endunless -%}
                    {%- endfor -%}
                    `,
                    preview: ``
                },
                price_options: {
                    code: this.get_price_options,
                    preview: ``
                }
            };
        },

        css() {
            return `
                .ecom-shopify__search-and-filter .ecom-iconlist--image img{
                    width: 20%;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--link{
                    text-decoration:none
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list{
                    display:grid;
                }
                .ecom-shopify__search-and-filter .ecom-filter-search--item{
                    position: relative
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='inline'] .ecom-filter-search--item{
                    display: flex;
                    align-items:center;
                }
                .ecom-shopify__search-and-filter .ecom-filter-search-content{
                    flex:1;
                    display:flex;
                    flex-direction:column;
                    gap:10px;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--title{
                    margin:0;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list, .ecom-filter-search--container {
                    margin: 0;
                    padding: 0;
                    list-style-type: none;
                }
                .ecom-shopify__search-and-filter .ecom-filter-search--container{
                    display:flex;
                    align-items:center;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='default'] .ecom-filter-search--container {
                    padding-top: calc(var(--ecom-spacing) / 2);
                    padding-bottom: calc(var(--ecom-spacing) / 2);
                }

                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='default'] .ecom-filter-search--item{
                    flex-direction:column;
                    display:flex;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='default']{
                    display:grid !important;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='inline']{
                    display: flex;
                    flex-wrap: wrap;
                    align-items: center;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='inline'] {
                    margin-left: calc(var(--ecom-spacing) / -2);
                    margin-right: calc(var(--ecom-spacing) / -2);
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--list[data-layout='inline'] .ecom-filter-search--container {
                    padding-left: calc(var(--ecom-spacing) / 2);
                    padding-right: calc(var(--ecom-spacing) / 2);
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--icon[data-image="true"]{
                    display: none;
                }
                .ecom-shopify__search-and-filter .ecom-iconlist--icon svg {
                    height: 37px;
                    width: 37px;
                }
                .ecom-shopify__search-and-filter .ecom-filter-search--container{
                    display: inline-flex;
                    align-items: center;
                }
                .ecom-shopify__search-and-filter .ecom__filter-select{
                    width: 100%;
                    padding: 10px;
                    border: 1px solid #ccc;
                    border-radius: 5px;
                }
                .ecom-shopify__search-and-filter .ecom__filter-select {
                    appearance: none;
                    -webkit-appearance: none;
                    -moz-appearance: none;
                    background-color: white;
                    border: 1px solid #ccc;
                    padding: 10px;
                    font-size: 16px;
                    border-radius: 4px;
                    background-image: url('data:image/svg+xml;utf8,<svg fill="%23ccc" height="24" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M7 10l5 5 5-5z"/></svg>'); /* Đường dẫn tới hình ảnh mũi tên */
                    background-repeat: no-repeat;
                    background-position: right 10px center;
                    background-size: 10px;
                    padding-right: 30px;
                }
                .ecom-shopify__search-and-filter .ecom__filter-select.first-option-selected {
                    color: #999!important;
                }

                .ecom-shopify__search-and-filter .ecom__filter-select::-ms-expand {
                    display: none;
                }
                .ecom-shopify__search-and-filter .ecom__form-action{
                    display: flex;
                    align-items: flex-end;
                    justify-content: left;
                    height: 100%;
                }
            `;
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: "paragraph",
                            options: {
                                warnings: {
                                    content: this.$t("this_element_is_used_to_filter_the_products_in_the_store_please_note_that_the_predefined_fields_for_collection_availability_vendor_product_type_price_and_tag_can_only_be_used_once")
                                }
                            }
                        },
                        {
                            type: 'group',
                            name: 'filters',
                            params: [
                                {
                                    type: 'availability_select',
                                    name: this.$t('show_availability_select'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: "text",
                                            name: "label",
                                            label: this.$t("label"),
                                            value: "Title",

                                        },
                                        {
                                            type: "text",
                                            name: "placeholder",
                                            label: this.$t("all_select_label"),
                                            value: this.$t("all_select_value"),
                                            description: this.$t("desc_of_all_select_availability")
                                        },
                                    ]
                                },
                                {
                                    type: 'collection_select',
                                    name: this.$t('show_collection_select'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: "text",
                                            name: "label",
                                            label: this.$t("label"),
                                            value: this.$t("label")
                                        },
                                        {
                                            type: "text",
                                            name: "placeholder",
                                            label: this.$t("all_select_label"),
                                            value: this.$t("all_select_value"),
                                            description: this.$t("desc_of_all_select_collection")
                                        },
                                        {
                                            type: "dropdown",
                                            name: "source_collection",
                                            label: this.$t("collection_source"),
                                            options: {
                                                default: false,
                                                preview: "title",
                                                values: {
                                                    all_collection: this.$t("all_collection"),
                                                    collections: this.$t("specific_collections")
                                                }
                                            },
                                            value: "all_collection"

                                        },
                                        {
                                            type: "picker",
                                            name: "collections",
                                            label: this.$t("select_the_collections_to_show"),
                                            options: {
                                                type: "collection",
                                                default: false,
                                                multiple: true,
                                                visible: function (data) {
                                                    return (
                                                        data["source_collection"] === "collections"
                                                    );
                                                }
                                            }
                                        },
                                    ]
                                },
                                {
                                    type: 'vendor_select',
                                    name: this.$t('show_vendor_select'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: "text",
                                            name: "label",
                                            label: this.$t("label"),
                                            value: this.$t("label")
                                        },
                                        {
                                            type: "text",
                                            name: "placeholder",
                                            label: this.$t("all_select_label"),
                                            value: this.$t("all_select_value"),
                                            description: this.$t("desc_of_all_select_vendor")
                                        },
                                    ]
                                },
                                {
                                    type: 'product_type_select',
                                    name: this.$t('show_product_type_select'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: "text",
