        javascript() {
            return function () {
                if (!this.$el || !this.isLive) return;
                const $el = this.$el;
                const selects = $el.querySelectorAll(".ecom__filter-select");
                const searchButton = $el.querySelector(".ecom__form-filter-search-button");
                let selectedCollection = "all";
                let collections = {};
                let collectionVendors = {};
                let collectionProductTypes = {};
                let collectionTags = {};
                selects.forEach((select) => {
                    if (select.name === "collection") {
                        const strCollections = select.getAttribute("collections");
                        const strVendors = select.getAttribute("vendors");
                        const strProductTypes = select.getAttribute("product_types");
                        const strTags = select.getAttribute("tags");
                        collections = parseStringCollection(strCollections);
                        collectionVendors = parseStringToObject(strVendors);
                        collectionProductTypes = parseStringToObject(strProductTypes);
                        collectionTags = parseStringToObject(strTags);
                        initCollectionSelect(collections);
                    }

                    if (select.name === "vendor") {
                        initVendorsSelect();
                    }

                    if (select.name === "product_type") {
                        initProductTypeSelect();
                    }

                    if (select.name === "tag") {
                        initTagSelect();
                    }

                    select.addEventListener("change", (e) => {
                        if (select.name === "collection") {
                            selectedCollection = e.target.value;
                            const vendors = collectionVendors[selectedCollection];
                            const productTypes = collectionProductTypes[selectedCollection];
                            const tags = collectionTags[selectedCollection];

                            updateVendorSelect(vendors);
                            updateProductType(productTypes);
                            updateTagSelect(tags);
                        }
                    });
                });

                searchButton.addEventListener("click", handleSearch);

                function initCollectionSelect(collections) {
                    const collectionSelect = $el.querySelector(
                        ".ecom__filter-select[name='collection']"
                    );
                    if (!collectionSelect) return;
                    const strSpecificCollections =
                        collectionSelect.getAttribute("specific_collections") ?? "";
                    const collectionSource = collectionSelect.getAttribute("collection_source");
                    while (collectionSelect.options.length > 1) {
                        collectionSelect.remove(1);
                    }
                    collections.forEach((collection) => {
                        const option = document.createElement("option");
                        option.value = collection.value;
                        option.text = collection.text;
                        collectionSelect.add(option);
                    });
                    if (collectionSource === "collections") {
                        const specificCollections = parseStringCollection(
                            strSpecificCollections
                        ).map((collection) => collection.value);
                        specificCollections.push("all");
                        for (let i = collectionSelect.options.length - 1; i >= 0; i--) {
                            const option = collectionSelect.options[i];
                            if (!specificCollections.includes(option.value)) {
                                collectionSelect.remove(i);
                            }
                        }
                    }
                }

                function updateVendorSelect(vendors) {
                    const vendorSelects = $el.querySelectorAll(
                        ".ecom__filter-select[name='vendor']"
                    );
                    if (!vendorSelects.length) return;

                    vendorSelects.forEach((vendorSelect) => {
                        while (vendorSelect.options.length > 1) {
                            vendorSelect.remove(1);
                        }

                        vendors.forEach((vendor) => {
                            const option = document.createElement("option");
                            option.value = vendor;
                            option.text = vendor;
                            vendorSelect.add(option);
                        });
                    });
                }

                function updateProductType(productTypes) {
                    const productTypeSelects = $el.querySelectorAll(
                        ".ecom__filter-select[name='product_type']"
                    );
                    if (!productTypeSelects.length) return;

                    productTypeSelects.forEach((productTypeSelect) => {
                        while (productTypeSelect.options.length > 1) {
                            productTypeSelect.remove(1);
                        }

                        productTypes
                            .filter((item) => item !== "")
                            .forEach((productType) => {
                                const option = document.createElement("option");
                                option.value = productType;
                                option.text = productType;
                                productTypeSelect.add(option);
                            });
                    });
                }

                function updateTagSelect(tags) {
                    const tagSelects = $el.querySelectorAll(".ecom__filter-select[name='tag']");
                    if (!tagSelects.length) return;

                    tagSelects.forEach((tagSelect) => {
                        while (tagSelect.options.length > 1) {
                            tagSelect.remove(1);
                        }

                        tags.forEach((tag) => {
                            const option = document.createElement("option");
                            option.value = tag;
                            option.text = tag;
                            tagSelect.add(option);
                        });
                    });
                }

                function initVendorsSelect() {
                    const vendorSelects = $el.querySelectorAll(
                        ".ecom__filter-select[name='vendor']"
                    );
                    if (!vendorSelects.length) return;

                    vendorSelects.forEach((vendorSelect) => {
                        const strVendors = vendorSelect.getAttribute("data");
                        while (vendorSelect.options.length > 1) {
                            vendorSelect.remove(1);
                        }

                        strVendors.split(",").forEach((vendor) => {
                            const option = document.createElement("option");
                            option.value = vendor;
                            option.text = vendor;
                            vendorSelect.add(option);
                        });
                    });
                }

                function initProductTypeSelect() {
                    const productTypeSelects = $el.querySelectorAll(
                        ".ecom__filter-select[name='product_type']"
                    );
                    if (!productTypeSelects.length) return;

                    productTypeSelects.forEach((productTypeSelect) => {
                        const strProductTypes = productTypeSelect.getAttribute("data");
                        while (productTypeSelect.options.length > 1) {
                            productTypeSelect.remove(1);
                        }

                        strProductTypes.split(",").forEach((productType) => {
                            const option = document.createElement("option");
                            option.value = productType;
                            option.text = productType;
                            productTypeSelect.add(option);
                        });
                    });
                }

                function initTagSelect() {
                    const tagSelects = $el.querySelectorAll(".ecom__filter-select[name='tag']");
                    if (!tagSelects.length) return;

                    tagSelects.forEach((tagSelect) => {
                        const strTags = tagSelect.getAttribute("data");
                        while (tagSelect.options.length > 1) {
                            tagSelect.remove(1);
                        }

                        strTags.split(",").forEach((tag) => {
                            const option = document.createElement("option");
                            option.value = tag;
                            option.text = tag;
                            tagSelect.add(option);
                        });
                    });
                }

                function parseStringToObject(str) {
                    const result = {};

                    const collections = str.split("|");
                    collections.forEach((collection) => {
                        const [key, value] = collection.split(":");
                        result[key] = value ? value.split(",") : [];
                    });

                    return result;
                }

                function parseStringCollection(str) {
                    const result = [];
                    const collections = str.split(",");
                    collections.forEach((collection) => {
                        const [key, value] = collection.split("|");
                        result.push({ value: key, text: value });
                    });
                    return result;
                }

                function convertOptionValuePrice(optionStr) {
                    console.log(optionStr);
                    let fromPrice = "";
                    let toPrice = "";

                    const [from, to] = optionStr.split("-");
                    fromPrice = from;
                    toPrice = to;
                    return { fromPrice, toPrice };
                }

                function setSelectValuesFromUrl(url) {
                    const urlObj = new URL(url);
                    const params = new URLSearchParams(urlObj.search);
                    const path = decodeURIComponent(urlObj.pathname);
                    const collectionMatch = path.match(/\/collections\/([^/?&]+)/);

                    if (collectionMatch) {
                        const collectionName = collectionMatch[1];
                        const selectElement = document.querySelector('select[name="collection"]');

                        if (selectElement) {
                            selectElement.value = collectionName;
                            const vendors = collectionVendors[collectionName];
                            const productTypes = collectionProductTypes[collectionName];
                            const tags = collectionTags[collectionName];

                            updateVendorSelect(vendors);
                            updateProductType(productTypes);
                            updateTagSelect(tags);
                        }
                    }

                    let priceRange = '';

                    params.forEach((value, key) => {
                        if (key.includes('custom')) {
                            const customName = key.split('custom.')[1]; // Lấy phần sau 'custom.'
                            const selectElement = document.querySelector(`select[name="custom.${customName}"]`);

                            if (selectElement) {
                                selectElement.value = value;
                            }
                        }
                        else if (key.includes('price')) {
                            if (key.endsWith('gte')) {
                                priceRange += value + '-';
                            } else if (key.endsWith('lte')) {
                                priceRange += value;
                            }
                        } else {
                            const nameParts = key.split('.');
                            const selectName = nameParts[nameParts.length - 1];

                            const selectElement = document.querySelector(`select[name="${selectName}"], select[id="${selectName}"]`);

                            if (selectElement) {
                                selectElement.value = value;
                            }
                        }
                    });

                    if (priceRange) {
                        const priceSelect = document.querySelector('select[name="price"]');
                        console.log(priceSelect);
                        if (priceSelect) {
                            priceSelect.value = priceRange;
                        }
                    }
                }
                setSelectValuesFromUrl(window.location.href);

                // selects.forEach((select) => {
                //     select.classList.toggle("first-option-selected", select.selectedIndex == 0);
                // });

                function handleSearch() {
                    let baseUrl = window.Shopify.shop + window.Shopify.routes.root;
                    // const baseUrl = window.location.origin;
                    const collectionUrl = "collections/";
                    const preFilterText = "filter.p.";
                    const prePriceText = "filter.v.";
                    const preCustomText = "filter.p.m.";
                    let queryUrl = "";
                    let queryParams = "";

                    // const typeAvailables = $el.querySelectorAll(".ecom-filter-type-available");

                    // Xác định URL của collection và thêm vào queryUrl trước
                    selects.forEach((select) => {
                        const name = select.name;
                        const value = select.value;

                        if (name === "collection") {
                            queryUrl += collectionUrl + value;
                        } else if (name === "price") {
                            if (value !== "all") {
                                const { fromPrice, toPrice } = convertOptionValuePrice(value);
                                if (fromPrice) {
                                    queryParams += `${prePriceText}${name}.gte=${fromPrice}&`;
                                }
                                if (toPrice) {
                                    queryParams += `${prePriceText}${name}.lte=${toPrice}&`;
                                }
                            }
                        } else if (name === 'availability')
                        {
                            if (value !== "all") {
                                queryParams += `${prePriceText}${name}=${value}&`;
                            }
                        }
                        else {
                            let nameParam = name;
                            if (value !== "all") {
                                if(['vendor', 'product_type', 'tag'].includes(name)) {
                                    queryParams += `${preFilterText}${nameParam}=${encodeURIComponent(
                                        value
                                    ).replace(/%20/g, "+")}&`;
                                }else{
                                    queryParams += `${preCustomText}${nameParam}=${encodeURIComponent(
                                        value
                                    ).replace(/%20/g, "+")}&`;
                                }

                            }
                        }
                    });

                    queryParams = queryParams.slice(0, -1);
                    if (!queryUrl) {
                        queryUrl += collectionUrl + "all";
                    }
                    const finalUrl = queryUrl + (queryParams ? "?" + queryParams : "");

                    // const searchUrl = `/search?${queryParams}`;
                    let target = searchButton.getAttribute("data");
                    if (!/^(https?:\/\/)/i.test(baseUrl)) {
                        baseUrl = 'https://' + baseUrl;
                    }
                    window.open(baseUrl + finalUrl, target);
                }
            };
        },

