    },
    methods: {
        getCollections(field) {
            return field?.type === "collection_select" &&
                field?.settings?.source_collection === "collections"
                ? (field?.settings?.collections ?? []).map((collection) => collection.value).join(",")
                : "";
        },
        getCollectionOptions(field) {
            const collections = this.getCollections(field);
            const allCollections = this.liquid("collections")
                .split(",")
                .map((item) => {
                    const [handle, title] = item.split("|");
                    return { handle, title, selected: false };
                });
            let strOptions = `<option selected value="all">${field?.settings.placeholder ? field.settings.placeholder : '' }</option>`;
            for (const collection of allCollections) {
                if (field?.settings?.source_collection === "collections") {
                    if (collections.includes(collection.handle)) {
                        strOptions += `<option value="${collection.handle}">${collection.title}</option>`;
                    }
                } else {
                    strOptions += `<option value="${collection.handle}">${collection.title}</option>`;
                }
            }
            return strOptions;
        },
        getCustomOptions(field) {
            const options = field?.settings?.options?.split("\n") ?? [];
            let strOptions = `<option selected value="all">${field?.settings.placeholder ? field.settings.placeholder : '' }</option>`;
            for (const option of options) {
                strOptions += `<option value="${option}">${option}</option>`;
            }
            return strOptions;
        },
        checkSelectExist(field) {
            let count = 0;
            for (const item of this.data?.settings.filters) {
                if(item?.type === 'custom_select' && field?.type === 'custom_select'){
                    item?.settings?.customName === field?.settings?.customName ? count++ : count;
                }

            }
            return count > 1;
        }
    }
};
