<template>
    <div class="ec-preset-picker" role="radiogroup" :aria-label="field?.label ?? 'Preset'">
        <!-- No label of its own: Field.vue already draws one above the control. -->
        <button
            v-for="(option, index) in options"
            :key="option.value"
            ref="cards"
            type="button"
            class="ec-preset-picker__card"
            :class="{ 'ec-preset-picker__card--selected': option.value === selected }"
            :data-preset="option.value"
            role="radio"
            :aria-checked="option.value === selected ? 'true' : 'false'"
            :tabindex="option.value === selected ? 0 : -1"
            @click="select(option.value)"
            @keydown="onKeydown($event, index)"
        >
            <span class="ec-preset-picker__thumb" aria-hidden="true">
                <span class="ec-preset-picker__panel">
                    <span class="ec-preset-picker__bar"></span>
                    <span class="ec-preset-picker__rows">
                        <span class="ec-preset-picker__row"></span>
                        <span class="ec-preset-picker__row"></span>
                        <span class="ec-preset-picker__row"></span>
                        <span class="ec-preset-picker__row"></span>
                    </span>
                </span>
                <span class="ec-preset-picker__dot"></span>
            </span>
            <span class="ec-preset-picker__name">{{ option.label }}</span>
        </button>
    </div>
</template>

<script>
    /**
     * Style presets as a grid of cards, each a miniature of the skin it applies.
     *
     * The same field type is rendered a second time by the Polaris Extensions
     * Hub, off the same settings.json: see the main app's
     * `resources/extension-settings/src/components/fields/PresetPickerField.ts`
     * and the `.ec-preset-picker` block of its `src/styles.css`. The builder is
     * a separate repo and a separate Vite project, so the markup and the CSS
     * below are a copy, not an import - a change to how a card looks has to be
     * made in both places or the two forms drift apart.
     */

    /* Preset keys renamed after shops had already saved a value. The storefront
       widget maps them the same way, so highlighting follows what is applied. */
    const ALIASES = { dark: 'midnight', rounded: 'soft' };

    export default {
        name: 'Preset_pickerField',
        props: {
            // eslint-disable-next-line vue/require-default-prop
            data: [String, Number],
            field: {
                type: Object,
                default(){
                    return {};
                }
            }
        },
        emits: ['update:data'],
        computed: {
            /* Accepts `{ key: label }`, `[{ value, label }]` or `['a', 'b']`.
               Labels arrive already translated: the extensions store resolves
               every `$t:` token in the settings tree before the fields mount. */
            options(){
                const raw = this.field?.options?.values;
                if (Array.isArray(raw)){
                    return raw.map((item) => {
                        if (item && typeof item === 'object'){
                            const value = String(item.value ?? item['key'] ?? '');
                            return { value, label: String(item.label ?? item.name ?? value) };
                        }
                        return { value: String(item), label: String(item) };
                    });
                }
                if (raw && typeof raw === 'object'){
                    return Object.entries(raw).map(([name, label]) => ({
                        value: name,
                        label: String(label ?? name)
                    }));
                }
                return [];
            },
            selected(){
                /* `__delete__` is the reset sentinel the fields use for "nothing
                   saved"; like an unknown key it falls back to the schema default
                   and then to the first card, so a card is always lit. */
                let raw = this.data ?? '';
                if (raw === '__delete__' || raw === '') raw = this.field?.value ?? this.field?.default ?? '';
                raw = String(raw);
                const value = ALIASES[raw] ?? raw;
                if (this.options.some((option) => option.value === value)) return value;
                return this.options[0]?.value ?? '';
            }
        },
        methods: {
            select(value){
                if (value === this.selected) return;
                this.$emit('update:data', value);
            },
            onKeydown(event, index){
                const step = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1
                    : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1
                        : 0;
                if (!step) return;
                event.preventDefault();
                const total = this.options.length;
                if (!total) return;
                const next = (index + step + total) % total;
                this.select(this.options[next].value);
                this.$refs.cards?.[next]?.focus();
            }
        }
    };
</script>

