<template>
    <div class="w-6 h-48 rounded-2xl cursor-pointer ecom-color-hue">
        <div
            ref="vslider"
            class="color-slider color-slider-vertical h-full"
            @mousedown="onDragStart"
        >
            <div
                class="ecom-picker-slider-new h-5 w-5 rounded-full absolute pointer-events-none left-1/2 translate-y-0.5 -translate-x-1/2"
                :style="pointStyle"
            />
        </div>
    </div>
</template>

<script lang="ts">
import { getElSizePosition, getValInRange } from "./untility.ts";

export default {
    props: {
        value: {
            type: Number,
            default: 0
        }
    },
    data() {
        return {
            elSizePostion: {}
        };
    },
    computed: {
        pointStyle() {
            let cls = {};
            const value = getValInRange(this.value, 0, 100);
            cls.top = "calc(" + (168 * value) / 100 + "px)";
            return cls;
        }
    },
    methods: {
        resetOffset() {
            let $el = this.$refs.vslider;
            let { width, height, left, top } = getElSizePosition($el);
            this.elSizePostion = { width, height, left, top };
        },
        onDragStart(e) {
            this.resetOffset();
            this.onDragging(e);
            this.bindGlobalEvent();
        },
        onDragging(e) {
            let { pageY } = e;
            let { height, top } = this.elSizePostion;
            top = pageY - top;
            let percent = (top / height) * 100;
            percent = percent < 0 ? 0 : percent > 100 ? 100 : parseFloat(percent.toFixed(4));
            this.$emit("change", percent);
        },
        onDragEnd() {
            this.unbindGlobalEvent();
        },
        bindGlobalEvent() {
            window.addEventListener("mousemove", this.onDragging);
            window.addEventListener("mouseup", this.onDragEnd);
        },
        unbindGlobalEvent() {
            window.removeEventListener("mousemove", this.onDragging);
            window.removeEventListener("mouseup", this.onDragEnd);
        }
    }
};
</script>

