<template>
    <template v-if="link && url !== ''">
        <a v-bind:href="url" :class="[styleTypo, buttonSize, lightMode, darkMode]" :target="target">
            <EcomIcon v-if="icon !== ''" :source='icon' :size="sizeIcon" class="inline-flex justify-center items-center mx-1.5 px-0.5"></EcomIcon>
            <slot></slot>
        </a>
    </template>
    <template v-else-if="!split">
        <button type="button" :disabled="disabled || loading" :id="id"  class="outline-interactive-600 flex gap-1 px-2" :class="[styleTypo, buttonSize, lightMode, darkMode]" @click="onAction" :data-tooltip="dataTooltip">
            <Loading v-if="loading" type="spin" :size="5" />
            <template v-else>
                <slot name="before"></slot>
                <EcomIcon v-if="icon !== ''" :source='icon' :size="sizeIcon" :color="colorIcon" class="inline-flex justify-center items-center"></EcomIcon>
                <span v-if="$slots.default"><slot></slot></span>
                <slot name="after"></slot>
            </template>
        </button>
    </template>
    <template v-else>
        <div class="inline-flex relative before:bg-transparent button-pullic">
            <div class="inline-flex" >
                <button type="button" :data-tooltip="dataTooltip" :disabled="disabled" :id="id"  :class="[styleTypo, buttonSize, lightMode, darkMode]" class="bg-dark hover:bg-[#1a1a1a] btn-public relative rounded-r-none rounded-lg border-r-0 !outline-none transition hover:transition duration-300 pr-3 pl-3" @click="onAction">
                    <slot name="before"></slot>
                    <EcomIcon v-if="icon !== ''" :source='icon' :size="'w-5'" class="inline-flex justify-center items-center mr-1.5 px-0.5"></EcomIcon>
                    <slot></slot>
                    <slot name="after"></slot>
                    <span class="border-l border-[#30303060] absolute -right-px -top-px -bottom-px"></span>
                </button>
                <div ref="mainSplit">
                    <button type="button" :disabled="disabled" :class="[styleTypo , buttonSize, lightMode, darkMode, btnSplitClass]" class="bg-dark hover:bg-[#1a1a1a] rounded-l-none rounded-lg !outline-none" @click="splitShow = !splitShow">
                        <EcomIcon :source="CaretDownMinor" :size="'w-5'"></EcomIcon>
                    </button>
                </div>
            </div>
            <Transition
                enter-active-class="transition ease-out duration-10"
                enter-from-class="transform -translate-y-2 scale-90 opacity-0"
                enter-to-class="transform translate-y-100 scale-100 opacity-100"
                leave-active-class="transition ease-out duration-15"
                leave-from-class="transform translate-y-100 scale-100 opacity-100"
                leave-to-class="transform -translate-y-2 scale-90 opacity-0"
            >
                <ul v-if="splitShow" class="absolute right-0 top-full shadow-lg bg-white rounded-lg min-w-30 p-2 mt-1     border-gray-100 border">
                    <template v-for="(item, key) in actions">
                        <li v-if="item.hidden === false" :key="key" class="mb-1 last:mb-0">
                            <ecom-button fullWidth :icon="item.icon" @click="item.onAction" class="!justify-start font-normal border-0 whitespace-nowrap hover:bg-gray-100  !shadow-none transition hover:transition duration-300 min-w-[180px]">{{ item.title }}</ecom-button>
                        </li>
                    </template>
                </ul>
            </Transition>
        </div>
    </template>
</template>

<script lang="ts">
    import { CaretDownMinor } from '@/assets/icons'
    export default {
        props: {
            default: {
                type: Boolean,
                default: false
            },
            outline: {
                type: Boolean,
                default: false,
            },
            primary: {
                type: Boolean,
                default: false,
            },
            destructive: {
                type: Boolean,
                default: false,
            },
            critical: {
                type: Boolean,
                default: false,
            },
            link: {
                type: Boolean,
                default: false,
            },
            url: {
                type: String,
                default: '',
            },
            icon: {
                type: String,
                default: '',
            },
            size: {
                type: String,
                default: 'medium',
            },
            fullWidth: {
                type: Boolean,
                default: false,
            },
            // small,medium,large
            split: {
                type: Boolean,
                default: false,
            },
            onAction: {
                type: Function,
                default: null,
            },
            actions: {
                type: Array,
                default: null,
            },
            target: {
                type: String,
                default: '_blank',
            },
            plain: {
                type: Boolean,
                default: false,
            },
            dataTooltip:{
                type: String,
                default: '',
            },
            disabled: {
                type: Boolean,
                default: false,
            },
            id:{
                type: String,
                default: '',
            },
            loading: {
                type: Boolean,
                default: false
            },
            iconColor: {
                type: String,
                default: ''
            },
            picker: {
                type: Boolean,
                default: false
            },
            customStyle:{
                type:Boolean,
                default:false
            }
        },
        data(){
            return {
                CaretDownMinor: CaretDownMinor,
                splitShow: false,
                // darkMode: '',
                // styleTypo: '',
            }
        },
        computed: {
            sizeIcon(){
                switch (this.size) {
                    case 'small':
                        return 'w-5';
                        break;
                    case 'medium':
                        return 'w-6';
                        break;
                    case 'large':
                        return 'w-7';
                        break;
                    default:
                        return this.size;
                        break;
                }

            },
            colorIcon(){
                if(this.iconColor) {
                    return this.iconColor;
                }
                if(this.default) {
                    return 'text-[#414141]'
                }
                if(this.critical) {
                    return 'text-white'
                }
                if(this.plain)
                {
                    if(this.destructive )
                    {
                        return 'text-red-900';
                    }
                    if(this.primary)
                    {
                        return 'text-primary-700';
                    }
                }
                if(this.primary || this.destructive){
                    return 'text-white';
                }
                return '';
            },
            lightMode(){
                if(this.default) {
                    return 'bg-transparent hover:bg-[#fafafa] relative ec-button-outline-shadow';
                }
                if(this.critical) {
                    return 'bg-[#E51C00] text-white hover:bg-danger-700 relative ec-button-critical-shadow';
                }
                if(this.outline){
                    return 'bg-transparent border-gray-200 hover:bg-gray-100';
                }

                if(this.primary){
                    if(this.plain)
                    {
                        return 'text-primary-700 hover:bg-gray-200'
                    }
                    return 'text-white !bg-dark hover:bg-[#1a1a1a] ec-shadow-button relative';
                }

                if(this.destructive){
                    if(this.plain)
                    {
                        return 'text-red-900 hover:bg-gray-200'
                    }
                    return 'text-white bg-danger-600 hover:bg-danger-700 hover:shadow-lg';
                }

                if(this.link){
                    return '';
                }

                if(this.picker) {
                    return 'hover:bg-surface-tertiary-active';
                }

                if(this.customStyle){
                    return '';
                }
                
                return 'bg-white hover:bg-gray-100';
            },
            darkMode(){

                if(this.outline){
                    return '   ';
                }
                if(this.primary || this.destructive || this.link){
                    return '';
                }
                return '  ';
            },

            styleTypo(){
                if(this.outline){
                    return 'inline-flex items-center justify-center font-medium text-sm border rounded-lg py-1 px-3';
                }

                if(this.primary || this.destructive){
                    return 'inline-flex items-center justify-center font-medium text-sm border border-transparent rounded-lg py-1 px-3';
                }

                if(this.link){
                    return 'inline-flex items-center justify-center font-medium border border-transparent text-sm underline underline-offset-2 hover:text-primary-700';
                }

                return 'inline-flex items-center justify-center font-medium text-sm rounded py-1 px-3';
            },
            buttonSize(){
                let tmp = '';
                switch (this.size) {
                    case 'small':
                        tmp += ' h-7 !text-xs';
                        break;
                    case 'medium':
                        tmp += ' h-8 text-sm';
                        break;
                    case 'large':
                        tmp += ' h-10 !text-base';
                        break;
                    default:
                        break;
                }
                this.fullWidth ? tmp += ' !flex w-full' : '';
                return tmp;
            },
            btnSplitClass(){
                if(this.primary || this.destructive){
                    return 'ml-[1px]';
                }
            }
        },
        mounted() {
            document.addEventListener("click", this.handleClickOutside);
        },
        beforeDestroy() {
            document.removeEventListener("click", this.handleClickOutside);
        },
        methods: {
            handleClickOutside(event) {
                const mainSplitElement = this.$refs.mainSplit;
                if (mainSplitElement && !mainSplitElement.contains(event.target) && this.splitShow) {
                    this.splitShow = false;
                }
            },
        },
    }
</script>

