        right: -1px;
        border-radius: 10px;
        z-index: 11;
        pointer-events: none;
        transition: 0.1s;
    }
    .ec-button-critical-shadow:active::before {
        box-shadow: -0.0625rem 0rem 0.0625rem 0rem rgba(26, 26, 26, .122) inset, 0.0625rem 0rem 0.0625rem 0rem rgba(26, 26, 26, .122) inset, 0rem 0.125rem 0.0625rem 0rem rgba(26, 26, 26, .2) inset;
    }
    .button-pullic::before{
        background-color: transparent;
        box-shadow: 0rem 0.125rem 0rem 0rem #fff3 inset, 0.125rem 0rem 0rem 0rem #fff3 inset, -0.125rem 0rem 0rem 0rem #fff3 inset, 0rem -0.0625rem 0rem 0.0625rem #000 inset, 0rem 0.0625rem 0rem 0rem #000 inset;
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        border-radius: 10px;
        z-index: 11;
        pointer-events: none;
    }
    .button-pullic .ec-shadow-button::before{
        display: none;
    }
    button:disabled {
        opacity: .5;
        pointer-events: none;
        cursor: not-allowed;
    }
</style>
