// store/modules/library/mutations.ts
import type {
    LibraryState,
    LibraryContextState,
    LibraryCacheState,
    LibraryStatusState,
    LibraryQuery,
} from './types';

export default {
    // ── Context ──────────────────────────────────────────────────────────────

    /**
     * Merge vào context. Nếu payload có `query`, merge sâu thêm một lớp
     * để không ghi đè toàn bộ query khi chỉ muốn đổi một vài field.
     */
    setContext(state: LibraryState, payload: Partial<LibraryContextState>): void {
        state.context = {
            ...state.context,
            ...payload,
            query: {
                ...state.context.query,
                ...(payload.query ?? {}),
            },
        };
    },

    /** Merge vào context.query. */
    setQuery(state: LibraryState, payload: Partial<LibraryQuery>): void {
        state.context.query = { ...state.context.query, ...payload };
    },

    // ── Cache – meta ──────────────────────────────────────────────────────────

    /**
     * Merge vào toàn bộ cache. Nếu payload có `meta`, merge sâu thêm một lớp
     * để giữ các meta field không có trong payload.
     */
    setCache(state: LibraryState, payload: Partial<LibraryCacheState>): void {
        state.cache = {
            ...state.cache,
            ...payload,
            meta: {
                ...state.cache.meta,
                ...(payload.meta ?? {}),
            },
        };
    },

    /** Merge một số field vào cache.meta mà không đụng đến cache.lists. */
    setMeta(state: LibraryState, payload: Partial<LibraryCacheState['meta']>): void {
        state.cache.meta = { ...state.cache.meta, ...payload };
    },

    /** Cập nhật currentNiche trong meta (merge nông). */
    setCurrentNiche(
        state: LibraryState,
        payload: { pages?: { id: string; title?: string }; sections?: { id: string; title?: string } },
    ): void {
        state.cache.meta.currentNiche = { ...state.cache.meta.currentNiche, ...payload };
    },

    /** Thêm source mới nếu chưa tồn tại (dùng từ page.ts). */
    addSource(state: LibraryState, payload: LibraryCacheState['meta']['sources'][number]): void {
        if (!state.cache.meta.sources.find((s) => s.id === payload.id)) {
            state.cache.meta.sources = [...state.cache.meta.sources, payload];
        }
    },

    /** Set toàn bộ danh sách sources. */
    setSource(state: LibraryState, payload: LibraryCacheState['meta']['sources']): void {
        state.cache.meta.sources = payload;
    },

    /** Set categories (alias setSourceCategories dùng từ page.ts). */
    setSourceCategories(state: LibraryState, payload: any[]): void {
        state.cache.meta.categories = payload;
    },

    /** Set favorites. */
    favorites(state: LibraryState, payload: Array<string | number>): void {
        state.cache.meta.favorites = payload;
    },

    // ── Cache – lists ─────────────────────────────────────────────────────────

    /** Ghi đè toàn bộ một key trong cache.lists. */
    setList(state: LibraryState, payload: { key: string; list: any }): void {
        state.cache.lists = { ...state.cache.lists, [payload.key]: payload.list };
    },

    /** Merge một phần vào một key trong cache.lists. */
    patchList(state: LibraryState, payload: { key: string; patch: Record<string, any> }): void {
        const current = state.cache.lists[payload.key] ?? {};
        state.cache.lists = {
            ...state.cache.lists,
            [payload.key]: { ...current, ...payload.patch },
        };
    },

    /**
     * Merge object vào cache.lists (backward-compat).
     * - Nếu cả giá trị cũ lẫn mới đều là object (không phải array) thì merge nông thêm
     *   một cấp, để cập nhật sections.trending không ghi đè mất sections.popular…
     * - Ngược lại ghi đè thẳng.
     * - Luôn tăng cacheVersion để listOfData getter re-compute.
     */
    mergeLists(state: LibraryState, payload: Record<string, any>): void {
        const next: Record<string, any> = { ...state.cache.lists };
        for (const key of Object.keys(payload)) {
            const prev = next[key];
            const val  = payload[key];
            const prevIsObj = prev != null && typeof prev === 'object' && !Array.isArray(prev);
            const valIsObj  = val  != null && typeof val  === 'object' && !Array.isArray(val);
            next[key] = prevIsObj && valIsObj ? { ...prev, ...val } : val;
        }
        state.cache.lists = next;
        // Trigger getter re-computation kể cả khi chỉ có cache.lists thay đổi
        state.cacheVersion++;
    },

    // ── Cache layer ──────────────────────────────────────────────────────────

    /**
     * Ghi nhớ cache key hiện tại cho một tab.
     * Tự động tăng cacheVersion để listOfData getter re-compute.
     * Dùng bởi actions.load() sau khi CacheService.set() thành công.
     */
    setActiveKey(state: LibraryState, payload: { tab: string; key: string }): void {
        state.activeKeys = { ...state.activeKeys, [payload.tab]: payload.key };
        state.cacheVersion++;
    },

    /**
     * Bỏ activeKey của một tab.
     *
     * Dùng khi response được ghi thẳng vào cache.lists mà KHÔNG đi qua CacheService
     * (detail mode: tab pages đặt detailKey theo sort, theme_pages…). Giữ lại activeKey
     * cũ thì getter listOfData sẽ overlay entry cache của lần fetch trước đè lên dữ liệu
     * vừa merge → list "đứng yên" dù API đã trả đúng filter/search.
     */
    clearActiveKey(state: LibraryState, tab: string): void {
        if (!tab || !(tab in state.activeKeys)) return;
        const next = { ...state.activeKeys };
        delete next[tab];
        state.activeKeys = next;
        state.cacheVersion++;
    },

    /**
     * Tăng cacheVersion thủ công (dùng khi CacheService cập nhật
     * nhưng activeKey không đổi, ví dụ: background revalidate).
     */
    incrementCacheVersion(state: LibraryState): void {
        state.cacheVersion++;
    },

    // ── Status ────────────────────────────────────────────────────────────────

    /**
     * Merge vào status. Nếu payload có `preview`, merge sâu thêm một lớp
     * để giữ các field không đổi (ví dụ: markup, screen).
     */
    setStatus(state: LibraryState, payload: Partial<LibraryStatusState>): void {
        state.status = {
            ...state.status,
            ...payload,
            preview: {
                ...state.status.preview,
                ...(payload.preview ?? {}),
            },
        };
    },

    /** Merge vào status.preview (dùng khi chỉ cần cập nhật preview). */
    setPreview(state: LibraryState, payload: Partial<LibraryStatusState['preview']>): void {
        state.status.preview = { ...state.status.preview, ...payload };
    },

    // ── Status – shortcuts (tên giữ nguyên để tương thích component cũ) ──────

    showSaveForm(state: LibraryState, payload: boolean): void {
        state.status.showSaveForm = payload;
    },

    detailTask(state: LibraryState, payload: boolean): void {
        state.status.detailTask = payload;
    },

    setDetailPost(state: LibraryState, payload: any): void {
        state.status.detailPost = payload;
    },

    /**
     * Đặt detail đang xem. Nhận { id, title? } hoặc null để đóng.
     * Lưu vào context.query.detailKey thay vì state riêng.
     */
    setDetailScreen(state: LibraryState, payload: { id: string; title?: string } | null): void {
        state.context.query = {
            ...state.context.query,
            detailKey: payload?.id ?? null,
        };
    },
};
