            <template v-for="(item, index) in items" :key="index">
                <component :is="item?.link?.href ? 'a' : 'div'" class="ecom-marquee_item" v-bind="item?.link">
                    <component :is="data.settings.tag || 'h3'"
                        v-html="lang(item.text, 'marquee_text' + index)"
