            return function () {
                if(!this.$el) return;
                const isLive = this.isLive, $el = this.$el;
                let checkLang = document.querySelector('html[dir="rtl"]');
                class MarqueeComponent extends HTMLElement {
                    constructor() {
                        super();
                        //   this.attachShadow({ mode: "open" });
                        this.containerWidth = 0;
                        this.marqueeWidth = 0;
                        this.multiplier = 1;
                        this.isMounted = false;

                        // Default props (can be overwritten by attributes)
                        this.styleProp = {};
                        this.classNameProp = "";
                        this.autoFillProp = false;
                        this.playProp = true;
                        this.pauseOnHoverProp = false;
                        this.pauseOnClickProp = false;
                        this.directionProp = "left";
                        this.speedProp = 50;
                        this.delayProp = 0;
                        this.loopProp = 0;
                        this.gradientProp = false;
                        this.gradientColorProp = "white";
                        this.gradientWidthProp = 200;

                        // Refs
                        this.rootRef = null;
                        this.containerRef = null;
                        this.marqueeRef = null;
                        this.childrenHtml = '';
                        this.interval = 0;
                        this.duration = 0;
                        // Do NOT call render() in constructor — Safari enforces the Custom Elements
                        // spec which forbids innerHTML manipulation before the element is connected.
                        // render() is called in connectedCallback instead.
                    }

                        checkRTL() {
                            if (this.isMounted) {
                                const style = window.getComputedStyle(this);
                                if (style.direction === 'rtl') return true;
                            }
                            const htmlDir = document.documentElement.getAttribute('dir');
                            const bodyDir = document.body.getAttribute('dir');
                            return htmlDir === 'rtl' || bodyDir === 'rtl';
                        }

                    static get observedAttributes() {
                        return [
                            "style",
                            "class-name",
                            "auto-fill",
                            "play",
                            "pause-on-hover",
                            "pause-on-click",
                            "direction",
                            "speed",
                            "delay",
                            "loop",
                            "gradient",
                            "gradient-color",
                            "gradient-width",
                        ];
                    }

                    connectedCallback() {
                        this.isMounted = true;
                        // @ts-ignore
                        this.childrenHtml = this.innerHTML;
                        this.render();
                        const imgs = this.querySelectorAll('img');
                        if(imgs.length > 0) {
                            let started = false;
                            const startInterval = () => {
                                if (started) return;
                                started = true;
                                this.interval = setInterval(() => this.handle(), 500);
                            };
                            // Fallback: Safari sometimes doesn't fire onload/onerror for duplicate
                            // img elements created via innerHTML when src is already cached.
                            // Start the interval after 2s regardless.
                            setTimeout(startInterval, 2000);
                            Promise.all(Array.from(imgs).filter(img => !img.complete).map(img => new Promise(resolve => { img.onload = img.onerror = resolve; }))).then(startInterval);
                        }
                        else {
                            setTimeout(() => {this.handle()}, 500);
                            this.interval = setInterval(() => this.handle(), 500)
                        }
                    }

                    attributeChangedCallback(name, oldValue, newValue) {
                        switch (name) {
                            case "style":
                                this.styleProp = newValue;
                                break;
                            case "class-name":
                                this.classNameProp = newValue;
                                break;
                            case "auto-fill":
                                this.autoFillProp = newValue !== null;
                                break;
                            case "play":
                                this.playProp = newValue !== null;
                                break;
                            case "pause-on-hover":
                                this.pauseOnHoverProp = newValue == 'true' ? true : false;
                                break;
                            case "pause-on-click":
                                this.pauseOnClickProp = newValue !== null;
                                break;
                            case "direction":
                                // this.directionProp = newValue;
                                const isRTL = this.checkRTL();
                                if(newValue == 'right') {
                                    this.directionProp = isRTL ? 'right' : 'left'
                                }
                                else {
                                    this.directionProp = isRTL ? 'left' : 'right'
                                }
                                break;
                            case "speed":
                                this.speedProp = parseInt(newValue, 10) || 50;
                                break;
                            case "delay":
                                this.delayProp = parseInt(newValue, 10) || 0;
                                break;
                            case "loop":
                                this.loopProp = parseInt(newValue, 10) || 0;
                                break;
                            case "gradient":
                                this.gradientProp = newValue !== null;
                                break;
                            case "gradient-color":
                                this.gradientColorProp = newValue || "white";
                                break;
                            case "gradient-width":
                                this.gradientWidthProp = parseInt(newValue, 10) || 200;
                                break;
                        }
                        // Only render after connected — before that, props are just stored
                        // and render() will be called with all correct prop values in connectedCallback.
                        // @ts-ignore — TS can't infer this.isMounted from constructor in nested class
                        if (this.isMounted) this.render();
                    }

                    render() {
                        const isRTL = this.checkRTL();
                        const styleModify = `
                        --transform: ${this.directionProp === "up"
                                ? "rotate(-90deg)"
                                : this.directionProp === "down"
                                    ? "rotate(90deg)"
                                    : "none"};
                        --width: ${this.directionProp === "up" || this.directionProp === "down" ? `100vh` : "100%"};
                        --pause-on-hover: ${!this.playProp || this.pauseOnHoverProp ? "paused" : "running"};
                        display: flex;
                        `

                        const style = `

                        --duration: ${this.duration}s;
                        --play: ${this.playProp ? 'running' : 'pause'};
                        --direction: ${this.directionProp === "left" ? "normal" : "reverse"};
                        --delay: 0s;
                        --iteration-count: infinite;
                        --min-width: ${this.autoFillProp ? `auto` : "100%"};
                        --percent-start: ${!isRTL ? "0%" : "100%"};
                        --percent-end: ${!isRTL ? "-100%" : "0%"};
                        display: flex;
                    `;
                        const html = `
                        <div class="ecom-text-marquee-container ${this.classNameProp}" style="${styleModify}">
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                            <div class="ecom-text-marque-wrapper" style="${style}">
                                ${this.renderChildren()}
                            </div>
                        </div>
                    `;

                        this.innerHTML = html;
                        this.rootRef = this.querySelector(".ecom-text-marquee-container");
                        this.marqueeRef = this.querySelector(".ecom-text-marque-wrapper");
                    }

                    calculateWidth() {
                        const containerRect = this.rootRef.getBoundingClientRect();
                        const marqueeRect = this.marqueeRef.getBoundingClientRect();
                        this.containerWidth = containerRect.width > containerRect.height ? containerRect.width : containerRect.height;
                        this.marqueeWidth = marqueeRect.width > marqueeRect.height ? marqueeRect.width : marqueeRect.height;
                        this.multiplier = this.autoFillProp && this.containerWidth && this.marqueeWidth
                            ? Math.ceil(this.containerWidth / this.marqueeWidth) + 1
                            : 1;

                    }
                    calculateDuration() {
                        if (this.autoFillProp) {
                            this.duration = (this.marqueeWidth * this.multiplier) / this.speedProp;
                        } else {
                            this.duration = this.marqueeWidth < this.containerWidth
                                ? this.containerWidth / this.speedProp
                                : this.marqueeWidth / this.speedProp;
                        }
                        this.render();
                    }

                    renderChildren() {
                        let childrenHtml = "";
                        for (let i = 0; i < this.multiplier; i++) {
                            childrenHtml += `<div class="ecom-text-marquee-child" style="display: flex">${this.childrenHtml}</div>`;
                        }
                        return childrenHtml;
                    }

                    addEventListeners() {
                        if (this.pauseOnHoverProp) {
                            this.rootRef.addEventListener("mouseenter", () => {
                                this.playProp = false;
                                // this.render();
                            });
                            this.rootRef.addEventListener("mouseleave", () => {
                                this.playProp = true;
                                // this.render();
                            });
                        }

                        if (this.pauseOnClickProp) {
                            this.rootRef.addEventListener("click", () => {
                                this.playProp = !this.playProp;
                            });
                        }

                        this.marqueeRef.addEventListener("animationiteration", () => {
                            if (typeof this.onCycleComplete === "function") {
                                this.onCycleComplete();
                            }
                        });

                        this.marqueeRef.addEventListener("animationend", () => {
                            if (typeof this.onFinish === "function") {
                                this.onFinish();
                            }
                        });
                    }
                    handle() {
                        const _this = this;
                        if(!this.duration) {
                            _this.calculateWidth();
                            _this.calculateDuration();
                            _this.addEventListeners();
                            _this.classList.add('show')
                        }
                        else {
                            clearInterval(_this.interval);
                        }
                    }
                }
                if (!customElements.get('ecom-marquee-component')) {
                    customElements.define('ecom-marquee-component', MarqueeComponent);
                }
