        css() {
            return `
                ecom-marquee-component {
                    opacity: 0;
                    visibility: hidden;
                    height: 0;
                }
                ecom-marquee-component.show {
                    opacity: 1;
                    visibility: visible;
                    height: auto
                }
                .ecom-text-marquee-container {
                    overflow-x: hidden;
                    display: flex;
                    flex-direction: row;
                    position: relative;
                    width: var(--width);
                    transform: var(--transform);
                }

                .ecom-text-marquee-container:hover div {
                    animation-play-state: var(--pause-on-hover);
                }

                .ecom-text-marquee-container:active div {
                    animation-play-state: var(--pause-on-click);
                }

                .ecom-text-marquee-overlay {
                    position: absolute;
                    width: 100%;
                    height: 100%;
                }

                .ecom-text-marquee-overlay::before,
                .ecom-text-marquee-overlay::after {
                    background: linear-gradient(to right, var(--gradient-color), #fff);
                    content: "";
                    height: 100%;
                    position: absolute;
                    width: var(--gradient-width);
                    z-index: 2;
                    pointer-events: none;
                    touch-action: none;
                }

                .ecom-text-marquee-overlay::after {
                    right: 0;
                    top: 0;
                    transform: rotateZ(180deg);
                }

                .ecom-text-marquee-overlay::before {
                    left: 0;
                    top: 0;
                }

                .ecom-text-marque-wrapper {
                    flex: 0 0 auto;
                    min-width: var(--min-width);
                    z-index: 1;
                    display: flex;
                    flex-direction: row;
                    align-items: center;
                    animation: ecom-scroll var(--duration) linear var(--delay) var(--iteration-count);
                    animation-play-state: var(--play);
                    animation-delay: var(--delay);
                    animation-direction: var(--direction);
                }

                @keyframes ecom-scroll {
                    0% {
                        transform: translateX(var(--percent-start, 0%));
                    }

                    100% {
                        transform: translateX(var(--percent-end, -100%));
                    }
                }
                .ecom-text-marquee-child {
                    display: flex;
                    transform: var(--transform);
                }
                .ecom-marquee {
                    overflow: hidden;
                    display: flex;
                }

                .element__text-marquee .ecom-marquee_items {
                    font-size: 1.8em;
                    width: 100%;
                    white-space: nowrap;
                }

                .element__text-marquee.animation-reverse .ecom-marquee_items {
                    justify-content: end;
                }

                .ecom-marquee_items.ecom-anim_marquee {
                    animation: ecomMarquee 10s linear infinite;
                }

                .element__text-marquee.animation-reverse .ecom-marquee_items.ecom-anim_marquee {
                    animation: ecomMarqueeReverse 10s linear infinite;
                }

                .element__text-marquee:hover .ecom-marquee_items {
                    animation-play-state: paused;
                }
                .ecom-marquee_items .ecom-marquee_item {
                    display: flex;
                    text-decoration: none;
                }
                @keyframes ecomMarquee {
                    0% { margin-left: 0; }
                    100% { margin-left: -100%; }
                }

                @keyframes ecomMarqueeReverse {
                    0% { margin-left: -100%; }
                    100% { margin-left: 0; }
                }

                .ecom-marquee_items h3 {
                    display: flex;
                    align-items: center;
                }

                .ecom-flex_full {
                    flex: 0 0 100%;
                    width: 100%;
                }

                .ecom-icon-separator svg {
                    width: 20px;
                    height: 20px;
                }

                .ecom-icon-separator, .ecom-marquee-image {
                    padding-left: 15px;
                    padding-right: 15px;
                    line-height: normal;
                    align-self: center;
                }
            `;
        },

