    unmounted() {

    },
    watch: {
        items: {
            deep: true,
            handler: function() {
                this.refresh();
            }
        },
        'data.settings.animation_speed'() {
            this.syncMarqueeSpeed();
        },
        iconSeparator: {
            deep: true,
            handler: function() {
                this.refresh();
            }
        },
    },
    methods: {
        quickToolBar() {
            return ['animation_speed', 'reverse_direction'];
        },
        refresh() {
            this.textMarqueeData.refresh = this.$helpers.randid();
        },
        syncMarqueeSpeed() {
            if (this.exporting !== false) {
                return;
            }
            const raw = this.data?.settings?.animation_speed;
            const speed = raw == null || raw === '' ? 50 : Number(raw);
            const clamped = !speed || speed < 10 ? 10 : speed;

            this.$nextTick(() => {
                const marquee = this.$el?.querySelector?.('ecom-marquee-component');
                if (!marquee) {
                    return;
                }
                marquee.setAttribute('speed', String(clamped));
                // Recalculate duration after speed change (handle() only runs when duration is 0)
                marquee.duration = 0;
                if (typeof marquee.handle === 'function') {
                    marquee.handle();
                }
            });
        },

        style() {
            let style = [];
            if(this.data.settings?.items && this.data.settings?.items.length > 0) {
                style.push(
                {
                    group_alias: 'text',
                    options: {
                        group_title: this.$t('text'),
                        group_name: 'text_item',
                        selector: ` .ecom-marquee_items .ecom-marquee_item ${this.data.settings.tag || 'h3'}`
                    },
                    modify: {
                        remove: [
                            { index: 0, length: 1 }
                        ],
                        params: {
                            position: 10,
                            fields: {
                                alias: 'spacing',
                                options: {
                                    label: this.$t('spacing'),
                                }
                            }
                        }
                    }
                })
            }

            if(this.data.settings?.items && this.data.settings?.items?.some((item) => item.icon)) {
                style.push({
                    group_alias: 'icon',
                    options: {
                        group_title: this.$t('icon'),
                        group_name: 'icon',
                        selector: ' .ecom-icon-separator',
                    },
                    modify:{
                        params:[
                            {
                                position:15,
                                fields:[
                                    {
                                        type:'line'
                                    },
                                    {
                                        alias:'spacing',
                                        options: {
                                            label: this.$t('spacing'),
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                })
            }
            if(this.data.settings?.items && this.data.settings.items.some((item) => item.image?.url)) {
                style.push({
                    group_alias:'image',
                    options:{
                        group_title: this.$t('image'),
                        selector: ' .ecom-marquee-image'
                    },
                    modify:{
                        remove: {
                            index: 0,
                            length: 2
                        },
                        params:[
                            {
                                position: 2,
                                fields: [
                                    {
                                        type: 'number',
                                        label: this.$t('width'),
                                        name: 'width',
                                        options: {
                                            responsive: true,
                                            units: {
                                                px: {
                                                    min: 0,
                                                    max: 200
                                                },
                                                'vw': {
                                                    min: 0,
                                                    max: 100
                                                }
                                            }
                                        },
                                        css:{
                                            important: true,
                                            selector: ' img',
                                            properties:{
                                                width:''
                                            }
                                        }
                                    },
                                ]
                            },
                            {
                                position:20,
                                fields:{
                                    alias:'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            }
                        ]

                    }
                })
            }

            return style;
        }
    }
};
</script>
