                            }
                        },
                        {
                            name: "play_on_lightbox",
                            label: $t('open_in_lightbox'),
                            type: "toggle",
                            oneline: true,
                            options: {
                                values: {
                                    on: {
                                        label: $t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: $t('no'),
                                        value: false
                                    }
                                },
                                oneline: true,
