                    ]
                },
                {

                    group_title: $t('tracking'),
                    params: [

                        {
                            type: 'text',
                            name: 'tracking_id',
                            label: $t('tracking_id'),
                            options: {
                                placeholder: $t('enter_tracking_id'),
                            }
                        },
                        {
                            type: 'paragraph',
                            content: $t('you_can_use_this_field_to_add_a_tracking_id_to_your_button_this_id_will_be_sent_to_your_ec_analytics_when_the_button_is_clicked'),
                        },
                    ]
                }
            ];
        },

        javascript() {
            return function () {
                if (!this.settings || !this.$el) {
                    return;
                }
                const $el = this.$el;
                const isLive = this.isLive,
                    loop = this.settings.loop,
                    autoplay = this.settings.autoplay,
                    lazyload = this.settings.lazyload || false,
                    controls = this.settings.player_controls || false,
                    pauseOnHover = this.settings.pause_on_hover || false,
                    clickToPlay = this.settings.click_to_play_pause,
                    openInLightbox = this.settings.play_on_lightbox || false,
                    HAVE_METADATA = 1;
                let $button = $el.querySelector(".ecom-video_overlay-icon");
                const poster = $el.querySelector(".ecom-video-poster");
                let $icon;
                $icon = $button && $button.querySelector(".ecom-video-icon-play");
                const videoWrapper = $el.querySelector('.ecom-element_video-iframe');
                // document.addEventListener("DOMContentLoaded", function() {\
                if(lazyload) {
                    setTimeout(function(){
                        createObserver(videoWrapper)
                    }, 500)
                };
                function createObserver(element){
                    let options = {
                        root: null,
                        rootMargin: "0px",
                        threshold: 0.5
                    };
                    let observer = new IntersectionObserver(handleIntersect, options);
                    observer.observe(element);
                    // window.removeEventListener('scroll', lazyloadVideo)
                }
                function handlePauseOnHover(vid, videoLoop) {
                    let hoverHandlers = { handleMouseenter, handleMouseleave, handleEnded };
                    function handleMouseenter() {
                        if(vid.readyState >= HAVE_METADATA){
                            vid.pause();
                        }
                    }
                    function handleMouseleave() {
                        if(vid.readyState >= HAVE_METADATA){
                            vid.play();
                        }
                    }
                    function handleEnded() {
                        handleRemovePauseOnHover(vid, hoverHandlers);
                    }
                    if(pauseOnHover){
                        vid.addEventListener('mouseenter', handleMouseenter);
                        vid.addEventListener('mouseleave', handleMouseleave)
                        let linkExtra = $el.querySelector('.ecom-video_link-extra');
                        if(linkExtra && linkExtra.href){
                            linkExtra.addEventListener('mouseenter', handleMouseenter);
                            linkExtra.addEventListener('mouseleave', handleMouseleave);
                        }

                        if(!videoLoop){
                            vid.addEventListener('ended', handleEnded)
                        }

                    }
                }

                function handleRemovePauseOnHover(vid, handle){
                    if (handle) {
                        const { handleMouseenter, handleMouseleave, handleEnded } = handle;
                        let linkExtra = $el.querySelector('.ecom-video_link-extra');
                        vid.removeEventListener('mouseenter', handleMouseenter);
                        vid.removeEventListener('mouseleave', handleMouseleave);
                        vid.removeEventListener('ended', handleEnded);
                        if(linkExtra && linkExtra.href){
                            linkExtra.removeEventListener('mouseenter', handleMouseenter);
                            linkExtra.removeEventListener('mouseleave', handleMouseleave);
                        }
                    }
                }

                function handleIntersect(entries, observer){
                        entries.forEach(function(entry){
                            if(entry.isIntersecting) {
                                const source = entry.target.querySelector('video source');
                                const video = entry.target.querySelector('video');
                                const iframe = entry.target.querySelector('iframe');
                                if(video && source) {
                                    source.src = source.dataset.source;
                                    video.load();
                                    video.addEventListener('loadeddata', function() {
                                        if(autoplay) {
                                            video.play();
                                        }
                                    });
                                }
                                if(iframe) {
                                    let src = iframe.dataset.srcVideo;
                                    iframe.setAttribute("src", src);
                                }
                                observer.unobserve(entry.target);
                            }
                        });
                }
                let video = $el.querySelector(".ecom_video");
                let iframe = $el.querySelector(".ecom_iframe");
                if(clickToPlay){
                    video.addEventListener('click', ()=>{
                        if (video.readyState >= HAVE_METADATA){
                            if (video.paused){
                                video.play();
                            } else {
                                video.pause();
                            }
                        }
                    });
                }
                if(autoplay) {
                    if($button) $button.classList.remove("ecom-overlay");
                    if($icon) $icon.style.display ="none";
                    if(poster) poster.style.display = 'none';
                }
                if(video && !loop) {
                    video.addEventListener('ended', function() {
                        if(poster) poster.style.display = 'block';
                        if($button) $button.classList.add("ecom-overlay");
                        if($icon) $icon.style.display ="block";
                    });
                }
                if ($button) {
                    $button.addEventListener("click", () => {

                        if (this.settings.source == "hosted" || this.settings.source == "uploaded" && video) {
                            if(poster) poster.style.display = 'none';
                            video.autoplay = true;
                            video.play();
                            $button.classList.remove("ecom-overlay");
                            $icon.style.display ="none";
                        } else if(iframe) {
                            // let src = iframe.getAttribute("src") + "&autoplay=1";
                            let src = iframe.getAttribute("src");
                            if(src.includes('autoplay=0')){
                                src = src.replace('autoplay=0', 'autoplay=1')
                            }
                            else {
                                src = src + "&autoplay=1";
                            }
                            iframe.setAttribute("src", src);
                            if(!openInLightbox) {
                                if(poster) poster.style.display = 'none';
                                $button.classList.remove("ecom-overlay");
                                $icon.style.display = "none";
                            }
                            else {
                                setTimeout(() => {
                                    src = src.replace('autoplay=1', 'autoplay=0')
                                    iframe.setAttribute("src", src);

                                }, 100)
                            }
                        }

                    });

                }
                if(video) {
                    if(isLive && !poster){
                        handlePauseOnHover(video, loop);
                    }
                    if(poster) {
                        poster.addEventListener('click', function() {
                            poster.style.display = 'none';
                            video.play();
                            if(isLive){
                                handlePauseOnHover(video, loop);
                            }
                        });
                    }
                    if(!pauseOnHover){
                        video.addEventListener('pause', function() {
                            if(poster) poster.style.display = 'block';
                            if($button) $button.classList.add("ecom-overlay");
                            if($icon) $icon.style.display ="block";
                        })
                    }
                    if(!controls && $button) {
                        video.addEventListener('click', function() {
                            video.pause()
                        })
                    }
                }

                $el.querySelectorAll('[data-ec-tracking-id]').forEach(function($btn){
                    if($btn.dataset.ecTrackingId)
                        {
                            $btn.addEventListener('click', function(){
                                if(window.Shopify.analytics)
                                {
                                    Shopify.analytics.publish("ec_custom_events",{
                                        "button_id": $btn.id,
                                        "tracking_id": $btn.dataset.ecTrackingId
                                    })
                                }
                            }, { once: true});
                        }
                });
                //to do
                const popup = $el.querySelector('[ecom-modal]');
                if (popup && this.settings.image_overlay && openInLightbox && window.EComModal) {
                    const popup_width = popup.dataset.width;
                    const popup_height = popup.dataset.height;
                    var id = this.id
                    new window.EComModal(popup, {
                        cssClass: [id, 'ecom-core', 'ecom-core-simulator'],
                        onOpen: function() {
                            var modal = document.querySelector('.ecom-modal.' + id);
                            if(modal) {
                                const content = modal.querySelector('.ecom-modal-box__content');
                                content.classList.add('ecom-element_video-iframe');
                                const style = {
                                    width: popup_width,
                                    height: popup_height,
                                }
                                Object.assign(content.style, style);
                            }

                        },
                        onClose: function() {
                            var modal = document.querySelector('.ecom-modal.' + id);
                            if(modal) {
                                const iframe = modal.querySelector('.ecom-element_video-iframe iframe');
                                if(iframe) {
                                    iframe.src = '';
                                }
                            }

                        }
                    });
                }
            };
        },
        css() {
            return `
            .ecom-video-poster {
                position: absolute;
                width: 100%;
                height: 100%;
            }
            .ecom-video-poster img {
                width: 100%;
                height: 100% !important;
                object-fit: cover;
            }
            .ecom-element_video-popup{
                display:none;
            }

            .ecom-video_link-extra {
                position: absolute;
                inset: 0;
                z-index: 5;
            }

            .element__video .ecom-video_link-extra {
                display: block;
            }
                .element__video.ecom-element{
                    display: flex;
                    width: 100%;
                }
                .ecom-element_video-iframe{
                    display:inline-flex;
                    width:100%;
                    position:relative;
                    overflow:hidden;
                    justify-content: center;
                    transform: translateZ(0);
                }
                .ecom-video_overlay-icon.ecom-overlay {
                    pointer-events: auto;
                }
                .ecom-element_video-iframe .ecom-video_overlay-icon{
