        video() {
            return this.data.settings;
        },

        linkYoutube() {
            //Viết lại cho dễ nhìn 
            const src = this.video?.srcYoutube;
            if (!src){ 
                return "";
            }
            const getYoutubeId = (url) => {
                const patterns = [
                    /youtu\.be\/([^#&?]{11})/,
                    /youtube\.com\/watch\?v=([^#&?]{11})/,
                    /youtube\.com\/embed\/([^#&?]{11})/,
                    /youtube\.com\/shorts\/([^#&?]{11})/,
                    /[?&]v=([^#&?]{11})/
                ];

                for (const pattern of patterns) {
                    const match = url.match(pattern);
                    if (match) return match[1];
                }

                return null;
            };
            const videoId = getYoutubeId(src);
            if (!videoId) return "";

            const params = new URLSearchParams({
                version: 3,
                controls: this.video?.player_controls ? 1 : 0,
                mute: this.video?.mute ? 1 : 0,
                showinfo: 0,
                iv_load_policy: 3,
                autoplay: this.video?.autoplay ? 1 : 0,
                loop: this.video?.loop ? 1 : 0
            });

            if (this.video?.start_time) params.append("start", this.video.start_time);
            if (this.video?.end_time) params.append("end", this.video.end_time);

            // YouTube bắt buộc phải có playlist để loop 1 video
            if (this.video?.loop) {
                params.append("playlist", videoId);
            }

            return `https://www.youtube.com/embed/${videoId}?${params.toString()}`;
            
            // if (this.video?.srcYoutube) {
            //     const regExpYt = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
            //     let val = this.video.srcYoutube.match(regExpYt);
            //     let videoIdYt = val && val[2].length === 11 ? val[2] : null;
            //     if(!videoIdYt) {
            //         const regex = /youtube\.com\/shorts\/([a-zA-Z0-9_-]+)/;
            //         const match = this.video.srcYoutube.match(regex);
            //         if (match) {
            //             videoIdYt = match[1];
            //         }
            //     }
            //     return `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3${
            //         this.video.start_time ? "&start=" + this.video.start_time : ""
            //     }${this.video.end_time ? "&end=" + this.video.end_time : ""}&controls=${
            //         this.video.player_controls ? 1 : 0
            //     }&mute=${
            //         this.video.mute ? 1 : 0
            //     }&showinfo=0&iv_load_policy=3&autoplay=${this.video?.autoplay ? 1 : 0}&loop=${this.video?.loop ? 1 : 0}&playlist=${this.video?.loop ? videoIdYt : ''}`;
            // } else {
            //     return "";
            // }
        },
        linkVimeo() {
            if (this.video?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.video.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?controls=${this.data?.settings?.player_controls ? 1 : 0}&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&muted=${this.data?.settings?.mute || this.data?.settings?.autoplay ? 1 : 0}${
                    this.video.start_time ? "&byline=1#t=00h00m" + this.video.start_time + "ss" : ""
                }&showinfo=0&autoplay=${this.video?.autoplay ? 1 : 0}&loop=${this.video?.loop ? 1 : 0}&autopause=${this.video?.autopause ? 1 : 0}`;
            } else {
                return "";
            }
        },
        linkSelfHosted() {
            if(this.video.source === 'hosted')
            {
                if (this.video?.link) {
                    let check = this.video.link.match(
                        /(http(s)?:\/\/.)?(www\.)?[-a-zA-Z0-9@:%._+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_+.~#?&=]*)/
                    );
                    if (check && check[0] == "https://drive.google.com") {
                        const regex = /\/file\/d\/(.+)\/(.+)/;
                        let val = this.video.link.match(regex);
                        let videoId = val ? val[1] : null;
                        return `${
                            location.protocol
                        }//drive.google.com/uc?export=download&id=${videoId}#t=${
                            this.video.start_time ? this.video.start_time : ""
                        },${this.video.end_time ? this.video.end_time : ""}`;
                    } else {
                        return (
                            this.video.link +
                            `#t=${this.video.start_time ? this.video.start_time : ""},${
                                this.video.end_time ? this.video.end_time : ""
                            }`
                        );
                    }
                } else {
                    return "";
                }
            }
            else if(this.video?.source === 'uploaded')
            {
                let url = this.video?.upload?.value || '';
                // Add #t=0.001 to show first frame as thumbnail when no poster and no autoplay
                if (url && !this.video?.poster_image?.value && !this.video?.autoplay) {
                    url += '#t=0.001';
                }
                return url;
            }
            return '';

        },
        attrVideo() {
            return {
                controls: this.video.player_controls,
                autoplay: this.video.autoplay,
                loop: this.video.loop,
                playsinline:this.video.autoplay,
                preload: this.video.autoplay ? true: false
            };
        },
        default() {
            return {
                settings: {
                    link: "https://cdn.shopify.com/s/files/1/0629/4392/0358/files/flower.webm?v=1649754044",
                    srcVimeo: "https://vimeo.com/210603721",
                    srcYoutube: "https://www.youtube.com/watch?v=2djJhgfl91s",
                    source: "youtube",
                    player_controls: true,
                    autopause: false
                }
            };
        }
    },

    watch: {
        'data.settings.mute': {
            deep: true,
            handler: function(newVal) {
                if(this.$refs.video) {
                    this.$refs.video.muted = newVal;
                    if(newVal) {
                        this.$refs.video.setAttribute('muted','');
                    } else {
                        this.$refs.video.removeAttribute('muted');
                    }
                }
            }
        }
