<template>
    <Teleport to="body">
        <Popup :width="1200" :height="'80vh'" :popclass="popclass"
            :nosave="true"
            :wrpclass="'divide-y items-center my-5 bg-white   rounded-lg z-100'"
            bodyclass="overflow-y-auto w-full" :closeClass="'mt-1.5'" @close="close">
            <template #body>
                <div class="h-full overflow-auto flex flex-col">
                    <div
                        class="p-6 flex flex-grow flex-row w-full bg-white   shadow-custom">
                        <iframe ref="image-editor" @load="onLoad" width="100%" height="100%"
                            src="https://image-editor.ecomposer.app/"></iframe>
                    </div>
                    <div class="flex gap-2 px-4 h-14 min-h-[64px] w-full justify-end items-center">
                        <s-button
                            variant="secondary"
                            @click="close"
                        >
                            {{ $t("discard") }}
                        </s-button>
                        <s-button
                            variant="primary"
                            @click="save"
                            :loading="saving"
                        >
                            {{ $t("save_settings") }}
                        </s-button>
                    </div>
                </div>
            </template>
        </Popup>
    </Teleport>
</template>
<script  lang="ts">
export default {
    name: 'image-editor',
    props: {
        data: {
            type: Object,
            default: () => ({
                src: "https://cdn.shopify.com/s/files/1/0629/4392/0358/files/S3b44f6830e2b43e5b88ef67f4a03ad06l.jpg?v=1684813483",
                // mode: "crop",
                size: {
                    width:500,
                    height:500
                }
            }),
        },
        show: {
            type: Boolean,
            default: false
        }

    },
    emits: ['close', 'update:data', 'upload'],
    data () {
        return {
            saving: false,
            showPopup: false,
            ctx: null,
            itv: null,
        }
    },
    computed: {
        popclass() {
            return `h-full w-full flex justify-center items-center !z-[100]`;
        },
    },
    methods: {
        onMessage (e) {
            // console.log(e);

            if (!e.data.action ) {
                return false;
            }
            switch (e.data.action) {
                case 'image-editor-save':
                    if(e.data.data.dest) {
                        this.$emit('upload', e.data.data);
                    }
                    // this.close()
                    break;
                case 'image-editor-ready':
                    // this.$refs['image-editor'].contentWindow.postMessage({ action: 'image-editor-init', data: this.data }, '*')
                    break;
                default:
                    break;
            }
        },

        close () {
            this.showPopup = false
            window.removeEventListener('message', this.onMessage)
            this.$emit('close');
        },
        save () {
            this.$refs['image-editor'].contentWindow.postMessage({ action: 'image-editor-save' }, '*');
            this.saving = true;
        },
        onLoad () {
            window.addEventListener('message', this.onMessage)
            setTimeout(() => {
                var editor = this.$refs['image-editor'].contentWindow;
                editor.postMessage({ action: 'image-editor-init', data:  JSON.parse(JSON.stringify(this.data))}, '*');
            }, 500)
            // editor.enableButtonExport = false;
        }
    },
    beforeDestroy () {
        window.removeEventListener('message', this.onMessage)
    }
}
</script>