<template>
    <input
        v-if="!field.options || (['full', 'short', true].indexOf(field.options.toolbar) === -1)"
        v-model="value"
        v-focus="field.options?.autofocus ? 'select' : false"
        type="text"
        :placeholder="field?.options?.placeholder ?? field?.placeholder ?? null"
        class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input hover:border-input-hover placeholder-form-input text-xs font-normal focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40"
        :class="'h-8'"
        :style="field.options?.control_width ? 'width:'+field.options?.control_width : (field.options?.oneline ? 'max-width:60%' : '')"
        :maxlength="field?.options?.max"
        :disabled="field?.options?.disabled"
        @change="onchange"

    >
    <EditorComponent
        v-else
        :data="value"
        :field="field"
        :type="1"
        @update:data="$emit('update:data', $event)"
    />
</template>

<script lang="ts">
    import EditorComponent from '../../components/editor/Editor.vue';
    export default {
        name: 'EditorField',
        components: {
            EditorComponent
        },
        props: {
            data: {
                type: String,
                default: ''
            },
            field: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        emits: ['update:data'],
        data() {
            return {
                ready: false
            };
        },
        computed: {
            value: {
                get(){
                    return this.data != '__empty__' ? this.data : '';
                },
                set(val){
                    if (this.field?.options?.update != 'onchange' || this.field.options.toolbar) {
                        this.$emit('update:data', val);
                    }
                }
            }
        },
        watch: {
            data(val) {
                this.value = val;
            }
        },
        methods: {
            onchange(e) {
                if (this.field?.options?.update == 'onchange') {
                    this.$emit('update:data', e.target.value);
                }
            }
        }
    };
</script>
