<template>
    <div
        v-for="(field, index) in gparams"
        :key="(field.name) || index"
        class="px-2"
        :class="field.options?.half ? 'w-1/2' : 'w-full'"
    >
        <div v-for="(warning, iWarning) in warnings(group, field)" :key="iWarning" class="flex w-full py-5 px-4 mb-3 text-xs rounded text-gray-600 border border-[#E1B878] shadow-sm bg-[#FFF5EA] font-normal">
            <EcomIcon :source="CircleAlertMajor" class="mr-4" :color="'text-yellow-600'"></EcomIcon>
            <div class="text-xs items-center leading-5" v-html="warning" />
        </div>
        <FieldQuickTool
            v-if="isQuickToolBar"
            :data="field"
            :group="group"
            :field-values="fieldValues"
            :freeform="freeform"
            :aipath="getFieldAIPath(aipath, index)"
            :isQuickToolBar="isQuickToolBar"
            :class="{'mb-3.5' : index < gparams.length - 1}"
            @update:data="$emit('update:data', $event)"
            @update:delete="$emit('update:delete', $event)"
            @update:clicked="$emit('update:clicked', $event)"
        />
        <Field
            v-else
            :data="field"
            :group="group"
            :field-values="fieldValues"
            :freeform="freeform"
            :aipath="getFieldAIPath(aipath, index)"
            :class="{'' : index < gparams.length - 1}"
            @update:data="$emit('update:data', $event)"
            @update:delete="$emit('update:delete', $event)"
            @update:clicked="$emit('update:clicked', $event)"
        />
    </div>
</template>

<script lang="ts">
import { defineAsyncComponent } from '@vue/runtime-core';

import { relationMixin } from '../../mixins';
import {CircleAlertMajor} from '@/assets/icons'

export default {
    components: { 
        Field:  defineAsyncComponent(() => import('./Field.vue')),
        FieldQuickTool:  defineAsyncComponent(() => import('./FieldQuickTool.vue'))
    },
    mixins: [relationMixin],
    data(){
        return {
            CircleAlertMajor
        }
    },
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        },
        fieldValues: {
            type: Object,
            default() {
                return {};
            }
        },
        gparams: {
            type: Array,
            default() {
                return [];
            }
        },
        freeform: {
            type: Boolean,
            default: false
        },
        aipath: {
            type: String,
            default: ''
        },
        isQuickToolBar: {
            type: Boolean,
            default: false
        }
    },
    emits: ['update:label', 'update:delete', 'update:clicked', 'update:data'],
    computed: {
        group () {
            return this.data;
        },
        values() {
            return this.fieldValues;
        }
    },
    methods: {
        warnings (g, f) {
            let wns = f.options?.warnings;
            let rs = [];
            if(wns && typeof wns === 'object') {
                let p = this.pathField(g, f),
                    v = this.$helpers.valueByKey(p, this.values, '||');
                if(wns.constructor === Object) {
                    wns = [wns];
                }
                wns.forEach(wn => {
                    let {content, condition} = wn;
                    if(content) {
                        if(!condition || condition(v)) {
                            rs.push(content);
                        }
                    }
                });
            }
            return rs;
        },
        getFieldAIPath(path: string, index: number) {
            const paths = [];
            if (path) {
                paths.push(path);
            }
            if (this.group.group_name) {
                paths.push(this.group.group_name);
            }
            return paths.join('.');
        }
    }
};
</script>
