        },
        idPageCat() {
            const page = this.params?.page;
            if (!page) return '';
            const categories = this.$store.getters['library/categories'] || [];
            const match = categories.find(
                (c) => c.type === 'page' && c.slug === page
            );
            return match ? page : '';
        },
        /**
         * Category `section` khớp page type đang chỉnh sửa — dùng để filter sẵn thư viện
         * khi mở từ nút "Explore library" của khối thêm section.
         * `metadata.page_types` của category type `section` chứa chính page type (vd: 'product').
         * Nhiều category cùng khớp thì lấy cái đầu tiên theo thứ tự API trả về (ordering giảm dần).
         * '' = không category nào khớp → mở thư viện không filter.
         */
        sectionCatByPageType() {
            const page = String(this.params?.page ?? '').trim().toLowerCase();
            if (!page) return '';
            const categories = this.$store.getters['library/categories'] || [];
            const match = categories.find(
                (c) => c?.type === 'section' && this.categoryPageTypes(c).includes(page)
            );
            return match?.slug || '';
        },
        currentLibrary() {
            return this.insert.metaData?.source || 'ecom';
        },
        showStructure() {
            return !this.isFullScreen && this.params.page !== 'menu';
        }
