        this.$store.commit('builder/setEditingElement', null);

    },
    methods: {

        overStartStructure() {
            if (
                this.isDragging &&
                (this.dragCurrent.is != 'section' || this.dragCurrent.data?.isLibrarySection)
            ) {
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    if (!this.isDragging) return;
                    this.overStructure = true;
                    this.$store.commit('builder/setDropTo', this);
                }, 50)
            }
        },
        overStartGrid(e) {
            if (
                this.isDragging &&
                (this.dragCurrent.is != 'section' || this.dragCurrent.data?.isLibrarySection)
            ) {
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    if (!this.isDragging) return;
                    this.overGrid = true;
                    this.$store.commit('builder/setDropTo', this);
                }, 50)
            }
        },
        outOverGrid() {
            if (!this.isFullScreen) {
                // clearTimeout(this.timmer);
                // this.timmer = setTimeout(() => {
                this.overGrid = false;
                this.$store.commit('builder/setDropTo', null);
                // }, 50);
            }
        },
        openLibrarySection(source) {
            this.$store.dispatch('library/initAsync');
            this.$store.dispatch('library/setInsert', {
                isOpen: true,
                type: 'library',
            });
        },
        setStructure(st) {
            if (
                typeof st[0] == 'string' &&
                typeof st[1] == 'object'
            ) {
                if (st[1].grid) {
                    this.$parent.section.blocks = st[1].blocks;
                    this.$parent.section.settings = st[1].settings;
                    // Active new section when add
                    // const currentSection = this.$parent.section;
                    // if (!currentSection.id) {
                    //     currentSection.id = this.$helpers.randid();
                    // }
                    // this.$store.commit('builder/setEditingElement', this.$parent);

                    this.$parent.data.advanced = this.$parent.data?.advanced || {};
                    this.$parent.data.advanced.spacing__tablet = {
                        padding: {
                            right: '15px',
                            left: '15px',
                        }
                    };
                    this.$parent.data.advanced.spacing__mobile = {
                        padding: {
                            right: '15px',
                            left: '15px',
                        }
                    };
                    if(window.mixpanel) {
                        window.mixpanel.track("Click Button_Build With FreeForm Canvas", {
                            event_name: "Click Button_Build With FreeForm Canvas"
                        });
                    }
                    return true;
                }
                if (st[1][0].blocks) {
                    this.$parent.section.id = this.$helpers.randid();
                    this.$parent.section.name = 'flexContainer';
                    this.$parent.section.blocks = st[1][0].blocks || [];
                    this.$parent.section.settings = st[1][0].settings || {};
                    // Active new section when add
                    // const currentSection = this.$parent.section;
                    // if (!currentSection.id) {
                    //     currentSection.id = this.$helpers.randid();
                    // }
                    // this.$store.commit('builder/setEditingElement', this.$parent);

                    this.$parent.data.advanced = this.$parent.data?.advanced || {};
                    this.$parent.data.advanced.spacing__tablet = {
                        padding: {
                            right: '15px',
                            left: '15px',
                        }
                    };
                    this.$parent.data.advanced.spacing__mobile = {
                        padding: {
                            right: '15px',
                            left: '15px',
                        }
                    };
                    setTimeout(() => {
                        const instancesStore = InstanceStore();
                        const inst = instancesStore.get(this.$parent.section.id);
                        if(inst) this.$store.commit('builder/setEditingElement', inst);
                    }, 200);
                    return true;
                }
                if (!this.$parent.section.blocks) {
                    this.$parent.section.blocks = [];
                }

                st[1].forEach((col) => {
                    this.$parent.section.blocks = col.blocks;
                    this.$parent.section.settings = col.settings;
                    this.$parent.section.name = 'flexContainer';
                });

                return;
            }

            if (!!this.$parent.section.blocks) {
                this.$parent.section.blocks = [];
            }
            st.forEach((s) => {
                this.$parent.blocks.push({
                    width: s,
                    blocks: []
                });
            });

        },
        /** `metadata.page_types` của category (API trả object, null hoặc chuỗi JSON) → mảng page type lowercase. */
        categoryPageTypes(category) {
            let meta = category?.metadata;
            if (!meta) return [];
            if (typeof meta === 'string') {
                try {
                    meta = JSON.parse(meta);
                } catch (e) {
                    return [];
                }
            }
            const types = meta?.page_types;
            if (!Array.isArray(types)) return [];
            return types.map((t) => String(t).trim().toLowerCase()).filter(Boolean);
        },
        async openLibrary(name) {
            // sectionCatByPageType đọc library/categories. Lần mở đầu (initAsync chưa xong)
            // danh sách còn rỗng → không resolve được category nào. Nạp trước rồi mới mở panel:
            // để TemplateExpand mount xong mới có categories thì mounted() đã đọc currentCat rỗng
            // và mất preselect.
            if (name === 'ecom' && !(this.$store.getters['library/categories'] || []).length) {
                try {
                    await this.$store.dispatch('library/initAsync');
                } catch (e) {
                    // Categories rỗng: vẫn mở thư viện, chỉ là không filter sẵn.
                }
            }

            this.$store.dispatch(ROOT_STORE.ACTIONS.SET_TAB, 'templateExpand');
            this.$store.dispatch(ROOT_STORE.ACTIONS.UPDATE_IS_TEMP_HIDE, false);
            this.$store.commit('global/setSidebarTabActive', { id: 'template' });
            this.$store.dispatch('library/setLoading', true);
            let metaData;
            if (name == 'theme') {
                metaData = {
                    ...this.insert.metaData,
                    category: '',
                    source: 'theme',
                    screen: 'theme',
                };
                this.$store.commit('library/setDetailScreen', { title: '', id: 'theme_pages' });
                this.$store.commit('library/showSaveForm', false);
                this.$store.dispatch('library/setInsert', {
                    current: 'pages',
                    metaData,
                });
            } else if (name === 'ecom') {
                // Khối này là luồng thêm section vào trang đã có nội dung → mở tab Sections
                // (không phải Pages) với category filter sẵn theo page type đang chỉnh sửa.
                this.$store.commit('library/setDetailScreen', null);
                this.$store.commit('library/showSaveForm', false);
                const sectionSlug = this.sectionCatByPageType;
                metaData = {
                    ...this.insert.metaData,
                    category: '',
                    category_slug: sectionSlug || undefined,
                    // Sections không có filter Industry: giữ tags của tab Pages thì sections()
                    // lọc theo tên tag → list rỗng mà UI không hiện filter nào.
                    tags: '',
                    // Còn từ khoá cũ trong metaData.search thì TemplateExpand coi là đang search
                    // (hasActiveSearch) và bỏ qua category khởi tạo → mất preselect.
                    search: '',
                    source: name,
                    paged: 1,
                };
                this.$store.dispatch('library/setCurrentCat', { sections: sectionSlug });
                this.$store.dispatch('library/setInsert', {
                    current: 'sections',
                    metaData,
                });
            } else {
                this.$store.commit('library/setDetailScreen', null);
                this.$store.commit('library/showSaveForm', false);
                metaData = {
                    ...this.insert.metaData,
                    category: '',
                    category_slug: undefined,
                    source: name,
                };
                this.$store.dispatch('library/setInsert', {
                    current: 'all_pages',
                    metaData,
                });
            }

            // library/changeLibrary mặc định reset categoryId = null.
            // Với luồng mở từ Structure -> Explore library, cần set thẳng query để request
            // đầu đã filter đúng category section của page type hiện tại.
            if (name === 'ecom') {
                const sectionSlug = this.sectionCatByPageType;
                this.$store.commit('library/setContext', { sourceId: name });
                this.$store.commit('library/setQuery', {
                    page: 1,
                    search: '',
                    nicheId: null,
                    tags: [],
                    // sections top-level: còn detailKey thì buildRequestPayload đi nhánh detail
                    // (type: [detailKey]) và data ghi sai key trong cache.lists.
                    detailKey: null,
                    categoryId: sectionSlug || null,
                    pageContext: this.idPageCat || undefined,
                });
                this.$store.dispatch('library/load', { isChangeCat: true });
            } else {
                this.$store.dispatch('library/changeLibrary', name);
            }
        },
        close() {

            this.$refs.wrapper.style.height = this.$refs.wrapper.offsetHeight + 'px';
            this.$refs.wrapper.classList.remove('core__helper--show');
            this.$refs.wrapper.classList.add('core__helper--close');

            setTimeout(() => { this.$parent.dropOut(); }, 450);

            let html = window.EComposerBuilder.contentDocument.querySelector('html'),
                body = window.EComposerBuilder.contentDocument.body;

            html.scrollTo({ top: html.scrollTop - 250, behavior: 'smooth' });
            body.scrollTo({ top: body.scrollTop - 250, behavior: 'smooth' });

        },
        dropIn(current) {
            if (current.is == 'section') {
                const dropData = current.dropOut();
                if (dropData?.isLibrarySection) {
                    const insertIndex = this.$parent.index;
                    this.$parent.stack.splice(insertIndex, 1);
                    this.$store.dispatch('library/insertPost', {
                        id: dropData.id,
                        dragInsertIndex: insertIndex
                    });
                }
                return;
            }
            if (current.is == 'column') {
                let crow = current.$parent;
                if (!this.$parent.section.columns) {
                    this.$parent.section.columns = [];
                }
                this.$parent.columns.push(current.dropOut());
                crow.refreshCols();
            } else {
                current.data.id = this.$helpers.randid();
                let payload = {
                    type: 'block',
                    data: current.data,
                    section_id: null,
                    action: "moved",
                    parent_id: null,
                    index: null
                }
                this.$store.dispatch('history/addStack', payload);


                if (this.overGrid) {
                    delete this.$parent.section.columns;
                    this.$parent.section.settings = {
                        "height": "fixed",
                        "min-height": "400px"
                    }
                    this.$parent.section.blocks = [];
                    let block = current.dropOut() || {};
                    if (!block || Object.keys(block).length === 0) {
                        console.error("Không thể lấy dữ liệu block từ nguồn kéo thả");
                        return;
                    }

                    // Tạo bản sao và đảm bảo có ID
                    block = JSON.parse(JSON.stringify(block));
                    if (!block.id) {
                        block.id = this.$helpers.randid();
                        block.IDInit = true;
                    }
                    // Khởi tạo layouts nếu chưa có
                    if (!block.layouts) {
                        block.layouts = getOptionsGrid(block).layouts || {};
                    }
                    if (!block.layouts.options) {
                        block.layouts.options = {
                            resize: {
                                conner: true,
                                x: true,
                                y: false
                            },
                            ratioSize: false,
                            autoHeight: true
                        };
                    }
                    if (!block.layouts["desktop"]) {
                        this.setupScreenLayouts(block, 0, 0, 400);
                    }
                    this.$parent.section.blocks.push(block);
                    return;
                }
                if (this.overStructure) {
                    // Xử lý đặc biệt cho FlexContainer — mutate section data, không gán computed readonly
                    if (current.data.name === 'flexContainer') {
                        const sectionData = this.$parent.data;
                        delete sectionData.columns;
                        sectionData.name = 'flexContainer';
                        sectionData.settings = JSON.parse(JSON.stringify(current.data.settings || {}));
                        sectionData.blocks = JSON.parse(JSON.stringify(current.data.blocks || [])).map((block) => {
                            if (!block.id) {
                                block.id = this.$helpers.randid();
                                block.IDInit = true;
                            }
                            return block;
                        });
                        this.$parent.refreshCols();
                        return;
                    }
                    if (!this.$parent.section.columns) {
                        this.$parent.section.columns = [];
                    }
                    this.$parent.columns.push({
                        width: 50,
                        blocks: [current.dropOut()]
                    });
                }
            }
            this.$parent.refreshCols();
        },
        // Hàm trợ giúp thiết lập layout cho các màn hình
        setupScreenLayouts(block, left, top, width, height, staticValue = false) {
            const screens = ["desktop"];
            screens.forEach((screen) => {
                if (!block.layouts[screen]) {
                    block.layouts[screen] = {};
                }
                block.layouts[screen].left = left;
                block.layouts[screen].top = top;
                block.layouts[screen].width = width || block.layouts[screen].width || 400;
                block.layouts[screen].height = height || block.layouts[screen].height || "auto";
                block.layouts[screen].static = staticValue;
            });
            return block;
        },
        openPageSetting() {
            this.$store.commit('page/setImportPopup', true);
        },
        pasteClipBoard() {
            if (!window.navigator.clipboard) {
                return this.$store.commit('global/setToast', {
                    isError: true,
                    message: this.$t('your_browser_not_support_clipboard'),
                    duration: 4000
                });
            }
            window.navigator.clipboard.readText().then((text) => {
                if (!text) {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: this.$t('your_clipboard_empty'),
                        duration: 4000
                    });
                }
                else {
                    try {
                        let data = JSON.parse(text);
                        this.$store.commit('page/insertSections', { sections: [data], keepEmptyStructure: true, index: this.$parent.index }, { root: true });
                    }
                    catch (e) {
                        this.$store.commit('global/setToast', {
                            isError: true,
                            message: this.$t('your_data_from_clipboard_invalid'),
                            duration: 4000
                        });
                    }
                }
            })
                .catch(e => {
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: e.message,
                        data: e,
                        duration: 4000
                    });
                })
        }

    }
};
