<template>
    <div class="ecom-element ecom-product-single ecom-product-single__buy_it_now_btn" :data-preview-mode="exporting.toString()" v-bind="classFullHeight">
        <div class="ecom-product-single__buy_it_now_btn-buttons-wrapper" v-bind="classFullHeight">
            <button
                type="button"
                class="ecom-product-single__buy_it_now_btn--checkout"
                :class="animatedClass"
                :data-variant-id="liquid('variant_id')"

            >
                <span v-html="lang(data.settings?.label, 'button_label')" />
                <span
                    v-if="data.settings?.icon"
                    :style="'order:' + data.settings?.icon_position"
                    class="ecom-button-icon ecom-product-single__buy_it_now-icon-link ecom-in_flex"
                    v-html="data.settings?.icon"
                >
                </span>
            </button>
        </div>
    </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'productBuyNow',

    mixins: [Liquid, Javascript, Element],
    props: {

        data: {
            type: Object,
            default() {
                return {
                };
            }
        }
    },
    data(){
        return {
            jsreactives: [
                'animation_loop_time', 'animation'
            ]
        }
    },
    computed: {
        classFullHeight() {
            const attrs = {
                class: {
                    'ecom-ingrid-full-height': this.data.inGrid,
                },
            };
            return attrs;
        },
        javascript() {
            return function () {
                if(!this.$el)
                {
                    return false;
                }
                const $el = this.$el;
                let $wrapper = $el.closest('.ecom-product-form--single');
                if(!$wrapper){
                    const section = $el.closest('.ecom-builder');
                    if(section){
                        $wrapper = section.querySelector('.ecom-product-form--single');
                    }
                }
                if (!$wrapper) {
                    return false;
                }
                if(this.isLive)
                {
                    let selector = $wrapper.querySelector('[name=id]');
                    const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                    const isHighVariantProduct = variantCount > 250 || $wrapper.querySelector('[data-high-variant-product]');
                    const buyNowBtn = $el.querySelector('.ecom-product-single__buy_it_now_btn--checkout');
                    const product_id = $wrapper.dataset.product_id;
                    if(!product_id) return;
                    let product = null;
                    const json = $wrapper.querySelector('[id^=product-json-' + product_id + ']');
                    if (!json) {
                        return;
                    }
                    try {
                        product = JSON.parse(json.innerHTML);
                    } catch (e) {
                        return;
                    }
                    if(buyNowBtn) {
                        buyNowBtn.addEventListener('click', function(e){
                            e.preventDefault();
                            let quantity = 1;
                            if($wrapper.querySelector('[name=quantity]')){
                                quantity = $wrapper.querySelector('[name=quantity]').value;
                            }
                            let idWrapper  = $wrapper.querySelector('select[name=id]') || $wrapper.querySelector('input[name=id]');
                            if(!idWrapper) console.warn("EC error: Select id or input id not found!");
                            let id = idWrapper.value;
                            let variant = null;
                            if(isHighVariantProduct) {
                                variant = product;
                            }
                            else {
                                variant = product.variants.find(variant => variant.id == id);
                            }
                            if(!variant || variant.available === false){
                                return;
                            }
                            if(window.Shopify.analytics)
                            {
                                Shopify.analytics.publish("ec_buy_now",   {
                                    "cartLine": {
                                        "cost": {
                                            "totalAmount": {
                                                "amount": variant.price * quantity,
                                                "currencyCode": window.Shopify.currency.active
                                            }
                                        },
                                        "merchandise": {
                                            "id": variant.id,
                                            "image": variant.image,
                                            "price": {
                                                "amount": variant.price,
                                                "currencyCode": window.Shopify.currency.active
                                            },
                                            "product": {
                                                "id":  product.id,
                                                "title":  product.title,
                                                "vendor": product.vendor
                                            },
                                            "sku": variant.sku,
                                            "title": variant.title
                                        },
                                        "quantity": quantity
                                    }
                                })
                            }
                            let link = `${window.EComposer.routes.cart_url}/${id}:${quantity}`
                            if(window.location.search.includes('selling_plan')) {
                                const regex = /selling_plan=(\d+)/;
                                const matches = window.location.search.match(regex);

                                if (matches) {
                                    const sellingPlanValue = matches[1];
                                    link = `${window.EComposer.routes.cart_url}/clear?return_to=/cart/add?items[][id]=${id}%26items[][quantity]=${quantity}%26items[][selling_plan]=${sellingPlanValue}%26return_to=/checkout`
                                }
                            }
                            location.href = link;
                        });
                    }

                    if(!product.available){
                        buyNowBtn.classList.add('ecom-disable-buy');
                        buyNowBtn.disabled = true;
                    }
                    if(selector){
                        $wrapper.addEventListener('ecomVariantChange', function(event) {
                            let variant = event.detail.variant;
                            if(!variant || variant.available === false){
                                buyNowBtn.classList.add('ecom-disable-buy');
                                buyNowBtn.disabled = true;
                            }
                            else{
                                buyNowBtn.classList.remove('ecom-disable-buy');
                                buyNowBtn.disabled = false;
                            }
                        })
                    }
                }

                const handleAnimation = function(_this) {
                  if (!$el) return;

                  const $btn_wrapper = $el.querySelector('.ecom-product-single__buy_it_now_btn--checkout');
                   if (!$btn_wrapper) return;

                  let intervalTime = parseInt(_this.settings.animation_loop_time) * 1000 || 6000,
                      animTime = 1000;

                  setInterval(function() {
                      $btn_wrapper.classList.add('animated');
                      setTimeout(function(){
                        $btn_wrapper.classList.remove('animated');
                      }, animTime);
                  }, intervalTime);
                }

                if (this.settings.animation) {
                  handleAnimation(this);
                }
            };
        },
        animatedClass() {
          return this.data?.settings?.animation ? 'animated' : '';
        },
        liquids() {
            return {
                variant_id: {
                    code: '{{product.first_available_variant.id}}',
                    preview: '0'
                },
            }
        },
        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },
        css() {
          return `
            .ecom-product-single__buy_it_now_btn--checkout {
                display: flex;
                justify-content: center;
                cursor: pointer;
                align-items: center;
            }
            .ecom-product-single__buy_it_now_btn-buttons-wrapper{
                display: flex;
                width: 100%;
            }
            .ecom-product-single__buy_it_now-icon-link svg{
                width: 20px;
                height: 20px;
            }
            .ecom-product-single__buy_it_now_btn--checkout.ecom-disable-buy{
                opacity: 0.6;
            }
            .ecom-ingrid-full-height > .ecom-product-single__buy_it_now_btn--checkout {
                width: 100%;
                height: 100%;
            }
          `;
        },
        settings() {
            return [
                {
                    params: [
                        {
                            type: 'paragraph',
                            options: {
                                warnings: {
                                    content: this.$t('the_element_will_not_work_with_the_subscription_options_and_the_properties_product_element')
                                }
                            }
                        },
                        {
                            type: 'text',
                            name: 'label',
                            label: this.$t('button_label'),
                        },
                        {
                            type: 'picker',
                            label: this.$t('icon'),
                            name: 'icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible: function(data){
                                    return (
                                        data &&
                                        data['icon']
                                    )
                                }
                            },
                            css:{
                                selector:' .ecom-button-icon',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('icon_spacing'),
                            name: 'spacing',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 200
                                    }
                                },
                                visible: function(data){
                                    return (
                                        data &&
                                        data['icon']
                                    )
                                }
                            },
                            css:{
                                selector:' .ecom-product-single__buy_it_now_btn--checkout',
                                properties:{
                                    gap:''
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'animation',
                            label: this.$t('button_animation'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('enable'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('disable'),
                                        value: false
                                    }
                                }
                            },
                        },
                        {
                          type: "number",
                          label: this.$t('loop_time_span_class_lowercase_s_span'),
                          name: "animation_loop_time",
                          options: {
                              min: 2,
                              default: 6,
                              max: 10,
                              visible: function (data) {
                                  return data.animation == true;
                              }
                          }
                        },
                        {
                            type:'line'
                        },
                        {
                            type:'paragraph',
                            content: this.$t('integrated_with_omega_facebook_pixel_https_apps_shopify_com_facebook_multi_pixels_surface_detail_e_catc_surface_type_partner'),

                        }
                    ]
                }
            ];
        },
        default() {
            return {
                "settings": {
                    "animation": true,
                    "animation_loop_time": 3,
                    "label": "Buy it now",
                    "icon": "<svg version=\"1.1\" id=\"lni_lni-angle-double-right\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" viewBox=\"0 0 64 64\" style=\"enable-background:new 0 0 64 64;\" xml:space=\"preserve\" fill=\"currentColor\"><g><path d=\"M36.2,28.1L11.3,1.8c-0.7-0.7-1.8-0.7-2.5-0.1C8.1,2.4,8.1,3.5,8.8,4.2l24.9,26.3c0.7,0.7,0.7,1.9,0,2.6L8.8,59.7c-0.7,0.7-0.6,1.8,0.1,2.5c0.3,0.3,0.8,0.5,1.2,0.5c0.5,0,0.9-0.2,1.3-0.6l24.9-26.6C38.2,33.5,38.2,30.2,36.2,28.1z\"></path><path d=\"M54.3,28.2L29.3,1.9c-0.7-0.7-1.8-0.7-2.5-0.1c-0.7,0.7-0.7,1.8-0.1,2.5l24.9,26.3c0.7,0.7,0.7,1.9,0,2.6L26.8,59.8c-0.7,0.7-0.6,1.8,0.1,2.5c0.3,0.3,0.8,0.5,1.2,0.5c0.5,0,0.9-0.2,1.3-0.6l24.9-26.6C56.2,33.6,56.2,30.3,54.3,28.2z\"></path></g></svg>",
                    "icon_position": 1,
                    "spacing": "10px"
                },
                "style": {
                    "checkout_button": {
                        "tab": "normal",
                        "spacing": {
                            "padding": {
                            "top": "12.5px",
                            "left": "50px",
                            "bottom": "12.5px",
                            "right": "50px"
                            }
                        },
                        "buttonTypography": {
                            "text-transform": "uppercase",
                            "font-size": "16px"
                        },
                        "buttonColornormalmode": "#FFF",
                        "buttonBackgroundnormalmode": {
                            "classic": {
                            "background-color": "#0691b1"
                            }
                        },
                        "buttonBordernormalmode": {
                            "border-style": "none"
                        },
                        "buttonBackgroundhovermode": {
                            "classic": {
                            "background-color": "#12bbe0"
                            }
                        },
                        "transition": {
                            "transition": {
                            "duration": "300ms",
                            "timing": "ease"
                            }
                        },
                        "align-items": "center",
                        "buttonBorderRadiushovermode": {
                            "top": "3px",
                            "left": "3px",
                            "bottom": "3px",
                            "right": "3px"
                        },
                        "buttonBorderRadiusnormalmode": {
                            "right": "3px",
                            "top": "3px",
                            "left": "3px",
                            "bottom": "3px"
                        },
                        "buttonHeightnormalmode": "45px",
                        "width": "225px"
                    },
                    "button_animation": {
                        "animation": "shake"
                    },
                    "icon_button": {
                        "tab": "normal",
                        "iconFontSize": "20px"
                    }
                }
            }
        }
    },
    methods: {
        quickToolBar() {
            return ['buttonColor', 'buttonBackground'];
        },

        style() {
            const inGrid = this.data.inGrid || false;
            const params = [
                {
                    group_alias: `button${inGrid ? ':grid' : ''}`,
                    options:{
                        group_title: this.$t('button'),
                        group_name: 'checkout_button',
                        selector:' .ecom-product-single__buy_it_now_btn .ecom-product-single__buy_it_now_btn--checkout',
                    },
                    modify:{
                        remove:  !inGrid ?[
                            {index: 6, length: 1},
                            {index: 11, length: 1}
                        ] : [],
                        params: !inGrid ?[
                            {
                                position:0,
                                fields: [
                                    {
                                        alias: 'width',
                                        options: {
                                            label: this.$t('width'),
                                            css: {
                                                selector: 'root .ecom-product-single__buy_it_now_btn--checkout'
                                            }
                                        }
                                    },
                                    {
                                        alias:'align-items',
                                        options:{
                                            label: this.$t('alignment'),
                                            css:{
                                                selector:'root .ecom-product-single__buy_it_now_btn-buttons-wrapper',
                                                properties:{
                                                    'align-items':'',
                                                    'justify-content':''
                                                }
                                            }
                                        }
                                    }
                                ]
                            },
                        ] : []
                    }
                },
                {
                    group_alias: "icon:hover",
                    options: {
                        group_title: this.$t('icon'),
                        group_name: "icon_button",
                        selector: " .ecom-product-single__buy_it_now-icon-link"
                    }
                },
                {
                  group_name: 'button_animation',
                  group_title: this.$t('animation_effect'),
                  selector: ' .ecom-product-single__buy_it_now_btn--checkout',
                  params: [
                      {
                        name: "animation",
                        label: this.$t('animation'),
                        type: "popup",
                        options: {
                            type: "dropdown",
                            prevew: 'title',
                            values: {
                                'fading': this.$t('fading'),
                                'fade-in': this.$t('fade_in'),
                                'fade-in-down': this.$t('fade_in_down'),
                                'fade-in-left': this.$t('fade_in_left'),
                                'fade-in-right': this.$t('fade_in_right'),
                                'fade-in-up': this.$t('fade_in_up'),
                                'zooming': this.$t('zooming'),
                                'zoom-in': this.$t('zoom_in'),
                                'zoom-in-down': this.$t('zoom_in_down'),
                                'zoom-in-left': this.$t('zoom_in_left'),
                                'zoom-in-right': this.$t('zoom_in_right'),
                                'zoom-in-up': this.$t('zoom_in_up'),
                                'bouncing': this.$t('bouncing'),
                                'bounce-in': this.$t('bounce_in'),
                                'bounce-in-down': this.$t('bounce_in_down'),
                                'bounce-in-left': this.$t('bounce_in_left'),
                                'bounce-in-right': this.$t('bounce_in_right'),
                                'bounce-in-up': this.$t('bounce_in_up'),
                                'sliding': this.$t('sliding'),
                                'sliding-in': this.$t('sliding_in'),
                                'sliding-in-down': this.$t('sliding_in_down'),
                                'sliding-in-left': this.$t('sliding_in_left'),
                                'sliding-in-right': this.$t('sliding_in_right'),
                                'sliding-in-up': this.$t('sliding_in_up'),
                                'rotate': this.$t('rotate'),
                                'rotate-in': this.$t('rotate_in'),
                                'rotate-in-down': this.$t('rotate_in_down'),
                                'rotate-in-left': this.$t('rotate_in_left'),
                                'rotate-in-right': this.$t('rotate_in_right'),
                                'rotate-in-up': this.$t('rotate_in_up'),
                                'attention-seekers': this.$t('attention_seekers'),
                                'bounce': this.$t('bounce'),
                                'flash': this.$t('flash'),
                                'pulse': this.$t('pulse'),
                                'rubber-band': this.$t('rubber_band'),
                                'shake': this.$t('shake'),
                                'head-shake': this.$t('head_shake'),
                                'heart-beat': this.$t('heart_beat'),
                                'swing': this.$t('swing'),
                                'tada': this.$t('tada'),
                                'wobble': this.$t('wobble'),
                                'jello': this.$t('jello'),
                                'light-speed ': this.$t('light_speed'),
                                'light-speed-in': this.$t('light_speed_in'),
                                'specials': this.$t('specials'),
                                'roll-in': this.$t('roll_in'),
                                'shake-y': this.$t('shake_y'),
                                'back-in-down': this.$t('back_in_down'),
                                'back-in-left': this.$t('back_in_left'),
                                'back-in-right': this.$t('back_in_right'),
                                'back-in-up': this.$t('back_in_up'),
                                'flip': this.$t('flip'),
                                'flip-x': this.$t('flip_x'),
                                'flip-y': this.$t('flip_y'),
                                'light-speed-in-right': this.$t('light_speed_in_right'),
                                'light-speed-in-left': this.$t('light_speed_in_left'),
                                'roll': this.$t('roll'),
                            },
                            size: "small",
                        },
                        css: {
                            selector: ".animated",
                            properties: {
                                'entrance-animation': ""
                            }
                        }
                    },
                  ]
              }
