<template>
<div class="relative select-none text-xs max-h-350">
    <div 
    v-for="(global, key) in valueTypeFiltered" 
    :key="key"
    @click="selectGlobal(global, key)"
    class="ec-global-typo rounded px-4 py-2 cursor-pointer hover:bg-surface-secondary-hover active:bg-surface-secondary-active transition mb-0.5 flex items-center justify-between gap-2 group/item"
    :class="{'bg-surface-secondary-selected': key == data}"
>
    <!-- Hiển thị màu sắc -->
    <div class="shrink-0 flex items-center gap-2">
        <span 
            class="w-5 h-5 rounded-full border border-gray-300" 
            :style="{ backgroundColor: global.value }"
        />
        
        {{ global.title }}
    </div>
    <div class="opacity-0 invisible group-hover/item:opacity-100 group-hover/item:visible transition truncate" :title="global.value.toUpperCase()">
        {{global.value.toUpperCase()}}
    </div>
</div>
</div>
</template>
<script>
import { CircleTickMinor } from '@/assets/icons'
export default {
    props: {
        data: {
            type: String,
            default: ""
        },
        isPanelOpen: {
            type: Boolean,
            default: false
        },
    },
    data() {
        return {
            icons: {
                CircleTickMinor
            }
        }
    },
    computed: {
        globalData() {
            return this.$store.getters['settings/globalData']
        },
        valueType() {
            return this.globalData('colors');
        },
        valueTypeFiltered() {
            let values = {};
            for (let k in this.valueType) {
                let d = this.valueType[k];
                if (
                    (typeof d.value === 'string' && d.value) ||
                    (typeof d.value === 'object' && Object.keys(d.value).length)
                ) {
                    values[k] = d;
                }
            }
            return values;
        }
    },
    methods: {
        selectGlobal(global, key) {
            this.$emit('update', global.value, key);
        },
    }
}
</script>
<style lang="css">
    .max-h-350 {
        max-height: 350px;
        overflow-y: scroll;
    }
</style>