<template>
    <div class="ecom-element ecom-collection ecom-collection__description">
        <div class="ecom-collection__description-wrapper">
            <div class="ecom-collection__description-container" :content_type="contentType">
                <template v-if="contentType === 'text'">
                    <div class="ecom-collection__description--paragraph">
                        <div  class="ecom-text-des" :class="{'ecom-view-more-enable': type === 'short' && view_more}" v-html="liquid(description_short)" />
                        <div
                            v-if="type === 'short' && view_more"
                            class="ecom-collection__description--view-more ecom-w__full ecom-flex"
                        >
                            <button
                                type="button"
                                class="ecom-collection__description-view-more-btn"
                            >
                                <span class="ecom__element--button-icon" v-if="data.settings?.view_more_icon" v-html="data.settings.view_more_icon" />
                                <span v-text="lang(data.settings.view_more_text, 'view_more_text')"></span>
                            </button>
                        </div>
                    </div>
                    <div 
                        v-if="type === 'short' && view_more"
                        class="ecom-collection__description--full"
                        style="display: none"
                    >
                        <div class="ecom-text-des" :class="{'ecom-view-more-enable': type === 'short' && view_more}"
                            v-html="liquid('description_text')"
                        />
                        <div class="ecom-collection__description--view-less ecom-flex"  v-if="type === 'short' && view_more">
                            <button
                                type="button"
                                class="ecom-collection__description-view-less-btn"
                            >
                                <span class="ecom__element--button-icon" v-if="data.settings?.view_less_icon" v-html="data.settings.view_less_icon" />
                                <span v-text="lang(data.settings.view_less_text, 'view_less_text')"></span>
                            </button>

                        </div>
                    </div>
                </template>
                <template v-else>
                    <div
                        class="ecom-collection__description--paragraph ecom-html-des" :class="{'ecom-view-more-enable': type === 'short' && view_more}"
                        :style="maxHeight ? { 'max-height': 'var(--ecom-description-height)' ,'--ecom-description-height': maxHeight} : null"
                        v-html="liquid(description_short)"
                    />
                    <div v-if="type === 'short' && view_more" class="ecom-collection__description--view-more ecom-w__full ecom-flex">
                        <button
                            type="button"
                            class="ecom-collection__description-view-more-btn"
                    
                        >
                            <span class="ecom__element--button-icon" :class="{'ecom-view-more-enable': type === 'short' && view_more}" v-if="data.settings?.view_more_icon" v-html="data.settings.view_more_icon" />
                            <span v-text="lang(data.settings.view_more_text, 'view_more_text')"></span>
                        </button>
                    </div>
                    <div class="ecom-collection__description--view-less ecom-flex"  v-if="type === 'short' && view_more">
                        <button
                            type="button"
                            class="ecom-collection__description-view-less-btn"
                            style="display:none"
                        >
                            <span class="ecom__element--button-icon" v-if="data.settings?.view_less_icon" v-html="data.settings.view_less_icon" />
                            <span v-text="lang(data.settings.view_less_text, 'view_less_text')"></span>
                        </button>

                    </div>
                </template>
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
import { addSwitch } from "@/plugins/fields/utils";
export default {
    name: 'CollectionDescription',
    docs: 'https://help.ecomposer.io/docs/elements/collection-elements/description/',
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data(){
        return {
            jsreactives: ['view_more_text','view_more','type','content_type']
        }
    },
    computed: {
        contentType() {
            return this.data?.settings?.content_type ?? 'text';
        },

        css() {
            return `
                .ecom-collection__description--paragraph, .ecom-collection__description-view-more-btn {
                    overflow: hidden
                }
                .ecom-collection__description-view-more-btn, .ecom-collection__description-view-less-btn{
                    cursor:pointer;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
                .ecom__element--button-icon svg{
                    width: 12px;
                    height: 12px;
                }
                .ecom-html-des, .ecom-text-des {
                    position: relative;
                }
                .ecom-collection__description--paragraph.ecom-html-des.ecom-view-more-enable[style*="max-height"]::after, .ecom-collection__description--paragraph .ecom-text-des.ecom-view-more-enable::after {
                    position: absolute;
                    content: '';
                    left: 0;
                    right: 0;
                    bottom: 0;
                    height: 100%;
                    pointer-events: none;
                }
            `;
        },

        description_type() {
            return this.type === 'short' ? 'short_description' : 'description';
        },

        description_short() {
            return this.contentType === 'text'
                ? this.type === 'short'
                    ? 'short_description'
                    : 'description_text'
                : 'description';
        },

        javascript() {
            return function () {
                /**
                 * this.settings.view_more
                 * this.settings.view_more_text
                 */
                let $dom = this.$el.querySelector('.ecom-collection__description-view-more-btn');
                let contentType = this.settings['content_type'];
                let $full = this.$el.querySelector('.ecom-collection__description--full');
                let $less  = this.$el.querySelector('.ecom-collection__description-view-less-btn')
                let $short = this.$el.querySelector('.ecom-collection__description--paragraph');
                if ($dom) {
                    $dom.addEventListener('click', function () {
                        if (contentType === 'text' && $full) {
                            $full.style.display = 'inherit';
                            $short.style.display = 'none';
                        } else {
                            $short.style.maxHeight = null;
                        }
                        this.style.display = 'none';
                        if($less)
                            $less.style.display = 'flex';
                    });
                    $less && $less.addEventListener('click', function(){
                        $dom.style.display = 'flex';
                        this.style.display = 'none';
                         if (contentType === 'text' && $full) {
                            if($full)
                                $full.style.display = 'none';

                            $short.style.display = 'block';
                        } else {
                            $short.style.maxHeight = 'var(--ecom-description-height)';
                        }
                    });
                }
            };
        },

        limit() {
            return this.data &&
                this.data.settings &&
                this.data.settings.limit &&
                parseInt(this.data.settings.limit) > 0
                ? parseInt(this.data.settings.limit)
                : 50;
        },

        liquids() {
            return {
                description: {
                    code: `
                        {%- if collection != empty -%}
                            {%- if collection.description != empty -%}
                                {{collection.description}}
                            {%- endif -%}
                        {%- else -%}
                            <div>Please select the collection in settings</div>
                        {%- endif -%}
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-10 big"></div>
                                <div class="ecom-skeleton-col-2 ecom-skeleton-empty big"></div>
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-12"></div>
                            </div>
                        </div>
                    `
                },
                description_text: {
                    code: '{{collection.description | strip_html }}',
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-10 big"></div>
                                <div class="ecom-skeleton-col-2 ecom-skeleton-empty big"></div>
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-12"></div>
                            </div>
                        </div>
                    `
                },
                short_description: {
                    code: `
                        {%- if collection != empty -%}
                            {%- if collection.description != empty -%}
                                {{ collection.description | strip_html | truncatewords: ${this.limit} }}
                            {%- elsif EComBuilderMode -%}
                                <div>Collection without description</div>
                            {%- endif -%}
                        {%- elsif EComBuilderMode -%}
                            <div>Please select the collection in settings</div>
                        {%- endif -%}
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div>
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-6"></div>
                                    <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-8"></div>
                                    <div class="ecom-skeleton-col-4 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-4"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                </div>
                            </div>
                        </div>

                    `
                }
            };
        },

        maxHeight() {
            // Chỉ clamp khi có nút "View more" để mở ra, nếu không description sẽ bị
            // cắt vĩnh viễn bởi `overflow: hidden` mà không có cách nào xem hết.
            return this.contentType === 'html' && this.type === 'short' && this.view_more
                ? this.data.settings['max-height']
                : null;
        },

        requestShopifyType() {
            return {
                shopify_type: 'collection'
            };
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('content_type'),
                            name: 'content_type',
                            options: {
                                preview: 'title',
                                type: 'dropdown',
                                values: { text: this.$t('text'), html: 'HTML' },
                                default: false
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('description_type'),
                            name: 'type',
                            value: 'short',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                values: {
                                    short: this.$t('short'),
                                    full: this.$t('full')
                                },
                                default: false
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('maximum_words_to_show'),
                            name: 'limit',
                            value: '50',
                            placeholder: '50',
                            options: {
                                control_width: '40%',
                                input: true,
                                slider: false,
                                min: 0,
                                // oneline: true,
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['type'] === 'short' &&
                                        data['content_type'] === 'text'
                                    );
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('max_height'),
                            name: 'max-height',
                            placeholder: '200',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 1000
                                    },
                                    'vh': {
                                        min: 0,
                                        max: 100
                                    },
                                    'vw': {
                                        min: 0,
                                        max: 100
                                    },
                                },
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['type'] === 'short' &&
                                        data['content_type'] == 'html'
                                    );
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_view_more'),
                            name: 'view_more',
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: function (data) {
                                    return data['type'] === 'short';
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('view_more_icon'),
                            name: 'view_more_icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible:function(data){return data.view_more}
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('view_less_icon'),
                            name: 'view_less_icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible:function(data){return data.view_more}
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible:function(data){return data.view_more}
                            },
                            css:{
                                selector:' .ecom__element--button-icon',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "spacing",
                            label: this.$t('spacing'),
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 1,
                                        max: 50,
                                        step: 1
                                    }
                                },
                                visible:function(data){return data.view_more},
                                reset:false
                            },
                            css: {
                                selector: 'root .ecom-collection__description--view-less button ,root .ecom-collection__description--view-more button',
                                properties: {
                                    gap: ""
                                }
                            }
                        },
                        {
                            label: this.$t('view_more_text_button'),
                            name: 'view_more_text',
                            type: 'text',
                            options: {
                                visible: function (data) {
                                    return data['type'] === 'short' && data['view_more'];
                                }
                            }
                        },
                        {
                            label: this.$t('view_less_text_button'),
                            name: 'view_less_text',
                            type: 'text',
                            options: {
                                visible: function (data) {
                                    return data['type'] === 'short' && data['view_more'];
                                }
                            }
                        }
                    ]
                }
            ];
        },

        type() {
            return this.data && this.data.settings && this.data.settings.type
                ? this.data.settings.type
                : 'short';
        },

        view_more() {
            return this.data && this.data.settings && this.data.settings.view_more
                ? this.data.settings.view_more
                : false;
        },

        default() {
            return {
                settings: {
                    content_type: "text",
                    type: "short",
                    limit: "50",
                    view_more: false,
                    view_more_text: "View more",
                    view_less_text: "View less",
                    "max-height": "200px",
                    "spacing": "5px",
                    "icon_position": 1
                },
                style: {
                    collection_description: {
                        textTextAlign: "left"
                    }
                }
            }
        }
    },

    methods: {
        style() {
            let style = [
                {
                    group_alias: 'text',
                    options: {
                        group_title: this.$t('description'),
                        group_name: 'collection_description',
                        selector: ' .ecom-text-des, .ecom-html-des',
                    },
                    modify: {
                        params: [
                                {
                                position: 3,
                                fields: {
                                    type: 'background',
                                    label: this.$t('overlay_gradient'),
                                    name: 'background_gradient',
                                    options: {
                                        oneline: true,
                                        reset: true,
                                        types: ['gradient'],
                                    },
                                    css:{
                                        selector: 'root .ecom-collection__description--paragraph.ecom-html-des.ecom-view-more-enable[style*="max-height"]::after,root .ecom-collection__description--paragraph .ecom-text-des.ecom-view-more-enable::after',
                                        properties:{
                                            'background':'',
                                        }
                                    }
                                }
                            },
                            {
                                position: 20,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            }
                        ]
                    }
                }
            ];

            if (this.data.settings.view_more) {
                style.push({
                    group_alias: 'button',
                    options: {
                        group_title: this.$t('view_more'),
                        group_name: 'collection_view_more',
                        selector: ' .ecom-collection__description-view-more-btn'
                    },
                    modify: {
                        params: [
                            {
                                position: 0,
                                fields: [
                                    {
                                        type: 'choose',
                                        label: this.$t('alignment'),
                                        name: 'alignment',
                                        options: {
                                            oneline: true,
                                            responsive: true,
                                            type: 'text-align',
                                            values: ['flex-start', 'center', 'flex-end']
                                        },
                                        css: {
                                            properties: {
                                                'justify-content':''
                                            },
                                            selector: 'root .ecom-collection__description--view-more'
                                        }
                                    }
                                ]
                            }
                           
                        ]
                    }
                });
                style.push({
                    group_alias: 'button',
                    options: {
                        group_title: this.$t('view_less'),
                        group_name: 'collection_view_less',
                        selector: ' .ecom-collection__description-view-less-btn'
                    },
                    modify: {
                        position: 0,
                        params:{
                            alias:'align-items',
                            options:{
                                label: this.$t('alignment'),
                                css:{
                                    selector:'root .ecom-collection__description--view-less',
                                    properties:{
                                        'align-items':'',
                                        'justify-content':''
                                    }
                                }
                            }
                        }
                    }
                });
            }
            const iconParamsDefault = [
                {
                    name: "iconPrimaryColor",
                    label: this.$t('color'),
                    type: "color",
                    options: {
                        oneline: true,
                        global: {
                            type: "colors"
                        },
                    },
                    css: {
                        properties: {
                            color: ""
                        }
                    }
                },
                {
                    name: "iconBackground",
                    label: this.$t('background'),
                    type: "background",
                    options: {
                        oneline: true,
                        responsive: true,
                    },
                    css: {
                        properties: {
                            background: ""
                        }
                    }
                },
                {
                    type: "popup",
                    label: this.$t('border'),
                    name: "iconBorder",
                    options: {
                        oneline: true,
                        type: "border",
                    },
                    css: {
                        properties: {
                            border: ""
                        }
                    }
                },
                {
                    name: "iconBoxShadow",
                    label: this.$t('box_shadow'),
                    type: "popup",
                    options: {
                        oneline: true,
                        type: "box-shadow",
                    },
                    css: {
                        properties: {
                            "box-shadow": ""
                        }
                    }
                },
                {
                    name: "iconBorderRadius",
                    label: this.$t('border_radius'),
                    type: "dimension",
                    options: {
                        responsive: true,
                        type: "radius",
                        units: {
                            "%": {
                                min: 0,
                                max: 100
                            },
                            px: {
                                min: 0,
                                max: 1000
                            }
                        }
                    },
                    css: {
                        properties: {
                            overflow:'hidden',
                            "border-radius": ""
                        }
                    }
                },
            ]
            if(this.data.settings?.view_more_icon || this.data.settings?.view_less_icon)
            {
                style.push({
                    group_title: this.$t('icon'),
                    group_name: 'icon',
                    selector: ' .ecom-collection__description-view-less-btn, .ecom-collection__description-view-more-btn ',
                    params:[
                        {
                            name: "iconFontSize",
                            label: this.$t('size'),
                            type: "number",
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 300
                                    }
                                }
                            },
                            css: {
                                selector: " svg",
                                properties: {
                                    height: "",
                                    width: ""
                                }
                            }
                        },
                        {
                            name: "iconTransform",
                            label: this.$t('rotate'),
                            type: "number",
                            options: {
                                responsive: true,
                                min: 0,
                                max: 360
                            },
                            css: {
                                selector: " svg",
                                properties: {
                                    transform: "rotate(%value%deg)"
                                }
                            }
                        },
                        {
                            name: "tab",
                            type: "tab",
                            value: "normal",
                            options: {
                                tabs: [
									{
										name: "normal",
										title: this.$t('normal')
									},
									{
										name: "hover",
										title: this.$t('hover')
									}
                                ]
                            },
                            css: {
                                isCss: false
                            }
                        },
                        ...addSwitch(iconParamsDefault,'normal' , { selector: '  svg'}),
                        ...addSwitch(iconParamsDefault,'hover',{ selector: ':hover  svg'}),
                    ]
                });
            }

            return style;
        }
    }
};
</script>
