import { $t } from '@/plugins/i18n';
export default ({ reverse, screens, name }) => {
    let result = [];
    for (let k in screens) {
        let screen = screens[k];
        if (reverse && k !== 'desktop') {
            result[0] = result[0] ?? [];
            result[0].push(
                {
                    name: 'flex-direction' + ((k !== 'desktop') ? ('__' + k) : ''),
                    label: $t('reverse_screen_title', {title: screen.title}),
                    type: 'popup',
                    value: 'row',
                    options: {
                        type: 'dropdown',
                        preview: 'title',
                        oneline: true,
                        values: {
                            row: $t('default'),
                            'column-reverse': $t('vertical_reverse'),
                            'row-reverse': $t('horizontal_reverse'),
                            'column': $t('vertical'),



                        },
                        warnings:
                            k == 'tablet' ? {
                                content: $t('strong_the_reverser_only_works_properly_when_each_column_is_on_a_line_strong'),
                            } : []
                    },
                    css: {
                        properties: {
                            'flex-direction': ''
                        },
                        important: name === 'Row',
                        selector:  name === 'Row' ? ' > div.core__row--columns' : ' div.core__row--columns',
                    }
                }
            );
        }
        result[1] = result[1] ?? [];
        result[1].push({
            name: 'display' + ((k !== 'desktop') ? ('__' + k) : ''),
            label: $t('hide_on_screen_title', {title: screen.title}),
            type: 'toggle',
            // Empty = visible (keep element's natural display: flex/block/…).
            // Only 'none' should emit CSS — never force display:block.
            value: '',
            options: {
                oneline: true,

                values: {
                    on: {
                        label: $t('yes'),
                        value: 'none'
                    },
                    off: {
                        label: $t('no'),
                        value: ''
                    }
                },
            },
            css: {
                properties: {
                    display: ''
                }
            }
        });
    }
    return result.map((item, i) => {
        if (i < result.length - 1) {
            return [...item, { type: 'line' }];
        }
        return item;
    }).flat();
};