export type VideoSourceLike = {
    url?: string;
    format?: string;
    mimeType?: string;
    width?: number;
    height?: number;
};

const FORMAT_PRIORITY: Record<string, number> = {
    mp4: 4,
    webm: 3,
    mov: 2,
    m3u8: 1,
};

const getFormat = (source: VideoSourceLike): string => {
    const format = (source?.format || '').toLowerCase();
    if (format) return format;

    const mimeType = (source?.mimeType || '').toLowerCase();
    if (mimeType.includes('/')) return mimeType.split('/').pop() || '';

    return ((source?.url || '').split('?')[0].split('.').pop() || '').toLowerCase();
};

/**
 * Shopify splits an uploaded video into several renditions (SD-480p, HD-720p, HD-1080p, m3u8...)
 * and does not return them in a fixed order, so picking sources[0] often lands on a low quality
 * rendition. Pick the best playable one instead: playable format first, then resolution, then bitrate.
 */
export const getBestVideoSource = <T extends VideoSourceLike>(sources: T[]): T | null => {
    if (!Array.isArray(sources) || sources.length === 0) {
        return null;
    }

    if (sources.length === 1) return sources[0];

    const getScore = (source: T) => {
        const url = source?.url || '';

        const resolution = Number(source?.height) || Number(url.match(/(\d+)p/i)?.[1]) || 0;
        const bitrate = Number(url.match(/(\d+(?:\.\d+)?)Mbps/i)?.[1]) || 0;
        const formatScore = FORMAT_PRIORITY[getFormat(source)] || 0;

        return formatScore * 10_000_000 + resolution * 1_000 + bitrate;
    };

    return [...sources].sort((a, b) => getScore(b) - getScore(a))[0] || null;
};
