// store/modules/library/constants.ts

/** Map tab name → Laravel route name, dùng trong action load(). */
export const LIBRARY_ROUTES: Record<string, string> = {
    my_favorites : 'builder.favorites.get',
    my_templates : 'builder.my_templates',
    my_tasks     : 'builder.my_tasks',
    pages        : 'builder.pages',
    sections     : 'builder.sections',
    all_pages    : 'builder.all-pages',
};

/** Tên route API, dùng trực tiếp trong actions thay vì hard-code string. */
export const API_ROUTES = {
    INIT              : 'builder.library.init',
    TEMPLATE          : 'builder.template',
    TEMPLATE_CREATE   : 'builder.template.create',
    TEMPLATES_DELETE  : 'builder.templates.delete-multiple',
    TASK              : 'builder.tasks',
    TASK_UPDATE       : 'builder.tasks.update',
    FAVORITE          : 'builder.favorite',
    POST              : 'builder.post',
    POST_THEME        : 'builder.theme_post',
} as const;

/** Các tab thuộc thư viện EComposer (không cần đăng nhập). */
export const ECOM_TABS = ['pages', 'sections', 'all_pages'] as const;

/**
 * Page size của tab My Favorites.
 * Backend (PostController::favorite) chặn tối đa 100 favorite/user nên 1 trang
 * là đủ hiển thị toàn bộ — tránh việc user tưởng bị giới hạn số item đã lưu
 * khi grid không đủ cao để kích hoạt infinite scroll.
 */
export const FAVORITES_PAGE_SIZE = 100;

/** Các tab thuộc nội dung cá nhân của user. */
export const USER_TABS = ['my_favorites', 'my_templates', 'my_tasks'] as const;

export type LibraryTab = typeof ECOM_TABS[number] | typeof USER_TABS[number];
