<template>
    <div class="flex justify-end" :class="id">
        <div class="relative inline-flex justify-end">
            <button type="button" class="relative flex items-center popup__button color-picker-btn"
                :class="size === 'normal' ? 'w-8 h-8 rounded-full border-none ' : 'w-3 h-3 rounded-xs'"
                :style="bg" :data-tooltip="globalTitle ?? value ?? null" data-tooltip-location="bottom"
                @click="open($event)" ref="popupColorPickerBtn" ><span class="color-picker-btn-inner"></span></button>
            <Teleport to="body" v-if="isopen">
                <BackDrop v-if="isopen" @click="doClose" class="outside-close-cursor"></BackDrop>
                <transition enter-active-class="transition duration-200 ease-out"
                    enter-from-class="transform scale-90 opacity-0" enter-to-class="transform scale-100 opacity-100"
                    leave-active-class="transition duration-150 ease-in"
                    leave-from-class="transform scale-100 opacity-100" leave-to-class="transform scale-90 opacity-0">
                    <div class="z-[62] fixed ecom-fields__popup popup-color"
                        :id="idTeleport"
                        :style="{
                            top: popupColorPosition.top,
                            left: popupColorPosition.left,
                            bottom: popupColorPosition.bottom
                        }">
                        <ColorComponent class="relative z-[2]"
                            :global-selected="dGlobal.selected"
                            :global="global"
                            :value="value"
                            :field="field"
                            :showColorPopupAtBottom="showColorPopupAtBottom"
                            :idTeleport ="idTeleport"
                            @refeshColor="refeshColor"
                            @selectedTab="onTabChanged"
                            @update:value="value = $event"
                            @update:global-selected="dGlobal.selected = $event" />
                    </div>
                </transition>
            </Teleport>
        </div>
    </div>
</template>

<script lang="ts">
import { Popmenu } from '@/mixins';
import ColorComponent from '../../components/molecules/ColorPicker/ColorPanel.vue';
import { showPopupAtBottom, showPopupAtBottomInSideNar } from '@/utils';

type ColorPickerInstance = {
    isopen: boolean;
    clearClosePopupListener?: () => void;
};

const colorPickerInstances = new Set<ColorPickerInstance>();

function closeOtherColorPickers(current: ColorPickerInstance) {
    colorPickerInstances.forEach((vm) => {
        if (vm !== current && vm.isopen) {
            vm.isopen = false;
            vm.clearClosePopupListener?.();
        }
    });
}

interface PopupPosition {
    top: string | number;
    left: string;
    bottom: string | number;
}

interface PopupDimensions {
    width: number;
    height: number;
}

export default {
    name: 'Color',
    components: {
        ColorComponent,
    },
    mixins: [Popmenu],
    props: {
        field: {
            type: Object,
            default() {
                return {};
            }
        },
        data: [Object, String],
        size: {
            type: String,
            default: 'normal'
        }
    },
    emits: ['update:data'],
    data() {
        return {
            popupColorPosition: { top: 0, left: '0px', bottom: 0 } as PopupPosition,
            idTeleport: 'popup-color-' + Date.now() + Math.random().toString(36).substr(2, 9),
            value: this.data ?? this.field.value ?? '',
            isWatch: false,
            dGlobal: {
                selected: ''
            },
            valueStart: '',
            showColorPopupAtBottom: true,
            mutationObserver: null as MutationObserver | null,
            popupElement: null as HTMLElement | null,
            popupDimensions: { width: 270, height: 468 } as PopupDimensions,
            closePopupListenerTimer: null as ReturnType<typeof setTimeout> | null
        };
    },
    computed: {
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        bg() {
            return {
                '--background-color': this.value
                    ? this.value
                    : `linear-gradient(to top left,
                        rgba(0,0,0,0) 0%,
                        rgba(0,0,0,0) calc(50% - 0.8px),
                        red 50%,
                        rgba(0,0,0,0) calc(50% + 0.8px),
                        rgba(0,0,0,0) 100%)`
            };
        },
        globalTitle() {
            if (this.dGlobal) {
                return this.$store.getters['settings/globalTitle']('colors', this.dGlobal.selected);
            }
            return '';
        },
        global() {
            return this.field?.options?.global;
        }
    },
    watch: {
        'dGlobal.selected'(val) {
            if (val && this.global) {
                this.$emit('update:data', {
                    ['global-' + this.global.type]: val
                });
            }
        },
        data: {
            immediate: true,
            handler: function (val) {
                if (this.isWatch) {
                    this.isEmit = false;
                    this.value = val;
                    this.dGlobal.selected = this.global?.value ?? '';
                }
                this.isWatch = true;
            }
        },
        value: {
            immediate: true,
            handler: function (val) {
                if (this.isEmit) {
                    this.isWatch = false;
                    this.$emit('update:data', val);
                }
                this.isEmit = true;
            }
        },
        isopen() {
            if (this.isopen) {
                this.$store.commit("builder/setIsPopupOpen", true);
                this.clearClosePopupListener();
                // Defer so the click that opened the picker (label/hex) can finish bubbling
                // before we listen — otherwise closePopupSelection closes immediately.
                this.closePopupListenerTimer = setTimeout(() => {
                    window.addEventListener('click', this.closePopupSelection);
                    this.closePopupListenerTimer = null;
                }, 0);
                this.startObservingPopup();
            } else {
                this.clearClosePopupListener();
                this.stopObservingPopup();
            }
        },
        isPopupOpen(val) {
            if(val === false) {
                this.isopen = false;
            }
        }
    },
    methods: {
        openPicker() {
            this.open();
        },
        open() {
            if (this.isopen) {
                this.isopen = false;
                return;
            }
            // Label/hex use @click.stop — close other Color pickers only, not background popup.
            closeOtherColorPickers(this);
            this.$nextTick(() => {
                this.isopen = true;
            });
        },
        clearClosePopupListener() {
            if (this.closePopupListenerTimer) {
                clearTimeout(this.closePopupListenerTimer);
                this.closePopupListenerTimer = null;
            }
            window.removeEventListener('click', this.closePopupSelection);
        },
        refeshColor() {
            this.value = '';
            this.dGlobal.selected = null;
        },
        doClose() {
            this.isopen = false;
        },
        closePopupSelection(e: any) {
            if (!e.target.closest(`.${this.id}`) && !e.target.closest(`#${this.idTeleport}`)) {
                this.isopen = false;
                this.clearClosePopupListener();
            }
        },

        // Khởi tạo MutationObserver để theo dõi popup
        startObservingPopup() {
            this.stopObservingPopup(); // Đảm bảo không có observer nào đang chạy

            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === Node.ELEMENT_NODE) {
                                const element = node as Element;
                                if (element.id === this.idTeleport) {
                                    this.popupElement = element as HTMLElement;
                                    this.updatePopupDimensions();
                                    this.calculatePopupPosition();
                                    this.updatePopupVisibility();

                                    requestAnimationFrame(() => {
                                        this.updatePopupDimensions();
                                        this.calculatePopupPosition();
                                        this.updatePopupVisibility();
                                    });
                                }
                            }
                        });
                    }
                });
            });

            // Bắt đầu quan sát body để theo dõi khi popup được thêm vào
            this.mutationObserver.observe(document.body, {
                childList: true,
                subtree: true
            });
        },

        // Dừng MutationObserver
        stopObservingPopup() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },

        // Cập nhật kích thước popup
        updatePopupDimensions() {
            if (this.popupElement) {
                this.popupDimensions = {
                    width: this.popupElement.offsetWidth || 270,
                    height: this.popupElement.offsetHeight || 468
                };
            }
        },

        // Cập nhật hiển thị popup (top/bottom)
        updatePopupVisibility() {
            if (!this.popupElement || !this.$refs.popupColorPickerBtn) return;

            const themeSettingModalEle = document.querySelector(".theme-settings__inner--right") as HTMLElement;
            if (themeSettingModalEle) {
                this.showColorPopupAtBottom = showPopupAtBottom(themeSettingModalEle, this.$refs.popupColorPickerBtn, this.popupElement);
            } else {
                this.showColorPopupAtBottom = showPopupAtBottomInSideNar(this.$refs.popupColorPickerBtn, this.popupElement);
            }
        },

        // Tính toán lại vị trí khi có kích thước thực tế của popup
        calculatePopupPosition() {
            if (!this.popupElement || !this.$refs.popupColorPickerBtn) return;

            const rect = this.$refs.popupColorPickerBtn.getBoundingClientRect();
            const { width: popupWidth, height: popupHeight } = this.popupDimensions;
            const distanceToRightRect = window.innerWidth - rect.left - rect.width;

            const distanceToBottom = window.innerHeight - rect.top - rect.height;

            // Tìm container cha
            const fixedSelected = this.$refs.popupColorPickerBtn.closest('.popup-container') as HTMLElement || this.$refs.popupColorPickerBtn.closest('.fixed') as HTMLElement || this.$refs.popupColorPickerBtn.closest('.absolute') as HTMLElement;
            const fixedRect = fixedSelected.getBoundingClientRect();

            // Tính toán vị trí left với kích thước thực tế
            let left: number;
            if(fixedSelected) {
                const {left: leftFixed, width: selectedWidth} = fixedRect;
                const distanceToRight = window.innerWidth - leftFixed - selectedWidth;

                if(leftFixed >= popupWidth) {
                    const spaceRectToFixedRect = rect.left - leftFixed;
                    if(spaceRectToFixedRect > 50) {
                        left = rect.left - popupWidth - 20;
                    }else {
                        left = leftFixed - popupWidth;
                    }
                }else if(distanceToRight >=  popupWidth) {
                    const spaceRectToFixedRect = distanceToRightRect - distanceToRight;
                    if(spaceRectToFixedRect > 50) {
                        left = rect.left + rect.width + 20;
                    }else {
                        left = leftFixed + selectedWidth;
                    }

                }else {
                    left = rect.left + rect.width + 20;
                }
            }else {
                left = rect.left + rect.width + 20;
            }

            // Tính toán vị trí top/bottom với kích thước thực tế
            let top: string, bottom: string;
            const fixedPopupGetter = this.$refs.popupColorPickerBtn.closest('.fixed') as HTMLElement;
            const containerFly = this.$refs.popupColorPickerBtn.closest('.popup-container') as HTMLElement;
            let bottomFixedSpace = 0;
            if(fixedPopupGetter) bottomFixedSpace = window.innerHeight - fixedPopupGetter.getBoundingClientRect().top;

            if(fixedPopupGetter && !containerFly && bottomFixedSpace >= popupHeight) {
                top = fixedPopupGetter.getBoundingClientRect().top + window.scrollY + "px";
                bottom = 'auto';
            }else if (distanceToBottom >= popupHeight) {
                top = (rect.bottom + window.scrollY - rect.height - 15) + "px";
                bottom = 'auto';
            } else {
                top = (rect.bottom + window.scrollY) - (popupHeight - distanceToBottom) + "px";
                bottom = 'auto';
            }

            this.popupColorPosition = { top, left: left + 'px', bottom };
        },
        onTabChanged() {
            this.$nextTick(() => {
                this.updatePopupDimensions();
                this.calculatePopupPosition();
                this.updatePopupVisibility();
            });
        }
    },
    mounted() {
        colorPickerInstances.add(this);
        this.valueStart = this.value;
    },
    beforeUnmount() {
        colorPickerInstances.delete(this);
        this.stopObservingPopup();
        this.clearClosePopupListener();
    }
};
</script>

