type EditorConfigs = {
    locked: boolean;
    snapLines: boolean;
    distanceLines: boolean;
    showColumnGrid: boolean;
    autoSnap: boolean;
    safeMode: boolean;
};
let storageData;
// Fallback: đọc localStorage cho các config đã được user setting trước đó (trước khi chuyển sang lưu DB)
// Khi editor_config từ DB load xong sẽ override qua setEditorConfigs()
function _ls<T>(key: string, fallback: T): T {
    try {
        const raw = localStorage.getItem(key);
        if (raw !== null) return JSON.parse(raw) as T;
    } catch {}
    return fallback;
}

const configsEdtior: EditorConfigs = {
    locked: _ls('editor-locked', false),
    snapLines: _ls('editor-snap-lines', true),
    distanceLines: _ls('editor-distance-lines', true),
    showColumnGrid: _ls('editor-show-column-grid', true),
    autoSnap: _ls('editor-auto-snap', true),
    // safeMode KHÔNG seed từ localStorage: nó là state của DB (editor_config.safe_mode) và
    // URL iframe workspace bị chốt ngay ở Workspace.created(), TRƯỚC khi page/init trả về.
    // Seed cũ (localStorage true nhưng DB false/không có key) làm URL mang safe_mode=1, rồi
    // hydrateSafeModeFromDb lật state về false -> iframe render bằng URL cũ và server trả
    // "Safe mode is active" trong khi builder tưởng đang ở workspace thật.
    safeMode: false,
};

try {
    storageData = localStorage.getItem("optionsPromo") || "";
    if (!storageData) {
        storageData = {
            pages_library: {
                trending: {
                    enable: true,
                    expiry: null
                },
                popular: {
                    enable: true,
                    expiry: null
                },
                newest: {
                    enable: true,
                    expiry: null
                }
            },
            sections_library: {
                trending: {
                    enable: true,
                    expiry: null
                },
                popular: {
                    enable: true,
                    expiry: null
                },
                newest: {
                    enable: true,
                    expiry: null
                }
            },
            popular_extension: {
                enable: true,
                expiry: null
            },
            newest_extension: {
                enable: true,
                expiry: null
            }
        };
    } else {
        storageData = JSON.parse(storageData);
    }

} catch (e) {}
export const promoConfig = storageData;
export const editorConfigs = configsEdtior;
