<template>
    <div class="ecom-element ecom-cart ecom-gift-wrap-cart">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <div class="ecom-gift-cart-wrapper">
            <div class="ecom-gift-wrap-cart__container"
            >
                <div class="ecom-gift-wrap-cart__wrapper ecom-flex">
                    <div class="ecom-gift-wrap-cart__content ecom-flex ecom-fl_center ecom-al_center">
                        <div v-if="data.settings?.submit_type === 'checkbox'" 
                            class="ecom-gift-wrap-cart__action-checkbox ecom-flex"
                            v-html="liquid('checkbox')"
                        />
                        <span v-html="data.settings?.icon_text" 
                            class="ecom-gift-wrap-cart__content-icon">
                        </span>
                        <span v-html="lang(data.settings?.label, 'gift_label')" 
                            class="ecom-gift-wrap-cart__content-text">
                        </span>
                    </div>
                    <div v-if="data.settings?.submit_type === 'button'" 
                        class="ecom-gift-wrap-cart__action-button ecom-flex"
                        v-html="liquid('button')"
                    />
                </div>
            </div>
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
import { Liquid, Element,Javascript } from '@/mixins';
export default {
    name: 'Cart Gift Wrap',
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        liquids(){
            let tagLink = this.exporting && this.data.settings.product ? 'a' : 'div'
            return {
                button: {
                    code: `
                        {%- capture product_handle -%} ${this.data.settings.product?.value} {%- endcapture -%}
                        {%- assign product = all_products[product_handle] -%}
                        <${tagLink} {% if product.selected_or_first_available_variant.id %} href="/cart/add/{{product.selected_or_first_available_variant.id}}" {% endif %}
                            class="ecom-gift-wrap-cart__button">
                            <span class="ecom-gift-wrap-cart__button-icon">
                                ${this.data.settings?.icon_button ?? ''}
                            </span>
                            <span class="ecom-gift-wrap-cart__button-text">
                                ${this.data.settings?.button_label ? this.lang(this.data.settings?.button_label, 'button_gift_label') : ''}
                            </span>
                        </${tagLink}>
                    `,
                    preview: ''
                },
                checkbox: {
                    code: `
                        {%- capture product_handle -%} ${this.data.settings.product?.value} {%- endcapture -%}
                        {%- assign product = all_products[product_handle] -%}
                        <input type="checkbox" {% if product.selected_or_first_available_variant.id %} data-variant-id="{{product.selected_or_first_available_variant.id}}" data-href="/cart/add/{{product.selected_or_first_available_variant.id}}" {% endif %}
                            class="ecom-gift-wrap-cart__checkbox">
                    `,
                    preview: ''
                }
            };
        },
        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'picker',
                            name: 'product',
                            label: this.$t('choose_product'),
                            options: {
                                type: 'product',
                                output: ['value', 'name', 'thumbnail'],
                                editAlt: true,
                                visible: {
                                    keep_data: false
                                }
                            }
                        },
                        {
                            type: 'textarea',
                            label: this.$t('content'),
                            name: 'label',
                            options: {
                                toolbar: true,
                                height: 80
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('icon'),
                            name: 'icon_text',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible: {
                                    keep_data: false,
                                }
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1]
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__content-icon',
                                properties: {
                                    order: ''
                                }
                            }
                        },
                        {
                            name: "icon_animation",
                            label: this.$t('animation'),
                            type: "dropdown",
                            options: {
                                search: true,
                                type: "animation",
                                size: "small"
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__content-icon',
                                properties: {
                                    animation: ""
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'gap_text',
                            label: this.$t('gap'),
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 50
                                    }
                                }
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__content',
                                properties: {
                                    gap: ''
                                }
                            }
                        },
                        {
                            type: 'line'
                        },
                        {
                            type: 'popup',
                            name: 'submit_type',
                            label: this.$t('submit_type'),
                            options: {
                                default: false,
                                preview: 'title',
                                type: 'dropdown',
                                values: {
                                    button: this.$t('button'),
                                    checkbox: this.$t('checkbox')
                                }
                            }
                        },
                        {
                            type: 'text',
                            name: 'button_label',
                            label: this.$t('button_label'),
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'button'
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('icon_button'),
                            name: 'icon_button',
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'button'
                                },
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_button_position',
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'button'
                                },
                                type: 'align-x',
                                values: [-1, 1]
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__button-icon',
                                properties: {
                                    order: ''
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'gap_button',
                            label: this.$t('gap'),
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'button'
                                },
                                units: {
                                    px: {
                                        min: 0,
                                        max: 50
                                    }
                                }
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__button',
                                properties: {
                                    gap: ''
                                }
                            }
                        },
                        {
                            type: 'paragraph',
                            name: 'paragraph',
                            content: this.$t('b_ordering_b'),
                            options: {
                                visible: (data) => {
                                    return data['submit_type'] === 'checkbox'
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'order_text',
                            label: this.$t('text'),
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'checkbox'
                                },
                                units: {
                                    '': {
                                        min: 1,
                                        max: 10
                                    }
                                }
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__content-text',
                                properties: {
                                    order: ''
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'order_icon',
                            label: this.$t('icon'),
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'checkbox'
                                },
                                units: {
                                    '': {
                                        min: 1,
                                        max: 10
                                    }
                                }
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__content-icon',
                                properties: {
                                    order: ''
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'order_checkbox',
                            label: this.$t('checkbox'),
                            options: {
                                visible: (data)=>{
                                    return data['submit_type'] === 'checkbox'
                                },
                                units: {
                                    '': {
                                        min: 1,
                                        max: 10
                                    }
                                }
                            },
                            css: {
                                selector: ' .ecom-gift-wrap-cart__action-checkbox',
                                properties: {
                                    order: ''
                                }
                            }
                        },
                    ]
                }
            ];
        },
        javascript(){
            return function(){
                if(!this.$el) return;
                let $el = this.$el, isLive = this.isLive;
                if(isLive){
                    let elCartJson = document.querySelector("#ecom-cart-json");
                    let cartJson = elCartJson && elCartJson.innerHTML ? JSON.parse(elCartJson.innerHTML) : null ;
                    let checkbox = $el.querySelector('.ecom-gift-wrap-cart__checkbox');
                    let giftVariantId = checkbox ? parseInt(checkbox.dataset.variantId) : null;
                    if(cartJson && giftVariantId) {
                        let items = cartJson.items;
                        if(items.length > 0){
                            let gift = items.find(function(item){
                                if(item.variant_id == giftVariantId) {
                                    checkbox.checked = true
                                }
                            })
                        }
                    }
                    if(checkbox){
                        if(checkbox.checked !== true) {
                            checkbox.addEventListener('click', function(){
                                if(giftVariantId) {
                                    window.location = checkbox.dataset.href;
                                }
                            })
                        }
                        else {
                            checkbox.addEventListener('click', function(){
                                if(checkbox.dataset.href) {
                                    window.location = `/cart/change?id=${giftVariantId}&quantity=0`;
                                }
                            })
                        }
                    }
                }
            };
        },
        css(){
