                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
                .ecom-gift-wrap-cart__content-icon svg, .ecom-gift-wrap-cart__button-icon svg {
                    width: 12px;
                    height: 12px;
                }
                .ecom-gift-wrap-cart__button {
                    text-decoration: none;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
                .ecom-gift-wrap-cart__action-checkbox {
                    height: 100%;
                    justify-content: center;
                    align-items: center;
                }
                .ecom-gift-wrap-cart__checkbox[type=checkbox]{
                    -webkit-appearance: none;
                    -moz-appearance: none;
                    appearance: none;
                    padding: 0;
                    -webkit-print-color-adjust: exact;
                    color-adjust: exact;
                    display: inline-block;
                    vertical-align: middle;
                    background-origin: border-box;
                    -webkit-user-select: none;
                    -moz-user-select: none;
                    -ms-user-select: none;
                    user-select: none;
                    flex-shrink: 0;
                    height: 1.6rem;
                    width: 1.6rem;
                    background-color: #fff;
                    border: 1px solid rgba(209,213,219,1);
                }
                .ecom-gift-wrap-cart__checkbox[type=checkbox]:checked {
                    border-color: transparent;
                    background-color: #059669;
                    background-size: 100% 100%;
                    background-position: center;
                    background-repeat: no-repeat;
                    background-image: url("data:image/svg+xml,%3csvg viewBox='0 0 16 16' fill='white' xmlns='http://www.w3.org/2000/svg'%3e%3cpath d='M12.207 4.793a1 1 0 010 1.414l-5 5a1 1 0 01-1.414 0l-2-2a1 1 0 011.414-1.414L6.5 9.086l4.293-4.293a1 1 0 011.414 0z'/%3e%3c/svg%3e");
                }
                .ecom-gift-wrap-cart__action-button {
                    max-width: 100%;
                }
            `;
        },
        style() {
            let style = [
                {
                    group_alias: 'box',
                    options: {
                        group_title: this.$t('general'),
                    }
                },
                {
                    group_alias: 'text',
                    options: {
                        group_name: 'text',
                        group_title: this.$t('text'),
                        selector: ' .ecom-gift-wrap-cart__content-text'
                    },
                    modify: {
                        remove: {
                            index: 0,
                            length: 1
                        },
                        
                    }
                },
                {
                    group_alias: 'icon',
                    options: {
                        group_name: 'icon_text',
                        group_title: this.$t('text_icon'),
                        selector: 'root .ecom-gift-wrap-cart__content-icon'
                    }
                },

            ]
            let button = [
                {
                    group_alias: 'button',
                    options: {
                        group_name: 'button',
                        group_title: this.$t('button'),
                        selector: ' .ecom-gift-wrap-cart__button'
                    }
                },
                {
                    group_alias: 'icon',
                    options: {
                        group_name: 'icon_button',
                        group_title: this.$t('button_icon'),
                        selector: 'root .ecom-gift-wrap-cart__button-icon'
                    }
                },
            ];
            let checkbox = {
                group_title: this.$t('checkbox'),
                params: [
                    {
                        type: 'number',
                        name: 'checkbox_size',
                        label: this.$t('size'),
                        options: {
                            units: {
                                "px": {
                                    min: 0,
                                    max: 50
                                }
                            }
                        },
                        css: {
                            selector: 'root .ecom-gift-wrap-cart__action-checkbox input.ecom-gift-wrap-cart__checkbox',
                            properties: {
                                width: '',
                                height: ''
                            }
                        } 
                    },
                    {
                        type: 'tab',
                        name: 'tab',
                        value: 'normal',
                        options: {
                            tabs: [
                                {
                                    name: 'normal',
                                    title: this.$t('normal'),
                                },
                                {
                                    name: 'hover',
                                    title: this.$t('hover'),
                                },
                                {
                                    name: 'active',
                                    title: this.$t('active'),
                                }
                            ]
                        },
                        css: false
                    },
    
                    {
                        alias: 'background',
                        options: {
                            css: {
                                selector: 'root .ecom-gift-wrap-cart__checkbox'
                            },
                            options: {
                                visible: data => data['tab'] === 'normal'
                            }
                        }
                    },
                    {
                        alias: 'background',
                        options: {
                            name: 'backgroundHover',
                            css: {
                                properties: {
                                    background: ''
                                },
                                selector: 'root .ecom-gift-wrap-cart__checkbox:hover'
                            },
                            options: {
                                visible: data => data['tab'] === 'hover'
                            }
                        }
                    },
                    {
                        alias: 'background',
                        options: {
                            name: 'backgroundActive',
                            css: {
                                properties: {
                                    background: ''
                                },
                                important: true,
                                selector: 'root .ecom-gift-wrap-cart__checkbox:checked'
                            },
                            options: {
                                visible: data => data['tab'] === 'active'
                            }
                        }
                    },
                    {
                        type: 'popup',
                        label: this.$t('border'),
                        name: 'popup',
                        options: {
                            type: 'border',
                            visible: data => data['tab'] === 'normal'
                        },
                        css: {
                            selector: 'root .ecom-gift-wrap-cart__checkbox'
                        }
                    },
                    {
                        type: 'popup',
                        label: this.$t('border'),
                        name: 'popupHover',
                        options: {
                            type: 'border',
                            visible: data => data['tab'] === 'hover'
                        },
                        css: {
                            properties: {
                                border: ''
                            },
                            selector: 'root .ecom-gift-wrap-cart__checkbox:hover'
                        }
                    },
                    {
                        type: 'popup',
                        label: this.$t('border'),
                        name: 'popupActive',
                        options: {
                            type: 'border',
                            visible: data => data['tab'] === 'active'
                        },
                        css: {
                            properties: {
                                border: ''
                            },
                            important: true,
                            selector: 'root .ecom-gift-wrap-cart__checkbox:checked'
                        }
                    },
                    {
                        type: 'dimension',
                        label: this.$t('border_radius'),
                        name: 'border-radius',
                        options: {
                            type: 'radius',
                            units: 'default',
                            visible: data => data['tab'] === 'normal'
                        },
                        css: {
                            important:true,
                            selector: 'root .ecom-gift-wrap-cart__checkbox'
                        }
                    },
                    {
                        type: 'dimension',
                        label: this.$t('border_radius'),
                        name: 'border-radiusHover',
                        options: {
                            units: 'default',
                            type: 'radius',
                            visible: data => data['tab'] === 'hover'
                        },
                        css: {
                            important:true,
                            properties: {
                                'border-radius': ''
                            },
                            selector: 'root .ecom-gift-wrap-cart__checkbox:hover'
                        }
                    },
                    {
                        type: 'dimension',
                        label: this.$t('border_radius'),
                        name: 'border-radiusActive',
                        options: {
                            units: 'default',
                            type: 'radius',
                            visible: data => data['tab'] === 'active'
                        },
                        css: {
                            properties: {
                                'border-radius': ''
                            },
                            important: true,
                            selector: 'root .ecom-gift-wrap-cart__checkbox:checked'
                        }
                    },
                    {
                        name: "transition",
                        type: "number",
                        label: this.$t('transition_duration_span_class_lowercase_ms_span'),
                        options: {
                            min: 0,
                            max: 5000,
                            visible: {
                                keep_data: true,
                                condition: (data) => {
                                    return data["tab"] === "hover";
                                }
                            }
                        },
                        css: {
                            selector: "root .ecom-gift-wrap-cart__checkbox",
                            properties: {
                                transition: "all %value%ms ease"
                            }
                        }
                    },
                    {
                        type: 'line'
                    },
                    { alias: 'spacing', options: {css: {selector: 'root .ecom-gift-wrap-cart__checkbox'}}},
                ]
            }
            if(this.data.settings?.submit_type === 'checkbox') {
                style.push(checkbox)
            }
            else {
                style.push(...button)
            }
            return style;
        },
        default() {
            return {
                "settings": {
                    "icon_text": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" fill=\"currentColor\"><path d=\"M256 85.46L280.1 44.45C296.3 16.91 325.9 0 357.8 0H360C408.6 0 448 39.4 448 88C448 102.4 444.5 115.1 438.4 128H464C490.5 128 512 149.5 512 176V240C512 260.9 498.6 278.7 480 285.3V448C480 483.3 451.3 512 416 512H96C60.65 512 32 483.3 32 448V285.3C13.36 278.7 0 260.9 0 240V176C0 149.5 21.49 128 48 128H73.6C67.46 115.1 64 102.4 64 88C64 39.4 103.4 0 152 0H154.2C186.1 0 215.7 16.91 231.9 44.45L256 85.46zM288 176V240H464V176H288zM224 176H48V240H224V176zM224 288H80V448C80 456.8 87.16 464 96 464H224V288zM288 464H416C424.8 464 432 456.8 432 448V288H288V464zM360 128C382.1 128 400 110.1 400 88C400 65.91 382.1 48 360 48H357.8C342.9 48 329.1 55.91 321.5 68.78L286.7 128H360zM225.3 128L190.5 68.78C182.9 55.91 169.1 48 154.2 48H152C129.9 48 112 65.91 112 88C112 110.1 129.9 128 152 128H225.3z\"></path></svg>",
                    "gap_text": "5px",
                    "gap_button": "0px",
                    "icon_button_position": 1,
                    "icon_position": -1,
                    "label": "Do you want a gift wrap? <font color=\"#9e9595\">Only $5.00</font>",
                    "button_label": "Add A Gift Wrap",
                    "submit_type": "button"
                },
                "style": {
                    "text": {
                        "textColor": "#000000",
                        "textTypography": {
                            "font-size": "14px"
                        }
                    },
                    "icon_text": {
                        "iconFontSize": "20px",
                        "iconPrimaryColor": "#000000"
                    },
                    "button": {
                        "tab": "normal",
                        "buttonWidthnormalmode": "150px",
                        "buttonHeightnormalmode": "30px",
                        "buttonColornormalmode": "#000000",
                        "buttonBackgroundnormalmode": {
                            "classic": {
                                "background-color": "#ffffff"
                            }
                        },
                        "buttonColorhovermode": "#ffffff",
                        "buttonBackgroundhovermode": {
                            "classic": {
                                "background-color": "#000000"
                            }
                        },
                        "buttonBorderRadiusnormalmode": {
                            "top": "20px",
                            "left": "20px",
                            "bottom": "20px",
                            "right": "20px"
                        },
                        "buttonBordernormalmode": {
                            "border-style": "solid",
                            "border-color": "#000000",
                            "border-width": {
                                "top": "0.8px",
                                "left": "0.8px",
                                "bottom": "0.8px",
                                "right": "0.8px"
                            }
                        },
                        "buttonCursor": "pointer",
                        "transitions": {
                            "transitions": {
                                "duration": "300ms"
                            }
                        },
                        "spacing": {
                            "margin": {
                                "left": "37.5px"
                            }
                        },
                        "buttonTypography": {
                            "font-size": "12px"
                        }
                    }
                }
            }
        }
    },
    methods: {}
};
</script>
