<template>
    <div class="ecom-element ecom-cart ecom-cart__checkout-button" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <input type="hidden" name="checkout" value="ec">
        <div class="ecom-cart__checkout-button-wrapper" :class="{'ecom-ingrid-full-height': data.inGrid}">
            <div class="ecom-cart__checkout-button-container" :class="{'ecom-ingrid-full-height': data.inGrid}">
                <button
                    type="submit"
                    name="checkout"
                    class="ecom-cart__checkout-button--submit"
                    :class="{'ecom-ingrid-full-height': data.inGrid}"
                >
                    <span
                        class="ecom-cart-checkout-text"
                        v-html="lang(data.settings.label,'checkout_label')"
                    />
                    <span
                        class="ecom__element--button-icon"
                        v-html="data.settings?.icon"
                    />
                </button>
                <div v-if="data.settings?.accelerated_checkout"
                    v-html="liquid('additional_checkout_buttons')"
                    class="ecom-cart__additional-checkout-buttons"
                />
            </div>
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
    import {Liquid, Element, Javascript } from '@/mixins';
    export default {
        name: 'Cart Checkout',
        mixins: [Liquid, Element, Javascript],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        data(){
            return {
                jsreactives:[
                    'label'
                ]
            }
        },
        computed: {
            liquids () {
                return {
                    additional_checkout_buttons: {
                        code: `
                        {% if additional_checkout_buttons %}
                            <div class="additional-checkout-buttons ${this.data.settings?.accelerated_checkout_style == 'horizontal' ? '' : 'additional-checkout-buttons--vertical'}">
                                {{ content_for_additional_checkout_buttons }}
                            </div>
                        {% endif %}`
                        ,
                        preview: ''
                    }
                };
            },

            settings () {
                return [
                    {
                        group_title: this.$t('general'),
                        params: [
                            {
								type: 'paragraph',
								options: {
									warnings: {
										content: this.$t('note_this_element_can_only_work_when_you_put_it_to_the_same_section_with_the_cart_item_element'),
									}
								}
							},
                            {
                                type: 'text',
                                label: this.$t('checkout_label'),
                                name: 'label',
                                placeholder: this.$t('checkout'),
                                options: {
                                    toolbar: true
                                }
                            },
                            {
                                type: 'picker',
                                label: this.$t('icon'),
                                name: 'icon',
                                options: {
                                    type: 'icon',
                                    layout: 'grid',
                                    output: 'value',
                                    multiple: false,
                                    simple: false
                                }
                            },
                            {
                                type: 'choose',
                                label: this.$t('icon_position'),
                                name: 'icon_position',
                                options: {
                                    type: 'align-x',
                                    values: [-1, 1],
                                    visible: {
                                        keep_data: false,
                                        condition: (data) => {
                                            return data['icon'];
                                        }
                                    }
                                },
                                css:{
                                    selector:' .ecom__element--button-icon',
                                    properties:{
                                        order:''
                                    }
                                }
                            },
                            {
                                type: 'number',
                                label: this.$t('icon_spacing'),
                                name: 'spacing',
                                options: {
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 200
                                        }
                                    },
                                    visible: {
                                        keep_data: false,
                                        condition: (data) => {
                                            return data['icon'];
                                        }
                                    }
                                },
                                css:{
                                    selector:' .ecom-cart__checkout-button--submit',
                                    properties:{
                                        gap:''
                                    }
                                }
                            },
                            {
                                type: 'line'
                            },
                            {
                                type: 'paragraph',
                                content: this.$t('b_accelerated_checkout_buttons_b'),
                            },
                            {
                                type: 'paragraph',
                                options: {
                                    warnings: {
                                        content: this.$t('the_accelerated_checkout_button_only_works_when_one_or_more_offline_payment_methods_are_enabled_on_your_store'),
                                    }
                                }
                            },
                            {
                                type: 'switch',
                                name: 'accelerated_checkout',
                                label: this.$t('use_accelerated_checkout'),
                                options: {
                                    values: {
                                        on: {
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                name: 'accelerated_checkout_style',
                                label: this.$t('style'),
                                value: 'horizontal',
                                options: {
                                    visible: (data)=>{
                                        return data['accelerated_checkout'] === true
                                    },
                                    type: 'dropdown',
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        horizontal: this.$t('horizontal'),
                                        vertical: this.$t('vertical'),
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                name: 'accelerated_checkout_alignment',
                                label: this.$t('alignment'),
                                value: 'center',
                                options: {
                                    visible: (data)=>{
                                        return data['accelerated_checkout'] === true
                                    },
                                    type: 'dropdown',
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        'flex-start': 'Flex start',
                                        'center': 'Center',
                                        'flex-end': 'Flex end',
                                    }
                                },
                                css: {
                                    selector: ' [data-shopify-buttoncontainer]',
                                    properties: {
                                        'justify-content': ''
                                    }
                                }
                            }
                        ]
                    }
                ];
            },
            javascript () {
                return function () {
                    let $form = this.$el.closest('form'),isLive=this.isLive;
                    let labelButton = this.settings.label;
                    labelButton = document.createTextNode(labelButton);
                    if($form)
                    {
                        let $buttons = $form.querySelectorAll('.ecom-cart__checkout-button--submit'),
                            $notices = $form.querySelectorAll('.ecom-cart__agree-notice-message'),
                            requiredCheckBoxList = $form.querySelectorAll('.ecom-required--checkbox'),
                            $agrees = $form.querySelectorAll('.ecom-cart__agree--input'),
                            $button = null,
                            $notice = null,
                            $agree = null;
                        if($buttons.length && $buttons.length  > 1) {
                            $buttons.forEach(function(btn) {
                                if($button) return;
                                if(((window.innerWidth > 1024 && !btn.closest('.hide-on-desktop'))
                                    || ((window.innerWidth > 767 && window.innerWidth <= 1024) && !btn.closest('.hide-on-tablet'))
                                    || (window.innerWidth <= 767 && !btn.closest('.hide-on-mobile')))){
                                    $button = btn;
                                }
                            });
                        }
                        else {
                            $button = $buttons[0];
                        }
                        if($agrees.length && $agrees.length  > 1) {
                            $agrees.forEach(function(btn) {
                                if($agree) return;
                                if(((window.innerWidth > 1024 && !btn.closest('.hide-on-desktop'))
                                    || ((window.innerWidth > 767 && window.innerWidth <= 1024) && !btn.closest('.hide-on-tablet'))
                                    || (window.innerWidth <= 767 && !btn.closest('.hide-on-mobile')))){
                                    $agree = btn;
                                }
                            });
                        }
                        else {
                            $agree = $agrees[0];
                        }
                        if($notices.length && $notices.length  > 1) {
                            $notices.forEach(function(btn) {
                                if($notice) return;
                                if(((window.innerWidth > 1024 && !btn.closest('.hide-on-desktop'))
                                    || ((window.innerWidth > 767 && window.innerWidth <= 1024) && !btn.closest('.hide-on-tablet'))
                                    || (window.innerWidth <= 767 && !btn.closest('.hide-on-mobile')))){
                                    $notice = btn;
                                }
                            });
                        }
                        else {
                            $notice = $notices[0];
                        }
                        if(!$button) return;
                        let check = $form.querySelector(".ecom-cart__product-items");
                        if(!check) {
                            $button.setAttribute('disabled', 'disabled');
                            return;
                        }
                        // handle checkbox required
                        function handleRequiredCheckbox() {
                            if(requiredCheckBoxList.length > 1) {
                                let isChecked = false;

                                requiredCheckBoxList.forEach(function(checkbox) {
                                    if(checkbox.checked) {
                                        isChecked = true;
                                    }
                                })

                                if(isChecked) {
                                    requiredCheckBoxList.forEach(function(checkbox) {
                                        checkbox.required = false;
                                    })
                                } else {
                                    requiredCheckBoxList.forEach(function(checkbox) {
                                        checkbox.required = true;
                                    })
                                }
                            }
                        }
                        // handle submit form
                        function handleSubmit(){
                            $form.addEventListener('submit',function(event){
                                event.preventDefault();
                                if($notice && $agree && !$agree.checked)
                                {
                                    $notice.style.display= 'inherit';
                                    return false;
                                }
                                else
                                {
                                    if(isLive)
                                    {
                                        this.submit();
                                    }

                                }
                                return false;
                            });
                        }
                        // check app hulk-product-options
                        // available -> change name button || block redirect to check out
                        /*
                        if(window.hulkapps){
                            $button.setAttribute('name', 'ecom_cart_checkout');
                        }
                        */
                        // unavailable
                        $button.addEventListener('click', function(){
                            handleRequiredCheckbox();
                            handleSubmit()
                        });

                    }

                };
            },
            // requestShopifyType () {
            //     return {
            //         shopify_type: 'cart'
            //     };
            // },
            css(){
                return `
                    .ecom-cart__checkout-button--submit[disabled='disabled'] {
                        opacity: 0.3;
                    }
                    .ecom-cart__checkout-button--submit{
                        width: 100%;
                        display: flex;
                        padding: 10px 15px;
                        font-weight: 500;
                        font-size: 14px;
                        line-height: 16px;
                        align-items: center;
                        background-color: #000000;
                        color: #FFFFFF;
                        border: none;
                        text-decoration: none;
                    }
                    .ecom__element--button-icon {
                        height: 20px;
                    }
                    .ecom-cart__checkout-button-container {
                        display: flex;
                        flex-direction: column;
                    }
                `;
            },
            style () {
                const inGrid = this.data.inGrid;
                const params = [
                    {
                        group_alias: `button${inGrid ? ':grid' : ''}`,
                        options:{
                            group_title: this.$t('button'),
                            group_name: 'button',
                            selector: ' .ecom-cart__checkout-button--submit',
                        },
                        modify:{
                            params:[
                                {
                                    position:0,
                                    fields: [
                                        !inGrid ?
                                        {
                                            alias:'align-items',
                                            options:{
                                                label: this.$t('alignment'),
                                                name: 'button_alignment',
                                                css:{
                                                    selector:'root .ecom-cart__checkout-button-container',
                                                    properties:{
                                                        'align-items':'',
                                                        'justify-content':''
                                                    }
                                                }
                                            }
                                        } : {},
                                        {
                                            alias:'align-items',
                                            options:{
                                                label: this.$t('text_alignment'),
                                                name: 'text_alignment',
                                                css:{
                                                    selector:'root .ecom-cart__checkout-button--submit',
                                                    properties:{
                                                        'justify-content':''
                                                    }
                                                }
                                            }
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias:'icon',
                        options:{
                            group_name: 'icon',
                            group_title: this.$t('icon'),
                            selector: ' .ecom__element--button-icon',
                        },
                        modify:{
                            params:[
                                {
                                    position:15,
                                    fields:[
                                        {
                                            type: 'line'
                                        },
                                        {
                                            alias:'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    }
                ];
                /*
                if(this.data.settings.accelerated_checkout) {
                    params.push({
                        group_alias: 'box',
                        options: {
                            group_name: 'accelerated_checkout',
                            group_title: this.$t('accelerated_checkout'),
                            selector: 'root .ecom-cart__additional-checkout-buttons'
                        },
                        modify: {
                            params: [
                                {
                                    position: 20,
                                    fields: [
                                        {
                                            alias: 'spacing',
                                            options: {
                                                label: this.$t('spacing'),
                                            }
                                        }
                                    ]
                                }
                            ]
                        }
                    })
                }
                */
                return params;
            },
            default() {
                return {
                    "settings": {
                        "label": "Checkout",
                        "spacing": "10px",
                        "accelerated_checkout_style": "horizontal"
                    },
                    "style": {
                        "button": {
                        "tab": "normal",
                        "buttonWidthnormalmode": "300px",
                        "text_alignment": "center",
                        "button_alignment": "center",
                        "buttonHeightnormalmode": "50px",
                        "buttonBackgroundnormalmode": {
                            "classic": {
                            "background-color": "#000000"
                            }
                        },
                        "buttonColornormalmode": "#ffffff",
                        "buttonBorderRadiusnormalmode": {
                            "right": "4px",
                            "top": "4px",
                            "left": "4px",
                            "bottom": "4px"
                        }
                        },
                        "icon": {
                            "iconFontSize": "20px"
                        }
                    }
                }
            }
        },
        methods: {}
    };
</script>
