<template>
    <div class="ec-keys">
        <!-- No label of its own: Field.vue already draws one above the control. -->
        <div v-for="action in actions" :key="action.name" class="ec-keys__row">
            <span class="ec-keys__keys">
                <code>{{ altLabel }}</code>
                <code>Shift</code>
                <select
                    class="ec-shortcut-keys__select"
                    :aria-label="action.label"
                    :value="chosen[action.name]"
                    @change="pick(action.name, $event.target.value)"
                >
                    <option
                        v-for="code in keys"
                        :key="code"
                        :value="code"
                        :disabled="code !== chosen[action.name] && taken.indexOf(code) > -1"
                    >{{ keyChar(code) }}</option>
                </select>
            </span>
            <span class="ec-keys__label">{{ action.label }}</span>
        </div>
    </div>
</template>

<script>
    /**
     * One editable row per shortcut: the modifiers are fixed, the merchant only
     * picks the letter. Needed because Alt+Shift+A is not ours alone - a
     * browser extension or another app on the storefront can hold the same
     * combo and a page script cannot outrank an extension, so moving our own
     * key is the way out.
     *
     * The Polaris Extensions Hub renders the same field off the same
     * settings.json: see the main app's
     * `resources/extension-settings/src/components/fields/ShortcutKeysField.ts`
     * and the `.ec-keys` / `.ec-shortcut-keys` blocks of its `src/styles.css`.
     * The builder is a separate repo and a separate Vite project, so this is a
     * copy - a change to one side has to be made on the other.
     */
    export default {
        name: 'Shortcut_keysField',
        props: {
            data: {
                type: Object,
                default: null
            },
            field: {
                type: Object,
                default(){
                    return {};
                }
            }
        },
        emits: ['update:data'],
        computed: {
            actions(){
                return this.field?.options?.actions ?? [];
            },
            keys(){
                return this.field?.options?.keys ?? [];
            },
            /* The key Windows calls Alt is printed "option" on every Mac
               keyboard. The Hub resolves a `{{alt}}` token in the schema for
               this; the builder has no such layer, so the choice is made here. */
            altLabel(){
                const nav = typeof navigator === 'undefined' ? null : navigator;
                const platform = nav?.userAgentData?.platform || nav?.platform || nav?.userAgent || '';
                return /mac/i.test(String(platform)) ? '⌥ Option' : 'Alt';
            },
            /* A saved value is a partial object: an action added after the shop
               last saved has no entry yet and takes the schema default. */
            chosen(){
                const saved = this.data && typeof this.data === 'object' ? this.data : {};
                const out = {};
                for (const action of this.actions){
                    const raw = String(saved[action.name] ?? action.value ?? '');
                    out[action.name] = this.keys.indexOf(raw) === -1
                        ? String(action.value ?? this.keys[0] ?? '')
                        : raw;
                }
                return out;
            },
            taken(){
                return Object.values(this.chosen);
            }
        },
        methods: {
            keyChar(code){
                if (/^Key[A-Z]$/.test(code)) return code.slice(3);
                if (/^Digit[0-9]$/.test(code)) return code.slice(5);
                return code;
            },
            pick(name, code){
                this.$emit('update:data', { ...this.chosen, [name]: code });
            }
        }
    };
</script>

