<template>
  <div class="ecom-element ecom__element ecom-placeholder-extension">
    <div v-if="!exporting" class="ecom-placeholder-extension__wrapper"
      :data-ecom-placeholder="$t('extension_is_not_installed', {extensionName: extName})">
    </div>
  </div>
</template>

<script>
import { Element } from '@/mixins';
export default {
  name: 'PlaceholderExtension',
  mixins: [Element],
  props: {
    data: {
      type: Object,
      default() {
        return {};
      }
    }
  },
  methods: {
    replaceNumber(val) {
      return val ? val.replace(/\(\d+\)$/, '') : val;
    }
  },
  computed: {
    extName() {
      return this.replaceNumber(this.data.title);
    },
    queryString() {
      let title = encodeURIComponent(this.data.title);
      let queryString = this.replaceNumber(title);
      return queryString;
    },
    settings() {
      return [{
        group_title: this.$t('general'),
        params: [
          {
            type: 'paragraph',
            description: this.$t("you_must_install_extension", {extensionName: this.extName, queryString: this.queryString})
          },
        ]
      }];
    },
    css() {
      return `
      .ecom-placeholder-extension__wrapper::before{
        content: attr(data-ecom-placeholder);
        text-align: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        position: relative;
        justify-content: center;
        align-items: center;
        border-radius: 8px;
        border: 1px dashed #91D0FF;
        color: #00527C;
        font-size: 13px;
        line-height: 20px;
        font-weight: 650;
        opacity: 1;
        padding: 6px;
      }
      `
    }
  }
}
</script>