<template>
    <div
        ref="wrapper"
        class="ecom__element ecom-element element__text"
        :class="getType !== '' ? getType : ''"
        :data-stopdrag="isEditingThisElement ? true : null"
    >
        <Liquid :data="getMetaLiquid" />
        <div
            ref="content"
            class="text-content ecom-html"
            :style="[maxHeight ? `max-height: var(--ecom-text-height); --ecom-text-height: ${maxHeight}` : '']"
            :class="[
                `has-drop-cap-view-${dropCapView}`,
                data.settings?.dropcap ? 'ecom__text--dropcap' : '',
                contentType == 'short' ? 'ecom-text--is-mark' : ''
            ]"
            :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
            spellcheck="false"
            @dblclick="edit"
            @click="handleContentClick"
            @keyup="update"
            @blur="handleBlur"
            v-html="isEditingThisElement ? editingValue : exporting ? lang(convertedContent, 'text-content', metaLang) : data.settings?.content"
        />

        <div class="ecom-text--more-actions" v-if="contentType === 'short' && view_more">
            <button
                type="button"
                class="ecom-text_view-more-btn"
                ref="showMore"
                @click="showMore"
            >
                <span class="ecom__element--button-icon" v-if="data.settings?.view_more_icon" v-html="data.settings.view_more_icon" />
                <span v-text="lang(data.settings.view_more_text, 'view_more_text')"></span>
            </button>
        </div>
        <div class="ecom-text--less-actions"  v-if="contentType === 'short' && view_more">
            <button
                type="button"
                ref="showLess"
                class="ecom-text_view-less-btn"
                style="display:none"
                @click="showLess"
            >
                <span class="ecom__element--button-icon" v-if="data.settings?.view_less_icon" v-html="data.settings.view_less_icon" />
                <span v-text="lang(data.settings.view_less_text, 'view_less_text')"></span>
            </button>

        </div>
    </div>
</template>

<script>
import { Element, Liquid, Javascript } from '@/mixins';
import { addSwitch } from "@/plugins/fields/utils";
import { placeCaretAtEnd, resolveMetaEdgeCaret, applyCaretRange } from '@/utils/contentEditable';
export default {
    name: 'TextEditor',
    presets: true,
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/text/',
    mixins: [Element, Liquid, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            dropCapView: 'default',
            editing: false,
            lastUpdate: 0,
            editingValue: '',
            metaLang: {},
            metaLiquid: '',
            convertedContent: '',
            isBlur: false,
            isTyping: false
        };
    },
    computed: {
        getType() {
            return this.data?.style?.text?.textTextShadow?.type ? 'ecom-type-' + this.data?.style?.text?.textTextShadow?.type : 'ecom-type-deffault';
        },
        isContentEditable() {
            return this.$store.getters["builder/isContentEditable"];
        },
        editingElementId() {
            return this.$store.getters["builder/editingElementId"];
        },
        isEditingThisElement() {
            return this.editingElementId === this.text.id && this.isContentEditable;
        },
        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'textarea',
                            label: this.$t('content'),
                            name: 'content',
                            options: {
                                toolbar: 'full',
                                generator: true,
                                dynamic: true,
                                height: 250,
                                textFormat: true,
                                warnings: {
                                    content: this.$t('notice_shopify_multiple_languages_will_not_support_too_long_content_please_use_the_element_page_content_instead')
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('drop_cap'),
                            name: 'dropcap',
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('content_type'),
                            name: 'type',
                            value: 'full',
                            options: {
                                preview: "title",
                                type: 'dropdown',
                                values: {
                                    short: this.$t('short'),
                                    full: this.$t('full')
                                },
                                default: false
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('max_height'),
                            name: 'max-height',
                            placeholder: '200',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 1000
                                    },
                                    'vh': {
                                        min: 0,
                                        max: 100
                                    },
                                    'vw': {
                                        min: 0,
                                        max: 100
                                    }
                                },
                                visible: function (data) {
                                    return data['type'] === 'short';
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_view_more'),
                            name: 'view_more',
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: function (data) {
                                    return data['type'] === 'short';
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('view_more_icon'),
                            name: 'view_more_icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible: function(data){return data.view_more && data.type == 'short'}
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('view_less_icon'),
                            name: 'view_less_icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible:function(data){return data.view_more && data.type == 'short'}
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible:function(data){return data.view_more && data.type == 'short'}
                            },
                            css:{
                                selector:' .ecom__element--button-icon',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "spacing",
                            label: this.$t('spacing'),
                            options: {
                                label: this.$t('spacing'),
                                responsive: true,
                                units: {
                                    px: {
                                        min: 1,
                                        max: 50,
                                        step: 1
                                    }
                                },
                                visible:function(data){return data.view_more && data.type == 'short'},
                                reset:false
                            },
                            css: {
                                selector: 'root .ecom-text--more-actions button ,root .ecom-text--less-actions button',
                                properties: {
                                    gap: ""
                                }
                            }
                        },
                        {
                            label: this.$t('view_more_text_button'),
                            name: 'view_more_text',
                            type: 'text',
                            options: {
                                visible: function (data) {
                                    return data['type'] === 'short' && data['view_more'];
                                }
                            }
                        } ,
                        {
                            label: this.$t('view_less_text_button'),
                            name: 'view_less_text',
                            type: 'text',
                            options: {
                                visible: function (data) {
                                    return data['type'] === 'short' && data['view_more'];
                                }
                            }
                        }
                    ]
                }
            ];
        },

        css() {
            return `
                .ecom__text--dropcap:first-letter {
                    font-size: 40px;
                    color: #2bcf19;
                    display:inline-flex;
                    border-style: solid;
                    border-width: 1px;
                    border-color: transparent;
                    float:left;
                    line-height:1;
                }
                .ecom__text--dropcap.has-drop-cap-view-default:first-letter {
                    border:none;
                }
                body[ecom-loaded] .ecom-sections .element__text a {
                    cursor: auto;
                }
                .text-content.ecom-html {
                    overflow: hidden;
                    position: relative;
                }

                .ecom-text--is-mark::after {
                    position: absolute;
                    content: '';
                    left: 0;
                    right: 0;
                    bottom: 0;
                    height: 150px;
                    background: linear-gradient(rgba(255, 255, 255, 0), rgb(255, 255, 255));
                    pointer-events: none;
                }

                .ecom-text_view-more-btn,
                .ecom-text_view-less-btn {
                    display: flex;
                    background: none;
                    outline: none;
                    border: none;
                    align-items: center;
                }

                .ecom__element--button-icon {
                    display: flex;
                    align-items: center;
                }

                .ecom-text_view-more-btn svg, .ecom-text_view-less-btn svg {
                    width: 16px;
                    color: #fff;
                }
                sub, sup{
                    position: relative;
                    font-size: 75%;
                    line-height: 0;
                    vertical-align: baseline;
                }
                sup{
                    top: -.5em;
                }
                sub{
                    bottom: -.25em;
                }
                .ecom-type-hollow .text-content {
                    text-shadow: var(--stroke) !important;
                    background: transparent !important;
                    -webkit-background-clip: unset !important;
                    -webkit-text-fill-color: unset !important;
                }
                .ecom-type-text_3d .text-content {
                    text-shadow: var(--text_3d) !important;
                }
                .ecom-type-gradient .text-content {
                    animation: var(--animation);
                }
                @keyframes gradientMove {
                    0% { background-position: 100% 100%; }
                    100% { background-position: 0% 0%; }
                }
            `;
        },

        contentType() {
            return this.data.settings?.type;
        },

        maxHeight() {
            return this.data.settings.type === 'short'
                ? this.data.settings['max-height']
                : null;
        },

        view_more() {
            return this.data && this.data.settings && 'view_more' in this.data.settings
                ? this.data.settings.view_more
                : false;
        },

        text() {
            return this.data;
        },
        getMetaLiquid() {
            return this.metaLiquid;
        },
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.text.id;
        },

        javascript() {
            return function() {
                if(!this.$el) { return; }

                const $el = this.$el;

                const read_more_btn = $el.querySelector('.ecom-text_view-more-btn');
                const read_less_btn = $el.querySelector('.ecom-text_view-less-btn');
                const el_content = $el.querySelector('.text-content.ecom-html');
                if(!el_content) { return; }

                if(read_more_btn) {
                    read_more_btn.addEventListener('click', () => {
                        el_content.classList.remove('ecom-text--is-mark');
                        el_content.style.maxHeight = "";
                        read_more_btn.style.display = "none";
                        read_less_btn.style.display = "";
                    })
                }

                if(read_less_btn) {
                    read_less_btn.addEventListener('click', () => {
                        el_content.classList.add('ecom-text--is-mark');
                        el_content.style.maxHeight = "var(--ecom-text-height)";
                        read_less_btn.style.display = "none";
                        read_more_btn.style.display = "";
                    })
                }
            }
        },

        default(){
            return {
                settings: {
            		type: "full",
                    content: "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.",
                    "max-height": "200px",
                    view_more: true,
                    view_less_text: "view less",
                    spacing: "6px",
                    view_more_text: "view more"
                },
                style: {
                    // text: {
                    //     textTextAlign: "left"
                    // },
                    text_dropcap: {
                        dropcapTypography: {
                            "font-size": "40px"
                        },
                        dropcapColor: "#f50c0c",
                        dropcapColorStackedView: "#5eff00",
                        dropcapBackgroundStackedView: "#4800ff",
                        dropcapColorFramedView: "#2bcf19",
                        dropcapBackgroundFramedView: "transparent",
                        dropcapView: "framed"
                    },
                    collection_view_more: {
                        tab: "normal",
                        "align-items": "flex-start",
                        buttonTypography: {
                            "text-decoration": "underline",
                            "font-size": "none"
                        },
                        spacing: {
                            padding: {
                                top: "5px",
                                bottom: "5px"
                            }
                        }
                    },
                        collection_view_less: {
                            tab: "normal",
                            buttonTypography: {
                                "text-decoration": "underline"
                            },
                            spacing: {
                                padding: {
                                top: "5px",
                                bottom: "5px"
                                }
                            }
                        },
                        icon: {
                            tab: "normal",
                            iconFontSize: "16px",
                            iconPrimaryColornormalmode: "#000000"
                        }
                }
            }
        }
    },
    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit("builder/setIsContentEditable", false);
                this.$store.commit("builder/setEditingElementId", "");

                const content = this.$refs.content;
                const hasFigmeta = content.innerText.includes('figmeta') || content.innerHTML.includes('figmeta');
                this.text.settings.content = hasFigmeta ? content.innerText : content.innerHTML;
            }
            if (val) {
                this.$store.commit("builder/setEditingElementId", this.text.id);
            }
        },
        'data.settings.content': {
            handler(newVal) {
                this.processContent();
                if (!this.isEditingThisElement || (!this.isTyping && newVal !== this.editingValue)) {
                    this.editingValue = newVal;
                }
            },
            immediate: true
        },
        'data.style': {
            handler() {
                this.dropCapView = this.data?.style?.text_dropcap?.dropcapView ?? 'default';
            },
            deep: true,
            immediate: true
        },
        isContentEditable() {
            this.isBlur = false;
        },
        isEditingThisElement(val) {
            if(val) {
                this.editingValue = this.data.settings.content;
                this.processContent();
                this.focusContentEditor();
            }
        }
    },
    methods: {
        handleBlur() {
            // setTimeout(() => {
            //     this.$refs.content.focus();
            // }, 50);
            if(!this.isBlur) return;
            setTimeout(() => {
                this.$store.commit("builder/setIsContentEditable", false);
            }, 200);
        },
        processContent() {
            const text = this.data.settings?.content;
            if(!text) return '';

            const dom = document.createElement('div');
            dom.innerHTML = text;
            const meta_nodes = dom.querySelectorAll('span[data-meta]');

            // Reset state
            this.metaLiquid = '';
            this.metaLang = {};

            if(meta_nodes) {
                meta_nodes.forEach((el) => {
                    const rawKey = el.dataset.metaKey || '';
                    const meta_key = rawKey.replace(/[^a-zA-Z0-9_]/g, '_').replace(/^[0-9]/, '_$&') || 'meta';
                    const metafield = el.dataset.meta;
                    const meta = document.createTextNode(`{{${meta_key}}}`);

                    const metaAssign = el.dataset.metaAssign;
                    this.metaLiquid += metaAssign || `{%- assign ${meta_key} = ${metafield}-%}`;
                    this.metaLang[meta_key] = meta_key;

                    el.replaceWith(meta);
                });
            }

            this.convertedContent = dom.innerHTML;
        },
        style() {
            let style = [
                {
                    group_alias: 'text',
                    options:{
                        group_title: this.$t('text'),
                        selector: ' .text-content,  .text-content a,  .text-content p,  .text-content span'
                    },
                    modify: {
                        params: [
                            {
                                position: 4,
                                fields: {
                                    alias: 'border',
                                    options: {
                                        label: this.$t('border')
                                    }
                                }
                            },
                            {
                                position: 20,
                                liteMode: true,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            }
                        ]
                    }
                }
            ];
            if (this.data.settings?.dropcap) {
                style.push({
                    group_alias: 'text:dropcap',
                    options:{
                        selector: ' .ecom__text--dropcap:first-letter'
                    }
                });
            }

            if (this.data.settings.view_more) {
                style.push({
                    group_alias: 'button',
                    options: {
                        group_title: this.$t('view_more'),
                        group_name: 'collection_view_more',
                        selector: ' .ecom-text_view-more-btn'
                    },
                    modify: {
                        position: 0,
                        params:{
                            alias:'align-items',
                            options:{
                                label: this.$t('alignment'),
                                css:{
                                    properties:{
                                        'justify-content':''
                                    }
                                }
                            }
                        }
                    }
                });

                style.push({
                    group_alias: 'button',
                    options: {
                        group_title: this.$t('view_less'),
                        group_name: 'collection_view_less',
                        selector: ' .ecom-text_view-less-btn'
                    },
                    modify: {
                        position: 0,
                        params:{
                            alias:'align-items',
                            options:{
                                label: this.$t('alignment'),
                                css:{
                                    properties:{
                                        'justify-content':''
                                    }
                                }
                            }
                        }
                    }
                });
                 const iconParamsDefault = [
                {
                    name: "iconPrimaryColor",
                    label: this.$t('color'),
                    type: "color",
                    options: {
                        oneline: true,
                        global: {
                            type: "colors"
                        },
                    },
                    css: {
                        properties: {
                            color: ""
                        }
                    }
                },
                {
                    name: "iconBackground",
                    label: this.$t('background'),
                    type: "background",
                    options: {
                        oneline: true,
                        responsive: true,
                    },
                    css: {
                        properties: {
                            background: ""
                        }
                    }
                },
                {
                    type: "popup",
                    label: this.$t('border'),
                    name: "iconBorder",
                    options: {
                        oneline: true,
                        type: "border",
                    },
                    css: {
                        properties: {
                            border: ""
                        }
                    }
                },
                {
                    name: "iconBoxShadow",
                    label: this.$t('box_shadow'),
                    type: "popup",
                    options: {
                        oneline: true,
                        type: "box-shadow",
                    },
                    css: {
                        properties: {
                            "box-shadow": ""
                        }
                    }
                },
                {
                    name: "iconBorderRadius",
                    label: this.$t('border_radius'),
                    type: "dimension",
                    options: {
                        responsive: true,
                        type: "radius",
                        units: {
                            "%": {
                                min: 0,
                                max: 100
                            },
                            px: {
                                min: 0,
                                max: 1000
                            }
                        }
                    },
                    css: {
                        properties: {
                            overflow:'hidden',
                            "border-radius": ""
                        }
                    }
                },
            ]

            if(this.data.settings?.view_more_icon || this.data.settings?.view_less_icon)
            {
                style.push({
                    group_title: this.$t('icon'),
                    group_name: 'icon',
                    selector: ' .ecom-text_view-more-btn, .ecom-text_view-less-btn',
                    params:[
                        {
                            name: "iconFontSize",
                            label: this.$t('size'),
                            type: "number",
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 300
                                    }
                                }
                            },
                            css: {
                                selector: " svg",
                                properties: {
                                    height: "",
                                    width: ""
                                }
                            }
                        },
                        {
                            name: "iconTransform",
                            label: this.$t('rotate'),
                            type: "number",
                            options: {
                                responsive: true,
                                min: 0,
                                max: 360
                            },
                            css: {
                                selector: " svg",
                                properties: {
                                    transform: "rotate(%value%deg)"
                                }
                            }
                        },
                        {
                            name: "tab",
                            type: "tab",
                            value: "normal",
                            options: {
                                tabs: [
                                    {
                                        name: 'normal',
                                        title: this.$t('normal'),
                                    },
                                    {
                                        name: 'hover',
                                        title: this.$t('hover'),
                                    }
                                ]
                            },
                            css: {
                                isCss: false
                            }
                        },
                        ...addSwitch(iconParamsDefault,'normal' , { selector: '  svg'}),
                        ...addSwitch(iconParamsDefault,'hover',{ selector: ':hover  svg'}),
                    ]
                });
            }
            }
            return style;
        },
        edit() {
            this.$store.commit("builder/setIsContentEditable", true);
        },
        focusContentEditor() {
            this.$nextTick(() => {
                const el = this.$refs.content;
                if (!el || !this.isEditingThisElement) return;
                placeCaretAtEnd(el, this.idoc());
            });
        },
        /** Dynamic source tag là contenteditable="false"; khi nó nằm cuối nội dung thì
         *  bấm vào vùng trống phía sau không ra con trỏ, không gõ thêm được.
         *  Chỉ can thiệp lúc đang inline-edit, còn lại để builder xử lý click như cũ. */
        handleContentClick(e) {
            if (!this.isEditingThisElement) return;
            const range = resolveMetaEdgeCaret(this.$refs.content, e, this.idoc());
            applyCaretRange(range, this.idoc());
        },
        showMore(){
            let showMore = this.$refs?.showMore;
            let showLess = this.$refs?.showLess;
            let content = this.$refs?.content;
            if(content && showMore){
                content.classList.remove('ecom-text--is-mark');
                content.style.maxHeight = "";
                showMore.style.display = "none";
                showLess.style.display = "";
            }
        },
        showLess(){
            let showMore = this.$refs?.showMore;
            let showLess = this.$refs?.showLess;
            let content = this.$refs?.content;
            if(content && showLess){
                content.classList.add('ecom-text--is-mark');
                content.style.maxHeight = "var(--ecom-text-height)";
                showLess.style.display = "none";
                showMore.style.display = "";
            }
        },
        update(e) {
            const now = Date.now();
            if (now - this.lastUpdate > 300) {
                const newContent = e.target.innerText.includes('figmeta') || e.target.innerHTML.includes('figmeta')
                    ? e.target.innerText
                    : e.target.innerHTML;

                if (this.text.settings.content !== newContent) {
                    this.isTyping = true;
                    this.text.settings.content = newContent;
                    this.lastUpdate = now;
                    this.$nextTick(() => {
                        this.processContent();
                        this.isTyping = false;
                    });
                }
            }
        }
    }
};
</script>
