                    hide_day_of_the_week ? day_of_week = '' : day_of_week += ', ';
                    let day = parseInt(date.split(',')[1]);
                    let month = date.split(',')[2];
                    date = date.split(',')[3];
                    let year = date.split(' ')[0];
                    switch(date_format){
                        case "DoW_dd_mm_style_1":
                            switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${day}${textSt} ${month}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${day}${textNd} ${month}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${day}${textRd} ${month}`;
                                default:
                                    return `${day_of_week}${day}${textTh} ${month}`;
                            }

                        case "DoW_dd_mm_style_2":
                            return `${day_of_week}${day} ${month}`;
                            break;
                        case "DoW_mm_dd_style_1":
                            return `${day_of_week}${month} ${day}`;
                            break;
                        case "DoW_mm_dd_style_2":
                            switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${month} ${day}${textSt}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${month} ${day}${textNd}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${month} ${day}${textRd}`;
                                default:
                                    return `${day_of_week}${month} ${day}${textTh}`;
                            }

                        case "DoW_dd_mm_yyyy_style_1":
                            switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${day}${textSt} ${month} ${year}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${day}${textNd} ${month} ${year}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${day}${textRd} ${month} ${year}`;
                                default:
                                    return `${day_of_week}${day}${textTh} ${month} ${year}`;
                            }
                        case "DoW_dd_mm_yyyy_style_2":

                            switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${day}${textSt} ${month}, ${year}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${day}${textNd} ${month}, ${year}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${day}${textRd} ${month}, ${year}`;
                                default:
                                    return `${day_of_week}${day}${textTh} ${month}, ${year}`;
                            }
                        case "DoW_mm_dd_yyyy_style_1":
                            switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${month} ${day}${textSt}, ${year}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${month} ${day}${textNd}, ${year}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${month} ${day}${textRd}, ${year}`;
                                default:
                                    return `${day_of_week}${month} ${day}${textTh}, ${year}`;
                            }
                        case "DoW_mm_dd_yyyy_style_2":
                            return `${day_of_week}${month} ${day}, ${year}`;
                            break;
                        case "DoW_dd_mm_yyyy_style_3":
                            return `${day_of_week}${day}/${month}/${year}`;
                            break;
                        case "DoW_mm_dd_yyyy_style_3":
                            return `${day_of_week}${month}/${day}/${year}`;
                            break;
                        case "DoW_yyyy_mm_dd":
                            return `${day_of_week}${year}/${month}/${day}`;
                            break;
                        default:
                        switch(day){
                                case 1:
                                case 21:
                                case 31:
                                    return `${day_of_week}${day}${textSt} ${month}`;
                                case 2:
                                case 22:
                                    return `${day_of_week}${day}${textNd} ${month}`;
                                case 3:
                                case 23:
                                    return `${day_of_week}${day}${textRd} ${month}`;
                                default:
                                    return `${day_of_week}${day}${textTh} ${month}`;
                            }
                    }
                }
                function getTime(){
                    let cut_off_time = element_delivery.dataset.time || "dontHave";
                    let hour = null;
                    let min = null;
                    let sec = null;
                    let date = new Date();
                    if(cut_off_time === 'dontHave'){
                        return 'NaN';
                    }
                    else{
                        let pattern = /^([\d]{1,2})\:$/g;
                        let pattern_2 = /^([\d]{1,2})\:([\d]{1,2})\:$/g;
                        let pattern_3 = /^([\d]{1,2})\:([\d]{1,2})\:([\d]{1,2})$/g;
                        if(cut_off_time.match(pattern) || cut_off_time.match(pattern_2) || cut_off_time.match(pattern_3)){
                            hour = parseInt(cut_off_time.split(':')[0]);
                            min = parseInt(cut_off_time.split(':')[1]);
                            sec = parseInt(cut_off_time.split(':')[2]);

                            if(!min){
                                min = 0;
                            }
                            if(!sec){
                                sec = 0;
                            }
                            if(hour>=24 || min >=60 || sec>=60) return 'NaN';
                        }
                        else{
                            return 'NaN';
                        }
                    }
                    let time = new Date().toUTCString().split(' ')[4];
                    let hour_c = parseInt(time.split(':')[0]);
                    let min_c = parseInt(time.split(':')[1]);
                    let sec_c = parseInt(time.split(':')[2]);
                    let rs_hour = null;
                    let rs_min = null;
                    let rs_sec = null;
                    if(sec_c>sec){
                        rs_sec = sec + 60 - sec_c;
                        min--;
                    }
                    else{
                        rs_sec = sec-sec_c;
                    }
                    if(min_c>min){
                        rs_min = min+60-min_c;
                        hour--;
                    }
                    else{
                        rs_min = min-min_c;
                    }
                    if(hour_c>hour){
                        rs_hour = 24+hour-hour_c;
                        date = new Date(date.setDate(date.getDate() + 1));
                    }
                    else{
                        rs_hour = hour-hour_c;
                    }
                    date.setSeconds(rs_sec);
                    date.setMinutes(rs_min);
                    date.setHours(rs_hour);
                    return date;
                }
                function getDate(){
                    let value_start = element_delivery.dataset.ds || "2days";
                    let value_end = element_delivery.dataset.de || "5days";
                    let number_start = 0;
                    let number_end = 0;
                    let arr_day_of_week = ['sun','mon','tue','wed','thu','fri','sat'];
                    if(value_start){
                        number_start = parseInt(value_start.replace('days', ''));
                    }
                    if(value_end){
                        number_end = parseInt(value_end.replace('days', ''));
                    }
                    let mode = element_delivery.dataset.mode || "only_delivery";
                    let exclude_days = element_delivery.dataset.cut || "";
                    let date_format = element_delivery.dataset.format || "DoW_dd_mm_style_1";
                    const one_day = 1000 * 60 * 60 * 24;

                    // Parse excluded days properly
                    let arr_exclude_days = [];
                    if (exclude_days) {
                        let arr = exclude_days.split(',').map(function(day){
                            return day.trim().toLowerCase();
                        });
                        for(let i = 0; i< arr.length; i++){
                            if(arr_day_of_week.includes(arr[i]) && !arr_exclude_days.includes(arr[i])){
                                arr_exclude_days.push(arr[i]);
                            }
                        }
                    }

                    if(arr_exclude_days.length >= 7){
                        return { date_format: ['Invalid', 'Invalid'], date_count: { start: 0, end: 0 } };
                    }

                    // Calculate base date depending on cutoff time
                    let current_date = getTime();
                    let base_date = new Date();
                    if(current_date !== 'NaN' && current_date.getDate() !== (new Date()).getDate()) {
                        base_date.setDate(base_date.getDate() + 1);
                    }

                    function isExcluded(d) {
                        let dayName = arr_day_of_week[d.getDay()];
                        return arr_exclude_days.includes(dayName);
                    }

                    let date_start = new Date(base_date);
                    let date_end = new Date(base_date);

                    if(mode === 'only_delivery'){
                        date_start.setDate(date_start.getDate() + number_start);
                        while(isExcluded(date_start)){
                            date_start.setDate(date_start.getDate() + 1);
                        }

                        date_end.setDate(date_end.getDate() + number_end);
                        while(isExcluded(date_end)){
                            date_end.setDate(date_end.getDate() + 1);
                        }
                    }
                    else if(mode === 'delivery_shipping'){
                        // Đẩy tới ngày đi làm hợp lệ ĐẦU TIÊN (nếu base_date vô tình rơi vào ngày nghỉ)
                        while(isExcluded(date_start)) {
                            date_start.setDate(date_start.getDate() + 1);
                        }
                        let valid_start_days = 0;
                        while(valid_start_days < number_start){
                            date_start.setDate(date_start.getDate() + 1);
                            if(!isExcluded(date_start)) valid_start_days++;
                        }

                        // Đẩy tới ngày hợp lệ ĐẦU TIÊN cho date_end
                        while(isExcluded(date_end)) {
                            date_end.setDate(date_end.getDate() + 1);
                        }
                        let valid_end_days = 0;
                        while(valid_end_days < number_end){
                            date_end.setDate(date_end.getDate() + 1);
                            if(!isExcluded(date_end)) valid_end_days++;
                        }
                    }

                    function countDate(date1, date2) {
                        let d1 = new Date(date1.getFullYear(), date1.getMonth(), date1.getDate());
                        let d2 = new Date(date2.getFullYear(), date2.getMonth(), date2.getDate());
                        return Math.abs(Math.round((d1 - d2) / one_day));
                    }
                    
                    function getFakeUTC(d) {
                        let days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
                        let months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                        return `${days[d.getDay()]}, ${('0' + d.getDate()).slice(-2)} ${months[d.getMonth()]} ${d.getFullYear()} 12:00:00 GMT`;
                    }

                    return {
                        date_format: [
                            formatDate(convertFullDate(getFakeUTC(date_start), date_format)),
                            formatDate(convertFullDate(getFakeUTC(date_end), date_format))
                        ], 
                        date_count: {
                            start: countDate(date_start, new Date()), 
                            end: countDate(date_end, new Date())
                        } 
                    };
                }
                function isAfterCutoff(){
                    let current_date = getTime();
                    if(current_date === 'NaN') return false;
                    return current_date.getDate() !== (new Date()).getDate();
                }
                function replaceTime(){
                    let contentAfterCutoff = element_delivery.dataset.contentAfter;
                    let dataFilter = (isAfterCutoff() && contentAfterCutoff) ? contentAfterCutoff : element_delivery.dataset.content;
                    if(!dataFilter || dataFilter==='') return false;
                    const date_format = getDate().date_format;
                    const date_count = getDate().date_count;
                    dataFilter = dataFilter.replace("[date_start]", `<span class="ecom-delivery-time__date">${date_format[0]}</span>`);
                    dataFilter = dataFilter.replace("[date_end]", `<span class="ecom-delivery-time__date">${date_format[1]}</span>`);
                    dataFilter = dataFilter.replace("[date_count_start]", date_count.start);
                    dataFilter = dataFilter.replace("[date_count_end]", date_count.end);
                    element_delivery.innerHTML = dataFilter;
                    let date = new Date(getTime());
                    let hour = null, min = null;
                    if(date==='NaN'){
                        hour = 'NaN';
                        min = 'NaN';
                    }else{
                        hour = date.getHours();
                        min = date.getMinutes();
                    }

                    let text_hour = element_delivery.dataset.textHour || 'hour(s)';
                    let text_min = element_delivery.dataset.textMin || 'minute(s)';
                    let text_replace = element_delivery.dataset.timeReplace;
                    if(!text_replace) {
                        dataFilter = dataFilter.replace(`[hour]`,``);
                        element_delivery.innerHTML = dataFilter;
                        return false;
                    }
                    dataFilter  = dataFilter.replace(`[${text_replace}]`,`${hour} ${text_hour} ${min} ${text_min}`);
                    element_delivery.innerHTML = dataFilter;
                    element_delivery.closest('.ecom-product-single__delivery-time').classList.add('ecom-delivery-loaded')
                    return true;
                }
                replaceTime();

                const handleReplaceDateTime = setInterval(function(){
                    let progress = replaceTime();
                    if(!progress) {
                        clearInterval(handleReplaceDateTime);
                    }
                },1000);
                // handle when product unavailable
                let hide_when_unavailable = this.settings.hide_when_unavailable;
                if(hide_when_unavailable) {
                    function handleProductUnavailabel() {
                        const $section = $el.closest(".ecom-product-form--single");
                        if(!$section) return;
                        let product = null;
                        const selector = $section.querySelector('[name="id"]');
                        const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                        const isHighVariantProduct = isLive && (variantCount > 250 || $section.querySelector('[data-high-variant-product]'));

                        if(selector) {
                            const json = $section && $section.querySelector('#' + selector.dataset.jsonProduct);
                            if (!json) {
                                return;
                            }

                            try {
                                product = JSON.parse(json.innerHTML);
                            } catch (e) {
                                return;
                            }
                            let variant = null;
                            if(isHighVariantProduct) {
                                variant = product;
                            }
                            else {
                                variant = product.variants.find(function(variant) {
                                    if(variant.id == selector.value) return variant;
                                });
                            }
                            $el.style.display = variant && variant.available ? 'block' : 'none';
                            $section.addEventListener('ecomVariantChange', function(event) {
                                let variant = event.detail.variant;
                                $el.style.display = variant && variant.available ? 'block' : 'none';
                            });
                        }
                        else {
                            if($el.querySelector('[data-sold-out]').dataset.soldOut == 'true') {
                                $el.style.display = 'none';
                            }
                        }
                    }
                    handleProductUnavailabel();
                }

            }
        }
    },
    watch: {

    },
    mounted(){

    }
};
</script>
