<template>
    <div class="ecom-element ecom-cart ecom-cart__coupon">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <div class="ecom-cart__coupon-wrapper">
            <div class="ecom-cart__coupon-container"
                :data-msg-loading="lang(data.settings.msg_loading, 'coupon_msg_loading')"
                :data-msg-removing="lang(data.settings.msg_removing, 'coupon_msg_removing')"
                :data-msg-success="lang(data.settings.msg_success, 'coupon_msg_success')"
                :data-msg-invalid="lang(data.settings.msg_invalid, 'coupon_msg_invalid')"
                :data-msg-empty="lang(data.settings.msg_empty, 'coupon_msg_empty')"
                :data-msg-removed="lang(data.settings.msg_removed, 'coupon_msg_removed')"
                :data-msg-remove-fail="lang(data.settings.msg_remove_fail, 'coupon_msg_remove_fail')"
                :data-msg-error="lang(data.settings.msg_error, 'coupon_msg_error')"
                :data-msg-duplicate="lang(data.settings.msg_duplicate, 'coupon_msg_duplicate')"
                :data-msg-shipping="lang(data.settings.msg_shipping, 'coupon_msg_shipping')"
            >
                <label class="ecom-cart__coupon-text"
                        v-html="lang(data.settings.label || 'Coupon code', 'cart_coupon_label')"
                    />
                <div class="ec-cart__coupon-input-wrap">
                    <div class="ec-cart__coupon-applied-list">
                        <div v-if="exporting === false && !isLive" class="ec-cart__coupon-applied">
                            <span class="ec-cart__coupon-applied-code">SUMMER20</span>
                            <button type="button" class="ec-cart__coupon-remove" disabled tabindex="-1">&times;</button>
                        </div>
                    </div>
                    <input
                        type="text"
                        name="coupon"
                        class="ecom-cart__coupon--input ec-cart__coupon--input"
                        :placeholder="lang(data.settings.placeholder || 'Enter your coupon code', 'coupon_placeholder')"
                        autocomplete="off"
                        value=""
                    >
                    <button
                        type="button"
                        class="ec-cart__coupon--button"
                    >
                        {{ lang(data.settings.apply_text || 'Apply', 'apply') }}
                    </button>
                </div>
                <p
                    class="ec-cart__coupon-message"
                    role="status"
                    aria-live="polite"
                />
            </div>
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
    import {  Element, Liquid, Javascript } from '@/mixins';
    export default {
        name: 'Cart Coupon',
        mixins: [ Element, Liquid, Javascript],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            settings () {
                return [
                    {
                        group_title: this.$t('general'),
                        params: [
                            {
								type: 'paragraph',
								options: {
									warnings: {
										content: this.$t('note_this_element_can_only_work_when_you_put_it_to_the_same_section_with_the_cart_item_element')
									}
								}
							},
                            {
                                type: 'text',
                                label: this.$t('label_title'),
                                name: 'label',
                                placeholder: this.$t('coupon_code'),
                            },
                            {
                                type: 'text',
                                label: this.$t('coupon_placeholder'),
                                name: 'placeholder',
                                placeholder: this.$t('how_can_we_help_you'),
                            },
                            {
                                type: 'text',
                                label: this.$t('apply_button_text'),
                                name: 'apply_text',
                                placeholder: 'Apply',
                            },
                            {
                                type: 'popup',
                                label: this.$t('layout'),
                                name: 'button_layout',
                                options: {
                                    type: 'dropdown',
                                    default: false,
                                    icon_type: 'alignment',
                                    preview: 'title',
                                    values: {
                                        'column': this.$t('vertical'),
                                        'row': this.$t('horizontal'),
                                    }
                                },
                                css: {
                                    selector: 'root .ec-cart__coupon-input-wrap',
                                    properties: {
                                        'flex-direction': ''
                                    }
                                }
                            },
                            {
                                type: 'dimension',
                                label: this.$t('gap'),
                                name: 'input_gap',
                                css: {
                                    selector: 'root .ec-cart__coupon-input-wrap',
                                    properties: {
                                        'gap': ''
                                    }
                                }
                            },
                        ]
                    },
                    {
                        group_title: this.$t('messages'),
                        params: [
                            {
                                type: 'text',
                                label: this.$t('loading_message'),
                                name: 'msg_loading',
                                placeholder: 'Checking discount code...',
                            },
                            {
                                type: 'text',
                                label: this.$t('removing_message'),
                                name: 'msg_removing',
                                placeholder: 'Removing discount code...',
                            },
                            {
                                type: 'text',
                                label: this.$t('success_message'),
                                name: 'msg_success',
                                placeholder: 'Discount code applied successfully.',
                            },
                            {
                                type: 'text',
                                label: this.$t('invalid_message'),
                                name: 'msg_invalid',
                                placeholder: 'Discount code is invalid or not applicable to current cart items.',
                            },
                            {
                                type: 'text',
                                label: this.$t('empty_message'),
                                name: 'msg_empty',
                                placeholder: 'Please enter a discount code.',
                            },
                            {
                                type: 'text',
                                label: this.$t('removed_message'),
                                name: 'msg_removed',
                                placeholder: 'Discount code has been removed.',
                            },
                            {
                                type: 'text',
                                label: this.$t('remove_failed_message'),
                                name: 'msg_remove_fail',
                                placeholder: 'Cannot remove this discount code right now.',
                            },
                            {
                                type: 'text',
                                label: this.$t('error_message'),
                                name: 'msg_error',
                                placeholder: 'Cannot apply discount right now. Please try again.',
                            },
                            {
                                type: 'text',
                                label: this.$t('duplicate_message'),
                                name: 'msg_duplicate',
                                placeholder: 'This discount code has already been applied.',
                            },
                            {
                                type: 'text',
                                label: this.$t('shipping_discount_message'),
                                name: 'msg_shipping',
                                placeholder: 'Shipping discounts are applied at checkout after a shipping address is entered.',
                            },
                        ]
                    }
                ];
            },
            javascript(){
                return function(){
                    if (!this || !this.isLive || !this.$el) {
                        return;
                    }

                    function setCookie(cname, cvalue, exdays) {
                        const d = new Date();
                        d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));
                        let expires = 'expires='+d.toUTCString();
                        document.cookie = cname + '=' + cvalue + ';' + expires + ';path=/';
                    }

                    function getCookie(cname) {
                        let name = cname + '=';
                        let ca = document.cookie.split(';');
                        for(let i = 0; i < ca.length; i++) {
                            let c = ca[i];
                            while (c.charAt(0) == ' ') {
                            c = c.substring(1);
                            }
                            if (c.indexOf(name) == 0) {
                            return c.substring(name.length, c.length);
                            }
                        }
                        return '';
                    }

                    function removeCookie(cname) {
                        document.cookie = cname + '=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/';
                    }

                    const root = window.Shopify && window.Shopify.routes && window.Shopify.routes.root
                        ? window.Shopify.routes.root
                        : '/';
                    const $container = this.$el.querySelector('.ecom-cart__coupon-container');
                    const $input = this.$el.querySelector('[name="coupon"]');
                    const $button = this.$el.querySelector('.ec-cart__coupon--button');
                    const $message = this.$el.querySelector('.ec-cart__coupon-message');
                    const $appliedList = this.$el.querySelector('.ec-cart__coupon-applied-list');
                    let isApplying = false;
                    let confirmedAppliedCodes = [];

                    const msgs = {
                        loading:    ($container && $container.dataset.msgLoading)    || 'Checking discount code...',
                        removing:   ($container && $container.dataset.msgRemoving)   || 'Removing discount code...',
                        success:    ($container && $container.dataset.msgSuccess)    || 'Discount code applied successfully.',
                        invalid:    ($container && $container.dataset.msgInvalid)    || 'Discount code is invalid or not applicable to current cart items.',
                        empty:      ($container && $container.dataset.msgEmpty)      || 'Please enter a discount code.',
                        removed:    ($container && $container.dataset.msgRemoved)    || 'Discount code has been removed.',
                        removeFail: ($container && $container.dataset.msgRemoveFail) || 'Cannot remove this discount code right now.',
                        error:      ($container && $container.dataset.msgError)      || 'Cannot apply discount right now. Please try again.',
                        duplicate:  ($container && $container.dataset.msgDuplicate)  || 'This discount code has already been applied.',
                        shipping:   ($container && $container.dataset.msgShipping)   || 'Shipping discounts are applied at checkout after a shipping address is entered.',
                    };

                    if(!$input) {
                        return;
                    }

                    function parseJsonSafe(response) {
                        return response.text().then(function(text) {
                            if(!text) return {};
                            try {
                                return JSON.parse(text);
                            } catch (e) {
                                return { errors: text };
                            }
                        });
                    }

                    function getAppliedCodesFromCart(cart) {
                        const discountCodes = Array.isArray(cart && cart.discount_codes)
                            ? cart.discount_codes
                            : [];
                        if (discountCodes.length > 0) {
                            return discountCodes
                                .filter(function(dc) {
                                    return typeof dc === 'string' ? true : (dc && dc.applicable !== false);
                                })
                                .map(function(dc) {
                                    return (typeof dc === 'string' ? dc : (dc && dc.code ? dc.code : '')).trim();
                                })
                                .filter(Boolean);
                        }

                        const discountApplications = Array.isArray(cart && cart.cart_level_discount_applications)
                            ? cart.cart_level_discount_applications
                            : (Array.isArray(cart && cart.discount_applications) ? cart.discount_applications : []);
                        if (discountApplications.length > 0) {
                            return discountApplications
                                .filter(function(app) { return app && app.type === 'discount_code'; })
                                .map(function(app) { return (app && app.title ? app.title : '').trim(); })
                                .filter(Boolean);
                        }

                        const lineApplicationTitles = [];
                        const items = Array.isArray(cart && cart.items) ? cart.items : [];
                        items.forEach(function(item) {
                            const allocations = Array.isArray(item && item.line_level_discount_allocations)
                                ? item.line_level_discount_allocations
                                : [];
                            allocations.forEach(function(allocation) {
                                const app = allocation && allocation.discount_application;
                                const title = app && app.type === 'discount_code' && app.title ? app.title.trim() : '';
                                if(title) {
                                    lineApplicationTitles.push(title);
                                }
                            });
                        });
                        if(lineApplicationTitles.length > 0) {
                            return uniqueCodes(lineApplicationTitles);
                        }

                        return [];
                    }

                    function showMessage(content, status) {
                        if(!$message) return;
                        $message.textContent = content || '';
                        $message.classList.remove('ecom-is-error', 'ecom-is-success', 'ecom-is-loading');
                        if(status) {
                            $message.classList.add('ecom-is-' + status);
                        }
                    }

                    function escapeHtml(text) {
                        return String(text)
                            .replace(/&/g, '&amp;')
                            .replace(/</g, '&lt;')
                            .replace(/>/g, '&gt;')
                            .replace(/"/g, '&quot;');
                    }

                    function renderAppliedCodes(codes) {
                        if (!$appliedList) return;
                        $appliedList.innerHTML = codes.map(function(code) {
                            const safe = escapeHtml(code);
                            return '<div class="ec-cart__coupon-applied">'
                                + '<span class="ec-cart__coupon-applied-code">' + safe + '</span>'
                                + '<button type="button" class="ec-cart__coupon-remove" data-code="' + safe + '" aria-label="Remove discount code">&times;</button>'
                                + '</div>';
                        }).join('');
                    }

                    function getRenderedAppliedCodes() {
                        return Array.from(
                            ($appliedList && $appliedList.querySelectorAll('.ec-cart__coupon-remove')) || []
                        ).map(function(btn) {
                            return (btn.dataset.code || '').trim();
                        }).filter(Boolean);
                    }

                    function uniqueCodes(codes) {
                        const seen = {};
                        return codes.filter(function(code) {
                            const normalized = (code || '').trim().toLowerCase();
                            if(!normalized || seen[normalized]) {
                                return false;
                            }
                            seen[normalized] = true;
                            return true;
                        });
                    }

                    function rememberAppliedCodes(codes) {
                        const appliedCodes = uniqueCodes(Array.isArray(codes) ? codes : []);
                        confirmedAppliedCodes = appliedCodes.slice();
                        renderAppliedCodes(appliedCodes);
                        if(appliedCodes.length > 0) {
                            setCookie('discount_codes', JSON.stringify(appliedCodes), 100);
                            return;
                        }
                        removeCookie('discount_codes');
                        removeCookie('discount_code');
                    }

                    function getCurrentAppliedCodes() {
                        const renderedCodes = getRenderedAppliedCodes();
                        return renderedCodes.length > 0 ? renderedCodes : confirmedAppliedCodes.slice();
                    }

                    function normalizeCode(code) {
                        return (code || '').trim().toLowerCase();
                    }

                    function codesInclude(codes, code) {
                        const normalizedCode = normalizeCode(code);
                        return codes.some(function(existingCode) {
                            return normalizeCode(existingCode) === normalizedCode;
                        });
                    }

                    function codesMatch(previousCodes, nextCodes) {
                        if(previousCodes.length !== nextCodes.length) {
                            return false;
                        }
                        return nextCodes.every(function(code) {
                            return codesInclude(previousCodes, code);
                        });
                    }

                    function getDiscountCodeFromResponse(cart, code) {
                        const normalizedCode = normalizeCode(code);
                        const discountCodes = Array.isArray(cart && cart.discount_codes)
                            ? cart.discount_codes
                            : [];

                        return discountCodes.find(function(discountCode) {
                            const rawCode = typeof discountCode === 'string'
                                ? discountCode
                                : (discountCode && discountCode.code ? discountCode.code : '');
                            return normalizeCode(rawCode) === normalizedCode;
                        }) || null;
                    }

                    function updateNodeContent(currentNode, nextNode) {
                        if(!currentNode || !nextNode) return;
                        currentNode.innerHTML = nextNode.innerHTML;
                    }

                    function updateInformations(parsedDocument) {
                        const currentWrappers = document.querySelectorAll('.ecom-cart__informations');
                        const nextWrappers = parsedDocument.querySelectorAll('.ecom-cart__informations');

                        if(!currentWrappers.length || !nextWrappers.length) {
                            return;
                        }

                        currentWrappers.forEach(function(currentWrapper, index) {
                            const nextWrapper = nextWrappers[index] || nextWrappers[0];
                            if(!nextWrapper) {
                                return;
                            }
                            currentWrapper.innerHTML = nextWrapper.innerHTML;
                        });
                    }

                    function updateProductPrices(parsedDocument) {
                        const currentProductContainers = document.querySelectorAll('.ecom-cart__product .ecom-cart__product-container');
                        const nextProductContainers = parsedDocument.querySelectorAll('.ecom-cart__product .ecom-cart__product-container');

                        if(!currentProductContainers.length || !nextProductContainers.length) {
                            return;
                        }

                        currentProductContainers.forEach(function(currentContainer, containerIndex) {
                            const nextContainer = nextProductContainers[containerIndex] || nextProductContainers[0];
                            if(!nextContainer) {
                                return;
                            }

                            const currentItems = currentContainer.querySelectorAll('.ecom-cart__product-item');
                            const nextItems = nextContainer.querySelectorAll('.ecom-cart__product-item');

                            if(!currentItems.length || !nextItems.length) {
                                return;
                            }

                            currentItems.forEach(function(currentItem, itemIndex) {
                                const nextItem = nextItems[itemIndex];
                                if(!nextItem) {
                                    return;
                                }

                                const mappedSelectors = [
                                    '.ecom-cart__product-informations .ecom-cart__product-infos',
                                    '.ecom-cart__product-prices',
                                    '.ecom-cart__product-item__totals'
                                ];

                                mappedSelectors.forEach(function(selector) {
                                    const currentPart = currentItem.querySelector(selector);
                                    const nextPart = nextItem.querySelector(selector);
                                    updateNodeContent(currentPart, nextPart);
                                });
                            });
                        });
                    }

                    function updateCartJsonScript(parsedDocument) {
                        const currentCartJsonNodes = document.querySelectorAll('#ecom-cart-json');
                        const nextCartJsonNodes = parsedDocument.querySelectorAll('#ecom-cart-json');
                        if(!currentCartJsonNodes.length || !nextCartJsonNodes.length) {
                            return;
                        }

                        currentCartJsonNodes.forEach(function(node, index) {
                            const nextNode = nextCartJsonNodes[index] || nextCartJsonNodes[0];
                            if(nextNode) {
                                node.textContent = nextNode.textContent;
                            }
                        });
                    }

                    function updateFreeShippingFromCartJson() {
                        const cartJsonNode = document.querySelector('#ecom-cart-json');
                        const freeShippingTextNodes = document.querySelectorAll('.ecom-free-shipping-bar__container .ecom-free-shipping-bar__text');
                        const freeShippingProgressNodes = document.querySelectorAll('.ecom-free-shipping-bar__container .ecom-free-shipping-bar__progress-bar-stroke');

                        if(!cartJsonNode || !freeShippingTextNodes.length || !cartJsonNode.textContent) {
                            return;
                        }

                        let cartJson = null;
                        try {
                            cartJson = JSON.parse(cartJsonNode.textContent);
                        } catch (e) {
                            return;
                        }

                        const total = Number(cartJson.items_subtotal_price || 0) / 100;

                        freeShippingTextNodes.forEach(function(freeShippingTextNode, index) {
                            const minPrice = Number(freeShippingTextNode.dataset.minPrice || 0);
                            if(!minPrice) {
                                return;
                            }

                            const freeShippingProgressNode = freeShippingProgressNodes[index] || null;
                            let result = minPrice - total;
                            const content = unescape(freeShippingTextNode.dataset.content || '');
                            const successContent = freeShippingTextNode.dataset.successContent || '';

                            if(freeShippingProgressNode) {
                                let percent = total / minPrice * 100;
                                if(percent > 100) percent = 100;
                                if(percent < 0) percent = 0;
                                freeShippingProgressNode.style.width = percent + '%';
                            }

                            if(result > 0) {
                                const formatted = window.EComposer && typeof window.EComposer.formatMoney === 'function'
                                    ? window.EComposer.formatMoney(result * 100)
                                    : result;
                                freeShippingTextNode.innerHTML = content.replace(/\{price}/g, formatted);
                                return;
                            }

                            freeShippingTextNode.innerHTML = successContent;
                        });
                    }

                    function updateDiscountApplicationsFromCart(cart) {
                        const cartLevel = Array.isArray(cart && cart.cart_level_discount_applications)
                            ? cart.cart_level_discount_applications
                            : [];
                        const allApplications = Array.isArray(cart && cart.discount_applications)
                            ? cart.discount_applications
                            : [];

                        // aggregate from line_level_discount_allocations (line-item discounts)
                        const lineAppMap = {};
                        const items = Array.isArray(cart && cart.items) ? cart.items : [];
                        items.forEach(function(item) {
                            const allocations = Array.isArray(item.line_level_discount_allocations)
                                ? item.line_level_discount_allocations
                                : [];
                            allocations.forEach(function(allocation) {
                                const app = allocation && allocation.discount_application;
                                if (!app) return;
                                const key = app.key || app.title;
                                if (lineAppMap[key]) {
                                    lineAppMap[key].total_allocated_amount += (allocation.amount || 0);
                                } else {
                                    lineAppMap[key] = {
                                        title: app.title || '',
                                        total_allocated_amount: allocation.amount || 0,
                                    };
                                }
                            });
                        });
                        const lineApplications = Object.keys(lineAppMap).map(function(k) { return lineAppMap[k]; });

                        // priority: cart_level > discount_applications > aggregated line items
                        const applications = cartLevel.length > 0
                            ? cartLevel
                            : (allApplications.length > 0 ? allApplications : lineApplications);

                        const discountDls = document.querySelectorAll('.ecom-cart__informations-discount_application');

                        if (!discountDls.length) {
                            return;
                        }

                        discountDls.forEach(function(dl) {
                            if (applications.length === 0) {
                                dl.style.display = 'none';
                                return;
                            }
                            dl.style.display = '';
                            const dd = dl.querySelector('.ecom-cart__information-text');
                            if (!dd) return;

                            dd.innerHTML = applications.map(function(app) {
                                const rawAmount = app.total_allocated_amount || 0;
                                const formatted = window.EComposer && typeof window.EComposer.formatMoney === 'function'
                                    ? window.EComposer.formatMoney(rawAmount)
                                    : rawAmount;
                                const title = app.title || '';
                                return '<span class="ecom-cart__informations-discount_application-value">'
                                    + title + ' &minus;' + formatted
                                    + '</span><br>';
                            }).join('');
                        });
                    }

                    function refreshCartPartials() {
                        const refreshUrl = root + 'cart' + window.location.search;
                        const refreshUrlWithTs = refreshUrl + (refreshUrl.indexOf('?') !== -1 ? '&' : '?') + '_ec_ts=' + Date.now();

                        return fetch(refreshUrlWithTs, {
                            method: 'GET',
                            headers: { 'Accept': 'text/html' },
                            credentials: 'same-origin',
                            cache: 'no-store',
                        })
                        .then(function(response) {
                            if(!response.ok) {
                                throw new Error('Cannot refresh cart information.');
                            }
                            return response.text();
                        })
                        .then(function(htmlText) {
                            const parsedDocument = new DOMParser().parseFromString(htmlText, 'text/html');
                            updateInformations(parsedDocument);
                            updateProductPrices(parsedDocument);
                            updateCartJsonScript(parsedDocument);
                            updateFreeShippingFromCartJson();
                        });
                    }

                    function setLoading(loading) {
                        isApplying = loading;
                        if ($input) $input.disabled = loading;
                        if ($button) $button.disabled = loading;
                        if ($appliedList) {
                            $appliedList.querySelectorAll('.ec-cart__coupon-remove').forEach(function(btn) {
                                btn.disabled = loading;
                            });
                        }
                        if(loading) {
                            showMessage(msgs.loading, 'loading');
                        }
                    }

                    function requestCartUpdate(codes) {
                        const discountCodes = Array.isArray(codes)
                            ? uniqueCodes(codes)
                            : [(codes || '').trim()].filter(Boolean);
                        const discountValue = discountCodes.join(',');
                        const payload = {
                            discount: discountValue,
                        };

                        return fetch(root + 'cart/update.js', {
                            method: 'POST',
                            headers: {
                                Accept: 'application/json',
                                'Content-Type': 'application/json',
                            },
                            credentials: 'same-origin',
                            body: JSON.stringify(payload),
                        }).then(function(response) {
                            return parseJsonSafe(response).then(function(data) {
                                if(!response.ok || data.errors || data.error) {
                                    throw new Error(data.errors || data.error || 'Cannot apply this discount code.');
                                }
                                return data;
                            });
                        });
                    }

                    function requestCart() {
                        return fetch(root + 'cart.js', {
                            method: 'GET',
                            headers: {
                                Accept: 'application/json',
                            },
                            credentials: 'same-origin',
                        }).then(function(response) {
                            return parseJsonSafe(response).then(function(data) {
                                if(!response.ok) {
                                    throw new Error('Cannot validate discount from cart response.');
                                }
                                return data;
                            });
                        });
                    }

                    function isDiscountApplied(cart, code) {
                        const normalizedCode = (code || '').trim().toLowerCase();
                        const discountApplications = Array.isArray(cart && cart.cart_level_discount_applications)
                            ? cart.cart_level_discount_applications
                            : (Array.isArray(cart && cart.discount_applications) ? cart.discount_applications : []);
                        const discountCodes = Array.isArray(cart && cart.discount_codes)
                            ? cart.discount_codes
                            : [];

                        if (!normalizedCode) {
                            return discountApplications.length === 0;
                        }

                        const matchedCode = discountCodes.some(function(discountCode) {
                            const rawCode = typeof discountCode === 'string'
                                ? discountCode
                                : (discountCode && discountCode.code ? discountCode.code : '');
                            const applicable = typeof discountCode === 'object'
                                ? discountCode.applicable !== false
                                : true;
                            return normalizeCode(rawCode) === normalizedCode && applicable;
                        });

                        if (matchedCode) {
                            return true;
                        }

                        return discountApplications.some(function(discount) {
                            const title = (discount && discount.title ? discount.title : '').trim().toLowerCase();
                            return discount && discount.type === 'discount_code' && title === normalizedCode;
                        });
                    }

                    function notify(content, status) {
                        showMessage(content, status);
                    }

                    function applyDiscountCode() {
                        if(isApplying) return;

                        const code = ($input.value || '').trim();
                        if(!code) {
                            showMessage(msgs.empty, 'error');
                            return;
                        }

                        const currentCodes = getCurrentAppliedCodes();
                        const currentNormalizedCodes = currentCodes.map(function(currentCode) {
                            return currentCode.toLowerCase();
                        });

                        if (currentNormalizedCodes.indexOf(code.toLowerCase()) !== -1) {
                            showMessage(msgs.duplicate, 'error');
                            return;
                        }

                        setLoading(true);

                        const nextCodes = currentCodes.concat([code]);

                        requestCartUpdate(nextCodes)
                            .then(function(updatedCart) {
                                return requestCart().then(function(cart) {
                                    return {
                                        updatedCart: updatedCart,
                                        cart: cart,
                                    };
                                });
                            })
                            .then(function(result) {
                                const updatedCart = result.updatedCart;
                                const cart = result.cart;
                                const appliedCodes = getAppliedCodesFromCart(cart);
                                const discountCodeFromUpdate = getDiscountCodeFromResponse(updatedCart, code);
                                const rejectedByUpdateResponse = discountCodeFromUpdate && discountCodeFromUpdate.applicable === false;
                                const acceptedByUpdateResponse = discountCodeFromUpdate && discountCodeFromUpdate.applicable === true;
                                const codeVisibleInAppliedCodes = codesInclude(appliedCodes, code);
                                const shippingDiscount = acceptedByUpdateResponse &&
                                    !codeVisibleInAppliedCodes &&
                                    codesMatch(currentCodes, appliedCodes);
                                const applied = !rejectedByUpdateResponse && (
                                    codeVisibleInAppliedCodes ||
                                    isDiscountApplied(cart, code)
                                );

                                if(shippingDiscount) {
                                    rememberAppliedCodes(appliedCodes.length > 0 ? appliedCodes : currentCodes);
                                    if ($input) $input.value = '';
                                    notify(msgs.shipping, 'error');
                                    return refreshCartPartials()
                                        .then(function() { updateDiscountApplicationsFromCart(cart); })
                                        .catch(function() { updateDiscountApplicationsFromCart(cart); });
                                }

                                if(applied) {
                                    rememberAppliedCodes(appliedCodes);
                                    if ($input) $input.value = '';
                                    notify(msgs.success, 'success');
                                    return refreshCartPartials()
                                        .then(function() { updateDiscountApplicationsFromCart(cart); })
                                        .catch(function() { updateDiscountApplicationsFromCart(cart); });
                                }

                                return requestCartUpdate(currentCodes)
                                    .then(function() {
                                        return requestCart();
                                    })
                                    .then(function(restoredCart) {
                                        const restoredCodes = getAppliedCodesFromCart(restoredCart);
                                        rememberAppliedCodes(restoredCodes.length > 0 ? restoredCodes : currentCodes);
                                        notify(msgs.invalid, 'error');
                                        return refreshCartPartials()
                                            .then(function() { updateDiscountApplicationsFromCart(restoredCart); })
                                            .catch(function() { updateDiscountApplicationsFromCart(restoredCart); });
                                    });
                            })
                            .catch(function(error) {
                                const message = error && error.message
                                    ? error.message
                                    : msgs.error;
                                if(currentCodes.length > 0) {
                                    rememberAppliedCodes(currentCodes);
                                }
                                notify(message, 'error');
                            })
                            .finally(function() {
                                setLoading(false);
                            });
                    }

                    function removeDiscountCode(codeToRemove) {
                        if(isApplying) return;

                        const currentCodes = getCurrentAppliedCodes();

                        const remainingCodes = currentCodes.filter(function(c) {
                            return c.toLowerCase() !== (codeToRemove || '').trim().toLowerCase();
                        });

                        setLoading(true);
                        showMessage(msgs.removing, 'loading');

                        requestCartUpdate(remainingCodes)
                            .then(function() {
                                return requestCart();
                            })
                            .then(function(cart) {
                                const appliedCodes = getAppliedCodesFromCart(cart);
                                const removed = appliedCodes.every(function(appliedCode) {
                                    return appliedCode.toLowerCase() !== (codeToRemove || '').trim().toLowerCase();
                                });

                                if(!removed) {
                                    rememberAppliedCodes(appliedCodes);
                                    notify(msgs.removeFail, 'error');
                                    return refreshCartPartials()
                                        .then(function() { updateDiscountApplicationsFromCart(cart); })
                                        .catch(function() { updateDiscountApplicationsFromCart(cart); });
                                }

                                if (appliedCodes.length === 0) {
                                    rememberAppliedCodes([]);
                                    if ($input) $input.value = '';
                                    notify(msgs.removed, 'success');
                                    return refreshCartPartials()
                                        .then(function() { updateDiscountApplicationsFromCart(cart); })
                                        .catch(function() { updateDiscountApplicationsFromCart(cart); });
                                }

                                rememberAppliedCodes(appliedCodes);
                                notify(msgs.removed, 'success');
                                return refreshCartPartials()
                                    .then(function() { updateDiscountApplicationsFromCart(cart); })
                                    .catch(function() { updateDiscountApplicationsFromCart(cart); });
                            })
                            .catch(function(error) {
                                const message = error && error.message
                                    ? error.message
                                    : msgs.error;
                                notify(message, 'error');
                            })
                            .finally(function() {
                                setLoading(false);
                            });
                    }

                    function syncInitialState() {
                        requestCart()
                            .then(function(cart) {
                                const appliedCodes = getAppliedCodesFromCart(cart);
                                if(appliedCodes.length > 0) {
                                    rememberAppliedCodes(appliedCodes);
                                    return;
                                }
                                rememberAppliedCodes([]);
                                try {
                                    const savedCodes = JSON.parse(getCookie('discount_codes') || '[]');
                                    if (Array.isArray(savedCodes) && savedCodes.length > 0 && $input) {
                                        $input.value = savedCodes[0];
                                    }
                                } catch (e) {
                                    const legacyCode = getCookie('discount_code');
                                    if (legacyCode && $input) $input.value = legacyCode;
                                }
                            })
                            .catch(function() {
                                rememberAppliedCodes([]);
                            });
                    }

                    syncInitialState();

                    if($button) {
                        $button.addEventListener('click', function(event) {
                            event.preventDefault();
                            applyDiscountCode();
                        });
                    }

                    if($appliedList) {
                        $appliedList.addEventListener('click', function(event) {
                            const removeBtn = event.target.closest('.ec-cart__coupon-remove');
                            if (!removeBtn) return;
                            event.preventDefault();
                            const codeToRemove = removeBtn.dataset.code;
                            if (codeToRemove) removeDiscountCode(codeToRemove);
                        });
                    }

                    $input.addEventListener('keydown', function(event){
                        if(event.key === 'Enter') {
                            event.preventDefault();
                            applyDiscountCode();
                        }
                    });

                };
            },
