// store/modules/library/cache.ts
//
// Tầng cache ngoài Vuex: in-memory Map + localStorage.
// Vuex chỉ giữ activeKeys (string) + cacheVersion (number) để drive reactivity.
// Data thật nằm ở đây, không nằm trong state.cache.lists.

import type { LibraryContextState } from './types';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CacheEntry {
    data: any;
    timestamp: number;
}

export interface CacheGetResult {
    data: any;
    /** true nếu vẫn dùng được nhưng đã quá TTL → cần revalidate ngầm */
    stale: boolean;
}

// ── Config ────────────────────────────────────────────────────────────────────

const STORAGE_PREFIX = 'ecom_lib_v2_';

/** Thời gian tươi (ms). Hết TTL → stale nhưng vẫn dùng được (serve stale). */
const TTL: Record<string, number> = {
    sections     : 60 * 60 * 1000,   // 60 phút
    all_pages    : 60 * 60 * 1000,
    my_templates : 60 * 60 * 1000,
    my_favorites : 60 * 60 * 1000,
    pages        : 60 * 60 * 1000,
    default      : 60 * 60 * 1000,
};

/** Giữ tối đa N entry trong localStorage trước khi xóa cũ nhất. */
const MAX_LS_ENTRIES = 30;

// ── In-memory store ───────────────────────────────────────────────────────────

/** Tồn tại trong tab, không serialize. Nhanh hơn localStorage nhiều lần. */
const mem = new Map<string, CacheEntry>();

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Lấy tên tab từ full cache key (format: ecom_lib_v2_{tab}_{source}_{hash}). */
function tabFromKey(key: string): string {
    const withoutPrefix = key.slice(STORAGE_PREFIX.length);
    return withoutPrefix.split('_')[0] ?? 'default';
}

function getTTL(tab: string): number {
    return TTL[tab] ?? TTL.default;
}

/** DJB2 hash đơn giản, không cần crypto. */
function djb2(str: string): string {
    let h = 5381;
    for (let i = 0; i < str.length; i++) {
        h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
    }
    return h.toString(36);
}

// ── Key generation ────────────────────────────────────────────────────────────

/**
 * Tạo cache key xác định duy nhất theo context.
 * KHÔNG đưa page number vào key: cache lưu accumulated list.
 * Key chỉ thay đổi khi tab / source / category / sort / search / filter thay đổi.
 */
export function generateCacheKey(context: LibraryContextState): string {
    const q = context.query;
    const raw = [
        context.tab,
        context.sourceId,
        q.categoryId ?? '',
        q.sort ?? 'created_at',
        q.search ?? '',
        q.filter ?? '',
        q.priceTier ?? '',
        Array.isArray(q.tags) ? q.tags.join(',') : (q.tags ?? ''),
        q.detailKey ?? '',
    ].join('|');

    const hash = djb2(raw);
    return `${STORAGE_PREFIX}${context.tab}_${context.sourceId}_${hash}`;
}

// ── CacheService ──────────────────────────────────────────────────────────────

export const LibraryCacheService = {

    /**
     * Đọc entry từ memory rồi localStorage.
     * Trả về null nếu không có gì.
     * Trả về { data, stale: true } nếu tìm thấy nhưng đã quá TTL.
     */
    get(key: string): CacheGetResult | null {
        // 1. Memory (fastest — same session)
        const m = mem.get(key);
        if (m) {
            const stale = Date.now() - m.timestamp > getTTL(tabFromKey(key));
            return { data: m.data, stale };
        }

        // 2. localStorage (persistence across refresh)
        try {
            const raw = localStorage.getItem(key);
            if (!raw) return null;
            const entry: CacheEntry = JSON.parse(raw);
            mem.set(key, entry); // warm up memory
            const stale = Date.now() - entry.timestamp > getTTL(tabFromKey(key));
            return { data: entry.data, stale };
        } catch {
            return null;
        }
    },

    /** Ghi vào cả memory lẫn localStorage. */
    set(key: string, data: any): void {
        const entry: CacheEntry = { data, timestamp: Date.now() };
        mem.set(key, entry);
        try {
            localStorage.setItem(key, JSON.stringify(entry));
            this._cleanup();
        } catch {
            // localStorage đầy → chỉ giữ trong memory
            try { localStorage.removeItem(key); } catch { /* ignore */ }
        }
    },

    /** Xóa một key cụ thể. */
    invalidate(key: string): void {
        mem.delete(key);
        try { localStorage.removeItem(key); } catch { /* ignore */ }
    },

    /**
     * Xóa toàn bộ key thuộc một tab.
     * Dùng khi user thay đổi dữ liệu (e.g. xóa template, save new).
     */
    invalidateTab(tab: string): void {
        for (const k of mem.keys()) {
            if (tabFromKey(k) === tab) mem.delete(k);
        }
        try {
            Object.keys(localStorage)
                .filter(k => k.startsWith(STORAGE_PREFIX) && tabFromKey(k) === tab)
                .forEach(k => localStorage.removeItem(k));
        } catch { /* ignore */ }
    },

    /** Xóa toàn bộ cache (dùng khi logout hoặc clear). */
    clear(): void {
        mem.clear();
        try {
            Object.keys(localStorage)
                .filter(k => k.startsWith(STORAGE_PREFIX))
                .forEach(k => localStorage.removeItem(k));
        } catch { /* ignore */ }
    },

    /**
     * LRU eviction: giữ MAX_LS_ENTRIES mới nhất trong localStorage.
     * Memory cache không giới hạn (tab reload sẽ tự dọn).
     */
    _cleanup(): void {
        try {
            const keys = Object.keys(localStorage).filter(k => k.startsWith(STORAGE_PREFIX));
            if (keys.length <= MAX_LS_ENTRIES) return;
            const sorted = keys
                .map(k => {
                    try {
                        const t = (JSON.parse(localStorage.getItem(k)!) as CacheEntry).timestamp;
                        return { k, t };
                    } catch {
                        return { k, t: 0 };
                    }
                })
                .sort((a, b) => a.t - b.t); // oldest first
            sorted.slice(0, keys.length - MAX_LS_ENTRIES).forEach(({ k }) => localStorage.removeItem(k));
        } catch { /* ignore */ }
    },
};
