<template>
    <div class="ecom-qtb-color flex justify-end" :class="id">
        <!-- Swatch button: nhỏ gọn, hình tròn -->
        <button
            type="button"
            class="ecom-qtb-color__swatch"
            :style="swatchStyle"
            @click.stop="toggle"
            ref="swatchBtn"
        />

        <!-- Popup thả xuống dưới — anchor vào toolbar, không teleport ra body -->
        <Teleport to="body" v-if="isopen">
            <BackDrop @click="close" class="outside-close-cursor" />
            <transition
                enter-active-class="transition duration-150 ease-out"
                enter-from-class="transform scale-90 opacity-0"
                enter-to-class="transform scale-100 opacity-100"
                leave-active-class="transition duration-150 ease-in"
                leave-from-class="transform scale-100 opacity-100"
                leave-to-class="transform scale-90 opacity-0"
            >
                <div
                    class="z-[62] fixed ecom-fields__popup ecom-qtb-color__popup"
                    :id="idTeleport"
                    :style="popupStyle"
                >
                    <!-- Dùng lại chính xác ColorComponent như Color.vue bình thường -->
                    <ColorComponent
                        :global-selected="dGlobal.selected"
                        :global="global"
                        :value="value"
                        :field="field"
                        :showColorPopupAtBottom="true"
                        :idTeleport="idTeleport"
                        @refeshColor="onRefresh"
                        @selectedTab="recalcPosition"
                        @update:value="value = $event"
                        @update:global-selected="dGlobal.selected = $event"
                    />
                </div>
            </transition>
        </Teleport>
    </div>
</template>

<script lang="ts">
import { Popmenu } from '@/mixins';
import ColorComponent from '../../components/molecules/ColorPicker/ColorPanel.vue';

interface PopupPosition {
    top: string;
    left: string;
    bottom: string;
}

export default {
    name: 'ColorQuickTool',
    components: { ColorComponent },
    mixins: [Popmenu],
    props: {
        field: {
            type: Object,
            default: () => ({})
        },
        data: [Object, String],
    },
    emits: ['update:data'],
    data() {
        return {
            value: this.data ?? (this.field as any).value ?? '',
            isWatch: false,
            dGlobal: { selected: '' },
            idTeleport: 'qtb-color-' + Date.now() + Math.random().toString(36).substr(2, 9),
            popupStyle: { top: '0px', left: '0px', bottom: 'auto' } as PopupPosition,
            popupDimensions: { width: 270, height: 468 },
            mutationObserver: null as MutationObserver | null,
            popupElement: null as HTMLElement | null,
        };
    },
    computed: {
        isPopupOpen() {
            return this.$store.getters['builder/isPopupOpen'];
        },
        swatchStyle() {
            const empty = `linear-gradient(to top left,
                rgba(0,0,0,0) 0%,
                rgba(0,0,0,0) calc(50% - 0.8px),
                red 50%,
                rgba(0,0,0,0) calc(50% + 0.8px),
                rgba(0,0,0,0) 100%)`;
            return { background: this.value || empty };
        },
        global() {
            return (this.field as any)?.options?.global;
        }
    },
    watch: {
        'dGlobal.selected'(val: string) {
            if (val && this.global) {
                this.$emit('update:data', { ['global-' + this.global.type]: val });
            }
        },
        data: {
            immediate: true,
            handler(val: any) {
                if (this.isWatch) {
                    this.isEmit = false;
                    this.value = val;
                    this.dGlobal.selected = this.global?.value ?? '';
                }
                this.isWatch = true;
            }
        },
        value: {
            immediate: true,
            handler(val: any) {
                if (this.isEmit) {
                    this.isWatch = false;
                    this.$emit('update:data', val);
                }
                this.isEmit = true;
            }
        },
        isopen(val: boolean) {
            if (val) {
                this.$store.commit('builder/setIsPopupOpen', true);
                this.startObserving();
                window.addEventListener('click', this.onClickOutside);
            } else {
                this.stopObserving();
                window.removeEventListener('click', this.onClickOutside);
            }
        },
        isPopupOpen(val: boolean) {
            if (val === false) this.isopen = false;
        }
    },
    methods: {
        toggle(event: MouseEvent) {
            event.stopPropagation();
            if (this.isopen) {
                this.close();
            } else {
                this.isopen = true;
                this.$nextTick(() => this.calcPosition());
            }
        },
        close() {
            this.isopen = false;
        },
        onRefresh() {
            this.value = '';
            this.dGlobal.selected = null;
        },
        onClickOutside(e: MouseEvent) {
            const target = e.target as HTMLElement;
            if (
                !target.closest(`.${this.id}`) &&
                !target.closest(`#${this.idTeleport}`)
            ) {
                this.close();
            }
        },
        recalcPosition() {
            this.$nextTick(() => this.calcPosition());
        },
        calcPosition() {
            const btn = this.$refs.swatchBtn as HTMLElement;
            if (!btn) return;

            const rect = btn.getBoundingClientRect();
            const popupWidth = this.popupDimensions.width;  // 270
            const popupHeight = this.popupDimensions.height; // 468

            // Tính left: ưu tiên căn theo btn, cạnh trái popup ~ở btn
            let left = rect.left;
            if (left + popupWidth > window.innerWidth - 8) {
                left = window.innerWidth - popupWidth - 8;
            }
            if (left < 8) left = 8;

            // Tính top: ưu tiên thả xuống dưới btn; nếu không đủ chỗ thì lên trên
            let top: string, bottom: string;
            const spaceBelow = window.innerHeight - rect.bottom;
            const spaceAbove = rect.top;

            if (spaceBelow >= popupHeight + 8) {
                top = rect.bottom + 8 + 'px';
                bottom = 'auto';
            } else if (spaceAbove >= popupHeight + 8) {
                top = rect.top - popupHeight - 8 + 'px';
                bottom = 'auto';
            } else {
                // Không đủ cả hai chiều → gắn sát đáy viewport
                top = Math.max(8, window.innerHeight - popupHeight - 8) + 'px';
                bottom = 'auto';
            }

            this.popupStyle = { top, left: left + 'px', bottom };
        },
        startObserving() {
            this.stopObserving();
            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if ((node as Element).id === this.idTeleport) {
                                this.popupElement = node as HTMLElement;
                                this.$nextTick(() => {
                                    if (this.popupElement) {
                                        this.popupDimensions = {
                                            width: this.popupElement.offsetWidth || 270,
                                            height: this.popupElement.offsetHeight || 468,
                                        };
                                    }
                                    this.calcPosition();
                                });
                            }
                        });
                    }
                });
            });
            this.mutationObserver.observe(document.body, { childList: true, subtree: true });
        },
        stopObserving() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },
    },
    beforeUnmount() {
        this.stopObserving();
        window.removeEventListener('click', this.onClickOutside);
    }
};
</script>

<style scoped>
/* Swatch button: hình tròn nhỏ gọn, vừa với toolbar icon 32x32 */
