<template>
    <div class="ecom-element ecom-product-single ecom-product-single__wishlist">
        <div class="ecom-product-single__wishlist-wrapper">
            <div
                class="ecom-product-single__wishlist-container"
                :data-wishlist-app="liquid('wishlist_app')"
                :class="!exporting ? 'ecom-placeholder-on-builder-mode': ''"
                :data-ecom-placeholder="exporting? '': 'Please select wishlist app in settings'"
                v-html="liquid('wishlist')"
            />
        </div>
    </div>
</template>

<script>
    import { Liquid, Element, Javascript } from '@/mixins';
    export default {
        name: 'productWishlist',

        mixins: [Liquid, Element, Javascript],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {

            classes () {
                return this.data && this.data.settings && this.data.settings.classes
                    ? this.data.settings.classes
                    : '';
            },

            heading () {
                return this.data && this.data.settings && this.data.settings.tag
                    ? this.data.settings.tag
                    : 'h3';
            },

            liquids () {
                return {
                    wishlist_app: {
                        code: `{%- assign wishlist_app = shop.metafields.ecomposer.app_wishlist.value -%}{{wishlist_app}}`,
                        preview: ''
                    },
                    wishlist: {
                        code: `{%- if wishlist_app -%}
                            {%- assign variant_selected = product.selected_or_first_available_variant -%}
                            {%- if EComBuilderMode == true -%}
                                <div class="ecom-theme-app-extensions-skeleton">
                                    <div class="ecom-app-extension-info">
                                        <span class="ecom-theme-app-extension-icon">
                                            <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\"><path d=\"M255.1 96L267.1 84.02C300.6 51.37 347 36.51 392.6 44.1C461.5 55.58 512 115.2 512 185.1V190.9C512 232.4 494.8 272.1 464.4 300.4L283.7 469.1C276.2 476.1 266.3 480 256 480C245.7 480 235.8 476.1 228.3 469.1L47.59 300.4C17.23 272.1 0 232.4 0 190.9V185.1C0 115.2 50.52 55.58 119.4 44.1C164.1 36.51 211.4 51.37 244 84.02L255.1 96zM255.1 141.3L221.4 106.6C196.1 81.31 160 69.77 124.7 75.66C71.21 84.58 31.1 130.9 31.1 185.1V190.9C31.1 223.6 45.55 254.7 69.42 277L250.1 445.7C251.7 447.2 253.8 448 255.1 448C258.2 448 260.3 447.2 261.9 445.7L442.6 277C466.4 254.7 480 223.6 480 190.9V185.1C480 130.9 440.8 84.58 387.3 75.66C351.1 69.77 315.9 81.31 290.6 106.6L255.1 141.3z\"/></svg>
                                        </span>
                                        <div class="ecom-theme-app-extension-content">
                                        <span class="ecom-theme-app-extension-title">{{wishlist_app | replace: '_', ' ' | replace: '-', ' ' | capitalize}}</span>
                                        <div class="ecom-placeholder-on-builder-mode" data-ecom-placeholder="The wishlist element will display when published to Online store"></div>
                                        </div>
                                    </div>
                                </div>
                            {%- else -%}
                                {%- case wishlist_app -%}
                                    {% when 'growave'%}
                                        <div
                                            class="gw-wl-add-to-wishlist-placeholder"
                                            data-gw-product-id="{{product.id}}"
                                            data-gw-variant-id="{{product.id}}"
                                            style="display: block"
                                        ></div>

                                    {%- when 'swym-relay' -%}
                                        <div class="swym-wishlist-button-bar"></div>
                                        <button class="${!this.exporting ? '' : 'swym-loaded'} swym-button swym-add-to-wishlist-view-product product_{{product.id}}" data-swaction="addToWishlist" data-product-id="{{product.id | json}}" data-variant-id="{{ product.variants[0].id }}" data-product-url="{{ shop.url }}{{ product.url }}"></button>
                                    {%- when 'wishlist-wishify' -%}
                                            <div id="ZlistWishlist" data-product-id="{{product.id}}" data-handle = "{{product.handle}}"
                                            data-image="{{product.featured_image | image_url: width: 360}}"  data-variantname="{{product.selected_or_first_available_variant.title}}" data-title="{{product.title}}" data-variant="{{product.selected_or_first_available_variant.id}}" data-price="{{product.selected_or_first_available_variant.price | remove: "." | remove: "," | divided_by: 100.0 }}"></div>
                                            <${'script'} type="text/ecom-custom-js"  src="https://zooomyapps.com/wishlist/ListWishlistProduct.js" data-product-id="{{product.id}}" data-shop-id="{{shop.permanent_domain}}" data-customer-id="{{customer.id}}" ></${'script'}>
                                    {%- when 'wishlist-hero' -%}
                                        <div id="wishlist-hero-product-page-button"></div>
                                    {%- else -%}
                                {%- endcase -%}
                            {% endif %}
                        {%- endif -%}`,
                        preview: `
                            <div class="ecom-skeleton-item">
                                <div>
                                    <div class="ecom-skeleton-row">
                                        <div class="ecom-skeleton-col-4"></div>
                                        <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                        <div class="ecom-skeleton-col-6"></div>
                                        <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                        <div class="ecom-skeleton-col-2"></div>
                                        <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                                    </div>
                                </div>
                            </div>
                        `
                    }
                };
            },

            settings () {
                return [{
                    params: [
                        {
                            type: 'paragraph',
                            content: this.$t('show_add_to_wishlist_button_you_must_install_the_app_first_and_after_that_select_the_wishlist_app_here_settings_app_settings_apps')
                        }
                    ]
                }];
            },
            javascript () {
                if (this.exporting) {
                    return function () { };
                }
                return function () {
                    let $el = this.$el;
                    let $container = $el.querySelector('.ecom-product-single__wishlist-container');
                    if ($container) {
                        switch ($container.dataset.wishlistApp) {
                            case 'swym-relay':
                                /*
                                if (window._swat) {
                                    window._swat.initializeActionButtons('.swym-add-to-wishlist-view-product');
                                }
                                */
                                break;
                            case 'wishlist-wishify':
                                // eslint-disable-next-line no-var
                                var dom = document.createElement('script');
                                dom.src = 'https://zooomyapps.com/wishlist/ListWishlistProduct.js';
                                window.document.head.appendChild(dom);
                                break;
                            case 'wishlist-hero':
                                var buttonDiv = $el.querySelector('.ecom-product-single-wishlist');
                                var ev = new CustomEvent('wishlist-hero-add-to-custom-element', {
                                    detail: buttonDiv,
                                });
                                document.dispatchEvent(ev);
                                break;
                            default:
                                break;
                        }
                    }

                };
            },
            requestShopifyType () {
                return {
                    shopify_type: 'product'
                };
            },

            css () {
                return ``;
            },
        },
    };
</script>
