import { $t } from "@/plugins/i18n";
import { promoConfig } from "./storage";
import exporting from "@/utils/exporting";
import { worker } from "@/services/api";

// App Blocks sidebar: số app gợi ý (chưa cài) fetch tối đa — giảm dữ liệu giữ trong RAM.
const RECOMMENDED_APPS_LIMIT = 15;
// Khi user search trong App Blocks: KHÔNG giới hạn kết quả (không có nút "load more" trong panel,
// cắt bớt = app đúng từ khóa biến mất). 200 chỉ là trần an toàn, khớp `APPS_BUILDER_MAX_PER_PAGE` ở backend.
const APP_BLOCKS_SEARCH_PER_PAGE = 200;
// Giới hạn số bản ghi `installed.data` lưu cache App Blocks (RAM); `load()` dùng 0 = không slice.
const APP_BLOCKS_INSTALLED_CATALOG_MAX = 200;

/** Chuẩn hoá từng item trong `apps.data` (translates, deep clone). */
function mapAppsDataItems(dataApps: any) {
    if (!dataApps) return { data: [] };
    if (!Array.isArray(dataApps.data)) {
        dataApps.data = [];
        return dataApps;
    }
    dataApps.data = dataApps.data.map((item: any) => {
        const newData = JSON.parse(JSON.stringify(item));
        const translates: Record<string, unknown> = {};
        if (newData.translates) {
            newData.translates.forEach((translate: any) => {
                translates[translate.language] = {
                    title: translate.title,
                    description: translate.description,
                    content: translate.content
                };
            });
            newData.translates = translates;
        }
        return newData;
    });
    return dataApps;
}

function installedIdSet(installed: any[]) {
    return new Set(
        (installed || [])
            .map((id: any) => Number(id))
            .filter((id: number) => Number.isFinite(id) && id > 0)
    );
}

function normalizeAppBlocksNotInstalledPayload(raw: any, maxItems: number) {
    if (raw == null) {
        return null;
    }
    const mapped = mapAppsDataItems(JSON.parse(JSON.stringify(raw)));
    if (maxItems > 0 && mapped?.data?.length > maxItems) {
        mapped.data = mapped.data.slice(0, maxItems);
    }
    return mapped;
}

/** API cũ: `installed` = mảng id. API mới: paginator Laravel `{ data: Post[] }`. */
function installedIdsFromResponse(raw: any): any[] {
    if (raw == null) {
        return [];
    }
    if (Array.isArray(raw)) {
        return raw;
    }
    if (typeof raw === "object" && Array.isArray(raw.data)) {
        return raw.data.map((a: any) => a?.id).filter((id: any) => id != null);
    }
    return [];
}

function isInstalledPaginatorPayload(raw: any): boolean {
    return (
        raw != null &&
        typeof raw === "object" &&
        !Array.isArray(raw) &&
        Array.isArray(raw.data)
    );
}

/** Route/query params cho API `builder.apps` — backend nhận `is_builder` từ builder. */
function buildAppsRouteParams(queries: Record<string, unknown>, payload: Record<string, unknown> = {}) {
    return {
        is_builder: true,
        ...queries,
        ...payload
    };
}

/**
 * `state.installed` = id app đã cài, dùng chung TOÀN builder (element registry, `mergedInstalledApps`,
 * các getter `notInstalled*`). Chỉ được set từ response KHÔNG lọc theo từ khóa — response của một
 * lần search chỉ chứa app đã cài khớp từ khóa, ghi đè vào đây sẽ làm builder tưởng shop gỡ hết app.
 */
function commitInstalledIds(commit: any, raw: any) {
    commit("setInstalled", installedIdsFromResponse(raw));
}

/**
 * `state.appBlocksInstalled` = catalog app đã cài RIÊNG cho panel App Blocks, có thể đã lọc theo
 * từ khóa search. Chỉ 2 action của panel được set; `load()` (catalog đầy đủ của Extensions Hub)
 * không được đụng vào, nếu không mở detail 1 extension sẽ reset kết quả search đang hiển thị.
 */
function commitAppBlocksInstalled(commit: any, raw: any, catalogMaxItems: number) {
    if (!isInstalledPaginatorPayload(raw) || !raw.data.length) {
        commit("setAppBlocksInstalled", null);
        return;
    }
    const mapped = mapAppsDataItems(JSON.parse(JSON.stringify(raw)));
    if (catalogMaxItems > 0 && mapped?.data?.length > catalogMaxItems) {
        mapped.data = mapped.data.slice(0, catalogMaxItems);
    }
    commit("setAppBlocksInstalled", mapped);
}

export default {
    namespaced: true,
    state: {
        library: {
            open: false,
            loading: false,
            detail: null,
            listLoading: true
        },
        loadingPartners: true,
        loadingAll: false,
        queries: {
            page: 1,
            category: null,
            query: null,
            type: "popular",
            tag: null
        },
        apps: null,
        categories: [],
        installed: [],
        toast: {
            open: false,
            type: "success",
            message: ""
        },
        timeout: null,
        optionsPromo: promoConfig,
        /** Catalog nhẹ chỉ cho sidebar App Blocks (~RECOMMENDED_APPS_LIMIT / kết quả search). Không thay `apps` (full library). */
        appBlocksApps: null,
        /**
         * Catalog app chưa cài riêng từ API `not_installed` (paginator giống `apps`).
         * Khi backend không gửi key này, giữ null để getter recommended fallback lọc từ `appBlocksApps`.
         */
        appBlocksNotInstalled: null,
        /** App đã cài (full row) từ `response.installed` dạng paginator; null nếu API chỉ trả mảng id. */
        appBlocksInstalled: null,
        /** Loading riêng cho preview/search App Blocks (không dùng chung `loadingAll` của extensions `load`). */
        appBlocksCatalogLoading: false,
        /** Từ khóa search App Blocks đang active — giữ khi refresh catalog sau install. */
        appBlocksSearchQuery: "",
        /**
         * Từ khóa đã fetch THÀNH CÔNG lần gần nhất (khác `appBlocksSearchQuery` vì query có thể
         * được set ngay khi user gõ, trước khi debounce fetch chạy xong). Dùng để check cache,
         * tránh so sánh nhầm với query chưa kịp fetch.
         */
        appBlocksLoadedQuery: null,
        /** Increment để bảo ListElements mở panel App Blocks (hash `#search_extensions`, …). */
        appBlocksPanelRequest: 0,
        /**
         * Từ khóa đang có request bay — dedupe khi cùng một từ khóa được dispatch nhiều lần
         * (deep-link + watcher, hoặc nhiều instance ListElements) thay vì bắn request trùng.
         */
        appBlocksInflightQuery: null as string | null
    },
    getters: {
        open(state) {
            return state.library.open;
        },
        categories(state) {
            return state.categories;
        },
        apps(state) {
            return state.apps;
        },
        queries(state) {
            return state.queries;
        },
        installed(state) {
            return state.installed;
        },
        appBlocksApps(state) {
            return state.appBlocksApps;
        },
        appBlocksCatalogLoading(state) {
            return state.appBlocksCatalogLoading;
        },
        appBlocksSearchQuery(state) {
            return state.appBlocksSearchQuery;
        },
        appBlocksLoadedQuery(state) {
            return state.appBlocksLoadedQuery;
        },
        /**
         * Id các app backend đã match cho `appBlocksLoadedQuery` (union apps / installed / not_installed).
         * Backend search cả `tags` (vd. tag "cross sell" trên "Frequently Bought Together") nên UI
         * KHÔNG được filter lại theo title — dùng set này để giữ đúng kết quả server trả về.
         */
        appBlocksSearchMatchedIds(state) {
            const ids = new Set<number>();
            if (!state.appBlocksLoadedQuery) {
                return ids;
            }
            [
                state.appBlocksApps?.data,
                state.appBlocksInstalled?.data,
                state.appBlocksNotInstalled?.data
            ].forEach((pool: any) => {
                (pool || []).forEach((app: any) => {
                    const id = Number(app?.id);
                    if (Number.isFinite(id) && id > 0) ids.add(id);
                });
            });
            return ids;
        },
        appBlocksPanelRequest(state) {
            return state.appBlocksPanelRequest;
        },
        appBlocksNotInstalled(state) {
            return state.appBlocksNotInstalled;
        },
        /** Danh sách app đã cài (đủ field) cho App Blocks: ưu tiên `installed.data`, fallback giao `appBlocksApps` ∩ id. */
        installedAppsForAppBlocks(state) {
            if (
                state.appBlocksInstalled != null &&
                Array.isArray(state.appBlocksInstalled.data) &&
                state.appBlocksInstalled.data.length
            ) {
                return state.appBlocksInstalled.data;
            }
            const allApps = state.appBlocksApps?.data ?? state.apps?.data ?? [];
            const installedIds = installedIdSet(state.installed);
            return allApps.filter((app: any) => installedIds.has(Number(app?.id)));
        },
        /** Full library: apps chưa cài (màn Extension / code cũ). */
        notInstalledApps(state) {
            const allApps = state.apps?.data || [];
            const installedIds = installedIdSet(state.installed);
            return allApps.filter((app: any) => !installedIds.has(Number(app?.id)));
        },
        /**
         * App Blocks sidebar: ưu tiên `appBlocksNotInstalled` từ API `not_installed`,
         * fallback lọc từ `appBlocksApps` / `apps` (API cũ không tách not_installed).
         */
        notInstalledAppsForAppBlocks(state) {
            const installedIds = installedIdSet(state.installed);
            if (
                state.appBlocksNotInstalled != null &&
                Array.isArray(state.appBlocksNotInstalled.data)
            ) {
                return state.appBlocksNotInstalled.data.filter(
                    (app: any) => !installedIds.has(Number(app?.id))
                );
            }
            const allApps = state.appBlocksApps?.data ?? state.apps?.data ?? [];
            return allApps.filter((app: any) => !installedIds.has(Number(app?.id)));
        },
        library(state) {
            return state.library;
        },
        detail(state) {
            return state.library.detail;
        },
        loading(state) {
            return state.library?.loading;
        },
        loadingPartners(state) {
            return state.loadingPartners;
        },
        loadingAll(state) {
            return state.loadingAll;
        },
        listLoading(state) {
            return state.library.listLoading;
        },
        toast(state) {
            return state.toast;
        },
        partners(state) {
            return state.partners;
        },
        optionsPromo(state) {
            return state.optionsPromo;
        }
    },
    mutations: {
        setApps(state, payload) {
            state.apps = payload;
        },
        setAppBlocksApps(state, payload) {
            state.appBlocksApps = payload;
        },
        setAppBlocksNotInstalled(state, payload) {
            state.appBlocksNotInstalled = payload;
        },
        setAppBlocksInstalled(state, payload) {
            state.appBlocksInstalled = payload;
        },
        setAppBlocksCatalogLoading(state, payload) {
            state.appBlocksCatalogLoading = !!payload;
        },
        setAppBlocksSearchQuery(state, payload) {
            state.appBlocksSearchQuery = (payload || "").trim();
        },
        setAppBlocksInflightQuery(state, payload) {
            state.appBlocksInflightQuery = payload;
        },
        setAppBlocksLoadedQuery(state, payload) {
            state.appBlocksLoadedQuery = payload == null ? null : (payload || "").trim();
        },
        /** Yêu cầu mở panel App Blocks (ListElements watch token này). */
        requestOpenAppBlocksPanel(state, payload) {
            state.appBlocksSearchQuery = (payload?.query ?? payload ?? "").toString().trim();
            state.appBlocksPanelRequest = (state.appBlocksPanelRequest || 0) + 1;
        },
        setCategories(state, payload) {
            state.categories = payload;
        },
        setInstalled(state, payload) {
            state.installed = payload;
        },
        setLoading(state, payload) {
            state.library.loading = payload;
        },
        setLoadingPartners(state, payload) {
            state.loadingPartners = payload;
        },
        setLoadingAll(state, payload) {
            state.loadingAll = payload;
        },
        setListLoading(state, payload) {
            state.library.listLoading = payload;
        },
        setDetail(state, payload) {
            state.library.detail = payload;
        },
        setQueryType(state, payload) {
            state.queries.type = payload;
        },
        setQueryPage(state, payload) {
            state.queries.page = payload;
        },
        setQueryQuery(state, payload) {
            state.queries.query = payload;
        },
        setQueryTag(state, payload) {
            state.queries.tag = payload;
        },
        setQueryCategory(state, payload) {
            state.queries.category = payload;
        },
        setPartners(state, payload) {
            state.partners = payload;
        },
        setOptionsPromo(state, payload) {
            state.optionsPromo = payload;
        }
    },

    actions: {
        open({ state, dispatch }) {
            state.library.open = true;
            if (state.apps === null) {
                state.library.loading = true;
                dispatch("load");
                if (!window.location.hash.includes("extensions")) {
                    window.location.hash = "extensions";
                }
            }
        },
        updatePromo({ commit, state }) {
            try {
                commit("setOptionsPromo", state.optionsPromo);
                localStorage.setItem("optionsPromo", JSON.stringify(state.optionsPromo));
            } catch (e) {
            }
        },
        loadPartners({ state, dispatch, commit }) {
            this.$worker
                .fetch(window.route("builder.apps", buildAppsRouteParams(state.queries)))
                .then((response) => {
                    commit("setLoadingPartners", false);
                    const partners = (response.data.partners && response.data.partners.extensions) || null;
                    console.log('partners', partners);
                    commit('setPartners', partners);
                })
                .catch((e) => {
                    commit("setLoadingPartners", false);
                });
        },
        load({ state, dispatch, commit }) {
            commit("setLoadingAll", true);
            const optionsPromo = state.optionsPromo;
            return this.$worker
                .fetch(window.route("builder.apps", buildAppsRouteParams(state.queries)))
                .then((response) => {
                    commit("setLoadingAll", false);
                    if (response.data.status === "success") {
                        let my_cat = [
                            {
                                title: "All categories",
                                id: ""
                            },
                            ...(response.data.categories || [])
                        ];
                        const rawApps = response.data.apps;
                        const dataApps = mapAppsDataItems(
                            rawApps != null
                                ? JSON.parse(JSON.stringify(rawApps))
                                : { data: [] }
                        );
                        if (
                            optionsPromo &&
                            optionsPromo[state.queries.type + "_extension"] &&
                            !state.queries.query
                        ) {
                            const value = optionsPromo[state.queries.type + "_extension"];
                        }
                        commit("setCategories", my_cat);
                        commit("setApps", dataApps);
                        // KHÔNG đụng `appBlocksInstalled`: `load()` chạy cả khi mở detail 1 extension
                        // (hashchange `#extensions/<id>`), ghi đè sẽ reset kết quả search của panel.
                        // `queries.query` = search của Extensions Hub → response cũng bị lọc, không dùng.
                        if (
                            Object.prototype.hasOwnProperty.call(response.data, "installed") &&
                            !state.queries.query
                        ) {
                            commitInstalledIds(commit, response.data.installed);
                        }
                    } else
                        throw new Error(
                            response.data.message ? response.data.message : $t("unknown_error")
                        );
                })
                .catch((e) => {
                    commit("setLoadingAll", false);
                    dispatch('global/setToast', {
                        isError: true,
                        message: e.message,
                        data: e,
                        duration: 4000
                    },{ root: true });
                    return false;
                });
        },

        /**
         * Fetch nhẹ cho App Blocks: ~RECOMMENDED_APPS_LIMIT app (gửi `per_page` nếu backend hỗ trợ; luôn slice phía client để giới hạn RAM).
         */
        reloadAppBlocksCatalog({ state, dispatch }) {
            const q = (state.appBlocksSearchQuery || "").trim();
            if (q) {
                return dispatch("loadAppBlocksSearch", { query: q, force: true });
            }
            return dispatch("loadAppBlocksPreview", { force: true });
        },

        loadAppBlocksPreview({ state, dispatch, commit }, payload) {
            const force = payload?.force === true;
            commit("setAppBlocksSearchQuery", "");
            // Đã có cache cho preview (không search) → không fetch lại mỗi lần mở panel.
            if (!force && state.appBlocksApps !== null && state.appBlocksLoadedQuery === "") {
                return Promise.resolve();
            }
            if (state.appBlocksInflightQuery === "") {
                return Promise.resolve();
            }
            commit("setAppBlocksInflightQuery", "");
            commit("setLoadingAll", true);
            commit("setAppBlocksCatalogLoading", true);
            const params = buildAppsRouteParams(state.queries, {
                page: 1,
                query: null,
                per_page: RECOMMENDED_APPS_LIMIT
            });
            this.$worker
                .fetch(window.route("builder.apps", params))
                .then((response) => {
                    commit("setAppBlocksInflightQuery", null);
                    commit("setLoadingAll", false);
                    commit("setAppBlocksCatalogLoading", false);
                    if (response.data.status !== "success") {
                        throw new Error(
                            response.data.message ? response.data.message : $t("unknown_error")
                        );
                    }
                    const rawApps = response.data.apps;
                    const dataApps = mapAppsDataItems(
                        rawApps != null
                            ? JSON.parse(JSON.stringify(rawApps))
                            : { data: [] }
                    );
                    if (dataApps?.data?.length) {
                        dataApps.data = dataApps.data.slice(0, RECOMMENDED_APPS_LIMIT);
                    }
                    commit("setAppBlocksApps", dataApps);
                    commit("setAppBlocksLoadedQuery", "");
                    commit(
                        "setAppBlocksNotInstalled",
                        normalizeAppBlocksNotInstalledPayload(
                            response.data.not_installed,
                            RECOMMENDED_APPS_LIMIT
                        )
                    );
                    if (Object.prototype.hasOwnProperty.call(response.data, "installed")) {
                        // Preview không có từ khóa → response `installed` là đầy đủ, set được cả 2.
                        commitInstalledIds(commit, response.data.installed);
                        commitAppBlocksInstalled(
                            commit,
                            response.data.installed,
                            APP_BLOCKS_INSTALLED_CATALOG_MAX
                        );
                    }
                })
                .catch((e) => {
                    commit("setAppBlocksInflightQuery", null);
                    commit("setLoadingAll", false);
                    commit("setAppBlocksCatalogLoading", false);
                    dispatch(
                        "global/setToast",
                        {
                            isError: true,
                            message: e.message,
                            data: e,
                            duration: 4000
                        },
                        { root: true }
                    );
                });
        },

        /**
         * Search App Blocks: fetch theo từ khóa, giới hạn số bản ghi (per_page + slice client).
         */
        loadAppBlocksSearch({ state, dispatch, commit }, payload) {
            const q = (payload?.query || "").trim();
            const force = payload?.force === true;
            if (!q) {
                return dispatch("loadAppBlocksPreview", { force });
            }
            commit("setAppBlocksSearchQuery", q);
            // Đã có cache cho đúng từ khoá search này → không fetch lại.
            if (!force && state.appBlocksApps !== null && state.appBlocksLoadedQuery === q) {
                return Promise.resolve();
            }
            // Cùng từ khóa đã có request đang bay → bỏ qua.
            if (state.appBlocksInflightQuery === q) {
                return Promise.resolve();
            }
            commit("setAppBlocksInflightQuery", q);
            commit("setLoadingAll", true);
            commit("setAppBlocksCatalogLoading", true);
            const params = buildAppsRouteParams(state.queries, {
                ...(payload && typeof payload === "object" ? payload : {}),
                page: 1,
                query: q,
                per_page: APP_BLOCKS_SEARCH_PER_PAGE
            });
            this.$worker
                .fetch(window.route("builder.apps", params))
                .then((response) => {
                    // Chỉ xoá cờ nếu nó vẫn là của request này — response của từ khóa cũ về sau
                    // sẽ xoá nhầm cờ đang thuộc về request mới, làm request mới bị bắn lại lần 2.
                    if (state.appBlocksInflightQuery === q) {
                        commit("setAppBlocksInflightQuery", null);
                    }
                    // Response về trễ (user đã gõ tiếp): bỏ qua, đừng ghi đè dữ liệu đang hiển thị
                    // bằng kết quả của từ khóa cũ. Request cho từ khóa mới đang bay/đã có cache.
                    if (q !== state.appBlocksSearchQuery) {
                        return;
                    }
                    commit("setLoadingAll", false);
                    commit("setAppBlocksCatalogLoading", false);
                    if (response.data.status !== "success") {
                        throw new Error(
                            response.data.message ? response.data.message : $t("unknown_error")
                        );
                    }
                    const rawApps = response.data.apps;
                    const dataApps = mapAppsDataItems(
                        rawApps != null
                            ? JSON.parse(JSON.stringify(rawApps))
                            : { data: [] }
                    );
                    if (dataApps?.data?.length) {
                        dataApps.data = dataApps.data.slice(0, APP_BLOCKS_SEARCH_PER_PAGE);
                    }
                    commit("setAppBlocksApps", dataApps);
                    commit("setAppBlocksLoadedQuery", q);
                    commit(
                        "setAppBlocksNotInstalled",
                        normalizeAppBlocksNotInstalledPayload(
                            response.data.not_installed,
                            APP_BLOCKS_SEARCH_PER_PAGE
                        )
                    );
                    if (Object.prototype.hasOwnProperty.call(response.data, "installed")) {
                        // Response đã lọc theo từ khóa → chỉ set catalog của panel, không đụng
                        // `state.installed` (xem doc `commitInstalledIds`).
                        commitAppBlocksInstalled(
                            commit,
                            response.data.installed,
                            APP_BLOCKS_INSTALLED_CATALOG_MAX
                        );
                    }
                })
                .catch((e) => {
                    if (state.appBlocksInflightQuery === q) {
                        commit("setAppBlocksInflightQuery", null);
                    }
                    commit("setLoadingAll", false);
                    commit("setAppBlocksCatalogLoading", false);
                    dispatch(
                        "global/setToast",
                        {
                            isError: true,
                            message: e.message,
                            data: e,
                            duration: 4000
                        },
                        { root: true }
                    );
                });
        },

        close({ state }) {
            state.library.open = false;
            if (window.location.hash.includes("extensions")) {
                window.location.hash = "";
            }
        },

        setToast({ state }, payload) {
            let message = payload.data?.message || payload.message;
            let dataTranslate = payload.data?.translate_data || payload.translate_data || {};
            if (message) {
                let translateKey = message.startsWith("$t|")
                    ? message.replace("$t|", "").trim()
                    : message;
                payload.message = $t(translateKey, dataTranslate);
            }
            state.toast = payload;
            clearTimeout(state.timeout);
            state.timeout = setTimeout(() => {
                state.toast = {
                    open: false
                };
            }, 6000);
        },

        uninstall({ commit, dispatch, state }, payload) {
            dispatch("setLoading", { id: payload.id, status: true });
            this.$worker
                .fetch(window.route("builder.apps.uninstall", { id: payload.id }), null, "DELETE")
                .then((response) => {
                    commit("setLoading", false);
                    if (response.data.status === "success") {
                        // commit(
                        //     "builder/setPopup",
                        //     {
                        //         show: true,
                        //         type: "success",
                        //         loading: false,
                        //         title: $t("complete"),
                        //         message: $t("your_extension_has_been_uninstalled_successfully"),
                        //         closeable: true
                        //     },
                        //     { root: true }
                        // );
                        dispatch("load").then(() => dispatch("reloadAppBlocksCatalog"));
                        dispatch("page/uninstallEcoSystemApp", response.data.extension, {
                            root: true
                        });
                        if (typeof payload.callback == "function") {
                            payload.callback();
                        }
                    } else {
                        throw new Error(
                            response.data.message ? response.data.message : $t("unknown_message")
                        );
                    }
                })
                .catch((e) => {
                    commit("setLoading", false);
                    commit(
                        "builder/setPopup",
                        {
                            show: true,
                            type: "error",
                            loading: false,
                            title: $t("notice"),
                            message: e.message,
                            closeable: true,
                            data: e
                        },
                        { root: true }
                    );
                    if (state.apps?.data) {
                        state.apps.data.forEach((app) => {
                            if (app.id === payload.id) {
                                app.loading = false;
                            }
                        });
                    }
                });
        },

        install({ commit, dispatch, state }, payload) {
            let app = state.apps?.data?.find((app) => app.id === payload.id);
            if (!app) app = state.library.detail;
            if (app) {
                if (app?.options?.schema?.handle_install === true) {
                    let key = "EComCallback" + new Date().getTime();

                    window[key] = (payload, params) => {
                        if (payload === "accept") {
                            installApp(this);
                        }
                    };
                    // ?utm_source=ecomposer&utm_medium=extension&ref=ecomposer
                    commit(
                        "builder/setPopup",
                        {
                            type: "warning",
                            title: $t("oops"),
                            show: true,
                            message: $t(
                                "please_make_sure_you_installed_b_title_b_app_before_using_this_extension",
                                { title: app?.options?.schema?.name || app.title }
                            ),
                            callback: key,
                            action: {
                                title: $t("yes_app_installed")
                            },
                            second_action: {
                                title: $t("not_yet_add_app_now"),
                                link: app?.options?.schema?.link || "https://apps.shopify.com/"
                            },
                            closeable: true
                        },
                        { root: true }
                    );
                } else {
                    installApp(this);
                }
            }

            function installApp(_this) {
                dispatch("setLoading", { id: payload.id, status: true });
                _this.$worker
                    .fetch(window.route("builder.apps.install", { id: payload.id }), null, "POST")
                    .then((response) => {
                        commit("setLoading", false);
                        dispatch("setLoadingDetail", { id: payload.id, status: false });
                        dispatch("detail", {
                            id: payload.id,
                            tab: response.data.extension?.options?.schema?.settings
                                ? "settings"
                                : "details"
                        });
                        if (response.data.status === "success") {
                            const extension = response.data.extension;
                            if (extension) {
                                dispatch("page/syncEcoSystemAppOnInstall", extension, { root: true });
                            }
                            dispatch("load").then(() => dispatch("reloadAppBlocksCatalog"));

                            if (
                                !response.data?.options?.schema?.component &&
                                !response.data?.extension?.options?.schema?.hide_component
                            ) {
                                let key = "EComCallback" + new Date().getTime();

                                window[key] = (payload, params) => {
                                    if (payload === "accept") {
                                        commit(
                                            "builder/setPopup",
                                            {
                                                show: true,
                                                loading: true,
                                                closeable: false,
                                                message: $t("saving_please_wait")
                                            },
                                            { root: true }
                                        );

                                        setTimeout(() => {
                                            exporting().then((res) => {
                                                dispatch(
                                                    "page/save",
                                                    { data: res, action: "save", reload: true },
                                                    { root: true }
                                                );
                                            });
                                        }, 500);
                                    }
                                };

                                commit(
                                    "builder/setPopup",
                                    {
                                        type: "warning",
                                        title: $t("congratulations"),
                                        show: true,
                                        loading: false,
                                        loading_btn: true,
                                        message: $t("save_and_reload_text"),
                                        callback: key,
                                        action: {
                                            title: $t("save_and_reload")
                                        },
                                        closeable: true
                                    },
                                    { root: true }
                                );
                            } else {
                                commit(
                                    "builder/setPopup",
                                    {
                                        show: true,
                                        type: "success",
                                        loading: false,
                                        title: $t("congratulations"),
                                        message: $t(
                                            "your_extension_has_been_installed_successfully"
                                        ),
                                        closeable: true
                                    },
                                    { root: true }
                                );
                                payload.tab = "settings";
                            }

                            if (typeof payload.callback == "function") {
                                payload.callback();
                            }
                            if (response.data.info) {
                                commit(
                                    "builder/setPopup",
                                    {
                                        show: true,
                                        type: "warning",
                                        loading: false,
                                        title: $t("action_required"),
                                        message: response.data.info,
                                        closeable: true,
                                        data: response.data
                                    },
                                    { root: true }
                                );
                            }
                        } else if (response.data.message === 'grant_access_scopes' && response.data.translate_data && window.shopify) {
                            // show scopes modal
                             (async () => {
                                 // get current scopes  
                                 const { granted } = await window.shopify.scopes.query();
                                 // get missing scopes
                                 const missingScopes = response.data.translate_data.scopes.filter(scope => !granted.includes(scope));
                                 if(missingScopes.length > 0) {
                                    try{
                                        const { result } = await window.shopify.scopes.request(missingScopes);
                                        if('granted-all' === result) {
                                            // toast
                                            dispatch('global/setToast', {
                                                show: true,
                                                error: false,
                                                message: 'Scopes granted successfully',
                                                duration: 4000
                                            },{ root: true });
                                            installApp(_this);
                                            // redirect to route
                                            // window.location.href = response.data.translate_data.route;
                                        } else {
                                            // toast
                                            dispatch('global/setToast', {
                                                show: true,
                                                error: true,
                                                message: 'Abort grant access scopes',
                                                duration: 4000
                                            },{ root: true });
                                        }
                                    } catch (e:any) {
                                        // toast
                                        dispatch('global/setToast', {
                                            show: true,
                                            error: true,
                                            message: e.message,
                                            duration: 4000
                                        },{ root: true });
                                    }
                                 }
                             })();
                        }
                        else {
                            commit(
                                "builder/setPopup",
                                {
                                    show: true,
                                    type: "error",
                                    loading: false,
                                    title: $t("notice"),
                                    message: response.data.message,
                                    closeable: true,
                                    data: response.data
                                },
                                { root: true }
                            );
                            // console.log('throw new Error', response.data.message);
                            // throw new Error(response.data.message ? response.data.message : $t('unknown_message'));
                        }
                    })
                    .catch((e) => {
                        commit("setLoading", false);
                        commit(
                            "builder/setPopup",
                            {
                                show: true,
                                type: "error",
                                loading: false,
                                title: $t("notice"),
                                message: e.message,
                                closeable: true,
                                data: e
                            },
                            { root: true }
                        );
                        if (state.apps?.data) {
                            state.apps.data.forEach((app) => {
                                if (app.id === payload.id) {
                                    app.loading = false;
                                }
                            });
                        }
                    });
            }
        },

        detail({ commit, dispatch }, payload) {
            dispatch("setLoadingDetail", { id: payload.id, status: true });
            window.location.hash = "extensions/" + payload.id;
            this.$worker
                .fetch(
                    window.route("builder.apps.settings", { post: payload.id, page: payload.page }),
                    null,
                    "GET"
                )
                .then((response) => {
                    dispatch("setLoadingDetail", { id: payload.id, status: false });
                    commit("setListLoading", false);
                    if (response.data.status === "success") {
                        // window.location.hash = "extensions/" + payload.id;
                        response.data.app.type = "detail";
                        response.data.app.tab = payload.tab;
                        //convert object languages
                        let dataApp = response.data.app;
                        if (dataApp.translate) {
                            let translate = dataApp.translate;
                            let newData = {};
                            translate.forEach((item) => {
                                newData[item.language] = {
                                    title: item.title,
                                    description: item.description,
                                    content: item.content
                                };
                            });
                            dataApp.translate = newData;
                        }
                        //replace locales object by current locale
                        let currentLocal = window.ECOM_INIT?.locale || "en";
                        let obj = response?.data?.app?.options?.schema;
                        let locales = obj.locales;
                        let settings = obj.settings;
                        const replaceKeys = (data, callBack) => {
                            for (let key in data) {
                                if (typeof data[key] === "string" && data[key].startsWith("$t:")) {
                                    let translateKey = data[key].replace("$t:", "");
                                    if (
                                        locales[currentLocal] &&
                                        translateKey in locales[currentLocal]
                                    ) {
                                        data[key] = locales[currentLocal][translateKey];
                                    }
                                } else if (typeof data[key] === "object" && data[key] !== null) {
                                    callBack(data[key]);
                                }
                            }
                        };
                        const traverseData = (currentData) => {
                            if (Array.isArray(currentData) && currentData.length) {
                                currentData.forEach((item) => {
                                    replaceKeys(item, traverseData);
                                });
                            } else if (
                                typeof currentData === "object" &&
                                !Array.isArray(currentData) &&
                                currentData !== null
                            ) {
                                replaceKeys(currentData, traverseData);
                            }
                        };
                        if (locales) {
                            traverseData(settings);
                        }

                        commit("setDetail", {
                            ...response.data.app,
                            review: response.data.review,
                            reviews: response.data.reviews
                        });
                        if (typeof payload.callback == "function") {
                            payload.callback();
                        }
                        if (response.data.info) {
                            commit(
                                "builder/setPopup",
                                {
                                    show: true,
                                    type: "warning",
                                    loading: false,
                                    title: $t("information"),
                                    message: response.data.info,
                                    closeable: true
                                },
                                { root: true }
                            );
                        }
                    } else {
                        throw new Error(
                            response.app.message ? response.app.message : $t("unknown_message")
                        );
                    }
                })
                .catch((e) => {
                    commit("setListLoading", false);
                    dispatch('global/setToast', {
                        isError: true,
                        message: e.message,
                        data: e,
                        duration: 4000
                    },{ root: true });
                });
        },

        setLoading({ state }, payload) {
            let app =
                state?.apps?.data?.constructor === Array
                    ? state.apps.data.filter((a) => {
                          return a.id === payload.id;
                      })
                    : null;
            if (app?.[0]) {
                app[0].loading = payload.status;
            }
            if (state.library.detail) {
                state.library.detail.loading = payload.status;
            }
        },

        setLoadingDetail({ state }, payload) {
            let app =
                state?.apps?.data?.constructor === Array
                    ? state.apps.data.filter((a) => {
                          return a.id === payload.id;
                      })
                    : null;
            if (app?.[0]) {
                app[0].loadingDetail = payload.status;
            }
            if (state.library.detail) {
                state.library.detail.loading = payload.status;
            }
        },

        closeDetail({ commit }) {
            commit("setDetail", null);
            window.location.hash = "extensions";
        }
    }
};
