import { $t } from '@/plugins/i18n';
import {
  MEASUREMENT_TYPES,
  REFERENCE_TYPES,
  TYPES_WITHOUT_LIST,
  listTypeOf,
} from '@/utils/metafieldLiquid';

const ENTITY_TYPES = ['product', 'collection', 'page', 'article', 'blog'] as const;

/** Map page/section type to Liquid owner for predefined sources + metafields. */
export function normalizeShopifyType(type: string): string {
  if (!type) return 'page';
  if (type === 'post') return 'article';
  if ((ENTITY_TYPES as readonly string[]).includes(type)) return type;
  return 'shop';
}

/**
 * DS-05: field/metafield types Shopify theme editor cho phép nối vào setting
 * `text` / `richtext` (EComposer editor tương đương richtext).
 * Nguồn: https://shopify.dev/docs/storefronts/themes/architecture/settings/dynamic-sources
 * — bảng "Metafield and input setting compatibility", cột `richtext`/`text`.
 */
export const DYNAMIC_TEXT_COMPATIBLE_TYPES = [
  'single_line_text_field',
  'list.single_line_text_field',
  'multi_line_text_field',
  'rich_text_field',
  'number_integer',
  'number_decimal',
  'date',
  'date_time',
  'weight',
  'volume',
  'dimension',
  'rating',
  'money',
  'link', // chỉ hợp lệ với richtext/inline_richtext, EComposer editor luôn richtext-like
];

/**
 * DS-05: field không tương thích trực tiếp (url, color, boolean, language, json,
 * mixed_reference, list.link…) → ẩn, TRỪ KHI là field reference (isReference = true)
 * — reference luôn hiện để cho phép drill-down tìm field lá tương thích bên trong.
 */
export function isDynamicFieldTypeCompatible(type?: string | null): boolean {
  if (!type) return true; // Không rõ type (data cũ/thiếu) → không ẩn nhầm, giữ hành vi cũ
  return DYNAMIC_TEXT_COMPATIBLE_TYPES.includes(type);
}

/**
 * MF-EL-01: type mà element Metafields render được.
 *
 * KHÁC `DYNAMIC_TEXT_COMPATIBLE_TYPES` ở trên: danh sách kia cố ý hẹp vì lọc cho
 * việc chèn inline vào rich text editor. Element đứng độc lập render được nhiều
 * hơn, nên phải có allowlist riêng.
 *
 * Danh sách này CHỈ chứa type đã thực sự có nhánh render trong element — không
 * thêm trước. Merchant chọn được type nào là type đó chắc chắn ra giá trị
 * (yêu cầu Q6 của PO: không để chọn xong rồi ra rỗng mà không hiểu vì sao).
 *
 * `metaobject_reference` nằm trong danh sách nhưng KHÔNG tự render được — nó là
 * container. Element drill xuống field lá rồi render field đó theo type của nó.
 * KHÔNG bao giờ thêm `mixed_reference` (PO chốt không support).
 */
const ELEMENT_METAFIELD_SUPPORTED_BASE_TYPES = [
  // MF-EL-01
  'single_line_text_field',
  'multi_line_text_field',
  'number_integer',
  'number_decimal',
  'id',
  'json',
  // MF-EL-03
  'boolean',
  'date',
  'date_time',
  'money',
  'rating',
  'color',
  'url',
  'link',
  ...MEASUREMENT_TYPES,
  // MF-EL-04
  'rich_text_field',
  'file_reference',
  // MF-EL-05 — container, render theo field lá bên trong
  'metaobject_reference',
  // MF-EL-06
  ...REFERENCE_TYPES,
];

/**
 * Biến thể `list.*` sinh từ chính danh sách base ở trên, không gõ tay.
 *
 * Gõ tay thì mỗi lần thêm base type mới lại phải nhớ thêm cả dòng `list.` tương
 * ứng — sinh tự động nên hai danh sách không bao giờ lệch nhau. Trừ ra những
 * type Shopify không có biến thể list (`TYPES_WITHOUT_LIST`) để không đẻ ra
 * `list.boolean` — thứ merchant không bao giờ chọn được.
 */
export const ELEMENT_METAFIELD_SUPPORTED_TYPES = [
  ...ELEMENT_METAFIELD_SUPPORTED_BASE_TYPES,
  ...ELEMENT_METAFIELD_SUPPORTED_BASE_TYPES
    .filter((type) => !TYPES_WITHOUT_LIST.includes(type))
    .map(listTypeOf),
];

export function isElementMetafieldSupported(type?: string | null): boolean {
  if (!type) return false; // Không rõ type → coi như chưa hỗ trợ, đừng để merchant chọn rồi ra rỗng
  return ELEMENT_METAFIELD_SUPPORTED_TYPES.includes(type);
}

export default {
  namespaced: true,
  state: {
      open: false,
      show: false,
      loading: false,
      shopifyType: '',
      metafileds: {},
      dynamicSource: [],
      // DS-03: metaobjects
      metaobjects: [] as any[],
      metaobjectsLoaded: false,
      metaobjectsLoading: false,
      // DS-03-1: cache field refs — { defType: { fieldKey: referencedType } }
      metaobjectFieldRefsCache: {} as Record<string, Record<string, string>>,
      // DS-03 redesign: cache entries — { defType: [{handle, title}] }
      metaobjectEntriesCache: {} as Record<string, Array<{ handle: string; title: string }>>,
      // DS-05-1: cache field data (refs + raw values) theo entry cụ thể — key `${type}::${handle}`
      metaobjectEntryFieldDataCache: {} as Record<string, { fieldRefs: Record<string, string>; fieldValues: Record<string, string> }>,
  },
  getters: {
      open(state) {
          return state.open;
      },
      show(state) {
        return state.show;
      },
      loading(state) {
        return state.loading;
      },
      shopifyType(state) {
        return state.shopifyType;
      },
      normalizedShopifyType(state) {
        return normalizeShopifyType(state.shopifyType);
      },
      metafileds(state) {
        return state.metafileds[normalizeShopifyType(state.shopifyType)];
      },
      /**
       * Đọc definitions theo owner CỤ THỂ thay vì theo `state.shopifyType`.
       *
       * Element Metafields luôn cần definitions của PRODUCT, kể cả khi đang ở
       * layout Page/Collection — nó nằm trong `nonPageTypeElements`
       * (`Layout/Section.vue:464`) nên không bị ràng buộc theo loại trang.
       * Getter `metafileds` ở trên phụ thuộc state dùng chung với panel Insert
       * Dynamic Source của editor nên không dùng được cho việc này.
       */
      metafieldsByOwner: (state) => (owner: string) => {
        return state.metafileds[normalizeShopifyType(owner)];
      },
      dynamicSource(state) {
        return state.dynamicSource;
      },
      // DS-03
      metaobjects(state) {
        return state.metaobjects;
      },
      metaobjectsLoaded(state) {
        return state.metaobjectsLoaded;
      },
      metaobjectsLoading(state) {
        return state.metaobjectsLoading;
      },
      /**
       * Type của metaobject definition mà một metafield trỏ tới.
       *
       * Shopify đã biết điều này — nằm trong `validations` của metafield
       * definition — nên không có lý gì bắt merchant chọn lại bằng tay. Hai dạng
       * validation phải đỡ cả hai:
       *
       *   metaobject_definition_type → chính chuỗi type (`shopify.material`)
       *   metaobject_definition_id   → GID, phải map qua `id` của definitions
       *
       * Trả '' khi chưa suy ra được (definitions chưa nạp, metafield không phải
       * metaobject_reference, hoặc metafield không giới hạn về một definition).
       * Chỗ gọi phải coi '' là "chưa biết", không phải "không có".
       */
      metaobjectTypeForMetafield: (state) => (owner: string, namespace: string, key: string): string => {
        if (!namespace || !key) return '';

        const list = state.metafileds[normalizeShopifyType(owner)] || [];
        const node = list.find(
          (edge: any) => edge?.node?.namespace === namespace && edge?.node?.key === key
        )?.node;
        if (!node) return '';

        const validations = node.validations || [];
        const byType = validations.find((v: any) => v?.name === 'metaobject_definition_type');
        if (byType?.value) return byType.value;

        const byId = validations.find((v: any) => v?.name === 'metaobject_definition_id');
        if (!byId?.value) return '';

        return state.metaobjects.find((def: any) => def?.id === byId.value)?.type || '';
      },
      // DS-03-1: lookup map type → definition để drill-down sang referenced definition
      definitionsByType(state): Record<string, any> {
        const map: Record<string, any> = {};
        for (const def of state.metaobjects) {
          map[def.type] = def;
        }
        return map;
      },
      // DS-04: Market sources hardcoded — Shopify Localization variables
      marketSources() {
        return [
          { title: 'Market name',       key: 'localization.country.name' },
          { title: 'Market handle',     key: 'localization.market.handle' },
          { title: 'Language name',     key: 'localization.language.name' },
          { title: 'Language ISO code', key: 'localization.language.iso_code' },
          { title: 'Country name',      key: 'localization.country.name' },
          { title: 'Country ISO code',  key: 'localization.country.iso_code' },
          { title: 'Currency code',     key: 'localization.country.currency.iso_code' },
        ];
      },
  },
  mutations: {
      open(state, payload) {
          state.open = payload;
      },
      show(state, payload) {
        state.show = payload;
      },
      loading(state, payload) {
        state.loading = payload;
      },
      metafileds(state, payload) {
        state.metafileds[payload.shopify_type] = payload.data;
      },
      // DS-03
      setMetaobjects(state, payload) {
        state.metaobjects = payload;
        state.metaobjectsLoaded = true;
        state.metaobjectsLoading = false;
      },
      setMetaobjectsLoading(state, payload) {
        state.metaobjectsLoading = payload;
      },
      // DS-03-1: cache field refs cho 1 definition type
      setMetaobjectFieldRefs(state, { defType, refs }: { defType: string; refs: Record<string, string> }) {
        state.metaobjectFieldRefsCache = {
          ...state.metaobjectFieldRefsCache,
          [defType]: refs,
        };
      },
      // DS-03 redesign: cache entries for a definition type
      setMetaobjectEntries(state, { defType, entries }: { defType: string; entries: Array<{ handle: string; title: string }> }) {
        state.metaobjectEntriesCache = {
          ...state.metaobjectEntriesCache,
          [defType]: entries,
        };
      },
      // DS-05-1: cache field data (refs + raw values) cho 1 entry cụ thể
      setMetaobjectEntryFieldData(state, { cacheKey, data }: { cacheKey: string; data: { fieldRefs: Record<string, string>; fieldValues: Record<string, string> } }) {
        state.metaobjectEntryFieldDataCache = {
          ...state.metaobjectEntryFieldDataCache,
          [cacheKey]: data,
        };
      },
      dynamicSource(state, payload) {
        const normalizedType = normalizeShopifyType(payload);
        state.shopifyType = payload;

        const source = {
          product: [
            { title: $t('title'),         key: 'product.title' },
            { title: $t('link_title'),    key: 'product.title | link_to: product.url' },
            { title: $t('description'),   key: 'product.description' },
            { title: $t('type'),          key: 'product.type' },
            { title: $t('vendor'),        key: 'product.vendor' },
            { title: 'SKU',               key: 'product.selected_or_first_available_variant.sku' },
            { title: 'Handle',            key: 'product.handle' },
            { title: 'URL',               key: 'product.url' },
            { title: $t('image'),         key: 'product | img_tag' },
            { title: $t('price'),         key: 'product.price | money' },
            { title: $t('price_compare'), key: 'product.compare_at_price | money' },
            { title: $t('tags'),          key: "product.tags | join: ', '" },
            { title: 'Available',         key: 'product.available' },
          ],
          collection: [
            { title: $t('title'),          key: 'collection.title' },
            { title: $t('description'),    key: 'collection.description' },
            { title: $t('tags'),           key: "collection.tags | join: ', '" },
            { title: $t('all_tags'),       key: "collection.all_tags | join: ', '" },
            { title: $t('all_type'),       key: "collection.all_types | join: ', '" },
            { title: $t('all_vendor'),     key: "collection.all_vendors | join: ', '" },
            { title: $t('featured_image'), key: 'collection.featured_image | img_tag' },
            // DS-02: fix bug — products_count là số, không dùng img_tag
            { title: $t('products_count'), key: 'collection.products_count' },
            { title: 'Handle',             key: 'collection.handle' },
            { title: 'URL',                key: 'collection.url' },
          ],
          page: [
            { title: $t('title'),       key: 'page.title' },
            // page_description là global object (SEO meta), không phải page.page_description
            { title: $t('description'), key: 'page_description' },
            { title: $t('content'),     key: 'page.content' },
            { title: $t('author'),      key: 'page.author' },
            { title: 'Handle',          key: 'page.handle' },
            { title: 'URL',             key: 'page.url' },
          ],
          article: [
            { title: $t('title'),       key: 'article.title' },
            { title: $t('link_title'),  key: 'article.title | link_to: article.url' },
            { title: $t('excerpt'),     key: 'article.excerpt' },
            { title: $t('content'),     key: 'article.content' },
            { title: $t('author'),      key: 'article.author' },
            { title: $t('tags'),        key: "article.tags | join: ', '" },
            { title: 'Handle',          key: 'article.handle' },
            { title: 'URL',             key: 'article.url' },
            { title: 'Published at',    key: "article.published_at | date: '%B %d, %Y'" },
            { title: $t('image'),       key: 'article.image | img_tag' },
          ],
          blog: [
            { title: $t('title'),      key: 'blog.title' },
            { title: $t('link_title'), key: 'blog.title | link_to: blog.url' },
            // DS-02: fix bug — blog.all_tags (cũ là article.all_tags)
            { title: $t('all_tags'),   key: "blog.all_tags | join: ', '" },
            { title: 'Handle',         key: 'blog.handle' },
            { title: 'URL',            key: 'blog.url' },
          ],
          // DS-02: home, list-collections, cart, search… → shop (Liquid: shop.metafields.namespace.key)
          shop: [
            { title: 'Shop name', key: 'shop.name' },
            { title: 'Email',     key: 'shop.email' },
            { title: 'Domain',    key: 'shop.domain' },
            { title: 'URL',       key: 'shop.url' },
            { title: 'Currency',  key: 'shop.currency' },
            { title: $t('description'), key: 'shop.description' },
            { title: 'Phone',     key: 'shop.phone' },
          ],
        };

        state.dynamicSource = (source as any)[normalizedType] ?? [];
      },
  },
  actions: {
    // DS-03 redesign: fetch up to 20 entries for the entry picker
    loadMetaobjectEntries(
      { state, commit }: any,
      defType: string,
    ): Promise<Array<{ handle: string; title: string }>> {
      if (state.metaobjectEntriesCache[defType]) {
        return Promise.resolve(state.metaobjectEntriesCache[defType]);
      }
      return (this as any).$worker
        .fetch(window.route('sources.metaobject.entries', { type: defType }), null)
        .then((response: any) => {
          if (response.data.status === 'success') {
            const entries: Array<{ handle: string; title: string }> = response.data.entries || [];
            commit('setMetaobjectEntries', { defType, entries });
            return entries;
          }
          const message = response?.data?.message || 'Failed to load metaobject entries';
          return Promise.reject(new Error(message));
        });
    },

    // DS-03-1: fetch field → referencedType map cho 1 definition type
    // Inspect actual entry (schema không expose referenced type trực tiếp)
    loadMetaobjectFieldRefs({ state, commit }, defType: string): Promise<Record<string, string>> {
      // Cache hit — trả về ngay
      if (state.metaobjectFieldRefsCache[defType]) {
        return Promise.resolve(state.metaobjectFieldRefsCache[defType]);
      }
      return this.$worker
        .fetch(window.route('sources.metaobject.refs', { type: defType }), null)
        .then((response) => {
          if (response.data.status === 'success') {
            const refs = response.data.fieldRefs || {};
            commit('setMetaobjectFieldRefs', { defType, refs });
            return refs;
          }
          return {};
        })
        .catch(() => ({}));
    },

    /**
     * DS-05-1: fetch field refs + raw values cho ĐÚNG entry (handle) merchant đang chọn.
     * Dùng để "Smart Fallback": khi 1 field metaobject_reference không resolve được
     * referencedType (thường do trỏ tới metaobject app-owned của app khác — Shopify
     * chỉ cho app sở hữu định nghĩa `$app:` truy cập schema đó), nhưng field vẫn có
     * raw `value` đọc được → cho phép merchant "Insert Raw Value" thay vì bó tay.
     * `handle` optional — nếu không truyền (vd chế độ via-metafield, chưa có entry cụ thể),
     * backend fallback lấy 1 entry mẫu đầu tiên (giữ hành vi cũ của loadMetaobjectFieldRefs).
     */
    loadMetaobjectEntryFieldData(
      { state, commit }: any,
      { defType, handle }: { defType: string; handle?: string | null },
    ): Promise<{ fieldRefs: Record<string, string>; fieldValues: Record<string, string> }> {
      const cacheKey = `${defType}::${handle || ''}`;
      if (state.metaobjectEntryFieldDataCache[cacheKey]) {
        return Promise.resolve(state.metaobjectEntryFieldDataCache[cacheKey]);
      }
      const params: Record<string, string> = { type: defType };
      if (handle) params.handle = handle;
      return this.$worker
        .fetch(window.route('sources.metaobject.refs', params), null)
        .then((response: any) => {
          const data = {
            fieldRefs: (response.data.status === 'success' && response.data.fieldRefs) || {},
            fieldValues: (response.data.status === 'success' && response.data.fieldValues) || {},
          };
          commit('setMetaobjectEntryFieldData', { cacheKey, data });
          return data;
        })
        .catch(() => ({ fieldRefs: {}, fieldValues: {} }));
    },
    // DS-03: load metaobject definitions (có cache — không fetch lại nếu đã load)
    // Trả về promise để caller có thể await (dùng khi dựng lại state từ liquid path).
    loadMetaobjects({ state, commit }) {
      if (state.metaobjectsLoaded) return Promise.resolve();
      commit('setMetaobjectsLoading', true);
      return this.$worker
        .fetch(window.route('sources.metaobjects'), null)
        .then((response) => {
          if (response.data.status === 'success') {
            commit('setMetaobjects', response.data.metaobjects);
          } else {
            commit('setMetaobjectsLoading', false);
          }
        })
        .catch(() => {
          commit('setMetaobjectsLoading', false);
        });
    },
    /**
     * `payload.owner`: buộc load definitions của một owner cụ thể thay vì tự dò từ
     * section. Khi có override thì KHÔNG commit `dynamicSource` — `state.shopifyType`
     * là state dùng chung với panel Insert Dynamic Source của editor, ghi đè nó sẽ
     * làm panel đó hiện sai bộ predefined source.
     */
    loadDynamicSources({ getters, state, commit, dispatch, rootGetters }, payload?: { owner?: string }) {
      commit('loading', true);
      const ownerOverride = payload?.owner;
      const editingElement = rootGetters['builder/activeElement'], sections = rootGetters['page/sections'], section = sections.find((s:any) => s.id == editingElement?.section_id);
      let shopify_type = ownerOverride || (section?.shopify_type ?  section?.shopify_type : rootGetters['page/params']?.page);
      const metafieldOwner = normalizeShopifyType(shopify_type);
      if(shopify_type && !ownerOverride) {
        commit('dynamicSource', shopify_type);
      }

      if(state?.metafileds && state.metafileds.hasOwnProperty(metafieldOwner)) {
        commit('loading', false);
        return;
      }
      console.log('Load Dynamic Resource')
      this.$worker
          .fetch(window.route('sources.load', {shopify_type: metafieldOwner}), null)
          .then((response) => {
              if (response.data.status === 'success') {
                commit('metafileds', {shopify_type: metafieldOwner, data: response.data.metafields});
                commit('loading', false);
              } else {
                  throw new Error(
                      response?.data?.message ? response.data.message : 'Unknow error'
                  );
              }
          })
          .catch((e) => {
            commit('loading', false);
        });
    }
  }
};