<template>
    <Liquid v-if="conditionLiquid?.start && exporting && is !== 'section'" :data="conditionLiquid.start"></Liquid>
    <component
        :is="data?.settings?.tag ?? (is == 'section' ? 'section' : 'div')"
        v-bind="rowAttrs"
        @mouseenter="overRow"
        @mouseleave="outRow"
        @contextmenu="rightClickMenu"
        @click="editRow"
        :data-notice-content="!exporting ? $t('this_image_is_for_preview_only') : null"
        :class="[!exporting ? 'dom-relative' : '', needReplaceBg ? is == 'section' ? 'ecom-replace-notice' : 'ecom-replace-notice-column' : '', parallaxBgImage ? 'ecom-use-parallax' : '']"
        v-show="data.visibility !== false"
    >
        <div v-if="parallaxBgImage" class="ecom-parallax-background" :data-image="parallaxBgImage">
            <img :src="parallaxBgImage" />
        </div>
        <transition
            enter-active-class="transition duration-300 ease-out"
            enter-from-class="opacity-0"
            enter-to-class="opacity-100"
            leave-active-class="transition duration-300 ease-in"
            leave-from-class="opacity-100"
            leave-to-class="opacity-0"
            v-if="!inGrid && !exporting"
        >
            <div v-if="isActiveSettings" class="ecom-box-hover" style="z-index: 100;">
                <div class="label-section ecom-label-section" :title="$t('edit') + ' ' + $t(is)" :class="[isEditing ? 'active' : '', locked ? 'cursor-default' : '']" @mousedown="startDrag" @mouseup="editRow" :style="{marginBottom: '-1px'}">
                    <EcomIcon v-if="is == 'section'" :source="icons.SectionMajor" class="icon-builder ec-opacity-50"></EcomIcon>
                    <span :title= "$t('back_to_parent')" v-else class="core--settings__back core__block--settings__back" @click.prevent.stop="handleBack2Parent">
                        <EcomIcon :source="icons.backIcon" class="icon-back"></EcomIcon>
                    </span>
                    <span v-if="data?.title && data?.title !== ''">{{ data.title }}</span>
                    <span v-else>{{ is === 'row' ? $t('row') : $t('section') }}</span>
                </div>
                <!-- <div class="section__settings-edit" :style="{ marginBottom: shouldApplyMarginBottom ? '-28px' : '0' }" v-if="isEditing && !locked">
                    <span class="btn-in-section" v-if="is == 'section' && params?.page !== 'menu'" :title="$t('add')+' ' + $t(is)" @click="addSection">
                        <EcomIcon size="w-4" :source="icons.CirclePlusMajor" class="icon-builder icon-scale text-white"></EcomIcon>
                    </span>
                    <span class="btn-in-section" v-if="is == 'section' && params?.page !== 'menu' && !isFirst" :title="$t('move_to_previous_position')" @click="moveSection($event, 'prev')">
                        <EcomIcon :source="icons.ArrowUpMinor" class="icon-builder"></EcomIcon>
                    </span>
                    <span class="btn-in-section" v-if="is == 'section' && params?.page !== 'menu' && !isLast" :title="$t('move_to_next_position')" @click="moveSection($event, 'next')">
                        <EcomIcon :source="icons.ArrowDownMinor" class="icon-builder"></EcomIcon>
                    </span>
                    <span v-if="params?.page !== 'menu'" :title="$t('delete')+ ' ' + $t(is)" class="btn-in-section section__settings--delete" @click="dropOut(false)">
                        <EcomIcon :source="icons.DeleteMajor" class="icon-builder"></EcomIcon>
                    </span>
                </div> -->
            </div>
        </transition>
        <div v-if="!exporting && !inGrid" class="mark-box" :class="[isActiveSettings ? isEditing ? 'active' : 'hover' : '', isEditing ? 'ecom_current-edit' : '']">
            <span @mouseup="editRow" class="mask-dom left"></span>
            <span class="line-border top" :class="classSectionActive"></span>
            <span class="line-border right"></span>
            <span class="line-border bottom" :class="classSectionActive"></span>
            <span class="line-border left"></span>
        </div>
        <div
            v-if="deep < 5"
            :data-deep="exporting===false ? deep : null"
            class="core__row--columns"
            :class="data?.settings?.['content-width'] == 'full' ? 'core__row--full' : ''"
        >
            <ColumnElement
                v-for="(col, i) in visibleColumns"
                :key="col.id"
                :index="i"
                :data="col"
                :deep="deep"
                :section_id="section_id"
                :breadcrumb="breadcrumb ? `${breadcrumb}/${data?.id}` : data?.id"
                :dragParent="dragParent"
                :inGrid="inGrid"
            />
        </div>
        <div
            v-else-if="exporting===false"
            class="core__notice--error"
            :data-deep="exporting===false ? deep : null"
        >
            <span>{{ $t('maximum_nesting_level_reached._a_section_allows_up_to_3_nested_inner_rows_only') }}</span>
        </div>
        <div v-if="['section', 'row'].includes(is)" class="ecom-section__overlay">
            <video
                class="ecom-video-background"
                :muted="true"
                defaultmuted
                playsinline
                preload="true"
                v-if="show_video_background && ['upload','external'].includes(data?.settings?.source)"
                :data-play-pause-inview="data.settings?.inview_playpause"
                :loop="data.settings.loop"
                :autoplay="data.settings.autoplay"
                :data-source="data.settings?.source"
                :src="video_url"
                ref="video"
            />
            <div
                class="ecom-video-background-youtube-wrapper"
                v-if="show_video_background && ['youtube','vimeo'].includes(data?.settings?.source)"
            >
                <div
                    class="ecom-video-background-youtube"
                >
                    <iframe
                        class="ecom-video-background"
                        frameborder="0"
                        allowfullscreen="1"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        style="border: 0; width: 100%; height: 100% !important"
                        :src="data?.settings?.source == 'vimeo' ? linkVimeo : linkYoutube"
                        :data-play-pause-inview="data.settings?.inview_playpause"
                        :data-source="data.settings?.source"
                    />
                </div>
            </div>
            <div class="ecom-overlay" />
        </div>
        <template v-else />
        <template v-if="canDrop">
            <div
                class="placeholder__top"
                style="z-index:11"
                @mouseenter="placehover"
            />
            <div
                class="placeholder__bottom"
                style="z-index:11"
                @mouseenter="placehover"
            />
        </template>
        <template v-else />
        <transition
            enter-active-class="transition duration-400 ease-out"
            enter-from-class="opacity-0"
            enter-to-class="opacity-100"
            leave-active-class="transition duration-400 ease-in"
            leave-from-class="opacity-100"
            leave-to-class="opacity-0"
        >
            <div
                v-if="isEditing && is == 'section' && !exporting && !isFullScreen && !isDragging"
                class="core__row--padding-top transition"
                :class="classSectionActive"
                @mousedown.stop="startDragPadding($event, 'top')"
            >
                <span
                    v-if="isDragPadding && paddingPosition == 'top'"
                    class="core__block--padding-value"
                    v-html="paddingCurrentVal + 'px'"
                />
                <span
                    v-if="isDragPadding && paddingPosition == 'top'"
                    class="core__block--padding-markup top-0"
                    :style="{height: paddingCurrentVal + 'px'}"
                />
            </div>
        </transition>
        <transition
            enter-active-class="transition duration-400 ease-out"
            enter-from-class="opacity-0"
            enter-to-class="opacity-100"
            leave-active-class="transition duration-400 ease-in"
            leave-from-class="opacity-100"
            leave-to-class="opacity-0"
        >
            <div
                v-if="isEditing && is == 'section' && !exporting && !isFullScreen && !isDragging"
                class="core__row--padding-bottom transition"
                :class="classSectionActive"
                @mousedown.stop="startDragPadding($event, 'bottom')"
            >
                <span
                    v-if="isDragPadding && paddingPosition == 'bottom'"
                    class="core__block--padding-value"
                    v-html="paddingCurrentVal + 'px'"
                />
                <span
                    v-if="isDragPadding && paddingPosition == 'bottom'"
                    class="core__block--padding-markup"
                    :style="{height: paddingCurrentVal + 'px'}"
                />
            </div>
        </transition>
    </component>
    {{ exporting === true && conditionLiquid?.start && is !== 'section' ? conditionLiquid?.end : ''}}
</template>

<script>
import ColumnElement from './Column.vue';
import { Core, Element, Liquid } from '@/mixins';
import { mapGetters } from 'vuex';
import { getIdParentAndIndex } from '@/utils/helpers';
import { widthPxCalculate } from "@/plugins/vue-grid-layout/helpers/utils";
import { EditMajor, MobilePlusMajor, DeleteMajor, ArrowUpMinor, ArrowDownMinor, SectionMajor, ecPlus, backIcon, CirclePlusMajor, sangIcon, WandIcon } from '@/assets/icons';
export default {
    name: 'Row',
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/inner-row/',
    components: {
        ColumnElement
    },
    mixins: [Core, Element, Liquid],
    props: {
        data: {
            type: Object,
            default() {
                return {
                    columns: [],
                    settings: {
                        shopify_type: 'product'
                    }
                };
            }
        },
        section_id: {
            type: String,
            default: ''
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        },
        'breadcrumb': {
            type: String,
            default: ''
        },
        'dragParent': {
            type: Boolean,
            default: false
        },
        inGrid: {
            type: Boolean,
            default: false
        }
    },
    data() {
        return {
            shouldApplyMarginBottom: false,
            is: this.deep == 1 ? 'section' : 'row',
            name: this.deep == 1 ? this.$t('section') : this.$t('inner_row'),
            over: false,
            dragging: false,
            placeholder: '',
            rand: '094',
            timmer: 0,
            icons: {
                EditMajor, MobilePlusMajor, DeleteMajor, ArrowUpMinor, ArrowDownMinor, SectionMajor, ecPlus, backIcon, CirclePlusMajor, sangIcon, WandIcon
            },
            isMuted: this.data?.settings?.muted,
            space: 0,
            position: 0,
            isDragPadding: false,
            paddingPosition: '',
            paddingCurrentVal: 0,
            needReplaceBg: false,
            mouseOver: false
        };
    },
    computed: {
        locked() {
            return this.$store.getters['builder/editorConfigs']?.locked;
        },
        checkEdit() {
            return this.$store.getters['builder/editingElement']?.data?.id == this.data.id;
        },
        conditionLiquid() {
            if(!this.condition) return {}
            let liquids = {
                start: `
                        {% assign condition = true %}
                        ${this.condition ? this.condition : ''}
                        {% if condition %}
                    `,
                end: `
                        {% endif %}
                    `
            };
            return liquids;
        },
        ...mapGetters('settings', [ 'isLiteMode' ]),
        stack() {
            return this.is == 'section'
                ? this.$parent.$parent.sections
                : this.inGrid ? this.$parent?.$parent?.$parent?.$parent?.$parent.stack : this.$parent?.$parent?.$parent?.blocks ? this.$parent?.$parent?.$parent?.blocks : [];
        },

        row() {
            return this.data;
        },

        columns() {
            return this.row.columns ? this.row.columns : [];
        },

        colids() {
            let ids = [];
            this.columns.forEach((col) => {
                ids.push(col.id);
            });
            return ids.join(',');
        },

        rowSettings() {
            return this.row.settings ? this.row.settings : {};
        },

        stretch() {
            return this.row.settings ? this.row.settings.stretch : false;
        },

        visibleColumns() {
            // Getter thuần — không gán id/IDInit ở đây. Mutate trong computed khiến
            // effect tự invalidate dependency của chính nó -> Vue báo
            // "Maximum recursive updates exceeded". Normalize nằm ở watcher `columns`.
            return Array.isArray(this.columns)
                ? this.columns.filter((col) => col && col.visibility !== false)
                : [];
        },

        styleattr() {
            let bg = null;
            if(this.exporting && this.data?.settings?.dynamic_background && ['product','collection','article'].includes(this.params.page) )
            {
                bg = "{{"+this.params.page+" | image_url: width: 2048 }}";
                bg = 'url(\'liquid[['+ encodeURIComponent(bg)+']]\')';
            }
            return {
                wrapper: {
                    // outline: this.isActive ? `${this.deep === 1 ? '2' : '1'}px solid ${this.isEditing ? 'rgb(var(--primary-color-active))' : 'rgba(var(--primary-color-light))'} `: '',
                    // boxShadow: this.isActiveBorder ? `inset 0 0 0 ${this.isEditing ? '2px rgb(var(--primary-color-active))' : '1px rgba(var(--primary-color-light))'}` : '',
                    zIndex: this.exporting ? 'inherit' : (this.isActive ? 3 : 1),
                    backgroundImage: bg
                },
                settings: `display: ${this.isActive ? 'inline-block' : 'none'}, margin-bottom: ${this.shouldApplyMarginBottom ? '-28px' : '0'}`
            };
        },

        isActive() {
            return (
                !this.exporting &&
                !this.isFullScreen &&
                (this.over) && !this.dragCurrent);
        },

        isActiveSettings() {
            return (
                !this.exporting &&
                !this.isFullScreen &&
                (this.over && this?.deep === 1 || this.isEditing) && !this.dragCurrent);
        },
        classSectionActive() {
            // Only applies to top-level sections.
            // Nested rows/flexboxes must return "" to avoid coincidental
            // index arithmetic causing wrong ecom-section-above/below class.
            if (this.is !== 'section') return "";
            if(this.editingElement) {
                const sections = this.sections.filter(section => section.visibility);
                // First: try to match editingElement directly (top-level section)
                let index = sections.findIndex(section => section.id === this.editingElement?.data?.id);
                // Fallback: editingElement is a nested element inside a section (e.g. nested FlexContainer)
                // In that case, use section_id to find the parent section's position
                if (index === -1) {
                    const sectionId = this.editingElement?.section_id;
                    if (sectionId) {
                        index = sections.findIndex(section => section.id === sectionId);
                    }
                }
                if (index === -1) return "";
                if(this.index - index == 1) {
                    return ['ecom-section-below']
                } else if(this.index - index == -1) {
                    return ['ecom-section-above']
                }
                return "";
            }
        },
        isActiveBorder() {
            return (
                this.exporting === false &&
                !this.isFullScreen &&
                (this.over || this.activeElement?.data?.id === this.data.id || this.editingElement?.data?.id === this.data.id) && !this.dragCurrent);
        },

        isEditing() {
            return this.editingElement?.data?.id === this.data.id;
        },

        isFirst() {
            return this.index == 0;
        },

        isLast() {
            return (
                this?.$parent?.visibleSections &&
                this.index == this?.$parent?.visibleSections?.length - 1
            );
        },

        isDraggingCol() {
            return this.dragCurrent && this.dragCurrent.is == 'column';
        },

        isDropTo() {
            return this.dropTo === this && this.canDrop && this.dragCurrent !== this;
        },

        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this);
        },

        rowAttrs() {
            // SR wins over Entrance Animation on the same node (priority: SR > Entrance)
            // Only top-level section Row — not nested/inner rows.
            // srPreview lets the builder canvas emit the same attrs as export.
            const hasSR = (this.exporting === true || this.srPreview) && this.is === 'section' && !!(
                this.data?.settings?.scroll_reveal || this.$store.getters['page/settings']?.scroll_reveal
            );
            const attrs = {
                ref: 'wrapper',
                style: this.styleattr.wrapper,
                'data-placeholder': this.placeholder ? this.placeholder : null,
                key: this.row.refresh,
                class: {
                    'ecom-current-section-drag': this.sectionDrag,
                    'ecom-animated': !this.exporting,
                    'ecom-animation': !hasSR && this.data?.advanced?.animation_type,
                    'ecom-row ecom-core': true,
                  //  'ecom-ingrid-full-height': this.inGrid,
                    drop__placeholder: this.isDropTo,
                    drag__placeholder: this.isDragMe,
                    core__block: this.deep > 1,
                    'ecom-section': this.deep === 1,
                    'ecom-section__stretched': this.stretch,
                    'ecom-section__video-bg' : this.show_video_background && ['youtube','vimeo'].includes(this.data?.settings?.source),
                    ...this.classes
                },
                'data-id': this.data.id,
                ...this.attributes
            };

            if(this.scrollingAnimation) {
                attrs['ecom-scrolling-animation'] = this.scrollingAnimation;
            }

            if(hasSR) {
                const sectionSR = this.data?.settings?.scroll_reveal;
                const src = sectionSR ? this.data.settings : this.$store.getters['page/settings'];
                attrs['data-ec-sr']       = src.scroll_reveal_type  || 'fade-up';
                attrs['data-ec-sr-delay'] = String(src.scroll_reveal_delay || 100);
            }

            if (!hasSR && this.data?.advanced?.animation_delay) {
                const delayValue = this.data.advanced.animation_delay.toString().replace(/ms$/, '');
                attrs["ec-delay"] = delayValue || 0;
            }

            return attrs;
        },
        video_url(){
            let source = this.data?.settings?.source;
            if(!['upload','external'].includes(source))
            {
                return '';
            }
            if(source === 'upload')
            {
                return this.data?.settings.video?.value??'';
            }
            return this.data?.settings?.url??'';
        },
        hasVideoLink() {
            let source = this.data?.settings?.source || null;
            switch (source) {
                case 'upload':
                    return this.data?.settings.video?.value;
                case 'external':
                    return this.data?.settings?.url;
                case 'youtube':
                    return this.data?.settings.srcYoutube;
                default:
                    return this.data?.settings.srcVimeo;
            }
        },
        linkYoutube() {
            if (this.data?.settings?.srcYoutube) {
                const regExpYt = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
                let val = this.data?.settings?.srcYoutube.match(regExpYt);
                let videoIdYt = val && val[2].length === 11 ? val[2] : null;
                return `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3${
                    this.data?.settings?.start_time ? "&start=" + this.data?.settings?.start_time : ""
                }${this.data?.settings?.end_time ? "&end=" + this.data?.settings?.end_time : ""}&controls=0&mute=${
                    this.data?.settings?.muted ? 1 : 0
                }&showinfo=0&enablejsapi=1&iv_load_policy=3&playlist=${videoIdYt}&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },
        linkVimeo() {
            if (this.data?.settings?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.data?.settings?.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?controls=0&api=1&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&muted=${this.data?.settings?.muted || this.data?.settings?.autoplay ? 1 : 0}${
                    this.data?.settings?.start_time ? "&byline=1#t=00h00m" + this.data?.settings?.start_time + "ss" : ""
                }&showinfo=0&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },
        params(){
            return this.$store.getters['page/params'];
        },
        settings() {
            let settings =  [
                {
                    group_title: this.$t('layout'),
                    params: [
                        {
                            type: 'choose',
                            name: 'content-width',
                            label: this.$t('content_width'),
                            options: {
                                reset:true,
                                type: 'content-width',
                                values: [
                                    'boxed',
                                    'full',
                                ],
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return !this.inGrid;
                                    }
                                },
                            }
                        },
                        {
                            name: 'max-width',
                            label: this.$t('max_width'),
                            type: 'number',
                            css: {
                                selector: '>div.core__row--columns'
                            },
                            value: '1140px',
                            options: {
                                units: {
                                    px: {
                                        min: 250,
                                        max: 1600,
                                        step: 1
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['content-width'] === 'boxed' && !this.inGrid;
                                    }
                                },
                                responsive: true
                            }
                        },
                        {
                            name: 'height',
                            label: this.$t('content_height'),
                            type: 'choose',
                            css: {
                                selector: '>div.core__row--columns'
                            },
                            options: {
                                reset:true,
                                type: 'content-height',
                                values: [
                                    '100vh',
                                    'auto',
                                ],
                                oneline: true,
                                visible: {
                                    condition: (data) => {
                                        return !this.inGrid
                                    }
                                }
                            }
                        },
                        {
                            name: 'min-height',
                            label: this.$t('minimum_height'),
                            type: 'number',
                            css: {
                                selector: '>div.core__row--columns>.ecom-column.ecom-core>.core__column--wrapper>.core__blocks'
                            },
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 1440,
                                        step: 1
                                    },
                                    vh: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    },
                                    wh: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    }
                                },
                                responsive: true,
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data?.height == 'auto';
                                    }
                                }
                            }
                        },
                        {
                            name: 'padding',
                            label: this.$t('column_gap'),
                            type: 'popup',
                            css: {
                                selector: '>.core__row--columns>.ecom-column>.core__column--wrapper'
                            },
                            options: {
                                responsive: true,
                                values: {
                                    '0px': this.$t('no_gap'),
                                    '5px': this.$t('narrow'),
                                    '15px': this.$t('extended'),
                                    '20px': this.$t('wide'),
                                    '30px': this.$t('wider'),
                                    inherit: this.$t('custom'),
                                },
                                preview: 'title',
                                type: 'dropdown'
                            }
                        },
                        {
                            name: 'custom-padding',
                            label: this.$t('custom_gap'),
                            type: 'number',
                            css: {
                                selector: '>.core__row--columns>.ecom-column>div.core__column--wrapper',
                                properties: {
                                    padding: ''
                                }
                            },
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 500,
                                        step: 1
                                    },
                                    '%': {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    },
                                    vh: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    },
                                    vw: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        let key = 'padding';
                                        if(this.screen !== 'desktop')
                                        {
                                            key += `__${this.screen}`;
                                        }
                                        return data[key] === 'inherit';
                                    }
                                },
                                responsive: true
                            }
                        },
                        {
                            type: 'line'
                        },
                        {
                            type: 'paragraph',
                            content: '** '+this.$t('align_columns_inside')+' **'
                        },
                        {
                            type: 'choose',
                            label: this.$t('align_items'),
                            name: 'align-items',
                            css: {
