        gridLayoutStyle() {
            const ensureNumber = (value) => {
                if (typeof value === "string") {
                    return parseFloat(value.replace(/[^\d.-]/g, "")) || 0;
                }
                return typeof value === "number" ? value : 0;
            };
            const idoc =  window.EComposerBuilder.contentDocument;
            const screenWidth = idoc?.defaultView?.innerWidth || 1440;
            const section = this.sections.find((section) => section.id === this.sectionId);
            const activePreset = this.$store.getters['page/activePreset'];
            const widthSettings = activePreset?.theme_settings["max-width"] || 1200;
            let sectionWidth = section?.settings["content-width"] === "full" ? screenWidth : (parseFloat(section?.settings["max-width"]) || parseFloat(widthSettings));

            const containerWidths = {
                desktop: sectionWidth,
                tablet: 767,
                mobile: 338
            };
            // Breakpoints
            const breakpoints = {
                desktop: 1025,
                tablet: 1023,
                mobile: 767
            };
            const hasValue = (value) => {
                // Nếu là undefined hoặc null
                if (value === undefined || value === null) return false;

                // Nếu là chuỗi rỗng
                if (typeof value === "string" && value.trim() === "") return false;

                // Chuyển đổi sang số và kiểm tra
                const num = parseFloat(String(value).replace(/[^\d.-]/g, ""));

                // Trả về false nếu NaN, nhưng true nếu là 0
                return !isNaN(num);
            };
            const layouts = this.$parent?.data?.layouts;
            if (!layouts) return "";
            const sectionId = this?.$parent?.section_id || this?.$parent?.$parent?.section_id || '';
            const blockId =  this?.$parent?.data?.id;

            // CSS Rules
            let cssRules = "";

            // Tạo CSS cho các breakpoints
            if (layouts.desktop) {
                const layout = layouts.desktop;
                // Đảm bảo các giá trị là số
                const x = ensureNumber(layout.left);
                const y = ensureNumber(layout.top);
                const h = ensureNumber(layout.height);
                const rotation = ensureNumber(layout.rotation || 0);

                const containerWidth = containerWidths.desktop;

                // Convert width to pixels if it's percentage
                const w = ensureNumber(widthPxCalculate(layout.width, containerWidth));

                // Kiểm tra xem element có ở center không
                const elementCenterX = x + (w / containerWidth) * 100 / 2;
                const isCentered = Math.abs(elementCenterX - 50) < 1; // tolerance 1%

                // Kiểm tra element có căn right không (x + width gần bằng 100%)
                const elementRightEdge = x + (w / containerWidth) * 100;
                const isRightAligned = Math.abs(elementRightEdge - 100) <= 1; // tolerance 1%

                // Xác định align dựa trên vị trí phần trăm
                let justifySelf;
                if (isCentered) {
                    justifySelf = "center";
                } else if (isRightAligned) {
                    justifySelf = "end";
                } else if (x < 50) {
                    justifySelf = "start";
                } else {
                    justifySelf = "end";
                }
                const alignSelf = "start";

                // Tính toán margins
                let marginLeft, marginRight;

                if (justifySelf === "center") {
                    marginLeft = "0";
                    marginRight = "0";
                } else if (justifySelf === "start") {
                    marginLeft = `${x}%`;
                    marginRight = "auto";
                } else { // justifySelf === "end"
                    if (isRightAligned) {
                        // Trường hợp căn right: margin-right = 0, margin-left = auto
                        marginLeft = "auto";
                        marginRight = "0";
                    } else {
                        // Trường hợp thông thường
                        marginLeft = "auto";
                        const rightMarginPercent = 100 - x - (w / containerWidth) * 100;
                        marginRight = isNaN(rightMarginPercent) ? "0%" : `${rightMarginPercent}%`;
                    }
                }

                // Margin-top luôn tính bằng px
                const marginTop = `${y}px`;

                // Gộp margin thành một thuộc tính
                const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;
                // CSS cho desktop
                cssRules += `
                .${sectionId} .ecom-block.${blockId} {
                    justify-self: ${justifySelf};
                    align-self: ${alignSelf};
                    width: ${layout.width};
                    height: ${layouts.options.autoHeight ? "auto;" : `${h}px;`};
                    margin: ${margin};`;

                // Thêm rotation nếu cần
                if (rotation !== 0) {
                    cssRules += `
                    transform: rotate(${rotation}deg);
                    transform-origin: center center;`;
                }
                //zindex
                if (layout.zindex) {
                    cssRules += `
                    z-index: ${ensureNumber(layout.zindex)};`;
                }

                cssRules += `
                }`;
            }

            // Chỉ render CSS cho tablet và mobile nếu có giá trị thực sự
            ["tablet", "mobile"].forEach((device) => {
                if (!layouts[device]) return;

                const layout = layouts[device];

                // Kiểm tra xem layout có thuộc tính nào có giá trị không
                const hasLeft = hasValue(layout.left);
                const hasTop = hasValue(layout.top);
                const hasWidth = hasValue(layout.width);
                const hasHeight = hasValue(layout.height);
                const hasRotation = hasValue(layout.rotation);
                //zindex
                const hasZIndex = hasValue(layout.zindex);

                // Nếu không có giá trị tùy chỉnh nào, không render CSS cho breakpoint này
                if (!hasLeft && !hasTop && !hasWidth && !hasHeight && !hasRotation && !hasZIndex) return;

                const minWidth = breakpoints[device];

                // Bắt đầu media query
                cssRules += `
                @media screen and (max-width: ${minWidth}px)`;

                if (device === "tablet") {
                    cssRules += ` and (min-width: ${breakpoints.mobile + 1}px)`;
                }

                cssRules += ` {
                    .${sectionId} .ecom-block.${blockId} {
                        position: relative;`;

                // Chỉ render các thuộc tính có giá trị
                if (hasWidth) {
                    cssRules += `
                        ${
                            layout.full_width
                                ? "width: 100%;"
                                : `width: ${layout.width};`
                        }`;
                }

                if (hasHeight) {
                    cssRules += `
                        height: ${layouts.options.autoHeight ? "auto;" : `${ensureNumber(layout.height)}px;`}`;
                }

                // Chỉ render justify-self nếu có left
                let justifySelf = 'start';
                if (hasLeft) {
                    const x = ensureNumber(layout.left);
                    const containerWidth = containerWidths[device];

                    // Nếu không có width tùy chỉnh, sử dụng width từ desktop hoặc fallback
                    let w = 0;
                    if (hasWidth) {
                        w = ensureNumber(widthPxCalculate(layout.width, containerWidth));
                    } else if (layouts.desktop && layouts.desktop.width) {
                        // Fallback về desktop width nếu có
                        w = ensureNumber(widthPxCalculate(layouts.desktop.width, containerWidth));
                    }

                    // Chỉ kiểm tra center và right alignment nếu có width hợp lệ
                    justifySelf = x < 50 ? "start" : "end";
                    if (w > 0) {
                        const elementCenterX = x + (w / containerWidth) * 100 / 2;
                        const isCentered = Math.abs(elementCenterX - 50) < 1; // tolerance 1%

                        // Kiểm tra element có căn right không (x + width gần bằng 100%)
                        const elementRightEdge = x + (w / containerWidth) * 100;
                        const isRightAligned = Math.abs(elementRightEdge - 100) <= 1; // tolerance 1%

                        if (isCentered) {
                            justifySelf = "center";
                        } else if (isRightAligned) {
                            justifySelf = "end";
                        }
                    }

                    cssRules += `
                        justify-self: ${justifySelf};`;
                }

                //has zindex
                if (hasZIndex) {
                    cssRules += `
                        z-index: ${ensureNumber(layout.zindex)};`;
                }
                // Chỉ thêm margin nếu có left hoặc top
                if (hasLeft || hasTop) {
                    const containerWidth = containerWidths[device];
                    const x = hasLeft ? ensureNumber(layout.left) : 0;
                    const y = hasTop ? ensureNumber(layout.top) : 0;

                    // Nếu không có width tùy chỉnh, sử dụng width từ desktop hoặc fallback
                    let w = 0;
                    if (hasWidth) {
                        w = ensureNumber(widthPxCalculate(layout.width, containerWidth));
                    } else if (layouts.desktop && layouts.desktop.width) {
                        // Fallback về desktop width nếu có
                        w = ensureNumber(widthPxCalculate(layouts.desktop.width, containerWidth));
                    }

                    // Tính toán margins
                    let marginLeft, marginRight;

                    // Chỉ kiểm tra center và right alignment nếu có width hợp lệ
                    let isCentered = false;
                    let isRightAligned = false;
                    if (w > 0) {
                        const elementCenterX = x + (w / containerWidth) * 100 / 2;
                        isCentered = Math.abs(elementCenterX - 50) < 1; // tolerance 1%

                        // Kiểm tra element có căn right không (x + width gần bằng 100%)
                        const elementRightEdge = x + (w / containerWidth) * 100;
                        isRightAligned = Math.abs(elementRightEdge - 100) <= 1; // tolerance 1%
                    }

                    if (isCentered) {
                        marginLeft = "0";
                        marginRight = "0";
                    } else if (justifySelf === "start") {
                        marginLeft = `${x}%`;
                        marginRight = "auto";
                    } else {
                        if (isRightAligned) {
                            // Trường hợp căn right: margin-right = 0, margin-left = auto
                            marginLeft = "auto";
                            marginRight = "0";
                        } else {
                            // Trường hợp thông thường
                            marginLeft = "auto";
                            const rightMarginPercent = 100 - x - (w / containerWidth) * 100
                            marginRight = isNaN(rightMarginPercent) ? "0%" : `${rightMarginPercent}%`;
                        }
                    }

                    const marginTop = hasTop ? `${y}px` : "0";
                    const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

                    cssRules += `
                        margin: ${margin};`;
                }

                // Thêm rotation nếu có và khác 0
                if (hasRotation) {
                    const rotation = ensureNumber(layout.rotation || 0);
                    if (rotation !== 0) {
                        cssRules += `
                        transform: rotate(${rotation}deg);
                        transform-origin: center center;`;
                    }
                }

                cssRules += `
                    }
                }`;
            });
            return cssRules;
        }
    },

    watch: {
        // colids() {
        //     this.$store.dispatch('history/addStack', {
        //         type: 'columns',
        //         name: '',
        //         action: 'Changed'
        //     });
        // },
        // Gán id cho column mới ngoài computed (deep: 1 -> chỉ track thêm/bớt column,
        // không track cả cây con của từng column).
        columns: {
            immediate: true,
            deep: 1,
            handler(val) {
                if (!Array.isArray(val)) return;
                val.forEach((col) => {
                    if (col && col.id === undefined) {
                        col.id = this.$helpers.randid();
                        col.IDInit = true;
                    }
                });
            }
        },
        stretch: {
            immediate: true,
            handler() {
                this.$helpers.dispatchResize();
            }
        },
        rowSettings: {
            deep: true,
            handler() {
                this.$helpers.dispatchResize();
            }
        },
        'data.style.background': {
            deep: true,
            handler() {
                if(this.data.style?.background?.backgroundnormalmode?.classic && this.data.style?.background?.backgroundnormalmode?.classic['background-image']) {
                    const img_bg = this.data.style.background.backgroundnormalmode.classic['background-image'];
                    if(img_bg.includes('ecom-need-replace')) {
                        this.needReplaceBg = true;
                    }
                    else {
                        this.needReplaceBg = false;
                    }
                }
                else {
                    this.needReplaceBg = false;
                }
            }
        },
        'data.settings.autoplay': {
            deep: false,
            handler(autoplay) {
                if(this.$refs.video) {
                    if(autoplay) {
                        this.$refs.video.load();
                        this.$refs.video.setAttribute('muted', '');
                    } else {
                        this.$refs.video.pause();
                        this.$refs.video.removeAttribute('muted');
                    }
                }
            }
        },

    },

    updated() {
        if (this.row.columns === undefined) {
            this.row.columns = [];
        }
    },

    mounted() {
        if(this.$refs.video && this.data?.settings?.autoplay) {
            this.$refs.video.setAttribute('muted', '');
        }
        if (this.exporting === false) {
            //this.stacks[this.data.id] = this;
            this.instanceStore.register(this.data.id, this)
        }

        if(this.data.style?.background?.backgroundnormalmode?.classic && this.data.style?.background?.backgroundnormalmode?.classic['background-image']) {
            const img_bg = this.data.style.background.backgroundnormalmode.classic['background-image'];
           if(img_bg.includes('ecom-need-replace')) {
            this.needReplaceBg = true;
           }
        }
        if(this.data?.inGrid && this.exporting) {

            const target = this.data;

            if (!target.css) {
                target.css = {};
            }
            if (!target.css.style) {
                target.css.style = {};
            }
            if (!target.css.style.style) {
                target.css.style.style = '';
            }
            target.css.style.style += this.gridLayoutStyle;
        }


    },
    methods: {
        findGridParent() {
            let parent = this.$parent;
            while (parent && parent.$options.name !== "Grid") {
                parent = parent.$parent;
            }
            return parent;
        },
        createStyle() {
            if(this.$refs?.wrapper) {
                this.$helpers.addStyle2Component(this.$refs?.wrapper, this.data);
            }
        },
        handleEnterAdd() {
            const form = this.$refs.settingsAdd.closest('form.ecom-row');
            if(form) form.style.zIndex = 3;
        },
        handleLeaveAdd() {
            const form = this.$refs.settingsAdd.closest('form.ecom-row');
            if(form) form.style.zIndex = 1;
        },
        handleBack2Parent() {
            const breacumbsPath = this?.breadcrumb || this?.$attrs?.breadcrumb;
            if(breacumbsPath) {
                const breacumbs = breacumbsPath.split('/');
                if(breacumbs.length > 0) {
                    const parent = breacumbs.slice(-2, -1);
                    const stack = this.instanceStore.get(parent[0]);
                    //const stack = this.stacks[parent];
                    if(stack) {
                        // Giống editBlock() trong blockMixin: luôn ưu tiên $refs.blockElement
                        // (instance thực sự của row lồng / group element như tabs, slider,
                        // accordion, product box, ...), không chỉ khi nằm trong FlexContainer.
                        const target = stack.$refs?.blockElement || stack;
                        this.$store.commit('builder/setActiveElement', target);
                        this.$store.commit('builder/setEditingElement', target);
                    }
                }
            }
        },
        refresh() {
            this.data.refresh = this.$helpers.randid();
        },
        moveSection(e, position) {
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            const sections = this.$parent.sections.splice(index, 1);
            const newIndex = position === 'prev' ? index -1 : index + 1;
            this.$parent.sections.splice(newIndex, 0, sections[0]);
            const section = this.sections.find((section) => section.id == this.data.id);
            this.$store.dispatch("history/addStack", {
                type: "section",
                index: index,
                data: section,
                section_id: this.data.id,
                action: "delete"
            });
            setTimeout(() => {
                const html = this.idoc().querySelector('html');
                const element =  this.$refs.wrapper;
                const elementRect = element.getBoundingClientRect();
                const absoluteElementTop = elementRect.top + window.pageYOffset;
                const middle = absoluteElementTop - (html.offsetHeight / 2);

                this.scroll(middle);
            }, 100)

        },
        startDragPadding(e, name) {
            this.position = e['clientY'];
            this.paddingPosition = name;
            this.idoc().onmouseup = this.onMouseUp;
            this.idoc().onmousemove = this.onMouseMove;
        },
        onMouseMove(e) {
            const $el = this.$refs.wrapper ?? this.$el,
                    advance = Object.assign({}, this.data.advanced);

            let padding = this.paddingPosition == 'bottom' ? advance?.spacing?.padding?.bottom : advance?.spacing?.padding?.top;
            let space = 0, result = '';
            padding = padding ? parseInt(padding.replace(/[^0-9.]/g, "")) : 0;

            this.idoc().body.style.cursor = 'ns-resize';

            let newP = e['clientY'];
            space = newP - this.position;

            if(Math.abs(space) > 3) {
                this.paddingCurrentVal = padding;
                this.isDragPadding = true;

                let padding_current = space + padding >= 0 ? space + padding : 0;
                if(this.paddingPosition == 'bottom') {
                    $el.style.setProperty('padding-bottom', (padding_current) + 'px', 'important');
                } else {
                    //$el.style.paddingTop = Math.abs(padding_current) + 'px';
                    $el.style.setProperty('padding-top', Math.abs(padding_current) + 'px', 'important');
                }
                this.paddingCurrentVal = result = Math.abs(padding_current);
            }

            this.space = result == 0 || result == '' ? 0 : result + 'px';
        },
        onMouseUp() {
            const currentScreen = this.currentScreen(), currentScreenName = currentScreen.name == 'desktop' ? '' :  currentScreen.name,
                    spacing_res = currentScreenName ? 'spacing__' + currentScreenName : 'spacing';

            const element = this, $el = (element.$refs.wrapper ?? element.$el)?.parentElement,
                    advance = Object.assign({}, this.data.advanced);
            if(!advance.hasOwnProperty(spacing_res)) {
                advance[spacing_res] = {
                    padding: {

                    }
                }
            } else if(!advance[spacing_res].hasOwnProperty('padding')) {
                advance[spacing_res].padding = {}
            }
            const space = this.space;
            this.space = 0;
            if(this.paddingPosition == 'bottom') {
                advance[spacing_res].padding.bottom = space;
            } else {
                advance[spacing_res].padding.top = space;
            }

            Object.assign(this.data.advanced, advance);

            setTimeout(() => {
                $el.style.paddingBottom = null;
                $el.style.paddingTop = null;
            }, 1000)
            this.isDragPadding = false;
            this.paddingCurrentVal = 0;
            this.idoc().body.style.cursor = 'default';
            this.idoc().onmouseup = null;
            this.idoc().onmousemove = null;
        },
        currentScreen(){
            return this.$store.getters['builder/currentScreen'];
        },
        overRow() {
            if (!this.isFullScreen) {
                this.over = true;
                // this.parentsOut();
                clearTimeout(this.timmer);
            }
        },

        outRow() {
            if (!this.isFullScreen) {
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    this.over = false;
                }, 50);
            }
        },

        placehover(e) {
            if (this.isFullScreen || !this.canDrop || !this.isDragging || this.inGroup) {
                return;
            }
            let pos = e.target.classList.contains('placeholder__top') ? 'top' : 'bottom';
            this.$store.commit('builder/setDropTo', this);
            this.$store.commit('builder/setDropPos', pos);
            this.placeholder = pos;
        },

        editRow() {
            // Trường hợp bên trong group thì active group
            if(this._group) {
                const inst = this.instanceStore.get(this._group.data.id);
                this.$store.commit('builder/setActiveElement', inst);
                this.$store.commit('builder/setEditingElement', inst);
                return;
            };
            const editingElement = this.$store.getters['builder/editingElement'];
            if (!editingElement || (editingElement.data.id !== this.data.id)) {
                let inst = this.is == 'section' ? this.$parent : this;
                this.$store.commit('builder/setActiveElement', this);
                this.$store.commit('builder/setEditingElement', this);
                const rect = (this.$refs.wrapper ?? this.$el)?.getBoundingClientRect?.() ?? {};
                const isNearTop = rect.top <= 50; // Kiểm tra nút có sát mép trên màn hình không
                this.shouldApplyMarginBottom = isNearTop;
            }

        },
        edit(){
            this.editRow();
        },

        addSection() {
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.$parent.sections.splice(index, 0, {
                config: {},
                columns: []
            });

            this.$parent.indexofnew = index;
            this.over = false;
        },

        addSectionAfter() {
            // if(this.isLiteMode){
            //     this.openLibrarySection();
            // }else{
            // }
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.$parent.sections.splice(realIndex + 1, 0, {
                config: {},
                columns: []
            });

            this.$parent.indexofnew = realIndex + 1;
            this.over = false;
        },

        openLibrarySection(source){
            // this.$store.dispatch('library/open', {
            //     section: this.$parent,
            //     source: source,
            //     tab: 'sections'
            // });
            this.$store.dispatch('library/initAsync');
            this.$store.dispatch('library/setInsert', {
                isOpen: true,
                type: 'library',
            });
        },

        refreshCols() {

            if (this.columns.length === 0) {
                this.$parent.$parent[this.is == 'row' ? 'blocks' : 'sections']?.splice(
                    this.$parent.index,
                    1
                );
            }

            this.columns.forEach((c) => {
                c.width =(100 / this.columns.length).toFixed(10).slice(0, -8);
                c.settings.width = c.width+'%';
            });

            //this.row.refresh = this.$helpers.randid();

            this.dispatchResize();
        },

        duplicate() {
            let data = this.$helpers.generateElementId(this.$parent.cloneData());

            let height = this.$refs.wrapper.offsetHeight;
            if (this.is == 'section') {
                const index = this.stack.findIndex((s) => s.id == this.section_id);
                this.stack.splice(index + 1, 0, data);
                this.$store.dispatch('history/addStack', {
                    type: 'section',
                    index: index + 1,
                    data:  data,
                    section_id: data.id,
                    action: 'add'
                });
            } else if (this.is == 'row') {
                if(this.inGrid) {
                    let clone = JSON.parse(JSON.stringify(this.$parent.cloneData()));
                    const grid = this.findGridParent();
                    if (!grid || !grid.data || !grid.data.blocks) {
                        console.error("Không tìm thấy grid hoặc blocks trong grid");
                        return;
                    }
                    try {

                        // Tạo ID mới
                        clone.id = this.$helpers.randid();

                        // Cập nhật title nếu có
                        if (clone.title) {
                            clone.title = clone.title.replace(/\(([\d]*)\)|$/, (...m) => {
                                if (m[1]) return "(" + (parseInt(m[1]) + 1) + ")";
                                else return "(1)";
                            });
                        }
                        const containerWidth = grid?.containerWidth || grid?.width || 1200;

                        // Cập nhật layout cho tất cả breakpoints với vị trí hợp lý
                        if (clone.layouts) {
                            Object.keys(clone.layouts).forEach((breakpoint) => {
                                if (["desktop", "tablet", "mobile"].includes(breakpoint) && clone.layouts[breakpoint])  {
                                    // Lấy giá trị hiện tại
                                    const currentLeft = parseFloat(clone.layouts[breakpoint].left); // %
                                    const currentWidth = parseFloat(clone.layouts[breakpoint].width); // px
                                    const currentTop = parseFloat(clone.layouts[breakpoint].top); // px

                                    // Tính phần trăm chiếm dụng của width
                                    const widthPercent = (currentWidth / containerWidth) * 100;

                                    // Tính không gian còn lại bên phải
                                    const spaceRight = 100 - (currentLeft + widthPercent);

                                    // Kiểm tra không gian và quyết định dịch chuyển
                                    if (spaceRight >= 2) {
                                        // Nếu bên phải đủ không gian, dịch sang phải 2%
                                        clone.layouts[breakpoint].left = currentLeft + 2;
                                    } else if (currentLeft >= 2) {
                                        // Nếu bên trái đủ không gian, dịch sang trái 2%
                                        clone.layouts[breakpoint].left = currentLeft - 2;
                                    }
                                    // Nếu không đủ không gian bên nào, giữ nguyên vị trí ngang

                                    // Luôn dịch chuyển xuống dưới 20px
                                    clone.layouts[breakpoint].top = currentTop + 20;
                                }
                            });
                        }
                        // Thêm vào blocks
                        const index = grid.data.blocks.findIndex((b) => b.id === this.data.id);
                        if (index > -1) {
                            grid.data.blocks.splice(index + 1, 0, clone);
                        } else {
                            grid.data.blocks.push(clone);
                            grid.handleUndoRedoGridItem(clone, "added");

                        }

                        // Emit sự kiện để cập nhật grid
                        this.eventBus.emit("update-grid-layout", {
                            sectionId: this.section_id,
                            blocks: grid.data.blocks
                        });
                    } catch (error) {
                        console.error("Lỗi khi duplicate:", error);
                    }
                }
                else {
                    this.stack.splice(this.index + 1, 0, data);
                    this.$store.dispatch('history/addStack', {
                        type: 'block',
                        index: this.index + 1,
                        data:  data,
                        section_id: this.section_id,
                        parent_id: this.$parent.parentColumn.data.id,
                        action: 'duplicated'
                    });
                }
            }
            this.scroll(height);
        },

        paste(clipboard) {
            if(!clipboard) {
                return;
            }
            let index = this.stack.findIndex((s) => s.id == this.section_id);
            let data = this.$helpers.copy(clipboard.data);
            data = this.$helpers.generateElementId(data);
            switch (clipboard.is) {
                case 'section':
                case 'grid':
                    if (this.is == 'section') {
                        this.stack.splice(index + 1, 0, data);
                        this.$store.dispatch('history/addStack', {
                            type: 'section',
                            index: index + 1,
                            data:  data,
                            section_id: data.id,
                            action: 'add'
                        });
                        this.scroll(this.$refs.wrapper.offsetHeight);
                    }
                    break;
                case 'column':
                    if (this.columns.length >= 10) {
                        this.notice({
                            message: 'Can not insert more than 10 columns in a ' + this.is,
                            type: 'error'
                        });
                    } else {
                        index = this.columns.length;
                        this.columns.splice(index, 0, data);
                        this.$store.dispatch('history/addStack', {
                            type: 'Column',
                            index: index,
                            data:  data,
                            section_id: this.is == 'row' ? this.section_id : this.data.id,
                            parent_id: this.data.id,
                            action: 'duplicated',
                        });
                        this.refreshCols();
                    }
                    break;
                case 'block':
                case 'blockFlex':
                    let parent_id = this.data.columns[0].id;
                    if ((data.row || data.group) && this.is == 'row' && !this.inGrid) {
                        index = this.$parent.index + 1;
                        parent_id = this.$parent.parentColumn.data.id;
                        this.stack.splice(index, 0, data);
                    } else {
                        index = this.columns[0].blocks.length;
                        this.columns[0].blocks.push(data);
                    }
                    this.$store.dispatch('history/addStack', {
                        type: 'block',
                        index: index,
                        data:  data,
                        section_id: this.section_id ,
                        parent_id: parent_id,
                        action: 'duplicated',
                    });
                    this.scroll(this.$refs.wrapper.offsetHeight / 2);
                    break;
            }
        },

        insertCol() {
            if (this.columns.length >= 10) {
                this.notice({
                    message: 'Can not insert more than 10 columns in a row',
                    type: 'error'
                });

            } else {
                let id = this.$helpers.randid();
                this.columns.push({
                    width: Math.round(100 / (this.columns.length + 1)),
                    settings: {
                        width: '50%'
                    },
                    blocks: [],
                    id: id
                });
                let realIndex= this.stack.findIndex((s) => s.id == id),
                    new_index = realIndex > -1 ? realIndex : this.index;
                //History
                let section = this.is == 'row'  ? this.sections.find(s => s.id == this.section_id) : this.stack[new_index];
                this.$store.dispatch('history/addStack', {
                        type: 'column',
                        id:  id,
                        parent_id: section.id,
                        action: 'insertColumn'
                    });
                this.refreshCols();
            }
        },

        dropOut(moved = true) {
            if (this.data.id == this.editingElement?.data?.id) {
                setTimeout(() => {
                    this.$store.dispatch('builder/setEditingElement', null);
                }, 50);
            }
            let id = this.data.id;
            if(this?.is == 'row' && this?.deep >= 2) {
                id = this.$parent?.data?.id;
            }

            let realIndex= this.stack.findIndex((s) => s.id == id),
                new_index = realIndex > -1 ? realIndex : this.index;
            //History
            let section = this.is == 'row'  ? this.sections.find(s => s.id == this.section_id) : this.stack[new_index];

            if(section) {
                if(this.is == 'section') {
                    this.$store.dispatch('history/addStack', {
                        type: 'section',
                        index: new_index,
                        data:  section,
                        section_id: section.id,
                        action: 'delete'
                    });
                }
                else {
                    let { parent_id, index } = getIdParentAndIndex(this.$parent);
                    this.$store.dispatch('history/addStack', {
                        type: 'Block',
                        index: new_index,
                        data:  this.$parent.data,
                        section_id: this.section_id,
                        parent_id: parent_id,
                        action: moved ? 'moved' : 'deleted'
                    });
                }
            }
            return this.stack.splice(new_index, 1)[0];

        },

        dropIn(current, pos) {
            const index = this.stack.findIndex((s) => s.id == this.section_id);
            if (this.is == 'section') {
                const dropData = current.dropOut();
                if (dropData?.isLibrarySection) {
                    // onDragEnd maps dropPos as: 'right'→1, anything else→0.
                    // 'bottom' becomes 0, so pos always arrives as 0 for section drags.
                    // Read dropPos directly from the store to correctly distinguish top vs bottom.
                    const insertOffset = this.dropPos === 'bottom' ? 1 : 0;
                    this.$store.dispatch('library/insertPost', {
                        id: dropData.id,
                        dragInsertIndex: index + insertOffset
                    });
                } else {
                    this.stack.splice(index + pos, 0, dropData);
                }
            }
        }
    }
};
</script>
