// GridItem.vue - Fixed TypeScript version
<template>
    <div
        ref="item"
        :data-id="i"
        class="ecom-grid-item ecom-grid-item-content no-touch"
        :class="[
            classObj,
            {
                'ecom-rotating-item': parent?.isRotatingSelection && isInSelection,
                'ecom-grid-row': options?.isRow || group
            }
        ]"
        :style="[computedStyle, dragResizeStyle]"
        @mouseover="handleMouseEnter"
        @mouseleave="handleMouseLeave"
        @mousemove="handleMouseMove"
        @mousedown="dragDropHandler?.handleElementMouseDown"
    >
        <slot></slot>
        <template v-if="resizableAndNotStatic">
            <template v-if="options?.resize?.conner && !inGroup">
                <span
                    class="ecom-grid-resizable-handle dir-bottom-left"
                    @mousedown.stop="startResize($event, 'sw')"
                ></span>
                <span
                    class="ecom-grid-resizable-handle dir-bottom-right"
                    @mousedown.stop="startResize($event, 'se')"
                ></span>
                <span
                    class="ecom-grid-resizable-handle dir-top-left"
                    @mousedown.stop="startResize($event, 'nw')"
                ></span>
                <span
                    class="ecom-grid-resizable-handle dir-top-right"
                    @mousedown.stop="startResize($event, 'ne')"
                ></span>
            </template>
            <template v-if="options?.resize?.y && !inGroup">
                <span
                    class="ecom-grid-resizable-handle dir-bottom-center"
                    @mousedown.stop="startResize($event, 's')"
                ></span>
                <span
                    class="ecom-grid-resizable-handle dir-top-center"
                    @mousedown.stop="startResize($event, 'n')"
                ></span>
            </template>
            <template v-if="options?.resize?.x && !inGroup">
                <span
                    class="ecom-grid-resizable-handle dir-left-center"
                    @mousedown.stop="startResize($event, 'w')"
                ></span>
                <span
                    class="ecom-grid-resizable-handle dir-right-center"
                    @mousedown.stop="startResize($event, 'e')"
                ></span>
            </template>
            <span
                v-show="!isDragging && !isResizing && !inGroup && !isItemLocked"
                class="ecom-grid-rotate-handle"
                @mousedown.stop="rotateHandler?.startRotate($event)"
            >
                <EcomIcon class="ecom-grid-rotate-icon" :source="icons.rotate" />
                <span v-show="isShowingRotateValue" class="rotation-value"
                    >{{ Math.round(innerRotation) }}°</span
                >
            </span>
        </template>
    </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from "vue";
import { getDocumentDir } from "../../helpers/DOM";
import { mapGetters } from "vuex";
// @ts-ignore
import { rotate_icon, DragDropMajor } from "@/assets/icons";
import { ensureNumericValue, addUnit, widthPxCalculate } from "../../helpers/utils";
import { gridDebug, gridDebugError } from "../../helpers/debug";
import { DragDropHandler } from "./DragDropHandler";
import { ResizeHandler } from "./ResizeHandler";
import { RotateHandler } from "./RotateHandler";
import { KeyboardHandler } from "./KeyboardHandler";
import type {
    DragStartPosition,
    DragMouseStartPosition,
    DifferenceMouseItem,
    DragPosition,
    ResizeInitialState,
    TextData,
    KeyboardState,
} from "./types";

interface GridItemOptions {
    resize?: {
        conner?: boolean;
        x?: boolean;
        y?: boolean;
    };
    ratioSize?: boolean;
    autoHeight?: boolean;
    changeFontSize?: {
        className: string;
        nameStyle?: string;
    } | null;
    nameStyleSize?: {
        name: string;
        widthName: string;
        heightName: string;
    };
    isRow?: boolean;
}

export default defineComponent({
    name: "GridItem",
    emits: [
        "resized",
        "resizing",
        "resizeend",
        "rotated",
        "rotate",
        "dragstart",
        "dragmove",
        "dragend",
        "moved",
        "zindexed",
        "move",
        "containerSizeUpdated"
    ],
    props: {
        sectionId: {
            type: String,
            required: false,
            default: null
        },
        isDraggable: {
            type: Boolean as PropType<boolean | null>,
            required: false,
            default: null
        },
        isResizable: {
            type: Boolean as PropType<boolean | null>,
            required: false,
            default: null
        },
        static: {
            type: Boolean,
            required: false,
            default: false
        },
        minH: {
            type: Number,
            required: false,
            default: 1
        },
        minW: {
            type: Number,
            required: false,
            default: 1
        },
        maxH: {
            type: Number,
            required: false,
            default: Infinity
        },
        maxW: {
            type: Number,
            required: false,
            default: Infinity
        },
        // Position in percentage from the left (0-100%)
        left: {
            type: [String, Number] as PropType<string | number>,
            required: true
        },
        // Position in pixels from the top
        top: {
            type: [String, Number] as PropType<string | number>,
            required: true
        },
        // Width in percentage (0-100%)
        width: {
            type: [String, Number] as PropType<string | number>,
            required: true
        },
        // Height in pixels
        height: {
            type: [String, Number] as PropType<string | number>,
            required: false
        },
        rotation: {
            type: Number,
            required: false,
            default: 0
        },
        zindex: {
            type: [String, Number] as PropType<string | number>,
            required: false,
            default: null
        },
        i: {
            type: [String, Number] as PropType<string | number>,
            required: true
        },
        center: {
            type: Boolean,
            required: false,
            default: false
        },
        options: {
            type: Object as PropType<GridItemOptions>,
            required: false,
            default: (): GridItemOptions => ({
                resize: {
                    conner: true,
                    x: true,
                    y: true
                },
                ratioSize: true,
                autoHeight: false,
                changeFontSize: null
            })
        },
        dragIgnoreFrom: {
            type: String,
            required: false,
            default: "[data-stopdrag]"
        },
        dragAllowFrom: {
            type: String,
            required: false,
            default: null
        },
        resizeIgnoreFrom: {
            type: String,
            required: false,
            default: "a, button"
        },
        inGroup: {
            type: Boolean,
            required: false,
            default: false
        },
        group: {
            type: Boolean,
            required: false,
            default: false
        },
        isGuideLine: {
            type: Boolean,
            required: false,
            default: false
        },
        gridContainerWidth: {
            type: Number,
            required: false,
            default: 1200
        },
        isItemLocked: {
            type: Boolean,
            required: false,
            default: false
        }
    },
    inject: ["eventBus", "instanceStore", "exporting"],
    data() {
        return {
            icons: {
                rotate: rotate_icon,
                DragDropMajor
            },
            dragResizeStyle: null as Record<string, any> | null,
            isShowingRotateValue: false,
            draggable: null as boolean | null,
            resizable: null as boolean | null,
            useCssTransforms: true,
            _dragRAF: null as number | null,
            _resizeRAF: null as number | null,
            _styleRAF: null as number | null,
            // Interaction state
            isDragging: false,
            dragging: null as DragPosition | null,
            isResizing: false,
            resizing: null,
            isMouseMoved: false,
            isResizingPrepared: false,

            // Style and state
            innerStyle: {} as Record<string, any>,
            rtl: false,

            // Values for each property
            innerLeft: this.left,
            innerTop: this.top,
            innerWidth: this.width,
            innerHeight: this.height,
            innerZindex:
                this.zindex === "" || this.zindex === null || this.zindex === undefined
                    ? "inherit"
                    : this.zindex,
            leftOld: this.left,
            topOld: this.top,
            widthOld: this.width,
            heightOld: this.height,
            innerRotation: this.rotation,
            isMouseEnter: false,
            initialRotation: 0,
            initialAngle: 0,
            isRotating: false,

            // Drag state
            dragStartPosition: null as DragStartPosition | null,
            dragMouseStartPosition: null as DragMouseStartPosition | null,
            lastSectionId: null as string | null,
            // Event flags
            timmer: null as number | null,
            offsetDropOut: {
                x: 0,
                y: 0
            },
            _initialTextData: null as TextData | null,
            _aspectRatio: 0,
            isNormalZoom: true,
            isOutsideContainer: false, // Cờ đánh dấu khi item hoàn toàn nằm ngoài container
            isVisible: true, // Trạng thái hiển thị của grid item gốc
            containerHeight: 600, // Default value, will be updated
            resizeDirection: null as string | null,
            scaleRatio: 1,
            delayUpdateWidth: false,
            keyboardState: {
                isKeyPressed: false,
                currentKey: null,
                moveInterval: null,
                moveTimeout: null,
                initialDelay: 500, // Delay trước khi bắt đầu di chuyển liên tục (ms)
                repeatDelay: 50, // Thời gian giữa các lần di chuyển khi giữ phím (ms)
                isListening: false // Trạng thái listening để tránh duplicate listeners
            } as KeyboardState,
            isUpdatingFromResize: false,
            timeoutUpdateGridSize: null as ReturnType<typeof setTimeout> | null,
            timeoutChangeFontSize: null as ReturnType<typeof setTimeout> | null,
            resizeObserver: null as ResizeObserver | null,
            dragDropHandler: null as DragDropHandler | null,
            differenceMouseItem: null as DifferenceMouseItem | null,
            previousLeft: 0,
            previousTop: 0,
            isDraggingPrepared: false,
            isScreenSyncing: false,
            lastAutoHeightTrigger: "init",
            resizeHandler: null as ResizeHandler | null,
            rotateHandler: null as RotateHandler | null,
            keyboardHandler: null as KeyboardHandler | null,
            resizeInitialState: null as ResizeInitialState | null,
            _currentResizeValues: null as any
        };
    },
    created() {
        if ((this as any).exporting) return;

        const self = this;

        (self as any).setDraggableHandler = function (isDraggable: boolean) {
            if (self.isDraggable === null) {
                self.draggable = isDraggable;
            }
        };

        (self as any).setResizableHandler = function (isResizable: boolean) {
            if (self.isResizable === null) {
                self.resizable = isResizable;
            }
        };

        (self as any).directionchangeHandler = () => {
            this.rtl = getDocumentDir() === "rtl";
        };

        (this as any).eventBus.on("compact", (self as any).compactHandler);
        (this as any).eventBus.on("setDraggable", (self as any).setDraggableHandler);
        (this as any).eventBus.on("setResizable", (self as any).setResizableHandler);
        (this as any).eventBus.on("directionchange", (self as any).directionchangeHandler);

        this.rtl = getDocumentDir() === "rtl";
    },
    beforeUnmount() {
        if ((this as any).exporting) return;

        const self = this;
        // Remove listeners
        (this as any).eventBus.off("compact", (self as any).compactHandler);
        (this as any).eventBus.off("setDraggable", (self as any).setDraggableHandler);
        (this as any).eventBus.off("setResizable", (self as any).setResizableHandler);
        (this as any).eventBus.off("directionchange", (self as any).directionchangeHandler);
        (this as any).eventBus.off("update-grid-item", this.handleUpdateGridItem);
        window.removeEventListener("resize", this.updateScaleRatio);


        if (this.dragDropHandler) {
            this.dragDropHandler.destroy();
            this.dragDropHandler = null;
        }
        if (this.resizeHandler) {
            this.resizeHandler.destroy();
            this.resizeHandler = null;
        }
        if (this.rotateHandler) {
            this.rotateHandler.destroy();
            this.rotateHandler = null;
        }
        if (this.keyboardHandler) {
            this.keyboardHandler.destroy();
            this.keyboardHandler = null;
        }
        // Đảm bảo cancel tất cả animation frames
        if (this._dragRAF) {
            cancelAnimationFrame(this._dragRAF);
            this._dragRAF = null;
        }
        if (this._resizeRAF) {
            cancelAnimationFrame(this._resizeRAF);
            this._resizeRAF = null;
        }
        if (this._styleRAF) {
            cancelAnimationFrame(this._styleRAF);
            this._styleRAF = null;
        }
        this.destroyResizeObserver();
    },
    mounted() {
        // Giữ nguyên code hiện tại
        if (this.isDraggable === null) {
            this.draggable = (this.parent as any)?.isDraggable;
        } else {
            this.draggable = this.isDraggable;
        }

        if (this.isResizable === null) {
            this.resizable = (this.parent as any)?.isResizable;
        } else {
            this.resizable = this.isResizable;
        }

        this.useCssTransforms = (this.parent as any)?.useCssTransforms;

        if ((this as any).exporting) return;

        this.initializeDragDropHandler();
        this.initializeResizeHandler();
        this.initializeRotateHandler();
        this.initializeKeyboardHandler();

        // Cập nhật tỷ lệ scale
        this.updateScaleRatio();
        this.widthOld = this.innerWidth;
        this.heightOld = this.innerHeight;
        // Thêm sự kiện lắng nghe khi scale thay đổi
        window.addEventListener("resize", this.updateScaleRatio);

        (this as any).eventBus.on("update-grid-item", this.handleUpdateGridItem);
        // Delay initialization to ensure DOM is ready
        this.$nextTick(() => {
            setTimeout(() => {
                this.updateGridSize();
                this.initResizeObserver();
            }, 300);
            setTimeout(() => {
                this.keyboardHandler?.addKeyboardListeners();
            }, 100); // Delay 100ms để tránh xung đột với extension
        });
    },
    activated() {
        if (!(this as any).exporting) {
            this.$nextTick(() => {
                this.keyboardHandler?.ensureKeyboardListeners();
            });
        }
    },

    // Thêm deactivated hook
    deactivated() {
        this.keyboardHandler?.stopKeyboardMove();
        this.keyboardHandler?.removeKeyboardListeners();
    },
    computed: {
        hasImgElement(): boolean {
            return !!(this.$refs.item as HTMLElement)?.querySelector(".ecom-base-image");
        },
        isFullScreen(): boolean {
            return (this.$store as any).getters["builder/isFullScreen"];
        },
        locked(): boolean {
            return (this.$store as any).getters["builder/editorConfigs"]?.locked;
        },
        autoSnap(): boolean {
            return (this.$store as any).getters["builder/editorConfigs"]?.autoSnap;
        },
        isPercentWidth(): boolean {
            return typeof this.innerWidth === "string" && this.innerWidth.includes("%");
        },
        currentScreen(): string {
            return (this.$store as any).getters["builder/screen"];
        },
        parent(): any {
            return this.inGroup ? this.$parent?.$parent : this.$parent;
        },
        isGroupDragging(): boolean {
            return this.parent?.isGroupDragging;
        },
        classObj(): Record<string, boolean> {
            return {
                "ecom-grid-resizable": this.resizableAndNotStatic,
                static: this.static,
                resizing: this.isResizing,
                "ecom-grid-draggable-dragging": this.isDragging,
                "ecom-pointer-events-none": this.isDragging,
                cssTransforms: this.useCssTransforms,
                "ecom-current-section-drag": this.sectionDrag,
                "ecom-grid-active":
                    this.gridActive ||
                    (!this.inGroup && this.isMouseEnter) ||
                    (this.isDragging && !this.isGroupDragging),
                "disable-userselect": this.isDragging,
                "no-touch": this.isAndroid && this.draggableOrResizableAndNotStatic,
                "ecom-grid-current-edit": this.isEditing
            };
        },

        computedStyle(): Record<string, any> {
            if (this.isResizing && this.dragResizeStyle) {
                return {}; // Trả về object rỗng để không ghi đè dragResizeStyle
            }
            // Tính toán các giá trị từ state
            const x = ensureNumericValue(this.innerLeft); // Giá trị phần trăm từ trái
            const y = ensureNumericValue(this.innerTop); // Giá trị pixel từ trên xuống
            const w = this.isPercentWidth
                ? (ensureNumericValue(this.innerWidth) / 100) * this.gridContainerWidth
                : ensureNumericValue(this.innerWidth); // Width in pixels
            const h = ensureNumericValue(this.innerHeight); // Height in pixels

            const rotation = this.innerRotation || 0; // Rotation in degrees

            // Xử lý khác biệt cho item trong group
            if (this.inGroup) {
                let groupWrapper = this.$parent;
                while (groupWrapper && (groupWrapper as any).$options.name !== "GroupWrapper") {
                    groupWrapper = groupWrapper.$parent;
                }

                if (groupWrapper && (groupWrapper as any).bounds) {
                    // Lấy chiều rộng container để tính toán
                    const containerWidth = this.parent.containerWidth;
                    const originalLeft = (this.$refs.item as HTMLElement)
                        ? parseFloat((this.$refs.item as HTMLElement).getAttribute("data-original-left") || "0")
                        : x;
                    const originalTop = (this.$refs.item as HTMLElement)
                        ? parseFloat((this.$refs.item as HTMLElement).getAttribute("data-original-top") || "0")
                        : y;

                    // Sử dụng giá trị data-original nếu hợp lệ, nếu không thì sử dụng innerLeft/innerTop
                    const effectiveLeft = !isNaN(originalLeft) ? originalLeft : x;
                    const effectiveTop = !isNaN(originalTop) ? originalTop : y;

                    // Chuyển đổi vị trí % thành px
                    const xPx = (effectiveLeft / 100) * containerWidth;

                    // Lấy vị trí của group wrapper
                    const groupX = (groupWrapper as any).bounds.x; // % từ trái
                    const groupY = (groupWrapper as any).bounds.y; // px từ trên

                    // Chuyển đổi vị trí % của group thành px
                    const groupXPx = (groupX / 100) * containerWidth;

                    // Tính toán vị trí tương đối so với group theo px
                    const relativeXPx = xPx - groupXPx;
                    const relativeYPx = effectiveTop - groupY;

                    // Khi ở trong group, sử dụng position absolute với tọa độ tương đối
                    return {
                        position: "absolute",
                        left: `${relativeXPx}px`, // Dùng px thay vì %
                        top: `${relativeYPx}px`,
                        width: `${w}px`,
                        height: this.options?.autoHeight ? "auto" : `${h}px`,
                        transform: rotation !== 0 ? `rotate(${rotation}deg)` : "none",
                        WebkitTransform: rotation !== 0 ? `rotate(${rotation}deg)` : "none",
                        transformOrigin: "center center",
                        zIndex:
                            this.innerZindex ||
                            (this.isDragging ? 1000 : this.isResizing ? 900 : 0),
                        ...this.innerStyle
                    };
                }
            }

            // Kiểm tra xem element có ở center không
            const elementCenterX = x + (w / this.gridContainerWidth) * 100 / 2;
            const isCentered = this.center ? true :  this.autoSnap ? Math.abs(elementCenterX - 50) < 1 : false ; // tolerance 1%
            const justifySelf = isCentered ? "center" : (x < 50 ? "start" : "end");
            const alignSelf = "start"; // Luôn align từ trên xuống

            // Tính toán margins
            let marginLeft: string, marginRight: string;
            if (justifySelf === "center") {
                marginLeft = "auto";
                marginRight = "auto";
            } else if (justifySelf === "start") {
                marginLeft = `${x}%`;
                marginRight = "auto";
            } else {
                marginLeft = "auto";
                const rightMarginPercent = 100 - x - (w / this.gridContainerWidth) * 100;
                marginRight = isNaN(rightMarginPercent) ? "0%" : `${rightMarginPercent}%`;
            }

            // Margin-top luôn tính bằng px
            const marginTop = `${y}px`;

            // Gộp margin thành một thuộc tính
            const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

            // Tạo transform style cho rotation
            let transform = "none";
            if (rotation !== 0) {
                transform = `rotate(${rotation}deg)`;
            }

            // Trả về style object
            return {
                justifySelf: justifySelf,
                alignSelf: alignSelf,
                width:
                    typeof this.innerWidth === "string" && this.innerWidth.includes("%")
                        ? this.innerWidth
                        : `${w}px`,
                height: this.options?.autoHeight ? "auto" : `${h}px`,
                margin: margin,
                transform: transform,
                WebkitTransform: transform,
               // zIndex: this.isDragging || this.isResizing ? 1000 : this.innerZindex || "inherit",
               zIndex: this.innerZindex || "inherit",
                ...this.innerStyle
            };
        },

        dropTo(): any {
            return (this.$store as any).getters["builder/dropTo"];
        },
        gridActive(): boolean {
            return (this.activeElements && this.activeElements[this.i as string]) || this.isEditing;
        },
        resizableAndNotStatic(): boolean {
            return !!this.resizable && !this.static && !this.isItemLocked;
        },
        draggableOrResizableAndNotStatic(): boolean {
            return (!!this.draggable || !!this.resizable) && !this.static;
        },
        isAndroid(): boolean {
            return navigator.userAgent.toLowerCase().indexOf("android") !== -1;
        },
        screen(): string {
            return (this.$store as any).getters["builder/screen"];
        },
        idoc(): Document {
            try {
                return (window as any).EComposerBuilder?.contentDocument || document;
            } catch (e) {
                console.log('Error accessing contentDocument:', e);
                return document;
            }
        },
        resizableHandleClass(): string {
            return "ecom-grid-resizable-handle";
        },
        sectionDrag(): boolean {
            let dropTo = this.dropTo;
            if (dropTo && !dropTo.name) dropTo = (this as any).instanceStore.get(dropTo);
            if (!dropTo) return false;
            while (dropTo.$parent) {
                if (dropTo.grid) {
                    break;
                }
                dropTo = dropTo.$parent;
            }
            return dropTo.grid && dropTo.grid.i === this.i;
        },
        isEditing(): boolean {
            return (
                this.editingElement &&
                (this.editingElement?.data?.id === this.i ||
                    (!["block", "column"].includes(this.editingElement.is) &&
                        this.editingElement.$parent.data &&
                        this.editingElement.$parent.data.id === this.i))
            );
        },
        canDrag(): boolean {
            return !!this.draggable && !this.static && this.isNormalZoom;
        },
        isInSelection(): boolean {
            return (
                this.parent &&
                this.parent.hasSelection &&
                this.parent.selectedItems &&
                this.parent.selectedItems.some((item: any) => item.i === this.i)
            );
        },
        ...mapGetters("builder", ["editingElement", "activeElement", "activeElements"])
    },
    watch: {
        isDraggable() {
            this.draggable = this.isDraggable;
        },
        static() {
            // Không cần reinitializeInteract() nữa
        },
        draggable() {
            // Không cần reinitializeInteract() nữa
        },
        isResizable() {
            this.resizable = this.isResizable;
        },
        resizable() {
            // Không cần reinitializeInteract() nữa
        },
        left(val: string | number) {
            if (this.isGuideLine) {
                gridDebug("item", "watch:left-guideline", {
                    itemId: this.i,
                    oldValue: this.innerLeft,
                    newValue: val,
                    sectionId: this.sectionId
                }, this as any);
                this.innerLeft = val;
                this.createStyle();
            }
        },
        width(newVal: string | number) {
            if (!this.isDragging && !this.isResizing) {
                gridDebug("item", "watch:width", {
                    itemId: this.i,
                    oldValue: this.innerWidth,
                    newValue: newVal,
                    source: "watch",
                    sectionId: this.sectionId
                }, this as any);
                this.innerWidth = newVal;
                this.widthOld = newVal;
                this.createStyle();
            }
        },
        height(newVal: string | number) {
            if (!this.isDragging && !this.isResizing) {
                gridDebug("item", "watch:height", {
                    itemId: this.i,
                    oldValue: this.innerHeight,
                    newValue: newVal,
                    source: "watch",
                    sectionId: this.sectionId
                }, this as any);
                this.innerHeight = newVal;
                this.heightOld = newVal;
                this.createStyle();
            }
        },
        rotation(newVal: number) {
            if (!this.isRotating && !this.isDragging) {
                this.innerRotation = newVal;
                this.createStyle();
            }
        },

        minH() {
            // Không cần reinitializeInteract() nữa
        },
        maxH() {
            // Không cần reinitializeInteract() nữa
        },
        minW() {
            // Không cần reinitializeInteract() nữa
        },
        maxW() {
            // Không cần reinitializeInteract() nữa
        },
        currentScreen(val: string, oldVal: string) {
            this.isScreenSyncing = true;
            gridDebug("item", "screen:before-sync", {
                itemId: this.i,
                fromScreen: oldVal,
                toScreen: val,
                left: { old: this.innerLeft, new: this.left },
                top: { old: this.innerTop, new: this.top },
                width: { old: this.innerWidth, new: this.width },
                height: { old: this.innerHeight, new: this.height },
                containerWidth: this.gridContainerWidth
            }, this as any);
            this.innerLeft = this.left;
            this.innerRotation = this.rotation;
            this.innerTop = this.top;
            this.innerWidth = this.width;
            this.innerHeight = this.height;
            this.innerZindex = this.zindex;
            this.widthOld = this.innerWidth;
            this.heightOld = this.innerHeight;
            this.createStyle();
            gridDebug("item", "screen:after-sync", {
                itemId: this.i,
                fromScreen: oldVal,
                toScreen: val,
                innerLeft: this.innerLeft,
                innerTop: this.innerTop,
                innerWidth: this.innerWidth,
                innerHeight: this.innerHeight,
                innerRotation: this.innerRotation,
                innerZindex: this.innerZindex
            }, this as any);
            if (val && oldVal && val !== oldVal) {
                this.delayUpdateWidth = true;
                this.updateGridSize();
                this.$nextTick(() => {
                    setTimeout(() => {
                        this.delayUpdateWidth = false;
                        this.isScreenSyncing = false;
                    }, 300);
                });
            } else {
                this.isScreenSyncing = false;
            }
        },
        inGroup: {
            handler(newValue: boolean, oldValue: boolean) {
                if (newValue !== oldValue) {
                    // Nếu trạng thái inGroup thay đổi, cập nhật lại style
                    this.$nextTick(() => {
                        this.createStyle();

                        // Nếu vừa được add vào group, emit sự kiện để group wrapper cập nhật bounds
                        if (newValue === true) {
                            (this as any).eventBus.emit("item-added-to-group", {
                                itemId: this.i,
                                section_id: this.sectionId
                            });
                        }
                    });
                }
            },
            immediate: true
        },
        gridContainerWidth: {
            handler(newContainerWidth: number, oldContainerWidth: number) {
                return; // Comment tam, vi neu de code nay thi se bi tinh toan sai
            },
            immediate: false
        },
        isEditing: {
            handler(newVal: boolean) {
                this.$nextTick(() => {
                    this.keyboardHandler?.ensureKeyboardListeners();
                    if (!newVal) {
                        this.keyboardHandler?.stopKeyboardMove();
                    }
                });
            },
            immediate: true
        },

        gridActive: {
            handler(newVal: boolean) {
                this.$nextTick(() => {
                    this.keyboardHandler?.ensureKeyboardListeners();
                    if (!newVal) {
                        this.keyboardHandler?.stopKeyboardMove();
                    }
                });
            },
            immediate: true
        }
    },
    methods: {
        initializeKeyboardHandler() {
            const keyboardOptions = {
                enableKeyboard: true,
                initialDelay: 500,
                repeatDelay: 50,
                shiftMultiplier: 5,
                normalStep: 1
            };

            const keyboardEvents = {
                onKeyboardStart: (data: any) => {
                    // Additional keyboard start logic if needed
                },
                onKeyboardMove: (data: any) => {
                    // Additional keyboard move logic if needed
                },
                onKeyboardEnd: (data: any) => {
                    // Additional keyboard end logic if needed
                }
            };

            this.keyboardHandler = new KeyboardHandler(this as any, keyboardOptions, keyboardEvents);
        },

        initializeRotateHandler() {
            const rotateOptions = {
                enableRotate: true,
                snapToAngle: false,
                snapThreshold: 15,
                showRotationValue: true
            };

            const rotateEvents = {
                onRotated: (i: string | number, angle: number) => {
                    // Additional rotate logic if needed
                }
            };

            this.rotateHandler = new RotateHandler(this as any, rotateOptions, rotateEvents);
        },

        initializeResizeHandler() {
            const resizeOptions = {
                ratioSize: this.options?.ratioSize || true,
                autoHeight: this.options?.autoHeight || false,
                changeFontSize: this.options?.changeFontSize || undefined,
                nameStyleSize: this.options?.nameStyleSize || undefined
            };

            const resizeEvents = {
                onResized: (i: string | number, height: number, width: number, left: number, top: number, resizeEnd: boolean) => {
                    // Additional resized logic if needed
                }
            };

            this.resizeHandler = new ResizeHandler(this as any, resizeOptions, resizeEvents);
        },

        initializeDragDropHandler() {
            const dragDropOptions = {
                enableDrag: true,
                enableDrop: true,
                snapToGrid: this.autoSnap,
                snapThreshold: 5
            };

            const dragDropEvents = {
                onDragStart: (data: any) => {
                    // Additional drag start logic if needed
                },
                onDragMove: (data: any) => {
                    // Additional drag move logic if needed
                },
                onDragEnd: (data: any) => {
                    // Additional drag end logic if needed
                },
                onMoved: (i: string | number, left: number, top: number) => {
                    // Additional moved logic if needed
                }
            };

            this.dragDropHandler = new DragDropHandler(this as any, dragDropOptions, dragDropEvents);
        },

        initResizeObserver() {
            if (this.$refs.item && window.ResizeObserver) {
                this.handleUpdateItemHeightAuto("resize-observer:init");
                this.resizeObserver = new ResizeObserver((entries) => {
                    for (const entry of entries) {
                        if (!this.isResizing) {
                            this.handleUpdateItemHeightAuto("resize-observer:callback");
                            this.parent.updateHeight();
                        }
                    }
                });
                this.resizeObserver.observe(this.$refs.item as Element);
            } else {
                console.warn("ResizeObserver không được hỗ trợ");
                this.setupFallback();
            }
        },

        setupFallback() {
            this.handleUpdateItemHeightAuto("resize-fallback:init");

            const resizeHandler = () => {
                this.$nextTick(() => {
                    this.handleUpdateItemHeightAuto("resize-fallback:window-resize");
                });
            };

            window.addEventListener("resize", resizeHandler);
        },

        destroyResizeObserver() {
            if (this.resizeObserver) {
                this.resizeObserver.disconnect();
                this.resizeObserver = null;
            }
        },

        getBodyScale(): number {
            if (!this.idoc || !this.idoc.body) return 1;

            const style = window.getComputedStyle(this.idoc.body);
            const transform = style.transform || style.webkitTransform;

            if (!transform || transform === "none") return 1;

            const matrixMatch = transform.match(/matrix\((.+)\)/);
            if (matrixMatch) {
                const matrix = matrixMatch[1].split(", ").map(parseFloat);
                return matrix[0];
            }

            const scaleMatch = transform.match(/scale\((.+)\)/);
            if (scaleMatch) {
                return parseFloat(scaleMatch[1]);
            }

            return 1;
        },

        updateScaleRatio() {
            this.scaleRatio = this.getBodyScale();
            gridDebug("item", "scale:update", {
                itemId: this.i,
                scaleRatio: this.scaleRatio,
                sectionId: this.sectionId
            }, this as any);
        },

        shouldIgnoreDrag(e: MouseEvent): boolean {
            if (this.dragIgnoreFrom) {
                const closest = (e.target as Element).closest(this.dragIgnoreFrom);
                if (closest) {
                    return true;
                }
            }

            if (this.dragAllowFrom) {
                const closest = (e.target as Element).closest(this.dragAllowFrom);
                if (!closest) {
                    return true;
                }
            }

            return false;
        },

        emitDragEvent(eventType: string, x: number, y: number) {
            if (eventType === "dragstart") {
                this.$emit("dragstart", this.i, x, y);
            } else if (eventType === "dragmove") {
                this.$emit("dragmove", this.i, x, y);
                this.$emit("move", this.i, x, y);
            } else if (eventType === "dragend") {
                this.$emit("dragend", this.i, x, y);
            }

            const sectionId =
                this.dropTo !== null && this.dropTo?.data?.id
                    ? this.dropTo.data.id
                    : this.sectionId;

            let dragEventData: any;
            if (this.lastSectionId && sectionId !== this.lastSectionId) {
                dragEventData = {
                    eventType: "dragend",
                    i: this.i,
                    section_id: this.lastSectionId,
                    x: eventType === "dragend" && !(this.parent as any).over ? this.leftOld : x,
                    y: eventType === "dragend" && !(this.parent as any).over ? this.topOld : y,
                    h: ensureNumericValue(this.innerHeight),
                    w: this.innerWidth,
                    rotation: this.innerRotation
                };
            } else {
                dragEventData = {
                    eventType: eventType,
                    i: this.i,
                    section_id: sectionId,
                    x: eventType === "dragend" && !(this.parent as any).over ? this.leftOld : x,
                    y: eventType === "dragend" && !(this.parent as any).over ? this.topOld : y,
                    h: ensureNumericValue(this.innerHeight),
                    w: this.innerWidth,
                    rotation: this.innerRotation
                };
            }

            this.lastSectionId = sectionId;
            gridDebug("item", "drag-event:emit", {
                itemId: this.i,
                eventType,
                sectionId,
                payload: dragEventData
            }, this as any);
            (this as any).eventBus.emit("dragEvent", dragEventData);
        },

        getTransformStyle(): string {
            if (this.innerRotation !== 0) {
                return `rotate(${this.innerRotation}deg)`;
            }
            return "none";
        },

        updateContainerSize(width?: number) {
            let cwidth = width;
            if (this.$refs.item && (this.$refs.item as HTMLElement).parentElement) {
                const itemElement = this.$refs.item as HTMLElement;
                const gridElement = itemElement.closest(".ecom-grid-layout") as HTMLElement | null;
                const targetElement = gridElement || itemElement.parentElement;
                cwidth = targetElement?.offsetWidth || cwidth;
                this.containerHeight = targetElement?.offsetHeight || this.containerHeight;
            }
            gridDebug("item", "container:update", {
                itemId: this.i,
                containerWidth: cwidth,
                containerHeight: this.containerHeight,
                sectionId: this.sectionId
            }, this as any);
            this.$emit("containerSizeUpdated", cwidth);
        },

        startRotate(e: MouseEvent) {
            if (this.rotateHandler) {
                this.rotateHandler.startRotate(e);
            }
        },

        startResize(e: MouseEvent, direction: string) {
            if (this.resizeHandler) {
                this.resizeHandler.startResize(e, direction);
            }
        },

        updateGridSize() {
            const inst = (this as any).instanceStore.get(this.i);
            if (inst) {
                const screen = this.screen === "desktop" ? "" : "__" + this.screen;
                this.isUpdatingFromResize = true;

                const updateSizeGrid = (target: any) => {
                    if (!target.size_grid) target.size_grid = {};
                    const widthUnit =
                        typeof this.innerWidth === "string" && this.innerWidth.includes("%")
                            ? "%"
                            : "px";

                    target.size_grid["width_grid" + screen] =
                        Math.ceil(ensureNumericValue(this.innerWidth)) + widthUnit;
                    target.size_grid["rotate_grid" + screen] = Math.ceil(
                        ensureNumericValue(this.innerRotation)
                    );

                    if (!this.options?.autoHeight) {
                        target.size_grid["height_grid" + screen] =
                            Math.ceil(ensureNumericValue(this.innerHeight)) + "px";
                    }
                    if (this.options?.nameStyleSize) {
                        const { name, widthName, heightName } = this.options.nameStyleSize;
                        if (target[name]) {
                            if (widthName) {
                                target[name][widthName + screen] =
                                    Math.ceil(ensureNumericValue(this.innerWidth)) + widthUnit;
                            }

                            if (heightName) {
                                target[name][heightName + screen] =
                                    Math.ceil(ensureNumericValue(this.innerHeight)) + "px";
                            }
                        }
                    }
                };

                if (!inst?.data?.row) {
                    if (inst?.data.group) {
                        updateSizeGrid(inst.data.group.style || (inst.data.group.style = {}));
                    } else {
                        updateSizeGrid(inst.data.style || (inst.data.style = {}));
                    }
                } else {
                    updateSizeGrid(inst.data.row.style || (inst.data.row.style = {}));
                }

                setTimeout(() => {
                    this.isUpdatingFromResize = false;
                }, 1000);
                if(this.timeoutUpdateGridSize) {
                    clearTimeout(this.timeoutUpdateGridSize);
                }
                this.timeoutUpdateGridSize = setTimeout(() => {
                    this.isUpdatingFromResize = false;
                }, 500);
                if (
                    this._initialTextData &&
                    this._initialTextData.textEl &&
                    this._initialTextData.newFontSize &&
                    this.options?.changeFontSize?.nameStyle
                ) {
                    const name =
                        this.currentScreen === "desktop"
                            ? "textTypography"
                            : "textTypography__" + this.currentScreen;
                    if (!inst.data.style) {
                        inst.data.style = {};
                    }
                    if (!inst.data.style[this.options.changeFontSize.nameStyle]) {
                        inst.data.style[this.options.changeFontSize.nameStyle] = {};
                    }
                    if (!inst.data.style[this.options.changeFontSize.nameStyle][name]) {
                        inst.data.style[this.options.changeFontSize.nameStyle][name] = {};
                    }
                    inst.data.style[this.options.changeFontSize.nameStyle][name][
                        "font-size"
                    ] = `${this._initialTextData.newFontSize}px`;
                    if(this.timeoutChangeFontSize) {
                        clearTimeout(this.timeoutChangeFontSize);
                    }
                    this.timeoutChangeFontSize = setTimeout(() => {
                        if(this._initialTextData?.textEl) {
                            this._initialTextData.textEl.style.fontSize = ``;
                            this._initialTextData = null;
                        }
                    }, 200);
                }
                if (this.options?.autoHeight) {
                    this.handleUpdateItemHeightAuto("update-grid-size");
                }
            }
        },

        handleMouseEnter() {
            if (this.isFullScreen) return;
            this.isMouseEnter = true;
        },

        handleMouseLeave() {
            this.isMouseEnter = false;
        },

        handleMouseMove(e: MouseEvent) {
            const iframeDoc = (window as any).EComposerBuilder?.contentDocument || document;

            const scrollX = iframeDoc.documentElement.scrollLeft || iframeDoc.body.scrollLeft || 0;
            const scrollY = iframeDoc.documentElement.scrollTop || iframeDoc.body.scrollTop || 0;

            const rect = (this.$refs.item as HTMLElement).getBoundingClientRect();
            const actualLeft = rect.left / this.scaleRatio;
            const actualTop = rect.top / this.scaleRatio;

            this.offsetDropOut = {
                x: e.clientX + scrollX - actualLeft,
                y: e.clientY + scrollY - actualTop
            };
        },

        setEditingElement(e: MouseEvent) {
            (this.parent as any).$parent.justDragged = true;
            const inst = (this as any).instanceStore.get(this.i);
            if (inst) {
                const blockElement = !["block", "row", "blocks"].includes(inst.is)
                    ? inst
                    : inst.$refs.blockElement;
                (this.$store as any).commit("builder/setEditingElement", blockElement);
                if (
                    (this as any).$helpers &&
                    (this as any).$helpers.isCommaPressed &&
                    (this as any).$helpers.isCommaPressed(e)
                ) {
                    (this.$store as any).commit("builder/setActiveElements", {
                        blockElement: blockElement,
                        activeElement: this.activeElement,
                        isCommaPressed: true
                    });
                }
            }
            setTimeout(() => {
                (this.parent as any).$parent.justDragged = false;
            }, 300);
        },

        createStyle() {
            if ((this as any)._isFirstRender === undefined) {
                (this as any)._isFirstRender = true;
            }

            if (this.isDragging || this.isResizing || this.inGroup || (this as any)._isFirstRender) {
                this._styleRAF = requestAnimationFrame(() => {
                    this._createStyleInternal();
                    this._styleRAF = null;
                });
                if ((this as any)._isFirstRender) {
                    (this as any)._isFirstRender = false;
                }
            } else {
                if (this._styleRAF) {
                    cancelAnimationFrame(this._styleRAF);
                }
                this._styleRAF = requestAnimationFrame(() => {
                    this._createStyleInternal();
                    this._styleRAF = null;
                });
            }
        },

        _createStyleInternal() {
            if (this.dragResizeStyle) return;

            this.innerStyle = {};

            if (this.isDragging && this.dragging) {
                // Handle dragging state
            } else if (!this.isResizing) {
                if (this.inGroup && this.$refs.item) {
                    const originalLeft = (this.$refs.item as HTMLElement).getAttribute("data-original-left");
                    const originalTop = (this.$refs.item as HTMLElement).getAttribute("data-original-top");

                    if (originalLeft && !isNaN(parseFloat(originalLeft))) {
                        this.innerLeft = parseFloat(originalLeft);
                    }

                    if (originalTop && !isNaN(parseFloat(originalTop))) {
                        this.innerTop = parseFloat(originalTop);
                    }
                }

                if (this.innerWidth !== undefined) {
                    if (typeof this.innerWidth === "string") {
                        if (/\d(px|%|rem|em|vh|vw)$/.test(this.innerWidth)) {
                            this.innerStyle.width = this.inGroup
                                ? this.innerWidth === '100%' ? '100%' : widthPxCalculate(
                                      ensureNumericValue(this.innerWidth),
                                      this.gridContainerWidth
                                  )
                                : this.innerWidth;
                        } else {
                            this.innerStyle.width = this.innerWidth + "px";
                        }
                    } else {
                        this.innerStyle.width = this.innerWidth + "px";
                    }
                }

                if (this.innerHeight !== undefined) {
                    if (this.options?.autoHeight) {
                        this.innerStyle.height = "auto";
                    } else if (typeof this.innerHeight === "string") {
                        if (/\d(px|%|rem|em|vh|vw)$/.test(this.innerHeight)) {
                            this.innerStyle.height = this.innerHeight;
                        } else {
                            this.innerStyle.height = this.innerHeight + "px";
                        }
                    } else {
                        this.innerStyle.height = this.innerHeight + "px";
                    }
                }
            }
        },

        zoomChangedHandler(data: any) {
            this.isNormalZoom = data.isNormal;
        },

        handleUpdateGridItem(data: any) {
            if (data.id === this.i) {
                if (data.left !== undefined) {
                    this.innerLeft = data.left;
                }
                if (data.top !== undefined) {
                    this.innerTop = data.top;
                }
                if (data.width !== undefined) {
                    this.innerWidth = data.width;
                }
                if (data.height) {
                    this.innerHeight = data.height;
                }
                if (data.rotation !== undefined) {
                    this.innerRotation = data.rotation;
                }
                this.innerZindex = data.zindex;
                this.createStyle();
                if (
                    this.options?.changeFontSize &&
                    (data.direction === "se" ||
                        data.direction === "sw" ||
                        data.direction === "ne" ||
                        data.direction === "nw" ||
                        data.unRedo == true)
                ) {
                    // Handle font size change logic directly here since handleFontSizeChange doesn't exist
                    // This logic was moved from the non-existent method
                    this.timeoutUpdateGridSize = setTimeout(() => {
                        this.isUpdatingFromResize = false;
                    }, 500);
                    const textEl = (this.$refs.item as HTMLElement)?.querySelector(this.options.changeFontSize.className);
                    if (textEl) {
                        if (textEl) {
                        // Lưu trữ dữ liệu ban đầu nếu chưa có
                        if (!this._initialTextData) {
                            const textElHTMLElement = textEl as HTMLElement;
                            const computedStyle = window.getComputedStyle(textElHTMLElement);
                            const initialFontSize = parseFloat(computedStyle.fontSize);
                            const initialWidth = textElHTMLElement.offsetWidth / this.scaleRatio;
                            const initialHeight = textElHTMLElement.offsetHeight / this.scaleRatio;
                            const lineHeight = parseFloat(computedStyle.lineHeight);
                            const isMultiLine = textElHTMLElement.offsetHeight > lineHeight * 1.5;

                            this._initialTextData = {
                                textEl: textElHTMLElement,
                                fontSize: initialFontSize,
                                width: initialWidth,
                                height: initialHeight,
                                isMultiLine
                            };
                        }

                        if (this._initialTextData) {
                            const { fontSize, width, isMultiLine, height } = this._initialTextData;
                            const textElHTMLElement = textEl as HTMLElement;
                            let newFontSize = 16;
                            if (isMultiLine) {
                                // Với text nhiều dòng: scale theo width và height
                                const widthRatio = ensureNumericValue(String(data.width)) / width / this.scaleRatio;
                                const heightRatio = ensureNumericValue(String(data.height)) / height / this.scaleRatio;
                                const scaleFactor = Math.min(widthRatio, heightRatio);
                                newFontSize = Math.max(
                                    parseFloat((fontSize * scaleFactor).toFixed(2)),
                                    8
                                ); // Minimum 8px
                                textElHTMLElement.style.fontSize = `${newFontSize}px`;
                            } else {
                                // Với text 1 dòng: scale chỉ theo width
                                const widthRatio = ensureNumericValue(String(data.width)) / width / this.scaleRatio;
                                newFontSize = Math.max(
                                    parseFloat((fontSize * widthRatio).toFixed(2)),
                                    8
                                ); // Minimum 8px
                                textElHTMLElement.style.fontSize = `${newFontSize}px`;
                            }
                            this._initialTextData.newFontSize = newFontSize;
                        }}
                    }
                }
                this.updateGridSize();
            }
        },

        handleUpdateItemHeightAuto(trigger: string = "unknown") {
            this.lastAutoHeightTrigger = trigger;
            const measuredHeight = this.$refs.item
                ? (this.$refs.item as HTMLElement).getBoundingClientRect().height / this.scaleRatio
                : null;
            const currentHeight = ensureNumericValue(this.innerHeight);
            const deltaHeight = measuredHeight === null ? null : measuredHeight - currentHeight;

            gridDebug("item", "auto-height:check", {
                itemId: this.i,
                sectionId: this.sectionId,
                trigger,
                isScreenSyncing: this.isScreenSyncing,
                delayUpdateWidth: this.delayUpdateWidth,
                isDragging: this.isDragging,
                isResizing: this.isResizing,
                isUpdatingFromResize: this.isUpdatingFromResize,
                currentHeight,
                measuredHeight,
                deltaHeight
            }, this as any);

            if (
                this.options?.autoHeight &&
                this.$refs.item &&
                parseInt(ensureNumericValue(this.innerHeight).toString()) !==
                    parseInt(((this.$refs.item as HTMLElement).getBoundingClientRect().height / this.scaleRatio).toString())
            ) {
                this.innerHeight = (this.$refs.item as HTMLElement).getBoundingClientRect().height / this.scaleRatio;
                (this.$refs.item as HTMLElement).setAttribute("data-original-height", this.innerHeight.toString());
                gridDebug("item", "auto-height:emit-resized", {
                    itemId: this.i,
                    sectionId: this.sectionId,
                    trigger,
                    isScreenSyncing: this.isScreenSyncing,
                    delayUpdateWidth: this.delayUpdateWidth,
                    isDragging: this.isDragging,
                    isResizing: this.isResizing,
                    isUpdatingFromResize: this.isUpdatingFromResize,
                    nextHeight: this.innerHeight,
                    currentWidth: this.innerWidth
                }, this as any);
                this.$emit("resized", this.i, this.innerHeight, this.innerWidth);
            }
        },
    }
});
</script>