import { mapGetters } from "vuex";

// Performance optimization constants
const DEBOUNCE_FAST = 100;        // When few elements (< 3)
const DEBOUNCE_NORMAL = 200;      // When moderate elements (3-10)
const DEBOUNCE_SLOW = 300;        // When many elements (> 10)
const MAX_ELEMENTS_PER_BATCH = 5; // Maximum elements per request
const REQUEST_TIMEOUT = 15000;     // 15 seconds timeout
const SECTION_DEBOUNCE = 150;      // Debounce for section queue (reduced from 200ms)

// Render bị 503 khi Shopify tạm thời bị Cloudflare throttle (server đánh dấu retryable).
// Tự render lại vài lần phía client, giãn cách + jitter, để section không gãy giữa lúc edit.
const RENDER_RETRY_MAX = 2;        // số lần render lại tối đa khi gặp 503 throttle
const RENDER_RETRY_BASE_MS = 2500; // chờ trước lần thử lại đầu tiên
const RENDER_RETRY_STEP_MS = 2000; // mỗi lần thử tiếp chờ thêm bấy nhiêu

export const ECOM_LIQUID_PASSWORD_REQUIRED = "ECOM_LIQUID_PASSWORD_REQUIRED";

let liquidPasswordGateBlocked = false;

function blockLiquidForPasswordGate(): void {
    if (liquidPasswordGateBlocked) {
        return;
    }
    liquidPasswordGateBlocked = true;
    window.dispatchEvent(new CustomEvent(ECOM_LIQUID_PASSWORD_REQUIRED));
}

export function resetLiquidProcessing(): void {
    liquidPasswordGateBlocked = false;
    (window as any).liquidProcessingQueue = undefined;
}

export default {
    inject: ["exporting"],
    components: {
        Liquid: {
            inject: ["exporting"],
            props: {
                data: {
                    type: String,
                    default: ""
                }
            },
            template: `{{ data && exporting === true ? 'liquid[['+encodeURIComponent(data)+']]' : '' }}`
        }
    },
    data() {
        return {
            combinedLiquid: {
                timer: 0,
                timeout: 0,
                elements: {},
                sheduled: {},
                processId: 0
            },
            // Thêm hệ thống queue để xử lý tuần tự
            liquidQueue: {
                isProcessing: false,
                queue: [],
                currentBatch: {}
            }
        };
    },
    computed: {
        allowTypes() {
            return ["section", "product", "page", "article", "blog", "cart", "collection"];
        },
        market() {
            return this.$store.getters["page/market"];
        },
        liquidBefore() {
            let settings = this.data.settings;

            if (!settings) {
                return "";
            }
            const section_id = this?.section?.id || this.data?.id;

            let form_class = "";
            if (this?.data?.advanced?.["display"] == "none") {
                form_class = " ec-hide-on-desktop";
            } else if (this?.data?.advanced?.["display__tablet"] == "none") {
                form_class = " ec-hide-on-tablet";
            } else if (this?.data?.advanced?.["display__mobile"] == "none") {
                form_class = " ec-hide-on-mobile";
            }

            let shopify_type = this.shopify_type;
            switch (shopify_type) {
                case "product":
                    return `
                    {% comment %}
                        // Reactive
                        * this.data.settings.product
                    {% endcomment  %}
                    {% liquid
                        unless recommendations.performed
                        if ${
                            this.data?.template === "featured_product" || this?.isProductBox
                                ? " true "
                                : "request.page_type != 'product' or product == blank"
                        }
                            assign selected_product = '${this.selected_product}'
                            if selected_product == blank or selected_product == '' or all_products[selected_product] == blank
                                assign product = collections['all'].products.first
                            else
                                assign product = all_products[selected_product]
                                if product.id == blank
                                    assign product = collections['all'].products.last
                                endif
                            endif
                        endif
                        endunless
                    %}
                    {%- if product != blank -%}
                        {%- capture ec_form_id -%}product_form_{{ product.id }}_${section_id}{%- endcapture -%}
                        {%- form 'product', product, id: ec_form_id, class: "ecom-product-form ecom-product-form--single ecom-click${form_class}", product_id: product.id, data-product_id: product.id,data-product-id: product.id, data-handle: product.handle-%}

                 `;
                case "collection":
                    return `
                    {% comment %}
                        // Reactive
                        * this.data.settings.collection
                    {% endcomment  %}
                    {% liquid
                        if request.page_type != 'collection' or collection == blank
                            assign selected_collection = '${this.selected_collection}'
                            if selected_collection == blank or selected_collection == '' or collections[selected_collection] == blank
                                assign collection = collections.all
                            else
                                assign collection = collections[selected_collection]
                                if collection.id == blank
                                    assign collection = collections.all
                                endif
                            endif
                        endif
                    %}
                 `;
                case "cart":
                    return `
                    <form action="{{ routes.cart_url }}" class="ecom-cart-form" method="post" enctype="multipart/form-data">
                `;
                case "blog":
                    return `
                    {%- capture blog_handle -%}${
                        this.data.settings?.blog?.value ? this.data.settings.blog.value : ""
                    }{%-  endcapture-%}
                    {% assign blog_handle = blog_handle | strip %}
                    {%- if request.page_type != 'blog' and blog_handle != blank -%}
                        {%- assign blog = blogs[blog_handle]-%}
                        {%- assign tmp_block = blog -%}
                    {%- else -%}
                        {% unless tmp_block %}{% assign tmp_block = blog %}{% endunless %}
                        {% if tmp_block != nil and tmp_block != blank %}{% assign blog = tmp_block %}{% endif %}
                    {%- endif -%}
                `;
                case "article":
                    return `
                    {% unless tmp_block %}{% assign tmp_block = blog %}{% endunless %}
                    {%- capture article_selected -%}${
                        this.data.settings?.article?.value ? this.data.settings.article.value : ""
                    }{%-  endcapture-%}
                    {% assign article_selected = article_selected | strip %}
                    {%- if request.page_type != 'article' and article_selected != blank  -%}
                        {%- assign article = articles[article_selected]-%}
                        {% assign blog_handle = article_selected | split: '/' | first %}
                        {% assign  blog = blogs[blog_handle] %}
                    {%- endif -%}
                `;
                default:
                    return "";
            }
        },
        page_type() {
            return this.$store.getters["page/params"].page;
        },
        liquidAfter() {
            let settings = this.data.settings;
            if (!settings) {
                return "";
            }
            let shopify_type = this.shopify_type;
            let tagName = "script";
            switch (shopify_type) {
                case "product":
                    return `

                    {% unless ecom_has_variant_picker %}

                        <input type="hidden" name="id" value="{{product.selected_or_first_available_variant.id}}" />
                        <${tagName} type="application/json" id="product-json-{{product.id}}-${
                        this.data.id
                    }">
                            {% if product.variants_count > 250 %}
                                {% assign checkIsHighVariant = true %}
                            {% endif %}
                            {%- ${
                                this.page_type === "block" ? "render" : "render"
                            } "ecom_product_json", product: product, checkIsHighVariant: checkIsHighVariant-%}
                        </${tagName}>
                    {% endunless %}
                    {%- endform -%}
                    {% assign ecom_has_variant_picker = false %}

                    {%- endif -%}
                `;
                case "collection":
                    return ``;
                case "cart":
                    return `<input type="hidden" name="checkout" value="ec" /></form>`;
                case "blog":
                    return ``;
                case "article":
                    return ``;
                default:
                    return "";
            }
        },

        isShopify() {
            return this.shopify_type != "section";
        },

        selected_product() {
            if (!this?.data?.settings) return null;
            return "product" in this?.data?.settings ?? []
                ? this?.data?.settings?.product?.value ?? ""
                : "";
        },

        selected_collection() {
            return "collection" in this?.data?.settings ?? []
                ? this?.data?.settings?.collection?.value ?? ""
                : "";
        },

        self() {
            return this.data;
        },

        shopify_type() {
            return this.data &&
                this.data.shopify_type &&
                this.allowTypes.indexOf(this.data.shopify_type) > -1 &&
                this.data.hasElementRequestLiquid
                ? this.data.shopify_type
                : "section";
        },
        params() {
            return this.$store.getters["page/params"];
        },
        ...mapGetters("builder", ["getLiquids"])
    },
    methods: {
        acceptRequest(req) {
            if (!this.data.settings) {
                this.self.settings = {};
            }

            let res = true;

            Object.keys(req).forEach((re) => {
                if (re == "shopify_type") {
                    if (this.shopify_type == "section" || this.shopify_type == req[re]) {
                        this.self[re] = req[re];
                    } else {
                        res = false;
                    }
                } else if (this.self?.settings?.constructor === Object) {
                    this.self.settings[re] = req[re];
                }
            });

            return res;
        },

        // Phương thức mới để xử lý liquid tuần tự
        processLiquid(element) {
            if (this.exporting !== false) {
                return;
            }

            if (!this.isShopify) {
                // if return, only allow children element run liquid inside section has type is Shopify
                //return;
            }

            // Thêm check để tránh process đồng thời
            if (this.sectionProcessing) {
                // Nếu đang process, thêm vào queue để process sau
                setTimeout(() => {
                    this.processLiquid(element);
                }, 100);
                return;
            }

            // Dynamic debounce based on element count
            let now = new Date().getTime(),
                combined = this.combinedLiquid;

            combined.elements[element.id] = element;
            combined.timer = now;
            clearTimeout(combined.timeout);

            // Calculate dynamic debounce time based on current element count
            const elementCount = Object.keys(combined.elements).length;
            const debounceTime = elementCount < 3 ? DEBOUNCE_FAST :
                                elementCount < 10 ? DEBOUNCE_NORMAL :
                                DEBOUNCE_SLOW;

            combined.timeout = setTimeout(() => {
                this.doProcessLiquid();
            }, debounceTime);
        },

        // Khởi tạo queue global
        initGlobalQueue() {
            if (!window.liquidProcessingQueue) {
                window.liquidProcessingQueue = {
                    isProcessing: false,
                    sectionQueues: {}, // Group theo section
                    processingOrder: [] // Thứ tự xử lý các section
                };
            }
        },

        // Lấy section ID của element hiện tại
        getSectionId() {
            // Ưu tiên dùng section.id nếu có
            if (this?.section?.id) {
                return this.section.id;
            }

            // Hoặc dùng data.id của component cha (section)
            if (this?.data?.id) {
                return this.data.id;
            }

            // Fallback: tìm shopifyWrapper (section chứa element)
            if (this.shopifyWrapper?.data?.id) {
                return this.shopifyWrapper.data.id;
            }

            // Default fallback
            return "default_section";
        },

        // Thêm element vào queue global
        addToGlobalQueue(element) {
            // Đảm bảo queue được khởi tạo
            this.initGlobalQueue();

            const queue = window.liquidProcessingQueue;
            const sectionId = this.getSectionId();

            // Tạo section queue nếu chưa có
            if (!queue.sectionQueues[sectionId]) {
                queue.sectionQueues[sectionId] = {
                    elements: {},
                    instance: this, // Lưu instance đại diện cho section
                    timeout: null,
                    isReady: false
                };

                // Thêm section vào thứ tự xử lý nếu chưa có
                if (!queue.processingOrder.includes(sectionId)) {
                    queue.processingOrder.push(sectionId);
                }
            }

            const sectionQueue = queue.sectionQueues[sectionId];

            // Thêm/cập nhật element trong section
            sectionQueue.elements[element.id] = {
                element: element,
                instance: this
            };

            // Debounce để chờ thêm elements trong cùng section (optimized timing)
            clearTimeout(sectionQueue.timeout);
            sectionQueue.timeout = setTimeout(() => {
                sectionQueue.isReady = true;
                // Bắt đầu xử lý nếu chưa đang xử lý
                if (!queue.isProcessing) {
                    this.processNextSection();
                }
            }, SECTION_DEBOUNCE); // Reduced debounce for faster initial load
        },

        // Xử lý section tiếp theo trong queue
        async processNextSection() {
            // Đảm bảo queue được khởi tạo
            this.initGlobalQueue();

            const queue = window.liquidProcessingQueue;

            if (queue.isProcessing || liquidPasswordGateBlocked) {
                return;
            }

            // Tìm section ready tiếp theo trong thứ tự
            let nextSectionId = null;
            for (const sectionId of queue.processingOrder) {
                const sectionQueue = queue.sectionQueues[sectionId];
                if (
                    sectionQueue &&
                    sectionQueue.isReady &&
                    Object.keys(sectionQueue.elements).length > 0
                ) {
                    nextSectionId = sectionId;
                    break;
                }
            }

            if (!nextSectionId) {
                return; // Không có section nào ready
            }

            queue.isProcessing = true;
            const sectionQueue = queue.sectionQueues[nextSectionId];

            try {
                await this.doProcessSectionElements(sectionQueue, nextSectionId);
            } catch (error) {
                console.error("Error processing section:", nextSectionId, error);
            }

            // Xóa section đã xử lý
            delete queue.sectionQueues[nextSectionId];
            queue.processingOrder = queue.processingOrder.filter((id) => id !== nextSectionId);

            // Đánh dấu hoàn thành và xử lý section tiếp theo
            queue.isProcessing = false;

            // Tiếp tục xử lý section tiếp theo nếu có
            setTimeout(() => {
                this.processNextSection();
            }, 100);
        },

        // Xử lý tất cả elements trong 1 section
        async doProcessSectionElements(sectionQueue, sectionId) {
            const elements = sectionQueue.elements;
            const instance = sectionQueue.instance;

            if (!elements || Object.keys(elements).length === 0) {
                console.warn("No elements to process in section:", sectionId);
                return;
            }

            const elementIds = Object.keys(elements);

            // Check if we need to split into batches
            if (elementIds.length > MAX_ELEMENTS_PER_BATCH) {
                console.warn(
                    `Section ${sectionId} has ${elementIds.length} elements, ` +
                    `splitting into batches of ${MAX_ELEMENTS_PER_BATCH}`
                );

                // Split elements into batches and process sequentially
                for (let i = 0; i < elementIds.length; i += MAX_ELEMENTS_PER_BATCH) {
                    const batchIds = elementIds.slice(i, i + MAX_ELEMENTS_PER_BATCH);
                    const batchElements = {};
                    batchIds.forEach(id => {
                        batchElements[id] = elements[id];
                    });

                    await this.processBatch(batchElements, sectionId, instance, i / MAX_ELEMENTS_PER_BATCH + 1);
                }
                return;
            }

            // Process single batch
            await this.processBatch(elements, sectionId, instance, 1);
        },

        // Gọi builder.scripts để render liquid, kèm timeout + tự thử lại khi Shopify bị
        // Cloudflare throttle tạm thời (server trả cờ retryable, hoặc message chứa mã 503).
        // Trả về response cuối cùng; ném REQUEST_TIMEOUT nếu quá hạn để caller xử lý riêng.
        async renderScriptsWithRetry(instance, processId, rawcode) {
            let res: any = null;

            for (let attempt = 0; attempt <= RENDER_RETRY_MAX; attempt++) {
                let timeoutId: any;
                const timeoutPromise = new Promise((_, reject) => {
                    timeoutId = setTimeout(() => reject(new Error("REQUEST_TIMEOUT")), REQUEST_TIMEOUT);
                });

                const fetchPromise = instance.$worker.fetch(
                    window.route(
                        "builder.scripts",
                        instance.params?.page === "product"
                            ? { ...instance.params, handle: instance.selected_product }
                            : instance.params
                    ),
                    {
                        layout: "none",
                        code: '<process id="' + processId + '" />' + rawcode,
                        settings: JSON.parse(JSON.stringify(instance.data.settings || {})),
                        market: instance.market
                    },
                    "POST"
                );

                try {
                    res = await Promise.race([fetchPromise, timeoutPromise]);
                } finally {
                    clearTimeout(timeoutId);
                }

                // Chỉ thử lại với lỗi throttle TẠM THỜI. str_replace phía server có thể ép
                // bool true -> "1" nên dùng truthy, không so === true; fallback bắt mã 503.
                const isRetryable =
                    res?.data?.status !== "success" &&
                    (!!res?.data?.retryable ||
                        /\(code:\s*5\)|503/.test(String(res?.data?.message || "")));

                if (!isRetryable || attempt === RENDER_RETRY_MAX) {
                    return res;
                }

                // Giãn cách tăng dần + jitter để nhiều render không cùng lúc đập vào Cloudflare.
                // Giữ progress bar để merchant biết đang xử lý, không tưởng builder bị treo.
                const delay =
                    RENDER_RETRY_BASE_MS + attempt * RENDER_RETRY_STEP_MS + Math.floor(Math.random() * 1500);
                instance.$store.dispatch("global/setProgress", { show: true, percent: 10 });
                await new Promise((r) => setTimeout(r, delay));
            }

            return res;
        },

        // Toast thân thiện khi render fail do Shopify bận (đã thử lại nhưng vẫn 503),
        // thay cho việc section im lặng gãy hoặc hiện HTML 503 thô gây hoang mang.
        notifyRenderBusy(instance) {
            instance.$store.commit(
                "global/setToast",
                {
                    isError: true,
                    message: "Couldn't refresh the preview because Shopify is busy right now. Please edit again in a moment.",
                    duration: 5000
                },
                { root: true }
            );
        },

        // Helper method to process a batch of elements
        async processBatch(elements, sectionId, instance, batchNumber) {
            // Đã dính password ở 1 request trước -> không gửi thêm request nào nữa.
            if (liquidPasswordGateBlocked) {
                return;
            }

            let rawcode = `{% assign EComBuilderMode = true %} ` + instance.liquidBefore;
            let processId = Math.random();
            let sheduled = {};

            // Gom tất cả elements trong batch thành 1 request
            Object.keys(elements).forEach((elementId) => {
                const elementData = elements[elementId];
                const elementInstance = elementData.instance;

                if (elementInstance.getLiquids?.[elementId]?.raw) {
                    if (!sheduled[elementId]) {
                        sheduled[elementId] = [];
                    }
                    rawcode += elementInstance.getLiquids[elementId].raw;
                    sheduled[elementId].push(processId);
                }
            });

            rawcode += instance.liquidAfter;

            // Show progress
            const progressMessage = Object.keys(elements).length > 1
                ? `Processing batch ${batchNumber} (${Object.keys(elements).length} elements)...`
                : 'Processing liquid...';

            instance.$store.dispatch("global/setProgress", { show: true, percent: 10 });

            try {
                const res = await this.renderScriptsWithRetry(instance, processId, rawcode);
                instance.$store.dispatch("global/setProgress", { show: false, percent: 100 });

                // Request /scripts chết do storefront password -> chặn request sau + báo Workspace reload iframe.
                if (res.data?.required_store_password) {
                    blockLiquidForPasswordGate();
                    return;
                }

                if (res.data.status === "success") {
                    let returnedProcessId = res.data.result.match(/<process id="([\d\.]*)"\s?\/?>/);
                    if (returnedProcessId === null) {
                        instance.$store.commit(
                            "global/setToast",
                            {
                                isError: true,
                                message: instance.$t("error_while_process_liquid"),
                                duration: 4000
                            },
                            { root: true }
                        );
                        return;
                    }
                    returnedProcessId = returnedProcessId[1];

                    // Xử lý kết quả cho tất cả elements trong section
                    Object.keys(sheduled).forEach((elementId) => {
                        const processIds = sheduled[elementId];
                        if (processIds[processIds.length - 1] != returnedProcessId) {
                            return; // This is not latest request of this element
                        }

                        const elementData = elements[elementId];
                        const elementInstance = elementData.instance;

                        if (res.data.result.indexOf(elementId) > -1) {
                            let reg = new RegExp(
                                '<ecom-embed-start id="' +
                                    elementId +
                                    '" name="([\\s\\S]+?)"\\s?\\/?>([\\s\\S]*)<ecom-embed-end id="' +
                                    elementId +
                                    '" name="\\1"\\s?\\/?>',
                                "g"
                            );

                            res.data.result.replace(reg, (...m) => {
                                if (elementInstance.getLiquids?.[elementId]?.content) {
                                    elementInstance.getLiquids[elementId].content[m[1]] = m[2];
                                }
                            });
                        } else {
                            if (elementInstance.getLiquids[elementId]) {
                                elementInstance.getLiquids[elementId].content = {};
                            }
                        }

                        // Trigger refresh cho element
                        if (elementData.element && elementInstance.$helpers) {
                            elementData.element.refresh = elementInstance.$helpers.randid();
                        }
                    });
                } else {
                    // Đã thử lại nhưng vẫn 503 (Shopify bận) -> báo nhẹ nhàng cho merchant.
                    const busy =
                        !!res?.data?.retryable ||
                        /\(code:\s*5\)|503/.test(String(res?.data?.message || ""));
                    if (busy) {
                        this.notifyRenderBusy(instance);
                    }
                    throw new Error(res.data.message ? res.data.message : "Server error");
                }
            } catch (e: any) {
                const isTimeout = e.message === 'REQUEST_TIMEOUT';

                console.error(
                    `Error processing section ${sectionId} (batch ${batchNumber}):`,
                    {
                        elementCount: Object.keys(elements).length,
                        isTimeout,
                        error: e
                    }
                );

                instance.$store.dispatch("global/setProgress", { show: false, percent: 100 });

                if (isTimeout) {
                    instance.$store.commit("global/setToast", {
                        isError: true,
                        message: `Request timeout after ${REQUEST_TIMEOUT / 1000}s. Section has too many elements (${Object.keys(elements).length}). Try splitting into smaller sections.`,
                        duration: 6000
                    });
                }
            }
        },

        // Giữ lại để backward compatibility (deprecated)
        async processNextInQueue() {
            return this.processNextSection();
        },

        // Giữ lại để backward compatibility (deprecated)
        async doProcessSingleElement(element) {
            console.warn(
                "doProcessSingleElement is deprecated, elements are now processed by section"
            );
            // Fallback: thêm element vào queue để xử lý theo section
            this.addToGlobalQueue(element);
        },

        // Method này được giữ lại để backward compatibility nhưng không được khuyến khích sử dụng
        async doProcessLiquid() {
            // Đã dính password ở 1 request trước -> không gửi thêm request nào nữa.
            if (liquidPasswordGateBlocked) {
                return;
            }

            // Đánh dấu đang processing
            this.sectionProcessing = true;

            let combined = this.combinedLiquid,
                rawcode = `{% assign EComBuilderMode = true %} ` + this.liquidBefore;

            if (!combined || !combined.elements || Object.keys(combined.elements).length === 0) {
                this.sectionProcessing = false;
                return;
            }

            let processId = Math.random();

            Object.keys(combined.elements).forEach((id) => {
                if (this.getLiquids[id].raw && combined.sheduled[id] === undefined) {
                    combined.sheduled[id] = [];
                }
                rawcode += this.getLiquids[id].raw;
                combined.sheduled[id].push(processId);
            });

            rawcode += this.liquidAfter;

            this.$store.dispatch("global/setProgress", { show: true, percent: 10 });

            try {
                const res = await this.renderScriptsWithRetry(this, processId, rawcode);

                this.$store.dispatch("global/setProgress", { show: false, percent: 100 });

                // Request /scripts chết do storefront password -> chặn request sau + báo Workspace reload iframe.
                if (res.data?.required_store_password) {
                    blockLiquidForPasswordGate();
                    this.sectionProcessing = false;
                    return;
                }

                if (res.data.status === "success") {
                    let returnedProcessId = res.data.result.match(/<process id="([\d\.]*)"\s?\/?>/);
                    if (returnedProcessId === null) {
                        this.$store.commit(
                            "global/setToast",
                            {
                                isError: true,
                                message: this.$t("error_while_process_liquid"),
                                duration: 4000
                            },
                            { root: true }
                        );
                        this.sectionProcessing = false;
                        return;
                    }
                    returnedProcessId = returnedProcessId[1];

                    Object.keys(combined.sheduled).forEach((id) => {
                        let processIds = combined.sheduled[id];
                        if (processIds[processIds.length - 1] != returnedProcessId) {
                            return; // This is not latest request of this element
                        }

                        if (res.data.result.indexOf(id) > -1) {
                            let reg = new RegExp(
                                '<ecom-embed-start id="' +
                                    id +
                                    '" name="([\\s\\S]+?)"\\s?\\/?>([\\s\\S]*)<ecom-embed-end id="' +
                                    id +
                                    '" name="\\1"\\s?\\/?>',
                                "g"
                            );

                            res.data.result.replace(reg, (...m) => {
                                if (this.getLiquids?.[id]?.content) {
                                    this.getLiquids[id].content[m[1]] = m[2];
                                }
                            });
                        } else {
                            if (this.getLiquids[id]) {
                                this.getLiquids[id].content = {};
                            }
                        }

                        if (combined.elements[id]) {
                            combined.elements[id].refresh = this.$helpers.randid();
                            delete combined.elements[id];
                        }
                        delete combined.sheduled[id];
                    });
                } else {
                    // Đã thử lại nhưng vẫn 503 (Shopify bận) -> báo nhẹ nhàng cho merchant.
                    const busy =
                        !!res?.data?.retryable ||
                        /\(code:\s*5\)|503/.test(String(res?.data?.message || ""));
                    if (busy) {
                        this.notifyRenderBusy(this);
                    }
                    throw new Error(res.data.message ? res.data.message : "Server error");
                }
            } catch (e) {
                console.error(e);
                this.$store.dispatch("global/setProgress", { show: false, percent: 100 });
            } finally {
                // Đảm bảo luôn reset flag
                this.sectionProcessing = false;
            }
        }
    }
};
