// store/modules/library/types.ts

import { FAVORITES_PAGE_SIZE } from './constants';

// --- Request body đúng format API (metadata + library) ---
export interface LibraryRequestMetadata {
    paged: number;
    limit: number;
    search: string;
    category: string | number | null;
    category_slug?: string;  
    filter: string | null;
    tags: string[] | string;
    sort: string;
    type?: string[] | string;
    detail?: string | null;
    source?: string;
    /**
     * Loại trang đang chỉnh sửa (URL param `page`).
     * Laravel dùng để filter template — vd: khi !== 'popups' thì loại trừ popup templates.
     */
    page_context?: string;
    /**
     * Giới hạn loại post trả về ('section' | 'page'). Hiện dùng cho route favorites
     * để sidebar Section chỉ lấy section đã favorite; bỏ trống = lấy cả hai.
     */
    post_type?: string;
}

export interface LibraryRequestPayload {
    metadata: LibraryRequestMetadata;
    library: string;
}

// --- Query nội bộ (context.query), map sang metadata khi gọi API ---
export interface LibraryQuery {
    page: number;
    pageSize: number;
    search: string;
    categoryId: string | number | null;
    nicheId: string | null;
    tags: string | string[];
    sort: string;
    filter: string | null;
    /** Lọc paid/free — gửi API qua metadata.type = 'pro' | 'free' (khớp Laravel allPages/pages/sections). */
    priceTier: 'pro' | 'free' | null;
    detailKey: string | null;
    /** Lưu category theo từng source (pages-ecom, sections) để tương thích component. */
    categoryBySource?: Record<string, string | number>;
    /**
     * Loại trang đang được chỉnh sửa (lấy từ URL param `page`, vd: 'product', 'popups'…).
     * Gửi lên API qua metadata.page_context để Laravel filter template theo context.
     */
    pageContext?: string;
    /** Giới hạn loại post ('section' | 'page') — gửi API qua metadata.post_type. */
    postType?: string | null;
}

// --- 3 state: context / cache / status ---
export interface LibraryContextState {
    tab: string;
    sourceId: string;
    isOpen: boolean;
    mode: 'popup' | 'sidebar' | 'library' | null;
    query: LibraryQuery;
}

export interface LibraryCacheState {
    lists: Record<string, any>;
    meta: {
        categories: any[] | null;
        tags: Record<string, any>;
        sources: Array<{ id: string; title: string; logo?: string; logo_white?: string; icon?: string; icon_white?: string; isActive?: boolean }>;
        favorites: Array<string | number>;
        partners?: Record<string, any>;
        optionsPromo?: Record<string, any>;
        /** Niche đang chọn (tương thích component). */
        currentNiche?: { pages?: { id: string; title?: string }; sections?: { id: string; title?: string } };
    };
}

export interface LibraryStatusState {
    initializing: boolean;
    /** true khi đổi filter/category/sort/tab — ẩn list, chỉ show placeholder */
    loading: boolean;
    /** true khi cuộn xuống load thêm — giữ list hiện tại, thêm placeholder phía dưới */
    loadingMore: boolean;
    error: string | null;
    firstLoad: boolean;
    success?: string | null;
    errors?: any;
    showSaveForm?: boolean;
    detailTask?: boolean;
    detailPost?: any;
    loadingSave?: boolean;
    preview: { open: boolean; markup?: string; id?: string | number; screen?: string };
}

/** State module library. */
export interface LibraryState {
    context: LibraryContextState;
    cache: LibraryCacheState;
    status: LibraryStatusState;

    /**
     * Map tab → cache key hiện tại (do LibraryCacheService quản lý).
     * Vuex chỉ giữ key (string), không giữ data.
     * e.g. { sections: 'ecom_lib_v2_sections_ecom_abc123', all_pages: '...' }
     */
    activeKeys: Record<string, string>;

    /**
     * Counter tăng mỗi khi CacheService được cập nhật.
     * Getter listOfData phụ thuộc vào đây để re-compute đúng thời điểm.
     */
    cacheVersion: number;
}

/** Map metaData (legacy) sang query để setInsert chấp nhận payload cũ. */
export function metaDataToQuery(metaData: Record<string, any>): Partial<LibraryQuery> {
    if (!metaData || typeof metaData !== 'object') return {};
    return {
        page: metaData.paged ?? undefined,
        pageSize: metaData.limit ?? undefined,
        search: metaData.search ?? undefined,
        categoryId: metaData.category_slug
            ? metaData.category_slug
            : (metaData.category !== undefined && metaData.category !== '' ? metaData.category : undefined),/* Ưu tiên dùng category_slug; nếu không có thì dùng category id, vì sự khác biệt live và local*/
        filter: metaData.filter ?? undefined,
        priceTier: (() => {
            const t = metaData.priceTier;
            if (t === 'pro' || t === 'free') return t;
            if (metaData.filter === 'premium') return 'pro';
            if (metaData.filter === 'free') return 'free';
            const ty = metaData.type;
            if (typeof ty === 'string' && (ty === 'pro' || ty === 'free')) return ty;
            return undefined;
        })(),
        // tags: hỗ trợ cả dạng string (niche id) và array
        tags: Array.isArray(metaData.tags)
            ? metaData.tags
            : (typeof metaData.tags === 'string' && metaData.tags !== '' ? [metaData.tags] : undefined),
        sort: metaData.sort ?? undefined,
        postType: metaData.post_type ?? undefined
    };
}

/** Map sort value → type key. */
export function sortToType(sort: string): string {
    const map: Record<string, string> = {
        created_at: 'newest',
        installed: 'popular',
        trending: 'trending',
    };
    return map[sort] || 'newest';
}

/** Build body gửi lên API từ context. Cần gì truyền tham số và lấy ra. */
export function buildRequestPayload(context: LibraryContextState): LibraryRequestPayload {
    const q = context.query;
    const isPagesTab    = context.tab === 'all_pages';
    const isSectionsTab = context.tab === 'sections';
    const isFavoritesTab = context.tab === 'my_favorites';

    let type: string | string[];
    let detail: string | null | undefined;

    const tier = q.priceTier;
    if (tier === 'pro' || tier === 'free') {
        type = tier;
        detail = undefined;
    } else if (isPagesTab) {
         // all_pages: type = categoryId (page type) hoặc rỗng = show all
        //  type   = q.categoryId != null && q.categoryId !== '' ? [String(q.categoryId)] : [];
        // all_pages:
        // - Luôn gửi kèm thông tin sort (newest/popular/trending) trong type
        // - Nếu có categoryId (page type) thì type = [categoryId, sortKey]
        // - Nếu không có categoryId thì type = [sortKey]
        const sortKey = sortToType(q.sort);
        if (q.categoryId != null && q.categoryId !== '') {
            type = [String(q.categoryId), sortKey];
        } else {
            type = [sortKey];
        }
        detail = undefined;
    } else if (isSectionsTab && !q.detailKey) {
        // sections top-level: gửi 1 type dựa theo sort (trending/popular/newest) là string không phải array
        type   = sortToType(q.sort);
        // type   = ['trending', 'popular', 'newest'];
        // detail = undefined;
        detail = undefined;
    } else {
        // detail view (niche/category) hoặc tab khác
        type   = q.detailKey ? [q.detailKey] : ['trending', 'popular', 'newest'];
        detail = q.detailKey ?? undefined;
    }

    const isSlugTab = isSectionsTab || isPagesTab;   // đổi để cả pages và sections đều dùng category_slug

    const metadata: LibraryRequestMetadata = {
        paged   : q.page,
        // limit riêng cho sections (masonry page 1 quá ngắn nên ko khởi động dc loadmore)
        // và cho my_favorites (load hết 1 lần, xem FAVORITES_PAGE_SIZE)
        limit   : isSectionsTab ? 30 : isFavoritesTab ? FAVORITES_PAGE_SIZE : q.pageSize,
        search  : q.search,
        category: q.categoryId ?? '',
        category_slug : isSlugTab ? (q.categoryId ? String(q.categoryId) : undefined) : undefined,
        filter  : q.filter,
        tags    : q.tags,
        sort    : q.sort || 'created_at',
        type,
        detail,
        page_context: q.pageContext || undefined,
        post_type: q.postType || undefined,
    };
    return { metadata, library: context.sourceId };
}

export interface MetaData {
    paged: number;
    limit: number;
    search: string;
    category: string;
    filter: string | null;
    /** Đồng bộ với query.priceTier / metadata.type pro|free */
    priceTier?: 'pro' | 'free' | null;
    tags: string[] | string;
    sort: string;
    type?: string[] | string;
    detail?: string;
    source?: string;
    is_free?: 0 | 1 | null;
}

