<i18n>
{
    "en": {
        "upload": "Upload",
        "reload_to_choose": "Reload to choose"
    },
    "fr": {
        "upload": "Télécharger",
        "reload_to_choose": "Recharger pour choisir"
    },
    "de": {
        "upload": "Hochladen",
        "reload_to_choose": "Neu laden, um zu wählen"
    },
    "ja": {
        "upload": "アップロード",
        "reload_to_choose": "選択するためにリロード"
    }
}
</i18n>
<template>
	<li
		v-detectVisible="detectVisible"
		class="relative p-2 transition cursor-pointer select-none item"
        :class="[classItem(item)]"
		:style="item.fn == 'upload' ? 'width: 100%' : ''"
	>
		<div
			class="relative"
			:class="[
				// layout == 'grid' ? 'pb-100p' : '',
				item.fn == 'upload' ? 'pb-20' : 'pb-10',
			]"
		>
			<div
				v-if="show"
				class="absolute inset-0 group"
			>
				<template v-if="item.fn == 'upload'">
					<span
						class="absolute top-0 left-0 flex flex-col items-center justify-center w-full font-medium text-gray-500  transition bg-white  border-2 border-gray-100 border-dashed rounded group-hover:text-primary-700 group-hover:border-primary-700  p-2 h-16"
					>
						<EcomIcon :source="icons.ExportMinor" :size="'w-5'"></EcomIcon>
						<text>{{ $t('upload') }}</text>
					</span>
					<input
						class="absolute top-0 left-0 z-10 w-full h-full opacity-0 cursor-pointer"
						type="file"
						:accept="acceptInput"
						multiple
						@change="$emit('upload', $event)"
					>
				</template>
				<div v-else class="flex items-center h-full" @click="toggleItem(item)">
					<div class="flex items-center w-full h-full" :class="{'opacity-30': item.loading}">
						<template v-if="layout == 'list'">
							<span class="block w-10 h-10 mr-2 text-gray-700  fill-current svg-full">
								<span v-html="item.thumbnail"/>
							</span>
							<span class="flex-1 block text-sm text-gray-500  truncate uppfirst">
								{{ item.name }}
							</span>
						</template>
						<div
							v-else
							class="relative flex flex-col items-center justify-center w-full h-full overflow-hidden transition duration-100 bg-white  rounded shadow-content"
							:title="item.reload ? $t('reload_to_choose') : item.name">
							<span v-if="!item.thumbnail.startsWith('<')" class="w-10 h-10 text-gray-700  fill-current svg-full bg-gray-50 border border-gray-200 rounded flex justify-center items-center p-[10px]">
								<img class="w-full h-full object-scale-down" :src="item.thumbnail" alt="" crossorigin="anonymous">
							</span>
							<span
								v-else
								class="w-10 h-10  fill-current svg-full bg-gray-50 border border-gray-200 rounded flex justify-center items-center p-[10px]"
								:class="isActive(item.value) > -1 ? 'text-white bg-primary' : ''"
								v-html="item.thumbnail"
							/>
							<!-- <p
								class="text-center text-xs mt-0.5 max-w-full px-1 block truncate uppfirst text-gray-600 "
							>
								<span>{{
									item.reload ? 'Reload to choose' : item.name
								}}</span>
							</p> -->
						</div>
					</div>
					<!-- <span
						class="absolute flex items-center justify-center w-4 h-4 p-px transition rounded-full opacity-0 bg-primary"
						:class="[
							isActive(item.value) > -1
								? ' opacity-100'
								: '',
							layout == 'grid'
								? 'right-0 bottom-0 z-10'
								: 'top-1/2 right-0 transform -translate-y-1/2 group-hover:opacity-100',
						]"
					>
						<EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" :color="'text-white'"></EcomIcon>
					</span> -->
					<span
						v-if="item.loading"
						class="absolute transform -translate-x-1/2 -translate-y-1/2 top-1/2 left-1/2"
					>
						<Loading type="spin"/>
						<span
							class="absolute text-sm transform -translate-x-1/2 -translate-y-1/2 top-1/2 left-1/2"
						>
							{{ item.per }}
						</span>
					</span>
					<template v-if="isActive(item.value) === -1 && (item.id + '').startsWith('gid://')">
						<template v-if="!item.removing">
							<EcomIcon :source="icons.DeleteMajor" :size="'w-4'" @click.stop="$emit('remove', item)" class="absolute w-4 h-4 text-gray-500 transition top-0.5 right-0.5 z-1 flex items-center hover:text-red-600 opacity-0 group-hover:opacity-100"></EcomIcon>
						</template>

						<Loading v-else
							:size="4"
							type="spin"
							class="absolute w-4 h-4 text-gray-500 transition top-1 right-1 z-1"
						></Loading>
					</template>
				</div>
			</div>
		</div>
	</li>
</template>

<script lang="ts">
import { detectVisible } from '../../directives';
import { ExportMinor, TickSmallMinor, DeleteMajor } from "@/assets/icons";

export default {
    name: 'IconContent',
	directives: {
		detectVisible
	},
    components: {
    },

    props: {
        value: {
            type: Array,
						default(){
							return [];
						}
        },
        item: {
            type: Object,
						default(){
							return {};
						}
        },
        layout: {
            type: String,
						default: ''
        }
    },
	emits: ['upload', 'remove', 'toggleItem', 'reload'],

    data(){
        return {
            show: false,
            info: {},
			icons: {
				ExportMinor, TickSmallMinor, DeleteMajor
			}

        };
    },

    computed: {
        acceptInput(){
            return '.svg';
        },
			hasReload() {
            return this.item.reload;
        }
    },
		watch: {
        hasReload(val) {
            if (val) {
                setTimeout(() => {
                    this.$emit('reload');
                }, 1000);
            }
        }
    },
    methods: {
        fileName(data){
                let name = this.$helpers.file.name(data);
                return name ? name :  data;
            },
        isActive(value) {
            return this.value.reduce((acc, cur, index) => {
                if (cur.value == value) {
					acc = index;
				}
                return acc;
            }, -1);
        },
		classItem(item){
			let cl = '';
			if(this.layout == 'grid'){
				cl += 'w-1/5 pt-0 px-1 mb-0.5';
			}else{
				cl += 'py-2.5 pl-4 w-full border-b border-gray-100  bg-white  ';
				if(item.fn === 'item'){
					cl += 'h-15';
				}else{
					cl += 'h-25';
				}
				if(!item.reload){
					cl += ' cursor-pointer';
				}
			}
			if(item.reload){
				cl += ' opacity-50 pointer-events-none transform scale-90';
			}
			return cl;

        },
		detectVisible(){
			this.show = true;
		},
		async getContentSVG(url) {
			let res = await fetch(url);
			return (await res.text()).replace(/([\n])/g, '').replace(/([\t])/g, '').replace(/([ ],{2,})/g,' ').replace(/<!--(.*?)-->/g,'');
		},
		async toggleItem(item){
			const formatSvg = (htmlSVG) => {
				var div = document.createElement('div');
				div.innerHTML = htmlSVG;
				let svg =  div.querySelector('svg');
				if(!svg) {
					return htmlSVG;
				}
				let stroke = svg.getAttribute('stroke');
				if(stroke && stroke !== 'none') {
					svg.setAttribute('stroke', 'currentColor');
				}
				else {
					svg.setAttribute('fill', 'currentColor');
				}
				return svg.outerHTML;
			};
			if(!item?.value?.startsWith('<')){
				let dataSVG = await this.getContentSVG(item.value);
				dataSVG = formatSvg(dataSVG);
				item.thumbnail = dataSVG;
				item.value = dataSVG;
			}
			this.$emit('toggleItem', item);
		},
    }
};
</script>

<style>
 .svg-full svg{
	width: 100%;
	height: 100%;
 }
 .min-w-1\/3{
	min-width: 33.333333%;
 }
 .max-w-1\/3{
	max-width: 33.333333%;
 }
</style>
