const getHeightOfElementOrSvgEle = (ele: HTMLElement | SVGGraphicsElement) => {
    if (ele instanceof HTMLElement) {
        return ele.offsetHeight;
    } else if (ele instanceof SVGGraphicsElement) {
        return ele.getBBox().height;
    } else {
        return 20;
    }
};

/**
 * Handle show popup in multiple case (Extension Modal, Global Setting Modal, ...)
 * @param containerEle container wraps target element
 * @param targetEle element which is clicked to open popup
 * @param popupEle popup element which is opened after click target ele
 * @param options is array of number which we want to minus
 * @returns show at bottom or show at the top
 */
export const showPopupAtBottom = (
    containerEle: HTMLElement,
    targetEle: HTMLElement | SVGGraphicsElement,
    popupEle: HTMLElement,
    options?: number[]
): boolean => {
    const containerRect = containerEle.getBoundingClientRect();
    const targetRect = targetEle.getBoundingClientRect() as DOMRect;
    const yPos = targetRect.top - containerRect.top;
    var sum = options?.reduce((accumulator: number, currentValue: number) => {
        return accumulator + currentValue;
    }, 0);

    const distanceBtnToTop = yPos - 5;
    const distanceBtnToBottom =
        containerEle.offsetHeight -
        window.scrollY -
        yPos -
        getHeightOfElementOrSvgEle(targetEle) -
        (sum ?? 0);

    if (distanceBtnToTop < popupEle.offsetHeight && distanceBtnToBottom < popupEle.offsetHeight) {
        return true;
    } else {
        return distanceBtnToBottom >= popupEle.offsetHeight;
    }
};

/**
 * Handle show popup in Side Bar Setting
 * @param targetEle element which is clicked to open popup
 * @param popupELe popup element which is opened after click target ele
 * @returns show at bottom or show at the top
 */
export const showPopupAtBottomInSideNar = (
    targetEle: HTMLElement | SVGGraphicsElement,
    popupELe: HTMLElement
): boolean => {
    const sideBarContainerEle = document.getElementById("ecom-sidebar") as HTMLElement;
    const elementPanel = document.querySelector(".element-panel__bottom") as HTMLElement; // the delete and learn more buttons sections (at the bottom)
    const elementPanelHeight = elementPanel ? elementPanel.offsetHeight : 0;
    return showPopupAtBottom(sideBarContainerEle, targetEle, popupELe, [elementPanelHeight]);
};

export const htmlTags = {
    inline: [
        'a', 'abbr', 'b', 'bdi', 'bdo', 'big', 'button', 'cite', 'code', 'dd', 'del', 'dfn', 'em', 'font', 'i', 'ins', 'kbd', 'label', 'mark', 'meter', 'q', 's', 'samp', 'small', 'span', 'strong', 'sub', 'sup', 'svg', 'time', 'u', 'var', 'wbr'
    ],
    block: [
        'address', 'article', 'aside', 'blockquote', 'caption', 'details', 'dialog', 'div', 'dt', 'fieldset', 'figcaption', 'figure', 'footer', 'form', 'header', 'hgroup', 'legend', 'li', 'main', 'nav', 'noscript', 'pre', 'section', 'td', 'th', 'search', 'template'
    ],
    blockSpecial: [
        'canvas', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'iframe', 'menu', 'ol', 'p', 'summary', 'ul'
    ],
    special: [
        'area', 'audio', 'col', 'colgroup', 'data', 'datalist', 'dl', 'embed', 'map', 'object', 'optgroup', 'option', 'output', 'picture', 'progress', 'rp', 'rt', 'ruby', 'script', 'select', 'source', 'table', 'tbody', 'textarea', 'tfoot', 'thead', 'tr', 'track', 'video'
    ],
    maybeSelfClosed: ['path'],
    selfClosed: [
        'br', 'hr', 'img', 'input', 'param'
    ],
    isInline(tag: string) {
        tag = tag.toLowerCase();
        return this.inline.indexOf(tag) >= 0;
    },
    isBlock(tag: string) {
        tag = tag.toLowerCase();
        return this.block.indexOf(tag) >= 0;
    },
    isBlockSpecial(tag: string) {
        tag = tag.toLowerCase();
        return this.blockSpecial.indexOf(tag) >= 0;
    },
    isSpecial(tag: string) {
        tag = tag.toLowerCase();
        return this.special.indexOf(tag) >= 0;
    },
    isMaybeSelfClosed(tag: string) {
        tag = tag.toLowerCase();
        return this.maybeSelfClosed.indexOf(tag) >= 0;
    },
    isSelfClosed(tag: string) {
        tag = tag.toLowerCase();
        return this.selfClosed.indexOf(tag) >= 0;
    }
}

export const unwrapNode = (node, range, returnOnly) => {
    let pnode = node.parentNode;
    const fragment = document.createDocumentFragment();
    while (node.childNodes[0]) {
        fragment.appendChild(node.childNodes[0]);
    };
    if (returnOnly) {
        return fragment;
    }
    if (pnode) {
        pnode.removeChild(node);
    }
    range.insertNode(fragment);
    if (pnode) {
        pnode.normalize();
    }
}