// ============================================================
// Shopify input limits
// ============================================================

// inventoryQuantities.quantity is a GraphQL Int: "-(2^31) to 2^31 - 1".
// https://shopify.dev/docs/api/admin-graphql/latest/scalars/Int
export const MAX_INVENTORY_QUANTITY = 2147483647;

// Money is a *string* scalar with no documented ceiling, so we don't invent one —
// crawled products can legitimately cost millions. The only real bound is JS
// itself: past MAX_SAFE_INTEGER the number loses precision and is meaningless.
// https://shopify.dev/docs/api/admin-graphql/latest/scalars/Money
export const MAX_MONEY = Number.MAX_SAFE_INTEGER;

/**
 * Serialize a number for a Money field. Beyond 1e21 both String() and toFixed()
 * emit exponential notation ("1e+27"), which Shopify rejects as malformed Money,
 * so format with explicit digits instead of capping the value.
 */
export function toMoney(value: number): string {
    const num = Number(value);
    if (!Number.isFinite(num)) return '0.00';
    return num.toLocaleString('en-US', {
        useGrouping: false,
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    });
}

// ============================================================
// Types
// ============================================================

export interface ProductVariant {
    name: string;
    price: number;
    compareAtPrice?: number;
    sku?: string;
    image?: string;
    options: Record<string, string>;
    available?: boolean;
    quantity?: number;
}

export interface ProductOption {
    name: string;
    values: string[];
}

export interface CrawledProduct {
    title: string;
    description: string;
    descriptionText: string;
    images: string[];
    videos?: Array<{ src: string; thumbnail?: string | null }>;
    price: { amount: number; currency: string; compareAtPrice?: number };
    originalPrice?: { amount: number; currency: string };
    options: ProductOption[];
    variants: ProductVariant[];
    attributes: Record<string, string>;
    category?: string;
    brand?: string;
    tags?: string[];
    rating?: number;
    reviewCount?: number;
    meta_description?: string;
    seoDescription?: string;
    source: 'amazon' | 'aliexpress' | 'etsy' | 'shopify';
    sourceUrl: string;
}

export interface TemplateItem {
    id: string;
    title: string;
    description: string | null;
    thumbnail: string | null;
    installed: number;
    matched?: boolean;
}

export interface ShopifyCreatedProduct {
    id: string;
    handle: string;
    title: string;
    status: string;
    onlineStoreUrl?: string | null;
    featuredImage?: any;
    featuredMedia?: any;
    media?: any;
}

export type WizardStep = 'link' | 'preview' | 'creating' | 'templates' | 'generating';
export type ImportMode = 'shopify' | 'json';

interface ProductImportState {
    isOpen: boolean;
    currentStep: WizardStep;

    // Step 1: Link Input
    importMode: ImportMode;
    productUrl: string;
    jsonString: string;
    selectedStoreProduct: any;
    selectedProductVariantsTotal: number | null; // exact variant count from GraphQL (may exceed 250)
    isCrawling: boolean;
    crawlError: { title: string; message: string; code?: string } | string;
    isExistingProduct: boolean; // true when user selected an existing Shopify product

    // Step 2: Preview & Edit
    crawledProduct: CrawledProduct | null;
    originalDescription: string; // description gốc lúc crawl, dùng cho "Revert to original"
    // Pricing
    markupType: 'none' | 'percentage' | 'fixed';
    markupValue: number;
    compareAtMarkupType: 'none' | 'percentage' | 'fixed';
    compareAtMarkupValue: number;
    variantPriceOverrides: Record<number, number>;  // variant index -> custom price
    variantCompareAtPriceOverrides: Record<number, number>;  // variant index -> custom compare-at price (from manual edit)
    sourceCompareAtPrices: Record<number, number>;  // variant index -> original compare-at price from source
    // Inventory
    defaultQuantity: number;
    variantQuantityOverrides: Record<number, number>;
    // Tags & SEO
    tags: string[];
    seoTitle: string;
    seoDescription: string;
    // AI loading states
    isRewritingDescription: boolean;
    isSuggestingTags: boolean;
    isSuggestingSEO: boolean;
    isSuggestingSEODesc: boolean;

    // Step 3: Create Product
    isCreatingProduct: boolean;
    createProductError: string;
    shopifyProduct: ShopifyCreatedProduct | null;

    // Step 4: Template Selection
    isSearchingTemplates: boolean;
    templateKeywords: string[];
    templates: TemplateItem[];
    selectedTemplateId: string | null;
    templateError: string;
    // Scroll-to-load-more pagination
    templatesOffset: number;
    hasMoreTemplates: boolean;
    isLoadingMoreTemplates: boolean;

    // Step 5: AI Generation
    isGenerating: boolean;
    generateProgress: number;
    generateProgressText: string;
    generateError: string;
}

