/**
 * Ensure scopes required by the product import flow are granted.
 * Uses the App Bridge Scopes API to check and, if needed, request the
 * scope from the merchant via a permission grant modal.
 * Throws if the merchant declines.
 */
const PRODUCT_IMPORT_REQUIRED_SCOPES = [
    'read_publications',
    'write_publications',
    'read_locations',
    'write_inventory',
];

const SHOPIFY_MEDIA_FIELDS_FRAGMENT = `
    fragment fieldsForMediaTypes on Media {
        alt
        mediaContentType
        preview { image { id altText url } }
        status
        ... on MediaImage {
            id
            image { altText url }
        }
        ... on Video {
            id
            sources { format height mimeType url width }
            originalSource { format height mimeType url width }
        }
        ... on ExternalVideo {
            id
            host
            originUrl
        }
    }
`;

function stripHtml(value: string): string {
    return value.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function normalizeSeoDescription(value: any, limit: number): string {
    if (typeof value !== 'string') return '';
    return value.replace(/\s+/g, ' ').trim().substring(0, limit);
}

function getInitialSeoDescription(product: CrawledProduct | null): string {
    if (!product) return '';

    const metaDescription = normalizeSeoDescription(product.meta_description, 320);
    if (metaDescription) return metaDescription;

    const seoDescription = normalizeSeoDescription(product.seoDescription, 320);
    if (seoDescription) return seoDescription;

    const fallbackSource = product.description || (product as any).body_html || '';
    return normalizeSeoDescription(stripHtml(fallbackSource), 160);
}

// Fallback chain cho body description: body_html → meta description → SEO description → title
function resolveDescription(product: CrawledProduct, title: string): string {
    const source = product.description
        || (product as any).body_html
        || product.meta_description
        || product.seoDescription
        || title;
    if (!source) return '';
    // Nếu nguồn là plain text (meta description, title...) thì bọc <p>
    return /<[a-z][\s\S]*>/i.test(source) ? source : `<p>${escapeHtml(source)}</p>`;
}

function escapeHtml(value: string): string {
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

const USER_ERROR_FIELD_LABELS: Record<string, string> = {
    title: 'Title',
    descriptionHtml: 'Description',
    vendor: 'Brand',
    productType: 'Category',
    tags: 'Tags',
    seo: 'SEO',
    price: 'Price',
    compareAtPrice: 'Compare at price',
    sku: 'SKU',
    barcode: 'Barcode',
    inventoryQuantities: 'Quantity',
    optionValues: 'Option',
};

// Turns a GraphQL userError's `field` path (e.g. ["input", "variants", "1", "price"])
// into a readable "Variant 2 - Price" label and its message, kept separate so
// formatUserErrors() can group identical messages instead of repeating them.
function formatUserError(userError: { field?: (string | number)[] | null; message: string }): { label: string; message: string } {
    const field = (userError.field || []).filter((part) => part !== 'input');
    if (field.length === 0) return { label: '', message: userError.message };

    const parts: string[] = [];
    for (let i = 0; i < field.length; i++) {
        const part = field[i];
        if ((part === 'variants' || part === 'files') && typeof field[i + 1] !== 'undefined') {
            const index = Number(field[i + 1]);
            const noun = part === 'variants' ? 'Variant' : 'Image';
            parts.push(!isNaN(index) ? `${noun} ${index + 1}` : noun);
            i++;
            continue;
        }
        const key = String(part);
        parts.push(USER_ERROR_FIELD_LABELS[key] || key.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/^./, (c) => c.toUpperCase()));
    }

    return { label: parts.join(' - '), message: userError.message };
}

// Shopify often repeats the exact same message once per affected item (e.g. one
// "alt exceeds 512 characters" per image). Group by message and merge the labels
// into one line instead of printing the message N times.
function formatUserErrors(userErrors: { field?: (string | number)[] | null; message: string }[]): string {
    const groups = new Map<string, string[]>();
    userErrors.forEach((userError) => {
        const { label, message } = formatUserError(userError);
        const labels = groups.get(message) || [];
        if (label) labels.push(label);
        groups.set(message, labels);
    });

    return Array.from(groups.entries())
        .map(([message, labels]) => (labels.length ? `${labels.join(', ')} ${message}` : message))
        .join(' | ');
}

// After a variant at `removedIndex` is deleted, shift every override keyed
// on an index greater than it down by one so overrides stay attached to
// the correct (now re-indexed) variant.
function reindexAfterRemove(map: Record<number, number>, removedIndex: number): Record<number, number> {
    const result: Record<number, number> = {};
    Object.keys(map).forEach((key) => {
        const index = Number(key);
        if (index === removedIndex) return;
        result[index > removedIndex ? index - 1 : index] = map[index];
    });
    return result;
}

function uniqueStrings(values: any[]): string[] {
    const seen = new Set<string>();
    const result: string[] = [];
    for (const value of values) {
        const str = typeof value === 'string' ? value.trim() : '';
        if (!str) continue;
        const key = str.toLowerCase();
        if (seen.has(key)) continue;
        seen.add(key);
        result.push(str);
    }
    return result;
}

function parseTagList(value: any): string[] {
    if (Array.isArray(value)) return uniqueStrings(value);
    if (typeof value === 'string') {
        return uniqueStrings(value.split(',').map(tag => tag.trim()));
    }
    return [];
}

function extractProductTags(product: Partial<CrawledProduct>): string[] {
    const attributes = product.attributes || {};
    return uniqueStrings([
        ...parseTagList(product.tags),
        ...parseTagList(attributes.Tags),
        ...parseTagList((attributes as any).tags),
        ...parseTagList((attributes as any)['Product Tags']),
    ]).slice(0, 250);
}

function isDefaultVariant(variant: ProductVariant): boolean {
    const name = (variant.name || '').trim();
    const optionValues = Object.values(variant.options || {}).filter(Boolean);
    return optionValues.length === 0 && /^(default|default title)$/i.test(name);
}

function getMediaImageUrl(node: any): string {
    if (!node || node.mediaContentType !== 'IMAGE') return '';
    return node.image?.url || node.preview?.image?.url || '';
}

function getMediaVideoUrl(node: any): string {
    if (!node) return '';
    if (node.mediaContentType === 'EXTERNAL_VIDEO') {
        return node.originUrl || '';
    }
    if (node.mediaContentType !== 'VIDEO') return '';

    const sources = Array.isArray(node.sources) ? node.sources : [];
    const playable = sources.filter((item: any) => /mp4|webm/i.test(item?.mimeType || item?.format || ''));
    const source = getBestVideoSource(playable.length ? playable : sources);
    return source?.url || node.originalSource?.url || '';
}

function collectMediaUrls(media: any): { images: string[]; videos: string[] } {
    const images: string[] = [];
    const videos: string[] = [];
    for (const edge of (media?.edges || [])) {
        const node = edge.node;
        const imageUrl = getMediaImageUrl(node);
        if (imageUrl) images.push(imageUrl);

        const videoUrl = getMediaVideoUrl(node);
        if (videoUrl) videos.push(videoUrl);
    }
    return {
        images: uniqueStrings(images),
        videos: uniqueStrings(videos),
    };
}

function cleanBrandName(brand: string | undefined): string | undefined {
    if (!brand) return brand;
    let b = brand.trim();
    if (b.toLowerCase().startsWith('visit the ') && b.toLowerCase().endsWith(' store')) {
        b = b.substring(10, b.length - 6).trim();
    }
    return b;
}

function normalizeCrawledProduct(product: CrawledProduct): CrawledProduct {
    const attributes = product.attributes || {};
    const title = product.title || '';
    const description = resolveDescription(product, title);
    const options = (product.options || [])
        .map((opt: ProductOption) => ({
            name: opt.name,
            values: uniqueStrings(opt.values || []),
        }))
        .filter((opt: ProductOption) => opt.name && opt.values.length > 0 && !(opt.values.length === 1 && opt.values[0] === 'Default Title'));
    const variants = (product.variants || [])
        .filter((variant: ProductVariant) => !isDefaultVariant(variant))
        .map((variant: ProductVariant) => ({
            ...variant,
            name: variant.name || Object.values(variant.options || {}).filter(Boolean).join(' / '),
            price: Number(variant.price) || product.price?.amount || 0,
            options: variant.options || {},
        }));

    return {
        ...product,
        title,
        description,
        descriptionText: product.descriptionText || stripHtml(description || title),
        images: uniqueStrings(product.images || []),
        videos: (product.videos || []).reduce((acc: Array<{ src: string; thumbnail?: string | null }>, v: any) => {
            if (typeof v === 'string' && v) {
                acc.push({ src: v, thumbnail: null });
            } else if (v && v.src) {
                acc.push({ src: v.src, thumbnail: v.thumbnail || null });
            }
            return acc;
        }, []),
        price: {
            amount: Number(product.price?.amount) || 0,
            currency: product.price?.currency || 'USD',
            compareAtPrice: variants[0]?.compareAtPrice,
        },
        options,
        variants,
        attributes,
        category: product.category?.trim() || attributes['Product Type'] || attributes.Category || undefined,
        brand: cleanBrandName(product.brand) || cleanBrandName(attributes.Vendor) || undefined,
        tags: extractProductTags(product),
    };
}

async function ensureProductImportScopes(): Promise<void> {
    // shopify.scopes is provided by App Bridge in the embedded app context
    const scopesApi = (window as any).shopify?.scopes;
    if (!scopesApi) return; // Guard: running outside embedded context

    const { granted } = await scopesApi.query();
    const missingScopes = PRODUCT_IMPORT_REQUIRED_SCOPES.filter(scope => !granted.includes(scope));
    if (missingScopes.length === 0) return; // Already have it

    let response: any;
    try {
        response = await scopesApi.request(missingScopes);
    } catch (err: any) {
        const msg = err?.message || 'Failed to request product import permissions. Please try again.';
        (window as any).shopify?.toast?.show(msg, { isError: true, duration: 6000 });
        throw new Error(msg);
    }

    if (response.result !== 'granted-all') {
        const msg = 'Permission to access required product import data was declined. Please grant the required permissions and try again.';
        (window as any).shopify?.toast?.show(msg, { isError: true, duration: 6000 });
        throw new Error(msg);
    }
}

/**
 * Fetch and cache the Online Store publication ID.
 * Required for publishablePublish — the Online Store channel must be
 * explicitly targeted by its publication GID.
 * Requests required product import scopes if not already granted.
 */
let _onlineStorePublicationId: string | null = null;
async function getOnlineStorePublicationId(): Promise<string> {
    if (_onlineStorePublicationId) return _onlineStorePublicationId;

    // Ensure we have the scope before calling the API
    await ensureProductImportScopes();

    const query = `
        query {
            publications(first: 10) {
                edges {
                    node {
                        id
                        name
                    }
                }
            }
        }
    `;
    const resp = await window.fetch('shopify:admin/api/graphql.json', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query }),
    });
    const json = await resp.json();
    const edges = json?.data?.publications?.edges || [];
    const onlineStore = edges.find(
        (e: any) => e.node?.name === 'Online Store'
    );
    if (!onlineStore) {
        throw new Error('Online Store publication channel not found.');
    }
    _onlineStorePublicationId = onlineStore.node.id;
    return _onlineStorePublicationId as string;
}

