<i18n>
{
    "en": {
        "drop_here": "Drop here",
        "cant_drop_here": "Can't drop here"
    },
    "fr": {},
    "de": {},
    "ja": {
        "drop_here": "ここにドロップ",
        "cant_drop_here": "ここにはドロップできません"
    }
}
</i18n>
<template>
    <template v-if="!isFlexContainer">
        <div
            ref="wrapper"
            class="core__blocks"
            :class="{
                'core__blocks--empty': visibleBlocks.length === 0 && !isFullScreen,
                'drop__placeholder': visibleBlocks.length === 0 && isDropTo && !isFullScreen,
                'ec-block-spacer-visible': displaySpacer,
                'ec-block-spacer-dragging': SpacerValue > 0,
            }"
            :style="cssVar"
            @mouseenter="overBlocks"
            @mouseleave="outBlocks"
        >
            <div v-if="visibleBlocks.length > 0" class="core__blocks--body">
                <template v-for="(block, i) in visibleBlocks" :key="block.id">
                    <BlockElement
                        v-if="block.name !== 'flexContainer'"
                        :data="block"
                        :deep="deep"
                        :index="i"
                        :control="control"
                        :section_id="section_id"
                        :breadcrumb="`${breadcrumb}`"
                        :dragParent="dragParent"
                    />
                    <FlexContainer
                        v-else
                        :data="block"
                        :deep="deep"
                        :index="i"
                        :control="control"
                        :section_id="section_id"
                        :breadcrumb="`${breadcrumb}`"
                        :dragParent="dragParent"
                    />
                </template>
            </div>
            <div
                v-else-if="!isFullScreen"
                class="core__empty--placeholder"
                :class="{'ecom-cant-drop': checkInGridDrop}"
                :data-label="checkInGridDrop ? $t('cant_drop_here') : $t('drop_here')"
                @click="editColumn"
            >
                <span @click.stop="backtoElements" @dblclick="handleDoubleClickAddCloumn">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" fill="currentColor"><path d="M240 352V272H160C151.2 272 144 264.8 144 256C144 247.2 151.2 240 160 240H240V160C240 151.2 247.2 144 256 144C264.8 144 272 151.2 272 160V240H352C360.8 240 368 247.2 368 256C368 264.8 360.8 272 352 272H272V352C272 360.8 264.8 368 256 368C247.2 368 240 360.8 240 352zM512 256C512 397.4 397.4 512 256 512C114.6 512 0 397.4 0 256C0 114.6 114.6 0 256 0C397.4 0 512 114.6 512 256zM256 32C132.3 32 32 132.3 32 256C32 379.7 132.3 480 256 480C379.7 480 480 379.7 480 256C480 132.3 379.7 32 256 32z"/></svg>
                </span>
            </div><template v-else />
        </div>
    </template>
    <template v-else ref="wrapper">
        <template v-if="visibleBlocks.length > 0">
            <template v-for="(block, i) in visibleBlocks" :key="block.id">
                <BlockElement
                     v-if="!block.blocks"
                    :data="block"
                    :deep="deep"
                    :index="i"
                    :control="control"
                    :section_id="section_id"
                    :breadcrumb="`${breadcrumb}`"
                    :dragParent="dragParent"
                    :isFlexContainer="isFlexContainer"
                    :isParentRow="direction.includes('row')"
                />
                <FlexContainer
                    v-else
                    :data="block"
                    :deep="deep"
                    :index="i"
                    :section_id="section_id"
                    :breadcrumb="`${breadcrumb}`"
                    :dragParent="true"
                    :isParentRow="direction.includes('row')"
                />
            </template>
            
        </template>

        <div
            v-else-if="!isFullScreen"
            class="core__blocks"
            :class="{
                'core__blocks--empty': visibleBlocks.length === 0 && !isFullScreen,
                'drop__placeholder': visibleBlocks.length === 0 && isDropTo && !isFullScreen,
                'ec-block-spacer-visible': displaySpacer,
                'ec-block-spacer-dragging': SpacerValue > 0,
                'core__row--columns': isFlexContainer && deep == 2,
            }"
            :style="cssVar"
            @mouseenter="overBlocks"
            @mouseleave="outBlocks"
        >
            <div
                class="core__empty--placeholder"
                :class="{'ecom-cant-drop': checkInGridDrop}"
                :data-label="checkInGridDrop ? $t('cant_drop_here') : $t('drop_here')"
                @click="editColumn"
            >
                <span @click.stop="backtoElements" @dblclick="handleDoubleClickAddCloumn">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" fill="currentColor"><path d="M240 352V272H160C151.2 272 144 264.8 144 256C144 247.2 151.2 240 160 240H240V160C240 151.2 247.2 144 256 144C264.8 144 272 151.2 272 160V240H352C360.8 240 368 247.2 368 256C368 264.8 360.8 272 352 272H272V352C272 360.8 264.8 368 256 368C247.2 368 240 360.8 240 352zM512 256C512 397.4 397.4 512 256 512C114.6 512 0 397.4 0 256C0 114.6 114.6 0 256 0C397.4 0 512 114.6 512 256zM256 32C132.3 32 32 132.3 32 256C32 379.7 132.3 480 256 480C379.7 480 480 379.7 480 256C480 132.3 379.7 32 256 32z"/></svg>
                </span>
            </div>
        </div>
    </template>
</template>


<script lang="ts">
import { defineAsyncComponent } from 'vue';
import { Core } from '@/mixins';
import LoadingComponent from '@/components/Builder/Components/Core/Layout/Loading.vue';
import BlockSpacer from './BlockSpacer.vue';
import { getIdParentAndIndex } from '@/utils/helpers';

export default {
    name: 'Blocks',
    components: {
        BlockElement: defineAsyncComponent({
            loader: () => import('./Block.vue'),
            loadingComponent: LoadingComponent,
            delay: 0,
            timeout: 60000
        }),
        FlexContainer: defineAsyncComponent({
            loader: () => import('@/components/Builder/Components/Core/Elements/Base/FlexContainer.vue'),
            loadingComponent: LoadingComponent,
            delay: 0,
            timeout: 60000
        }),
        BlockSpacer
    },
    mixins: [Core],
    props: {
        'data': {
            type: Array,
            default: () => {
                return [];
            }
        },
        'deep': {
            type: Number,
            default: 0
        },
        'control': {
            type: Boolean,
            default: true
        },
        'section_id': {
            type: String,
            default: ''
        },
        'breadcrumb': {
            type: String,
            default: ''
        },
        'dragParent': {
            type: Boolean,
            default: false
        },
        'index': {
            type: Number,
            default: 0
        },
        isFlexContainer: {
            type: Boolean,
            default: false
        },
        direction: {
            type: String,
            default: 'column'
        },
    },
    emits: ['active'],
    data() {
        return {
            is: 'blocks',
            over: false,
            timeoutId: null,
            // Lưu trữ spacing giữa các blocks
            blockSpacings: {}, // { index: spacing_value }
            displaySpacer: false,
            SpacerValue: 0,
            id: this.$helpers.randid(),
        };
    },
    mounted() {
        this.instanceStore.register(this.id, this)
    },
    watch: {
        // Gán id cho block mới ngoài computed (deep: 1 -> chỉ track thêm/bớt block,
        // không track cả cây con của từng block).
        blocks: {
            immediate: true,
            deep: 1,
            handler(val) {
                if (!Array.isArray(val)) return;
                val.forEach((block) => {
                    if (!block) return;
                    if (block.id === undefined) {
                        block.id = this.$helpers.randid();
                        block.IDInit = true;
                    }
                    if (block.group && block.IDInit !== false) {
                        block.IDInit = false;
                    }
                });
            }
        }
    },
    computed: {
        blocks() {
            return this.data;
        },
        checkInGridDrop() {
            return !this.$helpers.checkGridDrop(this.dragCurrent, this)
        },
        visibleBlocks() {
            // Getter thuần — không gán id/IDInit ở đây. Mutate trong computed khiến
            // effect tự invalidate dependency của chính nó -> Vue báo
            // "Maximum recursive updates exceeded". Normalize nằm ở watcher `blocks`.
            return this.blocks.filter((block) => {
                if (!block) return false;
                return block.visibility !== false && (
                    !block.row || block.row.visibility !== false
                );
            });
        },
        stack() {
            return this.data;
        },
        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this);
        },
        sections() {
            return this.$store.getters['page/sections'];
        },
        column() {
            return this.$parent;
        },
        cssVar() {
            const css = {};
            if (this.SpacerValue) {
                css['--ecom-global-elements-space'] = this.SpacerValue + 'px';
            } else {
                 if (this.column.data && this.column.data.settings && this.column.data.settings["margin-top"]) {
                    css["--ecom-global-elements-space"] = this.column.data.settings["margin-top"];
                }
            }
            return css;
        },
    },

    methods: {
        updateSpace(value) {
            this.displaySpacer = value;
        },
         updateSpaceValue(value) {
            this.SpacerValue = value;
        },
        onSetTabDefault() {
            this.$store.commit('SET_TAB', 'elements');
        },

        overBlocks(e) {
            if (this.isFullScreen) {
                return;
            }

            this.over = true;

            if (this.canDrop && this.isDragging) {
                // Huỷ timer đang chờ (kể cả timer setDropTo null của outBlocks)
                // trước khi đặt timer mới, tránh timer mồ côi bắn sai thứ tự
                clearTimeout(this.timmer);
                if (
                    this.blocks.length > 0 &&
                    e.target === this.$refs.wrapper
                ) {
                    if (
                        (
                            this.dragCurrent.$parent === this ||
                            this.dragCurrent.$parent.$parent === this ||
                            this.inGroup
                        )
                    ) {
                        // Reverse drag element back to current column
                        this.$store.commit('builder/setDropTo', null);
                    } else {
                        let ins = this.instanceStore.get(this.blocks[this.blocks.length - 1].id);
                        if (ins) {
                            this.timmer = setTimeout(() => {
                                if (!this.isDragging) return;
                                this.$store.commit('builder/setDropTo', ins?.data?.id);
                                this.$store.commit('builder/setDropPos', 'bottom');
                                ins.placeholder = 'bottom';
                            }, 60);
                        }
                    }
                } else if (
                    this.blocks.length === 0 &&
                    e.target === e.currentTarget
                ) {
                    this.timmer = setTimeout(() => {
                        if (!this.isDragging) return;
                        this.$store.commit('builder/setDropTo', this);
                    }, 60);
                }
            }
        },

        outBlocks() {
            if (!this.isFullScreen) {
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    if (!this.dragCurrent || !this.$parent.over) {
                        this.over = false;
                        this.$store.commit('builder/setDropTo', null);
                    }
                }, 50);
            }
        },

        activeCol(e) {
            if (e.target.classList.contains('core__empty--placeholder')) {
                this.$emit('active');
            }
        },

        backtoElements() {
            this.$store.commit('builder/setDragging', { timmer: new Date().getTime() });
            this.$store.commit('builder/setEditingElement', null);
            this.$store.commit('SET_TAB', 'elements');
            this.$store.dispatch('UPDATE_IS_TEMP_HIDE', false);
            this.$store.commit('global/setSidebarTabActive', { id: 'elements' });
        },

        handleDoubleClickAddCloumn() {
            this.$store.commit('global/toggleBorder', true);
            if (this.timeoutId) {
                clearTimeout(this.timeoutId);
            };
            this.timeoutId = setTimeout(() => {
                this.$store.commit('global/toggleBorder', false);
                this.timeoutId = null;
            }, 1000);
        },

        editColumn() {
            if (this?.$parent?.is === 'column') {
                this.$store.commit('builder/setActiveElement', this.$parent);
                this.$store.commit('builder/setEditingElement', this.$parent);
            }
        },

        dropIn(current) {
            if (this.section_id) {
                const { parent_id, index } = getIdParentAndIndex(current);
                if(!current.data.id) {
                    current.data.id = this.$helpers.randid();
                    current.data.IDInit = true;
                }
                let payload = {
                    type: 'block',
                    data: current.data,
                    section_id: this.section_id,
                    action: "moved",
                    parent_id: parent_id,
                    index: index
                }
                this.$store.dispatch('history/addStack', payload);
            }

            this.stack.push(current.dropOut());
            if (this.$parent.is == 'column') {
                this.$parent.column.refresh = this.$helpers.randid();
            }
        }
    },
};
</script>