export const generateUniqueID = () => {
    return Math.floor((1 + Math.random()) * 0x10000)
            .toString(8)
            .substring(1);
}
export  function countStringBytes(str: string): number {
    // Create a TextEncoder for UTF-8 encoding
    const encoder = new TextEncoder();
  
    // Encode the string into bytes
    const encodedBytes = encoder.encode(str);
  
    // Return the length of the byte array
    return  (encodedBytes.length / 1024).toFixed(2) as any;
  }

export const markdown = (markdownText: string) => {
    if (!markdownText) {
        return '';
    }
    const regex = /(?:https?:)?(?:\/\/)?(?:[0-9A-Z-]+\.)?(?:youtu\.be\/|youtube(?:-nocookie)?\.com\S*?[^\w\s-])([\w-]{11})(?=[^\w-]|$)(?![?=&+%\w.-]*(?:['"][^<>]*>|<\/a>))[?=&+%\w.-]*/gim;

    const htmlText = markdownText
        .replace(/^#### (.*$)/gim, '<h4 class="text-base font-medium text-text-primary ">$1</h4>')
        .replace(/^### (.*$)/gim, '<h3 class="text-base font-semibold text-text-primary ">$1</h3>')
        .replace(/^## (.*$)/gim, '<h2 class="text-sm font-semibold text-text-primary ">$1</h2>')
        .replace(/^# (.*$)/gim, '<h1 class="text-xl font-semibold text-text-primary ">$1</h1>')
        .replace(/^\\> (.*$)/gim, '<blockquote>$1</blockquote>')
        .replace(/\*\*([^\*]+)\*\*/gim, '<strong class="text-text-primary font-semibold">$1</strong>')
        .replace(/\*(.*)\*/gim, '<i>$1</i>')
        .replace(/!\[(.*?)\]\((.*?)\)/gim, '<img alt=\'$1\'  src=\'$2\' />')
        .replace(regex,`<iframe src="https://www.youtube-nocookie.com/embed/$1" class="aspect-video aspect-w-16 aspect-h-9" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allow-fullScreen></iframe>`)
        .replace(
            /\[(.*?)\]\((#.*?)\)/gim,
            `
        <a href='$2' class="ecom-markdown-link font-medium text-text-primary underline hover:no-underline hover:text-secondary-700 ecom-field-open-settings">$1
        </a>`
        )
        .replace(
            /\[(.*?)\]\((.*?)\)/gim,
            `
        <a href='$2' class="ecom-markdown-link font-medium text-text-primary underline hover:no-underline hover:text-secondary-700 break-words" target='_blank'>$1
            <svg xmlns="http://www.w3.org/2000/svg" class="inline-flex h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                <path d="M11 3a1 1 0 100 2h2.586l-6.293 6.293a1 1 0 101.414 1.414L15 6.414V9a1 1 0 102 0V4a1 1 0 00-1-1h-5z" />
                <path d="M5 5a2 2 0 00-2 2v8a2 2 0 002 2h8a2 2 0 002-2v-3a1 1 0 10-2 0v3H5V7h3a1 1 0 000-2H5z" />
            </svg>
        </a>`
        )
        .replace(/`([^`]+)`/gim, '<code>$1</code>')
        .replace(/\n$/gim, '<br />');

    return htmlText.trim();
}
export const slugify = (str: string)=>{
    const characterMap :Object = {
        'à': 'a', 'á': 'a', 'ả': 'a', 'ã': 'a', 'ạ': 'a',
        'è': 'e', 'é': 'e', 'ẻ': 'e', 'ẽ': 'e', 'ẹ': 'e',
        'ì': 'i', 'í': 'i', 'ỉ': 'i', 'ĩ': 'i', 'ị': 'i',
        'ò': 'o', 'ó': 'o', 'ỏ': 'o', 'õ': 'o', 'ọ': 'o',
        'ù': 'u', 'ú': 'u', 'ủ': 'u', 'ũ': 'u', 'ụ': 'u',
        'ỳ': 'y', 'ý': 'y', 'ỷ': 'y', 'ỹ': 'y', 'ỵ': 'y',
        'đ': 'd',
        'Ă': 'A', 'Â': 'A', 'Đ': 'D', 'Ê': 'E', 'Ô': 'O', 'Ơ': 'O', 'Ư': 'U',
        'ă': 'a', 'â': 'a', 'ê': 'e', 'ô': 'o', 'ơ': 'o', 'ư': 'u',
      };
    
      return str
        .split('')
        .map(char => characterMap[char] || char)
        .join('')
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/--+/g, '-')
        .replace(/^-+|-+$/g, '');
}

/**
 * Shopify Admin GraphQL trả `currencyFormats.moneyFormat` ở dạng đã HTML-escape
 * (`&lt;span class=money&gt;${{amount}}&lt;/span&gt;`) trong khi storefront dùng bản raw.
 * Không decode thì mọi chỗ đổ giá bằng innerHTML/v-html sẽ in ra nguyên chuỗi thẻ HTML.
 */
export function decodeHtmlEntities(value: any): any {
    if (typeof value !== 'string' || value.indexOf('&') === -1) return value;

    const named: Record<string, string> = {
        amp: '&',
        lt: '<',
        gt: '>',
        quot: '"',
        apos: "'",
        nbsp: ' '
    };

    // Một lượt duy nhất: `&amp;lt;` giữ nguyên thành `&lt;`, không bị decode chồng.
    return value.replace(/&(#x[0-9a-fA-F]+|#[0-9]+|[a-zA-Z]+);/g, (match, code: string) => {
        if (code[0] === '#') {
            const codePoint = code[1] === 'x' || code[1] === 'X'
                ? parseInt(code.slice(2), 16)
                : parseInt(code.slice(1), 10);

            return Number.isFinite(codePoint) && codePoint > 0
                ? String.fromCodePoint(codePoint)
                : match;
        }

        return named[code.toLowerCase()] ?? match;
    });
}
