<i18n>
{
    "en": {
        "unlink": "Unlink",
        "link": "Link"
    },
    "fr": {
        "unlink": "Supprimer le lien",
        "link": "Lien"
    },
    "de": {
        "unlink": "Verknüpfung entfernen",
        "link": "Verknüpfung"
    },
    "ja": {
        "unlink": "リンク解除",
        "link": "リンク"
    }
}
</i18n>
<template>
    <div
        class="relative mt-2"
        :class="isSimple ? 'h-[128px]' : 'h-[200px]'"
    >
            <div
                v-if="current.name && !input.show"
                class="fixed top-0 left-0 z-50 w-full h-full"
                :style="{cursor}"
            />

        <div
            v-if="unitsLength > 1"
            class="absolute right-0 flex mb-3 bottom-full"
            :class="unitPopoverId"
        >
            <button
                type="button"
                class="px-1.5 h-[19px] uppercase border-0 focus:outline-none focus:ring-0 min-w-6 text-tiny font-medium rounded bg-dark text-white text-[10px] flex items-center justify-between gap-2"
                @click="toggleUnitPopover"
            >
                {{ unit }}
                <svg width="8" height="6" viewBox="0 0 8 6" fill="none" xmlns="http://www.w3.org/2000/svg"><g clip-path="url(#clip0_1962_2099)"><path fill-rule="evenodd" clip-rule="evenodd" d="M0.239665 1.20041C0.543198 0.918556 1.01775 0.936132 1.2996 1.23966L4 4.14779L6.70041 1.23966C6.98226 0.936132 7.45681 0.918556 7.76034 1.20041C8.06387 1.48226 8.08145 1.95681 7.7996 2.26034L4.5496 5.76034C4.40769 5.91317 4.20855 6 4 6C3.79145 6 3.59232 5.91317 3.45041 5.76034L0.200408 2.26034C-0.081444 1.95681 -0.0638681 1.48226 0.239665 1.20041Z" fill="#ffffff" style="fill:#ffffff;fill-opacity:1;"/></g><defs><clipPath id="clip0_1962_2099"><rect width="8" height="6" fill="white" style="fill:white;fill-opacity:1;"/></clipPath></defs></svg>
            </button>
            <div
                v-if="unitPopoverOpen"
                class="shadow-md flex gap-1 py-1 px-1 top-full translate-y-1 absolute bg-white rounded transition z-20 right-0"
            >
                <button
                    v-for="key in unitsKey"
                    :key="key"
                    type="button"
                    class="px-2 h-[19px] leading-4 uppercase border-0 focus:outline-none focus:ring-0 min-w-5 text-tiny font-medium rounded hover:bg-gray-100"
                    :class="{'bg-dark text-white': unit === key}"
                    @click="selectUnit(key)"
                >
                    {{ key }}
                </button>
            </div>
        </div>
        <Box
            v-if="isSimple"
            v-model:data="valueInput"
            :responsiveData="responsiveData ? responsiveData : {}"
            v-model:current="current"
            size="small"
            class="w-full"
            v-bind="bindAttr"
            @click-input="clickInput"
            @close-input="closeInput"
            :linked="linked"
        />
        <template v-else>
            <Box
                v-model:data="valueInput['margin']"
                :responsiveData="responsiveData ? responsiveData['margin'] : {}"
                v-model:current="current"
                type="margin"
                v-bind="bindAttr"
                @click-input="clickInput"
                @close-input="closeInput"
            />
            <Box
                v-model:data="valueInput['padding']"
                v-model:current="current"
                type="padding"
                size="small"
                class="w-57"
                :responsiveData="responsiveData ? responsiveData['padding'] : {}"
                :unit-configs="unitConfigs"
                :linked="linked"
                :v-bind="bindAttr"
                @click-input="clickInput"
                @close-input="closeInput"
            />
        </template>
        <button
            class="absolute flex items-center justify-center transition transform -translate-x-1/2 -translate-y-1/2 top-1/2 left-1/2 box-sizing group border border-input rounded-lg w-[60px] h-8"
            :class="[linked ? 'bg-dark text-white !border-dark' : 'bg-white hover:bg-dark hover:!border-dark hover:text-white']"
            type="button"
            :data-tooltip="linked ? $t('unlink') : $t('link')"
            @click="linked = !linked"
        >
            <EcomIcon :source="icons.LinkMinor" :size="'w-5'" :color=" linked ? 'text-white' : 'text-icon-primary group-hover:text-white'" class="flex items-center"></EcomIcon>
        </button>
        <InputComponent
            ref="input"
            v-model:number="input.value"
            :payload="input"
            :unit-configs="unitConfigs"
            :type="current.type"
        />
    </div>
</template>


<script lang="ts">
    import InputComponent from './Input.vue';
    import Box from './Box.vue';

    import { dragMixin } from '../../mixins';
    import {LinkMinor} from '@/assets/icons';

    export default {
        name: 'Dimension',
        components: {
            Box,
            InputComponent
        },
        mixins: [dragMixin],
        props: {
            data: Object,
            responsiveData: Object,
            field: {
                type: Object,
                default() { return {} ;}
            }
        },
        emits: ['update:data'],
        data() {
            return {
                icons: {
                    // faLink,
                    LinkMinor
                },
                linked: false,
                isWatch: true,
                isEmit: false,
                current: {},
                unit: null,
                input: {
                    value: null,
                    show: false,
                    pos: {}
                },
                valueInput: {},
                isChangeScreen: false,
                unitPopoverOpen: false,
                unitPopoverId: 'unit-popover-' + Math.random().toString(36).substr(2, 9)
            };
        },
        computed: {
            currentScreen(){
                return this.$store.getters['builder/currentScreen'];
            },
            bindAttr() {
                return {
                    unit: this.unit,
                    linked: this.linked,
                    field: this.field,
                    unitConfigs: this.unitConfigs
                };
            },
            options() {
                return this.field.options ?? {};
            },
            units() {
                let unitsDefault = {
                    margin: {
                        px: {
                            min: -500,
                            max: 500
                        },
                        '%': {
                            min: -100,
                            max: 100
                        },
                        em: {
                            min: -100,
                            max: 100
                        },
                        rem: {
                            min: -100,
                            max: 100
                        }
                    },
                    padding: {
                        px: {
                            min: 0,
                            max: 500
                        },
                        '%': {
                            min: 0,
                            max: 100
                        },
                        em: {
                            min: 0,
                            max: 100
                        },
                        rem: {
                            min: 0,
                            max: 100
                        }
                    },
                    radius: {
                        px: {
                            min: 0,
                            max: 400
                        },
                        '%': {
                            min: 0,
                            max: 100
                        }
                    }
                };
                let units = this.options.units;
                if(units === 'default') {
                    if(this.isSimple) {
                        if(this.isRadius) {
                            return unitsDefault.radius;
                        }
                        return unitsDefault[this.fieldName ?? 'padding'];
                    }
                    return {
                        margin: unitsDefault.margin,
                        padding: unitsDefault.padding
                    };
                }
                return units ?? {};
            },
            unitsKey(){
                if(this.isSimple) {
                    return Object.keys(this.units);
                }
                else {
                    return Object.keys(this.units.margin ?? {});
                }
            },
            unitsLength(){
                return this.unitsKey.length;
            },
            unitConfigs() {
                let configs = {};
                let { type } = this.current;
                let d = {
                    min: type === 'margin' ? -1000 : 0,
                    max: 1000,
                    step: 1
                };
                ['min', 'max', 'step'].forEach(c => {
                    let units = !this.isSimple ? this.units?.[type] : this.units;
                    configs[c] = units?.[this.unit]?.[type]?.[c] ??
                        units?.[this.unit]?.[c] ??
                        this.options?.[c] ?? d[c];
                });
                return configs;
            },
            isSimple() {
                return this.options.simple || this.options.type === 'radius';
            },
            isRadius() {
                return this.options.type === 'radius';
            },
            values(){
                let values = {};
                const set = (obj, vs) => {
                    for(let key in vs){
                        let v = vs[key];
                        if(v !== undefined && v !== null && v !== '' && ((isNaN(v) && typeof v !== 'number') || (!isNaN(v) && typeof v === 'number'))) {
                            if(!this.unit){
                                obj[key] = v;
                            }
                            else {
                                if(v === 'none') {
                                    delete(obj[key]);
                                } else {
                                    obj[key] = typeof v === 'number' ? (v + this.unit.replace('NaN', '').replace('auto', '')) : v;
                                }

                            }
                        }
                    }
                };
                if(!this.isSimple) {
                    for(let type in this.valueInput) {
                        values[type] = values[type] ?? {};
                        set(values[type], this.valueInput[type]);
                    }
                }
                else {
                    set(values, this.valueInput);
                }

                return values;
            },
            cursor() {
                return this.dragDir(this.current.type || this.fieldName, this.current.name)?.c;
            },
            fieldName() {
                return Object.keys(this.field.css?.properties ?? {})[0] ?? this.field.name;
            }
        },
        watch: {
            values: {
                immediate: true,
                handler: function(val){
                    if(this.isEmit){
                        this.isWatch = false;
                        this.$emit('update:data', val);
                    }
                    if(!this.isChangeScreen) {
                        this.isEmit = true;
                    }
                }
            } ,
            currentScreen() {
                this.isChangeScreen = true;
                setTimeout(() => this.isChangeScreen = false, 200)
            },
            data: {
                deep: true,
                immediate: true,
                handler: function(val){
                    if(this.isWatch || this.isSimple){
                        this.isEmit = false;
                        this.extractData(val ?? {});
                    }
                    this.isWatch = true;

                }
            },
            'input.value': function(val) {
                let {type, name} = this.current;
                if(name) {
                    if(val !== '') {
                        let v;
                        if(type) {
                            this.valueInput[type] = this.valueInput[type] ?? {};
                            v = this.valueInput[type];
                        }
                        else {
                            v = this.valueInput;
                        }
                        v[name] = val;
                    }
                    else {
                        if(type) {
                            delete this.valueInput?.[type]?.[name];
                            if(Object.keys(this.valueInput[type]).length === 0) {
                                delete this.valueInput[type];
                            }
                        }
                        else {
                            delete this.valueInput?.[name];
                        }

                    }

                }

            }
        },
        methods: {
            getUnit(value){
                let unit = '';
                if(typeof value === 'string'){
                    unit = /\D+$/g.exec(value)?.[0] ?? '';
                }

                return unit;
            },
            extractData(values){
                if(Object.keys(values).length){
                    this.link = false;
                    let valueInput = {};
                    let unit = '';
                    const set = (obj, v) => {
                        for(let key in v){
                            if(v[key] !== undefined) {
                                obj[key] = v[key] === 'auto' ? v[key] : parseFloat(v[key]);
                            }

                            unit = this.getUnit(v[key]);

                        }
                    };
                    if(!this.isSimple) {
                        for(let type in values) {
                            valueInput[type] = valueInput[type] ?? {};
                            set(valueInput[type], values[type]);
                        }
                    }
                    else {
                        set(valueInput, values);
                    }

                    this.unit = (unit !== 'auto' && unit != '') ? unit : (this.unitsKey[0] ?? '');
                    this.valueInput = valueInput;
                }
                else {
                    this.unit = this.unitsKey?.[0] ?? '';
                    this.valueInput = {};
                }

                if(this.isWatch) {
                    this.linked = this.isLinked(this.valueInput)
                }
            },
            isLinked(obj) {
                const sameValue = (o) => {
                    if(o !== null && typeof o === 'object') {
                        let vs = Object.values(o);
                        if(vs.length === 4) {
                            return vs[0] === vs[1] &&
                                    vs[1] === vs[2] &&
                                    vs[2] === vs[3];
                        }
                    }
                    return false;
                };
                let c = true;
                if(typeof Object.values(obj)[0] === 'object') {
                    for(const k in obj) {
                        c = sameValue(obj[k]);
                    }
                }
                else {
                    c = sameValue(obj);
                }
                return !!c;
            },
            clickInput({value, el}) {
                if(!el) {
                    this.input = {};
                    return;
                }
                if(!this.input.show) {
                    this.$refs.input.acceptClose = false;
                    let rect = this.$el.getBoundingClientRect(),
                        rectEl = el.getBoundingClientRect();
                        let topOffset = rectEl.y - rect.y + el.offsetHeight + 10;
                        if(topOffset + rect.top + rect.height > window.innerHeight) {
                            // Hiển thị ngay bên trên input
                            // Khoảng cách từ input đến top của parent - chiều cao dropdown - spacing
                            const inputTopOffset = rectEl.top - rect.top;
                            // height của popup input là 134px
                            topOffset = inputTopOffset - 134 - 10;
                        }
                    this.input = {
                        value, show: true,
                        pos: {
                            top: topOffset,
                            left: rectEl.x - rect.x
                        }
                    };
                }
                else {
                    this.current = {};
                    this.input = {};
                }

            },
            closeInput() {
                this.input = {};
            },
            toggleUnitPopover() {
                this.unitPopoverOpen = !this.unitPopoverOpen;
                if (this.unitPopoverOpen) {
                    document.addEventListener('click', this.closeUnitPopover);
                }
            },
            selectUnit(key) {
                this.unit = key;
                this.closeUnitPopover();
            },
            closeUnitPopover(e) {
                if (
                    e === undefined ||
                    !e.target.closest('.' + this.unitPopoverId)
                ) {
                    this.unitPopoverOpen = false;
                    document.removeEventListener('click', this.closeUnitPopover);
                }
            }
        }
    };
</script>
