import { addWindowEventListener, removeWindowEventListener } from "../../helpers/DOM";
import { ensureNumericValue } from "../../helpers/utils";
// @ts-ignore
import { rotate_icon } from "@/assets/icons";
import { SelectionHandler } from "./SelectionHandler";
import type { SelectionOptions, SelectionEvents } from "./SelectionTypes";
import { GuidelineUtils } from "./utils/GuidelineUtils";
import type { GridLayoutInstance } from "./types/GridLayoutTypes";
import { gridDebug } from "../../helpers/debug";
export default {
    name: "GridLayout",
    inject: ["eventBus", "exporting", "instanceStore"],
    mixins: [Core],
    emits: ["layout-created", "layout-updated", "update-scale-ratio", "updateSelectionStatus"],
    props: {
        // If true, the container height swells and contracts to fit contents
        autoSize: {
            type: Boolean,
            default: true
        },
        colNum: {
            type: Number,
            default: 12
        },
        rowHeight: {
            type: Number,
            default: 150
        },
        maxRows: {
            type: Number,
            default: Infinity
        },
        margin: {
            type: Array,
            default: function () {
                return [10, 10];
            }
        },
        isDraggable: {
            type: Boolean,
            default: true
        },
        isResizable: {
            type: Boolean,
            default: true
        },
        isMirrored: {
            type: Boolean,
            default: false
        },
        useCssTransforms: {
            type: Boolean,
            default: true
        },
        verticalCompact: {
            type: Boolean,
            default: true
        },
        layout: {
            type: Array<LayoutItem>,
            required: true
        },
        responsive: {
            type: Boolean,
            default: false
        },
        responsiveLayouts: {
            type: Object,
            default: function () {
                return {};
            }
        },
        breakpoints: {
            type: Object,
            default: function () {
                return { lg: 1200, md: 996, sm: 0 };
            }
        },
        cols: {
            type: Object,
            default: function () {
                return { lg: 12, md: 12, sm: 12 };
            }
        },
        preventCollision: {
            type: Boolean,
            default: false
        },
        section_id: {
            type: String,
            default: null
        },
        data: {
            type: Object
        },
        isPreview: {
            type: Boolean,
            default: false
        }
    },
    data: function () {
        return {
            is: "selection",
            timmer: null,
            icons: {
                rotate: rotate_icon
            },
            width: window.screen.width,
            mergedStyle: {},
            lastLayoutLength: 0,
            isDraggingGrid: false,
            rows: 300,
            placeholder: {
                i: "placeholder",
                left: 0,
                top: 0,
                width: 0,
                height: 0,
                rotation: 0,
                dirX: "",
                dirY: "",
                snapEdge: "",
                snapEdgeRight: "",
                snapColIndex: 0,
                snapColIndexRight: 0
            },
            layouts: {}, // array to store all layouts from different breakpoints
            lastBreakpoint: null, // store last active breakpoint
            guidelineUtils: null as GuidelineUtils | null,
            gutter: 20,
            resizeEventHandler: null,
            dragEventHandler: null,
            erd: null,
            over: false,
            isSelecting: false,
            hasSelection: false, // Trạng thái có item được chọn
            selectionStart: { x: 0, y: 0 },
            selectionEnd: { x: 0, y: 0 },
            selectionBorders: {
                h: [], // Đường viền ngang
                v: [] // Đường viền dọc
            },
            selectedItems: [],
            selectionRatio: false,
            selectionArea: {
                minX: 0,
                minY: 0,
                maxX: 0,
                maxY: 0
            },
            isDraggingMultiple: false,
            lastSelectionTimestamp: 0,
            isResizingSelection: false, // Trạng thái đang resize selection
            isResizingSelectionMove: false, // Trạng thái đang resize selection
            selectionResizeStart: { x: 0, y: 0 }, // Vị trí bắt đầu resize
            selectionResizeType: "", // Loại resize (n, s, e, w, ne, nw, se, sw)
            selectionResizeInitial: {
                // Kích thước và vị trí ban đầu của selection trước khi resize
                minX: 0,
                minY: 0,
                maxX: 0,
                maxY: 0
            },
            selectionResizeRatio: 1, // Tỷ lệ width/height của selection khi resize giữ tỷ lệ,
            lastMouseX: 0,
            lastMouseY: 0,
            isResizingSelectionFlag: false,
            isRotatingSelection: false,
            selectionRotateStart: { x: 0, y: 0 },
            selectionRotationAngle: 0,
            selectionRotationCenter: { x: 0, y: 0 },
            selectionRotateInitial: {}, // Lưu trữ góc quay ban đầu của các items
            lastRotationMouseX: 0,
            lastRotationMouseY: 0,
            lastAngle: undefined,
            innerRowHeight: 1,
            containerCenter: {
                x: 0,
                y: 0
            },
            itemWidthPx: 0,
            itemHeightPx: 0,
            isResizing: false,
            resizingSizePosition: { top: 0, left: 0 },
            selectedItemsInitialPos: [],
            isItemInContainer: true,
            isNormalZoom: true,
            isGroupDragging: false,
            // Khoảng cách tối đa để hiển thị guide (px)
            maxGuideDistance: 100,
            dragStartPosition: null,
            _heightUpdateRAF: null,
            scaleRatio: 1,
            guideLinePosition: 0, // Vị trí pixel cho guide line
            containerWidth: 0 // Lưu chiều rộng container
        };
    },
    created() {
        if (this.exporting) return;
        const self = this;
        // Accessible refernces of functions for removing in beforeDestroy
        self.resizeEventHandler = function ({
            eventType,
            i,
            x,
            y,
            h,
            w,
            edges,
            rotation,
            section_id
        }) {
            if (section_id !== self.section_id) return;
            self.resizeEvent(eventType, i, x, y, h, w, edges, rotation);
        };

        self.dragEventHandler = function ({
            eventType,
            i,
            x,
            y,
            h,
            w,
            rotation,
            section_id,
            undo = false,
            data = null
        }) {
            if (self.section_id !== section_id) return;
            if (eventType) self.dragEvent(eventType, i, x, y, h, w, rotation);
            // show border selection khi redo  của xoá selection
            // if(undo) {
            //     self.$store.commit(
            //         "builder/setActiveSelection", null
            //     );
            //     if(data) {
            //         self.selectedItems = data;

            //         if(!Object.keys(self.activeElements).length) {
            //             self.$nextTick(() => {
            //                 self.selectedItems.forEach((item) => {
            //                     const inst = self.instanceStore.get(item.i);
            //                     let blockElement = !["block", "row", "blocks"].includes(inst?.is)
            //                         ? inst
            //                         : inst.$refs.blockElement;
            //                     if (inst?.data?.row) {
            //                         blockElement = inst;
            //                     }
            //                     if (inst && inst.$refs && blockElement) {
            //                         self.$store.commit("builder/setActiveElements", blockElement);
            //                     }
            //                 })
            //             })
            //         }
            //         else {
            //             // chưa update đúng được vị trí group settings
            //             self.updateSelectionBorders();
            //         }
            //         self.eventBus.emit("groupSettingsOpen", {
            //             sectionId: self.section_id,
            //             isSelection: true,
            //             preferPosition: "top-center"
            //         });
            //         self.$store.commit(
            //             "builder/setActiveSelection",
            //             `grid-layout-${self.section_id}`
            //         );
            //     }
            //     else {
            //         self.selectedItems = [];
            //         self.updateSelectionBorders();
            //         self.eventBus.emit("groupSettingsClose");
            //     }
            // }
        };

        self.eventBus.on("resizeEvent", self.resizeEventHandler);
        self.eventBus.on("dragEvent", self.dragEventHandler);
        this.$emit("layout-created", self.layout);
    },
    beforeUnmount: function () {
        // Remove listeners
        this.eventBus.off("resizeEvent", this.resizeEventHandler);
        this.eventBus.off("dragEvent", this.dragEventHandler);
        this.instanceStore.unregister(`grid-layout-${this.section_id}`);
        this.eventBus.off("selectionDeleted", this.clearSelection);
        removeWindowEventListener("resize", this.onWindowResize);
        this.eventBus.off("groupDragging", this.handleGroupDragging);
        this.eventBus.off("updateGroupPlaceholder", this.updateGroupPlaceholder);
        this.eventBus.off("selectionDeleted", this.clearSelection);
        this.eventBus.off("setGridSelectionItems");
        this.eventBus.off("selectionDeleted");
        if (this.selectionHandler) {
            this.selectionHandler.destroy();
            this.selectionHandler = null;
        }
        if (this.guidelineUtils) {
            this.guidelineUtils.destroy();
            this.guidelineUtils = null;
        }
        if (this.erd && this.$refs.item) {
            this.erd.uninstall(this.$refs.item);
        }
    },
    mounted() {
        this.instanceStore.register(`grid-layout-${this.section_id}`, this);

        this.$nextTick(() => {
            const self = this;
            this.$nextTick(() => {
                self.onWindowResize();

                self.initResponsiveFeatures();

                // self.width = self.$el.offsetWidth;
                addWindowEventListener("resize", this.onWindowResize);

                compact(self.layout, self.verticalCompact);

                //self.$emit("layout-updated", self.layout);
                if (!self.data?.settings?.["min-height"]) {
                    self.updateHeight();
                }
                self.$nextTick(() => {
                    if (!this.erd && self.$refs.item) {
                        this.erd = elementResizeDetectorMaker({
                            strategy: "scroll", //<- For ultra performance.
                            callOnAdd: false
                        });
                        this.erd.listenTo(self.$refs.item, function () {
                            self.onWindowResize();
                        });
                    }
                });
            });
            if (Object.keys(this.activeElements).length > 0) {
                this.layout.forEach((item) => {
                    // Bỏ qua các placeholder
                    if (
                        !item.i ||
                        item.i.startsWith("selection-") ||
                        item.i.startsWith("ecom-grid-placeholder")
                    ) {
                        return;
                    }
                    Object.keys(this.activeElements).forEach((key) => {
                        if (key === item.i) {
                            this.selectedItems.push(item);
                        }
                    });
                });
                this.updateSelectionBorders();

                this.eventBus.emit("groupSettingsOpen", {
                    sectionId: this.section_id,
                    isSelection: true,
                    preferPosition: "top-center"
                });
            }
        });
        this.eventBus.on("selectionDeleted", this.clearSelection);

        this.eventBus.on("groupDragging", (data) => {
            if (this.section_id === data.sectionId) {
                this.handleGroupDragging(data);
            }
        });
        this.eventBus.on("setGridSelectionItems", (data) => {
            if (this.selectionHandler) {
                this.selectionHandler.setGridSelectionItems(data);
            }
        });

        this.eventBus.on("selectionDeleted", () => {
            if (this.selectionHandler) {
                this.selectionHandler.clearSelection();
            }
        });
        this.eventBus.on("updateGroupPlaceholder", this.updateGroupPlaceholder);

        this.updateScaleRatio();

        const selectionOptions: SelectionOptions = {
            enableSelection: true,
            multiSelectThreshold: 2,
            selectionTolerance: 5
        };

        const selectionEvents: SelectionEvents = {
            onSelectionStart: (data) => {},
            onSelectionMove: (data) => {},
            onSelectionEnd: (data) => {
                // Handle selection end
            },
            onSelectionCleared: () => {
                // Handle selection cleared
            }
        };

        this.selectionHandler = new SelectionHandler(this, selectionOptions, selectionEvents);
        this.selectionHandler.initSelection();

        this.guidelineUtils = new GuidelineUtils(this as GridLayoutInstance);
    },
    computed: {
        centerV(): boolean {
            return this.guidelineUtils?.centerV || false;
        },
        centerH(): boolean {
            return this.guidelineUtils?.centerH || false;
        },
        sameV(): any[] {
            return this.guidelineUtils?.sameV || [];
        },
        sameH(): any[] {
            return this.guidelineUtils?.sameH || [];
        },
        guideLineLeft(): number {
            return this.guidelineUtils?.guideLineLeft || 0;
        },
        guideLineRight(): number {
            return this.guidelineUtils?.guideLineRight || 0;
        },
        guideLineX(): any {
            return this.guidelineUtils?.guideLineX || { x: 0, y: 0, w: 0 };
        },
        guideLineY(): any {
            return this.guidelineUtils?.guideLineY || { x: 0, y: 0, h: 0 };
        },
        guideLineXDistance(): number {
            return this.guidelineUtils?.guideLineXDistance || 0;
        },
        guideLineYDistance(): number {
            return this.guidelineUtils?.guideLineYDistance || 0;
        },
        nearbyItems(): any {
            return (
                this.guidelineUtils?.nearbyItems || {
                    left: null,
                    right: null,
                    top: null,
                    bottom: null
                }
            );
        },
        distanceGuides(): any {
            return (
                this.guidelineUtils?.distanceGuides || {
                    left: { visible: false },
                    right: { visible: false },
                    top: { visible: false },
                    bottom: { visible: false }
                }
            );
        },
        sections() {
            return this.$parent.sections || [];
        },
        editorConfigs() {
            return this.$store.getters["builder/editorConfigs"];
        },
        isDragDifferent() {
            return this.dragCurrent && this.dragCurrent?.section_id !== this.section_id;
        },
        currentScreen() {
            return this.$store.getters["builder/screen"];
        },
        sizeIndicatorStyle() {
            return {
                position: "fixed",
                top: this.resizing ? this.resizing.top - 35 : 0,
                left: this.resizing ? this.resizing.left : 0,
                backgroundColor: "rgba(52, 152, 219, 0.9)",
                color: "white",
                padding: "3px 8px",
