        guideLineYLabelStyle() {
            return {
                position: "absolute",
                left: "2px",
                top: "50%",
                transform: "translateY(-50%)",
                backgroundColor: "rgba(52, 152, 219, 0.8)",
                color: "white",
                padding: "2px 4px",
                borderRadius: "4px",
