            };
        },
        placeholderColumns() {
            return Array.from({ length: 12 }, (_, index) => ({
                index: index + 1,
                style: {
                    gridColumn: `${index + 1} / span 1`,
                    height: "100%"
                }
            }));
        },
        responsiveGutter() {
            const currenScreen = this.currentScreen;

            // Điều chỉnh gutter dựa trên breakpoint
            switch (currenScreen) {
                case "mobile": // Mobile
                    return 5; // Gutter nhỏ hơn cho mobile
                case "tablet": // Tablet
                    return 8; // Gutter vừa phải cho tablet
                default:
                    return this.gutter; // Giữ nguyên gutter cho desktop
            }
        },
        columnTemplate() {
            return `repeat(${this.responsiveColumnCount}, 1fr)`;
        },
        responsiveColumnCount() {
            const currenScreen = this.currentScreen;

            switch (currenScreen) {
                case "mobile": // Mobile
                    return 4; // Ít cột hơn cho mobile
                case "tablet": // Tablet
                    return 8; // Số cột vừa phải cho tablet
                case "lg": // Desktop
                default:
                    return 12; // 12 cột cho desktop
            }
        },
        selectionBoxStyle() {
            if (!this.isSelecting) return {};

            const rect = this.$refs.item.getBoundingClientRect();
            const startX = Math.min(this.selectionStart.x, this.selectionEnd.x);
            const startY = Math.min(this.selectionStart.y, this.selectionEnd.y);
            const width = Math.abs(this.selectionEnd.x - this.selectionStart.x);
            const height = Math.abs(this.selectionEnd.y - this.selectionStart.y);

            return {
                position: "absolute",
                left: `${startX}px`,
                top: `${startY}px`,
                width: `${width}px`,
                height: `${height}px`,
                backgroundColor: "rgba(52, 152, 219, 0.1)",
                border: "1px dashed #3498db",
                pointerEvents: "none",
                zIndex: 900
            };
        },
        currentCols: function () {
            let newBreakpoint = getBreakpointFromWidth(this.breakpoints, this.width);
            let newCols = getColsFromBreakpoint(newBreakpoint, this.cols);
            return newCols;
        },
        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this.$parent);
        },
        dropTo() {
            return this.$store.getters["builder/dropTo"];
        },
        activeElements() {
            return this.$store?.getters["builder/activeElements"];
        },
        // Tính toán vị trí các handle resize dựa trên selectionArea
        selectionResizeHandles() {
            if (!this.hasSelection) return [];

            // Lấy tọa độ chính xác từ selectionBorders thay vì selectionArea
            const topBorder = this.selectionBorders.h[0];
            const bottomBorder = this.selectionBorders.h[1];
            const leftBorder = this.selectionBorders.v[0];
            const rightBorder = this.selectionBorders.v[1];

            if (!topBorder || !bottomBorder || !leftBorder || !rightBorder) return [];

            const minX = leftBorder.x;
            const maxX = topBorder.x + topBorder.w;
            const minY = topBorder.y + 0.5;
            const maxY = bottomBorder.y + 0.5;

            if (this.selectedItems.length) {
                this.selectionRatio = this.selectedItems.find((item) => item.options?.ratioSize)
                    ? true
                    : false;
            }

            // Tính vị trí giữa các cạnh một cách chính xác
            const middleX = minX + (maxX - minX) / 2;
            const middleY = minY + (maxY - minY) / 2;
            if (this.selectionRatio) {
                return [
                    // Các handle ở góc
                    { x: minX, y: minY, type: "nw", class: "ecom-selection-resizable-handle-nw" }, // Tây-bắc
                    { x: maxX, y: minY, type: "ne", class: "ecom-selection-resizable-handle-ne" }, // Đông-bắc
                    { x: minX, y: maxY, type: "sw", class: "ecom-selection-resizable-handle-sw" }, // Tây-nam
                    { x: maxX, y: maxY, type: "se", class: "ecom-selection-resizable-handle-se" } // Đông-nam
                ];
            }
            return [
                // Các handle ở giữa cạnh
                { x: middleX, y: minY, type: "n", class: "ecom-selection-resizable-handle-n" }, // Bắc
                { x: middleX, y: maxY, type: "s", class: "ecom-selection-resizable-handle-s" }, // Nam
                { x: minX, y: middleY, type: "w", class: "ecom-selection-resizable-handle-w" }, // Tây
                { x: maxX, y: middleY, type: "e", class: "ecom-selection-resizable-handle-e" }, // Đông

                // Các handle ở góc
                { x: minX, y: minY, type: "nw", class: "ecom-selection-resizable-handle-nw" }, // Tây-bắc
                { x: maxX, y: minY, type: "ne", class: "ecom-selection-resizable-handle-ne" }, // Đông-bắc
                { x: minX, y: maxY, type: "sw", class: "ecom-selection-resizable-handle-sw" }, // Tây-nam
                { x: maxX, y: maxY, type: "se", class: "ecom-selection-resizable-handle-se" } // Đông-nam
            ];
        },
        selectionRotateStyle() {
            return {
                // Style cho biểu tượng rotate
                position: "absolute",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: "#3498db",
                borderRadius: "50%",
                width: "20px",
                height: "20px",
                color: "white",
                cursor: "pointer",
                zIndex: 1000
            };
        },
        minHeight() {
            return this.data?.settings["min-height"];
        },
        params() {
            return this.$store.getters['page/params'];
        }
    },
    watch: {
        width: function (width) {
            this.$nextTick(() => {
                if (this.timmer) clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    this.eventBus.emit("updateWidth", {
                        width: width,
                        section_id: this.section_id
                    });
                }, 50);
            });
        },
        minHeight: {
            handler: function (newVal) {
                this.updateHeight();
            },
            deep: true
        },
        rowHeight: function () {
            this.eventBus.emit("setRowHeight", this.rowHeight);
        },
        isDraggable: function () {
            this.eventBus.emit("setDraggable", this.isDraggable);
        },
        isResizable: function () {
            this.eventBus.emit("setResizable", this.isResizable);
        },
        maxRows: function () {
            this.eventBus.emit("setMaxRows", this.maxRows);
        },
        margin(newVal, oldVal) {
            if (!newVal.every((val, index) => val === oldVal[index])) {
                this.updateHeight();
            }
        },
        placeholder: {
            handler: function (currentVal) {
                // Validation trước khi gọi GuidelineUtils
                if (
                    !this.guidelineUtils ||
                    !currentVal ||
                    currentVal.left === undefined ||
                    currentVal.top === undefined ||
                    currentVal.width === undefined ||
                    currentVal.height === undefined
                ) {
                    return;
                }

                this.guidelineUtils.updateGuidelines(currentVal);
            },
            deep: true
        },
        activeElements: {
            handler(newActiveElements) {
                const activeElementsCount = Object.keys(newActiveElements || {}).length;

                if (activeElementsCount >= 2) {
                    // Cập nhật selectedItems trong GridLayout
                    this.selectedItems = Object.keys(newActiveElements)
                        .map((id) => {
                            const block = this.layout.find((item) => item.i === id);
                            return block ? { ...block } : null;
                        })
                        .filter(Boolean);

                    if (this.selectedItems.length >= 2) {
                        this.hasSelection = true;

                        // ===== FIX: Update SelectionHandler state =====
                        if (this.selectionHandler) {
                            this.selectionHandler.selectionState.selectedItems = [
                                ...this.selectedItems
                            ];
                            this.selectionHandler.selectionState.hasSelection = true;
                        }

                        this.updateSelectionBorders();

                        this.$nextTick(() => {
                            const topBorder =
                                this.$refs.item.querySelector(".ecom-selection-active");
                            if (topBorder && this.section_id) {
                                this.eventBus.emit("groupSettingsOpen", {
                                    el: topBorder,
                                    sectionId: this.section_id,
                                    isSelection: true,
                                    preferPosition: "top-center"
                                });
                            }
                            this.$store.commit(
                                "builder/setActiveSelection",
                                `grid-layout-${this.section_id}`
                            );
                        });
                    }
                } else {
                    this.clearSelection();
                }
            },
            deep: true
        },
        hasSelection() {
            this.$emit("updateSelectionStatus", this.hasSelection);
        }
    },
    methods: {
        gridHeight() {
            // Chiều cao của container theo pixel
            if (this.$refs.item) {
                return this.$refs.item.offsetHeight;
            }
            // Mặc định nếu chưa có ref
            return this.data?.settings?.["min-height"]
                ? parseInt(this.data.settings["min-height"])
                : 300;
        },
        startDragSelection(e: MouseEvent): void {
            if (this.selectionHandler) {
                // Sync state trước
                this.selectionHandler.syncStateFromInstance();

                // Kiểm tra và start drag
                if (
                    this.selectionHandler.dragHandler &&
                    this.selectionHandler.dragHandler.canStartDrag(e)
                ) {
                    this.selectionHandler.dragHandler.startDragSelection(e);
                }
            }
        },
        clearSelection(): void {
            if (this.selectionHandler) {
                this.selectionHandler.clearSelection();
            }
        },
        emitSelectionDragUpdate() {
            const topBorderElement = (this.$refs.item as HTMLElement).querySelector(
                ".ecom-selection-active"
            );
            if (topBorderElement) {
                this.eventBus.emit("selectionDragUpdate", {
                    el: topBorderElement,
                    sectionId: this.section_id
                });
            }
        },
        getIframeScale() {
            try {
                const iframeDoc = this.idoc();
                if (!iframeDoc || !iframeDoc.body) return 1;

                const style = window.getComputedStyle(iframeDoc.body);
                const transform = style.transform || style.webkitTransform;

                if (!transform || transform === "none") return 1;

                // Trích xuất giá trị scale từ ma trận transform
                const matrixMatch = transform.match(/matrix\((.+)\)/);
                if (matrixMatch) {
                    const matrix = matrixMatch[1].split(", ").map(parseFloat);
                    return matrix[0]; // Scale là giá trị đầu tiên trong ma trận
                }

                // Trích xuất trực tiếp từ scale
                const scaleMatch = transform.match(/scale\((.+)\)/);
                if (scaleMatch) {
                    return parseFloat(scaleMatch[1]);
                }

                return 1;
            } catch (e) {
                console.error("Error getting iframe scale:", e);
                return 1;
            }
        },
        updateScaleRatio() {
            this.$emit("update-scale-ratio", this.getIframeScale());
            this.scaleRatio = this.getIframeScale();
        },
        /**
         * Tìm GridItem component từ blockId
         * @param blockId ID của block cần tìm
         * @returns GridItem component hoặc null nếu không tìm thấy
         */
        findGridItem(blockId: string) {
            // Lấy instance từ instanceStore
            const instance = this.instanceStore.get(blockId);
            if (!instance) return null;

            let gridItem = null;
            let parent = instance;

            // Tìm trong cây component cho đến khi tìm thấy GridItem
            while (parent && !gridItem) {
                if (
                    parent.$parent &&
                    parent.$parent.$options &&
                    parent.$parent.$options.name === "GridItem"
                ) {
                    gridItem = parent.$parent;
                    break;
                }
                parent = parent.$parent;
            }

            return gridItem;
        },
        handleGroupDragging(data) {
            this.isGroupDragging = data.isDragging;
        },

        updateGroupPlaceholder(data) {
            // Cập nhật placeholder để hiển thị guide lines
            this.placeholder = {
                i: data.i,
                left: data.left,
                top: data.top,
                width: data.width,
                height: data.height,
                dirX: "",
                dirY: "",
                snapEdge: "",
                snapEdgeRight: "",
                snapColIndex: 0,
                snapColIndexRight: 0
            };
        },

        // Hàm hỗ trợ kiểm tra chồng lấp chiều dọc
        hasVerticalOverlap(top1, bottom1, top2, bottom2) {
            return top1 < bottom2 && bottom1 > top2;
        },

        // Hàm hỗ trợ kiểm tra chồng lấp chiều ngang
        hasHorizontalOverlap(left1, right1, left2, right2) {
            return left1 < right2 && right1 > left2;
        },

        overGrid(e) {
            if (this.isFullScreen) {
                return;
            }
            this.over = true;
            if (
                !this.dropTo &&
                this.dragCurrent &&
                this.dragCurrent.is != "column" &&
                this.dragCurrent.is != "section"
            ) {
                this.$store.commit("builder/setDropTo", this.$parent);
            }
        },
        outGrid() {
            if (!this.isFullScreen || !this.isDraggingGrid) {
                this.timmer = setTimeout(() => {
                    if (!this.dragCurrent || !this.$parent.$parent.over) {
                        this.over = false;
                        this.$store.commit("builder/setDropTo", null);
                    }
                }, 50);
            }
        },
        mousemove(e: MouseEvent): void {
            if (!this.dropTo) {
                this.overGrid(e);
            }
            const offsetParent = (e.target as HTMLElement).offsetParent || document.body;
            const offsetParentRect =
                offsetParent === document.body
                    ? { left: 0, top: 0 }
                    : offsetParent.getBoundingClientRect();

            // Lưu ý: Chỉ tính offset từ Parent mà không cộng scroll
            const x = e.clientX - offsetParentRect.left;
            const y = e.clientY - offsetParentRect.top;
            this.$parent.mouse = { x, y };
        },
        checkItemInContainer(item) {
            if (!item) return false;

            const containerWidth = this.$el?.offsetWidth || this.width;
            const containerHeight = this.gridHeight();

            // Chuyển đổi left từ % sang pixel
            const leftPx = (ensureNumericValue(item.left) / 100) * containerWidth;
            const widthPx = ensureNumericValue(item.width);
            const rightPx = leftPx + widthPx;

            // Top và height đã là pixel
            const topPx = ensureNumericValue(item.top);
            const heightPx = ensureNumericValue(item.height);
            const bottomPx = topPx + heightPx;

            // Kiểm tra biên
            const isWithinHorizontalBounds = leftPx >= 0 && rightPx <= containerWidth;
            const isWithinVerticalBounds = topPx >= 0 && bottomPx <= containerHeight;

            return isWithinHorizontalBounds && isWithinVerticalBounds;
        },

        updateAllLayouts() {
            console.log(`[GridLayout ${this.data?.id}] updateAllLayouts:`, {
                screen: this.screen,
                layoutCount: this.layout.length,
                containerWidth: this.containerWidth
            });

            // CHỈ cập nhật responsive layouts cho màn hình hiện tại
            const currentScreen = this.screen;
            this.layouts[currentScreen] = JSON.parse(JSON.stringify(this.layout));

            // CHỈ cập nhật layout cho màn hình hiện tại trong data object
            this.layout.forEach((item) => {
                const block = this.data.blocks.find((block) => block.id === item.i);
                if (block && block.layouts) {
                    // Đảm bảo có object cho screen hiện tại
                    if (!block.layouts[currentScreen]) {
                        block.layouts[currentScreen] = {};
                    }

                    // Cập nhật tất cả thuộc tính (không so sánh với desktop)
                    block.layouts[currentScreen].width = item.width;
                    block.layouts[currentScreen].height = item.height;
                    block.layouts[currentScreen].left = item.left;
                    block.layouts[currentScreen].top = item.top;
                    if (item.rotation !== undefined) {
                        block.layouts[currentScreen].rotation = item.rotation;
                    }
                }
            });
        },
        startSelectionResize(e: MouseEvent, type: string): void {
            if (this.selectionHandler) {
                this.selectionHandler.startSelectionResize(e, type);
            }
        },
        // Phương thức mới để cập nhật selection area từ các items đã resize
        updateSelectionAreaFromItems() {
            if (!this.hasSelection || this.selectedItems.length < 2) return;

            let minX = Infinity,
                minY = Infinity;
            let maxX = -Infinity,
                maxY = -Infinity;

            const containerWidth = this.$refs.item?.offsetWidth || this.width || 1200;

            this.selectedItems.forEach((item) => {
                const leftPercent = ensureNumericValue(item.left);
                const topPixels = ensureNumericValue(item.top);

                // Xác định kiểu của width và chuyển đổi sang phần trăm nếu cần
                let widthValue = item.width;
                let widthPercent;

                if (typeof widthValue === "string" && widthValue.includes("%")) {
                    // Nếu width đã là %, lấy giá trị số trực tiếp
                    widthPercent = parseFloat(widthValue);
                } else {
                    // Nếu width là px, chuyển đổi sang %
                    const widthPixels = ensureNumericValue(widthValue);
                    widthPercent = (widthPixels / containerWidth) * 100;
                }

                const heightPixels = ensureNumericValue(item.height);

                minX = Math.min(minX, leftPercent);
                minY = Math.min(minY, topPixels);
                maxX = Math.max(maxX, leftPercent + widthPercent);
                maxY = Math.max(maxY, topPixels + heightPixels);
            });

            this.selectionArea = { minX, minY, maxX, maxY };
        },

        // Resize các items được chọn
        resizeSelectedItems() {
            if (!this.hasSelection || this.selectedItems.length < 2) return;

            // Tính toán tỷ lệ thay đổi
            // Sử dụng kích thước thực (px) thay vì đơn vị grid để tính toán chính xác hơn
            const oldWidth = this.selectionResizeInitial.maxX - this.selectionResizeInitial.minX;
            const oldHeight = this.selectionResizeInitial.maxY - this.selectionResizeInitial.minY;
            const newWidth = this.selectionArea.maxX - this.selectionArea.minX;
            const newHeight = this.selectionArea.maxY - this.selectionArea.minY;

            // Tỷ lệ thay đổi
            const widthRatio = newWidth / oldWidth;
            const heightRatio = newHeight / oldHeight;

            // Tạo bản sao của layout hiện tại
            const newLayout = cloneLayout(this.layout);

            // Tìm vị trí ban đầu của các item khi bắt đầu resize
            // Điều này rất quan trọng để tránh tích lũy lỗi
            const initialItems = {};
            this.selectedItems.forEach((item) => {
                // Tìm vị trí ban đầu từ selectionResizeInitial
                // Lưu ý: cần lưu trữ vị trí ban đầu khi bắt đầu resize
                initialItems[item.i] = {
                    x: item.left,
                    y: item.top,
                    w: item.width,
                    h: item.height
                };
            });

            // Cập nhật từng item được chọn từ vị trí BAN ĐẦU
            this.selectedItems.forEach((item) => {
                // Tìm item trong layout
                const layoutItem = newLayout.find((li) => li.i === item.i);
                if (!layoutItem) return;

                // Lấy vị trí ban đầu
                const initialPos = initialItems[item.i];
                if (!initialPos) return;

                // Tính vị trí tương đối trong vùng chọn ban đầu
                const relX = initialPos.x - this.selectionResizeInitial.minX;
                const relY = initialPos.y - this.selectionResizeInitial.minY;

                // Tính tỷ lệ vị trí (quan trọng: giữ vị trí tương đối)
                const relXRatio = oldWidth === 0 ? 0 : relX / oldWidth;
                const relYRatio = oldHeight === 0 ? 0 : relY / oldHeight;

                // Tính vị trí mới dựa trên tỷ lệ vị trí
                let newX, newY, newW, newH;

                // Xử lý các trường hợp resize khác nhau
                switch (this.selectionResizeType) {
                    case "n":
                    case "s": // Chỉ thay đổi height
                        newX = initialPos.x;
                        newY = Math.round(this.selectionArea.minY + relY * heightRatio);

                        // Kích thước W giữ nguyên, H thay đổi theo tỷ lệ
                        newW = initialPos.w;
                        newH = Math.max(1, Math.round(initialPos.h * heightRatio));
                        break;

                    case "e":
                    case "w": // Chỉ thay đổi width
                        newX = Math.round(this.selectionArea.minX + relX * widthRatio);
                        newY = initialPos.y;

                        // Kích thước W thay đổi theo tỷ lệ, H giữ nguyên
                        newW = Math.max(1, Math.round(initialPos.w * widthRatio));
                        newH = initialPos.h;
                        break;

                    case "ne":
                    case "nw":
                    case "se":
                    case "sw": // Thay đổi cả width và height
                        newX = Math.round(this.selectionArea.minX + relX * widthRatio);
                        newY = Math.round(this.selectionArea.minY + relY * heightRatio);

                        // Kích thước W và H thay đổi theo tỷ lệ
                        newW = Math.max(1, Math.round(initialPos.w * widthRatio));
                        newH = Math.max(1, Math.round(initialPos.h * heightRatio));
                        break;

                    default:
                        newX = initialPos.x;
                        newY = initialPos.y;
                        newW = initialPos.w;
                        newH = initialPos.h;
                }

                // Giới hạn trong phạm vi grid
                newX = Math.min(Math.max(0, newX), this.colNum - newW);
                newY = Math.max(0, newY);
                newW = Math.min(newW, this.colNum - newX);

                // Cập nhật giá trị mới cho layout item
                layoutItem.left = newX;
                layoutItem.top = newY;
                layoutItem.width = newW;
                layoutItem.height = newH;
            });

            // Sử dụng compact từ helper function, không phải phương thức
            const compactedLayout = compact(newLayout, this.verticalCompact);

            // Cập nhật selectedItems từ layout mới
            this.selectedItems = this.selectedItems.map((item) => {
                const updatedItem = compactedLayout.find((layoutItem) => layoutItem.i === item.i);
                return updatedItem || item;
            });
        },

        // Thêm phương thức này
        isInSelectionBox(clickX, clickY) {
            if (!this.hasSelection) return false;

            // Lấy phần tử selection-box
            const selectionBoxElement = this.$el.querySelector(".ecom-selection-box");
            if (!selectionBoxElement) return false;

            // Lấy vị trí và kích thước của selection box
            const boxRect = selectionBoxElement.getBoundingClientRect();
            const containerRect = this.$el.getBoundingClientRect();

            // Điều chỉnh tọa độ tương đối
            const relativeRect = {
                left: boxRect.left - containerRect.left,
                top: boxRect.top - containerRect.top,
                right: boxRect.right - containerRect.left,
                bottom: boxRect.bottom - containerRect.top,
                width: boxRect.width,
                height: boxRect.height
            };

            // Kiểm tra nếu điểm nằm trong hình chữ nhật
            return (
                clickX >= relativeRect.left &&
                clickX <= relativeRect.right &&
                clickY >= relativeRect.top &&
                clickY <= relativeRect.bottom
            );
        },
        duplicate() {
            this.eventBus.emit("groupDuplicate");
            this.$store.commit("builder/setContextMenu", { current: null });
        },
        dropOut() {
            this.eventBus.emit("groupDelete");
            this.$store.commit("builder/setContextMenu", { current: null });
        },
        rightClickShowMenu(e) {
            if (this.is == "block" && !this.control) {
                return true;
            }

            if (!this.isFullScreen && this.contextMenu && !this.contextMenu.current) {
                let rect = window.EComposerBuilder.getBoundingClientRect(),
                    y = e.clientY + rect.top,
                    top;
                if (y + 320 > rect.height) {
                    top = y - (e.clientY + rect.top + 320 - rect.height);
                } else {
                    top = y;
                }
                this.$store.commit("builder/setContextMenu", {
                    current: this,
                    x: e.clientX + rect.left,
                    y: top,
                    time: new Date().getTime(),
                    stick: e.pageX < rect.width - 200 ? "left" : "right",
                    bottom: y + 320 > rect.height
                });
            }
            e.preventDefault();
        },

        updateSelectionBorders() {
            if (this.selectionHandler) {
                this.selectionHandler.updateSelectionBorders();
                this.selectionHandler.syncStateToInstance();
            }
        },

        handleKeyDown(e) {
            if (e.key === "Escape") {
                // Xóa lựa chọn
                this.isSelecting = false;
                this.hasSelection = false;
                this.$store.commit("builder/clearActiveElements");
                this.selectionBorders.h = [];
                this.selectionBorders.v = [];
                this.selectedItems = [];
            }
        },
        between: function (a, b, tolerance = 3) {
            const numA = ensureNumericValue(a);
            const numB = ensureNumericValue(b);

            return numA >= numB - tolerance && numA <= numB + tolerance;
        },
        initLayoutFromBlocks() {
            // Lấy screen hiện tại
            const currentScreen = this.currentScreen;

            // Chuyển đổi blocks thành layout items
            this.layout = this.data.blocks.map((block) => {
                // Lấy thông tin layout cho screen hiện tại
                const screenLayout = block.layouts[currentScreen] || {};

                // Xử lý các giá trị ban đầu
                let leftValue = 0;
                let topValue = 0;
                let widthValue = 100;
                let heightValue = 50;

                // Trích xuất giá trị số từ chuỗi có thể chứa đơn vị
                if (screenLayout.left !== undefined) {
                    leftValue =
                        typeof screenLayout.left === "string"
                            ? parseFloat(screenLayout.left)
                            : screenLayout.left;
                }

                if (screenLayout.top !== undefined) {
                    topValue =
                        typeof screenLayout.top === "string"
                            ? parseFloat(screenLayout.top)
                            : screenLayout.top;
                }

                if (screenLayout.width !== undefined) {
                    widthValue =
                        typeof screenLayout.width === "string"
                            ? parseFloat(screenLayout.width)
                            : screenLayout.width;
                }

                if (screenLayout.height !== undefined) {
                    heightValue =
                        typeof screenLayout.height === "string"
                            ? parseFloat(screenLayout.height)
                            : screenLayout.height;
                }

                // Tạo layout item - lưu trữ các giá trị số không kèm đơn vị
                return {
                    i: block.id,
                    left: leftValue, // Lưu giá trị số
                    top: topValue, // Lưu giá trị số
                    width: widthValue, // Lưu giá trị số
                    height: heightValue, // Lưu giá trị số
                    rotation: screenLayout.rotation || 0,
                    options: block.layouts.options || {}
                };
            });

            // Cập nhật chiều cao sau khi khởi tạo layout
            this.updateHeight();
        },

        updateHeight(value: number = 0) {
            if (
                this.data?.settings?.["min-height"] ||
                (this.data?.settings?.["min-height__" + this.screen] && this.screen != "desktop")
            ) {
                setTimeout(() => {
                    if (this.$refs.item) {
                        this.$refs.item.style.height = "";
                    }
                }, 100);
                return;
            }
            // if (this.isResizingSelectionFlag) return;
            // Sử dụng requestAnimationFrame để đồng bộ với chu kỳ render
            if (this._heightUpdateRAF) {
                cancelAnimationFrame(this._heightUpdateRAF);
            }

            this._heightUpdateRAF = requestAnimationFrame(() => {
                const height = this.containerHeight(value);
                this.mergedStyle = { height };

                if (this.$refs.item) {
                    this.$refs.item.style.height = height;
                }

                this._heightUpdateRAF = null;
            });
        },
        onWindowResize: function () {
            // Bỏ qua resize window event khi đang trong quá trình resize selection
            if (this.isResizingSelectionFlag) {
                return;
            }

            // Đảm bảo lấy width chính xác
            if (this.$refs && this.$refs.item && this.$refs.item.offsetWidth > 0) {
                const newWidth = this.$refs.item.offsetWidth;

                gridDebug("layout", "window:resize", {
                    sectionId: this.section_id,
                    oldWidth: this.width,
                    newWidth,
                    oldContainerWidth: this.containerWidth,
                    newContainerWidth: newWidth
                }, this as any);

                this.containerWidth = newWidth; // Cập nhật containerWidth

                // Chỉ cập nhật width nếu thực sự có thay đổi
                if (Math.abs(this.width - newWidth) > 1) {
                    this.width = newWidth;
                }
            }

            this.eventBus.emit("resizeEvent", {});
            this.updateScaleRatio();
        },
        containerHeight(value: number = 0) {
            // Nếu là fixed height, sử dụng min-height từ settings
            if (this.data?.settings?.["min-height"]) {
                return this.data.settings["min-height"];
            }
            if (value) {
                return value + "px";
            }
            // Tính chiều cao dựa trên item xa nhất
            let maxBottom = 0;
            this.layout.forEach((item) => {
                // Xử lý cả trường hợp giá trị là số và chuỗi
                let height =
                    typeof item.height === "string" ? parseFloat(item.height) : item.height;
                let top = typeof item.top === "string" ? parseFloat(item.top) : item.top;

                // Nếu parse trả về NaN, gán giá trị mặc định là 0
                if (isNaN(height)) height = 0;
                if (isNaN(top)) top = 0;

                // Tìm bottom xa nhất (top + height)
                const bottom = top + height;
                maxBottom = Math.max(maxBottom, bottom);
            });

            // Thêm padding dưới
            return maxBottom + "px";
        },
        dragEvent(eventName, id, left, top, height, width, rotation) {
            // Tìm item trong layout
            let l = this.layout.find((item) => item.i === id);
            if (!l) {
                l = { left: 0, top: 0, height: 0, width: 0, i: id };
            }
            // Đảm bảo left và top là số không phải chuỗi
            const leftValue = typeof left === "string" ? parseFloat(left) : left;
            const topValue = typeof top === "string" ? parseFloat(top) : top;
            const widthValue = isPercentWidth(width)
                ? widthPxCalculate(width, this.containerWidth)
                : ensureNumericValue(width);
            const heightValue = typeof height === "string" ? parseFloat(height) : height;
            const prevLeftValue = typeof l.left === "string" ? parseFloat(l.left) : l.left;
            const prevTopValue = typeof l.top === "string" ? parseFloat(l.top) : l.top;

            gridDebug("layout", `drag:${eventName}`, {
                sectionId: this.section_id,
                itemId: id,
                leftValue,
                topValue,
                widthValue,
                heightValue,
                rotation,
                previousLeft: prevLeftValue,
                previousTop: prevTopValue,
                currentPlaceholder: this.placeholder
            }, this as any);

            if (eventName === "dragstart" || eventName === "dragmove") {
                // Cập nhật placeholder - sử dụng thuộc tính đồng nhất với GridItem
                this.placeholder = {
                    ...this.placeholder,
                    i: id,
                    left: leftValue, // Giữ % cho left
                    top: topValue, // Giữ px cho top
                    width: widthValue, // Giữ px cho width
                    height: heightValue, // Giữ px cho height
                    rotation: rotation
                };

                // Xác định hướng kéo
                this.placeholder.dirX =
                    leftValue > prevLeftValue
                        ? "right"
                        : leftValue < prevLeftValue
                        ? "left"
                        : this.placeholder.dirX;
                this.placeholder.dirY =
                    topValue > prevTopValue
                        ? "down"
                        : topValue < prevTopValue
                        ? "up"
                        : this.placeholder.dirY;

                // ĐẶT BIẾN isDragging và isDraggingGrid ngay lập tức
                this.isDraggingGrid = true;
                let maxY = 0;
                if (this.layout.length > 0) {
                    const layouts = this.layout.map((item) => {
                        if (this.placeholder.i === item.i) {
                            return {
                                ...item,
                                top: this.placeholder.top,
                                height: this.placeholder.height
                            };
                        }
                        return item;
                    });

                    maxY = Math.max(
                        ...layouts.map((item) => {
                            // Xử lý trường hợp height và top có thể là NaN
                            let itemTop =
                                typeof item.top === "string" ? parseFloat(item.top) : item.top;
                            let itemHeight =
                                typeof item.height === "string"
                                    ? parseFloat(item.height)
                                    : item.height;

                            // Nếu parse trả về NaN, gán giá trị mặc định là 0
                            if (isNaN(itemTop)) itemTop = 0;
                            if (isNaN(itemHeight)) itemHeight = 0;

                            return itemTop + itemHeight;
                        })
                    );
                }

                if (
                    maxY <= this.placeholder.top + this.placeholder.height &&
                    !this.data?.settings?.["min-height"]
                ) {
                    this.updateHeight(maxY);
                }
            }

            // Emit sự kiện khi kéo xong
            if (eventName === "dragend") {
                // Đặt lại các biến trạng thái
                this.isDraggingGrid = false;
                if (this.guidelineUtils) {
                    this.guidelineUtils.clearAllGuides();
                }
            }
        },
        resizeEvent(eventName, id, left, top, height, width, edges, rotation) {
            let l = this.layout.find((item) => item.i === id);
            if (!l) {
                l = { height: 0, width: 0, left: 0, top: 0, i: id };
            }

            // Đảm bảo các giá trị là số không có đơn vị
            const leftValue = typeof left === "string" ? parseFloat(left) : left;
            const topValue = typeof top === "string" ? parseFloat(top) : top;
            const widthValue = isPercentWidth(width)
                ? widthPxCalculate(width, this.containerWidth)
                : ensureNumericValue(width);
            const heightValue = typeof height === "string" ? parseFloat(height) : height;
            gridDebug("layout", `resize:${eventName}`, {
                sectionId: this.section_id,
                itemId: id,
                leftValue,
                topValue,
                widthValue,
                heightValue,
                edges,
                rotation,
                currentPlaceholder: this.placeholder
            }, this as any);
            if (eventName === "resizestart") {
                this.isResizing = true;
            }
            if (eventName === "resizestart" || eventName === "resizemove") {
                // Lưu kích thước thực tế để hiển thị
                this.itemWidthPx = widthValue;
                this.itemHeightPx = heightValue;

                // Lấy vị trí hiển thị kích thước
                const gridItemInstance = this.instanceStore.get(id);
                if (gridItemInstance && gridItemInstance.$el) {
                    // Cập nhật scale ratio trước khi sử dụng
                    this.updateScaleRatio();

                    const rect =
                        gridItemInstance.$el instanceof HTMLElement
                            ? gridItemInstance.$el
                            : gridItemInstance.$el?.parentNode;

                    const gridItem = rect.closest(".ecom-grid-item");
                    const gridItemRect = gridItem.getBoundingClientRect();

                    // Điều chỉnh tỷ lệ cho vị trí và sau đó áp dụng offset
                    const builder = this.idoc().querySelector('#ecom-builder');
                    const builderRect = builder.getBoundingClientRect();
                    let adjustTop = 0, adjustLeft = 0;
                    if(this.params.page === 'popup') {
                        adjustTop = builderRect.top;
                        adjustLeft = builderRect.left - 10;
                    }
                    this.resizingSizePosition = {
                        top: (gridItemRect.bottom - adjustTop) / this.scaleRatio + 5,
                        left: (gridItemRect.left - adjustLeft) / this.scaleRatio + 10
                    };
                }

                if (eventName === "resizestart") {
                    this.isResizing = true;
                }

                // Cập nhật placeholder với các thuộc tính
                this.placeholder = {
                    ...this.placeholder,
                    i: id,
                    left: leftValue,
                    top: topValue,
                    width: widthValue,
                    height: heightValue,
                    rotation: rotation
                };

                this.placeholder.dirX = edges?.right
                    ? "right"
                    : edges?.left
                    ? "left"
                    : this.placeholder.dirX;
                this.placeholder.dirY = edges?.bottom
                    ? "down"
                    : edges?.top
                    ? "up"
                    : this.placeholder.dirY;
            }

            // Emit sự kiện cập nhật chiều cao container
            this.updateHeight();
            if (eventName === "resizeend") {
                this.isResizing = false;
                this.$nextTick(() => {
                    if (this.guidelineUtils) {
                        this.guidelineUtils.clearAllGuides();
                    }
                });
            }
        },

        // clear all responsive layouts
        initResponsiveFeatures() {
            // clear layouts
            this.layouts = Object.assign({}, this.responsiveLayouts);
        },

        learPlaceholderGuides() {
            if (this.guidelineUtils) {
                this.guidelineUtils.clearAllGuides();
            }
        },

        snapToColLeft(leftPercent: number, widthPercent?: number): number {
            return this.guidelineUtils?.snapToColLeft(leftPercent, widthPercent) || leftPercent;
        },

        snapToColRight(rightPercent: number, widthPercent?: number): number {
            return this.guidelineUtils?.snapToColRight(rightPercent, widthPercent) || rightPercent;
        },

        applySnapToItem(itemId: string, position: any): any {
            return this.guidelineUtils?.applySnapToItem(itemId, position) || position;
        },

        isLeftEdgeOfColumn(left: number): boolean {
            return (
                this.guidelineUtils?.updateLeftColumnSnap?.({
                    ...this.placeholder,
                    left
                } as any) || false
            );
        },

        isRightEdgeOfColumn(placeholder: any): boolean {
            return this.guidelineUtils?.updateRightColumnSnap?.(placeholder) || false;
        }
    }
};
</script>
