        <div class="ecom-product-single__add-to-cart-wrapper" :class="{'ecom-ingrid-full-height': data.inGrid}">
            <div class="ecom-product-single__add-to-cart-container" :class="{'ecom-ingrid-full-height': data.inGrid}">
                <div v-if="data.settings?.payment_terms" class="ecom-product-single__add-to-cart-payment-terms" v-html="liquid('payment_terms')" />
                <div class="ecom-product-single__add-to-cart-buttons" :class="{'ecom-ingrid-full-height': data.inGrid}">
                    <div class="ecom-product-single__add-to-cart-buttons-wrapper" :class="{'ecom-ingrid-full-height': data.inGrid}">
                        <button type="submit" class="ecom-product-single__add-to-cart--submit ecom-flex"
                            :class="animatedClass"
                            :data-text-add-cart="lang(data.settings?.add_to_cart, 'add_to_cart')"
                            :data-text-pre-order="lang(data.settings?.pre_order, 'pre_order')"
                            :data-text-unavailable="lang(data.settings?.product_unavailable, 'product_unavailable')"
                            :data-text-outstock="lang(data.settings?.product_outstock, 'out_stock')"
                            :data-text-added-cart="lang(data.settings?.added_cart_text, 'added_cart_text')"
                            :data-message-added-cart="lang(data.settings?.added_cart_message, 'added_cart_message')"
                            v-bind="attrLink"
                            :data-action="data?.settings?.action ?? 'popup'"
                            :data-variant-id="liquid('variant_id')"
                            name="add"
                        >
                            <span
                                class="ecom-add-to-cart-text"
                                v-html="lang(data.settings.add_to_cart, 'add_to_cart')"
                            />
                            <span class="ecom-add-to-cart__price" v-if="data.settings?.show_dynamic_price"><span class="ecom-add-to-cart__money" v-html="liquid('price')"></span></span>

                            <span
                                class="ecom__element--button-icon"
                                v-html="data.settings?.icon"
                            />
                        </button>
                    </div>
                    <div v-if="exporting !== true" class="ecom-product-single__add-to-cart--json"
                        v-html="liquid('product_json')"
                    />
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'productAddToCart',
    mixins: [Liquid, Javascript, Element],
    presets:true,
    props: {
        data: {
            type: Object,
            default() {
                return {
                    
                };
            }
        }
    },
    data(){
        return {
            jsreactives: [
                'add_to_cart', 'product_unavailable','product_outstock','animation', 'animation_loop_time', 'show_total_price'
            ]
        }
    },
    computed: {
        element_id() {
            return this.data?.id || '';
        },
        javascript() {
            return function () {
                const isLive = this.isLive;
                if(!this.$el)
                {
                    return false;
                }
                const $el = this.$el;
                const $wrapper = $el.closest('.ecom-product-form--single');
                if (!$wrapper) {
                    return false;
                }
                if ($wrapper) {
                    if(this.settings.show_total_price) {
                        const priceWrapper = $el.querySelector('.ecom-product-single__price--sale');
                        let quantity = $wrapper.querySelector('#quantity');
                        if(priceWrapper && quantity) {
                            function updatePrice(el){
                                priceWrapper.innerHTML = window.EComposer.formatMoney(parseInt(priceWrapper.getAttribute('data-price')) * parseInt(el.value));
                            }
                            function setTotalPrice(el) {
                                setTimeout(()=>{
                                    updatePrice(el);
                                }, 100)
                                el.addEventListener('change', function() {
                                    updatePrice(el);
                                })
                            }
                            setTotalPrice(quantity);

                            $wrapper.addEventListener('ecomQuantityType', function () {
                                const qty = $wrapper.querySelector('#quantity');
                                if(quantity) {
                                    setTotalPrice(quantity);
                                }
                            })
                            $wrapper.addEventListener('ecomVariantChange', function(event) {
                                if(event.detail.variant) {
                                    const variant = event.detail.variant;
                                    const qty = quantity ? parseInt(quantity.value) : 1;
                                    priceWrapper.setAttribute('data-price', variant.price);
                                    if(qty > 1) {
                                        priceWrapper.innerHTML = window.EComposer.formatMoney(variant.price * parseInt(qty));
                                    }
                                }
                            })
                        }
                    }
                }
                const selector = $wrapper.querySelector('[name="id"]'),
                    $addCartButton = $el.querySelector('.ecom-product-single__add-to-cart--submit'),
                    form = $el.closest('form');
                const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                const isHighVariantProduct = isLive && (variantCount > 250 || form.querySelector('[data-high-variant-product]'));
                if(!form) return;
                function handleChange() {
                    let product = null;
                    const product_id = form.dataset.product_id;
                    let json = null;
                    if(product_id) {
                        json = form.querySelector('[data-selected-variant]') ||  form.querySelector('[id^=product-json-' + product_id + ']');
                    }
                    if(!json) {
                        json = $el.querySelector('[id^=addtocart-product-json]') || !isLive ? $el?.querySelector('[id^=addtocart-product-json]') : null;
                    }
                    if(!json) return;
                    try {
                        product = JSON.parse(json.innerHTML);
                    } catch (e) {
                        return;
                    }

                    let variant = null;
                    if(isHighVariantProduct || !product.variants) {
                        variant = product;
                    }
                    else {
                        variant = product.variants.find(v => v.available) || product.variants[0];
                    }
                    if(variant) {

                        const AtcText = $addCartButton.querySelector('.ecom-add-to-cart-text');
                        if(!AtcText) return;

                        if(variant.available == false) {
                            $addCartButton.setAttribute('disabled', 'disabled');
                            AtcText.innerText = $addCartButton.dataset.textOutstock;
                            $addCartButton.classList.remove('ecom-product-single__pre-order');
                        } else if(variant.inventory_quantity <= 0 && variant.inventory_policy == 'continue' && variant.inventory_management) {
                            AtcText.innerText = $addCartButton.dataset.textPreOrder;
                            $addCartButton.classList.add('ecom-product-single__pre-order');
                        }

                    }
                }
                if (!isLive) {
                    if ($wrapper) {
                        if (selector && !selector.classList.contains('ecom-product-single__picker-default-variant')) {
                            selector.dispatchEvent(new window.Event('ecomUpdate'));
                        }
                        else {
                            handleChange()
                        }
                    }
                } else {

                    if(!form.querySelector('select[name=id]')  || (form.querySelector('select[name=id]') && selector.classList.contains('ecom-product-single__picker-default-variant'))) {
                        handleChange();
                    }
                    if(!selector && $addCartButton && $addCartButton.dataset.variantId)
                    {
                        const dom = document.createElement('input');
                        dom.type ='hidden';
                        dom.value = $addCartButton.dataset.variantId;
                        $el.appendChild(dom);
                    }

                }

                const handleAnimation = function(_this) {
                  if (!$el) return;
                  const $btn_wrapper = $el.querySelector('.ecom-product-single__add-to-cart--submit');
                  if (!$btn_wrapper) return;

                  let intervalTime = parseInt(_this.settings.animation_loop_time) * 1000 || 6000,
                      animTime = 1000;

                  setInterval(function() {
                      $btn_wrapper.classList.add('animated');
                      setTimeout(function(){
                        $btn_wrapper.classList.remove('animated');
                      }, animTime);
                  }, intervalTime);
                }

                if (this.settings.animation) {
                  handleAnimation(this);
                }
            };
        },

        liquids() {
            let tag = 'script';
            const liquids = {
                price:{
                    code:`
                    {%- liquid
                        if product.has_only_default_variant
                            assign target = product
                        else
                            assign target = product.selected_or_first_available_variant
                        endif
                    -%}
                        <span class="separator"> - </span>
                        <div class="ecom-product-single__price--sale {% if target.compare_at_price == nil or target.compare_at_price <=  target.price %} ecom-product-single__price-normal {% endif %}" data-price="{{target.price}}">
                            {%- if settings.currency_code_enabled -%}
                                {{target.price | money_with_currency}}
                            {%- else -%}
                                {{target.price| money }}
                            {%- endif -%}
                        </div>
                    `
                },
                product_json: {
                    code: `

                    <${tag} type="application/json" id="addtocart-product-json-{{product.id}}">
                    {%- ${this.page_type === 'block' ? 'render': 'render'} "ecom_product_json", product: product  -%}
                    </${tag}>
                    `,
                    preview: `<${tag} id="product-json-preview">{}</${tag}>`
                },
                variant_id: {
                    code: '{{product.first_available_variant.id}}',
                    preview: '0'
                },
                payment_terms: {
                    code: `
                        {% comment %}
                            this.data.settings.payment_terms
                        {% endcomment %}
                        {{ form | payment_terms }}

                    `,
                    preview: ``
                }
            };
            if (this.exporting === true) {
                liquids.product_json = {
                    code: `
                    <${tag} type="application/json" id="addtocart-product-json-{{product.id}}-${this.element_id}">
                    {%- render "ecom_product_json", product: product -%}
                    </${tag}>
                    `,
                    preview: ''
                };
            }
            return liquids;
        },
