                                        value: false
                                    }
                                }
                            },
                        },
                        {
                          type: "number",
                          label: this.$t('loop_time_span_class_lowercase_s_span'),
                          name: "animation_loop_time",
                          options: {
                              min: 2,
                              default: 6,
                              max: 10,
                              visible: function (data) {
                                  return data.animation == true;
                              }
                          }
                        },
                        {
                            type:'line'
                        },
                        {
                            type:'paragraph',
                            content: this.$t('integrated_with_omega_facebook_pixel_https_apps_shopify_com_facebook_multi_pixels_surface_detail_e_catc_surface_type_partner'),

                        }
                    ]
                }
            ];
        },
        css() {
            return `
                    .ecom-add-to-cart__price .ecom-product-single__price--sale{
