                    }
                    .ecom-ingrid-full-height.ecom-product-single__add-to-cart--submit {
                        width: 100%;
                        height: 100%;
                    }
                `;
        },

        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },

        default() {
            return {
                "settings": {
                    "add_to_cart": "Add to cart",
                    "product_unavailable": "Unavailable",
                    "product_outstock": "Out stock",
                    "show_dynamic_checkout": true,
                    "added_cart_text": "Added to cart",
                    "added_cart_message": "Added to cart",
                    "action": "popup",
                    "payment_terms": false,
                    "icon": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 512\" fill=\"currentColor\"><path d=\"M423.3 440.7c0 25.3-20.3 45.6-45.6 45.6s-45.8-20.3-45.8-45.6 20.6-45.8 45.8-45.8c25.4 0 45.6 20.5 45.6 45.8zm-253.9-45.8c-25.3 0-45.6 20.6-45.6 45.8s20.3 45.6 45.6 45.6 45.8-20.3 45.8-45.6-20.5-45.8-45.8-45.8zm291.7-270C158.9 124.9 81.9 112.1 0 25.7c34.4 51.7 53.3 148.9 373.1 144.2 333.3-5 130 86.1 70.8 188.9 186.7-166.7 319.4-233.9 17.2-233.9z\"></path></svg>",
                    "icon_position": -1,
                    "spacing": "10px",
                    "animation": true,
                    "animation_loop_time": 3
                },
                "style": {
                    "dynamic_price": {
                        "textTypography": {
                        "font-size": "14px",
                        "font-weight": "400"
                    },
                    "textColor": "#ffffff",
                    "separator_spacing": {
                        "margin": {
                            "right": "10px"
                        }
                        }
                    },
                    "add_to_cart_button": {
                        "tab": "normal",
                        "spacing": {
                            "padding": {
                                "top": "12.5px",
                                "left": "50px",
                                "bottom": "12.5px",
                                "right": "50px"
                            }
                        },
                        "buttonColorhovermode": "#fff",
                        "buttonBackgroundhovermode": {
