            if(this.data.inGrid) {
                className += ' ecom-ingrid-full-height';
            }
            return className;
        },
    },
    methods: {
        quickToolBar() {
            return ['buttonColor', 'buttonBackground', 'buttonTypography'];
        },

        style() {
            const inGrid = this.data.inGrid || false;
            const params = [
                {
                    group_alias: `button${inGrid ? ':grid' : ''}`,
                    options:{
                        group_title: this.$t('add_to_cart'),
                        group_name: 'add_to_cart_button',
                        selector: ' .ecom-product-single__add-to-cart--submit',
                    },
                    modify:{
