                                                'rubber-band': this.$t('rubber_band'),
                                                'shake': this.$t('shake'),
                                                'head-shake': this.$t('head_shake'),
                                                'heart-beat': this.$t('heart_beat'),
                                                'swing': this.$t('swing'),
                                                'tada': this.$t('tada'),
                                                'wobble': this.$t('wobble'),
                                                'jello': this.$t('jello'),
                                                'light-speed ': this.$t('light_speed'),
                                                'light-speed-in': this.$t('light_speed_in'),
                                                'specials': this.$t('specials'),
                                                'roll-in': this.$t('roll_in'),
                                                'shake-y': this.$t('shake_y'),
                                                'back-in-down': this.$t('back_in_down'),
                                                'back-in-left': this.$t('back_in_left'),
                                                'back-in-right': this.$t('back_in_right'),
                                                'back-in-up': this.$t('back_in_up'),
                                                'flip': this.$t('flip'),
                                                'flip-x': this.$t('flip_x'),
                                                'flip-y': this.$t('flip_y'),
                                                'light-speed-in-right': this.$t('light_speed_in_right'),
                                                'light-speed-in-left': this.$t('light_speed_in_left'),
                                                'roll': this.$t('roll'),
                                            },
                                            size: "small",
                                        },
                                        css: {
                                            selector: ".animated",
                                            properties: {
                                                'entrance-animation': ""
                                            }
                                        }
                                    },
                                ]
                            }
                        ]
                    }
                },
                {
                    group_alias: `button${inGrid ? ':grid' : ''}`,
                    options:{
                        group_title: this.$t('pre_order_button'),
                        group_name: 'pre_order_button',
                        selector: ' .ecom-product-single__add-to-cart--submit.ecom-product-single__pre-order',
                    }
                },
                {
                    group_alias: 'text',
                    options: {
                        group_title: this.$t('dynamic_price'),
                        group_name: 'dynamic_price',
                        selector: ' .ecom-add-to-cart__price .ecom-product-single__price--sale, .ecom-add-to-cart__price .separator'
                    },
                    modify: {
                        remove: [
                        {index: 0, length: 1},
                        ],
                        params:[
                        {
                            position:5,
                            fields:{
                                alias: 'spacing',
                                options: {
                                    name: 'separator_spacing',
                                    label: this.$t('separator_spacing'),
                                    css:{
                                        selector: 'root .ecom-add-to-cart__price .separator'
                                        }

                                }
                            }

                        },
                        {
                            position:6,
                            fields:{
                                alias: 'spacing',
                                options: {
                                    name: 'price_spacing',
                                    label: this.$t('price_spacing'),
                                    css:{
                                        selector: 'root .ecom-add-to-cart__price .ecom-product-single__price--sale'
                                        }
                                }
                            }

                        },
                    ]
                    },


                },
                {
                    group_alias: `button${inGrid ? ':grid' : ''}`,
                    options:{
                        group_title: this.$t('sold_out_or_unavailable'),
                        group_name: 'sold_out_or_unavailable_button',
                        selector: ' .ecom-product-single__add-to-cart--submit:disabled',
                    }
                }
            ];
            if(this.data.settings?.show_dynamic_price) {
                params.push({
                    group_alias: 'text:hover',
                    options: {
                        group_title: this.$t('dynamic_price'),
                        group_name: 'dynamic_price',
                        selector: ' .ecom-add-to-cart__price'
                    },
                    modify: {
                        remove: [
                        {index: 0, length: 1},
                        {index: 4, length: 2},
                        {index: 6, length: 3}
                        ],
                        params:[
                        {
                            position: 3,
                            fields: {
                                name: 'textColor',
                                label: this.$t('text_color'),
                                type: 'color',
                                options: {
                                    oneline: true,
                                    global: {
                                        type: 'colors'
                                    },
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data['tab'] === 'normal';
                                        }
                                    }
                                },
                                css: {
                                    properties: {
                                        'color': ''
                                    }
                                }
                            }
                        },
                        {
                            position: 4,
                            fields: {
                                name: 'textTextShadow',
                                liteMode: true,
                                label: this.$t('text_shadow'),
                                type: 'popup',
                                options: {
                                    oneline: true,
                                    type: 'text-shadow',
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data['tab'] === 'normal';
                                        }
                                    }
                                },
                                css: {
                                }
                            }
                        },
                        {
                            position:7,
                            fields: {
                                name: 'textColorHover',
                                label: this.$t('text_color'),
                                type: 'color',
                                options: {
                                    oneline: true,
                                    global: {
                                        type: 'colors'
                                    },
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data['tab'] === 'hover';
                                        }
                                    }
                                },
                                css: {
                                    selector: 'root .ecom-product-single__add-to-cart--submit:hover .ecom-add-to-cart__price',
                                    properties: {
                                        'color': ''
                                    }
                                }
                            }
                        },
                        {
                            position:8,
                            fields:{
                                name: 'textTextShadowHover',
                                liteMode: true,
                                label: this.$t('text_shadow'),
                                type: 'popup',
                                options: {
                                    oneline: true,
                                    type: 'text-shadow',
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data['tab'] === 'hover';
                                        }
                                    }
                                },
                                css: {
                                    selector: 'root .ecom-product-single__add-to-cart--submit:hover .ecom-add-to-cart__price',
                                }
                            }
                        },
                        {
                            position:15,
                            fields:{
                                alias: 'spacing',
                                options: {
                                    name: 'separator_spacing',
                                    label: this.$t('hyphen_spacing'),
                                    css:{
                                        selector: ' .separator'
                                    }

                                }
                            }

                        },
                        {
                            position:16,
                            fields:{
                                alias: 'spacing',
                                options: {
                                    name: 'price_spacing',
                                    label: this.$t('price_spacing'),
                                    css:{
                                        selector: ' .ecom-product-single__price--sale'
                                        }
                                }
                            }

                        }
                    ]
                    }
                })
            }
            if (this.data.settings?.icon) {
                params.push({
                    group_alias:'icon',
                    options:{
                        group_name: 'icon',
                        group_title: this.$t('icon'),
                        selector: ' .ecom__element--button-icon',
                    },
                    modify:{
                        params:[
                            {
                                position:1,
                                fields:[
                                    {
                                        type: 'color',
                                        name: 'icon_color_hover',
                                        label: this.$t('hover_color'),
                                        css: {
                                            properties: {
                                                '--icon-color-hover':''
                                            },
                                        }
                                    }
                                ]
                            },
                            {
                                position:15,
                                fields:[
                                    {
                                        type: 'line'
                                    },
                                    {
                                        alias:'spacing'
                                    }
                                ]
                            }
                        ]
                    }
                });
            }
            return params;
        }
    }
};
</script>
