import { $t } from '@/plugins/i18n';
import type { RootStateType } from "@/store/interfaces";

// Load isNavigatorPinned from localStorage, default to false
const getStoredNavigatorPinned = (): boolean => {
    try {
        const stored = localStorage.getItem('ecom_isNavigatorPinned');
        return stored === 'true';
    } catch (e) {
        return false;
    }
};

// Load isSeoAuditPinned from localStorage, default to true
const getStoredSeoAuditPinned = (): boolean => {
    try {
        const stored = localStorage.getItem('ecom_isSeoAuditPinned');
        return stored === null ? true : stored === 'true';
    } catch (e) {
        return true;
    }
};

