<!-- ref="toolbar" bỏ class overflow-y-auto bị ẩn khi mở chọn màu -->
<template>
    <!--
        Panel nổi (color picker / text format) được Teleport ra <body>.
        Nếu để inline, chúng bị kẹt trong stacking context của
        `.ecom-fields__group-body` (relative z-8) và `ul.toolbar` (transform),
        nên luôn bị title group (sticky z-9) đè lên.
    -->
    <Teleport to="body" v-if="isPanelOpen">
        <div
            class="fixed inset-0 z-[61] bg-transparent outside-close-cursor"
            @click="closePanel"
        ></div>
        <div ref="panel" class="fixed z-[62]" :style="panelStyle">
            <div
                v-if="showing === 'foreColor' || showing === 'backColor'"
                class="w-full max-w-[290px] 3xl:w-60 shadow-popup bg-white pt-4 pb-4 rounded toolbar__color-picker"
            >
                <ColorPicker
                    :key="showing"
                    :value="colors[showing]"
                    @update:data="changeColor($event, showing)"
                />
                <div class="pl-4 pr-4 flex justify-end">
                    <ecom-button
                        @click="clickToolbar($event, showing)"
                        :outline="true"
                        class="rounded group text-sm h-8"
                        >{{ $t("select") }}</ecom-button
                    >
                </div>
            </div>
            <div
                v-else
                class="w-full max-w-[290px] 3xl:w-60 shadow-popup bg-white px-1 py-2 rounded toolbar__text-format"
            >
                <button
                    v-for="(type, index) in textFormats"
                    :key="index"
                    @click="clickToolbar($event, type.action)"
                    class="block w-full py-1 px-4 text-left hover:bg-gray-100"
                    :class="[type.cssClasses, classToolbar(type.action)]"
                >
                    {{ type.name }}
                </button>
            </div>
        </div>
    </Teleport>
    <ul
        v-if="toolbarFilterd.length"
        ref="toolbar"
        class="relative flex flex-row flex-wrap p-2 pb-0.5 content-between row-span-1 bg-[#F9FAFB] border border-[#E3E3E3] border-b-0 rounded-t-lg focus:outline-none focus:ring-2 ring-offset-1 focus:ring-primary-400 transform -translate-y-px transition z-10"
    >
        <li
            v-for="(toolbar, index) in toolbarFilterd"
            :key="toolbar?.name || index"
            class="mb-1 flex"
            :class="{ 'flex-break': toolbar?.action === 'break' }"
        >
            <template v-if="toolbar.action">
                <button
                    href="#"
                    type="button"
                    class="relative min-w-[31px] z-10 block p-1 transition border-0 rounded-sm cursor-pointer group focus:outline-none focus:ring-0"
                    :data-tooltip="
                        'openTextFormat' == toolbar.action ? textFormatTooltip() : toolbar.name
                    "
                    :class="[classToolbar(toolbar.action)]"
                    :style="styleButton(toolbar.action)"
                    @click="clickToolbar($event, toolbar.action)"
                >
                    <!-- <input
                        v-if="['foreColor', 'backColor'].includes(toolbar.action)"
                        type="color"
                        class="absolute top-0 left-0 z-10 w-full h-full opacity-0 cursor-pointer"
                        :class="{'pointer-events-none' : !toolbar.support}"
                        @input="changeColor($event,toolbar.action)"
                    > -->

                    <span
                        class="flex flex-nowrap items-center justify-center"
                        v-html="
                            'openTextFormat' == toolbar.action
                                ? textFormatIcon() + toolbar.icon
                                : toolbar.icon
                        "
                    />
                </button>

                <span
                    v-if="toolbar.separator"
                    class="block w-px h-6 mx-1 border-r border-gray-100"
                />
            </template>
        </li>
    </ul>
</template>

