        toolbarFilterd() {
            let toolbarTemp = this.toolbars;
            if (this.type == 0) {
                return [];
            } else if (this.type == 1) {
                toolbarTemp = toolbarTemp.filter(
                    (x) => x && ["insertImage", "insertVideo"].indexOf(x?.action) === -1
                );
            }
            if (this.field?.options?.excludeTools?.length) {
                toolbarTemp = toolbarTemp.filter(
                    (x) => x && this.field.options.excludeTools.indexOf(x.action) === -1
                );
            }
            return toolbarTemp;
        },
        textFormats() {
            return [
                {
                    action: "p",
                    name: this.$t("paragraph"),
                    cssClasses: "text-sm"
                },
                {
                    action: "h1",
                    name: this.$t("heading") + " 1",
                    cssClasses: "font-bold text-4xl"
                },
                {
                    action: "h2",
                    name: this.$t("heading") + " 2",
                    cssClasses: "font-bold text-3xl"
                },
                {
                    action: "h3",
                    name: this.$t("heading") + " 3",
                    cssClasses: "font-bold text-2xl"
                },
                {
                    action: "h4",
                    name: this.$t("heading") + " 4",
                    cssClasses: "font-bold text-xl"
                },
                {
                    action: "h5",
                    name: this.$t("heading") + " 5",
                    cssClasses: "font-bold text-lg"
                },
                {
                    action: "h6",
                    name: this.$t("heading") + " 6",
                    cssClasses: "font-bold text-base"
                }
            ];
        },
        CMDs() {
            return this.toolbarFilterd.map((x) => x.action);
        },
        isPanelOpen() {
            return ["foreColor", "backColor", "openTextFormat"].includes(this.showing);
        }
    },
    watch: {
        showing() {
            if (this.isPanelOpen) {
                // Ẩn panel ở frame đầu tiên để tránh nhảy từ góc (0, 0)
                this.panelStyle = { ...this.panelStyle, visibility: "hidden" };
                this.bindPanelListeners();
                this.$nextTick(() => {
                    this.positionPanel();
                    requestAnimationFrame(this.positionPanel);
                });
            } else {
                this.panelAnchor = null;
                this.unbindPanelListeners();
            }
        }
    },
    beforeUnmount() {
        this.unbindPanelListeners();
    },
    methods: {
        styleButton(cmd) {
            let val = this.state[cmd];
            switch (cmd) {
                case "foreColor":
                case "codeFormat":
                    return { "--ta-fill": val };
                case "backColor": {
                    let c = "";
                    if (!val) {
                        c = "rgb(0, 0, 0)";
                    } else {
                        c = val == "rgb(255, 255, 255)" ? "rgb(0, 0, 0)" : val;
                    }
                    return { "--ta-fill": c };
                }
                default:
                    return {};
            }
        },
        classToolbar(cmd) {
            let val = this.state[cmd];
            switch (cmd) {
                // case 'foreColor':
                // case 'backColor':
                //     return 'hover:bg-gray-200 rounded  ';
                default:
                    return val ? "text-primary bg-gray-100" : "text-icon hover:bg-gray-200";
            }
        },
        clickToolbar($event, action) {
            if (this.isFloatingPanelAction(action) && action !== this.showing) {
                this.panelAnchor = ($event?.currentTarget as HTMLElement) || null;
            }

            this.showing = action === this.showing ? null : action;
            this.$emit("select", action);
        },
        isFloatingPanelAction(action) {
            return ["foreColor", "backColor", "openTextFormat"].includes(action);
        },
        closePanel() {
            this.showing = "";
        },
        bindPanelListeners() {
            // capture = true để bắt cả scroll của các container bên trong sidebar
            window.addEventListener("scroll", this.positionPanel, true);
            window.addEventListener("resize", this.positionPanel);
        },
        unbindPanelListeners() {
            window.removeEventListener("scroll", this.positionPanel, true);
            window.removeEventListener("resize", this.positionPanel);
        },
        positionPanel() {
            const anchor = this.panelAnchor;
            const panel = this.$refs["panel"] as HTMLElement;
            const $toolbar = this.$refs["toolbar"] as HTMLElement;
            if (!anchor || !anchor.isConnected || !panel || !$toolbar) return;

            const anchorRect = anchor.getBoundingClientRect();
            const toolbarRect = $toolbar.getBoundingClientRect();
            const gap = 4;
            const margin = 8;
            const width = Math.round(toolbarRect.width);

            // Set width trước khi đo chiều cao: panel dùng `w-full` nên nếu chưa có
            // width thì offsetHeight sẽ sai (chữ bị xuống dòng).
            panel.style.width = `${width}px`;
            const height = panel.offsetHeight;

            let top = anchorRect.bottom + gap;
            const notEnoughBelow = top + height > window.innerHeight - margin;
            const enoughAbove = anchorRect.top - gap - height >= margin;
            if (notEnoughBelow && enoughAbove) {
                top = anchorRect.top - gap - height;
            }
            top = Math.max(margin, Math.min(top, window.innerHeight - height - margin));

            const maxLeft = window.innerWidth - Math.min(width, 290) - margin;
            const left = Math.max(margin, Math.min(toolbarRect.left, maxLeft));

            this.panelStyle = {
                top: `${Math.round(top)}px`,
                left: `${Math.round(left)}px`,
                width: `${width}px`,
                visibility: "visible"
            };
        },
        changeColor(val, action) {
            this.colors[action] = val;
            let itv = null;
            clearTimeout(itv);

            itv = setTimeout(() => {
                this.$emit("updateColor", { val, action });
            }, 100);
        },
        textFormatIcon() {
            let activeType = "";
            ["h1", "h2", "h3", "h4", "h5", "h6"].forEach((act) => {
                if (this.state[act]) {
                    activeType = act;
                }
