            let icon = "";
            switch (activeType) {
                case "h1":
                    icon = `<svg width="20" height="20" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M15.17 5.415a.747.747 0 0 1 .07.46.75.75 0 0 1 .01.125v7.502h1a.75.75 0 1 1 0 1.5l-4-.002a.75.75 0 1 1 0-1.5h1.5V6.964l-1.415.708a.75.75 0 0 1-.67-1.342l2.5-1.25a.75.75 0 0 1 1.006.336ZM4.5 6A.75.75 0 0 0 3 6v8.25a.75.75 0 0 0 1.5 0v-3.5h3.25v3.5a.75.75 0 0 0 1.5 0V6a.75.75 0 0 0-1.5 0v3.25H4.5V6Z"></path></svg>`;
                    break;
                case "h2":
                    icon = `<svg width="20" height="20" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M4.5 5.75a.75.75 0 0 0-1.5 0v8.5a.75.75 0 0 0 1.5 0V11h3.25v3.25a.75.75 0 0 0 1.5 0v-8.5a.75.75 0 0 0-1.5 0V9.5H4.5V5.75ZM12.25 5C11.56 5 11 5.56 11 6.25V7.5a.75.75 0 0 0 1.5 0v-1h2.232a.75.75 0 0 1 .598 1.203l-4.124 5.443a1 1 0 0 0 .797 1.604h4.247a.75.75 0 0 0 0-1.5h-3.24l3.515-4.641C17.648 7.127 16.591 5 14.732 5H12.25Z"></path></svg>`;
