        textFormatTooltip() {
            let activeType = "";
            ["h1", "h2", "h3", "h4", "h5", "h6"].forEach((act) => {
                if (this.state[act]) {
                    activeType = act;
                }
            });
            if (!activeType) {
                activeType = "p";
            }
            let toolTip = "";
            switch (activeType) {
                case "h1":
                    toolTip = this.$t("heading") + " 1";
                    break;
                case "h2":
                    toolTip = this.$t("heading") + " 2";
                    break;
                case "h3":
                    toolTip = this.$t("heading") + " 3";
                    break;
                case "h4":
                    toolTip = this.$t("heading") + " 4";
                    break;
                case "h5":
                    toolTip = this.$t("heading") + " 5";
                    break;
                case "h6":
                    toolTip = this.$t("heading") + " 6";
                    break;
                default:
                    toolTip = this.$t("paragraph");
                    break;
            }
            return toolTip;
        }
