<template>
    <div class="p-2">
        <div class="relative max-h-1/3 overflow-y-auto">
            <button
                v-for="v in values"
                type="button"
                :key="v.name"
                class="whitespace-nowrap text-left w-full rounded text-sm flex min-w-full px-2 py-2 mb-0.5 last:mb-0 transition text-gray-600   hover:bg-gray-100 hover:text-gray-900"
                :class="isActive(v) ? 'relative bg-surface-tertiary ' : ''"
                @click="choose(v.name)"
                :data-tooltip="previewTooltip(v.name)"
                :data-tooltip-location="previewTooltip(v.name) ? 'left' : undefined"
            >
                <span class="truncate text-xs  ">{{ v.title }}</span>
                <span
                    v-if="isActive(v)"
                    class="absolute -left-2 rounded-r top-0 h-full bg-primary"
                    style="width:3px"
                />
            </button>
        </div>
    </div>
</template>

<script>
    import {
        ensureAnimationPreviewKeyframes,
        previewTooltipHtml,
        ensureScrollingPresetPreviewKeyframes,
        scrollingPresetTooltipHtml
    } from '@/utils/animationPreview';

    export default {
        name: 'PopupDropdown',
        props: {
            // eslint-disable-next-line vue/require-default-prop
            data: {
                type: [Number, String, Boolean]
            },
            values: {
                type: Object,
                default() {
                    return {};
                }
            },
            /**
             * ANIM-03. Mặc định false: component này là dropdown popup dùng chung cho rất
             * nhiều field, chỉ 3 field animation mới có keyframe để preview.
             */
            previewAnimation: {
                type: Boolean,
                default: false
            },
            /**
             * Preview cho dropdown PRESET của tab Scrolling. Gate RIÊNG, không dùng chung
             * với `previewAnimation`: hai bên lấy keyframe từ hai nguồn khác nhau
             * (`entrance_animations` vs `animation-presets.json`), và nới gate cũ sẽ kéo
             * theo hệ hover legacy vốn dùng chung `icon_type: 'animation'`.
             */
            previewScrollingPresets: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:data', 'close'],
        computed: {
            value() {
                return this.data;
            }
        },
        created() {
            // Lazy: chỉ bơm ~18KB keyframes khi merchant thực sự mở dropdown animation.
            // Guard theo id nằm trong hàm nên mở/đóng bao nhiêu lần cũng chỉ một thẻ <style>.
            if (this.previewAnimation) {
                ensureAnimationPreviewKeyframes();
            }
            if (this.previewScrollingPresets) {
                ensureScrollingPresetPreviewKeyframes();
            }
        },
        methods: {
            /**
             * Preview chạy trong tooltip toàn cục thay vì một ô cố định trong popup: hiệu ứng
             * hiện ngay cạnh dòng đang trỏ nên mắt không phải rời khỏi danh sách.
             *
             * Gắn `data-tooltip` lên CẢ DÒNG chứ không phải một icon riêng — 34 option mà mỗi
             * dòng thêm một icon thì danh sách rối, lại bắt merchant rê trúng mục tiêu nhỏ.
             *
             * `Tooltip.vue` là singleton `z-[506]`, cao hơn popup teleport (`z-index: 61`),
             * nên preview không bị popup che.
             *
             * Trả `undefined` (không phải '') cho option không có keyframe, vd mục "Default":
             * Vue bỏ hẳn attribute, nên `e.target.closest('[data-tooltip]')` trong Tooltip.vue
             * không match dòng đó. Để '' thì attribute vẫn tồn tại và dòng đó trở thành một
             * `[data-tooltip]` rỗng, làm Tooltip giữ nguyên nội dung của dòng trước.
             */
            previewTooltip(name) {
                if (this.previewAnimation) {
                    return previewTooltipHtml(name) || undefined;
                }
                if (this.previewScrollingPresets) {
                    return scrollingPresetTooltipHtml(name) || undefined;
                }
                return undefined;
            },
            isActive(item) {
                return this.value === item.name ||
                    (item.name === '__delete__' &&
                        (this.value === undefined ||
                        this.value === '__delete__') ||
                        this.value === '__empty__'
                    );
            },
            choose(val) {
                this.$emit('update:data', val);
                this.$emit('close');
            }
        }
    };
</script>
