<template>
    <div class="ecom-element ecom-search-resutl_text">
        <div v-if="this.exporting" class="ecom-search-text"
            v-html="liquid('text')"
        />
        <div v-else class="ecom-search-text" v-html="text"/>
    </div>
</template>

<script>
import { Liquid, Element } from '@/mixins';
export default {
    name: 'SearchTextResult',
    presets:false,
    mixins: [Liquid, Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        text() {
            let text = this.data.settings.text || this.$t("count_results_found_for_terms");
            text =  text.replace('{{ count }}', 10);
            text = text.replace('{{ terms }}', 'men')
            return text
        },
        liquids() {
            return {
                text: {
                    code: `
                                {% assign count = search.results_count %}
                                {% liquid
                                    assign search_terms = search.terms
                                    assign key_terms = search_terms
                                    if search_terms contains 'product_type:'
                                        assign arr_terms = search_terms | remove: 'product_type:' | replace_first: ' AND',' AND ' | replace_first: '  ', ' ' | split: ' AND '
                                        assign product_type = arr_terms[0] | strip
                                        assign search_terms = arr_terms[1] | strip
                                        if search_terms == blank
                                        assign key_terms = key_terms | remove: ' AND '
                                        assign search_terms = product_type
                                        endif
                                        assign search_terms = key_terms | remove: 'product_type:' | remove: 'product_type: '
                                    endif
                                    assign terms = search_terms
                                %}
                                
                                ${this.lang(this.data.settings.text, 'search_text_1',{ count: 'count', terms: 'terms' })} 

                    `,
                    preview: `The preview title`
                },
            };
        },

        settings() {
            return [
                {
                    type: 'paragraph',
                    options: {
                        wraning: {
                            content: this.$t("this_is_sample_data_only_work_in_live_page")
                        }
                    }
                },
                {
                    type: 'textarea',
                    name: 'text',
                    label: 'Text',
                    // placeholder: 'Use: {{ search }} and {{ count }} to replace search and search result',
                    options: {
                        toolbar: false,
                        height: 80
                    },
                    

                },
                {
                    type: 'paragraph',
                    content: this.$t("count_the_number_of_results_found_and_terms_is_search_term_entered")
                },
            ];
        },

        default() {
            return {
                settings: {
                    'text': this.$t("count_results_found_for_terms")
                },
                style: {
                }
            }
        }
    },
    methods: {
        style() {
            
            let style = [ 
                {
                    group_alias: 'text:spacing',
                    options:{
                        group_title: '',
                        selector: ' .ecom-search-text'
                    }
                }
            ];
            return style;
        },
    }
};
</script>
