import { fetchFiles } from '@/utils';
import { compareObjectsShallow } from '@/utils/helpers';

// q: query
const filterItem = (arr, q, sort) => {
    let [query, brand, category] = q.split('|||');
    let arrFiltered = [];
    arrFiltered = arr.filter(item => {
        let check = true;
        if(brand) {
            check &= item.brand === brand;
        }
        if(category && category !== 'All') {
            check &= item.cate === category;
        }
        if(query) {
            check &= item.name.toLowerCase().indexOf(query.toLowerCase()) > -1;
        }
        return check;
    });
    
    // if(sort) {
    //     if(arrFiltered[0]?.name) {
    //         arrFiltered.sort((a, b) => {
    //             return sort === 'asc' ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name);
    //         });
    //     } else if(arrFiltered[0]?.title) {
    //         arrFiltered.sort((a, b) => {
    //             return sort === 'asc' ? a.title.localeCompare(b.title) : b.title.localeCompare(a.title);
    //         });
    //     }
    // }
    return arrFiltered;
};
export default {
    namespaced: true,
    state: {
        limit: {
            icon: 39
        },
        loading: {
            loadmore: false,
            data: false
        },
        types: {},
        freeImgCat: null
    },
    getters: {
        freeImgCat(state) {
            return state.freeImgCat;
        },
        data(state){
            let itemUpload = {
                'fn':'upload',
                'id': 'item_uplad',
                'value':'',
                'url':'',
                'thumbnail':''
            };
            return async function(type, subtype = '', search, filter, loadmore = false, reload = false, sort = 'asc') {
                let cates = [];
                if(typeof subtype === 'object'){
                    let firstKey = Object.keys(subtype)[0];
                    cates = subtype[firstKey];
                    subtype = firstKey;
                }
                else{
                    cates = [subtype];
                }
                state.types[type] = state.types[type] ?? {};
                let stateType = state.types[type];
                if(subtype && typeof subtype === 'string'){
                    stateType[subtype] = stateType[subtype] ?? {};
                    stateType = stateType[subtype];
                }
                const usesClientSideSearch = type === 'font' && subtype === 'google';
                if(stateType['search'] !== search){
                    Object.assign(stateType , {
                        search, page:1
                    });
                    if(!stateType.loadAll) {
                        stateType.after = '';
                        stateType.items = [];
                    }
                    delete stateType['scroll_top'];
                }
                if(type === 'image') {
                    stateType.sort = sort;
                }
                stateType.items = stateType.items ?? [];
                let items = stateType.items;

                let limit = state.limit[type] ?? 30;

                if(loadmore) {
                    state.loading.loadmore = true;
                    stateType.page ++;
                } else {
                    state.loading.data = true;
                }

                // filter product image or other image
                // Only reset cursor (after) when filter VALUE actually changes, NOT every time filter has values.
                // Bug before: `Object.keys(filter).length > 0` was always true when filter active,
                // causing stateType.after to reset to '' on every Load more → same page fetched again.
                const filterChanged = !compareObjectsShallow(stateType.filter ?? {}, filter);
                if(filterChanged) {
                    stateType.after = '';
                    // Filter changed mid-session: start fresh from page 1
                    stateType.page = 1;
                    stateType.items = [];
                }
                stateType.filter = filter;

                let posStart = ( stateType.page - 1 ) * limit;
                let dataFilted = filterItem(items, stateType.search, stateType.sort);

                const resDataExists = (arr, length) => {
                    let rs = arr.slice(loadmore ? posStart : 0, length);
                    if(subtype == 'uploaded'){
                        return this.$helpers.addObjToFirstArr(rs, itemUpload);
                    }
                    return rs;
                };
                let inData = posStart + limit <= dataFilted.length && !reload && !search;
                // A reload used to empty `items` right here, before the refetch
                // had answered. mergeArrByIndex below already replaces the whole
                // array, so clearing up front bought nothing — and when the
                // refetch came back empty it left the picker with no list and
                // nothing to restore it from.
                if(subtype === 'free' && state.freeImgCat) {
                    inData = false;
                }
                // When filter is active, never serve from cache — always fetch from API
                if(Object.keys(filter).length > 0) {
                    inData = false;
                }
                
                if (stateType.after !== false || subtype === 'freeImgCat') {
                    if (inData || (subtype === 'freeImgCat' && items.length)) {
                        return resDataExists(dataFilted, posStart + limit);
                    } else {
                        let ress = { items: [] };
                        for(let i = 0 ; i < cates.length ; i ++){
                            let res = await fetchFiles(type, cates[i], stateType['search'], filter, stateType.after, limit, this, state?.freeImgCat?.handle || '', loadmore );
                            let {before, after, items} = res;

                            items.forEach(item => {
                                if(item) {
                                    item.brand = cates[i]
                                }
                            });

                            Object.assign(ress, { before, after });
                            ress.items.push(...items);
                        }
                        this.$helpers.mergeArrByIndex(items, ress.items, posStart);

                        // Shopify's file search lags behind writes: a file uploaded
                        // seconds ago — a video especially, it has to transcode
                        // first — may not be indexed yet, and the query answers
                        // with an empty page. Handing that back wipes a library
                        // that is still perfectly intact, so keep what we had.
                        // Only for a plain reload: an empty answer to a search or
                        // to a filter is a real answer and must be shown.
                        const lostEverything = reload
                            && !ress.items.length
                            && items.length
                            && !stateType.search
                            && !Object.keys(filter ?? {}).length;
                        if (lostEverything) {
                            // keep the old cursor too, so Load more still works
                            return resDataExists(
                                filterItem(items, stateType.search, stateType.sort),
                                limit
                            );
                        }

                        stateType.after = ress.after;
                        if(ress.after === false && (!stateType.search || usesClientSideSearch)) {
                            stateType.loadAll = true;
                        }
                        // Google Web Fonts always returns the full list and ignores our
                        // picker query, so search it locally before rendering results.
                        const resultItems = usesClientSideSearch
                            ? filterItem(ress.items, stateType.search, stateType.sort)
                            : ress.items;
                        let rs = resultItems.slice(0, limit);
                        if(posStart == 0 && subtype == 'uploaded'){
                            return this.$helpers.addObjToFirstArr(rs, itemUpload);
                        }
                        return rs;
                    }
                }else{
                    return resDataExists(dataFilted, posStart + limit);
                }

            };
        },
        categories(state){
            return function({ type, subtype }) {
                let cates = {};
                let stateData = state.types?.[type]?.[subtype];
                if(stateData){
                    let { items = [] } = stateData;
                    items.forEach(item => {
                        if(item) {
                            let {brand, cate} = item;
                            if(brand && cate){
                                cates[brand] = cates[brand] ?? {};
                                let cBrand = cates[brand];
                                cBrand[cate] = (cBrand[cate] ?? 0) + 1;
                            }
                        }
                    });
                }
                return cates;
            };
        },
        loading(state){
            return state.loading;
        },
        isLoadmore(state){
            return function(type, subtype){
                if(subtype === 'freeImgCat') {
                    return false;
                }

                let stateType = state.types[type];
                if(subtype) {
                    stateType = stateType[subtype];
                }
                let { search, items } = stateType;
                let dataFilted = items;
                if(search) {
                    dataFilted = filterItem(items, search);
                }
                return stateType.after || stateType.page * (state.limit[type] ?? 30) < dataFilted.length;
            };
        },
        search(state){
            return function(type, subtype){
                let stateType = state.types[type];
                if(subtype) {
                    stateType = stateType[subtype];
                }
                return stateType?.search ?? '';
            };
        },
        scrollTop(state){
            return ({type, subtype, layout}) => {
                let stateType = state.types[type];
                if(subtype) {
                    stateType = stateType[subtype];
                }
                return stateType?.scroll_top?.[layout] ?? 0;
            };
        }

    },
    mutations: {
        freeImgCat(state, payload) {
            state.freeImgCat = payload;
        },
        setScrollTop(state, {type, subtype, layout, top}){
            let stateType = state.types[type];
            if(subtype) {
                stateType = stateType[subtype];
            }
            if(stateType){
                stateType.scroll_top = stateType.scroll_top ?? {};
                stateType.scroll_top[layout] = top;
            }
        },
        removeItem(state, { type, id }) {
            let data = state.types?.[type]?.['uploaded']?.['items'];
            if(data) {
                let i = data.findIndex(d => d.id === id);
                if(i > -1) {
                    data.splice(i, 1);
                }
            }
        },
        addFirstItem(state, {type, subtype,  item}){
            let stateType = state.types[type];
            if(subtype) {
                stateType = stateType[subtype];
            }
            stateType.items.splice(0, 0, item);

        },
        reloadItems(state, { type, subtype }){
            let stateType = state.types[type];
            if(subtype) {
                stateType = stateType[subtype];
            }
            if(stateType){
                //stateType.items.splice(0, stateType.items.length);
                stateType.after = '';
                stateType.page = 1;
            }
        },
        removeLoading(state){
            state.loading = {};
        }
    },
    actions: {
        setScrollTop({commit}, payload){
            commit('setScrollTop', payload);
        },
        removeItem({commit}, payload){
            commit('removeItem', payload);
        },
        addFirst({commit}, payload){
            commit('addFirstItem', payload);
        },
        reload({commit}, payload){
            commit('reloadItems', payload);
        },
        removeLoading({commit}) {
            commit('removeLoading');
        }
    }
};
