<template>
    <div class="w-full relative -mb-[3px]">
        <template v-if="showToolbar">
            <Toolbar
                v-if="toolbar.show || (alwayToolbar && !initHidden)"
                ref="toolbar"
                :type="shortToolbar ? 1 : 2"
                :state="selection.state"
                :field="field"
                @select="eventAction($event)"
                @updateColor="updateColor($event)"
            />
            <ImportLink
                ref="insert-link"
                :data="ObjLink"
                :targetIcon="true"
                @update:link="updateLink"
                @update:remove-link="removeFromMenu"
            />
            <DynamicSources
                v-if="dynamicSouce"
                ref="dynamic-sources"
                @update:metafield="updateMetafield"
            />
            <Generator
                v-if="generator"
                ref="generator"
                @update:content="updateHTML"
            />
            <Emoji
                ref="emoji"
            />

            <!-- <template !shortToolbar">
                <ImportVideo ref="insert-video" @update:video="updateHTML" />
                <ImportImage
                    ref="insert-image"
                    :data="objImage"
                    @update:image="updateHTML"
                    @edit:image="editImage"
                />
            </template><template v-else /> -->
        </template><template v-else />

        <div class="relative w-full">
            <iframe
                class="editor w-full text-sm transition transform -translate-y-px bg-white border ecom-textarea-focus text-form-input border-[#E3E3E3] placeholder-form-input editor h-9 focus:outline-none"
                :class="[toolbar?.show ? 'rounded-b-lg' : '', showToolbar && !alwayToolbar && !toolbar?.show ? 'rounded' : 'rounded-b-lg']"
                :style="'min-height:' + minHeight + 'px;'"
                :data-type="type"
                :srcdoc="srcdoc"
                ref="editor"
                @load="onload"
            />
            <div
                class="absolute top-0 rounded-0 pointer-events-none bottom-px left-px right-px z-1"
            />
            <span
                v-if="field.placeholder && !html"
                class="absolute text-sm text-gray-500  pointer-events-none top-2 left-3 right-3 truncate"
                v-html="field.placeholder"
            /><template v-else />
            <button
                v-if="showToolbar && (!alwayToolbar || initHidden)"
                type="button"
                class="absolute transform text-gray-600 cursor-pointer transition rounded-full bg-gray-100 hover:bg-gray-200     top-0.5 right-1 p-1.5 w-7 h-7 flex items-center justify-center"
                :class="[toolbar.show ? 'text-red-600' : '', isfocus ? ' hidden' : '']"
                :data-tooltip="(toolbar.show ? $t('hide') : $t('show')) + ' ' + $t('toolbar')"
                @click="toolbar.show = !toolbar.show"
            >
                <EcomIcon :source="icons[toolbar.show ? 'ChevronDownMinor' : 'EditMinor']" :size="'w-4'" class="flex items-center"></EcomIcon>
            </button><template v-else />
            <ModifyMenu
                v-if="showToolbar"
                ref="modify"
                :url="metadata.menu"
                :info="metadata.posMenu"
                :max-width="metadata.maxWidthMenu"
                @update:delete="removeFromMenu"
                @update:edit="editFromMenu"
            /><template v-else />
        </div>
        <div
            v-if="editSource"
            ref="source-actions"
            class="flex text-sm items-center justify-center mt-2 gap-2"
        >
            <button
                class="inline-flex items-center px-2 py-2 border border-transparent shadow-sm text-xs font-medium rounded-md text-white bg-gray-600    focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 group gap-1"
                @click="eventAction('dynamicSources')"
            >
                <EcomIcon :source="icons.ecRefresh" :size="'w-5'" class="flex items-center"></EcomIcon>
                {{ $t('change_source') }}
            </button>
            <button
                class="inline-flex items-center px-2 py-2 border border-transparent shadow-sm text-xs font-medium rounded-md bg-white     border-gray-250 focus:outline-none focus:ring-2 focus:ring-offset-2 group gap-1"
                @click="deleteSource"
            >
                <EcomIcon :source="icons.DeleteMinor" :size="'w-5'"></EcomIcon>
                {{ $t('delete_source') }}
            </button>
        </div>
        <!-- <div
            v-if="wasPaste"
            class="inline-block w-full p-3 mt-2 text-sm text-gray-500  whitespace-normal border-l-4 border-yellow-200 bg-yellow-50 i-full"
        >
            <span class="py-0.5 px-1.5 bg-gray-200 rounded-sm">⌘ + shift + v</span> to paste text
            only
        </div>
        <template v-else /> -->
    </div>
  </template>

  <script lang="ts">
  import Toolbar from './Toolbar.vue';
  import Emoji from './Emoji.vue';
  import ImportLink from './InsertLink/InsertLink.vue';
  import DynamicSources from './InsertDynamicSources/DynamicSources.vue';
  import Generator from './Generator.vue';
  import ModifyMenu from './Menu.vue';
  import { node2Obj } from '../../utils';
  import { resolveMetaEdgeCaret, applyCaretRange } from '@/utils/contentEditable';
  import {textHelper} from '@/utils';
  import { EditMinor, ChevronDownMinor, DeleteMinor, ecRefresh } from "@/assets/icons";

  /** Đánh dấu dynamic source tag đang được chọn. Cố tình dùng ATTRIBUTE thay vì class:
   *  normalizeEditorHtml() strip nó ở mọi đường HTML đi ra khỏi editor, nên trạng thái
   *  chỉ tồn tại trong DOM của iframe, không lọt vào settings.content lẫn trang live. */
  const ACTIVE_META_ATTR = 'data-ecom-meta-active';
  const ACTIVE_META_SELECTOR = `[${ACTIVE_META_ATTR}]`;
  /** Không có cờ `g` — dùng với .test() nên không được mang lastIndex giữa các lần gọi. */
  const HAS_FONT_RE = /<font/i;
  /** Khớp cả dạng có giá trị (`=""`) lẫn không, kèm khoảng trắng đứng trước. */
  const ACTIVE_META_ATTR_RE = new RegExp(
      `\\s+${ACTIVE_META_ATTR}(?:\\s*=\\s*(?:"[^"]*"|'[^']*'|[^\\s"'>]+))?`,
      'gi'
  );

  export default {
    name: 'Editor',
    components: {
        Toolbar,
        ImportLink,
        ModifyMenu,
        DynamicSources,
        Generator,
        Emoji
    },
    props: {
        data: {
            type: String,
            default: ''
        },
        type: {
            type: Number,
            default: 2
        },
        field: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    emits: ['update:data'],
    data() {
        return {
            icons: {
                EditMinor, ChevronDownMinor, DeleteMinor, ecRefresh
            },
            value: '',
            html: '',
            count: 0,
            editor: null,
            editorDoc: null,
            isfocus: false,
            editSource: false,
            itv: null,
            toolbar: {
                show: true
            },
            selection: {
                selection: undefined,
                action: undefined,
                range: undefined,
                state: {},
                image: {
                    node: undefined
                }
            },
            metadata: {
                images: [],
                menu: '',
                posMenu: {},
                maxWidthMenu: 0
            },
            wasPaste: false,
            _editingMetaNode: null as Element | null,
            /** Node đang được highlight — giữ để khỏi phải quét DOM ở mọi click. */
            _activeMetaNode: null as Element | null,
            /** Cloned range saved when opening dynamic sources picker (survives iframe blur). */
            _insertRangeBookmark: null as Range | null,
            srcdoc: `<html><head><meta http-equiv=Content-Type content="text/html; charset=UTF-8"><link rel="stylesheet" href="https://cdn.ecomposer.app/vendors/css/ecom-base.css"/><style>html{height:100%;}body{box-sizing: border-box;margin: 0;padding: 6px 12px;height:100%;font-size:12px;line-height:20px;color:#303030;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif,'Apple Color Emoji','Segoe UI Emoji'}iframe,img{max-width:100%}ol,ul{margin:0;margin-block-start:0;margin-block-end:0;margin-inline-start:0;margin-inline-end:0;padding-inline-start:20px}
                .ecom-dynamic-meta {
                     position: relative;
                    background: #eaf4ff;
                    color: #003a5a;
                    padding: 3px 6px;
                    display: inline-flex;
                    margin: 1px 2px;
                    border-radius: 6px;
                    font-size: 10px;
                    cursor: pointer;
                    align-items: center;
                    justify-content: center;
                }
                .ecom-dynamic-meta:after {
                    content: attr(data-title);
                    padding-left: 20px;
                }
                .ecom-meta-editor[data-ecom-meta-active] > .ecom-dynamic-meta {
                    background: #cfe4ff;
                    color: #00304a;
                    box-shadow: 0 0 0 2px #005bd3;
                }
                sub, sup{
                    position: relative;
                    font-size: 75%;
                    line-height: 0;
                    vertical-align: baseline;
                }
                sup{
                    top: -.5em;
                }
                sub{
                    bottom: -.25em;
                }
                .ecom-dynamic-meta::before {
                    content: '';
                    position: absolute;
                    left: 7px;
                    top: 6px;
                    width: 12px;
                    height: 14px;
                    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512"><path d="M224 512C100.3 512 0 476.2 0 432V80C0 35.82 100.3 0 224 0C347.7 0 448 35.82 448 80V432C448 476.2 347.7 512 224 512zM416 80.45C415.7 79.69 414.4 77.27 409.8 73.31C402.4 67.11 389.9 60.09 371.6 53.57C335.4 40.62 283.2 32 224 32C164.8 32 112.6 40.62 76.37 53.57C58.1 60.09 45.59 67.11 38.25 73.31C33.55 77.27 32.29 79.69 32 80.45V182.1C46.47 192.7 69.9 202.8 100.9 210.4C135.5 218.9 177.1 224 224 224C270 224 312.5 218.9 347.1 210.4C378.1 202.8 401.5 192.7 416 182.1V80.45zM416 219.5C398.8 228.4 377.9 235.8 354.8 241.5C317.3 250.7 272.2 256 224 256C175.8 256 130.7 250.7 93.22 241.5C70.11 235.8 49.18 228.4 32 219.5V310.1C46.47 320.7 69.9 330.8 100.9 338.4C135.5 346.9 177.1 352 224 352C270 352 312.5 346.9 347.1 338.4C378.1 330.8 401.5 320.7 416 310.1V219.5zM38.25 438.7C45.59 444.9 58.1 451.9 76.37 458.4C112.6 471.4 164.8 480 224 480C283.2 480 335.4 471.4 371.6 458.4C389.9 451.9 402.4 444.9 409.8 438.7C414.4 434.7 415.7 432.3 416 431.6V347.5C398.8 356.4 377.9 363.8 354.8 369.5C317.3 378.7 272.2 384 224 384C175.8 384 130.7 378.7 93.22 369.5C70.11 363.8 49.18 356.4 32 347.5V431.6C32.29 432.3 33.55 434.7 38.25 438.7zM416 431.4C416.1 431.3 416.1 431.3 416.1 431.3L416 431.4zM31.96 431.4C31.94 431.3 31.93 431.3 31.92 431.3L31.96 431.4zM31.96 80.56C31.93 80.65 31.92 80.7 31.92 80.7L31.96 80.56zM416.1 80.7C416.1 80.7 416.1 80.65 416 80.56z"/></svg>');}</style> </head> <body class="text-content ecom-html" data-ecom-autop="${this.field?.options?.autop ? 'true' : 'false'}></body></html>`
        };
    },
    computed: {
        showToolbar() {
            return (this.type > 0 && this.field?.options?.toolbar !== false) || this.alwayToolbar;
        },
        alwayToolbar() {
            return ['short', 'full'].indexOf(this.field?.options?.toolbar) > -1;
        },
        shortToolbar() {
            return this.field?.options?.toolbar == 'short' || this.type === 1;
        },
        initHidden() {
            return this.field?.options?.initHidden == true;
        },
        minHeight() {
            return this.field?.options?.height ?? '';
        },
        dynamicSouce() {
            return this.field?.options?.dynamic ?? false;
        },
        generator(){
            return this.field?.options?.generator ?? false;
        },
        ObjLink() {
            if (!this.selection.range) {
                return {};
            }
            let link = this.selectionIsLink();
            if (!link) {
                return { text: this.selection.range.toString() };
            }
            let obj = node2Obj(link);
            if (link.querySelector('[data-ecom-role="external-link-icon"]')) {
                obj.targetIcon = 1;
            }
            return obj;
        },
        objImage() {
            if (!this.selection.image.node) {
                return {};
            }
            return node2Obj(this.selection.image.node);
        }
    },
    watch: {
        data: {
            immediate: true,
            handler: function (val) {
                if (!this.isEmit || val !== this.html) {
                    this.value = val ?? '';
                    this.html = val ?? '';
                    if (this.editorDoc) {
                        this.editorDoc.body.innerHTML = this.normalizeEditorHtml(val ?? '');
                        this.editorDoc.body.querySelectorAll('.ecom-meta-editor').forEach((el) => {
                            el.setAttribute('contenteditable', 'false');
                        });
                    }
                    // Nội dung đổi (chọn element khác) → range/meta node cũ trỏ vào DOM đã bị
                    // thay thế, phải xoá để không chèn dynamic source vào node mồ côi.
                    this.selection.range = undefined;
                    this.selection.selection = undefined;
                    this._insertRangeBookmark = null;
                    this._editingMetaNode = null;
                    // innerHTML vừa bị ghi đè → node cũ đã detach, thả ra để không
                    // giữ sống cả cây DOM cũ.
                    this._activeMetaNode = null;
                    this.editSource = false;
                    this.clearSelection();
                    //this.getStateSelection();
                }
                this.isEmit = false;
            }
        }
    },
    mounted() {
        this.updateMaxWidthMenu();
        if (this.initHidden) {
            this.toolbar.show = false;
        }
        // this.$nextTick(() => {
        //     this.metadata.maxWidthMenu = this.$refs.editor?.clientWidth;
        // });
        // window.addEventListener('resize', this.updateMaxWidthMenu);
    },
    updated() {
    // Xóa bỏ event listener khi component bị hủy
        this.updateMaxWidthMenu();
    },
    methods: {
        isEmptyEditorHtml(html) {
            if (html == null || html === '') {
                return true;
            }
            const trimmed = String(html).trim();
            if (!trimmed) {
                return true;
            }
            if (/^(<br\s*\/?>|&nbsp;|\s)+$/i.test(trimmed)) {
                return true;
            }
            if (/^<(p|div)>(\s|<br\s*\/?>|&nbsp;)*<\/\1>$/i.test(trimmed)) {
                return true;
            }
            return false;
        },
        // Chuẩn hoá HTML editor — dùng chung cho lúc nạp, emit và toggle code mode:
        //  1) execCommand sinh `<font>` (foreColor → `<font color>`, code mode → `<font face="monospace">`).
        //     Đổi cho giống Quill: `<font>` có màu → `<span style="color">`, `<font>` không màu → mở thẻ.
        //  2) Nội dung rỗng (<br>, &nbsp;, <p></p>...) → chuỗi rỗng.
        // Strip `<font>` TRƯỚC rồi mới check rỗng (vd `<font><br></font>` sau khi mở thẻ mới lộ là rỗng).
        normalizeEditorHtml(html) {
            //  3) Attribute highlight tag đang chọn chỉ để hiển thị trong editor → phải xoá.
            //     Dùng string replace chứ KHÔNG parse DOM: nếu đi qua innerHTML thì mỗi lần
            //     gõ (khi đang có tag highlight) đều bị browser chuẩn hoá lại markup —
            //     vừa tốn CPU vừa lặng lẽ đổi HTML người dùng.
            if (html && html.indexOf(ACTIVE_META_ATTR) !== -1) {
                html = html.replace(ACTIVE_META_ATTR_RE, '');
            }
            // `/<font/i.test()` thay cho `toLowerCase().indexOf()`: tương đương hoàn toàn
            // nhưng không copy cả chuỗi HTML mỗi lần gõ.
            if (html && HAS_FONT_RE.test(html)) {
                const host = document.createElement('div');
                host.innerHTML = html;
                host.querySelectorAll('font').forEach((font) => {
                    const color = font.style.color || font.getAttribute('color') || '';
                    if (color) {
                        const span = document.createElement('span');
                        span.style.color = color;
                        if (font.style.backgroundColor) span.style.backgroundColor = font.style.backgroundColor;
                        while (font.firstChild) span.appendChild(font.firstChild);
                        font.replaceWith(span);
                    } else {
                        const parent = font.parentNode;
                        if (!parent) return;
                        while (font.firstChild) parent.insertBefore(font.firstChild, font);
                        parent.removeChild(font);
                    }
                });
                html = host.innerHTML;
            }
            return this.isEmptyEditorHtml(html) ? '' : html;
        },
        updateMaxWidthMenu() {
            this.$nextTick(() => {
                const editor = this.$refs.editor;
                if (editor) {
                    this.metadata.maxWidthMenu = editor.clientWidth;
                }
            });
        },
        onload() {
            if (!this.$refs['editor']) {
                return;
            }
            this.editor = this.$refs['editor'];
            this.editorDoc = this.editor.contentDocument;
            this.editorDoc.body.innerHTML = this.normalizeEditorHtml(this.value);
            this.editorDoc.designMode = 'on';
            // Must run AFTER designMode='on': ensure existing ecom-meta-editor spans
            // (saved before this fix) are non-editable so the cursor cannot land inside them.
            this.editorDoc.body.querySelectorAll('.ecom-meta-editor').forEach((el) => {
                el.setAttribute('contenteditable', 'false');
            });
            this.editorDoc.body.oninput = this.inputEditor;
            this.editorDoc.body.onselectstart = this.selectstart;
            this.editorDoc.body.onclick = this.clickEditor;
            this.editorDoc.body.onblur = this.selectend;
            this.editorDoc.body.onkeydown = this.keyDown;
            this.editorDoc.body.onpaste = this.pasteContent;
        },
        formatDoc(sCmd, sValue) {
            this.editorDoc.execCommand(sCmd, false, sValue);
        },
        inputEditor(e) {
            if (this.type === 1 && e.keyCode === 13) {
                e.preventDefault();
                return false;
            }

            let html = this.selection.state['codeFormat'] ? e.target.querySelector('xmp')?.innerHTML : e.target.innerHTML;
            html = this.normalizeEditorHtml(html);
            this.html = html;
            this.$emit('update:data', html);
            this.isEmit = true;
            //this.onSelectionChange();
            if (this.type === 2) {
                if (
                    e.target.scrollHeight > 64 &&
                    e.target.scrollHeight < 250 &&
                    this.minHeight === ''
                ) {
                    e.target.style.minHeight = e.target.scrollHeight + 'px';
                } else if (e.target.scrollHeight < 64 && this.minHeight === '') {
                    e.target.style.minHeight = '';
                }
            }
        },
        keyDown(e) {
            // if (/*e.which === 13 &&  */this.type == 1) {
            //     // e.preventDefault();
            // }
            if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.keyCode == 86) {
                this.wasPaste = true;
                setTimeout(() => {
                    this.wasPaste = false;
                }, 5000);
            }
        },
        pasteContent(e) {
            if (this.type == 1 && this.editorDoc) {
                let clipboardData = e.clipboardData || window.clipboardData;
                let pastedData = clipboardData.getData('text/plain') || '';
                console.log(e.clipboardData.getData('text/plain'), window.clipboardData);
                if (pastedData !== '') {
                    this.formatDoc('insertText', pastedData);
                    e.preventDefault();
                }
            }
        },
        restoreRange(selectLink = true) {
            let rangeData = this.selection.range;
            if (!rangeData) {
                return false;
            }
            let $link = this.selectionIsLink();
            let range = rangeData;
            if ($link && selectLink) {
                range = this.editorDoc.createRange();
                range.selectNodeContents($link);
            }
            this.editorDoc.getSelection().removeAllRanges();
            this.editorDoc.getSelection().addRange(range);
        },
        updateColor(color) {
            clearTimeout(this.itv);
            this.itv = setTimeout(()=> {
                // this.formatDoc(color.action, color.val);

                color.action === 'foreColor'
                    ? color.val.includes("#")?this.formatDoc(color.action, color.val):textHelper?.inserColor(this.selection, color.val)
                    : this.formatDoc(color.action, color.val);

                if(this.editorDoc)
                    this.editorDoc.body.dispatchEvent(new Event('input'));
            },100)
        },
        eventAction(action) {
            this.selection.action = action;

            switch (action) {
                case 'p':
                case 'h1':
                case 'h2':
                case 'h3':
                case 'h4':
                case 'h5':
                case 'h6':
                    this.formatDoc('formatblock', action);
                break;
                case 'insertLink':
                    this.$refs['insert-link'].show = true;
                    this.$refs['emoji'].show = false;
                    break;
                case 'backColor':
                    this.$refs['emoji'].show = false;
                    break;
                case 'foreColor':
                    this.$refs['emoji'].show = false;
                    break;
                case 'dynamicSources': {
                    if (this.selection.range) {
                        this._insertRangeBookmark = this.selection.range.cloneRange();
                    }
                    const $sources = this.$refs['dynamic-sources'];
                    if ($sources) {
                        // Gán TRƯỚC khi bật show: watcher `show` bên DynamicSources đọc
                        // currentSource ngay lúc mở để nhảy tới đúng nguồn đang dùng.
                        // null = đang chèn tag mới, panel mở ở màn gốc như cũ.
                        $sources.currentSource = this.editSource ? this.readEditingMetaInfo() : null;
                        $sources.show = true;
                    }
                    this.$refs['emoji'].show = false;
                    this.$store.dispatch('dynamicSources/loadDynamicSources');
                    break;
                }
                case 'contentGenerator':
                    this.$refs['generator'].show = true;
                    this.$refs['emoji'].show = false;
                    // this.$store.dispatch('dynamicSources/loadDynamicSources');
                    break;
                case 'insertunorderedlist':
                    this.formatDoc('insertunorderedlist');
                    this.$refs['emoji'].show = false;
                    break;
                case 'insertorderedlist':
                    this.formatDoc('insertorderedlist');
                    this.$refs['emoji'].show = false;
                    break;
                case 'removeFormat':
                    this.$refs['emoji'].show = false;
                    textHelper.removeList(this.selection);
                    this.formatDoc('removeFormat');
                    this.formatDoc('formatblock', 'div');
                    textHelper.removeFormat(this.selection);
                    // this.removeEmptyTags(this.selection);
                    this.selection.state = [];
                    if(this.editorDoc && this.editorDoc.body)
                        this.editorDoc.body.dispatchEvent(new Event('input'));
                    break;
                case 'codeFormat':
                    this.$refs['emoji'].show = false;
                    this.switchFormatCode();
                    this.selection.state[action] = !this.selection.state[action];
                    if(this.editorDoc)
                        this.editorDoc.body.dispatchEvent(new Event('input'));
                    break;
                case 'emoji':
                    // let range, selection;
                    this.selection.range = this.editorDoc.createRange();//Create a range (a range is a like the selection but invisible)
                    this.selection.range.selectNodeContents(this.editorDoc.body);//Select the entire contents of the element with the range
                    this.selection.range.collapse(false);//collapse the range to the end point. false means collapse to end rather than the start
                    this.selection.selection = this.editorDoc.getSelection();//get the selection object (allows you to change selection)
                    this.selection.selection.removeAllRanges();//remove any selections already made
                    this.selection.selection.addRange(this.selection.range);//make the range you have just created the visible selection
                    this.$refs['emoji'].show = !this.$refs['emoji'].show;
                    
                    const wrapper = this.$refs['emoji'].$refs['wrapper'];
                    const _this = this;
                    const handleClick = function(e) {
                        if(e.target.className.includes('emoji-item')){
                            _this.editorDoc.dispatchEvent(new Event('focus'))
                            _this.editorDoc.execCommand('insertText', false, e.target.innerHTML);
                        }
                    };
                    if(wrapper && this.count == 0) {
                        this.count++;
                        wrapper.addEventListener('click', handleClick);
                    }
                    let scrollChild = this.$refs['toolbar'].$el.nextElementSibling.getBoundingClientRect().top;
                    let scrollParent = this.$refs['toolbar'].$refs['toolbar'].closest('.overflow-auto').getBoundingClientRect().top;
                    
                    if(this.$refs['emoji'].show) {
                        this.$nextTick(() => {
                            setTimeout(() => {
                                this.$refs['emoji'].$refs['wrapper'].scrollIntoView({behavior: "smooth", block: "center", inline: "start"});
                            }, 50);
                            //this.$refs['emoji'].$refs['wrapper'].scrollIntoView({behavior: "smooth", block: "center", inline: "start"});
                        })
                    }else {
                        setTimeout(() => {
                            this.$refs['toolbar'].$refs['toolbar'].closest('.overflow-auto').scrollTo({top: scrollChild - scrollParent, left: 0, behavior: "smooth"});
                        }, 100);
                    }
                    break;
                default:
                    this.selection.state[action] = !this.selection.state[action];
                    this.formatDoc(action, action);
                    break;
            }
            this.getStateSelection();
        },
        clearSelection() {
            if (window.getSelection) {
                if (window.getSelection().empty) {
                    window.getSelection().empty();
                } else if (window.getSelection().removeAllRanges) {
                    window.getSelection().removeAllRanges();
                }
            } else if (this.editorDoc.selection) {
                this.editorDoc.selection.empty();
            }
        },
        getStateSelection() {
            const cmds = [
            {
                    tag: 'p',
                    action: 'p',
                },
                {
                    tag: 'h1',
                    action: 'h1',
                },
                {
                    tag: 'h2',
                    action: 'h2',
                },
                {
                    tag: 'h3',
                    action: 'h3',
                },
                {
                    tag: 'h4',
                    action: 'h4',
                },
                {
                    tag: 'h5',
                    action: 'h5',
                },
                {
                    tag: 'h6',
                    action: 'h6',
                },
                {
                    tag: 'b',
                    action: 'bold'
                },
                {
                    tag: 'i',
                    action: 'italic'
                },
                {
                    tag: 'u',
                    action: 'underline'
                },
                {
                    tag: 'ol',
                    action: 'insertorderedlist'
                },
                {
                    tag: 'ul',
                    action: 'insertunorderedlist'
                },
                {
                    tag: 'sub',
                    action: 'subscript'
                },
                {
                    tag: 'sup',
                    action: 'superscript'
                },
                {
                    tag: 'span',
                    action: 'backColor'
                },
                {
                    tag: 'font',
                    action: 'foreColor'
                },
                {
                    tag: 'strike',
                    action: 'strikeThrough'
                }
            ];

            cmds.forEach((cmd) => {
                this.selection.state[cmd.action] = this.isSelectionInTag(cmd.tag);
                if (cmd.tag === 'font') {
                    let fontNode = this.editorDoc.getSelection().focusNode;
                    while (fontNode && fontNode !== 'BODY') {
                        fontNode = fontNode.parentElement;
                        if(fontNode?.style?.backgroundColor) {
                            this.selection.state['backColor'] =  true;
                            break;
                        }
                    }
                }
            });

        },
        removeEmptyTags(element) {
            const tagsToKeep = ['BR', 'HR', 'IMG', 'INPUT', 'META']; // Thẻ đóng hoặc không cần nội dung

            if (element.nodeType === Node.TEXT_NODE) {
                element = element.parentElement;
            }

            const elements = Array.from(element.querySelectorAll('*'));

            elements.forEach(el => {
                // Kiểm tra nếu thẻ trống và không nằm trong danh sách các thẻ cần giữ lại
                if (!el.textContent.trim() && el.children.length === 0 && !tagsToKeep.includes(el.tagName)) {
                    el.remove();
                }
            });
        },
        selectionIsLink() {
            var container = this.selection.range.commonAncestorContainer;
            if (container.nodeType == 3) {
                container = container.parentNode;
            }
            return container.closest('a') ?? false;
        },
        isSelectionInTag(tag) {
            // Get the current node
            let selection = this.editorDoc.getSelection();
            let currentNode = selection.focusNode;
            // While the node is not the editor division

            while (currentNode && currentNode !== 'BODY')
            {
                if(currentNode?.tagName === tag.toUpperCase())
                    return true;
                // Move up in the tree
                currentNode = currentNode?.parentNode;
            }
            return false;
        },
        setDataMenu(el) {
            let $menu = this.$refs['modify'];
            let $editor = this.$refs['editor'],
                $editor_h = $editor.offsetHeight,
                $editor_st = $editor.scrollTop;
            let top = el.offsetTop + el.offsetHeight / (el.tagName == 'IMG' ? 2 : 1) - $editor_st;
            top = top > $editor_h ? $editor_h : top;
            this.metadata.posMenu = {
                top: top,
                left: el.offsetLeft,
                width: el.offsetWidth
            };
            $menu.show = true;
        },
        onSelectionChange() {
            if (this.type == 0) {
                return;
            }
            this.selection.selection = this.editorDoc.getSelection();

            this.selection.range = this.editorDoc.getSelection().getRangeAt(0);
            this.getStateSelection();
            let isLink = this.selectionIsLink();
            if (isLink) {
                this.metadata.menu = isLink.getAttribute('href');
                this.setDataMenu(isLink);
                this.selection.action = 'insertLink';
            } else {
                let $menu = this.$refs['modify'];
                $menu.show = false;
            }
        },
        selectstart() {
            if (this.type == 0) {
                return;
            }
            this.selection.selection = this.editorDoc.getSelection();
            this.editorDoc.addEventListener('selectionchange', this.onSelectionChange);
        },
        selectend() {
            if (this.type == 0) {
                return;
            }
            this.editorDoc.removeEventListener('selectionchange', this.onSelectionChange);
            this.isfocus = false;
            setTimeout(() => {
                let $modify = this.$refs['modify'];
                if ($modify) {
                    $modify.show = false;
                }
            }, 200);
        },
        removeFromMenu() {
            if (this.selection.action == 'insertLink') {
                textHelper.removeLink(this.selection);
                if(this.editorDoc)
                    this.editorDoc.body.dispatchEvent(new Event('input'));
            } else if (this.selection.action == 'insertImage') {
                this.selection.image.node.remove();
                if(this.editorDoc)
                    this.editorDoc.body.dispatchEvent(new Event('input'));
            }
        },
        editFromMenu() {
            if (this.selection.action == 'insertLink') {
                this.eventAction('insertLink');
            } else if (this.selection.action == 'insertImage') {
                this.$refs['insert-image'].show = true;
            }
        },
        editImage(val) {
            if (val && this.selection.image.node) {
                var element = this.editorDoc.createElement('div');
                element.innerHTML = val;
                element = element.firstChild;
                this.selection.image.node.replaceWith(element);
                if(this.editorDoc)
                    this.editorDoc.body.dispatchEvent(new Event('input'));
            }
        },
        updateLink({ data }) {
            this.editorDoc.body.focus();
            if (this.selection.range) {
                // this.selection.range.deleteContents();
                // this.formatDoc('removeFormat');
                this.formatDoc('delete');
                // this.editorDoc.getSelection().deleteContents();
            }
            this.restoreRange();
            textHelper.insertLink(this.selection, data);
            if(this.editorDoc)
                this.editorDoc.body.dispatchEvent(new Event('input'));

        },
        /** Đọc thông tin nguồn của tag đang được sửa, để panel hiện "Current source"
         *  và tick sẵn item tương ứng. Trả null nếu không xác định được tag. */
        readEditingMetaInfo() {
            const wrapper = this._editingMetaNode as Element | null;
            if (!wrapper) return null;
            const metaSpan = wrapper.classList?.contains('ecom-dynamic-meta')
                ? wrapper
                : wrapper.querySelector?.('.ecom-dynamic-meta');
            if (!metaSpan) return null;
            return {
                // data-title bị cắt ngắn cho vừa chip; tag mới có kèm bản đầy đủ.
                title: metaSpan.getAttribute('data-title') || '',
                fullTitle: metaSpan.getAttribute('data-title-full')
                    || metaSpan.getAttribute('data-title') || '',
                path: metaSpan.getAttribute('data-meta') || '',
                key: metaSpan.getAttribute('data-meta-key') || ''
            };
        },
        findMetaEditorWrapper(node: Node | null): Element | null {
            if (!node) return null;
            const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
            return el?.closest?.('.ecom-meta-editor') ?? null;
        },
        rangeSelectsMetaEditor(range: Range): Element | null {
            if (!range || !this.editorDoc) return null;
            let node: Node | null = range.commonAncestorContainer;
            if (node.nodeType === Node.TEXT_NODE) {
                node = node.parentElement;
            }
            const metaEditor = (node as Element)?.classList?.contains('ecom-meta-editor')
                ? (node as Element)
                : (node as Element)?.closest?.('.ecom-meta-editor') ?? null;
            if (!metaEditor || range.collapsed) return null;
            const full = this.editorDoc.createRange();
            full.selectNode(metaEditor);
            const startsBeforeOrAt = range.compareBoundaryPoints(Range.START_TO_START, full) <= 0;
            const endsAfterOrAt = range.compareBoundaryPoints(Range.END_TO_END, full) >= 0;
            return startsBeforeOrAt && endsAfterOrAt ? metaEditor : null;
        },
        shouldInsertBeforeMetaEditor(range: Range, metaEditor: Element): boolean {
            const metaSpan = metaEditor.querySelector('.ecom-dynamic-meta');
            if (!metaSpan || !this.editorDoc) return true;
            const probe = this.editorDoc.createRange();
            probe.setStart(range.startContainer, range.startOffset);
            probe.collapse(true);
            const afterMeta = this.editorDoc.createRange();
            afterMeta.setStartAfter(metaSpan);
            afterMeta.collapse(true);
            return probe.compareBoundaryPoints(Range.START_TO_START, afterMeta) < 0;
        },
        /** Range chỉ dùng được khi 2 đầu còn nằm trong body của editor HIỆN TẠI.
         *  Đổi sang element khác → watcher `data` ghi đè innerHTML, range cũ trỏ vào
         *  DOM đã detach nên insertNode() chèn vào node mồ côi (editor không hiện gì). */
        isUsableRange(range: Range | null | undefined): boolean {
            const body = this.editorDoc?.body;
            if (!range || !body) return false;
            const inBody = (node: Node | null) => !!node && (node === body || body.contains(node));
            return inBody(range.startContainer) && inBody(range.endContainer);
        },
        /** Chưa click vào editor (range null) hoặc range đã cũ → đặt con trỏ ở CUỐI nội dung
         *  để dynamic source vẫn được chèn thay vì bị bỏ qua im lặng. */
        ensureInsertRange(): boolean {
            if (this.isUsableRange(this.selection.range)) return true;
            const body = this.editorDoc?.body;
            if (!body) return false;
            // Code mode: toàn bộ nội dung nằm trong <xmp> và inputEditor chỉ đọc xmp.innerHTML
            // → phải chèn BÊN TRONG xmp, nếu không tag sẽ mất ở lần gõ tiếp theo.
            const codeHost = body.querySelector('xmp');
            // Nội dung thường được bọc trong <p>/<div>/<h*> — chèn vào CUỐI block cuối cùng
            // để tag nằm ngay sau text, không thành sibling nằm dưới đoạn văn.
            const last = body.lastChild as Element | null;
            const target =
                codeHost ||
                (last?.nodeType === Node.ELEMENT_NODE &&
                /^(P|DIV|H[1-6]|BLOCKQUOTE)$/.test(last.tagName) &&
                !last.classList?.contains('ecom-meta-editor')
                    ? last
                    : body);
            const range = this.editorDoc.createRange();
            range.selectNodeContents(target);
            range.collapse(false);
            const sel = this.editorDoc.getSelection();
            if (sel) {
                sel.removeAllRanges();
                sel.addRange(range);
                this.selection.selection = sel;
            }
            this.selection.range = range;
            return true;
        },
        /** Đặt con trỏ cạnh dynamic source tag ở rìa nội dung khi browser không tự đặt
         *  được (tag là contenteditable="false" nên không có vị trí gõ sau/trước nó).
         *  Logic dùng chung với inline-edit trên canvas — xem resolveMetaEdgeCaret. */
        ensureCaretPlaceable(event?: MouseEvent) {
            const range = resolveMetaEdgeCaret(this.editorDoc?.body, event, this.editorDoc);
            if (!range) return;
            applyCaretRange(range, this.editorDoc);
            this.selection.selection = this.editorDoc.getSelection();
            this.selection.range = range;
        },
        /** Đánh dấu tag đang được chọn để user biết mình đang sửa cái nào khi editor có
         *  nhiều dynamic source. Chỉ đổi attribute, không đụng nội dung/layout. */
        highlightMetaNode(wrapper: Element | null) {
            const body = this.editorDoc?.body;
            if (!body) return;
            // Đường nóng: clickEditor gọi hàm này ở MỌI click trong editor. Click vào
            // chữ thường mà chẳng có gì đang sáng thì thoát luôn — không quét DOM.
            if (!wrapper && !this._activeMetaNode) return;
            if (this._activeMetaNode && this._activeMetaNode !== wrapper) {
                this._activeMetaNode.removeAttribute(ACTIVE_META_ATTR);
            }
            if (wrapper) {
                // Chỉ quét khi BẬT highlight (hiếm — click vào chip): nội dung dán vào
                // có thể mang theo attribute của chip được copy lúc đang sáng.
                body.querySelectorAll(ACTIVE_META_SELECTOR).forEach((el) => {
                    if (el !== wrapper) el.removeAttribute(ACTIVE_META_ATTR);
                });
                wrapper.setAttribute(ACTIVE_META_ATTR, '');
            }
            this._activeMetaNode = wrapper;
        },
        /** Nút Change/Delete source render BÊN DƯỚI iframe nên hay nằm ngoài vùng nhìn
         *  của panel setting — cuộn tới ngay sau khi bấm vào tag để user thấy. */
        revealSourceActions() {
            this.$nextTick(() => {
                this.$refs['source-actions']?.scrollIntoView({
                    behavior: 'smooth',
                    block: 'nearest',
                    inline: 'nearest'
                });
            });
        },
        insertDynamicSourceElement(element: Node) {
            const range = this.selection.range;
            if (!range || !this.editorDoc) return;

            const startMeta = this.findMetaEditorWrapper(range.startContainer);
            const endMeta = this.findMetaEditorWrapper(range.endContainer);
            const selectedMeta = this.rangeSelectsMetaEditor(range);
            const metaEditor = selectedMeta || startMeta || endMeta;

            if (metaEditor?.parentNode) {
                const insertBefore = selectedMeta
                    ? false
                    : startMeta
                        ? this.shouldInsertBeforeMetaEditor(range, metaEditor)
                        : !endMeta;
                if (insertBefore) {
                    metaEditor.parentNode.insertBefore(element, metaEditor);
                } else {
                    metaEditor.parentNode.insertBefore(element, metaEditor.nextSibling);
                }
                return;
            }

            if (!range.collapsed) {
                range.deleteContents();
            }
            range.insertNode(element);
        },
        updateMetafield(data) {
            if (!this.editorDoc?.body) return;
            this.editorDoc.body.focus();

            if (this._insertRangeBookmark) {
                if (this.isUsableRange(this._insertRangeBookmark)) {
                    this.selection.range = this._insertRangeBookmark;
                }
                this._insertRangeBookmark = null;
            }

            if (this.editSource) {
                // Replacing an existing source: delete the meta node first,
                // deleteSource() also updates selection.range to the insertion point.
                this.deleteSource();
            } else if (this.isUsableRange(this.selection.range)) {
                const insideMeta = this.findMetaEditorWrapper(this.selection.range.startContainer)
                    || this.findMetaEditorWrapper(this.selection.range.endContainer)
                    || this.rangeSelectsMetaEditor(this.selection.range);
                // Never deleteContents inside/on a meta tag — that removes or splits the chip.
                if (!insideMeta) {
                    this.selection.range.deleteContents();
                }
            }
            // Không có range dùng được (chưa click vào editor / vừa đổi element) → chèn vào cuối.
            if (!this.ensureInsertRange()) return;
            this.restoreRange(false);
            this.insertDynamicSourceElement(data);

            // Move cursor to just after the inserted ecom-meta-editor span so that
            // subsequent insertions are placed next to it, not nested inside it.
            if (data && (data as Element).parentNode && this.editorDoc) {
                const range = this.editorDoc.createRange();
                range.setStartAfter(data as Node);
                range.collapse(true);
                const sel = this.editorDoc.getSelection();
                if (sel) {
                    sel.removeAllRanges();
                    sel.addRange(range);
                    this.selection.selection = sel;
                    this.selection.range = range;
                }
            }

            if (this.editorDoc)
                this.editorDoc.body.dispatchEvent(new Event('input'));
            this.editSource = false;
            this._editingMetaNode = null;
            this.highlightMetaNode(null);
        },
        updateHTML(html){
            this.editorDoc.body.innerHTML = html;
            if(this.editorDoc)
                this.editorDoc.body.dispatchEvent(new Event('input'));
        },
        clickEditor(e) {
            this.isfocus = true;
            let target = e.target;
            // With contenteditable="false" on ecom-meta-editor, e.target may be the
            // wrapper itself or the inner ecom-dynamic-meta span.
            const isDynamicTag = e.target && (
                e.target.classList.contains('ecom-dynamic-meta') ||
                e.target.classList.contains('ecom-meta-editor')
            );
            if (isDynamicTag) {
                this.editSource = true;
                // Store a direct reference to the wrapper span and set the selection
                // range around it so deleteSource/updateMetafield can find it reliably.
                const wrapper = e.target.closest('.ecom-meta-editor') ?? (e.target.classList.contains('ecom-meta-editor') ? e.target : null);
                this.highlightMetaNode(wrapper);
                this.revealSourceActions();
                if (wrapper && this.editorDoc) {
                    this._editingMetaNode = wrapper;
                    const range = this.editorDoc.createRange();
                    range.selectNode(wrapper);
                    const sel = this.editorDoc.getSelection();
                    if (sel) {
                        sel.removeAllRanges();
                        sel.addRange(range);
                        this.selection.selection = sel;
                        this.selection.range = range;
                    }
                }
            } else {
                this.editSource = false;
                this._editingMetaNode = null;
                this.highlightMetaNode(null);
                this.ensureCaretPlaceable(e);
            }
            if (this.type < 2) {
                return;
            }

            let elImg = target.closest('img');
            if (elImg) {
                this.selection.image.node = elImg;
                this.metadata.menu = '';
                this.setDataMenu(elImg);
                this.selection.action = 'insertImage';
            }
        },
        switchFormatCode() {
            if(!this.editorDoc?.body) return false;
            if(this.selection.state['codeFormat']) {
                const xmp = this.editorDoc.body.querySelector('xmp');
                if (xmp) {
                    this.editorDoc.body.innerHTML = this.normalizeEditorHtml(xmp.innerHTML);
                }
            } else {
                const xmp = document.createElement('xmp');
                xmp.style.display = 'contents';
                xmp.style.whiteSpace = 'inherit';
                const inner = this.editorDoc.body.innerHTML == "<br>" ? "" : this.editorDoc.body.innerHTML;
                xmp.innerHTML = this.normalizeEditorHtml(inner);
                this.editorDoc.body.innerHTML = '';
                this.editorDoc.body.appendChild(xmp);
            }
        },

        deleteSource() {
            // 1. Prefer the stored reference captured when user clicked on the tag.
            let metaNode = this._editingMetaNode || null;

            // 2. Fallback: walk up the DOM from the current focus node.
            if (!metaNode && this.selection?.selection?.focusNode) {
                let currentNode = this.selection.selection.focusNode;
                while (currentNode && currentNode.nodeName !== 'BODY') {
                    if (currentNode?.classList?.contains('ecom-meta-editor')) {
                        metaNode = currentNode;
                        break;
                    }
                    currentNode = currentNode?.parentNode;
                }
            }

            if (!metaNode?.parentNode) return;

            const parent = metaNode.parentNode;
            // Capture the index before removal so we can position the cursor correctly.
            const siblingIndex = Array.from(parent.childNodes).indexOf(metaNode);
            parent.removeChild(metaNode);
            this._editingMetaNode = null;
            // Node vừa bị xoá khỏi DOM — thả tham chiếu highlight kèm theo.
            this._activeMetaNode = null;
            this.editSource = false;

            // Place a collapsed range at the position where the node was removed.
            if (this.editorDoc) {
                const range = this.editorDoc.createRange();
                const nextSibling = parent.childNodes[siblingIndex];
                if (nextSibling) {
                    range.setStartBefore(nextSibling);
                } else {
                    range.setStart(parent, parent.childNodes.length);
                }
                range.collapse(true);
                const sel = this.editorDoc.getSelection();
                if (sel) {
                    sel.removeAllRanges();
                    sel.addRange(range);
                    this.selection.selection = sel;
                    this.selection.range = range;
                }
                this.editorDoc.body.dispatchEvent(new Event('input'));
            }
        }
    }
  };
  </script>
  <style>
  .editor {
    min-height: 2rem;
    max-height: 15rem;
  }
  .editor[data-type='2'] {
    min-height: 4rem;
  }
  </style>