        javascript(){
            return function(){
                if(!this.$el) return false;
                const $el = this.$el;
                let api_key = this.settings.api_key || null;
                let zoom = this.settings.zoom || 15;
                let script = document.createElement('script');
                let itemLocations = $el.querySelectorAll('.element__address-location-item');
                let map = $el.querySelector(".ecom__element-location");
                let element = $el.querySelector('.element__address-location-item.active');
                let address = "",
                    scroll_top = this.settings.scroll_top ?? 0,
                    scroll_top__tablet = this.settings.scroll_top__tablet ?? 0,
                    scroll_top__mobile = this.settings.scroll_top__mobile ?? 0,
                    multiple = this.settings.multiple || false
                if(element){
                    address = element.dataset.location;
                }
                else{
                    address = 'Ha Noi';
                }
               
                if(!element) return;
                let imageMarker = element.dataset.image ?? null,
                    animation =  element.dataset.animation ?? null,
                    markerContent = element.dataset.markerContent ?? null,
                    name = element.dataset.name ?? null;
                let valueAdd = 0;
                if(window.innerWidth > 1024) {
                    valueAdd = parseInt(scroll_top);
                }
                else if(window.innerWidth <= 1024 && window.innerWidth > 768) {
                    valueAdd = parseInt(scroll_top__tablet);
                }
                else {
                    valueAdd = parseInt(scroll_top__mobile);
                }
                const multipleAddress = [];
                itemLocations.forEach(function(item, index){
                    const result = {
                        location: item.dataset.location,
                        image: item.dataset.image || null,
                        animation: item.dataset.animation,
                        markerContent: item.dataset.markerContent,
                        name: item.dataset.name,
                    }
                    multipleAddress.push(result);
                    item.addEventListener('click', function(){
                        itemLocations.forEach(function(item){
                            item.classList.remove('active');
                        });
                        let animation = item.dataset.animation
                        item.classList.add('active');
                        window.initialize = initialize(item.dataset.location, item.dataset.image,animation, item.dataset.markerContent, item.dataset.name);
                        const rect = map.getBoundingClientRect();
                        if(valueAdd) {
                            window.scrollTo({ behavior: 'smooth', top: rect.top + window.scrollY - valueAdd });
                        }
                        // map.scrollIntoView();
                    });
                });
                function handleAddTitle(infowindow){
                    google.maps.event.addListener(infowindow, 'domready', function() {
                        // 1. Tìm đúng container header của Google
                        const headerContainer = document.querySelector('.gm-style-iw-chr .gm-style-iw-ch');
                        if (headerContainer) {
                            const html = `
                                <div dir="ltr" jstcache="0" style="">
                                    <div jstcache="37" class="transit-container">
                                        <div jstcache="10">
                                            <div jstcache="11" class="gm-title gm-full-width" jsan="7.gm-title,7.gm-full-width">
                                            ${infowindow.title ? infowindow.title : ''}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            `
                            headerContainer.innerHTML = html
                        }
                    });
                }
                function initialize(address, image_marker, animation, marker_content, name){
                    let geocoder = new google.maps.Geocoder();
                    
                    geocoder.geocode( {'address' : address}, async function(results, status) {
                        if (status == google.maps.GeocoderStatus.OK) {
                            let latitude = results[0].geometry.location.lat();
                            let longitude = results[0].geometry.location.lng();
                            let latlng = new google.maps.LatLng(latitude, longitude);
                            let mapOptions = {
                                zoom: zoom,
                                center: latlng
                            }
    
                            const map = new google.maps.Map($el.querySelector(".ecom__element-location"), mapOptions);
                            if(multiple) {
                                let j = 0;
                                for(const address of multipleAddress) {
                                    if(!address.location) continue;
                                    await geocoder.geocode( {'address' : address.location}, function(results, status) {
                                        if (status == google.maps.GeocoderStatus.OK) {
                                            let icon = null
                                            let latitude = results[0].geometry.location.lat();
                                            let longitude = results[0].geometry.location.lng();
                                            if(address.image){
                                                icon = {
                                                    url: address.image, // url
                                                    scaledSize: new google.maps.Size(50, 50), // scaled size
                                                };
                                            }
                                            multipleAddress[j].position = new google.maps.LatLng(latitude, longitude);
                                            multipleAddress[j].icon = icon;
                                            
                                        }
                                    })
                                    j++;
                                }
                                
                                var infowindow = new google.maps.InfoWindow();

                                var marker, i;
                                handleAddTitle(infowindow);
                                for (i = 0; i < multipleAddress.length; i++) {  
                                    const address = multipleAddress[i];
                                    marker = new google.maps.Marker({
                                        position: address.position,
                                        icon: address.icon,
                                        map: map
                                    });
                                    if(address.animation=='true'){
                                        marker.setAnimation(google.maps.Animation.BOUNCE);
                                    }
                                    
                                    google.maps.event.addListener(marker, 'click', (function(marker, i) {
                                        return function() {
                                            infowindow.title = address.name;
                                            infowindow.setContent(address.markerContent || address.location);
                                            infowindow.open(map, marker);
                                        }
                                    })(marker, i));
                                }
                            }
                            else {
                                //IMG
                                let icon = null;
                                if(image_marker){
                                     icon = {
                                        url: image_marker, // url
                                        scaledSize: new google.maps.Size(50, 50), // scaled size
                                    };
                                }
                                const marker = new google.maps.Marker({
                                    position: results[0].geometry.location,
                                    map: map,
                                    icon: icon
                                });
                                if(animation=='true'){
                                    marker.setAnimation(google.maps.Animation.BOUNCE);
                                }
                                let infowindow = new google.maps.InfoWindow({
                                    content: marker_content || address,
                                    maxWidth: 200,
                                });
                                marker.setMap(map);
                                marker.addListener('click', ()=>{
                                    infowindow.title = name;
                                    infowindow.open({
                                        anchor: marker,
                                        map,
                                    });
                                })
                                map.addListener('zoom_changed', ()=>{
                                    map.setCenter(latlng);
                                    map.panTo(latlng);
                                });
                                handleAddTitle(infowindow);
                            }
                        }
                    });
                }
                setTimeout(()=>window.initialize = initialize(address,imageMarker, animation, markerContent, name),1000);
               
                if(api_key){
                    script.src = `https://maps.googleapis.com/maps/api/js?key=${api_key}&callback=initialize`;
                    script.id = 'ecom__location-map--api_key';
                    const _script = document.getElementById('ecom__location-map--api_key');
                    if(_script){
                        document.head.removeChild(_script);
                    }
                    document.head.appendChild(script);
                }
                
            }
        },
