<script lang="ts">
import { GridItem, GridLayout } from "@/plugins/vue-grid-layout/index";
import { defineAsyncComponent } from "vue";
import LoadingComponent from "../Loading.vue";
import { Core, Element } from "@/mixins";
import GroupWrapper from "../GroupWrapper.vue";
import {
    EditMajor,
    MobilePlusMajor,
    DeleteMajor,
    ArrowUpMinor,
    ArrowDownMinor,
    SectionMajor,
    ecPlus,
    backIcon,
    resize_section,
    CirclePlusMajor,
    sangIcon,
    autoLayoutIcon,
    ChecklistMajor,
    CancelMajor,
    tickIcon,
    xIcon
} from "@/assets/icons";
import {
    cloneLayout,
    ensureNumericValue,
    widthPxCalculate,
    isPercentWidth,
    handleSetHistorySelection
} from "@/plugins/vue-grid-layout/helpers/utils";
import { gridDebug } from "@/plugins/vue-grid-layout/helpers/debug";
import { getIdParentAndIndex } from "@/utils/helpers";
import {
    AutoLayoutHelper,
    HeightManager,
    LayoutChangeApplicator,
    AutoLayoutStateManager,
    AUTO_LAYOUT_PRESETS,
    MobileLayoutOptimizer,
    EnhancedAutoLayoutHelper,
    GroupAwareAutoLayoutHelper,
    type GroupAwareAutoLayoutResult,
    type AutoLayoutConfig,
    type HeightPreview
} from "@/plugins/vue-grid-layout/helpers";

import { getOptionsGrid, elementIframe } from "../configElement"; // config element in grid layout
import { ResizeHandler } from "./ResizeHandler";
import type { ResizeOptions, ResizeEvents } from "./types";
import { GridConfig } from "./GridConfig.js";

export default {
    name: "Grid",
    inject: ["instanceStore", "eventBus"],
    mixins: [Core, Element],
    components: {
        GridItem,
        GridLayout,
        GroupWrapper,
        BlockGridElement: defineAsyncComponent({
            loader: () => import("../BlockGrid.vue"),
            loadingComponent: LoadingComponent,
            delay: 0,
            timeout: 60000
        }),
        BlockElement: defineAsyncComponent({
            loader: () => import("../Block.vue"),
            loadingComponent: LoadingComponent,
            delay: 0,
            timeout: 60000
        }),
    },
    props: {
        data: {
            type: Object,
            default() {
                return {
                    blocks: [],
                    settings: {}
                };
            }
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        }
    },
    data: function () {
        return {
            isSelection: false,
            layout: [],
            _blockCache: new Map(),
            _cachedGroupedBlockIds: new Map(),
            _lastGroupUpdate: "",
            _xyCache: {},
            draggable: true,
            resizable: true,
            mirrored: false,
            responsive: true,
            preventCollision: false,
            compact: false,
            rowHeight: 1,
            colNum: 1200,
            marginX: 0,
            marginY: 0,
            breakpoints: { lg: 1024, md: 767, sm: 0 },
            cols: { lg: 1200, md: 1024, sm: 767 },
            screens: {
                desktop: "lg",
                tablet: "md",
                mobile: "sm"
            },
            over: false,
            is: "grid",
            mouse: {
                x: 0,
                y: 0
            },
            moving: false,
            icons: {
                EditMajor,
                MobilePlusMajor,
                DeleteMajor,
                ArrowUpMinor,
                ArrowDownMinor,
                SectionMajor,
                ecPlus,
                backIcon,
                resize_section,
                CirclePlusMajor,
                sangIcon,
                autoLayoutIcon,
                ChecklistMajor,
                CancelMajor,
                tickIcon,
                xIcon
            },
            shouldApplyMarginBottom: false,
            tempBlock: null,
            rotating: false,
            justDragged: false,
            resizeHandler: null as ResizeHandler | null,
            tempIdBlock: null,
            isUpdatingLayout: false,
            differenceMouseItem: null,
            gridContainerWidth: 1200,
            scaleRatio: 1,
            sectionResizeObserver: null as ResizeObserver | null,

            // Simplified auto layout state - sử dụng StateManager thay vì local state
            isAutoLayoutProcessing: false,
            isAutoLayoutPreviewing: false,
            groupLayoutPreview: null,
            nonGroupLayoutPreview: null,
            // Auto layout settings có thể để trong component hoặc move ra ngoài
            autoLayoutSettings: {
                preset: "NORMAL",
                enableAnimation: true,
                enablePerformanceTracking: true,
                enableMobileCentering: true,
                mobileBreakpoint: 768,
                fullWidthItemsSpacing: null,
                enableHeightUpdate: true
            },
            justSelected: false,
            sectionIdOld: ""
        };
    },
    mounted() {
        if (this.$refs.video && this.data?.settings?.autoplay) {
            this.$refs.video.setAttribute("muted", "");
        }
        if (this.exporting === false) {
            //this.stacks[this.data.id] = this;
            this.instanceStore.register(this.data.id, this);
        }

        this.layout = this.data.blocks.map((block) => {
            let l = this.getScreenLayout(block, this.screen);
            l.i = block.id;
            l.group = block.group || elementIframe.includes(block.name) ? true : false;
            l.options = getOptionsGrid(block)?.options;
            l.inGroup = block.group_id || false;

            return l;
        });

        if (this.exporting) return;

        this.initializeResizeHandler();

        // Setup ResizeObserver to watch section width changes
        this.$nextTick(() => {
            const observedElement = this.$refs?.grid?.$refs?.item || this.$el;
            if (observedElement) {
                this.sectionResizeObserver = new ResizeObserver((entries) => {
                    for (const entry of entries) {
                        const newWidth = this.getActualGridLayoutWidth();
                        if (newWidth && this.gridContainerWidth !== newWidth) {
                            this.gridContainerWidth = newWidth;
                        }
                    }
                });
                this.sectionResizeObserver.observe(observedElement);

                // Initial width update
                const initialWidth = this.getActualGridLayoutWidth();
                if (initialWidth) {
                    this.gridContainerWidth = initialWidth;
                }
            }

            this.eventBus.emit("layout-mounted", {
                width: this.getActualGridLayoutWidth()
            });
        });

        setTimeout(() => {
            window.dispatchEvent(new Event("resize"));
            this.eventBus.emit("layout-mounted", {
                width: this.$refs.grid?.width
            });
        }, 50);

        this.eventBus.on("refresh-grid", ({ sectionId }) => {
            if (sectionId !== this.data.id) return;
            // ✅ 1. FORCE CLEAR ALL CACHES
            this._blockCache = new Map();
            this._cachedGroupedBlockIds = new Map();
            this._lastGroupUpdate = "";
            this._xyCache = {};

            // ✅ 2. REBUILD LAYOUT FROM BLOCKS (CRITICAL)
            this.rebuildLayoutFromBlocks();

            // ✅ 3. FORCE VUE REACTIVITY
            this.$forceUpdate();

            // ✅ 4. WAIT FOR DOM UPDATE, THEN FORCE GRID UPDATE
            this.$nextTick(() => {
                // Force grid layout component update
                if (this.$refs.grid) {
                    this.$refs.grid.$forceUpdate();

                    // Trigger grid internal refresh
                    this.$refs.grid.updateHeight?.();
                    this.$refs.grid.resizeEvent?.();
                }
            });
        });

        this.eventBus.on("update-grid-layout", ({ sectionId, blocks }) => {
            if (sectionId === this.data.id) {
                // Cập nhật blocks
                this.data.blocks = blocks;

                // Cập nhật layout
                this.layout = blocks.map((block) => {
                    let l = this.getScreenLayout(block, this.screen);
                    l.i = block.id;
                    l.options = l.layouts?.options ?? getOptionsGrid(block)?.options;
                    l.visibility = block.visibility || undefined;
                    l.group = block.group || elementIframe.includes(block.name) ? true : false;
                    l.inGroup = block.group_id || false;
                    return l;
                });

                // Clear block cache
                this._blockCache = new Map();

                // Force grid re-render
                this.$nextTick(() => {
                    this.$refs.grid?.$forceUpdate();
                    this.eventBus.emit("layout-updated");
                });
            }
        });
        this.eventBus.on("remove-item", (id: string) => {
            const index = this.layout.map((item) => item.i).indexOf(id);
            if (index !== -1) {
                this.layout.splice(index, 1);
            }
        });
        this.eventBus.on("difference-mouse-item", (data) => {
            this.differenceMouseItem = data;
        });

        this.eventBus.on("updateWidth", this.updateWidthHandler);
        document.addEventListener("keydown", this.handleAutoLayoutKeyboard);
        this.idoc().addEventListener("keydown", this.handleAutoLayoutKeyboard);
    },
    beforeUnmount() {
        this.eventBus.off("update-grid-layout");
        this.eventBus.off("refresh-grid");
        this.eventBus.off("difference-mouse-item");
        this.eventBus.off("updateWidth", this.updateWidthHandler);
        document.removeEventListener("keydown", this.handleAutoLayoutKeyboard);
        this.idoc().removeEventListener("keydown", this.handleAutoLayoutKeyboard);

        if (this.resizeHandler) {
            this.resizeHandler.destroy();
            this.resizeHandler = null;
        }

        // Cleanup ResizeObserver
        if (this.sectionResizeObserver) {
            this.sectionResizeObserver.disconnect();
            this.sectionResizeObserver = null;
        }
    },
    computed: {
        isActiveGroup() {
            return this.$store.getters["builder/activeGroup"];
        },
        isResizing() {
            return this.resizeHandler ? this.resizeHandler.isCurrentlyResizing() : false;
        },

        isBoxed(): boolean {
            return (
                this.data.settings["content-width"] === "boxed" ||
                this.data.settings["content-width"] === undefined
            );
        },
        video_url(): string {
            let source = this.data?.settings?.source;
            if (!["upload", "external"].includes(source)) {
                return "";
            }
            if (source === "upload") {
                return this.data?.settings.video?.value ?? "";
            }
            return this.data?.settings?.url ?? "";
        },
        show_video_background(): boolean {
            return (
                ["upload", "external", "youtube", "vimeo"].includes(this.data.settings?.source) &&
                this.hasVideoLink
            );
        },
        hasVideoLink(): string | undefined {
            let source = this.data?.settings?.source || null;
            switch (source) {
                case "upload":
                    return this.data?.settings.video?.value;
                case "external":
                    return this.data?.settings?.url;
                case "youtube":
                    return this.data?.settings.srcYoutube;
                default:
                    return this.data?.settings.srcVimeo;
            }
        },
        // canResizeHeight(): boolean {
        //     return (
        //         (this.screen === "desktop" && this.data?.settings?.height === "fixed") ||
        //         (this.screen === "tablet" && this.data?.settings?.height === "fixed__tablet") ||
        //         (this.screen === "mobile" && this.data?.settings?.height === "fixed__mobile")
        //     );
        // },
        linkYoutube() {
            if (this.data?.settings?.srcYoutube) {
                const regExpYt = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
                let val = this.data?.settings?.srcYoutube.match(regExpYt);
                let videoIdYt = val && val[2].length === 11 ? val[2] : null;
                return `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3?${
                    this.data?.settings?.start_time
                        ? "&start=" + this.data?.settings?.start_time
                        : ""
                }${
                    this.data?.settings?.end_time ? "&end=" + this.data?.settings?.end_time : ""
                }&controls=0&mute=${
                    this.data?.settings?.muted ? 1 : 0
                }&showinfo=0&iv_load_policy=3&playlist=${videoIdYt}&autoplay=${
                    this.data?.settings?.autoplay ? 1 : 0
                }&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },
        linkVimeo() {
            if (this.data?.settings?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.data?.settings?.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?controls=0&autoplay=${
                    this.data?.settings?.autoplay ? 1 : 0
                }&muted=${this.data?.settings?.muted || this.data?.settings?.autoplay ? 1 : 0}${
                    this.data?.settings?.start_time
                        ? "&byline=1#t=00h00m" + this.data?.settings?.start_time + "ss"
                        : ""
                }&showinfo=0&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
