            }
        },
        locked() {
            return this.$store.getters["builder/editorConfigs"]?.locked;
        },
        sections() {
            return this.$parent.sections;
        },
        params() {
            return this.$store.getters["page/params"];
        },
        gridAttrs() {
            // SR wins over Entrance Animation on the same node (priority: SR > Entrance)
            // Only top-level Grid section — not nested/inner grids.
            // srPreview lets the builder canvas emit the same attrs as export.
            const hasSR = (this.exporting === true || this.srPreview) && this.deep === 1 && !!(
                this.data?.settings?.scroll_reveal || this.$store.getters['page/settings']?.scroll_reveal
            );
            const attrs = {
                ref: "wrapper",
                style: { zIndex: this.exporting ? "inherit" : this.isActive ? 3 : 1 },
                class: {
                    "ecom-animated": !this.exporting,
                    "ecom-animation": !hasSR && this.data?.advanced?.animation_type,
                    "ecom-section ecom-row ecom-core": true,
                    "ecom-previewing-section": this.isAutoLayoutPreviewing,
                    drop__placeholder: this.isDropTo,
                    drag__placeholder: this.isDragMe,
                    core__block: this.deep > 1,
                    "ecom-grid-no-block": !this.layout.length && !this.exporting,
                    ...this.classes
                },
                "data-id": this.section_id,
                ...this.attributes
            };

            if (this.scrollingAnimation) {
                attrs["ecom-scrolling-animation"] = this.scrollingAnimation;
            }

            if (hasSR) {
                const sectionSR = this.data?.settings?.scroll_reveal;
                const src = sectionSR ? this.data.settings : this.$store.getters['page/settings'];
                attrs['data-ec-sr']       = src.scroll_reveal_type  || 'fade-up';
                attrs['data-ec-sr-delay'] = String(src.scroll_reveal_delay || 100);
            }

            if (!hasSR && this.data?.advanced?.animation_delay) {
                const delayValue = this.data.advanced.animation_delay.toString().replace(/ms$/, '');
                attrs["ec-delay"] = delayValue || 0;
            }

            return attrs;
        },
        screen: function () {
            return this.$store.getters["builder/screen"];
        },
        section_id() {
            return this.data.id;
        },
        canDrop() {
            if (this.dragCurrent?.data?.isLibrarySection) {
                return false;
