        },
        isCurrentDrop() {
            return this.dropTo === this;
        },
        isDragging() {
            return this.$store.getters["builder/isDragging"];
        },
        // Lấy tất cả block ids đã được group
        groupedBlockIds: {
            cache: true,
            get() {
                if (!this.data.groups) return new Set();

                if (
                    this._cachedGroupedBlockIds &&
                    this._lastGroupUpdate === JSON.stringify(this.data.groups)
                ) {
                    return this._cachedGroupedBlockIds;
                }

                this._lastGroupUpdate = JSON.stringify(this.data.groups);

                const allBlockIds = Object.values(this.data.groups).reduce((acc, group) => {
                    // Kiểm tra nếu group và group.blocks tồn tại và là mảng
                    if (group && Array.isArray(group.blocks)) {
                        return [...acc, ...group.blocks];
                    }
                    return acc;
                }, []);

                this._cachedGroupedBlockIds = new Set(allBlockIds);
                return this._cachedGroupedBlockIds;
            }
        },

        ungroupedBlocks() {
            return this.data.blocks.filter((block) => !this.groupedBlockIds.has(block.id));
        },
        isEditing() {
            return this.editingElement?.data?.id === this.section_id;
        },
        isFirst() {
            return this.index == 0;
        },

        isLast() {
            return (
                this?.$parent?.visibleSections &&
                this.index == this?.$parent?.visibleSections?.length - 1
            );
        },
        isActive() {
            return !this.exporting && !this.isFullScreen && this.over && !this.dragCurrent;
        },
        isActiveSettings() {
            return (
                (!this.exporting &&
                    !this.isFullScreen &&
                    (this.over || this.isEditing) &&
                    this.dragCurrent !== this) ||
                this.isAutoLayoutPreviewing
            );
        },
        classSectionActive() {
            if (this.editingElement) {
                const sections = this.sections.filter((section) => section.visibility);
                const index = sections.findIndex(
                    (section) => section.id === this.editingElement?.data?.id
                );
                if (index === -1) return "";
                if (this.index - index == 1) {
                    return ["ecom-section-below"];
                } else if (this.index - index == -1) {
                    return ["ecom-section-above"];
                }
                return "";
            }
        },
        gridConfigContext() {
            return {
                $t: this.$t,
                isBoxed: this.isBoxed,
                hasVideoLink: this.hasVideoLink,
                show_video_background: this.show_video_background,
                // SR settings only for top-level Grid sections
                isTopLevelSection: this.deep === 1
            };
        },

        // ✅ GridConfig instance với automatic caching
        gridConfigInstance() {
            return new GridConfig(this.gridConfigContext);
