        isMobileScreen() {
            return MobileLayoutOptimizer.isMobileLayout(this.screen, this.gridContainerWidth);
        },

        currentAutoLayoutPreset() {
            if (this.isMobileScreen) {
                const hasFullWidthItems = this.hasFullWidthItemsInLayout();
                return MobileLayoutOptimizer.createMobilePreset(
                    this.gridContainerWidth,
                    hasFullWidthItems
                );
            }
            return (
                AUTO_LAYOUT_PRESETS[this.autoLayoutSettings.preset] || AUTO_LAYOUT_PRESETS.NORMAL
            );
        }
    },
    watch: {
        screen: function (newScreen, oldScreen) {
            if (this.isAutoLayoutPreviewing) {
                this.cancelAutoLayoutPreview();
            }

            gridDebug("grid", "screen:rebuild-layout:start", {
                sectionId: this.section_id,
                fromScreen: oldScreen,
                toScreen: newScreen,
                currentContainerWidth: this.gridContainerWidth,
                blockCount: this.data.blocks.length
            }, this as any);

            // Lấy mobile screen width để so sánh
            const mobileWidth = 380;

            const newLayout = [];
            this.data.blocks.forEach((block) => {
                const layoutItem = {};
                layoutItem.i = block.id;
                layoutItem.group = block.group || elementIframe.includes(block.name) ? true : false;
                layoutItem.inGroup = block.group_id || false;

                // Đảm bảo layouts đã được khởi tạo
                if (!block.layouts) {
                    block.layouts = {
                        desktop: {}
                    };
                }

                // Lấy cả desktop layout và current screen layout
                const desktopLayout = block.layouts.desktop || {};
                const screenLayout = block.layouts[newScreen] || {};

                // Xử lý đặc biệt cho mobile: auto-adjust width nếu cần
                let shouldAdjustForMobile = false;
                if (newScreen === "mobile") {
                    shouldAdjustForMobile = this.shouldAdjustWidthForMobile(
                        screenLayout,
                        desktopLayout,
                        mobileWidth
                    );
                }

                // Xử lý từng thuộc tính riêng biệt với logic fallback
                // 1. Kiểm tra trong screen hiện tại trước
                // 2. Nếu không có, fallback về desktop
                // 3. Nếu vẫn không có, sử dụng giá trị mặc định

                // Xử lý left
                layoutItem.left =
                    screenLayout.left !== undefined && screenLayout.left !== null // fix trường hợp left = null
                        ? screenLayout.left
                        : desktopLayout.left !== undefined
                        ? desktopLayout.left
                        : 0;

                // Xử lý top (giữ nguyên logic fallback)
                layoutItem.top =
                    screenLayout.top !== undefined
                        ? screenLayout.top
                        : desktopLayout.top !== undefined
                        ? desktopLayout.top
                        : 0;

                // Xử lý width
                layoutItem.width =
                    screenLayout.width !== undefined
                        ? screenLayout.width
                        : desktopLayout.width !== undefined
                        ? desktopLayout.width
                        : 100;

                // Điều chỉnh đặc biệt cho mobile sau khi đã có giá trị fallback
                if (shouldAdjustForMobile) {
                    layoutItem.width = "100%";
                    layoutItem.left = 0;

                    // Chỉ cập nhật width và left vào mobile layout khi cần thiết
                    if (!block.layouts[newScreen]) {
                        block.layouts[newScreen] = {};
                    }
                    block.layouts[newScreen].width = "100%";
                    block.layouts[newScreen].left = 0;
                }

                // Xử lý height
                layoutItem.height =
                    screenLayout.height !== undefined
                        ? screenLayout.height
                        : desktopLayout.height !== undefined
                        ? desktopLayout.height
                        : 50;

                // Xử lý rotation
                layoutItem.rotation =
                    screenLayout.rotation !== undefined ? screenLayout.rotation : 0;

                // Xử lý zindex
                layoutItem.zindex =
                    screenLayout.zindex !== undefined
                        ? screenLayout.zindex
                        : desktopLayout.zindex !== undefined
                        ? desktopLayout.zindex
                        : "";

                // Xử lý locked
                layoutItem.locked = screenLayout.locked !== undefined ? screenLayout.locked : false;

                // Options thường chỉ có một bộ
                layoutItem.options = getOptionsGrid(block)?.options || {};

                // Thêm vào layout mới
                newLayout.push(layoutItem);
            });

            // Gán layout mới
            this.layout = newLayout;
            const gridElement = this.$refs.grid.$refs?.item;
            this.gridContainerWidth =
                gridElement.offsetWidth || this.gridContainerWidth;
            gridDebug("grid", "screen:rebuild-layout:end", {
                sectionId: this.section_id,
                fromScreen: oldScreen,
                toScreen: newScreen,
                gridContainerWidth: this.gridContainerWidth,
                layoutSnapshot: newLayout.map((item) => ({
                    i: item.i,
                    left: item.left,
                    top: item.top,
                    width: item.width,
                    height: item.height,
                    rotation: item.rotation,
                    zindex: item.zindex,
                    locked: item.locked
                }))
            }, this as any);
            if (!this.data.settings["min-height"] && newScreen != "desktop") {
                setTimeout(() => {
                    gridElement.style.height = ``;
                }, 100);
            }
        },
        layout: {
            handler(newLayout) {
                //console.trace("Layout changed:", JSON.parse(JSON.stringify(this.layout)));
            },
            deep: true
        },
        "data.blocks": {
            handler(newBlocks) {
                //console.trace("Blocks changed:", JSON.parse(JSON.stringify(newBlocks)));
            },
            deep: true
        },
        moving: {
            handler(newVal) {
                // Add z-index for form
                const form = this.$el.closest(".ecom-row.ecom-cart-form");
                if (form) {
                    if (newVal) {
                        form.classList.add("ecom-moving");
                    } else {
                        form.classList.remove("ecom-moving");
                    }
                }
            }
        },
        "data.settings.autoplay": {
            deep: false,
            handler(autoplay) {
                if (this.$refs.video) {
                    if (autoplay) {
                        this.$refs.video.load();
                        this.$refs.video.setAttribute("muted", "");
                    } else {
                        this.$refs.video.pause();
                        this.$refs.video.removeAttribute("muted");
                    }
                }
            }
        }
    },
    methods: {
        getActualGridLayoutWidth() {
            const gridRef = this.$refs?.grid;
            const gridElement = gridRef?.$refs?.item;
            if (gridElement?.offsetWidth) {
                return gridElement.offsetWidth;
            }

            const fallbackGrid = this.$el?.querySelector?.(".ecom-grid-layout");
            if (fallbackGrid?.offsetWidth) {
                return fallbackGrid.offsetWidth;
            }

            return this.$el?.offsetWidth || this.gridContainerWidth;
        },

        initializeResizeHandler() {
            const options: ResizeOptions = {
                enableResize: true,
                minHeight: 100,
                realTimeUpdate: true
            };

            const events: ResizeEvents = {
                onResizeStart: (data) => {},
                onResize: (data) => {
                    // Handle resize progress if needed
                },
                onResizeEnd: (data) => {}
            };

            this.resizeHandler = new ResizeHandler(this, options, events);
        },
        handleGroupZIndexed(groupId, newZIndex) {
            // Cập nhật group data khi GroupWrapper emit event
            const section = this.sections.find((s) => s.id === this.sectionId);
            if (section && section.groups && section.groups[groupId]) {
                section.groups[groupId].zIndex = newZIndex;
            }
        },
        placehover(e) {
            if (this.isFullScreen || !this.canDrop || !this.isDragging) {
                return;
            }
            let pos = e.target.classList.contains("placeholder__top") ? "top" : "bottom";
            this.$store.commit("builder/setDropTo", this);
            this.$store.commit("builder/setDropPos", pos);
            this.placeholder = pos;
        },
        updateSelectionStatusEvent(status) {
            this.isSelection = status;
        },
        updateWidthHandler(width) {
            if (width.section_id && width.section_id != this.data.id) return;
            this.gridContainerWidth = width.width;
        },

        setDragEnded(value) {
            this.justDragged = value;
        },

        createStyle() {
            if (this.$refs?.wrapper) {
                this.$helpers.addStyle2Component(this.$refs?.wrapper, this.data);
            }
        },

        edit() {
            this.editRow();
        },
        toggleSectionWidth() {
            if (
                this.data.settings["content-width"] === "boxed" ||
                this.data.settings["content-width"] === undefined
            ) {
                this.data.settings["content-width"] = "full";
            } else {
                this.data.settings["content-width"] = "boxed";
            }
        },

        updateScaleRatioEvent(val) {
            this.scaleRatio = val;
        },

        // =============================================================================
        // LAYOUT UPDATE METHODS
        // =============================================================================
        layoutUpdatedEvent: function (newLayout) {
            if (this.isUpdatingLayout) {
                return;
            }
            this._blockCache = new Map();

            this.isUpdatingLayout = true;

            try {
                newLayout.forEach((updatedItem) => {
                    const existingIndex = this.layout.findIndex((item) => item.i === updatedItem.i);
                    if (existingIndex !== -1) {
                        this.layout[existingIndex] = { ...updatedItem };

                        const blockIndex = this.data.blocks.findIndex(
                            (block) => block.id === updatedItem.i
                        );
                        if (blockIndex !== -1) {
                            if (!this.data.blocks[blockIndex].layouts[this.screen]) {
                                this.data.blocks[blockIndex].layouts[this.screen] = {};
                            }
                            this.data.blocks[blockIndex].layouts[this.screen] = {
                                ...this.data.blocks[blockIndex].layouts[this.screen],
                                left: updatedItem.left,
                                top: updatedItem.top,
                                width: updatedItem.width,
                                height: updatedItem.height,
                                rotation: updatedItem.rotation,
                                center: updatedItem.center
                            };
                        }
                    }
                });
            } finally {
                setTimeout(() => {
                    this.isUpdatingLayout = false;
                }, 50);
            }

            this.$nextTick(() => {
                if (this.$refs.grid) {
                    this.$refs.grid.originalLayout = cloneLayout(newLayout);
                }
            });
        },
        shouldAdjustWidthForMobile(screenLayout, desktopLayout, mobileWidth) {
            // Kiểm tra nếu screen layout chưa có width (mobile chưa được set)
            const hasNoMobileWidth = screenLayout.width === undefined;

            if (!hasNoMobileWidth) {
                return false; // Đã có mobile width, không cần điều chỉnh
            }

            // Lấy width hiện tại (từ desktop hoặc tablet)
            let currentWidth = desktopLayout.width;

            // Nếu desktop width là undefined, sử dụng default
            if (currentWidth === undefined) {
                return false; // Không có width để so sánh
            }

            // Kiểm tra nếu width hiện tại là px và lớn hơn mobile width
            if (this.isPixelWidth(currentWidth)) {
                const widthInPx = this.extractPixelValue(currentWidth);
                return widthInPx > mobileWidth;
            }

            // Nếu width hiện tại là % và >= 80%, cũng điều chỉnh
            if (this.isPercentWidth(currentWidth)) {
                const widthInPercent = this.extractPercentValue(currentWidth);
                return widthInPercent >= 80;
            }

            // Nếu width hiện tại là số (không có đơn vị, coi như px)
            if (typeof currentWidth === "number") {
                return currentWidth > mobileWidth;
            }

            return false;
        },

        /**
         * Kiểm tra xem width có phải là pixel không
         */
        isPixelWidth(width) {
            return typeof width === "string" && width.includes("px");
        },

        /**
         * Kiểm tra xem width có phải là phần trăm không
         */
        isPercentWidth(width) {
            return typeof width === "string" && width.includes("%");
        },

        /**
         * Lấy giá trị pixel từ string
         */
        extractPixelValue(width) {
            if (typeof width === "string" && width.includes("px")) {
                return parseFloat(width.replace("px", ""));
            }
            return 0;
        },

        /**
         * Lấy giá trị phần trăm từ string
         */
        extractPercentValue(width) {
            if (typeof width === "string" && width.includes("%")) {
                return parseFloat(width.replace("%", ""));
            }
            return 0;
        },
        /**
         * Make Auto Layout Preview với Group Support - ENHANCED
         */
        async makeAutoLayoutPreview() {
            if (this.isAutoLayoutPreviewing) {
                return;
            }

            try {
                this.isAutoLayoutProcessing = true;
                this.$el.classList.add("auto-layout-processing");

                // Tạo config
                const config = AutoLayoutHelper.createScreenOptimizedConfig(
                    this.gridContainerWidth,
                    this.screen,
                    {
                        ...this.currentAutoLayoutPreset,
                        centerSingleItemsOnMobile: this.autoLayoutSettings.enableMobileCentering,
                        mobileWidthThreshold: this.autoLayoutSettings.mobileBreakpoint,
                        enableFullWidthOptimization: true,
                        fullWidthItemsSpacing:
                            this.autoLayoutSettings.fullWidthItemsSpacing ||
                            this.currentAutoLayoutPreset.fullWidthItemsSpacing
                    }
                );

                // ✅ SỬA: Sử dụng Group-Aware Auto Layout Helper
                console.log("🎯 Starting Group-Aware Auto Layout Preview...");

                // Log debug info
                GroupAwareAutoLayoutHelper.logProcessingUnitsInfo(
                    GroupAwareAutoLayoutHelper.convertToProcessingUnits(
                        this.data.blocks,
                        this.data.groups || {},
                        this.getScreenLayout.bind(this),
                        config.screen,
                        config.gridContainerWidth
                    ),
                    config
                );

                // Save original state before preview
                this.saveOriginalStateForPreview();

                // Process group-aware auto layout
                const result = GroupAwareAutoLayoutHelper.processGroupAwareAutoLayout(
                    this.data.blocks,
                    this.data.groups || {},
                    this.getScreenLayout.bind(this),
                    config
                );

                if (result.itemChanges.size > 0 || result.groupChanges.size > 0) {
                    this.isAutoLayoutPreviewing = true;

                    // Lưu kết quả preview
                    this.groupLayoutPreview = result.groupChanges;
                    this.nonGroupLayoutPreview = result.itemChanges;

                    // Apply preview changes
                    await this.applyGroupAwarePreviewChanges(result);

                    // Process height preview if needed
                    if (result.maxBottomPosition && this.autoLayoutSettings.enableHeightUpdate) {
                        const heightManager = HeightManager.getInstance();
                        const isMobileScreen =
                            config.screen === "mobile" ||
                            config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

                        const heightPreview = heightManager.updateHeightAfterAutoLayout(
                            result.maxBottomPosition,
                            this.data.settings,
                            config.screen,
                            this.$refs.grid?.$refs?.item,
                            isMobileScreen,
                            this.autoLayoutSettings.enableHeightUpdate,
                            true // isPreview = true
                        );

                        if (heightPreview) {
                            const stateManager = AutoLayoutStateManager.getInstance();
                            stateManager.setHeightPreview(heightPreview);
                        }
                    }

                    console.log("✅ Group-aware auto layout preview completed:", {
                        itemChanges: result.itemChanges.size,
                        groupChanges: result.groupChanges.size,
                        fullWidthUnits: result.fullWidthUnits.size
                    });
                } else {
                    console.log("⚠️ No changes needed for auto layout");
                    this.finishAutoLayoutPreview();
                }
            } catch (error) {
                console.error("❌ Group-aware auto layout preview failed:", error);
                this.finishAutoLayoutPreview();
            } finally {
                this.isAutoLayoutProcessing = false;
                this.$el.classList.remove("auto-layout-processing");
            }
        },

        /**
         * Confirm Auto Layout - Sử dụng Helper Classes
         */
        async confirmAutoLayout() {
            if (!this.isAutoLayoutPreviewing) {
                return;
            }

            try {
                console.log("🎯 Confirming Group-Aware Auto Layout...");

                // ✅ Xử lý Group Changes
                if (this.groupLayoutPreview && this.groupLayoutPreview.size > 0) {
                    console.log(`📦 Processing ${this.groupLayoutPreview.size} group changes...`);

                    for (const [groupId, groupLayoutChange] of this.groupLayoutPreview) {
                        console.log(`📦 Confirmed group ${groupId} changes:`, groupLayoutChange);

                        // Cập nhật group bounds nếu cần
                        if (this.data.groups && this.data.groups[groupId]) {
                            // Group bounds sẽ được cập nhật thông qua item movements
                            await this.updateGroupBoundsAfterAutoLayout(groupId);
                        }
                    }
                }

                // ✅ Xử lý Individual Item Changes (bao gồm cả items trong group đã được di chuyển)
                if (this.nonGroupLayoutPreview && this.nonGroupLayoutPreview.size > 0) {
                    console.log(`📋 Processing ${this.nonGroupLayoutPreview.size} item changes...`);

                    for (const [itemId, changes] of this.nonGroupLayoutPreview) {
                        const block = this.data.blocks.find((b) => b.id === itemId);
                        if (block) {
                            // Kiểm tra xem item có phải full-width không
                            const isFullWidth = this.isItemFullWidthInPreview(itemId);

                            // ✅ Cập nhật layout của item với enhanced method
                            this.updateItemLayoutEnhanced(
                                { id: itemId, block },
                                this.screen,
                                changes,
                                isFullWidth,
                                false // isPreview = false (confirm mode)
                            );

                            console.log(`   📋 Confirmed item ${itemId} changes:`, changes);
                        }
                    }
                }

                // ✅ Confirm height changes nếu có
                const stateManager = AutoLayoutStateManager.getInstance();
                const state = stateManager.getState();

                if (state.heightPreview && this.autoLayoutSettings.enableHeightUpdate) {
                    const heightManager = HeightManager.getInstance();
                    heightManager.confirmHeightUpdate(
                        state.heightPreview,
                        this.data.settings,
                        this.$refs.grid?.$refs?.item
                    );
                    console.log("📏 Confirmed height changes");
                }

                // ✅ Add to history
                let payload = {
                    type: "section",
                    data: this.sections.find((s) => s.id == this.section_id),
                    section_id: this.section_id,
                    action: "group_aware_auto_layout"
                };
                this.$store.dispatch("history/addStack", payload);

                // ✅ Emit layout update
                this.eventBus.emit("layout-updated");

                console.log("✅ Group-aware auto layout confirmed successfully");
            } catch (error) {
                console.error("❌ Failed to confirm group-aware auto layout:", error);
            } finally {
                this.finishAutoLayoutPreview();
            }
        },

        // THÊM method mới để apply preview changes:
        /**
         * Apply Group-Aware Preview Changes
         */
        async applyGroupAwarePreviewChanges(result) {
            console.log("🔄 Applying group-aware preview changes...");

            // 1. Apply individual item changes (bao gồm cả items trong group)
            if (result.itemChanges && result.itemChanges.size > 0) {
                for (const [itemId, changes] of result.itemChanges) {
                    const block = this.data.blocks.find((b) => b.id === itemId);
                    if (block) {
                        const isFullWidth = result.fullWidthUnits.has(itemId);

                        // Apply preview với isPreview = true
                        this.updateItemLayoutEnhanced(
                            { id: itemId, block },
                            this.screen,
                            changes,
                            isFullWidth,
                            true // isPreview = true
                        );
                    }
                }
            }

            // 2. Update group bounds cho các groups đã được di chuyển
            if (result.groupChanges && result.groupChanges.size > 0) {
                for (const [groupId] of result.groupChanges) {
                    // Group bounds sẽ được tự động update thông qua item movements
                    console.log(`📦 Preview applied for group ${groupId}`);
                }
            }

            // 3. Emit layout updated
            this.eventBus.emit("layout-updated");

            console.log("✅ Group-aware preview changes applied");
        },

        // THÊM helper method:
        /**
         * Kiểm tra item có phải full-width trong preview không
         */
        isItemFullWidthInPreview(itemId) {
            // Kiểm tra trong các preview states
            if (this.nonGroupLayoutPreview && this.nonGroupLayoutPreview.has(itemId)) {
                const changes = this.nonGroupLayoutPreview.get(itemId);

                // Nếu width được set thành "100%" hoặc left = 0 với width lớn
                if (
                    changes.width === "100%" ||
                    (changes.left === 0 &&
                        (changes.width === "100%" ||
                            (typeof changes.width === "number" &&
                                changes.width >= this.gridContainerWidth * 0.98)))
                ) {
                    return true;
                }
            }

            return false;
        },

        /**
         * Cancel Auto Layout Preview - Sử dụng Helper Classes
         */
        async cancelAutoLayoutPreview() {
            if (!this.isAutoLayoutPreviewing) {
                console.warn("⚠️ No auto layout preview to cancel");
                return;
            }

            console.log("🔄 Canceling auto layout preview...");

            try {
                const stateManager = AutoLayoutStateManager.getInstance();

                // ✅ Validate original state trước khi restore
                if (!stateManager.validateOriginalState()) {
                    console.error("❌ Cannot cancel: Invalid original state");
                    return;
                }

                const state = stateManager.getState();

                // ✅ 1. Restore với COMPLETE callbacks
                stateManager.restoreOriginalState(
                    // Emit grid item update
                    (data) => this.eventBus.emit("update-grid-item", data),
                    // Restore data attributes
                    (itemId, dataAttributes) =>
                        this.restoreGridItemDataAttributes(itemId, dataAttributes),
                    // ✅ NEW: Restore block layouts
                    (blockId, layouts) => this.restoreBlockLayouts(blockId, layouts)
                );

                // ✅ 2. Restore groups nếu có
                if (this.groupLayoutPreview) {
                    for (const [groupId] of this.groupLayoutPreview) {
                        this.restoreGroupBounds(groupId);
                    }
                }

                // ✅ 3. Cancel height preview
                if (state.heightPreview && this.$refs.grid?.$refs?.item) {
                    const heightManager = HeightManager.getInstance();
                    heightManager.cancelHeightPreview(
                        state.heightPreview.originalHeight,
                        this.$refs.grid.$refs.item
                    );
                }

                console.log("✅ Auto layout preview cancelled successfully");
            } catch (error) {
                console.error("❌ Failed to cancel auto layout preview:", error);
            } finally {
                // ✅ 4. Complete cleanup
                this.finishAutoLayoutPreview();
            }
        },
        /**
         * Update Group Bounds After Auto Layout - NEW METHOD
         */
        async updateGroupBoundsAfterAutoLayout(groupId) {
            try {
                if (!this.data.groups || !this.data.groups[groupId]) {
                    console.warn(`Group ${groupId} not found`);
                    return;
                }

                const group = this.data.groups[groupId];
                const groupBlocks = group.blocks || [];

                if (groupBlocks.length === 0) {
                    return;
                }

                // Lấy thông tin về các items trong group
                const groupItems = groupBlocks
                    .map((blockId) => {
                        const block = this.data.blocks.find((b) => b.id === blockId);
                        if (!block) return null;

                        const layout = this.getScreenLayout(block, this.screen);
                        return {
                            id: blockId,
                            left: layout.left,
                            top: layout.top,
                            width: layout.width,
                            height: layout.height,
                            originalWidth: layout.width,
                            center: layout.center
                        };
                    })
                    .filter((item) => item !== null);

                if (groupItems.length === 0) {
                    return;
                }

                // Tính toán bounds mới
                const newBounds = EnhancedAutoLayoutHelper.calculateGroupBounds(
                    groupItems,
                    this.gridContainerWidth
                );

                if (!newBounds) {
                    return;
                }

                // Emit event để GroupWrapper cập nhật bounds
                this.eventBus.emit("update-group-bounds", {
                    groupId: groupId,
                    bounds: newBounds,
                    source: "auto-layout"
                });

                // Cập nhật vào group data nếu cần
                if (this.data.groups[groupId]) {
                    this.data.groups[groupId].bounds = newBounds;
                }
            } catch (error) {
                console.error(`❌ Failed to update bounds for group ${groupId}:`, error);
            }
        },

        /**
         * Restore Group Bounds - NEW METHOD
         */
        restoreGroupBounds(groupId) {
            try {
                // Emit event để GroupWrapper tự tính toán lại bounds từ vị trí items
                this.eventBus.emit("restore-group-bounds", {
                    groupId: groupId,
                    source: "auto-layout-cancel"
                });
            } catch (error) {
                console.error(`❌ Failed to restore bounds for group ${groupId}:`, error);
            }
        },

