        getGridItemDataAttributes(itemId) {
            const gridItemElement = this.$el.querySelector(`[data-id="${itemId}"]`);
            if (!gridItemElement) {
                return {};
            }

            return {
                "data-original-left": gridItemElement.getAttribute("data-original-left") || "",
                "data-original-top": gridItemElement.getAttribute("data-original-top") || "",
                "data-original-width": gridItemElement.getAttribute("data-original-width") || "",
                "data-original-height": gridItemElement.getAttribute("data-original-height") || ""
            };
        },
        restoreBlockLayouts(blockId, originalLayouts) {
            const block = this.data.blocks.find((b) => b.id === blockId);
            if (!block) {
                console.error(`❌ Block not found for restore: ${blockId}`);
                return;
            }

            // ✅ CRITICAL: Deep restore block.layouts
            block.layouts = JSON.parse(JSON.stringify(originalLayouts));

            // ✅ Update layout array
            const layoutItem = this.layout.find((l) => l.i === blockId);
            if (layoutItem) {
                const screenLayout = originalLayouts[this.screen] || originalLayouts.desktop || {};
                layoutItem.left = screenLayout.left || 0;
                layoutItem.top = screenLayout.top || 0;
                layoutItem.width = screenLayout.width || 100;
                layoutItem.height = screenLayout.height || 50;
                layoutItem.zindex = screenLayout.zindex || "";
                layoutItem.rotation = screenLayout.rotation || 0;
            }

            console.log(`✅ Restored block layouts for ${blockId}`);
        },
