        // ========================================================================
        // LAYOUT UPDATE METHODS - REFACTORED TO USE LayoutChangeApplicator
        // ========================================================================

        /**
         * Update Item Layout Enhanced - Sử dụng LayoutChangeApplicator
         */
        updateItemLayoutEnhanced(
            item,
            currentScreen,
            updates,
            isFullWidth = false,
            isPreview = false
        ) {
            const block = item.block;

            if (!block.layouts[currentScreen]) {
                block.layouts[currentScreen] = {};
            }

            // Cập nhật block.layouts với special handling cho full-width items
            Object.keys(updates).forEach((key) => {
                if (updates[key] !== undefined) {
                    if (isFullWidth) {
                        if (key === "left") {
                            block.layouts[currentScreen][key] = 0;
                        } else if (key === "width") {
                            block.layouts[currentScreen][key] = "100%";
                        } else {
                            block.layouts[currentScreen][key] = updates[key];
                        }
                    } else {
                        block.layouts[currentScreen][key] = updates[key];
                    }
                }
            });

            // Cập nhật layout array
            const layoutItem = this.layout.find((l) => l.i === item.id);
            if (layoutItem) {
                Object.keys(updates).forEach((key) => {
                    if (updates[key] !== undefined) {
                        if (isFullWidth && key === "left") {
                            layoutItem[key] = 0;
                        } else if (isFullWidth && key === "width") {
                            layoutItem[key] = "100%";
                        } else {
                            layoutItem[key] = updates[key];
                        }
                    }
                });
            }

            // ✅ MỚI: Cập nhật data-original-* attributes cho grid item
            this.updateGridItemDataAttributes(item.id, updates, isFullWidth, isPreview);

            // Sử dụng LayoutChangeApplicator để emit events
            const applicator = LayoutChangeApplicator.getInstance();
            applicator.emitLayoutUpdateEvents(item, updates, isFullWidth, {
                emitUpdateGridItem: (data) => this.eventBus.emit("update-grid-item", data),
                emitMoved: (id, left, top) => this.$emit("moved", id, left, top),
                emitResized: (id, height, width, left, top) =>
                    this.$emit("resized", id, height, width, left, top),
                emitZindexed: (id, zindex) => this.$emit("zindexed", id, zindex)
            });

            // Cập nhật item data local
            applicator.updateItemDataLocal(item, updates, isFullWidth, this.gridContainerWidth);
        },

        /**
         *  Cập nhật data-original-* attributes cho grid item
         */
        updateGridItemDataAttributes(itemId, updates, isFullWidth = false, isPreview = false) {
            // Tìm grid item element
            const gridItemElement = this.$el.querySelector(`[data-id="${itemId}"]`);
            if (!gridItemElement) {
                console.warn(`Grid item element not found for id: ${itemId}`);
                return;
            }

            // ✅ Cập nhật data-original-left
            if (updates.left !== undefined) {
                const newLeft = isFullWidth ? 0 : updates.left;
                gridItemElement.setAttribute("data-original-left", newLeft.toString());
            }

            // ✅ Cập nhật data-original-top
            if (updates.top !== undefined) {
                gridItemElement.setAttribute("data-original-top", updates.top.toString());
            }

            // ✅ Cập nhật data-original-width
            if (updates.width !== undefined) {
                const newWidth = isFullWidth ? "100%" : updates.width;
                gridItemElement.setAttribute("data-original-width", newWidth.toString());
            }

            // ✅ Cập nhật data-original-height
            if (updates.height !== undefined) {
                gridItemElement.setAttribute("data-original-height", updates.height.toString());
            }

            // ✅ Thêm class để đánh dấu đang preview (optional)
            if (isPreview) {
                gridItemElement.classList.add("auto-layout-preview");
            } else {
                gridItemElement.classList.remove("auto-layout-preview");
            }
        },

        /**
         * - Restore data-original-* attributes từ original state
         */
        restoreGridItemDataAttributes(itemId, originalAttributes) {
            const gridItemElement = this.$el.querySelector(`[data-id="${itemId}"]`);
            if (!gridItemElement) {
                console.warn(`⚠️ Grid item element not found for restore: ${itemId}`);
                return;
            }

            console.log(`🏷️ Restoring data attributes for ${itemId}:`, originalAttributes);

            // ✅ Restore tất cả data-original-* attributes
            Object.keys(originalAttributes).forEach((attrName) => {
                const attrValue = originalAttributes[attrName];
                if (attrValue !== null && attrValue !== undefined && attrValue !== "") {
                    gridItemElement.setAttribute(attrName, attrValue);
                } else {
                    gridItemElement.removeAttribute(attrName);
                }
            });

            // ✅ Remove preview classes
            gridItemElement.classList.remove("auto-layout-preview");

            console.log(`✅ Restored data attributes for ${itemId}`);
        },
        // ========================================================================
        // UTILITY METHODS - ENHANCED WITH HELPERS
        // ========================================================================

        /**
         * Check if has full-width items - Sử dụng Helper
         */
        hasFullWidthItemsInLayout() {
            if (!this.layout || this.layout.length === 0) return false;

            const itemsData = AutoLayoutHelper.convertBlocksToLayoutItems(
                this.data.blocks,
                this.getScreenLayout.bind(this),
                this.screen,
                this.gridContainerWidth
            );

            const analysis = AutoLayoutHelper.analyzeFullWidthItems(
                itemsData,
                this.gridContainerWidth
            );
            return analysis.fullWidthItems.length > 0 || analysis.oversizedItems.length > 0;
        },

        // ========================================================================
        // KEYBOARD HANDLER - Giữ nguyên nhưng có thể enhance
        // ========================================================================

        handleAutoLayoutKeyboard(event) {
            if (!this.isAutoLayoutPreviewing) return;

            // Enter = confirm
            if (event.key === "Enter" && !event.ctrlKey && !event.altKey && !event.shiftKey) {
                event.preventDefault();
                this.confirmAutoLayout();
            }

            // Escape = cancel
            if (event.key === "Escape") {
                event.preventDefault();
                this.cancelAutoLayoutPreview();
            }
        },

        // =============================================================================
        // DUPLICATE SECTION
        // =============================================================================
        duplicate() {
            // Lấy chiều cao wrapper
            const height = this.$refs.wrapper.offsetHeight;
            // Clone dữ liệu
            const data = this.cloneData(this);

            // Nếu có group thì xử lý lại group_id và groups
            if (data.groups && Object.keys(data.groups).length > 0) {
                // Tạo groupMap lưu blocks theo group_id cũ
                const groupMap = new Map();

                // Gom blocks theo group_id
                data.blocks.forEach((block) => {
                    if (block.group_id) {
                        if (!groupMap.has(block.group_id)) {
                            groupMap.set(block.group_id, {
                                blocks: [],
                                zIndex: 1
                            });
                        }
                        groupMap.get(block.group_id).blocks.push(block.id);
                    }
                });

                // Tạo map ánh xạ group_id cũ sang group_id mới
                const groupIdMap = {};
                data.groups = {};

                groupMap.forEach((groupData, oldGroupId) => {
                    const newGroupId = `gr-${crypto.randomUUID().slice(0, 8)}`;
                    groupIdMap[oldGroupId] = newGroupId;
                    data.groups[newGroupId] = groupData;
                });

                // Cập nhật lại group_id cho các block
                data.blocks.forEach((block) => {
                    if (block.group_id && groupIdMap[block.group_id]) {
                        block.group_id = groupIdMap[block.group_id];
                    }
                });
            }
            const index = this.sections.findIndex((s) => s.id == this.section_id);
            // Thêm section mới vào sau vị trí hiện tại
            this.sections.splice(index + 1, 0, data);

            // Cuộn tới vị trí mới
            this.scroll(height);
        },

        // =============================================================================
        // PASTE & CLIPBOARD METHODS
        // =============================================================================
        // helper
        // Thêm các hàm helper
        calculateBounds(blocks, screen, containerWidth) {
            let minLeft = Number.MAX_SAFE_INTEGER;
            let minTop = Number.MAX_SAFE_INTEGER;
            let maxLeft = 0;

            blocks.forEach((block) => {
                const layout = block.layouts[screen];
                const blockWidth = isPercentWidth(layout.width)
                    ? widthPxCalculate(layout.width, containerWidth)
                    : parseFloat(layout.width);

                minLeft = Math.min(minLeft, layout.left);
                minTop = Math.min(minTop, layout.top);
                maxLeft = Math.max(maxLeft, layout.left + (blockWidth / containerWidth) * 100);
            });

            return { minLeft, minTop, maxLeft };
        },

        processBlocks(blocks, screen, containerWidth, distanceLeft, distanceTop, context) {
            blocks.forEach((block) => {
                block.layouts = block.layouts || { desktop: {}, tablet: {}, mobile: {} };
                block.inGrid = true;

                const layout = block.layouts[screen];
                const newLeft = layout.left - distanceLeft;
                const newTop = layout.top - distanceTop;
                const width = parseFloat(layout.width || 100);

                const maxAllowedLeft = 100 - (width / containerWidth) * 100;

                const newBlockLayout = {
                    left: Math.max(0, Math.min(newLeft, maxAllowedLeft)),
                    top: Math.max(0, newTop),
                    width: layout.width || "100%",
                    height: layout.height || 50,
                    center: layout.center || false,
                    i: block.id,
                    static: false
                };

                layout.left = newBlockLayout.left;
                layout.top = newBlockLayout.top;

                context.layout.push(newBlockLayout);
            });
        },
        paste(clipboard) {
            if (!clipboard) return;
            let data = this.$helpers.copy(clipboard.data);
            const mouseX = this.mouse?.x || 0;
            const mouseY = this.mouse?.y / this.scaleRatio || 0;
            const gridElement = this.$refs.grid.$refs.item;
            const gridPos = this.calculateGridPosition(mouseX, mouseY, gridElement, 0);
            switch (clipboard.is) {
                case "block":
                case "blockFlex": {
                    data = this.$helpers.generateElementId(data);
                    data.id = this.$helpers.randid();
                    data.inGrid = true;
                    this.handleUndoRedoGridItem(data, "added");
                    if (!data.layouts) {
                        data.layouts = { desktop: {}, tablet: {}, mobile: {} };
                    }
                    const newBlockLayout = {
                        left: gridPos.left,
                        top: gridPos.top,
                        width: data.layouts[this.screen].width || 100,
                        height: data.layouts[this.screen].height || 50,
                        i: data.id,
                        static: false,
                        center: data.layouts[this.screen].center || false
                    };
                    const containerWidth = gridElement.offsetWidth || 1200;
                    newBlockLayout.left = Math.max(
                        0,
                        Math.min(
                            newBlockLayout.left,
                            100 - (parseFloat(newBlockLayout.width) / containerWidth) * 100
                        )
                    );
                    newBlockLayout.top = Math.max(0, newBlockLayout.top);
                    data.layouts[this.screen] = newBlockLayout;
                    if (!this.data.blocks) this.data.blocks = [];
                    this.data.blocks.push(data);
                    this.layout.push(newBlockLayout);

                    this.eventBus.emit("refresh-grid", { sectionId: this.data.id });

                    this.$nextTick(() => {
                        this.eventBus.emit("content-resize", {
                            i: data.id,
                            width: newBlockLayout.width,
                            height: newBlockLayout.height,
                            rotation: newBlockLayout.rotation || 0
                        });

                        setTimeout(() => {
                            this.eventBus.emit("content-resize", {
                                i: data.id,
                                width: newBlockLayout.width,
                                height: newBlockLayout.height,
                                rotation: newBlockLayout.rotation || 0
                            });
                            window.dispatchEvent(new Event("resize"));
                        }, 100);
                    });
                    break;
                }

                // Trong switch case
                case "group_grid":
                case "selection": {
                    const isGroup = clipboard.is === "group_grid";
                    const { blocks, idGroup, group } = isGroup
                        ? clipboard.data
                        : { blocks: clipboard.data };
                    const containerWidth = gridElement.offsetWidth || 1200;

                    // Tính toán bounds
                    const { minLeft, minTop, maxLeft } = this.calculateBounds(
                        blocks,
                        this.screen,
                        containerWidth
                    );

                    // Tính toán khoảng cách
                    let distanceLeft = minLeft - gridPos.left;
                    const distanceTop = minTop - gridPos.top;

                    // Điều chỉnh distanceLeft nếu cần
                    if (distanceLeft < 0 && distanceLeft < maxLeft - 100) {
                        distanceLeft = maxLeft - 100;
                    }

                    // Xử lý blocks
                    this.processBlocks(
                        blocks,
                        this.screen,
                        containerWidth,
                        distanceLeft,
                        distanceTop,
                        this
                    );

                    // Xử lý dữ liệu đặc thù
                    if (isGroup) {
                        this.data.groups = this.data.groups || {};
                        this.data.groups[idGroup] = group;
                    }

                    // Cập nhật data
                    this.data.blocks = this.data.blocks || [];
                    blocks.forEach((block) => {
                        block.id = this.$helpers.randid();
                    });
                    this.data.blocks.push(...blocks);
                    const blockIds = blocks.map((block) => block.id);
                    handleSetHistorySelection(this.data, blockIds, this.screen, "duplicated");
                    // Kích hoạt event
                    this.eventBus.emit("refresh-grid", { sectionId: this.data.id });
                    break;
                }
                case "section":
                case "grid": {
                    let data = this.$helpers.copy(clipboard.data);
                    data = this.$helpers.generateElementId(data);
                    const index = this.sections.findIndex((s) => s.id == this.section_id);
                    this.sections.splice(index + 1, 0, data);
                    this.scroll(this.$refs.wrapper.offsetHeight);
                    break;
                }
            }
        },

        // =============================================================================
        // UI INTERACTION METHODS
        // =============================================================================
        editRow() {
            const editingElement = this.$store.getters["builder/editingElement"];
            if (!editingElement || editingElement.data.id !== this.data.id) {
                this.$store.commit("builder/setActiveElement", this);
                this.$store.commit("builder/setEditingElement", this);
                const rect = this.$el.getBoundingClientRect();
                const isNearTop = rect.top <= 50;
                this.shouldApplyMarginBottom = isNearTop;
            }
        },

        editSection(event) {
            if (this.isUpdatingLayout) return;
            const editingElement = this.$store.getters["builder/editingElement"];
            if (this.justDragged || this.justSelected) return;
            if (!editingElement || editingElement.data.id !== this.section_id) {
                let inst = this.is == "section" ? this.$parent : this;
                this.$store.commit("builder/setActiveElement", this);
                this.$store.commit("builder/setEditingElement", inst);
                const rect = this.$el.getBoundingClientRect();
                const isNearTop = rect.top <= 50;
                this.shouldApplyMarginBottom = isNearTop;
            }
        },



        // =============================================================================
        // SECTION MANAGEMENT METHODS
        // =============================================================================
        addSection() {
            let realIndex = this.sections.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.$parent.sections.splice(index, 0, { config: {}, columns: [] });
            this.$parent.indexofnew = index;
            this.over = false;
        },

        addSectionAfter() {
            let realIndex = this.sections.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.sections.splice(index + 1, 0, { config: {}, columns: [] });
            this.$parent.indexofnew = realIndex + 1;
            this.over = false;
        },

        moveSection(e, position) {
            let realIndex = this.sections.findIndex((s) => s.id == this.section_id),
                index = realIndex > -1 ? realIndex : this.index;
            const sections = this.sections.splice(index, 1);
            const newIndex = position === "prev" ? index - 1 : index + 1;
            this.sections.splice(newIndex, 0, sections[0]);
            const section = this.sections.find((section) => section.id == this.data.id);
            this.$store.dispatch("history/addStack", {
                type: "section",
                index: index,
                data: section,
                section_id: this.data.id,
                action: "delete"
            });
            setTimeout(() => {
                const html = this.idoc().querySelector("html");
                const element = this.$refs.wrapper;
                const elementRect = element.getBoundingClientRect();
                const absoluteElementTop = elementRect.top + window.pageYOffset;
                const middle = absoluteElementTop - html.offsetHeight / 2;
                this.scroll(middle);
            }, 100);
        },

        dropOut() {
            if (this.section_id == this.editingElement?.data?.id) {
                setTimeout(() => {
                    this.$store.dispatch("builder/setEditingElement", null);
                }, 50);
            }
            let id = this.section_id;
            let index = this.sections.findIndex((section) => section.id == id);
            const result = this.sections.find((section) => section.id == id);
            if (result) {
                this.$store.dispatch("history/addStack", {
                    type: "section",
                    index: index,
                    data: result,
                    section_id: this.data.id,
                    action: "delete"
                });
                this.sections.splice(index, 1);
                return result;
            }
        },

        // =============================================================================
        // BLOCK MANAGEMENT METHODS
        // =============================================================================
        getBlock(blockId) {
            return this.data.blocks.find((block) => block.id === blockId);
        },

        getBlockIndex(blockId) {
            return this.data.blocks.findIndex((block) => block.id === blockId);
        },

        getBlockLayout(blockId) {
            const layoutItem = this.layout.find((item) => item.i === blockId);

            if (layoutItem) {
                return {
                    i: blockId,
                    left: layoutItem.left != null ? ensureNumericValue(layoutItem.left) : 0,
                    top: layoutItem.top != null ? ensureNumericValue(layoutItem.top) : 0,
                    width: layoutItem.width != null ? layoutItem.width : 100,
                    height: layoutItem.height != null ? ensureNumericValue(layoutItem.height) : 50,
                    rotation: layoutItem.rotation || 0,
                    zindex: layoutItem.zindex != null ? layoutItem.zindex : "",
                    options: layoutItem.options || {},
                    group: layoutItem.group || false,
                    locked: layoutItem.locked || false,
                    center: layoutItem.center || false
                };
            }

            const block = this.data.blocks.find((b) => b.id === blockId);
            if (!block || block.visibility === false) return null;

            let screenLayout = {};
            if (!block.layouts) {
                block.layouts = getOptionsGrid(block).layouts || {};
            }
            if (block.layouts[this.screen]) {
                screenLayout = block.layouts[this.screen];
            } else if (block.layouts.desktop) {
                screenLayout = block.layouts.desktop;
            }

            return {
                i: blockId,
                left: screenLayout.left != null ? ensureNumericValue(screenLayout.left) : 0,
                top: screenLayout.top != null ? ensureNumericValue(screenLayout.top) : 0,
                width: screenLayout.width != null ? screenLayout.width : 100,
                height: screenLayout.height != null ? ensureNumericValue(screenLayout.height) : 50,
                zindex: screenLayout.zindex != null ? screenLayout.zindex : "",
                rotation: screenLayout.rotation || 0,
                options: block.layouts.options || {},
                group: block.group || elementIframe.includes(block.name) ? true : false,
                locked: screenLayout.locked || false,
                center: screenLayout.center || false
            };
        },

        getScreenLayout(block, screen) {
            if (!block.layouts) {
                block.layouts = { desktop: {}, tablet: {}, mobile: {} };
            }

            const result = {};
            const desktopLayout = block.layouts.desktop || {};
            const screenLayout = block.layouts[screen] || {};

            result.left =
                screen !== "desktop" && screenLayout.left !== undefined
                    ? screenLayout.left
                    : desktopLayout.left !== undefined
                    ? desktopLayout.left
                    : 0;

            result.top =
                screen !== "desktop" && screenLayout.top !== undefined
                    ? screenLayout.top
                    : desktopLayout.top !== undefined
                    ? desktopLayout.top
                    : 0;

            result.width =
                screen !== "desktop" && screenLayout.width !== undefined
                    ? screenLayout.width
                    : desktopLayout.width !== undefined
                    ? desktopLayout.width
                    : 100;

            result.height =
                screen !== "desktop" && screenLayout.height !== undefined
                    ? screenLayout.height
                    : desktopLayout.height !== undefined
                    ? desktopLayout.height
                    : 50;

            result.rotation =
                screen !== "desktop" && screenLayout.rotation !== undefined
                    ? screenLayout.rotation
                    : desktopLayout.rotation !== undefined
                    ? desktopLayout.rotation
                    : 0;

            result.zindex =
                screen !== "desktop" && screenLayout.zindex !== undefined
                    ? screenLayout.zindex
                    : desktopLayout.zindex !== undefined
                    ? desktopLayout.zindex
                    : "";
            result.locked =
                screen !== "desktop" && screenLayout.locked !== undefined
                    ? screenLayout.locked
                    : desktopLayout.locked !== undefined
                    ? desktopLayout.locked
                    : false;

            result.center =
                screen !== "desktop" && screenLayout.center !== undefined
                    ? screenLayout.center
                    : desktopLayout.center !== undefined
                    ? desktopLayout.center
                    : false;

            return result;
        },
        rebuildLayoutFromBlocks() {
            console.log("🔧 Rebuilding layout from blocks...");

            // ✅ CRITICAL: Rebuild hoàn toàn layout array từ data.blocks
            const newLayout = [];

            this.data.blocks.forEach((block, index) => {
                if (!block.id) {
                    console.error(`❌ Block missing ID at index ${index}:`, block);
                    return;
                }
                if (block.visibility === false) {
                    //console.error(`❌ Block ${block.id} is hidden at index ${index}:`, block);
                    return;
                }

                // Đảm bảo layouts được khởi tạo
                if (!block.layouts) {
                    console.warn(`⚠️ Block ${block.id} missing layouts, initializing...`);
                    block.layouts = {
                        desktop: { left: 0, top: index * 60, width: 100, height: 50 }
                    };
                }

                // Lấy layout cho screen hiện tại
                const screenLayout = this.getScreenLayout(block, this.screen);

                const layoutItem = {
                    i: block.id,
                    left: screenLayout.left,
                    top: screenLayout.top,
                    width: screenLayout.width,
                    height: screenLayout.height,
                    rotation: screenLayout.rotation || 0,
                    zindex: screenLayout.zindex || "",
                    group: block.group || elementIframe.includes(block.name) ? true : false,
                    options: getOptionsGrid(block)?.options || {},
                    visibility: block.visibility,
                    locked: screenLayout.locked,
                    static: false,
                    center: screenLayout.center || false
                };

                newLayout.push(layoutItem);
            });

            // ✅ REPLACE layout array completely
            this.layout.splice(0, this.layout.length, ...newLayout);
        },

        updateLayoutProperty(block, screen, property, value) {
            if (!block.layouts[screen]) {
                block.layouts[screen] = {};
            }

            const previousValue = block.layouts[screen][property];

            if (property === "width") {
                if (typeof value === "string" && (value.includes("px") || value.includes("%"))) {
                    block.layouts[screen][property] = value;
                } else if (typeof value === "number") {
                    const oldValue = block.layouts[screen][property];
                    const oldUnit =
                        typeof oldValue === "string" && oldValue.includes("%") ? "%" : "px";
                    block.layouts[screen][property] = value + oldUnit;
                } else {
                    block.layouts[screen][property] = value;
                }
            } else {
                block.layouts[screen][property] = value;
            }

            gridDebug("grid", "layout-property:update", {
                sectionId: this.section_id,
                blockId: block.id,
                screen,
                property,
                previousValue,
                nextValue: block.layouts[screen][property]
            }, this as any);
        },

        getLayoutItem(blockId) {
            const index = this.getBlockIndex(blockId);
            return this.layout[index] || {};
        },

        // =============================================================================
        // GRID EVENT HANDLERS
        // =============================================================================
        move: function (i, newX, newY) {
            this.moving = true;
        },

        resize: function (i, newH, newW, newHPx, newWPx) {
            this.moving = true;
            this.resizing = true;
        },

        rotate: function (i, angle) {
            this.rotating = true;
        },

        moved: function (i, newX, newY, center = false) {
            this.isUpdatingLayout = true;
            try {
                // Sanitize và validate giá trị
                const sanitizedX = ensureNumericValue(newX);
                const sanitizedY = ensureNumericValue(newY);

                // Kiểm tra NaN và fallback về 0
                const validX = isNaN(sanitizedX) ? 0 : sanitizedX;
                const validY = isNaN(sanitizedY) ? 0 : sanitizedY;

                const previousLayoutItem = this.layout.find((item) => item.i === i)
                    ? { ...this.layout.find((item) => item.i === i) }
                    : null;

                gridDebug("grid", "move:commit:start", {
                    sectionId: this.section_id,
                    itemId: i,
                    inputX: newX,
                    inputY: newY,
                    sanitizedX,
                    sanitizedY,
                    validX,
                    validY,
                    center,
                    previousLayoutItem,
                    previousBlockLayout: this.data.blocks.find((block) => block.id === i)?.layouts?.[this.screen] || null
                }, this as any);

                // Cập nhật this.layout
                let sections_data = JSON.parse(JSON.stringify(this.sections));
                const layoutItem = this.layout.find((item) => item.i === i);
                if (layoutItem) {
                    layoutItem.left = validX;
                    layoutItem.top = validY;
                    layoutItem.center = center;
                }

                const block = this.data.blocks.find((block) => block.id === i);
                if (block) {
                    this.handleUndoRedoGridItem(block, "moved");

                    this.updateLayoutProperty(block, this.screen, "left", validX);
                    this.updateLayoutProperty(block, this.screen, "center", center);
                    this.updateLayoutProperty(block, this.screen, "top", validY);

                    gridDebug("grid", "move:commit:end", {
                        sectionId: this.section_id,
                        itemId: i,
                        finalLayoutItem: layoutItem ? { ...layoutItem } : null,
                        finalBlockLayout: block.layouts?.[this.screen] || null
                    }, this as any);
                }
            } finally {
                setTimeout(() => {
                    this.isUpdatingLayout = false;
                    this.moving = false;
                }, 50);
            }
        },

        zindexed: function (i, newZindex) {
            this.isUpdatingLayout = true;
            try {
                const layoutItem = this.layout.find((item) => item.i === i);
                if (layoutItem) {
                    layoutItem.zindex = ensureNumericValue(newZindex);
                }

                const block = this.data.blocks.find((block) => block.id === i);
                if (block) {
                    this.handleUndoRedoGridItem(block, "zindexed");
                    this.updateLayoutProperty(
                        block,
                        this.screen,
                        "zindex",
                        ensureNumericValue(newZindex)
                    );
                }
            } finally {
                setTimeout(() => {
                    this.isUpdatingLayout = false;
                }, 50);
            }
        },

        resized: function (i, newH, newW, newLeft, newTop, isResize = false) {
            this.isUpdatingLayout = true;

            try {
                let wModify = newW,
                    hModify = newH;
                const layoutItem = this.layout.find((item) => item.i === i);
                const block = this.data.blocks.find((block) => block.id === i);
                const hasPositionPayload = newLeft !== undefined || newTop !== undefined;
                const commitType = isResize
                    ? "user-resize"
                    : hasPositionPayload
                    ? "programmatic-resize"
                    : "auto-height-or-screen-sync";

                gridDebug("grid", "resize:commit:start", {
                    sectionId: this.section_id,
                    itemId: i,
                    inputHeight: newH,
                    inputWidth: newW,
                    inputLeft: newLeft,
                    inputTop: newTop,
                    isResize,
                    commitType,
                    hasPositionPayload,
                    activeScreen: this.screen,
                    previousLayoutItem: layoutItem ? { ...layoutItem } : null,
                    previousBlockLayout: block?.layouts?.[this.screen] || null
                }, this as any);

                if (layoutItem) {
                    if (newH) {
                        const sanitizedH = ensureNumericValue(newH);
                        layoutItem.height = isNaN(sanitizedH) ? 50 : sanitizedH;
                    } else if (block) {
                        if (this.screen !== "desktop") {
                            if (this.screen == "tablet") {
                                hModify = block.layouts.desktop.height;
                            } else {
                                hModify =
                                    block.layouts.tablet.height || block.layouts.desktop.height;
                            }
                        }
                        const sanitizedH = ensureNumericValue(hModify);
                        layoutItem.height = isNaN(sanitizedH) ? 50 : sanitizedH;
                    }

                    if (newW) {
                        if (typeof newW === "string" && /\d(px|%|rem|em|vh|vw)$/.test(newW)) {
                            layoutItem.width = newW;
                            wModify = newW;
                        } else {
                            layoutItem.width = ensureNumericValue(newW);
                            wModify = ensureNumericValue(newW);
                        }
                    } else if (block) {
                        if (this.screen !== "desktop") {
                            if (this.screen == "tablet") {
                                wModify = block.layouts.desktop.width;
                            } else {
                                wModify = block.layouts.tablet.width || block.layouts.desktop.width;
                            }
                        }
                        layoutItem.width = ensureNumericValue(wModify);
                    }

                    if (newLeft !== undefined) {
                        const sanitizedLeft = ensureNumericValue(newLeft);
                        layoutItem.left = isNaN(sanitizedLeft) ? 0 : sanitizedLeft;
                    }
                    if (newTop !== undefined) {
                        const sanitizedTop = ensureNumericValue(newTop);
                        layoutItem.top = isNaN(sanitizedTop) ? 0 : sanitizedTop;
                    }
                }

                if (block) {
                    const layouts = block.layouts[this.screen] || block.layouts.desktop;
                    const { width, height } = layouts;
                    const options = getOptionsGrid(block).options;
                    if (
                        !isNaN(hModify) &&
                        !isNaN(height) &&
                        isResize &&
                        (ensureNumericValue(width) !== ensureNumericValue(wModify) ||
                            ensureNumericValue(Math.ceil(height)) !==
                                ensureNumericValue(Math.ceil(hModify)))
                    ) {
                        this.handleUndoRedoGridItem(block, "resized");
                    }
                    const sanitizedH = ensureNumericValue(hModify);
                    const validH = isNaN(sanitizedH) ? 50 : sanitizedH;
                    this.updateLayoutProperty(
                        block,
                        this.screen,
                        "height",
                        validH
                    );
                    this.updateLayoutProperty(block, this.screen, "width", wModify);
                    if (newLeft !== undefined) {
                        const sanitizedLeft = ensureNumericValue(newLeft);
                        const validLeft = isNaN(sanitizedLeft) ? 0 : sanitizedLeft;
                        this.updateLayoutProperty(
                            block,
                            this.screen,
                            "left",
                            validLeft
                        );
                    }
                    if (newTop !== undefined) {
                        const sanitizedTop = ensureNumericValue(newTop);
                        const validTop = isNaN(sanitizedTop) ? 0 : sanitizedTop;
                        this.updateLayoutProperty(
                            block,
                            this.screen,
                            "top",
                            validTop
                        );
                    }

                    gridDebug("grid", "resize:commit:end", {
                        sectionId: this.section_id,
                        itemId: i,
                        commitType,
                        finalHeight: hModify,
                        finalWidth: wModify,
                        finalLayoutItem: layoutItem ? { ...layoutItem } : null,
                        finalBlockLayout: block.layouts?.[this.screen] || null
                    }, this as any);
                }
            } finally {
                setTimeout(() => {
                    this.isUpdatingLayout = false;
                    this.moving = false;
                    this.resizing = false;
                }, 50);
            }
        },

        rotated: function (i, angle) {
            this.isUpdatingLayout = true;

            try {
                const layoutItem = this.layout.find((item) => item.i === i);
                if (layoutItem) {
                    layoutItem.rotation = ensureNumericValue(angle);
                }

                const block = this.data.blocks.find((block) => block.id === i);
                if (block) {
                    this.handleUndoRedoGridItem(block, "rotated");
                    this.updateLayoutProperty(
                        block,
                        this.screen,
                        "rotation",
                        ensureNumericValue(angle)
                    );
                }
            } finally {
                setTimeout(() => {
                    this.isUpdatingLayout = false;
                    this.rotating = false;
                }, 50);
            }
        },

        containerSizeUpdated: function (width) {
            this.gridContainerWidth = width;
        },
        // =============================================================================
        // handle undo/redo
        // =============================================================================
        handleUndoRedoGridItem(block, action, sectionIdOld = "", dataStructure = null) {
            if (!(this.isSelection || this.isActiveGroup)) {
                let payload = {
                    type: "BlockGrid",
                    data: null,
                    action: action,
                    screen: this.screen,
                    section_id: this.section_id,
                    dataStructure: dataStructure
                };
                switch (action) {
                    case "added":
                        if (sectionIdOld) {
                            payload.section_from = sectionIdOld;
                        }
                        payload = {
                            ...payload,
                            data: block
                        };
                        break;
                    default:
                        const layouts = block.layouts[this.screen] || block.layouts.desktop;
                        const { top, left, width, height, zindex, rotation, group } = layouts;
                        payload = {
                            ...payload,
                            data: {
                                id: block.id,
                                top,
                                left,
                                width,
                                height,
                                zindex: zindex || "",
                                rotation: rotation || 0,
                                group
                            }
                        };
                        break;
                }
                this.$store.dispatch("history/addStack", payload);
            }
        },
        // =============================================================================
        // UTILITY METHODS những method cần thiết
        // =============================================================================
        calcXY(top, left) {
            const key = `${top}-${left}`;
            if (this._xyCache && this._xyCache[key]) {
                return this._xyCache[key];
            }

            if (!this._xyCache) this._xyCache = {};
            const cacheSize = Object.keys(this._xyCache).length;
            if (cacheSize > 1000) {
                const keys = Object.keys(this._xyCache);
                for (let i = 0; i < 100; i++) {
                    delete this._xyCache[keys[i]];
                }
            }

            const gridElement = this.$refs.grid.$refs.item;
            const containerWidth = gridElement ? gridElement.offsetWidth : 1200;
            const leftPercent = (left / containerWidth) * 100;

            this._xyCache[key] = {
                x: leftPercent,
                y: top
            };

            return this._xyCache[key];
        },

        calcColWidth(): number {
            const gridElement = this.$refs.grid?.$el;
            const containerWidth = gridElement
                ? gridElement.offsetWidth
                : this.cols[this.screens[this.screen]] || 1200;
            return (containerWidth - this.marginX * (this.colNum + 1)) / this.colNum;
        },

        // =============================================================================
        // DRAG & DROP METHODS
        // =============================================================================
        overBlocks(e) {
            if (this.isFullScreen) return;
            this.over = true;
            if (this.dragCurrent?.data?.isLibrarySection) {
                this.$store.commit('builder/setDropTo', null);
            }
        },

        outBlocks() {
            if (!this.isFullScreen || !this.isDragging) {
                this.timmer = setTimeout(() => {
                    if (!this.dragCurrent || !this.$parent.over) {
                        this.over = false;
                    }
                }, 50);
            }
        },
        // Calculate next Z-Index
        calculateNextZIndex() {
            const DEFAULT_START_ZINDEX = 10;

            if (!this.data.blocks || this.data.blocks.length === 0) {
                return DEFAULT_START_ZINDEX;
            }

            let maxZIndex = 0;
            let hasAnyZIndex = false;

            // Duyệt qua tất cả blocks để tìm z-index cao nhất
            this.data.blocks.forEach((block) => {
                if (!block.layouts) return;

                // Kiểm tra z-index trong tất cả các screen layouts
                Object.keys(block.layouts).forEach((screen) => {
                    if (screen === "options") return; // Skip options key

                    const layout = block.layouts[screen];
                    if (
                        layout &&
                        layout.zindex !== undefined &&
                        layout.zindex !== null &&
                        layout.zindex !== ""
                    ) {
                        const currentZIndex = parseInt(layout.zindex);
                        if (!isNaN(currentZIndex)) {
                            maxZIndex = Math.max(maxZIndex, currentZIndex);
                            hasAnyZIndex = true;
                        }
                    }
                });
            });

            // Nếu không có z-index nào, trả về giá trị mặc định
            if (!hasAnyZIndex) {
                return DEFAULT_START_ZINDEX;
            }

            // Trả về max z-index + 1
            return maxZIndex + 1;
        },

        //Set Z-Index for block across all screens
        setBlockZIndex(block, zindex) {
            if (!block.layouts) {
                block.layouts = {};
            }

            // Thiết lập z-index cho screen hiện tại
            if (!block.layouts[this.screen]) {
                block.layouts[this.screen] = {};
            }
            block.layouts[this.screen].zindex = zindex;

            // Thiết lập z-index cho desktop nếu screen hiện tại không phải desktop
            if (this.screen !== "desktop") {
                if (!block.layouts.desktop) {
                    block.layouts.desktop = {};
                }
                block.layouts.desktop.zindex = zindex;
            }
        },
        dropIn(current, offset) {
            const index = this.sections.findIndex((s) => s.id == this.section_id);
            if (current.is === "grid" || current.is === "section") {
                this.sections.splice(index + offset, 0, current.dropOut());
                return;
            }
            this.dataStructure = getIdParentAndIndex(current);
            if (
                (current?.section_id === this.data.id && current?.inGrid) ||
                current.is === "column"
            )
                return;
            if (current?.section_id && current?.section_id !== this.data.id) {
                this.sectionIdOld = current?.section_id;
            }
            const sections = JSON.parse(JSON.stringify(this.sections));
            let block = current.dropOut() || {};

            if (!block || Object.keys(block).length === 0) {
                console.error("Không thể lấy dữ liệu block từ nguồn kéo thả");
                return;
            }

            block = JSON.parse(JSON.stringify(block));
            if (!block.id) {
                block.id = this.$helpers.randid();
                block.IDInit = true;
            }

            if (!block.layouts) {
                block.layouts = getOptionsGrid(block).layouts || {};
            }

            const mouseX = this.mouse?.x || 0;
            const mouseY = this.mouse?.y / this.scaleRatio || 0;
            const gridElement = this.$refs.grid.$refs.item;
            const { left, top, gridRect } = this.calculateGridPosition(
                mouseX,
                mouseY,
                gridElement,
                0
            );
            // ✅ CALCULATE Z-INDEX FOR NEW BLOCK
            const newZIndex = this.calculateNextZIndex();
            this.initLayoutOptions(block);

            if (!block.layouts[this.screen]) {
                block.layouts.modify = true;
                block = this.setupScreenLayouts(block, left, top, newZIndex);
                this.tempBlock = block;
                return;
            }

            const dataUndo = current.data;
            if (dataUndo.group) {
                dataUndo.group.id = block.id;
            }
            this.handleUndoRedoGridItem(
                { ...dataUndo, id: block.id },
                "added",
                current.section_id,
                JSON.parse(JSON.stringify(this.dataStructure))
            );

            let adjustedLeft = left;
            let adjustedTop = top;

            if (block.layouts[this.screen]) {
                const { width, height } = block.layouts[this.screen];

                if (this.differenceMouseItem && current.section_id !== this.data.id) {
                    const ratio = this.differenceMouseItem.containerWidth / this.gridContainerWidth;
                    adjustedLeft -= (this.differenceMouseItem.left * ratio) / this.scaleRatio;
                    adjustedTop -= this.differenceMouseItem.top;
                } else {
                    if (width) {
                        adjustedLeft -=
                            ((parseFloat(width) * this.scaleRatio) / 2 / gridRect.width) * 100;
                    }
                    if (height) {
                        adjustedTop -= (parseFloat(height) * this.scaleRatio) / 2;
                    }
                }
            }

            if (adjustedLeft < 0) adjustedLeft = 0;
            if (adjustedTop < 0) adjustedTop = 0;
            const precentWidth =
                ensureNumericValue(
                    widthPxCalculate(block.layouts[this.screen]?.width, this.gridContainerWidth)
                ) / this.gridContainerWidth ||
                ensureNumericValue(
                    widthPxCalculate(block.layouts["desktop"].width, this.gridContainerWidth)
                ) / this.gridContainerWidth;
            if (adjustedLeft + precentWidth * 100 > 100) {
                adjustedLeft = 100 - precentWidth * 100;
            }

            block = this.setupScreenLayouts(block, adjustedLeft, adjustedTop);

            // ✅ SET Z-INDEX FOR THE NEW BLOCK
            this.setBlockZIndex(block, newZIndex);

            block.inGrid = true;

            if (!this.data.blocks) this.data.blocks = [];

            this.data.blocks.push(block);

            const layoutItem = {
                i: block.id,
                left: block.layouts[this.screen]?.left || adjustedLeft,
                top: block.layouts[this.screen]?.top || adjustedTop,
                width: block.layouts[this.screen]?.width || block.layouts["desktop"].width,
                height: block.layouts[this.screen]?.height || block.layouts["desktop"].height,
                rotation: block.layouts[this.screen]?.rotation || block.layouts["desktop"].rotation,
                zindex: newZIndex, // ✅ SET Z-INDEX IN LAYOUT ITEM
                options: block.layouts.options,
                group: block.group ? true : false
            };

            this.layout.push(layoutItem);

            this.$nextTick(() => {
                this.eventBus.emit("refresh-grid", { sectionId: this.data.id });
                this.differenceMouseItem = null;
                this.eventBus.emit("update-grid-item", {
                    id: block.id,
                    left: adjustedLeft,
                    top: adjustedTop,
                    width: block.layouts[this.screen]?.width || block.layouts["desktop"].width,
                    height: block.layouts[this.screen]?.height || block.layouts["desktop"].height,
                    rotation:
                        block.layouts[this.screen]?.rotation || block.layouts["desktop"].rotation,
                    zindex: newZIndex // ✅ EMIT Z-INDEX IN UPDATE EVENT
                });
                this.dataStructure = null;
            });
        },

        // =============================================================================
        // RESIZE HANDLING
        // =============================================================================
        startResizing(e) {
            if (this.resizeHandler) {
                this.resizeHandler.startResizing(e);
            }
        },

        // =============================================================================
        // HELPER METHODS - Giữ lại những method cần thiết cho component
        // =============================================================================
        setupScreenLayouts(block, left, top, zindex = 10) {
            const screens = ["desktop"];
            screens.forEach((screen) => {
                if (!block.layouts[screen]) {
                    block.layouts[screen] = {};
                }
                block.layouts[screen].left = left;
                block.layouts[screen].top = top;
                block.layouts[screen].width = block.layouts[screen].width || 400;
                block.layouts[screen].height = block.layouts[screen].height || "auto";
                block.layouts[screen].zindex = zindex;
            });
            return block;
        },

        initLayoutOptions(block) {
            if (!block.layouts.options) {
                block.layouts.options = {
                    resize: { conner: true, x: true, y: false },
                    ratioSize: false,
                    autoHeight: true
                };
            }
            return block;
        },

        calculateGridPosition(mouseX, mouseY, gridElement, offset = 0) {
            const gridRect = gridElement ? gridElement.getBoundingClientRect() : null;
            let left = 0,
                top = 0;

            if (gridRect) {
                const offsetParent = gridElement.offsetParent || document.body;
                const offsetParentRect =
                    offsetParent === document.body
                        ? { left: 0, top: 0 }
                        : offsetParent.getBoundingClientRect();
                const gridLeft = gridRect.left - offsetParentRect.left;
                const gridTop = gridRect.top - offsetParentRect.top;

                const relativeX = mouseX - gridLeft;
                const relativeY = mouseY - gridTop;

                left = (relativeX / gridRect.width) * 100;
                top = relativeY - offset;
            }

            return {
                left: Math.max(0, Math.min(100, left)),
                top: Math.max(0, top),
                gridRect
            };
        },

        // =============================================================================
        // LEGACY METHODS - Giữ lại để tương thích
        // =============================================================================
        updateSizeNewElement(payload) {
            const { id, width, height, canSetTempBlockNull, isUpdate } = payload;

            if (isUpdate && this.tempIdBlock) {
                const index = this.layout.findIndex((item) => item.i === this.tempIdBlock);
                if (index !== -1) {
                    this.stack.map((block) => {
                        if (block.id === this.tempIdBlock) {
                            block.layouts[this.screen].width = width;
                            block.layouts[this.screen].height = height;
                            this.eventBus.emit("update-grid-item", {
                                id: this.tempIdBlock,
                                left: block.layouts[this.screen].left,
                                top: block.layouts[this.screen].top,
                                width: width + "px",
                                height: height + "px"
                            });
                        }
                    });
                }
                this.$nextTick(() => {
                    this.tempBlock = null;
                });
                return;
            }

            const block = this.tempBlock;

            if (!block.layouts) block.layouts = {};

            const gridElement = this.$refs.grid.$refs.item;
            const gridRect = gridElement ? gridElement.getBoundingClientRect() : null;
            if (!block.layouts[this.screen]) {
                block.layouts[this.screen] = block.layouts["desktop"];
            }
            block.layouts[this.screen].width = width / this.scaleRatio;
            block.layouts[this.screen].height = height;
            block.layouts[this.screen].left -= (width / 2 / gridRect.width) * 100;
            block.layouts[this.screen].top -= height / 2;
            block.layouts[this.screen].left =
                block.layouts[this.screen].left >= 0 ? block.layouts[this.screen].left : 0;
            block.layouts[this.screen].top =
                block.layouts[this.screen].top >= 0 ? block.layouts[this.screen].top : 0;
            const precentWidth = block.layouts[this.screen]?.width / gridRect.width;
            if (block.layouts[this.screen].left + precentWidth * 100 > 100) {
                block.layouts[this.screen].left = 100 - precentWidth * 100;
            }
            const clone = JSON.parse(JSON.stringify(block));
            clone.id = this.$helpers.randid();
            this.handleUndoRedoGridItem(clone, "added", this.sectionIdOld, this.dataStructure);
            clone.editOnMounted = true;
            this.tempIdBlock = clone.id;

            this.stack.push(clone);
            this.layout.push({
                ...clone.layouts[this.screen],
                group: clone.group ? true : false,
                i: clone.id,
                options: clone.layouts.options
            });
            this.sectionIdOld = "";
            this.dataStructure = null;
            if (canSetTempBlockNull) {
                this.tempBlock = null;
            }
        },

        layoutCreatedEvent: function (newLayout) {
            // console.log("Created layout: ", newLayout)
        },

        layoutMountedEvent: function (newLayout) {},

        itemTitle(item) {
            let result = item.i;
            if (item.static) {
                result += " - Static";
            }
            return result;
        }
    }
};
</script>
