<template>
    <div class="ecom-element ecom-shopify-elements ecom-shopify__article-date">
        <div class="ecom-shopify__article-date--wrapper">
            <div
                class="ecom-shopify__article-date--container ecom-flex ecom-al_center"
            >
                <div
                    v-if="data.settings?.icon"
                    class="ecom-shopify__article-date-icon ecom-flex ecom-al_center"
                    v-html="data.settings?.icon"
                />
                <div
                    class="ecom-shopify__article-date--date"
                    v-html="liquid('date')"
                />
            </div>
        </div>
    </div>
</template>

<script>
    import { Liquid, Element } from '@/mixins';

    export default {
        name: 'ArticleAuthor',

        mixins: [Liquid, Element],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            css () {
                return `
                    .ecom-shopify__article-date-icon svg {
                        width: 16px;
                        height: 16px;
                    }
                `;
            },
            page_type () {
                return this.$store.getters['page/params'].page;
            },
            format_date(){
                const format = this.data?.settings?.date_format;
                return format && format !== 'day_first'
                    ? `format: '${format}'`
                    : format === 'day_first'
                        ? `'%e/%-m/%Y'`
                        : `format: 'date'`;
            },
            liquids () {
                return {
                    date: {
                        code: `
                        {% if article and article.created_at != blank %}
                            <div class="ecom-shopify__article-date-text">
                                {{article.${this.type} | time_tag: ${this.format_date}}}
                            </div>
                        {% else %}
                              ${this.exporting === false ? `<div>${this.page_type === 'post' ? this.$t('publish_article_first') : this.$t('select_article_in_setting')}</div>` : ``}
                        {% endif %}
                    `,
                        preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-col-12">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-9 ecom-skeleton-big"></div>
                                </div>
                            </div>
                        </div>
                    `
                    }
                };
            },

            requestShopifyType () {
                return {
                    shopify_type: 'article'
                };
            },
            type(){
                return this.data?.settings?.type??'created_at';
            },
            settings () {
                return [
                    {
                        params: [
                            {
                                type: 'popup',
                                label: this.$t('date_type'),
                                name:'type',
                                options: {
                                    type: 'dropdown',
                                    default: false,
                                    values:{
                                        updated_at: this.$t('updated_at'),
                                        created_at: this.$t('created_at'),
                                        published_at: this.$t('published_at'),
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                name: 'date_format',
                                label: this.$t('date_format'),
                                options: {
                                    type: 'dropdown',
                                    values: {
                                        default: this.$t("date_format_default"),
                                        abbreviated_date: this.$t("date_format_abbreviated_date"),
                                        basic: this.$t("date_format_basic"),
                                        date: this.$t("date_format_date"),
                                        date_at_time: this.$t("date_format_date_at_time"),
                                        on_date: this.$t("date_format_on_date"),
                                        day_first: this.$t("day_first")
                                    }
                                }
                            },
                            {
                                type: 'picker',
                                label: this.$t('icon'),
                                name: 'icon',
                                options: {
                                    type: 'icon',
                                    layout: 'grid',
                                    output: 'value',
                                    multiple: false,
                                    simple: false
                                }
                            },
                            {
                                type: 'choose',
                                label: this.$t('icon_position'),
                                name: 'icon_position',
                                options: {
                                    type: 'align-x',
                                    values: [-1, 1],
                                    visible: {
                                        keep_data: false,
                                        condition: (data) => {
                                            return data['icon'];
                                        }
                                    }
                                },
                                css:{
                                    selector:' .ecom-shopify__article-date-icon',
                                    properties:{
                                        order:''
                                    }
                                }
                            },
                            {
                                type: 'number',
                                label: this.$t('spacing'),
                                name: 'spacing',
                                options: {
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 200
                                        }
                                    },
                                    visible: {
                                        keep_data: false,
                                        condition: (data) => {
                                            return data['icon'];
                                        }
                                    }
                                },
                                css:{
                                    selector:' .ecom-shopify__article-date--container',
                                    properties:{
                                        gap:''
                                    }
                                }
                            },
                        ]
                    }
                ];
            },

            style () {
                return [
                    {
                        group_alias: 'text:spacing',
                        options: {
                            group_name: 'date_text',
                            group_title: this.$t('general'),
                            selector: ' .ecom-shopify__article-date-text time'
                        },
                        modify: {
                            remove: {
                                length: 1,
                                index: 0
                            },
                            params: [
                                {
                                    position: 1,
                                    fields: [
                                        {
                                            alias: 'justify-content',
                                            options: {
                                                label: this.$t('alignment'),
                                                css: {
                                                    selector: 'root .ecom-shopify__article-date--container'
                                                }
                                            }
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias:'icon',
                        options:{
                            group_name: 'icon',
                            group_title: this.$t('icon'),
                            selector: ' .ecom-shopify__article-date-icon',
                        },
                        modify:{
                            params:[
                                {
                                    position:15,
                                    fields:[
                                        {
                                            type: 'line'
                                        },
                                        {
                                            alias:'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                ];
            },

            default() {
                return {
                    settings: {
                        type: "created_at",
                        date_format: "date"
                    },
                    style: {
                        date_text: {
                            textTextAlign: "left"
                        }
                    }
                }
            }
        }
    };
</script>
