<template>
    <div
        v-if="groupSection?.visibility !== false"
        ref="groupWrapper"
        class="group-wrapper"
        :class="classObject"
        :style="groupStyle"
        :section_id="section_id"
        :group_id="groupId"
        @mouseover="handleMouseEnter"
        @mouseleave="handleMouseLeave"
        @click.stop="handleClick"
        @mousedown.stop="handleGroupMouseDown"
        @contextmenu.stop="rightClickMenu"
    >
        <slot></slot>
        <div v-if="isActiveGroup && showGapResizers" class="ecom-group-gap-resizers">
            <div
                v-for="(gapItem, index) in gapItems"
                v-show="gapItem.isVisible"
                :key="gapItem.gapKey || 'gap-' + index"
                class="ecom-group-gap-item"
                :style="gapItem.style"
            >
                <div
                    class="ecom-group-gap-highlight"
                    :style="{ height: gapItem.height + 'px' }"
                ></div>
                <div class="ecom-group-gap-resizer" @mousedown.stop="startResizeGap($event, index)">
                    <span class="ecom-group-gap-resizer__icon"></span>
                    <div
                        v-if="isResizingGap && resizingGapIndex === index"
                        class="ec-block-spacer__value"
                    >
                        {{ gapValue }}px
                    </div>
                </div>
            </div>
        </div>
        <div
            v-show="isActiveGroup"
            v-for="(handle, i) in selectionResizeHandles"
            :key="'selection-handle-' + i"
            class="ecom-selection-resizable-handle"
            :class="handle.class"
            :style="{
                position: 'absolute',
                left: handle.x,
                top: handle.y + '%',
                width: '10px',
                height: '10px',
                background: '#fff',
                border: '1px solid rgb(var(--primary-color-active))',
                borderRadius: '50%',
                cursor: handle.type + '-resize',
                zIndex: 1000,
                transform: 'translate(-50%, -50%)'
            }"
            @mousedown.stop="startSelectionResize($event, handle.type)"
        ></div>
    </div>
</template>

<script>
import { mapGetters } from "vuex";
import { rotate_icon } from "@/assets/icons";
import {
    ensureNumericValue,
    widthPxCalculate,
    isPercentWidth,
    handleSetHistoryGroup
} from "@/plugins/vue-grid-layout/helpers/utils";

export default {
    name: "GroupWrapper",
    props: {
        groupId: {
            type: String,
            required: true
        },
        section_id: {
            type: String,
            required: false
        },
        layout: {
            type: Array,
            required: true
        },
        group: {
            type: Object,
            required: true
        },
        zindex: {
            type: [String, Number],
            required: false,
            default: null
        }
    },
    inject: ["eventBus", "instanceStore", "exporting"],
    emits: ["moved"],
    data() {
        return {
            is: "group_grid",
            icons: {
                rotate: rotate_icon
            },
            bounds: {
                x: 0,
                y: 0,
                w: 0,
                h: 0
            },
            margin: [10, 10],
            cols: 12,
            rowHeight: 30,
            useCssTransforms: true,
            isActive: false,
            isDragging: false,
            dragging: null,
            lastX: NaN,
            lastY: NaN,
            interactObj: null,
            gridParent: null,
            dragTransform: { x: 0, y: 0 },
            dragStartPos: null,
            dragStartBounds: null,
            isRotating: false,
            rotateStart: null,
            initialRotation: 0,
            initialAngle: 0,
            rotationCenter: null,
            groupRotation: 0,
            lastRotateTimestamp: 0,
            initialItemsPosition: null,
            isDraggingPrepared: false,
            containerWidth: 0,
            dragMouseStartPosition: null, // Vị trí chuột khi bắt đầu drag
            dragMouseOffset: null, // Offset giữa vị trí chuột và góc trên bên trái của group
            isDraggingOutOfBounds: false, // Đánh dấu khi kéo ra khỏi container
            newPosition: null, // Vị trí mới sau khi kéo xong
            isMouseMoved: false, // Kiểm tra xem chuột có di chuyển đủ xa để coi là drag không
            isDraggingPrepared: false, // Trạng thái chuẩn bị kéo, chưa phải đang kéo thực sự
            isResizingGroup: false, // Trạng thái resize group
            selectionResizeType: "", // Loại resize (n, s, e, w, ne, nw, se, sw)
            selectionResizeStart: null, // Vị trí chuột lúc bắt đầu resize
            selectionResizeInitial: null,
            selectedItems: [],
            scaleRatio: 1,
            selectionArea: null, // Bounds ban đầu trước khi resize
            showGapResizers: true,
            gapItems: [],
            isResizingGap: false,
            resizingGapIndex: null,
            resizingGapStart: null,
            minGap: 0, // Khoảng cách tối thiểu
            sortedGridItems: [],
            gapValue: 0,
            groupRatio: false,
            timeoutUpdateBounds: null,
            innerZindex:
                this.zindex === "" || this.zindex === null || this.zindex === undefined
                    ? "inherit"
                    : this.zindex
        };
    },

    methods: {
        getGroupBaseZIndex() {
            if (this.section_id && this.groupId) {
                const section = this.sections?.find((s) => s.id === this.section_id);
                if (section && section.groups && section.groups[this.groupId]) {
                    return section.groups[this.groupId].zIndex || 2;
                }
            }
            return 2;
        },

        // method để cập nhật zIndex từ bên ngoài (được gọi từ GroupSettings)
        updateZIndex(newZIndex) {
            this.innerZindex = newZIndex;

            // Cập nhật vào group data
            if (this.section_id && this.groupId) {
                const section = this.sections?.find((s) => s.id === this.section_id);
                if (section && section.groups && section.groups[this.groupId]) {
                    section.groups[this.groupId].zIndex = newZIndex;
                }
            }

            // Emit event để GroupSettings biết đã cập nhật
            this.$emit("zindexed", this.groupId, newZIndex);
            this.eventBus.emit("group-zindex-changed", {
                groupId: this.groupId,
                sectionId: this.section_id,
                zIndex: newZIndex
            });
        },
        /**
         * Handle update group bounds từ auto layout
         */
        handleUpdateGroupBoundsFromAutoLayout(data) {
            if (data.groupId !== this.groupId) return;

            // Cập nhật bounds
            this.bounds = {
                x: data.bounds.x,
                y: data.bounds.y,
                w: data.bounds.w,
                h: data.bounds.h
            };

            // Apply style ngay lập tức
            this.applyGroupWrapperStyle();

            // Tính toán lại gap items nếu cần
            this.$nextTick(() => {
                this.calculateGapItems();
            });

            // Emit event bounds updated
            this.eventBus.emit("group-bounds-updated", {
                groupId: this.groupId,
                bounds: this.bounds,
                source: data.source
            });
        },

        /**
         * Handle restore group bounds từ auto layout cancel
         */
        handleRestoreGroupBoundsFromAutoLayout(data) {
            if (data.groupId !== this.groupId) return;

            // Force tính toán lại bounds từ vị trí items hiện tại
            this.$nextTick(() => {
                this.forceUpdateBounds();
                this.calculateGapItems();
            });
        },
        rightClickMenu(e) {
            if (
                (this.is == 'block' &&
                !this.control) ||
                (this.data?.inGrid && this.data?.layouts[this.screen]?.locked)
            ) {
                return true;
            }

            if (
                !this.isFullScreen &&
                this.contextMenu &&
                !this.contextMenu.current
            ) {
                // Lấy thông tin về scale và wrapper
                const mainWrapper = document.querySelector('.ecom-builder_main-wrapper');
                const iframeRect = window.EComposerBuilder.getBoundingClientRect();

                let scaleFactor = 1;
                let wrapperOffset = { left: 0, top: 0 };

                if (mainWrapper) {
                    const transform = window.getComputedStyle(mainWrapper).transform;
                    if (transform !== 'none') {
                        const matrix = transform.match(/matrix\(([^)]+)\)/);
                        if (matrix) {
                            const values = matrix[1].split(',');
                            scaleFactor = parseFloat(values[0]);
                        }
                    }

                    const wrapperRect = mainWrapper.getBoundingClientRect();
                    wrapperOffset = {
                        left: wrapperRect.left,
                        top: wrapperRect.top
                    };
                }

                // Tính toán vị trí chính xác
                let finalX, finalY;

                if (scaleFactor !== 1) {
                    // Có scale: convert từ iframe coordinate sang document coordinate
                    finalX = wrapperOffset.left + (e.clientX * scaleFactor);
                    finalY = wrapperOffset.top + (e.clientY * scaleFactor);
                } else {
                    // Không có scale: sử dụng cách cũ
                    finalX = e.clientX + iframeRect.left;
                    finalY = e.clientY + iframeRect.top;
                }

                // Tính toán top position
                let top;
                if (finalY + 320 > window.innerHeight) {
                    top = finalY - (finalY + 320 - window.innerHeight);
                } else {
                    top = finalY;
                }

                this.$store.commit('builder/setContextMenu', {
                    current: this,
                    x: finalX,
                    y: top,
                    time: new Date().getTime(),
                    stick: finalX < window.innerWidth - 200 ? 'left' : 'right',
                    bottom: finalY + 320 > window.innerHeight
                });
            }
            e.preventDefault();
        },
        getHighestZIndex(groups) {
            // Lấy z-index cao nhất từ các group hiện tại
            const highestExisting = Math.max(...Object.values(groups).map((g) => g.zIndex || 1), 0);

            // Đảm bảo trả về ít nhất là 2
            return Math.max(highestExisting, 1) + 1;
        },
        dropOut() {
            this.eventBus.emit("groupDelete", {
                groupId: this.groupId,
                sectionId: this.section_id
            });
        },
        duplicate() {
            this.eventBus.emit("groupDuplicate", {
                groupId: this.groupId,
                sectionId: this.section_id
            });
        },
        cloneMe() {
            const newBlocks = [];
            const section = this.instanceStore.get(this.section_id),
                newGroupId = `gr-${crypto.randomUUID().slice(0, 8)}`,
                newGroup = JSON.parse(JSON.stringify(this.group)),
                highestZ = this.getHighestZIndex(section.data.groups);
            newGroup.blocks = [];
            newGroup.zIndex = Math.max(highestZ, 2);
            // Tạo bản sao cho mỗi block
            for (const blockId of this.group.blocks) {
                const originalBlock = section.data.blocks.find((b) => b.id === blockId);

                if (originalBlock) {
                    // Tạo ID mới
                    const newBlockId = `ecom-${crypto.randomUUID().slice(0, 8)}`;

                    // Tạo deep clone của block
                    const newBlock = JSON.parse(JSON.stringify(originalBlock));
                    newBlock.id = newBlockId;
                    newBlock.group_id = newGroupId;
                    newBlocks.push(newBlock);
                    newGroup.blocks.push(newBlockId);
                }
            }

            return { blocks: newBlocks, group: newGroup, idGroup: newGroupId };
        },
        areAllGapsEqual() {
            // Nếu không có gap hoặc chỉ có 1 gap, return false
            if (!this.gapItems || this.gapItems.length <= 1) {
                return false;
            }

            // Lọc ra các gap visible (không bị đè lên nhau)
            const visibleGaps = this.gapItems.filter((gap) => gap.isVisible && gap.gap >= 0);

            // Nếu không có gap visible hoặc chỉ có 1 gap visible, return false
            if (visibleGaps.length <= 1) {
                return false;
            }

            // Lấy giá trị gap đầu tiên làm reference
            const firstGapValue = visibleGaps[0].gap;

            // Tolerance để so sánh số thực (1px)
            const tolerance = 1;

            // Kiểm tra tất cả gap có bằng nhau không (trong phạm vi tolerance)
            return visibleGaps.every((gap) => Math.abs(gap.gap - firstGapValue) <= tolerance);
        },
        forceCalculateGapItems() {
            if (!this.isActiveGroup) return;

            // Đảm bảo có đủ grid items
            if (!this.gridItems || this.gridItems.length < 2) {
                this.showGapResizers = false;
                this.gapItems = [];
                return;
            }

            // Đợi DOM ổn định trước khi tính toán
            this.$nextTick(() => {
                setTimeout(() => {
                    this.calculateGapItems();
                }, 50);
            });
        },
        calculateGapItems() {
            // Kiểm tra nếu không có đủ grid items
            if (!this.gridItems || this.gridItems.length < 2) {
                this.showGapResizers = false;
                this.gapItems = [];
                return;
            }

            // Lấy chiều rộng container cho tính toán
            const containerWidth = this.containerWidth;

            // Lấy vị trí của group wrapper
            const groupX = this.bounds.x; // % từ trái
            const groupY = this.bounds.y; // px từ trên

            // Lấy tất cả grid items và sắp xếp theo vị trí top
            const gridItems = this.gridItems
                .map((item) => {
                    // Lấy giá trị gốc từ data-attributes
                    const originalLeft = parseFloat(item.getAttribute("data-original-left") || "0");
                    const originalTop = parseFloat(item.getAttribute("data-original-top") || "0");
                    const originalHeight = parseFloat(
                        item.getAttribute("data-original-height") || "0"
                    );
                    const id = item.getAttribute("data-id");

                    if (isNaN(originalTop) || isNaN(originalHeight) || !id) {
                        return null;
                    }

                    // Tính bottom trong hệ tọa độ gốc
                    const bottom = originalTop + originalHeight;

                    // Tính vị trí trong tọa độ tương đối với group wrapper
                    const leftPx = (originalLeft / 100) * containerWidth;
                    const relativeXPx = leftPx - (groupX / 100) * containerWidth;
                    const relativeYPx = originalTop - groupY;
                    const relativeBottomPx = relativeYPx + originalHeight;

                    return {
                        id,
                        originalTop,
                        originalHeight,
                        bottom, // Bottom trong hệ tọa độ gốc
                        element: item,
                        // Vị trí tương đối so với group
                        relativeTop: relativeYPx,
                        relativeBottom: relativeBottomPx
                    };
                })
                .filter((item) => item !== null)
                .sort((a, b) => a.originalTop - b.originalTop);

            if (gridItems.length < 2) {
                this.showGapResizers = false;
                this.gapItems = [];
                return;
            }

            this.sortedGridItems = gridItems;

            // Tạo mảng các gap mới dựa trên vị trí hiện tại
            const newGaps = [];

            for (let i = 0; i < gridItems.length - 1; i++) {
                const currentItem = gridItems[i];
                const nextItem = gridItems[i + 1];

                // Gap là khoảng cách từ bottom của item trên đến top của item dưới
                // Không dùng Math.max để giữ nguyên giá trị âm
                const gap = nextItem.originalTop - currentItem.bottom;

                // Tạo unique key cho gap này dựa trên ID của 2 items
                const gapKey = `${currentItem.id}-${nextItem.id}`;

                // Tạo gap object, lưu cả gap âm
                const gapObject = {
                    topItemId: currentItem.id,
                    bottomItemId: nextItem.id,
                    gapKey: gapKey,
                    // Lưu vị trí trong hệ tọa độ gốc
                    originalTop: currentItem.bottom,
                    gap: gap, // Giữ nguyên giá trị, có thể âm
                    height: Math.max(0, gap), // Chỉ height mới không âm để hiển thị
                    isVisible: gap > 0, // Flag để xác định có hiển thị không
                    isOverlapping: gap < 0, // Flag mới để xác định có đè lên nhau không
                    // Style dùng vị trí tương đối so với group
                    style: {
                        position: "absolute",
                        left: "0",
                        top: `${currentItem.relativeBottom}px`,
                        width: "100%",
                        height: `${Math.max(0, gap)}px`,
                        pointerEvents: gap > 0 ? "all" : "none",
                        display: gap > 0 ? "block" : "none"
                    }
                };

                newGaps.push(gapObject);
            }

            // Cập nhật gapItems một cách thông minh để duy trì tính ổn định
            this.updateGapItemsStably(newGaps);

            // SỬA: Chỉ hiển thị resizers khi tất cả gap đều bằng nhau
            this.showGapResizers = this.areAllGapsEqual();
        },
        updateGapItemsStably(newGaps) {
            // Nếu chưa có gapItems, tạo mới
            if (!this.gapItems || this.gapItems.length === 0) {
                this.gapItems = [...newGaps];
                return;
            }

            // Tạo map để tra cứu nhanh các gap hiện tại
            const currentGapMap = new Map();
            this.gapItems.forEach((gap, index) => {
                if (gap.gapKey) {
                    currentGapMap.set(gap.gapKey, { gap, index });
                }
            });

            // Mảng kết quả sẽ có cùng thứ tự với newGaps
            const resultGaps = [];

            newGaps.forEach((newGap, newIndex) => {
                const existing = currentGapMap.get(newGap.gapKey);

                if (existing) {
                    // Gap đã tồn tại, cập nhật thông tin
                    const updatedGap = {
                        ...existing.gap,
                        originalTop: newGap.originalTop,
                        gap: newGap.gap,
                        height: newGap.height,
                        isVisible: newGap.isVisible,
                        isOverlapping: newGap.isOverlapping, // Thêm flag mới
                        style: newGap.style
                    };
                    resultGaps.push(updatedGap);
                } else {
                    // Gap mới, thêm vào
                    resultGaps.push(newGap);
                }
            });

            // Cập nhật mảng gapItems
            this.gapItems = resultGaps;
        },
        startResizeGap(e, index) {
            // Kiểm tra xem gap có visible không
            const gapItem = this.gapItems[index];
            if (!gapItem || !gapItem.isVisible) {
                return; // Không xử lý gap không visible
            }

            // Cập nhật scale ratio
            this.updateScaleRatio();

            // Đánh dấu đang resize gap
            this.isResizingGap = true;
            this.resizingGapIndex = index;

            this.gapValue = Math.round(gapItem.gap);

            // Lưu thông tin về tất cả các gap ban đầu (bao gồm cả gap không visible)
            // để đảm bảo index mapping chính xác
            const initialGaps = this.gapItems.map((gap) => ({
                id: gap.topItemId + "-" + gap.bottomItemId,
                gap: gap.gap,
                originalTop: gap.originalTop,
                gapKey: gap.gapKey,
                isVisible: gap.isVisible
            }));

            // Lưu vị trí chuột ban đầu và giá trị gap ban đầu
            this.resizingGapStart = {
                mouseY: e.clientY,
                gap: gapItem.gap,
                allGaps: initialGaps
            };

            // Lưu vị trí ban đầu của tất cả các items
            this.initialItemsPositionBeforeGapResize = this.sortedGridItems.map((item) => ({
                id: item.id,
                originalTop: item.originalTop,
                bottom: item.bottom,
                height: item.originalHeight
            }));

            // Thêm class để hiển thị trạng thái đang resize
            this.$refs.groupWrapper.classList.add("ecom-group-resizing-gap");

            // Thêm event listeners
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.addEventListener("mousemove", this.handleResizeGap);
            iframeDoc.addEventListener("mouseup", this.endResizeGap);

            e.preventDefault();
            e.stopPropagation();
        },

        endResizeGap(e) {
            if (!this.isResizingGap) return;
            const section = this.sections.find((s) => s.id == this.section_id);
            handleSetHistoryGroup(section, this.group.blocks, this.screen, "moved", this.groupId);
            // Gỡ bỏ event listeners
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.removeEventListener("mousemove", this.handleResizeGap);
            iframeDoc.removeEventListener("mouseup", this.endResizeGap);

            // Xóa class trạng thái resize
            this.$refs.groupWrapper.classList.remove("ecom-group-resizing-gap");

            // Đặt lại trạng thái
            this.isResizingGap = false;
            this.resizingGapIndex = null;
            this.resizingGapStart = null;
            this.gapValue = 0;
            // Emit sự kiện "moved" cho từng grid item
            this.sortedGridItems.forEach((item) => {
                const id = item.id;
                const newTop = parseFloat(item.originalTop);
                const newLeft = parseFloat(item.element.getAttribute("data-original-left"));

                // Tìm GridItem instance để emit sự kiện moved
                const gridItem = this.findGridItem(id);
                if (gridItem) {
                    gridItem.$emit("moved", id, newLeft, newTop);
                }
            });

            // Cập nhật layout cuối cùng
            this.updateFinalLayoutAfterGapResize();

            e.preventDefault();
            e.stopPropagation();
        },
        handleResizeGap(e) {
            if (!this.isResizingGap || this.isLockedGroup) return;
            if (this.isLocked) {
                this.$store.commit("builder/setShowNoticeLockmode", true);
                return;
            }
            const index = this.resizingGapIndex;
            const initial = this.resizingGapStart;

            // Tính toán delta khoảng cách
            const deltaY = (e.clientY - initial.mouseY) / this.scaleRatio;

            // Tính gap mới cho gap đang được resize
            const newGap = Math.max(this.minGap, initial.gap + deltaY);

            this.gapValue = Math.round(newGap);
            // Tính chính xác deltaGap (có thể bị giới hạn bởi minGap)
            const actualDeltaGap = newGap - initial.gap;
            // Thay đổi height section khi thoả mãn các điều kiện
            const { maxYInGroup, maxY, lastItemId } = this.layout.reduce(
                (acc, item) => {
                    const itemY = item.top + item.height;
                    const isInGroup = this.group.blocks.includes(item.i);

                    if (isInGroup && itemY > acc.maxYInGroup) {
                        acc.maxYInGroup = itemY;
                        acc.lastItemId = item.i;
                    }

                    if (itemY > acc.maxY) {
                        acc.maxY = itemY;
                        acc.lastItemId = item.i;
                    }

                    return acc;
                },
                { maxYInGroup: 0, maxY: 0, lastItemId: null }
            );

            // Tính toán chiều cao mới cho group
            const newHeight = maxYInGroup + actualDeltaGap * this.gapItems.length;

            // Kiểm tra điều kiện cập nhật height
            const shouldUpdateHeight =
                this.$parent?.$refs.item && !this.gridParent.data?.settings?.["min-height"];

            if (shouldUpdateHeight) {
                // Cập nhật height dựa trên điều kiện
                if (this.group.blocks.includes(lastItemId) && newHeight > maxY) {
                    this.$parent.$refs.item.style.height = `${newHeight}px`;
                } else if (parseInt(this.$parent.$refs.item.style.height) !== maxY) {
                    this.$parent.$refs.item.style.height = `${maxY}px`;
                }
            }

            // Áp dụng delta này cho các gap có thể thay đổi
            for (let i = 0; i < this.gapItems.length; i++) {
                const currentGap = this.gapItems[i];
                const initialGap = initial.allGaps[i];

                // Kiểm tra xem initialGap có tồn tại không
                if (!initialGap) {
                    console.warn(`Missing initial gap data for index ${i}`);
                    continue;
                }

                // Chỉ cập nhật gap nếu gap ban đầu >= 0 (không đè lên nhau)
                if (initialGap.gap >= 0) {
                    // Tính gap mới cho mỗi gap, đảm bảo không nhỏ hơn minGap
                    const newGapValue = Math.max(this.minGap, initialGap.gap + actualDeltaGap);

                    // Cập nhật gap
                    currentGap.gap = newGapValue;
                    currentGap.height = newGapValue;
                    currentGap.style.height = `${newGapValue}px`;

                    // Cập nhật isVisible status
                    currentGap.isVisible = newGapValue > 0;
                    currentGap.isOverlapping = false;
                    currentGap.style.display = newGapValue > 0 ? "block" : "none";
                    currentGap.style.pointerEvents = newGapValue > 0 ? "all" : "none";
                } else {
                    // Gap ban đầu < 0 (đè lên nhau), giữ nguyên
                    currentGap.gap = initialGap.gap;
                    currentGap.height = 0;
                    currentGap.style.height = "0px";
                    currentGap.isVisible = false;
                    currentGap.isOverlapping = true;
                    currentGap.style.display = "none";
                    currentGap.style.pointerEvents = "none";
                }
            }

            // Di chuyển tất cả các items dựa trên thay đổi gap
            this.updateItemPositionsAfterGapChange(actualDeltaGap);

            // Cập nhật bounds của group
            this.handleUpdateBounds();
        },
        updateItemPositionsAfterGapChange(deltaGap) {
            if (!this.sortedGridItems || this.sortedGridItems.length <= 1) return;

            const updatedItems = [];

            // Tạo một mảng để theo dõi items nào được phép di chuyển
            const canMoveItem = new Array(this.sortedGridItems.length).fill(true);

            // Kiểm tra gap ban đầu để xác định item nào không được di chuyển
            for (let i = 0; i < this.gapItems.length; i++) {
                const initialGap = this.resizingGapStart.allGaps[i];
                if (initialGap && initialGap.gap < 0) {
                    // Nếu gap ban đầu < 0 (đè lên nhau), item phía dưới không được di chuyển
                    canMoveItem[i + 1] = false;
                }
            }

            // Cập nhật các item từ thứ hai trở đi
            for (let i = 1; i < this.sortedGridItems.length; i++) {
                const item = this.sortedGridItems[i];
                const initialPosition = this.initialItemsPositionBeforeGapResize[i];

                if (!initialPosition) {
                    console.warn(`Missing initial position for item index ${i}`);
                    continue;
                }

                let newTop;

                if (!canMoveItem[i]) {
                    // Item này không được di chuyển (vì đè lên item trước đó)
                    newTop = initialPosition.originalTop;
                } else {
                    // Tính số lượng gap có thể di chuyển phía trên item này
                    let movableGapsAbove = 0;
                    for (let j = 0; j < i; j++) {
                        const initialGap = this.resizingGapStart.allGaps[j];
                        if (initialGap && initialGap.gap >= 0) {
                            movableGapsAbove++;
                        }
                    }

                    // Tính vị trí mới: vị trí ban đầu + (số gap có thể di chuyển * delta)
                    newTop = initialPosition.originalTop + movableGapsAbove * deltaGap;
                }

                // Cập nhật vị trí
                item.originalTop = newTop;
                item.relativeTop = newTop - this.bounds.y;
                item.bottom = newTop + item.originalHeight;
                item.relativeBottom = item.relativeTop + item.originalHeight;

                // Cập nhật data-attribute
                item.element.setAttribute("data-original-top", newTop);

                // Thêm vào danh sách cần cập nhật
                updatedItems.push({
                    id: item.id,
                    top: newTop
                });
            }

            // Emit sự kiện để cập nhật grid item
            if (updatedItems.length > 0) {
                updatedItems.forEach((item) => {
                    this.eventBus.emit("update-grid-item", {
                        id: item.id,
                        top: item.top
                    });
                });
            }

            // Cập nhật vị trí của các gap sau khi items đã di chuyển
            this.updateGapPositionsAfterItemMove();
        },

        // Cập nhật vị trí gap sau khi items di chuyển
        updateGapPositionsAfterItemMove() {
            for (let i = 0; i < this.gapItems.length; i++) {
                const gap = this.gapItems[i];
                const topItem = this.sortedGridItems[i];

                if (topItem && gap) {
                    // Cập nhật originalTop của gap dựa trên bottom của item phía trên
                    gap.originalTop = topItem.bottom;

                    // Cập nhật style position tương đối với group
                    gap.style.top = `${topItem.relativeBottom}px`;
                }
            }
        },
        calculateAverageGap() {
            if (!this.gapItems || this.gapItems.length === 0) return this.minGap;

            let totalGap = 0;
            this.gapItems.forEach((gap) => {
                totalGap += gap.gap;
            });

            return totalGap / this.gapItems.length;
        },

        // Di chuyển các items phía dưới khoảng cách
        moveItemsBelowGap(gapIndex, delta) {
            const gapItem = this.gapItems[gapIndex];
            if (!gapItem) return;

            // Lấy originalTop của gap - đây là vị trí trong hệ tọa độ gốc
            const gapOriginalTop = gapItem.originalTop;

            // Mảng lưu trữ các item đã cập nhật để cập nhật lại một lần
            const updatedItems = [];

            // Di chuyển tất cả các grid items phía dưới gap
            this.sortedGridItems.forEach((item) => {
                // Nếu item nằm dưới gap trong hệ tọa độ gốc
                if (item.originalTop > gapOriginalTop) {
                    // Tính toán vị trí mới trong hệ tọa độ gốc
                    const newOriginalTop = item.originalTop + delta;

                    // Cập nhật data-attribute
                    item.element.setAttribute("data-original-top", newOriginalTop);

                    // Cập nhật thông tin trong sortedGridItems
                    item.originalTop = newOriginalTop;
                    item.bottom = newOriginalTop + item.originalHeight;

                    // Cập nhật vị trí tương đối
                    item.relativeTop = newOriginalTop - this.bounds.y;
                    item.relativeBottom = item.relativeTop + item.originalHeight;

                    // Thêm vào danh sách cần cập nhật
                    updatedItems.push({
                        id: item.id,
                        top: newOriginalTop
                    });
                }
            });

            // Emit sự kiện để cập nhật grid item trong một lần
            if (updatedItems.length > 0) {
                updatedItems.forEach((item) => {
                    this.eventBus.emit("update-grid-item", {
                        id: item.id,
                        top: item.top
                    });
                });
            }

            // Cập nhật vị trí của các gap phía dưới
            for (let i = gapIndex + 1; i < this.gapItems.length; i++) {
                this.gapItems[i].originalTop += delta;
                // Cập nhật style với vị trí tương đối
                this.gapItems[i].style.top = `${this.gapItems[i].originalTop - this.bounds.y}px`;
            }

            // Cập nhật bounds của group ngay lập tức để tránh hiệu ứng giật
            this.updateBounds();
        },

        // Cập nhật layout sau khi resize khoảng cách
        updateFinalLayoutAfterGapResize() {
            // Emit sự kiện "moved" cho từng grid item
            this.sortedGridItems.forEach((item) => {
                const id = item.id;
                const newTop = parseFloat(item.originalTop);
                const newLeft = parseFloat(item.element.getAttribute("data-original-left"));

                // Tìm GridItem instance để emit sự kiện moved
                const gridItem = this.findGridItem(id);
                if (gridItem) {
                    gridItem.$emit("moved", id, newLeft, newTop);
                }
            });

            // Xóa biến lưu trữ tạm thời
            this.initialItemsPositionBeforeGapResize = null;

            // Cập nhật layout cuối cùng
            const gridLayout = this.$parent;
            if (gridLayout && typeof gridLayout.updateAllLayouts === "function") {
                gridLayout.updateAllLayouts();
            }

            // Emit sự kiện cập nhật layout
            this.eventBus.emit("layout-updated", this.layout);
        },
        getIframeScale() {
            try {
                const iframeDoc = this.idoc;
                if (!iframeDoc || !iframeDoc.body) return 1;

                const style = window.getComputedStyle(iframeDoc.body);
                const transform = style.transform || style.webkitTransform;

                if (!transform || transform === "none") return 1;

                // Trích xuất giá trị scale từ ma trận transform
                const matrixMatch = transform.match(/matrix\((.+)\)/);
                if (matrixMatch) {
                    const matrix = matrixMatch[1].split(", ").map(parseFloat);
                    return matrix[0]; // Scale là giá trị đầu tiên trong ma trận
                }

                // Trích xuất trực tiếp từ scale
                const scaleMatch = transform.match(/scale\((.+)\)/);
                if (scaleMatch) {
                    return parseFloat(scaleMatch[1]);
                }

                return 1;
            } catch (e) {
                console.error("Error getting iframe scale:", e);
                return 1;
            }
        },

        updateScaleRatio() {
            this.scaleRatio = this.getIframeScale();
        },
        calculateSelectionArea() {
            const ids = this.group.blocks;
            this.selectedItems = [];

            this.layout.forEach((item) => {
                // Bỏ qua các placeholder
                if (!item.i || !ids.includes(item.i)) {
                    return;
                }
                if (item.options?.ratioSize && !this.groupRatio) {
                    this.groupRatio = true;
                }
                this.selectedItems.push(item);
            });

            // Khởi tạo selectionArea dựa trên bounds hiện tại
            this.selectionArea = {
                minX: this.bounds.x,
                minY: this.bounds.y,
                maxX: this.bounds.x + this.bounds.w,
                maxY: this.bounds.y + this.bounds.h
            };
        },
        startSelectionResize(e, type) {
            if (!this.selectionArea) {
                this.calculateSelectionArea();
                this.selectionArea = {
                    minX: this.bounds.x,
                    minY: this.bounds.y,
                    maxX: this.bounds.x + this.bounds.w,
                    maxY: this.bounds.y + this.bounds.h
                };
            }
            this.updateSelectionAreaFromItems();
            // Bắt đầu resize group
            this.selectionResizeType = type;

            // Lưu vị trí chuột ban đầu
            const rect = this.$refs.groupWrapper.offsetParent.getBoundingClientRect();
            this.selectionResizeStart = {
                x: e.clientX - rect.left,
                y: e.clientY - rect.top
            };

            // Lưu kích thước và vị trí ban đầu của group
            this.selectionResizeInitial = JSON.parse(JSON.stringify(this.selectionArea));

            // Lưu vị trí ban đầu của tất cả các items trong group
            this.initialItemsPosition = this.gridItems.map((item) => {
                return {
                    i: item.getAttribute("data-id"),
                    left: this.ensureNumericValue(item.getAttribute("data-original-left")),
                    top: this.ensureNumericValue(item.getAttribute("data-original-top")),
                    width: item.getAttribute("data-original-width"),
                    height: this.ensureNumericValue(item.getAttribute("data-original-height")),
                    rotation: this.ensureNumericValue(item.getAttribute("data-rotation") || 0)
                };
            });
            const section = this.sections.find((s) => s.id === this.section_id);
            this.oldSection = JSON.parse(JSON.stringify(section));
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.addEventListener("mousemove", this.handleSelectionResize);
            iframeDoc.addEventListener("mouseup", this.endSelectionResize);

            e.preventDefault();
            e.stopPropagation();
        },

        // Xử lý khi resize selection
        handleSelectionResize(e) {
            this.isResizingGroup = true;
            if (!this.isResizingGroup) return;

            const rect = this.$refs.groupWrapper.offsetParent.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            const hasMoved =
                Math.abs(mouseX - this.selectionResizeStart.x) > 3 ||
                Math.abs(mouseY - this.selectionResizeStart.y) > 3;
            if (!hasMoved || this.isLockedGroup) return;
            if (this.isLockedGroup && hasMoved) {
                this.$store.commit("builder/setShowNoticeLockmode", true);
                return;
            }
            // Tính delta từ vị trí ban đầu
            const deltaX = mouseX - this.selectionResizeStart.x;
            const deltaY = mouseY - this.selectionResizeStart.y;

            // Lấy chiều rộng container để tính toán chính xác
            const containerWidth = this.containerWidth;
            const containerHeight = this.$refs.groupWrapper.offsetParent.offsetHeight || 1000;

            // Hệ số giảm tốc để chuyển động mượt mà hơn
            const dampingFactor = 1.0;
            const scaledDeltaX = deltaX * dampingFactor;
            const scaledDeltaY = deltaY * dampingFactor;

            // Chuyển delta X từ pixel sang phần trăm
            const deltaXPercent = (scaledDeltaX / containerWidth) * 100;

            // Tính toán kích thước ban đầu của vùng chọn
            const initialWidth =
                this.selectionResizeInitial.maxX - this.selectionResizeInitial.minX;
            const initialHeight =
                this.selectionResizeInitial.maxY - this.selectionResizeInitial.minY;

            // Khai báo biến để lưu kích thước và vị trí mới - THAY ĐỔI từ const sang let
            let newWidth = initialWidth;
            let newHeight = initialHeight;
            let offsetX = 0;
            let offsetY = 0;

            // Xác định thay đổi kích thước dựa trên loại resize
            switch (this.selectionResizeType) {
                case "n": // Resize cạnh trên
                    newHeight = initialHeight - scaledDeltaY;
                    offsetY = scaledDeltaY;
                    break;
                case "s": // Resize cạnh dưới
                    newHeight = initialHeight + scaledDeltaY;
                    break;
                case "e": // Resize cạnh phải
                    newWidth = initialWidth + deltaXPercent;
                    break;
                case "w": // Resize cạnh trái
                    newWidth = initialWidth - deltaXPercent;
                    offsetX = deltaXPercent;
                    break;
                case "nw": // Resize từ góc trên-trái
                    newHeight = initialHeight - scaledDeltaY;

                    if (this.groupRatio) {
                        const aspectRatio = initialWidth / initialHeight;
                        // Tính width mới dựa trên height mới và tỷ lệ khung hình
                        newWidth = newHeight * aspectRatio;
                        // Tính offsetX để giữ cạnh phải đứng yên
                        offsetX = initialWidth - newWidth;
                    } else {
                        newWidth = initialWidth - deltaXPercent;
                        offsetX = deltaXPercent;
                    }

                    // Tính offsetY để giữ cạnh dưới đứng yên
                    offsetY = initialHeight - newHeight;
                    break;
                case "ne": // Resize từ góc trên-phải
                    // Tính toán height mới dựa trên deltaY
                    newHeight = initialHeight - scaledDeltaY;

                    if (this.groupRatio) {
                        const aspectRatio = initialWidth / initialHeight;
                        // Tính width mới dựa trên height mới và tỷ lệ khung hình
                        newWidth = newHeight * aspectRatio;
                    } else {
                        newWidth = initialWidth + deltaXPercent;
                    }

                    // Tính offsetY để giữ cạnh dưới đứng yên
                    offsetY = initialHeight - newHeight;
                    break;
                case "sw": // Resize góc dưới-trái
                    newWidth = initialWidth - deltaXPercent;
                    newHeight = initialHeight + scaledDeltaY;
                    offsetX = deltaXPercent;
                    break;
                case "se": // Resize góc dưới-phải
                    newWidth = initialWidth + deltaXPercent;
                    newHeight = initialHeight + scaledDeltaY;
                    break;
            }

            if (this.groupRatio) {
                const initialWidth =
                    this.selectionResizeInitial.maxX - this.selectionResizeInitial.minX;
                const initialHeight =
                    this.selectionResizeInitial.maxY - this.selectionResizeInitial.minY;
                const aspectRatio = initialWidth / initialHeight;

                // Lưu lại giá trị trước khi áp dụng tỷ lệ
                const widthBeforeRatio = newWidth;
                const heightBeforeRatio = newHeight;

                // Quyết định sử dụng chiều rộng hay chiều cao làm gốc tính toán
                const useWidth =
                    this.selectionResizeType.includes("e") ||
                    this.selectionResizeType.includes("w");

                if (useWidth) {
                    newHeight = newWidth / aspectRatio;
                } else {
                    // Nếu dùng height làm gốc, tính width mới
                    const calculatedWidth = newHeight * aspectRatio;
                    // Chỉ cập nhật newWidth nếu giá trị mới hợp lý
                    if (
                        Math.abs(calculatedWidth - widthBeforeRatio) <
                        Math.abs(newWidth - widthBeforeRatio)
                    ) {
                        newWidth = calculatedWidth;
                    }
                }
            }
            // Đảm bảo kích thước không âm hoặc quá nhỏ
            newWidth = Math.max(5, newWidth);
            newHeight = Math.max(5, newHeight);

            // Tính tỷ lệ scale cho width và height - THAY ĐỔI từ const sang let
            let scaleX = newWidth / initialWidth;
            let scaleY = newHeight / initialHeight;

            // THÊM MỚI: Biến để theo dõi xem có đạt đến giới hạn hay không
            let hitRightBound = false;
            let hitLeftBound = false;
            let hitTopBound = false;
            let hitBottomBound = false;

            // Kiểm tra xem item có vượt quá giới hạn container không
            this.gridItems.forEach((item) => {
                // Lấy giá trị ban đầu
                const itemId = item.getAttribute("data-id");
                const initialPos = this.initialItemsPosition.find((pos) => pos.i === itemId);
                if (!initialPos) return;

                // Tính toán vị trí tương đối so với điểm gốc của selection
                const relativeX = initialPos.left - this.selectionResizeInitial.minX;
                const relativeY = initialPos.top - this.selectionResizeInitial.minY;

                // Áp dụng tỷ lệ scale và offset để dự tính vị trí mới
                const newRelativeX = relativeX * scaleX;
                const newRelativeY = relativeY * scaleY;
                const newLeft = this.selectionResizeInitial.minX + offsetX + newRelativeX;
                const newTop = this.selectionResizeInitial.minY + offsetY + newRelativeY;

                // Tính width mới
                let newWidthValue;
                const isPercentWidth =
                    typeof initialPos.width === "string" && initialPos.width.includes("%");

                if (isPercentWidth) {
                    newWidthValue = parseFloat(initialPos.width) * scaleX;
                } else {
                    newWidthValue = ensureNumericValue(initialPos.width) * scaleX;
                    // Chuyển đổi sang % để kiểm tra
                    newWidthValue = (newWidthValue / containerWidth) * 100;
                }

                // Tính height mới
                const newHeightValue = initialPos.height * scaleY;

                // Kiểm tra các giới hạn
                if (newLeft < 0) {
                    hitLeftBound = true;
                }

                if (newLeft + newWidthValue > 100) {
                    hitRightBound = true;
                }

                if (newTop < 0) {
                    hitTopBound = true;
                }

                if (newTop + newHeightValue > containerHeight) {
                    hitBottomBound = true;
                }
            });

            // Xử lý giới hạn để grid item không bị co lại khi đạt đến mép container
            if (hitRightBound) {
                if (this.selectionResizeType.includes("e")) {
                    // Nếu resize từ bên phải và đạt đến giới hạn, giữ nguyên kích thước hiện tại
                    const maxAllowedWidth =
                        this.selectionResizeInitial.maxX > 100
                            ? initialWidth
                            : 100 - this.selectionResizeInitial.minX;

                    newWidth = Math.min(newWidth, maxAllowedWidth);
                    scaleX = newWidth / initialWidth;
                }
            }

            if (hitLeftBound) {
                if (this.selectionResizeType.includes("w")) {
                    // Nếu resize từ bên trái và đạt đến giới hạn, điều chỉnh offset để không vượt quá
                    const minAllowedOffset = -this.selectionResizeInitial.minX;
                    offsetX = Math.max(offsetX, minAllowedOffset);

                    // Tính lại width dựa trên offset đã điều chỉnh
                    newWidth = Math.min(newWidth, initialWidth + this.selectionResizeInitial.minX);
                    scaleX = newWidth / initialWidth;
                }
            }

            if (hitBottomBound) {
                if (this.selectionResizeType.includes("s")) {
                    // Nếu resize từ dưới lên và đạt đến giới hạn, giữ nguyên kích thước hiện tại
                    const maxAllowedHeight = containerHeight - this.selectionResizeInitial.minY;
                    if (this.gridParent.data?.settings?.["min-height"]) {
                        newHeight = Math.min(newHeight, maxAllowedHeight);
                    }
                    scaleY = newHeight / initialHeight;
                }
            }

            if (hitTopBound) {
                if (this.selectionResizeType.includes("n")) {
                    // Nếu resize từ trên xuống và đạt đến giới hạn, điều chỉnh offset để không vượt quá
                    const minAllowedOffset = -this.selectionResizeInitial.minY;
                    offsetY = Math.max(offsetY, minAllowedOffset);

                    // Tính lại height dựa trên offset đã điều chỉnh
                    newHeight = Math.min(
                        newHeight,
                        initialHeight + this.selectionResizeInitial.minY
                    );
                    scaleY = newHeight / initialHeight;
                }
            }
            // Đảm bảo tỷ lệ scale không quá nhỏ
            scaleX = Math.max(0.1, scaleX);
            scaleY = Math.max(0.1, scaleY);

            // Tính toán maxY để điều chỉnh height section
            let maxY = 0,
                maxBottom = 0;
            this.layout.forEach((item) => {
                if (!this.group.blocks.includes(item.i)) {
                    let itemY = item.top + item.height;
                    if (itemY > maxY) {
                        maxY = itemY;
                    }
                }
            });
            // Cập nhật từng item trong group với giá trị đã điều chỉnh
            this.gridItems.forEach((item) => {
                // Lấy ID của item
                const itemId = item.getAttribute("data-id");

                // Tìm vị trí ban đầu của item
                const initialPos = this.initialItemsPosition.find((pos) => pos.i === itemId);
                if (!initialPos) return;

                // Tính toán vị trí tương đối so với điểm gốc của selection
                const relativeX = initialPos.left - this.selectionResizeInitial.minX;
                const relativeY = initialPos.top - this.selectionResizeInitial.minY;

                // Áp dụng tỷ lệ scale cho vị trí tương đối - đã điều chỉnh trong giới hạn
                const newRelativeX = relativeX * scaleX;
                const newRelativeY = relativeY * scaleY;

                // Tính toán vị trí mới sau khi scale - đã điều chỉnh trong giới hạn
                const newLeft = this.selectionResizeInitial.minX + offsetX + newRelativeX;
                const newTop = this.selectionResizeInitial.minY + offsetY + newRelativeY;

                // XỬ LÝ ĐƠN VỊ WIDTH (% hoặc px)
                const initialWidth = initialPos.width;
                let newWidthValue;
                let isPercentWidth = false;

                if (typeof initialWidth === "string" && initialWidth.includes("%")) {
                    // Nếu width ban đầu là %
                    isPercentWidth = true;
                    const percentValue = parseFloat(initialWidth);

                    // Scale giá trị % dựa trên tỷ lệ resize điều chỉnh
                    newWidthValue = percentValue * scaleX;

                    // Giới hạn giá trị % không quá nhỏ
                    newWidthValue = Math.max(1, newWidthValue);

                    // Format với đơn vị %
                    const formattedWidth = `${newWidthValue}%`;

                    // Cập nhật vào DOM
                    item.setAttribute("data-original-width", formattedWidth);
                } else {
                    // Nếu width ban đầu là px
                    const widthInPx = ensureNumericValue(initialWidth);

                    // Scale giá trị px với tỷ lệ điều chỉnh
                    newWidthValue = widthInPx * scaleX;

                    // Giới hạn giá trị px không quá nhỏ
                    newWidthValue = Math.max(10, newWidthValue);

                    // Cập nhật vào DOM
                    item.setAttribute("data-original-width", newWidthValue);
                }

                // Tính toán height mới (luôn là px)
                let newHeightValue = initialPos.height * scaleY;
                newHeightValue = Math.max(10, newHeightValue); // Đảm bảo không nhỏ hơn 10px

                // Xử lý tỷ lệ khung hình nếu cần
                const instanceStore = this.instanceStore?.get(itemId);
                if (instanceStore && instanceStore.options && instanceStore.options.autoHeight) {
                    // Tính tỷ lệ chiều cao theo chiều rộng ban đầu
                    const aspectRatio = initialPos.height / ensureNumericValue(initialWidth);

                    // Tính height mới dựa trên width mới và tỷ lệ khung hình
                    if (isPercentWidth) {
                        // Nếu width là %, cần chuyển về px để tính height
                        const newWidthPx = (newWidthValue / 100) * containerWidth;
                        newHeightValue = newWidthPx * aspectRatio;
                    } else {
                        newHeightValue = newWidthValue * aspectRatio;
                    }
                }

                // Cập nhật thuộc tính top và height vào DOM
                item.setAttribute("data-original-left", newLeft);
                item.setAttribute("data-original-top", newTop);
                item.setAttribute("data-original-height", newHeightValue);
                if (newTop + newHeightValue > maxBottom) {
                    maxBottom = newTop + newHeightValue;
                }
                // Emit sự kiện để cập nhật grid item
                this.eventBus.emit("update-grid-item", {
                    id: itemId,
                    left: newLeft,
                    top: newTop,
                    width: isPercentWidth ? `${newWidthValue}%` : newWidthValue,
                    height: newHeightValue,
                    direction: this.selectionResizeType
                });
            });
            // update height section khi không có min-height
            if (!this.gridParent.data?.settings?.["min-height"]) {
                if (maxBottom > containerHeight || maxBottom > maxY) {
                    this.$parent.updateHeight(maxBottom);
                } else if (parseInt(containerHeight) !== parseInt(maxY)) {
                    this.$parent.updateHeight(maxY);
                }
            }
            // Cập nhật kích thước và vị trí của group
            this.updateSelectionAreaFromItems();
            this.calculateGapItems();
            this.handleUpdateBounds();
        },
        updateSelectionAreaFromItems() {
            let minX = Infinity,
                minY = Infinity;
            let maxX = -Infinity,
                maxY = -Infinity;

            this.gridItems.forEach((item) => {
                // Lấy các giá trị từ data-attributes
                const left = this.ensureNumericValue(item.getAttribute("data-original-left"));
                const top = this.ensureNumericValue(item.getAttribute("data-original-top"));
                const width = item.getAttribute("data-original-width");
                const height = this.ensureNumericValue(item.getAttribute("data-original-height"));

                // Xử lý width dựa trên loại (% hoặc px)
                let widthValue;
                if (typeof width === "string" && width.includes("%")) {
                    widthValue = parseFloat(width);
                } else {
                    widthValue = this.ensureNumericValue(width);
                    // Chuyển đổi px sang % cho tính toán nhất quán
                    widthValue = (widthValue / this.containerWidth) * 100;
                }

                // Cập nhật giá trị min/max
                minX = Math.min(minX, left);
                minY = Math.min(minY, top);
                maxX = Math.max(maxX, left + widthValue);
                maxY = Math.max(maxY, top + height);
            });

            // Đảm bảo các giá trị là hợp lệ
            if (isFinite(minX) && isFinite(minY) && isFinite(maxX) && isFinite(maxY)) {
                this.selectionArea = { minX, minY, maxX, maxY };
            }
        },

        // Kết thúc resize selection
        endSelectionResize(e) {
            // Reset biến lưu vị trí chuột
            this.lastMouseX = 0;
            this.lastMouseY = 0;

            // Gỡ bỏ event listeners
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.removeEventListener("mousemove", this.handleSelectionResize);
            iframeDoc.removeEventListener("mouseup", this.endSelectionResize);
            if (!this.isResizingGroup) return;
            handleSetHistoryGroup(
                this.oldSection,
                this.group.blocks,
                this.screen,
                "resized",
                this.groupId
            );
            // Đặt lại trạng thái
            this.isResizingGroup = false;
            this.selectionResizeType = "";

            // Cập nhật layout từ các thay đổi đã thực hiện
            this.gridItems.forEach((item) => {
                const itemId = item.getAttribute("data-id");
                const gridItem = this.findGridItem(itemId);
                if (gridItem) {
                    const left = this.ensureNumericValue(item.getAttribute("data-original-left"));
                    const top = this.ensureNumericValue(item.getAttribute("data-original-top"));
                    const width = item.getAttribute("data-original-width");
                    const height = this.ensureNumericValue(
                        item.getAttribute("data-original-height")
                    );

                    gridItem.$emit("resized", itemId, height, width, left, top);
                    gridItem.updateGridSize && gridItem.updateGridSize();
                }
            });

            // Cập nhật thông tin cho GroupSettings
            const topBorderElement = iframeDoc.querySelector(".ecom-selection-active");
            if (topBorderElement) {
                this.eventBus.emit("selectionResizeComplete", {
                    el: topBorderElement,
                    sectionId: this.section_id
                });
            }

            // Cập nhật vị trí và kích thước cuối cùng
            this.updateSelectionAreaFromItems();
            this.updateBounds();

            const gridLayout = this.$parent;
            if (gridLayout && typeof gridLayout.updateAllLayouts === "function") {
                gridLayout.updateAllLayouts();
            }

            e.preventDefault();
            e.stopPropagation();
        },
        ensureNumericValue(value) {
            if (value === undefined || value === null) {
                return 0; // Trả về 0 thay vì undefined/null
            }

            if (typeof value === "string") {
                // Loại bỏ đơn vị nếu có
                const numericString = value.replace(/[^\d.-]/g, "");
                const parsed = parseFloat(numericString);
                return isNaN(parsed) ? 0 : parsed; // Trả về 0 nếu không thể parse
            }

            return isNaN(value) ? 0 : value; // Đảm bảo không trả về NaN
        },
        findGridItem(blockId) {
            // Lấy instance từ instanceStore
            const instance = this.instanceStore.get(blockId);
            if (!instance) return null;

            let gridItem = null;
            let parent = instance;

            // Tìm trong cây component cho đến khi tìm thấy GridItem
            while (parent && !gridItem) {
                if (
                    parent.$parent &&
                    parent.$parent.$options &&
                    parent.$parent.$options.name === "GridItem"
                ) {
                    gridItem = parent.$parent;
                    break;
                }
                parent = parent.$parent;
            }

            return gridItem;
        },
        getItemGridValue(item) {
            return {
                left: Number(item.getAttribute("data-original-left")) || 0,
                top: Number(item.getAttribute("data-original-top")) || 0,
                width: item.getAttribute("data-original-width"),
                height: Number(item.getAttribute("data-original-height")) || 0,
                id: item.getAttribute("data-id"),
                i: item.getAttribute("data-id"),
                rotation: Number(item.getAttribute("data-rotation")) || 0
            };
        },
        startRotate(e) {
            if (this.isLocked) {
                this.$store.commit("builder/setShowNoticeLockmode", true);
                return;
            }

            // Đặt trạng thái đang quay
            this.isRotating = true;

            // Lưu góc quay ban đầu của group
            this.initialRotation = this.groupRotation || 0;

            // Tính tâm quay (center của group)
            const rect = this.$refs.groupWrapper.getBoundingClientRect();
            this.rotationCenter = {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };

            // Tính góc ban đầu của chuột so với tâm
            const dx = e.clientX - this.rotationCenter.x;
            const dy = e.clientY - this.rotationCenter.y;
            this.initialAngle = Math.atan2(dy, dx) * (180 / Math.PI);

            // Thêm event listeners
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.addEventListener("mousemove", this.handleRotateMove);
            iframeDoc.addEventListener("mouseup", this.endRotate);

            // Thông báo rằng group đang bắt đầu quay
            if (this.instanceStore) {
                this.instanceStore.register("isGroupRotating", true);
                this.instanceStore.register("rotatingGroupId", this.groupId);
            }

            // Thêm class để thay đổi cursor
            if (this.$refs.groupWrapper) {
                this.$refs.groupWrapper.classList.add("rotating");
            }

            e.preventDefault();
            e.stopPropagation();
        },

        handleRotateMove(e) {
            if (!this.isRotating || !this.rotationCenter || this.isLockedGroup) return;

            // Tính góc quay dựa trên vị trí chuột so với tâm quay
            const dx = e.clientX - this.rotationCenter.x;
            const dy = e.clientY - this.rotationCenter.y;

            // Góc tính bằng radian, chuyển sang độ
            let angle = Math.atan2(dy, dx) * (180 / Math.PI);

            // Tính góc tương đối so với góc ban đầu khi click
            let deltaAngle = angle - this.initialAngle;

            // Cập nhật góc quay mới cho group
            const newRotation = (((this.initialRotation + deltaAngle) % 360) + 360) % 360;
            this.groupRotation = newRotation;

            // Giới hạn tốc độ cập nhật
            const now = Date.now();
            if (now - this.lastRotateTimestamp > 16) {
                // Khoảng 60fps
                this.lastRotateTimestamp = now;

                // Quay tất cả các items trong group
                this.rotateAllGroupItems(deltaAngle);

                // Phát sự kiện đang quay group
                if (this.eventBus) {
                    this.eventBus.emit("groupRotating", {
                        groupId: this.groupId,
                        rotation: this.groupRotation,
                        element: this.$refs.groupWrapper
                    });
                }
            }
        },

        rotateAllGroupItems(deltaAngle) {
            // Lấy danh sách Grid Items
            const gridItems = this.gridItems || [];
            if (gridItems.length === 0) return;

            // Tìm Grid Layout cha
            let gridLayout = null;
            if (this.$parent && this.$parent.$parent) {
                gridLayout = this.$parent.$parent;
            }
            if (!gridLayout || !gridLayout.layout || !Array.isArray(gridLayout.layout)) return;

            // Lấy bản sao của layout hiện tại
            const currentLayout = [...gridLayout.layout];
            const newLayout = [...currentLayout];

            // Lấy screen hiện tại
            const screen = this.screen || "desktop";

            // Lưu trữ danh sách các item đã cập nhật
            const updatedItems = [];

            // Cập nhật từng Grid Item
            gridItems.forEach((item) => {
                try {
                    // Lấy instance của GridItem
                    const itemInstance = this.findGridItem(item);
                    if (!itemInstance || !itemInstance.i) return;

                    // Lấy thông tin từ GridItem
                    const itemId = itemInstance.i;
                    const currentRotation = itemInstance.rotation || 0;

                    // Tìm item trong layout
                    const layoutItemIndex = newLayout.findIndex((li) => li.i === itemId);
                    if (layoutItemIndex === -1) return;

                    // Tính toán rotation mới cho item
                    const newRotation = (((currentRotation + deltaAngle) % 360) + 360) % 360;

                    // Cập nhật góc quay mới vào layout
                    newLayout[layoutItemIndex] = {
                        ...newLayout[layoutItemIndex],
                        rotation: newRotation
                    };

                    // Lưu vào danh sách đã cập nhật
                    updatedItems.push({
                        id: itemId,
                        rotation: newRotation
                    });

                    // Phát sự kiện rotate cho từng GridItem
                    if (this.eventBus) {
                        this.eventBus.emit("rotateEvent", {
                            eventType: "rotate",
                            i: itemId,
                            angle: newRotation
                        });
                    }
                } catch (error) {
                    console.error("Error rotating grid item:", error);
                }
            });

            // Cập nhật layout trong GridLayout
            if (gridLayout && typeof gridLayout.$emit === "function") {
                gridLayout.$emit("update:layout", newLayout);
            }

            // Cập nhật section.blocks nếu cần
            try {
                if (this.section_id && updatedItems.length > 0 && this.$store) {
                    const sections = this.$store.getters["page/sections"] || [];
                    const section = sections.find((s) => s.id === this.section_id);

                    if (section && section.blocks && Array.isArray(section.blocks)) {
                        updatedItems.forEach((update) => {
                            const blockIndex = section.blocks.findIndex((b) => b.id === update.id);
                            if (
                                blockIndex !== -1 &&
                                section.blocks[blockIndex].layouts &&
                                section.blocks[blockIndex].layouts[screen]
                            ) {
                                // Cập nhật góc xoay cho block trong layout của screen hiện tại
                                section.blocks[blockIndex].layouts[screen].rotation =
                                    update.rotation;
                            }
                        });
                    }
                }
            } catch (error) {
                console.error("Error updating section blocks:", error);
            }
        },

        endRotate(e) {
            if (!this.isRotating) return;

            // Gỡ bỏ event listeners
            const iframeDoc = window.EComposerBuilder?.contentDocument || document;
            iframeDoc.removeEventListener("mousemove", this.handleRotateMove);
            iframeDoc.removeEventListener("mouseup", this.endRotate);

            // Đặt lại trạng thái
            this.isRotating = false;

            // Reset instance store
            if (this.instanceStore) {
                this.instanceStore.register("isGroupRotating", false);
                this.instanceStore.register("rotatingGroupId", null);
            }

            // Xóa class rotating
            if (this.$refs.groupWrapper) {
                this.$refs.groupWrapper.classList.remove("rotating");
            }

            // Cập nhật góc quay vào cấu trúc dữ liệu chính
            try {
                if (this.section_id && this.groupId && this.$store) {
                    const sections = this.$store.getters["page/sections"] || [];
                    const section = sections.find((s) => s.id === this.section_id);

                    if (section && section.groups && section.groups[this.groupId]) {
                        // Lưu góc quay vào group
                        section.groups[this.groupId].rotation = this.groupRotation;
                    }
                }
            } catch (error) {
                console.error("Error updating group rotation:", error);
            }

            // Phát sự kiện hoàn thành quay group
            if (this.eventBus) {
                this.eventBus.emit("groupRotateComplete", {
                    groupId: this.groupId,
                    rotation: this.groupRotation
                });
            }

            // Cập nhật vị trí và layout cuối cùng
            this.updateFinalLayoutAfterRotation();

            e.preventDefault();
            e.stopPropagation();
        },

        updateFinalLayoutAfterRotation() {
            // Tìm Grid Layout cha
            let gridLayout = null;
            if (this.$parent && this.$parent.$parent) {
                gridLayout = this.$parent.$parent;
            }
            if (!gridLayout) return;

            // Emit sự kiện layout-updated
            if (typeof gridLayout.$emit === "function" && gridLayout.layout) {
                gridLayout.$emit("layout-updated", gridLayout.layout);
            }

            // Gọi updateAllLayouts nếu có trong gridLayout
            if (typeof gridLayout.updateAllLayouts === "function") {
                gridLayout.updateAllLayouts();
            } else {
                // Phương thức thay thế nếu updateAllLayouts không tồn tại
                this.updateAllLayoutsManually(gridLayout);
            }
        },

        updateAllLayoutsManually(gridLayout) {
            if (!gridLayout || !gridLayout.layout || !Array.isArray(gridLayout.layout)) return;

            try {
                // Lấy screen hiện tại
                const screen = this.screen || "desktop";

                // Cập nhật section.blocks với layout hiện tại
                if (this.section_id && this.$store) {
                    const sections = this.$store.getters["page/sections"] || [];
                    const section = sections.find((s) => s.id === this.section_id);

                    if (section && section.blocks && Array.isArray(section.blocks)) {
                        // Tạo một bản sao của blocks để làm việc
                        const updatedBlocks = [...section.blocks];

                        gridLayout.layout.forEach((layoutItem) => {
                            const blockIndex = updatedBlocks.findIndex(
                                (b) => b.id === layoutItem.i
                            );
                            if (
                                blockIndex !== -1 &&
                                updatedBlocks[blockIndex].layouts &&
                                updatedBlocks[blockIndex].layouts[screen]
                            ) {
                                // Cập nhật toàn bộ layout cho block
                                updatedBlocks[blockIndex].layouts[screen] = {
                                    ...updatedBlocks[blockIndex].layouts[screen],
                                    x: layoutItem.x,
                                    y: layoutItem.y,
                                    w: layoutItem.w,
                                    h: layoutItem.h,
                                    rotation: layoutItem.rotation || 0,
                                    i: layoutItem.i
                                };
                            }
                        });

                        // Cập nhật blocks trong section
                        section.blocks = updatedBlocks;

                        // Emit sự kiện cập nhật grid layout
                        if (this.eventBus) {
                            this.eventBus.emit("update-grid-layout", {
                                sectionId: this.section_id,
                                blocks: updatedBlocks
                            });
                        }
                    }
                }
            } catch (error) {
                console.error("Error updating layouts manually:", error);
            }
        },
        handleGroupMouseDown(e) {
            // Bỏ qua nếu đang rotate hoặc đã khóa
            this.calculateSelectionArea();
            if (this.isResizing || this.isRotating || this.isFullScreen || this.isLockedGroup)
                return;

            // Kiểm tra nếu click vào grid item
            // if (
            //     e.target.classList.contains("ecom-grid-item") ||
            //     e.target.closest(".ecom-grid-item")
            // ) {
            //     return;
            // }

            // Cập nhật scale ratio
            this.updateScaleRatio();
            this.$store.commit("builder/setActiveElement", null);
            // Đánh dấu đang chuẩn bị kéo, chưa phải đang kéo thực sự
            this.isDraggingPrepared = true;
            this.isMouseMoved = false; // Reset trạng thái di chuyển chuột

            // Đặt style cho document
            document.body.style.userSelect = "none";
            document.body.style.cursor = "move";
            this.idoc.body.style.userSelect = "none";
            this.idoc.body.style.cursor = "move";

            // Lấy vị trí hiện tại của group
            let parentRect = this.$refs.groupWrapper.offsetParent.getBoundingClientRect();
            let clientRect = this.$refs.groupWrapper.getBoundingClientRect();

            // Điều chỉnh vị trí theo scale
            this.dragStartPos = {
                left: (clientRect.left - parentRect.left) / this.scaleRatio,
                top: (clientRect.top - parentRect.top) / this.scaleRatio
            };
            this.dragStartBounds = { ...this.bounds };
            this.dragStartPosition = { ...this.dragStartPos };

            // Lưu vị trí chuột ban đầu
            this.dragMouseStartPosition = {
                x: e.clientX,
                y: e.clientY
            };

            // Tính offset giữa chuột và góc trên bên trái của group (có scale)
            this.dragMouseOffset = {
                x: (e.clientX - clientRect.left) / this.scaleRatio,
                y: (e.clientY - clientRect.top) / this.scaleRatio
            };

            // Lấy kích thước container
            if (this.gridParent && this.gridParent.$el) {
                let _gridParentEl = this.gridParent.$el;
                if (!(_gridParentEl instanceof Element)) {
                    _gridParentEl = _gridParentEl.nextElementSibling || _gridParentEl.parentElement?.querySelector(':first-child');
                }
                if (!_gridParentEl || typeof _gridParentEl.getBoundingClientRect !== 'function') return;
                const containerRect = _gridParentEl.getBoundingClientRect();
                this.containerBounds = {
                    ...containerRect,
                    width: containerRect.width / this.scaleRatio,
                    height: containerRect.height / this.scaleRatio
                };
            }

            // Reset transform về 0,0 khi bắt đầu kéo
            this.dragTransform = { x: 0, y: 0 };

            // Lưu vị trí ban đầu của các items trong group
            this.initialItemsPosition = this.gridItems.map((item) => {
                return this.getItemGridValue(item);
            });

            // Thêm event listeners
            this.idoc.addEventListener("mousemove", this.handleGroupDragMove);
            this.idoc.addEventListener("mouseup", this.endGroupDrag);

            e.preventDefault();
            e.stopPropagation();
        },

        handleGroupDragMove(e) {
            if (!this.isDraggingPrepared || this.isLockedGroup) return;
            const activeGroup = this.$store.getters["builder/activeGroup"];
            if (!activeGroup) {
                this.$store.commit("builder/setActiveGroup", this.groupId);
            }
            try {
                if (this.$store) {
                    this.$store.commit("global/setCloseBlockSt", true);
                }
                this.eventBus.emit("groupSettingsClose");
            } catch (e) {}

            // Tính toán khoảng cách di chuyển để xác định có phải drag thật không
            const deltaX = e.clientX - this.dragMouseStartPosition.x;
            const deltaY = e.clientY - this.dragMouseStartPosition.y;

            // Xác định nếu chuột đã di chuyển đủ xa để coi là drag thực sự (>3px)
            const hasMoved = Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3;
            if (this.isLocked && hasMoved) {
                this.$store.commit("builder/setShowNoticeLockmode", true);
                return;
            }
            // Nếu đây là lần đầu tiên chuột di chuyển đủ xa để coi là drag
            if (hasMoved && !this.isMouseMoved) {
                this.isMouseMoved = true;
                this.isDragging = true; // Bây giờ mới đánh dấu là đang drag thật sự

                // Thông báo cho instance store
                this.$parent.isGroupDragging = true;

                // Cập nhật grid height
                this.updateGridHeight();

                // Thêm class cho grid parent
                this.gridParent.$el.classList.add("ecom--group_dragging");

                // Thêm class cho group wrapper để có thể áp dụng CSS đặc biệt khi kéo
                this.$refs.groupWrapper.classList.add("ecom-group-dragging");
            }

            // Nếu chưa di chuyển đủ xa, không thực hiện xử lý drag
            if (!this.isMouseMoved) return;

            // Reset editing element và active element
            this.$store.commit("builder/setEditingElement", null);
            this.$store.commit("builder/setActiveElement", null);

            // Lấy kích thước container (điều chỉnh theo scale)
            const containerWidth = this.containerWidth;
            const containerHeight = this.gridParent.$el.offsetHeight;

            // Điều chỉnh delta theo scale
            const scaledDeltaX = deltaX / this.scaleRatio;
            const scaledDeltaY = deltaY / this.scaleRatio;

            // Tính vị trí mới dựa trên vị trí gốc + offset đã scale
            const newPosX = this.dragStartPos.left + scaledDeltaX;
            const newPosY = this.dragStartPos.top + scaledDeltaY;

            // Tính vị trí tương đối theo phần trăm
            const leftPercent = (newPosX / containerWidth) * 100;

            // Tính toán giới hạn di chuyển
            const groupRect = this.$refs.groupWrapper.getBoundingClientRect();
            const groupWidth = groupRect.width / this.scaleRatio;
            const groupHeight = groupRect.height / this.scaleRatio;
            const groupWidthPercent = (groupWidth / containerWidth) * 100;

            // Tính các giới hạn
            const minLeft = 0; // Không để group vượt qua biên trái
            const maxLeft = 100 - groupWidthPercent; // Không để group vượt qua biên phải
            const minTop = 0; // Không để group vượt qua biên trên

            // Tính maxTop dựa trên thiết lập height của container
            let maxTop = Number.MAX_SAFE_INTEGER; // Mặc định không giới hạn
            if (this.gridParent.data?.settings?.["min-height"]) {
                maxTop = containerHeight - groupHeight;
            }

            // Điều chỉnh vị trí để không vượt quá các cạnh
            let adjustedLeft = Math.max(minLeft, Math.min(maxLeft, leftPercent));
            let adjustedTop = Math.max(minTop, Math.min(maxTop, newPosY));

            // Lưu lại vị trí dự kiến đã điều chỉnh
            this.newPosition = {
                left: adjustedLeft,
                top: adjustedTop
            };

            // Tính vị trí đã giới hạn trong pixel
            const limitedPosX = (adjustedLeft / 100) * containerWidth;
            const limitedPosY = adjustedTop;

            // Tính transform giới hạn - chênh lệch giữa vị trí giới hạn và vị trí ban đầu
            const limitedDeltaX = limitedPosX - this.dragStartPos.left;
            const limitedDeltaY = limitedPosY - this.dragStartPos.top;

            // Tạo transform giới hạn
            const newDragTransform = {
                x: limitedDeltaX,
                y: limitedDeltaY
            };

            // Cập nhật dragTransform với vị trí mới
            this.dragTransform = newDragTransform;

            // Kiểm tra xem group có đang ở ngoài biên không
            const isOutOfBounds =
                leftPercent < minLeft ||
                leftPercent > maxLeft ||
                newPosY < minTop ||
                newPosY > maxTop;

            // Thêm class để hiển thị trạng thái nếu group đang ở ngoài giới hạn
            if (isOutOfBounds !== this.isDraggingOutOfBounds) {
                this.isDraggingOutOfBounds = isOutOfBounds;

                if (this.$refs.groupWrapper) {
                    if (isOutOfBounds) {
                        this.$refs.groupWrapper.classList.add("ecom-group-out-of-bounds");
                    } else {
                        this.$refs.groupWrapper.classList.remove("ecom-group-out-of-bounds");
                    }
                }
            }
            let maxY = 0;
            this.layout.forEach((item) => {
                if (!this.group.blocks.includes(item.i)) {
                    let itemY = item.top + item.height;
                    if (itemY > maxY) {
                        maxY = itemY;
                    }
                }
            });

            // Kiểm tra hướng di chuyển của group
            const isMovingDown = this.lastY !== null && adjustedTop >= this.lastY;
            this.lastY = adjustedTop;

            // Kiểm tra và tự động tăng chiều cao section khi group chạm đáy
            const groupBottom = adjustedTop + groupHeight;

            if (
                this.$parent &&
                this.$parent.$refs.item &&
                !this.gridParent.data?.settings?.["min-height"] &&
                groupBottom > maxY &&
                ((!isMovingDown && groupBottom < this.$parent.$refs.item.offsetHeight) ||
                    (isMovingDown && groupBottom > this.$parent.$refs.item.offsetHeight))
            ) {
                // requestAnimationFrame(() => {
                // Update grid height theo khoảng cách kéo
                const newHeight = Math.max(groupBottom, maxY);
                this.$parent.$refs.item.style.height = `${newHeight}px`;
                this.newHeight = newHeight;
            } else if (
                this.$parent &&
                this.$parent.$refs.item &&
                !this.gridParent.data?.settings?.["min-height"] &&
                groupBottom < maxY &&
                parseInt(this.$parent.$refs.item.style.height) != parseInt(maxY)
            ) {
                this.$parent.$refs.item.style.height = `${maxY}px`;
            }

            // Emit sự kiện
            this.eventBus.emit("groupDragging", {
                groupId: this.groupId,
                position: {
                    x: adjustedLeft,
                    y: adjustedTop
                },
                element: this.$refs.groupWrapper,
                isDragging: true,
                bounds: {
                    left: adjustedLeft,
                    top: adjustedTop,
                    width: (groupWidth / containerWidth) * 100,
                    height: groupHeight
                },
                sectionId: this.section_id
            });

            // Emit sự kiện để GridLayout cập nhật placeholder
            this.eventBus.emit("updateGroupPlaceholder", {
                i: "group-" + this.groupId,
                left: adjustedLeft,
                top: adjustedTop,
                width: groupWidth,
                height: groupHeight
            });
        },

        endGroupDrag(e) {
            // Xóa event listeners
            this.idoc.removeEventListener("mousemove", this.handleGroupDragMove);
            this.idoc.removeEventListener("mouseup", this.endGroupDrag);

            // Khôi phục style
            document.body.style.userSelect = "";
            document.body.style.cursor = "";
            if (this.gridParent && this.gridParent.$el) {
                this.gridParent.$el.classList.remove("ecom--group_dragging");
            }
            this.idoc.body.style.userSelect = "";
            this.idoc.body.style.cursor = "";

            // Xóa class ecom-group-dragging
            this.$refs.groupWrapper.classList.remove("ecom-group-dragging");

            // KHI CLICK KHÔNG DRAG: Nếu chuột không di chuyển đủ xa, coi như là click thường, không phải drag
            if (!this.isMouseMoved) {
                this.$store.commit("builder/setActiveGroup", this.groupId);
                this.$store.commit("builder/setEditingElement", null);
                this.eventBus.emit("groupSettingsOpen", {
                    el: this.$refs.groupWrapper,
                    sectionId: this.section_id,
                    fromClickInGroupItem: true
                });
                this.isDraggingPrepared = false;
                this.dragStartPos = null;
                this.dragStartBounds = null;
                this.dragStartPosition = null;
                return; // Kết thúc xử lý mà không thay đổi vị trí
            } else {
                // Action move group
                const section = this.sections.find((s) => s.id == this.section_id);
                handleSetHistoryGroup(
                    section,
                    this.group.blocks,
                    this.screen,
                    "moved",
                    this.groupId
                );
                // this.$store.dispatch("history/addStack", {
                //     type: "group",
                //     data: this.sections.find((s) => s.id == this.section_id),
                //     section_id: this.section_id
                // });
            }

            // Tính toán vị trí mới trong grid
            const newLeftPercent = this.newPosition.left;
            const newTopPixels = this.newPosition.top;

            // Tính delta dựa trên sự thay đổi
            const deltaXPercent = newLeftPercent - this.dragStartBounds.x;
            const deltaYPixels = newTopPixels - this.dragStartBounds.y;

            // CHỈ cập nhật bounds một lần tại đây
            this.bounds = {
                ...this.bounds,
                x: newLeftPercent,
                y: newTopPixels
            };

            // Cập nhật vị trí của các items trong group
            this.updateGroupItemsPosition(deltaXPercent, deltaYPixels);

            // Cập nhật hiển thị của group wrapper (chuyển từ transform sang margin)
            this.dragTransform = { x: 0, y: 0 }; // Reset transform
            this.applyGroupWrapperStyle();

            // Emit sự kiện cập nhật bounds
            this.eventBus.emit("group-bounds-updated", {
                groupId: this.groupId,
                bounds: this.bounds
            });

            // Đánh dấu là vừa kết thúc drag
            this.$refs.groupWrapper.setAttribute("data-drag-completed", "true");

            // Emit sự kiện kết thúc kéo group
            this.eventBus.emit("groupDragEnd", {
                groupId: this.groupId,
                element: this.$refs.groupWrapper
            });

            // Mở lại GroupSettings sau khi kéo
            setTimeout(() => {
                if (this.isActiveGroup) {
                    this.eventBus.emit("groupSettingsOpen", {
                        el: this.$refs.groupWrapper,
                        sectionId: this.section_id,
                        fromDragComplete: true
                    });

                    // Xóa thuộc tính đánh dấu sau một khoảng thời gian
                    setTimeout(() => {
                        this.$refs.groupWrapper.removeAttribute("data-drag-completed");
                    }, 300);
                }
            }, 50);

            // Reset các biến
            this.dragStartPos = null;
            this.dragStartBounds = null;
            this.isDragging = false;
            this.isDraggingPrepared = false;
            this.isMouseMoved = false;
            this.initialItemsPosition = null;
            this.dragStartPosition = null;
            this.containerBounds = null;
            this.newPosition = null;

            // Cập nhật height cuối cùng
            this.updateGridHeight();
            const gridLayout = this.$parent;
            if (gridLayout && typeof gridLayout.updateAllLayouts === "function") {
                gridLayout.updateAllLayouts();
            }
            this.$parent.isGroupDragging = false;

            this.eventBus.emit("updateGroupPlaceholder", {
                i: null,
                left: 0,
                top: 0,
                width: 0,
                height: 0
            });

            // Reset trạng thái group dragging
            this.eventBus.emit("groupDragging", {
                isDragging: false
            });
        },

        applyGroupWrapperStyle() {
            if (!this.$refs.groupWrapper) return;
            const containerWidth = this.containerWidth;
            const widthPx = (this.bounds.w / 100) * containerWidth;

            // Tính toán margins dựa trên bounds
            const justifySelf = this.bounds.x < 50 ? "start" : "end";

            let marginLeft, marginRight;
            if (justifySelf === "start") {
                marginLeft = `${this.bounds.x}%`;
                marginRight = "auto";
            } else {
                marginLeft = "auto";
                marginRight = `${Math.max(0, 100 - this.bounds.x - this.bounds.w)}%`;
            }

            const marginTop = `${this.bounds.y}px`;
            const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

            // Thêm rotation transform
            const rotationTransform = this.groupRotation ? ` rotate(${this.groupRotation}deg)` : "";

            // Áp dụng style
            this.$refs.groupWrapper.style.margin = margin;
            this.$refs.groupWrapper.style.width = `${widthPx}px`;
            this.$refs.groupWrapper.style.height = `${this.bounds.h}px`;
            this.$refs.groupWrapper.style.transform = rotationTransform;
        },
        updateGridHeight(maxY = null) {
            const gridLayout = this.$parent;
            if (!gridLayout || !gridLayout.$refs.item) return;

            // Kiểm tra xem grid parent có thiết lập fixed height không
            let isFixedHeight = false;

            // Phương pháp 1: Kiểm tra từ gridParent
            if (this.gridParent && typeof this.gridParent === "object") {
                isFixedHeight = this.gridParent.data?.settings?.height === "fixed";
            }

            // Phương pháp 2: Kiểm tra từ section nếu phương pháp 1 không có kết quả
            if (!isFixedHeight && this.section_id && this.$store) {
                const sections = this.$store.getters["page/sections"] || [];
                const section = sections.find((s) => s.id === this.section_id);
                isFixedHeight = section?.settings?.height === "fixed";
            }

            // Phương pháp 3: Kiểm tra từ store nếu các phương pháp trên không có kết quả
            if (!isFixedHeight && this.section_id && this.$store) {
                const sections = this.$store.getters["page/sections"] || [];
                const section = sections.find((s) => s.id === this.section_id);
                isFixedHeight = section?.settings?.height === "fixed";
            }

            // Nếu grid có fixed height, không thay đổi chiều cao
            if (isFixedHeight) {
                return;
            }

            // Nếu không phải fixed height, tiếp tục với logic hiện tại
            const bottomY = maxY || this.currentMaxY;
            const height =
                bottomY * (gridLayout.rowHeight + gridLayout.margin[1]) + gridLayout.margin[1];

            gridLayout.$refs.item.style.height = `${height}px`;
        },

        updateGroupItemsPosition(deltaX, deltaY) {
            if (Math.abs(deltaX) < 0.001 && Math.abs(deltaY) < 0.001) return;

            // Update each item's position
            this.gridItems.forEach((item) => {
                const itemInstance = this.getItemGridValue(item);
                const currentLeft = this.ensureNumericValue(itemInstance.left);
                const currentTop = this.ensureNumericValue(itemInstance.top);

                if (isNaN(currentLeft) || isNaN(currentTop)) {
                    console.warn(
                        "Invalid position for item:",
                        itemInstance.i,
                        "left:",
                        itemInstance.left,
                        "top:",
                        itemInstance.top
                    );
                    return;
                }

                // Tính toán vị trí mới
                const newLeft = parseFloat((currentLeft + deltaX).toFixed(4));
                const newTop = parseFloat((currentTop + deltaY).toFixed(4));
                // Cập nhật vào DOM attributes
                item.setAttribute("data-original-left", newLeft);
                item.setAttribute("data-original-top", newTop);

                const id = item.getAttribute("data-id");
                if (!id) return;
                this.$emit("moved", id, newLeft, newTop);
            });
        },
        forceUpdateBounds() {
            const gridItems = this.gridItems;
            if (gridItems.length === 0) return;

            let minX = Infinity;
            let minY = Infinity;
            let maxX = -Infinity;
            let maxY = -Infinity;

            // Lấy kích thước container
            const containerWidth = this.containerWidth;

            // Xác định bounds từ grid items
            gridItems.forEach((item) => {
                const x = parseFloat(item.getAttribute("data-original-left"));
                const y = parseFloat(item.getAttribute("data-original-top"));
                const width = item.getAttribute("data-original-width");
                const w = isPercentWidth(width)
                    ? widthPxCalculate(width, containerWidth)
                    : ensureNumericValue(width);
                const h = parseFloat(item.getAttribute("data-original-height"));

                if (!isNaN(x) && !isNaN(y) && !isNaN(w) && !isNaN(h)) {
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);

                    // Chuyển width từ px sang %
                    const widthPercent = isPercentWidth(width)
                        ? ensureNumericValue(width)
                        : (w / containerWidth) * 100;
                    maxX = Math.max(maxX, x + widthPercent);
                    maxY = Math.max(maxY, y + h);
                }
            });

            // Đảm bảo giá trị hợp lý
            minX = isFinite(minX) ? parseFloat(minX.toFixed(4)) : 0;
            minY = isFinite(minY) ? parseFloat(minY.toFixed(4)) : 0;
            maxX = isFinite(maxX) ? parseFloat(maxX.toFixed(4)) : minX + 1;
            maxY = isFinite(maxY) ? parseFloat(maxY.toFixed(4)) : minY + 1;

            // Nếu bounds đã được cập nhật từ endGroupDrag, chỉ cập nhật width và height
            if (this.isDragging || this.newPosition) {
                this.bounds = {
                    ...this.bounds,
                    w: parseFloat((maxX - minX).toFixed(4)),
                    h: parseFloat((maxY - minY).toFixed(4))
                };
            } else {
                // Cập nhật toàn bộ bounds nếu không phải là sau khi drag
                this.bounds = {
                    x: minX,
                    y: minY,
                    w: parseFloat((maxX - minX).toFixed(4)),
                    h: parseFloat((maxY - minY).toFixed(4))
                };
            }

            // Luôn cập nhật hiển thị
            this.applyGroupWrapperStyle();
        },
        updateContainerWidth() {
            if (this.gridParent && this.gridParent.$el) {
                this.$nextTick(() => {
                    const gridLayout = this.gridParent.$el.querySelector(".ecom-grid-layout");
                    const rect = gridLayout.getBoundingClientRect();

                    // Điều chỉnh width theo scale
                    this.containerWidth = rect.width / this.getIframeScale();
                });
            }
        },
        calcColWidth() {
            // Đảm bảo containerWidth luôn hợp lệ
            const effectiveWidth = Math.max(this.containerWidth, 100);

            // Khi container là full width, cần điều chỉnh cách tính
            if (this.isFullWidth) {
                // Sử dụng containerWidth trực tiếp khi là full width
                return (effectiveWidth - this.margin[0] * (this.cols + 1)) / this.cols;
            }

            // Công thức tính toán thông thường
            return (effectiveWidth - this.margin[0] * (this.cols + 1)) / this.cols;
        },
        handleMouseEnter() {
            if (this.isFullScreen) return;

            // Lấy active element hiện tại
            const activeElement = this.$store.getters["builder/activeElement"];
            // Chỉ set isActive = true nếu:
            // - Không có active element, HOẶC
            // - Active element không nằm trong group này
            const shouldSetActive = !activeElement || !this.group.blocks.includes(activeElement.data?.id);

            if (shouldSetActive) {
                this.isActive = true;
            }
        },
        handleMouseLeave() {
            this.isActive = false;
        },
        handleClick(e) {
            if (this.isFullScreen) return;
            // Nếu đang kéo thả hoặc vừa chuẩn bị kéo, không xử lý click
            if (this.isDragging || this.isDraggingPrepared) {
                e.preventDefault();
                e.stopPropagation();
                return;
            }

            // Kiểm tra xem có phải vừa kéo thả xong không
            const justDragged = this.$refs.groupWrapper.hasAttribute("data-drag-completed");

            // Bỏ qua nếu click vào grid item
            if (
                e.target.classList.contains("ecom-grid-item") ||
                e.target.closest(".ecom-grid-item")
            ) {
                return;
            }

            // Nếu đã là active group nhưng vừa kéo xong, vẫn mở lại settings
            // Nếu chưa là active group, setActiveGroup và mở settings
            if (!this.isActiveGroup || justDragged) {
                // Đảm bảo group được chọn
                this.$store.commit("builder/setActiveGroup", this.groupId);
                this.$store.commit("builder/setEditingElement", null);
                // Mở GroupSettings
                this.eventBus.emit("groupSettingsOpen", {
                    el: this.$refs.groupWrapper,
                    sectionId: this.section_id,
                    fromClick: true
                });

                // Ngăn chặn sự kiện click lan tỏa
                e.stopPropagation();
            }
        },
        handleUpdateBounds() {
            const gridItems = this.gridItems;
            if (gridItems.length === 0) return;

            let minX = Infinity;
            let minY = Infinity;
            let maxX = -Infinity;
            let maxY = -Infinity;

            // Lấy kích thước container để tính toán chính xác
            const containerWidth = this.containerWidth;

            gridItems.forEach((item) => {
                // Lấy giá trị từ data-original-* để xác định bounds
                const x = ensureNumericValue(item.getAttribute("data-original-left"));
                const y = ensureNumericValue(item.getAttribute("data-original-top"));
                const width = item.getAttribute("data-original-width");
                const w = isPercentWidth(width)
                    ? widthPxCalculate(width, containerWidth)
                    : ensureNumericValue(width);
                const h = ensureNumericValue(item.getAttribute("data-original-height"));

                if (!isNaN(x) && !isNaN(y) && !isNaN(w) && !isNaN(h)) {
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);

                    // Quan trọng: Chuyển đổi width từ px sang % trước khi tính maxX
                    const widthPercent = isPercentWidth(width)
                        ? ensureNumericValue(width)
                        : (w / containerWidth) * 100;
                    maxX = Math.max(maxX, x + widthPercent);

                    maxY = Math.max(maxY, y + h);
                }
            });

            // Đảm bảo giá trị hợp lý
            minX = isFinite(minX) ? minX : 0;
            minY = isFinite(minY) ? minY : 0;
            maxX = isFinite(maxX) ? maxX : minX + 1;
            maxY = isFinite(maxY) ? maxY : minY + 1;

            // Xác định nếu bounds đã thay đổi
            const boundsChanged =
                this.bounds.x !== minX ||
                this.bounds.y !== minY ||
                this.bounds.w !== maxX - minX ||
                this.bounds.h !== maxY - minY;

            if (boundsChanged) {
                // Cập nhật bounds của group
                this.bounds = {
                    x: minX, // % vị trí trái của group
                    y: minY, // px vị trí trên của group
                    w: maxX - minX, // % chiều rộng (maxX và minX đều là %)
                    h: maxY - minY // px chiều cao (maxY và minY đều là px)
                };

                this.eventBus.emit("group-bounds-updated", {
                    groupId: this.groupId,
                    bounds: this.bounds
                });
            }
        },
        updateBounds() {
            if (this.timeoutUpdateBounds) {
                clearTimeout(this.timeoutUpdateBounds);
            }
            this.timeoutUpdateBounds = setTimeout(() => {
                this.handleUpdateBounds();
            }, 50);
        },
        calcPosition(x, y, w, h) {
            const colWidth = this.calcColWidth();

            return {
                left: Math.round(colWidth * x + (x + 1) * this.margin[0]),
                top: Math.round(this.rowHeight * y + (y + 1) * this.margin[1]),
                width:
                    w === Infinity
                        ? w
                        : Math.round(colWidth * w + Math.max(0, w - 1) * this.margin[0]),
                height:
                    h === Infinity
                        ? h
                        : Math.round(this.rowHeight * h + Math.max(0, h - 1) * this.margin[1])
            };
        },
        // Hàm hỗ trợ để lấy z-index của group
        getGroupZIndex() {
            if (this.isDragging) return 1000; // Khi đang kéo thả, z-index cao nhất
            if (this.section_id && this.groupId) {
                const section = this.sections?.find((s) => s.id === this.section_id);
                if (section && section.groups && section.groups[this.groupId]) {
                    return section.groups[this.groupId].zIndex || 2;
                }
            }
            return 2;
        }
    },

    computed: {
        isFullScreen() {
            return this.$store.getters["builder/isFullScreen"];
        },
        screen() {
            return this.$store.getters["builder/screen"];
        },
        ...mapGetters("builder", ["contextMenu"]),
        idoc() {
            try {
                return window.EComposerBuilder?.contentDocument || document;
            } catch (e) {
                return document;
            }
        },
        selectionResizeHandles() {
            if (!this.isActiveGroup) return [];
            if (this.groupRatio) {
                return [
                    { x: 0, y: 0, type: "nw", class: "ecom-selection-resizable-handle-nw" }, // Tây-bắc
                    { x: "100%", y: 0, type: "ne", class: "ecom-selection-resizable-handle-ne" }, // Đông-bắc - SỬA
                    { x: 0, y: 100, type: "sw", class: "ecom-selection-resizable-handle-sw" }, // Tây-nam
                    { x: "100%", y: 100, type: "se", class: "ecom-selection-resizable-handle-se" } // Đông-nam - SỬA
                ];
            }
            return [
                // { x: 50, y: 0, type: "n", class: "ecom-selection-resizable-handle-n" }, // Bắc
                // { x: 50, y: 100, type: "s", class: "ecom-selection-resizable-handle-s" }, // Nam
                { x: "-.5px", y: 50, type: "w", class: "ecom-selection-resizable-handle-w" }, // Tây
                {
                    x: "calc(100% + .5px)",
                    y: 50,
                    type: "e",
                    class: "ecom-selection-resizable-handle-e"
                }, // Đông
                // Các handle ở góc
                { x: 0, y: 0, type: "nw", class: "ecom-selection-resizable-handle-nw" }, // Tây-bắc
                { x: "100%", y: 0, type: "ne", class: "ecom-selection-resizable-handle-ne" }, // Đông-bắc - SỬA
                { x: 0, y: 100, type: "sw", class: "ecom-selection-resizable-handle-sw" }, // Tây-nam
                { x: "100%", y: 100, type: "se", class: "ecom-selection-resizable-handle-se" } // Đông-nam - SỬA
            ];
        },
        isFullWidth() {
            // Phương pháp 1: Kiểm tra từ gridParent
            if (this.gridParent && typeof this.gridParent === "object") {
                if (this.gridParent.data?.settings?.["content-width"] === "full") {
                    return true;
                }
            }

            // Phương pháp 2: Kiểm tra từ section
            if (this.section_id && this.$store) {
                const sections = this.$store.getters["page/sections"] || [];
                const section = sections.find((s) => s.id === this.section_id);
                if (section?.settings?.["content-width"] === "full") {
                    return true;
                }
            }

            return false;
        },
        gridItems() {
            return Array.from(this.$refs.groupWrapper?.children || []).filter((el) =>
                el.classList.contains("ecom-grid-item")
            );
        },
        activeGroup() {
            return this.$store.getters["builder/activeGroup"];
        },
        isActiveGroup() {
            return this.activeGroup === this.groupId;
        },
        classObject() {
            return {
                "ecom-group-grid-active": this.isActive || this.isActiveGroup || this.isDragging,
                "ecom-group-dragging": this.isDragging,
                "ecom-group-active": this.isActiveGroup
            };
        },
        computedZIndex() {
            // Khi đang drag, sử dụng zIndex cao nhất
            if (this.isDragging) return 1000;
            if (this.isActiveGroup) return 900;

            // Sử dụng innerZindex hoặc lấy từ group data
            if (this.innerZindex !== "inherit") {
                return this.innerZindex;
            }

            // Fallback: lấy từ group data
            return this.getGroupBaseZIndex();
        },
        groupStyle() {
            // Khi đang kéo thả (dragging), sử dụng transform để có hiệu suất tốt
            if (this.isDragging) {
                // Tính toán width thực tế bằng pixel
                const containerWidth = this.containerWidth;
                const widthPx = (this.bounds.w / 100) * containerWidth;

                // Tạo transform với cả kéo và xoay
                const translateTransform = `translate(${this.dragTransform.x}px, ${this.dragTransform.y}px)`;
                const rotationTransform = this.groupRotation
                    ? ` rotate(${this.groupRotation}deg)`
                    : "";
                const transform = `${translateTransform}${rotationTransform}`;

                return {
                    width: `${widthPx}px`,
                    height: `${this.bounds.h}px`,
                    position: "absolute",
                    transformOrigin: "50% 50%",
                    transform: transform,
                    WebkitTransform: transform,
                    display: "block",
                    pointerEvents: "all",
                    outlineOffset: "-1px",
                    transition: "none",
                    willChange: "transform",
                    zIndex: this.computedZIndex,
                    marginLeft: `${this.bounds.x}%`,
                    marginTop: `${this.bounds.y}px`
                };
            }

            // Lấy giá trị từ bounds
            const x = this.ensureNumericValue(this.bounds.x); // % từ trái
            const y = this.ensureNumericValue(this.bounds.y); // px từ trên
            const w = this.ensureNumericValue(this.bounds.w); // % chiều rộng
            const h = this.ensureNumericValue(this.bounds.h); // px chiều cao
            const rotation = this.groupRotation || 0; // độ xoay

            // Lấy chiều rộng container để quy đổi % sang px
            const containerWidth = this.containerWidth;

            // Chuyển đổi chiều rộng từ % sang px - bounds.w đã là % do đã sửa ở updateBounds
            const widthPx = (w / 100) * containerWidth;

            // Xác định justifySelf dựa trên vị trí x
            const justifySelf = x < 50 ? "start" : "end";
            const alignSelf = "start"; // Luôn align từ trên xuống

            // Tính toán margins
            let marginLeft, marginRight;
            if (justifySelf === "start") {
                marginLeft = `${x}%`;
                marginRight = "auto";
            } else {
                marginLeft = "auto";
                // Đảm bảo không có giá trị âm hoặc NaN
                const rightMarginPercent = Math.max(0, 100 - x - w);
                marginRight = isNaN(rightMarginPercent) ? "0%" : `${rightMarginPercent}%`;
            }

            // Margin-top luôn tính bằng px
            const marginTop = `${y}px`;

            // Gộp margin thành một thuộc tính
            const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

            // Tạo transform style cho rotation
            let transform = "none";
            if (rotation !== 0) {
                transform = `rotate(${rotation}deg)`;
            }

            // Trả về style object
            return {
                justifySelf: justifySelf,
                alignSelf: alignSelf,
                width: `${widthPx}px`, // Đã chuyển đổi từ % sang px
                height: `${h}px`,
                margin: margin,
                transform: transform,
                WebkitTransform: transform,
                zIndex: this.computedZIndex,
                position: "absolute",
                transformOrigin: "50% 50%",
                willChange: this.isRotating ? "transform" : "auto",
                display: "block"
            };
        },

        currentMaxY() {
            return this.bounds.y + this.bounds.h;
        },
        groupSection() {
            if (!this.section_id) return null;
            const section = this.sections.find((s) => s.id === this.section_id);
            return section ? section.groups[this.groupId] || null : null;
        },
        isLocked() {
            return this.$store.getters["builder/editorConfigs"]?.locked;
        },
        isLockedGroup() {
            return this.groupSection?.locked;
        },
        ...mapGetters("page", ["sections"])
    },

    mounted() {
        // Lấy cấu hình từ grid parent
        let gridParent = this.$parent;
        if (gridParent) {
            this.gridParent = gridParent?.$parent;
            this.containerWidth = gridParent.width || 100;
        }
        this.instanceStore.register(this.groupId, this);

        //Khởi tạo innerZindex từ group data nếu chưa có
        if (this.innerZindex === "inherit") {
            this.innerZindex = this.getGroupBaseZIndex();
        }
        // Cập nhật bounds khi component được mount
        this.$nextTick(() => {
            this.updateBounds();
        });
        if (this.exporting) return;
        // Lắng nghe sự kiện layout-mounted từ grid
        this.eventBus.on("layout-mounted", (data) => {
            if (data?.width) {
                this.containerWidth = data.width;
                this.$nextTick(this.updateBounds);
            }
        });
        this.eventBus.on("group-gap-calculation-needed", (data) => {
            if (data.groupId === this.groupId) {
                this.forceCalculateGapItems();
            }
        });
        this.eventBus.on("update-group-bounds", this.handleUpdateGroupBoundsFromAutoLayout);
        this.eventBus.on("restore-group-bounds", this.handleRestoreGroupBoundsFromAutoLayout);

        try {
            if (this.section_id && this.groupId && this.$store) {
                const sections = this.$store.getters["page/sections"] || [];
                const section = sections.find((s) => s.id === this.section_id);

                if (section && section.groups && section.groups[this.groupId]) {
                    this.groupRotation = section.groups[this.groupId].rotation || 0;
                }
            }
        } catch (error) {
            console.error("Error initializing group rotation:", error);
        }
        // Lắng nghe các sự kiện drag và resize
        this.eventBus.on("dragEvent", this.updateBounds);
        this.eventBus.on("resizeEvent", this.updateBounds);
        this.eventBus.on("resizeEvent", this.updateContainerWidth);
        this.instanceStore.register(this.groupId, this);
        // Lắng nghe sự kiện item-resized-in-group để cập nhật lại bounds của group
        this.eventBus.on("item-resized-in-group", (data) => {
            if (data.groupId === this.groupId) {
                this.$nextTick(() => {
                    this.forceUpdateBounds();
                });
            }
        });

        this.updateScaleRatio();
    },

    beforeUnmount() {
        // Cleanup event listeners
        this.eventBus.off("layout-mounted");
        this.eventBus.off("dragEvent", this.updateBounds);
        this.eventBus.off("resizeEvent", this.updateBounds);
        this.eventBus.off("resizeEvent", this.updateContainerWidth);
        this.eventBus.off("item-resized-in-group");
        this.eventBus.off("group-gap-calculation-needed");
        this.eventBus.off("update-group-bounds", this.handleUpdateGroupBoundsFromAutoLayout);
        this.eventBus.off("restore-group-bounds", this.handleRestoreGroupBoundsFromAutoLayout);
        this.instanceStore.unregister?.(this.groupId);
    },
    watch: {
        containerWidth: {
            handler(newWidth, oldWidth) {
                if (newWidth !== oldWidth) {
                    // Đợi để các grid item cập nhật vị trí mới
                    this.$nextTick(() => {
                        this.updateBounds();
                    });
                }
            }
        },
        isActiveGroup(newValue) {
            if (newValue) {
                // Khi group trở thành active, tính toán khoảng cách
                this.$nextTick(() => {
                    this.calculateGapItems();
                });
            } else {
                // Khi group không còn active, ẩn resizers
                this.showGapResizers = false;
            }
        },
        zindex(newVal) {
            this.innerZindex =
                newVal === "" || newVal === null || newVal === undefined ? "inherit" : newVal;
        },

        // watch để emit events khi zIndex thay đổi
        computedZIndex(newVal, oldVal) {
            if (newVal !== oldVal && newVal !== "inherit") {
                this.eventBus.emit("group-style-updated", {
                    groupId: this.groupId,
                    sectionId: this.section_id,
                    zIndex: newVal
                });
            }
        }
    }
};
</script>
