<i18n>
{
    "en": {
        "close": "Close"
    },
    "fr": {
        "close": "Fermer"
    },
    "de": {
        "close": "Schließen"
    },
    "ja": {
        "close": "閉じる"
    }
}
</i18n>
<template>
    <div
        ref="wrapper"
        @keydown.esc="closePopup(true)"
        tabindex="-1"
        class="fixed top-0 left-0 z-[60] bg-black bg-opacity-50 outside-close-cursor"
        :class="popclass"
        @click="closePopup($event.target === $refs.wrapper)"
    >
        <div
            class="inset-0 shadow-2xl flex flex-col rounded-t overflow-hidden relative popup-container transition-all transform duration-400 opacity-0 -translate-x-8 max-h-screen ecom-default-cursor no-close-cursor"
            :class="wrpclass"
            :style="popupSize"
        >
            <!-- Topbar -->
            <div v-if="$slots.topbar" class="relative flex w-full ecom-popup-topbar z-2">
                <div class="relative z-30 flex flex-shrink-0 w-full h-14 font-medium text-gray-900 " :class="{'border-b  border-gray-200': borderTop}">
                    <slot name="topbar" />
                    <div class="absolute top-0 right-3 z-10 flex items-center h-14" :class="closeClass">
                        <ecom-button @click="closePopup(true)" :data-tooltip="`${$t('close')} (Esc)`" outline class="border-0 !shadow-none !bg-transparent transition hover:rotate-180 transform">
                            <EcomIcon :source="CancelMajor" class="icon-scale flex items-center text-gray-500 "></EcomIcon>
                        </ecom-button>
                    </div>
                </div>
            </div>
            <!-- Header -->
            <div
                v-if="$slots.header"
                class="w-full flex justify-between rounded-t items-center px-4 border-b border-default bg-surface-tertiary py-2"
            >
                <EcomText
                    :as="'h4'"
                    class="flex items-center text-sm font-semibold text-text-primary"
                >
                    <slot name="header" />
                </EcomText>
                <EcomButton
                    v-if="hasClose"
                    @click="closePopup(true)"
                    :data-tooltip="`${$t('close')} (Esc)`"
                    outline
                    class="border-0 !shadow-none !bg-transparent transition hover:!bg-surface-secondary-active transform !w-7 !h-7"
                >
                    <EcomIcon
                        :source="CancelMajor"
                        class="icon-scale flex items-center text-icon-primary"
                    ></EcomIcon>
                </EcomButton>
            </div>
            <!-- Body -->
            <div
                class="ecom-popup-list_wrapper flex relative flex-grow flex-col flex-1 z-1 overflow-auto bg-white"
                :class="[bodyclass, height != 'auto' ? '' : 'h-10', !$slots.header && !$slots.topbar ? 'rounded-t' : '', !hasFooterSlot ? 'rounded-b' : '']"
                @scroll="onScroll"
            >
                <slot name="body" />
            </div>
            <!-- Footer -->
            <div class="w-full flex ecom-popup-footer z-2" v-if="hasFooterSlot">
                <div
                    class="relative z-30 flex flex-shrink-0 w-full rounded-b font-medium text-gray-900 bg-white"
                >
                    <slot name="footer" />
                </div>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import EcomButton from "./EcomButton.vue";
import { CancelMajor, closeIcon } from "@/assets/icons";
export default {
    components: { EcomButton },
    data() {
        return {
            CancelMajor,
            closeIcon,
            itv: null
        };
    },
    props: {
        width: {
            type: [Number, String],
            default: 1400
        },
        height: {
            type: [Number, String],
            default: 0
        },
        popclass: {
            type: String,
            default: "h-full w-full flex justify-center items-center"
        },
        wrpclass: {
            type: String,
            default: "items-center my-5 bg-white  "
        },
        bodyclass: {
            type: String,
            default: "overflow-y-auto py-5 px-8 w-full"
        },
        borderTop: {
            type: Boolean,
            default: false
        },
        closeClass: {
            type: [String, Array],
            default: ""
        },
        isLarge: {
            type: Boolean,
            default: false
        },
        hasClose: {
            type: Boolean,
            default: true
        }
    },
    emits: ["close", "scroll-end"],

    computed: {
        hasFooterSlot() {
            return !!this.$slots["footer"];
        },
        popupSize() {
            return `width: ${typeof this.width == "number" ? this.width + "px" : this.width};

                    ${
                        this.screenWidth < 1600 && this.isLarge
                            ? "height: 95vh"
                            : this.height
                            ? typeof this.height == "number"
                                ? "height: " +
                                  this.height +
                                  "px;margin-top: calc(50vh - " +
                                  (50 + this.height / 2) +
                                  "px)"
                                : this.height == "auto"
                                ? "max-height: 88vh;margin-top: -10vh;margin-bottom:-10vh;"
                                : "height:" + this.height
                            : "height: calc(80vh - 2.5rem)"
                    }`;
        },
        tokenClose() {
            return this.popup.tokenClose;
        },
        popup() {
            return this.$store.getters["builder/popup"];
        },
        screenWidth() {
            return this.$store.getters["builder/getCurrentScreenWidth"];
        }
    },
    methods: {
        onScroll(e) {
            let target = e.target;
            if (target.offsetHeight + target.scrollTop + 50 >= target.scrollHeight) {
                clearTimeout(this.itv);
                this.itv = setTimeout(() => {
                    this.$emit("scroll-end");
                }, 400);
            }
        },
        closePopup(e) {
            if (e) {
                this.$emit("close", e);
            }
        }
    },
    mounted() {
        setTimeout(() => {
            const wrapper = this.$refs.wrapper;
            this.$nextTick(() => wrapper.focus());
            if (wrapper) {
                const container = wrapper.querySelector(".popup-container");
                if (container) {
                    container.classList.remove("-translate-x-8", "opacity-0");
                    container.classList.add("translate-x-0", "opacity-100");
                }
            }
        }, 10);
    }
};
</script>
<style scoped>
.outside-close-cursor {
    cursor: url("/images/closeCursor.svg") 15 15, auto;
}
.no-close-cursor {
    box-shadow: 0px 20px 20px -8px #1a1a1a47, 0px 1px 0px 0px #cccccc80 inset,
        0px -1px 0px 0px #0000002b inset, -1px 0px 0px 0px #0000002b inset,
        1px 0px 0px 0px #00000021 inset;
}
.ecom-default-cursor {
    cursor: default;
}
.ecom-popup-footer {
    box-shadow: 0px -2px 0px 0px #eeeeee;
}
.ecom-notice-popup .ecom-popup-list_wrapper {
    overflow-y: hidden;
}
</style>
