        javascript() {
            return function () {
                let $el = this.$el;
                if(!$el) return;


                let tabs = $el.querySelectorAll(":scope > .tabs__wrapper > div > .tabs__navs > .tabs__navs--items > .tabs__nav"),
                tabsBody = $el.querySelectorAll(":scope > .tabs__wrapper > .core__group--items > .tab__item"),
                action = this.settings.action;

                // Helper function để xử lý tab change
                function handleTabChange(tab, index) {
                    if (tab.classList.contains("ecom-item-active")) return;

                    tabs.forEach((item) => item.classList.remove("ecom-item-active"));
                    tabsBody.forEach((item) => item.classList.remove("ecom-item-active"));
                    tab.classList.add("ecom-item-active");
                    tabsBody[index].classList.add("ecom-item-active");

                    // Refresh Splide sliders trong tab mới
                    setTimeout(() => {
                        const activeTabBody = tabsBody[index];
                        if (activeTabBody) {
                            activeTabBody.querySelectorAll('.ec_splide').forEach(slider => {
                                slider.ec_splide?.refresh();
                            });
                        }
                    }, 50);

                    resizeWindow();
                }

                tabs.forEach((tab, index) => {
                    if(action === 'click' || window.screen.width < 1025) {
                        tab.onclick = () => handleTabChange(tab, index);
                    } else {
                        tab.onmouseover = () => handleTabChange(tab, index);
                    }
                });
                function handleHash() {
                    let hash = window.location.hash;
                    if (hash) {
                        let dom = $el.querySelector(`[data-target="${hash}"]`);
                        if (dom) {
                            dom.click();
                            let mouseoverEvent = new MouseEvent('mouseover', {
                                bubbles: true,
                                cancelable: true,
                                view: window
                            });
                            dom.dispatchEvent(mouseoverEvent);
                            let elementRect = dom.getBoundingClientRect();
                            let absoluteElementTop = elementRect.top + window.pageYOffset;
                            let middle = absoluteElementTop - (window.innerHeight / 2);
                            window.scrollTo(0, middle);
                        }
                    }
                }

                setTimeout(()=> {
                    handleHash();
                }, 300);

                function resizeWindow(){
                    // Refresh Splide sliders (fix when image product in tab) và trigger resize cuối cùng
                    setTimeout(()=>{
                        const activeTab = $el.querySelector('.tab__item.ecom-item-active');
                        if (activeTab) {
                            activeTab.querySelectorAll('.ec_splide').forEach(slider => {
                                slider.ec_splide?.refresh();
                            });
                        }
                        window.dispatchEvent(new window.Event('resize'));
                    }, 100);
                }
                window.addEventListener("hashchange", handleHash, false);
            };
