    methods: {
        onTabNavContextmenu(item) {
            if (this.exporting) return;
            this.tabs.actived = item.id;
        },
        /** Clicks on nav outside title (e.g. icon) — open/select tab. */
        onTabNavClick(i, e) {
            if (this.exporting) return;
            if (e?.target?.closest?.(".tabs_nav--text")) return;
            this.setEditingElement(i);
        },
        /** Click on title — select the tab. */
        onTabTitleClick(i) {
            if (this.exporting) return;
            this.setEditingElement(i);
        },
        /** Switch visible tab panel in builder (title click uses @click.stop so exported tab.onclick never runs). */
        activateTabPanel(index) {
            if (this.exporting) return;
            const root = this.$el;
            if (!root) return;
            const navs = root.querySelectorAll(
                ":scope > .tabs__wrapper > div > .tabs__navs > .tabs__navs--items > .tabs__nav"
            );
            const bodies = root.querySelectorAll(
                ":scope > .tabs__wrapper > .core__group--items > .tab__item"
            );
            const tab = navs[index];
            const body = bodies[index];
            if (!tab || !body) return;
            if (tab.classList.contains("ecom-item-active")) return;
            navs.forEach((el) => el.classList.remove("ecom-item-active"));
            bodies.forEach((el) => el.classList.remove("ecom-item-active"));
            tab.classList.add("ecom-item-active");
            body.classList.add("ecom-item-active");
        },
        quickToolBar() {
            return ['items'];
        },
        setEditingElement(i) {
            if (this.exporting) return;
            this.$store.commit("builder/setEditingElement", this);
            if (!("tabOpened" in this.data.settings.items)) {
                Object.defineProperty(this.data.settings.items, "tabOpened", {
                    enumerable: false,
                    writable: true
                });
            }
            this.data.settings.items.tabOpened = i;
            this.activateTabPanel(i);
        },
        check(val) {
            return this.data.settings?.items?.filter((x) => x[val]).length;
        },
        content_alignment(item){
            let style = '';
            if(item?.content_alignment) {
                style += '--ec-align-ct: ' + item?.content_alignment + ';';
            }
            if(item?.content_alignment__tablet) {
                style += '--ec-align-ct-tb: ' + item?.content_alignment__tablet + ';';
            }
            if(item?.content_alignment__mobile) {
                style += '--ec-align-ct-mb: ' + item?.content_alignment__mobile + ';';
            }
            return style;
        },
    },
    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit("builder/setIsContentEditable", false);
                this.$store.commit("builder/setEditingElementId", "");
            }
            if (val) {
                this.$store.commit("builder/setEditingElementId", this.tabs.id);
            }
        },
        "data.settings.items.tabOpened": function (index) {
            if (index >= 0) {
                this.$nextTick(() => this.activateTabPanel(index));
            }
        },
    },
};
