<script lang="ts">
import { mapGetters } from 'vuex';
import {ChevronLeftMinor, refreshIcon, CancelMajor, ArrowLeftMinor, ChevronDownMinor, CaretDownMinor, crown } from '@/assets/icons';
import Tabs from './Tabs.vue';

import CSearch from '../molecules/Search/Search.vue';
import ImagePickerFilter from './ImagePickerFilter.vue';

export default {
    name: 'PickerFrameChild',
    components: {
        CSearch,
        Tabs,
        ImagePickerFilter
    },
    data() {
        return {
            icons: {
                ChevronLeftMinor, refreshIcon, CancelMajor, ArrowLeftMinor, ChevronDownMinor, CaretDownMinor, crown
            }
        }
    },
    props: {
        header: {
            type: Object,
            default() {
                return {};
            }
        },
        position: {
            type: String,
            default: 'absolute'
        },
        isQuickToolBar: {
            type: Boolean,
            default: false
        }
    },
    emits: ['back', 'reload', 'close', 'update:search', 'update:tabs', 'loadFreeImg', 'update:sort', 'update:filter'],
    computed: {
        ...mapGetters('picker', ['categories', 'loading', 'freeImgCat']),
        ...mapGetters('builder', ['largeScreen']),
        isQtbAnchored() {
            return this.isQuickToolBar && this.header?.type === 'icon';
        },
        cates() {
            let { type, subtype } = this.header;
            return this.categories({
                type,
                subtype
            });
        },
        is_shopify_trial() {
            let global = this.$store.getters['global/user'];
            return global?.shopify_plan == 'trial';
        },
        uploadImage(){
            return ['image', 'video'].includes(this.header?.type);
        },
        isShowSearch() {
            const curTab = this.header?.tabs?.cur;
            if (curTab == 'ai') {
                return false;
            }
            return this.header?.search?.show && (!this.freeImgCat || curTab == 'uploaded');
        },

    },
    methods: {
        back2FreeCat() {
            this.$store.commit('picker/freeImgCat', null);
            this.$emit('loadFreeImg');
        },
        handleSort() {
            this.$emit('update:sort', this.header?.sort == 'asc' ? 'desc' : 'asc');
        },
        showUpgradeModal() {
            // Close the font picker popup
            this.$emit('close');
            // Close the typography popover (Popup.vue watches isPopupOpen)
            this.$store.commit('builder/setIsPopupOpen', false);
            // Show the upgrade popup
            this.$store.dispatch('upgrade/showUpgradePopup', {
                feature_key: 'upload_font',
                source_location: 'font_upload',
            });
        },
    }
};
</script>

