import {store} from '@/store';
export const upload = async ({type, file, compress, waitForUrl}: {type: string, file: File, compress?: boolean, waitForUrl?: boolean}, onUploadProgress: any = null, _: any) => {
    if(file.size && file.size > 20 * 1024 * 1024) {
        _.$store.commit('global/setToast', {
            isError: true,
            message: "File size exceeds the maximum upload limit.",
            duration: 4000
        }, { root: true });
        return false;
    }
    let formData = new FormData();
    formData.append('type',(type === 'icon' || type === 'font') ? 'FILE' : type.toUpperCase());
    formData.append('file', file);
    formData.append('wait_for_url', waitForUrl ? '1' : '0');

    if(compress !== undefined && compress !== null) {
        formData.append('compress', compress)
    }
    try {
        // console.log('Upload data', formData);
        const res = await _.$worker.fetch(
            route(type === 'icon' ? 'builder.icons' : 'builder.files'),
            formData,
            'POST'
        );
        if (res.status === 'error') {
            _.$store.commit('global/setToast', {
                isError: true,
                message: res.message  == 'Payload Too Large' ? "File size exceeds the maximum upload limit." : res.message,
                duration: 4000
            }, { root: true });
            return false;
        }
        if (res.data.status  === 'success') {
            let resData = res.data;
            return resData;
        }
        else {
            _.$store.commit('global/setToast', {
                isError: true,
                message: res.data.message,
                data: res.data,
                duration: 4000
            }, { root: true });
        }
        throw new Error(res.data.message);
    }
    catch(err) {
        _.$store.commit('global/setToast', {
            isError: true,
            message: err.message,
            data: err,
            duration: 4000
        }, { root: true });

        return false;
    }

};

export const fetch = async (type, subtype, query, next, limit, _) => {
    const getRoute = (params: null) => {
        switch (type) {
            case 'video':
            case 'audio':
                return route( 'builder.files', params);
            case 'image':
            case 'font':
                return route((subtype === 'free' || subtype === 'google') ? 'builder.bridge' : 'builder.files',params);
            case 'icon':
                return route('builder.icons',params);
            default:
                return route('builder.picker',params);
        }
    };

    const getParams = () => {
        let params = {};
        switch (type) {
            case 'icon': {
                params.type = subtype;
                if(query){
                    params.query = query;
                }
                if(next){
                    params.page = next;
                }
                params.limit = limit;
                break;
            }
            default: {
                if(subtype === 'free'){
                    if(next){
                        params.url = next;
                    }else{
                        params.url = 'https://burst.shopify.com/tools/stock-photos/api/photos'
                                        + ( query ? ('/search?q=') + query : '');
                    }
                }
                else if(subtype === 'google'){
                    params.url = 'https://www.googleapis.com/webfonts/v1/webfonts?key=AIzaSyCrsTDigL61TFHYPHTZduQP1cGi8CLfp90&sort=popularity';
                }
                else{
                    params.type = type;
                    params.limit = limit;
                    if(query){
                        params.query = query;
                    }
                    if(next){
                        params.page = next;
                    }
                }
                break;
            }
        }
        return params;
    };

    const formatResData = (resData) => {
        return resData.map(item => {
            if(type === 'image' || type === 'font'){
                if(subtype === 'free'){
                    let {id, title: name, url: value, url} = item;
                    let thumbnail = _.$helpers.resizeImage(url, {width: 150, height: 150});
                    return {
                        fn: 'item', id, name, value, url, thumbnail
                    };
                }
                else if(subtype === 'google'){
                    const url = (name) => 'https://fonts.googleapis.com/css?family='+name.replace(/\s/g, '+')+':100,200,300,400,500,600,700,800,900';
                    let {family: name, family: thumbnail} = item;
                    return {
                        fn: 'item',
                        id: _.$helpers.makeId(8),
                        name,
                        thumbnail,
                        value: url(name)
                    };
                }else{
                    let k = type === 'font' ? 'url' : 'src';
                    let {id, [k]: value, [k]: url, [k]: thumbnail} = item;
                    let name = _.$helpers.file.name(value);
                    let ext = _.$helpers.file.ext(value);
                    return {
                        fn: 'item', id, name, ext, value, url, thumbnail
                    };
                }
            }
            else if(type === 'icon'){
                let {keywords, name,  url, url: value, url: thumbnail} = item;
                if(!name){
                    name = _.$helpers.file.name(value);
                }

                let rs = {
                    id: item.id ?? _.$helpers.makeId(8),
                    fn: 'item', name, value, url, thumbnail
                };
                if(subtype !== 'uploaded') {
                    let cate = keywords.split(',')[0];
                    rs['cate'] = cate;
                }
                return rs;
            }
            else{
                let {id, title: name, image: url, handle: value} = item;
                let thumbnail = _.$helpers.resizeImage(url, {width: 150, height: 150});
                return {
                    fn: 'item', id, name, value, url, thumbnail
                };
            }
        });
    };

    const processing = (res) => {
        let after = false, before = false, items = [];

        if(subtype === 'free'){
            ({next: after = false, previous: before = false} = res?.result?.metadata?.paging ?? {});
        }
        else {
            ({next: after = false, previous: before = false} =  res?.data?.pageInfo ?? {});
        }
        items = formatResData(  res?.data?.files ??
                                res?.data?.items ??
                                res?.result?.data ??
                                res?.result?.items ??
                                res?.icons ??
                                []);
        return {after, before, items};
    };

    if(!type){
        return {items: [], before: false, after: false};
    }

    let params = getParams();
    const res = await _.$worker.fetch(getRoute(params), null, 'GET');


    if (res.status == 200) {
        let resData = res.data;
        if(resData['status'] === 'success'){
            return processing(resData);
        }
    }
    return {items: []};
};

export const remove = async (id, _) => {

    const res = await _.$worker.fetch(route('builder.files'),{
        ids: id,
        _method: 'DELETE'
    }, 'DELETE');
    if (res.data.status === 'success') {
        let resData = res.data;
        return resData;
    }
    return false;
};

export function slugify(text: string) {
    return text
        .toString()
        .toLowerCase()
        .normalize('NFD')                   // Chuyển thành dạng không dấu
        .replace(/[\u0300-\u036f]/g, '')   // Xóa dấu tiếng Việt
        .replace(/[^a-z0-9 -]/g, '')       // Xóa ký tự không phải chữ số, khoảng trắng, gạch ngang
        .replace(/\s+/g, '-')              // Thay khoảng trắng bằng gạch ngang
        .replace(/-+/g, '-')               // Xóa gạch ngang trùng lặp
        .replace(/^-+/, '')                // Xóa gạch ngang ở đầu
        .replace(/-+$/, '');               // Xóa gạch ngang ở cuối
}


export function base64ToFile(base64, title) {
    const arr = base64.split(',');
    const mime = arr[0].match(/:(.*?);/)[1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);

    while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
    }

    // Tạo filename từ title
    const slug = slugify(title);
    const extension = mime.split('/')[1] || 'png'; // Lấy extension từ mime type
    const filename = `${slug}.${extension}`;

    return new File([u8arr], filename, { type: mime });
}


export async function convertDataImageFromAiToBase64(b64Json: string) {
    try {
        console.log('Processing b64_json from AI generation');
        
        // 1. Kiểm tra format (có thể là PNG, JPEG, WEBP, v.v.)
        // b64_json từ AI thường là PNG hoặc JPEG
        let mimeType = 'image/png';
        
        // Phân tích base64 để xác định loại ảnh
        if (b64Json.startsWith('/9j/') || b64Json.startsWith('/9j/4AAQ')) {
            mimeType = 'image/jpeg';
            console.log('Detected JPEG format');
        } else if (b64Json.startsWith('iVBORw0KGgo')) {
            mimeType = 'image/png';
            console.log('Detected PNG format');
        } else if (b64Json.startsWith('UklGR')) {
            mimeType = 'image/webp';
            console.log('Detected WEBP format');
        } else {
            console.log('Unknown format, defaulting to PNG');
        }
        // 2. Tạo data URL với prefix đúng
        const dataUrl = `data:${mimeType};base64,${b64Json}`;
        console.log('Created data URL with mime type:', mimeType);
        return {
            success: true,
            data: dataUrl
        };
    } catch (error: any) {
        console.error('Error convert data AI image to base64:', error);
        return {
            success: false,
            message: error.message || 'Unknown error during convert data'
        };
    }
}

export const fetchImageWithXHR = (url: string): Promise<Blob> => {
    return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('GET', url, true);
        xhr.responseType = 'blob';
        xhr.onload = () => {
            if (xhr.status === 200) {
                resolve(xhr.response);
            } else {
                reject(new Error(`XHR failed: ${xhr.status}`));
            }
        };
        xhr.onerror = () => reject(new Error('XHR network error'));
        xhr.send();
    });
};

export async function uploadAIImage(
    b64Json: string,  // raw base64 từ AI (không có data:image/... prefix)
    altText: string,
    endpoint: string,
    options: CoreUploadOptions = {}
): Promise<{ url?: string; success: boolean; message?: string }> {
    try {
        console.log('Processing b64_json from AI generation');
        
        // 1. Kiểm tra format (có thể là PNG, JPEG, WEBP, v.v.)
        // b64_json từ AI thường là PNG hoặc JPEG
        let mimeType = 'image/png';
        
        // Phân tích base64 để xác định loại ảnh
        if (b64Json.startsWith('/9j/') || b64Json.startsWith('/9j/4AAQ')) {
            mimeType = 'image/jpeg';
            console.log('Detected JPEG format');
        } else if (b64Json.startsWith('iVBORw0KGgo')) {
            mimeType = 'image/png';
            console.log('Detected PNG format');
        } else if (b64Json.startsWith('UklGR')) {
            mimeType = 'image/webp';
            console.log('Detected WEBP format');
        } else {
            console.log('Unknown format, defaulting to PNG');
        }
        
        // 2. Tạo data URL với prefix đúng
        const dataUrl = `data:${mimeType};base64,${b64Json}`;
        console.log('Created data URL with mime type:', mimeType);
        
        // 3. Convert base64 to file
        const imgFile = base64ToFile(dataUrl, altText || 'ai-generated-image.png');
        
        if (!imgFile) {
            return {
                success: false,
                message: 'Failed to convert AI generated image to file'
            };
        }
        
        console.log('Created file from AI generation:', {
            name: imgFile.name,
            size: imgFile.size,
            type: imgFile.type
        });
        
        // 4. Gọi coreUpload
        const result = await coreUpload(imgFile, endpoint, {
            type: 'image',
            compress: false,
            ...options
        });
        
        console.log('Response from upload:', result);
        
        if (result.status === 'success' && result.data) {
            const url = result.data.url || result.data.src || result.data.value;
            return {
                url,
                success: true
            };
        } else {
            return {
                success: false,
                message: result.message || 'Upload failed'
            };
        }
    } catch (error: any) {
        console.error('Error uploading AI generated image:', error);
        return {
            success: false,
            message: error.message || 'Unknown error during upload'
        };
    }
}

