<template>
    <div class="ecom-element ecom-collection ecom-collection__banner" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-collection__banner-wrapper" 
            :class="[
                data.settings.background_parallax ? 'ecom-banner-use-parallax' : '',
                data.settings.hide_if_no_featured && hasFeaturedImage ? 'ecom-collection__banner-hide' : '',
                data.inGrid ? 'ecom-ingrid-full-height' : ''
            ]"
            :style="styleWraper"
        >
            <div v-if="data.settings.background_parallax" class="ecom-parallax-background">
                <img :src="linkImage" alt="">
            </div>
            <h1
                v-if="show_title"
                class="ecom-collection__banner-heading"
                v-html="liquid('title')"
            />
            <div
                v-if="show_description"
                class="ecom-collection__banner-paragraph"
                v-html="liquid('description')"
            />
            <div v-if="data.settings.overlay" class="ecom-overlay" />
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
    name: 'CollectionBanner',
    presets:true,
    docs: 'https://help.ecomposer.io/docs/elements/collection-elements/banner/',
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {}
        }
    },
    data() {
        return {
            jsreactives: ['background_parallax']
        }
    },
    computed: {
        javascript() {
            return function() {
                if(!this.$el) return;
                const $el = this.$el;
                const imageParallax = $el.querySelector(".ecom-banner-use-parallax .ecom-parallax-background img");
                if(!imageParallax) return;
                const imageParent = imageParallax.parentNode;
                function isInViewport(element) {
                    const rect = element.getBoundingClientRect();
                    return (
                        // rect.top >= 0 &&
                        rect.bottom > 0 &&
                        rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) 
                    );
                }
                function parallaxImg(image) {
                    if(!image) return;
                    let speed = -1,
                        imgY = imageParent.offsetTop,
                        winY = window.scrollY ?? 0,
                        winH = window.innerHeight,
                        parentH = imageParent.clientHeight;
                    const winBottom = winY + winH;
                    
                        // if (winBottom > imgY && winY < imgY + parentH) {
                            const imgBottom = (winBottom - imgY) * speed;
                            const imgTop = winH + parentH;
                            const imgPercent = (imgBottom / imgTop) * 100 + (50 - speed * 50);
                            image.style.top = imgPercent + '%';
                            image.style.transform = `translate(-50%, -${imgPercent}%)`;
                        // }
                }
                function handleScrollParallax() {
                    imageParent.style.display = 'flex';
                    if(isInViewport(imageParent)) {
                        parallaxImg(imageParallax);
                    }
                }
                handleScrollParallax();
                document.addEventListener('scroll', handleScrollParallax);
            }
        },
        liquids() {
            return {
                image: {
                    code: `
                        ${this.data.settings?.default_banner
                            ? `{%- capture default_img -%}${this.data.settings?.default_banner?.value}{%- endcapture -%}`
                            : ''
                        }
                    {%- assign banner = 'https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273' -%}
                    {%- if collection.featured_image -%}
                        {%- assign banner = collection.featured_image | image_url: width: 2048 -%}
                    {%- elsif default_img -%}
                    {%- assign banner = default_img -%}
                    {%- endif -%}
                    {{ banner }}`,
                    preview: `https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273`
                },
                title: {
                    code: '{{ collection.title }}',
                    preview: 'The sample collection title'
                },
                description: {
                    code: '{{ collection.description }}',
                    preview: 'The sample collection description'
                }
            };
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('image_source'),
                            name: 'source',
                            value: 'collection',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    collection: this.$t('collections'),
                                    file: this.$t('file_upload')
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('custom_banner'),
                            name: 'banner',
                            options: {
                                type: 'image',
                                multiple: false,
                                visible: function (data) {
                                    return data['source'] === 'file';
                                }
                            },
                            value: {
                                value: 'https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273'
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('default_banner'),
                            name: 'default_banner',
                            description: this.$t('default_image_will_display_if_collection_not_have_image'),
                            options: {
                                type: 'image',
                                multiple: false,
                                visible: function (data) {
                                    return data['source'] === 'collection';
                                }
                            },
                            value: {
                                value: 'https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273'
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_title'),
                            value: true,
                            name: 'show_title',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_description'),
                            value: true,
                            name: 'show_description',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline:true
                            },

                        },
                        {
                            type: 'toggle',
                            label: this.$t('enable_parallax_background'),
                            name: 'background_parallax',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('enable_overlay'),
                            name: 'overlay',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                        {
                            type: 'toggle',
                            label: 'Hide element if no featured image',
                            name: 'hide_if_no_featured',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                        {
                            name: "position",
                            label: this.$t('content_position'),
                            type: "popup",
                            value: "center center",
                            options: {
                                default: false,
                                preview: 'title',
                                values: {
                                    "center center": this.$t('center_center'),
                                    "center right": this.$t('center_right'),
                                    "center left": this.$t('center_left'),
                                    "top left": this.$t('top_left'),
                                    "top center": this.$t('top_center'),
                                    "top right": this.$t('top_right'),
                                    "bottom right": this.$t('bottom_right'),
                                    "bottom left": this.$t('bottom_left'),
                                    "bottom center": this.$t('bottom_center'),
                                },
                                type: "dropdown",
                                oneline: true,
                            },
                            css: {
                                selector: ' .ecom-collection__banner-wrapper',
                                properties: {
                                    'align-items': `
                                        switch(value) {
                                            case 'center center':
                                            case 'top center':
                                            case 'bottom center':
                                                return 'center';
                                            case 'top left':
                                            case 'bottom left':
                                            case 'center left':
                                                return 'flex-start';
                                            case 'top right':
                                            case 'bottom right':
                                            case 'center right':
                                                return 'flex-end';
                                        }
                                    `,
                                    'justify-content': `
                                        switch(value) {
                                            case 'center center':
                                            case 'center right':
                                            case 'center left':
                                                return 'center';
                                            case 'top center':
                                            case 'top left':
                                            case 'top right':
                                                return 'flex-start';
                                            case 'bottom center':
                                            case 'bottom left':
                                            case 'bottom right':
                                                return 'flex-end';
                                        }
                                    `
                                }
                            }
                        },
                        {
                            label: this.$t('custom_height'),
                            name: 'min-height',
                            type: 'number',
                            options: {
                                responsive: true,
                                slider: true,
                                units: {
                                    px: {
                                        min: 100,
                                        max: 1000
                                    }
                                },
                                visible: {
                                    condition: (data) => {
                                        return !this.data.inGrid;
                                    },
                                    keep_data: false
                                }
                            },
                            css: {
                                selector: ' .ecom-collection__banner-wrapper'
                            }
                        }
                    ]
                }
            ];
        },

        source() {
            return this.data && this.data.settings && 'source' in this.data.settings
                ? this.data.settings.source
                : 'collection';
        },
        banner() {
            return this.data && this.data.settings && 'banner' in this.data.settings
                ? this.data.settings.banner
                : 'https://cdn2.shopify.com/s/files/1/0121/5945/1236/files/backpack.svg?7273';
        },
        show_title() {
            return this.data && this.data.settings && 'show_title' in this.data.settings
                ? this.data.settings.show_title
                : false;
        },
        show_description() {
            return this.data && this.data.settings && 'show_description' in this.data.settings
                ? this.data.settings.show_description
                : false;
        },
        linkImage() {
            return this.source === 'collection' ? this.liquid('image') : this.banner.value
        },
        styleWraper() {
            let s = {
                'backgroundImage':
                    'url("' +
                    (this.source === 'collection' ? this.liquid('image') : this.banner.value) +
                    '")'
            };
            return this.data.settings.enable_parallax_background ? '' : s
        },
        hasFeaturedImage() {
            return this.liquid('image').includes('products/');
        },

        requestShopifyType() {
            return {
                shopify_type: 'collection'
            };
        },

        css() {
            return `
                .ecom-parallax-background {
                    position: absolute;
                    width: 100%;
                    height: 100%;
                    display: none;
                    overflow: hidden;
                }
                .ecom-parallax-background img {
                    max-width: unset !important;
                    object-fit: cover;
                    width: 100%;
                    position: absolute;
                    top: 0;
                    left: 50%;
                    transform: translate(-50%,0);
                    pointer-events: none;
                }
                .ecom-collection__banner-wrapper{
                    display:flex;
                    flex-direction: column;
                    justify-content:center;
                    background-size: cover;
                    background-repeat: no-repeat;
                    background-position: center;
                    position:relative;
                }
                .ecom-collection__banner-hide {
                    display: none !important;
                }
                /* Remove because Content position don't work */
                /*.ecom-collection__banner .ecom-collection__banner-wrapper {
                    display: block !important;
                }*/
                .ecom-collection__banner-wrapper .ecom-collection__banner-heading{
                    position:relative;
                    z-index:1;
                }
                .ecom-collection__banner-wrapper .ecom-collection__banner-paragraph{
                    position:relative;
                    z-index:1;

                }
                .ecom-collection__banner-wrapper .ecom-overlay{
                    position:absolute;
                    top:0;
                    left:0;
                    right:0;
                    bottom:0;
                    display:block;
                }
                @media(max-width: 767px) {
                    .ecom-parallax-background img {
                        width: 200%;
                    }
                }
            `;
        },

        default() {
            return {
                "settings": {
                    "source": "collection",
                    "show_title": true,
                    "show_description": true,
                    "position": "center center",
                    "overlay": false,
                    "banner": {
                        "value": "/images/placeholder.png"
                    },
                    "min-height": "300px",
                    "justify-content": "center"
                },
                "style": {
                    "overlay": {
                        "tab": "normal",
                        "imageOpacity": 0.35,
                        "backgroundnormalmode": {
                            "classic": {
                                "background-color": "#f78b8b"
                            }
                        }
                    }
                }
            }
        }
    },
    methods: {
        style() {
            let style = [
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('title'),
                        group_name: 'title',
                        selector: ' .ecom-collection__banner-heading'
                    },
                    modify: {
                        remove: {
                            index:0 ,length: 1
                        }
                    }
                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('description'),
                        group_name: 'description',
                        selector: ' .ecom-collection__banner-paragraph'
                    },
                    modify: {
                        remove: {
                            index:0 ,length: 1
                        }
                    }
                },
                {
                    group_title: this.$t('background'),
                    group_name: 'background',
                    selector: ' .ecom-collection__banner-wrapper',
                    params: [
                        // {
                        //     type: 'background',
                        //     label: this.$t('style'),
                        //     name: 'background',
                        //     options: {
                        //         responsive: true,
                        //         types: ['classic'],
                        //         image: false,
                        //         color: false
                        //     },
                        //     css: {
                        //         properties: {
                        //             background: ''
                        //         }
                        //     }
                        // },
                        {
                            name: "background-position",
                            label: this.$t('position'),
                            type: "popup",
                            value: "center center",
                            options: {
                                default: false,
                                preview: 'title',
                                values: {
                                    "center center": this.$t('center_center'),
                                    "center right": this.$t('center_right'),
                                    "center left": this.$t('center_left'),
                                    "top left": this.$t('top_left'),
                                    "top center": this.$t('top_center'),
                                    "top right": this.$t('top_right'),
                                    "bottom right": this.$t('bottom_right'),
                                    "bottom left": this.$t('bottom_left'),
                                    "bottom center": this.$t('bottom_center'),
                                    // custom: this.$t('custom')
                                },
                                type: "dropdown",
                                oneline: true,
                            },
                            css: {
                                properties: {
                                    'background-position': ''
                                }
                            }
                        },
                        {
                            name: "background-attachment",
                            label: this.$t('attachment'),
                            type: "popup",
                            options: {
                                default: false,
                                preview: 'title',
                                values: {
                                    fixed: this.$t('fixed'),
                                    scroll: this.$t('scroll'),
                                    local: this.$t('local'),
                                    inherit: this.$t('inherit')
                                },
                                type: "dropdown",
                                oneline: true,
                            },
                            css: {
                                properties: {
                                    'background-attachment': ''
                                }
                            }
                        },
                        {
                            name: "background-repeat",
                            label: this.$t('repeat'),
                            type: "popup",
                            options: {
                                default: false,
                                preview: 'title',
                                values: {
                                    "no-repeat": this.$t('no_repeat'),
                                    repeat: this.$t('repeat'),
                                    "repeat-x": this.$t('horizontally'),
                                    "repeat-y": this.$t('verically'),
                                },
                                type: "dropdown",
                                oneline: true,
                            },
                            css: {
                                properties: {
                                    'background-repeat': ''
                                }
                            }
                        },
                        {
                            name: "background-size",
                            label: this.$t('size'),
                            type: "popup",
                            options: {
                                type: "dropdown",
                                default: false,
                                preview: 'title',
                                values: {
                                    cover: this.$t('cover'),
                                    auto: this.$t('auto'),
                                    contain: this.$t('contain'),
                                    inherit: this.$t('inherit'),
                                },
                                oneline: true
                            },
                            css: {
                                properties: {
                                    'background-size': ''
                                }
                            }
                        }
                    ]
                }
            ];
            if ('overlay' in this.data.settings) {
                style.push({
                    group_alias: 'background:overlay',
                    options: {
                        group_title: this.$t('overlay'),
                        group_name: 'overlay',
                        selector: ' .ecom-collection__banner-wrapper',
                    }
                });
            }
            return style;
        }
    }
};
</script>
