<template>
    <div
        v-bind="blockAttrs"
        @mouseenter="overGroup"
        @mouseleave="outGroup"
        @contextmenu="rightClickMenu"
        @mousedown="activeGroup"
    >
        {{ conditionStart }}
        <div
        class="core__group--wrapper"
            :data-r="refresh"
            :style="styleattr.wrapper"
            :class="[gclass.wrapper, !exporting && isEditing ? 'ecom_current-edit' : '', inGrid ? 'ecom-ingrid-full-height' : '', isActiveBorder && !grid ? 'ecom-group-active' : '']"
        >
            <div
                v-if="isEditing && !exporting && !isFullScreen && $parent?.$parent?.isFlexContainer"
                class="ecom-resize-flexbox"
                @mousedown.prevent.stop="startDragResize($event, 'custom-width', $parent.$parent.$refs.wrapper, 'block', 'right')"
            >
                <span v-if="dragResize.isActive && dragResize.direction !== 'left'">
                    {{ dragResize.finalWidth }}
                </span>
            </div>
            <div
                v-if="isEditing && !exporting && !isFullScreen && $parent?.$parent?.isFlexContainer"
                class="ecom-resize-flexbox ecom-resize-left"
                @mousedown.prevent.stop="startDragResize($event, 'custom-width', $parent.$parent.$refs.wrapper, 'block', 'left')"
            >
                <span v-if="dragResize.isActive && dragResize.direction === 'left'">
                    {{ dragResize.finalWidth }}
                </span>
            </div>
            <slot
                name="before"
                :items="gitems"
                :haActived="haActived"
            />
            <slot
                name="items"
                :items="gitems"
                :haActived="haActived"
            >
                <div
                    class="core__group--items"
                    :class="gclass.items"
                    :style="gstyle.items"
                >
                    <div
                        v-for="(gitem, i) in gitems"
                        :id="gitem.id ? gitem.id : ''"
                        :key="i"
                        :class="{
                            'core__group--item': 1,
                            [gclass.item]: gclass.item,
                            'ecom-item-active ecom-item-group-init': (!haActived && i === 0)
                        }"
                        :style="itemStyleFn ? itemStyleFn(gitem) : null"
                        :data-id="gitem.id"
                    >
                        <slot
                            name="title"
                            :item="gitem"
                            :haActived="haActived"
                            :index="i"
                        />

                        <div
                            v-if="nameElement != 'group'"
                            :class="{
                                'core__group--body': 1,
                                [gclass.body]: gclass.body
                            }"
                            :style="gstyle.body"
                        >
                            <div class="ec-flex-wp ecom-flex">
                                <Blocks
                                    v-if="data.template"
                                    :data="gblocks(gitem)"
                                    :deep="deep"
                                    :index="i"
                                    :control="control"
                                    :section_id="section_id"
                                    :breadcrumb="`${breadcrumb}`"
                                    :isFlexContainer="isFlexContainer"
                                />
                                <GroupLiquid
                                    v-else
                                    :deep="deep"
                                    :index="i"
                                    :control="control"
                                    :data="gitem"
                                    :section_id="section_id"
                                    :isProductBox="isProductBox"
                                    :breadcrumb="`${breadcrumb}`"
                                    :isFlexContainer="isFlexContainer"
                                />
                            </div>
                        </div>
                        <div
                            v-else
                            :class="{
                                'core__group--body': 1,
                                [gclass.body]: gclass.body
                            }"
                            :style="gstyle.body"
                        >
                            <Blocks
                                v-if="data.template"
                                :data="gblocks(gitem)"
                                :deep="deep"
                                :index="i"
                                :control="control"
                                :section_id="section_id"
                                :breadcrumb="`${breadcrumb}`"
                                :isFlexContainer="isFlexContainer"
                            />
                            <GroupLiquid
                                v-else
                                :deep="deep"
                                :index="i"
                                :control="control"
                                :data="gitem"
                                :section_id="section_id"
                                :isProductBox="isProductBox"
                                :breadcrumb="`${breadcrumb}`"
                                :isFlexContainer="isFlexContainer"
                            />
                        </div>
                    </div>
                </div>
            </slot>
            <slot
                name="after"
                :items="gitems"
            />
        </div>
        <template v-if="isDragging">
            <div
                class="placeholder__top"
                @mouseover="placehover"
            />
            <div
                class="placeholder__bottom"
                @mouseover="placehover"
            />
        </template>
        <template v-else />
        {{ conditionEnd }}
    </div>
</template>

<script>
    import { mapGetters } from 'vuex';
    import { Core, DragResize } from '@/mixins';
    import GroupLiquid from './GroupLiquid.vue';
    import { DragDropMajor, EditMinor, DuplicateMinor, DeleteMinor, ArrowDownMinor, ArrowUpMinor} from "@/assets/icons";
    export default {
        name: 'Group',
        mixins: [ Core, DragResize ],
        components: { GroupLiquid },
        props: {
            'data': {
                type: Object,
                default () {
                    return {};
                }
            },
            'index': {
                type: Number,
                default: 0
            },
            'deep': {
                type: Number,
                default: 0
            },
            'control': {
                type: Boolean,
                default: true
            },
            'gclasses': {
                type: Object,
                default () {
                    return {};
                }
            },
            'close_all': {
                type: Boolean,
                default: false
            },
            'gstyles': {
                type: Object,
                default () {
                    return {};
                }
            },
            'section_id': {
                type: String,
                default: ''
            },
            'isProductBox': {
                type: Boolean,
                default: false
            },
            'breadcrumb': {
                type: String,
                default: ''
            },
            inGrid: {
                type: Boolean,
                default: false
            },
            isFlexContainer: {
                type: Boolean,
                default: false
            },
            'itemStyleFn': {
                type: Function,
                default: null
            },
            nameElement: {
                type: String,
                default: 'group'
            }
        },
        data () {
            return {
                is: 'group',
                name: this.data.element,
                element: this.data.element,
                over: false,
                refresh: '',
                placeholder: '',
                validElements: ['heading', 'text', 'image', 'divi']
            };
        },
        computed: {
            isParentRow() {
                return this.$parent?.$parent?.isParentRow || false;
            },
            grid () {
                return this.$parent.$parent.grid;
            },
            locked () {
                return this.$store.getters['builder/editorConfigs']?.locked;
            },
            conditionStart() {
                if(this.conditionLiquid?.start && this.exporting === true) return this.conditionLiquid.start;
                return;
            },
            conditionEnd() {
                if(this.conditionLiquid?.start && this.exporting === true) return this.conditionLiquid.end;
                return;
            },
            conditionLiquid() {
                if(!this.condition) return {}
                let liquids = {
                    start: `
                            {% assign condition = true %}
                            ${this.condition ? this.condition : ''}
                            {% if condition %}
                        `,
                    end: `
                            {% endif %}
                        `
                };
                return liquids;
            },
            isFirst () {
                return this.index == 0;
            },

            isLast () {
                return this.index == this.$parent?.$parent?.$parent?.$parent?.blocks?.length - 1;
            },
            icons(){
                return {
                    DragDropMajor, EditMinor, DuplicateMinor, DeleteMinor, ArrowDownMinor, ArrowUpMinor
                };
            },
            css() {
                return `
                    .core__group--items {
                        flex: 1;
                    }
                `;
            },
            stack () {
                return this.$parent.$parent.$parent.$parent.blocks;
            },
            group () {
                return this.data;
            },
            column () {
                return this.block.$parent;
            },
            block () {
                return this.$parent.$parent;
            },
            blocks () {
                let re = this.gitems.filter((g) => { return g.id == this.data.actived; });
                if (re.length > 0) {
                    return re[0].blocks;
                } else {
                    return [];
                }
            },
            gitems () {
                return this?.group?.settings?.items ? this?.group?.settings?.items.filter(item => item?.visibility !== false) : [];// &&  this.group.settings  && this.group.settings.items ? this.group.settings.items : [];
            },
            gclass () {
                return this.gclasses ? this.gclasses : {};
            },
            gstyle () {
                return this.gstyles ? this.gstyles : {};
            },
            styleattr () {
                return {
                    wrapper: '',
                    settings: `display: ${this.isActiveBorder ? 'flex' : 'none'}`,
                };
            },
            blockAttrs () {
                return {
                    ref: 'wrapper',
                    class: {
                        'ecom-core ecom-group core__block': true,
                        'ecom-combined-elements': !this.control,
                        'ecom-ingrid-full-height': this.inGrid,
                        ...this.classes
                    },
                    ...this.attributes
                };
            },
            haActived() {
                return this.close_all;
            },
            isActive () {
                return !this.isFullScreen &&
                (
                    this.over
                ) && (
                    !this.dragCurrent ||
                    this.dragCurrent.is != 'section'
                );
            },
            isActiveBorder () {
                return !this.isFullScreen &&
                (
                    this.over ||
                    this.activeElement?.data?.id === this.data.id ||
                    this.editingElement?.data?.id === this.data.id
                ) && (
                    !this.dragCurrent ||
                    this.dragCurrent.is != 'section'
                );
            },
            isActiveSettings() {
                return (
                    !this.exporting &&
                    !this.isFullScreen &&
                    this.isEditing && !this.dragCurrent);
            },
            isEditing () {
                return this.editingElement?.data?.id === this.data.id;
            },
            isDragMe () {
                return this.dragCurrent === this.$parent.$parent;
            },
            isDropTo () {
                return this.dropTo === this.$parent.$parent;
            },
            sections() {
                return this.$store.getters['page/sections'];
            },
            //...mapGetters('builder', ['stacks'])
        },

        watch: {
            gitems: {
                immediate: true,
                deep: true,
                handler (val) {
                    if (val.length === 0) {
                        this.gitems.push({
                            'title': 'Untitled',
                            'blocks': []
                        });
                    }
                    this.gitems.forEach((gitem) => {
                        this.gindex(gitem);
                        this.gblocks(gitem);
                    });
                }
            }
        },

        created() {
            this.group.control = this.control;
        },

        methods: {
            moveSection(position) {
                let realIndex= this.stack.findIndex((s) => s.id == this.data.id), index = realIndex > -1 ? realIndex : this.index;
                const sections = this.$parent?.$parent?.blocks?.splice(index, 1) || this.$parent?.$parent?.$parent?.blocks?.splice(index, 1) || this.$parent?.$parent?.$parent?.$parent?.blocks?.splice(index, 1);
                const newIndex = position === 'prev' ? index - 1 : index + 1;
                if(this.$parent?.$parent?.blocks){
                    this.$parent?.$parent?.blocks?.splice(newIndex, 0, sections[0]);
                }else{
                    this.$parent?.$parent?.$parent?.$parent?.blocks?.splice(newIndex, 0, sections[0]);
                }
            },
            duplicate(){
                let height = this.$refs?.wrapper?.offsetHeight ?? 0,
                    clone = this.cloneData();

                if (clone.title) {
                    clone.title = clone.title.replace(/\(([\d]*)\)|$/, (...m) => {
                        if (m[1]) {
                            return '(' + (parseInt(m[1]) + 1) + ')';
                        } else {
                            return '(1)';
                        }
                    });
                }
                this.$parent.$parent.duplicate();
                this.scroll(height);
            },
            gindex (group) {
                if (group.id === undefined) {
                    group.id = this.$helpers.randid();
                }
                return group.id;
            },

            gblocks (group) {
                if (!group.blocks || typeof group.blocks != 'object') {
                    group.blocks = [];
                }
                return group.blocks;
            },

            overGroup () {
                if (!this.isFullScreen) {
                    this.over = true;
                    clearTimeout(this.timmer);
                }
            },

            outGroup () {
                if (!this.isFullScreen) {
                    clearTimeout(this.timmer);
                    this.timmer = setTimeout(() => {
                        this.over = false;
                    }, 100);
                }
            },

            placehover (e) {

                if (

                    this.isFullScreen || !this.isDragging
                    ['section', 'column'].indexOf(this.dragCurrent.is) > -1

                ) {
                    return;
                }

                if (
                    this.dropTo !== this.$parent.$parent
                ) {
                    this.$store.commit('builder/setDropTo', this.$parent.$parent?.data?.id);
                }

                if (
                    this.dropTo === this.$parent.$parent
                ) {
                    let pos = e.target.classList.contains('placeholder__top') ? 'top' : 'bottom';
                    this.$parent.$parent.placeholder = pos;
                    this.dropPos = pos;
                    this.$store.commit('builder/setDropPos', pos);
                }
            },
            // Hold click on group to active --> conflict with element and column
            activeGroup(e) {
                let timmer = this.$store.getters['builder/dragging']?.timmer ?? null;
                if (
                    !this.isFullScreen &&
                    (
                        !timmer || timmer < new Date().getTime() - 250
                    )
                ) {
                    this.$store.commit('builder/setActiveElement', this.$parent.$parent);
                    this.$store.commit('builder/setEditingElement', this.$parent);
                    if(this.locked) {
                        this.$store.commit('builder/setShowNoticeLockmode', true);
                        return;
                    }
                    if(!this.data.inGrid) this.startDrag(e);
                }
            },

            editGroup (e) {
                this.$store.commit('builder/setActiveElement', this);
                this.$store.commit('builder/setEditingElement', this.$parent);
                if(!this.locked) {
                    this.startDrag(e);
                }else{
                    this.$store.commit('builder/setShowNoticeLockmode', true);
                };
            },

            deleteGroup () {
                if(this.section_id) {
                    const section = this.sections.find( (s) => s.id === this.section_id);
                    if(section) {
                        this.$store.dispatch('history/addStack', {
                            type: this.$options?.name ?? this?.name,
                            data: section,
                            section_id: this.section_id,
                            action: 'Deleted'
                        });
                    }
                }
                this.dropOut();
                this.$parent.$parent.$parent.refresh = Math.random().toString(36).substr(2, 5);
            },

            dropOut () {
                if (this.editingElement?.data?.id === this.$parent.data.id) {
                    this.$store.commit('builder/setActiveElement', null);
                    this.$store.commit('builder/setEditingElement', null);
                }
                return this.$parent.$parent.dropOut();
            },
            /*
            dropIn (current, pos) {
                this.stack.splice(
                    this.index + pos, 0, current.dropOut()
                );
                this.refresh = Math.random().toString(36).substr(2, 5);
            }*/

        }
    };
</script>