<template>
    <div class="ecom-element ecom-instagram">
        <div
            v-if="instagram.settings.layout !== 'slider'"
            class="ecom-instagram--container ecom-instagram-wrapper ecom-base-instagram-grid"
            v-html="liquid('medias')"
        />
        <div v-else class="ecom-instagram--container ecom-swiper-a11y-host">
            <button
                v-if="$helpers.hasAutoplayToggle(data.settings)"
                type="button"
                class="ecom-swiper-autoplay-toggle"
                :data-position="data.settings?.a11y_autoplay_control_position || 'bottom-right'"
                data-state="playing"
                data-label-pause="Pause automatic slide show"
                data-label-play="Start automatic slide show"
                aria-label="Pause automatic slide show"
            >
                <svg class="ecom-swiper-autoplay-toggle__pause" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5h3v14H8zM13 5h3v14h-3z"/></svg>
                <svg class="ecom-swiper-autoplay-toggle__play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5v14l11-7z"/></svg>
            </button>
            <div
                class="ecom-instagram--slider ecom-swiper-container"
            >
                <div class="ecom-instagram-wrapper ecom-swiper-wrapper" v-html="liquid('medias')" />
            </div>
            <div
                v-if="isNavigation && isCombined() == 'combine'"
                class="ecom-swiper-navigation"
                :data-navigator-type="isCombined() == 'combine'"
            >
                <div class="ecom-flex-center">
                    <button
                        type="button"
                        v-show="isArrow()"
                        class="ecom-swiper-button ecom-swiper-button-prev"
                        v-html="instagram.settings.slider_prev_icon"
                    />
                    <div v-show="isPagination()" class="ecom-swiper-pagination" />
                    <button
                        type="button"
                        v-show="isArrow()"
                        class="ecom-swiper-button ecom-swiper-button-next"
                        v-html="instagram.settings.slider_next_icon"
                    />
                </div>
            </div>
            <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isArrow()" class="ecom-swiper-navigation-position">
                <button
                    :style="sliderNav"
                    class="ecom-swiper-button ecom-swiper-button-prev"
                    v-html="instagram.settings?.slider_prev_icon"
                />
                <button
                    :style="sliderNav"
                    class="ecom-swiper-button ecom-swiper-button-next"
                    v-html="instagram.settings?.slider_next_icon"
                />
            </div>
            <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isPagination()" class="ecom-swiper-pagination-position ecom-swiper-pagination" />
        </div>
    </div>
</template>

<script>
import { Element, Javascript, Liquid } from "@/mixins";
import liquid from "@/mixins/liquid";
export default {
    name: "Instagram",
    linkVideo: "https://youtu.be/rYON5YBhlc0?si=h-rw0BNvYoePW057",
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/instagram/',
    presets:false,
    mixins: [Element, Javascript, Liquid],
    vendors: ["light_galerry", "modal_js", "modal_css", "slider_js", "slider_css"],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        },
        index: {
            type: Number,
            default: 0
        },
        deep: {
            type: Number,
            default: 0
        }
    },
    data() {
        return {
            is: "instagram",
            name: "Instagram",
            jsreactives: ["items", "spacing", "group", "navigator","lightbox", "layout", "itemsCount", "overlay_use", "overlay_title", "link", "hide_video"]
        };
    },
    computed: {
        idoc () {
            return window.EComposerBuilder.contentDocument;
        },

        liquids() {
            const settings = this.data.settings;
            let previewItemCount = 4,
                link = settings.link,
                lightbox = link === "media" ? settings.lightbox : false,
                enable_lazy = settings.enable_lazy ?? false,
                hide_video = settings.hide_video ?? false,
                layout = settings.layout,
                overlay_use = settings.overlay_use,
                overlay_title = settings.overlay_title,
                limit = settings.itemsCount ? settings.itemsCount : 8;

            if (this.idoc) {
                const htmlWidth = this.idoc.querySelector('html').offsetWidth;
                if(htmlWidth) {
                    if (htmlWidth >= 768 && htmlWidth <= 1024) {
                        previewItemCount = 3;
                    } else if(htmlWidth < 768) {
                        previewItemCount = 2;
                    }
                }
            }



            return {
                medias: {
                    code: `
                        {%- assign instagram_medias = shop.metafields.ecomposer.instagram.value -%}
                        {% assign count = 0 %}

                        {% for m in instagram_medias %}
                            {% unless m.media_type == 'VIDEO' and ${hide_video} %}
                                {% if count < ${limit} %}
                                    {% assign count = count | plus: 1 %}
                                    <div class="ecom-instagram--item ${
                                        layout === "slider" ? " ecom-swiper-slide" : ""
                                    }">
                                        ${ link ? `<a target="_blank" href="${link === "media" ? `{{m.media_url}}` : `{{m.permalink}}`}" ${ lightbox == 'true' ? `ecom-modal="image"` : ""}>`
                                            : ""
                                        }
                                            <figure class="ecom-image-default">
                                                <img src="{{ m.thumbnail_url | default: m.media_url }}" alt="{{m.username}}" ${enable_lazy ? 'loading="lazy"' : ''}>
                                                ${
                                                    overlay_use
                                                        ? `<div class="ecom-base-instagram-overlay ecom-overlay">
                                                        ${
                                                            overlay_title
                                                                ? `<span class="ecom-overlay-text">${
                                                                    overlay_title ===
                                                                    "username"
                                                                        ? `{{m.username}}`
                                                                        : overlay_title === "caption"
                                                                        ? `{{m.caption}}` ?? ""
                                                                        : ""
                                                                }</span>`
                                                                : ""
                                                        }
                                                    </div>`
                                                        : ""
                                                }
                                            </figure>
                                        ${link ? "</a>" : ""}
                                    </div>
                                {% endif %}
                            {% endunless %}
                        {% endfor %}

                    `,

                    preview:

                        Array.from({length: previewItemCount})
                            .map(() => {
                                return `
                                    <div class="ecom-instagram__media--wrapper-item"></div>`;
                            })
                            .join("")
                }
            }
        },

        instagram() {
            return this.data;
        },
        screens() {
            let screens = this.$store.getters["builder/screens"];
            if (!screens) {
                return [];
            }
            return Object.entries(screens).sort(([, b1], [, b2]) => b1.width - b2.width);
        },
        screenMinW() {
            let rs = [];
            for (let i in this.screens) {
                let screen = this.$helpers.copy(this.screens[i]);
                screen[1].width = i === "0" ? 0 : parseInt(this.screens[i - 1][1].width) + 1;
                rs.push(screen);
            }
            return rs;
        },
        isNavigation() {
            return this.instagram.settings.slider_navigation_layout;
        },
        optionSwiper() {
            return this.$helpers.optionSwiper(this.instagram.settings);
        },
        sliderNav(){
            return {
                position: this.instagram.settings.navigation_position !== 'center' ? 'unset' : 'absolute'
            }
        },
        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: "paragraph",
                            content: this.$t('connect_your_instagram_account_to_get_photos_connect_here_settings_app_settings_apps')
                        },
                        {
                            type: "popup",
                            name: "layout",
                            label: this.$t('layout'),
                            options: {
                                type: "dropdown",
                                default: false,
                                preview: 'title',
                                values: {
                                    grid: this.$t('grid'),
                                    slider: this.$t('slider'),
                                }
                            }
                        },
                        {
                            type: "popup",
                            name: "link",
                            label: this.$t('image_link'),
                            options: {
                                type: "dropdown",
                                default: false,
                                preview: 'title',
                                values: {
                                    "": this.$t('none'),
                                    media: this.$t('media_link'),
                                    instagram: this.$t('instagram_post'),
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'enable_lazy',
                            label: this.$t('enable_lazyload'),
                            options: {
                                preview: 'title',
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'hide_video',
                            label: this.$t('don_t_get_video_post'),
                            options: {
                                values: {
                                    on: {
                                        label: 'yes',
                                        value: true
                                    },
                                    off: {
                                        label: 'no',
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "popup",
                            name: "lightbox",
                            label: this.$t('lightbox'),
                            value: false,
                            options: {
                                type: "dropdown",
                                default:false,
                                preview: 'title',
                                values: {
                                    true: this.$t('yes'),
                                    false: this.$t('no'),
                                },
                                visible: (data) => {
                                    return data["link"] === "media";
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t('maximum_items_to_show'),
                            name: "itemsCount",
                            options: {
                                min: 1,
                                max: 30
                            }
                        },
                        {
                            type: "paragraph",
                            content: "** "+ this.$t('overlay') +" **"
                        },
                        {
                            type: "toggle",
                            name: "overlay_use",
                            label: this.$t('enable_overlay'),
                            value: true,
                            options: {
                                values: {
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    },
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: "popup",
                            label: this.$t('title_source'),
                            name: "overlay_title",
                            options: {
                                type: "dropdown",
                                preview: 'title',
                                values: {
                                    "": this.$t('none'),
                                    username: this.$t('username'),
                                    caption: this.$t('caption'),
                                },
                                visible: (data) => {
                                    return data["overlay_use"] === true;
                                }
                            }
                        }
                    ]
                },
                {
                    group_alias: "swiper",
                    options: {
                        group_title: this.$t('slider_settings'),
                        options: {
                            keep_data: false,
                            visible: (data) => {
                                return data["layout"] == "slider";
                            }
                        }
                    },
                    modify: {
                        remove: {
                            // name: ['line_pagination','title_pagination','slider_pagination_style', 'slider_spacing_row']
                        }
                    }
                },
                {
                    group_title: this.$t('grid_settings'),
                    options: {
                        visible: {
                            keep_data: false,
                            condition: (data) => data.layout !== "slider"
                        }
                    },
                    params: [
                        {
                            type: "number",
                            label: this.$t('items_per_row'),
                            name: "slider_items",
                            options: {
                                responsive: true,
                                min: 1,
                                max: 12
                            },
                            css: {
                                selector: " .ecom-instagram--container.ecom-base-instagram-grid",
                                properties: {
                                    "grid-template-columns": "repeat(%value%, 1fr)"
                                }
                            }
                        }
                    ]
                }
            ];
        },
        css() {
            return `
${this.$helpers.autoplayToggleCss()}
                    /**
                     * EComposer Element Instagram
                     */
                    .ecom-base-instagram-grid {
                        display: grid;
                        gap: 30px 30px;
                        grid-template-columns: repeat(4, 1fr)
                    }
                    .ecom-flex-center, .ecom-swiper-navigation {
                        display: flex;
                        align-items: center;
                    }
                    .ecom-swiper-navigation{
                        justify-content: center
                    }
                    .ecom-swiper-navigation[data-navigator-type="combine"]{
                        justify-content: center
                    }
                    .ecom-instagram--container:not(.ecom-base-instagram-grid) {
                        position: relative;
                        display: flex;
                        flex-direction: column;
                    }
                    .ecom-instagram--item figure{
                        position: relative;
                        overflow: hidden;
                    }
                    .ecom-instagram--container .ecom-instagram--item,
                    .ecom-instagram--container .ecom-instagram--item a{
                        display: block
                    }
                    .ecom-instagram--container .ecom-instagram--item img{
                        position: relative;
                        object-fit: cover;
                    }
                    .ecom-instagram .ecom-swiper-button-next:after,
                    .ecom-instagram .ecom-swiper-button-prev:after {
                        content: none;
                    }
                    .ecom-instagram .ecom-swiper-button-next,
                    .ecom-instagram .ecom-swiper-button-prev {
                        border: 0;
                        background: transparent;
                        width: auto;
                        height: auto;
                        padding: 5px;
                        color: #444;
                        margin-top: 0;
                        transform: translateY(-50%);
                    }
                    .ecom-instagram--container .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-next,
                    .ecom-instagram--container .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-prev {
                        position: static;
                        margin: 0;
                        transform: none;
                    }
                    .ecom-instagram--slider,
                    .ecom-instagram--container .ecom-swiper-navigation[data-navigator-type="classic"] .ecom-swiper-pagination,
                    .ecom-instagram--container .ecom-swiper-navigation:not([data-navigator-type]) .ecom-swiper-pagination {
                        width:100%
                    }
                    .ecom-swiper-pagination-bullet:only-child {
                        opacity: none
                    }
                    .ecom-instagram .ecom-swiper-pagination:not(.ecom-swiper-pagination-progressbar) {
                        position: static;
                        color: rgb(5, 150, 105);
                        display:flex;
                        flex-wrap:wrap;
                        justify-content:center;
                        padding:10px;
                    }
                    .ecom-swiper-navigation-position {
                        display: flex;
                    }
                    .ecom-instagram .ecom-swiper-pagination-bullet{
                       border-radius:unset
                    }
                    .ecom-instagram .ecom-swiper-pagination-bullet,
                    .ecom-instagram .ecom-swiper-pagination-bullet-active{
                        background: currentColor;
                    }
                    .ecom-base-instagram-overlay.ecom-overlay {
                        position: absolute;
                        inset: 0;
                        z-index: 1;
                        color: #ffffff;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        pointer-events: none;
                        background: rgba(0,0,0,0.3);
                    }
                    .ecom-base-instagram-overlay.ecom-overlay>span {
                        padding: 0 10%;
                        overflow: hidden;
                        text-overflow: ellipsis;
                        white-space: nowrap;
                    }
                    .ecom-instagram--item{
                        text-align:center;
                    }

                    .ecom-instagram__media--wrapper-item {
                        background-color: #ededed;
                        background: linear-gradient(100deg, rgba(255, 255, 255, 0) 40%, rgba(255, 255, 255, 0.5) 50%, rgba(255, 255, 255, 0) 60%) #ededed;
                        background-size: 200% 100%;
                        background-position-x: 180%;
                        padding-top: 100%;
                        -webkit-animation: loading 1s ease infinite;;
                        animation: loading 1.6s ease infinite;
                    }

                    @keyframes loading {
                        to {
                            background-position-x: -20%;
                        }
                    }
                `;
        },
        javascript() {
            return function () {
                // Nút pause autoplay (WCAG 2.2.2). Đọc $container.swiper lúc click
                // nên không phụ thuộc thứ tự init của slider bên dưới.
                var $ecomAptg = this.$el && this.$el.querySelector('.ecom-swiper-autoplay-toggle');
                if ($ecomAptg && !$ecomAptg.getAttribute('data-ecom-bound')) {
                    $ecomAptg.setAttribute('data-ecom-bound', '1');
                    var $ecomAptgBox = this.$el.querySelector('.ecom-swiper-container');
                    $ecomAptg.addEventListener('click', function () {
                        var sw = $ecomAptgBox && $ecomAptgBox.swiper;
                        if (!sw || !sw.autoplay) return;
                        if (sw.autoplay.running) {
                            // stop() chứ không pause(): pause() sẽ bị resume() của
                            // pauseOnMouseEnter bật lại, người dùng bấm dừng phải dừng hẳn.
                            sw.autoplay.stop();
                            $ecomAptg.setAttribute('data-state', 'paused');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-play'));
                        } else {
                            sw.autoplay.start();
                            $ecomAptg.setAttribute('data-state', 'playing');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-pause'));
                        }
                    });
                }
                let $el = this.$el;
                const initSlider = () => {
                    if(!$el) return;
                    let $container = $el.querySelector(".ecom-swiper-container");
                    if(!$container) return;
                    const _settings = this.settings;
                    const _doInit = function() {
                        if(!(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function')) {
                            let _r = 0;
                            const _t = setInterval(function() {
                                _r++;
                                if(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function') { clearInterval(_t); _doInit(); }
                                else if(_r >= 20) clearInterval(_t);
                            }, 200);
                            return;
                        }
                        let options = window.EComposer.buildSwiperConfig(_settings);
                        options.pagination = options.pagination || {};
                        options.navigation = options.navigation || {};
                        options.pagination.el = $el.querySelector('.ecom-swiper-pagination');
                        options.navigation.nextEl = $el.querySelector('.ecom-swiper-button-next');
                        options.navigation.prevEl = $el.querySelector('.ecom-swiper-button-prev');
                        if(window.EComSwiper) {
                            new window.EComSwiper($container, Object.assign(options, {}));
                        }
                    };
                    _doInit();
                };

                if (this.settings.layout === "slider") {
                    initSlider();
                }
                let arr =  $el.querySelectorAll('[ecom-modal]');

                if(arr.length) {
                    new window.EComModal(arr, {
                        gallery: true,
                        cssClass: ['ecom-container-lightbox-' + this.id]
                    });
                }
            };
        },
        default() {
            return {
                    "settings": {
                        "overlay_use": true,
                        "slider_spacing": "30",
                        "itemsCount": 8,
                        "layout": "grid",
                        "slider_items": 4,
                        "slider_items__tablet": 3,
                        "slider_items__mobile": 2,
                        "slider_loop": true,
                        "slider_autoplay": true,
                        "slider_autoplay_speed": 2000,
                        "slider_pause": true,
                        "slider_navigation_layout": "classic_full",
                        "slider_prev_icon": "<svg xmlns=\"http: //www.w3.org/2000/svg\" width=\"52\" height=\"52\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"feather feather-chevron-left\"><polyline points=\"15 18 9 12 15 6\"></polyline></svg>",
                        "slider_next_icon": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"52\" height=\"52\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"feather feather-chevron-right\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>",
                        "slider_pagination_position": "static",
                        "slider_effect": "slide",
                        "slider_speed": 200,
                        "overlay_title": "username",
                        "slider_group": 1,
                        "slider_spacing_row": 10,
                        "slider_navigation_position": "bottom_center"
                    },
                    "style": {
                        "instagramImage": {
                            "imageOpacitynormalmode": 1,
                            "imageOpacityhovermode": 1,
                            "tab": "normal"
                        },
                        "swiper_nav": {
                            "navigatorFontSize": "36px",
                            "navigatorPrimaryColornormalmode": "rgba(59, 50, 50, 0.98)",
                            "navigatorPrimaryColorhovermode": "#000000",
                            "navtab": "normal",
                            "tab": "normal"
                        },
                        "instagramOverlay": {
                            "opacity": 0.28,
                            "opacityHover": 1,
                            "backgroundhovermode": {
                                "classic": {
                                    "background-color": "rgba(17, 24, 39, 0.3)"
                                }
                            },
                            "tab": "hover"
                        }
                    }

            };
        }
    },
    watch: {
        optionSwiper: {
            deep: true,
            handler: function () {
                this.instagram.refresh = this.$helpers.randid();
            }
        },
        isCombined: function() {
            this.instagram.refresh = this.$helpers.randid();
        }
    },
    methods: {
        isCombined() {
            let navigator = this.data?.settings?.slider_navigation_layout;
            return navigator === 'neo_full' ? 'combine' : 'classic';
        },
        refresh() {
            this.instagram.refresh = this.$helpers.randid();
        },
        isArrow() {
            return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                    this.data.settings?.slider_navigation_layout === 'neo_navigator' ||
                    this.data.settings?.slider_navigation_layout === 'classic_full' ||
                    this.data.settings?.slider_navigation_layout === 'navigation';
        },
        isPagination() {
            return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                    this.data.settings?.slider_navigation_layout === 'classic_full' ||
                    this.data.settings?.slider_navigation_layout === 'pagination';
        },
        style() {
            let checkNavPagination = [];
            if (this.isArrow()) {
                checkNavPagination.push({
                    title: "Navigator",
                    type: "swiper:nav"
                });
            }
            if (this.isPagination() && this.data.settings?.slider_pagination_style != 'progress') {
                checkNavPagination.push({
                    title: this.$t("pagination"),
                    type: "swiper:pagination"
                });
            }
            let modifyNavigation = {};
            if(this.isCombined === 'combine') {
                modifyNavigation = {
                    params: [
                        {
                            alias: 'spacing',
                            options: {
                                name: 'spacingNavigation',
                                css: {
                                    selector: ' .ecom-swiper-navigation'
                                }
                            }
                        },
                        {
                            type: 'line'
                        }
                    ],
                    remove: {
                        name: 'justify-content'
                    }
                };
            }
            let rs = [
                {
                    group_alias: "image",
                    options: {
                        group_name: "instagramImage",
                        liteMode: true,
                        group_title: this.$t('image'),
                        selector:
                            " .ecom-instagram .ecom-instagram--item figure,.ecom-instagram .ecom-instagram--item a"
                    }
                }
            ];

            if (this.instagram.settings.layout == 'grid') {
                rs.push({
                    group_name: "instagramGridStyle",
                    group_title: this.$t('grid'),
                    selector: " .ecom-instagram--container.ecom-base-instagram-grid",
                    params: [
                        {
                            type: "number",
                            name: "slider_spacing",
                            label: this.$t('spacing'),
                            options: {
                                responsive: true,
                                units: {
                                    'px': {
                                        min: 0,
                                        max: 100
                                    }
                                }
                            },
                            css: {
                                properties: {
                                    gap: "%value%"
                                },
                            }
                        }
                    ]
                });
            }

            if (this.instagram.settings.overlay_use) {
                rs.push({
                    group_alias: "background:overlaytext",
                    options: {
                        group_name: "instagramOverlay",
                        group_title: this.$t('overlay'),
                        selector: " .ecom-instagram .ecom-image-default"
                    }
                });
            }
            //console.log(checkNavPagination.length , 'check',this.isArrow(),this.isPagination());
            // Nút pause autoplay tồn tại độc lập với arrow/pagination nên phải push
            // group riêng, không gộp vào checkNavPagination (modifyNavigation splice
            // theo index, thêm field vào đó sẽ làm lệch vị trí các field khác).
            if (this.$helpers.hasAutoplayToggle(this.data?.settings)) {
                rs.push({
                    group_alias: 'swiper:autoplay',
                    options: {
                        group_title: this.$t('pause_button'),
                        selector: ' .ecom-instagram--container'
                    }
                });
            }
            if(checkNavPagination.length) {
                if(this.data.settings.slider_pagination_style === 'progress' && this.isPagination()) {
                    modifyNavigation.params = [
                      {
                        position: 50,
                        fields: [
                          {
                            type: 'line'
                          },
                          {
                            type: 'paragraph',
                            content: this.$t('b_pagination')
                          },
                          {
                            type: 'number',
                            name: 'widthProgress',
                            label: this.$t('width'),
                            options: {
                            units: {
                                '%': {
                                min: 1,
                                max: 100
                                }
                            }
                            },
                            css: {
                            selector: ' .ecom-swiper-pagination.ecom-swiper-pagination-progressbar.ecom-swiper-pagination-horizontal',
                            important: true,
                            properties: {
                                'width': ''
                            }
                            }
                        },
                          {
                            type: 'number',
                            name: 'sizeProgress',
                            label: this.$t('height'),
                            options: {
                              units: {
                                'px': {
                                  min: 1,
                                  max: 50
                                }
                              }
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar',
                              properties: {
                                '--ecom-swiper-pagination-progressbar-size': ''
                              }
                            }
                          },
                          {
                            type: "color",
                            name: "progress",
                            label: this.$t('progress'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar-fill',
                              properties: {
                                'background-color': ''
                              }
                            }
                          },
                          {
                            type: "color",
                            name: "track",
                            label: this.$t('track'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar',
                              properties: {
                                'background-color': ''
                              }
                            }
                          },
                          {
                            alias: 'spacing',
                            options: {
                              name: 'spacingPaginationProgress',
                              css: {
                                selector: ' .ecom-swiper-pagination-position.ecom-swiper-pagination-progressbar'
                              }
                            }
                          }
                        ]
                      }
                    ];
                }
                rs.push({
                        group_alias:checkNavPagination,
                        options:{
                            group_title: this.$t('navigation'),
                            selector:' .ecom-instagram--container'
                        },
                        modify: modifyNavigation

                });
            }
            return rs;
        }
    }
};
</script>
