<script lang="ts">
import { Popmenu } from '@/mixins';
import { dragMixin, fileMixin } from '../../mixins';
import { upload } from '../../utils/file';
import ImageEditor from '@/components/atomics/ImageEditor.vue';
import PickerModify from './PickerModify.vue';
import { languages } from "@/constants/language";
import { countries } from "@/constants/countries";
import { DeleteMajor, EditMajor, CircleInformationMajor, CirclePlusMajor, CancelMajor, ecDotsVertical, ImageMajor,WandIcon as MagicWandIcon } from "@/assets/icons";
import Popover from "@/components/SideBar/AI/Popover.vue";
export default {
    name: 'PickerPreview',
    components: {
        Popover,
        PickerModify,
        ImageEditor
    },
    mixins: [Popmenu, dragMixin, fileMixin],
    props: {
        valueProp: {
            type: Array,
            default() {
                return [];
            }
        },
        options: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    emits: ['update:temp', 'update:image', 'select-item', 'update:modify'],
    data() {
        return {
            show_edit: false,
            imageEdit: {
                size: {
                    width: 1000,
                    height: 1000
                },
                // mode: 'crop',
                src: this.valueProp[0].value
            },
            index: -1,
            drag: {
                axis: 'y'
            },
            showEditAlt: this.options.multiple,
            currentData: {},
            size: {},
            dragging: false,
            icons: {
                DeleteMajor, EditMajor, CircleInformationMajor, CirclePlusMajor, CancelMajor, ecDotsVertical, ImageMajor,  MagicWandIcon
            },
            overPreview: false,
            position_focal: {
                flag: false,
                flag_tablet: false,
                flag_mobile: false,
                top: this.valueProp[0].top ?? 0,
                left: this.valueProp[0].left ?? 0,
                top_tablet: this.valueProp[0].top_tablet ?? 0,
                left_tablet: this.valueProp[0].top_tablet ?? 0,
                top_mobile: this.valueProp[0].top_mobile ?? 0,
                left_mobile: this.valueProp[0].left_mobile ?? 0,
                transform: 'translate(-50%, -50%)'
            },
            showOptionChange: false
        };
    },
    computed: {
        checkPermissions() {
            const user = this.$store.getters['global/user'];
            return user?.plan_permissions?.permissions?.image_editor??false;
        },
        getUser() {
            return this.$store.getters['global/user'].name
        },
        values: {
            get() {
                return this.valueProp;
            },
            set(val) {
                this.$emit('update:image', val);
            }
        },
        isSingle() {
            return !this.options.multiple;
        },
        checkShopifyPicker() {
            return ['menu', 'blog', 'article', 'product', 'collection'].indexOf(this.options.type) >
                -1
                ? true
                : false;
        },
        strSize() {
            let str = '';
            if ('width' in this.size) {
                return `${this.size.width} x ${this.size.height}`;
            }
            return str;
        },
        getValue() {
            let value = this.values[0].value;
            if(this.screen === 'tablet' && this.values[0].value__tablet) {
                value = this.values[0].value__tablet;
            }
            if(this.screen === 'mobile' && this.values[0].value__mobile) {
                value = this.values[0].value__mobile;
            }
            return value;
        },
        setStyle() {
            let style = {};
            if(this.screen === 'desktop'){
                style = {
                    left: this.position_focal.left ? this.position_focal.left + '%' : this.values[0].left ? this.values[0].left + '%' : '50%',
                    top: this.position_focal.top ? this.position_focal.top + '%' : this.values[0].top ? this.values[0].top + '%' : '50%' ,
                    "transform": this.position_focal.transform
                }
            }
            else if(this.screen === 'tablet') {
                style = {
                    left: this.position_focal.left_tablet ? this.position_focal.left_tablet + '%' : this.values[0].left_tablet ? this.values[0].left_tablet + '%' : '50%',
                    top: this.position_focal.top_tablet ? this.position_focal.top_tablet + '%' : this.values[0].top_tablet ? this.values[0].top_tablet + '%' : '50%' ,
                    "transform": this.position_focal.transform
                }
            }
            else {
                style = {
                    left: this.position_focal.left_mobile ? this.position_focal.left_mobile + '%' : this.values[0].left_mobile ? this.values[0].left_mobile + '%' : '50%',
                    top: this.position_focal.top_mobile ? this.position_focal.top_mobile + '%' : this.values[0].top_mobile ? this.values[0].top_mobile + '%' : '50%' ,
                    "transform": this.position_focal.transform
                }
            }
            return style;
        },
        alt() {
            let item: any = this.values[0];
            switch(this.screen) {
                case 'tablet': {
                    let v = item.alt__tablet || item.name__tablet;
                    return v ? v.replace(/ecom-edit-image-(.{10})/, '') : ''
                }
                case 'mobile': {
                    let v = item.alt__mobile || item.name__mobile;
                    return v ? v.replace(/ecom-edit-image-(.{10})/, '') : ''
                }
                default: {
                    let v = item.alt || item.name;
                    return v ? v.replace(/ecom-edit-image-(.{10})/, '') : ''
                }
            }

        }
    },
    watch: {
        values: {
            deep: true,
            immediate: true,
            handler(newVal) {
                this.getSizeImage();
                switch(this.screen) {
                    case 'tablet':
                        if(newVal[0].value__tablet) {
                            this.imageEdit.src = newVal[0].value__tablet;
                        }
                        else {
                            this.imageEdit.src = newVal[0].value;
                        }
                        break;
                    case 'mobile':
                        if(newVal[0].value__mobile) {
                            this.imageEdit.src = newVal[0].value__mobile;
                        }
                        else if(newVal[0].value__tablet) {
                            this.imageEdit.src = newVal[0].value__tablet;
                        }
                        else {
                            this.imageEdit.src = newVal[0].value;
                        }
                        break;
                    default:
                        if(newVal[0].value) this.imageEdit.src = newVal[0].value;
                        break;
                }
            }
        },
        screen: {
            deep: true,
            handler(newVal) {
                this.getSizeImage();
                switch(newVal) {
                    case 'tablet':
                        if(this.values[0].value__tablet) {
                            this.imageEdit.src = this.values[0].value__tablet;
                        }
                        else {
                            this.imageEdit.src = this.values[0].value;
                        }
                        break;
                    case 'mobile':
                        if(this.values[0].value__mobile) {
                            this.imageEdit.src = this.values[0].value__mobile;
                        }
                        else if(this.values[0].value__tablet) {
                            this.imageEdit.src = this.values[0].value__tablet;
                        }
                        else {
                            this.imageEdit.src = this.values[0].value;
                        }
                        break;
                    default:
                        if(this.values[0].value) this.imageEdit.src = this.values[0].value;
                        break;
                }
            }
        }
    },
    methods: {
        getFlag(value) {
            if(!value) return;
            if(this.options?.type === 'language') {
                const language = languages.find(language => language.value === value);
                return {
                    flag: language?.flag,
                    name: language?.label
                }
            }
            else if(this.options?.type === 'country') {
                const country = countries.find(country => country.value === value);
                return {
                    flag: country?.flag,
                    name: country?.label
                }
            }
            return {
                flag: '',
                name: ''
            }
        },
        overStart(e, item) {
            this.overPreview = true;
        },
        overEnd(e, item) {
            if(!this.showOptionChange) {
                this.overPreview = false;
            }
        },
        changeImage(item, i, tab = 'uploaded') {
            this.showOptionChange = false;
            this.overPreview = false;
            this.$nextTick(() => {
                this.$emit('select-item', { item, i, tab })
            });
        },
        deleteValue() {
            this.showOptionChange = false;
            this.overPreview = false;
            this.$emit('delete-item');
        },
        // upload file (frist import upload -> import { upload } from '../../utils';)
        async upload (e) {
                // const parts = this.values[0].value.split('/');
                // const url = parts.slice(0, parts.length - 2).join('/') + '/files/';
                const url = 'https://' + this.getUser + '/cdn/shop/files/';
                let file = e.dest;
                if(!file) return;
                let id = this.$helpers.makeId(10);
                let fileName = file.name;
                if(fileName.match(/ecom-edit-image-(.{10})/)) {
                    fileName = fileName.replace(/ecom-edit-image-(.{10})/, '');
                }
                const newName = 'ecom-edit-image-' + id + fileName.replace('.jpeg', '.jpg'); // Set the new file name here change ext file name
                try {
                    let newFile = new File([file], newName, { type: file.type });
                    if(!newFile) return;
                    let res = await upload({type: 'image', file:newFile, compress: null}, null, this);
                    if (res.status === 'success') {
                        switch(this.screen) {
                            case 'tablet':
                                this.values[0].value__tablet = url + newFile.name;
                                this.values[0].thumbnail__tablet = url + newFile.name;
                                this.values[0].width__tablet = e.imageState.crop.width;
                                this.values[0].height__tablet = e.imageState.crop.height;
                                break;
                            case 'mobile':
                                this.values[0].value__mobile = url + newFile.name;
                                this.values[0].thumbnail__mobile = url + newFile.name;
                                this.values[0].width__mobile = e.imageState.crop.width;
                                this.values[0].height__mobile = e.imageState.crop.height;
                                break;
                            default:
                                this.values[0].value = url + newFile.name;
                                this.values[0].thumbnail = url + newFile.name;
                                this.values[0].width = e.imageState.crop.width;
                                this.values[0].height = e.imageState.crop.height;
                                break;
                        }

                        setTimeout(()=>{
                            if(res.status === 'success') {
                                // this.$store.commit(
                                //     'global/flash',
                                //     {
                                //         open: true,
                                //         timeout: 10000,
                                //         title: this.type != 'image' ? this.$t("the_uploaded_file_is_being_processed_in_the_background") : '',
                                //         message: this.type != 'image' ? this.$t("they_may_take_a_few_minutes_to_appear_in_your_file_list_refresh_to_fetch_new_items") : res.message,
                                //         type: 'success',
                                //         data: res
                                //     },
                                //     { root: true }
                                // );
                                this.$store.commit('global/setToast', {
                                    message: this.type != 'image' ? this.$t("they_may_take_a_few_minutes_to_appear_in_your_file_list_refresh_to_fetch_new_items") : res.message,
                                    data: res,
                                    duration: 4000
                                }, { root: true });
                            }
                            else
                            throw new Error(res.message ?? this.$t("unknown_error"));
                        },3000);
                        this.$emit('update:temp');
                        this.show_edit = false;
                    } else {
                        if(res.message) {
                            this.$store.commit('global/setToast', {
                                isError: true,
                                message: res.message,
                                data: res,
                                duration: 4000
                            }, { root: true });
                        }
                        this.deleteItem(id);
                        this.show_edit = false;
                    }
                }
                catch(error) {
                    console.log(error)
                }
            },




        // -----------------------------------------
        setValuePosition(top, left) {
            if(this.screen === 'desktop') {
                this.position_focal.flag = true;
                this.position_focal.top = top;
                this.position_focal.left = left;
            }
            else if(this.screen === 'tablet') {
                this.position_focal.flag_tablet = true;
                this.position_focal.top_tablet = top;
                this.position_focal.left_tablet = left;
            }
            else {
                this.position_focal.flag_mobile = true;
                this.position_focal.top_mobile = top;
                this.position_focal.left_mobile = left;
            }
        },
        dragFocalPoint(e) {
            e.preventDefault();
            e.stopPropagation();
            this.dragging = true;
            document.addEventListener('mousemove', this.setPosition);
            document.addEventListener('mouseup', this.onMouseUp);
        },
        onMouseUp(e) {
            e.stopPropagation();
            this.dragging = false;
            document.removeEventListener('mousemove', this.setPosition);
            document.removeEventListener('mouseup', this.onMouseUp);
        },
        setPosition(e) {
            if (!this.dragging) return;
            const image = this.$refs.image_popup;
            if (!image) return;
            const rect = image.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            const percentLeft = Math.max(0, Math.min(100, (x / rect.width) * 100));
            const percentTop = Math.max(0, Math.min(100, (y / rect.height) * 100));
            this.setValuePosition(percentTop, percentLeft);
        },
        changePositionFocalPoint(e) {
            const el_focal_point = this.$refs.focal__point;
            if(!el_focal_point) return;
            el_focal_point.classList.remove('hidden');
            this.$refs.btn_enable.$el.innerHTML = this.$t('remove_focal_point');
            this.setPosition(e);
        },
        saveSet() {
            //save position focal point
            if(this.position_focal.flag) {
                this.valueProp[0].top  = this.position_focal.top;
                this.valueProp[0].left  = this.position_focal.left;
            }
            if(this.position_focal.flag_tablet) {
                this.valueProp[0].top_tablet  = this.position_focal.top_tablet;
                this.valueProp[0].left_tablet  = this.position_focal.left_tablet;
            }
            if(this.position_focal.flag_mobile) {
                this.valueProp[0].top_mobile  = this.position_focal.top_mobile;
                this.valueProp[0].left_mobile  = this.position_focal.left_mobile;
            }
            //save alt image
            let value = this.$refs['inputEditAlt'].value;
            switch(this.screen) {
                case 'tablet':
                    this.values[0].name__tablet = value;
                    this.values[0].alt__tablet = value;
                    break;
                case 'mobile':
                    this.values[0].name__mobile = value;
                    this.values[0].alt__mobile = value;
                    break;
                default:
                    this.values[0].name = value;
                    this.values[0].alt = value;
                    break;
            }

            this.showEditAlt = false;
            // this.isopen = false;
            this.doClose();
        },
        cancelSet() {
            this.position_focal.top  = this.values[0].top;
            this.position_focal.left  = this.values[0].left;
            this.doClose();
            // this.isopen = false
            this.position_focal.top__tablet  = this.values[0].top__tablet;
            this.position_focal.left__tablet  = this.values[0].left__tablet;
            this.position_focal.top__mobile  = this.values[0].top__mobile;
            this.position_focal.left__mobile  = this.values[0].left__mobile;
        },
        mouseOverBtn() {
            const el_focal_point = this.$refs.focal__point;
            if(!el_focal_point) return;
            this.position_focal.transform += 'scale(1.5)';
        },
        mouseOutBtn() {
            const el_focal_point = this.$refs.focal__point;
            if(!el_focal_point) return;
            this.position_focal.transform = 'translate(-50%, -50%)';
        },
        enableFocalPoint(e) {
            const el_focal_point = this.$refs.focal__point;
            if(! el_focal_point) return;
            let check_focal = el_focal_point.classList.contains('hidden');
            if(check_focal) {
                this.setValuePosition(50, 50);
                el_focal_point.classList.remove('hidden');
                e.target.innerHTML = this.$t('remove_focal_point');
                return ;
            }
            el_focal_point.classList.add('hidden');
            e.target.innerHTML = this.$t('add_focal_point');
            this.setValuePosition(null, null);

        },
        classItem() {
            let cl = 'w-full ';
            if (!this.isSingle) {
                cl += 'transition-bg p-1 transition group-hover:bg-surface-tertiary group rounded';
            } else {
                cl += ' flex-col justify-center';
            }
            if(this.options?.type == 'image' && this.isSingle) {
                cl += ' wrapper-item';
            }
            if(this.overPreview) {
                cl += ' over-preview';
            }
            return cl;
        },
        fileName(data) {
            let name = this.$helpers.file.name(data);
            return name ? name : data;
        },
        deleteItem(index) {
            if (index > -1) {
                this.values.splice(index, 1);
                this.$emit('update:temp');
            }
        },
        // updateAlt() {
        //     let value = this.$refs['inputEditAlt'].value;
        //     this.values[0].name = value;
        //     this.showEditAlt = false;
        //     this.isopen = false;
        // },
        dragItem(e) {
            this.dragging = true;
            document.onmouseup = () => {
                this.dragging = false;
            };
            if (this.options.type !== 'font' && !this.isSingle) {
                this.mouseDownHandler(e);
            }
        },
        cbEndDrag(pos) {
            if (this.hasSorted && pos.before && pos.after) {
                let before = pos.before[0];
                let after = pos.after[0];
                this.values.splice(after, 0, ...this.values.splice(before, 1));
            }
        },
        getSizeImage() {
            if (this.isSingle && this.options.type === 'image' && this.values?.length) {
                let src = this.values[0].value || this.values[0].thumbnail;

                if(this.screen === 'tablet' && this.values[0].value__tablet) {
                    src = this.values[0].value__tablet || this.values[0].thumbnail__tablet;
                }
                if(this.screen === 'mobile' && this.values[0].value__mobile) {
                    src = this.values[0].value__mobile || this.values[0].thumbnail__mobile;
                }

                let img = new Image();
                img.onload = () => {
                    let { width, height } = img;
                    this.size = { width, height };
                };
                img.src = src;
            }
        }
    }
};
</script>
