import { mapGetters } from 'vuex';

export default {
    inject: ['exporting', 'instanceStore'],
    beforeUnmount() {
        //delete this.stacks?.[this?.data?.id];
        this.instanceStore.unregister(this?.data?.id)
    },
    computed: {
        dropTo() {
            const dropTo = this.$store.getters['builder/dropTo'];
            return dropTo ? (dropTo?.$options?.name ? dropTo : this.instanceStore.get(dropTo)) : null;
        },
        inGroup() {
            if(this._group) {
                if(this.dragCurrent === this._group.$parent.$parent) {
                    return true
                }
            }
            return false;
        },
        isDragging() {
            return this.dragCurrent;
        },
        isEditing() {
            return !this.isFullScreen && this.editingElement?.data?.id == this.data.id;
        },
        isActive() {
            let isDragPadding = this.$store.getters['builder/isDragPadding'] || '';
            return !this.isFullScreen
                    && (
                        isDragPadding == this.data.id || isDragPadding == ''
                    )
                    && (
                        this.over || this.dropTo === this
                    );
        },
        isActiveBorder() {
            let isDragPadding = this.$store.getters['builder/isDragPadding'] || '';
            return !this.isFullScreen
                    && (
                        isDragPadding == this.data.id || isDragPadding == ''
                    )
                    && (
                        this.over ||
                        (
                            this.activeElement?.data?.id == this.data.id ||
                            this.editingElement?.data?.id == this.data.id
                        ) ||
                        this.dropTo === this
                    );
        },
        isDragMe() {
            return this.dragCurrent === this;
        },
        isDropTo() {
            return this.dropTo === this;
        },
        hideOnScreen() {
            const data = this?.data?.advanced || this?.data?.group?.advanced || {};
            return (!this.isFullScreen &&
                data?.['display' + (this.screen == 'desktop' ? '' : '__' + this.screen)] == 'none'
            );
        },
        isFullScreen() {
            return this.exporting !== false || this.$store.getters['builder/isFullScreen'];
        },
        // Scroll Reveal preview mode — makes Row/Grid/FlexContainer emit the SR
        // attributes inside the builder canvas, the same way exporting does.
        srPreview() {
            return this.$store.getters['builder/srPreview'] === true;
        },
        classes() {
            return {
                'drag__placeholder': this.isDragMe && !this.data.inGrid,
                [this.data.id]: true,
                'hide-on-screen': this.hideOnScreen,
                'hide-on-desktop': this?.data?.advanced?.['display'] == 'none',
                'hide-on-tablet': this?.data?.advanced?.['display__tablet'] == 'none',
                'hide-on-mobile': this?.data?.advanced?.['display__mobile'] == 'none',
                [this.data?.advanced?.['classes'] ?? '']: true
            };
        },
        attributes() {

            let attr: any = {}

            if (this.data?.advanced?.['id']) {
                attr['id'] = this.data.advanced['id'];
            }
            if (this.data?.advanced?.['attributes']) {
                let attrs = this.data.advanced['attributes'].split(`\n`);
                attrs.forEach((att) => {
                    const [key,...val] = att.split(':');
                    let value = val.join(':');

                    if (key && value && ['id', 'class', 'data-placeholder'].indexOf(key) === -1) {
                        attr[key.replace(/[^a-zA-Z0-9\-\_\s]/g, '').replaceAll(" ", "")] = value.replace(/\"/g, '');
                    }
                });

            }
            return attr;
        },
        condition() {
            let data = this.data?.advanced?.['items'];
            const _this = this;
            let result='';
            if(!data) return;
            let conditions = data.map((condition) => {
                if(typeof condition === 'object') return condition;
            });

            for(let i = 0; i< conditions.length; i++) {
                    let condition = conditions[i];
                    let settings = conditions[i].settings,
                        operator = '';
                    if(!settings || !settings.operator) return;
                    if(i !== 0) {
                        operator = conditions[i-1].settings.operator ?? 'and'

                    }
                    else {
                        operator = 'and';
                    }
                    let not_contain = settings.condition == 'not_contain' ? true : false;
                    switch(condition.type) {
                        case 'user':
                            result += `{% assign checkUser = true %}`
                            settings.user_status && settings.user_status === 'logged' ? result += ` {%- if customer -%} {%- assign checkUser = true -%} {%- else -%} {%- assign checkUser = false -%} {%- endif -%}` : result += `{%- unless customer -%} {%- assign checkUser = true -%} {%- else -%} {%- assign checkUser = false -%} {%- endunless -%}`;
                            result += `{%- if condition ${operator} checkUser -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
                            break;
                        case 'user_tags':
                            result += _this.handleCondition(condition.type, settings.user_tags, operator, not_contain);
                        case 'page':
                            result += _this.handleCondition(condition.type, settings.page_tags, operator, not_contain);
                            break;
                        case 'product_vendor':
                            result += _this.handleCondition(condition.type, settings.product_vendor, operator, not_contain);
                            break;
                        case 'product_type':
                            result += _this.handleCondition(condition.type, settings.product_type, operator, not_contain);
                            break;
                        case 'metafields':
                            result += _this.handleConditionMetafields(settings, operator)
                            break;
                        case 'cart_page':
                            result += _this.handleConditionCart(settings, operator);
                            break;
                        case 'language':
                            result += _this.handleConditionLanguage(settings, operator);
                            break;
                        case 'country':
                            result += _this.handleConditionCountry(settings, operator);
                            break;
                    }
            }
            return result;
        },
        scrollingAnimation() {
            const advanced = this?.data?.group ? this.data.group?.advanced : this.data.advanced;
            if(!advanced) return;
            const animation = [];

            advanced.hasOwnProperty('scolling_horizontal') && animation.push({css: 'translateX', value: advanced.scolling_horizontal['scrolling-animation-px']});
            advanced.hasOwnProperty('scolling_vertical') && animation.push({css: 'translateY', value: advanced.scolling_vertical['scrolling-animation-px']});
            advanced.hasOwnProperty('scrolling_rotate') && animation.push({css: 'rotate', value: advanced.scrolling_rotate['scrolling-animation-deg']});
            advanced.hasOwnProperty('scrolling_opacity') && animation.push({css: 'opacity', value: advanced.scrolling_opacity['scrolling-animation-opacity']});
            advanced.hasOwnProperty('scrolling_scale') && animation.push({css: 'scale', value: advanced.scrolling_scale['scrolling-animation-scale']});
            advanced.hasOwnProperty('scrolling_blur') && animation.push({css: 'blur', value: advanced.scrolling_blur['scrolling-animation-blur']});

            return animation.length ? JSON.stringify(animation) : '';
        },

        /*Access to parent node*/
        _blocks() {
            return this.parent('blocks');
        },
        _block() {
            return this.parent('block');
        },
        _column() {
            return this.parent('column');
        },
        _row() {
            return this.parent('row');
        },
        _section() {
            return this.parent('section');
        },
        _group() {
            return this.parent('group');
        },
        parentColumn() {
            const breacumbsPath = this?.breadcrumb || this?.$attrs?.breadcrumb;
            if(breacumbsPath) {
                const breacumbs = breacumbsPath.split('/');
                if(breacumbs.length > 0) {
                    const parent = breacumbs.pop();
                    const stack = this.instanceStore.get(parent);
                    if(stack) {
                        return stack
                    }
                }
            }

            return null
        },

        // ...mapGetters('page', ['allNodes']),
        ...mapGetters('builder', ['screen', 'dragCurrent', 'dropPos', 'activeElement', 'editingElement', 'contextMenu', 'isSpacePressed']),
        ...mapGetters('global', ['sidebarTabActive']),
    },
    methods: {
        idoc() {
            return window?.EComposerBuilder?.contentDocument ?? null;
        },

        iwin() {
            return window?.EComposerBuilder?.contentWindow ?? null;
        },

        parent(is) {
            let get = (o) => {
                return o ? (o.is == is ? o : get(o.$parent)) : null;
            };
            return get(this);
        },

        parentsOver(inst) {
            if (!inst) {
                inst = this;
            }
            if (inst.$parent) {
                if (inst.$parent.over === false) {
                    inst.$parent.over = true;
                }
                this.parentsOver(inst.$parent);
            }
        },

        parentsOut(inst) {
            if (!inst) {
                inst = this;
            }
            if (inst.$parent) {
                if (inst.$parent.over === true) {
                    inst.$parent.over = false;
                }
                this.parentsOut(inst.$parent);
            }
        },

        notice(params) {
            // this.$store.commit('global/flash', {
            //     open: true,
            //     message: params.message,
            //     title: params.title,
            //     type: params.type,
            // });

            this.$store.commit('global/setToast', {
                isError: params.type == 'error',
                message: params.message,
                duration: 4000
            });
        },
        cloneEvent(e: MouseEvent, type: string) {
            return  new MouseEvent(type, {
                bubbles: true,
                cancelable: true,
                view: window,
                clientX: e.clientX,
                clientY: e.clientY,
                screenX: e.screenX,
                screenY: e.screenY,
                button: e.button,
                buttons: e.buttons,
                ctrlKey: e.ctrlKey,
                shiftKey: e.shiftKey,
                altKey: e.altKey,
                metaKey: e.metaKey
            });
        },

        // Thêm method để điều chỉnh vị trí theo scale
        adjustPositionForScale(clientX, clientY, rect) {
            // ec-dragging-element nằm ngoài iframe, trong document chính
            // Vị trí chuột đã được browser điều chỉnh tự động
            // Chúng ta chỉ cần đặt element đúng vị trí chuột thôi!

            const result = {
                x: clientX,
                y: clientY
            };

            return result;
        },

        // Sửa lại method startDrag
        startDrag(e, presetData = false) {
            if (
                (e && e.target.closest('[data-stopdrag]') !== null) ||
                (!this.idoc || !this.iwin) ||
                this.isSpacePressed
            ) {
                return;
            }
            // Fix k click được vào select (variant), input (quantity)
            if(e !== undefined && !e.target.closest('select') && !e.target.closest('textarea') && !e.target.closest('input')) {
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
            }

            const dragElement = document.getElementById('ec-dragging-element');
            if (dragElement && presetData && this.data) {
                const rect = window.EComposerBuilder.getBoundingClientRect();

                const adjustedPos = this.adjustPositionForScale(e.clientX, e.clientY, rect);

                dragElement.style.left = adjustedPos.x + 'px';
                dragElement.style.top = adjustedPos.y + 'px';
                dragElement.style.display = 'block';

                const titleDrag = dragElement.querySelector('.title-drag'),
                iconDrag = dragElement.querySelector('.icon-drag');
                if(titleDrag && iconDrag) {
                    let textIcon = `<svg class="inline-flex h-5 w-5 transition text-icon-primary fill-current icon-drag">
                                <use xlink:href="#icon-${this?.data?.name}"/>
                            </svg>`;
                    titleDrag.textContent = this.data.title;
                    iconDrag.innerHTML = textIcon;
                }

                if (!this.dragCurrent) {
                    try {
                        this.$store.commit('builder/setDragging', {
                            current: this.is === 'group' ? this.$parent.$parent : this,
                            dropTo: null,
                            dropPos: 'top'
                        });
                        if(this.sidebarTabActive.id == 'dragging_element_sidebar') {
                            this.$store.commit('SET_TAB', '');
                        }
                    } catch (err) {
                        console.error('Failed to register drag instance:', err);
                    }
                }
            }

            this.placeholder = 'top';
            document.body.style.userSelect = 'none';
            document.body.style.webkitUserSelect = 'none';
            document.body.style.cursor = 'pointer';
            this.idoc().body.style.userSelect = 'none';
            this.idoc().body.style.webkitUserSelect = 'none';
            this.idoc().body.style.cursor = 'pointer';

            let html = this.idoc().querySelector('html'),
                body = this.idoc().body,
                rect = window.EComposerBuilder.getBoundingClientRect(),
                _x = null,
                _y = null;

            // Cache scale/wrapper/kích thước iframe một lần lúc bắt đầu drag,
            // tránh querySelector + getComputedStyle + getBoundingClientRect trên mỗi mousemove
            const scaleFactor = (this as any).$helpers.getScaleFactor();
            const mainWrapper = document.querySelector('.ecom-builder_main-wrapper');
            const wrapperRect = mainWrapper ? mainWrapper.getBoundingClientRect() : null;
            const iframeWidth = (window as any).EComposerBuilder.offsetWidth;
            const iframeHeight = (window as any).EComposerBuilder.offsetHeight;

            // Quy đổi toạ độ event về toạ độ trong iframe
            const getIframePoint = (_e: MouseEvent) => {
                if (_e.view !== window) return { x: _e.clientX, y: _e.clientY };
                if (scaleFactor !== 1 && wrapperRect) {
                    return {
                        x: (_e.clientX - wrapperRect.left) / scaleFactor,
                        y: (_e.clientY - wrapperRect.top) / scaleFactor
                    };
                }
                return { x: _e.clientX - rect.left, y: _e.clientY - rect.top };
            };

            // Browser không bắn mouseenter/mousemove khi page scroll dưới con trỏ đứng yên,
            // nên dropTo/placeholder bị đóng băng trong lúc auto-scroll. Tự hit-test bằng
            // elementFromPoint và dispatch synthetic mouseenter/mouseleave/mousemove
            // (đúng thứ tự browser: leave sâu nhất trước, enter ngoài cùng trước)
            let lastPointer: { x: number; y: number } | null = null;
            let lastHoverEl: Element | null = null;
            const syntheticMouse = (type: string, target: Element, bubbles: boolean) => {
                if (!lastPointer) return;
                const ev = new MouseEvent(type, {
                    bubbles,
                    cancelable: true,
                    clientX: lastPointer.x,
                    clientY: lastPointer.y,
                    view: this.iwin()
                });
                (ev as any).__ecSynthetic = true;
                target.dispatchEvent(ev);
            };
            const getAncestorChain = (el: Element | null) => {
                const chain: Element[] = [];
                while (el) {
                    chain.push(el);
                    el = el.parentElement;
                }
                return chain;
            };
            const syncHoverAfterScroll = () => {
                const doc = this.idoc();
                if (!doc || !lastPointer) return;
                const el = doc.elementFromPoint(lastPointer.x, lastPointer.y);
                if (!el) return;
                if (el !== lastHoverEl) {
                    const newChain = getAncestorChain(el);
                    const oldChain = getAncestorChain(lastHoverEl);
                    const newSet = new Set(newChain);
                    const oldSet = new Set(oldChain);
                    for (const node of oldChain) {
                        if (!newSet.has(node)) syntheticMouse('mouseleave', node, false);
                    }
                    for (let i = newChain.length - 1; i >= 0; i--) {
                        if (!oldSet.has(newChain[i])) syntheticMouse('mouseenter', newChain[i], false);
                    }
                    lastHoverEl = el;
                }
                syntheticMouse('mousemove', el, true);
            };

            // Auto-scroll bằng vòng lặp rAF: scroll liên tục khi chuột nằm trong edge zone
            // (kể cả khi chuột đứng yên), tốc độ tăng dần khi càng sát mép.
            // Tốc độ tính theo px/giây * delta-time nên không phụ thuộc frame rate.
            // behavior 'instant' để CSS scroll-behavior: smooth (nếu theme có) không biến
            // mỗi bước scroll thành một animation — nguyên nhân khiến scroll cực chậm.
            const SCROLL_ZONE = 100;
            const MAX_SCROLL_SPEED = 1800; // px mỗi giây
            const MIN_SCROLL_SPEED = 200;
            let scrollVelocity = 0,
                scrollRafId: number | null = null,
                lastFrameTime: number | null = null;
            const autoScrollLoop = (now: number) => {
                if (scrollVelocity === 0) {
                    scrollRafId = null;
                    lastFrameTime = null;
                    return;
                }
                if (lastFrameTime !== null) {
                    const dt = Math.min(now - lastFrameTime, 64);
                    const delta = scrollVelocity * dt / 1000;
                    if (html) {
                        html.scrollTo({ top: html.scrollTop + delta, behavior: 'instant' as ScrollBehavior });
                    }
                    if (body) {
                        body.scrollTo({ top: body.scrollTop + delta, behavior: 'instant' as ScrollBehavior });
                    }
                    syncHoverAfterScroll();
                }
                lastFrameTime = now;
                scrollRafId = requestAnimationFrame(autoScrollLoop);
            };
            const updateAutoScroll = (y: number) => {
                if (y < SCROLL_ZONE) {
                    const ratio = 1 - Math.max(y, 0) / SCROLL_ZONE;
                    scrollVelocity = -Math.max(MIN_SCROLL_SPEED, MAX_SCROLL_SPEED * ratio);
                } else if (y > iframeHeight - SCROLL_ZONE) {
                    const ratio = 1 - Math.max(iframeHeight - y, 0) / SCROLL_ZONE;
                    scrollVelocity = Math.max(MIN_SCROLL_SPEED, MAX_SCROLL_SPEED * ratio);
                } else {
                    scrollVelocity = 0;
                    return;
                }
                if (scrollRafId === null) {
                    scrollRafId = requestAnimationFrame(autoScrollLoop);
                }
            };
            const stopAutoScroll = () => {
                scrollVelocity = 0;
                lastFrameTime = null;
                if (scrollRafId !== null) {
                    cancelAnimationFrame(scrollRafId);
                    scrollRafId = null;
                }
            };

            // Cập nhật vị trí ghost element theo rAF thay vì trên mỗi mousemove
            let ghostX = 0,
                ghostY = 0,
                ghostRafId: number | null = null;
            const applyGhostPosition = () => {
                ghostRafId = null;
                const ghost = (window as any)['ec-dragging-element'];
                if (ghost) {
                    ghost.style.left = ghostX + 'px';
                    ghost.style.top = ghostY + 'px';
                }
            };

            this.$store.commit('builder/resetDragging');

            let onDragMove = (_e) => {
                // Bỏ qua event synthetic do chính syncHoverAfterScroll dispatch
                if (_e.__ecSynthetic) {
                    return;
                }

                // Mouseup bị mất (thả chuột ngoài cửa sổ browser / khe giữa iframe và
                // parent document) → mousemove kế tiếp có buttons === 0 → kết thúc drag
                // thay vì để ghost dính theo con trỏ. Preset mode không áp dụng vì
                // "sticky mode" (element bám con trỏ sau khi thả chuột) là hành vi chủ đích.
                if (!presetData && _e.buttons === 0) {
                    onDragEnd();
                    return;
                }

                if (_x === null) {
                    _x = _e.clientX;
                    _y = _e.clientY;
                }

                if (
                    (
                        Math.abs(_e.clientX - _x) > 5 ||
                        Math.abs(_e.clientY - _y) > 5
                    ) &&
                    !this.dragCurrent
                ) {
                    if(this.locked) {
                        this.$store.commit("builder/setShowNoticeLockmode", true);
                        return;
                    }
                    try {
                        this.$store.commit('builder/setDragging', {
                            current: this.is === 'group' ? this.$parent.$parent : this,
                            dropTo: null,
                            dropPos: 'top'
                        });
                        if(this.sidebarTabActive.id == 'dragging_element_sidebar') {
                            this.$store.commit('SET_TAB', '');
                        }
                    } catch (err) {
                        console.error('Failed to register drag instance:', err);
                    }
                }

            // Sửa phần cập nhật vị trí ec-dragging-element
            if((window as any)['ec-dragging-element']) {
                let finalX, finalY;

                if (_e.view !== window) {
                    // Event từ DIV scaled - cần convert về vị trí thực tế
                    if (scaleFactor !== 1 && wrapperRect) {
                        // _e.clientX/Y là vị trí trong DIV gốc (1440px)
                        // Cần scale xuống theo scaleFactor để có vị trí thực trong DIV scaled
                        // Vị trí cuối cùng = vị trí wrapper + vị trí scaled
                        finalX = wrapperRect.left + _e.clientX * scaleFactor;
                        finalY = wrapperRect.top + _e.clientY * scaleFactor;
                    } else {
                        // Không có scale - dùng cách cũ
                        finalX = _e.clientX + rect.left;
                        finalY = _e.clientY + rect.top;
                    }
                } else {
                    // Event từ document chính
                    finalX = _e.clientX;
                    finalY = _e.clientY;
                }

                ghostX = finalX;
                ghostY = finalY;
                if (ghostRafId === null) {
                    ghostRafId = requestAnimationFrame(applyGhostPosition);
                }
            }

            // Scroll the view while dragging to the edge of top or bottom
            lastPointer = getIframePoint(_e);
            if (_e.view !== window) {
                lastHoverEl = _e.target as Element;
            }
            updateAutoScroll(lastPointer.y);

            // Kiểm tra xem chuột có nằm ngoài vùng drag hợp lệ không
            if (_e.view !== window) {
                // Event từ iframe - kiểm tra theo iframe bounds
                if((_e.clientX < 0 || _e.clientX > iframeWidth ||
                _e.clientY < 0 || _e.clientY > iframeHeight) && (this as any).dropTo) {
                    this.$store.commit('builder/setDropTo', null);
                }
            } else {
                // Event từ document chính - kiểm tra theo wrapper bounds khi có scale
                if (scaleFactor !== 1 && wrapperRect) {
                    if((_e.clientX < wrapperRect.left || _e.clientX > wrapperRect.right ||
                    _e.clientY < wrapperRect.top || _e.clientY > wrapperRect.bottom) && (this as any).dropTo) {
                        this.$store.commit('builder/setDropTo', null);
                    }
                } else {
                    // Không có scale - dùng logic cũ
                    if((rect.right - rect.left < _e.clientX || _e.clientX < 0) && (this as any).dropTo) {
                        this.$store.commit('builder/setDropTo', null);
                    }
                }
            }

            currentMouseUp = onDragEnd;
        },

        handleEndDrag = () => {
            this.$store.commit('builder/resetDragging');
            this.$store.commit('builder/setActiveElement', null);
            this.$store.commit('builder/sectionDrag', null);
            this.$store.commit('builder/setDropTo', null);
        },

        onDragEnd = () => {
            stopAutoScroll();
            if (ghostRafId !== null) {
                cancelAnimationFrame(ghostRafId);
                ghostRafId = null;
            }
            try {
                // Clear event listeners
                this.cleanupDragEvents();

                // Reset styles
                this.resetDragStyles();

                // Handle drop if valid
                if (
                this.dropTo?.control !== false &&
                this.dragCurrent &&
                this.dropTo &&
                this.dragCurrent !== this.dropTo &&
                this.$helpers.checkGridDrop(this.dragCurrent, this.dropTo)
                ) {
                    let pos = this.dropPos == 'right' ? 1 : 0;
                    if (
                        (
                            this.dragCurrent.$parent === this.dropTo.$parent ||
                            this.dragCurrent.$parent.$parent.$parent === this.dropTo.$parent
                        ) &&
                        this.dragCurrent.index < this.dropTo.index
                    ) {
                        pos -= 1;
                    }
                    this.dragCurrent.over = false;
                    this.dropTo.over = false;
                    this.dropTo.dropIn(this.dragCurrent, pos);

                    this.$store.commit('global/setSidebarTabActive', {id: 'elements'});
                    this.$store.dispatch('UPDATE_IS_TEMP_HIDE', true);
                    this.$store.commit('SET_TAB', 'elements');
                } else if((this.dragCurrent && this.sidebarTabActive.id == 'dragging_element_sidebar') || (presetData && this.sidebarTabActive.id == 'dragging_element_sidebar')) {
                    this.$store.commit('SET_TAB', 'elements');
                    this.$store.dispatch('UPDATE_IS_TEMP_HIDE', false);
                    this.$store.commit('global/setSidebarTabActive', {id: 'elements'});
                    dragElement.style.display = 'none';
                }
            } catch (err) {
                console.error('Error in drag end:', err);
                // Ensure cleanup even if error occurs
                this.cleanupDragEvents();
                this.resetDragStyles();
            }
            handleEndDrag();
        },

        handlePresetDragEnd = () => {
            currentMouseUp = onDragEnd;
        };

        // Huỷ drag không drop (dùng khi window mất focus giữa chừng)
        const cancelDrag = () => {
            stopAutoScroll();
            if (ghostRafId !== null) {
                cancelAnimationFrame(ghostRafId);
                ghostRafId = null;
            }
            this.cleanupDragEvents();
            this.resetDragStyles();
            if (dragElement) {
                dragElement.style.display = 'none';
            }
            handleEndDrag();
        };

        // Window mất focus (alt-tab, click ra ngoài app) → huỷ drag thay vì để kẹt.
        // Lưu ý: blur cũng bắn khi focus chuyển qua lại giữa main window và iframe
        // canvas, nên phải double-check hasFocus của cả hai document sau một tick
        const onWindowBlur = () => {
            setTimeout(() => {
                if (abortController.signal.aborted) return;
                if (!document.hasFocus() && !this.idoc()?.hasFocus()) {
                    cancelDrag();
                }
            }, 0);
        };

        // Dùng addEventListener + AbortController thay vì gán on* để không ghi đè /
        // bị ghi đè bởi các feature khác cũng dùng onmousemove (resize của Row/Block).
        // Abort session cũ còn treo (nếu có) trước khi mở session mới
        this.cleanupDragEvents();
        const abortController = new AbortController();
        (window as any).__ecDragAbort = abortController;
        const opts = { signal: abortController.signal };

        // Preset mode: lần thả chuột đầu tiên chuyển sang sticky mode (element bám
        // theo con trỏ, click để đặt) — giữ nguyên logic cũ qua currentMouseUp
        let currentMouseUp: () => void = presetData ? handlePresetDragEnd : onDragEnd;
        const handleMouseUp = () => currentMouseUp();

        const iframeDoc = this.idoc() as Document;
        iframeDoc.addEventListener('mousemove', onDragMove, opts);
        document.addEventListener('mousemove', onDragMove, opts);
        iframeDoc.addEventListener('mouseup', handleMouseUp, opts);
        document.addEventListener('mouseup', handleMouseUp, opts);
        window.addEventListener('blur', onWindowBlur, opts);
        this.iwin()?.addEventListener('blur', onWindowBlur, opts);
    },

        cleanupDragEvents() {
            const abort = (window as any).__ecDragAbort;
            if (abort) {
                abort.abort();
                (window as any).__ecDragAbort = null;
            }
        },

        resetDragStyles() {
            const elements = [document.body, this.idoc().body];
            elements.forEach(el => {
                el.style.userSelect = '';
                el.style.webkitUserSelect = '';
                el.style.cursor = '';
            });
        },
        rightClickMenu(e) {
            if (
                (this.is == 'block' &&
                !this.control) ||
                (this.data?.inGrid && this.data?.layouts[this.screen]?.locked)
            ) {
                return true;
            }

            if (
                !this.isFullScreen &&
                this.contextMenu &&
                !this.contextMenu.current
            ) {
                // Lấy thông tin về scale và wrapper
                const mainWrapper = document.querySelector('.ecom-builder_main-wrapper');
                const iframeRect = window.EComposerBuilder.getBoundingClientRect();

                let scaleFactor = 1;
                let wrapperOffset = { left: 0, top: 0 };

                if (mainWrapper) {
                    const transform = window.getComputedStyle(mainWrapper).transform;
                    if (transform !== 'none') {
                        const matrix = transform.match(/matrix\(([^)]+)\)/);
                        if (matrix) {
                            const values = matrix[1].split(',');
                            scaleFactor = parseFloat(values[0]);
                        }
                    }

                    const wrapperRect = mainWrapper.getBoundingClientRect();
                    wrapperOffset = {
                        left: wrapperRect.left,
                        top: wrapperRect.top
                    };
                }

                // Tính toán vị trí chính xác
                let finalX, finalY;

                if (scaleFactor !== 1) {
                    // Có scale: convert từ iframe coordinate sang document coordinate
                    finalX = wrapperOffset.left + (e.clientX * scaleFactor);
                    finalY = wrapperOffset.top + (e.clientY * scaleFactor);
                } else {
                    // Không có scale: sử dụng cách cũ
                    finalX = e.clientX + iframeRect.left;
                    finalY = e.clientY + iframeRect.top;
                }

                // Tính toán top position
                let top;
                if (finalY + 320 > window.innerHeight) {
                    top = finalY - (finalY + 320 - window.innerHeight);
                } else {
                    top = finalY;
                }

                // Thêm một delay nhỏ để đảm bảo event chuột phải đã hoàn thành
                setTimeout(() => {
                    this.$store.commit('builder/setContextMenu', {
                        current: this,
                        x: finalX,
                        y: top,
                        time: new Date().getTime(),
                        stick: finalX < window.innerWidth - 200 ? 'left' : 'right',
                        bottom: finalY + 320 > window.innerHeight
                    });
                }, 10); // Delay 10ms
            }
            e.preventDefault();
        },

        cloneMe() {
            if(this.is !== 'selection') {
                return this.$helpers.copy(this.data);
            }
            return Object.values(this.activeElements).map(it => this.$helpers.copy(it.data))
        },

        cloneData() {
            const _this = this;
            const regex = /"id"\s?:\s?"ecom-[^\"]+\"/g;
            let string = JSON.stringify(this.data);

            let clone = string.replace(regex, function() {
                return `"id":"${_this.$helpers.randid()}"`;
            });
            return JSON.parse(clone);
        },

        dispatchResize() {
            if (typeof(Event) === 'function') {
                this.iwin().dispatchEvent(new Event('resize'));
            }
        },

        scroll(to, bh) {

            let html = this.idoc().querySelector('html'),
                body = this.idoc().body;
            if(html)
                html.scrollTo({ top: html.scrollTop + to, behavior: bh !== false ? 'smooth' : '' });
            if(body)
                body.scrollTo({ top: body.scrollTop + to, behavior: bh !== false ? 'smooth' : '' });
        },

        scrollTo(to, bh) {

            let html = this.idoc().querySelector('html'),
                body = this.idoc().body;

            html.scrollTo({ top: to, behavior: bh !== false ? 'smooth' : '' });
            body.scrollTo({ top: to, behavior: bh !== false ? 'smooth' : '' });
        },
        handleCondition(type:string, input:string, operator:string, not_contain: boolean = false) {
            let result = '';
            let typeCondition = '';
            if(input && input.toString() !== '') {
                switch(type) {
                    case 'page':
                        typeCondition = 'tags';
                        break;
                    case 'product_vendor':
                        typeCondition = 'vendor';
                        break;
                    case 'product_type':
                        typeCondition = 'type';
                        break;
                    case 'user_tags':
                        typeCondition = 'user_tags';
                        break;
                }
                result += `{%- assign page_type = request.page_type -%}
                            ${not_contain ? '{%- assign checkCondition = true -%}' : '{%- assign checkCondition = false -%}'}`;
                if(typeCondition === 'tags') {
                    result += `{%- case page_type -%}
                                    {%- when 'collection' -%}
                                        {% assign typeCondition = collection.${typeCondition} %}
                                    {%- when 'article' -%}
                                        {% assign typeCondition = article.${typeCondition} %}
                                    {%- when 'blog' -%}
                                        {% assign typeCondition = blog.${typeCondition} %}
                                    {%- when 'product' -%}
                                        {% assign typeCondition = product.${typeCondition} %}
                                {%- endcase -%}`
                }
                else if(typeCondition === 'user_tags') {
                    result += `{% assign typeCondition = customer.tags %} {%- unless customer -%}{%- assign checkCondition = false -%}{%-endunless-%}`;
                }
                else {
                    if(input.toString().includes(',')) {
                        // multi-tag: assign as plain string for direct == comparison
                        result += `{% assign typeCondition = product.${typeCondition} %}`
                    } else {
                        // single-tag: array via concat for contains + for-loop check
                        result += `{% assign typeCondition = "" | split: '' %}{% assign typeCondition = product.${typeCondition} | concat: typeCondition %}`
                    }
                }
                if(input.toString().includes(',')) {
                    let tags = input.split(',');
                    if(tags.length) {
                        if(typeCondition === 'tags' || typeCondition === 'user_tags') {
                            // tags/user_tags are arrays → use contains + for-loop for exact match
                            tags.forEach((tag) => {
                                result += `
                                    {% assign tag = "${tag.trim()}" | replace: 'amp;', '' %}
                                    {%- if typeCondition contains tag -%}
                                        {% for type in typeCondition %}
                                            {% if type == tag %}
                                                ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                                                {% break %}
                                            {% endif %}
                                        {% endfor %}
                                    {%- endif -%}
                                `
                            });
                        } else {
                            // product.type / product.vendor are single strings → use direct == comparison
                            tags.forEach((tag) => {
                                result += `
                                    {% assign tag = "${tag.trim()}" | replace: 'amp;', '' %}
                                    {%- if typeCondition == tag -%}
                                        ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                                    {%- endif -%}
                                `
                            });
                        }
                        if(type !== 'user_tags') {
                            result += `{%- unless 'collection,product,blog,article' contains page_type -%}
                                {% assign checkCondition = true %}
                            {%- endunless -%}`
                        }
                    }
                }
                else {
                    result += `
                        {%- if typeCondition contains "${input.trim()}" -%}
                            {% for type in typeCondition  %}
                                {% if type == "${input.trim()}" %}
                                    ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                                    {% break %}
                                {% endif %}
                            {% endfor %}
                        {%- endif -%}
                        ${type !== 'user_tags'
                            ? `{%- unless 'collection,product,blog,article' contains page_type -%}
                                    {% assign checkCondition = true %}
                                {%- endunless -%}`
                            : ``
                        }
                    `
                }
                result += `{%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
            }
            return result;
        },
        handleConditionMetafields (settings, operator) {
            let metafields = settings.metafields ?? '',
                condition_metafields = '==',
                value = settings.metafields_value ?? '',
                value_type = settings.value_type;
            switch(value_type) {
                case 'boolean':
                    condition_metafields = settings.condition_metafields_boolean;
                    break;
                case 'number':
                    condition_metafields = settings.condition_metafields_number;
                    break;
                case 'string':
                    condition_metafields = settings.condition_metafields_string;
                    break;
            }
            let result = `{%- assign checkCondition = true -%} {% assign metafields = ${metafields} | default: '' %}`;
            if(settings.metafields_condition_type === 'is_empty') {
                result += `
                {%- if metafields == blank -%}
                    {%- assign checkCondition = true -%}
                {%- else -%}
                    {%- assign checkCondition = false -%}
                {%- endif -%}
                {%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
                return result;
            }
            if(settings.metafields_condition_type === 'not_empty') {
                result += `
                {%- if metafields != blank -%}
                    {%- assign checkCondition = true -%}
                {%- else -%}
                    {%- assign checkCondition = false -%}
                {%- endif -%}
                {%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
                return result;
            }
            if(metafields.toString() === '' || value.toString() === '') return '';
            if(condition_metafields === 'contains') {
                result += `{% assign metafields = metafields | join: "," %}{% assign metafields = metafields | split: "," %}`
            }
            if(value_type === 'string') value = `"${value}"`;
            result += `
                {%- if metafields and metafields ${condition_metafields} ${value} -%}
                    {%- assign checkCondition = true -%}
                {%- else -%}
                    {%- assign checkCondition = false -%}
                {%- endif -%}
                {%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}
            `
            return result;
        },
        handleConditionCart(settings, operator) {
            let result = '';
            if(settings.condition_cart === 'empty') {
                result += `{%- if cart.item_count == 0 -%}{% assign checkCondition = true %} {%- else -%} {% assign checkCondition = false %} {%- endif -%}
                            {%- unless request.page_type == 'cart' -%} {% assign checkCondition = true %}{%- endunless -%}
                            {%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}
                `
            }
            else {
                result += `{%- if cart.item_count == 0 -%}{% assign checkCondition = false %} {%- else -%} {% assign checkCondition = true %} {%- endif -%}
                            {%- unless request.page_type == 'cart' -%} {% assign checkCondition = true %}{%- endunless -%}
                            {%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}
                `
            }
            return result;
        },
        handleConditionLanguage(settings, operator) {
            let langs = settings.language_iso_code,
            not_contain = settings.condition == 'not_contain' ? true : false;
            if(!langs) return '';
            let result = `{% assign iso_code = request.locale.iso_code %} {% assign langCheck = "${langs.trim()}" %}{%- assign checkCondition = true -%}`;
            if(langs.toString().includes(',')) {
                const arr = langs.split(',');
                langs = arr.map(it => it.trim()).join(',');
                result += `{% assign langCheck = langCheck | split: "," %}
                        {% for lang in langCheck  %}
                            {% if lang == iso_code %}
                                ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                                {% break %}
                            {% endif %}
                        {% endfor %}
                    `
            }
            else {
                result += `
                    {% if iso_code == langCheck %}
                        ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                    {% else %}
                        ${not_contain ? '{%- assign checkCondition = true -%}' : '{%- assign checkCondition = false -%}'}
                    {% endif %}
                `
            }
            result += `{%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
            return result;
        },
        handleConditionCountry(settings, operator) {
            // country_iso_code comes from the country picker (multiple) => array of ISO 3166-1 alpha-2 codes
            let codes = settings.country_iso_code ?? [],
                not_contain = settings.condition == 'not_contain' ? true : false;

            if (!Array.isArray(codes)) {
                codes = codes.toString().split(',');
            }
            codes = codes.map(code => code?.toString().trim().toUpperCase()).filter(code => code);
            if (!codes.length) return '';

            // localization.country is the market country the visitor is browsing in
            let result = `{%- assign country_iso_code = localization.country.iso_code | default: '' -%}
                        {%- assign countryCheck = "${codes.join(',')}" | split: "," -%}
                        ${not_contain ? '{%- assign checkCondition = true -%}' : '{%- assign checkCondition = false -%}'}
                        {%- for country_code in countryCheck -%}
                            {%- if country_code == country_iso_code -%}
                                ${not_contain ? '{%- assign checkCondition = false -%}' : '{%- assign checkCondition = true -%}'}
                                {%- break -%}
                            {%- endif -%}
                        {%- endfor -%}`;
            result += `{%- if condition ${operator} checkCondition -%} {%- assign condition = true -%} {%- else -%} {%- assign condition = false -%} {%- endif -%}`
            return result;
        },
    }
};
