    >
        <a v-if="pageTypes !== 'popup'" :id="button?.button_id" :class="animatedClass"
            :href="button?.link ? button.link.href : '#'" v-bind="attrLink" :data-ec-tracking-id="button?.tracking_id"
            :data-event-tracking-fb="button?.event_tracking_fb" :draggable="!exporting ? false : null"
            class="ecom__element--button ecom-flex ecom-fl_center ecom-al_center"
            :data-ecom-popup="button?.button_type && button?.button_type === 'popup' ? (button?.popup_container?.id ?? button?.popup_container?.value) : null">
            <span
                ref="content"
                class="ecom__element--button-icon-text ecom-html"
                :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
                spellcheck="false"
                @dblclick.stop.prevent="edit"
                @keyup="update"
                @blur="handleBlur"
                v-html="isEditingThisElement ? editingValue : lang(button?.content, 'button-content')"
