        </a>
        <a v-else :id="button?.button_id"
            :class="[animatedClass, button?.button_type === 'dont_show_again' ? 'ecom-close-not-show' : '']"
            :href="'javascript:void(0)'"
            v-bind="attrLink" :data-ec-tracking-id="button?.tracking_id"
            :data-event-tracking-fb="button?.event_tracking_fb" :draggable="!exporting ? false : null"
            class="ecom__element--button ecom-flex ecom-fl_center ecom-al_center">
            <span
                ref="content"
                class="ecom__element--button-icon-text ecom-html"
                :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
                spellcheck="false"
                @dblclick.stop.prevent="edit"
                @keyup="update"
                @blur="handleBlur"
                v-html="isEditingThisElement ? editingValue : lang(button?.content, 'button-content')"
            />
            <span class="ecom-button-icon ecom__element--button-icon" v-html="button?.icon" />
        </a>
    </div>
</template>

<script>
import { Element, Javascript } from '@/mixins';
import { hover } from "@/plugins/fields/core/alias/icon";
import { getContentEditableValue, placeCaretAtEnd } from '@/utils/contentEditable';

const VALID_BUTTON_STYLE_PRESETS = ['primary', 'secondary', 'accent', 'link'];
/** Popup dropdown default; matches field system convention (DropdownOptions active state). */
const BUTTON_STYLE_PRESET_FIELD_DEFAULT = '__delete__';

const BUTTON_SITE_SUFFIX = {
    primary: '_button_primary',
    secondary: '_button_secondary',
    accent: '_button_accent',
    link: '_button_link',
};

const BUTTON_SITE_STYLE_FIELD_STEMS = [
    // new-format keys (from 896fba8ff refactor) kept for cleanup
    'color',
    'background-color',
    'box-shadow',
    'border',
    'border-radius',
    'colorHover',
    'background-colorHover',
    'box-shadowHover',
    'borderHover',
    'border-radiusHover',
    'typography',
    'text-shadow',
    'padding',
];

const BUTTON_PRESET_FIELD_MAPPINGS = [
    { siteBase: 'typography', elementKey: 'buttonTypography' },
    { siteBase: 'text-shadow', elementKey: 'buttonTextShadow' },
    { siteBase: 'padding', elementKey: 'spacing', wrapAs: 'padding' },
    { siteBase: 'color', elementKey: 'buttonColornormalmode', hover: false },
    { siteBase: 'background-color', elementKey: 'buttonBackgroundnormalmode', hover: false },
    { siteBase: 'box-shadow', elementKey: 'buttonBoxShadow', hover: false },
    { siteBase: 'border', elementKey: 'buttonBordernormalmode', hover: false },
    { siteBase: 'border-radius', elementKey: 'buttonBorderRadiusnormalmode', hover: false },
    { siteBase: 'color', elementKey: 'buttonColorhovermode', hover: true },
    { siteBase: 'background-color', elementKey: 'buttonBackgroundhovermode', hover: true },
    { siteBase: 'border', elementKey: 'buttonBorderhovermode', hover: true },
    { siteBase: 'border-radius', elementKey: 'buttonBorderRadiushovermode', hover: true },
];

const LEGACY_BUTTON_STYLE_PREFIXES = [
    'buttonTypography',
    'buttonTextShadow',
    'buttonBoxShadow',
    'buttonColor',
    'buttonBackground',
    'buttonBorder',
    'buttonBorderRadius',
    'spacing',
    'padding',
    'tab',
];

function normalizeButtonStylePreset(value) {
    if (value === null || value === undefined || value === '' || value === '__delete__') {
        return '';
    }
    const preset = String(value);
    return VALID_BUTTON_STYLE_PRESETS.includes(preset) ? preset : '';
}

function getSiteButtonSettings(themeSettings) {
    if (!themeSettings || typeof themeSettings !== 'object') {
        return {};
    }
    const nested = themeSettings.button;
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
        return nested;
    }
    return themeSettings;
}

function siteButtonFieldKey(preset, base, hover = false) {
    if (!preset) {
        if (hover) {
            const hoverKeys = {
                color: 'colorHover',
                'background-color': 'background-colorHover',
                border: 'borderHover',
                'border-radius': 'border-radiusHover',
                'box-shadow': 'box-shadowHover',
            };
            return hoverKeys[base] ?? null;
        }
        return base;
    }

    const suffix = BUTTON_SITE_SUFFIX[preset];
    if (hover) {
        const hoverBase = {
            color: 'colorHover',
            'background-color': 'background-colorHover',
            border: 'borderHover',
            'border-radius': 'border-radiusHover',
            'box-shadow': 'box-shadowHover',
        };
        const h = hoverBase[base];
        return h ? `${h}${suffix}` : null;
    }

    const named = {
        typography: `typography${suffix}`,
        'text-shadow': `text-shadow${suffix}`,
        padding: `padding${suffix}`,
        color: `color${suffix}`,
        'background-color': `background-color${suffix}`,
        border: `border${suffix}`,
        'border-radius': `border-radius${suffix}`,
        'box-shadow': `box-shadow${suffix}`,
    };
    return named[base] ?? null;
}

/** Element `type: background` stores `{ classic | gradient }`; site button preset uses `type: color`. */
function isBackgroundFieldDataShape(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return false;
    }
    return Object.prototype.hasOwnProperty.call(value, 'classic') ||
        Object.prototype.hasOwnProperty.call(value, 'gradient');
}

function siteColorValueToBackgroundFieldData(raw) {
    if (raw === undefined || raw === null || raw === '') {
        return undefined;
    }
    if (isBackgroundFieldDataShape(raw)) {
        return JSON.parse(JSON.stringify(raw));
    }
    return {
        classic: {
            'background-color': JSON.parse(JSON.stringify(raw)),
        },
    };
}

const BUTTON_ELEMENT_BACKGROUND_KEYS = new Set(['buttonBackgroundnormalmode', 'buttonBackgroundhovermode']);

function copySiteFieldToElement(siteButton, siteKeyStem, elementKeyStem, target = {}, wrapAs = null) {
    const toBackgroundField = BUTTON_ELEMENT_BACKGROUND_KEYS.has(elementKeyStem);

    for (const key of Object.keys(siteButton)) {
        if (key !== siteKeyStem && !key.startsWith(`${siteKeyStem}__`)) {
            continue;
        }
        const raw = siteButton[key];
        if (raw === undefined || raw === null || raw === '') {
            continue;
        }
        const suffix = key === siteKeyStem ? '' : key.slice(siteKeyStem.length);
        let value = JSON.parse(JSON.stringify(raw));
        if (toBackgroundField) {
            value = siteColorValueToBackgroundFieldData(value);
            if (value === undefined) {
                continue;
            }
        }
        const targetKey = `${elementKeyStem}${suffix}`;
        if (wrapAs) {
            const existing = target[targetKey];
            target[targetKey] = Object.assign(
                {},
                typeof existing === 'object' && existing !== null ? existing : {},
                { [wrapAs]: value }
            );
        } else {
            target[targetKey] = value;
        }
    }
    return target;
}

function buildButtonStyleFromSitePreset(themeSettings, preset) {
    if (!preset) {
        return {};
    }

    const siteButton = getSiteButtonSettings(themeSettings);
    const output = { tab: 'normal' };

    for (const mapping of BUTTON_PRESET_FIELD_MAPPINGS) {
        const siteKeyStem = siteButtonFieldKey(preset, mapping.siteBase, !!mapping.hover);
        if (!siteKeyStem) {
            continue;
        }
        copySiteFieldToElement(siteButton, siteKeyStem, mapping.elementKey, output, mapping.wrapAs ?? null);
    }

    return output;
}

/** Style values copied/cleared when applying a preset (excludes UI-only keys). */
function isButtonPresetStyleKey(key) {
    if (key === 'buttonStylePreset' || key === 'tab_button') {
        return false;
    }
    if (LEGACY_BUTTON_STYLE_PREFIXES.some((prefix) => key === prefix || key.startsWith(prefix))) {
        return true;
    }
    return BUTTON_SITE_STYLE_FIELD_STEMS.some(
        (stem) => key === stem || key.startsWith(`${stem}__`)
    );
}

function isButtonPresetManagedKey(key) {
    if (key === 'tab' || key === 'tab_button') {
        return true;
    }
    return isButtonPresetStyleKey(key);
}

function clearButtonPresetManagedStyles(buttonStyle) {
    for (const key of Object.keys(buttonStyle)) {
        if (key === 'buttonStylePreset') {
            continue;
        }
        if (isButtonPresetManagedKey(key)) {
            delete buttonStyle[key];
        }
    }
}

function pickButtonPresetStyle(buttonStyle) {
    if (!buttonStyle) {
        return {};
    }
    const picked = {};
    for (const key of Object.keys(buttonStyle)) {
        if (key === 'buttonStylePreset') {
            continue;
        }
        if (isButtonPresetStyleKey(key)) {
            picked[key] = JSON.parse(JSON.stringify(buttonStyle[key]));
        }
    }
    return picked;
}

function serializeButtonPresetSnapshot(style) {
    return JSON.stringify(pickButtonPresetStyle(style));
}

function isButtonStyleCustomized(buttonStyle, snapshot) {
    if (!buttonStyle || !snapshot) {
        return false;
    }

    return serializeButtonPresetSnapshot(buttonStyle) !== snapshot;
}

