                        condition: (data) => data['tab'] === 'hover',
                    },
                },
                css: {
                    selector: ':hover',
                    properties: { width: '' },
                },
            },
            {
                name: 'buttonHeighthovermode',
                liteMode: true,
                label: $t('height'),
                type: 'number',
                options: {
