}

export default {
    name: 'Button',
    presets: true,
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/button/',
    mixins: [Element, Javascript],
    inject: ['exporting'],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            editing: false,
            jsreactives: ['animation_loop_time', 'animation'],
            _applyingButtonPreset: false,
            _buttonPresetSnapshot: null,
            editingValue: '',
            lastUpdate: 0,
            isTyping: false,
            isBlur: false
        };
    },
    computed: {
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.data.id;
        },
        isContentEditable() {
            return this.$store.getters['builder/isContentEditable'];
        },
        editingElementId() {
            return this.$store.getters['builder/editingElementId'];
        },
        isEditingThisElement() {
            if (this.exporting) return false;
            return this.editingElementId === this.data.id && this.isContentEditable;
        },
        pageTypes() {
            return this.$store.getters['page/params']?.page || '';
        },
        javascript() {
            return function () {
                if (!this.$el) {
                    return false;
                }
                const $el = this.$el;

                if (this.settings.animation) {
                    (function (_this) {
                        if (!$el) return;

                        const $btn_wrapper = $el.querySelector('.ecom__element--button');
                        if (!$btn_wrapper) return;

                        let intervalTime = parseInt(_this.settings.animation_loop_time) * 1000 || 6000,
                            animTime = 1000;

                        setInterval(function () {
                            $btn_wrapper.classList.add('animated');
                            setTimeout(function () {
                                $btn_wrapper.classList.remove('animated');
                            }, animTime);
                        }, intervalTime);

                    })(this)
                }
                var $button = $el.querySelector('.ecom__element--button');
                if (this.isLive && $button && $button.dataset.ecTrackingId) {
                    $button.addEventListener('click', function (e) {
                        if (window.Shopify && window.Shopify.analytics) {
                            e.preventDefault();

                            let dt =
                                window.EComposer.PAGE ||
                                window.EComposer.TEMPLATE ||
                                window.EComposer.SECTION ||
                                window.EComposer.BLOCK ||
                                {};

                            const data = Object.assign({
                                "button_id": $button.id,
                                "tracking_id": $button.dataset.ecTrackingId,
                            }, dt);

                            try {
                                Shopify.analytics.publish("ec_custom_events", data);
                            } catch (err) {
                                console.error('[EC Tracking] Error publishing analytics event:', err);
                            }

                            // Redirect thủ công sau khi publish để pixel sandbox kịp
                            // nhận postMessage và gọi fetch(keepalive:true) trước khi navigate.
                            const href = $button.getAttribute('href');
                            const target = $button.getAttribute('target');

                            if (href && href !== '#' && href !== 'javascript:void(0)') {
                                if (target === '_blank') {
                                    // _blank: tab hiện tại không unload → không cần delay
                                    window.open(href, '_blank');
                                } else {
                                    // Delay 300ms để pixel sandbox kịp gọi fetch(keepalive:true)
                                    // trước khi page navigate → sandbox bị destroy.
                                    setTimeout(function () {
                                        window.location.href = href;
                                    }, 300);
                                }
                            }
                        }
                    }, { once: true });
                }
                if (this.isLive && $button && $button.dataset.eventTrackingFb) {
                    $button.addEventListener('click', function (e) {
                        if (window.fbq) {
                            window.fbq('track', `${$button.dataset.eventTrackingFb}`);
                        }
                    }, { once: true });
                }

            };
        },
        animatedClass() {
            return this.data?.settings?.animation ? 'animated' : '';
        },
        buttonPresetClass() {
            const preset = this.data?.style?.button?.buttonStylePreset;
            const validPresets = ['primary', 'secondary', 'accent', 'link'];
            if (preset && validPresets.includes(preset)) {
                return `ecom-button-${preset}`;
            }
            return 'ecom-button-default';
        },
        settings() {
            const settingsButton = [{
                group_alias: 'button:settings',
                options: {
                    group_name: '',
                    group_title: this.$t('button'),
                },
                modify: {
                    remove: [
                        {
                            index: 4,
                            length: 1
                        }
                    ],
                    params: [{
                        position: 10,
                        fields: [
                            {
                                type: 'line'
                            },
                            {
                                type: 'toggle',
                                name: 'animation',
                                label: this.$t('button_animation'),
                                options: {
                                    preview: 'title',
                                    values: {
                                        on: {
                                            label: this.$t('enable'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('disable'),
                                            value: false
                                        }
                                    }
                                },
                            },
                            {
                                type: "number",
                                label: this.$t('loop_time_span_class_lowercase_s_span'),
                                name: "animation_loop_time",
                                options: {
                                    min: 2,
                                    default: 6,
                                    max: 10,
                                    visible: function (data) {
                                        return data.animation == true;
                                    }
                                }
                            },
                        ]
                    }]
                }
            },
            {

                group_title: this.$t('tracking'),
                params: [

                    {
                        type: 'text',
                        name: 'tracking_id',
                        label: this.$t('tracking_id'),
                        options: {
                            placeholder: this.$t('your_cta_name')
                        }
                    },
                    {
                        type: 'paragraph',
