                        options: {
                            type: 'popup',
                            layout: 'list',
                            multiple: false,
                            visible: (data)=>{
                                return data['button_type'] && data['button_type'] === 'popup'
                            }
                        }
                    },

                ]
            })
            return settingsButton;
        },
