                //             "font-family": {
                //                 "name": "Inter",
                //                 "value": "https://fonts.googleapis.com/css?family=Inter:100,200,300,400,500,600,700,800,900",
                //                 "thumbnail": "Inter"
                //             },
                //             "font-size": "14px",
                //             "font-weight": "500",
                //             "line-height": "1.4em",
                //             "letter-spacing": "0px",
                //             "font-style": "normal",
                //             "text-transform": "capitalize"
                //         },
                //         "buttonBorderRadiusnormalmode": {
                //             "top": "4px",
                //             "left": "4px",
                //             "bottom": "4px",
                //             "right": "4px"
                //         },
