    },
    watch: {
        'data.style.button.buttonStylePreset'(newVal, oldVal) {
            if (this._applyingButtonPreset || this.exporting) {
                return;
            }

            const preset = normalizeButtonStylePreset(newVal);
            const prevPreset = normalizeButtonStylePreset(oldVal);

            if (preset === prevPreset) {
                return;
            }

            if (!preset) {
                this._buttonPresetSnapshot = null;
                return;
            }

            // First pick: oldVal undefined — apply unless page already has saved preset styles.
            if (oldVal === undefined && this._buttonPresetSnapshot) {
                return;
            }

            this.confirmAndApplyButtonPreset(preset, prevPreset);
        },
        'data.style.button': {
            deep: true,
            handler(buttonStyle) {
                if (this._applyingButtonPreset || this.exporting || !buttonStyle) {
                    return;
                }

                const preset = normalizeButtonStylePreset(buttonStyle.buttonStylePreset);
                if (!preset) {
                    return;
                }

                // No snapshot yet = user picked preset in dropdown but has not confirmed Apply.
                // Do not treat as customization (avoids _applyingButtonPreset blocking first apply).
                if (!this._buttonPresetSnapshot) {
                    return;
                }

                if (isButtonStyleCustomized(buttonStyle, this._buttonPresetSnapshot)) {
                    this._applyingButtonPreset = true;
                    buttonStyle.buttonStylePreset = BUTTON_STYLE_PRESET_FIELD_DEFAULT;
                    this._buttonPresetSnapshot = null;
                    this.$nextTick(() => {
                        this._applyingButtonPreset = false;
                    });
                }
            },
        },
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit('builder/setIsContentEditable', false);
                this.$store.commit('builder/setEditingElementId', '');
                const content = this.$refs.content;
                if (content) {
                    this.button.content = getContentEditableValue(content, 'text');
                }
            }
            if (val) {
                this.$store.commit('builder/setEditingElementId', this.data.id);
            }
        },
        'data.settings.content': {
            handler(newVal) {
                if (!this.isEditingThisElement || (!this.isTyping && newVal !== this.editingValue)) {
                    this.editingValue = newVal;
                }
            },
            immediate: true
        },
        isContentEditable() {
            this.isBlur = false;
        },
        isEditingThisElement(val) {
            if (val) {
                this.editingValue = this.data.settings.content;
                this.focusContentEditor();
            }
        },
    },
    methods: {
        confirmAndApplyButtonPreset(preset, prevPreset) {
            const callbackKey = `ecomButtonStylePreset_${Date.now()}`;
            window[callbackKey] = (action) => {
                if (action === 'accept') {
                    this.applyButtonStylePreset(preset);
                } else {
                    this._applyingButtonPreset = true;
                    if (!this.data.style) {
                        this.data.style = {};
                    }
                    if (!this.data.style.button) {
                        this.data.style.button = {};
                    }
                    this.data.style.button.buttonStylePreset = prevPreset || BUTTON_STYLE_PRESET_FIELD_DEFAULT;
                    this.$nextTick(() => {
                        this._applyingButtonPreset = false;
                    });
                }
                this.$store.commit('builder/setPopup', { show: false });
                delete window[callbackKey];
            };

            this.$store.commit('builder/setPopup', {
                show: true,
                type: 'warning',
                size: 'small',
                loading: false,
                closeable: true,
                title: this.$t('button_style_preset_override_title'),
                message: this.$t('button_style_preset_override_message'),
                callback: callbackKey,
                action: {
                    title: this.$t('apply'),
                },
                cancel: this.$t('cancel'),
            });
        },
        applyButtonStylePreset(preset) {
            const themeSettings = this.$store.getters['settings/themeSettings'];
            const presetStyles = buildButtonStyleFromSitePreset(themeSettings, preset);

            this._applyingButtonPreset = true;

            if (!this.data.style) {
                this.data.style = {};
            }
            if (!this.data.style.button) {
                this.data.style.button = {};
            }

            clearButtonPresetManagedStyles(this.data.style.button);
            Object.assign(this.data.style.button, presetStyles, {
                buttonStylePreset: preset,
            });

            this._buttonPresetSnapshot = serializeButtonPresetSnapshot(this.data.style.button);

            this.$nextTick(() => {
                this._applyingButtonPreset = false;
                if (typeof this.createStyle === 'function') {
                    this.createStyle();
                }
            });
        },
        edit() {
            if (this.exporting) return;
            this.editingValue = this.data.settings?.content || '';
            this.$store.commit('builder/setEditingElementId', this.data.id);
            this.$store.commit('builder/setIsContentEditable', true);
        },
        focusContentEditor() {
            this.$nextTick(() => {
                const el = this.$refs.content;
                if (!el || !this.isEditingThisElement) return;
                placeCaretAtEnd(el, this.idoc());
            });
        },
        handleBlur() {
            if (this.exporting) return;
            if (!this.isBlur) return;
            setTimeout(() => {
                this.$store.commit('builder/setIsContentEditable', false);
            }, 200);
        },
        update(e) {
            if (this.exporting) return;
            const now = Date.now();
            if (now - this.lastUpdate > 300) {
                const target = e.target;
                const newContent = getContentEditableValue(target, 'text');
                if (this.button.content !== newContent) {
                    this.isTyping = true;
                    this.button.content = newContent;
                    this.lastUpdate = now;
                    this.$nextTick(() => {
                        this.isTyping = false;
                    });
                }
            }
        },
        quickToolBar() {
            return ['buttonStylePreset', 'buttonColornormalmode', 'buttonBackgroundnormalmode'];
        },
        style() {
            const inGrid = this.data.inGrid || false;
            const buttonStyleFields = getButtonElementStyleFields(this.$t, inGrid);
            let style = [
                {
                    group_name: 'button',
                    group_title: this.$t('button'),
                    selector: ' .ecom__element--button',
                    params: [
                        {
                            name: 'buttonStylePreset',
                            label: this.$t('button_style'),
                            type: 'popup',
                            value: BUTTON_STYLE_PRESET_FIELD_DEFAULT,
                            options: {
                                type: 'dropdown',
                                values: {
                                    [BUTTON_STYLE_PRESET_FIELD_DEFAULT]: this.$t('default'),
                                    'primary': this.$t('primary'),
                                    'secondary': this.$t('secondary'),
                                    'accent': this.$t('accent'),
                                    'link': this.$t('link'),
                                },
                                preview: 'title',
                                oneline: true,
                            },
                            css: {
                                isCss: false,
                            },
                        },
                        ...(!inGrid
                            ? [
                                {
                                    alias: 'justify-content',
                                    options: {
                                        label: this.$t('alignment'),
                                        css: {
                                            selector: 'root .ecom-button-default',
                                        },
                                    },
                                },
                            ]
                            : []),
                        {
                            alias: 'text-align',
                            options: {
                                label: this.$t('content_alignment'),
                                name: 'content_alignment',
                                liteMode: true,
                                css: {
                                    selector: 'root .ecom__element--button, root .ecom__element--button span',
                                    properties: {
                                        'justify-content': '',
                                        'text-align': '',
                                        'align-items': '',
                                    },
                                },
                            },
                        },
                        ...buttonStyleFields,
                    ],
                },
                {
                    group_name: 'button_animation',
                    group_title: this.$t('animation_effect'),
                    selector: ' .ecom__element--button',
                    params: [
                        {
                            name: "animation",
                            label: this.$t('animation'),
                            type: "popup",
                            options: {
                                type: "dropdown",
                                prevew: 'title',
                                values: {
                                    // 'fading': this.$t('fading'),
                                    'fade-in': this.$t('fade_in'),
                                    'fade-in-down': this.$t('fade_in_down'),
                                    'fade-in-left': this.$t('fade_in_left'),
                                    'fade-in-right': this.$t('fade_in_right'),
                                    'fade-in-up': this.$t('fade_in_up'),
                                    // 'zooming': this.$t('zooming'),
                                    'zoom-in': this.$t('zoom_in'),
                                    'zoom-in-down': this.$t('zoom_in_down'),
                                    'zoom-in-left': this.$t('zoom_in_left'),
                                    'zoom-in-right': this.$t('zoom_in_right'),
                                    'zoom-in-up': this.$t('zoom_in_up'),
                                    // 'bouncing': this.$t('bouncing'),
                                    'bounce-in': this.$t('bounce_in'),
                                    'bounce-in-down': this.$t('bounce_in_down'),
                                    'bounce-in-left': this.$t('bounce_in_left'),
                                    'bounce-in-right': this.$t('bounce_in_right'),
                                    'bounce-in-up': this.$t('bounce_in_up'),
                                    // 'sliding': this.$t('sliding'),
                                    // 'sliding-in': this.$t('sliding_in'),
                                    // 'sliding-in-down': this.$t('sliding_in_down'),
                                    // 'sliding-in-left': this.$t('sliding_in_left'),
                                    // 'sliding-in-right': this.$t('sliding_in_right'),
                                    // 'sliding-in-up': this.$t('sliding_in_up'),
                                    'rotate': this.$t('rotate'),
                                    // 'rotate-in': this.$t('rotate_in'),
                                    // 'rotate-in-down': this.$t('rotate_in_down'),
                                    // 'rotate-in-left': this.$t('rotate_in_left'),
                                    // 'rotate-in-right': this.$t('rotate_in_right'),
                                    // 'rotate-in-up': this.$t('rotate_in_up'),
                                    // 'attention-seekers': this.$t('attention_seekers'),
                                    // 'bounce': this.$t('bounce'),
                                    'flash': this.$t('flash'),
                                    'pulse': this.$t('pulse'),
                                    'rubber-band': this.$t('rubber_band'),
                                    'shake': this.$t('shake'),
                                    // 'head-shake': this.$t('head_shake'),
                                    'heart-beat': this.$t('heart_beat'),
                                    'swing': this.$t('swing'),
                                    'tada': this.$t('tada'),
                                    'wobble': this.$t('wobble'),
                                    'jello': this.$t('jello'),
                                    // 'light-speed': this.$t('light_speed'),
                                    // 'light-speed-in': this.$t('light_speed_in'),
                                    // 'specials': this.$t('specials'),
                                    // 'roll-in': this.$t('roll_in'),
                                    'shake-y': this.$t('shake_y'),
                                    'back-in-down': this.$t('back_in_down'),
                                    'back-in-left': this.$t('back_in_left'),
                                    'back-in-right': this.$t('back_in_right'),
                                    'back-in-up': this.$t('back_in_up'),
                                    'flip': this.$t('flip'),
                                    'flip-x': this.$t('flip_x'),
                                    'flip-y': this.$t('flip_y'),
                                    'light-speed-in-right': this.$t('light_speed_in_right'),
                                    'light-speed-in-left': this.$t('light_speed_in_left'),
                                    'roll': this.$t('roll'),
                                },
                                size: "small",
                                preview: 'title',
                            },
                            css: {
                                selector: ".animated",
                                properties: {
                                    'entrance-animation': ""
                                }
                            }
                        },
                    ]
                }
            ];
            if (this.button?.icon) {
                let icon_params = [...hover('root .ecom__element--button:hover .ecom-button-icon').params];
                icon_params.push(
                    {
                        type: "line",
                        liteMode: true
                    },
                    {
                        alias: "spacing"
                    }
                )
                style.push({
                    group_title: this.$t('icon'),
                    group_name: 'icon',
                    selector: ' .ecom-button-icon',
                    params: icon_params
                });
            }

            return style;
        }
    },
    mounted() {
        if(this.pageTypes !== 'popup') {
            if(this.data?.settings?.button_type === 'dont_show_again') {
                this.data.settings.button_type = 'link';
            }
        }

        const buttonStyle = this.data?.style?.button;
        if (buttonStyle) {
            const raw = buttonStyle.buttonStylePreset;
            if (raw === undefined || raw === null || raw === '') {
                buttonStyle.buttonStylePreset = BUTTON_STYLE_PRESET_FIELD_DEFAULT;
            }
        }

        const preset = normalizeButtonStylePreset(this.data?.style?.button?.buttonStylePreset);
        if (preset) {
            this._buttonPresetSnapshot = serializeButtonPresetSnapshot(this.data?.style?.button);
        }
    }
};
