<template>
    <GroupElement
        :data="data"
        :close_all="data.settings?.close_all"
        :section_id="section_id"
        :breadcrumb="`${breadcrumb}/${data?.id}`"
        :item-style-fn="content_alignment"
        :gclasses="{
            wrapper: wrapper_class,
            body: 'ecom-accordion__body' + (data.settings.disable_effect ? ' ecom-accordion__body--auto-height' : '') + (data.settings.newChange ? ' ecom-accordion__item--flex' : ''),
            item: 'ecom-accordion__item',
        }"
        :inGrid="data.inGrid"
        :isFlexContainer="data.settings.newChange"
        :nameElement="'accordion'"

    >
        <template #title="{ item, index }">
            <div
                class="ecom-accordion__title ecom-flex ecom-w__full ecom-al_center ecom-items"
                @click="onAccordionTitleBarClick(index, $event)"
                :class="{
                    'ecom-item-active': index === 0 && !data.settings?.close_all
                }"
                :data-target="'#'+item.id_target"
                :data-target-id="'#'+item.id"
            >
                <div
                    v-if="data.settings?.icon?.value"
                    class="ecom-accordion_nav--icon ecom-items--icon"
                    :style="{
                        order: data.settings?.iconPosition
                    }"
                    v-html="data.settings?.icon?.value"
                />
                <div
                    v-if="data.settings.iconActive?.value"
                    class="ecom-accordion_nav--icon ecom-items--icon ecom-items-icon-active"
                    :style="{
                        order: data.settings?.iconPosition
                    }"
                    v-html="data.settings?.iconActive?.value"
                />

                <div class="ecom-accordion_wrapper-info ecom-flex ecom-al_center">
                    <span
                        class="ecom-items--icon ecom-accordion_icon-title"
                        :data-image="item.type === 'image'"
                        v-html="item.icon_title?.value"
                    ></span>
                    <div v-if="item.type === 'image'" class="ecom-accordion--image">
                        <img
                            :src="item?.image?.value"
                            :alt="item?.image?.name"
                            class="ecom-image-default"
                        />
                    </div>
                    <component
                        :is="item.tag ? item.tag : 'div'"
                        class="ecom-accordion__title-text ecom-items--text ecom-html"
                        spellcheck="false"
                        @click.stop="onAccordionTitleTextClick(index)"
                        v-html="item?.content_type === 'liquid' ? item.title : lang(item.title, 'item_title_' + index)"
                    />
                </div>
            </div>
        </template>
    </GroupElement>
</template>
<script>
import GroupElement from "../../Layout/Group.vue";

import { Element, Javascript } from "@/mixins";

export default {
    name: "Accordion",
    inject: ['instanceStore'],
    presets: true,
    components: { GroupElement },
    mixins: [Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
