            return this?.$parent.section_id || "";
        },
        accordion() {
            return this.data;
        },
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.accordion.id;
        },
        isContentEditable() {
            return this.$store.getters["builder/isContentEditable"];
        },
        wrapper_class() {
            return this.data.settings?.close_all
                ? "ecom-accordion__wrapper ecom-flex ecom-column ecom-w__full ecom__element ecom__accordion ecom-accordion-close-all"
