        },
        css() {
            return `
                    /*
                    body[ecom-loaded] .ecom__accordion:not(.ecom-accordion-close-all) .ecom-item-active.ecom-accordion__item:first-child > .ecom-accordion__body {
                        height: 100% !important;
                    }

                    body[ecom-loaded] .ecom-accordion__item:not(.ecom-item-active) > .ecom-accordion__body {
                        height: 0 !important;
                    } */
                    .ecom-accordion__title-text{
                        flex:1;
                        white-space: pre-wrap;
                    }
                    .core__group--item.ecom-accordion__item.ecom-item-active > .ecom-accordion__body {
                        overflow: inherit;
                    }
                    .core__group--item.ecom-accordion__item {
                        width: 100%;
                        flex:unset !important;
                        transition: all 500ms ease;
                    }
                    .ecom-accordion__item + .ecom-accordion__item {
                        margin-top: -1px;
                    }
                    .ecom-core .ecom-accordion__item >.ecom-accordion__body {
                        overflow: hidden;
                        margin: 0;
                        border: 0;
                        height:0;
                        opacity: 0;
                        /*transition:height 300ms ease-out;*/
                    }
                    .ecom-core .ecom-item-active > .ecom-accordion__body {
                        opacity: 1 !important;
                    }
                    /*.core__group--wrapper:not(.ecom-accordion-close-all) .ecom-accordion__item:first-child >.ecom-accordion__body  {
                        display: block;
                    }*/
                    .ecom-accordion__title {
                        cursor: pointer;
                    }
                    .ecom-accordion_nav--icon {
                        display: flex;
                        align-items: center;
                    }
                    .ecom-accordion_wrapper-info {
                        flex: 1;
                    }
                    .ecom-accordion_wrapper-info svg {
                        width: 20px;
                        height: 20px;
                    }
                    .ecom-accordion_wrapper-info .ecom-accordion_icon-title {
                        display: flex;
                    }

                    .ecom-accordion_nav--icon svg{
                        height:auto;
                    }
                    .ecom-accordion__body > div:not(.ec-flex-wp){
                        padding:0 !important;
                    }
                    .ecom-accordion__body > .ec-flex-wp{
                        flex-direction: column;
                    }
                    .ecom-items-icon-active{
                        display:none;
                    }
                    .ecom-accordion_nav--icon.ecom-items--icon {
                      transition: all .2s ease;
                    }
                    .ecom-item-active.ecom-accordion__item > .ecom-items > .ecom-accordion_nav--icon{
                        display:none
                    }
                    .ecom-item-active.ecom-accordion__item > .ecom-items > .ecom-items-icon-active{
                        display:flex;
                    }
                    .ecom-accordion__wrapper .core__group--items{
                        display:flex;
                        flex-wrap:wrap;
                    }
                    .ecom-core .ecom-item-active > .ecom-accordion__body.ecom-accordion__body--auto-height,
                    .ecom-item-group-init.ecom-item-active > .ecom-accordion__body{
                        height:auto !important;
                    }
                    .ecom-items--icon[data-image="true"]{
                        display: none;
                    }
                    .ec-flex-wp .ecom-accordion__wrapper .core__group--items .core__blocks--body {
                        justify-content: var(--ec-align-ct);
                    }
                    @media (max-width: 1024px) {
                        .ec-flex-wp .ecom-accordion__wrapper .core__group--items .core__blocks--body {
                            justify-content: var(--ec-align-ct-tb);
                        }
                    }
                    @media (max-width: 767px) {
                        .ec-flex-wp .ecom-accordion__wrapper .core__group--items .core__blocks--body {
                            justify-content: var(--ec-align-ct-mb);
                        }
                    }
                `;
        },

        javascript() {
            return function () {
                let $el = this.$el;
                if (!$el) return;
                let isLive = this.isLive;
                const disable_auto_close = this.settings.disable_auto_close ?? false,
                    disable_auto_close__tablet = this.settings.disable_auto_close__tablet ?? false,
                    disable_auto_close__mobile = this.settings.disable_auto_close__mobile ?? false,
                    scroll_on_mobile = this.settings.scroll_on_mobile ?? false,
                    disable_effect = this.settings.disable_effect ?? false,
                    close_all = this.settings.close_all ?? false;
                // Scope all DOM operations to this accordion. Descendant selectors would also
                // bind the parent accordion's settings/handler to nested accordions.
                const itemsContainer = $el.querySelector(
                    ":scope > .core__group--wrapper > .core__group--items"
                );
                const ownAccordionItems = itemsContainer
                    ? itemsContainer.querySelectorAll(":scope > .ecom-accordion__item")
                    : [];
                const accordionTitles = Array.from(ownAccordionItems)
                    .map(item => item.querySelector(":scope > .ecom-accordion__title"))
                    .filter(Boolean);

                function isInViewport(el) {
                    const rect = el.getBoundingClientRect();
                    return (
                        rect.top >= 0 &&
                        rect.left >= 0 &&
                        rect.bottom <=
                            (window.innerHeight || document.documentElement.clientHeight) &&
                        rect.right <= (window.innerWidth || document.documentElement.clientWidth)
                    );
                }

                function getInnerWidth() {
                    return window.EComposer.TEMPLATE_ID ? window.screen.width : window.innerWidth;
                }

                function canCloseActive(innerWidth) {
                    return (disable_auto_close__mobile && innerWidth < 768) ||
                        (disable_auto_close__tablet && innerWidth > 767 && innerWidth < 1025) ||
                        (disable_auto_close && innerWidth > 1024);
                }

                function openAccordion(body) {
                    if (!body) return;

                    const oldTransition = body.style.transition;
                    body.style.transition = 'none'; // Tắt transition để không bị nhảy
                    body.style.height = 'auto';

                    const targetHeight = body.scrollHeight;

                    body.style.height = '0px';
                    body.offsetHeight; // force reflow
                    body.style.transition = oldTransition; // Bật lại transition

                    requestAnimationFrame(() => {
                        const newHeight = disable_effect ? 'auto' : (isLive ? targetHeight + 'px' : 'auto');
                        body.style.height = newHeight;
                    });
                }

                function closeAccordion(item) {
                    item.classList.remove("ecom-item-active");
                    const body = item.querySelector(":scope > .ecom-accordion__body");
                    if (body) {
                        if (!disable_effect) {
                            body.style.height = body.scrollHeight + 'px';
                            body.offsetHeight; // force reflow
                        }
                        requestAnimationFrame(() => {
                            body.style.height = '0px';
                        });
                    }
                }

                function getElementPosition(obj) {
                    let currenttop = 0;
                    if (obj.offsetParent) {
                        do {
                            currenttop += obj.offsetTop;
                        } while ((obj = obj.offsetParent));
                    }
                    return currenttop;
                }

                function smoothScrollTo(top) {
                    const targetPosition = Math.max(0, top);
                    const startPosition = window.pageYOffset || document.documentElement.scrollTop;
                    const distance = targetPosition - startPosition;
                    if (distance === 0) return;
                    const duration = 300;
                    let start = null;
                    function step(timestamp) {
                        if (!start) start = timestamp;
                        const progress = Math.min((timestamp - start) / duration, 1);
                        const ease = progress < 0.5
                            ? 2 * progress * progress
                            : 1 - Math.pow(-2 * progress + 2, 2) / 2;
                        window.scrollTo(0, startPosition + distance * ease);
                        if (progress < 1) window.requestAnimationFrame(step);
                    }
                    window.requestAnimationFrame(step);
                }

                function scrollToElement(el) {
                    smoothScrollTo(getElementPosition(el) - 100);
                }

                function handle(accordionTitles, isInit = false) {
                    accordionTitles.forEach((accordion, index) => {
                        const parent = accordion.parentNode;
                        const body = parent.querySelector(":scope > .ecom-accordion__body");
                        if (!disable_effect && body) {
                            body.classList.add("ecom-effect-accodion");
                        }
                        // Only set height on init for first item, or if item is currently active
                        const isItemActive = parent.classList.contains("ecom-item-active");
                        if (body && !close_all && ((isInit && index === 0) || isItemActive)) {
                            requestAnimationFrame(() => {
                                body.style.height = body.scrollHeight + "px";
                            });
                        }
                        accordion.onclick = function (e) {
                            e.preventDefault();
                            // In the builder (isLive undefined) the Vue click handlers own open/close.
                            // Running this handler too would toggle twice and cancel itself out.
                            if (!isLive) {
                                window.dispatchEvent(new window.Event("renderScroll"));
                                return;
                            }
                            const currentInnerWidth = getInnerWidth();
                            const parent = this.parentNode;
                            const accWrapper = parent.parentNode;
                            const accordionItems = accWrapper.querySelectorAll(
                                ":scope > .ecom-accordion__item"
                            );
                            const titles = Array.from(accordionItems)
                                .map(item => item.querySelector(":scope > .ecom-accordion__title"))
                                .filter(Boolean);
                            const body = parent.querySelector(":scope > .ecom-accordion__body");

                            parent.classList && parent.classList.remove('ecom-item-group-init');

                            const isActive = this.classList.contains("ecom-item-active");
                            const allowCloseActive = canCloseActive(currentInnerWidth);

                            if (isActive) {
                                if (allowCloseActive) {
                                    this.classList.remove("ecom-item-active");
                                    parent.classList.remove("ecom-item-active");
                                    closeAccordion(parent);
                                } else {
                                    accordionItems.forEach(closeAccordion);
                                    titles.forEach(t => t.classList.remove("ecom-item-active"));
                                }
                            } else {
                                if (!allowCloseActive) {
                                    accordionItems.forEach(closeAccordion);
                                    titles.forEach(t => t.classList.remove("ecom-item-active"));
                                }

                                accordion.classList.add("ecom-item-active");
                                parent.classList.add("ecom-item-active");

                                // Handle nested accordion
                                let parentAccordionBody = parent.closest(".ecom-accordion__body");
                                while (parentAccordionBody) {
                                    parentAccordionBody.style.height = "auto";
                                    parentAccordionBody = parentAccordionBody.parentElement
                                        ?.closest?.(".ecom-accordion__body");
                                }

                                if (!disable_effect && body) {
                                    body.classList.add("ecom-effect-accodion");
                                }
                                openAccordion(body);
                            }

                            window.dispatchEvent(new window.Event("renderScroll"));

                            const titleEl = this;
                            const shouldScroll = scroll_on_mobile || currentInnerWidth > 1024;

                            function doScroll() {
                                window.dispatchEvent(new window.Event("renderScroll"));
                                if (shouldScroll && !isInViewport(titleEl)) {
                                    scrollToElement(titleEl);
                                }
                            }

                            if (shouldScroll && !disable_effect) {
                                // Listen on wrapper to catch transitionend from ALL items (opening + closing)
                                // Debounce to wait for the LAST transition to complete
                                let timer;
                                const onEnd = function (e) {
                                    if (e.propertyName === 'height') {
                                        clearTimeout(timer);
                                        timer = setTimeout(() => {
                                            accWrapper.removeEventListener('transitionend', onEnd);
                                            doScroll();
                                        }, 50);
                                    }
                                };
                                accWrapper.addEventListener('transitionend', onEnd);
                                // Fallback in case transitionend doesn't fire
                                setTimeout(() => {
                                    accWrapper.removeEventListener('transitionend', onEnd);
                                    doScroll();
                                }, 600);
                            } else {
                                requestAnimationFrame(() => {
                                    setTimeout(doScroll, 100);
                                });
                            }
                        };
                    });
                }

                handle(accordionTitles, true); // isInit = true for first load

                if (!close_all) {
                    requestAnimationFrame(() => {
                        const initEl = $el.querySelector('.ecom-item-group-init');
                        if (initEl) initEl.classList.remove('ecom-item-group-init');
                    });
                }

                function handleHash() {
                    const hash = window.location.hash;
                    if (hash) {
                        const dom = $el.querySelector(`[data-target="${hash}"]`);
                        if (dom) {
                            dom.click();
                            dom.dispatchEvent(new MouseEvent('mouseover', {
                                bubbles: true,
                                cancelable: true,
                                view: window
                            }));
                            const elementRect = dom.getBoundingClientRect();
                            const absoluteElementTop = elementRect.top + window.pageYOffset;
                            const middle = absoluteElementTop - (window.innerHeight / 2);
                            smoothScrollTo(middle);
                        }
                    }
                }

                requestAnimationFrame(() => {
                    setTimeout(handleHash, 100);
                });

                window.addEventListener("resize", () => handle(accordionTitles));
                window.addEventListener("hashchange", handleHash, false);
            };
        },

        settings() {
            return [
                {
                    group_title: this.$t("items"),
                    params: [
                        {
                            name: "items",
                            type: "group",
                            value: [],
                            options: {
                                add_text: this.$t("add_item"),
                                is_clear_all: false
                            },
                            params: [
                                {
                                    type: "textarea",
                                    label: this.$t("title"),
                                    name: "title",
                                    title_unique: true,
                                    options: {
                                        toolbar: false
                                    }
                                },
                                {
                                    type: "paragraph",
                                    content: "Tips: You can use Liquid code here to display dynamic content, such as metafields. Change the content type to 'Liquid code' below (Only works in live mode)."
                                },
                                {
                                    type: "text",
                                    label: this.$t("id_target"),
                                    name: "id_target",
                                },
                                // {
                                //     type: "picker",
                                //     label: this.$t('icon'),
                                //     name: "icon_title",
                                //     options: {
                                //         type: "icon",
                                //         multiple: false
                                //     },
                                //     css: {
                                //         isCss: false
                                //     }
                                // },
                                {
                                    type: "popup",
                                    name: "type",
                                    label: this.$t("choose_type"),
                                    value: "icon",
                                    options: {
                                        type: "dropdown",
                                        default: false,
                                        preview: "title",
                                        values: {
                                            icon: this.$t("icon"),
                                            image: this.$t("image")
                                        }
                                    }
                                },
                                {
                                    type: "picker",
                                    label: this.$t("choose_image"),
                                    name: "image",
                                    options: {
                                        responsive: false,
                                        type: "image",
                                        editAlt: false,
                                        visible: {
                                            keep_data: true,
                                            condition: (data) => {
                                                return data["type"] === "image";
                                            }
                                        }
                                    }
                                },
                                {
                                    type: "picker",
                                    label: this.$t("icon"),
                                    name: "icon_title",
                                    options: {
                                        type: "icon",
                                        multiple: false,
                                        visible: {
                                            keep_data: true,
                                            condition: (data) => {
                                                return data["type"] !== "image";
                                            }
                                        }
                                    }
                                },
                                {
                                    type: "popup",
                                    label: this.$t("span_class_uppercase_html_span_tag"),
                                    name: "tag",
                                    value: "div",
                                    options: {
                                        type: "dropdown",
                                        values: {
                                            h1: "H1",
                                            h2: "H2",
                                            h3: "H3",
                                            h4: "H4",
                                            h5: "H5",
                                            h6: "H6",
                                            div: "DIV",
                                            p: "P"
                                        }
                                    }
                                },
                                {
                                    type: "popup",
                                    label: "Content type",
                                    name: "content_type",
                                    value: "text",
                                    options: {
                                        type: "dropdown",
                                        default: false,
                                        values: {
                                            text: "Text",
                                            liquid: "Liquid code (use for metafields)",
                                        }
                                    }
                                },
                                {
                                    type: "choose",
                                    label: this.$t("content_alignment"),
                                    name: "content_alignment",
                                    options: {
                                        oneline: true,
                                        responsive: true,
                                        type: "align-x-full",
                                        values: ["flex-start", "center", "flex-end"],
                                        visible: {
                                            condition: (data, datas, values = this.data.settings) => {
                                                return values.newChange;
                                            }
                                        }
                                    }
                                }
                            ]
                        }
                    ]
                },
                {
                    group_title: this.$t("general"),
                    params: [
                        {
                            type: "toggle",
                            name: "disable_auto_close",
                            label: this.$t("disable_auto_close"),
                            value: false,
                            options: {
                                responsive: true,
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "toggle",
                            name: "scroll_on_mobile",
                            label: this.$t("scroll_up_to_the_tab_title_when_opening_tabs_on_mobile"),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "toggle",
                            name: "close_all",
                            label: this.$t("default_close"),
                            value: false,
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "toggle",
                            name: "disable_effect",
                            label: this.$t("disable_effect_animate_accordion"),
                            value: true,
                            options: {
                                values: {
                                    on: {
                                        label: this.$t("yes"),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t("no"),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "speed",
                            label: this.$t("speed_span_class_lowercase_ms_span"),
                            options: {
                                units: {
                                    "": {
                                        min: 0,
                                        max: 2000
                                    }
                                },
                                visible: (data) => {
                                    return !data["disable_effect"];
                                }
                            },
                            css: {
                                selector: " .ecom-effect-accodion",
                                properties: {
                                    transition: "height %value%ms ease, opacity %value%ms ease"
                                }
                            }
                        },
                        {
                            type: "picker",
                            label: this.$t("icon"),
                            name: "icon",
                            options: {
                                type: "icon",
                                multiple: false
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: "picker",
                            label: this.$t("icon_active"),
                            name: "iconActive",
                            options: {
                                type: "icon",
                                multiple: false
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            name: "iconPosition",
                            label: this.$t("icon_position"),
                            type: "choose",
                            value: "0",
                            activeQuickToolBar: true,
                            options: {
                                oneline: true,
                                type: "align-x",
                                values: ["0", "1"],
                                visible: (data) => data["icon"] || data["iconActive"]
                            }
                        }
                    ]
                }
            ];
        },

        style() {
            return [
                {
                    group_alias: "items",
                    options: {
                        group_name: "accordion_general",
                        group_title: this.$t("box_title"),
                        selector: " .ecom-accordion__title"
                    },
                    modify: {
                        params: [
                            {
                                position: 0,
                                fields: [
                                    {
                                        alias: "text-align",
                                        options: {
                                            label: this.$t("alignment")
                                        }
                                    },
                                    {
                                        name: "headingBoxShadow",
                                        label: this.$t("box_shadow"),
                                        type: "popup",
                                        options: {
                                            oneline: true,
                                            type: "box-shadow"
                                        }
                                    }
                                ]
                            },
                            {
                                position: 20,
                                liteMode: true,
                                fields: [
                                    {
                                        type: "line",
                                        liteMode: true
                                    },
                                    {
                                        alias: "spacing",
                                        options: {
                                            label: this.$t("spacing")
                                        }
                                    }
                                ]
                            }
                        ],
                        remove: [
                            {
                                index: 7,
                                length: 1
                            },
                            {
                                index: 10,
                                length: 1
                            }
                        ]
                    }
