    methods: {
        quickToolBar() {
            return ['items'];
        },
        /** Clicks on title bar outside title text (icons, image) — select + toggle panel. */
        onAccordionTitleBarClick(index, e) {
            if (this.exporting) return;
            if (e?.target?.closest?.(".ecom-accordion__title-text")) return;
            this.selectAccordionItem(index);
            this.toggleAccordionPanel(index);
        },
        /** Click on title text — select the item and toggle its panel. */
        onAccordionTitleTextClick(index) {
            if (this.exporting) return;
            this.panelToggleFromClick = true;
            this.selectAccordionItem(index);
            this.toggleAccordionPanel(index);
            this.$nextTick(() => {
                this.panelToggleFromClick = false;
            });
        },
        getAccordionPanelContext(index) {
            const root = this.$el;
            if (!root) return null;
            // Only use the items owned by this accordion. A descendant selector here also
            // collects accordions nested inside item bodies and makes the Vue item index point
            // at the wrong DOM node (for example: 7 settings items became 25 DOM items).
            const itemsContainer = root.querySelector(
                ":scope > .core__group--wrapper > .core__group--items"
            );
            if (!itemsContainer) return null;
            const items = itemsContainer.querySelectorAll(":scope > .ecom-accordion__item");
            const item = items[index];
            if (!item) return null;
            const title = item.querySelector(":scope > .ecom-accordion__title");
            if (!title) return null;
            const disable_effect = this.data.settings?.disable_effect ?? false;
            const innerWidth = window.innerWidth;
            const allowCloseActive =
                (this.data.settings?.disable_auto_close__mobile && innerWidth < 768) ||
                (this.data.settings?.disable_auto_close__tablet && innerWidth > 767 && innerWidth < 1025) ||
                (this.data.settings?.disable_auto_close && innerWidth > 1024);
            const deactivate = (el) => {
                el.classList.remove("ecom-item-active");
                // Must go with `ecom-item-active`: while both are present the stylesheet forces
                // `height: auto !important` on the body, which outranks any inline height.
                el.classList.remove("ecom-item-group-init");
                const t = el.querySelector(":scope > .ecom-accordion__title");
                if (t) t.classList.remove("ecom-item-active");
            };
            const closeItem = (el) => {
                const b = el.querySelector(":scope > .ecom-accordion__body");
                if (!b) {
                    deactivate(el);
                    return;
                }
                if (disable_effect) {
                    deactivate(el);
                    b.style.height = "0px";
                    return;
                }
                b.classList.add("ecom-effect-accodion");
                // Still active here, so `overflow: inherit` is in play — clip or the content
                // stays fully visible while the box collapses underneath it.
                b.style.overflow = "hidden";
                // Pin the current height as an explicit start value with the transition off,
                // BEFORE dropping the active classes. Those classes carry
                // `height: auto !important` and `overflow: inherit`, so removing them first
                // would snap the panel shut with nothing left to animate from.
                const oldTransition = b.style.transition;
                b.style.transition = "none";
                b.style.height = b.scrollHeight + "px";
                b.offsetHeight; // force reflow — commits the start value
                b.style.transition = oldTransition;
                deactivate(el);
                requestAnimationFrame(() => {
                    b.style.height = "0px";
                });
            };
            // Never close the item we are about to open: mid-transition that would reset its
            // height back to scrollHeight and fight the open below, swallowing the click.
            const closeOthers = () => items.forEach((el) => el !== item && closeItem(el));
            const openItem = (el) => {
                el.classList.add("ecom-item-active");
                const t = el.querySelector(":scope > .ecom-accordion__title");
                if (t) t.classList.add("ecom-item-active");
                el.classList.remove("ecom-item-group-init");
                // Nested accordions: ancestors hold a pixel height, so grow them or the
                // opening body gets clipped.
                let ancestor = el.parentElement?.closest?.(".ecom-accordion__body");
                while (ancestor) {
                    ancestor.style.height = "auto";
                    ancestor = ancestor.parentElement?.closest?.(".ecom-accordion__body");
                }
                const b = el.querySelector(":scope > .ecom-accordion__body");
                if (!b) return;
                if (disable_effect) {
                    b.style.overflow = "";
                    b.style.height = "auto";
                    return;
                }
                b.classList.add("ecom-effect-accodion");
                // The active item gets `overflow: inherit` from the stylesheet (so open panels
                // can spill dropdowns). During the growth that means nothing is clipped and the
                // content simply pops in at full size while the box catches up. Clip it for the
                // duration of the animation and hand overflow back to CSS once open.
                b.style.overflow = "hidden";
                // Measure the natural height with the transition off, then animate 0 -> target.
                // `height: auto` is not animatable, which is why the target must be in px.
                const oldTransition = b.style.transition;
                b.style.transition = "none";
                b.style.height = "auto";
                const targetHeight = b.scrollHeight;
                b.style.height = "0px";
                b.offsetHeight; // force reflow
                b.style.transition = oldTransition;
                const view = b.ownerDocument?.defaultView || window;
                const duration = parseFloat(view.getComputedStyle(b).transitionDuration) || 0;
                if (!duration) {
                    // No speed configured — same as live, nothing to animate.
                    b.style.overflow = "";
                    b.style.height = "auto";
                    return;
                }
                // Hand the height back to `auto` once open, otherwise editing the content
                // inside the panel would be clipped at the measured height.
                let fallback;
                const onEnd = (ev) => {
                    if (ev && (ev.target !== b || ev.propertyName !== "height")) return;
                    clearTimeout(fallback);
                    b.removeEventListener("transitionend", onEnd);
                    if (b.parentElement?.classList.contains("ecom-item-active")) {
                        b.style.height = "auto";
                        b.style.overflow = "";
                    }
                };
                b.addEventListener("transitionend", onEnd);
                fallback = setTimeout(onEnd, duration * 1000 + 50);
                requestAnimationFrame(() => {
                    b.style.height = targetHeight + "px";
                });
            };
            return {
                items,
                item,
                title,
                allowCloseActive,
                closeItem,
                closeOthers,
                openItem
            };
        },
        /** Open panel only (e.g. sidebar item select) — title uses toggleAccordionPanel. */
        activateAccordionPanel(index, force = false) {
            if (this.exporting) return;
            // "Default close" keeps everything shut on plain selection; `force` is for callers
            // that explicitly need the item open.
            if (!force && this.data.settings?.close_all) return;
            const ctx = this.getAccordionPanelContext(index);
            if (!ctx) return;
            const { item, title, allowCloseActive, closeOthers, openItem } = ctx;
            if (title.classList.contains("ecom-item-active") && item.classList.contains("ecom-item-active")) {
                return;
            }
            if (!allowCloseActive) {
                closeOthers();
            }
            openItem(item);
        },
        /** Single click on title — open or close panel (exported onclick behaviour). */
        toggleAccordionPanel(index) {
            if (this.exporting) return;
            const ctx = this.getAccordionPanelContext(index);
            if (!ctx) return;
            const { items, item, title, allowCloseActive, closeItem, closeOthers, openItem } = ctx;
            const isActive = title.classList.contains("ecom-item-active");

            if (isActive) {
                // closeItem drops the active classes itself, and only after it has pinned the
                // start height — removing them here first would kill the collapse animation.
                if (allowCloseActive) {
                    closeItem(item);
                } else {
                    items.forEach((el) => closeItem(el));
                }
                return;
            }

            if (!allowCloseActive) {
                closeOthers();
            }
            openItem(item);
        },
        selectAccordionItem(i) {
            if (this.exporting) return;
            this.$store.commit("builder/setEditingElement", this);
            this.$store.commit("builder/setEditingElementId", this.accordion.id);
            if (!("tabOpened" in this.data.settings.items)) {
                Object.defineProperty(this.data.settings.items, "tabOpened", {
                    enumerable: false,
                    writable: true
                });
            }
            this.data.settings.items.tabOpened = i;
        },
        content_alignment(item){
            let style = '';
            if(item?.content_alignment) {
                style += '--ec-align-ct: ' + item?.content_alignment + ';';
            }
            if(item?.content_alignment__tablet) {
                style += '--ec-align-ct-tb: ' + item?.content_alignment__tablet + ';';
            }
            if(item?.content_alignment__mobile) {
                style += '--ec-align-ct-mb: ' + item?.content_alignment__mobile + ';';
            }
            return style;
        },
    },
    mounted() {
        //this.stacks[this.data.id] = this;
        this.instanceStore.register(this.data.id, this)
    },
    beforeDestroy() {
        this.instanceStore.unregister(this.data.id, this);
    },
    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit("builder/setIsContentEditable", false);
                this.$store.commit("builder/setEditingElementId", "");
            }
            if (val) {
                this.$store.commit("builder/setEditingElementId", this.accordion.id);
            }
        },
        "data.settings.items.tabOpened": function (index) {
            if (index >= 0 && !this.panelToggleFromClick && !this.isContentEditable) {
                this.$nextTick(() => this.activateAccordionPanel(index));
            }
        }
    }
};
</script>
