<template>
    <div class="relative w-full h-4 mb-2.5 shadow-[inset_0_0_2px_1px_#939393] cursor-pointer rounded-2xl group/opacity">
        <div
            ref="vslider"
            class="color-slider color-slider-horizontal rounded-2xl"
            @mousedown="onDragStart"
        >
            <div
                ref="pointer"
                class="ecom-picker-slider-horizontal h-4 w-4 rounded-full absolute pointer-events-none top-1/2 -translate-y-1/2"
                :style="pointStyle"
            >
                <div
                    class="absolute bottom-full rounded -translate-y-1 left-1/2 -translate-x-1/2 bg-white shadow opacity-0 invisible group-hover/opacity:opacity-100 group-hover/opacity:visible transition px-1 py-0.5"
                    :class="{ '!opacity-100 !visible': isDragging }"
                >
                    {{ Math.round(value) }}
                </div>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import { getElSizePosition, getValInRange } from "./untility.ts";

export default {
    props: {
        value: {
            type: Number,
            default: 0,
        }
    },
    data() {
        return {
            elSizePostion: {},
            isDragging: false,
            vsliderWidth: 0,
            pointerWidth: 0,
        };
    },
    mounted() {
        this.vsliderWidth = this.$refs.vslider.offsetWidth;
        this.pointerWidth = this.$refs.pointer.offsetWidth;
    },
    computed: {
        pointStyle() {
            let cls = {};
            const value = getValInRange(this.value, 0, 100);
            if (this.vsliderWidth) {
                cls.left = "calc(" + ((this.vsliderWidth - this.pointerWidth) * value) / 100 + "px)";
            }
            return cls;
        }
    },
    methods: {
        resetOffset() {
            let $el = this.$refs.vslider;
            let { width, height, left, top } = getElSizePosition($el);
            this.elSizePostion = { width, height, left, top };
        },
        onDragStart(e) {
            this.isDragging = true;
            this.resetOffset();
            this.onDragging(e);
            this.bindGlobalEvent();
        },
        onDragging(e) {
            let { pageY, pageX } = e;
            let { height, width, top, left } = this.elSizePostion;
            left = pageX - left;
            let percent = (left / width) * 100;
            percent = percent < 0 ? 0 : percent > 100 ? 100 : parseFloat(percent.toFixed(4));
            this.$emit("change", percent);
        },
        onDragEnd() {
            this.isDragging = false;
            this.unbindGlobalEvent();
        },
        bindGlobalEvent() {
            window.addEventListener("mousemove", this.onDragging);
            window.addEventListener("mouseup", this.onDragEnd);
        },
        unbindGlobalEvent() {
            window.removeEventListener("mousemove", this.onDragging);
            window.removeEventListener("mouseup", this.onDragEnd);
        }
    }
};
</script>

