<i18n>
{
    "en": { "preset": "Preset", "default": "None" },
    "fr": { "preset": "Préréglage", "default": "Aucun" },
    "de": { "preset": "Voreinstellung", "default": "Keine" },
    "ja": { "preset": "プリセット", "default": "なし" },
    "zh": { "preset": "预设", "default": "无" },
    "ar": { "preset": "إعداد مسبق", "default": "لا شيء" }
}
</i18n>
<template>
    <!-- Bố cục bám đúng hàng của field `popup` trong Field.vue (label trái · pill giá trị ·
         nút icon phải) để tab Scrolling nhìn nhất quán với 5 field bên dưới.
         KHÔNG khai thẳng `type: 'popup'` được: Popup.vue chỉ nhận `data` của riêng key nó
         và Field.updateData cũng chỉ ghi lại đúng key đó, trong khi preset phải ghi vào 5
         key anh em (scolling_horizontal, scrolling_rotate, scrolling_opacity, ...). -->
    <div v-if="presets.length" class="flex items-center gap-2">
        <label class="text-xs leading-5 text-text-primary font-normal">{{ $t('preset') }}</label>

        <div class="ml-auto flex items-center gap-1.5">
            <div
                v-if="selectedTitle"
                class="bg-[#CDFEE1] text-[#0C5132] font-[550] h-5 flex items-center px-2 text-xs rounded-full max-w-16"
            >
                <span class="block truncate capitalize" :data-tooltip="selectedTitle">{{ selectedTitle }}</span>
            </div>

            <PopupField
                :field="popupField"
                :data="data"
                :title-popup="$t('preset')"
                @update:data="choose"
            />
        </div>
    </div>
</template>

<script lang="ts">
import { defineAsyncComponent } from 'vue';
import { loadAnimationPresets } from '@/constants/animation-presets';
import { i18n, getLocale } from '@/plugins/i18n';

/** Mục "bỏ chọn" trong dropdown — trùng sentinel mà Field.isValidValue() coi là rỗng. */
const NONE = '__delete__';

export default {
    name: 'Animation_presetField',
    components: {
        // Async: Popup.vue -> Fields.vue -> Field.vue -> (import.meta.glob) -> chính file này.
        // Import tĩnh tạo vòng tròn, Popup có thể resolve ra undefined lúc render.
        // Cùng lý do Field.vue dùng defineAsyncComponent cho AIDesc.
        PopupField: defineAsyncComponent(() => import('../popup/Popup.vue'))
    },
    props: {
        field: {
            type: Object,
            default() { return {}; }
        },
        /** id của preset đang chọn, lưu ở `data.advanced.scrolling_preset` */
        data: {
            type: String,
            default: ''
        },
        /** chính là object `data.advanced` đang sống của element */
        fieldValues: {
            type: Object,
            default() { return {}; }
        }
    },
    emits: ['update:data'],
    data() {
        return {
            presets: [],
            /**
             * Giá trị của những key mà preset ĐANG CHỌN đã ghi đè, chụp ngay trước lúc ghi.
             * Key vắng mặt = lúc đó key chưa tồn tại -> restore là xoá hẳn.
             *
             * Cố ý chụp theo từng lần apply chứ không chụp một lần ở created(): nếu chụp
             * một lần thì merchant chỉnh tay sau khi mở panel rồi mới chọn preset sẽ bị
             * restore ghi đè mất phần chỉnh tay đó.
             *
             * Rỗng khi mở lại panel / F5 mà data đã có sẵn preset: lúc đó không có cách
             * nào biết trạng thái trước khi preset được apply ở phiên trước, nên coi như
             * trục đó thuộc về preset và bỏ chọn là xoá trục đó đi.
             */
            baseline: {}
        };
    },
    computed: {
        selectedPreset() {
            return this.presets.find((preset: any) => preset?.id === this.data) ?? null;
        },
        selectedTitle(): string {
            return this.selectedPreset ? this.title(this.selectedPreset) : '';
        },
        /**
         * Field "giả" chỉ để mượn UI của Popup.vue (nút icon + danh sách teleport).
         *
         * `values` là OBJECT chứ không phải chuỗi 'entrance-animation', nên ô preview động
         * của ANIM-03 không bật ở đây (điều kiện của nó là `values === 'entrance-animation'`).
         * Đúng ý: preset scrolling là bộ số nội suy theo vị trí cuộn, không có @keyframes
         * nào để preview.
         */
        popupField() {
            const values: Record<string, string> = { [NONE]: this.$t('default') };
            this.presets.forEach((preset: any) => {
                values[preset.id] = this.title(preset);
            });
            return {
                type: 'popup',
                name: this.field?.name ?? 'scrolling_preset',
                options: {
                    type: 'dropdown',
                    icon_type: 'animation',
                    // Cờ để Popup.vue bật tooltip preview cho từng dòng preset. Tường minh
                    // thay vì để Popup đoán theo tên field.
                    previewScrollingPresets: true,
                    values
                }
            };
        }
    },
    watch: {
        // Không deep: chỉ fire khi đổi sang element khác (object khác), không fire khi
        // chính ta mutate. Field component được tái sử dụng giữa các element nên nếu
        // không reset thì baseline của element cũ sẽ rò sang element mới.
        fieldValues() {
            this.baseline = {};
        }
    },
    async created() {
        this.presets = await loadAnimationPresets('scrolling');
    },
    methods: {
        title(preset: any) {
            const locale = getLocale(i18n);
            return preset?.title?.[locale] ?? preset?.title?.en ?? preset?.id;
        },
        keysOf(preset: any) {
            return Object.keys(preset?.values ?? {});
        },
        choose(id: string) {
            // Chọn lại đúng preset đang dùng thì không làm gì: bỏ chọn đã có mục "None"
            // riêng trong danh sách, không cần hành vi toggle ngầm như bản nút trước đây.
            if (id === this.data) {
                return;
            }

            if (!id || id === NONE) {
                this.releaseSelected();
                this.$emit('update:data', '');
                // '' để Field.isValidValue() trả false -> xoá hẳn key khỏi data.advanced
                return;
            }

            const preset = this.presets.find((p: any) => p?.id === id);
            if (!preset) {
                return;
            }

            // Nhả key của preset đang chọn TRƯỚC, nếu không thì đổi giữa 2 preset sẽ để
            // lại trục của preset cũ và element chạy đồng thời 2 hiệu ứng.
            this.releaseSelected();

            // Chụp baseline SAU khi nhả và TRƯỚC khi ghi -> giữ được cả phần merchant
            // chỉnh tay trên trục này từ lúc mở panel tới giờ.
            this.baseline = {};
            this.keysOf(preset).forEach((key: string) => {
                if (key in this.fieldValues) {
                    this.baseline[key] = this.$helpers.copy(this.fieldValues[key]);
                }
            });

            // mergeDeep chứ KHÔNG Object.assign: data lồng 2 tầng, assign phẳng sẽ thay
            // nguyên object 'scrolling-animation-*' và xoá mất trigger_start/trigger_end
            // merchant đã chỉnh.
            this.$helpers.mergeDeep(this.fieldValues, this.$helpers.copy(preset.values));

            this.$emit('update:data', preset.id);
        },
        /** Trả những key của preset đang chọn về trạng thái trước khi nó ghi. */
        releaseSelected() {
            const preset = this.selectedPreset;
            if (!preset) {
                return;
            }
            this.keysOf(preset).forEach((key: string) => {
                if (key in this.baseline) {
                    this.fieldValues[key] = this.$helpers.copy(this.baseline[key]);
                } else {
                    // Xoá hẳn chứ không set {} — core.ts scrollingAnimation() dùng
                    // hasOwnProperty, key rỗng vẫn lọt vào attr JSON và sinh ra
                    // translateX(undefined) ở storefront.
                    delete this.fieldValues[key];
                }
            });
            this.baseline = {};
        }
    }
};
</script>
