import advanced from "@/components/Builder/Helpers/CssGroup/advanced";
import { convertCss } from "@/components/Builder/Helpers/Css";
import { loadVendors, capitalize } from "@/utils/helpers";
import { $t } from "@/plugins/i18n";
import { widthPxCalculate } from "@/plugins/vue-grid-layout/helpers/utils";
export default {
    inject: ["exporting", "instanceStore", "eventBus"],
    data() {
        return {
            oldData: {},
            timeout: {},
            active_child_elenent: false,
            isUpdatingFromResize: false,
            timeoutResize: null,
            timeoutRotate: null
        };
    },
    computed: {
        canMultipleLanguages() {
            return this.getPermission("translates", false);
        },
        translationMechanism() {
            const app_translation_permission = this.getPermission('app_translation', false);
            const translationMechanism = this.getPermission('translation_mechanism', 'shopify');
            if(!app_translation_permission) {
                return 'shopify';
            }
            if(app_translation_permission) {
                return translationMechanism;
            }
        },

        fieldSettings() {
            if(!this.$t) this.$t = $t;
            return this.formatFields(this?.currentLayout?.settings ? this.currentLayout.settings : this.settings);
        },
        fieldStyle() {
            return this.formatFields(this?.currentLayout?.style ? this.currentLayout.style : this.style);
        },
        styleSchemaKey() {
            return (this.fieldStyle || []).map((f) => f?.name || f?.selector || '').join('|');
        },
        fieldAdvanced() {
            return this.formatFields(advanced(this));
        },
        params() {
            return this.$store.getters["page/params"];
        },
        translationPrefix(): String {
            return this.params.page === "menu"
                ? "ecomposer.ECOM_REPLACE_SECTION_NAME."
                : "sections.ECOM_REPLACE_SECTION_NAME.";
        },
        currentLayout() {
            return this.$store.getters['page/layout'];
        },
        stacks() {
            return this.$store.getters['builder/stacks'];
        },
        editingElement() {
            return this.$store.getters["builder/editingElement"];
        },
        isFullScreen() {
            return this.$store.getters["builder/isFullScreen"];
        },
        getPermission() {
            return this.$store.getters["global/getPermission"];
        },
        screen() {
            return this.$store.getters["builder/screen"];
        },
        market() {
            return this.$store.getters["page/market"];
        },
        sectionId() {
            return this?.$parent?.section_id || this?.$parent?.$parent?.section_id || "";
        },
        section() {
            const sections = this.$store.getters["page/sections"];
            return sections.find((section) => section.id === this.sectionId);
        },
        gridLayoutStyle() {
            if (!this.data.inGrid) return "";
            const layouts = this.$parent?.data?.layouts || this.data?.layouts;
            const section = this.section;
            const sectionId = this.sectionId;
            const intsSection = this.instanceStore.get(sectionId);
            if (!layouts || !section || !intsSection) return "";

            // Hàm kiểm tra giá trị có thực sự được định nghĩa và có ý nghĩa không
            const hasValue = (value) => {
                // Nếu là undefined hoặc null
                if (value === undefined || value === null) return false;

                // Nếu là chuỗi rỗng
                if (typeof value === "string" && value.trim() === "") return false;

                // Chuyển đổi sang số và kiểm tra
                const num = parseFloat(String(value).replace(/[^\d.-]/g, ""));

                // Trả về false nếu NaN, nhưng true nếu là 0
                return !isNaN(num);
            };

            // Hàm chuyển đổi giá trị sang số
            const ensureNumber = (value) => {
                if (typeof value === "string") {
                    return parseFloat(value.replace(/[^\d.-]/g, "")) || 0;
                }
                return typeof value === "number" ? value : 0;
            };
            const idoc = window.EComposerBuilder.contentDocument;
            const blockId = this.$parent?.data?.name == "row" ? this.$parent.data.id : this.data.id;
            const screenWidth = idoc?.defaultView?.innerWidth || 1440;
            const activePreset = this.$store.getters['page/activePreset'];
            
            
            let widthSettings = activePreset?.theme_settings["max-width"] || 1200;
            if(this.params.page == "popup") {
                widthSettings = intsSection.$el?.offsetWidth || 1200;
            }

            let sectionWidth = section?.settings["content-width"] === "full" ? screenWidth : (parseFloat(section?.settings["max-width"]) || parseFloat(widthSettings));

            const containerWidths = {
                desktop: sectionWidth,
                tablet: 737,
                mobile: 338
            };
            // Breakpoints
            const breakpoints = {
                desktop: 1025,
                tablet: 1023,
                mobile: 767
            };

            // CSS Rules
            let cssRules = "";

            // Đầu tiên, luôn render CSS cho desktop
            if (layouts.desktop) {
                const layout = layouts.desktop;
                const containerWidth = containerWidths.desktop;
                // Đảm bảo các giá trị là số
                const x = ensureNumber(layout.left);
                const y = ensureNumber(layout.top);
                const w = ensureNumber(widthPxCalculate(layout.width, containerWidth));
                const h = ensureNumber(layout.height);
                const rotation = ensureNumber(layout.rotation || 0);

                // Kiểm tra xem element có ở center không (dựa vào left% và width/containerWidth)
                const elementCenterX = x + (w / containerWidth) * 100 / 2;
                const isCentered = layout.center === true || Math.abs(elementCenterX - 50) < 1; // tolerance 1%

                // Luôn dùng justify-self: start với margin-left: x%
                // → left edge luôn ở x% bất kể containerWidth thực tế của viewer
                // → không phụ thuộc vào containerWidth lúc builder, không cần tính margin-right%
                const justifySelf = isCentered ? "center" : "start";
                const alignSelf = "start";

                // Margin: chỉ dùng margin-left để anchor left edge
                let marginLeft, marginRight;
                if (isCentered) {
                    marginLeft = "auto";
                    marginRight = "auto";
                } else {
                    // justify-self: start → margin-left = x% (scale đúng theo bất kỳ containerWidth)
                    marginLeft = `${x}%`;
                    marginRight = "auto";
                }

                // Margin-top luôn tính bằng px
                const marginTop = `${y}px`;

                // Gộp margin thành một thuộc tính
                const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;
                // CSS cho desktop
                cssRules += `
                .${sectionId} .ecom-block.${blockId} {
                    justify-self: ${justifySelf};
                    align-self: ${alignSelf};
                    width: ${typeof layout.width === 'number' ? `${layout.width}px` : layout.width};
                    height: ${layouts.options.autoHeight ? "auto;" : `${h}px;`};
                    margin: ${margin};`;

                // Thêm rotation nếu cần
                if (rotation !== 0) {
                    cssRules += `
                    transform: rotate(${rotation}deg);
                    transform-origin: center center;`;
                }
                //add z-index if exists
                if (layout.zindex) {
                    cssRules += `
                    z-index: ${layout.zindex};`;
                }
                cssRules += `
                }`;
            }

            // Chỉ render CSS cho tablet và mobile nếu có giá trị thực sự
            ["tablet", "mobile"].forEach((device) => {
                if (!layouts[device]) return;

                const layout = layouts[device];

                // Kiểm tra xem layout có thuộc tính nào có giá trị không
                const hasLeft = hasValue(layout.left);
                const hasTop = hasValue(layout.top);
                const hasWidth = hasValue(layout.width);
                const hasHeight = hasValue(layout.height);
                const hasRotation = hasValue(layout.rotation);
                //has zindex
                const hasZIndex = hasValue(layout.zindex);

                // Nếu không có giá trị tùy chỉnh nào, không render CSS cho breakpoint này
                if (!hasLeft && !hasTop && !hasWidth && !hasHeight && !hasRotation && !hasZIndex) return;

                const minWidth = breakpoints[device];

                // Bắt đầu media query
                cssRules += `
                @media screen and (max-width: ${minWidth}px)`;

                if (device === "tablet") {
                    cssRules += ` and (min-width: ${breakpoints.mobile + 1}px)`;
                }

                cssRules += ` {
                    .${sectionId} .ecom-block.${blockId} {
                        position: relative;`;

                // Chỉ render các thuộc tính có giá trị
                if (hasWidth) {
                    cssRules += `
                        ${
                            layout.full_width
                                ? "width: 100%;"
                                : `width: ${typeof layout.width === 'number' ? `${layout.width}px` : layout.width};`
                        }`;
                }

                if (hasHeight) {
                    cssRules += `
                        height: ${layouts.options.autoHeight ? "auto;" : `${layout.height}px;`};`;
                }

                // Chỉ render justify-self nếu có left
                let justifySelf = 'start';
                if (hasLeft) {
                    const x = ensureNumber(layout.left);
                    const containerWidth = containerWidths[device];

                    // Nếu không có width tùy chỉnh, sử dụng width từ desktop hoặc fallback
                    let w = 0;
                    if (hasWidth) {
                        w = ensureNumber(widthPxCalculate(layout.width, containerWidth));
                    } else if (layouts.desktop && layouts.desktop.width) {
                        w = ensureNumber(widthPxCalculate(layouts.desktop.width, containerWidth));
                    }

                    // Kiểm tra center alignment nếu có width hợp lệ
                    // Luôn dùng justify-self: start (không dùng end) để margin-left:x% tự scale đúng
                    if (w > 0) {
                        const elementCenterX = x + (w / containerWidth) * 100 / 2;
                        const isCentered = layout.center === true || Math.abs(elementCenterX - 50) < 1;
                        if (isCentered) {
                            justifySelf = "center";
                        }
                        // else: luôn giữ justifySelf = 'start'
                    }

                    cssRules += `
                        justify-self: ${justifySelf};`;
                }
                //zindex
                if (hasZIndex) {
                    cssRules += `
                        z-index: ${ensureNumber(layout.zindex)};`;
                }

                // Chỉ thêm margin nếu có left hoặc top
                if (hasLeft || hasTop) {
                    const x = hasLeft ? ensureNumber(layout.left) : 0;
                    const y = hasTop ? ensureNumber(layout.top) : 0;

                    // Margin: luôn dùng margin-left: x% (không cần containerWidth)
                    // → left edge luôn ở đúng x% bất kể viewport của viewer
                    let marginLeft, marginRight;
                    if (justifySelf === "center") {
                        marginLeft = "auto";
                        marginRight = "auto";
                    } else {
                        // justify-self: start → margin-left = x%
                        marginLeft = `${x}%`;
                        marginRight = "auto";
                    }

                    const marginTop = hasTop ? `${y}px` : "0";
                    const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

                    cssRules += `
                        margin: ${margin};`;
                }

                // Thêm rotation nếu có và khác 0
                if (hasRotation) {
                    const rotation = ensureNumber(layout.rotation || 0);
                    if (rotation !== 0) {
                        cssRules += `
                        transform: rotate(${rotation}deg);
                        transform-origin: center center;`;
                    }
                }

                cssRules += `
                    }
                }`;
            });

            return cssRules;
        },
        isLayoutWithTranslation() {
            return !this.currentLayout || this.currentLayout?.translation;
        }
    },
    watch: {
        styleSchemaKey() {
            if (this.exporting !== false) return;
            clearTimeout(this.timeout["styleSchema"]);
            this.timeout["styleSchema"] = setTimeout(() => {
                this.convertCss("style", this.data.style);
            }, 10);
        },
        "data.style": {
            deep: true,
            handler(val) {
                if (
                    val &&
                    (Object.keys(val).length === 0 ||
                        (val.section && Object.keys(val.section).length === 0))
                )
                    return;
                clearTimeout(this.timeout["style"]);
                this.timeout["style"] = setTimeout(() => {
                    this.reactiveConvertCss("style", val);
                }, 10);
            }
        },
        "data.style.size_grid": {
            deep: true,
            handler(val) {
                if (!this.data.inGrid) return;

                const gridItem = this.findGridItem();
                if (!gridItem || !gridItem?.$el) return;
                if (val && !gridItem.isUpdatingFromResize) {
                    let screen = this.screen == "desktop" ? "" : "__" + this.screen,
                        width = val["width_grid" + screen],
                        height = parseInt(val["height_grid" + screen]);
                    gridItem.innerWidth = width;
                    if(height !== undefined) {
                        gridItem.innerHeight = height;
                    }
                    gridItem.createStyle();
                    gridItem.$el.classList.add("ecom-transition-width");
                    if (this.timeoutResize !== null) clearTimeout(this.timeoutResize);
                    this.timeoutResize = setTimeout(() => {
                        gridItem.$el.classList.remove("ecom-transition-width");
                        gridItem.$emit("resized", gridItem.i, height ? height : gridItem.innerHeight, width);
                    }, 100);

                    // Xử lý riêng cho rotate_grid
                    const rotateValue = val["rotate_grid" + screen] || 0;
                    if (rotateValue !== gridItem.innerRotation) {
                        gridItem.innerRotation = rotateValue;
                        if(this.timeoutRotate !== null) clearTimeout(this.timeoutRotate);
                        this.timeoutRotate = setTimeout(() => {
                            gridItem.$emit("rotated", gridItem.i, rotateValue ?? 0);
                        }, 100);
                    }
                }
            }
        },
        "data.settings": {
            deep: true,
            handler(val) {
                if (Object.keys(val).length === 0) return;
                let v = this.$helpers.copy(val);
                if (v?.items?.[0]?.blocks) {
                    delete v.items;
                }

                clearTimeout(this.timeout["settings"]);
                this.timeout["settings"] = setTimeout(() => {
                    this.reactiveConvertCss("settings", v);
                }, 10);
            }
        },
        "data.advanced": {
            deep: true,
            handler(val) {
                if (!val) return;

                let $el = null;

                if (this?.is == "column") {
                    $el =
                        this.$el instanceof HTMLElement
                            ? this.$el.querySelector(".core__column--wrapper")
                            : null;
                } else if (
                    (this?.deep == 1 && this?.is !== "tabs") ||
                    (this?.deep >= 2 && this?.is == "row")
                ) {
                    $el = this.$el instanceof HTMLElement ? this.$el : null;
                } else {
                    $el = this.$el.parentNode;
                }
                //Margin, padding
                let spacingName = "spacing" + (this.screen === "desktop" ? "" : "__" + this.screen);
                if (val.hasOwnProperty(spacingName) && $el) {
                    let spacing = Object.assign({}, val[spacingName]),
                        margin = spacing?.margin || "",
                        padding = spacing?.padding || "";

                    if (padding) {
                        const { top, bottom, left, right } = padding;
                        top ? $el.style.setProperty("padding-top", top, "important") : "";
                        bottom ? $el.style.setProperty("padding-bottom", bottom, "important") : "";
                        //bottom ? $el.style.paddingBottom = bottom : ''
                        left ? ($el.style.paddingLeft = left) : "";
                        right ? ($el.style.paddingRight = right) : "";
                    }
                    if (margin) {
                        const { top, bottom, left, right } = margin;
                        top ? ($el.style.marginTop = top) : "";
                        bottom ? ($el.style.marginBottom = bottom) : "";
                        left ? ($el.style.marginLeft = left) : "";
                        right ? ($el.style.marginRight = right) : "";
                    }
                }
                // Entrance animation
                if (this.data.undoInBuilder) {
                    delete this.data.undoInBuilder;
                }
                //Position

                if (val.hasOwnProperty("left") && $el) $el.style.left = val.left;
                if (val.hasOwnProperty("right") && $el) $el.style.right = val.right;
                if (val.hasOwnProperty("top") && $el) $el.style.top = val.top;
                if (val.hasOwnProperty("bottom") && $el) $el.style.bottom = val.bottom;

                clearTimeout(this.timeout["advanced"]);
                this.timeout["advanced"] = setTimeout(() => {
                    this.reactiveConvertCss("advanced", val);
                }, 10);

                clearTimeout(this.timeout["styleInline"]);
                this.timeout["styleInline"] = setTimeout(() => {
                    if (val.hasOwnProperty(spacingName) && $el) {
                        $el.style.padding = "";
                        $el.style.margin = "";
                    }

                    if (val.hasOwnProperty("left") && $el) $el.style.left = "";
                    if (val.hasOwnProperty("right") && $el) $el.style.right = "";
                    if (val.hasOwnProperty("top") && $el) $el.style.top = "";
                    if (val.hasOwnProperty("bottom") && $el) $el.style.bottom = "";
                }, 500);
            }
        }
    },

    beforeCreate() {
        ["settings", "style", "advanced"].forEach((sch) => {
            if (this.data?.[sch]?.constructor !== Object) {
                this.data[sch] = {};
            }
        });
    },

    mounted() {
        if (
            this.exporting &&
            (this?.data?.layouts ||
                (["tabs", "slider", "accordion"].includes(this.data.element) &&
                    this.$parent?.data?.layouts))
        ) {
            const target = this.data.group ? this.data.group : this.data;

            if (!target.css) {
                target.css = {};
            }
            if (!target.css.style) {
                target.css.style = {};
            }
            if (!target.css.style.style) {
                target.css.style.style = "";
            }

            target.css.style.style += this.gridLayoutStyle;
        }
        if (this.exporting !== false) {
            return;
        }
        let name = (this.data?.name ?? this.$options?.name).toLowerCase();
        this.$store.dispatch("page/addAllElements", name);
        if (this.$options.vendors) {
            loadVendors(this.$options.vendors, name);
        }

        if (this.data && this.css) {
            /*
            this.$store.commit('page/storeCssBase', {
                name: name,
                data: this.css
            });
            */
            const cssBases = this.instanceStore.get("cssBases") || {};
            cssBases[name] = this.css;
            this.instanceStore.register("cssBases", cssBases);
        }

        if (this.data.id == this.editingElement?.data?.id) {
            this.$store.commit("builder/setEditingElement", this);
        }

        this.$helpers.setDefaultSettings(this);
        if (this.is != "column" && (this.$parent.inGrid || this.$parent.$parent.inGrid)) {
            this.data.inGrid = true;
        } else {
            delete this.data.inGrid;
        }
        if (this.layouts && !this.data.layouts) this.data.layouts = this.layouts;
        ["settings", "style", "advanced"].forEach((sch) => {
            if (this.data[sch]) {
                let val = this.data[sch];

                if (sch == "settings") {
                    val = this.$helpers.copy(val);
                    if(val.section && Object.keys(val.section).length === 0) {
                        delete val.section;
                    }
                    if (val?.items?.[0]?.blocks) {
                        delete val.items;
                    }
                }
                if (
                    Object.keys(val).length === 0 ||
                    (val.section && Object.keys(val.section).length === 0)
                )
                    return;
                this.reactiveConvertCss(sch, val);
            }
        });

        if (this.$options.hasChild) {
            this.childElementHelper();
        }
        /*
        if (this.data.inGrid) {
            const gridItem = this.findGridItem();
            if (!gridItem || !gridItem?.$el) return;
            if (this.data.style.size_grid && !gridItem.isUpdatingFromResize) {
                let screen = this.screen == "desktop" ? "" : "__" + this.screen,
                    width = this.data.style.size_grid["width_grid" + screen],
                    height = parseInt(this.data.style.size_grid["height_grid" + screen]),
                    rotate = this.data.style.size_grid["rotate_grid" + screen] || 0;
                gridItem.innerWidth = width;
                if(height !== undefined) {
                    gridItem.innerHeight = height;
                }
                gridItem.innerRotation = rotate;
                gridItem.createStyle();
            }
        };
        */
    },

    methods: {
        findGridParent() {
            let parent = this.$parent;
            while (parent && parent.$options.name !== "Grid") {
                parent = parent.$parent;
            }
            return parent;
        },
        findGridItem() {
            let parent = this.$parent;
            while (parent && parent.$options.name !== "GridItem") {
                parent = parent.$parent;
            }
            return parent;
        },
        lang(str: String, key, options = null): String {
            if (!str) {
                return "";
            }
            const previewCurrent = this.$store.getters['page/previewCurrent'];
            if(previewCurrent) {
                return str;
            }
            let key_temp = key;

            if (str.length > 998 && !(this.isLayoutWithTranslation && this.translationMechanism === 'ecomposer')) {
                return str;
            }

            if (!this.exporting || this.exporting === "preview") {
                if (options && Object.keys(options).length) {
                    Object.keys(options).forEach((k) => {
                        str = str.replace(
                            new RegExp("{{\\s*?" + k + "\\s*?}}", "g"),
                            "{{ " + options[k] + "}}"
                        );
                    });
                }
                if (options && options.escape) {
                    return escape(str);
                }
                return str;
            }
            if (!this.canMultipleLanguages) {
                return str;
            }
            const element_id = this.data?.id?.split('-')?.pop();
            key =  key && typeof key === 'string' ? this.$helpers.str2key(key) +'_'+  element_id: this.$helpers.str2key(str)  +'_'+  element_id;
            key = key+'_html';
            let payload = {};
            let text = str;
            let payloadName = this.data?.title || this.data?.name ? capitalize(this.data?.name) : 'DefaultBlockType';

            if(this.data?.title) {
                payloadName = this.data?.title;
            } else if(this.data?.name) {
                payloadName = capitalize(this.data?.name);
            } else {
                payloadName = 'DefaultBlockType';
            }

            if(!this.isLayoutWithTranslation || this.translationMechanism === 'shopify') {
                payload = {
                    id: key,
                    text: text
                };
            } else if(this.translationMechanism === 'ecomposer') {
                text = str.replace(/{{/g, '((').replace(/}}/g, '))')
                payload = {
                    translation: true,
                    section_id: this.data?.section?.id || this.sectionId,
                    section_title: this.data?.section?.title || "Default Title",
                    block_id: this.data?.id,
                    block_type: payloadName,
                    key: key_temp && typeof key_temp === 'string' ? this.$helpers.str2key(key_temp) : this.$helpers.str2key(str),
                    text: text
                };
            }

            this.$store.commit('page/setLanguage', payload);

            if(this.isLayoutWithTranslation && this.translationMechanism === 'ecomposer' && payload?.section_id && payload?.block_id && payload?.key) {
                const path = `translation.${payload.section_id}.${payload.block_id}.${payload.key}`;
                const filters = [];
                if (options && typeof options === 'object') {
                    Object.keys(options).forEach((k) => {
                        if (k === 'escape') return;
                        filters.push(`replace: '((${k}))',${options[k]}`);
                    });
                }
                if (options && options.escape) {
                    filters.push('escape');
                }
                return `{{ ${path}${filters.length ? ' | ' + filters.join(' | ') : ''} }}`;
            } else if (str && options && Object.keys(options).length) {
                let values =   Object.keys(options).map(k=> `${k}:${options[k]}`);
                let vals  = values.join(',');
                if(options && options.escape)
                {
                    return `{{ '${this.translationPrefix}${key}' | t: ${vals} | escape }}`;
                }
                return `{{ '${this.translationPrefix}${key}' | t: ${vals} }}`;
            }
            return `{{ '${this.translationPrefix}${key}' | t }}`;
        },

        formatFields(fields) {
            let settings = typeof fields == "function" ? fields() : fields;
            return this.$helpers.formatFields(settings);
        },

        reactiveConvertCss(type, value) {
            if (
                this.data.id &&
                this.oldData[type] !== JSON.stringify(value) &&
                this.exporting === false
            ) {
                this.convertCss(type, value);
                this.oldData[type] = JSON.stringify(value);
            }
        },

        convertCss(type, value) {
            let id = this.$parent?.data?.group ? this.$parent.data.id : this.data.id,
                rootSelector = ".ecom-core" + (id ? "." + id : ""),
                fields =
                    type === "style"
                        ? this.fieldStyle
                        : type === "settings"
                        ? this.fieldSettings
                        : this.fieldAdvanced;
            if (!this.data.css) {
                this.data.css = {};
            }

            this.data.css[type] = convertCss(rootSelector, fields, value);
            if (!this.exporting) {
                (
                    this.createStyle ||
                    this.$parent?.createStyle ||
                    this.$parent?.$parent?.createStyle
                )?.();
            }
        },

        idoc() {
            return window.EComposerBuilder.contentDocument;
        },
        iwin() {
            return window.EComposerBuilder.contentWindow;
        },
        childElementHelper() {
            try {
                window.EComposerBuilder.contentWindow
                    .Function(
                        `
                    var _this = this,$el=this.$el;
                    $el.querySelectorAll && this.$el.querySelectorAll('.ecom-child-element').forEach(elm=>{
                        elm.addEventListener('click', function(e){
                            e.preventDefault()
                            $el.querySelectorAll('.ecom-child-element-active').forEach(el=>{
                                el.classList.remove('ecom-child-element-active');
                            })
                            elm.classList.add('ecom-child-element-active');
                            $el.dispatchEvent(new window.CustomEvent('setactive',{detail: elm.dataset.childName}));

                        });

                    });
                    $el.addEventListener('click', function(e){
                        if(!e.target.closest('.ecom-child-element'))
                        {
                            $el.dispatchEvent(new window.CustomEvent('setactive',{detail:  null}));
                            $el.querySelectorAll('.ecom-child-element-active').forEach(el=>{
                                el.classList.remove('ecom-child-element-active');
                            })
                        }
                    });

                    `
                    )
                    .call({
                        $el: this.$el,

                        id: this.data.id
                    });
            } catch (ex) {
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: this.$t(
                        "an_error_occurred_while_executing_the_javascript_code_of_element",
                        { name: this.$options.name }
                    ),
                    duration: 4000
                });
                console.error(
                    '[ECOMPOSER ERROR] process javascript of element "' +
                        this.$options.name +
                        '": ',
                    ex
                );
            }
        },
        setActiveElement(e) {
            this.active_child_elenent = e.detail;
        }
    }
};
