<template>
    <div
        class="ecom-picker relative"
        :class="classRoot"
    >
        <div v-if="optionFormated.type === 'icon' && !optionFormated.multiple" class="inline-flex rounded">
            <button
                type="button"
                class="relative flex items-center justify-center text-gray-500 w-8 h-8 bg-gray-100 rounded  "
                :data-tooltip="iconSize > maxSize ? $t('your_icon_is_too_large_the_icon_should_be_less_than')+' '+ maxSize+ ' kilobytes' : $t('click_to_change')"
                :class="[iconSize > maxSize ? 'ring-2 ring-red-500': '']"
                :disabled="options?.disabled"
                @click="changeShowPopup"
            >
                <EcomIcon v-if="value.length === 0" :source="icons.EditMajor" :size="'w-5'" class="flex items-center"></EcomIcon>
                <span
                    v-else
                    class="block w-4 h-4 svg-full"
                    v-html="value[0]?.thumbnail || value[0]?.value"
                />

            </button>
        </div>
        <template v-else-if="optionFormated.simple">
            <button
                type="button"
                class="relative w-full flex items-center min-w-30 border border-input rounded-lg text-left text-form-input  text-xs h-7-5 pr-7 pl-3 group"
                :class="[value.length ? 'pr-7' : 'pr-2', optionFormated.type === 'font' ? 'h-8' : '']"
                :disabled="options?.disabled"
                @click="changeShowPopup"
            >
                <template v-if="value.length">
                    <template v-if="optionFormated.type === 'font'">
                        <link rel="stylesheet" :href="fontURL(value[0])">
                        <span class="truncate" :style="{ fontFamily:value[0].name }">{{ value[0].name }}</span>
                    </template>
                    <template v-else>
                        <img
                            class="h-full rounded mr-2 py-2"
                            :src="value[0].thumbnail ?? '/images/placeholder.png'"
                        >
                        <span class="truncate" v-html="value[0].name" />
                    </template>
                </template>
                <span v-else class="truncate ">
                    {{ optionFormated.title }}
                </span>
                <EcomIcon :source="icons.selectInputIcon" :size="'w-5'" :color="'text-icon-primary group-hover:text-text-primary transition-all'" class="absolute top-1/2 right-2 transform -translate-y-1/2 w-2 h-3 flex items-center justify-center"></EcomIcon>
            </button>
        </template>
        <template v-else>
            <div
                v-if="!value.length"
                :class="[
                    'flex flex-col gap-1 items-center justify-center bg-white hover:border-primary-700 py-6 rounded-lg w-full h-full',
                    optionFormated.noBorder ? '' : 'border border-dashed border-[#8A8A8A]'
                ]">
                <s-button
                    @click="changeShowPopup"
                    variant="secondary"
                    :disabled="options?.disabled"
                >
                    {{ options.button_text }}
                </s-button>
                <span v-if="options.type === 'image' && !hiddenFreeImages" class="text-text-secondary text-xs hover:underline cursor-pointer" @click="(e) => {changeShowPopup('free')}">
                    {{ $t('explore_free_images') }}
                </span>
                <span v-if="options.type === 'image'" class="text-xs hover:underline cursor-pointer bg-gradient-to-r from-purple-500 via-pink-500 to-orange-400 bg-clip-text text-transparent" @click="changeShowPopup('ai')">
                    {{ $t('generate_ai_image') }}
                </span>
            </div>
            <div v-else>

                <PickerPreview
                    :value-prop="value"
                    :options="optionsPreview"
                    @update:temp="updateTemp"
                    @update:image="updateImage"
                    @selectItem="selectItem"
                    @update:modify="updateModify"
                    @deleteItem="deleteItem"
                />
                <div
                    class="flex flex-col relative py-3 border-white divide-y border-t-2  "
                    v-if="options?.multiple || ['block', 'menu', 'page'].includes(options?.type)"
                >
                    <div class="flex gap-3 h-7">
                        <s-button variant="secondary" @click="changeShowPopup" icon="edit">
                            {{textButton.change}}
                        </s-button>
                        <s-button :disabled="options?.disabled" variant="tertiary" icon="delete" tone="critical" @click="deleteItem">
                            {{textButton.delete}}
                        </s-button>
                    </div>
                </div>
            </div>
        </template>
        <PickerComponent
            ref="picker"
            :value="selected ?? value"
            :is-change="isChange"
            :options="optionFormated"
            :values="options.values"
            @isSelected="isSelected"
            @update:tabs="updateTabs"
            @toggleItem="onToggleItem"
            @qtb-closed="$emit('qtb-closed')"
        />
    </div>
</template>

<script>
    import { mapGetters } from 'vuex';
    import PickerComponent from './PickerPopup.vue';
    import PickerPreview from './PickerPreview.vue';
    import { EditMajor, ecRefresh, selectInputIcon } from "@/assets/icons";
    import {countStringBytes} from '@/utils/string';
    export default {
        name: 'Picker',
        components: {
            PickerComponent,
            PickerPreview
        },
        props: {
            valueProp: {
                type: Array,
                default(){
                    return [];
                }
            },
            options: {
                type: Object,
                default(){
                    return {};
                }
            },
            isQuickToolBar: {
                type: Boolean,
                default: false
            },
        },
        emits: ['update:data', 'update:tabs', 'qtb-closed'],
        data(){
            return{
                maxSize: 10,
                search: '',
                selected: null,
                selectedTemp: null,
                selectedIndex: -1,
                value: '',
                valueTemp: '',
                isWatch: true,
                isEmit: false,
                icons: {EditMajor, ecRefresh, selectInputIcon},
                isopenPopup: false,
                tabs: [
                    {
                        title: this.$t('uploaded'),
                        active: true
                    },
                    {
                        title: this.$t('free_images'),
                        active: false
                    }
                ],
                aiMode: 'generate'
            };
        },
        computed: {
            iconSize(){
                if(this.optionFormated.type === 'icon')
                {
                    if(!this.value || !this.value.length || !this.value[0].value) return 0;

                    return  countStringBytes(this.value[0].value)
                }
                return 0;
            },
            hiddenFreeImages() {
                return this.options?.type === 'image' && this.options?.excludedTabs?.includes('free');
            },
            optionFormated(){
              return {
                title: this.options?.title ?? '',
                useSearch: this.options?.search ?? true,
                multiple: this.selected ? false : (this.options?.multiple ?? false),
                useDelete: this.options?.delete ?? false,
                drag: this.options?.drag ?? true,
                layout: ['language', 'country'].includes(this.options?.type) ? 'list' : (this.options?.layout ?? 'grid'),
                type: this.options?.type ?? 'menu',
                editAlt: this.options?.editAlt ?? false,
                modify: this.options?.modify ?? [],
                tabs: this.options?.tabs ?? {},
                simple: this.options?.simple ?? false,
                responsive: this.options?.responsive ?? false,
                textSelect: this.selected ? this.$t('update') : this.$t('select'),
                position: this.options?.position ?? 'absolute',
                editPro: this.options.editPro ?? true,
                noBorder: this.options.noBorder ?? false,
                aiMode: this.aiMode || 'generate',
                isQuickToolBar: !!(this.isQuickToolBar && this.options?.type === 'icon'),
              };
            },
            optionsPreview(){
                let { useDelete , layout, type, drag, modify, editAlt, editPro} = this.optionFormated;
                let multiple = this.options?.multiple ?? false;
                return {
                    useDelete, layout, type, drag, multiple, modify, editAlt, editPro,
                    excludedTabs: this.options.excludedTabs ?? []
                };
            },
            kValue() {
                let k = 'value';
                if (this.screen !== 'desktop') {
                    k += '__' + this.screen;
                }
                return k;
            },
            isChange(){
                if(this.selected) {
                    return JSON.stringify(this.selectedTemp) != JSON.stringify(this.selected);
                }
                return JSON.stringify(this.valueTemp) != JSON.stringify(this.value);
            },
            textButton(){
              return {
                change: this.optionFormated.multiple || this.selected ? this.$t('add_more') : this.$t('change'),
                delete: this.optionFormated.multiple || this.selected ? this.$t('remove_all') : this.$t('delete'),
                setting: this.$t('settings')
              };
            },
            isFullImage(){
                return (this.options.type == 'image' && !this.options.multiple);
            },
            classRoot(){
                let css = '';
                if(!this.optionFormated.simple && (this.optionFormated.type !== 'icon' || this.optionFormated.multiple)) {
                    css += 'w-full max-w-xs bg-[#FDFDFD] mt-2 rounded-lg';
                }
                else {
                    css += 'flex';
                }

                return css;
            },
            iconUploaded() {
                return this.value.length && !('cate' in this.value[0]);
            },
            iconSystem() {
                return this.value.length && 'cate' in this.value[0];
            },
            ...mapGetters('builder', ['screen']),

        },
        watch: {
            value: {
                deep: true,
                immediate: true,
                handler: function(val){
                if(this.isEmit){
                    this.isWatch = false;
                    if(!this.options.emitOnConfirm) {
                        this.$emit('update:data', this.cloneData(val));
                        if(this.optionFormated?.tabs?.cur) {
                            this.updateTabs(this.optionFormated?.tabs?.cur)
                        }
                    }
                }
                this.isEmit = true;
                }
            } ,
            valueProp: {
                deep: true,
                immediate: true,
                handler: function(val){
                if(this.isWatch){
                    this.isEmit = false;
                    this.value = this.cloneData(val),
                    this.valueTemp = this.cloneData(val);
                }
                this.isWatch = true;

                }
            },
            selected: {
                deep: true,
                handler: function(val) {
                    let item = val?.[0];
                    if(item) {
                        this.value[this.selectedIndex] = item;
                    }
                }
            }
        },
        methods: {
            changeTab(key){
                for (let index = 0; index < this.tabs.length; index++) {
                    this.tabs[index].active = false;
                }
                this.tabs[key].active = true;
            },
            cloneData(data){
                if(!data || typeof data !== 'object') return data;
                return JSON.parse(JSON.stringify(data));
            },
            onToggleItem(data) {
                console.log('Picker.vue - onToggleItem received:', data);
                if (data && data.item && data.tab === 'ai-edit') {
                    // Xử lý đặc biệt cho AI Edit
                    this.selectItem({item: data.item, i: -1, tab: data.tab});
                } else {
                    // Trường hợp click chọn ảnh bình thường từ tab AI hoặc nơi nào đó dùng toggleItem
                    // Nếu data là item object (có id), sử dụng trực tiếp
                    const item = data.item || data;
                    this.selectItem({item, i: -1});
                }
            },
            selectItem({item, i, tab = null}) {
                if(this.options?.disabled) return true;
                this.selectedIndex = i;
                this.selected = [item];
                this.selectedTemp = this.cloneData([item]);
                if(tab === 'ai-edit') {
                    this.aiMode = 'edit';
                    this.changeShowPopup('ai');
                } else if(tab) {
                    this.aiMode = 'generate';
                    this.changeShowPopup(tab);
                } else {
                    this.aiMode = 'generate';
                    this.changeShowPopup();
                }
            },
            updateSearch(val){
                this.search = val;
            },
            fontURL({name, value:src}){
                return this.$helpers.getLinkFont(name, src);
            },
            updateModify() {
                this.valueTemp = this.cloneData(this.value);
            },
            isSelected(val){
                this.selected = null;
                this.selectedTemp = null;
                this.selectedIndex = -1;
                if(!val && this.isChange){
                    this.value = this.cloneData(this.valueTemp);
                }else{
                    this.updateTemp();
                    if(this.options.emitOnConfirm) {
                        this.isWatch = false;
                        this.$emit('update:data', this.cloneData(this.value));
                    }
                }
            },
            updateTemp(){
              this.valueTemp = this.cloneData(this.value);
            },
            selectIconUpload() {
                this.updateTabs('uploaded');
                // this.$refs.picker.show = true;
                this.changeShowPopup();
            },
            selectIconSystem() {
                this.updateTabs('system');
                // this.$refs.picker.show = true;
                this.changeShowPopup();
            },
            updateTabs(val){
                this.optionFormated.tabs.cur = val;
                this.$emit('update:tabs', val);
            },
            updateImage(val){
              this.value = this.cloneData(val);
              this.valueTemp = this.cloneData(val);
            },
            deleteItem(){
                this.value = [];
                this.valueTemp = [];
            },
            changeShowPopup(tab = null){
                if(typeof tab === 'string') {
                    this.optionFormated.tabs.cur = tab;
                } else if(this.options.type === 'image') {
                    this.optionFormated.tabs.cur = 'uploaded';
                }
                if(this.options.type === 'image'){
                    // this.isopenPopup = !this.isopenPopup;

                    this.$refs.picker.show = true;
                }else{
                    this.$refs.picker.show = true;
                }
            },
            closeShowPopup() {
                if (this.$refs.picker) {
                    this.$refs.picker.show = false;
                }
            }
        }
    };
</script>
