<template>
    <PickerFrame
    :show="show"
    :header="headerFrame"
    :position="position"
    @close="show = false"
  >
    <template #content>
      <Loading
          v-if="loading"
          type="spin"
          :size="8"
          class="text-gray-800  transition mt-10"
      />
      <div v-else class="h-full overflow-y-auto">
        <div class="p-2 flex gap-2 flex-col">
            <label class="text-sm text-gray-600  font-semibold">
                {{ $t('describe_your_request') }}
            </label>
            <textarea
                v-model="content"
                :placeholder="$t('clearly_describe_your_content_ideas_or_requests_our_ai_will_generate_the_suggested_result')"
                class="p-3 block w-full transition    rounded shadow-sm text-form-input border border-gray-250 placeholder-form-input h-9 sm:text-sm   focus:ring-primary-400  focus:border-gray-100 min-h-40"
            />
            <Button
                :text="$t('generate')"
                type="primary"
                @click="generate"
            />
            <template v-if="result">
                <hr class="h-0 border-b border-gray-100 " /> 
                <label class="text-sm font-semibold text-gray-600 ">
                    {{ $t('the_result') }}
                </label>
                <textarea
                    v-model="result"
                    class="p-3 block w-full transition    rounded shadow-sm text-form-input border border-gray-250 placeholder-form-input h-9 sm:text-sm   focus:ring-primary-400  focus:border-gray-100 min-h-48"
                />
            </template>
            <p v-if=" count >=0 " class="text-sm">
                <span class="text-gray-500">{{ $t('used') }} </span>
                <span class="text-gray-700 "> {{ $t('count_50_requests_day', {count: count}) }}</span>
            </p>
            <div class="w-full p-3 pl-5 mb-3 text-xs font-light text-gray-600 border-l-4 border-yellow-500 shadow-sm bg-yellow-50">
                <ul class="list-none flex flex-col gap-1 pl-1">
                    <li>
                        {{ $t('our_ai_uses_chat_gpt_to_generate_content') }}
                    </li>
                    <li>
                        {{ $t('this_tool_can_be_used_in_e_composer_text_element') }}
                    </li>
                    <li>
                        {{ $t('we_don_t_store_or_share_any_data') }}
                    </li>
                </ul>
            </div>
            
        </div>
        
      </div>
  
    </template>
    <template #footer>
            <PickerFooter
              :is-change="!!result"
              @clickCancel="show = false"
              @clickSelect="eSelect"
              :textSelect="$t('insert')"
            />
          </template>
  </PickerFrame>
  </template>
  
  <script lang="ts">
    import PickerFrame from '../picker/PickerFrame.vue';
    import PickerFooter from '../picker/PickerFooter.vue';
    // import { faCheck,faXmark} from '@fortawesome/pro-light-svg-icons';
    import { clickOutside } from '../../directives';
  
    export default {
        name: 'InsertLink',
        directives: {
            clickOutside
        },
        components: {
            PickerFrame,
            PickerFooter
  
        },
        props: {
            data: {
                type: Object,
                default(){
                    return  {};
                }
            },
            type: {
                type: String,
                default: 'editor'
            },
            position: {
                type: String,
                default: 'absolute'
            }
        },
        emits: ['close_popup','update:content'],
        data(){
            return {
                show: false,
                value: {},
                attributes: '',
                styleGroupTyles: {},
                // icons: { faCheck,faXmark},
                loading: false,
                content:'',
                result: '',
                count: -1
            };
        },
        computed: {
          headerFrame(){
              return {
                  title: this.$t('ai_content_generator'),
                  search: {
                      show: false,
                      value: ''
                  }
              };
          }, 
        },
        watch: {
             
        },
        methods: {
            generate(){
                this.loading = true;
                this.$worker.fetch(window.route('builder.generator'), {
                    prompt: this.content
                }, 'POST').then((response) => {
                    this.loading = false;
                     if(response.data.status === 'success')
                     {
                        this.result = response.data.data.trim();
                        this.count = response.data.count;
                        // this.$emit('update:content', this.result);
                        // this.show = false;
                     }
                     else if(response.data.status === 'error')
                     {
                        throw new Error(response.data.message);
                        
                     }
                     else 
                        throw new Error(this.$t('invalid_response'));
                })
                .catch((error) => {
                    this.loading = false;
                    // this.$store.dispatch('global/flash',{
                    //     type: 'error',
                    //     message:error.message,
                    //     open: true,
                    //     data: error
                    // });
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: error.message,
                        data: error,
                        duration: 4000
                    });
                });
            },
            eSelect(){
                this.$emit('update:content', this.result);
               this.eClose();
            },
            eClose(){
                this.show = false;
                this.content = '';
                this.result = '';
            }
          
          
  
        }
  
    };
  </script>
  