<template>
    <Liquid :data="liquidBefore" />
    <Liquid v-if="conditionLiquid?.start && exporting" :data="conditionLiquid.start" />
    <OldStructure  v-if="(columns.length === 0 && !section.blocks) && !useFlexbox"/>
    <Structure v-else-if="(columns.length === 0 && !section.blocks)" />
    <template v-else-if="isFlexContainerSection">
        <template v-if="(exporting === false || exporting === 'preview')  && ['product', 'cart'].indexOf(shopify_type) > -1">
            <form
                class="ecom-click ecom-row"
                method="post"
                :action="shopify_type == 'product' ? '/cart/add' : '/cart/update'"
                :class="shopify_type == 'product' ? 'ecom-product-form ecom-product-form--single' : 'ecom-cart-form'"
                enctype="multipart/form-data"
                @submit.prevent="false"
            >
               <FlexContainer
                    :data="data"
                    :deep="1"
                    :index="index"
                    :section_id="data.id"
                    ref="row"
                />
            </form>
        </template>
        <template v-else>
            <FlexContainer
                :data="data"
                :deep="1"
                :index="index"
                :section_id="data.id"
                ref="row"
            />
        </template>
    </template>

    <template v-else-if="section.blocks && !section?.columns?.length">
        <template v-if="(exporting === false || exporting === 'preview')  && ['product', 'cart'].indexOf(shopify_type) > -1">
            <form
                class="ecom-click ecom-row"
                method="post"
                :action="shopify_type == 'product' ? '/cart/add' : '/cart/update'"
                :class="shopify_type == 'product' ? 'ecom-product-form ecom-product-form--single' : 'ecom-cart-form'"
                enctype="multipart/form-data"
                @submit.prevent="false"
            >
                <Grid :deep="1"
                    :data="data"
                    :index="index"
                    :section_id="data.id" ref="row"/>
            </form>
        </template>
        <template v-else>
            <Grid :deep="1"
                    :data="data"
                    :index="index"
                    :section_id="data.id" ref="row"/>
        </template>
    </template>
    <template v-else-if="(exporting === false || exporting === 'preview')  && ['product', 'cart'].indexOf(shopify_type) > -1">
        <form
            class="ecom-click ecom-row"

            method="post"
            :action="shopify_type == 'product' ? '/cart/add' : '/cart/update'"
            :class="shopify_type == 'product' ? 'ecom-product-form ecom-product-form--single' : 'ecom-cart-form'"
            enctype="multipart/form-data"
            @submit.prevent="false"
        >
            <Row
                ref="row"
                :deep="1"
                :data="data"
                :index="index"
                :section_id="data.id"
            />
        </form>
    </template>
    <Row
        v-else
        ref="row"
        :deep="1"
        :data="data"
        :index="index"
        :section_id="data.id"
    />
    {{ exporting === true && conditionLiquid?.start ? conditionLiquid?.end : ''}}
    <Liquid :data="liquidAfter" />
</template>

<script lang="ts">
    import { Core, ProcessLiquid } from '@/mixins';
    import Grid from './Grid/Grid.vue';
    import Structure from './Structure.vue';
    import FlexContainer from '@/components/Builder/Components/Core/Elements/Base/FlexContainer.vue';
import OldStructure from './OldStructure.vue';
    export default {
        name: 'Section',
        components: { Structure, Grid, FlexContainer, OldStructure },
        mixins: [Core, ProcessLiquid],
        inject: ['exporting'],
        props: {
            data: {
                type: Object,
                default () {
                    return {
                        columns: [],
                        settings: {
                        }
                    };
                }
            },
            'index': {
                type: Number,
                default: 0
            }
        },
        data() {
            return {
                is: 'rootSection',
                name: "Section",
                timmer: 0,
                isProductBox: false,

            };
        },
        mounted() {
            // this.iwin().interact(this.$refs.item, { context: this.idoc() }).draggable({
            //     onmove: onMove,
            //     inertia: { enabled: true },
            //     restrict: {
            //     drag: 'parent',
            //     endOnly: true,
            //     elementRect: { top: 0, left: 0, bottom: 1, right: 1 },
            //     },
            //     autoScroll: true,
            // })

            // function onMove(event) {
            //     console.log('onMove', event);
            //     const target = event.target
            //     const x = (parseFloat(target.getAttribute('data-x')) || 0) + event.dx
            //     const y = (parseFloat(target.getAttribute('data-y')) || 0) + event.dy

            //     if ('webkitTransform' in target.style || 'transform' in target.style) {
            //     target.style.webkitTransform = target.style.transform = 'translate(' + x + 'px, ' + y + 'px)'
            //     } else {
            //     target.style.left = x + 'px'
            //     target.style.top = y + 'px'
            //     }

            //     target.setAttribute('data-x', x)
            //     target.setAttribute('data-y', y)
            // }
        },
        computed: {
            conditionLiquid() {
                if(!this.condition) return {}
                let liquids = {
                    start: `
                            {% assign condition = true %}
                            ${this.condition ? this.condition : ''}
                            {% if condition %}
                        `,
                    end: `
                            {% endif %}
                        `
                };
                return liquids;
            },
            useFlexbox(){
                return this.$store.getters['global/user']?.use_flexbox || false
            },
            deep () {
                return 1;
            },
            sections () {
                return this.$parent.sections;
            },
            visibleSections () {
                return this.$parent.visibleSections;
            },
            stack () {
                return this.sections;
            },
            section () {
                return this.data;
            },
            columns () {
                return this.section.columns ? this.section.columns : [];
            },
            isFirst () {
                return this.index == 0;
            },
            isLast () {
                return this.sections && this.index == this.sections.length - 1;
            },
            isFlexContainerSection () {
                // Kiểm tra nếu section có blocks và block đầu tiên là FlexContainer
                return this.section.name === 'flexContainer';
            },


            editingElement(){
                return this.$store.getters['builder/editingElement'];
            },
            sectionCss(){
                return this.instanceStore.get('sectionCss');
                //return this.$store.getters['page/sectionCss']
            },

            // Override shopify_type from mixin to ensure reactivity
            shopify_type() {
                if (this.exporting === false) {
                    // Builder mode: use stored value directly
                    return this.data.shopify_type || 'section';
                }

                // Export/preview: re-scan to handle sections imported/copied between pages
                const hasShopifyElement = this.checkForShopifyElements();

                if (!hasShopifyElement) {
                    if (this.data.hasElementRequestLiquid) {
                        this.data.hasElementRequestLiquid = false;
                    }
                    return 'section';
                }

                const detectedType = this.detectShopifyType();
                if (detectedType) {
                    return detectedType;
                }

                // Fall back to stored shopify_type if detection fails
                if (this.data.shopify_type &&
                    this.allowTypes.indexOf(this.data.shopify_type) > -1) {
                    return this.data.shopify_type;
                }

                return 'section';
            },

            params(){
                return this.$store.getters['page/params']
            },
            // current(){
            //     return this.$store.getters['page/section'](this.data?.id)
            // }
        },

        /*
        watch: {
            current: {
                handler: function (val) {
                    if(this.exporting )
                    {
                        return false;
                    }

                    let activeElement =  window.document.activeElement;

                    if(activeElement?.type === 'INPUT' &&  activeElement?.type !== 'number')
                    {
                        return false;
                    }
                    else if( activeElement?.nodeName === 'INPUT'
                            && activeElement?.type !== 'range'
                            &&  activeElement?.type !== 'number'
                            && activeElement?.type !== 'checkbox'
                            && activeElement?.name != 'inputColor'
                    )
                    {
                        return false;
                    }
                    else if(activeElement?.type === 'IFRAME' && activeElement.id !== 'EComposerBuilder')
                    {
                        return false;
                    }

                    // console.log('Start watch current section',val);
                    clearTimeout(this.timmer);
                    this.timmer = setTimeout(() => {
                        this.renderSectionCss();
                    }, 100);
                },
                deep: true

            },



        },
        */
        beforeUnmount () {
            if (this.exporting !== false) {
                return;
            }
            let linkcss = window.EComposerBuilder.contentWindow['section-' + this.data.id];
            if (
                linkcss &&
                this.sections.filter((s) => {
                    return s.id == this.data.id;
                }).length === 0

            ) {
                try{
                    window.EComposerBuilder.contentDocument.head.removeChild(linkcss);
                }catch(e){
                    console.warn(e.message);
                }
            }
            const sectionCss = this.sectionCss;
            if (sectionCss && sectionCss[this.data.id]) {
                delete sectionCss[this.data.id];
                this.instanceStore.register('sectionCss', sectionCss);
            }
        },

        methods: {

            dropOut () {
                let realIndex= this.stack.findIndex((s) => s.id == this.data.id);
                if (realIndex > -1) {
                    this.$store.dispatch('history/addStack', {
                        type: 'section',
                        index: realIndex,
                        data:  this.data,
                        section_id: this.data.id,
                        action: 'delete'
                    });
                    return this.stack.splice(realIndex, 1)[0];
                }
                else
                {
                    return this.stack.splice(this.index, 1)[0];
                }
            },
            dropIn (current, pos) {
                if (this.is == 'section') {
                    this.stack.splice(this.index + pos, 0, current.dropOut());
                }
            },

            paste (clipboard) {
                if (this.$refs.row) {
                    this.$refs.row.paste(clipboard);
                } else {
                    this.section.columns = [{
                        width: 100,
                        blocks: []
                    }];
                    setTimeout(() => {
                        this.$refs.row.paste(clipboard);
                    }, 100);
                }
            },

            settings () {
                return this.$refs?.row?.settings ?? this.$refs?.flexContainer?.settings ?? [];
            },

            style () {
                return this.$refs?.row?.style ?? this.$refs?.flexContainer?.style ?? [];
            },

            refreshCols () {

                if (this.columns.length === 0) {
                    this.sections.splice(this.index, 1);
                    // this.$sections.splice(this.index, 1);
                }
                let w = 0;
                this.columns.forEach((c) => {
                    w += Number(c.width);
                });
                w = (w - 100) / this.columns.length;
                this.columns.forEach((c) => {
                    c.width -= Number(w);
                    /*if (this.stacks[c.id]?.column) {
                        this.stacks[c.id].column.refresh = this.$helpers.randid();
                    }*/
                });

                //this.section.refresh = this.$helpers.randid();

            },

            renderSectionCss() {
                if (this.data.id) {
                    let id = 'section-' + this.data.id;
                    let css  =  this.sectionCss?.[this.data?.id];
                    this.$helpers.renderCss(id, css);
                    let globalUsed = this.$helpers.getGlobalInCss( css);
                    this.$store.dispatch('page/setGlobalUsed', {id, payload: globalUsed});
                }
            },

            // Helper method to check if section contains Shopify elements
            // Refactored to match allNodes getter recursive pattern
            checkForShopifyElements() {
                const checkData = (data: any): boolean => {
                    if (!data) return false;

                    const checkBlocks = (blocks: any[]): boolean => {
                        if (!blocks || !Array.isArray(blocks)) return false;

                        for (let i = 0; i < blocks.length; i++) {
                            const elm = blocks[i];
                            if (!elm) continue;

                            // Skip hidden elements
                            if (elm.visibility === false) continue;

                            if (elm.hasRequestLiquid || elm.hasElementRequestLiquid) return true;

                            if (elm.name) {
                                const name = elm.name.toLowerCase();
                                if (['shopifyproductbox', 'shopifyarticlebox'].includes(name)) continue;

                                // Skip nonPageTypeElements — keeps in sync with detectShopifyType
                                if (['productmetafield', 'collectionproduct', 'productrecently'].includes(name)) continue;

                                if (name.startsWith('product') ||
                                    name.includes('cart') ||
                                    name.includes('collection') ||
                                    name.includes('blog') ||
                                    name.includes('article')) {
                                    return true;
                                }
                            }

                            if (elm.shopify_type && elm.shopify_type !== 'section') return true;

                            if (elm.row && checkData(elm.row)) return true;
                            if (elm.group?.settings && checkData(elm.group.settings)) return true;
                            if (elm.blocks && Array.isArray(elm.blocks) && checkBlocks(elm.blocks)) return true;
                        }

                        return false;
                    };

                    if (data.columns && Array.isArray(data.columns)) {
                        for (const col of data.columns) {
                            if (col.blocks && checkBlocks(col.blocks)) return true;
                        }
                    }
                    if (data.items && Array.isArray(data.items)) {
                        for (const item of data.items) {
                            if (item.blocks && checkBlocks(item.blocks)) return true;
                        }
                    }
                    if (data.blocks && checkBlocks(data.blocks)) return true;

                    return false;
                };

                return checkData(this.section);
            },

            // Helper to detect shopify_type from element names
            // Refactored to match allNodes getter recursive pattern
            detectShopifyType() {
                // Elements that start with 'product' or include page-type keywords
                // but are NOT page-type indicators (can be placed on any page)
                const nonPageTypeElements = [
                    'productmetafield',
                    'collectionproduct',  // product listing in collection — not a collection page indicator
                    'productrecently',    // Recently Viewed — works on any page
                ];

                const detectFromData = (data: any): string | null => {
                    if (!data) return null;

                    const detectFromBlocks = (blocks: any[]): string | null => {
                        if (!blocks || !Array.isArray(blocks)) return null;

                        for (let i = 0; i < blocks.length; i++) {
                            const elm = blocks[i];
                            if (!elm) continue;

                            // Skip hidden elements
                            if (elm.visibility === false) continue;

                            // Explicit shopify_type takes priority
                            if (elm.shopify_type && elm.shopify_type !== 'section') return elm.shopify_type;

                            if (elm.name) {
                                const name = elm.name.toLowerCase();

                                if (name.startsWith('cart')) return 'cart';

                                if (name.startsWith('product')) {
                                    if (nonPageTypeElements.includes(name)) continue;
                                    return 'product';
                                }

                                if (name.includes('collection') && !nonPageTypeElements.includes(name)) return 'collection';
                                // Check 'blog' BEFORE 'article' — 'blogArticles' contains 'article', order matters
                                if (name.includes('blog')) return 'blog';
                                if (name.includes('article')) return 'article';
                            }

                            if (elm.row) {
                                const t = detectFromData(elm.row);
                                if (t) return t;
                            }
                            if (elm.group?.settings) {
                                const t = detectFromData(elm.group.settings);
                                if (t) return t;
                            }
                            if (elm.blocks && Array.isArray(elm.blocks)) {
                                const t = detectFromBlocks(elm.blocks);
                                if (t) return t;
                            }
                        }

                        return null;
                    };

                    if (data.columns && Array.isArray(data.columns)) {
                        for (const col of data.columns) {
                            if (col.blocks) {
                                const t = detectFromBlocks(col.blocks);
                                if (t) return t;
                            }
                        }
                    }
                    if (data.items && Array.isArray(data.items)) {
                        for (const item of data.items) {
                            if (item.blocks) {
                                const t = detectFromBlocks(item.blocks);
                                if (t) return t;
                            }
                        }
                    }
                    if (data.blocks) {
                        const t = detectFromBlocks(data.blocks);
                        if (t) return t;
                    }

                    return null;
                };

                return detectFromData(this.section);
            }

        },
    };


</script>
