<template>
    <div
        class="mt-0.5 ecom-field--group relative"
        :class="id"
    >
        <div v-if="!isQuickToolBar" class="relative ecom-group-items flex flex-col gap-2">
            <div
                v-for="(value, index) in values"
                :key="value"
                class="bg-white ecom-group-item item flex flex-col items-center justify-center"
            >
                <div
                    class="relative flex items-center text-gray-500 transition header-group group h-8 border border-[#E3E3E3] w-full hover:bg-coolGray-50 hover:bg-gray-100 "
                    :class="opended(index) && hasChildren(value?.type) ? 'border-b-0 rounded-t-[8px]' : 'rounded-[8px]'"
                >
                    <div
                        class="flex items-center w-full pl-9 text-xs truncate transition cursor-pointer select-none h-8 px-2"
                        @click="toggleOpen(index, value?.type)"
                    >
                        <p class="truncate leading-5 group-hover:max-w-[130px]" :class="opended(index) ? 'max-w-[130px]' : 'group-hover:max-w-[130px]'">
                            <span
                                class="transition-all capitalize duration-75 text-text-primary"
                                v-html="title(value, index)"
                            />
                        </p>
                    </div>
                    <button
                        type="button"
                        class="absolute flex items-center ml-1 rounded left-0 bg-gray-100   "
                        :class="opended(index) ? 'hover:bg-form-active-hover' : hasChildren(value?.type) ? 'hover:bg-transparent' : 'cursor-default'"
                        @click="toggleOpen(index, value?.type)"
                    >
                        <EcomIcon :source="icons.ChevronRightMinor" :size="'w-5'" :class="[opended(index) ? 'rotate-90' : 'rotate-0', !hasChildren(value?.type) ? 'opacity-30' : '']" class="flex items-center justify-center w-6 h-6"></EcomIcon>
                    </button>
                    <div v-if="values[index]?.control !== false" class="absolute flex pl-2" :class="dir">
                        <button
                            type="button"
                            class="text-icon-primary hover:text-primary-700 opacity-0 flex items-center rounded justify-center py-1.5 focus:outline-none focus:ring-0 transition"
                            :class="[
                                !isDraggingStarted ? 'group-hover:opacity-100' : '',
                                acceptAddIndex(index) ? '' : 'hidden' ,
                                ,{
                                    'opacity-100 hover:bg-form-active-hover':opended(index)
                                }
                            ]"
                            :title="$t('clone')"
                            @click="duplicateValue(index)"
                        >
                            <EcomIcon :source="icons.DuplicateMinor" :size="'w-5'" class="flex justify-center items-center"></EcomIcon>
                        </button>
                        <button
                            v-if="isClearAll && canDelete(values[index])"
                            type="button"
                            class="text-icon-primary hover:text-danger-600  flex opacity-0  items-center rounded justify-center py-1.5 focus:outline-none focus:ring-0"
                            :class="{
                                'opacity-100 hover:bg-form-active-hover':opended(index),
                                'group-hover:opacity-100': !isDraggingStarted
                            }"
                            :title="$t('delete')"
                            @click="deleteItem(index)"
                        >
                            <EcomIcon :source="icons.DeleteMinor" :size="'w-5'" class="flex justify-center items-center"></EcomIcon>
                        </button>
                        <button
                            type="button"
                            class="ecom-mouse-down cursor-grab text-icon-primary hover:text-primary-700  relative flex items-center p-1.5 pl-0 transition rounded opacity-0   "
                            :class="{
                                'opacity-100 hover:bg-form-active-hover':opended(index),
                                'group-hover:opacity-100': !isDraggingStarted
                            }"
                            @mousedown="onMouseDown"
                            >
                            <EcomIcon :source="icons.DragHandleMinor" :size="'w-5'" class="flex justify-center items-center"></EcomIcon>
                        </button>
                    </div>
                </div>
                <Fields
                    v-if="opended(index) && hasChildren(value?.type)"
                    class="open-drag w-full pt-3 px-1 border border-[#E3E3E3] rounded-b-[8px] pb-3 "
                    :deep="1"
                    :ispop="true"
                    :data="!nullCustomType ? values[index].settings : values[index]"
                    :fields="!nullCustomType ? paramByType(value.type) : params"
                    :aipath="(aipath ? `${aipath}.` : '') + `${field.name}[${index}]`"
                />
            </div>
        </div>
        <div class="mt-2">
            <div class="relative">
                <div>
                    <ecom-button
                        ref="addNewItem"
                        type="button"
                        class="!p-0 !h-auto font-normal text-[#005BD3] hover:text-gray-800 hover:bg-transparent transition-all"
                        :class="{'opacity-50 pointer-events-none' : !acceptAdd('')}"
                        @click="addNewItem(null, $event)"
                        plain
                        :icon="icons.CirclePlusMajor"
                        :size="'w-5'"
                        :disabled="disabledAdd"
                    >
                        <!-- <EcomIcon :source="" :size="'w-5'" class="mr-1.5 flex justify-center items-center text-gray-500 "></EcomIcon> -->
                        <span class="text-xs" v-html="acceptAdd('') ? btnAddText : $t('limited')" />
                        <span v-if="nullCustomType && acceptAdd('')" class="ml-1 text-xs leading-5">
                            <template v-if="textLimit('normal')">({{ textLimit('normal') }})</template>
                        </span>
                    </ecom-button>
                </div>
                <div v-if="field.name === 'typo'" class="flex justify-center mt-2 -mx-2 gap-2">
                    <s-button
                        @click="showPopup"
                        variant="secondary"
                        tone="critical"
                        data-confirm="reset-typo"
                    >
                        {{ $t('reset_all_typo') }}
                    </s-button>
                    <s-button
                        @click="showPopup"
                        variant="secondary"
                        tone="critical"
                        data-confirm="reset-font-family"
                    >
                        {{ $t('reset_all_font_family') }}
                    </s-button>
                    <teleport to="body">
                        <Popup v-if="show_confirm" closeClass="" wrpclass="items-center my-5 bg-gray-100  rounded-lg" :width="620" :borderTop="true"
                            height="auto" bodyclass="w-full overflow-y-auto" @close="show_confirm = false">
                            <!-- <template #topbar>
                                <EcomText :as="'h3'" class="flex items-center px-4">Revisions (Auto saved)</EcomText>
                            </template> -->
                            <template #body>
                                <div class="bg-white border-b border-[#E4E5E7]  ">
                                    <EcomText :as="'h3'" class="flex items-center px-4 py-4 text-xl font-semibold">{{ type_popup === 'reset-typo' ? $t('notice_confirm_typo') : $t('notice_confirm_font') }}</EcomText>
                                </div>
                                <div  class="bg-white overflow-hidden sm:rounded-md w-full h-auto overflow-y-auto block relative min-h-[200px]">
                                    <div>
                                        <div class="inline-block overflow-hidden text-left align-bottom transition-all transform bg-white   rounded-lg w-full">
                                            <div class="text-center py-14 px-4 border-b border-[#E4E5E7]  w-full">
                                                <div class="max-w-lg mx-auto px-6">
                                                    <!-- <EcomText :as="'h3'" :alignment="'center'"> {{ type_popup === 'reset-typo' ? $t('title_reset_all_typo') : $t('title_reset_all_font_family') }} </EcomText> -->
                                                    <EcomText :alignment="'center'" :size="'small'">
                                                        {{ type_popup === 'reset-typo' ? $t('reset_typo_content') : $t('reset_font_content') }}
                                                    </EcomText>
                                                </div>
                                            </div>

                                            <div class="p-4 flex justify-end gap-3">
                                                <ecom-button type="button" @click="show_confirm = false" outline class="px-4 border-gray-250 text-sm">
                                                    {{ $t('no') }}
                                                </ecom-button>
                                                <ecom-button type="button" @click="resetTypo" primary class="px-4 text-sm">
                                                    {{ type_popup === 'reset-typo' ? $t('yes_reset_typo') : $t('yes_reset_font') }}
                                                </ecom-button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </template>
                        </Popup>
                    </teleport>
                </div>
                <ul
                    v-if="!nullCustomType && openMenu"
                    class="absolute max-w-4xl min-w-full overflow-y-auto mb-2 text-left transform -translate-x-1/2 bg-white   shadow-lg rounded transition ring-1 ring-black ring-opacity-10 top-full left-1/2 z-20   "
                    ref="popover-add"
                    :style="posPopover"
                >
                    <li
                        v-for="(item, type, index) in customTypes"
                        :key="type"
                        class="px-3 py-2 text-sm text-gray-700 truncate transition cursor-pointer hover:text-gray-700 hover:bg-gray-100   "
                        :class="{ 'border-b border-gray-200 ' : index < Object.keys(customTypes).length - 1,
                                'opacity-50 pointer-events-none' : !acceptAdd(type)}"
                        @click="addNewItem(type)"
                    >
                        <EcomText :as="'span'" class="text-xs font-450 text-text-primary">{{ item.name }}</EcomText>
                        <span
                            v-if="textLimit(type)"
                            class="ml-2 h-4 w-4 text-center rounded-xl bg-gray-200 float-right mt-0.5 text-xs text-gray-600"
                            :data-tooltip="textLimit(type) > 0 ? $t('max_adding') : $t('limited')"
                            data-tooltip-location="bottom"
                            v-html="textLimit(type)"
                        />
                    </li>
                </ul>
            </div>
        </div>
    </div>
</template>

<script lang="ts">

    import { dragMixin } from '../../mixins';
    import { removeCssInData, removeEmptyKeyObj } from '@/utils/helpers';
    import { ChevronRightMinor, DuplicateMinor, DeleteMinor, DragHandleMinor, CirclePlusMajor } from "@/assets/icons";
    import { eventBus } from '@/utils/eventBus';

    export default {
        name: 'GroupField',
        mixins: [ dragMixin ],
        props: {
            // eslint-disable-next-line vue/require-default-prop
            data: Array,
            field: {
                type: Object,
                default(){
                    return {};
                }
            },
            aipath: {
                type: String,
                default: ''
            },
            isQuickToolBar: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:data'],
        data(){
            return {
                show_confirm: false,
                type_popup: '',
                tabOpened: -1,
                values: [],
                isWatch: true,
                isEmit: false,
                drag: {
                    axis: 'y'
                },
                posPopover: {},
                openMenu: false,
                id: this.$helpers.randid(),
                icons: {
                    ChevronRightMinor, DuplicateMinor, DeleteMinor, DragHandleMinor, CirclePlusMajor
                }
            };
        },
        computed: {
            disabledAdd(){
                if(this.field?.options?.limit){
                    return this.data?.length >= (this.field?.options?.limit ?? 0);
                }
                return false;
            },
            dir(){
                return window.document.querySelector('html').getAttribute('dir') === 'rtl' ? 'left-2': 'right-px';
            },
            isClearAll(){
                if(this.field?.options?.is_clear_all ?? true){
                    return true;
                }else{
                    return this.values.length > 1;
                }
            },
            btnAddText(){
                return this.field?.options?.add_text ?? this.$t('add_item');
            },
            params(){
                return this.field?.params ?? [];
            },
            max(){
                return this.field?.options?.max;
            },
            customTypes(){
                let types = {};
                this.params.forEach( param => {
                    if( 'settings' in param && 'type' in param ) {
                        types[param['type']] = {
                            name: param['name'],
                            max: param['max'],
                            cantDelete: param['cantDelete']
                        };
                    }
                });
                return types;
            },
            nullCustomType(){
                return !Object.keys(this.customTypes).length;
            },
            count_block(){
                if(this.nullCustomType) {
                    return { normal: this.values.length };
                }
                else {
                    let rs = {};
                    for(let k in this.customTypes) {
                        rs[k] = this.values.filter(x => x.type === k).length;
                    }
                    return rs;
                }
            },
            aiFields() {
                return this.$store.getters['ai/fields'];
            }
        },
        watch: {
            data: {
                immediate: true,
                deep: true,
                handler: function(val){
                    if(this.isWatch){
                        this.isEmit = false;
                        this.values =  val ? val : [];
                    }
                    this.isWatch = true;

                }
            },
            values: {
                immediate: true,
                deep: true,
                handler: function(val){
                    if(this.isEmit){
                        this.isWatch = false;
                        this.$emit('update:data', val);
                    }
                    this.isEmit = true;
                }
            }
        },
        methods: {
            setGroupBodyZIndex(zIndex) {
                const body = this.$el?.closest?.(".ecom-fields__group-body");
                if (body) {
                    body.style.zIndex = zIndex;
                }
            },
            removeKeyType(obj, type) {
                if (Array.isArray(obj)) {
                    // if typeof obj == 'array' loop array
                    obj.forEach((item, index) => {
                        if (typeof item === 'object') {
                            // if typeof obj == 'object' callBack removeKeyType
                            this.removeKeyType(item,type);
                        }
                    });
                } else if (typeof obj === 'object') {
                    // typeof obj == 'object' loop object
                    for (const key in obj) {
                        if (key.includes(type)) {
                            // if obj include type -> remove key
                            delete obj[key];
                        } else if (typeof obj[key] === 'object') {
                            // if typeof obj == 'object' or 'array' callBack removeKeyType
                            this.removeKeyType(obj[key],type);
                        }
                    }
                }
            },
            resetTypo() {
                let data = JSON.parse(JSON.stringify(this.$store.getters['page/dataExport']));
                removeCssInData(data?.sections);
                data = removeEmptyKeyObj(data);
                let newSections = data?.sections;
                if(!newSections) {
                    this.show_confirm = false;
                    return
                };
                if(this.type_popup === 'reset-typo') {
                    this.removeKeyType(newSections, 'Typography');
                }
                else {
                    this.removeKeyType(newSections, 'font-family');
                }
                this.$store.dispatch('page/setSections', { data: [] });
                this.$store.dispatch('page/setSections', { data: newSections });
                this.show_confirm = false;
            },
            showPopup(e) {
                this.show_confirm = true;
                this.type_popup = e.target.dataset.confirm;
            },
            setid(index) {
                if (this.values[index].id === undefined) {
                    this.values[index].id = this.$helpers.randid();
                }
            },
            opended(index){
                return this.data?.tabOpened === index;
            },
            /**
             * ? Check if groups has no children params, which will hidden
             */
            hasChildren(type) {
                return (
                    this.nullCustomType ?
                    Object.keys(this.params ?? {}).length > 0 :
                    this.params.filter(p => p.type === type)[0]?.settings?.length
                );
            },
            classBtnHeader(index){
                if(this.opended(index)) {
                    return 'text-white hover:bg-primary';
                }
                else {
                    return 'text-gray-700 hover:bg-gray-50   ';
                }
            },
            limitBlock(type){
                if(this.nullCustomType) {
                    if(this.max !== undefined) {
                        return this.max - this.count_block['normal'];
                    }
                }
                else {
                    if(this.customTypes[type]?.max !== undefined) {
                        return this.customTypes[type].max - this.count_block[type];
                    }
                }
                return undefined;
            },
            acceptAdd(type) {
                return type !== undefined &&
                        (this.limitBlock(type) === undefined ||
                        this.limitBlock(type) > 0);
            },
            acceptAddIndex(index) {
                let value = this.values[index],
                    type = this.isCustomType(value) ? value['type'] : 'normal';

                return this.acceptAdd(type);
            },
            textLimit(type) {
                let limit = this.limitBlock(type);
                if(limit !== undefined) {
                    return `${limit}`;
                    //return `(${limit > 0 ? ('max ' + limit) : 'limited'})`;
                }
                return undefined;
            },
            isCustomType(value) {
                if (this.nullCustomType) {
                    return 'type' in value && 'settings' in value;
                }
                return 'type' in value;
            },
            paramByType(type){
                return this.params.filter(p => p.type === type)[0]?.settings ?? [];
            },
            title(value, index) {
                if(this.isCustomType(value) && value.hasElementRequestLiquid === false){
                    return this.customTypes[value.type]?.name ?? `${this.field?.options?.prefix_item ?? 'Item'} #` + (index + 1);
                } else {
                    if(value?.title) {
                        if(value.title.length <= 30) {
                            return value.title;
                        } else {
                            return value.title.slice(0, 30) + '...'
                        }

                    }
                    if(value?.label) {
                        if(value.label.length <= 30) {
                            return value.label;
                        } else {
                            return value.label.slice(0, 30) + '...'
                        }

                    }
                    if(value?.name) {
                        if(value.name.length <= 30) {
                            return value.name;
                        } else {
                            return value.name.slice(0, 30) + '...'
                        }

                    }
                    let selectedForTitle = `${this.field?.options?.prefix_item ?? 'Item'} #${index + 1}`;
                    if(this?.field?.title_unique === false) {
                        return selectedForTitle;
                    }
                    if (this?.field?.title_unique && value[this?.field?.title_unique]?.length > 0) {
                        selectedForTitle = value[this?.field?.title_unique];
                    }
                    else if (this?.field?.params[0].title_unique && value[this?.field?.params[0].name]?.length > 0) {
                       return selectedForTitle = value[this?.field?.params[0].name];
                    }
                    else if (!this?.field?.title_unique && value && typeof value === 'object') {
                        Object.keys(value).forEach(field => {
                            if (selectedForTitle === `Item #${index + 1}` && typeof value[field] === 'string' && value[field].length > 0 && !value[field].includes('ecom-')) {
                                selectedForTitle = this.$t(value[field]);
                            }
                        });
                    }
                    return selectedForTitle;
                }
            },

            toggleOpen(index, type){
                if(this.hasChildren(type)) {
                    this.data.tabOpened = this.opended(index) ? -1 : index;
                }
            },

            addNewItem(type, e){
                if (!this.nullCustomType && e) {

                    let btnAdd = e.target.closest('button'),
                        btnRect = btnAdd.getBoundingClientRect(),
                        btnTop = btnRect.top - btnRect.height / 2,
                        winHeight = window.innerHeight - 70,
                        dir = btnTop < winHeight / 2 ? 'bottom':'top',
                        maxHeight = this.$helpers.intBetween(
                            dir === 'top' ?
                            btnTop - 70 - btnRect.height / 2:
                            winHeight - btnTop - btnRect.height / 2,
                        0 , 300);

                    if (dir === 'top') {
                        this.posPopover.top = 'auto';
                        this.posPopover.bottom = '100%';
                    } else {
                        this.posPopover.bottom = 'auto';
                        this.posPopover.top = 'calc(100% + 10px)';
                    }

                    this.posPopover.maxHeight = maxHeight + 'px';
                    this.openMenu = true;
                    this.setGroupBodyZIndex(9);
                    document.addEventListener('click', this.doCloseMenu);

                }

                let newValue;

                if (this.acceptAdd(type)) {
                    if(!this.nullCustomType) {
                        if(type && typeof type === 'string'){
                            let typee = type;
                            let settings = this.field.params.find(function({type}) {if(type == typee) return type}) || {};
                            let cantDelete = settings.cantDelete || false;
                            settings = settings.values ? Object.assign({}, settings.values) : {};
                            newValue = {
                                type: type,
                                settings: settings
                            };
                            cantDelete ? newValue.cantDelete = cantDelete : '';
                            // newValue = this.values
                            //     .filter(value => value.type === type)
                            //     .slice(-1)[0] ??  { type, settings: {} };
                        }
                    } else {
                        newValue = {};
                        // newValue = this.values.slice(-1)[0] ?? {};
                    }
                }

                if (newValue !== undefined){
                    let clone = this.$helpers.copy(newValue);
                    delete clone.id;
                    this.values.splice(this.values.length, 0, clone);
                    if(this.data) {
                        this.data.tabOpened = this.values.length-1;
                    }
                }

                if (type !== null) {
                    this.openMenu = false;
                    this.setGroupBodyZIndex("");
                }

            },

            doCloseMenu(e) {
                if (
                    e === undefined ||
                    !e.target.closest('.'+this.id)
                ) {
                    this.openMenu = false;
                    this.setGroupBodyZIndex("");
                    document.removeEventListener('click', this.doCloseMenu);
                }
            },

            getAIFieldData() {
                const id = this.$store.getters['builder/editingElement']?.data?.id;
                if (id) {
                    const aiFields = this.aiFields;
                    if (aiFields && Object.keys(aiFields).length) {
                        if (id in aiFields) {
                            return {
                                editingId: id,
                                fields: aiFields[id]
                            }
                        }
                    }
                }
                return null;
            },

            duplicateValue(index) {
                if(this.acceptAddIndex(index)) {
                    let clone = this.$helpers.copy(this.values[index]);

                    // Hàm đệ quy để thêm id cho tất cả blocks
                    const addIdToBlocks = (obj: any) => {
                        if (!obj || typeof obj !== 'object') {
                            return;
                        }

                        // Nếu là array
                        if (Array.isArray(obj)) {
                            obj.forEach(item => {
                                // Nếu item là object, thêm id cho nó
                                if (item && typeof item === 'object' && !Array.isArray(item)) {
                                    item.id = this.$helpers.randid();
                                }
                                // Đệ quy tiếp
                                addIdToBlocks(item);
                            });
                            return;
                        }

                        // Nếu là object, duyệt qua tất cả các key
                        Object.keys(obj).forEach(key => {
                            // Nếu key là 'blocks' và value là array
                            if (key === 'blocks' && Array.isArray(obj[key])) {
                                obj[key].forEach(block => {
                                    if (block && typeof block === 'object') {
                                        block.id = this.$helpers.randid();
                                    }
                                    addIdToBlocks(block);
                                });
                            } else if (typeof obj[key] === 'object' && obj[key] !== null) {
                                // Đệ quy vào các object/array khác
                                addIdToBlocks(obj[key]);
                            }
                        });
                    };

                    // Thêm id cho tất cả blocks trong clone
                    addIdToBlocks(clone);

                    // Xóa id gốc của clone (nếu có)
                    delete clone.id;

                    this.values.splice(index, 0, clone);
                    this.data.tabOpened = index + 1;

                    const aiData = this.getAIFieldData();
                    if (aiData) {
                        const {editingId, fields} = aiData;
                        const resFields: typeof fields = {};
                        let count = 0;

                        Object.keys(fields).forEach(path => {
                            const pathArr = path.split('.');
                            if (!pathArr.length) {
                                return;
                            }
                            const key = pathArr.shift();
                            if (!key || !key.startsWith(`${this.field.name}[`)) {
                                return;
                            }
                            const arrayMatch = key.match(/\[(\d+)\]/);
                            if (!arrayMatch || arrayMatch.length < 1) {
                                return
                            }
                            const arrayIndex = parseInt(arrayMatch[1], 10);
                            if (arrayIndex <= index) {
                                return;
                            }
                            pathArr.unshift(`${this.field.name}[${arrayIndex + 1}]`);
                            resFields[pathArr.join('.')] = {...fields[path]};
                            delete(fields[path]);
                            count ++;
                        });
                        if (count) {
                            this.$store.commit('ai/updateField', {
                                [editingId]: { ...fields, ...resFields },
                            });
                        }
                    }
                }
            },

            deleteValue(index) {
                const aiData = this.getAIFieldData();
                if (aiData) {
                    const {editingId, fields} = aiData;
                    const key = `${this.field.name}[${index}].`;
                    let count = 0;
                    Object.keys(fields).forEach(path => {
                        if (path.startsWith(key)) {
                            delete fields[path];
                            count ++;
                        }
                    });
                    if (count) {
                        this.$store.commit('ai/updateField', {
                            [editingId]: { ...fields },
                        });
                    }
                }
                this.values.splice(index, 1);
            },

            onMouseDown(e){
                this.mouseDownHandler(e);
            },

            cbEndDrag(pos){
                if (this.hasSorted && pos.before && pos.after) {
                    let before = parseInt(pos.before[0]);
                    let after = parseInt(pos.after[0]);
                    if (Math.min(before, after) <= this.data.tabOpened &&
                        Math.max(before, after) >= this.data.tabOpened) {
                            if(before < after) {
                                this.data.tabOpened = this.data.tabOpened === before ? after : (this.data.tabOpened - 1);
                            }
                            else {
                                this.data.tabOpened = this.data.tabOpened === before ? after : (this.data.tabOpened + 1);
                            }
                    }
                    this.values.splice(after, 0, this.values.splice(before, 1)[0]);

                    const aiData = this.getAIFieldData();
                    if (aiData) {
                        const {editingId, fields} = aiData;
                        let sorted: typeof fields = {};
                        Object.keys(fields).forEach(path => {
                            const beforeKey = `${this.field.name}[${before}]`, afterKey = `${this.field.name}[${after}]`;
                            if (path.startsWith(beforeKey)) {
                                sorted[`${afterKey}${path.substring(beforeKey.length)}`] = fields[path];
                                delete fields[path];
                            }
                            if (path.startsWith(afterKey)) {
                                sorted[`${beforeKey}${path.substring(afterKey.length)}`] = fields[path];
                                delete fields[path];
                            }
                        });
                        if (Object.keys(sorted).length) {
                            this.$store.commit('ai/updateField', {
                                [editingId]: { ...fields, ...sorted }
                            });
                        }
                    }
                }
            },
            canDelete(item){
                return !item.cantDelete ? true : false;
            },
            deleteItem(index) {
                this.values.splice(index,1);
                const aiData = this.getAIFieldData();
                if (aiData) {
                    const {editingId, fields} = aiData;
                    const key = `${this.field.name}[${index}]`;
                    let count = 0;
                    Object.keys(fields).forEach(path => {
                        if (path.startsWith(key)) {
                            delete fields[path];
                            count ++;
                        }
                    });
                    if (count) {
                        this.$store.commit('ai/updateField', {
                            [editingId]: { ...fields },
                        });
                    }
                }
            }
        },
        mounted() {
            if(!this.data  || typeof this.data != 'object') {
            }
            else
            {
                Object.defineProperty( this.data, "tabOpened", { enumerable: false, writable: true } );
                this.data.tabOpened = -1;
            }


        },
        beforeUnmount() {
        }
    };
</script>
