    .dragging *{
        opacity: 0;
    }
    .dragging .header-group{
        opacity: 1;
    }
    .svg-full svg{
        width: 100%;
        height: 100%;
    }
    .ecom-mouse-down{
        cursor: grab;
    }
    .ecom-mouse-down:focus{
        cursor: grabbing;
    }
    .item:hover .item-hover\:w-6\/10 {
        width: 60%;
    }
    .ecom-dragging .open-drag{
        margin-bottom: 0;
    }
</style>
