<template>
    <div class="ecom-imgAccordion">
        <div class="ecom-imgAccordion-wrapper ecom-swiper-container" :class="['ecom-imgAccordion-' + data.settings?.expand_action]">
            <div class="ecom-swiper-wrapper ecom-flex">
                <div class="ecom-imgAccordion-item ecom-swiper-slide"
                    v-for="(item, index) in data.settings.items"
                    :v-key="index"
                    @click="setEditingElement(index)"
                    :class="[{ 'ecom-imgAccordion-item-expand': isFirstItem(index)}]"
                >
                    <div class="ecom-imgAccordion-img-wrapper">
                        <div class="ecom-imgAccordion-type-icon"
                            v-if="data.settings.enable_media_btn && (item.media?.source == 'video_url' || item.media?.source == 'video_upload') && imageAccordion.video_btn_icon"
                            ecom-modal="inline"
                            :ecom-modal-source="popupSrc + '-' + index"
                        >
                            <div class="ecom-imgAccordion-type-icon-svg"
                                v-html="imageAccordion.video_btn_icon"
                            ></div>
                            <span class="ecom-imgAccordion-type-text"
                                v-if="imageAccordion.video_btn_label"
                                v-html="imageAccordion.video_btn_label"></span>
                        </div>
                        <div class="ecom-imgAccordion-type-icon"
                            v-if="data.settings.enable_media_btn && item.media?.source == 'image' && imageAccordion.image_btn_icon"
                            ecom-modal="image"
                            :ecom-modal-source="item.media?.image?.value"
                            :src="item.media?.image?.value ? item.media?.image?.value : '/images/placeholder.png'"
                        >
                            <div class="ecom-imgAccordion-type-icon-svg"
                                v-html="imageAccordion.image_btn_icon"></div>
                            <span class="ecom-imgAccordion-type-text"
                                v-if="imageAccordion.image_btn_label"
                                v-html="imageAccordion.image_btn_label"></span>
                        </div>
                        <video class="ecom-imgAccordion-video"
                            v-if="item.media?.source == 'video_url' || item.media?.source == 'video_upload'"
                            :poster="item.media.poster_image?.value??''"
                            ecom-modal="inline"
                            :ecom-modal-source="popupSrc + '-' + index"
                            loop
                            playsinline
                            autoplay
                            ref="video"
                            @click="setEditingElement(index)"
                            >
                            <source :src="data.settings?.lazyload_video? '' : linkVideo(item?.media)" :data-source="linkVideo(item?.media)" />
                        </video>
                        <a
                            v-else-if="item.media?.image_link"
                            :href="item.media?.image_link.href"
                            :target="item.media?.image_link.target">
                            <img class="ecom-imgAccordion-img"
                                ref="buttonToOpenModalEl"
                                :src="item.media?.image?.value ? item.media?.image?.value : '/images/placeholder.png'"
                                :alt="item.media?.image?.name"
                                @click="setEditingElement(index)"
                                :width="item.media?.image?.width"
                                :height="item.media?.image?.height"
                            />
                        </a>
                        <img class="ecom-imgAccordion-img"
                            v-else
                            ref="buttonToOpenModalEl"
                            ecom-modal="image"
                            :ecom-modal-source="item.media?.image?.value"
                            :src="item.media?.image?.value ? item.media?.image?.value : '/images/placeholder.png'"
                            :alt="item.media?.image?.name"
                             @click="setEditingElement(index)"
                             :width="item.media?.image?.width"
                             :height="item.media?.image?.height"
                        />
                        <div style="display: none;">
                            <div v-if="item.media?.source == 'video_url' || item.media?.source == 'video_upload'" :id="'ecom-elements__lightbox-video-' + element_id + '-' + index" style="height:100%; width: 100%">
                                <video
                                    style="display: flex !important;width: 100%; height:100%;"
                                    class="ecom_video"
                                    :loop="item?.media?.video_loop"
                                    controls
                                >
                                    <source :src="data.settings?.lazyload_video? '' : linkVideo(item?.media)" :data-source="linkVideo(item?.media)"/>
                                </video>
                            </div>
                        </div>
                    </div>
                    <div class="ecom-imgAccordion-caption ecom-pa">
                        <div class="ecom-imgAccordion-caption-wrap">
                            <h3
                                class="ecom-imgAccordion-caption-heading"
                                v-if="item?.content?.heading"
                                v-html="lang(item.content.heading, 'imgAccordion-heading-' + index)"
                            ></h3>
                            <h4
                                class="ecom-imgAccordion-caption-subheading"
                                v-if="item?.content?.subheading"
                                v-html="lang(item.content.subheading, 'imgAccordion-subheading-' + index)"
                            ></h4>
                            <a class="ecom-imgAccordion-caption-button ecom-in_flex ecom-al_center"
                                v-if="item?.button?.content"
                                :href="item?.button?.link?.href ? item?.button?.link?.href : '#'"
                                :title="item?.button?.link?.title"
                                :target="item?.button?.link?.target"
                                :id="item?.button?.button_id"
                            >
                                <span class="ecom-imgAccordion-caption-button-text"
                                    v-html="lang(item.button.content, 'imgAccordion-button-' + index)"
                                ></span>
                                <span class="ecom-imgAccordion-caption-button-icon ecom-flex"
                                    v-if="item.button?.icon"
                                    v-html="item.button.icon"
                                ></span>
                            </a>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <div class="ecom-imgAccordion-prevNext"
            :class="{'ecom-imgAccordion-prevNext-special' : imageAccordion.fullwidth_mobile }">
            <div class="ecom-imgAccordion-prev">
                <svg fill="currentColor" viewBox="-78.5 0 512 512" xmlns="http://www.w3.org/2000/svg" ><path d="M257 64L291 98 128 262 291 426 257 460 61 262 257 64Z" /></svg>
            </div>
            <div class="ecom-imgAccordion-next">
                <svg fill="currentColor" viewBox="-77 0 512 512" xmlns="http://www.w3.org/2000/svg" ><path d="M98 460L64 426 227 262 64 98 98 64 294 262 98 460Z" /></svg>
            </div>
        </div>
    </div>
</template>

<script>

import { Element, Javascript } from "@/mixins";
export default {
    name: 'MediaAccordion',
    docs: 'https://help.ecomposer.io/docs/editor-elements/basic-elements/media-accordion',
    linkVideo: "https://youtu.be/Vc34aBvUncg?si=o4dr9MWGx3P9K5a0",
    presets: true,
    vendors: ['modal_js', 'modal_css', 'slider_js', 'slider_css'],
    mixins: [Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives:[
                'items',
                'source',
                'expand_action',
                'place_click',
                'enable_media_btn',
                'item_spacing__mobile',
                'fullwidth_mobile',
                'disable_auto_video',
                'poster_image',
                'lazyload_video'
            ]
        };
    },
    mounted() {
        if(this.$refs.video) {
            this.$refs.video.forEach(function(video) {
                video.muted = true;
                video.setAttribute('muted', '');
            })
        }
        if (this.data?.settings?.enable_media_btn && this.data?.settings?.place_click == 'button') {
            this.$refs.buttonToOpenModalEl && this.$refs.buttonToOpenModalEl.length && this.$refs.buttonToOpenModalEl.forEach(function(el) { el.removeAttribute('ecom-modal'); })
            this.$refs.video && this.$refs.video.length && this.$refs.video.forEach(function(el) { el.removeAttribute('ecom-modal'); })
        }
    },
    watch:{
        'data.settings.items': {
            deep: true,
            handler: function (newVal) {
                this.refresh();
            }
        }
    },
    computed: {
        isFirstItem() {
            return (index) => index === 0;
        },
        wholeItemClick() {
            return this.data?.settings?.place_click;
        },
        imageAccordion() {
            return this.data.settings;
        },
        element_id() {
            return this.data.id;
        },
        popupSrc() {
            let src = '#ecom-elements__lightbox-video-' + this.element_id;
            return src;
        },
        fullwidth() {
            return this.data?.settings?.fullwidth_mobile;
        },
        javascript() {
            return function() {
                if(!this.$el) return;
                let $el = this.$el;
                var $el_id = this.id;
                var items = $el.querySelectorAll('.ecom-imgAccordion-item');
                var items_wraper = $el.querySelectorAll('.ecom-imgAccordion-img-wrapper');
                var items_length = items.length;
                var expand_action = this.settings.expand_action;
                var place_click = this.settings.place_click;
                var playOnHover = !this.settings.disable_auto_video;
                var lazyload = this.settings.lazyload_video || false; 
                if(lazyload) {
                    createObserver($el)
                };
                function createObserver(element){
                    let options = {
                        root: null,
                        rootMargin: "0px",
                        threshold: 0.5
                    };
                    let observer = new IntersectionObserver(handleIntersect, options);
                    observer.observe(element);
                }
                function handleIntersect(entries, observer){
                    entries.forEach(function(entry){
                        if(entry.isIntersecting) {
                            const videos = entry.target.querySelectorAll('video.ecom-imgAccordion-video');
                            videos.forEach(video => {
                                let videoSource = video.querySelector('source');
                                videoSource.src = videoSource.dataset.source;
                                if(video && videoSource.src) {
                                    video.load();
                                    video.pause();
                                }
                            });
                            observer.unobserve(entry.target);
                        }
                    });
                }
                // Set width for content =(((
                setContentWidth($el);
                window.addEventListener('resize', function() {
                    setContentWidth($el);
                })
                function setContentWidth(accordion) {
                    var width = (accordion.offsetWidth * 4) / (items_length + 3);
                    accordion.querySelectorAll('.ecom-imgAccordion-caption').forEach(function(el) {
                        el.style.width = width + 'px';
                    })
                }
                const $container = $el.querySelector('.ecom-swiper-container');
                var item_spacing_mobile = this.settings.item_spacing__mobile ? this.settings.item_spacing__mobile : 0;
                var swiper;
                var params = {
                    "slidesPerView": 1.4,
                    "spaceBetween": item_spacing_mobile,
                    "centeredSlides": true,
                    "loop": true,
                    "navigation": {
                        "nextEl": `.${this.id} .ecom-imgAccordion-next`,
                        "prevEl": `.${this.id} .ecom-imgAccordion-prev`,
                    }
                }
                if(this.settings.fullwidth_mobile) {
                    params["slidesPerView"] = 1;
                    params["centeredSlides"] = false
                }
                function initSwiper() {
                    swiper = new window.EComSwiper($container, params);
                    swiper.on('slideChange', function() {
                        $el.querySelectorAll('video').forEach(function(video) { video.pause(); })
                        const currentSlide = swiper.slides[swiper.activeIndex];
                        currentSlide.querySelector('.ecom-imgAccordion-img-wrapper').removeAttribute('style');
                        $el.querySelector('.ecom-imgAccordion-item-expand').classList.remove('ecom-imgAccordion-item-expand');
                        currentSlide.classList.add('ecom-imgAccordion-item-expand');
                        var video = currentSlide.querySelector('video');
                        if(video && playOnHover)
                            video.onloadeddata = function() {
                                video.play();
                            };   
                    });
                };
                setTimeout(function(){
                    $el.querySelectorAll('video').forEach(function(video) { video.pause(); });
                },100) // On safari mobile, set autoplay and playsinline to show video and pause in script
                if(expand_action == 'click') {
                    // Dont show modal box at first click
                    items_wraper.forEach(function(e) { e.style.pointerEvents = 'none'; });
                    if(items_wraper[0])
                        items_wraper[0].removeAttribute('style');
                    $el.querySelectorAll('video').forEach(function(video) { video.pause(); })
                }

                // Pause video when click outside
                document.addEventListener('click', function(e) {
                    var aclass = e.target.classList;
                    if(!aclass.contains('ecom-imgAccordion-item-expand') && !aclass.contains('ecom-imgAccordion-prev') && !aclass.contains('ecom-imgAccordion-next') && !(place_click == 'button' && aclass.contains('ecom-imgAccordion-video'))) {
                        $el.querySelectorAll('video').forEach(function(video) { video.pause(); })
                    }
                })

                //
                items.forEach(function(item, index) {
                    var video = item.querySelector('video');

                    if(expand_action == 'hover')
                        item.addEventListener('mouseenter', function() {
                            if(window.innerWidth > 1024) {
                                items_wraper.forEach(function(e) { e.style.pointerEvents = 'none'; });
                                item.querySelector('.ecom-imgAccordion-img-wrapper').removeAttribute('style');
                                // Close last item and open this item
                                $el.querySelector('.ecom-imgAccordion-item-expand').classList.remove('ecom-imgAccordion-item-expand');
                                item.classList.add('ecom-imgAccordion-item-expand');

                                // If video, play
                                $el.querySelectorAll('video').forEach(function(otherVideo) {
                                    if (otherVideo !== video) { 
                                        otherVideo.pause();
                                    }
                                });
                                if (video && playOnHover && video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
                                        video.play()
                                }
                            }
                        })

                    item.addEventListener('click', function() {
                        items_wraper.forEach(function(e) { e.style.pointerEvents = 'none'; });
                        item.querySelector('.ecom-imgAccordion-img-wrapper').removeAttribute('style');
                        // Close last item and open this item
                        $el.querySelector('.ecom-imgAccordion-item-expand').classList.remove('ecom-imgAccordion-item-expand');
                        item.classList.add('ecom-imgAccordion-item-expand');

                        // If video, play
                        $el.querySelectorAll('video').forEach(function(otherVideo) {
                                    if (otherVideo !== video) { 
                                        otherVideo.pause();
                                    }
                        });
                        if (video && playOnHover) {
                            video.play();
                        }
                    })


                    $el.addEventListener('mouseenter', function() {
                        if(item.classList.contains('ecom-imgAccordion-item-expand') && video && playOnHover && video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA){
                            video.play();
                        }
                    })
                    $el.addEventListener('mouseleave', function() {
                        // If video, pause
                        if(video)
                            video.pause();
                    })

                })

                // Ecom modal
                var ecom_modals =  $el.querySelectorAll('[ecom-modal]');
                if(ecom_modals.length) {
                    new window.EComModal(ecom_modals, {
                        cssClass: ['ecom-container-lightbox-' + $el_id],
                        onOpen: function() {
                            const popup = document.querySelectorAll('.ecom-container-lightbox-' + $el_id);
                            popup.forEach(function(p) {
                                const video = p.querySelector('video');
                                const videoSource = p.querySelector('video source');
                                if(video != null ){
                                    videoSource.src = videoSource.dataset.source;
                                    playOnHover? video.play() : video.pause();
                                }
                            })
                        },
                        onClose: function () {
                            const popup = document.querySelectorAll('.ecom-container-lightbox-' + $el_id);
                            popup.forEach(function(p) {
                                const video = p.querySelector('video');
                                if(video != null){
                                    video.pause();
                                }
                            })
                        }
                    });
                }

                // Ecom swiper
                if(window.innerWidth < 768)
                    initSwiper();

                window.addEventListener('resize', function() {
                    if(window.innerWidth < 768) {
                        if(!swiper || swiper.destroyed) {
                            initSwiper();
                            items_wraper[swiper.activeIndex].removeAttribute('style');
                        }
                    }
                    else
                        if(swiper) swiper.destroy(true, true)
                })
            }
        },
        settings() {
            return [
                {
                    group_title: this.$t('banner_items'),
                    params: [
                        {
                            name: 'items',
                            type: 'group',
                            value: [],
                            options: {
                                add_text: this.$t('add_new_banner_item'),
                                is_clear_all: false
                            },
                            params: [
                                {
                                    group_name: 'media',
                                    group_title: this.$t('media'),
                                    params: [
                                        {
                                            type: 'popup',
                                            label: this.$t('source'),
                                            name: 'source',
                                            value: "image",
                                            options: {
                                                default: false,
                                                type: 'dropdown',
                                                values: {
                                                    'image': this.$t('image'),
                                                    'video_url': this.$t('custom_video_url'),
                                                    'video_upload': this.$t('upload_video')
                                                }
                                            }
                                        },
                                        {
                                            type: 'picker',
                                            label: this.$t('choose_image'),
                                            name: 'image',
                                            options: {
                                                responsive: false,
                                                type: 'image',
                                                editAlt: true,
                                                visible: {
                                                    'name': 'source',
                                                    'value': 'image'
                                                }
                                            }
                                        },
                                        {
                                            type: 'link',
                                            label: this.$t('source'),
                                            name: 'image_link',
                                            options: {
                                                visible: {
                                                    name: 'source',
                                                    value: 'image'
                                                }
                                            }
                                        },
                                        {
                                            type: 'text',
                                            label: this.$t('enter_your_custom_video_url'),
                                            name: 'video_url',
                                            description: this.$t('use_link_video_share_driver_mp_4_oog'),
                                            options: {
                                                visible: {
                                                    'name': 'source',
                                                    'value': 'video_url'
                                                }
                                            }
                                        },
                                        {
                                            type:'picker',
                                            name: 'upload',
                                            label: this.$t('choose_or_upload_a_video_n_i_maximum_10_mb_i'),
                                            options: {
                                                type:'video',
                                                visible: {
                                                    'name': 'source',
                                                    'value': 'video_upload'
                                                }
                                            }
                                        },
                                        {
                                            type: 'picker',
                                            label: this.$t('poster_image'),
                                            name: 'poster_image',
                                            options: {
                                                visible: {
                                                    keep_data: true,
                                                    condition: (data) => {
                                                        return (data["source"] === "video_url" || data["source"] === "video_upload");
                                                    }
                                                },
                                                responsive: false,
                                                type: 'image',
                                                editAlt: false
                                            }
                                        },
                                    ]
                                },
                                {
                                    group_title: this.$t('content'),
                                    group_name: 'content',
                                    params: [
                                        {
                                            type: "textarea",
                                            label: this.$t('heading'),
                                            name: "heading",
                                            options: {
                                                toolbar: true
                                            }
                                        },
                                        {
                                            type: "textarea",
                                            label: this.$t('sub_heading'),
                                            name: "subheading",
                                            options: {
                                                toolbar: true,
                                                height: 60
                                            }
                                        }
                                    ]
                                },
                                {
                                    group_alias: 'button:settings',
                                    options: {
                                        group_name: 'button',
                                        group_title: this.$t('button'),
                                    },
                                    modify: {
                                        remove: {
                                            index: 4,
                                            length: 2
                                        }
                                    }
                                }
                            ]
                        }
                    ]
                },
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('banner_expand_on'),
                            name: 'expand_action',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                default: false,
                                values: {
                                    'hover': this.$t('hover'),
                                    'click': this.$t('click')
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t('space_between_items'),
                            name: "item_spacing",
                            options: {
                                responsive: true,
                                reset: true,
                                units: {
                                    "px": {
                                        min: 0,
                                        max: 100
                                    }
                                }
                            },
                            css: {
                                selector:'root .ecom-imgAccordion-wrapper>div',
                                properties: {
                                    "column-gap": ""
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_media_type_button'),
                            name: 'enable_media_btn',
                            options: {
                                values: {
                                    on: {
                                        label: 'Yes',
                                        value: true
                                    },
                                    off: {
                                        label: 'No',
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            name: "lazyload_video",
                            label: this.$t("enable_lazyload_for_video"),
                            type: "toggle",
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                oneline: true
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('video_button_icon'),
                            name: 'video_btn_icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible: {
                                    name: 'enable_media_btn',
                                    value: true
                                }
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('video_button_label'),
                            name: 'video_btn_label',
                            options: {
                                visible: function(data) {
