        linkVideo(media) {
            if(media?.source === 'video_url')
            {
                if (media?.video_url) {
                    let check = media?.video_url.match(
                        /(http(s)?:\/\/.)?(www\.)?[-a-zA-Z0-9@:%._+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_+.~#?&=]*)/
                    );
                    if (check && check[0] == "https://drive.google.com") {
                        const regex = /\/file\/d\/(.+)\/(.+)/;
                        let val = media?.video_url.match(regex);
                        let videoId = val ? val[1] : null;
                        return `${
                            location.protocol
                        }//drive.google.com/uc?export=download&id=${videoId}`;
                    } else {
                        return (
                            media?.video_url
                        );
                    }
                } else {
                    return "";
                }
            }
            else if(media?.source === 'video_upload')
            {
                return media?.upload?.url;
            }
            return '';
        }
