<template>
    <div class="relative p-3 bg-white focus:outline-none focus:ring-0 rounded-b-lg border border-t-0 border-gray-200">
        <div class="w-full h-24 mb-4 rounded shadow-gradient-preview"
            :class="{ 'bg-white  ': !positionsValidSorted.length }" :style="preview('')" />

        <div class="relative mb-4" style="z-index:11">
            <div class="relative" @click="onAddNewColor" :data-tooltip="$t('click_to_add_color_stop')">
                <div class="relative h-5 rounded-full range shadow-range" :class="[
                    { 'bg-gray-50 ': !positionsValidSorted.length },
                    hasAdd ? 'cursor-crosshair' : 'cursor-default'
                ]" :style="preview()">
                    <div ref="range" class="relative mx-2.5">
                        <div v-for="pos in value.positions" :key="pos.index" :style="{ left: pos.index + '%' }" class="
                                item
                                absolute
                                top-0.5
                                transform
                                -translate-x-1/2
                                block
                                w-4
                                h-4
                                border-2 border-white
                                bg-transparent
                                flex
                                items-center
                                justify-center
                                rounded-full
                            " :class="[
                                selected == pos
                                    ? (isMove ? 'cursor-grabbing ' : 'cursor-pointer ') +
                                    'ring-2 ring-primary-500 z-1'
                                    : 'cursor-pointer',
                                { 'bg-empty': !pos.color }
                            ]" :data-tooltip="$t('click_to_select_color')" @mousedown="mouseDownItem(pos, $event)">
                            <span v-if="selected == pos" class="
                                    absolute
                                    -bottom-3
                                    left-1/2
                                    transform
                                    -translate-x-1/2
                                    p-0.5
                                    rounded-full
                                    bg-primary-500
                                " /><template v-else />
                        </div>
                    </div>
                </div>
            </div>
            <Teleport to="body" v-if="selected && showPicker">
                <transition enter-active-class="transition duration-200 ease-out"
                    enter-from-class="translate-y-1 opacity-0" enter-to-class="translate-y-0 opacity-100"
                    leave-active-class="transition duration-150 ease-in" leave-from-class="translate-y-0 opacity-100"
                    leave-to-class="translate-y-1 opacity-0">
                    <div class="z-[62] fixed ecom-fields__popup popup-color" :id="idTeleport" :style="{
                        top: popupColorPosition.top,
                        left: popupColorPosition.left,
                        bottom: popupColorPosition.bottom
                    }
                    ">
                        <ColorPicker v-clickOutside="closePopup" class="relative z-[2]" :value="color(selected?.color)"
                            :global="{ type: 'colors' }" :global-selected="selected?.color?.['global-colors']"
                            @refeshColor="updateColor('')" @update:value="updateColor($event)"
                            @update:global-selected="updateColor({ 'global-colors': $event })"
                            @update:delete="deleteColor" />
                    </div>
                </transition>
            </Teleport>
            <template v-else />
        </div>
        <div class="flex items-center justify-between mb-4">
            <span class="text-xs font-semibold text-black ">{{ $t('color_stop') }}</span>
            <span class="flex items-center">
                <EcomIcon @click="hasRefresh && (value.positions = [])" :source="icons.ecRefresh" :size="'w-5'"
                    class="transition flex items-center "
                    :class="value.positions?.length ? 'text-gray-500  hover:text-primary-700 cursor-pointer' : 'text-gray-500  '">
                </EcomIcon>
            </span>
        </div>
        <Fields v-if="value?.positions?.length" :data="value" :fields="fields" :freeform="true" /><template v-else />
        <div class="flex justify-center my-2">
            <a href="https://help.ecomposer.io/docs/faqs/how-to-create-gradient-backgrounds-for-buttons-or-section/"
                class="flex items-center bg-primary text-white text-sm font-medium rounded hover:underline px-3 py-1"
                target="_blank">
                <span>{{ $t('see_guide') }}</span>
                <EcomIcon :source="icons.QuestionMarkInverseMajor" :size="'w-5'" class="ml-1"></EcomIcon>
            </a>
        </div>
    </div>
</template>

<script lang="ts">
// import {faArrowsRotate, faQuestionSquare} from '@fortawesome/pro-light-svg-icons';
import ColorPicker from "../../components/molecules/ColorPicker/ColorPanel.vue";
//import ColorPicker from "@/components/Builder/Components/Utils/TextEditorBar/Color/GradientColor.vue";

import { convertGradient } from "@/components/Builder/Helpers/Css";
import { clickOutside } from "../../directives";
import { ecRefresh, QuestionMarkInverseMajor } from '@/assets/icons';

interface PopupColorPosition {
    top: string | number;
    left: string;
    bottom: string | number;
}

interface PopupDimensions {
    width: number;
    height: number;
}

export default {
    name: "Gradient",
    components: {
        ColorPicker,
    },
    directives: {
        clickOutside
    },
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    emits: ["update:data"],
    data() {
        return {
            popupColorPosition: { top: 0, left: '0px', bottom: 0 } as PopupColorPosition,
            idTeleport: "popup-gradient" + Date.now() + Math.random().toString(36).substr(2, 9),
            icons: {
                // faArrowsRotate, faQuestionSquare,
                ecRefresh, QuestionMarkInverseMajor
            },
            selected: null as any,
            value: {
                positions: [{ index: 0, color: "" }]
            },
            inputRange: null as HTMLElement | null,
            isMove: false,
            x: 0 as number | null,
            max: 10,
            showPicker: false,
            mutationObserver: null as MutationObserver | null,
            popupElement: null as HTMLElement | null,
            popupDimensions: { width: 267, height: 468 } as PopupDimensions
        };
    },
    computed: {
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        fields() {
            return [
                {
                    name: "type",
                    label: this.$t('type'),
                    type: "popup",
                    value: "linear",
                    options: {
                        type: "dropdown",
                        default: false,
                        preview: 'title',
                        values: {
                            linear: this.$t('linear'),
                            radial: this.$t('radial')
                        },
                        oneline: true
                    }
                },
                {
                    name: "angle",
                    label: this.$t('angle'),
                    type: "number",
                    value: 180,
                    options: {
                        min: 0,
                        max: 360,
                        visible: {
                            keep_data: true,
                            condition: (data: any) => {
                                return data["type"] == "linear";
                            }
                        }
                    }
                },
                {
                    name: "position",
                    label: this.$t('position'),
                    type: "popup",
                    value: "center center",
                    options: {
                        type: "dropdown",
                        default: false,
                        preview: 'title',
                        values: {
                            "center center": this.$t('center_center'),
                            "center right": this.$t('center_right'),
                            "center left": this.$t('center_left'),
                            "top left": this.$t('top_left'),
                            "top center": this.$t('top_center'),
                            "top right": this.$t('top_right'),
                            "bottom right": this.$t('bottom_right'),
                            "bottom left": this.$t('bottom_left'),
                            "bottom center": this.$t('bottom_center'),
                        },
                        oneline: true,
                        visible: {
                            keep_data: true,
                            condition: (data: any) => {
                                return data["type"] == "radial";
                            }
                        }
                    }
                }
            ];
        },
        positionsSorted() {
            let poss = this.$helpers.copy(this.value.positions);
            poss.sort((a: any, b: any) => a.index - b.index);
            return poss;
        },
        positionsValidSorted() {
            let poss = this.$helpers.copy(this.positionsSorted);
            return poss.filter((pos: any) => pos.color);
        },
        hasRefresh() {
            return this.positionsSorted.length;
        },
        hasAdd() {
            return this.positionsSorted.length < 10;
        },
        output() {
            if (this.positionsValidSorted?.length > 0) {
                // eslint-disable-next-line no-unused-vars
                let { positions, ...agrs } = this.value;
                return {
                    positions: this.positionsValidSorted,
                    ...agrs
                };
            }
            return {};
        },
        globalColors() {
            return this.$store.getters["settings/globalDatas"];
        },
        posArrow() {
            if (this.selected) {
                if (!this.inputRange) {
                    this.inputRange = this.$refs["range"] as HTMLElement;
                }
                if (!this.inputRange) {
                    return '0px';
                }
                let w = this.inputRange.offsetWidth;
                return this.intBetween((this.selected.index * w) / 100 + 10, 10, w + 10) + "px";
            }
            return "";
        }
    },
    watch: {
        data: {
            deep: true,
            immediate: true,
            handler(val) {
                if (val && JSON.stringify(val) !== JSON.stringify(this.output)) {
                    this.value = this.validValue(val);
                    this.selected = this.value.positions?.[0];
                } else if (!this.selected) {
                    this.selected = this.value.positions?.[0];
                }
            }
        },
        output: {
            deep: true,
            handler(val) {
                this.$emit("update:data", val);
            }
        },
        isPopupOpen(val) {
            if(val === false) {
                this.showPicker = false;
            }
        }
    },
    mounted() {
        this.inputRange = this.$refs["range"] as HTMLElement;
        if (window.EComposerBuilder?.contentDocument) {
            window.EComposerBuilder.contentDocument.onclick = () => {
                this.showPicker = false;
            };
        }
    },
    methods: {
        preview(type = "linear") {
            let output = this.$helpers.copy(this.output);
            if (type === "linear") {
                output.type = "linear";
                output.angle = 90;
            }
            return convertGradient(output);
        },
        color(v: any) {
            if (typeof v === "string") {
                return v;
            } else if (v?.["global-colors"]) {
                return this.globalColors?.colors?.[v["global-colors"]]?.value ?? "";
            }
            return "";
        },
        validValue(value: any) {
            let v: any = { positions: [] };
            ["first", "second"].forEach((t) => {
                if (value[t + "-color"]) {
                    v.positions.push({
                        index: value[t + "-location"] ?? 0,
                        color: value[t + "-color"]
                    });
                }
            });
            ["type", "angle", "position", "positions"].forEach((t) => {
                if (value[t]) {
                    v[t] = value[t];
                }
            });
            return v;
        },
        intBetween(num: any, min: any, max: any) {
            if (num === undefined) {
                return num;
            }
            return Math.max(min, Math.min(max, num));
        },
        updateColor(color: any) {
            if (this.selected) {
                this.selected.color = color;
            } else {
                let newItem = {
                    index: 0,
                    color
                };
                this.selected = newItem;
                this.value.positions.push(newItem);
            }
        },
        onAddNewColor(e: any) {
            this.isOpenPopupColor(e);
            //this.startObservingPopup();
            if (e.target.closest(".item:not(.ecom-group-item)")) {
                return;
            }

            let { x } = e,
                target = e.target,
                targetRect = target.getBoundingClientRect(),
                targetWidth = target.offsetWidth,
                percent = Math.round(((x - targetRect.x) / targetWidth) * 100);
            this.addNewColor(percent);
        },
        addNewColor(index: any, color = "") {
            if (!this.hasAdd) {
                return;
            }
            if (this.value.positions.length < 10) {
                let newItem = {
                    index,
                    color
                };
                this.selected = newItem;
                this.value.positions = this.value.positions.filter((pos: any) => pos.color != '');
                this.value.positions.push(newItem);
                this.showPicker = true;
                this.$store.commit("builder/setIsPopupOpen", true);
            }
        },
        startObservingPopup() {
            this.stopObservingPopup();

            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === Node.ELEMENT_NODE) {
                                const element = node as HTMLElement;
                                if (element.id === this.idTeleport) {
                                    this.popupElement = element as HTMLElement;
                                    this.isOpenPopupColor(element);
                                    requestAnimationFrame(() => {
                                        this.updatePopupDimensions();
                                        this.isOpenPopupColor(element);
                                    });
                                }
                            }
                        });
                    }
                });
            });

            this.mutationObserver.observe(document.body, {
                childList: true,
                subtree: true
            });
        },
        stopObservingPopup() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },
        updatePopupDimensions() {
            if (this.popupElement) {
                this.popupDimensions = {
                    width: this.popupElement.offsetWidth || 267,
                    height: this.popupElement.offsetHeight || 468
                };
            }
        },
        isOpenPopupColor(event: any) {
            const targetElement = (event.target || event) as HTMLElement;
            if (!targetElement?.getBoundingClientRect) {
                return;
            }
            const range = targetElement.closest('.range');

            if(!range) return;

            const rect = range.getBoundingClientRect();

            this.$nextTick(() => {
                const { width: popupWidth, height: popupHeight } = this.popupDimensions;

                const distanceToBottom = window.innerHeight - rect.top - rect.height;

                const fixedSelected = targetElement.closest('.ecom-library-popup') as HTMLElement || targetElement.closest('.popup-container') as HTMLElement || targetElement.closest('.fixed') as HTMLElement || targetElement.closest('.absolute') as HTMLElement;
                const fixedRect = fixedSelected.getBoundingClientRect();

                let left: number;
                if(fixedSelected) {
                    const {left: leftFixed, width: selectedWidth} = fixedRect;
                    const distanceToRight = window.innerWidth - leftFixed - selectedWidth;

                    if(leftFixed >= popupWidth) {
                        const spaceRectToFixedRect = rect.left - leftFixed;
                        if(spaceRectToFixedRect > 50) {
                            left = rect.left - popupWidth - 20;
                        }else {
                            left = leftFixed - popupWidth;
                        }
                    }else if(distanceToRight >=  popupWidth) {
                        left = leftFixed + selectedWidth;
                    }else {
                        left = rect.left + rect.width;
                    }
                }else {
                    left = rect.left + rect.width;
                }

                let top: string, bottom: string;
                const fixedPopupGetter = targetElement.closest('.ecom-fields__background') as HTMLElement;
                const containerFly = targetElement.closest('.ecom-library-popup') as HTMLElement || targetElement.closest('.popup-container') as HTMLElement;
                let bottomFixedSpace = 0;
                if(fixedPopupGetter) bottomFixedSpace = window.innerHeight - fixedPopupGetter.getBoundingClientRect().top;

                if(fixedPopupGetter && !containerFly && bottomFixedSpace >= popupHeight) {
                    top = fixedPopupGetter.getBoundingClientRect().top + window.scrollY + "px";
                    bottom = 'auto';
                }else if (distanceToBottom >= popupHeight) {
                    top = (rect.bottom + window.scrollY - rect.height - 15) + "px";
                    bottom = 'auto';
                } else {
                    top = (rect.bottom + window.scrollY) - (popupHeight - distanceToBottom) + "px";
                    bottom = 'auto';
                }

                this.popupColorPosition = {
                    top,
                    left: left + 'px',
                    bottom
                };
            });
        },
        mouseDownItem(pos: any, e: any) {
            this.isMove = false;
            this.selected = pos;
            this.x = e.x;
            document.onmousemove = this.mouseMove;
            document.onmouseup = this.mouseUp;
        },
        mouseMove(e: any) {
            if (this.x !== null && Math.abs(this.x - e.x) > 3) {
                this.showPicker = false;
                this.isMove = true;
                let { x } = e;
                let rangeWidth = this.inputRange?.offsetWidth || 0,
                    rangeRect = this.inputRange?.getBoundingClientRect();
                if (rangeRect) {
                    let per = Math.round(((x - rangeRect.x) / rangeWidth) * 100);
                    if (this.selected) {
                        this.selected.index = this.intBetween(per, 0, 100);
                    }
                }
            }
        },
        mouseUp() {
            if (!this.isMove) {
                this.showPicker = true;
                this.$store.commit("builder/setIsPopupOpen", true);
            }
            document.onmousemove = null;
            document.onmouseup = null;
            this.isMove = false;
            this.x = null;
        },
        deleteColor() {
            let i = this.value.positions.findIndex((pos: any) => pos === this.selected);
            this.value.positions.splice(i, 1);
            this.showPicker = false;
        },
        closePopup(e: any) {
            if (!e.target.closest(".item") && !e.target.closest(".range")) {
                this.showPicker = false;
            }
        }
    }
};
</script>

<style>
.bg-size-2 {
    background-size: 8px;
}

.bg-size-3 {
    background-size: 12px;
}

.bg-size-5 {
    background-size: 20px;
}

.shadow-range {
    box-shadow: inset 0 0 0 1px rgb(0 0 0 / 7%), inset 0 1px 3px 0 rgb(0 0 0 / 15%);
}

.shadow-gradient-preview {
    box-shadow: inset 0 0 0 1px #AEB4B9;
}

.bg-empty {
    background: linear-gradient(to top left,
            rgba(0, 0, 0, 0) 0%,
            rgba(0, 0, 0, 0) calc(50% - 0.8px),
            red 50%,
            rgba(0, 0, 0, 0) calc(50% + 0.8px),
            rgba(0, 0, 0, 0) 100%);
}
</style>
<style scoped>
.outside-close-cursor {
    cursor: url("/dist/images/closeCursor.svg") 15 15, auto;
}
</style>