<template>
    <div class="flex flex-wrap" 
        :class="[
            isFull ? 'w-full' : !$parent.isElement ? 'p-0' : ''
        ]">
        <div
            v-for="(group, index) in fieldsFiltered"
            :key="isGroup(group) ? index : ((group.group_name + group.selector) || index)"
            :class="[
                !isGroup(group) && !freeform ? 'px-2' : ($parent.isElement || isSettings || isSettingsExtension) && index !== fieldsFiltered.length - 1 ? 'relative after:block after:h-0 after:border-b after:border-[#F1F1F1] after:absolute after:bottom-0 after:left-0 after:right-0' : '',
                isSettings ? 'after:border-solid' : '',
                //freeform ? 'bg-white' : '',
            group.options?.half ? 'w-1/2 field-half' : 'w-full'
            ,{
                'border-gray-200 rounded': deep === 0 && !freeform && !isSettings,
                'flex items-center justify-between' : group.options?.oneline,
                'justify-center': isFull
            }]"
        >

            <GroupsWrap
                v-if="isGroup(group)"
                :data="group"
                :field-values="values"
                :fields="fields"
                :index="index"
                @update:data="updateData"
                @update:delete="$emit('update:delete', $event)"
                :ref="group.group_name"
                @update:clicked="onClickGroupFields"
                :loading="loading"
                :lastActiveGroup="lastActiveGroup"
                :aipath="aipath"
                :type="type"
                :isQuickToolBar="isQuickToolBar"
            />
            <Field
                v-else
                :data="group"
                :field-values="values"
                :freeform="freeform"
                :ispop="ispop"
                :aipath="aipath"
                :class="index !== fieldsFiltered.length - 1 ? 'mb-3' : ''"
                @update:data="updateData"
                @update:delete="$emit('update:delete', $event)"
                @update:label="$emit('update:label', $event)"
            />
        </div>
    </div>
</template>
<script lang="ts">
    import GroupsWrap from '../components/atoms/Groups.vue';
    import Field from '../components/atoms/Field.vue';

    import { fieldMixin, relationMixin } from '../mixins';


    export default {
        components: {
            GroupsWrap,
            Field
        },
        mixins: [fieldMixin, relationMixin],
        props: {
            fields: {
                type: Array,
                default () {
                    return [];
                }
            },
            isFull: {
                type: Boolean,
                default: false
            },
            // eslint-disable-next-line vue/require-default-prop
            data: Object,
            deep: {
                type: Number,
                default: 0
            },
            freeform: {
                type: Boolean,
                default: false
            },
            ispop: {
                type: Boolean,
                default: false
            },
            openDefault: {
                type: Boolean,
                default: true
            },
            isSettings: {
                type: Boolean,
                default: false
            },
            isSettingsExtension: {
                type: Boolean,
                default: false
            },
            aipath: {
                type: String,
                default: ''
            },
            type: {
                type: String,
                default: ''
            },
            isQuickToolBar: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:label', 'update:delete', 'update:clicked', 'update:data'],
        data() {
            const editing = 'content';
            return {
                valueDeleted: {},
                activeGroup: this.openDefault ? (editing == 'content' || this?.fields.length == 1  ? 0 : -1) : -1,
                values: {},
                groupsRefs: [],
                loading: false,
                lastActiveGroup: editing == 'content' || this?.fields.length == 1  ? 0 : -1,
                timeOutLoading: null
            };
        },
        computed: {
            fieldsFiltered() {
                let fields = this.$helpers.formatFields(this.fields);
                return fields.filter(f => {
                    if(this.isGroup(f)) {
                        return this.fieldVisible(f, {});
                    }
                    return this.fieldVisible({}, f);
                });
            }
        },
        watch: {
            activeGroup: {
                deep: true,
                handler(newVal, oldVal) {
                    this.lastActiveGroup = oldVal;
                }
            },
            data: {
                deep: true,
                immediate: true,
                handler(val) {
                    if(val && typeof val === 'object') {
                        this.values = val;
                    }
                    else {
                        this.values = this.$helpers.defaultValues(this.fields);
                    }
                }
            },
            values: {
                deep: true,
                handler: function(val) {
                    this.$emit('update:data',this.fields, val);
               }
            },
            fields: {
                deep: true,
                handler(val) {
                    let firstVisibleObject = val.find(obj => obj?.visible === true);
                    if(firstVisibleObject){
                        this.activeGroup = val.indexOf(firstVisibleObject) > 0 ? val.indexOf(firstVisibleObject) : 0;
                        if(this.$refs[firstVisibleObject?.group_name]){
                            this.$nextTick(()=>{
                                this.$refs[firstVisibleObject?.group_name][0]?.$el?.scrollIntoView({top: 0});
                            })
                        }
                    }
                }
            }
        },
        methods: {
            onClickGroupFields(options) {
                this.$emit('update:clicked', options);
            },
            updateData(field, value) {
                this.$emit('update:data',field, value)
            },
            fieldVisible(g, f){
                return this.fieldsHidden.indexOf(this.pathField(g, f)) === -1;
            },
             isShow(gr){
                return !('visible' in gr) || gr.visible === true;
            },
            setActiveGroup(value) {
                this.activeGroup = value;
            },
            setLoading(value) {
                this.loading = value;
                this.activeGroup = -1;
                if(this.loading) {

                    clearTimeout(this.timeOutLoading);
                    this.timeOutLoading = setTimeout(() => {
                        this.loading = false;
                        this.activeGroup = 0
                    }, 500)
                }
            }
        }
    };
</script>

<style>
div.field-half+.field-half {
    padding-left: 10px !important;
}
div:not(.field-half)+div.field-half,
div>.field-half:first-child {
    padding-right: 10px !important;
}
</style>
