export const ecResizeImage = function(t: String, r: String): String {
    try {
        if (t.indexOf('cdn.ecomposer.app') === -1)
            return t;
        if (!r || "original" == r ||  "full" == r || "master" == r)
            return t;
        var o = t.match(/\.(jpg|jpeg|gif|png|bmp|bitmap|tiff|tif)((\#[0-9a-z\-]+)?(\?v=.*)?)?$/igm);
        if (null == o)
            return '';
        var i = t.split(o[0])
          , x = o[0];
        return i[0] + "_" + r + x;
    } catch (o) {
        return t
    }
}
function copy(obj: any, cs: boolean = false, cache?: WeakMap<any, any>): any {
    // Early return for null/undefined and non-objects
    if (!obj || typeof obj !== 'object') {
        return obj;
    }

    // Only use cache if provided (for deep nested calls)
    if (cache?.has(obj)) {
        return cache.get(obj);
    }

    // Pre-create ignore set
    const ignoreSet = new Set([
        'id',
        'firstinit',
        'tab_active',
        'auto_apply',
        'hasElementRequestLiquid'
    ]);

    if (cs) {
        ignoreSet.add('css');
    }

    // Handle Date objects
    if (obj instanceof Date) {
        const result = new Date(obj.getTime());
        cache?.set(obj, result);
        return result;
    }

    // Handle Arrays
    if (Array.isArray(obj)) {
        const result = new Array(obj.length);
        cache?.set(obj, result);

        for (let i = 0; i < obj.length; i++) {
            result[i] = copy(obj[i], cs, cache);
        }
        return result;
    }

    // Handle Objects
    const cloned: { [key: string]: any } = {};
    cache?.set(obj, cloned);

    const keys = Object.keys(obj);
    for (let i = 0; i < keys.length; i++) {
        const key = keys[i];

        if (ignoreSet.has(key)) {
            continue;
        }

        const value = obj[key];

        if (cs) {
            if (Array.isArray(value)) {
                if (value.length === 0) continue;
            } else if (value?.constructor === Object) {
                if (Object.keys(value).length === 0) continue;
            }
        }

        cloned[key] = copy(value, cs, cache);
    }

    return cloned;
}


export function randid() {
    return 'ecom-' + Math.random().toString(36).substring(2, 20);
}

function makeId(length: number): string {
    var result = [];
    var characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    var charactersLength = characters.length;
    for (var i = 0; i < length; i++) {
        result.push(characters.charAt(Math.floor(Math.random() * charactersLength)));
    }
    return result.join('');
}

function mergeArrByIndex(arr1, arr2, index) {
    if (!arr2.length) {
        return;
    }

    if (index >= arr1.length) {
        arr1[index] = null;
    }

    arr1.splice(index, arr1.length, ...arr2);
}

function setValByKey(values, strKey, value, separator = '||', overwrite = true) {
    let keys = strKey.split(separator);
    if (typeof values === 'object' && keys.length) {
        let parentValue = keys.slice(0, -1).reduce((o, n) => (o[n] = o[n] ?? {}), values);
        let lastKey = keys.slice(-1);
        if (
            parentValue[lastKey] === undefined ||
            (parentValue[lastKey] !== undefined && overwrite)
        ) {
            parentValue[lastKey] = value;
        }
    }
    return values;
}

