/**
 * Interface for font definition
 */
interface FontDefinition {
    family: string;
    weight: string;
}

/**
 * Moves media queries, fonts, and imports to the top of CSS
 * @param css - Input CSS string
 * @returns Reorganized CSS string
 */
export function moveTopMediaCss(css: string): string {
    const mediaRules: Set<string> = new Set();
    const fontRules: Set<string> = new Set();
    const importRules: Set<string> = new Set();

    /**
     * Processes font-face rules
     * @param fontFaceRule - Complete font-face rule
     */
    const processFontFace = (fontFaceRule: string): void => {
        const fontDef: FontDefinition = {
            family: '',
            weight: ''
        };

        // Extract font properties
        fontFaceRule.replace(
            /font-(family|weight)\s*:\s*([^;]+)/g,
            (_match: string, prop: string, value: string): string => {
                if (prop === 'family') {
                    fontDef.family = slugify(value.trim());
                } else if (prop === 'weight') {
                    fontDef.weight = value.trim();
                }
                return '';
            }
        );

        // Create unique key for font
        const fontKey = `${fontDef.family}-${fontDef.weight}`;

        if (!Array.from(fontRules).some(rule => rule.includes(fontKey))) {
            fontRules.add(fontFaceRule);
        }
    };

    /**
     * Process CSS rules
     * @param rule - CSS rule to process
     */
    const processRule = (rule: string): void => {
        if (rule.includes('font-face')) {
            processFontFace(rule);
        } else {
            const trimmedRule = rule.trim();
            if (!importRules.has(trimmedRule)) {
                importRules.add(trimmedRule);
            }
        }
    };

    // Process the CSS content
    css = css.replace(
        /@import url\(([^)]+?)\);?|@font-face\s*{([^}]+?)}/g,
        (match: string, ...args: any[]): string => {
            if (!mediaRules.has(match)) {
                processRule(match);
            }
            return '';
        }
    );

    // Remove placeholder comment
    css = css.replaceAll('/**ECOM-INSERT-CSS**/', '');

    // Combine all rules in the correct order
    return [
        ...Array.from(importRules),
        ...Array.from(fontRules),
        '/**ECOM-INSERT-CSS**/',
        css
    ].join('');
}

/**
 * Converts a string to a URL-friendly slug
 * @param str - String to convert
 * @returns Slugified string
 */
function slugify(str: string): string {
    return str
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)/g, '');
}

