export const minifyHTML = function (html: string) {
    return html
        .replace(/<!--(?!<!)[^\[>][\s\S]*?-->/g, '') // Remove HTML comments
        .replace(/>\s+</g, '><') // Remove whitespace between tags
        .replace(/\s{2,}/g, ' ') // Collapse multiple whitespace characters to a single space in text content
        .replace(/\s*=\s*/g, '=') // Remove whitespace around attribute equals signs
        .replace(/\s{2,}([a-zA-Z0-9-_]+="[^"]*")/g, ' $1') // Combine attributes separated by excess whitespace
        .replace(/\s([a-zA-Z0-9-_]+)=""/g, '') // Remove empty attributes (attributes with empty string values)
        .trim();
}


import { vendors } from '@/constants';
const createVendor = function (name) {
    let ifr = window.EComposerBuilder,
        stack = store.getters['builder/elementVendors'],
        url = vendors[name],
        type = url && url.match(/.js([?#]|$)/) ? 'js' :
        (url && url.match(/.css([?#]|$)/) ? 'css' : ''),
        key = 'vendor-' + type + '-' + name;
    if (
        type !== '' &&
        url &&
        ifr.contentWindow[key] === undefined
    ) {
        let elem = type == 'js' ?
            ifr.contentDocument.createElement('script') :
            ifr.contentDocument.createElement('link');
        elem.id = key;
        if (type == 'js') {
            elem.type = 'text/javascript';
            elem.src = url;
            elem.onerror = () => {
                store.commit('global/setToast', {
                    isError: true,
                    message: $t("the_js_resource_could_not_load",{name: vendors[name]}),
                    duration: 4000
                });
            };
            ifr.contentDocument.body.appendChild(elem);
        } else {
            elem.rel = 'stylesheet';
            elem.media = 'all';
            elem.href = url;
            ifr.contentDocument.head.appendChild(elem);
        }
        stack.load[name] = false;
        elem.onload = () => {
            stack.load[name] = true;
            elem.setAttribute('data-loaded', 'true');
        };
    }
};

export const loadVendors = function(vendors, element) {
    let stack = store.getters['builder/elementVendors'];
    stack.register[element] = [];
    vendors.forEach(name => {
        createVendor(name);
        if (stack.register[element].indexOf(name) === -1) {
            stack.register[element].push(name);
        }
    });
}

