export const parseQueryParams = (params:Object):Object => {
    const params_data = Object.assign({}, params);

    if (params_data.hasOwnProperty("hmac")) {
        delete params_data.hmac;
    }
    if (params_data.hasOwnProperty("id_token")) {
        delete params_data.id_token;
    }
    if (params_data.hasOwnProperty("session")) {
        delete params_data.session;
    }

    return params_data;
}

const isFlexContainerBlock = (block) => {
    return block?.name === "flexContainer" && Array.isArray(block.blocks);
};

const getNavigatorContainerRow = (block) => {
    if (!block) return null;
    if (block.row) return block.row;
    if (isFlexContainerBlock(block)) return block;
    if (block.name?.toLowerCase() === "row") return block;
    return null;
};

const isElementSearched = (block, searchVal) => {
    if (block.title) {
        return block.title.toLowerCase().indexOf(searchVal.toLowerCase()) > -1;
    } else if (block.name) {
        return block.name.toLowerCase().indexOf(searchVal.toLowerCase()) > -1;
    } else {
        return false;
    }
}

export type IsSearchedAtLeast = {
    isSectionSearched: boolean;
}

/**
 * Filter blocks for grid layout (blocks directly in row)
 * @param blocks array of blocks
 * @param searchVal search value
 * @param isSearchedAtLeast search result tracker
 */
const filterGridBlocks = (blocks, searchVal, isSearchedAtLeast) => {
    for (let j = 0; j < blocks.length; j++) {
        const block = blocks[j];
        const containerRow = getNavigatorContainerRow(block);

        if (containerRow) {
            if (containerRow.title && containerRow.title.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
                containerRow.isNavigatorSearchResult = true; // mark this item is matched
                block.isNavigatorSearchResult = true; // mark this item is matched
                isSearchedAtLeast.isSectionSearched = true; // in section we found at least 1 elements
            }

            filterElementsFromRowDataNavigator(searchVal, containerRow, isSearchedAtLeast);

            // Remove all empty rows / flex containers
            if (!containerRow.isNavigatorSearchResult &&
                (!containerRow.columns?.length && !containerRow.blocks?.length)) {
                blocks.splice(j, 1);
                j--;
            }
        } else {
            if (isBlockGroup(block)) {
                if (block.title?.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
                    block.isNavigatorSearchResult = true; // mark this item is searched
                    block.isAtLeastGroupSearched = false; // this flag to mark at least one item is searched in group block
                    isSearchedAtLeast.isSectionSearched = true; // in section we found at least 1 elements
                }

                const groupItems = block.group.settings.items;
                for(let k = 0; k < groupItems.length; k++) {
                    const groupItem = groupItems[k];
                    filterGroupColumn(groupItem, searchVal, block);
                }

                // Remove all item in group with blocks empty
                block.group.settings.items = groupItems.filter(item => item.blocks?.length > 0 || item.isNavigatorSearchResult);

                // if group block has at least found one element, we mark at least matched in section
                if (block.isAtLeastGroupSearched) {
                    isSearchedAtLeast.isSectionSearched = true;
                }

            } else if (isElementSearched(block, searchVal)) {
                block.isNavigatorSearchResult = true; // mark this item is matched
                isSearchedAtLeast.isSectionSearched = true; // in section we found at least 1 elements

            } else {
                // Remove elements that not match with search value
                blocks.splice(j, 1);
                j--;
            }
        }
    }

    // Remove all block which is group and don't have any child inside was matched and it self was not matched
    return blocks.filter(block => !(isBlockGroup(block) && !block.isAtLeastGroupSearched && !block.isNavigatorSearchResult));
};

/**
 * Filter elements from row data in Navigator Bar
 * @param searchVal search value
 * @param row row data
 */
export const filterElementsFromRowDataNavigator = (searchVal, row, isSearchedAtLeast: IsSearchedAtLeast) => {
    // Check if this is grid layout (has blocks directly) or struct layout (has columns)
    if (row.blocks && row.blocks.length > 0) {
        // Grid / flex layout: filter blocks directly.
        // Title match on the row/section itself is handled by the caller (isSearched);
        // do not set isSectionSearched here — that flag means "matched children inside".
        if (row.title?.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
            row.isNavigatorSearchResult = true;
        }

        row.blocks = filterGridBlocks(row.blocks, searchVal, isSearchedAtLeast);

    }
    else if (row.columns && row.columns.length > 0) {
        // Struct layout: use existing logic with columns

        for (let i = 0; i < row.columns.length; i++) {
            const col = row.columns[i];

                // Filter elements in column
                if (col.title && col.title.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
                col.isNavigatorSearchResult = true; // mark this item is searched
                isSearchedAtLeast.isSectionSearched = true; // in section we found at least 1 elements
            }

            if (col.blocks && col.blocks.length > 0) {
                col.blocks = filterGridBlocks(col.blocks, searchVal, isSearchedAtLeast);
            }

            // Remove all empty columns and it self is not matched
            if (!col.isNavigatorSearchResult && (!col.blocks || col.blocks.length === 0)) {
                row.columns.splice(i, 1);
                i--;
            }
        }
    }
};

export const filterGroupColumn = (col, searchVal, groupBlock) => {
    const filterGroupRow = (searchVal, row) => {
        for (let i = 0; i < row.columns.length; i++) {
            // Filter elements in column
            const col = row.columns[i];
            filterGroupColumn(col, searchVal, groupBlock);

            col.blocks = col.blocks.filter(block => (block.isNavigatorSearchResult));

            // Remove all empty columns
            if (!col.isNavigatorSearchResult && (!col.blocks || col.blocks.length === 0)) {
                row.columns.splice(i, 1);
                i--;
            }
        }
    };

    // ------------- Start filter -------------
    if (col.title?.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
        col.isNavigatorSearchResult = true;
        groupBlock.isAtLeastGroupSearched = true; // mark at least item is searched in group block
    }

    for (let j = 0; j < col?.blocks?.length || 0; j++) {
        const block = col.blocks[j];

        const containerRow = getNavigatorContainerRow(block);

        if (containerRow) {
            if (containerRow.title?.toLowerCase().indexOf(searchVal.toLowerCase()) > -1) {
                containerRow.isNavigatorSearchResult = true;
                block.isNavigatorSearchResult = true;
                groupBlock.isAtLeastGroupSearched = true; // mark at least item is searched in group block
            }

            if (containerRow.columns?.length) {
                filterGroupRow(searchVal, containerRow);
            } else if (containerRow.blocks?.length) {
                const nestedSearched: IsSearchedAtLeast = { isSectionSearched: false };
                containerRow.blocks = filterGridBlocks(containerRow.blocks, searchVal, nestedSearched);
                if (nestedSearched.isSectionSearched) {
                    groupBlock.isAtLeastGroupSearched = true;
                }
            }

            // Remove all empty rows / flex containers
            if (!containerRow.isNavigatorSearchResult &&
                (!containerRow.columns?.length && !containerRow.blocks?.length)) {
                col.blocks.splice(j, 1);
                j--;
            }
        } else {
            if (isElementSearched(block, searchVal)) {
                block.isNavigatorSearchResult = true;
                groupBlock.isAtLeastGroupSearched = true; // mark at least item is searched in group block
            } else {
                // Remove elements that not match with search value
                col.blocks.splice(j, 1);
                j--;
            }
        }
    }
}

export const isNavigatorSearchEmpty = (emptySections: any[]): boolean => {
    return (
        !emptySections ||
        emptySections.length === 0 ||
        emptySections.every(
            (emptySection) =>
                !emptySection ||
                ((!emptySection.columns || emptySection.columns.length === 0) &&
                    (!emptySection.blocks || emptySection.blocks.length === 0))
        )
    );
};

export const showAndHideElement = (elem, inputId): boolean => {
    if (elem.visibility === undefined) {
        elem.visibility = true;
    }
    if (elem.id === inputId)  {
        elem.visibility = !elem.visibility;
        return true;
    }
    return false;
}

export const toggleVisibleElement = (sections, eleId): void => {
    function toggleVisibleRow (row, eleId) {
        function toggleCol (col) {
            if (showAndHideElement(col, eleId)) return;

            for (let j = 0; j < col?.blocks?.length || 0; j++) {
                const block = col.blocks[j];
                if (showAndHideElement(block, eleId)) return;

                if (block.name?.toLowerCase() === "row" || block.row) {
                    if (showAndHideElement(block.row, eleId)) return;
                    toggleVisibleRow(block.row, eleId);

                } else if (isBlockGroup(block)) {
                    const groupItems = block.group.settings.items;
                    for(let k = 0; k < groupItems.length; k++) {
                        toggleCol(groupItems[k]);
                    }
                }
            }
        }

        for (let i = 0; i < row.columns.length; i++) {
            const col = row.columns[i];
            toggleCol(col);
        }
    }

    for (let i = 0; i < sections.length ; i++) {
        const section = sections[i];
        if (showAndHideElement(section, eleId)) return;
        toggleVisibleRow(section, eleId);
    }
};

export const renameItem = (elem, inputId, newName): boolean => {
    if (elem.id === inputId)  {
        elem.title = newName
        return true;
    }
    return false;
}

export const renameElement = (sections, eleId, newName): void => {
    function renameRow (row, eleId) {
        function renameCol (col) {
            if (renameItem(col, eleId, newName)) return;

            for (let j = 0; j < col?.blocks?.length || 0; j++) {
                const block = col.blocks[j];
                if (renameItem(block, eleId, newName)) return;

                if (block.name?.toLowerCase() === "row" || block.row) {
                    if (renameItem(block.row, eleId, newName)) return;
                    renameRow(block.row, eleId);

                } else if (isBlockGroup(block)) {
                    const groupItems = block.group.settings.items;
                    for(let k = 0; k < groupItems.length; k++) {
                        renameCol(groupItems[k]);
                    }
                }
            }
        }

        for (let i = 0; i < row.columns.length; i++) {
            const col = row.columns[i];
            renameCol(col);
        }
    }

    for (let i = 0; i < sections.length ; i++) {
        const section = sections[i];
        if (renameItem(section, eleId, newName)) return;
        renameRow(section, eleId);
    }
};


export const expandAllItemsInSection = (row, expand) => {
    // Handles a flat list of blocks, used both for column blocks (struct layout)
    // and for blocks sitting directly on a section/row (flex/grid layout)
    const expandBlocks = (blocks) => {
        for (let j = 0; j < blocks?.length || 0; j++) {
            const block = blocks[j];

            const containerRow = getNavigatorContainerRow(block);

            if (containerRow) {
                expand[containerRow.id] = (containerRow.columns?.length > 0) || (containerRow.blocks?.length > 0);
                expandAllItemsInSection(containerRow, expand);
            } else if (isBlockGroup(block)) {
                expand[block.id] = block.group.settings.items.length > 0;
                const groupItems = block.group.settings.items;

                for(let k = 0; k < groupItems.length; k++) {
                    const groupItem = groupItems[k];
                    groupItem.isGroupItem = true;
                    expandItemsInCol(groupItem);
                }
            }
        }
    }

    const expandItemsInCol = (col) => {
        expand[col.id] = col.blocks?.length > 0;
        expandBlocks(col.blocks);
    }

    if (row.isSection) expand[row.id] = true;

    if(row.columns) {
        for (let i = 0; i < row.columns.length; i++) {
            const col = row.columns[i];
            expandItemsInCol(col);
        }
    }

    // Flex/grid layout: blocks sit directly on the row/section, not under columns
    if (row.blocks) {
        expandBlocks(row.blocks);
    }
}

export const addColumnTitleAndRowTitle = (row) => {
    const addColumnTitleTitle = (col, i) => {
        if (!col.isGroupItem && !col.title) col.title = `Column ${i + 1}`;

        for (let j = 0; j < col?.blocks?.length || 0; j++) {
            const block = col.blocks[j];

            const containerRow = getNavigatorContainerRow(block);

            if (containerRow) {
                if (!containerRow.title) {
                    containerRow.title = containerRow.name === "flexContainer" ? "Flex Container" : "Inner row";
                }
                addColumnTitleAndRowTitle(containerRow);
            } else if (isBlockGroup(block)) {
                const groupItems = block.group.settings.items;

                for(let k = 0; k < groupItems.length; k++) {
                    const groupItem = groupItems[k];
                    groupItem.isGroupItem = true;
                    if (!groupItem.title) groupItem.title = `Item ${k + 1}`;
                    addColumnTitleTitle(groupItem, k);
                }
            }
        }
    }
    if(row?.columns) {
        for (let i = 0; i < row.columns.length; i++) {
            const col = row.columns[i];
            addColumnTitleTitle(col, i)
        }
    }

    if (row?.blocks?.length) {
        for (let j = 0; j < row.blocks.length; j++) {
            const block = row.blocks[j];
            const containerRow = getNavigatorContainerRow(block);

            if (containerRow) {
                if (!containerRow.title) {
                    containerRow.title = containerRow.name === "flexContainer" ? "Flex Container" : "Inner row";
                }
                addColumnTitleAndRowTitle(containerRow);
            } else if (isBlockGroup(block)) {
                const groupItems = block.group.settings.items;

                for(let k = 0; k < groupItems.length; k++) {
                    const groupItem = groupItems[k];
                    groupItem.isGroupItem = true;
                    if (!groupItem.title) groupItem.title = `Item ${k + 1}`;
                    addColumnTitleTitle(groupItem, k);
                }
            }
        }
    }
}

export const isBlockGroup = (block) => {
    return block.group && block.group.control;
}

export const downloadJSON = (data, filename = 'data.json') => {
    const jsonStr = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
}
interface BaseObject {
  id?: string | number;
  group?: any;
  sections?: any[];
  columns?: any[];
  blocks?: any[];
  items?: any[];
  row?: any[];
  [key: string]: any;
}

export const keepOnlyIds = (obj: any): BaseObject | BaseObject[] | null => {
  // Handle null or undefined
  if (!obj) return null;

  // Handle arrays
  if (Array.isArray(obj)) {
    const arrResult = obj.map(item => keepOnlyIds(item))
      .filter((item): item is BaseObject => item !== null);
    return arrResult.length > 0 ? arrResult : null;
  }

  // Handle objects
  if (typeof obj === 'object') {
    const result: BaseObject = {};

    // Keep the id if it exists
    if (obj.id) {
      result.id = obj.id;
    }

    // Handle group object specially
    if (obj.group) {
      result.group = keepOnlyIds(obj.group);
    }

    // Recursively process nested objects
    for (const key in obj) {
      if ([
        'sections',
        'columns',
        'blocks',
        'items',
        'row'
      ].includes(key)) {
        const processed = keepOnlyIds(obj[key]);
        if (processed !== null) {
          result[key] = processed;
        }
      }
    }

    return Object.keys(result).length > 0 ? result : null;
  }

  return null;
};
export function transformData(input) {
    const output = {};

  // Hàm để trích xuất dữ liệu có id và thêm vào output
  function extractData(item) {
    if (item && item.id) {
      output[item.id] = { ...item };
      delete output[item.id].id;  // Xóa thuộc tính id khỏi đối tượng kết quả
    }
  }

  // Hàm duyệt qua blocks và columns
  function traverseColumns(columns) {
    if (Array.isArray(columns)) {
      columns.forEach((column) => {
        extractData(column);  // Lấy id từ column

        // Duyệt qua blocks trong mỗi column
        if (Array.isArray(column.blocks)) {
          column.blocks.forEach((block) => {
            extractData(block);  // Lấy id từ block

            // Kiểm tra nếu block có group và duyệt tiếp
            if (block.group) {
              extractData(block.group);
            }

            // Kiểm tra nếu block có row và duyệt tiếp
            if (block.row) {
              extractData(block.row);
              traverseColumns(block.row.columns); // Duyệt các column trong row
            }
          });
        }
      });
    }
  }

  // Duyệt qua các sections
  if (Array.isArray(input)) {
    input.forEach((section) => {
      extractData(section);  // Lấy id từ section
      if (section.columns) {
        traverseColumns(section.columns);  // Duyệt qua các columns trong section
      }
    });
  }

  return output;
}
export function debounce(fn: Function, delay = 300) {
    let timeoutId: ReturnType<typeof setTimeout>;
    return function (this: any, ...args: any[]) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => fn.apply(this, args), delay);
    };
  }
export function throttle (func: Function, wait: number){
    let lastCall = 0;
    return function(...args: any[]) {
        const now = Date.now();
        if (now - lastCall < wait) return;
        lastCall = now;
        return func(...args);
    };
};
