function isCommaPressed(e: KeyboardEvent): boolean {
        return (
                (navigator.platform.toUpperCase().indexOf("MAC") >= 0 && e.metaKey) ||
                (navigator.platform.toUpperCase().indexOf("WIN") >= 0 && e.ctrlKey)
        );
}

function stripHTML(html: string): string {
    const div = document.createElement("div");
    div.innerHTML = html;
    return div.textContent || div.innerText || "";
}

function formatNumber(number: number, locale?: string) {
    return number.toLocaleString(locale, {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0
    });
}

function formatNumberAbbreviated(number: number, digits = 2): string {
    if (number < 1000) {
        return number.toString();
    }
    const abbreviations = [
        { value: 1e12, symbol: 't' }, // trillion
        { value: 1e9, symbol: 'b' },  // billion
        { value: 1e6, symbol: 'm' },  // million
        { value: 1e3, symbol: 'k' }   // thousand
    ];
    if (digits < 0) {
        digits = 0;
    }
    for (const { value, symbol } of abbreviations) {
        if (number >= value) {
            let formatted = (number / value).toFixed(digits);
            while (formatted.endsWith('0')) {
                formatted = formatted.slice(0, -1);
            }
            if (formatted.endsWith('.')) {
                formatted = formatted.slice(0, -1);
            }
            return formatted + symbol;
        }
    }

    return number.toString();
}
export function getScaleFactor() {
    // Cách 1: Tính từ DOM - tìm element trực tiếp
    const mainWrapper = document.querySelector('.ecom-builder_main-wrapper');

    if (mainWrapper) {
        const transform = window.getComputedStyle(mainWrapper).transform;

        if (transform && transform !== 'none') {
            const matrix = transform.match(/matrix\(([^)]+)\)/);
            if (matrix) {
                const values = matrix[1].split(',');
                const scaleFactor = parseFloat(values[0]);
                return scaleFactor;
            }
        }
    }

    // Cách 2: Tính từ container width (tương tự logic trong updateIframeScale)
    const mainBuilder = document.getElementById("ecom-main-builder");
    const screen = store.getters['builder/currentScreen'];
    if (mainBuilder && screen.name === "desktop") {
        const containerWidth = mainBuilder.clientWidth;

        if (containerWidth < 1440) {
            const calculatedScale = containerWidth / 1440;
            return calculatedScale;
        }
    }

    return 1;
}

export const capitalize = (str: string) => {
    if (!str || typeof str !== 'string') {
        return '';
    }
    return str.charAt(0).toUpperCase() + str.slice(1);
};

/**
 * Group preset của element trong allPresets (name = slug category).
 * Admin lưu slug qua Str::slug() nên bị lowercase (shopifyContactForm → shopifycontactform)
 * còn tên element giữ camelCase → ưu tiên khớp chính xác, không có mới so không phân biệt hoa/thường.
 */
export const findPresetGroup = (presets: any[] | null | undefined, name: string | null | undefined) => {
    if (!name || !Array.isArray(presets)) {
        return undefined;
    }
    const key = String(name).toLowerCase();
    return presets.find((item) => item?.name === name)
        ?? presets.find((item) => String(item?.name ?? '').toLowerCase() === key);
};

export function getQuickToolBarSettings(element: Record<string, any>) {
    if (!element) {
        return {
            elementId: null,
            elementName: null,
            settings: [],
            style: []
        };
    }

    const quickToolBarNames = typeof element.quickToolBar === 'function'
        ? element.quickToolBar()
        : (typeof element.$options?.methods?.quickToolBar === 'function'
            ? element.$options.methods.quickToolBar.call(element)
            : null);

    if (!Array.isArray(quickToolBarNames) || quickToolBarNames.length === 0) {
        return {
            elementId: null,
            elementName: null,
            settings: [],
            style: []
        };
    }

    const extractByNames = (config: any, names: string[], groupContext: any = null, foundNames: Set<string>): any[] => {
        const result: any[] = [];
        if (!config || typeof config !== 'object') {
            return result;
        }

        if (Array.isArray(config)) {
            config.forEach(item => extractByNames(item, names, groupContext, foundNames).forEach(r => result.push(r)));
        } else {
            const currentGroupContext = {
                group_title: config.group_title || config.options?.group_title || groupContext?.group_title || '',
                group_name: config.group_name || config.group_alias || groupContext?.group_name || ''
            };

            if (config.name && (names.includes(config.name) || names.some(n => config.name === n + 'normalmode'))) {
                if (!foundNames.has(config.name)) {
                    foundNames.add(config.name);
                    result.push({
                        ...config,
                        group_title: currentGroupContext.group_title,
                        group_name: currentGroupContext.group_name
                    });
                }
            }

            Object.keys(config).forEach(key => {
                if (typeof config[key] === 'object' && config[key] !== null) {
                    extractByNames(config[key], names, currentGroupContext, foundNames).forEach(r => result.push(r));
                }
            });
        }
        return result;
    };

    const foundNames = new Set<string>();

    const extractedSettings = extractByNames(element.fieldSettings || [], quickToolBarNames, null, foundNames);
    const extractedStyle = extractByNames(element.fieldStyle || [], quickToolBarNames, null, foundNames);

    // Sort results by the order specified in quickToolBarNames
    const sortByNames = (items: any[]) => {
        return items.sort((a, b) => {
            const baseNameA = a.name?.replace(/normalmode$/, '') || '';
            const baseNameB = b.name?.replace(/normalmode$/, '') || '';
            const indexA = quickToolBarNames.indexOf(baseNameA) !== -1 ? quickToolBarNames.indexOf(baseNameA) : quickToolBarNames.indexOf(a.name);
            const indexB = quickToolBarNames.indexOf(baseNameB) !== -1 ? quickToolBarNames.indexOf(baseNameB) : quickToolBarNames.indexOf(b.name);
            return (indexA === -1 ? 999 : indexA) - (indexB === -1 ? 999 : indexB);
        });
    };

    return {
        elementId: element.data?.id,
        elementName: element.is || element.$options?.name,
        settings: sortByNames(extractedSettings),
        style: sortByNames(extractedStyle)
    };
}

export function compareObjectsShallow(obj1: Object, obj2: Object) {
    const keys1 = Object.keys(obj1);
    const keys2 = Object.keys(obj2);

    if (keys1.length !== keys2.length) {
        return false;
    }

    for (let key of keys1) {
        if (obj1[key] !== obj2[key]) {
            return false;
        }
    }

    return true;
}

/**
 * Check if document is RTL based on direction and language
 * @param {Document} doc - Document to check (default: window.document or document)
 * @returns {boolean} - true if RTL, false otherwise
 */
export function checkIsRTL(doc?: Document): boolean {
    const document = doc || (typeof window !== 'undefined' ? window.document : document);
    if (!document) return false;

    // RTL languages list (from i18n plugin)
    const rtlLanguages = ['ar', 'arc', 'dv', 'fa', 'ha', 'he', 'khw', 'ks', 'ku', 'ps', 'ur'];

    // Check direction from HTML attributes
    const htmlDir = document.documentElement?.dir ||
                    document.documentElement?.getAttribute('dir') ||
                    document.querySelector('html')?.getAttribute('dir');

    if (htmlDir === 'rtl') return true;

    // Check direction from body
    const bodyDir = document.body?.dir || document.body?.getAttribute('dir');
    if (bodyDir === 'rtl') return true;

    // Check computed style direction
    if (document.documentElement) {
        const computedDir = window.getComputedStyle(document.documentElement).direction;
        if (computedDir === 'rtl') return true;
    }

    if (document.body) {
        const computedBodyDir = window.getComputedStyle(document.body).direction;
        if (computedBodyDir === 'rtl') return true;
    }

    // Check language attribute
    const lang = document.documentElement?.lang ||
                 document.documentElement?.getAttribute('lang') ||
                 document.querySelector('html')?.getAttribute('lang');

    if (lang && rtlLanguages.includes(lang.toLowerCase())) {
        return true;
    }

    return false;
}

