<template>
    <div class="flex gap-1">
        <!-- File size filter -->
        <Popover
            :open="isFilterPanelOpen('file_size')"
            @close="toggleFilterPanel('file_size')"
            preferredPosition="bottom"
            preferredAlignment="end"
            :contentClass="'w-[300px] bg-white rounded-lg popover-shadow p-4 flex flex-col gap-2'"
            :arrowClass="'bg-white h-2 w-2 border border-gray-150 top-1 left-1'"
        >
            <template #trigger>
                <button @click="toggleFilterPanel('file_size')"
                    class="h-[22px] border-dashed border-0.5 border rounded-lg font-normal text-text-primary pl-2 pr-1 hover:border-solid flex gap-0.5 items-center active:bg-surface-secondary"
                    :class="{ '!border-solid': hasSizeFilter }">
                    <span class="w-max text-xs">{{ fileSizeDisplayText }}</span>
                    <ecom-icon v-if="hasSizeFilter" :source="icons.CancelMajor" @click.stop="resetSizeFilters" class="text-icon flex" size="w-4 h-4" />
                    <ecom-icon v-else :source="icons.CaretDownMinor" class="text-icon flex" size="w-4 h-4" />
                </button>
            </template>
            <template #default>
                <div :key="rerenderSizeKey" class="flex flex-col gap-2">
                    <s-number-field label="Min size (MB)" :value="filters.minSize" min="0" name="min_size" @input="handleMinSizeInput">
                    </s-number-field>
                    <s-number-field label="Max size (MB)" :value="filters.maxSize" min="0" name="max_size" @input="handleMaxSizeInput">
                    </s-number-field>
                </div>
                <button class="hover:underline text-[#005bd3] w-fit text-sm disabled:text-[#b5b5b5]" @click="resetSizeFilters" :disabled="!hasSizeFilter">Clear</button>
            </template>
        </Popover>
        
        <!-- Used in filter -->
        <Popover
            :open="isFilterPanelOpen('used_in')"
            @close="toggleFilterPanel('used_in')"
            preferredPosition="bottom"
            preferredAlignment="end"
            :contentClass="'w-[300px] bg-white rounded-lg popover-shadow p-4 flex flex-col gap-2'"
            :arrowClass="'bg-white h-2 w-2 border border-gray-150 top-1 left-1'"
        >
            <template #trigger>
                <button @click="toggleFilterPanel('used_in')"
                    class="h-[22px] border-dashed border-0.5 border rounded-lg font-normal text-text-primary pl-2 pr-1 hover:border-solid flex gap-0.5 items-center active:bg-surface-secondary"
                    :class="{ '!border-solid': hasUsedInFilter }">
                    <span class="w-max text-xs">{{ usedInDisplayText }}</span>
                    <ecom-icon v-if="hasUsedInFilter && selectProducts.length == 0" :source="icons.CancelMajor" @click.stop="resetUsedInFilters" class="text-icon flex" size="w-4 h-4" />
                    <ecom-icon v-else :source="icons.CaretDownMinor" class="text-icon flex" size="w-4 h-4" />
                </button>
            </template>
            <template #default>
                <s-choice-list label="Used in" name="Used in"
                    @change="handleUsedInChange"
                    :values="getUsedInValues()"
                    :disabled="filters.products?.length > 0">
                    <s-choice value="product">Product Media</s-choice>
                    <s-choice value="none">Other</s-choice>
                </s-choice-list>
                <button class="hover:underline text-[#005bd3] w-fit text-sm disabled:text-[#b5b5b5]" @click="resetUsedInFilters" :disabled="filters.products?.length > 0 || !hasUsedInFilter">Clear</button>
            </template>
        </Popover>

        <!-- Product -->
        <Popover
            :open="isFilterPanelOpen('product')"
            @close="toggleFilterPanel('product')"
            preferredPosition="bottom"
            preferredAlignment="end"
            :contentClass="'w-[300px] bg-white rounded-lg popover-shadow p-4 flex flex-col gap-2'"
            :arrowClass="'bg-white h-2 w-2 border border-gray-150 top-1 left-1'"
        >
            <template #trigger>
                <button @click="openProductFilter"
                    class="h-[22px] max-w-[350px] border-dashed border-0.5 border rounded-lg font-normal text-text-primary pl-2 pr-1 hover:border-solid flex gap-0.5 items-center active:bg-surface-secondary"
                    :class="{ '!border-solid': selectProducts.length > 0 }">
                    <span class="w-max text-xs whitespace-nowrap truncate">{{ productDisplayText }}</span>
                    <ecom-icon v-if="selectProducts.length > 0" :source="icons.CancelMajor" @click.stop="resetProductFilters" class="text-icon flex" size="w-4 h-4" />
                    <ecom-icon v-else :source="icons.CaretDownMinor" class="text-icon flex" size="w-4 h-4" />
                </button>
            </template>
            <template #default>
                <s-search-field labelAccessibilityVisibility="exclusive" placeholder="Search for products" @input="handleSearchInput" :disabled="filters.usedIn == 'none'" :value="searchValue" />
                <div v-if="!loadingProducts && (!loading?.loadmore || showmore)">
                    <div :key="rerenderKey">
                        <template v-for="product in selectProducts">
                            <s-checkbox
                                v-if="(searchValue && products.find((pd) => pd.id == product.id) != undefined) || !searchValue"
                                checked="true"
                                :label="product.name"
                                :name="product.id"
                                @change="handleSelectProduct"
                                :disabled="filters.usedIn == 'none'"
                            />
                        </template>
                    </div>
                    <template v-if="products.length > 0" v-for="product in products">
                        <s-checkbox
                            v-if="!product?.unchecked"
                            :label="product.name"
                            :name="product.id"
                            @change="handleSelectProduct"
                            :disabled="filters.usedIn == 'none'"
                        />
                    </template>
                    <div v-else class="text-sm text-text-primary">
                        No products found
                    </div>
                    <button 
                        v-if="isNext" class="hover:underline text-[#005bd3] w-fit text-sm mt-3" @click="getProducts(false, true, false); showmore = true" 
                        :disabled="filters.usedIn == 'none'"
                    >
                        Show more products
                    </button>
                </div>
                <div v-else class="flex items-center justify-center my-2">
                    <s-spinner accessibilityLabel="Loading" size="base"></s-spinner>
                </div>
                <button class="hover:underline text-[#005bd3] w-fit text-sm disabled:text-[#b5b5b5]" @click="resetProductFilters" :disabled="selectProducts.length == 0 || filters.usedIn == 'none'">Clear</button>
            </template>
        </Popover>

        <!-- Clear all -->
        <button
            v-if="hasSizeFilter || hasUsedInFilter || selectProducts.length > 0"
            class="font-medium text-xs text-text-primary w-fit px-2 py-1 rounded-lg hover:bg-[#0000000d] active:bg-[#00000014] ml-1"
            @click="resetSizeFilters();resetUsedInFilters();resetProductFilters()"
        >
            Clear all
        </button>
    </div>
</template>

<script>
import { mapGetters } from 'vuex';
import { CaretDownMinor, CancelMajor } from '@/assets/icons';
import Popover from "@/components/SideBar/AI/Popover.vue";

export default {
    components: {
        Popover
    },
    data() {
        return {
            icons: { CaretDownMinor, CancelMajor },
            activeFilterPanel: '',
            filters: {
                minSize: null,
                maxSize: null,
                usedIn: null,
                products: null
            },
            init: false,
            productsRequested: false,
            loadingProducts: false,
            products: [],
            selectProducts: [],
            searchValue: '',
            rerenderKey: 0,
            rerenderSizeKey: 0,
            timeout: null,
            showmore: true
        }
    },
    
    computed: {
        ...mapGetters('picker', { 'pickerData': 'data' }),
        ...mapGetters('picker', ['isLoadmore', 'scrollTop', 'loading', 'freeImgCat', 'search']),
        
        isNext() {
            return !this.init || this.isLoadmore('product', '');
        },

        fileSizeDisplayText() {
            const { minSize, maxSize } = this.filters;
            const hasMinSize = this.isValidFilterValue(minSize);
            const hasMaxSize = this.isValidFilterValue(maxSize);

            if (hasMinSize && hasMaxSize) {
                return `${minSize} MB - ${maxSize} MB`;
            } else if (hasMinSize) {
                return `Greater than ${minSize} MB`;
            } else if (hasMaxSize) {
                return `Less than ${maxSize} MB`;
            } else {
                return 'File size';
            }
        },
        
        usedInDisplayText() {
            const { usedIn } = this.filters;
            
            if (usedIn === 'product') return 'Product media';
            if (usedIn === 'none') return 'Other';
            return 'Used in';
        },
        
        hasSizeFilter() {
            return this.isValidFilterValue(this.filters.minSize) || this.isValidFilterValue(this.filters.maxSize);
        },
        
        hasUsedInFilter() {
            return this.isValidFilterValue(this.filters.usedIn);
        },

        productDisplayText() {
            return this.selectProducts.length > 0 ? `${this.selectProducts.map(product => product.name).join(', ')} base` : 'Product';
        }
    },
    
    methods: {
        toggleFilterPanel(panelName) {
            this.activeFilterPanel = this.activeFilterPanel === panelName ? '' : panelName;
        },

        // The product list only exists inside this popover, so fetch it the
        // first time the popover is opened. Loading it on mount cost every
        // picker open a second Shopify query that competed with the file list
        // for the same API budget, for a filter most merchants never touch.
        openProductFilter() {
            this.toggleFilterPanel('product');
            if (this.activeFilterPanel === 'product' && !this.productsRequested) {
                this.productsRequested = true;
                this.getProducts();
            }
        },
        
        isFilterPanelOpen(panelName) {
            return this.activeFilterPanel === panelName;
        },
        
        isValidFilterValue(value) {
            if (value === null || value === undefined || value === '') return false;
            if (Array.isArray(value)) return value.length > 0;
            if (typeof value === 'object') return Object.keys(value).length > 0;
            return true;
        },
        
        handleMinSizeInput(event) {
            const inputValue = event.currentTarget.value;
            this.setMinSize(inputValue === '' ? null : Number(inputValue));
        },
        
        handleMaxSizeInput(event) {
            const inputValue = event.currentTarget.value;
            this.setMaxSize(inputValue === '' ? null : Number(inputValue));
        },
        
        handleUsedInChange(event) {
            this.filters.usedIn = event.currentTarget.values[0];
        },
        
        setMinSize(value) {
            this.filters.minSize = value;
        },
        
        setMaxSize(value) {
            this.filters.maxSize = value;
        },
        
        getUsedInValues() {
            const { usedIn } = this.filters;
            return usedIn === '' ? [] : [usedIn];
        },
        
        resetSizeFilters() {
            this.filters.minSize = null;
            this.filters.maxSize = null;
            this.rerenderSizeKey++;
        },
        
        resetUsedInFilters() {
            this.filters.usedIn = null;
        },
        
        resetAllFilters() {
            Object.keys(this.filters).forEach(key => {
                this.filters[key] = null;
            });
        },
        
        getActiveFilters() {
            return Object.fromEntries(
                Object.entries(this.filters).filter(([, value]) => this.isValidFilterValue(value))
            );
        },

        getProducts(isSearch = false, loadMore = false, reload = false) {
            if (!loadMore) {
                this.loadingProducts = true;
            }
            const res = this.pickerData('product', '', this.searchValue, {}, loadMore, reload, 'asc');
            
            res.then((data) => {
                if (data.status === 'error') {
                    throw new Error(data.message);
                }
                if(!isSearch) {
                    this.products.splice(this.products.length, 0, ...data);
                } else {
                    this.products.splice( 0, this.products.length, ...data);
                    this.selectProducts.forEach(selectProduct => {
                        let product = this.products.find(product => product.id == selectProduct.id);
                        if(product) {
                            product.unchecked = true;
                        }
                    });
                }
                
                this.loadingProducts = false;
                this.$store.dispatch('picker/removeLoading');
                this.init = true;
            })
            .catch(e => {
                this.loadingProducts = false;
                // let the next open retry instead of leaving the popover empty
                this.productsRequested = false;
                this.$store.commit('global/setToast', {
                    isError: true,
                    message: e.message,
                    data: e,
                    duration: 4000
                });
            });
        },

        handleSelectProduct(event) {
            const id = event.currentTarget.name;
            const checked = event.currentTarget.checked;
            if(checked) {
                this.selectProducts.push(this.products.find(product => product.id == id));
                this.products.find(product => product.id == id).unchecked = true;
            } else {
                this.selectProducts = this.selectProducts.filter(product => product.id != id);
                this.products.find(product => product.id == id).unchecked = false;
                this.rerenderKey++;
            }
            this.filters.products = this.selectProducts.map(product => product.id);
        },

        resetProductFilters() {
            this.selectProducts = [];
            this.products.forEach(product => {
                product.unchecked = false;
            });
            this.filters.products = null;
        },

        handleSearchInput(event) {
            this.showmore = false;
            clearTimeout(this.timeout);
            const value = event.currentTarget.value;
            this.timeout = setTimeout(() => {
                this.searchValue = value;
                this.getProducts(true, false, false);
            }, 800);
        }
    },
    
    watch: {
        filters: {
            handler(newFilters) {
                const activeFilters = this.getActiveFilters();
                this.$emit('update', activeFilters);
            },
            deep: true
        }
    },

    beforeUnmount() {
        clearTimeout(this.timeout);
    },

}
</script>