function cssValueAndUnit(input: string) {
    const match = input.trim().match(/^([-+]?\d*\.?\d+)([a-zA-Z%]*)$/);
    if (match) {
        return {
            value: parseFloat(match[1]),
            unit: match[2] || null
        };
    } else {
        return null;
    }
}

function normalizeNumber(num: number, min?: number, max?: number, step?: number) {
    let val = num;
    if ('number' != typeof val || isNaN(val)) {
        return val;
    }
    if ('number' == typeof min && !isNaN(min) && val < min) {
        val = min;
    }
    if ('number' == typeof max && !isNaN(max) && val > max) {
        val = max;
    }
    if ('number' == typeof step && !isNaN(step) && step > 0) {
        val = Math.round(val / step) * step;
    }
    return val;
}

/**
 * Check if a value if a real object or not.
 * Array and null is not consider as an object although typeof statement returns 'object'
 * @param obj any
 * @return boolean
 */
export function isRealObject(obj: any): boolean {
    if (obj == null || typeof obj !== 'object') return false;
    if (Object.prototype.toString.call(obj) !== '[object Object]') return false;
    return Object.keys(obj).length > 0;
}

export function objEqual(obj1: object | null, obj2: object | null) {
    if (obj1 === obj2) {
        return true;
    }
    if (typeof obj1 !== 'object' || obj1 == null ||
        typeof obj2 !== 'object' || obj2 == null) {
        return false;
    }
    const keys1 = Object.keys(obj1);
    const keys2 = Object.keys(obj2);
    if (keys1.length !== keys2.length) {
        return false;
    }
    for (let key of keys1) {
        if (!obj2.hasOwnProperty(key)) {
            return false;
        }
        const child1 = obj1[key as keyof typeof obj1],
            child2 = obj2[key as keyof typeof obj2];
        if (isRealObject(child1)) {
            if (!isRealObject(child2) || !objEqual(child1, child2)) {
                return false;
            }
        } else if (Array.isArray(child1)) {
            if (!Array.isArray(child2) || !arrayEqual(child1, child2)) {
                return false;
            }
        } else if (!Object.is(child1, child2)) {
            return false;
        }
    }
    return true;
}

/**
 * Deep compare two arrays
 */
export function arrayEqual(array1: object | null, array2: object | null): boolean {
    if (!Array.isArray(array1) || !Array.isArray(array2) || array1.length != array2.length) {
        return false;
    }
    if (array1 === array2) {
        return true;
    }
    for (let index = 0; index < array1.length; index++) {
        if (Array.isArray(array1[index])) {
            if (!Array.isArray(array2[index]) || !arrayEqual(array1[index], array2[index])) {
                return false;
            }
        } else if (isRealObject(array1[index])) {
            if (!isRealObject(array2[index]) || !objEqual(array1[index], array2[index])) {
                return false;
            }
        } else if (!Object.is(array1[index], array2[index])) {
            return false;
        }
    }
    return true;
}

export function compareValues(value1: any, value2: any) {
    if (value1 === value2) {
        return true;
    }
    if (Array.isArray(value1) && Array.isArray(value2)) {
        if (value1.length !== value2.length) {
            return false;
        }
        return arrayEqual(value1, value2);
    }
    if (isRealObject(value1) && isRealObject(value2)) {
        return objEqual(value1, value2);
    }
    return false;
}

export function valueFromPath(o: object, s: string): any {
    s = s.replace(/\[(\w+)\]/g, '.$1'); // convert indexes to properties
    s = s.replace(/^\./, ''); // strip a leading dot
    var a = s.split('.');
    for (var i = 0, n = a.length; i < n; ++i) {
        var k = a[i];
        if (k in o) {
            o = o[k as keyof typeof o];
        } else {
            return;
        }
    }
    return o;
}

export function valueToPath(obj: Record<string | number, any>, path: string, value: any, update: boolean = true): void {
    path = path.replace(/\[(\w+)\]/g, '.$1'); // convert indexes to properties
    path = path.replace(/^\./, ''); // Remove leading dot

    const arr = path.split('.');
    for (let i = 0, n = arr.length; i < n; ++i) {
        let k = arr[i];

        // Convert numeric keys to numbers to support arrays
        const isArrayIndex = !isNaN(Number(k));
        if (isArrayIndex) k = Number(k) as any;

        if (i === n - 1) {
            if (value === undefined) {
                delete obj[k];
            } else if (update && typeof value === 'object' && value !== null && typeof obj[k] === 'object' && obj[k] !== null) {
                Object.assign(obj[k], value);
            } else {
                obj[k] = value;
            }
        } else {
            if (!(k in obj)) {
                obj[k] = isArrayIndex ? [] : {};
            }
            obj = obj[k];
        }
    }
}

/**
 * @param aiFields If the property key (block id) does not exist in the current sections, it will be deleted.
 * @param sections Array of sections
 */
export function setAIMarkupPaths(aiFields: AIFields | undefined, sections: Record<string, any>[]) {
    if (!aiFields || !sections) {
        return;
    }

    const ids = new Set(Object.keys(aiFields));
    const validIds = new Set<string>();

    // Collect all valid IDs from sections
    const collectIds = (data: Record<string, any> | Record<string, any>[]) => {
        if (typeof data !== "object" || data === null) return;

        if (Array.isArray(data)) {
            data.forEach(item => collectIds(item));
        } else {
            if (data.id) {
                validIds.add(data.id);
            }
            // Recursively check nested objects
            Object.values(data).forEach(value => {
                if (typeof value === "object" && value !== null) {
                    collectIds(value);
                }
            });
        }
    };

    sections.forEach(section => collectIds(section));

    const idsToDelete = new Set<string>();
    ids.forEach(id => {
        if (!validIds.has(id) || 'object' != typeof aiFields[id] || !Object.keys(aiFields[id]).length) {
            idsToDelete.add(id);
        }
    });
    idsToDelete.forEach(id => {
        ids.delete(id);
        delete aiFields[id];
    });
    const results: { [id: string]: string } = {};

    const findPath = (data: Record<string, any> | Record<string, any>[], path: string[] = [], includeFirstPath = true) => {
        if (typeof data !== "object" || data === null) {
            return;
        }

        const stack: { data: any; path: string[] }[] = [{ data, path: includeFirstPath ? path : [] }];

        while (stack.length) {
            const stackEntry = stack.pop();
            if (!stackEntry) {
                break;
            }
            const { data, path } = stackEntry;
            let lastPath = path.length ? path[path.length - 1].match(/^[^\[]+/)?.[0] || '' : '';
            if (!lastPath) {
                lastPath = 'sections';
            }
            if (Array.isArray(data)) {
                const basePath = path.length ? path.pop() : '';
                for (let i = 0; i < data.length; i++) {
                    stack.push({ data: data[i], path: [...path, `${basePath}[${i}]`] });
                }
            } else {
                if (data.id && ids.has(data.id)) {
                    const resultPath = [...path];
                    if ('group' in data && data.group && 'object' == typeof data.group
                        && 'settings' in data.group && Array.isArray(data.group.settings)) {
                        resultPath.push('group', 'settings');
                    } else {
                        resultPath.push('settings');
                    }
                    results[data.id] = resultPath.join('.');
                    Object.keys(aiFields[data.id]).forEach(k => {
                        aiFields[data.id][k].path = results[data.id];
                    });
                }
                for (const key in data) {
                    if (!data[key] || 'object' !== typeof data[key]) {
                        continue;
                    }
                    switch (lastPath) {
                        case 'sections':
                        case 'row':
                            if (!['blocks', 'columns'].includes(key)) {
                                continue;
                            }
                            break;
                        case 'columns':
                            if (!['blocks'].includes(key)) {
                                continue;
                            }
                            break;
                        case 'blocks':
                        case 'group':
                            if (!['settings', 'group', 'row'].includes(key)) {
                                continue;
                            }
                            break;
                    }
                    stack.push({ data: data[key], path: [...path, key] });
                }
            }
        }
    };

    sections.forEach((section, index) => {
        findPath(section, [`sections[${index}]`], sections.length > 1);
    });

    const resultKeys = new Set(Object.keys(results));
    resultKeys.forEach((key) => {
        if (!ids.has(key)) {
            delete aiFields[key];
        }
    });
}

export const randomNumber = (min: number, max: number) => {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

export const randomPick = <T>(arr: Array<T>) => {
    return arr[randomNumber(0, arr.length - 1)];
}

export function getAllFieldTypes() {
    // The allFields is a map of field names to field components, something like textareaField, textField, etc.
    return Object.keys(allFields).map((name) => {
        return name.endsWith('Field') ? name.slice(0, -5) : name;
    });
}

export function normalizeAIStringResponse(data: string) {
    if ('string' == typeof data) {
        if (data.startsWith('```json')) {
            data = data.substring(7);
        }
        if (data.endsWith('```')) {
            data = data.substring(0, data.length - 3);
        }
        if (data.startsWith('\n')) {
            data = data.substring(1);
        }
        if (data.endsWith('\n')) {
            data = data.substring(0, data.length - 1);
        }
        try {
            return JSON.parse(data);
        } catch (e) {
            console.error('Error parsing JSON:', e);
            return {};
        }
    } else {
        return data;
    }
}

/**
 * Process a field based on its type and parameters.
 * @param currentValue - The current value of the field.
 * @param params - The parameters of the field.
 * @param value - The value to process.
 */
export function normalizeFieldValue(currentValue: any, params?: Record<string, any>, value?: any) {
    if (!params) {
        return currentValue;
    }
    if ('popup' == params.type) {
        return normalizeFieldValue(currentValue, params.options, value);
    }
    if (isRealObject(value) && isRealObject(currentValue)) {
        value = {
            ...currentValue,
            ...value
        };
    }
    switch (params.type) {
        case 'choose': {
            let options = new Set(Array.isArray(params.options.values) ? params.options.values : []);
            if (!options.size && ['heading', 'rating'].includes(params.options.type)) {
                const type = params.options.type as 'heading' | 'rating';
                options = new Set(choices[type].map((item) => item.value));
            }
            if (/^-?\d+$/.test(value)) {
                value = parseInt(value, 10);
            } else if (/^-?\d+(\.\d+)?$/.test(value)) {
                value = parseFloat(value);
            }
            if (options.has(value)) {
                return value;
            }
            return currentValue;
        }
        case 'checkbox': {
            const options = params?.options?.values;
            if (!Array.isArray(value)) {
                if ('boolean' == typeof value) {
                    if (value) {
                        return Object.keys(options);
                    }
                    return undefined;
                }
                return currentValue;
            }
            if (value.length === 0) {
                return undefined;
            }
            if (isRealObject(options)) {
                let optionValues = Object.keys(options);
                return value.filter((key) => optionValues.includes(key));
            }
            return currentValue;
        }
        case 'dropdown': {
            const options = 'values' in params && 'object' == typeof params.values
                ? params.values
                : params.options?.values && 'object' == typeof params.options.values
                    ? params.options.values
                    : {};
            if (value in options) {
                return value;
            }
            if (params.default) {
                return params.default;
            }
            return currentValue;
        }
        case 'toggle': {
            const values = params.options?.values;
            if (values && isRealObject(values)) {
                if (value) {
                    return values.on?.value || true;
                }
                return values.off?.value || false;
            }
            return value || currentValue;
        }
        case 'border': {
            const curVal = currentValue && 'object' == typeof currentValue ? {...currentValue} : {};
            const newVal: {
                'border-width'?: {
                    top?: string;
                    right?: string;
                    bottom?: string;
                    left?: string;
                };
                'border-style'?: string;
                'border-color'?: string;
            } = {
                ...curVal
            };
            if (value['border-width']) {
                const borderWidth: typeof newVal['border-width'] = {};
                if (value['border-width']['top']) {
                    borderWidth.top = value['border-width']['top'];
                }
                if (value['border-width']['right']) {
                    borderWidth.right = value['border-width']['right'];
                }
                if (value['border-width']['bottom']) {
                    borderWidth.bottom = value['border-width']['bottom'];
                }
                if (value['border-width']['left']) {
                    borderWidth.left = value['border-width']['left'];
                }
                newVal['border-width'] = {
                    ...(curVal['border-width'] || {}),
                    ...borderWidth
                }
            }
            if (value['border-style']) {
                newVal['border-style'] = value['border-style'];
            }
            if (value['border-color']) {
                newVal['border-color'] = value['border-color'];
            }
            return newVal;
        }

        case 'typography': {
            const curVal = currentValue && 'object' == typeof currentValue ? {...currentValue} : {};
            const newVal: {
                "font-family"?: {
                    [key: string]: string;
                };
                "font-size"?: string;
                "font-weight"?: string;
                "text-transform"?: string;
                "font-style"?: string;
                "text-decoration"?: string;
                "line-height"?: string;
                "letter-spacing"?: string;
            } = {
                ...curVal
            };
            if (value["font-family"]) {
                newVal['font-family'] = value['font-family'];
            }
            if (value["font-size"]) {
                newVal['font-size'] = value['font-size'];
            }
            if (value["font-weight"]) {
                newVal['font-weight'] = value['font-weight'];
            }
            if (value["text-transform"]) {
                newVal['text-transform'] = value['text-transform'];
            }
            if (value["font-style"]) {
                newVal['font-style'] = value['font-style'];
            }
            if (value["text-decoration"]) {
                newVal['text-decoration'] = value['text-decoration'];
            }
            if (value["line-height"]) {
                newVal['line-height'] = value['line-height'];
            }
            if (value["letter-spacing"]) {
                newVal['letter-spacing'] = value['letter-spacing'];
            }
            return newVal;
        }
        case 'number': {
            let strVal = value != null ? value.toString(): '';
            const val = cssValueAndUnit(strVal);
            if (val && 'number' == typeof val.value) {
                val.value = normalizeNumber(val.value, params.options?.min, params.options?.max, params.options?.step);
                if ('string' == typeof val.unit) {
                    if ('string' == params.options?.unit) {
                        if (val.unit != params.options?.unit) {
                            val.unit = params.options.unit;
                        }
                    } else {
                        if (params.options?.units && isRealObject(params.options.units)) {
                            if (!(val.unit in params.options.units)) {
                                val.unit = Object.keys(params.options.units)[0];
                            }
                            if (val.unit) {
                                const { min, max, step } = params.options.units[val.unit];
                                val.value = normalizeNumber(val.value, min, max, step);
                            }
                        }
                    }
                } else {
                    if ('string' == params.options?.unit) {
                        val.unit = params.options.unit;
                    } else {
                        if (params.options?.units && isRealObject(params.options.units)) {
                            val.unit = Object.keys(params.options.units)[0];
                        }
                        if (val.unit) {
                            const { min, max, step } = params.options.units[val.unit as string]; // It is string here
                            val.value = normalizeNumber(val.value, min, max, step);
                        }
                    }
                }
                if (val.unit) {
                    return `${val.value}${val.unit}`;
                }
                return val.value;
            }
            return currentValue;
        }
        case 'picker': {
            return currentValue;
        }
        default: {
            return value;
        }
    }
};

export function getSettingParams(element: Record<string, any>, full?: boolean) {
    const elementSettings = 'function' == typeof element.settings
        ? element.settings()
        : element.settings || [];
    const aiFieldTypesExamples: {
        [type: string]: Record<string, any>
    } = {};

    return {
        settings: parseSettings(elementSettings, aiFieldTypesExamples, full),
        ...(Object.keys(aiFieldTypesExamples).length > 0 ? { aiFieldTypesExamples } : {})
    };
}

const parseSettings = (settings: Record<string, any>, aiFieldTypesExamples: {[type: string]: Record<string, any>}, full?: boolean) => {
    if (!settings) {
        return {};
    }
    let finalSettings: Record<string, any> = {};
    if (!Array.isArray(settings)) {
        return finalSettings;
    }
    settings.forEach((settings: Record<string, any>) => {
        const fields = settings.group_alias ? aliases(settings) : settings;
        if (!fields) {
            return;
        }
        if (Array.isArray(fields)) {
            console.error('Array fields are not supported!');
            return;
        }
        if (!('params' in fields) || !fields.params || !Array.isArray(fields.params)) {
            console.error('Settings has no params!');
            return;
        }
        const groupName = 'group_name' in fields && fields.group_name
            ? fields.group_name
            : ('name' in fields && fields.name)
                ? fields.name
                : undefined;
        const groupTitle = 'group_title' in fields && fields.group_title ? fields.group_title : undefined;

        fields.params.forEach((fParams) => {
            if (!fParams || 'string' !== typeof fParams.type) {
                return;
            }
            // Skip fields that only for organizing the settings
            if (['line', 'paragraph', 'heading'].includes(fParams.type)) {
                return;
            }
            const keys: string[] = [];
            if (groupName) {
                keys.push(groupName);
            }
            if (!fParams.name) {
                return;
            }
            keys.push(fParams.name);
            const settingsKey = keys.join('.');

            if (full) {
                finalSettings[settingsKey] = fParams;
            } else {
                if (!fParams.label) {
                    fParams.label = groupTitle || '';
                }
                finalSettings[settingsKey] = parseFieldParams(fParams, aiFieldTypesExamples, full);
            }
        });
    });
    return finalSettings;
}

const parseFieldParams = (fParams: Record<string, any>, aiFieldTypesExamples: {[type: string]: Record<string, any>}, full?: boolean) => {
    let aiSettings: {
        label: string;
        type: string;
        params?: Record<string, any>;
        options?: Record<string, any>;
        choices?: Record<string, any>;
        units?: Record<string, any>;
        responsive?: boolean;
        visible?: string;
    } = {
        label: helpers.stripHTML(fParams.label),
        type: fParams.type
    };

    if (fParams.params) {
        /* fParams.params.map((fParam: Record<string, any>) => {
            if ('popup' == fParam.type) {
                return {
                    label: helpers.stripHTML(fParam.label || aiSettings.label || ''),
                    type: fParam.options.type || fParam.type
                };
            }
            return {
                label: helpers.stripHTML(fParam.label || aiSettings.label || ''),
                type: fParam.type
            };
        }); */
    }

    if (fParams.options?.responsive) {
        aiSettings.responsive = fParams.options.responsive;
    }

    switch (fParams.type) {
        case 'group': {
            aiSettings.params = parseFieldParams([fParams], aiFieldTypesExamples, full);
            break;
        }
        case 'popup': {
            if (fParams.options.type) {
                if (fParams.options.type in popupTypes) {
                    // Do this later
                } else {
                    aiSettings = {
                        ...parseFieldParams({
                            ...fParams,
                            type: fParams.options.type || fParams.type
                        }, aiFieldTypesExamples, full),
                        label: aiSettings.label
                    };
                }
            }
            break;
        }
        case 'dropdown': {
            aiSettings.options = getDropdownOptions(fParams);
            break;
        }
        case 'choose': {
            aiSettings.choices = getChoices(fParams);
            break;
        }
        case 'checkbox': {
            const options = fParams?.options?.values || {};
            if (isRealObject(options)) {
                let finalOptions: {
                    value: string;
                    title: string;
                }[] = [];
                Object.keys(options).forEach((key) => {
                    finalOptions.push({
                        value: key,
                        title: options[key]
                    });
                });
                aiSettings.options = finalOptions;
                aiSettings.params = {
                    multiple: true
                }
            }
            if (!('checkbox' in aiFieldTypesExamples)) {
                aiFieldTypesExamples['checkbox'] = {
                    value: ['value1?', 'value2?', 'value3?'],
                    description: 'An array of option keys representing the checked options or an empty array if no options are checked'
                }
            }
            break;
        }
        case 'toggle': {
            const values = fParams.options?.values;
            if (values && isRealObject(values)) {
                let on = values.on?.value || true;
                if ('boolean' !== typeof on) {
                    let off = values.off?.value || '';
                    aiSettings.options = {
                        on,
                        off
                    }
                }
            }
            break;
        }
        case 'number': {
            if (fParams.options.units) {
                aiSettings.units = fParams.options.units;
            }
            break;
        }
        case 'picker': {
            if (fParams.options.type == 'image') {
                aiSettings.type = fParams.options.type;
                if (!('image' in aiFieldTypesExamples)) {
                    aiFieldTypesExamples['image'] = {
                        "name?": 'Image alt text',
                        "alt?": 'Image alt text',
                        "url?": 'https://via.placeholder.com/150',
                    };
                }
            }
            break;
        }
        default: {
            break;
        }
    }

    /**
     * TESTING ONLY - by manually adding conditions to the element settings
     */
    /* if (fParams.options?.visible) {
        aiSettings.visible = fParams.options.visible;
    } */
    /* if (fParams.conditions) {
        aiSettings.conditions = fParams.conditions;
    } */
    return aiSettings;
}

/** @see /src/plugins/fields/fields/dropdown/Dropdown.vue */
const getDropdownOptions = (fParams: Record<string, any>) => {
    if ('string' == typeof fParams.options?.type && fParams.options.type in dropdownTypes) {
        let ts = dropdownTypes[fParams.options.type as keyof typeof dropdownTypes] ?? [];
        if (
            ts.findIndex(x => x.name === '__delete__') === -1 &&
            ts.findIndex(x => x.title === $t('default')) === -1 &&
            fParams.options.default !== false
        ) {
            ts.splice(0, 0, { name: '__delete__', title: $t('default') });
        }
        return ts;
    }
    const add = (arr, obj) => {
        if (obj.constructor === Object) {
            let k;
            for (k in obj) {
                arr.push({
                    name: k,
                    title: obj[k]
                });
            }
        }
    };
    const optionsValue = fParams.options?.values ?? {};
    let type: Record<string, any>[] = [],
        k,
        value;
    if (optionsValue.constructor === Object) {
        add(type, optionsValue);
    }
    else if (optionsValue.constructor === Array) {
        for (k in optionsValue){
            value = optionsValue[k];
            if (value.constructor === Object) {
                type.push({...value});
                // if(value.values?.constructor === Object) {
                //     add(type, value.values);
                // }
            }
            else {
                type.push({name: value, title: value});
            }
        }
    }
    if (fParams.options?.default !== false &&
        type.findIndex(x => x.name === '__delete__') === -1 &&
        type.findIndex(x => x.title === $t('default')) === -1) {
        type.splice(0,0, {name: '__delete__', title: $t('default')});
    }
    return type;
}

const getChoices = (fParams: Record<string, any>) => {
    let result = structuredClone(choices);
    const type: string = 'string' == typeof fParams.options?.type ? fParams.options.type : 'align';
    if (type == 'heading' && fParams?.options?.modify) {
        const adds = fParams.options?.modify.add || [];
        const removes = fParams.options?.modify.remove || [];
        if (adds.length > 0) {
            adds.forEach((item) => {
                result.heading.push(item);
            })
        }
        if(removes.length > 0) {
            const valuesRemove = removes.map(item => item.value);
            const newHeadingTag = result.heading.filter(item => !valuesRemove.includes(item.value));
            result.heading = newHeadingTag;
        }
    }

    const values = Array.isArray(fParams.options?.values) ? fParams.options.values : [];

    if (type in result) {
        const prefChoices = result[type as keyof typeof result] as Record<string, any>[];
        if (values.length) {
            const options: Record<string, any>[] = [];
            if (prefChoices.length) {
                values.forEach((v: string, i: number) => {
                    if (isRealObject(prefChoices[i])) {
                        delete prefChoices[i].icon;
                    }
                    options.push({
                        ...(prefChoices[i] || {}),
                        value: v
                    })
                });
                return options;
            }
            return values;
        } else {
            return prefChoices;
        }
    }
    return [];
}

export async function aiRoute(route: string) {
    let url = null;
    try {
        url = new URL(route);
    } catch (e) {
        url = new URL(route, window.location.origin); 
    }
    if (window.ECOM_INIT.APPBRIDGE) {
        const token = await window.shopify.idToken();
        if (token) {
            url.searchParams.set('id_token', token);
        }
        let params = window.route().params;
        if (params.host) {
            url.searchParams.set('host', params.host);
        }
        if (params.shop) {
            url.searchParams.set('shop', params.shop);
        }
    }
    return url.href;
}

export const vueDeepClone = (obj: any, seen = new WeakMap()) => {
    // Unwrap Vue ref if needed
    if (isRef(obj)) obj = obj.value;

    // Handle raw values from Vue proxies
    obj = toRaw(obj);

    // Return primitive types or functions (not cloned)
    if (obj === null || typeof obj !== 'object') return obj;

    const objectType = Object.prototype.toString.call(obj);

    // Avoid browser/runtime objects that cannot be cloned safely.
    if (objectType === '[object Window]'
        || (typeof Window !== 'undefined' && obj instanceof Window)
        || (typeof Document !== 'undefined' && obj instanceof Document)
        || (typeof Node !== 'undefined' && obj instanceof Node)) {
        return null;
    }

    // Handle circular references
    if (seen.has(obj)) return seen.get(obj);

    // Handle Array
    if (Array.isArray(obj)) {
        let clone: Array<any> = [];
        seen.set(obj, clone);
        for (const item of obj) {
            clone.push(vueDeepClone(item, seen));
        }
        return clone;
    }

    // Handle Date
    if (obj instanceof Date) return new Date(obj.getTime());

    // Handle RegExp
    if (obj instanceof RegExp) return new RegExp(obj.source, obj.flags);

    // Handle Map
    if (obj instanceof Map) {
        let clone = new Map();
        seen.set(obj, clone);
        for (const [key, val] of obj.entries()) {
            clone.set(vueDeepClone(key, seen), vueDeepClone(val, seen));
        }
        return clone;
    }

    // Handle Set
    if (obj instanceof Set) {
        let clone = new Set();
        seen.set(obj, clone);
        for (const val of obj.values()) {
            clone.add(vueDeepClone(val, seen));
        }
        return clone;
    }

    // Handle plain objects
    let plainClone: Record<string, any> = {};
    seen.set(obj, plainClone);
    for (const key in obj) {
        let value;
        try {
            value = obj[key];
        } catch (e) {
            continue;
        }
        // Skip Vue internals
        if (key.startsWith('__v_') || typeof value === 'function' || typeof key === 'symbol') {
            continue;
        }
        plainClone[key] = vueDeepClone(value, seen);
    }

    return plainClone;
}
