{
    "en": {
        "click_to_edit": "Click to edit"
    },
    "fr": {
        "click_to_edit": "Cliquez pour modifier"
    },
    "de": {
        "click_to_edit": "Klicken, um zu bearbeiten"
    },
    "ja": {
        "click_to_edit": "編集するにはクリックしてください"
    }
}
</i18n>
<template>
    <div class="relative">
        <div
            v-if="unitsLength > 1"
            class="absolute right-0 flex mb-2 bottom-full heading-number"
            :class="unitPopoverId"
        >
            <button
                type="button"
                class="px-1.5 h-[19px] uppercase border-0 focus:outline-none focus:ring-0 min-w-6 text-tiny font-medium rounded bg-dark text-white text-[10px] flex items-center justify-between gap-2"
                @click="toggleUnitPopover"
            >
                {{ unit }}
                <svg width="8" height="6" viewBox="0 0 8 6" fill="none" xmlns="http://www.w3.org/2000/svg"><g clip-path="url(#clip0_1962_2099)"><path fill-rule="evenodd" clip-rule="evenodd" d="M0.239665 1.20041C0.543198 0.918556 1.01775 0.936132 1.2996 1.23966L4 4.14779L6.70041 1.23966C6.98226 0.936132 7.45681 0.918556 7.76034 1.20041C8.06387 1.48226 8.08145 1.95681 7.7996 2.26034L4.5496 5.76034C4.40769 5.91317 4.20855 6 4 6C3.79145 6 3.59232 5.91317 3.45041 5.76034L0.200408 2.26034C-0.081444 1.95681 -0.0638681 1.48226 0.239665 1.20041Z" fill="#ffffff" style="fill:#ffffff;fill-opacity:1;"/></g><defs><clipPath id="clip0_1962_2099"><rect width="8" height="6" fill="white" style="fill:white;fill-opacity:1;"/></clipPath></defs></svg>
            </button>
            <div
                v-if="unitPopoverOpen"
                class="shadow-md flex gap-1 py-1 px-1 top-full translate-y-1 absolute bg-white rounded transition z-20 right-0"
            >
                <button
                    v-for="key in unitsKey"
                    :key="key"
                    type="button"
                    class="px-2 h-[19px] leading-4 uppercase border-0 focus:outline-none focus:ring-0 min-w-5 text-tiny font-medium rounded hover:bg-gray-100"
                    :class="{'bg-dark text-white': unit === key}"
                    @click="selectUnit(key)"
                >
                    {{ key }}
                </button>
            </div>
        </div>
        <div class="flex items-center w-full slider-number-wrp">
            <template v-if="useSlide">
                <div class="relative flex flex-1">
                    <input
                        :key="unit"
                        :value="(value !== '' && value != null && value !== 'none' && value !== 'auto') ? (value ?? defaultNum) : (min < 0 && max > 0 ? 0 : min)"
                        type="range"
                        :min="min"
                        :max="max"
                        :step="step"
                        class="relative w-full h-5 ecom-slider-number focus:outline-none input-slider text-text-primary"
                        style="cursor: grab"
                        :placeholder="field?.placeholder"
                        @input="onInputSlider"
                    >
                    <div
                        class="absolute h-1 rounded pointer-events-none number-slide-per top-2/4 bg-dark"
                        :style="percentProgressbar"
                    />
                </div>
                <span
                    v-show="!showinput"
                    class="pl-2 text-xs text-right cursor-pointer text-text-primary font-[450] focus:outline-none sitooltip relative h-7-5 flex items-center justify-end shrink-0 tabular-nums min-w-[45px]"
                    :data-tooltip="$t('click_to_edit')"
                    @click="showInput"
                >{{ data ?? (dt || 'none') }}{{ data && dt ? display_unit : '' }}</span>
                <input
                    v-if="showinput"
                    v-focus="focus"
                    class="relative min-w-10 pl-2 pr-1 ml-2 text-center transition border border-gray-300 rounded shadow-sm h-7-5 sm:text-sm focus:ring-inset focus:ring-1 focus:ring-primary-400  focus:border-primary-400   focus:text-gray-600"
                    type="number"
                    :value="data !== undefined ? value : ''"
                    :min="min"
                    :max="max"
                    :step="step"
                    :placeholder="field?.placeholder"
                    @blur="debounceInputSlider"
                    @keydown.enter.esc="debounceInputSlider"
                    ref="input_slider"
                >
                <template v-else />
            </template>
            <div
                v-else
                class="flex justify-center"
                :class="{
                    'pl-2 ml-2': useSlide,
                    'w-20 number-input-container': !(
                        (field.options?.half && field.options?.half == true) ||
                        field.options?.control_width
                    ),
                    'w-full':
                        (field.options?.half && field.options?.half == true) ||
                        field.options?.control_width
                }"
                :style="
                    field.options?.control_width
                        ? 'width:' + field.options?.control_width
                        : field.options?.oneline
                        ? 'max-width:60%'
                        : ''
                "
            >
                <input
                    :value="data !== undefined ? value : ''"
                    class="relative w-full pl-2 pr-1 transition border rounded shadow-sm h-7-5 sm:text-sm focus:ring-inset focus:ring-1 focus:ring-primary-400 focus:border-primary-400 text-black"
                    :class="isQuickToolBar ? '!border-black !border-solid !border-[1px]' : 'border-gray-300'"
                    type="number"
                    :min="min"
                    :max="max"
                    :step="step"
                    :placeholder="field?.placeholder"
                    @input="debounceInput"
                    ref="input_default"
                >
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import { eventBus } from "@/utils/eventBus";

export default {
    name: 'Number',
    props: {
        field: {
            type: Object,
            default() {
                return {};
            }
        },
        // eslint-disable-next-line vue/require-default-prop
        data: [String, Number, Boolean, null],
        isQuickToolBar: {
            type: Boolean,
            default: false
        }
    },
    emits: ['update:data'],
    data() {
        return {
            value: this.data ?? this.field?.value ?? this.field.options?.units?.[this.unit]?.min ?? 0,
            units: this.field.options?.units ?? {},
            focus: this.field?.focus ? true : false,
            useSlide: this.field.options?.slider ?? true,
            status: true,
            emit: false,
            unit: '',
            display_unit: this.field.options?.unit ? this.field.options?.unit : '',
            showinput: this.field?.focus ? true : false,
            time: null,
            unitPopoverOpen: false,
            unitPopoverId: 'unit-popover-' + Math.random().toString(36).substr(2, 9)
        };
    },
    computed: {
        unitsKey() {
            return Object.keys(this.units);
        },
        unitsLength() {
            return this.unitsKey.length;
        },
        step() {
            return Object.keys(this.units).length > 0
                ? this.units[this.unit]?.step ?? 1
                : this.field.options?.step ?? 1;
        },
        dt(){
            if(this.value === '') {
                // User xoá trắng input -> trả '' để updateData xoá key khỏi settings.
                // Trước đây lưu 'none' vào data, sinh ra CSS invalid (vd `font-size: none`)
                // và làm mất unit của field ở lần mount sau.
                return '';
            }
            if(this.value == '') {
                // Giữ nguyên hành vi cũ cho các giá trị loose-equal '' (số 0)
                // để không đổi output của dữ liệu đang có.
                return 'none';
            }
            if (this.value == 'auto' || this.value == 'none') {
                return this.value;
            } else {
                if (this.unit) {
                    if (this.max !== '') {
                        if (this.value > this.max) {
                            return this.max + this.unit;
                        } else {
                            return this.value + this.unit;
                        }
                    } else {
                        return this.value + this.unit;
                    }
                } else {
                    return parseFloat(this.value);
                }
            }
        },
        defaultNum() {
            return this.field.options?.default;
        },
        min(){
            return Object.keys(this.units).length > 0
                ? this.units[this.unit]?.min ?? (this.useSlide ? 1 : '')
                : this.field.options?.min ?? (this.useSlide ? 1 : '');
        },
        max(){
            return Object.keys(this.units).length > 0
                ? this.units[this.unit]?.max ?? (this.useSlide ? 100 : '')
                : this.field.options?.max ?? (this.useSlide ? 100 : '');
        },
        percentProgressbar() {
            const empty = this.value === '' || String(this.value).toLowerCase() === 'auto' || String(this.value).toLowerCase() === 'none' || this.value == null;
            let translateX = 0;
            let scaleX = 0;

            if (!empty) {
                const parsedValue = parseFloat(this.value);
                const parsedMin = parseFloat(this.min);
                const parsedMax = parseFloat(this.max);

                if (!isNaN(parsedValue) && !isNaN(parsedMin) && !isNaN(parsedMax)) {
                    const range = parsedMax - parsedMin;
                    if (range !== 0) {
                        const P = Math.min(Math.max((parsedValue - parsedMin) / range, 0), 1);
                        let Z = 0;

                        // Nếu dải min âm, điểm gốc (Zero) nằm giữa slider
                        if (parsedMin < 0 && parsedMax > 0) {
                            Z = (0 - parsedMin) / range;
                        }

                        translateX = Math.min(P, Z) * 100;
                        scaleX = Math.abs(P - Z);
                    }
                }
            }

            if (isNaN(scaleX)) scaleX = 0;
            if (isNaN(translateX)) translateX = 0;

            return {
                transform: `translateY(-50%) translateX(${translateX}%) scaleX(${scaleX})`
            };
        }
    },
    watch: {
        unit: function () {
            if (this.value !== 'auto') {
                if (this.min) {
                    if (this.value < this.min) {
                        this.value = this.min;
                    }
                }
                if (this.max) {
                    if (this.value > this.max) {
                        this.value = this.max;
                    }
                }
            }
        },
        units: {
            immediate: true,
            handler: function (val) {
                if (val) {
                    this.unit = Object.keys(val)[0];
                }
            }
        },
        data: {
            immediate: true,
            handler: function (val) {
                if (this.status) {
                    this.emit = false;
                    if (typeof val !== 'undefined' && val !== null) {
                        if (typeof val === 'string' && val.length > 0 && val !== 'auto' && val !== 'none') {
                            let v = val.match(/[.-\d]/g) ?? [];
                            this.value = parseFloat(v.join('')) ?? 0;
                            for (var i = 0; i < v.length; i++) {
                                val = val.replace(v[i], '');
                            }

                            let unit = val.replace(/\s/g, '');
                            if(this.units[unit]) {
                                this.unit = unit;
                            }
                            else
                            {
                                this.unit = Object.keys(this.units)[0];
                            }

                        } else {
                            if (val !== 'auto') {
                                // Number hoặc 'none' không mang unit, nhưng field vẫn phải giữ
                                // unit mặc định của nó. Nếu gán '' thì dt() emit số thuần và
                                // giá trị mất unit vĩnh viễn (field 1 unit không có UI chọn
                                // lại unit). Xử lý giống nhánh string ở trên: chuỗi '20' cũng
                                // đang được gán lại Object.keys(units)[0].
                                this.unit = (typeof val === 'number' || val === 'none')
                                    ? (Object.keys(this.units)[0] ?? '')
                                    : '';
                            }
                            this.value = val;
                        }
                    } else {
                        this.value = this.defaultNum ?? 'none';
                    }
                }
                this.status = true;
            }
        },
        dt: {
            immediate: true,
            handler: function (val) {
                if (this.emit) {
                    this.status = false;
                    this.$emit('update:data', val);
                }
                this.emit = true;
            }
        }
    },
    mounted() {
        if(this.$refs.input_slider) {
            this.$refs.input_slider.select();
        }
    },
    beforeUnmount() {
        document.removeEventListener('click', this.closeUnitPopover);
    },
    methods: {
        onInputSlider(e: Event) {
            this.value = (e.target as HTMLInputElement).value;
        },
        showInput() {
            this.showinput = true;
            this.focus = true;

            this.$nextTick(
                function () {
                    this.$refs.input_slider.select();
                }.bind(this)
            );
        },
        debounceInput(e) {

            let value = e.target.value.trim();
            const setValue = () => {
                if (this.min !== '' && this.max !== '' && value.length > 0) {
                    this.value = this.minMax(value, this.min, this.max);
                } else {
                    this.value = value;
                }
            }
            let numValue = parseFloat(value);
            if(!isNaN(numValue) && (numValue < this.min || numValue > this.max)) {
                this.time = setTimeout(() => {
                    setValue();
                    if(this.$refs?.input_default) this.$refs.input_default.value = this.value
                }, 500);

            }
            else {
                if(this.time) {
                    clearTimeout(this.time);
                }
                setValue();
            }

        },
        debounceInputSlider(e) {

            let value = e.target.value.trim();
            const setValue = () => {
                if (this.min !== '' && this.max !== '' && value.length > 0) {
                    this.value = this.minMax(value, this.min, this.max);
                } else {
                    this.value = value;
                }
            }
            setValue();
            this.showinput = false;

        },
        minMax(value, min, max) {
            if (parseFloat(value) < min || isNaN(parseFloat(value))) {
                {
                    return min;
                }
            } else if (parseFloat(value) > max) {
                {
                    return max;
                }
            } else {
                return value;
            }
        },
        toggleUnitPopover() {
            this.unitPopoverOpen = !this.unitPopoverOpen;
            if (this.unitPopoverOpen) {
                document.addEventListener('click', this.closeUnitPopover);
            }
        },
        selectUnit(key) {
            this.unit = key;
            this.closeUnitPopover();
        },
        closeUnitPopover(e) {
            if (
                e === undefined ||
                !e.target.closest('.' + this.unitPopoverId)
            ) {
                this.unitPopoverOpen = false;
                document.removeEventListener('click', this.closeUnitPopover);
            }
        }
    }
};
</script>

