<i18n>
{
    "en": {
        "add_files": "Add files",
        "upload_a_file_or_drag_and_drop": "Upload a file or drag and drop"
    },
    "fr": {
        "add_files": "Ajouter des fichiers",
        "upload_a_file_or_drag_and_drop": "Télécharger un fichier ou faites glisser et déposez"
    },
    "de": {
        "add_files": "Dateien hinzufügen",
        "upload_a_file_or_drag_and_drop": "Datei hochladen oder per Drag & Drop verschieben"
    },
    "ja": {
        "add_files": "ファイルを追加",
        "upload_a_file_or_drag_and_drop": "ファイルをアップロードするかドラッグアンドドロップ"
    }
}
</i18n>
<template>
    <div class="relative flex flex-col items-center justify-center p-9 border border-dashed border-gray-250 rounded-lg group  " @drop="dragFile">
        <!-- <EcomIcon :source="PageUpMajor" :size="'w-8'" class="transition text-gray-500 group-hover:text-primary "></EcomIcon> -->
        <span v-if="!file" class="text-[#1F5199] bg-[#E5EFFD] rounded text-xs px-[6px] py-1 font-semibold">
            {{ $t('add_files') }}
        </span>
        <EcomText v-else :color="'text-gray-500  '" :fontWeight="'medium'">
            {{ file.name }}
        </EcomText>
        <EcomText :size="'small'" class="!text-[#6D7175] text-xs transition group-hover:text-gray-600  mt-1">
            {{ $t('upload_a_file_or_drag_and_drop') }}
        </EcomText>
        <input type="file" class="absolute inset-0 w-full h-full opacity-0 cursor-pointer " :accept="field.options?.accept ?? null" @change="uploadFile">
    </div>
</template>

<script lang="ts">
    import { PageUpMajor } from "@/assets/icons";
    export default {
        name: 'UploadField',
        props: {
            field: {
                type: Object,
                default() {
                    return {};
                }
            }
        },
        emits: ['update:data'],
        data() {
            return {
                file: null,
                PageUpMajor
            };
        },
        watch: {
            file(val) {
                this.$emit('update:data', val);
            }
        },
        methods: {
            uploadFile(e) {
                this.addFile(e.target.files);
            },
            dragFile(e) {
                this.addFile(e.dataTransfer.files);
            },
            addFile(files) {
                if(files.length) {
                    this.file = files[0];
                }
                else {
                    this.file = null;
                }
            }
        }
    };
</script>
