export default {
    worker: null,
    queues: {},
    // The local IndexedDB store is a convenience cache for revisions and presets, never
    // the source of truth — pages are saved through the API. When the database itself
    // cannot be opened (sandboxed iframe, private mode, a leftover database left at a
    // higher version by an older build) we disable it once and let every caller carry on
    // with an empty result, instead of leaking an unhandled rejection on every call.
    storeAvailable: true,
    async init() {
        if (!this.worker) {
            this.worker = new Worker('/worker.js?v=1.0.2', { type: 'module' });
            this.onmessage();
        }
    },
    onmessage() {
        this.worker.onmessage = (e) => {
            let data = e.data;
            let queued = this.queues[data.id];
            if (queued) {
                delete this.queues[data.id];
                if (data.status == 'success') {
                    queued.resolve(data.result);
                }
                else {
                    queued.fail(new Error(data.result), data.fatal === true);
                }
            }
        }
    },
    generateId() {
        return Math.random().toString(36).substring(2, 9);
    },
    disableStore(reason) {
        if (this.storeAvailable) {
            this.storeAvailable = false;
            console.warn('[worker] Local store unavailable, revision history is disabled for this session:', reason);
        }
    },
    async request(action: string, params: any = null, fallback: any = null) {
        if (!this.storeAvailable) {
            return fallback;
        }
        try {
            await this.init();
        }
        catch (e) {
            this.disableStore(e);
            return fallback;
        }
        return new Promise((resolve) => {
            let id = this.generateId();
            this.queues[id] = {
                resolve,
                fail: (error, fatal) => {
                    if (fatal) {
                        this.disableStore(error);
                    }
                    else {
                        console.warn(`[worker] "${action}" failed on the local store:`, error);
                    }
                    resolve(fallback);
                }
            };
            this.worker.postMessage({ action, id, params });
        });
    },
    async getAll() {
        return this.request('getAll', null, []);
    },
    async delete(params) {
        return this.request('delete', params);
    },
    async deleteByKeys(params) {
        return this.request('deleteByKeys', params);
    },
    async update(params) {
        return this.request('update', params);
    },
    async add(params) {
        return this.request('add', params);
    },
    async find(key, limit) {
        return this.request('find', { key, limit }, []);
    },
    async getToken() {
        return await window.shopify.idToken();
    },
    async fetch(route: string, params: any = null, method: string = 'GET', signal?: AbortSignal) {
        await this.init();
        let headers: Record<string, string> = {
            // 'Content-Type': 'application/json',
            "Accept": "application/json"
        };
        if (window.ECOM_INIT.APPBRIDGE) {

            let url = new URL(route);
            let queryParams = window.route().params;
            const token = await this.getToken();
            if (token) {
                headers['Authorization'] = `Bearer ${token}`;
            }
            if (queryParams.host) {
                url.searchParams.set('host', queryParams.host);
            }
            if (queryParams.shop) {
                url.searchParams.set('shop', queryParams.shop);
            }
            if (url.searchParams.has('id_token')) {
                url.searchParams.delete('id_token');
            }
            // params.worker_timestamp = new Date().getTime();
            url.searchParams.set('worker_timestamp', new Date().getTime().toString());
            route = url.href;
        }

        let shouldReturnBlob = false;
        if (params instanceof FormData && params.get('contentType') === 'blob') {
            shouldReturnBlob = true;
        } else if (params && typeof params === 'object' && params.contentType === 'blob') {
            shouldReturnBlob = true;
        }

        if (shouldReturnBlob) {
            headers["Accept"] = "image/*, application/json, */*";
        }

        if (params instanceof FormData) {
            // headers['Content-Type'] = 'multipart/form-data';
        }
        else if (typeof params === 'object' && params) {
            headers['Content-Type'] = 'application/json';
            params = JSON.stringify(params);
        }

        try{
            let response = await window.fetch(route, {
                method: method,
                body: ['DELETE', 'POST', "PUT", "PATCH"].includes(method.toUpperCase()) ? params : null,
                headers: headers,
                signal: signal
            });

            // The App Bridge session token used above is only valid for ~60s. If it expired
            // in-flight (network/processing latency) the backend rejects it with 401 even
            // though the shop is properly installed. Retry once with a freshly fetched token
            // before surfacing an error to the user.
            if (response.status === 401 && window.ECOM_INIT.APPBRIDGE) {
                console.warn('[Worker] Got 401, retrying once with a fresh session token');
                const freshToken = await this.getToken();
                if (freshToken) {
                    headers['Authorization'] = `Bearer ${freshToken}`;
                }
                response = await window.fetch(route, {
                    method: method,
                    body: ['DELETE', 'POST', "PUT", "PATCH"].includes(method.toUpperCase()) ? params : null,
                    headers: headers,
                    signal: signal
                });
            }

            if (!response.ok) {
                const msg = response.statusText || 'Server error';
                return {
                    status: 'error',
                    message: msg,
                    data: { status: 'error', message: msg }
                }
            }

            const contentType = response.headers.get('content-type');
            if (contentType && (contentType.startsWith('image/') || contentType === 'application/octet-stream')) {
                shouldReturnBlob = true;
            }

            try {
                if (shouldReturnBlob) {
                    return {
                        status: 'success',
                        data: await response.blob()
                    };
                }
                return {
                    status: 'success',
                    data: JSON.parse(await response.text())
                }
            }
            catch (e: any) {
                const msg = e.message || 'Failed to parse server response';
                return {
                    status: 'error',
                    message: msg,
                    data: { status: 'error', message: msg }
                }
            }
        }
        catch (e: any) {
            const msg = e.message || 'Network error';
            return {
                status: 'error',
                message: msg,
                data: { status: 'error', message: msg }
            }
        }
    }





}