import { ROOT_STORE } from "@/store/constants";

import type { MutationTree } from "vuex";
import type { RootMutationsTypes, RootStateType } from "@/store/interfaces";

export const mutations: MutationTree<RootStateType> & RootMutationsTypes = {
    [ROOT_STORE.MUTATIONS.SET_TAB](state: RootStateType, payload: string) {
        state.controls.current = payload;
    },
    [ROOT_STORE.MUTATIONS.UPDATE_IS_TEMP_HIDE](state: RootStateType, payload: boolean) {
        state.controls.isTempHide = payload;
    },
    [ROOT_STORE.MUTATIONS.UPDATE_IS_NAVIGATOR_PINNED](state: RootStateType, payload: boolean) {
        state.controls.isNavigatorPinned = payload;
        // Persist to localStorage
        try {
            localStorage.setItem('ecom_isNavigatorPinned', String(payload));
        } catch (e) {
            console.warn('Failed to save isNavigatorPinned to localStorage:', e);
        }
    },
    [ROOT_STORE.MUTATIONS.UPDATE_IS_SEO_AUDIT_PINNED](state: RootStateType, payload: boolean) {
        state.controls.isSeoAuditPinned = payload;
        // Persist to localStorage
        try {
            localStorage.setItem('ecom_isSeoAuditPinned', String(payload));
        } catch (e) {
            console.warn('Failed to save isSeoAuditPinned to localStorage:', e);
        }
    },
    [ROOT_STORE.MUTATIONS.UPDATE_REFRESH](state: RootStateType) {
        state.refresh = Math.random();
    },
    [ROOT_STORE.MUTATIONS.UPDATE_SEARCHING](state: RootStateType, payload: string) {
        state.controls.search = payload;
    },
    [ROOT_STORE.MUTATIONS.UPDATE_NAVIGATOR_SEARCHING](state: RootStateType, payload: string) {
        state.controls.navigatorSearch = payload;
    },
    [ROOT_STORE.MUTATIONS.UPDATE_VERSION](state: RootStateType, payload: string) {
        state.version = payload;
    }
};
