        <button
            type="button"
            class="w-8 h-8 rounded  color_bg-picker-btn"
            :class="{
                'ecom-bg__none': isNone,
                'color_bg-picker-btn--color': !isBackgroundImage && !isQuickToolBar,
                'color_bg-picker-btn--color-quick-tool': isQuickToolBar
            }"
            :style="preview"
            @click="open($event), $emit('update:isPanelOpen', !isPanelOpen)"
            ref="bgSettingBtn"
            :data-tooltip="title"
        >
        <span class="color_bg-picker-btn-inner"></span>
        </button>
        <Teleport to="body">
            <transition enter-active-class="transition duration-200 ease-out"
                enter-from-class="transform scale-90 opacity-0" enter-to-class="transform scale-100 opacity-100"
                leave-active-class="transition duration-150 ease-in" leave-from-class="transform scale-100 opacity-100"
                leave-to-class="transform scale-90 opacity-0">
                <div v-if="isopen"
                    class="fixed pb-10 mt-3 left-0 ecom-fields__background"
                    :class="[isPopup ? 'transform -translate-x-1/2' : '']"
                    :id="idTeleport"
                    :style="{
                        top: popupColorPosition.top,
                        left: popupColorPosition.left,
                        bottom: popupColorPosition.bottom,
                        zIndex: zIndex || 61
                    }">
                    <BackDrop v-if="isopen && !isPopup" @click="doClose" class="outside-close-cursor"
                        :style="{ zIndex: 1 }"></BackDrop>
                    <div
                        class="popup-container ecom-fields__background__inner relative text-text-primary inline-block bg-white rounded-xl 3xl:w-[267px] w-[270px] ec-shadow-popup-3 border border-popup"
                        :style="{ zIndex: 2 }">
                        <div class="flex items-center justify-between h-9 px-4 py-2 bg-surface-tertiary rounded-t-xl">
                            <span class="text-xs font-[550] text-gray-600  truncate w-full">{{ $t('background') }}</span>
                        </div>
                        <div class="background-content-inner">
                        <ul v-if="types && types.length > 1"
                            class="flex bg-surface-tertiary p-1 rounded-lg mt-3.5 mx-3">
                            <li v-for="(item, index) in types" :key="index"
                                class="flex-1 ecom-item-tab-bg-hover rounded"
                                :class="type === item ? 'rounded bg-white shadow-[0px_8px_20px_-4px_#1718181F,0px_3px_6px_-3px_#17181814]' : 'bg-transparent'">
                                <button type="button"
                                    class="flex h-6 w-full items-center justify-center whitespace-nowrap px-3 text-xs leading-5 text-center align-middle font-medium text-text-primary"
                                    :class="type === item ? '' : 'hover:text-primary-700 transition-all'
                                        " @click="changeType(item)">
                                    {{ $t(item) }}
                                </button>
                            </li>
                        </ul>
                        <div v-else class="w-full" />
                        <Fields v-if="type === 'classic'" :key="refresh" :fields="fields" :deep="1" :ispop="true"
                            :data="curValue" class="p-3.5 -mx-2" @update:data="updateData" />
                        <div v-else class="px-4 p-4">
                            <GradientComponent
                                :key="'bg-gradient-' + gradientRefreshKey"
                                :data="dataGradient"
                                @update="updateDataGradient"
                            />
                        </div>
                    </div>
                </div>
                </div>
            </transition>
        </Teleport>
    </div>
</template>

<script lang="ts">
import { Popmenu } from "@/mixins";
//import GradientComponent from "./Gradient.vue"
import GradientComponent from "@/components/Builder/Components/Utils/TextEditorBar/Color/GradientColor.vue";

import { convertBg } from "@/components/Builder/Helpers/Css";
import { $t } from "@/plugins/i18n";
import { showPopupAtBottom, showPopupAtBottomInSideNar } from "@/utils";

interface PopupPosition {
    top: string | number;
    left: string;
    bottom: string | number;
}

interface PopupDimensions {
    width: number;
    height: number;
}

export default {
    name: "Background",
    components: {
        GradientComponent,
    },
    mixins: [Popmenu],
    provide: {
        teleport_id: ".ecom-fields__background"
    },
    props: {
        field: {
            type: Object,
            default() {
                return {};
            }
        },
        data: {
            type: [Object, String],
            default() {
                return {};
            }
        },
        title: {
            type: String,
            default: ''
        },
        isPanelOpen: {
            type: Boolean,
            default: false
        },
        isPopup: {
            type: Boolean,
            default: false
        },
        zIndex: {
            type: [String, Number],
            default: 61
        },
        isQuickToolBar: {
            type: Boolean,
            default: false
        }
    },
    emits: ["update:data", 'update:isPanelOpen'],
    data() {
        return {
            popupColorPosition: { top: 0, left: '0px', bottom: 0 } as PopupPosition,
            idTeleport: "popup-background" + Date.now() + Math.random().toString(36).substr(2, 9),
            type: this.field.options?.types ? this.field.options?.types[0] : 'classic',
            values: this.$helpers.copy(this.data),
            types: this.field.options?.types ?? ["classic", "gradient"],
            refresh: 0,
            image: this.field.options?.image ?? true,
            classicColor: this.field.options?.classicColor ?? false,
            status: true,
            emit: false,
            showPopupAtTop: false,
            mutationObserver: null as MutationObserver | null,
            popupElement: null as HTMLElement | null,
            popupDimensions: { width: 270, height: 468 } as PopupDimensions,
            gradientRefreshKey: 0,
            skipDataWatch: false,
            skipDataWatchTimer: null as ReturnType<typeof setTimeout> | null
        };
    },
    computed: {
        dataGradient() {
            return {
                gradient: this.sanitizeGradientValue(this.curValue)
            };
        },
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        fields() {
            if (this.type === "classic") {
                return !this.classicColor
                    ? [
                        {
                            name: "background-color",
                            label: $t('color'),
                            type: "color",
                            options: {
                                oneline: true,
                                global: {
                                    type: "colors"
                                }
                            }
                        },
                        this.image
                            ? {
                                name: "background-image",
                                label: $t('image'),
                                type: "picker",
                                options: {
                                    type: "image",
                                    multiple: false,
                                    output: "value",
                                    position: "fixed",
                                    formatValue: 'url("%value%")'
                                }
                            }
                            : {},
                        {
                            type: 'size',
                            label: $t('image_size'),
                            name: 'image-size',
                            options: {
                                reset: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["background-image"];
                                    }
                                }
                            }
                        },
                        this.image
                            ? {
                                name: "background-position",
                                label: $t('position'),
                                type: "popup",
                                value: "center center",
                                options: {
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        "center center": this.$t('center_center'),
                                        "center right": this.$t('center_right'),
                                        "center left": this.$t('center_left'),
                                        "top left": this.$t('top_left'),
                                        "top center": this.$t('top_center'),
                                        "top right": this.$t('top_right'),
                                        "bottom right": this.$t('bottom_right'),
                                        "bottom left": this.$t('bottom_left'),
                                        "bottom center": this.$t('bottom_center'),
                                        custom: this.$t('custom')
                                    },
                                    type: "dropdown",
                                    oneline: true,
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data["background-image"];
                                        }
                                    }
                                }
                            }
                            : {
                                name: "background-position",
                                label: $t('position'),
                                type: "popup",
                                value: "center center",
                                options: {
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        "center center": this.$t('center_center'),
                                        "center right": this.$t('center_right'),
                                        "center left": this.$t('center_left'),
                                        "top left": this.$t('top_left'),
                                        "top center": this.$t('top_center'),
                                        "top right": this.$t('top_right'),
                                        "bottom right": this.$t('bottom_right'),
                                        "bottom left": this.$t('bottom_left'),
                                        "bottom center": this.$t('bottom_center'),
                                        custom: this.$t('custom')
                                    },
                                    type: "dropdown",
                                    oneline: true
                                }
                            },
                        {
                            name: "background-position-x",
                            label: $t('x_position'),
                            type: "number",
                            options: {
                                units: {
                                    px: {
                                        min: -800,
                                        max: 800,
                                        step: 1
                                    },
                                    em: {
                                        min: -100,
                                        max: 100,
                                        step: 0.1
                                    },
                                    "%": {
                                        min: -100,
                                        max: 100,
                                        step: 1
                                    },
                                    vw: {
                                        min: -100,
                                        max: 100,
                                        step: 1
                                    }
                                },
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["background-position"] === "custom";
                                    }
                                }
                            }
                        },
                        {
                            name: "background-position-y",
                            label: $t('y_position'),
                            type: "number",
                            options: {
                                units: {
                                    px: {
                                        min: -800,
                                        max: 800,
                                        step: 1
                                    },
                                    em: {
                                        min: -100,
                                        max: 100,
                                        step: 0.1
                                    },
                                    "%": {
                                        min: -100,
                                        max: 100,
                                        step: 1
                                    },
                                    vw: {
                                        min: -100,
                                        max: 100,
                                        step: 1
                                    }
                                },
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["background-position"] === "custom";
                                    }
                                }
                            }
                        },
                        this.image
                            ? {
                                name: "background-attachment",
                                label: $t('attachment'),
                                type: "popup",
                                options: {
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        fixed: this.$t('fixed'),
                                        scroll: this.$t('scroll'),
                                        local: this.$t('local'),
                                        inherit: this.$t('inherit')
                                    },
                                    type: "dropdown",
                                    oneline: true,
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data["background-image"];
                                        }
                                    }
                                }
                            }
                            : {
                                name: "background-attachment",
                                label: $t('attachment'),
                                type: "popup",
                                options: {
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        fixed: this.$t('fixed'),
                                        scroll: this.$t('scroll'),
                                        local: this.$t('local'),
                                        inherit: this.$t('inherit')
                                    },
                                    type: "dropdown",
                                    oneline: true
                                }
                            },
                        this.image
                            ? {
                                name: "background-repeat",
                                label: $t('repeat'),
                                type: "popup",
                                options: {
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        "no-repeat": this.$t('no_repeat'),
                                        repeat: this.$t('repeat'),
                                        "repeat-x": this.$t('horizontally'),
                                        "repeat-y": this.$t('verically'),
                                    },
                                    type: "dropdown",
                                    oneline: true,
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data["background-image"];
                                        }
                                    }
                                }
                            }
                            : {
                                name: "background-repeat",
                                label: $t('repeat'),
                                type: "popup",
                                options: {
                                    default: false,
                                    type: "dropdown",
                                    preview: 'title',
                                    values: {
                                        "no-repeat": this.$t('no_repeat'),
                                        repeat: this.$t('repeat'),
                                        "repeat-x": this.$t('horizontally'),
                                        "repeat-y": this.$t('verically'),
                                    },
                                    oneline: true
                                }
                            },
                        this.image
                            ? {
                                name: "background-size",
                                label: $t('size'),
                                type: "popup",
                                options: {
                                    type: "dropdown",
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        cover: this.$t('cover'),
                                        auto: this.$t('auto'),
                                        contain: this.$t('contain'),
                                        inherit: this.$t('inherit'),
                                    },
                                    oneline: true,
                                    visible: {
                                        keep_data: true,
                                        condition: (data) => {
                                            return data["background-image"];
                                        }
                                    }
                                }
                            }
                            : {
                                name: "background-size",
                                label: $t('size'),
                                type: "popup",
                                options: {
                                    type: "dropdown",
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        cover: this.$t('cover'),
                                        auto: this.$t('auto'),
                                        contain: this.$t('contain'),
                                        inherit: this.$t('inherit'),
                                    },
                                    oneline: true
                                }
                            }
                    ]
                    : [
                        {
                            name: "background-color",
                            label: $t('color'),
                            type: "color",
                            options: {
                                oneline: true,
                                global: {
                                    type: "colors"
                                }
                            }
                        }
                    ];
            } else if (this.type === "gradient") {
                return [
                    {
                        name: "first-color",
                        label: $t('color'),
                        type: "color",
                        options: {
                            oneline: true,
                            global: {
                                type: "colors"
                            }
                        }
                    },
                    {
                        name: "first-location",
                        label: $t('location'),
                        type: "number",
                        value: 0,
                        options: {
                            min: 0,
                            max: 100
                        }
                    },
                    {
                        name: "second-color",
                        label: $t('second_color'),
                        type: "color",
                        options: {
                            oneline: true,
                            global: {
                                type: "colors"
                            }
                        }
                    },
                    {
                        name: "second-location",
                        label: $t('location'),
                        type: "number",
                        value: 100,
                        options: {
                            min: 0,
                            max: 100
                        }
                    },
                    {
                        name: "type",
                        label: $t('type'),
                        type: "popup",
                        value: "linear",
                        options: {
                            type: "dropdown",
                            default: false,
                            preview: 'title',
                            values: {
                                linear: this.$t('linear'),
                                radial: this.$t('radial')
                            },
                            oneline: true
                        }
                    },
                    {
                        name: "angle",
                        label: $t('angle'),
                        type: "number",
                        value: 180,
                        options: {
                            min: 0,
                            max: 360,
                            visible: {
                                keep_data: true,
                                condition: (data) => {
                                    return data["type"] == "linear";
                                }
                            }
                        }
                    },
                    {
                        name: "position",
                        label: $t('position'),
                        type: "popup",
                        value: "center center",
                        options: {
                            type: "dropdown",
                            default: false,
                            values: {
                                "center center": this.$t('center_center'),
                                "center right": this.$t('center_right'),
                                "center left": this.$t('center_left'),
                                "top left": this.$t('top_left'),
                                "top center": this.$t('top_center'),
                                "top right": this.$t('top_right'),
                                "bottom right": this.$t('bottom_right'),
                                "bottom left": this.$t('bottom_left'),
                                "bottom center": this.$t('bottom_center'),
                            },
                            oneline: true,
                            visible: {
                                keep_data: true,
                                condition: (data) => {
                                    return data["type"] == "radial";
                                }
                            }
                        }
                    }
                ];
            } else {
                return [];
            }
        },
        isNone() {
            if (!this.preview || !Object.keys(this.data || {}).length) {
                return true;
            }
            if (typeof this.preview === "object") {
                const style = this.preview as Record<string, string>;
                if (style["--ecom-bg-picker-gradient"] || style["--background-color"]) {
                    return false;
                }
                if (style.background && !/^none(?:\s|;|$)/i.test(style.background.trim())) {
                    return false;
                }
                return true;
            }
            const s = String(this.preview).trim();
            if (!s || /^none(?:\s|;|$)/i.test(s)) {
                return true;
            }
            if (/url\s*\(/i.test(s) || /gradient\(/i.test(s) || /^#|^rgb|^hsl/i.test(s)) {
                return false;
            }
            return true;
        },
        isBackgroundImage() {
            return !!this.curValue?.["background-image"];
        },
        curValue() {

            let tmp = this.values?.[this.type] ?? {};
            if (!tmp || tmp.constructor === Array) {
                return {};
            }
            return tmp;
        },
        preview() {
            const bg = Object.keys(this.curValue).length
                ? convertBg({
                    [this.type]: this.curValue
                })
                : "";
            const bgCss = typeof bg === "string" ? [bg] : bg?.css ?? [];
            if (!bgCss.length) {
                return "";
            }
            const line = String(bgCss[0] || '').trim();
            if (!line) {
                return "";
            }
            const cssMatch = line.match(/^([a-z-]+)\s*:\s*(.+?)\s*;?$/i);
            if (!cssMatch) {
                return "";
            }
            const cssProp = cssMatch[1].toLowerCase();
            const cssValue = cssMatch[2];
            // Gradient: đưa vào biến cho .color_bg-picker-btn-inner (không set background trực tiếp lên nút)
            if (/background:\s*(?:linear|radial|conic)-gradient\(/i.test(line)) {
                const m = line.match(/^background:\s*(.+)$/i);
                const gradientVal = m ? m[1].trim().replace(/;\s*$/, '') : line.replace(/^background:\s*/i, '').replace(/;\s*$/, '');
                return {
                    '--ecom-bg-picker-gradient': gradientVal,
                    '--background-color': null
                };
            }
            // Ảnh URL: giữ nguyên shorthand background trên nút
            if (/background:\s*url\s*\(/i.test(line)) {
                return {
                    background: cssValue,
                    '--ecom-bg-picker-gradient': null,
                    '--background-color': null
                };
            }
            if (cssProp === "background-color") {
                return {
                    '--background-color': cssValue,
                    '--ecom-bg-picker-gradient': null
                };
            }
            return { [cssProp]: cssValue };
        },
        previewNative() {
            const curValue = this.curValue;
            if (!Object.keys(curValue).length) {
                return "";
            }
            const bgResult = convertBg({
                [this.type]: curValue
            });
            const bg = (bgResult?.css ?? []).filter((line) => line && String(line).trim());
            if (bg.length) {
                return [String(bg[0]).replace("background-color", "background")];
            }
            if (this.type === "gradient" && curValue.style) {
                return [String(curValue.style).trim().replace(/;\s*$/, "")];
            }
            return "";
        }
    },

    watch: {
        data: {
            deep: true,
            immediate: true,
            handler: function (val) {
                if (!this.skipDataWatch && (this.status || this.isResetFromParent(val))) {
                    this.emit = false;
                    this.mergeDataFromProp(val);
                    if (val && typeof val === 'object' && val !== '__delete__' && Object.keys(val).length > 0 && !this.type) {
                        this.changeType("gradient" in val ? "gradient" : "classic");

                    }
                }
                this.status = true;
            }
        },
        "values.classic": {
            deep: true,
            handler: function (val) {
                if (val?.["background-image"] && this.type == "classic") {
                    if (!val["background-size"]) {
                        this.values.classic["background-size"] = "cover";
                    }
                    if (!val["background-repeat"]) {
                        this.values.classic["background-repeat"] = "no-repeat";
                    }
                    if (!val["background-position"]) {
                        this.values.classic["background-position"] = "center center";
                    }
                    if (!val["background-attachment"]) {
                        this.values.classic["background-attachment"] = "scroll";
                    }
                }
            }
        },
        values: {
            deep: true,
            immediate: true,
            handler: function (val) {

                if (this.emit) {
                    this.status = false;
                    if (this.type.length > 0) {
                        let dt = this.appendNativeToPayload(this.$helpers.copy({
                            [this.type]: val[this.type]
                        }));
                        if (
                            typeof dt === 'object' &&
                            Object.keys(dt).length === 1 &&
                            Object.keys(dt)[0] === 'gradient' &&
                            Object.keys(dt.gradient).length === 0 &&
                            !this.hasClassicData(val.classic)
                        ) {
                            dt = '__delete__';
                        }
                        this.$emit(
                            "update:data",
                            dt
                        );
                    } else {
                        this.$emit("update:data", {});
                    }
                }
                this.emit = true;
            }
        },
        fields: {
            deep: true,
            handler: function () {
                this.refresh = this.$helpers.makeId(8);
            }
        },
        type(val) {
            if (val.length > 0) {
                this.$emit(
                    "update:data",
                    this.appendNativeToPayload(this.$helpers.copy({
                        [val]: this.values[val]
                    }))
                );
            } else {
                this.$emit("update:data", {});
            }
            this.status = false;
            // changeType sets emit=false to suppress duplicate payloads; re-enable for the next user edit
            this.emit = true;
        },
        isopen(val) {
            // Check if bottom space of background color panel not enough, we need to show at the top
            if (this.isopen) {
                this.$store.commit("builder/setIsPopupOpen", true);
                this.$nextTick(() => {
                    const backgroundColorEle = document.querySelector(".ecom-fields__background__inner") as HTMLElement;
                    if (backgroundColorEle) {
                        // If background color is shown on Extension Modal
                        const ecomExtViewDetailEle = document.getElementById("ecomExtViewDetail");
                        if (ecomExtViewDetailEle) {
                            this.showPopupAtTop = !showPopupAtBottom(ecomExtViewDetailEle, this.$refs.bgSettingBtn, backgroundColorEle);
                        } else {
                            // If background color is shown on Sidebar setting modal
                            this.showPopupAtTop = !showPopupAtBottomInSideNar(this.$refs.bgSettingBtn, backgroundColorEle);
                        }
                    }
                });
                this.startObservingPopup();
            }else {
                this.stopObservingPopup();
            }
        },
        isPopupOpen(val) {
            if(val === false) {
                this.isopen = false;
            }
        },
        isPanelOpen(val) {
            this.isopen = val;
        }
    },
    created() {
        if (this?.values?.gradient && !this?.values?.classic) {
            this.type = 'gradient';
        }
    },
    methods: {
        sanitizeGradientValue(gradient) {
            if (!gradient || typeof gradient !== 'object' || Array.isArray(gradient)) {
                return gradient ?? {};
            }
            const cleaned = this.$helpers.copy(gradient);
            if (cleaned.style) {
                delete cleaned.style;
            }
            return cleaned;
        },
        guardParentSync() {
            this.skipDataWatch = true;
            if (this.skipDataWatchTimer) {
                clearTimeout(this.skipDataWatchTimer);
            }
            this.skipDataWatchTimer = setTimeout(() => {
                this.skipDataWatch = false;
                this.skipDataWatchTimer = null;
            }, 100);
        },
        appendNativeToPayload(dt) {
            if (!this.field?.options?.toNative) {
                return dt;
            }
            const native = this.previewNative;
            if (Array.isArray(native) && native.length) {
                dt.native = this.$helpers.copy(native);
            } else if (typeof native === "string" && native) {
                dt.native = native;
            }
            return dt;
        },
        hasClassicData(classic) {
            if (!classic || typeof classic !== 'object' || Array.isArray(classic)) {
                return false;
            }
            return Object.keys(classic).some((key) => {
                const v = classic[key];
                return v !== '' && v != null && !(typeof v === 'object' && !Object.keys(v).length);
            });
        },
        isResetFromParent(val) {
            if (val === '__delete__' || val == null || val === '') {
                return true;
            }
            return (
                typeof val === 'object' &&
                !Array.isArray(val) &&
                Object.keys(val).length === 0
            );
        },
        mergeDataFromProp(val) {
            if (this.isResetFromParent(val)) {
                this.values = {};
                return;
            }
            const incoming = this.$helpers.copy(val);
            delete incoming.native;
            if (incoming.gradient) {
                incoming.gradient = this.sanitizeGradientValue(incoming.gradient);
            }
            const tabKeys = ['classic', 'gradient'];
            tabKeys.forEach((key) => {
                if (incoming[key] === undefined) {
                    return;
                }
                if (key === this.type) {
                    this.values[key] = incoming[key];
                } else {
                    this.values[key] = {
                        ...(this.values[key] || {}),
                        ...incoming[key]
                    };
                }
                delete incoming[key];
            });
            this.values = { ...this.values, ...incoming };
        },
        backToDefault() {
            this.values = {};
        },
        changeType(type) {
            if(this.values === '__delete__') {
                this.values = {};
            }
            this.emit = false;
            this.status = false;
            this.guardParentSync();
            if (this.values[type] === undefined) {
                this.values[type] = {};
            }
            if (type === 'gradient' && this.values.gradient) {
                this.values.gradient = this.sanitizeGradientValue(this.values.gradient);
                this.gradientRefreshKey += 1;
            }
            this.type = type;

            // Recalculate popup dimensions and position when type changes
            this.$nextTick(() => {
                if (this.isopen && this.popupElement) {
                    this.updatePopupDimensions();
                    this.calculatePopupPosition();

                    // Use requestAnimationFrame to ensure DOM is fully updated
                    requestAnimationFrame(() => {
                        this.updatePopupDimensions();
                        this.calculatePopupPosition();
                    });
                }
            });
        },
        updateData(f, val) {
            if (val) {
                if (this.type) {
                    if(this.values === '__delete__') {
                        this.values = {};
                    }
                    this.guardParentSync();
                    this.values = {
                        ...this.values,
                        [this.type]: val
                    };
                }
            }
        },
        updateDataGradient(val) {
            if (val) {
                if (this.type) {
                    if(this.values === '__delete__') {
                        this.values = {};
                    }
                    this.guardParentSync();
                    this.values = {
                        ...this.values,
                        [this.type]: this.sanitizeGradientValue(val)
                    };
                }
            }
        },
        doClose() {
            this.isopen = false;
        },
        startObservingPopup() {
            this.stopObservingPopup();

            this.mutationObserver = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'childList') {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === Node.ELEMENT_NODE) {
                                const element = node as HTMLElement;
                                if (element.id === this.idTeleport) {
                                    this.popupElement = element as HTMLElement;
                                    this.updatePopupDimensions();
                                    this.calculatePopupPosition();

                                    requestAnimationFrame(() => {
                                        this.updatePopupDimensions();
                                        this.calculatePopupPosition();
                                    });
                                }
                            }
                        });
                    }
                });
            });

            this.mutationObserver.observe(document.body, {
                childList: true,
                subtree: true
            });
        },
        stopObservingPopup() {
            if (this.mutationObserver) {
                this.mutationObserver.disconnect();
                this.mutationObserver = null;
            }
            this.popupElement = null;
        },
        updatePopupDimensions() {
            if (this.popupElement) {
                this.popupDimensions = {
                    width: this.popupElement.offsetWidth || 270,
                    height: this.popupElement.offsetHeight || 468
                };
            }
        },
        calculatePopupPosition() {
            if (!this.popupElement || !this.$refs.bgSettingBtn) return;

            const rect = this.$refs.bgSettingBtn.getBoundingClientRect();
            const { width: popupWidth, height: popupHeight } = this.popupDimensions;

            const distanceToBottom = window.innerHeight - rect.top - rect.height;

            const fixedSelected = this.$refs.bgSettingBtn.closest('.popup-container') as HTMLElement || this.$refs.bgSettingBtn.closest('.fixed') as HTMLElement || this.$refs.bgSettingBtn.closest('.absolute') as HTMLElement;
            const fixedRect = fixedSelected.getBoundingClientRect();

            let left: number;
            if(fixedSelected && this.isPopup === false) {
                const {left: leftFixed, width: selectedWidth} = fixedRect;
                const distanceToRight = window.innerWidth - leftFixed - selectedWidth;
                if(leftFixed >= popupWidth) {
                    const spaceRectToFixedRect = rect.left - leftFixed;
                    if(spaceRectToFixedRect > 50) {
                        left = rect.left - popupWidth - 20;
                    }else {
                        left = leftFixed - popupWidth;
                    }
                }else if(distanceToRight >=  popupWidth) {
                    left = leftFixed + selectedWidth;
                }else {
                    left = rect.left + rect.width;
                }
            }else {
                left = rect.left + rect.width;
            }

            let top: string, bottom: string;
            const fixedPopupGetter = this.$refs.bgSettingBtn.closest('.fixed') as HTMLElement;
            const containerFly = this.$refs.bgSettingBtn.closest('.popup-container') as HTMLElement;
            let bottomFixedSpace = 0;
            if(fixedPopupGetter) bottomFixedSpace = window.innerHeight - fixedPopupGetter.getBoundingClientRect().top;

            if(fixedPopupGetter && !containerFly && bottomFixedSpace >= popupHeight && this.isPopup === false) {
                top = fixedPopupGetter.getBoundingClientRect().top + window.scrollY + "px";
                bottom = 'auto';
            }else if (distanceToBottom >= popupHeight && this.isPopup === true) {
                bottom = 'auto';
                top = (rect.bottom + window.scrollY) + "px";
            }
            else if (distanceToBottom >= popupHeight) {
                top = (rect.bottom + window.scrollY - rect.height - 15) + "px";
                bottom = 'auto';
            } else {
                top = (rect.bottom + window.scrollY) - (popupHeight - distanceToBottom) + "px";
                bottom = 'auto';
            }

            this.popupColorPosition = {
                top,
                left: left + 'px',
                bottom
            };
        },
    },
    beforeUnmount() {
        if (this.skipDataWatchTimer) {
            clearTimeout(this.skipDataWatchTimer);
            this.skipDataWatchTimer = null;
        }
        this.stopObservingPopup();
    }

};
</script>

