<template>
    <div class="tab pt-1">
        <div class="tab__heading">
            <ul class="flex gap-px rounded-lg bg-surface-tertiary p-1">
                <li
                    v-for="(tab, index) in tabs"
                    :key="tab?.name ?? tab?.title"
                    class="flex flex-1 items-center gap-px"
                    :class="[
                        tabSelected === tab.name
                            ? 'rounded bg-white shadow-[0px_8px_20px_-4px_#1718181F,0px_3px_6px_-3px_#17181814]'
                            : '',
                        tab?.class ?? ''
                    ]"
                >
                    <button
                        type="submit"
                        class="flex h-6 w-full items-center justify-center whitespace-nowrap text-center align-middle font-medium text-text-primary"
                        :class="[
                            tabSelected === tab.name ? '' : 'transition-all hover:text-primary-700',
                            tab?.icon ? 'px-1' : tab?.class=='ecom-site-settings-btn-tab' ? 'px-1 text-[11px] font-normal': 'px-1 text-xs font-medium leading-5'
                        ]"
                        :data-tooltip="tab?.icon ? tab?.title || '':''"
                        data-tooltip-location="top"
                        :aria-label="tab?.title || tab?.name || 'tab'"
                        @click.prevent="tabSelected = tab.name"
                    >
                        <ecom-icon
                            v-if="tab?.icon"
                            :source="tab.icon"
                            :size="'w-4'"
                            class="flex items-center justify-center"
                        />
                        <span v-else>
                            {{ tab.title }}
                        </span>
                    </button>
                    <div
                        class="h-3 w-px bg-tab-divider"
                        :class="index !== tabSelectedIndex && index !== tabs.length - 1 && tabSelectedIndex !== index + 1 ? 'opacity-100' : 'opacity-0'"
                    />
                </li>
            </ul>
        </div>
    </div>
</template>
<script>
    export default {
        name: 'TabField',
        props: {
            data: {
                type: String,
                default: '',
            },
            field: {
                type: Object,
                default(){
                    return {};
                },
            }
        },
        emits: ['update:data'],
        data(){
            return {
                values: {}
            };
        },
        computed: {
            tabSelected: {
                get(){
                    return this.data && this.data !== '' ? this.data :  (this.field?.options?.tabs?.[0]?.name ?? this.tabs[0].name);
                },
                set(val){

                    this.$emit('update:data', val);
                }
            },
            tabSelectedIndex(){
                return this.tabs.findIndex(tab => tab.name === this.tabSelected);
            },
            tabs(){
                return this.field?.options?.tabs ?? [];
            }
        },
        mounted() {
            if (!this.data || this.data === '') {
                this.$emit('update:data', this.tabSelected);
            }
        }
    };
</script>
