<i18n>
{
    "en": {
        "reset": "Reset",
        "discard_changes": "Discard changes"
    },
    "fr": {
        "reset": "Réinitialiser",
        "discard_changes": "Annuler les modifications"
    },
    "de": {
        "reset": "Zurücksetzen",
        "discard_changes": "Änderungen verwerfen"
    },
    "ja": {
        "reset": "リセット",
        "discard_changes": "変更を破棄する"
    }
}
</i18n>
<template>
    <template v-if="isLiteMode && (group.liteMode === isLiteMode || hideLiteMode.includes(group.group_name))"></template>
    <div
        v-else
        class="ecom-fields__group-wrapper"
        :class="{ 'ecom-fields__group-wrapper--site-settings': $parent?.isSettings }"
    >
        <div
            @click="onClickGroupsFields($event, {activeTab: isActiveGroup})"
            v-if="hasGroupTitle(group) && !isQuickToolBar"
            class="transition-all group hover:bg-surface-secondary px-[15px]"
            :class="
                [
                    isActiveGroup ? 'bg-surface-secondary sticky z-[9] border-b border-[#F1F1F1]' : 'relative bg-transparent',
                    classNameTop,
                    $parent.isSettings ? '!pl-[14px] !pr-[9px]' : '',
                    isElementPanelContext ? 'pr-[16px] pl-[16px]' : '',
                    isActiveGroup && isElementPanelContext ? 'bg-white border-none ecom-fields__group-body--ecom-sidebar': '',
                ]
            "
            >
            <button v-if="group.params.length > 0" type="button"
                class="!outline-none relative flex items-center justify-between transition-all w-full text-sm font-medium text-gray-600 group-hover:text-primary-700 duration-200 focus:outline-none py-2.5"
                :class="[
                    $parent.isSettings ? 'pl-0 !bg-transparent' : '',
                    isActiveGroup && !$parent.isSettings ? '' : '',
                    isActiveGroup && $parent.isSettings ? '' : '',
                    isActiveGroup &&isElementPanelContext ? '' : '',
                ]" @click="$parent.activeGroup = ($parent.activeGroup != index ? index : null)">
                <div
                    class="flex items-center justify-start content-start w-full"
                    :class="isActiveGroup ? '' : ''"
                >
                    <span
                        v-if="group.icon"
                        class="mr-3 "
                        v-html="group.icon"
                    />
                    <span
                        :class="[
                            $parent.isSettings ? ' text-[13px] leading-5 font-medium ':' text-[13px] leading-5 font-medium'
                        ]"
                        class="uppfirst line-clamp-1 flex-1 text-left text-text-primary"
                    >{{ group.group_title || 'Untitled' }}</span>
                    <span
                        class=" rounded transition"
                        :class="$parent.isSettings ? '' : 'py-1.5 -my-2'"
                    >
                        <EcomIcon v-if="(index === 0 || isActiveGroup) && loading" :source="icons.ecIconLoad"
                            class="flex justify-center items-center origin-center text-icon-primary group-hover:text-primary-800 transition-all duration-200 animate-spin"></EcomIcon>
                        <EcomIcon v-else :source="icons.CaretDownMinor"
                            class="flex justify-center items-center transform origin-center text-icon-primary group-hover:text-primary-800"
                            :class="isActiveGroup ? '-rotate-180' : 'rotate-0'"></EcomIcon>
                    </span>
                </div>
            </button>
            <button v-if="canResets[index] && (group.group_name || group.reset)" type="button"
                class="absolute text-gray-500 transition transform -translate-y-1/2 top-1/2 hover:text-gray-800  "
                :class="$parent.isSettings ? 'right-10' : 'right-[41px]'"
                :data-tooltip="$t('reset_all')" @click="resetGroupName(group)">
                <EcomIcon :source="icons.resetIcon" :size="'w-5 flex items-center'" :color="'text-icon-primary'"></EcomIcon>
            </button>
        </div>
        <keep-alive>
            <div v-if="$parent.activeGroup === index || isQuickToolBar" class="mb-2 px-[16px] relative z-[8] ecom-fields__group-body"
                :class="{
                    'py-2': isActiveGroup && !isQuickToolBar,
                    'ecom-fields__group-body--extend-sidebar': isActiveGroup && isSiteSettingsContext && !isQuickToolBar,
                    'pt-1.5 ecom-fields__group-body--ecom-sidebar': isActiveGroup && isElementPanelContext && !isQuickToolBar,
                    'ecom-fields__group-body--field-popup': isActiveGroup && isFieldPopupContext && !isQuickToolBar,
                    'rounded': isActiveGroup && deep === 0 && hasGroupTitle(group) && !isQuickToolBar
                }"
                ref="groupWrapper"
                >
                <div v-if="group.description" class="mb-4 text-sm text-gray-500 "
                    v-html="$helpers.markdown(group.description)" />
                <div
                    class="flex flex-wrap"
                    :class="isGlobalColorsGroup ? 'global-color-fields' : (isGlobalTypographyGroup ? 'global-typography-fields' : (isQuickToolBar ? '' : '-mx-2 gap-y-3'))"
                >
                    <GlobalColor v-if="isGlobalColorsGroup" />
                    <GlobalTypography v-else-if="isGlobalTypographyGroup" />
                    <GroupFields
                        v-else
                        :data="group"
                        :aipath="aipath"
                        :gparams="gparams"
                        :field-values="fieldValues"
                        :freeform="freeform"
                        :isQuickToolBar="isQuickToolBar"
                        @update:data="updateData"
                        @update:delete="updateData"
                        @update:clicked="$emit('update:clicked', $event)"
                    />
                </div>
                <div v-if="!hasGroupTitle(group) && canResets[index] && (group.group_name || group.reset)"
                    class="inline-block mt-5 ml-2">
                    <a href="#" class="flex items-center text-red-500 hover:underline" @click="resetGroupName(group)">
                        <EcomIcon :source="icons.resetIcon" :size="'w-5 flex items-center'" :color="'text-icon-primary'"></EcomIcon>
                        <span class="text-sm font-normal ml-2">{{ $t('discard_changes') }}</span>
                    </a>
                </div>
            </div>
        </keep-alive>
    </div>
</template>



<script lang="ts">
    import { mapGetters } from 'vuex';
    import GroupFields from './Group.vue';
    import {CaretDownMinor, resetIcon, ecIconLoad} from '@/assets/icons';
    import GlobalColor from '@/components/Settings/components/Color.vue';
    import GlobalTypography from '@/components/Settings/components/Typography.vue';
    import { eventBus } from '@/utils/eventBus';

    export default {
        inject: ['eventBus'],
        components: {
            GroupFields,
            GlobalColor,
            GlobalTypography
        },
        props: {
            data: {
                type: Object,
                default() {
                    return {}
                }
            },
            fieldValues: {
                type: Object,
                default() {
                    return {};
                }
            },
            fields: {
                type: Array,
                default() {
                    return [];
                }
            },
            index: {
                type: Number,
                default: 0
            },
            freeform: {
                type: Boolean,
                default: false
            },
            loading: {
                type: Boolean,
                default: false
            },
            lastActiveGroup: {
                type: Number,
                default: -1
            },
            aipath: {
                type: String,
                default: '',
            },
            type: {
                type: String,
                default: ''
            },
            isQuickToolBar: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:label', 'update:delete', 'update:clicked', 'update:data'],
        data() {
            return {
                valueDeleted: {},
                originalValues: {},
                canResets: {},
                icons: {
                    CaretDownMinor, resetIcon, ecIconLoad
                },
                hideLiteMode: [
                    'instagramImage',
                    'dividerGap',
                    'banner_image',
                    // 'image_lightbox',
                    'general_imageComp',
                    'item_content_timeline',
                    'thumbnail_timeline',
                    'box_item_locator',
                    'general_masonry',
                    // 'image_masonry',
                    'st_product_image',
                    'st_image',
                    'collections_flow',
                    'blog_meta_img',
                    'product_thumb',
                    'button_animation',
                    'quantity_general',
                    'attributes_spacing',
                    'gavatar',
                    // 'border',
                    'product_wishlist',
                    'product_actions',
                    'categories_item_thumbnail',
                    'gmap_general',
                    // 'image_categories',
                    // 'image_lightbox',
                    // 'Image_masonry'
                ]
            }
        },
        computed: {
            classNameTop() {
                if(this.isActiveGroup) {
                    switch(this.type) {
                        case 'element':
                            return 'top-[44px]'
                        default:
                            return 'top-0';
                    }
                }
                return ''
            },
            isActiveGroup() {
                return this.$parent.activeGroup === this.index;
            },
            group() {
                return this.data;
            },
            gparams(){
                if(this.isQuickToolBar) {
                    return this.group.params;
                }else {
                    return this.group.params.filter((p) => {
                        return p.type && this.$parent.fieldVisible(this.group, p);
                    });
                }
            },
            deep() {
                return this.$parent.deep;
            },
            values() {
                return this.fieldValues;
            },
            isGlobalColorsGroup() {
                return this.group?.group_name === 'global-colors' && this.$parent?.isSettings;
            },
            isGlobalTypographyGroup() {
                return this.group?.group_name === 'global-typography' && this.$parent?.isSettings;
            },
            /** Site settings panel (`#extend-sidebar`): Fields với `isSettings` */
            isSiteSettingsContext() {
                return !!this.$parent?.isSettings;
            },
            /** Editor sidebar (`#ecom-sidebar`): không site settings, không popup nổi */
            isElementPanelContext() {
                const p = this.$parent;
                return !!p && !p.isSettings && !p.ispop;
            },
            /** Popup field (Teleport): `Fields` với `ispop` */
            isFieldPopupContext() {
                const p = this.$parent;
                return !!p && !p.isSettings && !!p.ispop;
            },
            ...mapGetters('settings', [ 'isLiteMode' ]),
        },
        mounted() {
            this.originalValues = this.$helpers.copy(this.values);

            const groupWrapper = this.$refs.groupWrapper;

            this.$nextTick(() => {
                if(this.$parent.activeGroup === this.index) {
                    groupWrapper.style.height = 'auto';
                }
            })
        },
        unmounted() {
        },
        methods: {
            onClickGroupsFields(event, options) {
                setTimeout(() => {
                    const groupWrapper = event.target.closest('.ecom-fields__group-wrapper').parentElement;
                    const overflowAuto = event.target.closest('.overflow-auto');
                    //Scroll to top of group
                    if (overflowAuto) {
                        overflowAuto.scrollIntoView({behavior: 'smooth', block: 'start'});
                        const offset = groupWrapper.getBoundingClientRect().top;
                            overflowAuto.scrollBy({top: offset - 146, behavior: 'smooth'});
                    }
                }, 100);
                this.$emit('update:clicked', {event, ...options})
            },
            onUpdateRefresh(){
                this.$store.commit('UPDATE_REFRESH');
            },
            hasGroupTitle(group) {
                return (group.group_title && group.group_title !== '') || this.fields.length > 1;
            },
            resetGroupName (tab) {
                if (tab.group_name) {
                    if (this.originalValues[tab.group_name]) {
                        this.values[tab.group_name] = this.$helpers.copy(this.originalValues[tab.group_name]);
                    } else {
                        delete this.values[tab.group_name];
                    }
                } else if (tab.params){
                    tab.params.forEach((p) => {
                        if (p.name) {
                            if (this.originalValues[p.name]) {
                                this.values[p.name] = this.$helpers.copy(this.originalValues[p.name]);
                            } else {
                                delete this.values[p.name];
                            }
                        }
                    });
                }
                delete this.canResets[this.index];
                this.onUpdateRefresh();
            },
            updateData(field) {
                if(!field || field.type !== 'tab')
                    this.canResets[this.index] = true;
            },
            activeTabGroup() {
                if (this.$parent) {
                    this.$parent.activeGroup = 0;
                }
                this.onClickGroupsFields(null, {activeTab: true});
            },

        }
    };
</script>
<style>
    /*
     * Body khi group đang mở — thêm class modifier (kèm py-2 khi active):
     * - .ecom-fields__group-body--extend-sidebar → Site settings (#extend-sidebar, Fields isSettings)
     * - .ecom-fields__group-body--ecom-sidebar   → Panel docked, không popup (vd. #ecom-sidebar)
     * - .ecom-fields__group-body--field-popup    → Fields ispop (popup Teleport)
     * Ví dụ: .ecom-fields__group-body--extend-sidebar { padding-top: ... }
     */

    #sidebar-theme-settings-form  .-mx-2.relative.p-3{
        margin-left: 0px;
    }
</style>
