<i18n>
{
    "en": {
        "select": "Select",
        "cancel": "Cancel",
        "currently_selected": "Currently selected"
    },
    "fr": {
        "select": "Sélectionner",
        "cancel": "Annuler",
        "currently_selected": "Actuellement sélectionné"
    },
    "de": {
        "select": "Auswählen",
        "cancel": "Abbrechen",
        "currently_selected": "Aktuell ausgewählt"
    },
    "ja": {
        "select": "選択する",
        "cancel": "キャンセル",
        "currently_selected": "現在選択中"
    }
}
</i18n>
<template>
    <div
        class="bottom-0 left-0 w-full bg-white rounded-xl rounded-t-none relative  "
        :class="[{
            'h-[68px] flex flex-col justify-center': ['image', 'video'].includes(type),
            'border-t border-gray-200': !isBlank && !['image', 'video'].includes(type)
        }]"
    >
        <div
            v-show="!isBlank && !['image', 'video', 'icon'].includes(type)"
            class="relative flex items-center h-16 px-3 text-sm border-b border-gray-100 rounded-b-xl"
        >
            <template v-if="type == 'font'">
                <span
                    class="text-lg text-gray-800  truncate"
                    :style="{fontFamily: data?.[0]?.name}"
                >
                    {{ data?.[0]?.name }}
                </span>
            </template>
            <template v-else-if="type == 'product_type' || type == 'product_vendor'">
                <span class="text-gray-800 text-md">
                    {{ data?.[0]?.name }}
                </span>
            </template>
            <template v-else>
                <div v-if="type !== 'blog'" class="w-10 h-10">
                    <!-- <span
                        v-if="type === 'icon'"
                        class="text-gray-700 fill-current svg-full "
                        v-html="data?.[0]?.thumbnail || data?.[0]?.value"
                    /> -->
                    <img
                        v-if="type"
                        class="block object-cover w-full h-full border border-gray-100 rounded"
                        :src="currentImage(type, data?.[0]) ?? '/images/placeholder.png'"
                        :alt="data?.[0]?.name"
                    >
                </div>
                <div class="absolute text-xs text-text-primary  transform -translate-y-1/2 top-1/2 right-3 left-4" :class="{'pl-12': type !== 'blog'}">
                    <h6 class="truncate font-[550]">
                        {{ data?.[0]?.name }}
                    </h6>
                </div>
            </template>
        </div>
        <div class="py-2 flex items-center justify-start px-3.5 gap-2" :class="{'hidden': type == 'font', '!justify-end': type == 'image' || type == 'video' }">
            <s-button
                @click="onClickSelect"
                :disabled="isAIImageGenerator ||( !isChange && data?.length <= 0)"
                variant="primary"
                :class="!isChange || data?.length <= 0 ? 'border-transparent' : ''"
                class="!text-xs px-3"
                :data-xx="data?.length"
                >{{ text[1] }}</s-button>
            <s-button
                @click="onClickCancel"
                variant="secondary"
                :disabled="isAIImageGenerator"
                :outline="true">{{ text[0] }}</s-button>
            <!-- <Button
                class="border-gray-250"
                :text="text[1]"
                :type="!isChange || data?.length <= 0 ? 'disabled' : 'primary'"
                :class="!isChange || data?.length <= 0 ? 'border-transparent' : ''"
                @click="$emit('clickSelect')"
            /> -->
        </div>
    </div>
</template>

<script lang="ts">
    import { $t } from '@/plugins/i18n';
    import { fileMixin } from '../../mixins';
    export default {
        name: 'PickerFooter',
        mixins: [ fileMixin ],
        props: {
            // eslint-disable-next-line vue/require-default-prop
            data: [String, Array],
            multiple: {
                type: Boolean,
                default: false
            },
            isChange: {
                type: Boolean,
                default: false
            },
            type: {
                type: String,
                default: ''
            },
            textSelect: {
                type: String,
                default: $t('select')
            }

        },
        emits: ['clickCancel', 'clickSelect'],
        computed: {
            text () {
                return [this.$t('cancel'), this.textSelect];
            },
            isBlank () {
                if (!this.data) {
                    return true;
                }
                return this.multiple
                    || !this.data.length
                    || (this.data.length == 1
                        && this.data[0].name === false
                    );
            },
            isAIImageGenerator() {
                return this.type === 'image' && this.data?.[0]?.type === 'ai';
            }
        },
        methods: {
            onClickSelect() {
                // console.log('🐞 src/plugins/fields/components/picker/PickerFooter.vue: 144 👉', this);
                this.$emit('clickSelect');
            },
            onClickCancel() {
                this.$emit('clickCancel');
            }
        }
    };
</script>
<style>
    .footer-current:before,
    .footer-current:after {
      content: '';
      position: absolute;
      right: 0;
      left: 0;
      display: block;
      height: 0.25rem;
      pointer-events: none;
      transition: opacity 0.2s cubic-bezier(0.64, 0, 0.35, 1);
      top: -0.25rem;
    }
    /* .footer-current:before {
      background: linear-gradient(0deg, #dfe3e8 0.0625rem, transparent 0);
    } */
    .footer-current:after {
      background: linear-gradient(0deg, rgba(64, 64, 64, 0.1), transparent 0.25rem);
    }
</style>
