<template>
    <div class="ecom-element ecom-base-elements ecom-element__qrcode" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-element__qrcode--wrapper ecom-qr--wrapper">
            <figure v-if="hasQrContent || hasStaticQrImage">
                <Liquid v-if="useLiquidQrExport" :data="liquidQrCaptureCode" />
                <div class="ecom-container-qr ecom-qr-align">
                    <div class="ecom-qr-content-position ecom-qr-default">
                        <picture
                            v-if="!hasLinkWrap"
                            class="ecom-image-picture ecom-qr-picture"
                        >
                            <img
                                v-if="qrDisplaySrc"
                                :key="qrImageCacheKey"
                                class="ecom-element__qrcode--image"
                                :src="qrDisplaySrc"
                                :alt="qrAlt"
                                :width="qrSize"
                                :height="qrSize"
                                crossorigin="anonymous"
                                loading="lazy"
                            />
                            <div
                                v-else
                                class="ecom-element__qrcode--placeholder"
                                :class="{ 'ecom-element__qrcode--placeholder--hint': !!qrPreviewHint }"
                                :style="{ width: qrSize + 'px', height: qrSize + 'px' }"
                            >
                                <span v-if="qrPreviewHint" class="ecom-element__qrcode--placeholder-text">{{ qrPreviewHint }}</span>
                            </div>
                        </picture>
                        <a
                            v-else
                            :href="linkWrapHref"
                            :target="linkWrapTarget"
                            class="ecom-qr-picture-link ecom-image-picture"
                        >
                            <picture class="ecom-image-picture ecom-qr-picture">
                                <img
                                    v-if="qrDisplaySrc"
                                    :key="qrImageCacheKey"
                                    class="ecom-element__qrcode--image"
                                    :src="qrDisplaySrc"
                                    :alt="qrAlt"
                                    :width="qrSize"
                                    :height="qrSize"
                                    crossorigin="anonymous"
                                    loading="lazy"
                                />
                                <div
                                    v-else
                                    class="ecom-element__qrcode--placeholder"
                                    :class="{ 'ecom-element__qrcode--placeholder--hint': !!qrPreviewHint }"
                                    :style="{ width: qrSize + 'px', height: qrSize + 'px' }"
                                >
                                    <span v-if="qrPreviewHint" class="ecom-element__qrcode--placeholder-text">{{ qrPreviewHint }}</span>
                                </div>
                            </picture>
                        </a>
                    </div>
                </div>
            </figure>
            <div
                v-else
                class="ecom-element__qrcode--placeholder"
                :style="{ width: qrSize + 'px', height: qrSize + 'px' }"
            />
            <a
                v-if="data.settings?.download_button"
                href="#"
                role="button"
                class="ecom-element__qrcode--download ecom-qr--download"
            >
                {{ downloadLabel }}
            </a>

        </div>
    </div>
</template>

<script>
import { Element, Javascript, Liquid } from "@/mixins";
import { $t } from '@/plugins/i18n';
import {
    absoluteUrlFromShopPath,
    buildQrApiFingerprint,
    buildQrBuilderPreviewSrc,
    buildQrDataLiquidCapture,
    buildQrGeneratorApiParams,
    buildQrGeneratorLiquidImgSrc,
    buildQrGeneratorUrlFromParams,
    buildQrLiquidAltMarkup,
    buildQrLiquidProcessCode,
    ensureAbsoluteQrData,
    extractQrPayloadFromLiquidResult,
    hasLiquidInContent,
    isQrCustomLiquidSource,
    isQrLogoRecoverableError,
    isQrResolvedDataValid,
    normalizeLogoUrlForCompare,
    normalizeQrContent,
    qrApiErrorMessage,
    resolveLogoUrl,
    resolveQrGeneratorUrlWithValidation,
    stripHtmlForQrPayload,
    validateQrGeneratorUrl,
    validateQrLiquidSyntax,
    validateQrLogoAsset,
} from '@/utils/qrcodeApi';

/** Wait after typing before processLiquid / generator API (builder only). */
const QR_CONTENT_DEBOUNCE_MS = 700;

/**
 * Builder error surfaces (avoid cross-triggering):
 * - Toast: generator failures via showGeneratorErrorToast (dedup _lastGeneratorToastMessage)
 * - Field _qr_liquid_error: syntax + empty-after-render only (not builder iframe limits)
 * - Field _qr_logo_error: logo reject while logo URL unchanged (_logoRejectedUrl)
 * - Canvas qrPreviewHint: liquid awaiting / storefront-only preview (no duplicate field text)
 * - _logoRejectedUrl: omit logo from API URLs; NOT in qrDebounceTrigger fingerprint
 * - liquids() embed: omitLogo only when exporting (storefront); builder preview omits in JS
 * - _logoValidationFailedKey: skip repeat HEAD probes; _qrLastLiquidProcessKey: skip repeat processLiquid on logo-only change
 */

/** Fallback when processLiquid does not resolve in builder iframe. */
const QR_LIQUID_PROCESS_TIMEOUT_MS = 15000;

/** Keys snapshotted at Generator run (includes saved CDN url). */
const QR_CONTENT_SNAPSHOT_KEYS = [
    'content_source', 'content_type', 'content',
    'logo', 'logo_size',
    'qr_foreground_color', 'qr_background_color',
    'qr_size', 'margin_size',
    'qr_image',
];

/** Keys for dirty / Generator button (excludes qr_image). */
const QR_GENERATOR_SNAPSHOT_KEYS = QR_CONTENT_SNAPSHOT_KEYS.filter(
    (key) => key !== 'qr_image'
);

function deepCloneJson(value) {
    if (value === undefined || value === null) {
        return {};
    }
    return JSON.parse(JSON.stringify(value));
}

/** Deep-clone settings + style for debounced Worker / processLiquid snapshots. */
function cloneQrSnapshot(settings, style) {
    return {
        settings: deepCloneJson(settings),
        style: deepCloneJson(style),
    };
}

/** Default settings for new QR elements — also used to backfill empty drag-drop data. */
const QR_SETTINGS_DEFAULTS = {
    content_source: 'static_text',
    content_type: 'text',
    content: 'https://ecomposer.io',
    logo: '',
    logo_size: 20,
    margin_size: 2,
    qr_foreground_color: '#000000',
    qr_background_color: '#ffffff',
    qr_size: 200,
    qr_image: '',
    alignment: 'center',
    download_button: false,
    download_label: 'Download QR Code',
    _qr_dirty: false,
    _qr_saving: false,
    _qr_status: '',
    _qr_status_error: false,
    _qr_liquid_error: '',
    _qr_liquid_error_detail: false,
    _qr_logo_error: '',
    _qr_logo_error_detail: false
};

/** Style panel defaults for `.ecom-qr--download` — mirrors computed `css()`. */
const QR_DOWNLOAD_BTN_STYLE_DEFAULTS = {
    tab: 'normal',
    spacing: {
        padding: {
            top: '8px',
            right: '16px',
            bottom: '8px',
            left: '16px'
        },
        margin: {
            top: '8px'
        }
    },
    buttonTypography: {
        'font-size': '14px'
    },
    buttonColornormalmode: '#ffffff',
    buttonBackgroundnormalmode: {
        classic: {
            'background-color': '#000000'
        }
    },
    buttonBordernormalmode: {
        'border-style': 'none'
    },
    buttonBorderRadiusnormalmode: {
        top: '4px',
        right: '4px',
        bottom: '4px',
        left: '4px'
    }
};

function isQrDownloadBtnStyleUnset(styleGroup) {
    if (!styleGroup || typeof styleGroup !== 'object') {
        return true;
    }
    const hasColor = !!styleGroup.buttonColornormalmode;
    const hasBackground = !!styleGroup.buttonBackgroundnormalmode?.classic?.['background-color'];
    const hasPadding = !!styleGroup.spacing?.padding?.top;
    return !hasColor && !hasBackground && !hasPadding;
}

function mergeMissingStyleDefaults(target, defaults) {
    if (!defaults || typeof defaults !== 'object') {
        return target;
    }
    const out = target && typeof target === 'object' ? target : {};
    Object.keys(defaults).forEach((key) => {
        const defVal = defaults[key];
        const curVal = out[key];
        if (curVal === undefined || curVal === null || curVal === '') {
            out[key] = JSON.parse(JSON.stringify(defVal));
        } else if (
            defVal &&
            typeof defVal === 'object' &&
            !Array.isArray(defVal) &&
            curVal &&
            typeof curVal === 'object' &&
            !Array.isArray(curVal)
        ) {
            out[key] = mergeMissingStyleDefaults(curVal, defVal);
        }
    });
    return out;
}

export default {
    name: "Qrcode",
    docs: 'https://help.ecomposer.io/docs/editor-elements/basic-elements/qr-code-element/',
    mixins: [Element, Javascript, Liquid],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            // Only download_button: other API fields must NOT be here — Javascript mixin
            // sets edata.refresh on jsreactives change, which remounts the block and bypasses debounce.
            jsreactives: ['download_button'],
            _logoRejectedUrl: '',
            /** Normalized logo key — toast once per asset (ignores ?v= query churn). */
            _logoToastShownKey: '',
            /** Cached failed HEAD probe — skip repeat validateQrLogoAsset for same asset. */
            _logoValidationFailedKey: '',
            _logoValidationFailedError: null,
            /** Last custom Liquid content that triggered processLiquid POST. */
            _qrLastLiquidProcessKey: '',
            _debouncedQrDisplaySrc: '',
            /** Frozen settings/style for Worker + processLiquid in builder (updated after debounce). */
            _debouncedApiSnapshot: null,
            _qrContentDebounceTimer: null,
            /** Snapshot at last Generator run (or mount) — used for dirty check. */
            _qrSavedBaseline: null,
            /** True while a Shopify file upload is in-progress — guards against double-click. */
            _isSaving: false,
            /** Skip clearing status on the next debounce tick after Save finishes. */
            _qrSaveJustFinished: false,
            _qrStoreUnsub: null,
            /** Cancels stale generator validation when settings change quickly. */
            _qrValidateGen: 0,
            /** Avoid repeating the same generator error toast. */
            _lastGeneratorToastMessage: '',
            /** True while waiting for processLiquid after debounced custom Liquid input. */
            _qrLiquidAwaitingProcess: false,
            /** Clears stuck "Rendering Liquid…" when processLiquid never callbacks. */
            _qrLiquidProcessTimer: null,
            /**
             * True while mounted() is backfilling default settings + loading the initial
             * preview. Suppresses qrDebounceTrigger / color watchers so they don't schedule
             * a second, redundant debounced fetch racing the immediate mount-time preview.
             */
            _qrSuppressInitWatchers: false,
        };
    },
    watch: {
        'data.settings.download_button': {
            handler(enabled) {
                if (enabled && this.exporting === false) {
                    this.ensureQrDownloadBtnStyleDefaults();
                }
            }
        },
        'data.settings.qr_foreground_color': {
            deep: true,
            handler() {
                if (this._qrSuppressInitWatchers) return;
                this.onQrColorSettingChanged();
            }
        },
        'data.settings.qr_background_color': {
            deep: true,
            handler() {
                if (this._qrSuppressInitWatchers) return;
                this.onQrColorSettingChanged();
            }
        },
        'data.settings.logo': {
            deep: true,
            handler(newLogo, oldLogo) {
                const newKey = normalizeLogoUrlForCompare(resolveLogoUrl(newLogo));
                const oldKey = normalizeLogoUrlForCompare(resolveLogoUrl(oldLogo));
                if (newKey === oldKey) {
                    return;
                }
                this._logoRejectedUrl = '';
                this._logoToastShownKey = '';
                this._logoValidationFailedKey = '';
                this._logoValidationFailedError = null;
                this.clearQrLogoError();
            }
        },
        qrDebounceTrigger: {
            handler(newVal, oldVal) {
                if (this.exporting !== false) {
                    return;
                }
                // Skip: mounted() already loads the initial preview immediately.
                // Without this guard, ensureQrSettingsDefaults() backfilling default
                // settings on mount fires this watcher too, scheduling a second,
                // redundant debounced fetch to qr.ecomposer.app racing the first one.
                if (this._qrSuppressInitWatchers) {
                    return;
                }
                const settings = this.data.settings || {};
                // User changed QR content — dismiss stale save/publish status message.
                if (
                    !this._isSaving
                    && !this._qrSaveJustFinished
                    && oldVal !== undefined
                    && oldVal !== newVal
                    && settings._qr_status
                ) {
                    settings._qr_status = '';
                    settings._qr_status_error = false;
                }
                // _qr_liquid_error: only cleared by liquid validation (applyDebouncedCustomLiquidState / onCustomLiquidProcessed)
                this.updateQrDirtyState();
                if (!this.hasQrContent) {
                    this.clearDebouncedQrState();
                    return;
                }
                this.scheduleQrDisplayUpdate();
            }
        },
        'liquidData.content': {
            deep: true,
            handler() {
                if (this.exporting !== false || !this._debouncedApiSnapshot) {
                    return;
                }
                if (!isQrCustomLiquidSource(this._debouncedApiSnapshot.settings || {})) {
                    return;
                }
                this.onCustomLiquidProcessed('liquid-watch');
            }
        },
        'data.refresh'() {
            if (this.exporting !== false || !this._debouncedApiSnapshot) {
                return;
            }
            if (!isQrCustomLiquidSource(this._debouncedApiSnapshot.settings || {})) {
                return;
            }
            if (this._qrLiquidAwaitingProcess) {
                this.onCustomLiquidProcessed('liquid-refresh');
            }
        }
    },
    mounted() {
        if (this.exporting === false) {
            // Backfilling defaults below mutates data.settings.*, which would otherwise
            // trigger qrDebounceTrigger / color watchers and schedule a second, redundant
            // debounced fetch racing the immediate applyDebouncedQrState() call further down.
            this._qrSuppressInitWatchers = true;
            this.ensureQrSettingsDefaults();
            this.ensureQrDownloadBtnStyleDefaults();
            this.initQrBaseline();
            if (this.hasQrContent) {
                this.applyDebouncedQrState();
            }
            // Watchers triggered by the defaults above flush before nextTick resolves —
            // safe to lift the guard here so real user edits schedule normally again.
            this.$nextTick(() => {
                this._qrSuppressInitWatchers = false;
            });
            // Refresh baseline when template is published (popup shows View action).
            this._qrStoreUnsub = this.$store.subscribe((mutation) => {
                if (mutation.type !== 'builder/setPopup') return;
                const payload = mutation.payload || {};
                if (payload.show && payload.action?.link) {
                    this.onTemplatePublished();
                }
            });
        }
    },
    beforeUnmount() {
        if (this._qrContentDebounceTimer) {
            clearTimeout(this._qrContentDebounceTimer);
            this._qrContentDebounceTimer = null;
        }
        this.clearQrLiquidProcessTimer();
        if (this._qrStoreUnsub) {
            this._qrStoreUnsub();
            this._qrStoreUnsub = null;
        }
    },
    computed: {
        hasLinkWrap() {
            const link = this.data.settings?.link_wrap;
            return !!(link && link.href);
        },
        linkWrapHref() {
            return this.data.settings?.link_wrap?.href || '#';
        },
        linkWrapTarget() {
            return this.data.settings?.link_wrap?.target || '_self';
        },
        qrSize() {
            return parseInt(this.data.settings?.qr_size, 10) || 200;
        },
        qrAlt() {
            if (this.exporting === true && this.usesLiquidContent) {
                return 'liquid[[' + encodeURIComponent(buildQrLiquidAltMarkup()) + ']]';
            }
            const plain = stripHtmlForQrPayload(this.data.settings?.content);
            return plain ? `QR Code: ${plain.slice(0, 120)}` : 'QR Code';
        },
        hasQrContent() {
            return !!(this.data.settings?.content || '').trim();
        },
        /** True when a Shopify CDN image has been saved for this static QR element. */
        hasStaticQrImage() {
            return !!(this.data.settings?.qr_image || '').trim();
        },
        isProductTemplatePage() {
            return this.params?.page === 'product' || this.data?.template === 'product';
        },
        usesLiquidContent() {
            return isQrCustomLiquidSource(this.data.settings || {}) && this.hasQrContent;
        },
        useLiquidQrExport() {
            return this.exporting === true && this.usesLiquidContent;
        },
        liquidQrCaptureCode() {
            if (!this.usesLiquidContent) {
                return '';
            }
            return buildQrDataLiquidCapture(this.data.settings || {});
        },
        liquids() {
            const rawSettings = this.qrApiSettingsSource;
            const rawStyle = this.qrApiStyleSource;
            if (!rawSettings || !isQrCustomLiquidSource(rawSettings)) {
                return {};
            }
            const { settings, style } = this.qrApiPayload(rawSettings, rawStyle);
            // Builder: never toggle omitLogo in liquid embed — prevents reactiveLiquidRaw churn
            // (logo reject → processLiquid loop). Logo omit applied in computeLiquidBuilderSrc only.
            const omitLogo = this.exporting === true && this.shouldOmitLogoFor(rawSettings);
            return {
                qrCapture: {
                    code: buildQrDataLiquidCapture(settings),
                    preview: ''
                },
                qrImageSrc: {
                    code: buildQrGeneratorLiquidImgSrc(settings, style, { omitLogo }),
                    // Custom Liquid: no generator preview until processLiquid resolves data.
                    preview: ''
                },
                qrProcess: {
                    code: buildQrLiquidProcessCode(settings, style, { omitLogo }),
                    preview: ''
                }
            };
        },
        /** Builder: debounced snapshot only — stops processLiquid on every keystroke. */
        qrApiSettingsSource() {
            if (this.exporting !== false) {
                return this.data.settings || {};
            }
            return this._debouncedApiSnapshot?.settings || null;
        },
        qrApiStyleSource() {
            if (this.exporting !== false) {
                return this.data.style || {};
            }
            return this._debouncedApiSnapshot?.style || {};
        },
        shopOrigin() {
            const shop = this.$store.getters['page/shop'];
            if (shop?.url) {
                return String(shop.url).replace(/\/$/, '');
            }
            if (shop?.domain) {
                return `https://${String(shop.domain).replace(/\/$/, '')}`;
            }
            return (typeof window !== 'undefined' ? window.location.origin : '').replace(/\/$/, '');
        },
        /** Fingerprint of API-related inputs — used to debounce Worker refetch in builder. */
        qrDebounceTrigger() {
            if (!this.hasQrContent) {
                return '';
            }
            const { settings, style } = this.qrApiPayload(
                this.data.settings || {},
                this.data.style || {}
            );
            return buildQrApiFingerprint(
                settings,
                style,
                // omitLogo is internal (_logoRejectedUrl) — must not re-trigger debounce loop
                { omitLogo: false }
            ) + '|' + (this.data.settings?.content || '').trim()
                + '|' + (this.data.settings?.content_source || 'static_text');
        },
        /** Builder: debounced `src` only; export/preview: live settings. */
        qrDisplaySrc() {
            if (this.exporting !== false) {
                return this.computeQrDisplaySrcFromLive();
            }
            if (!this.hasQrContent) {
                return '';
            }
            return this._debouncedQrDisplaySrc;
        },
        /** Builder-only hint when QR image cannot be previewed (e.g. Liquid fails on localhost). */
        qrPreviewHint() {
            if (this.exporting !== false || this.qrDisplaySrc || !this.hasQrContent) {
                return '';
            }
            const settings = this.data.settings || {};
            if (this._qrLiquidAwaitingProcess) {
                return 'Rendering Liquid…';
            }
            if (isQrCustomLiquidSource(settings)) {
                if (settings._qr_liquid_error) {
                    return '';
                }
                return 'Preview unavailable in editor. Check Liquid or view on your storefront.';
            }
            return 'Loading QR preview…';
        },
        qrImageCacheKey() {
            if (this.exporting === true && this.usesLiquidContent) {
                return 'qr-liquid-export';
            }
            return this.qrDisplaySrc || 'qr-empty';
        },
        shouldOmitLogo() {
            return this.shouldOmitLogoFor(this.data.settings || {});
        },
        downloadLabel() {
            const label = String(this.data.settings?.download_label || '').trim();
            return this.lang(label || 'Download QR Code', 'download_label');
        },
        css() {
            return `
                .ecom-element__qrcode--wrapper {
                    display: block;
                }
                .ecom-container-qr {
                    display: inline-block;
                    max-width: 100%;
                }
                .ecom-qr-picture .ecom-element__qrcode--image,
                .ecom-qr-picture img {
                    display: inline-block;
                    vertical-align: middle;
                    max-width: 100%;
                    height: auto;
                    width: auto;
                }
                .ecom-qr-picture-link {
                    display: inline-block;
                    line-height: 0;
                }
                .ecom-element__qrcode--placeholder {
                    display: inline-block;
                    vertical-align: middle;
                    background: #f3f4f6;
                }
                .ecom-element__qrcode--placeholder--hint {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    box-sizing: border-box;
                    padding: 8px;
                    background: #fffbeb;
                    border: 1px dashed #f59e0b;
                }
                .ecom-element__qrcode--placeholder-text {
                    display: block;
                    text-align: center;
                    font-size: 11px;
                    line-height: 1.35;
                    color: #92400e;
                    max-width: 100%;
                    word-break: break-word;
                }
                .ecom-element__qrcode--download {
                    display: inline-block;
                    margin-top: 8px;
                    padding: 8px 16px;
                    background-color: #000000;
                    color: #ffffff;
                    text-decoration: none;
                    border-radius: 4px;
                    font-size: 14px;
                    cursor: pointer;
                    border: none;
                }
                .ecom-element__qrcode--download:hover {
                    opacity: 0.85;
                }
            `;
        },
        javascript() {
            if (!this.data.settings?.download_button) {
                return function () {};
            }
            return function () {
                const $el = this.$el;
                if (!$el) return;

                const downloadBtn = $el.querySelector('.ecom-qr--download');
                if (!downloadBtn || downloadBtn.getAttribute('data-ecom-qr-bound')) {
                    return;
                }
                downloadBtn.setAttribute('data-ecom-qr-bound', '1');

                const fileName = 'qrcode.jpg';

                const triggerBlobDownload = function (blobUrl) {
                    const link = document.createElement('a');
                    link.href = blobUrl;
                    link.download = fileName;
                    link.rel = 'noopener';
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                };

                const downloadFromUrl = async function (href) {
                    if (href.startsWith('data:') || href.startsWith('blob:')) {
                        triggerBlobDownload(href);
                        return;
                    }

                    const res = await fetch(href, { mode: 'cors', credentials: 'omit' });
                    if (!res.ok) {
                        throw new Error('QR download failed');
                    }
                    const blob = await res.blob();
                    const blobUrl = URL.createObjectURL(blob);
                    triggerBlobDownload(blobUrl);
                    URL.revokeObjectURL(blobUrl);
                };

                const downloadViaCanvas = function (imageEl) {
                    const canvas = document.createElement('canvas');
                    const w = imageEl.naturalWidth || imageEl.width || 200;
                    const h = imageEl.naturalHeight || imageEl.height || 200;
                    canvas.width = w;
                    canvas.height = h;
                    const ctx = canvas.getContext('2d');
                    if (!ctx) {
                        throw new Error('Canvas unavailable');
                    }
                    ctx.drawImage(imageEl, 0, 0, w, h);
                    const dataUrl = canvas.toDataURL('image/jpeg', 0.92);
                    triggerBlobDownload(dataUrl);
                };

                downloadBtn.addEventListener('click', function (e) {
                    e.preventDefault();
                    e.stopPropagation();

                    const img = $el.querySelector('.ecom-qr-picture img');
                    if (!img) {
                        return;
                    }
                    const href = img.getAttribute('src');
                    if (!href || href === '#') {
                        return;
                    }

                    const runCanvasFallback = function () {
                        try {
                            downloadViaCanvas(img);
                        } catch (canvasErr) {
                            console.warn('[QR Code] Download failed:', canvasErr);
                        }
                    };

                    downloadFromUrl(href).catch(function () {
                        if (img.complete && img.naturalWidth) {
                            runCanvasFallback();
                            return;
                        }
                        img.addEventListener('load', runCanvasFallback, { once: true });
                    });
                });
            };
        },
        default() {
            return {
                settings: JSON.parse(JSON.stringify(QR_SETTINGS_DEFAULTS)),
                style: {
                    qr_download_btn: JSON.parse(JSON.stringify(QR_DOWNLOAD_BTN_STYLE_DEFAULTS))
                }
            };
        }
    },
    methods: {
        /**
         * Resolve QR color setting — plain hex or `{ 'global-colors': 'primary' }`.
         * Mirrors Field.vue valueGlobal() for the Worker API (needs literal hex).
         */
        resolveQrSettingColor(value) {
            if (value === undefined || value === null || value === '') {
                return '';
            }
            if (typeof value === 'string') {
                return value.trim();
            }
            if (typeof value === 'object' && !Array.isArray(value)) {
                for (const key of Object.keys(value)) {
                    if (!key.startsWith('global-')) {
                        continue;
                    }
                    const globalKey = value[key];
                    if (typeof globalKey !== 'string' || !globalKey) {
                        continue;
                    }
                    const type = /^global-([\w]+)/.exec(key)?.[1];
                    if (!type) {
                        continue;
                    }
                    const entry = this.$store.getters['settings/globalData'](type)?.[globalKey];
                    const resolved = entry?.value;
                    if (typeof resolved === 'string' && resolved.trim()) {
                        return resolved.trim();
                    }
                    if (resolved && typeof resolved === 'object') {
                        const classic = resolved.classic?.['background-color']
                            || resolved.color;
                        if (typeof classic === 'string' && classic.trim()) {
                            return classic.trim();
                        }
                    }
                }
            }
            return '';
        },
        /** Clone settings/style with global color refs resolved to hex for qr.ecomposer.app. */
        qrApiPayload(settings, style) {
            const s = { ...(settings || {}) };
            const st = { ...(style || {}) };
            const fg = this.resolveQrSettingColor(s.qr_foreground_color)
                || this.resolveQrSettingColor(st.qr_foreground_color);
            if (fg) {
                s.qr_foreground_color = fg;
            }
            const bg = this.resolveQrSettingColor(s.qr_background_color)
                || this.resolveQrSettingColor(st.qr_background_color);
            if (bg) {
                s.qr_background_color = bg;
            }
            return { settings: s, style: st };
