        ensureQrSettingsDefaults() {
            if (this.exporting !== false) {
                return;
            }
            if (!this.data.settings) {
                this.data.settings = {};
            }
            const settings = this.data.settings;
            const contentDefault = this.defaultQrContentValue();
            if (!(String(settings.content || '').trim())) {
                settings.content = contentDefault;
            }
            Object.keys(QR_SETTINGS_DEFAULTS).forEach((key) => {
                if (key === 'content') {
