            const current = this.data.style.qr_download_btn;
            const merged = isQrDownloadBtnStyleUnset(current)
                ? JSON.parse(JSON.stringify(QR_DOWNLOAD_BTN_STYLE_DEFAULTS))
                : mergeMissingStyleDefaults(
                    JSON.parse(JSON.stringify(current || {})),
                    QR_DOWNLOAD_BTN_STYLE_DEFAULTS
