            const logoKey = normalizeLogoUrlForCompare(logo);
            if (this.shouldOmitLogoFor(snapshot.settings)) {
                return false;
            }
            if (
                logoKey
                && this._logoValidationFailedKey === logoKey
                && this._logoValidationFailedError
            ) {
                if (logo) {
                    this._logoRejectedUrl = logo;
                }
                this.setQrLogoError(this._logoValidationFailedError);
                return true;
            }
            const check = await validateQrLogoAsset(logo);
            if (gen !== this._qrValidateGen) {
                return false;
            }
            if (check.ok) {
                if (this._logoValidationFailedKey === logoKey) {
                    this._logoValidationFailedKey = '';
                    this._logoValidationFailedError = null;
