                this._logoRejectedUrl = logoUrl;
            }
            if (logoKey && errorPayload) {
                this._logoValidationFailedKey = logoKey;
                this._logoValidationFailedError = errorPayload;
            }
            this.setQrLogoError(errorPayload);
            if (!logoKey || this._logoToastShownKey === logoKey) {
                return;
            }
            this._logoToastShownKey = logoKey;
            this.showGeneratorErrorToast(errorPayload, { logoFallbackApplied: true });
