        _snapshotQrContentSettings(settings) {
            const snapshot = {};
            for (const key of this._qrContentKeys()) {
                const val = settings[key];
                if (val === undefined || val === null) {
                    snapshot[key] = null;
                } else {
                    snapshot[key] = deepCloneJson(val);
                }
            }
            return snapshot;
        },
        /** Snapshot at last successful Generator run (or mount). Not updated on Publish. */
        initQrBaseline() {
            this._qrSavedBaseline = this._snapshotQrContentSettings(this.data.settings || {});
        },
        /** True when QR visual settings differ from last Generator baseline. */
        isQrGeneratorPending(settings = this.data.settings || {}) {
            if (!this._qrSavedBaseline || isQrCustomLiquidSource(settings)) {
