            }
        },
        /** Upload the current QR settings as a static image to Shopify Files. */
        async saveQrContent() {
            if (this._isSaving) return;
            const settings = this.data.settings || {};
            if (isQrCustomLiquidSource(settings)) return;
            const { settings: apiSettings, style: apiStyle } = this.qrApiPayload(
                settings,
                this.data.style
            );
            const snapshot = cloneQrSnapshot(apiSettings, apiStyle);
            const generatorUrl = this.computeStaticBuilderSrc(snapshot);
            if (!generatorUrl) return;
            this._isSaving = true;
            settings._qr_saving = true;
            settings._qr_status = '';
            settings._qr_status_error = false;
            try {
                const res = await this.$worker.fetch(
                    window.route('builder.files.replace-from-url'),
                    {
                        url: generatorUrl,
                        alt: this.qrAlt,
                        wait_for_url: '1',
                        element_id: this.data.id,
                    },
                    'POST'
                );
                const api = res?.data || {};
                if (api.status === 'success' && api.url) {
                    this._qrSaveJustFinished = true;
                    settings.qr_image = api.url;
                    this.initQrBaseline();
                    settings._qr_dirty = false;
                    settings._qr_status = 'QR code saved successfully!';
                    settings._qr_status_error = false;
                } else {
                    const msg = api.message || api.debug?.message || 'Failed to save QR code.';
                    settings._qr_status = msg;
                    settings._qr_status_error = true;
                }
            } catch (e) {
                console.warn('[QR Code] saveQrContent error:', e);
                settings._qr_status = 'Failed to save QR code.';
                settings._qr_status_error = true;
            } finally {
                this._isSaving = false;
                settings._qr_saving = false;
                this.$nextTick(() => {
                    this.updateQrDirtyState();
                    this._qrSaveJustFinished = false;
                });
            }
        },
        scheduleQrDisplayUpdate() {
            if (this._qrContentDebounceTimer) {
                clearTimeout(this._qrContentDebounceTimer);
            }
            this._qrContentDebounceTimer = setTimeout(() => {
                this._qrContentDebounceTimer = null;
                this.applyDebouncedQrState();
            }, QR_CONTENT_DEBOUNCE_MS);
        },
        applyDebouncedQrState() {
            const { settings, style } = this.qrApiPayload(
                this.data.settings,
                this.data.style
            );
            const snapshot = cloneQrSnapshot(settings, style);
            const gen = ++this._qrValidateGen;

            if (!isQrCustomLiquidSource(settings)) {
                this.clearQrLiquidError();
            }

            if (isQrCustomLiquidSource(settings)) {
                this.clearQrLiquidProcessTimer();
                this._qrLiquidAwaitingProcess = true;
                this._debouncedQrDisplaySrc = '';
            }

