        /**
         * Debounced preview pipeline (builder only).
         *
         *   validateSnapshotLogo (HEAD probe, may set _logoRejectedUrl)
         *        |
         *        +-- custom_liquid --> applyDebouncedCustomLiquidState
         *        |                      (syntax guard -> processLiquid OR reuse cache)
         *        |                      -> onCustomLiquidProcessed -> applyLiquidPreviewWithValidation
         *        |
         *        +-- static_text + logo rejected --> quickSrc without logo
         *        |                      -> refreshQrPreviewWithoutLogo
         *        |
         *        +-- static_text + logo OK --> applyPreviewWithValidation
         */
        async runDebouncedQrPreview(snapshot, gen) {
            const isLiquid = isQrCustomLiquidSource(snapshot.settings || {});

            const logoRejected = await this.validateSnapshotLogo(snapshot, gen);
            if (gen !== this._qrValidateGen) {
                return;
            }

            // Custom Liquid: always run processLiquid after logo check (_logoRejectedUrl may be set)
            if (isLiquid) {
                this.applyDebouncedCustomLiquidState(snapshot);
                return;
            }

            if (logoRejected) {
                const quickSrc = this.computeStaticBuilderSrc(snapshot) || '';
                if (quickSrc) {
                    this._debouncedQrDisplaySrc = quickSrc;
                }
                await this.refreshQrPreviewWithoutLogo(snapshot, gen);
                return;
            }

            await this.applyPreviewWithValidation(snapshot, gen);
        },
        setQrLiquidError(message) {
            const settings = this.data.settings;
            if (!settings) return;
            settings._qr_liquid_error = message;
            settings._qr_liquid_error_detail = true;
        },
        clearQrLiquidError() {
            const settings = this.data.settings;
            if (!settings) return;
            settings._qr_liquid_error = '';
            settings._qr_liquid_error_detail = false;
        },
        /** Debounced custom Liquid: syntax guard → processLiquid only (API after render). */
        applyDebouncedCustomLiquidState(snapshot) {
            const content = snapshot.settings?.content || '';
            try {
                const syntaxCheck = validateQrLiquidSyntax(content);
                if (!syntaxCheck.ok) {
                    this.clearQrLiquidProcessTimer();
                    this._qrLiquidAwaitingProcess = false;
                    this._debouncedQrDisplaySrc = '';
                    this.setQrLiquidError(syntaxCheck.message);
                    return;
                }
            } catch (e) {
                this.clearQrLiquidProcessTimer();
                this._qrLiquidAwaitingProcess = false;
                this._debouncedQrDisplaySrc = '';
                this.setQrLiquidError(
                    e instanceof Error ? e.message : 'Invalid Liquid syntax.'
                );
                return;
            }

            this.clearQrLiquidError();

            const liquidProcessKey = [
                (snapshot.settings?.content || '').trim(),
                snapshot.settings?.content_source || 'static_text',
            ].join('|');
            const resolved = this.resolveLiquidDataFromProcess();
            const canReuseLiquidProcess = this._qrLastLiquidProcessKey === liquidProcessKey
                && !!(resolved && !hasLiquidInContent(resolved));

            if (canReuseLiquidProcess) {
                this._qrLiquidAwaitingProcess = false;
                const gen = ++this._qrValidateGen;
                void this.applyLiquidPreviewWithValidation(snapshot, gen);
                return;
            }

            this._qrLastLiquidProcessKey = liquidProcessKey;
            this._debouncedQrDisplaySrc = '';
            this.$nextTick(() => {
                this.reactiveLiquid();
                this.$nextTick(() => {
                    if (!this._qrLiquidAwaitingProcess) {
                        return;
                    }
                    const resolvedAfter = this.resolveLiquidDataFromProcess();
                    if (resolvedAfter && !hasLiquidInContent(resolvedAfter)) {
                        this.onCustomLiquidProcessed('liquid-poll');
                        return;
                    }
                    this.scheduleQrLiquidProcessFallback();
                });
            });
        },
        /** After processLiquid returns — validate data, then call generator API if non-empty. */
        onCustomLiquidProcessed(source = 'liquid-poll') {
            const snapshot = this._debouncedApiSnapshot;
            if (!snapshot || !isQrCustomLiquidSource(snapshot.settings || {})) {
                return;
            }

            const resolvedRaw = this.resolveLiquidDataFromProcess();
            const stillUnresolved = !!(resolvedRaw && hasLiquidInContent(resolvedRaw));
            const processOutput = (this.liquidData?.content?.qrProcess || '').trim();

            // Ignore premature store updates before processLiquid finishes.
            if (
                source === 'liquid-watch'
                && this._qrLiquidAwaitingProcess
                && !processOutput
                && !resolvedRaw
            ) {
                return;
            }
            if (source === 'liquid-watch' && stillUnresolved) {
                return;
            }

            this.clearQrLiquidProcessTimer();
            this._qrLiquidAwaitingProcess = false;

            try {
                const payload = extractQrPayloadFromLiquidResult(resolvedRaw);

                if (!isQrResolvedDataValid(payload)) {
                    this._debouncedQrDisplaySrc = '';
                    const content = (snapshot.settings?.content || '').trim();
                    if (!content) {
                        this.clearQrLiquidError();
                        return;
                    }
                    if (this.isQrLiquidUnresolvableInBuilder(content, resolvedRaw, stillUnresolved)) {
                        this.clearQrLiquidError();
                        return;
                    }
                    this.setQrLiquidError(
                        'QR content is empty after Liquid renders. Check your variables or syntax.'
                    );
                    return;
                }

                this.clearQrLiquidError();
                const gen = ++this._qrValidateGen;
                this.applyLiquidPreviewWithValidation(snapshot, gen);
            } catch (e) {
                this._debouncedQrDisplaySrc = '';
                this.setQrLiquidError(
                    e instanceof Error ? e.message : 'Failed to render Liquid for QR code.'
                );
            }
        },
        showGeneratorErrorToast(errorPayload, options = {}) {
            if (!errorPayload) return;
            const message = qrApiErrorMessage(errorPayload.error, {
                ...options,
                details: errorPayload.details
            });
            if (!message || this._lastGeneratorToastMessage === message) return;
            this._lastGeneratorToastMessage = message;
