                const logoUrl = resolveLogoUrl(settings.logo);
                if (logoUrl && this.isLogoRejectedForUrl(logoUrl)) {
                    this.setQrLogoError(result.lastError);
                } else {
                    this.handleLogoReject(logoUrl, result.lastError);
                }
            } else if (!result.validation.ok && result.lastError) {
