                if (gen === this._qrValidateGen) {
                    this._debouncedQrDisplaySrc = url || '';
                }
                return;
            }
            const payload = extractQrPayloadFromLiquidResult(
                this.resolveLiquidDataFromProcess()
            );
            if (!isQrResolvedDataValid(payload)) {
                if (gen === this._qrValidateGen) {
                    this._debouncedQrDisplaySrc = '';
                }
                return;
            }
            const hasLogo = !this.shouldOmitLogoFor(snapshot.settings)
                && !!resolveLogoUrl(snapshot.settings.logo);
            const logoUrl = hasLogo ? resolveLogoUrl(snapshot.settings.logo) : '';
