                const rejectedLogo = resolveLogoUrl(snapshot.settings.logo);
                this.handleLogoReject(rejectedLogo, check);
                const urlNoLogo = this.computeLiquidBuilderSrc(snapshot);
                if (gen === this._qrValidateGen) {
                    this._debouncedQrDisplaySrc = urlNoLogo || '';
                }
                return;
            }
            if (
                !isQrLogoRecoverableError(check.error)
                || !this.isLogoRejectedForUrl(resolveLogoUrl(snapshot.settings.logo))
            ) {
                this.showGeneratorErrorToast(check);
            }
            if (gen === this._qrValidateGen) {
                const urlNoLogo = this.computeLiquidBuilderSrc(snapshot);
                this._debouncedQrDisplaySrc = urlNoLogo || '';
            }
