        async applyPreviewWithValidation(snapshot, parentGen) {
            const { settings, style } = snapshot;
            const gen = parentGen ?? ++this._qrValidateGen;
            if (isQrCustomLiquidSource(settings)) {
                return;
            }
            const result = await resolveQrGeneratorUrlWithValidation(settings, style, {
                omitLogo: this.shouldOmitLogoFor(settings),
            });
