            this.applyGeneratorValidationResult(result);
            this._debouncedQrDisplaySrc = result.url || '';
        },
        shouldOmitLogoFor(settings) {
            const logo = resolveLogoUrl(settings?.logo);
            if (!logo) return true;
            return this.isLogoRejectedForUrl(logo);
        },
        resolvePreviewDataForSettings(settings) {
            if (this.isProductTemplatePage && this.shopOrigin) {
                const handle = this.section?.settings?.product
                    || this.$store.getters['page/params']?.handle;
                if (handle) {
                    return absoluteUrlFromShopPath(
                        this.shopOrigin,
                        `/products/${handle}`
                    );
                }
            }
            return '';
        },
        resolveLiquidDataFromProcess() {
            const fromProcess = this.liquidData?.content?.qrProcess
                || this.liquidData?.content?.qrImageSrc;
            if (!fromProcess || typeof fromProcess !== 'string' || hasLiquidInContent(fromProcess)) {
                return '';
            }
            const trimmed = fromProcess.trim();
            if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
                return trimmed;
            }
            if (trimmed.startsWith('https://qr.ecomposer.app/')) {
                try {
                    const u = new URL(trimmed);
                    const data = u.searchParams.get('data');
                    if (data) {
                        return ensureAbsoluteQrData(data);
