            const omitLogo = this.shouldOmitLogoFor(settings);
            const params = buildQrGeneratorApiParams(settings, style, { omitLogo });
            return params ? buildQrGeneratorUrlFromParams(params) : '';
        },
        computeLiquidBuilderSrc(snapshot) {
            const { settings, style } = snapshot;
            const omitLogo = this.shouldOmitLogoFor(settings);
            const resolved = this.resolveLiquidDataFromProcess();
            if (!resolved || hasLiquidInContent(resolved)) {
                return '';
            }
            if (resolved.startsWith('https://qr.ecomposer.app/')) {
                const payload = extractQrPayloadFromLiquidResult(resolved);
                return isQrResolvedDataValid(payload) ? resolved : '';
            }
            const payload = extractQrPayloadFromLiquidResult(resolved) || resolved;
            if (!isQrResolvedDataValid(payload)) {
                return '';
