        /**
         * Export / preview src:
         * - static_text + qr_image (after Generator): Shopify CDN
         * - static_text without qr_image: generator API URL
         * - custom_liquid: generator API via Liquid (storefront renders at runtime)
         */
        computeQrDisplaySrcFromLive() {
            const { settings, style } = this.qrApiPayload(
                this.data.settings || {},
                this.data.style || {}
            );
            const savedCdn = (this.data.settings?.qr_image || '').trim();
            const isPublishedOutput = this.exporting !== false;

            if (!isQrCustomLiquidSource(settings)) {
                if (isPublishedOutput && savedCdn) {
                    return savedCdn;
                }
                if (!this.hasQrContent) {
                    return '';
                }
                return this.computeStaticBuilderSrc({ settings, style });
            }

            // custom_liquid: always generator API on storefront (Liquid embed)
            if (this.exporting === true) {
                return this.liquid('qrImageSrc');
            }
            if (!this.hasQrContent) {
                return '';
            }
            // Preview iframe: use resolved API URL when processLiquid succeeded
            return this.computeLiquidBuilderSrc({ settings, style });
        },
        buildQRContent() {
            return normalizeQrContent(this.data.settings);
        },
        quickToolBar() {
            return ['qr_size', 'qr_foreground_color', 'qr_background_color'];
        },
        requestShopifyType() {
            const page = this.params?.page;
            const types = ['collection', 'product', 'blog', 'article', 'page'];
            return types.includes(page) ? { shopify_type: page } : null;
        },
        contentFieldParam() {
            const isCustomLiquid = (this.data.settings?.content_source || 'static_text') === 'custom_liquid';
            const defaultContent = isCustomLiquid
                ? (this.isProductTemplatePage
                    ? '{{ shop.url }}{{ product.url }}'
                    : '{{ shop.url }}/pages/about-us')
                : QR_SETTINGS_DEFAULTS.content;
            return {
                type: 'text',
                name: 'content',
                label: $t('content'),
                value: defaultContent,
                placeholder: isCustomLiquid
                    ? (this.isProductTemplatePage
                        ? '{{ shop.url }}{{ product.url }}'
                        : '{{ shop.url }}/pages/about-us')
                    : 'https://example.com',
                description: isCustomLiquid
                    ? 'You can use Liquid code here to display dynamic content, such as metafields.'
                    : undefined
            };
        },
        contentSettingsParams() {
            return [
                {
                    type: 'paragraph',
                    name: '_qr_update_notice',
                    options: {
                        warnings: {
                            content: 'You changed the QR code settings. Click "Upload QR Code" button to update the image saved on your store.'
                        },
                        visible: {
                            keep_data: true,
                            condition: (data) => (data?.content_source || 'static_text') === 'static_text'
                                && !!(data?.qr_image || '').trim()
                                && !!data?._qr_dirty
                        }
                    }
                },
                {
                    type: 'popup',
                    name: 'content_source',
                    label: 'Content Source',
                    value: 'static_text',
                    options: {
                        type: 'dropdown',
                        default: false,
                        preview: 'title',
                        values: {
                            static_text: 'Static Text',
                            custom_liquid: 'Custom Liquid'
                        }
                    },
                    css: { isCss: false }
                },
                {
                    type: 'popup',
                    name: 'content_type',
                    label: 'Content Type',
                    options: {
                        type: 'dropdown',
                        default: false,
                        preview: 'title',
                        values: {
                            text: 'Text',
                            link: 'Link',
                            phone: 'Phone',
                            email: 'Email',
                            whatsapp: 'WhatsApp'
                        },
                        visible: (data) => (data?.content_source || 'static_text') === 'static_text'
                    },
                    css: { isCss: false }
                },
                this.contentFieldParam(),
                {
                    type: 'custom_status',
                    name: '_qr_liquid_error_display',
                    options: {
                        statusKey: '_qr_liquid_error',
                        errorKey: '_qr_liquid_error_detail',
                        visible: {
                            keep_data: true,
                            condition: (data) => (data?.content_source || 'static_text') === 'custom_liquid'
                                && !!data?._qr_liquid_error
                        }
                    }
                },
                {
                    type: 'picker',
                    name: 'logo',
                    label: 'Logo',
                    options: {
                        type: 'image'
                    },
                    description: 'Use PNG, JPEG, WebP, or GIF (HTTPS, max 1 MB). SVG is not supported.'
                },
                {
                    type: 'custom_status',
                    name: '_qr_logo_error_display',
                    options: {
                        statusKey: '_qr_logo_error',
                        errorKey: '_qr_logo_error_detail',
                        visible: {
                            keep_data: true,
                            condition: (data) => !!resolveLogoUrl(data?.logo) && !!data._qr_logo_error
                        }
                    }
                },
                {
                    type: 'number',
                    name: 'logo_size',
                    label: 'Logo size (% of QR code)',
                    value: 20,
                    description: 'Percent of QR symbol side (10–30%). Maps to Worker API logoRatio.',
                    options: {
                        min: 10,
                        max: 30,
                        step: 1,
                        visible: (data) => !!(data && data['logo'])
                    }
                },
                {
                    type: 'number',
                    name: 'margin_size',
                    label: 'Quiet Zone',
                    value: 2,
                    options: {
                        min: 0,
                        max: 16,
                        step: 1
                    }
                },
                {
                    type: 'number',
                    name: 'qr_size',
                    label: $t('size'),
                    value: 200,
                    options: {
                        min: 80,
                        max: 600,
                        step: 1
                    }
                },
                {
                    type: 'color',
                    name: 'qr_foreground_color',
                    label: 'QR Color',
                    value: '#000000',
                    options: {
                        global: { type: 'colors' }
                    },
                    css: { isCss: false }
                },
                {
                    type: 'color',
                    name: 'qr_background_color',
                    label: 'Background Color',
                    value: '#ffffff',
                    options: {
                        global: { type: 'colors' }
                    },
                    css: { isCss: false }
                },
                {
                    type: 'custom_button',
                    name: '_qr_save',
                    description: 'Upload the QR code image to your Shopify store. Re-upload whenever you change QR settings before publishing.',
                    options: {
                        text: (data) => data?._qr_saving ? 'Uploading...' : 'Upload QR Code',
                        variant: 'secondary',
                        loading: (data) => !!data?._qr_saving,
                        disabled: (data) => !!data?._qr_saving,
                        wrapperClass: 'py-1 flex justify-center w-full',
                        visible: {
                            keep_data: true,
                            condition: (data) => (data?.content_source || 'static_text') === 'static_text'
                        }
                    }
                },
                {
                    type: 'custom_status',
                    name: '_qr_status_display',
                    options: {
                        statusKey: '_qr_status',
                        errorKey: '_qr_status_error',
                        visible: {
                            keep_data: true,
                            condition: (data) => (data?.content_source || 'static_text') === 'static_text' && !!data?._qr_status
                        }
                    }
                }
            ];
        },
        settings() {
            return [
                {
                    group_title: $t('content'),
                    group_name: '',
                    params: this.contentSettingsParams()
                },
                {
                    group_title: $t('display'),
                    group_name: '',
                    params: [
                        
                        {
                            type: 'popup',
                            name: 'alignment',
                            label: $t('alignment'),
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    left: $t('left'),
                                    center: $t('center'),
                                    right: $t('right')
                                }
                            },
                            css: {
                                selector: ' .ecom-qr--wrapper',
                                properties: { 'text-align': '' }
                            }
                        },
                        {
                            type: 'link',
                            name: 'link_wrap',
                            label: 'Wrap Link'
                        },
                        {
                            type: 'toggle',
                            name: 'download_button',
                            label: 'Download Button',
                            value: false,
                            options: {
                                values: {
                                    on: { value: true },
                                    off: { value: false }
                                }
                            },
                            css: { isCss: false }
                        },
                        {
                            type: 'text',
                            name: 'download_label',
                            label: 'Button Label',
                            value: 'Download QR Code',
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => data && data['download_button'] === true
                                }
                            }
                        }
                    ]
                },

            ];
        },
        style() {
            return [
                {
                    group_alias: 'box',
                    options: {
                        group_name: 'qr_general',
                        group_title: 'QR Wrapper',
                        selector: ' .ecom-qr--wrapper'
                    },
                    modify: {
                        params: [
                            {
                                position: 10,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: $t('spacing')
                                    }
                                }
                            }
                        ]
                    }
                },
                {
                    group_alias: 'button',
                    options: {
                        group_name: 'qr_download_btn',
                        group_title: 'Download Button',
                        selector: ' .ecom-qr--download',
                        visible: (data) => !!(data && data.settings && data.settings.download_button === true)
                    }
                }
            ];
        }
    }
};
</script>
