import { $t } from '@/plugins/i18n';
import helpers from "@/utils/helpers";
import { Module } from 'vuex';

export type Toast = {
    message: string;
    isError?: boolean,
    data?: object,
    /* Duration in ms should be bigger than 500, set to 0 for prevent closing */
    duration?: number,
    action?: string,
    onAction?: () => void,
    onDismiss?:() => void,
    isAdding?: boolean,
    isRemoving?: boolean;
}

export type GlobalState = {
    progress: {
        show: boolean;
        percent: number;
    };
    progress_timeout: any;
    banner: {
        show: boolean;
        message: string;
        timeout: number;
        title: string;
        type: string;
    };
    flash: {
        open: boolean;
        message: string;
        title: string;
        type: string;
    };
    toasts: Record<string, Toast>;
    toastsTimeout: Map<string, any>;
    sidebar: {
        open_categories: Record<string, boolean>;
    };
    user: Record<string, any> | null;
    configs: {
        icons: any;
        tinify: any;
    };
    doc: any;
    loading: boolean;
    borderElements: boolean;
    sidebarTabActive: { id: string };
    closeBlockSt: any;
    ecNoel: boolean;
    newYear: boolean;
    assetUrl?: string;
    shopCurrency?: {
        currency: string;
        money_format: string;
        money_with_currency_format: string;
    };
    seoIssuesCount: number;
}


const module: Module<GlobalState, any> = {
    namespaced: true,
    state: {
        progress: {
            show: true,
            percent: 10,
        },
        progress_timeout: null,
        banner: {
            show: false,
            message: '',
            timeout: 10000,
            title: '',
            type: 'error',
        },
        flash: {
            open: false,
            message: '',
            title: '',
            type: 'success',
        },
        toasts: {},
        toastsTimeout: new Map(),
        sidebar: {
            open_categories: {}
        },
        user: null,
        configs: {
            icons: null,
            tinify: null
        },
        doc: null,
        loading: true,
        borderElements: false,
        sidebarTabActive: { id: ''},
        closeBlockSt: null,
        ecNoel: false,
        newYear: false,
        seoIssuesCount: 0,
    },
    getters: {
        closeBlockSt(state){
            return state.closeBlockSt;
        },
        ecNoel(state){
            return state.ecNoel;
        },
        seoIssuesCount(state){
            return state.seoIssuesCount;
        },
        newYear(state){
            return state.newYear;
        },
        sidebarTabActive(state){
            return state.sidebarTabActive;
        },
        borderElements(state){
            return state.borderElements;
        },
        progress(state) {
            return state.progress;
        },
        flash(state) {
            return state.flash;
        },
        toasts(state) {
            return state.toasts;
        },
        sidebar(state) {
            return state.sidebar;
        },
        user(state) {
            return state.user;
        },
        configs(state) {
            return state.configs;
        },
        isDesigner(state) {
            if (state.user && state.user.roles && state.user.roles[0].permissions && state.user.roles[0].permissions.some(permission => permission.name === 'design')) {
                return true;
            } else {
                return false;
            }
        },
        configIcons(state) {
            return state.configs.icons;
        },
        getPermission(state){
            return  (key,def = null)=>{
                return state.user?.plan_permissions?.permissions?.[key] ?? def;
            };
        },
        doc(state){
            return state.doc;
        },
        loading(state){
            return state.loading;
        },
        assetUrl(state) {
            return state.assetUrl;
        },
        shopCurrency(state) {
            return state.shopCurrency;
        }
    },
    mutations: {
        setCloseBlockSt(state, payload){
            state.closeBlockSt = payload;
        },
        setProgress(state, payload) {
            state.progress = { ...state.progress, ...payload };
        },
        setBanner(state, payload) {
            state.banner = payload;
        },
        flash(state, payload) {
            let  message = payload.data?.message || payload.message;
            let dataTranslate = payload.data?.translate_data || payload.translate_data || {};
            if(message){
            let translateKey = message.startsWith('$t|') ? message.replace('$t|', '').trim(): message;
            payload.message = $t(translateKey, dataTranslate);
            }
            state.flash = payload;
        },
        setToast(state, payload: Toast) {
            if (payload.duration == null || payload.duration == 0 || (payload.duration > 0 && payload.duration < 500)) {
                payload.duration = 3000;
            }
            // Translate
            let  message = payload.data?.message || payload.message;
            let dataTranslate = payload.data?.translate_data || payload.translate_data || {};
            if(message){
                let translateKey = message.startsWith('$t|') ? message.replace('$t|', '').trim(): message;
                payload.message = $t(translateKey, dataTranslate);
            }

            // Check for duplicate message
            for (const id in state.toasts) {
                if (state.toasts[id].message === payload.message) {
                    return;
                }
            }

            const id = `toast-${helpers.randid()}`;
            // Set isAdding to true so we can broatcast it or just simply add transitions
            payload.isAdding = true;
            state.toasts[id] = payload;
            if (state.toastsTimeout.has(id)) {
                clearTimeout(state.toastsTimeout.get(id));
            };
            if (payload.duration > 0) {
                state.toastsTimeout.set(id, setTimeout(() => {
                    state.toasts[id].isRemoving = true;
                    setTimeout(() => {
                        const {[id]:_, ...rest} = state.toasts;
                        state.toasts = rest;
                    }, 300);
                }, payload.duration));
            }
            // At this point if broadcast is set, it should be broadcasted, if not, we will add transitions after 50ms
            setTimeout(() => {
                if (state.toasts[id]) {
                    state.toasts[id].isAdding = undefined;
                }
            }, 50);
        },
        removeToast(state, id: string) {
            if (state.toastsTimeout.has(id)) {
                clearTimeout(state.toastsTimeout.get(id));
                state.toastsTimeout.delete(id);
            }
            if (!(id in state.toasts)) {
                return;
            }
            if (state.toasts[id].isAdding) {
                state.toasts[id].isAdding = undefined;
            }
            state.toasts[id].isRemoving = true;
            setTimeout(() => {
                const {[id]:_, ...rest} = state.toasts;
                state.toasts = rest;
            }, 200);
        },
        clearToasts(state) {
            for (const id in state.toasts) {
                if (state.toastsTimeout.has(id)) {
                    clearTimeout(state.toastsTimeout.get(id));
                    state.toastsTimeout.delete(id);
                }
            }
            state.toasts = {};
            state.toastsTimeout = new Map();
        },
        setUser(state, payload) {
            state.user = payload;
        },
        setConfig(state, payload) {
            state.configs = payload;
        },
        openCategories(state, payload) {
            state.sidebar.open_categories = {};
            state.sidebar.open_categories[['page', 'home'].indexOf(payload) > -1 ? 'layout' : payload] = true;
        },
        toggleBorder(state, payload) {
            state.borderElements = payload;
        },
        setSidebarTabActive(state, payload){
            state.sidebarTabActive = payload;
        },
        setSeoIssuesCount(state, payload: number) {
            state.seoIssuesCount = payload;
        },
        SET_PROGRESS_TIMEOUT(state, timeout: number | null) {
            state.progress_timeout = timeout;
        },
        CLEAR_PROGRESS_TIMEOUT(state) {
            if (state.progress_timeout) {
                clearTimeout(state.progress_timeout);
                state.progress_timeout = null;
            }
        },
        updateProgressPercent(state, percent) {
            state.progress = {
                ...state.progress,
                percent
            };
        },
        SET_LOADING(state, payload: boolean) {
        state.loading = payload;
        },
        setAssetUrl(state, payload: string) {
            state.assetUrl = payload;
        },
        setShopCurrency(state, payload: GlobalState['shopCurrency']) {
            state.shopCurrency = payload;
        },
    },
    actions: {
        setLoading({ commit }, payload: boolean) {
            commit('SET_LOADING', payload);
        },
        setDoc({state}, payload){
            state.doc = payload;
        },
        setProgress({ commit, state }, payload) {
            commit('CLEAR_PROGRESS_TIMEOUT');

            if (!payload.show) {
                commit('updateProgressPercent', 100);
                setTimeout(() => {
                    commit('setProgress', payload);
                }, 500);
            } else {
                const timeout = setInterval(() => {
                    if (state.progress.percent >= 90 || !state.progress.show) {
                        commit('CLEAR_PROGRESS_TIMEOUT');
                        return;
                    }
                    commit('updateProgressPercent', state.progress.percent + 1);
                }, 100);

                commit('SET_PROGRESS_TIMEOUT', timeout);
                commit('setProgress', payload);
            }
        },
        flash({ commit }, payload) {
            if(!('open' in payload))
            {
                payload.open = true;
            }
            commit('flash', payload);
        },
        setToast({ commit }, payload) {
            commit('setToast', payload);
        },
        setBanner({ commit }, payload) {
            commit('setBanner', payload);
        },
        setProgressTimeout({ commit }, timeout: number) {
            commit('CLEAR_PROGRESS_TIMEOUT');
            commit('SET_PROGRESS_TIMEOUT', timeout);
        },
        clearProgressTimeout({ commit }) {
            commit('CLEAR_PROGRESS_TIMEOUT');
        }
    },
};
export default module;
