        javascript(){
            return function(){
                if(!this.$el) return;
                let $el = this.$el,
                    isLive = this.isLive,
                    disable = this.settings.disable_when_cart_empty ?? false,
                    min_price = this.settings.minimum_price ?? 0,
                    el_freeShipping = $el.querySelector('.ecom-free-shipping-bar__text'),
                    el_cartJson = document.querySelector("#ecom-cart-json") ?? null,
                    el_progress = $el.querySelector('.ecom-free-shipping-bar__progress-bar-stroke'),
                    cartJson = null;

                let success_content = el_freeShipping && el_freeShipping.dataset.successContent ? unescape(el_freeShipping.dataset.successContent) : (this.settings.success_content ?? '');
                let content = el_freeShipping && el_freeShipping.dataset.content ? unescape(el_freeShipping.dataset.content) : (this.settings.content ?? '');

                if(!isLive && el_freeShipping) {
                    let results = window.EComposer.formatMoney(min_price * 100);
                    el_freeShipping.innerHTML = content.replace(/\{price}/g, results);
                    return;
                }
                
                if(!el_freeShipping || !el_cartJson) return;
                
                if(el_cartJson && el_cartJson.innerHTML) {
                    cartJson = JSON.parse(el_cartJson.innerHTML);
                }
                
                if(cartJson && isLive && disable && cartJson.item_count === 0) {
                    $el.style.display = 'none';
                    return;
                }
                
                let total = (cartJson?.items_subtotal_price ?? 0) / 100;
                let result = min_price - total;

                if(el_progress && isLive) {
                    let percent = total / min_price * 100;
                    if(percent > 100) percent = 100;
                    el_progress.style.width = `${percent}%`;
                }
                
                if(result > 0){
                    result = window.EComposer.formatMoney(result * 100);
                    let final_content = content.replace(/\{price}/g, result);
                    el_freeShipping.innerHTML = final_content;
                }
                else {
                    el_freeShipping.innerHTML = success_content;
                }
            };
