/**
 * Upgrade Popup Tracking Utility
 *
 * Sends analytics events via Mixpanel for the UpgradePopup lifecycle:
 * - impression: popup becomes visible
 * - click:      user clicks CTA (Upgrade / Buy Credits)
 * - dismiss:    user clicks Cancel / close
 *
 * Each event carries contextual metadata (feature_key, source_location,
 * popup_mode, plan info) so Product can slice conversion funnels.
 *
 * `trigger_type` is auto-derived in upgrade.ts from feature_key:
 *   - 'quota' = numeric limit reached (pages, ai_credits, etc.)
 *   - 'feature' = premium feature gate (library_vip, remove_branding, etc.)
 */

// ── Event type constants ────────────────────────────────────────────────

export const UPGRADE_EVENTS = {
    IMPRESSION: 'impression',
    CLICK: 'click',
    DISMISS: 'dismiss',
} as const;

export type UpgradeEventType = (typeof UPGRADE_EVENTS)[keyof typeof UPGRADE_EVENTS];

// ── Mixpanel event name mapping ─────────────────────────────────────────

const MIXPANEL_EVENT_NAMES: Record<UpgradeEventType, string> = {
    impression: 'Upgrade Popup - Impression',
    click: 'Upgrade Popup - Click',
    dismiss: 'Upgrade Popup - Dismiss',
};

// ── Event data shape ────────────────────────────────────────────────────

export interface UpgradeTrackingData {
    /** Which event fired */
    event_type: UpgradeEventType;
    /** Auto-derived: 'quota' (numeric limit) or 'feature' (premium gate) */
    trigger_type: string;
    /** Permission / feature key that caused the popup, e.g. 'max_limit', 'ai_credits' */
    feature_key: string;
    /** Where in the app the popup was triggered, e.g. 'publish', 'ai_assistant' */
    source_location: string;
    /** Popup mode: 'plan' or 'credits' */
    popup_mode: string;
    /** Plan ID the user selected (click) */
    plan_id?: number | null;
    /** Billing cycle at the time of the event */
    billing_cycle?: string;
    /** Plan tier the user was on before upgrade */
    from_plan?: string;
    /** Plan tier the user is upgrading to */
    to_plan?: string;
    /** Credit tier index selected (credits mode) */
    credit_tier?: number;
    /** Credit amount selected */
    credit_amount?: number;
}

// ── Send tracking via Mixpanel ──────────────────────────────────────────

/**
 * Fire-and-forget tracking call via Mixpanel.
 * Failures are silently logged — tracking should never block UX.
 */
export function trackUpgradeEvent(data: UpgradeTrackingData): void {
    try {
        const mixpanel = (window as any).mixpanel;
        if (!mixpanel || typeof mixpanel.track !== 'function') {
            return;
        }

        const eventName = MIXPANEL_EVENT_NAMES[data.event_type] || `Upgrade Popup - ${data.event_type}`;

        // Build properties — only include defined values
        const properties: Record<string, any> = {
            event_name: eventName,
            trigger_type: data.trigger_type,
            feature_key: data.feature_key,
            source_location: data.source_location,
            popup_mode: data.popup_mode,
        };

        if (data.plan_id != null) properties.plan_id = data.plan_id;
        if (data.billing_cycle) properties.billing_cycle = data.billing_cycle;
        if (data.from_plan) properties.from_plan = data.from_plan;
        if (data.to_plan) properties.to_plan = data.to_plan;
        if (data.credit_tier != null) properties.credit_tier = data.credit_tier;
        if (data.credit_amount != null) properties.credit_amount = data.credit_amount;

        mixpanel.track(eventName, properties);
    } catch (err) {
        console.warn('[UpgradeTracking] Failed to send event:', err);
    }
}
