<template>
    <div class="ecom-element ecom-shopify-elements ecom-shopify__article--image " :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-shopify__article--image-wrapper"  :class="{'ecom-ingrid-full-height': data.inGrid}" v-html="liquid('articleImage')" />
        <figcaption
            v-if="isHasCaption"
            class="ecom-image__caption"
            v-html="captionText"
        />
    </div>
</template>

<script>
import { Liquid, Element } from '@/mixins';

export default {
    name: 'ArticleImage',

    mixins: [Liquid, Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        captionText() {
            return this.data && this.data.settings && this.data.settings.caption ? this.data.settings.caption : '';
        },

        css() {
            return `
                .ecom-shopify__article--image-wrapper .ecom-image-default{
                    position:relative;
                }
                .ecom-shopify__article--image-wrapper .ecom-shopify__article-hero-portrait img,
                .ecom-shopify__article--image-wrapper .ecom-shopify__article-hero-square img {
                    height: 100%;
                    object-fit: cover;
                }
                .ecom-shopify__article-hero-image, .ecom-shopify__article-hero-image img { width: 100%; height: 100%}
            `;
        },
        isHasCaption () {
            return this.data && this.data.settings && this.data.settings.useCaption && this.data.settings.caption;
        },

        liquids() {
            return {
                articleImage: {
                    code: `
                        {% if article != blank %}
                            {% if article.image %}
                                <div class="ecom-shopify__article-hero-container ecom-image-align ecom-flex ${this.data.inGrid ? "ecom-ingrid-full-height" : ""}">
                                    <div class="ecom-shopify__article-hero-image ecom-image-default ${this.data.inGrid ? "ecom-ingrid-full-height" : ""}"
                                    itemprop="image"
                                    >
                                    <img srcset="
                                        {% if article.image.width >= 350 %}{{ article.image | image_url: width: 350 }} 350w,{% endif %}
                                        {% if article.image.width >= 700 %}{{ article.image | image_url: width: 700 }} 700w,{% endif %}
                                        {% if article.image.width >= 749 %}{{ article.image | image_url: width: 749 }} 749w,{% endif %}
                                        {% if article.image.width >= 1498 %}{{ article.image | image_url: width: 1498 }} 1498w,{% endif %}
                                        {% if article.image.width >= 1100 %}{{ article.image | image_url: width: 1100 }} 1100w,{% endif %}
                                        {% if article.image.width >= 2200 %}{{ article.image | image_url: width: 2200 }} 2200w,{% endif %}"
                                        sizes="(min-width: 1200px) 1100px, (min-width: 750px) calc(100vw - 10rem), 100vw"
                                        src="{{ article.image | image_url: width: 1100 }}"
                                        loading="lazy"
                                        width="{{ article.image.width }}"
                                        height="{{ article.image.height }}"
                                        alt="{{ article.image.alt | escape }}">
                                    </div>
                                </div>
                            {% endif %}
                        {% else %}
                            <div>Please select the article in settings</div>
                        {% endif %}
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div>
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-4"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-6"></div>
                                    <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                    <div class="ecom-skeleton-col-2"></div>
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                                </div>
                            </div>
                        </div>
                    `
                }
            };
        },

        requestShopifyType() {
            return {
                shopify_type: 'article'
            };
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: 'toggle',
                            name: 'useCaption',
                            label: this.$t('caption'),
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                    label: this.$t('yes'),
                                    value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            },
                            css:false
                        },
                        {
                            type: 'text',
                            name: 'caption',
                            options: {
                                placeholder: this.$t('enter_your_caption'),
                                visible: (data) => {
                                    return data['useCaption'];
                                }
                            }
                        },
                    ]
                }
            ];
        },

        default() {
            return {}
        }

    },
    methods:{
        style() {
            let style = [
                {
                    group_alias: 'image',
                    options: {
                        liteMode: true,
                        group_title: this.$t('image'),
                        group_name: 'Image',
                        selector: ' .ecom-shopify__article-hero-container'
                    },
                    modify:{
                        params: [
                            {
                                position: 0,
                                fields: [
                                    {
                                        type: 'choose',
                                        label: this.$t('alignment'),
                                        name: 'content_position',
                                        options: {
                                            oneline: true,
                                            responsive: true,
                                            reset: true,
                                            type: 'align-x-full',
                                            values: ['start','center','end']
                                        },
                                        css: {
                                            properties: {
                                                'justify-content': ''
                                            },
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                }
            ];
            if((this.data.settings.useCaption && this.data.settings.caption) ? true : false){
                style.push(
                    {
                        group_alias: 'text:spacing',
                        options: {
                            group_title: this.$t('caption'),
                            group_name:'caption',
                            selector: ' .ecom-image__caption'
                        }
                    }
                );
            }
            return style;
        },
    }
};
</script>