type GridDebugPayload = Record<string, unknown>;
type GridDebugSource = Record<string, any> | null | undefined;

const GRID_DEBUG_FLAG = "__ECOM_GRID_DEBUG__";
const GRID_DEBUG_STORAGE_KEY = "ecom-grid-debug";
const GRID_DEBUG_TRACE_KEY = "__ecomGridDebugTrace";

let traceCounter = 0;

function getGridDebugWindow(): Record<string, any> | null {
    if (typeof window === "undefined") {
        return null;
    }

    return window as unknown as Record<string, any>;
}

function parseBooleanLike(value: unknown): boolean | null {
    if (typeof value === "boolean") {
        return value;
    }

    if (typeof value !== "string") {
        return null;
    }

    const normalized = value.trim().toLowerCase();
    if (["1", "true", "on", "yes"].includes(normalized)) {
        return true;
    }

    if (["0", "false", "off", "no"].includes(normalized)) {
        return false;
    }

    return null;
}

export function isGridDebugEnabled(): boolean {
    const debugWindow = getGridDebugWindow();
    const windowFlag = parseBooleanLike(debugWindow?.[GRID_DEBUG_FLAG]);
    if (windowFlag !== null) {
        return windowFlag;
    }

    try {
        const storageFlag = parseBooleanLike(window.localStorage.getItem(GRID_DEBUG_STORAGE_KEY));
        if (storageFlag !== null) {
            return storageFlag;
        }
    } catch (error) {
        // Ignore localStorage access errors and keep debug enabled by default.
    }

    return false;
}

function getTraceData(source?: GridDebugSource): { id: string; startedAt: number } | null {
    if (!source) {
        return null;
    }

    return source[GRID_DEBUG_TRACE_KEY] || null;
}

function buildConsolePayload(payload: GridDebugPayload, source?: GridDebugSource): GridDebugPayload {
    const trace = getTraceData(source);

    return {
        timestamp: new Date().toISOString(),
        traceId: trace?.id || null,
        ...payload
    };
}

export function gridDebug(channel: string, event: string, payload: GridDebugPayload = {}, source?: GridDebugSource): void {
    if (!isGridDebugEnabled()) {
        return;
    }

    console.log(`[GridDebug][${channel}] ${event}`, buildConsolePayload(payload, source));
}

export function gridDebugError(
    channel: string,
    event: string,
    error: unknown,
    payload: GridDebugPayload = {},
    source?: GridDebugSource
): void {
    if (!isGridDebugEnabled()) {
        return;
    }

    console.error(`[GridDebug][${channel}] ${event}`, buildConsolePayload({ ...payload, error }, source));
}

export function beginGridDebugTrace(source: GridDebugSource, channel: string, payload: GridDebugPayload = {}): string {
    traceCounter += 1;
    const traceId = `${channel}-${Date.now().toString(36)}-${traceCounter}`;

    if (source) {
        source[GRID_DEBUG_TRACE_KEY] = {
            id: traceId,
            startedAt: Date.now()
        };
    }

    gridDebug(channel, "trace:start", { ...payload, traceId }, source);
    return traceId;
}

export function endGridDebugTrace(
    source: GridDebugSource,
    channel: string,
    event = "trace:end",
    payload: GridDebugPayload = {}
): void {
    const trace = getTraceData(source);

    gridDebug(
        channel,
        event,
        {
            ...payload,
            durationMs: trace ? Date.now() - trace.startedAt : null,
            traceId: trace?.id || null
        },
        source
    );

    if (source && source[GRID_DEBUG_TRACE_KEY]) {
        delete source[GRID_DEBUG_TRACE_KEY];
    }
}
