<template>
    <div class="ecom-element ecom-cart ecom-cart__note">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <div class="ecom-cart__note-wrapper">
            <div class="ecom-cart__note-container"
            >
                <label htmlFor="note" value="note">{{ lang(data.settings.label,'cart_note_label') }}</label>
                <component :is="'textarea'" name="note" class="ecom-cart ecom-cart__note--input" rows="3" :placeholder="lang(data.settings.placeholder,'cart_note_placeholder')">
                    {{ liquid('cart_note') }}
                </component>
            </div>
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
import { Liquid, Element,Javascript } from '@/mixins';
export default {
    name: 'Cart Note',
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        liquids(){
            return {
                cart_note: {
                    code: '{{ cart.note }}',
                    preview: ''
                }
            };
        },

        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'paragraph',
                            options: {
                                warnings: {
                                    content: this.$t('note_this_element_can_only_work_when_you_put_it_to_the_same_section_with_the_cart_item_element'),
                                }
                            }
                        },
                        {
                            type: 'paragraph',
                            content: this.$t('you_can_use_the_order_note_element_to_collect_the_customers_special_request_about_order_preparation_and_delivery'),
                        },
                        {
                            type: 'text',
                            label: this.$t('order_note_label'),
                            name: 'label',
                            placeholder: this.$t('order_note_optional'),
                        },
                        {
                            type: 'text',
                            label: this.$t('order_note_placeholder'),
                            name: 'placeholder',
                            placeholder: this.$t('note_about_your_order'),
                        },

                    ]
                }
            ];
        },

        javascript(){
            return function(){
                if(this.isLive)
                {
                    let $note = this.$el.querySelector('.ecom-cart__note--input');
                    if($note && window.EComposer.routes)
                    {
                        $note.addEventListener('change',function(){
                            window.fetch(window.EComposer.routes.cart_update_url,{
                                method: "POST",
                                headers: {
                                    'Content-Type':'application/json'
                                },
                                body: JSON.stringify({ note: this.value})
                            })
                            .then(res=>res.text())
                            .catch(e=>{
                                alert(e.message);
                            });
                        });
                    }
                }
            };
        },

        // requestShopifyType() {
        //     return {
        //         shopify_type: 'cart'
        //     };
        // },
        css(){
            return `
                .ecom-cart__note-container{
                    display:flex;
                    flex-direction: column;
                }
                .ecom-cart__note-container label{
                    font-style: normal;
                    font-weight: 500;
                    font-size: 1.4rem;
                    line-height: 20px;
                    color: #374151;
                    margin-bottom:4px;
                }
                .ecom-cart__note-container textarea{
                    background: #FFFFFF;
                    border: 1px solid #D1D5DB;
                    box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.05);
                    height: 93px;
                    font-style: normal;
                    font-weight: normal;
                    font-size: 1.4rem;
                    line-height: 20px;
                    color: #6B7280;
                    outline:none;
                }
            `;
        },
        style() {
            return [
                {
                    group_alias: 'box',
                    options: {
                        group_title: this.$t('general'),
                    }
                },
                {
                    group_alias: 'text',
                    options: {
                        group_title: this.$t('label'),
                        group_name: 'label',
                        selector: 'root .ecom-cart__note-container label'
                    },
                    modify: {
                        params: {
                            position: 10,
                            fields: {
                                alias: 'spacing',
                                options: {
                                    label: this.$t('spacing'),
                                }
                            }
                        }
                    }
                },
                {
                    group_alias: 'input',
                    options: {
                        group_name: 'input_textarea',
                        group_title: this.$t('input'),
                        selector: ' root .ecom-cart__note-container textarea'
                    },
                    modify: {
                        remove: {
                            index: 1,
                            length: 1,
                        },
                        params: [
                            {
                                position: 2,
                                fields: [
                                    {
                                        alias: 'justify-content',
                                        options: {
                                            label: this.$t('alignment'),
                                            css: {
                                                selector: 'root .ecom-cart__attributes-input',
                                                properties: {
                                                    'align-items': '',
                                                    'justify-content': ''
                                                }
                                            }
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                },
            ];
        },
        default() {
            return {
                settings: {
                    label: this.$t('order_note_optional'),
                    placeholder: this.$t('note_about_your_order'),
                },
                style: {
                    "input": {
                        "border-radius": {
                            "right": "4px",
                            "top": "4px",
                            "left": "4px",
                            "bottom": "4px"
                        }
                    },
                }
            }
        }
    },
    methods: {}
};
</script>
