        },
        methods: {
            handlerTab(tab) {
                this.active = tab;
                let {people, nature, objects, places, symbols, wrapper, flag, food, activity} = this.$refs;
                if(!wrapper) return;
                if(this.input  !== '') {
                    wrapper.scrollTop = 0;
                } else {
                    switch(tab) {
                        case 'People': 
                            wrapper.scrollTop = 0;
                        break;
                        case 'Nature': 
                            wrapper.scrollTop = nature.offsetTop - people.offsetTop;
                            break;
                        case 'Objects': 
                            wrapper.scrollTop = objects.offsetTop - people.offsetTop;
                            break;
                        case 'Places': 
                            wrapper.scrollTop = places.offsetTop - people.offsetTop;
                            break;
                        case 'Symbols': 
                            wrapper.scrollTop = symbols.offsetTop - people.offsetTop;
                            break;
                        case 'Flag': 
                            wrapper.scrollTop = flag.offsetTop - people.offsetTop;
                            break;
                        case 'Food': 
                            wrapper.scrollTop = food.offsetTop - people.offsetTop;
                            break;
                        case 'Activity': 
                            wrapper.scrollTop = activity.offsetTop - people.offsetTop;
                            break;
                        default: 
                            break;
                    }
                }
            },  
            handleShowTitle() {
                let {people, nature, objects, places, symbols, notice, wrapper, flag, food, activity} = this.$refs;
                let arrs = Object.values({people, nature, objects, places, symbols, flag, food, activity});
                arrs.forEach((arr)=>{
                    if(arr.querySelectorAll('.ecom-emoji-show').length === 0){
                        arr.classList.add('ecom-emoji-hidden');
                    } 
                    else {
                        arr.classList.remove('ecom-emoji-hidden');
                    }
                });
                if(wrapper.querySelectorAll('.ecom-emoji-show').length === 0) {
                    notice.classList.remove('ecom-emoji-hidden');
                }
                else {
                    notice.classList.add('ecom-emoji-hidden');
                }
            },
            inputSearch() {
                let wrapper = this.$refs.wrapper;
                this.active = '';
                wrapper.scrollTop = 0;
                const icons = wrapper && wrapper.querySelectorAll('.emoji-item');
                if(this.input != '') {
                    for(let i = 0; i < icons.length; i++) {
                        if(!icons[i].getAttribute('title').includes(this.input)) {
                            icons[i].classList.add('ecom-emoji-hidden');
                            icons[i].classList.remove('ecom-emoji-show');
                        }
                        else {
                            icons[i].classList.remove('ecom-emoji-hidden');
                            icons[i].classList.add('ecom-emoji-show');
                        }; 
                    }
                }
                else {
                    for(let i = 0; i < icons.length; i++) {
                        icons[i].classList.remove('ecom-emoji-hidden');
                        icons[i].classList.add('ecom-emoji-show');
                    }
                }
                this.handleShowTitle();
            },
            handleScroll() {
                if (this.scrollTimeout) {
                    clearTimeout(this.scrollTimeout);
                }

                this.scrollTimeout = setTimeout(() => {
                    const { people, nature, objects, places, symbols, flag, food, activity, wrapper } = this.$refs;
                    if (!wrapper) return;

                    const scrollTop = wrapper.scrollTop;
                    const sections = [
                        { ref: people, tab: 'People' },
                        { ref: nature, tab: 'Nature' },
                        { ref: food, tab: 'Food' },
                        { ref: activity, tab: 'Activity' },
                        { ref: objects, tab: 'Objects' },
                        { ref: places, tab: 'Places' },
                        { ref: symbols, tab: 'Symbols' },
                        { ref: flag, tab: 'Flag' },
                    ];

                    let currentSection = sections[0];
                    for (const section of sections) {
                        if (section.ref && section.ref.offsetTop - wrapper.offsetTop <= scrollTop + 50) {
                            currentSection = section;
                        } else {
                            break;
                        }
                    }

                    if (this.active !== currentSection.tab) {
                        this.active = currentSection.tab;
                    }
                }, 100);
            },
        },
        watch: {
            show: function(newVal) {
                this.input = '';
                this.inputSearch();
                if(newVal) {
                    this.$nextTick(() => {
                        this.handleScroll();
                    })
                }
            }
        }
    };
  </script>
