// Helper functions for component integration - ENHANCED
export class AutoLayoutHelper {
    /**
     * Chuyển đổi block data sang LayoutItem format
     */
    static convertBlocksToLayoutItems(
        blocks: any[],
        getScreenLayout: (block: any, screen: string) => any,
        screen: string,
        gridContainerWidth: number
    ): LayoutItem[] {
        return blocks
            .filter((block) => {
                const layout = getScreenLayout(block, screen);
                return layout && layout.width && layout.height;
            })
            .map((block) => {
                const layout = getScreenLayout(block, screen);

                let widthPx = ensureNumericValue(layout.width);
                if (typeof layout.width === "string" && layout.width.includes("%")) {
                    widthPx = (ensureNumericValue(layout.width) / 100) * gridContainerWidth;
                }

                return {
                    id: block.id,
                    left: ensureNumericValue(layout.left),
                    top: ensureNumericValue(layout.top),
                    width: widthPx,
                    height: ensureNumericValue(layout.height),
                    originalWidth: layout.width,
                    block: block,
                    zindex: layout.zindex || 0
                };
            });
    }

    /**
     * Tạo config mặc định cho auto layout - CẢI TIẾN CHO FULL-WIDTH ITEMS - SỬA
     */
    static createDefaultConfig(
        gridContainerWidth: number,
        screen: string,
        customConfig: Partial<AutoLayoutConfig> = {}
    ): AutoLayoutConfig {
        // Xác định có phải mobile không
        const isMobileScreen = screen === "mobile" || screen === "sm" || gridContainerWidth <= 768;

        // SỬA: Tính toán spacing dựa trên minGapPx và screen
        const minGapPx = customConfig.minGapPx || (isMobileScreen ? 8 : 20);
        const fullWidthItemsSpacing =
            customConfig.fullWidthItemsSpacing || Math.max(3, Math.floor(minGapPx * 0.6)); // 60% của minGapPx, tối thiểu 3px

        // Config mặc định tùy theo screen
        const baseConfig = {
            gridContainerWidth,
            screen,
            minGapPx,
            minWidthPx: isMobileScreen ? 40 : 50,
            maxWidthPercent: isMobileScreen ? 98 : 95,
            minHeightPx: isMobileScreen ? 25 : 30,
            verticalOverlapThreshold: isMobileScreen ? 8 : 10,
            horizontalGapThreshold: isMobileScreen ? 15 : 20,
            // Config cho mobile
            centerSingleItemsOnMobile: true,
            mobileWidthThreshold: 768,
            // SỬA: Config cho full-width items dựa trên minGapPx
            fullWidthItemsSpacing,
            enableFullWidthOptimization: true
        };

        return {
            ...baseConfig,
            ...customConfig
        };
    }

    /**
     * Tạo config tối ưu cho từng screen size - CẢI TIẾN - SỬA
     */
    static createScreenOptimizedConfig(
        gridContainerWidth: number,
        screen: string,
        customConfig: Partial<AutoLayoutConfig> = {}
    ): AutoLayoutConfig {
        const screenConfigs = {
            mobile: {
                minGapPx: 8,
                minWidthPx: 35,
                maxWidthPercent: 98,
                minHeightPx: 25,
                verticalOverlapThreshold: 6,
                horizontalGapThreshold: 12,
                centerSingleItemsOnMobile: true,
                fullWidthItemsSpacing: 5, // SỬA: Spacing nhỏ cho mobile
                enableFullWidthOptimization: true
            },
            tablet: {
                minGapPx: 12,
                minWidthPx: 45,
                maxWidthPercent: 96,
                minHeightPx: 28,
                verticalOverlapThreshold: 8,
                horizontalGapThreshold: 18,
                centerSingleItemsOnMobile: true,
                fullWidthItemsSpacing: 8, // SỬA: Spacing vừa phải cho tablet
                enableFullWidthOptimization: true
            },
            desktop: {
                minGapPx: 20,
                minWidthPx: 50,
                maxWidthPercent: 95,
                minHeightPx: 30,
                verticalOverlapThreshold: 10,
                horizontalGapThreshold: 20,
                centerSingleItemsOnMobile: false,
                fullWidthItemsSpacing: 12, // SỬA: Spacing hợp lý cho desktop
                enableFullWidthOptimization: true
            }
        };

        const normalizedScreen =
            screen === "lg" ? "desktop" : screen === "md" ? "tablet" : "mobile";

        const screenConfig = screenConfigs[normalizedScreen] || screenConfigs.desktop;

        // SỬA: Override fullWidthItemsSpacing nếu có trong customConfig
        const finalConfig = this.createDefaultConfig(gridContainerWidth, screen, {
            ...screenConfig,
            ...customConfig
        });

        return finalConfig;
    }

    /**
     * Validation cho layout items trước khi process
     */
    static validateLayoutItems(items: LayoutItem[]): { isValid: boolean; errors: string[] } {
        const errors: string[] = [];

        if (!items || items.length === 0) {
            errors.push("Không có items để xử lý");
        }

        items.forEach((item, index) => {
            if (!item.id) {
                errors.push(`Item tại index ${index} không có ID`);
            }

            if (typeof item.left !== "number" || item.left < 0) {
                errors.push(`Item ${item.id || index} có left không hợp lệ`);
            }

            if (typeof item.top !== "number" || item.top < 0) {
                errors.push(`Item ${item.id || index} có top không hợp lệ`);
            }

            if (typeof item.width !== "number" || item.width <= 0) {
                errors.push(`Item ${item.id || index} có width không hợp lệ`);
            }

            if (typeof item.height !== "number" || item.height <= 0) {
                errors.push(`Item ${item.id || index} có height không hợp lệ`);
            }
        });

        return {
            isValid: errors.length === 0,
            errors
        };
    }

    /**
     * Log thông tin debug cho auto layout - CẢI TIẾN CHO FULL-WIDTH
     */
    static logAutoLayoutInfo(
        items: LayoutItem[],
        config: AutoLayoutConfig,
        fullWidthItems?: Set<string>
    ) {
        console.group("🎯 Enhanced Auto Layout Debug Info");
        console.log("📊 Items count:", items.length);
        console.log("📐 Grid container width:", config.gridContainerWidth);
        console.log("📱 Screen:", config.screen);
        console.log(
            "🎯 Is Mobile Screen:",
            config.screen === "mobile" || config.gridContainerWidth <= config.mobileWidthThreshold
        );
        console.log("⚙️ Config:", config);

        if (fullWidthItems && fullWidthItems.size > 0) {
            console.log("📏 Full-width items:", fullWidthItems.size);
        }

        const itemsInfo = items.map((item) => {
            const widthPercent = (item.width / config.gridContainerWidth) * 100;
            const isFullWidth = widthPercent >= 98 || item.width >= config.gridContainerWidth;
            const isInFullWidthSet = fullWidthItems?.has(item.id) || false;

            return {
                id: item.id,
                position: `${item.left.toFixed(1)}%, ${item.top}px`,
                size: `${item.width}px × ${item.height}px`,
                widthPercent: `${widthPercent.toFixed(1)}%`,
                zindex: item.zindex,
                isFullWidth: isFullWidth,
                inFullWidthSet: isInFullWidthSet,
                willCenter:
                    widthPercent >= 50 ||
                    (config.centerSingleItemsOnMobile &&
                        (config.screen === "mobile" ||
                            config.gridContainerWidth <= config.mobileWidthThreshold))
            };
        });

        console.table(itemsInfo);
        console.groupEnd();
    }

    /**
     * Tính toán preview layout changes - CẢI TIẾN CHO FULL-WIDTH
     */
    static previewLayoutChanges(
        items: LayoutItem[],
        config: AutoLayoutConfig
    ): { item: LayoutItem; changes: any; willCenter: boolean; isFullWidth: boolean }[] {
        return items.map((item) => {
            const widthPercent = (item.width / config.gridContainerWidth) * 100;
            const isMobile =
                config.screen === "mobile" ||
                config.gridContainerWidth <= config.mobileWidthThreshold;
            const isFullWidth = widthPercent >= 98 || item.width >= config.gridContainerWidth;

            let willCenter = false;
            let newLeft = item.left;

            if (isFullWidth) {
                // Full-width items luôn có left = 0
                newLeft = 0;
                willCenter = false;
            } else {
                // Regular items
                willCenter = widthPercent >= 50 || (config.centerSingleItemsOnMobile && isMobile);
                newLeft = willCenter ? Math.max(0, (100 - widthPercent) / 2) : item.left;
            }

            const changes = {
                originalLeft: item.left,
                newLeft: newLeft,
                centeringApplied: willCenter,
                fullWidthApplied: isFullWidth,
                newWidth: isFullWidth ? "100%" : item.originalWidth
            };

            return {
                item,
                changes,
                willCenter,
                isFullWidth
            };
        });
    }

    /**
     * Phân tích full-width items
     */
    static analyzeFullWidthItems(items: LayoutItem[], gridContainerWidth: number) {
        const analysis = {
            fullWidthItems: [] as LayoutItem[],
            oversizedItems: [] as LayoutItem[],
            regularItems: [] as LayoutItem[],
            conflicts: [] as { item: LayoutItem; conflictsWith: LayoutItem[] }[]
        };

        items.forEach((item) => {
            const widthPercent = (item.width / gridContainerWidth) * 100;

            if (widthPercent >= 98 || item.width >= gridContainerWidth) {
                if (item.width > gridContainerWidth) {
                    analysis.oversizedItems.push(item);
                } else {
                    analysis.fullWidthItems.push(item);
                }
            } else {
                analysis.regularItems.push(item);
            }
        });

        // Tìm conflicts giữa full-width và regular items
        [...analysis.fullWidthItems, ...analysis.oversizedItems].forEach((fullWidthItem) => {
            const conflictsWith: LayoutItem[] = [];

            analysis.regularItems.forEach((regularItem) => {
                // Kiểm tra overlap theo chiều dọc
                const fullWidthBottom = fullWidthItem.top + fullWidthItem.height;
                const regularBottom = regularItem.top + regularItem.height;

                const hasVerticalOverlap =
                    regularItem.top < fullWidthBottom && regularBottom > fullWidthItem.top;

                if (hasVerticalOverlap) {
                    conflictsWith.push(regularItem);
                }
            });

            if (conflictsWith.length > 0) {
                analysis.conflicts.push({
                    item: fullWidthItem,
                    conflictsWith
                });
            }
        });

        return analysis;
    }

    /**
     * Tạo recommendation cho auto layout
     */
    static createLayoutRecommendations(
        items: LayoutItem[],
        config: AutoLayoutConfig
    ): {
        summary: string;
        recommendations: string[];
        warnings: string[];
        optimizations: string[];
    } {
        const analysis = this.analyzeFullWidthItems(items, config.gridContainerWidth);
        const isMobile =
            config.screen === "mobile" || config.gridContainerWidth <= config.mobileWidthThreshold;

        const recommendations: string[] = [];
        const warnings: string[] = [];
        const optimizations: string[] = [];

        // Phân tích và đưa ra recommendations
        if (analysis.fullWidthItems.length > 0) {
            recommendations.push(
                `Tìm thấy ${analysis.fullWidthItems.length} full-width items - sẽ được tối ưu tự động với spacing ${config.fullWidthItemsSpacing}px`
            );
        }

        if (analysis.oversizedItems.length > 0) {
            warnings.push(
                `${analysis.oversizedItems.length} items có width vượt quá container - sẽ được điều chỉnh về 100%`
            );
        }

        if (analysis.conflicts.length > 0) {
            warnings.push(
                `${analysis.conflicts.length} full-width items có conflicts với regular items`
            );
            optimizations.push(
                "Các regular items sẽ được di chuyển để tránh overlap với full-width items"
            );
        }

        if (isMobile && config.centerSingleItemsOnMobile) {
            optimizations.push("Items đơn lẻ sẽ được căn giữa cho mobile layout");
        }

        const regularItemsWithLargeWidth = analysis.regularItems.filter(
            (item) => (item.width / config.gridContainerWidth) * 100 >= 50
        );

        if (regularItemsWithLargeWidth.length > 0) {
            optimizations.push(
                `${regularItemsWithLargeWidth.length} regular items có width >= 50% sẽ được căn giữa`
            );
        }

        // Tạo summary
        const summary = `
      Phân tích ${items.length} items:
      ${analysis.fullWidthItems.length} full-width,
      ${analysis.oversizedItems.length} oversized,
      ${analysis.regularItems.length} regular items.
      ${analysis.conflicts.length} conflicts phát hiện.
      Full-width spacing: ${config.fullWidthItemsSpacing}px.
    `
            .trim()
            .replace(/\s+/g, " ");

        return {
            summary,
            recommendations,
            warnings,
            optimizations
        };
    }

    /**
     * ENHANCED: Tích hợp Height Management cho Auto Layout
     */
    static async processAutoLayoutWithHeight(
        items: LayoutItem[],
        config: AutoLayoutConfig,
        heightOptions: {
            settings: any;
            screen: string;
            gridElement: HTMLElement | null;
            enableHeightUpdate: boolean;
            isPreview?: boolean;
        }
    ): Promise<{
        layoutResult: AutoLayoutResult;
        heightPreview?: HeightPreview | null;
    }> {
        // Process auto layout
        const layoutResult = processAutoLayout(items, config);

        // Process height nếu có maxBottomPosition
        let heightPreview: HeightPreview | null = null;
        if (layoutResult.maxBottomPosition && heightOptions.enableHeightUpdate) {
            const heightManager = HeightManager.getInstance();
            const isMobileScreen =
                config.screen === "mobile" ||
                config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

            heightPreview = heightManager.updateHeightAfterAutoLayout(
                layoutResult.maxBottomPosition,
                heightOptions.settings,
                heightOptions.screen,
                heightOptions.gridElement,
                isMobileScreen,
                heightOptions.enableHeightUpdate,
                heightOptions.isPreview || false
            );
        }

        return {
            layoutResult,
            heightPreview
        };
    }

    /**
     * ENHANCED: Complete Auto Layout Preview với Height
     */
    static async makeCompleteAutoLayoutPreview(
        blocks: any[],
        getScreenLayout: (block: any, screen: string) => any,
        config: AutoLayoutConfig,
        heightOptions: {
            settings: any;
            gridElement: HTMLElement | null;
            enableHeightUpdate: boolean;
        },
        callbacks: {
            emitUpdateGridItem: (data: any) => void;
            saveOriginalState: () => void;
        }
    ): Promise<{
        success: boolean;
        result?: AutoLayoutResult;
        heightPreview?: HeightPreview | null;
        error?: string;
    }> {
        try {
            // 1. Prepare data
            const itemsData = this.convertBlocksToLayoutItems(
                blocks,
                getScreenLayout,
                config.screen,
                config.gridContainerWidth
            );

            if (itemsData.length === 0) {
                return { success: false, error: "Không có items hợp lệ để auto layout" };
            }

            // 2. Validation
            const validation = this.validateLayoutItems(itemsData);
            if (!validation.isValid) {
                return {
                    success: false,
                    error: `Validation failed: ${validation.errors.join(", ")}`
                };
            }

            // 3. Save original state
            callbacks.saveOriginalState();

            // 4. Process auto layout
            const layoutResult = processAutoLayout(itemsData, config);

            // 5. Save layout preview to state manager
            const stateManager = AutoLayoutStateManager.getInstance();
            stateManager.setPreviewChanges(layoutResult);
            stateManager.setPreviewing(true);

            // 6. Emit layout preview changes
            stateManager.emitPreviewChanges(callbacks.emitUpdateGridItem);

            // 7. Process height preview if needed - FIXED INTEGRATION
            let heightPreview: HeightPreview | null = null;
            if (layoutResult.maxBottomPosition && heightOptions.enableHeightUpdate) {
                const heightManager = HeightManager.getInstance();
                const isMobileScreen =
                    config.screen === "mobile" ||
                    config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

                // IMPORTANT: Call height preview AFTER layout preview
                heightPreview = heightManager.updateHeightAfterAutoLayout(
                    layoutResult.maxBottomPosition,
                    heightOptions.settings,
                    config.screen,
                    heightOptions.gridElement,
                    isMobileScreen,
                    heightOptions.enableHeightUpdate,
                    true // isPreview = true
                );

                if (heightPreview) {
                    stateManager.setHeightPreview(heightPreview);
                }
            }

            return {
                success: true,
                result: layoutResult,
                heightPreview
            };
        } catch (error) {
            console.error("❌ Complete auto layout preview failed:", error);
            return {
                success: false,
                error: error instanceof Error ? error.message : "Unknown error"
            };
        }
    }

    /**
     * ENHANCED: Complete Auto Layout Confirm với Height
     */
    static async confirmCompleteAutoLayout(
        itemsData: LayoutItem[],
        config: AutoLayoutConfig,
        heightOptions: {
            settings: any;
            gridElement: HTMLElement | null;
            enableHeightUpdate: boolean;
        },
        callbacks: {
            updateItemLayout: (
                item: LayoutItem,
                screen: string,
                updates: LayoutChange,
                isFullWidth: boolean
            ) => void;
            emitLayoutUpdate: () => void;
            addToHistory: () => void;
        }
    ): Promise<{ success: boolean; error?: string }> {
        try {
            const stateManager = AutoLayoutStateManager.getInstance();
            const state = stateManager.getState();

            if (!state.isPreviewing || !state.previewChanges) {
                return { success: false, error: "No preview state to confirm" };
            }

            const { changes, fullWidthItems, maxBottomPosition } = state.previewChanges;

            // 1. Apply layout changes
            const layoutApplicator = LayoutChangeApplicator.getInstance();
            await layoutApplicator.applyLayoutChangesEnhanced(
                changes,
                itemsData,
                config.screen,
                fullWidthItems,
                maxBottomPosition,
                {
                    updateItemLayout: callbacks.updateItemLayout,
                    emitLayoutUpdate: callbacks.emitLayoutUpdate
                }
            );

            // 2. Confirm height if exists - FIXED
            if (state.heightPreview && heightOptions.enableHeightUpdate) {
                const heightManager = HeightManager.getInstance();
                heightManager.confirmHeightUpdate(
                    state.heightPreview,
                    heightOptions.settings,
                    heightOptions.gridElement
                );
            }

            // 3. Add to history
            callbacks.addToHistory();

            // 4. Cleanup state
            stateManager.reset();

            return { success: true };
        } catch (error) {
            console.error("❌ Failed to confirm complete auto layout:", error);
            return {
                success: false,
                error: error instanceof Error ? error.message : "Unknown error"
            };
        }
    }

    /**
     * ENHANCED: Cancel Complete Auto Layout với Height
     */
    static cancelCompleteAutoLayout(
        callbacks: {
            emitUpdateGridItem: (data: any) => void;
        },
        gridElement: HTMLElement | null
    ): { success: boolean; error?: string } {
        try {
            const stateManager = AutoLayoutStateManager.getInstance();
            const state = stateManager.getState();

            if (!state.isPreviewing) {
                return { success: false, error: "No preview state to cancel" };
            }

            // 1. Restore layout items
            stateManager.restoreOriginalState(callbacks.emitUpdateGridItem);

            // 2. Cancel height preview if exists - FIXED
            if (state.heightPreview && gridElement) {
                const heightManager = HeightManager.getInstance();
                heightManager.cancelHeightPreview(state.heightPreview.originalHeight, gridElement);
            }

            // 3. Cleanup state
            stateManager.reset();

            return { success: true };
        } catch (error) {
            console.error("❌ Failed to cancel complete auto layout:", error);
            return {
                success: false,
                error: error instanceof Error ? error.message : "Unknown error"
            };
        }
    }
}
export class EnhancedAutoLayoutHelper extends AutoLayoutHelper {
    /**
     * Process complete auto layout với data attributes support
     */
    static async processCompleteAutoLayoutWithGroupsAndAttributes(
        blocks,
        groups,
        getScreenLayout,
        config,
        heightOptions,
        callbacks
    ) {
        try {
            // 1. Convert tất cả blocks thành layout items
            const allItemsData = this.convertAllBlocksToLayoutItems(
                blocks,
                groups,
                getScreenLayout,
                config.screen,
                config.gridContainerWidth
            );

            if (allItemsData.length === 0) {
                return { success: false, error: "Không có items hợp lệ để auto layout" };
            }

            // 2. Validation
            const validation = this.validateLayoutItems(allItemsData);
            if (!validation.isValid) {
                return {
                    success: false,
                    error: `Validation failed: ${validation.errors.join(", ")}`
                };
            }

            // 3. ✅ SỬA: Save original state bao gồm data attributes
            callbacks.saveOriginalState();

            // 4. Process auto layout cho TẤT CẢ items
            const layoutResult = processAutoLayout(allItemsData, config);

            // 5. Tách changes theo group và non-group
            const groupChanges = new Map();
            const nonGroupChanges = new Map();

            layoutResult.changes.forEach((changes, itemId) => {
                const item = allItemsData.find((i) => i.id === itemId);
                if (item && item.isInGroup) {
                    if (!groupChanges.has(item.groupId)) {
                        groupChanges.set(item.groupId, new Map());
                    }
                    groupChanges.get(item.groupId).set(itemId, changes);
                } else {
                    nonGroupChanges.set(itemId, changes);
                }
            });

            // 6. ✅ SỬA: Apply changes với data attributes update
            await this.applyChangesWithGroupUpdateAndAttributes(
                allItemsData,
                groupChanges,
                nonGroupChanges,
                layoutResult.fullWidthItems,
                config.screen,
                callbacks,
                true // ✅ isPreview = true
            );

            // 7. Process height preview if needed
            let heightPreview = null;
            if (layoutResult.maxBottomPosition && heightOptions.enableHeightUpdate) {
                const heightManager = HeightManager.getInstance();
                const isMobileScreen =
                    config.screen === "mobile" ||
                    config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

                heightPreview = heightManager.updateHeightAfterAutoLayout(
                    layoutResult.maxBottomPosition,
                    heightOptions.settings,
                    config.screen,
                    heightOptions.gridElement,
                    isMobileScreen,
                    heightOptions.enableHeightUpdate,
                    true // isPreview = true
                );
            }

            return {
                success: true,
                result: layoutResult,
                heightPreview,
                groupChanges,
                nonGroupChanges
            };
        } catch (error) {
            console.error("❌ Complete auto layout with groups and attributes failed:", error);
            return {
                success: false,
                error: error instanceof Error ? error.message : "Unknown error"
            };
        }
    }

    /**
     * Apply changes với data attributes support
     */
    static async applyChangesWithGroupUpdateAndAttributes(
        allItemsData,
        groupChanges,
        nonGroupChanges,
        fullWidthItems,
        currentScreen,
        callbacks,
        isPreview = false
    ) {
        const {
            updateItemLayout,
            emitLayoutUpdate,
            updateGroupBounds,
            updateDataAttributes, // ✅ MỚI callback
            restoreDataAttributes // ✅ MỚI callback
        } = callbacks;

        // 1. Apply changes cho non-group items với data attributes
        for (const [itemId, changes] of nonGroupChanges) {
            const item = allItemsData.find((i) => i.id === itemId);
            if (item) {
                const isFullWidth = fullWidthItems.has(itemId);
                updateItemLayout(item, currentScreen, changes, isFullWidth);

                // ✅ MỚI: Cập nhật data attributes
                if (updateDataAttributes) {
                    updateDataAttributes(itemId, changes, isFullWidth, isPreview);
                }
            }
        }

        // 2. Apply changes cho group items với data attributes
        for (const [groupId, itemChanges] of groupChanges) {
            for (const [itemId, changes] of itemChanges) {
                const item = allItemsData.find((i) => i.id === itemId);
                if (item) {
                    const isFullWidth = fullWidthItems.has(itemId);
                    updateItemLayout(item, currentScreen, changes, isFullWidth);

                    // ✅ MỚI: Cập nhật data attributes
                    if (updateDataAttributes) {
                        updateDataAttributes(itemId, changes, isFullWidth, isPreview);
                    }
                }
            }

            // Cập nhật bounds của group sau khi đã di chuyển các items
            if (updateGroupBounds) {
                await updateGroupBounds(groupId);
            }
        }

        // 3. Emit layout update
        if (emitLayoutUpdate) {
            emitLayoutUpdate();
        }
    }
    /**
     * Chuyển đổi tất cả blocks (kể cả trong group) sang LayoutItem format
     */
    static convertAllBlocksToLayoutItems(
        blocks,
        groups,
        getScreenLayout,
        screen,
        gridContainerWidth
    ) {
        return blocks
            .filter((block) => {
                const layout = getScreenLayout(block, screen);
                return layout && layout.width && layout.height;
            })
            .map((block) => {
                const layout = getScreenLayout(block, screen);

                let widthPx = ensureNumericValue(layout.width);
                if (typeof layout.width === "string" && layout.width.includes("%")) {
                    widthPx = (ensureNumericValue(layout.width) / 100) * gridContainerWidth;
                }

                // Xác định group ID nếu block thuộc group
                let groupId = null;
                if (groups) {
                    for (const [gId, group] of Object.entries(groups)) {
                        if (group.blocks && group.blocks.includes(block.id)) {
                            groupId = gId;
                            break;
                        }
                    }
                }

                return {
                    id: block.id,
                    left: ensureNumericValue(layout.left),
                    top: ensureNumericValue(layout.top),
                    width: widthPx,
                    height: ensureNumericValue(layout.height),
                    originalWidth: layout.width,
                    block: block,
                    zindex: layout.zindex || 0,
                    // Thêm thông tin group
                    groupId: groupId,
                    isInGroup: !!groupId
                };
            });
    }

    /**
     * Process auto layout cho tất cả items và cập nhật group bounds
     */
    static async processCompleteAutoLayoutWithGroups(
        blocks,
        groups,
        getScreenLayout,
        config,
        heightOptions,
        callbacks
    ) {
        try {
            // 1. Convert tất cả blocks thành layout items
            const allItemsData = this.convertAllBlocksToLayoutItems(
                blocks,
                groups,
                getScreenLayout,
                config.screen,
                config.gridContainerWidth
            );

            if (allItemsData.length === 0) {
                return { success: false, error: "Không có items hợp lệ để auto layout" };
            }

            // 2. Validation
            const validation = this.validateLayoutItems(allItemsData);
            if (!validation.isValid) {
                return {
                    success: false,
                    error: `Validation failed: ${validation.errors.join(", ")}`
                };
            }

            // 3. Save original state
            callbacks.saveOriginalState();

            // 4. Process auto layout cho TẤT CẢ items (kể cả trong group)
            const layoutResult = processAutoLayout(allItemsData, config);

            // 5. Tách changes theo group và non-group
            const groupChanges = new Map(); // groupId -> Map<itemId, changes>
            const nonGroupChanges = new Map(); // itemId -> changes

            layoutResult.changes.forEach((changes, itemId) => {
                const item = allItemsData.find((i) => i.id === itemId);
                if (item && item.isInGroup) {
                    if (!groupChanges.has(item.groupId)) {
                        groupChanges.set(item.groupId, new Map());
                    }
                    groupChanges.get(item.groupId).set(itemId, changes);
                } else {
                    nonGroupChanges.set(itemId, changes);
                }
            });

            // 6. Apply changes và cập nhật group bounds
            await this.applyChangesWithGroupUpdate(
                allItemsData,
                groupChanges,
                nonGroupChanges,
                layoutResult.fullWidthItems,
                config.screen,
                callbacks
            );

            // 7. Process height preview if needed
            let heightPreview = null;
            if (layoutResult.maxBottomPosition && heightOptions.enableHeightUpdate) {
                const heightManager = HeightManager.getInstance();
                const isMobileScreen =
                    config.screen === "mobile" ||
                    config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

                heightPreview = heightManager.updateHeightAfterAutoLayout(
                    layoutResult.maxBottomPosition,
                    heightOptions.settings,
                    config.screen,
                    heightOptions.gridElement,
                    isMobileScreen,
                    heightOptions.enableHeightUpdate,
                    true // isPreview = true
                );
            }

            return {
                success: true,
                result: layoutResult,
                heightPreview,
                groupChanges,
                nonGroupChanges
            };
        } catch (error) {
            console.error("❌ Complete auto layout with groups failed:", error);
            return {
                success: false,
                error: error instanceof Error ? error.message : "Unknown error"
            };
        }
    }

    /**
     * Apply changes và cập nhật group bounds
     */
    static async applyChangesWithGroupUpdate(
        allItemsData,
        groupChanges,
        nonGroupChanges,
        fullWidthItems,
        currentScreen,
        callbacks
    ) {
        const { updateItemLayout, emitLayoutUpdate, updateGroupBounds } = callbacks;

        // 1. Apply changes cho non-group items
        for (const [itemId, changes] of nonGroupChanges) {
            const item = allItemsData.find((i) => i.id === itemId);
            if (item) {
                const isFullWidth = fullWidthItems.has(itemId);
                updateItemLayout(item, currentScreen, changes, isFullWidth);
            }
        }

        // 2. Apply changes cho group items và cập nhật group bounds
        for (const [groupId, itemChanges] of groupChanges) {
            // Apply changes cho từng item trong group
            for (const [itemId, changes] of itemChanges) {
                const item = allItemsData.find((i) => i.id === itemId);
                if (item) {
                    const isFullWidth = fullWidthItems.has(itemId);
                    updateItemLayout(item, currentScreen, changes, isFullWidth);
                }
            }

            // Cập nhật bounds của group sau khi đã di chuyển các items
            if (updateGroupBounds) {
                await updateGroupBounds(groupId);
            }
        }

        // 3. Emit layout update
        if (emitLayoutUpdate) {
            emitLayoutUpdate();
        }
    }

    /**
     * Tính toán bounds mới cho group dựa trên vị trí items
     */
    static calculateGroupBounds(groupItems, gridContainerWidth) {
        if (!groupItems || groupItems.length === 0) {
            return null;
        }

        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;

        groupItems.forEach((item) => {
            const left = item.left;
            const top = item.top;

            // Xử lý width
            let widthPercent;
            if (typeof item.originalWidth === "string" && item.originalWidth.includes("%")) {
                widthPercent = parseFloat(item.originalWidth);
            } else {
                const widthPx = parseFloat(item.originalWidth) || item.width;
                widthPercent = (widthPx / gridContainerWidth) * 100;
            }

            const right = left + widthPercent;
            const bottom = top + item.height;

            minX = Math.min(minX, left);
            minY = Math.min(minY, top);
            maxX = Math.max(maxX, right);
            maxY = Math.max(maxY, bottom);
        });

        return {
            x: minX,
            y: minY,
            w: maxX - minX,
            h: maxY - minY
        };
    }

    /**
     * Preview auto layout với group support
     */
    static previewAutoLayoutWithGroups(blocks, groups, getScreenLayout, config) {
        const allItemsData = this.convertAllBlocksToLayoutItems(
            blocks,
            groups,
            getScreenLayout,
            config.screen,
            config.gridContainerWidth
        );

        const layoutResult = processAutoLayout(allItemsData, config);

        // Tách preview theo group
        const groupPreviews = new Map();
        const nonGroupPreviews = [];

        layoutResult.changes.forEach((changes, itemId) => {
            const item = allItemsData.find((i) => i.id === itemId);
            if (!item) return;

            const preview = {
                itemId,
                originalPosition: {
                    left: item.left,
                    top: item.top,
                    width: item.originalWidth,
                    height: item.height
                },
                newPosition: {
                    left: changes.left !== undefined ? changes.left : item.left,
                    top: changes.top !== undefined ? changes.top : item.top,
                    width: changes.width !== undefined ? changes.width : item.originalWidth,
                    height: changes.height !== undefined ? changes.height : item.height
                },
                isFullWidth: layoutResult.fullWidthItems.has(itemId)
            };

            if (item.isInGroup) {
                if (!groupPreviews.has(item.groupId)) {
                    groupPreviews.set(item.groupId, []);
                }
                groupPreviews.get(item.groupId).push(preview);
            } else {
                nonGroupPreviews.push(preview);
            }
        });

        // Tính toán new bounds cho các groups
        const groupBoundsPreview = new Map();
        groupPreviews.forEach((previews, groupId) => {
            const groupItems = previews.map((p) => ({
                left: p.newPosition.left,
                top: p.newPosition.top,
                width:
                    typeof p.newPosition.width === "string" && p.newPosition.width.includes("%")
                        ? (parseFloat(p.newPosition.width) / 100) * config.gridContainerWidth
                        : parseFloat(p.newPosition.width),
                height: p.newPosition.height,
                originalWidth: p.newPosition.width
            }));

            const newBounds = this.calculateGroupBounds(groupItems, config.gridContainerWidth);
            if (newBounds) {
                groupBoundsPreview.set(groupId, newBounds);
            }
        });

        return {
            layoutResult,
            groupPreviews,
            nonGroupPreviews,
            groupBoundsPreview
        };
    }

    /**
     * Log debug info với group support
     */
    static logAutoLayoutInfoWithGroups(blocks, groups, config) {
        const allItemsData = this.convertAllBlocksToLayoutItems(
            blocks,
            groups,
            this.getScreenLayout,
            config.screen,
            config.gridContainerWidth
        );

        const groupedItems = allItemsData.filter((item) => item.isInGroup);
        const ungroupedItems = allItemsData.filter((item) => !item.isInGroup);

        console.group("🎯 Enhanced Auto Layout with Groups Debug Info");
        console.log("📊 Total items:", allItemsData.length);
        console.log("📊 Grouped items:", groupedItems.length);
        console.log("📊 Ungrouped items:", ungroupedItems.length);
        console.log("📐 Grid container width:", config.gridContainerWidth);
        console.log("📱 Screen:", config.screen);
        console.log("⚙️ Config:", config);

        // Log group information
        if (groups) {
            console.log("👥 Groups:", Object.keys(groups).length);
            Object.entries(groups).forEach(([groupId, group]) => {
                const itemsInGroup = allItemsData.filter((item) => item.groupId === groupId);
                console.log(`   Group ${groupId}: ${itemsInGroup.length} items`);
            });
        }

        // Log items table
        const itemsInfo = allItemsData.map((item) => {
            const widthPercent = (item.width / config.gridContainerWidth) * 100;
            return {
                id: item.id,
                groupId: item.groupId || "none",
                position: `${item.left.toFixed(1)}%, ${item.top}px`,
                size: `${item.width}px × ${item.height}px`,
                widthPercent: `${widthPercent.toFixed(1)}%`,
                isFullWidth: widthPercent >= 98,
                willCenter: widthPercent >= 50 || config.centerSingleItemsOnMobile
            };
        });

        console.table(itemsInfo);
        console.groupEnd();
    }
}
// Performance tracking utilities
export class AutoLayoutPerformance {
    private static startTime: number;
    private static markers: Map<string, number> = new Map();

    static start(label: string = "auto-layout") {
        this.startTime = performance.now();
        this.markers.clear();
        console.time(label);
    }

    static mark(label: string) {
        const now = performance.now();
        this.markers.set(label, now - this.startTime);
        console.log(`⏱️ ${label}: ${(now - this.startTime).toFixed(2)}ms`);
    }

    static end(label: string = "auto-layout") {
        const totalTime = performance.now() - this.startTime;
        console.timeEnd(label);
        console.log(`🏁 Total auto layout time: ${totalTime.toFixed(2)}ms`);

        // Log performance breakdown
        if (this.markers.size > 0) {
            console.group("📈 Performance Breakdown");
            this.markers.forEach((time, marker) => {
                const percentage = ((time / totalTime) * 100).toFixed(1);
                console.log(`  ${marker}: ${time.toFixed(2)}ms (${percentage}%)`);
            });
            console.groupEnd();
        }
    }
}

