// Utility functions cho mobile optimization
export class MobileLayoutOptimizer {
    /**
     * Kiểm tra xem có phải layout mobile không
     */
    static isMobileLayout(screen: string, containerWidth: number): boolean {
        return screen === "mobile" || screen === "sm" || containerWidth <= 768;
    }

    /**
     * Tính toán optimal gap cho mobile - CẢI TIẾN CHO FULL-WIDTH - SỬA
     */
    static calculateOptimalGap(
        containerWidth: number,
        itemCount: number,
        hasFullWidthItems: boolean = false
    ): number {
        const baseGap = containerWidth <= 480 ? 5 : containerWidth <= 768 ? 8 : 15;

        // SỬA: Nếu có full-width items, giảm gap nhưng không quá nhỏ
        if (hasFullWidthItems) {
            return Math.max(3, Math.floor(baseGap * 0.7)); // 70% của baseGap, tối thiểu 3px
        }

        return baseGap;
    }

    /**
     * Kiểm tra item có cần căn giữa không trên mobile
     */
    static shouldCenterOnMobile(
        item: LayoutItem,
        config: AutoLayoutConfig,
        isInGroup: boolean = false,
        isFullWidth: boolean = false
    ): boolean {
        if (!config.centerSingleItemsOnMobile) return false;

        const isMobile = this.isMobileLayout(config.screen, config.gridContainerWidth);
        if (!isMobile) return false;

        // Full-width items không cần căn giữa vì đã có left = 0
        if (isFullWidth) return false;

        const widthPercent = (item.width / config.gridContainerWidth) * 100;

        // Luôn căn giữa item rộng
        if (widthPercent >= 50) return true;

        // Căn giữa item đơn lẻ (không trong group)
        if (!isInGroup) return true;

        return false;
    }

    /**
     * Tạo mobile-optimized preset - CẢI TIẾN CHO FULL-WIDTH - SỬA
     */
    static createMobilePreset(
        containerWidth: number,
        hasFullWidthItems: boolean = false
    ): Partial<AutoLayoutConfig> {
        const basePreset =
            containerWidth <= 480
                ? AUTO_LAYOUT_PRESETS.MOBILE_TIGHT
                : containerWidth <= 768
                ? AUTO_LAYOUT_PRESETS.MOBILE_NORMAL
                : AUTO_LAYOUT_PRESETS.MOBILE_SPACIOUS;

        // SỬA: Tính toán fullWidthItemsSpacing dựa trên basePreset và hasFullWidthItems
        const optimalSpacing = hasFullWidthItems
            ? Math.max(3, Math.floor(basePreset.fullWidthItemsSpacing * 0.8)) // Giảm 20%
            : basePreset.fullWidthItemsSpacing;

        return {
            ...basePreset,
            fullWidthItemsSpacing: optimalSpacing,
            minGapPx: hasFullWidthItems ? Math.max(5, basePreset.minGapPx - 2) : basePreset.minGapPx
        };
    }

    /**
     * Phân tích layout cho mobile - TÍNH NĂNG MỚI
     */
    static analyzeMobileLayout(items: LayoutItem[], config: AutoLayoutConfig) {
        const analysis = AutoLayoutHelper.analyzeFullWidthItems(items, config.gridContainerWidth);
        const isMobile = this.isMobileLayout(config.screen, config.gridContainerWidth);

        if (!isMobile) {
            return {
                isMobile: false,
                recommendations: ["Không phải mobile layout - sử dụng desktop optimization"]
            };
        }

        const recommendations: string[] = [];

        if (analysis.fullWidthItems.length > 0) {
            recommendations.push(
                `Mobile: ${analysis.fullWidthItems.length} full-width items sẽ được stack vertically với spacing ${config.fullWidthItemsSpacing}px`
            );
        }

        if (analysis.regularItems.length > 0) {
            const soloItems = analysis.regularItems.filter(
                (item) => !this.isItemInHorizontalGroup(item, analysis.regularItems, config)
            );

            if (soloItems.length > 0) {
                recommendations.push(`Mobile: ${soloItems.length} items đơn lẻ sẽ được căn giữa`);
            }
        }

        if (analysis.conflicts.length > 0) {
            recommendations.push(
                `Mobile: Sẽ tối ưu ${analysis.conflicts.length} conflicts để phù hợp với mobile`
            );
        }

        return {
            isMobile: true,
            analysis,
            recommendations,
            optimalConfig: this.createMobilePreset(
                config.gridContainerWidth,
                analysis.fullWidthItems.length > 0
            )
        };
    }

    /**
     * Kiểm tra item có nằm trong group horizontal không
     */
    private static isItemInHorizontalGroup(
        item: LayoutItem,
        allItems: LayoutItem[],
        config: AutoLayoutConfig
    ): boolean {
        const sameRowItems = allItems.filter((otherItem) => {
            if (otherItem.id === item.id) return false;
            return Math.abs(otherItem.top - item.top) <= config.verticalOverlapThreshold;
        });

        return sameRowItems.length > 0;
    }
}
