import { getMetafieldCodeParts, isValidMetafieldCode, mergeMetafieldToContext, unwrapResponse } from '@/utils/shopifyDataHelper';
import { ScopePermissionDeniedError } from '@/services/ShopifyDataService';
import { mapGetters } from 'vuex';
export default {
    inject: ['exporting'],
    components: {
        Liquid: {
            inject: ['exporting'],
            props: {
                data: {
                    type: String,
                    default: ''
                }
            },
            template: `{{ data && exporting === true ? 'liquid[['+encodeURIComponent(data)+']]' : '' }}`
        }
    },
    data() {
        return {
            currentEid: '',
            // Client-side rendered content, keyed by liquid name
            clientRenderedContent: {} as Record<string, string>,
            // Flag to prevent concurrent renders
            isClientRendering: false,
            pendingRerender: false,
            lastRenderedContextKey: null as string | null,
            renderLiquidsTimer: null as ReturnType<typeof setTimeout> | null,
            // Ensure initial css sync for liquid elements runs only once per mount
            hasSyncedInitialLiquidCss: false,
            // Mark when initial css sync has completed (used by components to hide skeleton)
            hasFinishedInitialLiquidCssSync: false,
            // Bật khi một call CSR bị từ chối scope -> ép element render SSR.
            liquidForceSSR: false,
        }
    },
    computed: {
        edata() {
            return this.data;
        },
        csrContextReactiveKeys(): string[] {
            const declared = (this as any).csrContextReactives;
            return Array.isArray(declared) && declared.length ? declared : ['handle'];
        },
        safeModeEnabled(): boolean {
            return this.$store.getters['builder/safeMode'] || false;
        },
        liquidData() {
            return this.getLiquids[this.edata.id];
        },
        canUseCustomLiquidForCSR(): boolean {
            return !this.exporting && !!this.$shopifyData && !!this.$liquidEngine;
        },
        isEcosystemApp(): boolean {
            return !this.exporting && (this.$options as any)?.isEcosystemApp === true;
        },
        isUsingLiquidCSR() {
            // Ecosystem app: luôn render Liquid bằng SSR, không dùng CSR.
            if (this.isEcosystemApp) return false;
            // Một call CSR đã bị từ chối scope -> ép SSR.
            if (this.liquidForceSSR) return false;
            return this.canUseCustomLiquidForCSR && this.canRenderClientSide;
        },
        canFallbackToLiquidSSR(): boolean {
            // Ecosystem app phải SSR kể cả khi Safe Mode bật (Safe Mode vốn CSR-only).
            if (this.isEcosystemApp) return true;
            return !this.safeModeEnabled;
        },
        /**
         * Check if element can render client-side
         * Returns true if at least one template can be rendered client-side
         * Individual templates with skipClientRender will fallback to server in liquid() method
         */
        canRenderClientSide(): boolean {
            if (!this.canUseCustomLiquidForCSR || !this.liquids) return false;

            let hasClientRenderableTemplate = false;

            for (const key of Object.keys(this.liquids)) {
                const liquid = this.liquids[key];
                // Skip templates marked for server-side rendering
                if (liquid.skipClientRender) {
                    continue;
                }
                // In builder mode, form and paginate are not needed
                if (this.$liquidEngine.hasUnsupportedTags(liquid.code, true)) {
                    continue; // Has {% render %} or {% section %}
                }
                hasClientRenderableTemplate = true;
            }

            return hasClientRenderableTemplate;
        },

        shopifyContext() {
            const _this: any = this;

            if (_this?.csrContext != null) return _this.csrContext;

            const section = _this.shopifyWrapper;
            const type = section?.shopify_type;

            if (!type) return null;

            return {
                type,
                handle: section.data?.settings?.[type]?.value || null
            };
        },
        reactiveLiquidRaw() {
            let rawdata = '',
                raws = {};
            if (!this?.data?.id) {
                return '';
            }
            if (this.liquids) {
                let isEmpty = true;
                Object.keys(this.liquids).forEach((lq) => {
                    if (this.liquids[lq].code && this.liquids[lq].code !== '') {
                        isEmpty = false;
                    }
                    rawdata += `<ecom-embed-start id="${this.edata.id}" name="${lq}" />`;
                    rawdata += `${this.liquids[lq].code}`;
                    rawdata += `<ecom-embed-end id="${this.edata.id}" name="${lq}" />`;
                    raws[lq] = this.liquids[lq].code;
                });
                return {
                    before: this.shopifyWrapper?.liquidBefore ?? '',
                    after: this.shopifyWrapper?.liquidAfter ?? '',
                    raw: isEmpty ? '' : rawdata,
                    raws: isEmpty ? {} : raws
                };
            }
            return '';
        },
        shopifyWrapper() {
            let hasRequestLiquidFound = false;
            let get = (o) => {
                if (!o) return null;
                if (o?.data?.hasRequestLiquid === true) {
                    hasRequestLiquidFound = true;
                }

                if (o.shopify_type) {
                    // Chỉ ghi khi giá trị thực sự đổi: đây là computed nên mọi lần ghi
                    // đều có thể trigger lại các effect đang đọc `o.data`.
                    if (hasRequestLiquidFound && o.data.hasElementRequestLiquid !== true) {
                        o.data.hasElementRequestLiquid = true;
                    }
                    return o;
                }
                return get(o.$parent);
            };
            return get(this);
        },
        ...mapGetters('builder', ['getLiquids'])
    },
    methods: {
        parent(is) {
            let get = (o) => {
                return o ? (o.is == is ? o : get(o.$parent)) : null;
            };
            return get(this);
        },
        /**
         * Main liquid rendering method - hybrid approach
         * Now purely synchronous - just returns cached content
         */
        liquid(name) {
            // Export mode: return encoded liquid
            if (this.exporting === true) {
                if (this.data.id !== this.currentEid) {
                    this.reactiveLiquid();
                }
                return 'liquid[[' + encodeURIComponent((this.liquidData?.raws ?? {})[name] ?? '') + ']]';
            }

            const liquidDef = this.liquids?.[name];

            // Preview export: instance preview là app Vue mới, không có $shopifyData và
            // đọc innerHTML ngay sau mount nên không CSR lại được. Dùng lại HTML mà
            // builder đã render CSR (lưu trong store dùng chung theo element id).
            if (this.exporting === 'preview') {
                const csrContent = (this.liquidData?.csr ?? {})[name];
                if (csrContent) {
                    return csrContent;
                }
            }

            // Check per-template skipClientRender flag
            if (liquidDef?.skipClientRender) {
                // Safe Mode is CSR-only, so unsupported templates stay on preview.
                if (!this.canFallbackToLiquidSSR) {
                    return liquidDef?.preview ?? '';
                }
                // Use server-rendered content or preview for this specific template
                return (this.liquidData?.content ?? {})[name] ?? (liquidDef?.preview ?? '');
            }

            // Try client-side rendered content first
            if (this.isUsingLiquidCSR) {
                const result = this.clientRenderedContent[name] ?? liquidDef?.preview ?? '';
                return result;
            }

            if (!this.canFallbackToLiquidSSR) {
                return liquidDef?.preview ?? '';
            }

            // Fallback: server-rendered content or preview
            return (this.liquidData?.content ?? {})[name] ?? (liquidDef?.preview ?? '');
        },
        /**
         * Pre-render ALL liquid templates client-side
         * Called when shopifyContext changes
         */
        async renderAllLiquidsClientSide() {
            if (this.renderLiquidsTimer) {
                clearTimeout(this.renderLiquidsTimer);
            }

            this.renderLiquidsTimer = setTimeout(() => {
                this.renderLiquidsTimer = null;
                this._renderAllLiquidsClientSideNow();
            }, 250);
        },
        async _renderAllLiquidsClientSideNow() {
            if (!this.liquids) return;
            if (!this.isUsingLiquidCSR) return;
            if (this.isClientRendering) {
                this.pendingRerender = true;
                return;
            }

            this.isClientRendering = true;

            try {
                if (
                    typeof this.$liquidEngine?.whenReady === 'function' &&
                    this.$liquidEngine.isReady?.() !== true
                ) {
                    let timeoutId: ReturnType<typeof setTimeout> | undefined;
                    await Promise.race([
                        this.$liquidEngine.whenReady(),
                        new Promise((r) => { timeoutId = setTimeout(r, 3000); })
                    ]);
                    clearTimeout(timeoutId);
                }

                // Build context once for all templates
                const context = await this.buildLiquidContext();
                const newContent: Record<string, string> = {};

                // Render each liquid template
                for (const name of Object.keys(this.liquids)) {
                    const liquidDef = this.liquids[name];

                    // Skip templates marked for server-side rendering
                    if (liquidDef.skipClientRender) {
                        continue;
                    }

                    const template = liquidDef.code;
                    if (!template) {
                        newContent[name] = liquidDef.preview ?? '';
                        continue;
                    }

                    try {
                        newContent[name] = await this.$liquidEngine.render(template, context);
                    } catch (error) {
                        newContent[name] = liquidDef.preview ?? '';
                    }
                }

                this.clientRenderedContent = newContent;
                this.cacheCsrContentForPreview(newContent);

                const ctx: any = this.shopifyContext;
                let contextKey = '';
                if (ctx) {
                    contextKey = [ctx.type, ...this.csrContextReactiveKeys.map((k) => ctx[k] ?? '')].join('|');
                }
                const contextChanged =
                    this.lastRenderedContextKey !== null && this.lastRenderedContextKey !== contextKey;
                this.lastRenderedContextKey = contextKey;

                if (contextChanged) {
                    this.edata.refresh = this.$helpers.randid();
                    return;
                }

                this.$nextTick(() => {
                    if (typeof this.runJavascript === 'function') {
                        this.runJavascript();
                    }
                    this.syncInitialLiquidCssOnce();
                    const styleHost = (this as any).$refs?.blockElement?.$el || this.$el;
                    if (styleHost && !styleHost.querySelector(`style[data-id="${this.data.id}"]`)) {
                        (this.createStyle || this.$parent?.createStyle || this.$parent?.$parent?.createStyle)?.();
                    }
                });
            } catch (error) {
                // Một call CSR bị từ chối scope -> bỏ CSR, render element bằng SSR
                // (server có object Liquid native, không cần scope của app).
                if (error instanceof ScopePermissionDeniedError) {
                    this.liquidForceSSR = true; // sticky: isUsingLiquidCSR giữ false, watcher không thử lại CSR
                    this.clientRenderedContent = {};
                    this.cacheCsrContentForPreview({});
                    if (this.canFallbackToLiquidSSR) {
                        this.reactiveLiquid();
                    }
                } else {
                    console.error('[Liquid] Failed to build context:', error);
                }
            } finally {
                this.isClientRendering = false;
                if (this.pendingRerender) {
                    this.pendingRerender = false;
                    this.renderAllLiquidsClientSide();
                }
            }
        },
        /**
         * Lưu HTML đã render CSR vào store dùng chung (builder/liquids[id].csr).
         * doExport('preview') mount một app Vue khác nhưng dùng chung store, nên đây là
         * đường duy nhất để preview lấy được nội dung CSR một cách đồng bộ.
         */
        cacheCsrContentForPreview(content: Record<string, string>) {
            // Chỉ builder được ghi cache; instance export/preview chỉ đọc.
            if (this.exporting !== false) return;

            const id = this.data?.id;
            if (!id || !this.getLiquids) return;

            if (!this.getLiquids[id]) {
                this.getLiquids[id] = {};
            }
            this.getLiquids[id].csr = { ...content };
        },
        syncInitialLiquidCssOnce() {
            if (this.exporting !== false || this.hasSyncedInitialLiquidCss) return;
            this.hasSyncedInitialLiquidCss = true;
            // Không dùng $nextTick(cb) trực tiếp: nếu flush hiện tại của Vue reject
            // (vd scheduler error ở component khác), callback sẽ bị bỏ qua vĩnh viễn
            // và css của element không bao giờ được sync (skeleton treo).
            this.$nextTick()
                .catch(() => { })
                .then(() => this.syncInitialLiquidCss());
        },
        async syncInitialLiquidCss() {
            if (this.exporting !== false) return;
            // @ts-ignore - from Element mixin
            if (typeof this.reactiveConvertCss === 'function') {
                // @ts-ignore
                const settings = this.$helpers.copy(this.data?.settings || {});
                // @ts-ignore
                const style = this.$helpers.copy(this.data?.style || {});
                if (Object.keys(settings).length) {
                    // @ts-ignore
                    this.reactiveConvertCss('settings', settings);
                }
                if (Object.keys(style).length) {
                    // @ts-ignore
                    this.reactiveConvertCss('style', style);
                }
            }
            this.hasFinishedInitialLiquidCssSync = true;
        },
        /**
         * Build Liquid context from section settings and cached data
         */
        async buildLiquidContext(): Promise<any> {
            const _this = this as any;
            const { type, handle, handles, name } = _this.shopifyContext || {};
            const context: any = {};

            if (!type) return context;

            try {
                context.shop = unwrapResponse(await _this.$shopifyData.get('shop'));
            } catch (error) {
                console.warn('[Liquid] Failed to load shop data:', error);
            }

            // Include type-specific data
            try {
                switch (type) {
                    case 'product':
                        const product = unwrapResponse(await _this.$shopifyData.get('product', handle))

                        context.product = product;
                        context.selected_variant = context.product?.selected_or_first_available_variant;
                        context.current_variant = context.selected_variant;

                        const metafieldCode = _this.shopifyContext?.metafieldCode;
                        if (product.handle && isValidMetafieldCode(metafieldCode)) {
                            try {
                                const metafield = await _this.$shopifyData.getMetafield(metafieldCode, {
                                    productHandle: product.handle
                                });

                                if (metafield) {
                                    const { resource, namespace, key } = getMetafieldCodeParts(metafieldCode);
                                    mergeMetafieldToContext(context, resource, namespace, key, metafield);
                                }
                            } catch {
                                //Silent fail
                            }
                        }

                        break;
                    case 'collection':
                        const collection = await _this.$shopifyData.getCollection(handle);
                        context.collection = collection;
                        context.products = collection?.products || [];

                        const filtersTask = (collection && _this.shopifyContext?.withFilters && !collection.filters)
                            ? _this.$shopifyData.getCollectionFilter(collection.handle)
                            : null;

                        const { value: linkValue, name: linkName } = _this.shopifyContext?.linklistData || {};
                        const menuTask = (linkValue && linkName)
                            ? _this.$shopifyData.getMenu(linkValue, linkName)
                            : null;

                        const [filtersRes, menuRes] = await Promise.allSettled([filtersTask, menuTask]);

                        if (filtersTask) {
                            if (filtersRes.status === 'fulfilled') {
                                collection.filters = filtersRes.value;
                            } else if (filtersRes.reason instanceof ScopePermissionDeniedError) {
                                throw filtersRes.reason;
                            } else {
                                collection.filters = [];
                            }
                        }

                        if (menuTask) {
                            if (menuRes.status === 'fulfilled') {
                                if (menuRes.value) {
                                    context.linklists = {
                                        ...context.linklists || {},
                                        [linkValue]: menuRes.value
                                    };
                                }
                            } else if (menuRes.reason instanceof ScopePermissionDeniedError) {
                                throw menuRes.reason;
                            }
                        }
                        break;
                    case 'list-collections':
                        context.collections = unwrapResponse(await _this.$shopifyData.get('collections'));
                        break;
                    case 'article':
                        context.article = unwrapResponse(await _this.$shopifyData.get('article', handle));
                        context.blog = context?.article?.blog;
                        break;
                    case 'blog':
                        context.blog = unwrapResponse(await _this.$shopifyData.get('blog', handle));
                        break;
                    case 'blogs':
                        context.blogs = unwrapResponse(await _this.$shopifyData.getBlogs(handles || []));
                        break;
                    case 'menu':
                        if (!handle) break;
                        context.linklists = {
                            ...context.linklists || {},
                            [handle]: await _this.$shopifyData.getMenu(handle, name)
                        }
                        break;
                    case 'collection-items':
                        context.collections = await _this.$shopifyData.getCollectionsByContext(_this.shopifyContext);
                        break;
                    case 'localization':
                        context.localization = await _this.$shopifyData.getLocalization(_this.$store.getters['builder/storefrontAvailable']);
                        break;
                    case 'cart':
                        context.cart = unwrapResponse(await _this.$shopifyData.get("cart"));
                        break;
                    case 'product-filter':
                        const filterData = _this.$shopifyData.getFilterData();
                        context.shop = {
                            ...context.shop || {},
                            ...(filterData.shop || {}),
                        }
                        context.collections = filterData.collections;
                        break;
                }
            } catch (error) {
                // Từ chối scope -> ném lên cho _renderAllLiquidsClientSideNow chuyển sang SSR.
                if (error instanceof ScopePermissionDeniedError) throw error;
                console.warn(`[Liquid] Failed to load ${type}:`, error);
            }

            // Add common context
            context.request = {
                page_type: type,
                host: window.location.host,
                path: window.location.pathname
            };

            context.section = this.shopifyWrapper?.data;

            // Merge local component context if available (e.g. from CollectionProductCSR)
            // @ts-ignore
            if (this.context && typeof this.context === 'object') {
                // @ts-ignore
                Object.assign(context, this.context);
            }

            return context;
        },
        reactiveLiquid() {

            let val = this.reactiveLiquidRaw;

            if (
                !this.liquids
            ) {
                return;
            }

            let id = this.data.id;

            if (!this.getLiquids[id]) {
                this.getLiquids[id] = {};
            }

            let myLiquid = this.getLiquids[id];

            if (this.exporting !== false) {
                myLiquid.raws = val.raws;
                this.currentEid = id;
                return;
            }

            if (!myLiquid.content) {
                myLiquid.content = {};
                Object.keys(this.liquids).forEach((l) => {
                    // Use preview if the liquid content of name is not loaded
                    if (!myLiquid.content[l]) {
                        myLiquid.content[l] = this.liquids[l].preview;
                    }
                });
            }

            if (
                val === '' || !val.raw ||
                (
                    myLiquid.raw === val.raw &&
                    myLiquid.before === val.before &&
                    myLiquid.after === val.after
                )
            ) {
                return;
            }

            myLiquid.raw = val.raw;
            myLiquid.raws = val.raws;
            myLiquid.before = val.before;
            myLiquid.after = val.after;

            this.shopifyWrapper.processLiquid(this.edata);
        }
    },
    watch: {
        reactiveLiquidRaw() {
            // Only trigger server-side processing if client-side can't handle it
            if (!this.isUsingLiquidCSR && this.canFallbackToLiquidSSR) {
                this.reactiveLiquid();
            }
        },
        shopifyContext: {
            handler() {
                this.clientRenderedContent = {};
                this.cacheCsrContentForPreview({});
                this.renderAllLiquidsClientSide();
            },
            deep: true
        },
        liquids: {
            immediate: true,
            handler() {
                if (this.liquids && this.shopifyContext) {
                    this.renderAllLiquidsClientSide();
                }
            },
            deep: true
        }
    },
    mounted() {
        if (this.exporting !== false) {
            return;
        }
        if (!this.edata.id) {
            this.edata.id = this.$helpers.randid();
        }

        if (
            this.requestShopifyType &&
            !this.shopifyWrapper.acceptRequest(this.requestShopifyType)
        ) {
            this.$store.commit('global/setToast', {
                isError: true,
                message: this.$t("this_element_type_cannot_be_dropped_into_a_section_please_drop_it_to_another_section", { shopify_type: this.shopifyWrapper.shopify_type }),
                duration: 4000
            }, { root: true });
            return setTimeout(() => {
                typeof this.$parent.dropOut === 'function' && this.$parent.dropOut();
            }, 10);
        }

        if (!this.isUsingLiquidCSR && this.canFallbackToLiquidSSR) {
            this.reactiveLiquid();
        }
        this.syncInitialLiquidCssOnce();
    },
    beforeUnmount() {
        if (this.renderLiquidsTimer) {
            clearTimeout(this.renderLiquidsTimer);
            this.renderLiquidsTimer = null;
        }
    }
};
