<template>
    <div class="ecom-element ecom-product-single ecom-product-single__quantity">
        <Liquid :data="productQty" />
        <div class="ecom-product-single__quantity-wrapper">
            <div class="ecom-product-single__quantity-container">
                <label class="ecom-product-single__quantity-container-label" for="quantity" v-text="lang(title, 'quanity_label')" />
                <div v-if="data.settings?.type === 'dropdown'" id="quantity-dropdown" class="ecom-product-single__quantity-dropdown-wrapper">
                    <select
                        name="quantity"
                        id="quantity"
                        class="ecom-product-single__quantity-dropdown"
                        :data-min-value="quantity_min_value"
                        :data-max-limit="quantity_dropdown_max_value"
                        :data-max-value="quantity_dropdown_max_value"
                        :data-step="quantity_step"
                        data-value = "1"
                        required
                    ></select>
                </div>
                <div v-else class="ecom-product-single__quantity-controls">
                    <button
                        type="button"
                        class=" ecom-product-single__quantity-controls-button ecom-product-single__quantity-controls-minus"
                        aria-label="control minus"
                    >
                        <ecom-icon v-if="!data.settings?.icon_minus" :source="icons.MinusMajor" class="ecom-product-single__quantity-controls-icon" />
                        <span v-else  v-html="data.settings?.icon_minus" class="ecom-flex ecom-fl_center ecom-al_center"/>
                    </button>
                    <label for="quantity" style="display: none;">Quantity</label>
                    <input
                        name="quantity"
                        type="number"
                        inputmode="numeric"
                        pattern="\d*"
                        id="quantity"
