<script>
import { MinusMajor, AddMajor } from '@/assets/icons';
import { Element, Javascript, Liquid } from '@/mixins';

export default {
    name: 'productQuantity',

    presets:true,

    mixins: [Element, Javascript, Liquid],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data(){
        return {
            jsreactives: [
                'use_quantity_limit',
                'quantity_min',
                'quantity_max',
                'quantity_step',
                'type'
            ]
        }
    },

    computed: {
        liquids() {
            return {
                maxQty: {
                    code: `${this.data.settings?.use_quantity_limit && this.data.settings?.quantity_max ? parseInt(this.data.settings.quantity_max) : `{{ max_qty | default: 9999 }}`}`
                }
            };
        },
        productQty() {
            return `
                {%- liquid
                assign selected_variant = product.selected_variant | default: product.selected_or_first_available_variant
                assign quantity_rule = selected_variant.quantity_rule
                assign current_inventory_quantity = selected_variant.inventory_quantity
                if selected_variant.inventory_management != null and current_inventory_quantity > 0 and selected_variant.inventory_policy != 'continue'
                    assign max_qty = current_inventory_quantity
                endif
                if selected_variant.quantity_rule.max and max_qty > selected_variant.quantity_rule.max
                    assign max_qty = selected_variant.quantity_rule.max
                endif
            -%}
            `;
        },
        quantity_min_value(){
            return this.data.settings?.use_quantity_limit && this.data.settings?.quantity_min ?  parseInt(this.data.settings.quantity_min):1;
        },
        quantity_input_max_value(){
            return this.data.settings?.use_quantity_limit && this.data.settings?.quantity_max ?  parseInt(this.data.settings.quantity_max):9999;
        },
        quantity_dropdown_max_value(){
            return this.data.settings?.use_quantity_limit && this.data.settings?.quantity_max ?  parseInt(this.data.settings.quantity_max):'';
        },
        quantity_step(){
            return this.data.settings?.quantity_step ? this.data.settings.quantity_step : 1;
