                                }
                            }
                        }
                    ]
                }
            ];
        },
        javascript() {
            return function () {
                const $el = this.$el;
                if(!$el) {
                    return;
                }
                let quantity_type = this.settings.type;
                let use_quantity_limit = this.settings.use_quantity_limit ? this.settings.use_quantity_limit : false;
                let quantityStep = this.settings.quantity_step ? this.settings.quantity_step : 1;
                let minValue = this.settings?.quantity_min ? this.settings.quantity_min : 1;
                let maxLimit = this.settings?.quantity_max ? this.settings.quantity_max : '';
                let dropdown_value = 1;
                const $wrapper = $el.closest('.ecom-product-form--single');
                const $quantity_dropdown = $el.querySelector('.ecom-product-single__quantity-dropdown');
                
                if($wrapper){
                    if(!this.isLive){
                        $wrapper.dispatchEvent(new CustomEvent('ecomQuantityType'));
                    }
                }
                if(quantity_type !== 'dropdown'){
                    const $plus = $el.querySelector('.ecom-product-single__quantity-controls-plus');
                    const $minus = $el.querySelector('.ecom-product-single__quantity-controls-minus');
                    const $input = $el.querySelector('.ecom-product-single__quantity-input');
                    if(!$plus || !$minus || !$input) return;
                    if ($input.value === '') {
                    $input.value = this.settings.quantity_min && parseInt(this.settings.quantity_min)>0 ? parseInt(this.settings.quantity_min) :'1';
                    }
                    if (!this.isLive) {
                         if ($input.dataset.ecomQtyBound === 'true') return;
                        $input.dataset.ecomQtyBound = 'true';
                    }
                    $plus.addEventListener('click', function (e) {
                        e.preventDefault();
                        $input.stepUp();
                        $input.dispatchEvent(new Event('change'));
                    });
                    $minus.addEventListener('click', function (e) {
                        e.preventDefault();
                        $input.stepDown();
                        $input.dispatchEvent(new Event('change'));
                    });
                    $input.addEventListener('change', function (e) {
                        const currentMax = $input.getAttribute('max');
                        if (currentMax && parseInt(currentMax) < parseInt(e.target.value)) {
                            e.target.value = parseInt(currentMax);
                        }
                        if($input.dataset.minValue && parseInt(e.target.value) < parseInt($input.dataset.minValue)){
                            e.target.value = parseInt($input.dataset.minValue);
                        }
                    });
                }else {
                    const $wrapper = $el.closest('.ecom-product-form--single');
                    if (!$wrapper) return false;
                    let selector = $wrapper.querySelector('[name="id"]');
                    const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                    const isHighVariantProduct = this.isLive && (variantCount > 250 || $wrapper.querySelector('[data-high-variant-product]'));
                    let product = null;
                    let isProductDefaultVariant = false;
                    
                    const readProductJson = () => {
                        if (!selector) return null;
                        const json = $wrapper.querySelector('#' + selector.dataset.jsonProduct) || !this.isLive ? $wrapper?.querySelector('[id^=product-json]') : null;
                        if (!json) return null;
                        try {
                            return JSON.parse(json.innerHTML);
                        } catch (e) {
                            return null;
                        }
                    };
                    if (selector) {
                        if(selector.classList.contains('ecom-product-single__picker-default-variant')) {
                            isProductDefaultVariant = true;
                        }
                        product = readProductJson();
                        if(!this.isLive){
                            setTimeout(()=>{
                                selector.dispatchEvent(new window.Event('ecomUpdate'));
                            }, 50);
                        }
                    }
                    const initDropdown = (selectedVariant = null) => {
                        let options = [];
                        let max_value = getMaxValue(selectedVariant);
                        let startValue = use_quantity_limit && minValue ?  minValue : 1;
                        let endValue = max_value > 0 ? max_value : 0;
                        if (startValue <= endValue) {
                            for (let i = startValue; i <= endValue; i += quantityStep) {
                                options.push(i);
                            }
                            if (options[options.length - 1] < endValue) {
                                options.push(endValue);
                            }
                        }
                        else{
                            if(startValue > endValue ){
                                options = [dropdown_value];
                            }
                        }
                        if (Array.isArray(options) && options.length){
                            $quantity_dropdown.innerHTML = '';
                            options.forEach(item => {
                                let option = document.createElement('option');
                                option.setAttribute('value', item);
                                option.text= item;
                                $quantity_dropdown.add(option);
                            });
                        }
                    }
                    function getMaxValue(selectedVariant = null){
                        let variant = null;
                        if(isHighVariantProduct) {
                            variant = product
                        }else if (isProductDefaultVariant) {
                            variant = product && product.variants ? product.variants[0] : null;
                        }else {
                            variant = selectedVariant;
                        }
                        let inventory_quantity = variant?.inventory_quantity;
                        let inventory_management = variant?.inventory_management;
                        let policy = variant?.inventory_policy;
                        let max_value = 0;
                        if(!variant || !variant.available){
                            dropdown_value = minValue;
                            $quantity_dropdown.setAttribute('disabled', true);
                            return minValue;
                        }
                        if (!dropdown_value || minValue > 0 && (dropdown_value < minValue)){
                            dropdown_value = minValue;
                        }
                        $quantity_dropdown.removeAttribute('disabled');
                        if(inventory_management){
                            if(inventory_quantity < 1 && policy == 'continue'){
                                let max = maxLimit && maxLimit > 0 ? maxLimit : '';
                                max_value = handleMaxValue( inventory_management, inventory_quantity, max );
                            }
                            if(inventory_quantity > 0){
                                if (inventory_quantity < minValue ) {
                                    dropdown_value = inventory_quantity;
                                }
                                if (policy === 'deny'){
                                    let max = maxLimit && maxLimit <= inventory_quantity ? maxLimit : inventory_quantity;
                                    max_value = handleMaxValue( inventory_management, inventory_quantity, max );
                                }
                                if(policy === 'continue'){
                                    let max = maxLimit && maxLimit <= inventory_quantity ? maxLimit : inventory_quantity;
                                    max_value = handleMaxValue( inventory_management, inventory_quantity, max );
                                }
                            }
                        }else{
                            let max = maxLimit && maxLimit > 0 ? maxLimit : '';
                            max_value = handleMaxValue( inventory_management, inventory_quantity, max );
                        }
                        if(maxLimit && minValue > maxLimit){
                                    dropdown_value = maxLimit;
                                    max_value = maxLimit;
                                    $quantity_dropdown.setAttribute('disabled', true);
                            }
                        if(max_value < 0){
                            max_value = 0;
                        }
                        if (max_value && dropdown_value > max_value) {
                            dropdown_value = max_value;
                        }
                        dropdown_value = isNaN(dropdown_value) || !dropdown_value ? 1 : dropdown_value;
                        $quantity_dropdown.dataset.value = dropdown_value;
                        return max_value;
                    }
                    function handleMaxValue( inven_management, inven_quantity = 0, max = 0) {
                        if(maxLimit && maxLimit > 0){
                            return max;
                        }
                        let value = minValue;
                        let count = 1;
                        for (let i = 1; i < 10; i++) {
                            if(max ? (value + quantityStep <= max): true) {
                                value = value + quantityStep;
                                count++;
                            }else{
                                break;
                            }
                        }
                        if (count < 10 && inven_management && inven_quantity && value + quantityStep > inven_quantity && inven_quantity < inven_quantity + quantityStep) {
                                value = inven_quantity;
                            }
                        return value;
                    }
                    const getInitialVariant = () => {
                        if (!product) return null;
                        if (isProductDefaultVariant) return product.variants && product.variants[0];
                        if (isHighVariantProduct) return product;
                        return product.selected_or_first_available_variant
                            || (product.variants && product.variants.find(v => v.available))
                            || (product.variants && product.variants[0])
                            || null;
                    };
                    
                    let buildFrames = 0;
                    const buildDropdown = () => {
                        if (this.isLive) {
                            initDropdown();
                            return;
                        }

                        if (!selector) {
                            selector = $wrapper.querySelector('[name="id"]');
                            if (selector && selector.classList.contains('ecom-product-single__picker-default-variant')) {
                                isProductDefaultVariant = true;
                            }
                        }
                        if (!product) {
                            product = readProductJson();
                        }
                        initDropdown(getInitialVariant());
                        if ((!selector || !product) && buildFrames < 60) {
                            buildFrames++;
                            requestAnimationFrame(buildDropdown);
                        }
                    };
                    buildDropdown();
                    $wrapper.addEventListener('ecomVariantChange', function(event) {
                        if(event.detail.variant) {
                            initDropdown(event.detail.variant);
                        }
                    })
                }

            };
        },
        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },
        title() {
            return this.data && this.data.settings && this.data.settings.title
                ? this.data.settings.title
                : '';
        },
        default() {
            return {
                "settings": {
                    "type": "input",
                    "justify-content": "flex-start",
                    "spacing": "0px",
                    "layout": "column",
                    "quantity_min": 1,
                    "quantity_max": 10,
