                            }
                        },
                        "padding": {
                            "top": "0px",
                            "left": "15px",
                            "bottom": "0px",
                            "right": "15px"
                        }
                    },
                    "quanity_minus": {
                        "iconBordernormalmode": {
                            "border-style": "solid",
                            "border-width": {
                                "top": "1px",
                                "left": "0px",
                                "bottom": "1px",
                                "right": "1px"
                            },
                            "border-color": "rgba(17, 24, 39, 0.2)"
                        },
                        "tab": "normal",
                        "iconFontSize": "24px",
                        "iconPrimaryColornormalmode": "#000000",
                        "iconBackgroundnormalmode": {
                            "classic": {
                                "background-color": "#f5f5f5"
