                        }
                    },
                    "quantity_dropdown": {
                        "tab": "normal",
                        "typo": {
                            "font-size": "16px"
                        },
                        "color": "#000",
                        "width": "136px",
                        "background": {
                            "classic": {
                                "background-color": "#F5F5F5"
                            }
                        }
                    },
                    "general": {
                        "height": "40px"
