                }
            }
        }
    },
    methods: {
        quickToolBar() {
            return ['layout'];
        },
        style() {
            let style = [
                {
                    group_name: 'general',
                    group_title: this.$t('general'),
                    selector: ' .ecom-product-single__quantity-container .ecom-product-single__quantity-controls input, .ecom-product-single__quantity-controls-button, .ecom-product-single__quantity-container .ecom-product-single__quantity-dropdown',
                    liteMode: true,
                    params: [
                        {
                            type: "number",
                            label: this.$t('height'),
                            name: 'height',
                            options: {
                                responsive: true,
                                reset: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 100
                                    },
                                }
                            },
                            css: {
                                properties: {
                                    height: ""
                                }
                            }
                        }
                    ]
                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('title'),
                        group_name: 'quanity_title',
                        selector: ' .ecom-product-single__quantity-container label'
                    }
                }
            ];
            if (this.data?.settings?.type === 'dropdown'){
                style.push({
                        group_alias: 'input',
                        options: {
                            group_title: this.$t('quantity_dropdown'),
                            group_name: 'quantity_dropdown',
                            selector: ' .ecom-product-single__quantity .ecom-product-single__quantity-dropdown',
                        },
                        modify: {
                            remove: {
                                name: ['colorPlaceholder']
                            }
                        }
                })
            }else{
                style.push({
                    group_alias: 'input',
                    options: {
                        group_title: this.$t('quantity_input'),
                        group_name: 'quanity_quanity',
                        selector:
                            ' .ecom-product-single__quantity-container .ecom-product-single__quantity-controls input'
                    }
                    },
                    {
                        group_alias: 'icon:hover',
                        options: {
                            group_title: this.$t('minus'),
                            group_name: 'quanity_plus',
                            selector:
                                ' .ecom-product-single__quantity-container .ecom-product-single__quantity-controls-minus'
                        },
                        modify:{
                            params:[
                                {
                                position:10,
                                fields: {
                                    type: 'dimension',
                                    label: this.$t('padding'),
                                    name: 'padding',
                                    options: {
                                        units: 'default',
                                        simple: true
                                    }
                                }
                            }

                            ]
                        }
                    },
                    {
                        group_alias: 'icon:hover',
                        options: {
                            group_title: this.$t('plus'),
                            group_name: 'quanity_minus',
                            selector:
                                ' .ecom-product-single__quantity-container .ecom-product-single__quantity-controls-plus'
                        },
                        modify:{
                            params:[
                                {
                                    position:10,
                                    fields: {
                                        type: 'dimension',
                                        label: this.$t('padding'),
                                        name: 'padding',
                                        options: {
                                            units: 'default',
                                            simple: true
                                        }
                                    }
                                }

                            ]
                        }
                    }
            )
            }
            return style;
        }
    }
};
</script>
