/**
 * Sinh Liquid hiển thị một metafield theo data type của nó.
 *
 * Tách riêng khỏi element vì MF-EL-04 (rich text, file) và MF-EL-06 (reference,
 * list) đều gọi lại: phần `list.*` chỉ là vòng lặp gọi hàm này với `item` thay vì
 * `owner.metafields.ns.key`. Nếu để logic nằm trong element thì hai task đó phải
 * duplicate toàn bộ bảng type.
 *
 * `expr` là biểu thức Liquid trỏ tới metafield, KHÔNG kèm `.value` —
 * ví dụ `product.metafields.custom.material` hoặc một biến vòng lặp.
 */

/**
 * Type dùng chung shape `{ value, unit }`. Shopify gọi nhóm này là measurement;
 * ngoài dimension/weight/volume còn ~30 type khác nhưng render giống hệt nhau.
 * Nguồn: https://shopify.dev/docs/apps/build/metafields/list-of-data-types
 */
export const MEASUREMENT_TYPES = [
    'dimension', 'weight', 'volume', 'area', 'distance', 'duration', 'energy',
    'power', 'pressure', 'speed', 'temperature', 'voltage', 'frequency',
    'antenna_gain', 'battery_charge_capacity', 'battery_energy_capacity',
    'capacitance', 'concentration', 'data_storage_capacity', 'data_transfer_rate',
    'display_density', 'electric_current', 'electrical_resistance', 'illuminance',
    'inductance', 'luminous_flux', 'mass_flow_rate', 'resolution',
    'rotational_speed', 'sound_level', 'thermal_power', 'volumetric_flow_rate',
];

export function isMeasurementType(type?: string | null): boolean {
    return !!type && MEASUREMENT_TYPES.includes(type);
}

/**
 * Reference trong scope MF-EL-06. `mixed_reference` KHÔNG bao giờ có mặt ở đây
 * (PO chốt tại Q6), `metaobject_reference` đi đường riêng vì nó là container.
 */
export const REFERENCE_TYPES = [
    'product_reference',
    'collection_reference',
    'page_reference',
    'article_reference',
    'variant_reference',
];

/**
 * Ảnh nằm ở field khác nhau tuỳ loại resource. `page` không có ảnh — chế độ Ảnh
 * của nó phải rơi về tiêu đề thay vì render thẻ img rỗng.
 */
const REFERENCE_IMAGE_FIELD: Record<string, string> = {
    product_reference: 'featured_image',
    collection_reference: 'image',
    article_reference: 'image',
    variant_reference: 'image',
};

export function isReferenceType(type?: string | null): boolean {
    return !!type && REFERENCE_TYPES.includes(type);
}

/** Có chế độ hiển thị Ảnh hay không — dropdown của element bám theo hàm này. */
export function referenceHasImage(type?: string | null): boolean {
    return !!type && !!REFERENCE_IMAGE_FIELD[type];
}

/**
 * Type KHÔNG có biến thể `list.*` phía Shopify. Dùng để sinh danh sách type hỗ
 * trợ, tránh đẻ ra `list.boolean` — thứ merchant không bao giờ chọn được.
 */
export const TYPES_WITHOUT_LIST = [
    'boolean', 'id', 'json', 'language', 'money',
    'multi_line_text_field', 'rich_text_field',
];

const LIST_PREFIX = 'list.';

export function isListType(type?: string | null): boolean {
    return !!type && type.startsWith(LIST_PREFIX);
}

/** `list.color` → `color`; type không phải list thì trả về chính nó. */
export function baseTypeOf(type?: string | null): string {
    if (!type) return '';
    return isListType(type) ? type.slice(LIST_PREFIX.length) : type;
}

export function listTypeOf(baseType: string): string {
    return LIST_PREFIX + baseType;
}

export interface MetafieldLiquidOptions {
    /** boolean */
    trueText?: string;
    falseText?: string;
    /** date & date_time */
    showDate?: boolean;
    dateFormat?: string;
    showTime?: boolean;
    timeFormat?: string;
    showTimeZone?: boolean;
    /** rating */
    ratingStyle?: 'stars' | 'number' | 'both';
    /** file_reference */
    fileDisplay?: 'auto' | 'image' | 'video' | 'link' | 'download';
    imageWidth?: number;
    /** Tắt lazyload cho ảnh nằm trên màn hình đầu (LCP). */
    disableLazyload?: boolean;
    /** Text dự phòng cho link file khi không suy ra được tên file. */
    fileFallbackText?: string;
    /** Chữ merchant tự đặt cho link / button file. Rỗng thì dùng tên file. */
    fileLinkText?: string;
    /** file_reference trỏ tới video của nhóm Media */
    videoControls?: boolean;
    videoAutoplay?: boolean;
    videoLoop?: boolean;
    videoMuted?: boolean;
    /** reference (MF-EL-06) */
    referenceDisplay?: 'title' | 'image' | 'url';
    referenceLink?: boolean;
    /** list.* (MF-EL-06) — marker/indent/số cột do field css lo, không nằm ở đây */
    listLayout?: 'inline' | 'list' | 'grid';
    listSeparator?: string;
    /**
     * metaobject_reference (MF-EL-05): đường đi từ metaobject xuống field lá,
     * ví dụ `['address', 'city']`. Rỗng nghĩa là merchant chưa chọn xong.
     */
    moPath?: string[];
    /** Type của field lá cuối `moPath` — quyết định render ra sao. */
    moLeafType?: string;
    /** class prefix cho markup có style riêng (color swatch, rating) */
    classPrefix?: string;
}

const DEFAULTS: Required<MetafieldLiquidOptions> = {
    trueText: 'Yes',
    falseText: 'No',
    showDate: true,
    dateFormat: '%d/%m/%Y',
    showTime: false,
    timeFormat: '%H:%M',
    showTimeZone: false,
    ratingStyle: 'stars',
    fileDisplay: 'auto',
    imageWidth: 1000,
    disableLazyload: false,
    fileFallbackText: 'File',
    fileLinkText: '',
    videoControls: true,
    videoAutoplay: false,
    videoLoop: false,
    videoMuted: false,
    referenceDisplay: 'title',
    referenceLink: true,
    listLayout: 'inline',
    listSeparator: ', ',
    moPath: [],
    moLeafType: '',
    classPrefix: 'ecom-metafield',
};

/** Escape nháy đơn để chuỗi merchant nhập không phá cú pháp Liquid. */
function q(value: string): string {
    return String(value ?? '').replace(/'/g, "\\'");
}

/**
 * Ghép format strftime từ 5 setting rời (Show date / Date format / Show time /
 * Time format / Show time zone) thay vì một dropdown preset cứng — merchant hiện
 * `date_time` mà chỉ muốn phần ngày thì tắt Show time là xong.
 */
function buildDateFormat(o: Required<MetafieldLiquidOptions>): string {
    const parts: string[] = [];
    if (o.showDate) parts.push(o.dateFormat);
    if (o.showTime) parts.push(o.timeFormat);
    // `%Z` chỉ có nghĩa khi đã có ngày hoặc giờ. Panel ẩn toggle trong trạng thái
    // đó rồi, nhưng page lưu từ trước vẫn có thể mang `show_time_zone: true` — và
    // `visible` dạng function giữ nguyên data khi field bị ẩn.
    if (o.showTimeZone && parts.length) parts.push('%Z');
    // Tắt hết thì vẫn phải ra cái gì đó, nếu không element trông như lỗi.
    return parts.length ? parts.join(' ') : o.dateFormat;
}

function buildRating(v: string, o: Required<MetafieldLiquidOptions>): string {
    const number = `<span class="${o.classPrefix}__rating-number">{{ ${v}.rating }} / {{ ${v}.scale_max }}</span>`;

    if (o.ratingStyle === 'number') return number;

    // ⚠️ CẢ HAI số phải ép về kiểu số.
    //
    // Shopify trả `rating` và `scale_max` dạng CHUỖI ("5.0"). So sánh hay chia
    // với chuỗi thì Liquid nổ `comparison of Integer with String failed`, và
    // Shopify chèn luôn câu lỗi vào giữa thuộc tính `class` lẫn nội dung thẻ.
    // `| round` cho scale (cần Integer để làm range), `| plus: 0` cho rating
    // (giữ phần thập phân — đó là thứ vẽ được nửa sao).
    //
    // Nửa sao vẽ bằng HAI HÀNG SAO CHỒNG NHAU, không phải ký tự nửa sao:
    // Unicode không có glyph nửa sao được font hỗ trợ rộng. Hàng dưới là toàn bộ
    // sao mờ, hàng trên là toàn bộ sao đậm bị `overflow: hidden` cắt theo phần
    // trăm — nên 4.5/5 ra đúng 90% chiều rộng.
    //
    // Dùng CÙNG một glyph ★ cho cả hai hàng (khác `opacity`) thay vì ★ và ☆:
    // hai glyph khác nhau có thể khác chiều rộng tuỳ font, lệch một chút là chỗ
    // cắt không trùng biên sao. `opacity` chứ không phải màu cố định để nó còn
    // đúng trên cả theme nền sáng và nền tối, và vẫn ăn theo màu chữ merchant đặt.
    //
    // Toàn bộ style là inline: element này không có file CSS riêng, nên phải
    // đúng ngay cả khi theme không có một dòng CSS nào cho nó.
    const star = `<span class="${o.classPrefix}__star" aria-hidden="true">&#9733;</span>`;
    const row = `{%- for ecom_mf_i in (1..ecom_mf_scale) -%}${star}{%- endfor -%}`;

    const stars = `{%- assign ecom_mf_scale = ${v}.scale_max | round -%}
{%- assign ecom_mf_rating = ${v}.rating | plus: 0 -%}
{%- if ecom_mf_scale > 0 -%}
{%- assign ecom_mf_pct = ecom_mf_rating | times: 100.0 | divided_by: ecom_mf_scale | round: 2 -%}
{%- if ecom_mf_pct > 100 -%}{%- assign ecom_mf_pct = 100 -%}{%- endif -%}
{%- if ecom_mf_pct < 0 -%}{%- assign ecom_mf_pct = 0 -%}{%- endif -%}
<span class="${o.classPrefix}__rating" role="img" aria-label="{{ ecom_mf_rating }} / {{ ecom_mf_scale }}" style="position: relative; display: inline-block; white-space: nowrap;">
<span class="${o.classPrefix}__rating-track" aria-hidden="true" style="opacity: 0.25;">${row}</span>
<span class="${o.classPrefix}__rating-fill" aria-hidden="true" style="position: absolute; left: 0; top: 0; overflow: hidden; white-space: nowrap; width: {{ ecom_mf_pct }}%;">${row}</span>
</span>
{%- endif -%}`;

    return o.ratingStyle === 'both' ? `${stars} ${number}` : stars;
}

/**
 * Ảnh LUÔN bọc trong wrapper `.ecom-image-default`.
 *
 * Đây là convention của platform, không phải trang trí. Alias style `image`
 * (`plugins/fields/core/alias/image.ts`) trỏ Width và Max width vào chính
 * `.ecom-image-default`, còn Height / Image fit / Border vào thẻ `img` CON của
 * nó. Render thẳng một `<img>` thì `helpers.mixS` cho ra selector không khớp gì
 * cả — 5 control đó vẫn hiện trong panel Design mà bấm không có tác dụng.
 */
function imageTag(
    srcExpr: string,
    altExpr: string,
    o: Required<MetafieldLiquidOptions>
): string {
    // `width`/`height` THẬT để trình duyệt giữ đúng khung trước khi ảnh tải về.
    // Thiếu hai thuộc tính này là nguyên nhân trực tiếp của CLS mà Lighthouse
    // chấm ("image elements do not have explicit width and height"), và mọi
    // element ảnh khác của platform đều có (xem Product/Image.vue).
    //
    // Bọc trong `if` vì `srcExpr` có thể là `generic_file` (PDF, zip) — loại đó
    // không có width/height, in ra sẽ thành `width=""`.
    //
    // `height: auto` trong style là BẮT BUỘC đi kèm: thuộc tính `height` được
    // map thành presentational hint cho CSS `height`, không ghi đè thì ảnh bị
    // bóp méo khi `width: 100%`.
    //
    // KHÔNG dùng `{%-`/`-%}` ở đây: dấu trim ăn luôn khoảng trắng ngăn cách hai
    // attribute, ra `alt="..."width="1200"` — HTML sai.
    const dims = `{% if ${srcExpr}.width %} width="{{ ${srcExpr}.width }}" height="{{ ${srcExpr}.height }}"{% endif %}`;

    // Ảnh metafield thường nằm dưới màn hình đầu nên `lazy` là mặc định đúng;
    // nhưng nếu merchant đặt nó ở trên (badge, size chart cạnh tiêu đề) thì lazy
    // làm chậm LCP — nên có đường tắt, cùng tên setting với các element khác.
    const loading = o.disableLazyload ? 'eager' : 'lazy';

    return `<span class="ecom-image-default ${o.classPrefix}__image-wrapper" style="display: inline-block;">`
        + `<img class="${o.classPrefix}__image" src="{{ ${srcExpr} | image_url: width: ${o.imageWidth} }}" alt="{{ ${altExpr} | escape }}"${dims} loading="${loading}" style="width: 100%; height: auto;" />`
        + `</span>`;
}

/**
 * URL của file KHÔNG lấy được từ một chỗ duy nhất.
 *
 * Bug thật đã gặp trên trang publish: metafield trỏ tới ảnh chọn từ library
 * Shopify thì `.value` là drop `image`, mà drop đó **không có `.url`** — chỉ
 * `generic_file` mới có. Kết quả là `<a href=""></a>`: link rỗng, chữ rỗng.
 *
 *   generic_file (PDF, zip…) → `.url`
 *   image (MediaImage)       → phải qua filter `image_url`
 *   video                    → nằm trong `.sources`
 *
 * Tên biến mang tiền tố `ecom_mf_` để không đụng biến của theme.
 */
function buildFileHref(v: string, o: Required<MetafieldLiquidOptions>): string {
    return `{%- liquid
  case ${v}.media_type
  when 'image'
    assign ecom_mf_href = ${v} | image_url: width: ${o.imageWidth}
  when 'video'
    assign ecom_mf_href = ${v}.sources.first.url
  else
    assign ecom_mf_href = ${v}.url
  endcase
  assign ecom_mf_name = ecom_mf_href | split: '?' | first | split: '/' | last
-%}`;
}

/**
 * Video của nhóm Media.
 *
 * Shopify gộp File / Image / Video vào cùng type `file_reference` — không có type
 * riêng cho video, và `metafieldDefinitions` cũng chỉ trả `type.name`. Chỉ phân
 * biệt được lúc render, qua `media_type` của chính file.
 *
 * `autoplay` bắt buộc kéo theo `muted`: trình duyệt chặn autoplay có tiếng, bật
 * autoplay mà không muted thì video đứng im và merchant tưởng element lỗi.
 */
function buildVideo(v: string, o: Required<MetafieldLiquidOptions>): string {
    const muted = o.videoMuted || o.videoAutoplay;
    const params = [
        `controls: ${o.videoControls ? 'true' : 'false'}`,
        `autoplay: ${o.videoAutoplay ? 'true' : 'false'}`,
        `loop: ${o.videoLoop ? 'true' : 'false'}`,
        `muted: ${muted ? 'true' : 'false'}`,
        `class: '${o.classPrefix}__video-el'`,
    ].join(', ');

    return `<div class="${o.classPrefix}__video">{{ ${v} | video_tag: ${params} }}</div>`;
}

/**
 * `file_reference` có thể trỏ tới MediaImage hoặc GenericFile.
 *
 * Chế độ Ảnh luôn kèm guard `media_type == 'image'`: merchant chọn Ảnh nhưng
 * metafield lại là PDF thì tự rơi về link, không render thẻ img vỡ.
 */
function buildFile(v: string, o: Required<MetafieldLiquidOptions>): string {
    const href = buildFileHref(v, o);

    // Chữ merchant đặt thắng tên file. Không đặt thì lấy tên file, và `default:`
    // là chốt cuối — suy ra tên thất bại thì vẫn phải có chữ để click, nếu không
    // thẻ a rỗng và merchant tưởng element không render gì.
    const name = o.fileLinkText
        ? o.fileLinkText
        : `{{ ecom_mf_name | default: '${q(o.fileFallbackText)}' }}`;

    const link = `<a class="${o.classPrefix}__file" href="{{ ecom_mf_href }}" target="_blank" rel="noopener">${name}</a>`;

    // `target="_blank"` cho cả button: thuộc tính `download` bị trình duyệt BỎ QUA
    // với URL khác origin, mà file Shopify nằm trên cdn.shopify.com — nên thực tế
    // nó mở file. Không mở tab mới thì khách rời hẳn trang sản phẩm.
    // Vẫn giữ `download` vì nó vô hại và sẽ đúng nếu file được serve same-origin.
    const download = `<a class="${o.classPrefix}__file ${o.classPrefix}__file--download" href="{{ ecom_mf_href }}" download="{{ ecom_mf_name }}" target="_blank" rel="noopener">${name}</a>`;
    const image = imageTag(v, `${v}.alt`, o);
    const video = buildVideo(v, o);

    if (o.fileDisplay === 'link') return href + link;
    if (o.fileDisplay === 'download') return href + download;

    // Chế độ cố định vẫn giữ guard: chọn Ảnh mà file là PDF thì rơi về link, chọn
    // Video mà file là ảnh cũng vậy — không bao giờ render thẻ sai loại.
    if (o.fileDisplay === 'image') {
        return href + `{%- if ${v}.media_type == 'image' -%}${image}{%- else -%}${link}{%- endif -%}`;
    }
    if (o.fileDisplay === 'video') {
        return href + `{%- if ${v}.media_type == 'video' -%}${video}{%- else -%}${link}{%- endif -%}`;
    }

    // 'auto': tự nhận theo media_type của file thật. Mặc định, vì nhóm Media của
    // Shopify dùng chung một type — chọn metafield Video thì phải ra player.
    return href
        + `{%- case ${v}.media_type -%}`
        + `{%- when 'image' -%}${image}`
        + `{%- when 'video' -%}${video}`
        + `{%- else -%}${link}`
        + `{%- endcase -%}`;
}

/**
 * Reference: theme Liquid tự resolve resource qua `.value`, không cần query thêm.
 *
 * Link bọc trong `{% if url %}`: resource unpublish khỏi Online Store không có
 * URL công khai, sinh thẻ a trỏ vào chỗ chết là đúng cái edge case 9 cấm.
 */
function buildReference(v: string, type: string, o: Required<MetafieldLiquidOptions>): string {
    const imageField = REFERENCE_IMAGE_FIELD[type];
    let inner: string;

    if (o.referenceDisplay === 'image' && imageField) {
        inner = imageTag(`${v}.${imageField}`, `${v}.title`, o);
    } else if (o.referenceDisplay === 'url') {
        inner = `{{ ${v}.url }}`;
    } else {
        inner = `{{ ${v}.title }}`;
    }

    // Tắt Liên kết là KHÔNG được sinh thẻ a — tiêu chí hoàn thành ghi rõ.
    if (!o.referenceLink) return inner;

    return `{%- if ${v}.url != blank -%}<a class="${o.classPrefix}__reference" href="{{ ${v}.url }}">${inner}</a>{%- else -%}${inner}{%- endif -%}`;
}

/**
 * `metaobject_reference` là container: đi theo `moPath` xuống field lá rồi render
 * field đó theo type của nó.
 *
 * `path.join('.value.')` vì truy cập field của metaobject trả về một metafield
 * drop, phải `.value` nữa mới sang được metaobject tiếp theo:
 *   ['city']          → `D.city`
 *   ['address','city'] → `D.address.value.city`
 */
function buildMetaobject(v: string, o: Required<MetafieldLiquidOptions>): string {
    const path = o.moPath ?? [];
    const leaf = o.moLeafType;

    // Lá lại là metaobject nghĩa là merchant chưa chọn tới đích (hoặc data lỗi) —
    // trả rỗng chứ không đệ quy vô hạn với cùng một `moPath`.
    if (!path.length || !leaf || baseTypeOf(leaf) === 'metaobject_reference') return '';

    const fieldDrop = `${v}.${path.join('.value.')}`;

    // Field của metaobject cũng có thể là list (vd. list.single_line_text_field).
    if (isListType(leaf)) return buildList(fieldDrop, baseTypeOf(leaf), o);

    return renderValue(`${fieldDrop}.value`, leaf, o, fieldDrop);
}

const LIST_ITEMS_VAR = 'ecom_mf_items';
const LIST_ITEM_VAR = 'ecom_mf_item';

/**
 * `list.*` = vòng lặp gọi lại đúng bộ render của type gốc — không có bảng type
 * thứ hai.
 *
 * `| compact` bỏ phần tử nil: reference trỏ tới resource đã xoá trả về nil, không
 * lọc thì list hiện ô trống hoặc separator lơ lửng (edge case 8). Lọc xong mà
 * rỗng thì không render wrapper, tránh `<ul></ul>` trơ trên trang.
 */
function buildList(expr: string, baseType: string, o: Required<MetafieldLiquidOptions>): string {
    const item = renderValue(LIST_ITEM_VAR, baseType, o, LIST_ITEM_VAR);
    if (!item) return '';

    const open = `{%- assign ${LIST_ITEMS_VAR} = ${expr}.value | compact -%}{%- if ${LIST_ITEMS_VAR}.size > 0 -%}`;
    const forOpen = `{%- for ${LIST_ITEM_VAR} in ${LIST_ITEMS_VAR} -%}`;
    const close = `{%- endfor -%}`;
    const end = `{%- endif -%}`;
    const cls = `${o.classPrefix}__list`;

    if (o.listLayout === 'grid') {
        // `display: grid` inline vì không field nào điều khiển nó; số cột và gap
        // do field css lo (responsive theo breakpoint), nên KHÔNG inline hai cái
        // đó — inline style thì CSS của field không ghi đè được.
        return `${open}<div class="${cls} ${cls}--grid" style="display: grid;">${forOpen}<div class="${cls}-item">${item}</div>${close}</div>${end}`;
    }

    if (o.listLayout === 'list') {
        return `${open}<ul class="${cls} ${cls}--bullet">${forOpen}<li class="${cls}-item">${item}</li>${close}</ul>${end}`;
    }

    return `${open}<span class="${cls} ${cls}--inline">${forOpen}${item}{%- unless forloop.last -%}<span class="${cls}-separator">${o.listSeparator}</span>{%- endunless -%}${close}</span>${end}`;
}

/**
 * Render một GIÁ TRỊ đã dereference.
 *
 * `v` là biểu thức trỏ tới giá trị (`…metafields.ns.key.value`, hoặc biến vòng
 * lặp — item của list ĐÃ là giá trị, không `.value` thêm lần nữa). `drop` là
 * metafield drop gốc, chỉ `rich_text_field` cần vì `metafield_tag` nhận cả drop.
 */
function renderValue(
    v: string,
    type: string,
    o: Required<MetafieldLiquidOptions>,
    drop: string
): string {
    if (isMeasurementType(type)) {
        return `{{ ${v}.value }} {{ ${v}.unit }}`;
    }

    if (isReferenceType(type)) {
        return buildReference(v, type, o);
    }

    switch (type) {
        case 'single_line_text_field':
        case 'number_integer':
        case 'number_decimal':
        case 'id':
            return `{{ ${v} }}`;

        case 'multi_line_text_field':
            return `{{ ${v} | newline_to_br }}`;

        case 'json':
            return `{{ ${v} | json }}`;

        case 'boolean':
            return `{% if ${v} %}${o.trueText}{% else %}${o.falseText}{% endif %}`;

        case 'date':
        case 'date_time':
            return `{{ ${v} | date: '${q(buildDateFormat(o))}' }}`;

        case 'money':
            return `{{ ${v} | money }}`;

        case 'rating':
            return buildRating(v, o);

        case 'rich_text_field':
            // `metafield_tag` nhận chính metafield drop, KHÔNG phải `.value`:
            // `.value` của rich text là cây JSON, in ra sẽ thành chuỗi thô.
            return `{{ ${drop} | metafield_tag }}`;

        case 'file_reference':
            return buildFile(v, o);

        case 'metaobject_reference':
            return buildMetaobject(v, o);

        case 'color':
            // Kích thước inline: không có CSS thì <span> rỗng sẽ cao 0px và merchant
            // tưởng metafield không có giá trị. Style group vẫn ghi đè được.
            return `<span class="${o.classPrefix}__swatch" title="{{ ${v} }}" style="background-color: {{ ${v} }}; display: inline-block; width: 24px; height: 24px; border-radius: 4px; vertical-align: middle;"></span>`;

        case 'url':
            return `<a class="${o.classPrefix}__link" href="{{ ${v} }}" target="_blank" rel="noopener">{{ ${v} }}</a>`;

        case 'link':
            return `<a class="${o.classPrefix}__link" href="{{ ${v}.url }}">{{ ${v}.text }}</a>`;

        default:
            return '';
    }
}

/**
 * Trả về Liquid hiển thị metafield, hoặc chuỗi rỗng nếu type chưa hỗ trợ.
 *
 * Chuỗi rỗng là tín hiệu để caller quyết định (hiện placeholder trong builder,
 * bỏ qua khi export) — KHÔNG tự sinh markup rác cho type lạ.
 */
export function buildMetafieldLiquid(
    expr: string,
    type?: string | null,
    options: MetafieldLiquidOptions = {}
): string {
    if (!expr || !type) return '';

    const o = { ...DEFAULTS, ...options } as Required<MetafieldLiquidOptions>;

    if (isListType(type)) {
        return buildList(expr, baseTypeOf(type), o);
    }

    return renderValue(`${expr}.value`, type, o, expr);
}

/**
 * Bọc output bằng `{% if %}` để trang thật không render gì khi metafield rỗng.
 *
 * Dùng ở MỌI mode: builder cũng render đoạn Liquid này (SSR qua storefront thật)
 * nên phải bọc thì bản xem trước mới khớp trang publish. Bọc xong mà rỗng thì
 * element không còn chỗ để click — `showPlaceholder` của element chịu phần đó.
 */
export function wrapEmptyState(
    expr: string,
    inner: string,
    fallbackText: string = ''
): string {
    if (!inner) return '';
    const fallback = fallbackText ? fallbackText : '';
    return `{%- if ${expr} != blank and ${expr}.value != blank -%}${inner}{%- else -%}${fallback}{%- endif -%}`;
}
