// Helper function để fetch stock image
export async function fetchStockImage(altText: string): Promise<any> {
    const searchUrl = 'https://burst.shopify.com/tools/stock-photos/api/photos/search?limit=1&q=' + encodeURIComponent(altText || '');

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10s timeout

    try {
        const response = await fetch(window.route('builder.bridge', {
            url: searchUrl,
        }), { signal: controller.signal });
        clearTimeout(timeoutId);
        return await response.json();
    } catch (error) {
        clearTimeout(timeoutId);
        console.warn('Stock photo search error:', error);
        return {
            status: 'error',
            message: 'Failed to fetch stock photo'
        };
    }
}

// AI Feedback helpers
export async function createFeedbackLog(payload: Record<string, any>): Promise<string | null> {
    try {
        const routeUrl = window.route('ai.feedback.store');
        const response = await fetch(routeUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ...payload, status: 'pending' })
        });
        const json = await response.json();
        if (json.success && json.log_id) {
            return json.log_id;
        }
    } catch (e) {
        console.error('[AI-Feedback] createFeedbackLog ERROR:', e);
    }
    return null;
}

export async function updateFeedbackStatus(logId: string, status: string, feedback: { rating?: number | null, comment?: string } = {}): Promise<void> {
    if (!logId) return;
    try {
        const routeUrl = window.route('ai.feedback.update', { id: logId });
        const payload: Record<string, any> = { feedback };
        if (status) payload.status = status;
        await fetch(routeUrl, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
    } catch (e) {
        console.error('[AI-Feedback] updateFeedbackStatus ERROR:', e);
    }
}

