        javascript() {
            return function () {
                // Nút pause autoplay (WCAG 2.2.2). Đọc $container.swiper lúc click
                // nên không phụ thuộc thứ tự init của slider bên dưới.
                var $ecomAptg = this.$el && this.$el.querySelector('.ecom-swiper-autoplay-toggle');
                if ($ecomAptg && !$ecomAptg.getAttribute('data-ecom-bound')) {
                    $ecomAptg.setAttribute('data-ecom-bound', '1');
                    var $ecomAptgBox = this.$el.querySelector('.ecom-swiper-container');
                    $ecomAptg.addEventListener('click', function () {
                        var sw = $ecomAptgBox && $ecomAptgBox.swiper;
                        if (!sw || !sw.autoplay) return;
                        if (sw.autoplay.running) {
                            // stop() chứ không pause(): pause() sẽ bị resume() của
                            // pauseOnMouseEnter bật lại, người dùng bấm dừng phải dừng hẳn.
                            sw.autoplay.stop();
                            $ecomAptg.setAttribute('data-state', 'paused');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-play'));
                        } else {
                            sw.autoplay.start();
                            $ecomAptg.setAttribute('data-state', 'playing');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-pause'));
                        }
                    });
                }
                const $el = this.$el;
                const $container = $el.querySelector('.ecom-lookbook-container');
                if(!$el || !$container) return;
                const settings = this.settings;

                const _initLookbook = function() {
                if(!(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function')) {
                    let _r = 0;
                    const _t = setInterval(function() {
                        _r++;
                        if(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function') { clearInterval(_t); _initLookbook(); }
                        else if(_r >= 20) clearInterval(_t);
                    }, 200);
                    return;
                }
                const Ecom = (function () {
                    let optionSwiper = window.EComposer.buildSwiperConfig(settings);
                    optionSwiper.pagination = {
                        el: $el.querySelector(".ecom-swiper-pagination"),
                        type: "bullets",
                        clickable: true
                    };
                    optionSwiper.navigation = {
                        nextEl: $el.querySelector(".ecom-swiper-button-next"),
                        prevEl: $el.querySelector(".ecom-swiper-button-prev")
                    };
                    optionSwiper.spaceBetween = 30;
                    // new window.EComSwiper($container, optionSwiper);

                    let ecomSlider = new window.EComSwiper($container, optionSwiper);

                    function ecomSliderInit() {
                        ecomSlider.init(); // Gọi phương thức init() để khởi tạo swiper
                    }

                    function gotoSlide(index) {
                        ecomSlider.slideTo(index, 300);
                    }

                    let gotoItem = function () {
                        let elements = $el.querySelectorAll('.goto-element-item');
                        for (let index = 0; index < elements.length; index++) {
                            const element = elements[index];
                            const indexDot = element.getAttribute('data-index');
                            element.addEventListener("click", function () {
                                gotoSlide(indexDot);
                            });
                        }
                    }

                    let setActiveLookBook = function() {
                        let elements = $el.querySelectorAll('.goto-element-item');
                        ecomSlider.on('slideChange', function () {
                            for (let index = 0; index < elements.length; index++) {
                                const element = elements[index];
                                const indexDot = element.getAttribute('data-index');
                                if(ecomSlider.activeIndex == indexDot){
                                    element.classList.add('ecom-box-active');
                                }else{
                                    element.classList.remove('ecom-box-active');
                                }
                            }
                        });
                    }

                    return {
                        ecomSliderInit: ecomSliderInit,
                        gotoItem: gotoItem,
                        setActiveLookBook: setActiveLookBook,
                    }
                })();

                if (window.EComSwiper) {
                    Ecom.ecomSliderInit();
                    Ecom.gotoItem();
                    Ecom.setActiveLookBook();
                }
                }; // end _initLookbook
                _initLookbook();

            }
        },

