        },
        lookBook() {
            return this.data.settings;
        },
        image() {
            if(!this.data.settings){
                return
            }
            let { image = {}, size, size_custom } = this.data.settings;
            if (Object.keys(image).length === 0) {
                return null;
            }
            if (size === 'custom') {
                size = size_custom;
            }
            else if(size) {
                size = {width: size.split('x')[0], height: size.split('x')[1]};
            }

            return {
                alt: image.alt || image.name,
                ...Object.keys(image)
                    .filter((k) => k.startsWith('value'))
                    .reduce((acc, cur) => {
                        acc[cur] = this.$helpers.resizeImage(image[cur], size);
                        return acc;
                    }, {}),
            };
        },
        screens() {
            return this.$store.getters['builder/screens'];
        },
        localPoint() {
          // focal point
          let style = {};
          let { image = {} } = this.data.settings;
          if (Object.keys(image).length === 0) {
              return null;
          }
          if(image?.left && image?.top) {
            style['object-position'] = `${image?.left}% ${image?.top}%`;
          }
          return style;
          // end focal point
        },
        imageLookbook() {
            return this.data.settings;
        },
        isCaption() {
            return this.data.settings?.use_caption && this.data.settings?.caption;
        },
        optionSwiper() {
            return this.$helpers.optionSwiper(this.data.settings);
        },
        canMultipleLanguages() {
            return this.getPermission('translates',false);
        },
        getUser() {
            return this.$store.getters['global/user']
        },
        productSource() {
            const items = this.data?.settings?.items || [];
            const handles = this.productHandles || [];

            if (handles.length) {
                return {
                    type: 'products_batch',
                    handles,
                    limit: 20
                };
            }

            return {
                type: 'sample_products',
                limit: Math.min(items.length || 1, 20)
            };
        },
        liquids() {
            return {
                product_items: {
                    code: `
                        {%- assign tmp_product = product -%}
                        {%- assign is_product_object = false -%}
                        {%- if EComClientRender -%}
                            {%- assign is_product_object = true -%}
                        {%- else -%}
                            {% assign productsDefault = collections.all.products %}
                            ${this.data.settings.items ? `
                                {% capture product_handles %} ${this.data.settings.items.map((item, index)=>{
                                    if(item?.product?.value){
                                        return item?.product?.value;
                                    }else{
                                        return `{% if productsDefault.size >= ${this.data.settings.items.length} %}{{ productsDefault[${index}].handle }}{% endif %}`
                                    }
                                }).join(',')} 
                            {% endcapture%}
                            {% assign products = product_handles | strip | split: ',' %}
                        {%- endif -%}
                            {% for p in products %}
                                {%- if is_product_object -%}
                                    {%- assign product = p -%}
                                {%- else -%}
                                    {% assign product = all_products[p]%}
                                {%- endif -%}
                                <div class="ecom-product-item ecom-swiper-slide" data-product_handles="{{ product_handles }}" >
                                    <div class="ecom-pr ecom-w__full ecom-lookbook__product-media">
                                        <div class="ecom-lookbook__product-media-wrap">
                                            {%- if product.featured_media -%}
                                                <img srcset="
                                                    {%- if product.featured_media.width >= 533 -%}{{ product.featured_media | image_url: width: 533 }} 533w,{%- endif -%}
                                                    {%- if product.featured_media.width >= 720 -%}{{ product.featured_media | image_url: width: 720 }} 720w,{%- endif -%}
                                                    {%- if product.featured_media.width >= 940 -%}{{ product.featured_media | image_url: width: 940 }} 940w,{%- endif -%}
                                                    {%- if product.featured_media.width >= 1066 -%}{{ product.featured_media | image_url: width: 1066 }} 1066w{%- endif -%}"
                                                    src="{{ product.featured_media | image_url: width: 533 }}"
                                                    sizes="(min-width: 1100px) 535px, (min-width: 750px) calc((100vw - 130px) / 2), calc((100vw - 50px) / 2)"
                                                    alt="{{ product.featured_media.alt | escape }}"
                                                    loading='lazy'
                                                    class="ecom-lookbook__product-media-image ecom-w__full"
                                                    width="{{ product.featured_media.width }}"
                                                    height="{{ product.featured_media.height }}"
                                                />
                                            {%- else -%}
                                                {{ 'product-1' | placeholder_svg_tag: 'ecom-lookbook__product-media-image ecom-lookbook__product-media-placeholder ecom-w__full' }}
                                            {%- endif -%}
                                        </div>
                                        ${this.product_info_snippet('onImage')}
                                    </div>
                                    <div style="display: flex; flex-wrap: wrap;">
                                        ${this.product_info_snippet('normal')}
                                    </div>
                                </div>
                            {% endfor %}
                        ` : '' }
                        {%- assign product = tmp_product -%}
                    `
                }
            };
        },
        products() {
            return this.data;
        },
        isNavigation() {
            return (
                this.data.settings?.slider_navigation_layout
            );
        },
        isCombined() {
            let navigator = this.data?.settings?.slider_navigation_layout;
            return navigator === "neo_full"  ? "combine" : "classic";
        },

        icon() {
            return this.data.settings?.icon;
        },
        layout() {
            return this.data && this.data.settings && "layout" in this.data.settings
                ? this.data.settings.layout
                : "grid";
        },
        show_description() {
            return (
                this.data &&
                this.data.settings &&
                "show_description" in this.data.settings &&
                this.data.settings.show_description === true
            );
        },
        short_limit() {
            return this.data &&
                this.data.settings &&
                "limit_short_description" in this.data.settings
                ? this.data.settings.limit_short_description
                : 10;
        },
        show_picker() {
            return this.data && this.data.settings && "show_picker" in this.data.settings
                ? this.data.settings.show_picker === "show"
                : false;
        },
        swatch_type() {
            let type =
                this.data && this.data.settings && "type" in this.data.settings
                    ? this.data.settings.type
                    : "dropdown";

            if (
                ["image", "color", "radio"].includes(type) &&
                this.data &&
                this.data.settings &&
                "option" in this.data.settings &&
                this.data.settings.option
            ) {
                return type;
            }
            return "dropdown";
        },
        option_layout() {
            return this.data &&
                this.data.settings &&
                "option_layout" in this.data.settings &&
                this.data.settings.option_layout
                ? this.data.settings.option_layout
                : "dropdown";
        },
        show_product_quickview() {
            return this.data?.settings?.show_product_quickview;
        },
        show_product_wishlist() {
            return this.data?.settings?.show_product_wishlist ?? false;
        },
        requestShopifyType() {
            let requires = ["collection"];
            if (this.data.template && requires.includes(this.data.template)) {
                return {
                    shopify_type: this.data.template
                };
            }
            return {};
        },
        badge_tags() {
            return this.getSetting('badges')?.settings?.badge_tags ?? "".split("\n").join(",");
        },
        sliderNav(){
            let position = this.data.settings?.navigation_position;
            // Field navigation_position is responsive, so the position must be resolved per screen
            // (inline `position` would leak the desktop value into tablet/mobile).
            let toPosition = (value) => (value || position) !== 'center' ? 'unset' : 'absolute';
            return {
                '--ecom-position': toPosition(position),
                '--ecom-position__tablet': toPosition(this.data.settings?.navigation_position__tablet),
                '--ecom-position__mobile': toPosition(this.data.settings?.navigation_position__mobile)
            }
        },
        optionSwiper() {
            return this.$helpers.optionSwiper(this.data.settings);
        },

        show_all() {
            return this.active_child_elenent === true;
        },

        title_snippet(){
            return `
                ${this.check('title') ? `
                    <${this.getSetting('title')?.settings?.title_tag ?? 'h3'} class="ecom-lookbook__product-title-tag">
                        <a
                            href="{{- product.url -}}"
                            title="{{product.title | escape }}"
                            target="${this.data.settings?.open_new_tab ? '_blank' : ''}"
                            class="ecom-lookbook__product-item-information-title ${this.getSetting('title')?.settings?.title_one_row ? "ecom-title-one-row" : ''}"
                        >
                            {{ product.title }}
                        </a>
                    </${this.getSetting('title')?.settings?.title_tag ?? 'h3'}>
                ` : ""}
            `
        },

        description_snippet(){
            return `
                ${this.check('description') ? `
                    <div class="ecom-lookbook__product-description">
                        {{ product.description | strip_html | replace: '\u00A0', ' ' | truncatewords: ${this.getSetting('description')?.settings?.limit_short_description !== undefined ? this.getSetting('description')?.settings?.limit_short_description : 50} }}
                    </div>
                ` : `` }
            `
        },

        vendor_snippet(){
            return `
                ${this.check('vendor') ? `
                    {% if product.vendor and product.vendor != blank %}
                    <div class="ecom-lookbook__product-item-vendor-element">
                        <span class="ecom-visually-hidden">${this.lang(this.getSetting('vendor').settings?.vendor_title, "vendor")}</span>
                        <span class="ecom-lookbook__product-item-vendor">{{  product.vendor | link_to_vendor}}</span>
                    </div>
                    {% endif %}
                ` : "" }
            `;
        },

        sku_snippet(){
            return `
                ${this.check('SKU') ? `
                    {% assign current_variant = product.selected_or_first_available_variant %}
                    {% if current_variant.sku and current_variant.sku != blank %}
                    <div class="ecom-lookbook__product-item-sku-element">
                        <span class="ecom-lookbook__product-item-sku-title">${this.lang(this.getSetting('SKU')?.settings?.sku_title, "sku")}</span>
                        <span class="ecom-lookbook__product-item-sku">{{ current_variant.sku }}</span>
                    </div>
                    {% endif %}
                ` : "" }
            `;
        },

        type_snippet(){
            return `
                ${this.check('type')? `
                    {% if product.type and product.type != blank%}
                        <div class="ecom-lookbook__product-item-type-element">
                            <span class="ecom-visually-hidden">${this.lang(this.getSetting('type')?.settings?.type_title,"product_type")}</span>
                            <span class="ecom-lookbook__product-item-type">{{ product.type | link_to_type }}</span>
                        </div>
                    {% endif %}
                ` : "" }
            `;
        },

        price_snippet(){
            return `
                ${this.check('product_price') ? `
                    <div class="ecom-lookbook__product-price-wrapper">
                        {%- if product.has_only_default_variant == false -%}
                        ${this.getSetting('product_price').settings?.price_from_text ?
                            `<span class="ecom-lookbook__product-price--from">
                                ${this.lang(this.getSetting('product_price')?.settings?.price_from_text,"price_from")}
                            </span>`
                            :``
                        }
                        {% endif %}
                        <span class="ecom-lookbook__product-price{% if product.compare_at_price_min > product.price_min %} ecom-lookbook__product-price--sale{% endif %}">
                            {{ product.price_min| money }}
                        </span>
                        <span class="ecom-lookbook__product-price--regular ecom-lookbook__product--compare-at-price" {%- if product.compare_at_price == nil or product.compare_at_price <=  product.price -%}  style="display:none" {% endif %}>
                            {{ product.compare_at_price_min | money }}
                        </span>
                    </div>
                ` : "" }
            `
        },

        quickview_snippet(){
            return `
                ${this.check('show_quickview') ? `
                    {%- assign quickview_app = shop.metafields.ecomposer.app_quickview.value -%}
                    <div class="ecom-lookbook__product--quickview-wrapper" data-quickview-app="{{quickview_app}}">
                        {%- if quickview_app -%}
                            {% case quickview_app %}
                                {% when 'intergrated' %}
                                    <a href="{{ product.url }}" title="{{ product.title }}" class="ecom-product-quickview" data-handle="{{product.handle}}" data-id="{{product.id}}">
                                    ${this.getSetting('show_quickview')?.settings?.quickview_icon ?? ""}
                                    <span class="ecom-product-quickview--text">
                                        ${this.getSetting('show_quickview')?.settings?.quickview_text ?? ""}
                                    </span>
                                    </a>
                            {% endcase %}
                        {% endif %}
                    </div>
                ` : ""}
            `;
        },

        wishlist_sippnet(){
            return `
                ${this.show_product_wishlist ? `
                    {%- assign wishlist_app = shop.metafields.ecomposer.app_wishlist.value -%}
                    <div class="ecom-lookbook__product--wishlist-wrapper" data-wishlist-app="{{wishlist_app}}">
                        {%- if wishlist_app -%}
                            {% case wishlist_app %}
                                {%- when 'swym-relay'-%}
                                    {% capture  ecom_swym_snippet%}{% include 'swym-product-view', product: product %}{% endcapture%}
                                    {% unless ecom_swym_snippet contains 'Liquid error' %}
                                        {{ ecom_swym_snippet }}
                                    {% else %}
                                        ${ !this.exporting ? `<a onClick="window.open('https://swym.it/help/adding-the-swym-product-view-snippet-to-your-shopify-theme/')" target="_blank" title="Documentation">Wishlit not integrated. Please follow this document to integrate</a>` : "" }
                                    {% endunless%}
                                    <button class="swym-button swym-add-to-wishlist-view-product product_{{product.id}} ecom-lookbook__product-wishlist-button" ${this.exporting ? "" : 'style="display:block;"'} data-swaction="addToWishlist" data-product-id="{{product.id | json}}"></button>
                                {% when 'wishlist-hero' %}
                                    {% capture the_hero_wishlist_snippet %}
                                        {% render 'wishlisthero-collection-product', product: product %}
                                    {% endcapture %}
                                    {% unless the_hero_wishlist_snippet contains 'Liquid error' %}
                                        {{ the_hero_wishlist_snippet }}
                                    {% endunless %}
                                {% when 'wishlist-wishify' %}
                                    {% capture the_wishify_wishlist_snippet %}
                                        {% render 'ZooomyListWishlistColl', product: product %}
                                    {% endcapture %}
                                    {% unless the_wishify_wishlist_snippet contains 'Liquid error' %}
                                        {{ the_wishify_wishlist_snippet }}
                                    {% endunless %}
                                {% when 'growave' %}
                                    <div
                                        class="gw-add-to-wishlist-product-card-placeholder"
                                        data-gw-product-id="{{product.id}}"
                                        data-gw-variant-id="{{product.id}}"
                                        data-gw-wishlist-counter-position="left-top"
                                        style="display: block"
                                    ></div>
                                {% else %}
                            {% endcase %}
                        {% endif%}
                    </div>
                ` : ``}
            `
        },

        sale_badge_snippet(){
            return `
                ${this.check('sale_badge') ? `
                    {%- if product.has_only_default_variant -%}
                        {%- if product.compare_at_price_min > product.price_min -%}
                            <div class="ecom-lookbook__product-price--bage-sale">
                                ${this.getSetting('sale_badge')?.settings?.sale_badge_type =="amount"
                                        ? `{%- assign sale = product.compare_at_price_min | minus: product.price_min | money -%}`
                                        : `{%- assign sale = product.compare_at_price_min | minus: product.price_min | times: 100.0 | divided_by: product.compare_at_price_min | round -%}`
                                }
                                <span>
                                    ${this.lang(this.getSetting('sale_badge').settings?.bage_sale,"sale_badge",{ sale: "sale" })}
                                </span>
                            </div>
                        {%- endif -%}
                    {%- else -%}
                        {%- if product.compare_at_price_min > product.price_min -%}
                            <div class="ecom-lookbook__product-price--bage-sale">
                                ${this.getSetting('sale_badge').settings?.sale_badge_type =="amount"
                                        ? `{%- assign sale = product.compare_at_price_min | minus: product.price_min | money -%}`
                                        : `{%- assign sale = product.compare_at_price_min | minus: product.price_min | times: 100.0 | divided_by: product.compare_at_price_min | round -%}`
                                }
                                <span>
