    watch: {
        'data.settings.items': {
            handler(newVal) {
                if (this._debouncedProductsTimmer) {
                    clearTimeout(this._debouncedProductsTimmer);
                }
                this._debouncedProductsTimmer = setTimeout(() => {
                    const handles = (newVal || [])
                        .map((item) => item?.product?.value)
                        .filter(Boolean);
                    if (handles.join(',') !== this.productHandles.join(',')) {
                        this.productHandles = handles;
                    }
                }, 500);
            },
            deep: true
        }
    },
    beforeUnmount() {
        if (this._debouncedProductsTimmer) {
            clearTimeout(this._debouncedProductsTimmer);
            this._debouncedProductsTimmer = null;
        }
    },
    methods: {
        async lookbookCsrProducts() {
            const items = this.data?.settings?.items || [];
            if (!items.length) return [];

            const loaded = new Map(
                (this.csrProducts || [])
                    .filter((product) => product?.handle)
                    .map((product) => [product.handle, product])
            );

            let defaults = [];
            if (items.some((item) => !item?.product?.value)) {
                try {
                    // Cùng cache key với sample_products mixin đã tải (limit bị chuẩn hoá
                    // trong ShopifyDataService) nên không phát sinh request mới.
                    defaults = await this.$shopifyData.getProducts({
                        type: 'sample_products',
                        limit: items.length
                    }) || [];
                } catch {
                    defaults = [];
                }
            }

            return items.map((item, index) => {
                const handle = item?.product?.value;
                return (handle ? loaded.get(handle) : defaults[index]) || null;
            });
        },
        async buildLiquidContext() {
            const context = await CollectionProductCSR.methods.buildLiquidContext.call(this);
            context.products = await this.lookbookCsrProducts();
            return context;
        },
