        setEditingElement(i) {
            this.$store.commit('builder/setEditingElement', this);
            if( !('tabOpened' in this.data.settings.items))
            {
                Object.defineProperty( this.data.settings.items, "tabOpened", { enumerable: false, writable: true } );

            }
            this.data.settings.items.tabOpened = i;
        },
        mouseDown(e, i) {
            if (this.exporting) {
                return;
            }
            let $target = e.target.closest('.element__image-lookbook--text');
            // $targetRoot = $target.getBoundingClientRect();
            this.drag.currentEl = $target;
            this.drag.i = i;
            this.idoc().onmousemove = this.onMouseMove;
            this.idoc().onmouseup = this.onMouseUp;
        },

        onMouseUp() {
            this.idoc().onmousemove = null;
            this.idoc().body.style.userSelect = '';
            this.idoc().body.style.cursor = '';
            let { i, x, y } = this.drag;
            if (i > -1 && this.drag.started) {
                this.lookBook.items[i].horizontalPosition = x;
                this.lookBook.items[i].verticalPosition = y;
            }
            Object.assign(this.drag, {
                x: -1,
                y: -1,
                i: -1,
                started: false
            });
        },

        onMouseMove(e) {
            let $root = this.$el.querySelector('.element__image-lookbook'),
                rectRoot = $root.getBoundingClientRect();
            let x = Math.round(((e.x - rectRoot.left) / rectRoot.width) * 100),
                y = Math.round(((e.y - rectRoot.top) / rectRoot.height) * 100);
            if (Math.abs(x) > 5 || Math.abs(y) > 5) {
                this.idoc().body.style.userSelect = 'none';
                this.idoc().body.style.cursor = 'move';
                x = Math.max(0, Math.min(100, x));
                y = Math.max(0, Math.min(100, y));
                this.drag.started = true;
                this.drag.x = x;
                this.drag.y = y;
                this.drag.currentEl.style.left = x + '%';
                this.drag.currentEl.style.top = y + '%';
            }
        },
        checkLabelLookbooks(){
            return this.data.settings.items?.some((x) => x.isShowLabel && x.lookbookLabel);
        },
        convertImageCard(item) {
            if(!item){
                return
            }
            let { thumbnailCard = {}, product, source = 'custom'} = item;
            if ((source === 'custom' && Object.keys(thumbnailCard).length === 0) ||
                (source === 'product') && !product) {
                return null;
            }
            return {
                alt: thumbnailCard.alt || thumbnailCard.name,
                src: (source === 'custom' ? thumbnailCard?.value : product?.thumbnail) || 'images/placeholder.png'
            };
        },

        isArrow() {
            return ['neo_full','navigation','classic_full'].includes(this.data.settings?.slider_navigation_layout)
        },

        isPagination() {
            return ['neo_full','classic_full','pagination'].includes(this.data.settings?.slider_navigation_layout);
        },

        check(val){
            return this.data.settings.informations && this.data.settings.informations.some(item => item.type == val);
        },

        getSetting(type){
            if(!this.data.settings.informations){
                return;
            }
            return this.data.settings.informations.find(item => item.type == type);
        },
        product_info_snippet(position){
            let title_snippet = this.title_snippet;
            let description_snippet = this.description_snippet;
            let vendor_snippet = this.vendor_snippet;
            let sku_snippet = this.sku_snippet;
            let type_snippet = this.type_snippet;
            let price_snippet = this.price_snippet;
            let quickview_snippet = this.quickview_snippet;
            let sale_badge_snippet = this.sale_badge_snippet;
            let badges_snippet = this.badges_snippet;
            let review_snippet = this.review_snippet;

            let product_info = this.data.settings.informations;
            let liquidArray = [];
            if(product_info){
                for (let index = 0; index < product_info.length; index++) {
                    const element = product_info[index];
                    switch (element.type) {
                        case 'title':
                            liquidArray.push({ html: title_snippet, position: this.getSetting('title')?.settings?.show_on_image})
                            break;
                        case 'description':
                            liquidArray.push({ html: description_snippet, position: this.getSetting('description')?.settings?.show_on_image})
                            break;
                        case 'vendor':
                            liquidArray.push({ html: vendor_snippet, position: this.getSetting('vendor')?.settings?.show_on_image})
                            break;
                        case 'SKU':
                            liquidArray.push({ html: sku_snippet, position: this.getSetting('SKU')?.settings?.show_on_image})
                            break;
                        case 'type':
                            liquidArray.push({ html: type_snippet, position: this.getSetting('type')?.settings?.show_on_image})
                            break;
                        case 'product_price':
                            liquidArray.push({ html: price_snippet, position: this.getSetting('product_price')?.settings?.show_on_image})
                            break;
                        case 'show_quickview':
                            liquidArray.push({ html: quickview_snippet, position: this.getSetting('show_quickview')?.settings?.show_on_image})
                            break;
                        case 'sale_badge':
                            liquidArray.push({ html: sale_badge_snippet, position: this.getSetting('sale_badge')?.settings?.show_on_image})
                            break;
                        case 'badges':
                            liquidArray.push({ html: badges_snippet, position: this.getSetting('badges')?.settings?.show_on_image})
                            break;
                        case 'review':
                            liquidArray.push({ html: review_snippet, position: this.getSetting('review')?.settings?.show_on_image})
                            break;
                        default:
                            break;
                    }
                }
            }

            if(liquidArray.length){
                if(position === 'onImage'){
                    let output = ''
                    for (let index = 0; index < liquidArray.length; index++) {
                        const element = liquidArray[index];
                        if(element.position)output += element.html;
                    }
                    return output
                }else{
                    let output = ''
                    for (let index = 0; index < liquidArray.length; index++) {
                        const element = liquidArray[index];
                        if(!element.position)output += element.html;
                    }
                    return output
                }
            }else{
                return ``;
            }
        },
    }
