const getOptionsGrid = (data) => {
    let layouts = null;
    const element = elements.find((el) => el.name == data.name);
    if (element) {
        layouts = element.layouts;
    }
    return {
        layouts: JSON.parse(JSON.stringify(layouts)),
        options: layouts ? layouts.options : null
    };
};
const elementIframe = ["video", "gmap", "row", "flexContainer"];
export { getOptionsGrid, elementIframe };
