import { store } from '@/store';
import { createApp } from 'vue';
import BlocksCore from '@/components/Builder/Components/Core/Layout/Blocks.vue';
import RowCore from '@/components/Builder/Components/Core/Layout/Row.vue';
import ColumnCore from '@/components/Builder/Components/Core/Layout/Column.vue';
import ThemeExtension from '@/components/atomics/ThemeExtension.vue';
import Icon from '@/components/atomics/Icon.vue';
import SectionElementCore from '@/components/Builder/Components/Core/Layout/Section.vue';
import { vendors } from '@/constants';
import { allComponents, minifyCss, minifyHTML, moveTopMediaCss, parseSectionCss, removeCssInData, removeEmptyKeyObj } from '@/utils/helpers';
import { i18n } from '../plugins/i18n';
import createInstanceStore from '@/utils/instance-store';
import { eventBus } from '@/utils';
// import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome'
const url = window.location.origin;

const doExport = (flag) => {
    const instanceStore = createInstanceStore()
    let instance = createApp({
        provide: {
            exporting: flag,
            instanceStore: instanceStore,
            eventBus: eventBus
        },
        computed: {
            sections() {
                return store.getters['page/sections'].filter((sec) => {
                    return sec.visibility !== false;
                });
            }
        },
        mounted() {

        },
        template: `<SectionElement
            v-for="(section, i) in sections"
            :key="section.id"
            :index="i"
            :data="section"
        />`
    }),
    wrp = document.createElement('div');
    instance.use(i18n);
    instance.component('Blocks', BlocksCore);

    instance.component('EcomIcon', Icon);
    instance.component('Row', RowCore);
    instance.component('SectionElement', SectionElementCore);
    // instance.component('ecom-icon',FontAwesomeIcon);
    instance.component('theme-extension', ThemeExtension);
    instance.use(store);

    instance.config.globalProperties.$helpers = store.$helpers;

    instance.mount(wrp);

    const  html =  wrp.innerHTML
        .replace(/"\/images/g, '"'+url+'/images')
        .replace(/(<!--v-if-->| ([\w\d\-_]+?)="\[object Object\]"| data-placeholder="")/g, '')
        .replace(/ contenteditable="[^"]*"| spellcheck="[^"]*"/g, '')
        .replace(/liquid\[\[\]\]/g, '')
        .replaceAll('data-ecom-muted="true"', 'muted')
        .replace(/<div([^>]*)class="ecom-grid-layout core__row--columns"([^>]*)>/g, (match, before, after) => {
            // Lấy section ID từ HTML
            const sectionIdMatch = match.match(/data-section-id="([^"]+)"/);
            const sectionId = sectionIdMatch ? sectionIdMatch[1] : null;
            // Tìm section có ID tương ứng
            const section = store.getters['page/sections'].find(s => s.id === sectionId);
            // Kiểm tra settings
            if (section && section.settings && section.settings['content-width'] === 'full') {
                return `<div${before}class="ecom-grid-layout core__row--columns core__row--full"${after}>`;
            }

            return match;
        })
        .replace(/liquid\[\[([\s\S]+?|)\]\]/g, (...m) => {
            // Decode liquid code in html attributes
            // Vue will break out if attribute value has not been encoded
            // eg: <div class="{{ 1==1 ? "aaa" : "bbb" }}"
            return decodeURIComponent(m[1]);
        })+`<!---This page has been built by EComposer Builder (www.ecomposer.io)--->`;

        instance.unmount();
        wrp.remove();
        instance = null;


    return html;

};

const buildPreview = (expo) => {
    let preview_css = expo.css_global.css+"\n"+expo.css;
    if(expo?.custom?.css) {
        preview_css += "\n"+ expo.custom.css
    }
    let preview_js = expo.js;
    if(expo?.custom?.js) {
        preview_js += "\n"+ expo.custom.js
    }

    preview_css = moveTopMediaCss(preview_css);
    let sections = `<div xid="ecom-builder" class="ecom-builder">
        <div class="ecom-sections">
            ${ expo.preview }
        </div>
    </div>`
    const isPopup = store.getters['page/params'].page === 'popup';
    const settings = store.getters['page/settings'];
    if (isPopup) {
        preview_css += settings?.style_popup ? settings.style_popup : '';
        preview_css += '.ecom-popup-placeholder{position:fixed;z-index:1000000;top:0;left:0;height:auto;width:100%;background-color:#fff}.ecom-popup-placeholder-inner{width:80%;margin:0 auto}.ecom-popup-placeholder-inner img{height:auto;width:100%}';
        preview_js += `\nconst popup = document.querySelector(".ecom-popups-container");
        if(popup) {
            popup.showModal();
        }`;
        const buttonClose = settings?.icon_close ? settings.icon_close : `<svg viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M1 1L9 9M1 9L9 1" stroke="currentColor" stroke-width="2" stroke-linecap="round"
                stroke-linejoin="round" />
        </svg>`;
        const popupPosition = settings?.popup_position ? 'ecom-popup-position-' + settings.popup_position : 'ecom-popup-position-center',
            popupAnimation = settings?.popup_animation ? 'ecom-popup-animation-' + settings.popup_animation : '';
        sections = `
            <dialog class="ecom-popups-container" id="ecom-dialog-${settings.handle || ''}">
                <div class="ecom-popups-wrapper ${popupPosition} ${popupAnimation}">
                    <button class="ecom-popup-close-button">
                        ${buttonClose}
                    </button>
                    <div class="ecom-popups-wrapper-inner">
                        <div xid="ecom-builder" class="ecom-builder">
                            <div class="ecom-sections">
                                ${ expo.preview }
                            </div>
                        </div>
                    </div>
                </div>
            </dialog>
            <div class="ecom-popup-placeholder ecom-section"><div class="ecom-popup-placeholder-inner core__row--columns"><img src="/images/placeholder-popup.jpg" alt="Popup placeholder"></div></div>
        `
    };
    return `
        <${'style'} data-shopify>${window.EComposerBuilder.contentDocument.querySelector('style[data-shopify]')?.innerHTML}</${'style'}>
         <link rel="stylesheet" media="all" href="https://cdn.ecomposer.app/vendors/css/ecom-base.css?v=1.9" />
        ${
            Object.keys(expo.vendors.css)
            .map(name => `<link rel="stylesheet" media="all" href="${ expo.vendors.css[name] }" />`)
            .join("\n")
        }
        <${'style'} type="text/css">${ minifyCss(preview_css) }</${'style'}>
            ${sections}
            ${
                Object.keys(expo.vendors.js)
                .map(name => `<${'script'} type="text/javascript" src="${ expo.vendors.js[name] }"></${'script'}>`)
                .join("\n")
            }
            <${'script'} type="text/javascript" src="${url}/js/ecom-base.js"></${'script'}>
            <${'script'} type="text/javascript">${ preview_js }</${'script'}>

        `;
};

export default function(mode: string | undefined = undefined) {
    store.commit('page/resetLanguages');

    const instanceStore = createInstanceStore();
    window.ECOM_APP_INSTANCE_STORE = instanceStore;
    const allInstances = window.ECOM_APP_INSTANCE_STORE.getAll ? window.ECOM_APP_INSTANCE_STORE.getAll() : new Map();
    return new Promise(async solve=>{
        const activePreset = store.getters['page/activePreset'];
        let expo = {
            ...store.getters['page/dataExport'],
            stats: {
                page: 0,
                sections: [],
                elements: {}
            },
            preview: doExport('preview'),
            output: doExport(true),
            vendors: {
                css: {},
                js: {}
            },
            js: '',
            css: '',
            css_global: {
                data: store.getters['settings/globalCssInit'],
                css: store.getters['settings/cssGlobalCurrentPreset']
            },
            theme_settings: activePreset?.theme_settings ?? store.getters['settings/themeSettings'],
            languages: store.getters['page/languages'],
            created: new Date().getTime()
        },
        alljs = store.getters['page/javascripts'];

        Object.keys(alljs).forEach((name) => {
            let usedsett = {};
            alljs[name].forEach(element => {
                usedsett[element.id] = {};
                element.data.replace(/([^\w\d]+|^)this\??\.settings\??(\.|\[('|"))([\w\d_]*)(\3\])?/g, (...m) => {
                    if (usedsett[element.id][m[4]] === undefined) {
                        usedsett[element.id][m[4]] = element.settings[m[4]];
                    }
                });
                // If the function uses swiper helpers (normalizeSwiperSettings / buildSwiperConfig),
                // those helpers access settings keys internally via a parameter — the regex above
                // cannot detect them. Include all element settings so no keys are missing on live.
                if (/normalizeSwiperSettings|buildSwiperConfig/.test(element.data)) {
                    Object.keys(element.settings).forEach(key => {
                        if (usedsett[element.id][key] === undefined) {
                            usedsett[element.id][key] = element.settings[key];
                        }
                    });
                }
            })

            expo.js += `
                (function(){
                    const Func = (function() {
                        ${ alljs[name][0].data }

                    });
                    ${ alljs[name].map(element => `
                        document.querySelectorAll('.${element.id}').forEach(function(el){
                            Func.call({$el: el, id: '${element.id}', settings: ${ JSON.stringify(usedsett[element.id]) },isLive: ${mode ? `"${mode}"` : true}});
                        });
                    `).join('')}

                })();
            `;
        });
        Object.values(instanceStore.get('cssBases') ?? {}).forEach(cssBase => {
            expo.css += (typeof cssBase === 'object' ?  Object.values(cssBase).join(`\n`) : cssBase);
        });
        expo.css += '\n';
        await store.dispatch('page/initSectionCss');
        let sectionCss = instanceStore.get('sectionCss') ?? {};
        Object.keys(sectionCss).forEach((sid) => {
            expo.css += parseSectionCss(sectionCss[sid]) + '\n';
        });
        expo.css = moveTopMediaCss(expo.css);


        if(expo.sections) {
            expo.sections = JSON.parse(JSON.stringify(expo.sections));
            expo.sections = removeCssInData(expo.sections);
            expo.sections = removeEmptyKeyObj(expo.sections);
            //Fix add section but don't have any content
            expo.sections = expo.sections.filter(s=>{
                return s?.columns?.length || s?.blocks?.length || s?.name === 'flexContainer';
            })
            expo.sections = expo.sections.map((sec) => {
                if (sec.name == 'flexContainer' && !sec.blocks) {
                    sec.blocks = [];
                }
                return sec
            });
            /*Getting stats from library*/
            let statelm = (elms) => {
                if (
                    elms &&
                    elms?.constructor == Array
                ) {
                    elms.forEach((elm) => {
                        if (elm?.row?.columns && Array.isArray(elm.row.columns)) {
                            elm.row.columns.forEach((col) => {
                                statelm(col.blocks);
                            });
                        }
                        else if(elm.blocks && Array.isArray(elm.blocks)) {
                            // Count this element first (FlexContainer, Tabs, Accordion, Slider, etc.)
                            if (elm.name && elm.name != 'row') {
                                if (!expo.stats.elements[elm.name]) {
                                    expo.stats.elements[elm.name] = 0;
                                }
                                expo.stats.elements[elm.name]++;
                            }
                            // Handle group element if present (e.g., slider, gallery, etc.)
                            if (elm?.group?.settings?.items) {
                                if (elm.group.element) {
                                    const groupElementName = elm.group.element;
                                    if (!expo.stats.elements[groupElementName]) {
                                        expo.stats.elements[groupElementName] = 0;
                                    }
                                    expo.stats.elements[groupElementName]++;
                                }
                                elm.group.settings.items.forEach((item) => {
                                    statelm(item.blocks);
                                });
                            }
                            // Then recurse into children
                            statelm(elm.blocks);
                        }
                        else if (elm.name != 'row') {
                            if (!expo.stats.elements[elm.name]) {
                                expo.stats.elements[elm.name] = 0;
                            }
                            expo.stats.elements[elm.name]++;
                            if (elm?.group?.settings?.items) {
                                // Count the group element type (e.g., slider, gallery, etc.) for vendors
                                if (elm.group.element) {
                                    const groupElementName = elm.group.element;
                                    if (!expo.stats.elements[groupElementName]) {
                                        expo.stats.elements[groupElementName] = 0;
                                    }
                                    expo.stats.elements[groupElementName]++;
                                }
                                elm.group.settings.items.forEach((item) => {
                                    statelm(item.blocks);
                                });
                            }
                        }
                    });
                }
            };
            expo.sections.forEach((sec) => {
                if (sec.stats) {
                    if (sec.stats.type == 'page') {
                        expo.stats.page = sec.stats.id;
                    } else if (
                        sec.stats.type == 'section' &&
                        expo.stats.sections.indexOf(sec.stats.id) === -1
                    ) {
                        expo.stats.sections.push( sec.stats.id );
                    }
                }
                // stats elements
                sec?.columns?.forEach((col) => {
                    statelm(col.blocks);
                });
                if(sec?.blocks?.length) {
                    statelm(sec.blocks);
                }

            });
        }

        let storeVendors = store.getters['builder/elementVendors'];
        Object.keys(expo.stats.elements).forEach(name => {
            name = name.toLowerCase();
            storeVendors.register?.[name]?.forEach(ven => {
                if (vendors[ven]) {
                    let url = vendors[ven],
                        type = url && url.match(/.js([?#]|$)/) ? 'js' :
                            (url && url.match(/.css([?#]|$)/) ? 'css' : '');
                    expo.vendors[type][ven] = url;
                }
            });
        });

        expo.preview = buildPreview( expo );
        allInstances.forEach((instance, key) => {
            if (instance && !instanceStore.get(key)) {
                instanceStore.register(key, instance);
            }
        });
        solve(expo);
    });
}

export const elementAIAssistantHTML = (name: string, data: Record<string, any>) => {
    const elmenId = data.id;
    if (!elmenId || typeof elmenId !== 'string') {
        return '';
    }
    const components = allComponents();
        const {componentName, componentInstance} = (() => {
        let componentName = '';
        let componentInstance = null;
        switch (name) {
            case 'row':
                componentName = 'Row';
                componentInstance = RowCore;
                break;
            case 'column':
                componentName = 'Column';
                componentInstance = ColumnCore;
                break;
            default:
                componentName = name.charAt(0).toUpperCase() + name.slice(1) + 'Element';
                componentInstance = components[componentName] || null;
        }

        return {
            componentName,
            componentInstance
        }
    })();
    if (!componentInstance) {
        return '';
    }
    const instanceStore = createInstanceStore()
    let instance = createApp({
        provide: {
            exporting: 'preview',
            instanceStore: instanceStore,
            eventBus: eventBus
        },
        computed: {
            elemData() {
                return data;
            }
        },
        mounted() {},
        template: `<${componentName} :data="elemData" />`
    });
    const wrp = document.createElement('div');
    instance.use(i18n);
    instance.component('Blocks', BlocksCore);

    instance.component('EcomIcon', Icon);
    instance.component('Row', RowCore);
    instance.component('Column', ColumnCore);
    instance.component('theme-extension', ThemeExtension);
    if ('row' !== name && 'column' !== name) {
        instance.component(componentName, componentInstance);
    }
    instance.use(store);
    instance.config.globalProperties.$helpers = store.$helpers;

    instance.mount(wrp);
    if (name == 'row' || name == 'column') {
        wrp.querySelectorAll('.ecom-block').forEach(block => {
            block.remove();
        });
    } else {
        if (!wrp.querySelector(`.${elmenId}`)) {
            const wrapper = document.createElement('div');
            wrapper.classList.add(elmenId);
            wrapper.innerHTML = wrp.innerHTML;
            wrp.innerHTML = '';
            wrp.appendChild(wrapper);
        }
    }

    // Replace all SVG contents with minimal empty SVGs while preserving attributes
    wrp.querySelectorAll('svg').forEach(svg => {
        const attrs: string[] = [];
        Array.from(svg.attributes).forEach(attr => {
            if (['width', 'height', 'viewBox'].includes(attr.name)) {
                attrs.push(`${attr.name}="${attr.value}"`);
            }
        });
        svg.outerHTML = `<svg ${attrs}><path d="M0 0h1v1H0z"/></svg>`;
    });
    wrp.querySelectorAll('*').forEach(el => {
        const element = el as HTMLElement;
        if (element.dataset?.content) {
            if (name == 'text') {
                element.removeAttribute('data-content');
            } else {
                element.dataset.content = element.dataset.content.slice(0, 100) + '...';
            }
        }
        el.childNodes.forEach(child => {
            if (child.nodeType == child.TEXT_NODE) {
                const text = child.textContent;
                if (text && text.length > 100) {
                    child.textContent = text.slice(0, 100) + '...';
                }
            }
        });
        if (el.tagName.toLowerCase() === 'img') {
            const src = el.getAttribute('src');
            if (src && src.startsWith('data:image/') && src.length > 100) {
                // Replace with the minimal base64 image
                el.setAttribute('src', 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7');
            }
        }
    });

    const html = minifyHTML(wrp.innerHTML
        .replace(/"\/images/g, '"'+url+'/images')
        .replace(/(<!--v-if-->| ([\w\d\-_]+?)="\[object Object\]"| data-placeholder="")/g, '')
        .replace(/ contenteditable="[^"]*"| spellcheck="[^"]*"/g, '')
        .replace(/liquid\[\[\]\]/g, '')
        .replaceAll('data-ecom-muted="true"', 'muted')
        .replace(/liquid\[\[([\s\S]+?|)\]\]/g, (...m) => {
            // Decode liquid code in html attributes
            // Vue will break out if attribute value has not been encoded
            // eg: <div class="{{ 1==1 ? "aaa" : "bbb" }}"
            return decodeURIComponent(m[1]);
        }));

    instance.unmount();
    wrp.remove();

    return html;
};
