// GridConfig.js
export class GridConfig {
  constructor(context) {
    this.context = context;
  }

  getSettings() {
    const { $t, isBoxed, isTopLevelSection } = this.context;

    const settings = [
      {
        group_title: $t("layout"),
        params: [
          {
            type: "choose",
            name: "content-width",
            label: $t("content_width"),
            options: {
              reset: true,
              type: "content-width",
              values: ["boxed", "full"]
            }
          },
          {
            name: "max-width",
            label: $t("max_width"),
            type: "number",
            css: {
              selector: ">.ecom-grid-layout"
            },
            options: {
              units: {
                px: {
                  min: 250,
                  max: 1600,
                  step: 1
                }
              },
              visible: {
                keep_data: false,
                condition: (data) => {
                  return data["content-width"] === "boxed";
                }
              },
              responsive: true
            }
          },
          {
            name: "min-height",
            label: $t("minimum_height"),
            type: "number",
            css: {
              selector: ">.ecom-grid-layout:not(.grid-resizing)",
              properties: {
                height: ""
              }
            },
            options: {
              units: {
                px: {
                  min: 0,
                  max: 3000,
                  step: 1
                },
                vh: {
                  min: 0,
                  max: 100,
                  step: 1
                },
                wh: {
                  min: 0,
                  max: 100,
                  step: 1
                }
              },
              responsive: true
            }
          }
        ]
      },
      {
        group_title: $t("video_background"),
        params: [
          {
            type: "popup",
            name: "source",
            label: $t("video_source"),
            options: {
              type: "dropdown",
              default: false,
              preview: "title",
              values: {
                none: $t("none"),
                upload: $t("upload_video"),
                external: $t("custom_video_url"),
                youtube: $t("youtube"),
                vimeo: $t("vimeo")
              }
            }
          },
          {
            type: "paragraph",
            name: "para_notice",
            options: {
              visible: (data) => {
                return (
                  data["source"] === "youtube" || data["source"] === "vimeo"
                );
              },
              warnings: {
                content: $t(
                  "youtube_and_vimeo_videos_will_be_disabled_on_mobile"
                )
              }
            }
          },
          {
            type: "picker",
            label: $t("choose_video_i_maximum_10_mb_i"),
            name: "video",
            options: {
              type: "video",
              visible: function (data) {
                return data["source"] === "upload";
              }
            }
          },
          {
            type: "text",
            label: $t("enter_your_custom_video_url"),
            name: "url",
            placeholder: "https://the-domain.com/*/video.mp4",
            options: {
              visible: function (data) {
                return data["source"] === "external";
              }
            }
          },
          {
            name: "srcYoutube",
            label: $t("youtube_link"),
            type: "text",
            options: {
              visible: function (data) {
                return data["source"] === "youtube";
              }
            }
          },
          {
            name: "srcVimeo",
            label: $t("vimeo_link"),
            type: "text",
            options: {
              visible: function (data) {
                return data["source"] === "vimeo";
              }
            }
          },
          {
            name: "start_time",
            label: $t("start_time_s"),
            type: "number",
            options: {
              half: true,
              slider: false,
              min: 0,
              max: 1000,
              visible: function (data) {
                return (
                  data["source"] === "vimeo" || data["source"] === "youtube"
                );
              }
            }
          },
          {
            name: "end_time",
            label: $t("end_time"),
            type: "number",
            options: {
              slider: false,
              min: 0,
              max: 1000,
              half: true,
              visible: function (data) {
                return data["source"] === "youtube";
              }
            }
          },
          {
            type: "toggle",
            name: "loop",
            label: $t("loop"),
            options: {
              values: {
                on: {
                  label: $t("on"),
                  value: true
                },
                off: {
                  label: $t("off"),
                  value: false
                }
              }
            }
          },
          {
            type: "toggle",
            name: "autoplay",
            label: $t("autoplay"),
            options: {
              values: {
                on: {
                  label: $t("on"),
                  value: true
                },
                off: {
                  label: $t("off"),
                  value: false
                }
              }
            }
          },
          {
            type: "paragraph",
            content: $t(
              "note_chromium_browsers_do_not_allow_autoplay_in_most_cases_however_muted_autoplay_is_always_allowed"
            )
          },
          {
            type: "toggle",
            name: "muted",
            label: $t("muted"),
            options: {
              values: {
                on: {
                  label: $t("yes"),
                  value: true
                },
                off: {
                  label: $t("no"),
                  value: false
                }
              },
              visible: function (data) {
                return data["source"] != "vimeo";
              }
            }
          },
          {
            type: "toggle",
            name: "inview_playpause",
            label: $t("auto_play_pause_when_in_view"),
            options: {
              values: {
                on: {
                  label: $t("yes"),
                  value: true
                },
                off: {
                  label: $t("no"),
                  value: false
                }
              }
            }
          },
          {
            type: "paragraph",
            content: $t("note_this_featured_not_working_on_safari")
          }
        ]
      }
    ];

    // SR only on top-level Grid section — not nested/inner grids
    if (isTopLevelSection) {
      settings.push({
        group_title: $t("scroll_reveal"),
        params: [
          {
            type: "paragraph",
            content: $t("scroll_reveal_section_description")
          },
          {
            type: "toggle",
            name: "scroll_reveal",
            label: $t("enable_scroll_reveal"),
            options: {
              values: {
                on:  { label: $t("yes"), value: true  },
                off: { label: $t("no"),  value: false }
              },
              oneline: true
            }
          },
          {
            type: "paragraph",
            options: {
              visible: data => data["scroll_reveal"] === true,
              warnings: { content: $t("scroll_reveal_override_warning") }
            }
          },
          {
            type: "popup",
            name: "scroll_reveal_type",
            label: $t("scroll_reveal_animation_style"),
            options: {
              type: "dropdown",
              preview: "title",
              values: {
                "fade-up":    "Fade Up",
                "fade-in":    "Fade In",
                "slide-left": "Slide Left",
                "zoom-in":    "Zoom In"
              },
              visible: { condition: data => data["scroll_reveal"] === true }
            }
          },
          {
            type: "number",
            name: "scroll_reveal_delay",
            label: $t("scroll_reveal_delay_between_items"),
            options: {
              min: 50, max: 300, step: 50, slider: true,
              visible: { condition: data => data["scroll_reveal"] === true }
            }
          }
        ]
      });
    }

    return settings;
  }

  getStyle() {
    const { $t } = this.context;

    return [
      {
        group_alias: "background",
        options: {
          group_title: $t("background"),
          css: true,
          reset: true
        }
      },
      {
        group_alias: "background:overlay",
        options: {
          group_title: $t("background_overlay"),
          group_name: "backgroud_overlay",
          selector: ">div.ecom-section__overlay"
        },
        modify: {
          remove: {
            index: 5,
            length: 1
          },
          params: [
            {
              position: 6,
              fields: [
                {
                  type: "background",
                  label: $t("background"),
                  name: "sectionBackgroundHover",
                  options: {
                    oneline: true,
                    responsive: true,
                    types: ["classic", "gradient"],
                    visible: {
                      condition: (data) => {
                        return data["tab"] === "hover";
                      }
                    }
                  },
                  css: {
                    selector:
                      "root:hover>.ecom-section__overlay>.ecom-overlay",
                    properties: {
                      background: ""
                    }
                  }
                }
              ]
            }
          ]
        }
      },
      {
        group_alias: "border",
        options: {
          group_title: $t("border"),
          css: true,
          reset: true
        },
        modify: {
          remove: [
            {
              index: 4,
              length: 1
            },
            {
              index: 7,
              length: 1
            }
          ],
          params: [
            {
              position: 3,
              fields: [
                {
                  type: "dimension",
                  label: $t("border_radius"),
                  name: "borderRadius",
                  options: {
                    responsive: true,
                    type: "radius",
                    units: "default",
                    visible: function (data) {
                      return data["bordertab"] === "normal";
                    }
                  },
                  css: {
                    selector: ", >div.ecom-section__overlay .ecom-overlay",
                    properties: {
                      "border-radius": ""
                    }
                  }
                }
              ]
            },
            {
              position: 7,
              fields: [
                {
                  type: "dimension",
                  label: $t("border_radius"),
                  name: "border-radiusHover",
                  options: {
                    responsive: true,
                    type: "radius",
                    units: "default",
                    visible: function (data) {
                      return data["bordertab"] === "hover";
                    }
                  },
                  css: {
                    selector:
                      ":hover,:hover >div.ecom-section__overlay .ecom-overlay",
                    properties: {
                      "border-radius": ""
                    }
                  }
                }
              ]
            }
          ]
        }
      },
      {
        group_alias: "typography",
        options: {
          group_title: $t("typography"),
          css: true,
          reset: true
        }
      }
    ].filter((p) => p);
  }

  getCss() {
    return `
      .ecom-grid-item .ecom-row > .core__row--columns {
        height: 100%;
      }
      .ecom-use-parallax {
        background: unset !important;
      }
      .ecom-parallax-background {
        position: absolute;
        width: 100%;
        height: 100%;
        display: flex;
        overflow: hidden;
      }
      .ecom-parallax-background img {
        object-fit: cover;
        width: 100%;
        position: absolute;
        top: 0;
        left: 50%;
        transform: translate(-50%,0);
        pointer-events: none;
      }
      .ecom-row {
        width: 100%;
        position: relative;
      }
      .ecom-video-background-youtube-wrapper {
        overflow: hidden
      }
      .ecom-section__overlay > .ecom-overlay, .ecom-section__overlay .ecom-video-background-youtube, .ecom-video-background-youtube-wrapper{
        position:absolute;
        top:0;
        left:0;
        bottom:0;
        right:0;
      }
      .ecom-row:not(.ecom-section) {
        float: left;
      }
      .ecom-row.ecom-section {
        clear: both;
      }
      .ecom-row:hover {
        z-index: 1;
      }
      .ecom-row>div.core__row--columns.core__row--full {
        max-width: 100%;
      }
      @media (min-aspect-ratio: 16/9) {
        .ecom-section__overlay .ecom-video-background-youtube  { height: 300%; top: -100%; }
      }
      @media (max-aspect-ratio: 16/9) {
        .ecom-section__overlay .ecom-video-background-youtube  { width: 300%; left: -100%; }
      }
      @supports not (aspect-ratio: 16 / 9) {
        .ecom-video-background-youtube:before {
          display: block;
          content: "";
          width: 100%;
          padding-top: 56.25%;
        }
        .ecom-video-background-youtube .ecom-video-background {
          position: absolute;
          top: 0;
          right: 0;
          bottom: 0;
          left: 0;
        }
        .ecom-video-background {
          -o-object-fit: unset !important;
          object-fit: unset !important;
        }
      }
      @media (max-width: 767px) {
        .ecom-section__video-bg .ecom-video-background-youtube {
          display: none;
        }
      }
    `;
  }
}