<template>
    <div class="ecom-element ecom-base-elements ecom-element__lightbox" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-element__lightbox-wrapper" :class="{'ecom-ingrid-full-height': data.inGrid}">
            <div
                class="ecom-element__lightbox-container ecom-flex"
                v-if="data.template === 'product'"
                :class="{'ecom-placeholder-on-builder-mode ecom-element__placeholder': !exporting, 'ecom-ingrid-full-height': data.inGrid}"
                :data-ecom-placeholder="exporting ? '' : 'This product not match with your condition'"
                v-html="liquid('product')"
            />

            <div
                class="ecom-element__lightbox-container ecom-flex"
                :class="{'ecom-ingrid-full-height': data.inGrid}"
                v-else
            >
                <button type="button" v-if="data.settings.general !== 'image'" ecom-modal="inline"
                        class="ecom__element--button ecom-elements__lightbox-button ecom-flex ecom-al_center ecom-fl_center"
                        :ecom-modal-source="popupSrc"
                >
                    <span  class="ecom-elements__lightbox-button-text" v-html="lang(data.settings.button_title,'lightbox_button_title')" />
                    <span class="ecom-button-icon ecom-elements__lightbox-button-icon ecom-flex" v-html="data.settings.icon" />
                </button>

                <button type="button" v-if="data.settings.general == 'image' && imageHandled?.value" ecom-modal="inline"
                        class="ecom-elements__lightbox-button-image"
                        :ecom-modal-source="popupSrc"
                >
                    <div class="ecom-image-default">
                        <picture class="ecom-lightbox-picture" v-html="$helpers.renImageResponsive(imageHandled, screens)" />
                    </div>
                </button>
                <div v-if="data.settings.source_type !== 'page'" style="display:none" >
                    <div v-if="data.settings.source_type === 'custom'" class="ecom-html" :id="'ecom-elements__lightbox-content-' + element_id">
                        <div class="ecom-elements__lightbox-content-heading" v-html="lang(data.settings.custom_heading_content)" />
                        <div class="ecom-elements__lightbox-content-body" v-html="lang(data.settings.custom_content)" />
                    </div>
                    <div v-if="data.settings.source_type === 'video_metafield'" :id="'ecom-elements__lightbox-content-' + element_id" style="height:100%; width: 100%">
                        <video
                            style="display: flex !important;width: 100%; height:100%;"
                            class="ecom_video"
                            controls
                            muted
                            playsinline
                        >
                            <source :src="liquid('video_metafield')" />
                        </video>
                    </div>
                    <div v-if="data.settings.source_type === 'video'" :id="'ecom-elements__lightbox-content-' + element_id" style="height:100%; width: 100%">
                        <video
                            style="display: flex !important;width: 100%; height:100%;"
                            v-if="data.settings?.source == 'self hosted'"
                            class="ecom_video"
                            controls
                            muted
                            playsinline
                        >
                            <source :src="linkSelfHosted" />
                        </video>
                        <iframe
                            v-else
                            class="ecom_iframe"
                            frameborder="0"
                            allowfullscreen="1"
                            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                            style="border: 0; width: 100%; height:100%; display: flex !important"
                            :src="data.settings?.source == 'vimeo' ? linkVimeo : linkYoutube"
                        >
                        </iframe>
                    </div>
                    <div v-if="data.settings.source_type == 'image_metafield'" :id="'ecom-elements__lightbox-content-' + element_id">
                        <img class="ecom-modal-picture" :src="liquid('image_metafield')" style="object-fit: cover; width: 100%;">
                    </div>
                    <div v-if="data.settings.source_type == 'image'" :id="'ecom-elements__lightbox-content-' + element_id" class="ecom-modal-picture">
                        <picture class="ecom-modal-picture" style="display:flex;" v-html="$helpers.renImageResponsive(this.imageSource, this.screens, true, {})"/>
                    </div>
                </div>
                <div v-else v-html="liquid('content')" />
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
import {hover} from "@/plugins/fields/core/alias/icon";
export default {
    name: 'lightbox',
    vendors: ['modal_js', 'modal_css'],
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {

                };
            }
        }
    },
    data(){
        return {
            jsreactives:['source_type','general']
        }
    },
    docs:function(data){
        if (data && data.template === 'product') {
            return 'https://help.ecomposer.io/docs/editor-elements/product-elements/size-chart/';
        }
        // Trả về mặc định
        return 'https://help.ecomposer.io/docs/elements/basic-elements/light-box/';
    },
    linkVideo:function(data){
        if (data && data.template === 'product') {
            return 'https://www.youtube.com/watch?v=P_FU6iXgSVA';
        }
        // Trả về mặc định
        return 'https://youtu.be/Wk4Ve1jI9SE';
    },
    computed: {
        screens() {
            return this.$store.getters["builder/screens"];
        },

        imageHandled() {
            if (!this.data?.settings) {
                return;
            }
            let image = { ...this.data.settings.image_popup };
            return {
                alt: image.name,
                ...image
            };
        },
        imageSource() {
            if (!this.data?.settings) {
                return;
            }
            let image = { ...this.data.settings.image_source };
            return {
                alt: image.name,
                ...image
            };
        },
        linkSelfHosted() {
            if (this.data.settings?.link) {
                let check = this.data.settings.link.match(
                    /(http(s)?:\/\/.)?(www\.)?[-a-zA-Z0-9@:%._+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_+.~#?&=]*)/
                );
                if (check[0] == "https://drive.google.com") {
                    const regex = /\/file\/d\/(.+)\/(.+)/;
                    let val = this.video.link.match(regex);
                    let videoId = val ? val[1] : null;
                    return `${location.protocol}//drive.google.com/uc?export=download&id=${videoId}`;
                } else {
                    return (
                        this.data.settings.link
                    );
                }
            } else {
                return;
            }
        },

        linkYoutube() {
            if (this.data.settings?.srcYoutube) {
                const regExpYt = /^.*(youtu\.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]{11}).*/;
                let val = this.data.settings.srcYoutube.match(regExpYt);
                let videoIdYt = val ? val[2] : null;

                return videoIdYt
                    ? `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3&autoplay=1&mute=1`
                    : "";
            } else {
                return "";
            }
        },
        linkVimeo() {
            if (this.data.settings?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.data.settings.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?rel=0?version=3&autoplay=1&muted=1`;
            } else {
                return "";
            }
        },

        element_id() {
            return this.data.id;
        },
        popupSrc() {
            let src = '#ecom-elements__lightbox-content-' + this.element_id
            return src;
        },
        liquids() {
            if(this.data.template !== 'product')
            {
                return {
                    image_metafield: {
                        code: `
                            {%- assign image = ${this.data.settings?.metafield} -%}
                            {{ image | image_url: width: 2048 }}
                        `
                    },
                    video_metafield: {
                        code: `
                        {% assign video = ${this.data.settings.metafield}.value.sources %}
                        {%- if video.size > 1 -%}
                            {{ video[1].url }}
                        {%- else -%}
                            {{ video[0].url }}
                        {%- endif -%}
                        `
                    },
                    content: {
                        code: `
                            ${this.data.settings && this.data.settings.source_type === 'page' ? `
                                <div class="ecom-html ecom-elements__lightbox-content" id="ecom-elements__lightbox-content-${this.element_id}" style="display:none">
                                    <div>
                                        {%- capture page_handle -%}${this.data.settings.page ? this.data.settings.page.value: ''}{%- endcapture-%}
                                        {% assign p = pages[page_handle] %}
                                        {% if p %}{{p.content}}{% endif %}
                                    </div>
                                </div>

                            `: ''}
                        `,
                        preview: ''
                    }
                }
            }
            return {
                product: {
                    code: `
                            {%- capture show_when -%}${this.data.settings.show_when}{%- endcapture -%}
                            {%- capture value -%}${this.data.settings.value}{%- endcapture -%}
                            {%- liquid
                                assign values  = value | split: ','
                                assign check = false
                                case show_when
                                    when 'all'
                                        assign check = true
                                    when 'option'
                                        for v in values
                                            assign val = v | strip
                                            if product.options contains val
                                                assign check = true
                                                break
                                            endif
                                        endfor
                                    when 'tag'
                                        for v in values
                                            assign val = v | strip
                                            if product.tags contains val
                                                assign check = true
                                                break
                                            endif
                                        endfor
                                    when 'type'
                                        for v in values
                                            assign val = v | strip
                                            if product.type contains val
                                                assign check = true
                                                break
                                            endif
                                        endfor
                                    when 'vendor'
                                        for v in values
                                            assign val = v | strip
                                            if product.vendor contains val
                                                assign check = true
                                                break
                                            endif
                                        endfor
                                    endcase
                            -%}
                            {%- if check -%}
                                {%- capture type -%}${this.data.settings.source_type}{%- endcapture -%}
                                    ${
                                        this.data.settings.general !== 'image' ? `
                                        <button type="button" ecom-modal="inline" class="ecom__element--button ecom-elements__lightbox-button ecom-flex ecom-fl_cener ecom-al_center" ecom-modal-source="#ecom-elements__lightbox-content-${this.element_id}">
                                            <span class="ecom-elements__lightbox-button-text" >
                                                ${this.lang(this.data.settings.button_title,'lightbox_button_title')}
                                            </span>
                                            <span class="ecom-button-icon ecom-elements__lightbox-button-icon">
                                                ${this.data.settings.icon ? this.data.settings.icon : ''}
                                            </span>
                                        </button>
                                        ` : ''
                                    }
                                    ${
                                        this.data.settings.general == 'image' && this.imageHandled?.value ? `
                                            <button ecom-modal="inline"
                                                    type="button"
                                                    class="ecom-elements__lightbox-button-image"
                                                    ecom-modal-source="#ecom-elements__lightbox-content-${this.element_id}"
                                            >
                                                <div class="ecom-image-default">
                                                    <picture class="ecom-lightbox-picture">
                                                        ${this.$helpers.renImageResponsive(this.imageHandled, this.screens)}
                                                    </picture>
                                                </div>
                                            </button>
                                        ` : ''
                                    }

                                    {%- if type != 'page' -%}
                                        <div style="display:none" >
                                            {%- if type == 'custom' -%}
                                                <div class="ecom-html" id="${'ecom-elements__lightbox-content-' + this.element_id}">
                                                    <div class="ecom-elements__lightbox-content-heading">${this.lang(this.data.settings.custom_heading_content)}</div>
                                                    <div class="ecom-elements__lightbox-content-body">${this.lang(this.data.settings.custom_content)}</div>
                                                </div>
                                            {%- elsif type == 'video' -%}

                                                <div id="${'ecom-elements__lightbox-content-' + this.element_id}" style="height:100%">
                                                    ${
                                                        this.data.settings?.source == 'self hosted' ? `
                                                            <video
                                                                style="display: flex !important;width: 100%; height:100%;"
                                                                class="ecom_video"
                                                                controls
                                                                playsinline
                                                            >
                                                                <source src="${this.linkSelfHosted}" />
                                                            </video>
                                                        ` : `
                                                            <iframe
                                                                class="ecom_iframe"
                                                                frameborder="0"
                                                                allowfullscreen="1"
                                                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                                                style="border: 0; width: 100%; height:100%; display: flex !important"
                                                                src="${this.data.settings?.source == 'vimeo' ? this.linkVimeo : this.linkYoutube}"
                                                            >
                                                            </iframe>
                                                        `
                                                    }


                                                </div>
                                            {%- elsif type == 'video_metafield' -%}

                                                <div id="${'ecom-elements__lightbox-content-' + this.element_id}" style="height:100%">
                                                    {% assign video = ${this.data.settings.metafield}.value.sources %}
                                                    {%- if video.size > 1 -%}
                                                        {% assign video_url = video[1].url %}
                                                    {%- else -%}
                                                        {% assign video_url = video[0].url %}
                                                    {%- endif -%}
                                                    <video
                                                        style="display: flex !important;width: 100%; height:100%;"
                                                        class="ecom_video"
                                                        controls
                                                        playsinline
                                                    >
                                                        <source src="{{ video_url }}" />
                                                    </video>
                                                </div>
                                            {%- elsif type == 'image_metafield' -%}
                                                {% assign image = ${this.data.settings?.metafield} %}
                                                <div id="${'ecom-elements__lightbox-content-' + this.element_id}" style="height:100%; width: 100%; display:flex;">
                                                    <img src="{{ image | image_url: width: 2048 }}" alt="" style="object-fit: cover; width: 100%;">
                                                </div>
                                            {%- else -%}
                                                <div id="${'ecom-elements__lightbox-content-' + this.element_id}" style="height:100%; width: 100%; display:flex;">
                                                    <picture style="height:100%; width: 100%; display:flex;">
                                                        ${this.$helpers.renImageResponsive(this.imageSource, this.screens, true, {'object-fit': 'cover', 'width': '100%'})}
                                                    </picture>
                                                </div>
                                            {%- endif -%}
                                        </div>
                                    {%- else -%}
                                        <div class="ecom-elements__lightbox-content ecom-html" id="ecom-elements__lightbox-content-${this.element_id}" style="display:none">
                                            <div>
                                                {%- capture page_handle -%}
                                                    ${this.data.settings.page ? this.data.settings.page.value: ''}
                                                {%- endcapture-%}
                                                {% assign p = pages[page_handle] %}
                                                {% if p %}{{p.content}}{% endif %}
                                            </div>
                                        </div>
                                    {%- endif -%}
                            {%- endif -%}
                        `,
                    preview: `
                            <div style="display: block;position: relative;width: 100%;">
                                <div class="ecom-skeleton-item">
                                    <div class="ecom-skeleton-col-12">
                                        <div class="ecom-skeleton-picture ecom-skeleton-big"></div>
                                        <div class="ecom-skeleton-row">
                                            <div class="ecom-skeleton-col-9 ecom-skeleton-big"></div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        `
                }
            };
        },
        javascript() {
            return function () {
                if(!this.$el) return;
                let $el = this.$el, isLive = this.isLive;
                var $el_id = this.id;
                const onClose = function () {
                    const popup = document.querySelectorAll('.ecom-container-lightbox-' + $el_id);
                    if(popup.length) {
                        popup.forEach(function(p) {
                            const popup_iframe = p.querySelector('iframe');
                            if(popup_iframe != null){
                                popup_iframe.contentWindow.postMessage('{"method":"pause"}', '*');
                                popup_iframe.src = '';
                            }

                            const video = p.querySelector('video');
                            if(video != null){
                                video.pause();
                            }
                        })
                    }
                }
                if($el && window.EComModal) {
                    var popup_selector = $el.querySelector('[ecom-modal]');
                    new window.EComModal(popup_selector, {
                        cssClass: ['ecom-container-lightbox-' + this.id, 'ecom-html', 'ecom-modal' ,'ecommodal-slide'],
                        onOpen: function() {
                            const popup = document.querySelectorAll('.ecom-container-lightbox-' + $el_id);
                                if(popup.length) {
                                    popup.forEach(function(p) {
                                        const popup_iframe = p.querySelector('iframe');
                                        if(popup_iframe != null){
                                            const src = popup_iframe.src.replace('muted=1', 'muted=0').replace('mute=1', 'mute=0');
                                            popup_iframe.src = src;
                                            // popup_iframe.src = popup_iframe.src;
                                        }
                                        const video = p.querySelector('video');
                                        if(video != null){
                                            video.play();
                                        }
                                    })

                                    window.dispatchEvent(new CustomEvent('ecom-lightbox-opened', {
                                        detail: {
                                            id: $el_id,
                                            el: popup,
                                        }
                                    }));
                                }
                        },
                        onClose
                    });
                }
                onClose();
            };
        },
        settings() {
            const settings =  [
                {
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('general'),
                            name: 'general',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: "title",
                                values: {
                                    image: this.$t('image'),
                                    button: this.$t('button'),
                                }
                            }
                        },
                        {
                            type: 'picker',
                            name: 'image_popup',
                            label: this.$t('select_image'),
                            options: {
                                type: 'image',
                                responsive: true,
                                multiple: false,
                                visible: function (data) {
                                    return data && data['general'] === 'image';
                                }
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('button_label'),
                            name: 'button_title',
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["general"] === "button";
                                    }
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('icon'),
                            name: 'icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                simple: false,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["general"] === "button";
                                    }
                                }
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('icon_position'),
                            name: 'icon_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['icon'] && data["general"] === "button";
                                    }
                                }
                            },
                            css:{
                                selector:' .ecom-button-icon',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('icon_spacing'),
                            name: 'spacing',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 200
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['icon'];
                                    }
                                }
                            },
                            css:{
                                selector:' .ecom__element--button',
                                properties:{
                                    gap:''
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('content_source'),
                            name: 'source_type',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    page: this.$t('page'),
                                    video: this.$t('video'),
                                    'video_metafield': this.$t('video_metafields'),
                                    image: this.$t('image'),
                                    'image_metafield': this.$t('image_metafields'),
                                    custom: this.$t('custom'),
                                }
                            }
                        },
                        {
                            type: 'text',
                            name: 'metafield',
                            label: this.$t('metafields'),
                            description: this.$t('metafields_type_is_file_single_br_ex_product_metafields_custom_img_custom'),
                            options: {
                                visible: function(data) {
                                    return (data['source_type'] === 'video_metafield' || data['source_type'] === 'image_metafield')
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('choose_image'),
                            name: 'image_source',
                            options: {
                                responsive: true,
                                type: 'image',
                                editAlt: false,
                                visible: function (data) {
                                    return data && data['source_type'] === 'image';
                                }
                            }
                        },
                        {
                            type: 'textarea',
                            label: this.$t('heading_content'),
                            name: 'custom_heading_content',
                            options: {
                                height: 120,
                                visible: function (data) {
                                    return data && data['source_type'] === 'custom';
                                }
                            }
                        },
                        {
                            type: 'textarea',
                            label: this.$t('content'),
                            name: 'custom_content',
                            options: {
                                toolbar: 'full',
                                height: 250,
                                visible: function (data) {
                                    return data && data['source_type'] === 'custom';
                                }
                            }
                        },
                        {
                            type: 'picker',
                            name: 'page',
                            label: this.$t('select_page'),
                            description: this.$t('this_page_content_will_appear'),
                            options: {
                                type: 'page',
                                layout: 'list',
                                multiple: false,
                                visible: function (data) {
                                    return data && data['source_type'] === 'page';
                                }
                            }
                        },
                        {
                            type: "popup",
                            label: this.$t('source'),
                            name: "source",
                            options: {
                                type: "dropdown",
                                preview: "title",
                                values: {
                                    youtube: "Youtube",
                                    vimeo: "Vimeo",
                                    "self hosted": this.$t('external_url'),
                                },
                                default: false,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["source_type"] === "video";
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            name: "link",
                            label: this.$t('external_url'),
                            description: this.$t('use_link_video_share_driver_mp_4_oog'),
                            type: "text",
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["source"] === "self hosted" && data["source_type"] === "video";
                                    }
                                }
                            }
                        },
                        {
                            name: "srcYoutube",
                            label: this.$t('youtube_link'),
                            type: "text",
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["source"] === "youtube" && data["source_type"] === "video";
                                    }
                                }
                            }
                        },
                        {
                            name: "srcVimeo",
                            label: this.$t('vimeo_link'),
                            type: "text",
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["source"] === "vimeo" && data["source_type"] === "video";
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'custom_content_popup',
                            label: this.$t('custom_content_popup'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('width'),
