                            name: 'value',
                            placeholder: this.$t('size'),
                            description: this.$t('enter_the_product_option_name_you_want_to_have_a_size_guide_for'),
                            options: {
                                visible: function (data) {
                                    return data && data['show_when'] && data['show_when'] !== 'all';
                                }
                            }
                        })
                }

            return settings;
        },

