        </button>

        <transition
            enter-active-class="transition duration-200 ease-out"
            enter-from-class="transform scale-90 opacity-0"
            enter-to-class="transform scale-100 opacity-100"
            leave-active-class="transition duration-150 ease-in"
            leave-from-class="transform scale-100 opacity-100"
            leave-to-class="transform scale-90 opacity-0"
        >
            <div v-if="isopen" class="absolute z-10 mt-2  top-full -right-1 text-left ecom-picker--modify">
                <BackDrop @click="doClose"></BackDrop>
                <div class="relative z-[2] inline-block w-64 text-white ">
                    <!-- <svg
                        viewBox="0 0 213.3 213.3"
                        class="absolute top-0 w-4 h-4 mr-10 -mt-3 transform rotate-180 right-[52px] fill-current"
                    >
                        <polygon
                            class="shadow-xxl"
                            points="0,53.333 106.667,160 213.333,53.333"
                        />
                    </svg> -->
                    <Fields
                        class="py-4 p-3 bg-white  rounded-lg shadow-popup"
                        :deep="1"
                        :data="data"
                        :fields="fields"
                    />
                </div>
            </div>
        </transition>
     </div>
</template>

<script lang="ts">
    import { Popmenu } from '@/mixins';
    import { EditMajor } from "@/assets/icons";
    export default {
        name: 'PickerModify',
        provide: {
            teleport_id: ".ecom-picker--modify"
        },
        mixins: [ Popmenu ],
        props: {
            fields: {
                type: Array,
                default() {
                    return [];
                }
            },
            data: {
                type: Object,
                default() {
                    return {};
                }
            },
            cl: {
                type: String,
                default: ''
            },
            noHover: {
                type: Boolean,
                default: false
            }
        },
        data(){
            return {
                icons: {
                    EditMajor
                }
            }
        },
        emits: ['update:modify'],
        watch: {
            data: {
                deep: true,
                handler() {
                    this.$emit('update:modify');
                }
            }
        },
        methods: {
            doClose(){
                this.isopen = false;
            }
        }
    };
