<template>
    <div class="ecom-element ecom-cart ecom-cart__informations">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <div class="ecom-cart__informations-wrapper">
            <div class="ecom-cart__informations-container" v-html="liquid('properties')" />
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
    import { Liquid, Element } from '@/mixins';
    export default {
        name: 'Cart informations',
        mixins: [Liquid, Element],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            csrContext() {
                return {
                    type: 'cart'
                }
            },
            liquids(){
                return {
                    properties: {
                        code: this.properties.map((property)=>{
                            switch(property.type)
                            {
                                case 'discounts':
                                    return `

                                    {% if cart.discount_applications.size > 0 %}
                                    <dl class="ecom-cart__informations-discount_application">
                                        <dt class="ecom-cart__information-title">${this.lang(property.settings.title,'discounts_title')}</dt>
                                        <dd class="ecom-cart__information-text">
                                            {% for discount_application in cart.discount_applications %}
                                                {%- assign amount = discount_application.total_allocated_amount | money -%}
                                                <span class="ecom-cart__informations-discount_application-value">
                                                    {% assign title = discount_application.title %}
                                                    ${this.lang(property.settings.message, 'discount_text',{ title: 'title', amount: 'amount' })}
                                                </span><br>
                                            {% endfor %}
                                        </dd>
                                    </dl>
                                    {% else %}
                                        ${!this.exporting
                                            ?  ` <dl class="ecom-cart__informations-discount_application">
                                                    <dt class="ecom-cart__information-title">${this.lang(property.settings.title,'discounts_title')}</dt>
                                                    <dd class="ecom-cart__information-text">
                                                        {%- assign tmp = 0 | money -%}
                                                        <span class="ecom-cart__informations-discount_application-value">
                                                            ${this.lang(property.settings.message, 'discount_text',{ title: 'discount_application.title', amount: 'tmp' })}
                                                        </span>
                                                    </dd>
                                                </dl> `
                                            : ""
                                        }
                                    {% endif %}
                                    `;
                                case 'item_count':
                                    return `
                                        <dl class="ecom-cart__informations-item_count">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'item_count_title')}
                                            </dt>
                                            <dd class="ecom-cart__information-text">
                                                {% assign count = cart.item_count %}
                                                ${this.lang(property.settings.text, 'item_count_text',{count: 'count'})}
                                            </dd>
                                        </dl>
                                    `;
                                case 'items_subtotal_price':
                                    return `
                                        <dl class="ecom-cart__informations-items_subtotal_price">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'item_subtotal_title')}
                                            </dt>
                                            <dd class="ecom-cart__information-text totals__subtotal-value" data-hulkapps-cart-total data-er-cart-total-price>
                                                {{ cart.items_subtotal_price | money }}
                                            </dd>
                                        </dl>
                                    `;
                                case 'original_total_price':
                                    return `
                                        <dl class="ecom-cart__informations-original_total_price">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'original_total_price')}
                                            </dt>
                                            <dd class="ecom-cart__information-text" data-hulkapps-cart-total>
                                                {{ cart.original_total_price | money }}
                                            </dd>
                                        </dl>
                                    `;
                                case 'taxes_included':
                                    return `
                                        <dl class="ecom-cart__informations-taxes_included">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'taxes_included_title')}
                                            </dt>
                                            <dd class="ecom-cart__information-text">
                                                {%- if cart.taxes_included-%}
                                                    ${this.lang(property.settings.included,'taxt_included_text')}
                                                {% else %}
                                                    ${this.lang(property.settings.included,'taxt_excluding_text')}
                                                {% endif %}
                                            </dd>
                                        </dl>
                                    `;
                                case 'total_discount':
                                    return `
                                    <dl class="ecom-cart__informations-total_discount">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'total_discount_title')}
                                            </dt>
                                            <dd class="ecom-cart__information-text">
                                                {%- assign tmp = cart.total_discount -%}
                                                {% comment %}
                                                {%- for item in cart.items -%}
                                                    {% if item.total_discount == 0 and item.variant.compare_at_price > item.price  %}
                                                        {% assign tmp = tmp | plus: item.variant.compare_at_price | minus: item.price %}
                                                        {% assign tmp = tmp | times: item.quantity %}
                                                    {% endif %}
                                                {%- endfor -%}
                                                {% endcomment %}
                                                {% assign amount = tmp | money %}
                                                ${this.lang(property.settings.text,'total_discount_text',{amount: 'amount'})}
                                            </dd>
                                    </dl>
                                    `;
                                case 'total_price':
                                    return `
                                    <dl class="ecom-cart__informations-total_price">
                                        <dt class="ecom-cart__information-title">
                                            ${this.lang(property.settings.title, 'total_price_title')}
                                        </dt>
                                        <dd class="ecom-cart__information-text totals__subtotal-value" data-hulkapps-cart-total data-er-cart-total-price {% if ${property.settings.show_bss_b2b_wholesale} %}bss-b2b-cart-total-price{% endif %}>
                                            {%- assign amount = cart.total_price | money -%}
                                            ${this.lang(property.settings.text,'total_price_text',{amount: 'amount' })}
                                        </dd>
                                    </dl>
                                    `;
                                case 'total_compare_at_price':
                                    return `
                                    {% assign amount = 0 %}
                                    {% for item in cart.items %}
                                        {% if item.variant.compare_at_price %}
                                            {% assign temp = item.variant.compare_at_price | times: item.quantity %}
                                            {% assign amount = amount | plus: temp %}
                                        {% endif %}
                                    {% endfor %}
                                    {% assign amount = amount | money %}
                                    <dl class="ecom-cart__informations-total_compare_at_price">
                                        <dt class="ecom-cart__information-title">
                                            ${this.lang(property.settings.title, 'total_price_title')}
                                        </dt>
                                        <dd class="ecom-cart__information-text totals__subtotal-value" data-er-cart-total-compare-price {% if ${property.settings.show_bss_b2b_wholesale} %}bss-b2b-cart-total-price{% endif %}>
                                            ${this.lang(property.settings.text,'total_price_text',{amount: 'amount' })}
                                        </dd>
                                    </dl>
                                    `;
                                case 'total_weight':
                                    return `
                                    <dl class="ecom-cart__informations-total_weight">
                                        <dt class="ecom-cart__information-title">
                                            ${this.lang(property.settings.title, 'total_weight_title')}
                                        </dt>
                                        <dd class="ecom-cart__information-text">
                                            {% assign amount = cart.total_weight | weight_with_unit  %}
                                            ${this.lang(property.settings.text,'total_weight_text',{amount: 'amount' })}
                                        </dd>
                                    </dl>
                                    `;
                                case 'savings_amount':
                                    return `
                                    {%- assign ecom_save = 0 -%}
                                    {%- assign ecom_compare = 0 -%}
                                    {%- for item in cart.items -%}
                                        {%- if item.variant.compare_at_price > item.price -%}
                                            {%- assign _s = item.variant.compare_at_price | minus: item.price | times: item.quantity -%}
                                            {%- assign ecom_save = ecom_save | plus: _s -%}
                                            {%- assign _c = item.variant.compare_at_price | times: item.quantity -%}
                                            {%- assign ecom_compare = ecom_compare | plus: _c -%}
                                        {%- endif -%}
                                    {%- endfor -%}
                                    {%- if ecom_save > 0 -%}
                                        {%- assign amount = ecom_save | money -%}
                                        {%- assign save_percent = ecom_save | times: 100 | divided_by: ecom_compare -%}
                                        <dl class="ecom-cart__informations-savings_amount">
                                            <dt class="ecom-cart__information-title">
                                                ${this.lang(property.settings.title, 'savings_amount_title')}
                                            </dt>
                                            <dd class="ecom-cart__information-text">
                                                ${property.settings.display_type === 'percent'
                                                    ? this.lang(property.settings.text_percent, 'savings_percent_text', { percent: 'save_percent' })
