                                                content: this.$t('show_subtotal_price_of_the_selected_items_covering_the_item_discount_n_this_price_doesn_t_include_some_fees_like_taxes_cart_discounts_shipping_costs_etc'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
