                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
                                                placeholder: this.$t('block_title'),
                                            },

                                        ],
                                        max: 1,
                                        values: {
                                            title: this.$t('subtotal'),
                                        }
                                    },
                                    {
                                        type: 'taxes_included',
                                        name:'Taxes',
                                        settings: [
                                            {
                                                type: 'paragraph',
                                                content: this.$t('to_make_the_taxes_be_included_in_your_products_prices_you_need_to_go_to_tax_settings_https_www_shopify_com_admin_settings_taxes_shpxid_c_3_bb_5_c_24_0574_4_d_27_06_ab_e_96_b_10_c_9_eb_73_once_you_finish_the_product_price_will_reflect_the_tax_value_based_on_your_customer_s_country'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
                                                placeholder: this.$t('block_title'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('the_text_when_taxes_included'),
                                                name: 'included',
                                                placeholder: this.$t('taxes_included'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('the_text_when_taxes_excluded'),
                                                name: 'excluding',
                                                placeholder: this.$t('taxes_excluded'),
                                            }
                                        ],
                                        max: 1,
                                        values: {
                                            title: this.$t('taxes'),
                                            included: this.$t('taxes_included'),
                                            excluding: this.$t('taxes_excluded'),
                                        }
                                    },
                                    {
                                        type: 'total_discount',
                                        name: 'Total discounts',
                                        settings: [
                                            {
                                                type: 'paragraph',
                                                content: this.$t('show_the_total_value_of_all_discounts'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
                                                placeholder: this.$t('block_title'),
                                            },
                                            {
                                                type: 'textarea',
                                                label: this.$t('total_discount_text'),
                                                name: 'text',
                                                description: this.$t('the_text_with_discount_amount_use_amount_to_show_discount_value'),
                                                placeholder: this.$t('saving_amount'),
                                            }
                                        ],
                                        max: 1,
                                        values: {
                                            title: this.$t('total_discount'),
                                            text: 'Saving {{amount}}'
                                        }
                                    },
                                    {
                                        type: 'total_price',
                                        name: 'Total price',
                                        settings: [
                                            {
                                                type: 'paragraph',
                                                content: this.$t('show_the_total_price_of_all_of_the_items_in_the_cart_after_discounts_have_been_applied'),
