                                                placeholder: this.$t('amount'),
                                            },
                                            {
                                                type: 'toggle',
                                                name: 'show_bss_b2b_wholesale',
                                                value: false,
                                                label: this.$t('show_bss_b2b_wholesale'),
                                                options: {
                                                    oneline: true,
                                                    values: {
                                                        on: {
                                                            label: this.$t('yes'),
                                                            value: true
                                                        },
                                                        off: {
                                                            label: this.$t('no'),
                                                            value: false
                                                        }
                                                    }
                                                },
                                            }
                                        ],
                                        max: 1,
                                        values: {
                                            title: this.$t('total_price'),
                                            text: '{{amount}}'
                                        }
                                    },
                                    {
                                        type: 'total_compare_at_price',
                                        name: 'Total compare at price',
                                        settings: [
                                            {
                                                type: 'paragraph',
                                                content: this.$t('show_the_total_compare_at_price_of_all_of_the_items_in_the_cart'),
                                            },
                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
