                                            {
                                                type: 'text',
                                                label: this.$t('title'),
                                                name: 'title',
                                                placeholder: this.$t('block_title'),
                                            },
                                                                                        {
                                                type: 'textarea',
                                                label: this.$t('total_weight_text'),
                                                name: 'text',
                                                description: this.$t('use_amount_to_show_total_item_weight_value'),
                                                placeholder: this.$t('amount'),
                                            }

                                        ],
                                        max: 1,
                                        values: {
                                            title: this.$t('total_weight'),
                                            text: '{{amount}}'
                                        }
                                    }, {
                                        type: 'savings_amount',
                                        name: 'Total savings',
                                        settings: [
                                            {
                                                type: 'paragraph',
                                                content: this.$t('show_total_savings_based_on_compare_at_price'),
                                            },
                                            {
                                                type: 'text',
