                                                        amount: this.$t('amount'),
                                                        percent: 'Percent',
                                                        both: 'Both',
                                                    }
                                                }
                                            },
                                            {
                                                type: 'textarea',
                                                label: this.$t('amount_text'),
                                                name: 'text_amount',
                                                description: this.$t('use_amount_to_show_the_total_price_value'),
