<template>
    <span v-html="svg" :class="size"></span>
</template>

<script>
    export default {
        props: {
            source: {
                type: String,
                default: '',
            },
            color: {
                type: String,
                default: '',
            },
            size: {
                type: String,
                default: 'w-5'
            }
        },
        computed: {
            svg(){
                var regex = /fill="([^"]*)"/g;
                var updatedSVGString = regex ? this.source?.replace(regex, 'fill="currentColor"') : this.source?.replace('<svg ', '<svg fill="currentColor" ');
                var updatedSVG = updatedSVGString?.replace(/(<svg[^>]*)\s(width|height)="[^"]+"/g, '$1');

                // var regex_width = /width="([^"]*)"/;
                // var updatedSVGWidth = updatedSVGString?.replace(regex_width, '');

                // var regex_height = /height="([^"]*)"/;
                // var updatedSVGHeight = updatedSVGWidth?.replace(regex_height, '');


                return updatedSVG?.replace('<svg', `<svg class="inline-flex ${this.size} ${this.color}"`)
            }
        }
    }
</script>

<style>
    .icon-scale path{
        transform: scale(1.3);
        transform-origin: center;
    }
</style>
