// ResizeHandler.ts
import type {
  GridInstance,
  ResizeOptions,
  ResizeEvents,
  ResizeEventData,
  ResizeState,
  ResizeHandlerInstance
} from './types';

export class ResizeHandler implements ResizeHandlerInstance {
  private instance: GridInstance;
  private options: ResizeOptions;
  private events: ResizeEvents;
  private resizeState: ResizeState;
  private _mouseMoveHandler: ((e: MouseEvent) => void) | null = null;
  private _mouseUpHandler: ((e: MouseEvent) => void) | null = null;

  constructor(instance: GridInstance, options: ResizeOptions = {}, events: ResizeEvents = {}) {
    this.instance = instance;
    this.options = {
      enableResize: true,
      minHeight: 100,
      snapToGrid: false,
      realTimeUpdate: true,
      ...options
    };
    this.events = events;

    this.resizeState = {
      isResizing: false,
      startY: 0,
      startHeight: 0,
      newHeight: 0,
      isListening: false
    };

    this.bindMethods();
  }

  private bindMethods(): void {
    this.handleResize = this.handleResize.bind(this);
    this.stopResizing = this.stopResizing.bind(this);
    this.startResizing = this.startResizing.bind(this);
  }

  public startResizing(e: MouseEvent): void {
    try {
      if (this.instance.exporting) return;

      e.preventDefault();

      const gridElement = this.instance.$refs.grid?.$refs?.item;
      if (!gridElement) {
        console.warn('Grid element not found for resize');
        return;
      }

      const computedStyle = window.getComputedStyle(gridElement);
      this.resizeState.startHeight = parseFloat(computedStyle.height);
      this.resizeState.newHeight = this.resizeState.startHeight;

      // Set initial height and add resizing class
      gridElement.style.height = `${this.resizeState.startHeight}px`;
      gridElement.classList.add("grid-resizing");

      this.resizeState.startY = e.clientY;
      this.resizeState.isResizing = true;

      // Add event listeners
      this.addResizeListeners();

      // Emit resize start event
      const resizeEventData: ResizeEventData = {
        eventType: 'resizestart',
        sectionId: this.instance.data.id,
        screen: this.instance.screen,
        startHeight: this.resizeState.startHeight,
        newHeight: this.resizeState.newHeight,
        deltaY: 0
      };

      this.instance.eventBus.emit("resizeEvent", resizeEventData);

      if (this.events.onResizeStart) {
        this.events.onResizeStart(resizeEventData);
      }
    } catch (error) {
      console.warn("Start resizing error:", error);
      this.stopResizing();
    }
  }

  public handleResize(e: MouseEvent): void {
    try {
      if (!this.resizeState.isResizing) return;

      e.preventDefault();

      const gridElement = this.instance.$refs.grid?.$refs?.item;
      if (!gridElement) return;

      const deltaY = e.clientY - this.resizeState.startY;
      this.resizeState.newHeight = Math.max(
        this.options.minHeight!,
        Math.round(this.resizeState.startHeight + deltaY)
      );

      if (this.options.realTimeUpdate) {
        requestAnimationFrame(() => {
          gridElement.style.height = `${this.resizeState.newHeight}px`;
        });
      }

      // Emit resize event
      const resizeEventData: ResizeEventData = {
        eventType: 'resize',
        sectionId: this.instance.data.id,
        screen: this.instance.screen,
        startHeight: this.resizeState.startHeight,
        newHeight: this.resizeState.newHeight,
        deltaY: deltaY
      };

      this.instance.eventBus.emit("resizeEvent", resizeEventData);

      if (this.events.onResize) {
        this.events.onResize(resizeEventData);
      }
    } catch (error) {
      console.warn("Handle resize error:", error);
      this.stopResizing();
    }
  }

  public stopResizing(): void {
    try {
      if (!this.resizeState.isResizing) return;

      const finalHeight = this.resizeState.newHeight;
      const gridElement = this.instance.$refs.grid?.$refs?.item;

      // Update settings data
      const height = `height${this.instance.screen === "desktop" ? "" : `__${this.instance.screen}`}`;
      const minHeight = `min-height${this.instance.screen === "desktop" ? "" : `__${this.instance.screen}`}`;

      this.instance.data.settings[minHeight] = finalHeight + "px";
      this.instance.data.settings[height] = "fixed";

      // Clean up grid element styles
      if (gridElement) {
        setTimeout(() => {
          gridElement.style.height = ``;
          gridElement.style.minHeight = ``;
        }, 100);

        gridElement.classList.remove("grid-resizing");
      }

      // Remove event listeners
      this.removeResizeListeners();

      // Reset resize state
      const oldIsResizing = this.resizeState.isResizing;
      this.resizeState.isResizing = false;

      // Emit events
      this.instance.$nextTick(() => {
        window.dispatchEvent(new Event("resize"));
        this.instance.eventBus.emit("layout-updated");
      });

      // Emit resize end event
      const resizeEventData: ResizeEventData = {
        eventType: 'resizeend',
        sectionId: this.instance.data.id,
        screen: this.instance.screen,
        startHeight: this.resizeState.startHeight,
        newHeight: finalHeight,
        deltaY: finalHeight - this.resizeState.startHeight
      };

      this.instance.eventBus.emit("resizeEvent", resizeEventData);

      if (this.events.onResizeEnd) {
        this.events.onResizeEnd(resizeEventData);
      }
    } catch (error) {
      console.warn("Stop resizing error:", error);
      // Force reset state even if error occurs
      this.resizeState.isResizing = false;
      this.removeResizeListeners();
    }
  }

  private addResizeListeners(): void {
    try {
      if (this.resizeState.isListening) return;

      const iframeDoc = this.instance.idoc();

      // Create wrapper functions
      this._mouseMoveHandler = this.handleResize.bind(this);
      this._mouseUpHandler = this.stopResizing.bind(this);

      // Add listeners to iframe document
      iframeDoc.addEventListener("mousemove", this._mouseMoveHandler);
      iframeDoc.addEventListener("mouseup", this._mouseUpHandler);

      this.resizeState.isListening = true;
    } catch (error) {
      console.warn("Add resize listeners error:", error);
    }
  }

  private removeResizeListeners(): void {
    try {
      if (!this.resizeState.isListening) return;

      const iframeDoc = this.instance.idoc();

      if (this._mouseMoveHandler) {
        iframeDoc.removeEventListener("mousemove", this._mouseMoveHandler);
        this._mouseMoveHandler = null;
      }

      if (this._mouseUpHandler) {
        iframeDoc.removeEventListener("mouseup", this._mouseUpHandler);
        this._mouseUpHandler = null;
      }

      this.resizeState.isListening = false;
    } catch (error) {
      console.warn("Remove resize listeners error:", error);
    }
  }

  public getCurrentHeight(): number {
    return this.resizeState.newHeight || this.resizeState.startHeight;
  }

  public isCurrentlyResizing(): boolean {
    return this.resizeState.isResizing;
  }

  public destroy(): void {
    try {
      // Stop any ongoing resize
      if (this.resizeState.isResizing) {
        this.stopResizing();
      }

      // Remove listeners
      this.removeResizeListeners();

      // Reset state
      this.resizeState = {
        isResizing: false,
        startY: 0,
        startHeight: 0,
        newHeight: 0,
        isListening: false
      };
    } catch (error) {
      console.warn("Destroy resize handler error:", error);
    }
  }
}