// @/plugins/vue-grid-layout/helpers/autoLayoutUtils.ts

export interface LayoutItem {
    id: string;
    left: number; // %
    top: number; // px
    width: number; // px
    height: number; // px
    originalWidth: string | number; // giữ nguyên định dạng gốc
    block: any;
    zindex: number | string;
}

export interface LayoutChange {
    left?: number;
    top?: number;
    width?: string | number;
    height?: number;
    zindex?: number | string;
}

export interface AutoLayoutConfig {
    gridContainerWidth: number;
    screen: string;
    minGapPx?: number;
    minWidthPx?: number;
    maxWidthPercent?: number;
    minHeightPx?: number;
    verticalOverlapThreshold?: number;
    horizontalGapThreshold?: number;
    // Thêm config mới cho mobile
    centerSingleItemsOnMobile?: boolean;
    mobileWidthThreshold?: number;
    // Config mới cho full-width items
    fullWidthItemsSpacing?: number; // Khoảng cách giữa các full-width items
    enableFullWidthOptimization?: boolean; // Bật tối ưu cho full-width items
}

export interface AutoLayoutResult {
    changes: Map<string, LayoutChange>;
    processedInGroups: Set<string>;
    fullWidthItems: Set<string>; // Thêm track cho full-width items
    maxBottomPosition?: number; // THÊM: Vị trí bottom cuối cùng để update height
}

export interface SectionHeightInfo {
    minHeightKey: string;
    settingValue?: string;
    visualValue?: number;
    type: "auto" | "fixed";
    value?: number;
}

export interface HeightPreview {
    newHeight: number;
    originalHeight: SectionHeightInfo;
    minHeightKey: string;
}

export class HeightManager {
    private static instance: HeightManager;

    static getInstance(): HeightManager {
        if (!this.instance) {
            this.instance = new HeightManager();
        }
        return this.instance;
    }

    /**
     * Preview height changes
     */
    previewHeightUpdate(
        maxBottomPosition: number,
        settings: any,
        screen: string,
        gridElement: HTMLElement | null,
        isMobileScreen: boolean = false
    ): HeightPreview | null {
        if (!maxBottomPosition || maxBottomPosition <= 0) {
            return null;
        }

        if (!gridElement) {
            return null;
        }

        // Tính toán height mới và làm tròn thành số nguyên
        const paddingBottom = isMobileScreen ? 10 : 20;
        const calculatedHeight = maxBottomPosition + paddingBottom;
        const newHeight = Math.round(calculatedHeight); // ✅ LÀM TRÒN THÀNH SỐ NGUYÊN

        // Lấy thông tin height hiện tại
        const originalHeight = this.getCurrentSectionHeight(settings, screen, gridElement);
        const minHeightKey = this.getMinHeightKey(screen);

        // NGAY LẬP TỨC apply preview visual với height đã làm tròn
        this.applyHeightPreview(gridElement, newHeight, originalHeight.type);

        const result: HeightPreview = {
            newHeight,
            originalHeight,
            minHeightKey
        };

        return result;
    }

    /**
     * Apply height preview - ENHANCED VERSION with ROUNDED HEIGHT
     */
    applyHeightPreview(
        gridElement: HTMLElement | null,
        height: number,
        type: "auto" | "fixed" = "auto"
    ): void {
        if (!gridElement) {
            return;
        }

        // ✅ Đảm bảo height là số nguyên
        const roundedHeight = Math.round(height);

        // LUÔN LUÔN apply style trực tiếp cho preview với height đã làm tròn
        gridElement.style.height = `${roundedHeight}px`;
        gridElement.classList.add("height-preview");

        // Thêm visual indicator
        if (!gridElement.classList.contains("height-preview-active")) {
            gridElement.classList.add("height-preview-active");
        }

        // Đảm bảo style được apply với height đã làm tròn
        gridElement.style.setProperty("min-height", `${roundedHeight}px`, "important");
    }

    /**
     * Confirm height update
     */
    confirmHeightUpdate(
        heightPreview: HeightPreview,
        settings: any,
        gridElement: HTMLElement | null
    ): void {
        const { newHeight, originalHeight, minHeightKey } = heightPreview;

        // ✅ Đảm bảo newHeight là số nguyên
        const roundedNewHeight = Math.round(newHeight);
        if (originalHeight.type === "auto") {
            // Auto height: keep style với height đã làm tròn
            if (gridElement) {
                gridElement.style.height = `${roundedNewHeight}px`;
                // Remove preview classes nhưng keep height
                gridElement.classList.remove("height-preview", "height-preview-active");
            }
        } else {
            // Fixed height: cập nhật min-height setting với height đã làm tròn
            const currentMinHeight =
                parseInt(settings[minHeightKey] || settings["min-height"]) || 0;

            if (roundedNewHeight > currentMinHeight) {
                settings[minHeightKey] = `${roundedNewHeight}px`; // ✅ Lưu height đã làm tròn
                // Remove preview styles để let CSS setting take over
                if (gridElement) {
                    gridElement.classList.remove("height-preview", "height-preview-active");
                    gridElement.style.removeProperty("height");
                    gridElement.style.removeProperty("min-height");
                }
            } else {
                // Keep preview style với height đã làm tròn
                if (gridElement) {
                    gridElement.style.height = `${roundedNewHeight}px`;
                }
            }
        }
    }

    /**
     * Cancel height preview
     */
    cancelHeightPreview(originalHeight: SectionHeightInfo, gridElement: HTMLElement | null): void {
        if (!gridElement) return;

        // Remove tất cả preview styles
        gridElement.classList.remove(
            "height-preview",
            "height-preview-active",
            "height-preview-fixed"
        );
        gridElement.style.removeProperty("--preview-height");
        gridElement.style.removeProperty("height");
        gridElement.style.removeProperty("min-height");

        // Restore về original nếu có với height đã làm tròn
        if (originalHeight.value && originalHeight.type === "auto") {
            const roundedOriginalHeight = Math.round(originalHeight.value);
            gridElement.style.height = `${roundedOriginalHeight}px`;
        }
    }

    /**
     * Clean up height preview - ENHANCED
     */
    cleanupHeightPreview(gridElement: HTMLElement | null): void {
        if (!gridElement) return;

        // Remove tất cả preview classes và styles
        gridElement.classList.remove(
            "height-preview",
            "height-preview-active",
            "height-preview-fixed"
        );
        gridElement.style.removeProperty("--preview-height");

        // CHỈ remove height/min-height nếu có preview classes
        const hasPreviewClass = gridElement.classList.contains("height-preview");
        if (hasPreviewClass) {
            gridElement.style.removeProperty("height");
            gridElement.style.removeProperty("min-height");
        }
    }

    /**
     * Enhanced updateHeightAfterAutoLayout
     */
    updateHeightAfterAutoLayout(
        maxBottomPosition: number,
        settings: any,
        screen: string,
        gridElement: HTMLElement | null,
        isMobileScreen: boolean = false,
        enableHeightUpdate: boolean = true,
        isPreview: boolean = false
    ): HeightPreview | null {
        if (!enableHeightUpdate) {
            return null;
        }

        if (isPreview) {
            // Preview mode: preview height update
            return this.previewHeightUpdate(
                maxBottomPosition,
                settings,
                screen,
                gridElement,
                isMobileScreen
            );
        } else {
            // Confirm mode: apply height update
            const heightPreview = this.previewHeightUpdate(
                maxBottomPosition,
                settings,
                screen,
                gridElement,
                isMobileScreen
            );
            if (heightPreview) {
                this.confirmHeightUpdate(heightPreview, settings, gridElement);
            }
            return heightPreview;
        }
    }

    // ... các method khác giữ nguyên
    getHeightKey(screen: string): string {
        return `height${screen === "desktop" ? "" : `__${screen}`}`;
    }

    getMinHeightKey(screen: string): string {
        return `min-height${screen === "desktop" ? "" : `__${screen}`}`;
    }

    isAutoHeight(settings: any, screen: string): boolean {
        const minHeightKey = this.getMinHeightKey(screen);

        if (screen === "desktop") {
            return settings?.["min-height"] === undefined;
        } else {
            const hasScreenSpecificMinHeight = settings?.[minHeightKey] !== undefined;
            return !hasScreenSpecificMinHeight && settings?.["min-height"] === undefined;
        }
    }

    getCurrentSectionHeight(
        settings: any,
        screen: string,
        gridElement: HTMLElement | null
    ): SectionHeightInfo {
        const minHeightKey = this.getMinHeightKey(screen);

        const currentVisualHeight = gridElement
            ? parseFloat(window.getComputedStyle(gridElement).height)
            : null;

        const currentSettingValue = settings[minHeightKey] || settings["min-height"];
        const heightType = this.isAutoHeight(settings, screen) ? "auto" : "fixed";

        return {
            minHeightKey,
            settingValue: currentSettingValue,
            visualValue: currentVisualHeight || undefined,
            type: heightType,
            value:
                currentVisualHeight ||
                (currentSettingValue ? parseFloat(currentSettingValue) : undefined)
        };
    }
}

