export class LayoutChangeApplicator {
    private static instance: LayoutChangeApplicator;

    static getInstance(): LayoutChangeApplicator {
        if (!this.instance) {
            this.instance = new LayoutChangeApplicator();
        }
        return this.instance;
    }

    /**
     * Apply layout changes với enhanced tracking cho full-width items
     */
    async applyLayoutChangesEnhanced(
        changes: Map<string, LayoutChange>,
        itemsData: LayoutItem[],
        currentScreen: string,
        fullWidthItems: Set<string>,
        maxBottomPosition: number | undefined,
        callbacks: {
            updateItemLayout: (
                item: LayoutItem,
                screen: string,
                updates: LayoutChange,
                isFullWidth: boolean
            ) => void;
            emitLayoutUpdate?: () => void;
        }
    ): Promise<void> {
        const batchSize = 5;
        const changeEntries = Array.from(changes.entries());

        // Phân chia theo priority: full-width items trước, regular items sau
        const fullWidthChanges = changeEntries.filter(([itemId]) => fullWidthItems.has(itemId));
        const regularChanges = changeEntries.filter(([itemId]) => !fullWidthItems.has(itemId));

        // Xử lý full-width items trước
        if (fullWidthChanges.length > 0) {
            for (const [itemId, layoutChanges] of fullWidthChanges) {
                const item = itemsData.find((i) => i.id === itemId);
                if (item) {
                    callbacks.updateItemLayout(item, currentScreen, layoutChanges, true);
                }
            }

            // Ngắt ngủ ngắn để UI có thể update
            await new Promise((resolve) => setTimeout(resolve, 100));
        }

        // Xử lý regular items theo batches
        for (let i = 0; i < regularChanges.length; i += batchSize) {
            const batch = regularChanges.slice(i, i + batchSize);

            batch.forEach(([itemId, layoutChanges]) => {
                const item = itemsData.find((i) => i.id === itemId);
                if (item) {
                    callbacks.updateItemLayout(item, currentScreen, layoutChanges, false);
                }
            });

            if (regularChanges.length > batchSize) {
                await new Promise((resolve) => setTimeout(resolve, 50));
            }
        }

        // Emit layout updated nếu có callback
        if (callbacks.emitLayoutUpdate) {
            callbacks.emitLayoutUpdate();
        }
    }

    /**
     * Helper để emit layout update events
     */
    emitLayoutUpdateEvents(
        item: LayoutItem,
        updates: LayoutChange,
        isFullWidth: boolean,
        callbacks: {
            emitUpdateGridItem: (data: any) => void;
            emitMoved: (id: string, left: number, top: number) => void;
            emitResized?: (
                id: string,
                height: number,
                width: number | string,
                left: number,
                top: number
            ) => void;
            emitZindexed?: (id: string, zindex: number | string) => void;
        }
    ): void {
        const finalUpdates = { ...updates };
        // Override cho full-width items
        if (isFullWidth) {
            if (finalUpdates.left !== undefined) finalUpdates.left = 0;
            if (finalUpdates.width !== undefined) finalUpdates.width = "100%";
        }

        callbacks.emitUpdateGridItem({
            id: item.id,
            left: finalUpdates.left !== undefined ? finalUpdates.left : item.left,
            top: finalUpdates.top !== undefined ? finalUpdates.top : item.top,
            width: finalUpdates.width !== undefined ? finalUpdates.width : item.originalWidth,
            height: finalUpdates.height !== undefined ? finalUpdates.height : item.height,
            zindex: finalUpdates.zindex !== undefined ? finalUpdates.zindex : item.zindex,
            isFullWidth: isFullWidth
        });

        callbacks.emitMoved(
            item.id,
            finalUpdates.left !== undefined ? finalUpdates.left : item.left,
            finalUpdates.top !== undefined ? finalUpdates.top : item.top
        );

        if (
            (finalUpdates.width !== undefined || finalUpdates.height !== undefined) &&
            callbacks.emitResized
        ) {
            callbacks.emitResized(
                item.id,
                finalUpdates.height !== undefined ? finalUpdates.height : item.height,
                finalUpdates.width !== undefined ? finalUpdates.width : item.originalWidth,
                finalUpdates.left !== undefined ? finalUpdates.left : item.left,
                finalUpdates.top !== undefined ? finalUpdates.top : item.top
            );
        }

        if (finalUpdates.zindex !== undefined && callbacks.emitZindexed) {
            callbacks.emitZindexed(item.id, finalUpdates.zindex);
        }
    }

    /**
     * Cập nhật item data local - ENHANCED
     */
    updateItemDataLocal(
        item: LayoutItem,
        updates: LayoutChange,
        isFullWidth: boolean,
        gridContainerWidth: number
    ): void {
        if (updates.left !== undefined) {
            item.left = isFullWidth ? 0 : updates.left;
        }
        if (updates.top !== undefined) item.top = updates.top;

        if (updates.width !== undefined) {
            if (isFullWidth) {
                item.width = gridContainerWidth;
                item.originalWidth = "100%";
            } else {
                const widthPx =
                    typeof updates.width === "string" && updates.width.includes("%")
                        ? (parseFloat(updates.width) / 100) * gridContainerWidth
                        : parseFloat(updates.width.toString());
                item.width = widthPx;
                item.originalWidth = updates.width;
            }
        }

        if (updates.height !== undefined) item.height = updates.height;
        if (updates.zindex !== undefined) item.zindex = updates.zindex;
    }
}

// ========================================================================
// PREVIEW AND STATE MANAGEMENT UTILITIES
// ========================================================================

export interface AutoLayoutState {
    isProcessing: boolean;
    isPreviewing: boolean;
    originalState: Map<string, any>;
    previewChanges: AutoLayoutResult | null;
    heightPreview: HeightPreview | null;
}

export class AutoLayoutStateManager {
    private static instance: AutoLayoutStateManager;
    private state: AutoLayoutState = {
        isProcessing: false,
        isPreviewing: false,
        originalState: new Map(),
        previewChanges: null,
        heightPreview: null
    };

    static getInstance(): AutoLayoutStateManager {
        if (!this.instance) {
            this.instance = new AutoLayoutStateManager();
        }
        return this.instance;
    }

    getState(): AutoLayoutState {
        return this.state;
    }

    setProcessing(isProcessing: boolean): void {
        this.state.isProcessing = isProcessing;
    }

    setPreviewing(isPreviewing: boolean): void {
        this.state.isPreviewing = isPreviewing;
    }

    /**
     * Lưu trữ state gốc trước khi preview
     */
    saveOriginalState(
        blocks: any[],
        getScreenLayout: (block: any, screen: string) => any,
        screen: string,
        getCurrentSectionHeight: () => SectionHeightInfo,
        getDataAttributes?: (blockId: string) => { [key: string]: string }
    ): void {
        this.state.originalState.clear();

        // ✅ Lưu trữ COMPLETE original state cho từng item
        blocks.forEach((block) => {
            const layout = getScreenLayout(block, screen);

            // ✅ Lưu cả data attributes nếu có callback
            let dataAttributes = {};
            if (getDataAttributes) {
                dataAttributes = getDataAttributes(block.id);
            }

            // ✅ Lưu COMPLETE layout data
            const originalData = {
                // Layout data
                left: layout.left,
                top: layout.top,
                width: layout.width,
                height: layout.height,
                originalWidth: layout.width,
                zindex: layout.zindex || 10,
                rotation: layout.rotation || 0,

                // Block metadata
                blockId: block.id,
                blockLayouts: JSON.parse(JSON.stringify(block.layouts)), // ✅ Deep copy

                // Data attributes
                dataAttributes: dataAttributes,

                // Timestamp for debugging
                savedAt: Date.now()
            };

            this.state.originalState.set(block.id, originalData);
        });

        // Lưu section height state
        this.state.originalState.set("sectionHeight", getCurrentSectionHeight());
    }

    /**
     * Lưu preview changes
     */
    setPreviewChanges(changes: AutoLayoutResult): void {
        this.state.previewChanges = changes;
    }

    /**
     * Lưu height preview
     */
    setHeightPreview(heightPreview: HeightPreview | null): void {
        this.state.heightPreview = heightPreview;
    }

    /**
     * Emit preview changes
     */
    emitPreviewChanges(emitUpdateGridItem: (data: any) => void): void {
        if (!this.state.previewChanges || !this.state.originalState.size) return;

        const { changes, fullWidthItems } = this.state.previewChanges;

        changes.forEach((layoutChanges, itemId) => {
            const originalState = this.state.originalState.get(itemId);
            if (!originalState) return;

            // Tính toán final values cho preview
            const finalValues = {
                id: itemId,
                left: layoutChanges.left !== undefined ? layoutChanges.left : originalState.left,
                top: layoutChanges.top !== undefined ? layoutChanges.top : originalState.top,
                width:
                    layoutChanges.width !== undefined
                        ? layoutChanges.width
                        : originalState.originalWidth,
                height:
                    layoutChanges.height !== undefined
                        ? layoutChanges.height
                        : originalState.height,
                zindex:
                    layoutChanges.zindex !== undefined
                        ? layoutChanges.zindex
                        : originalState.zindex,
                isPreview: true // Flag để grid biết đây là preview
            };

            // Special handling cho full-width items
            if (fullWidthItems.has(itemId)) {
                finalValues.left = 0;
                finalValues.width = "100%";
                (finalValues as any).isFullWidth = true;
            }

            // Emit update-grid-item cho preview
            emitUpdateGridItem(finalValues);
        });
    }

    /**
     * Restore về trạng thái gốc
     */
    restoreOriginalState(
        emitUpdateGridItem: (data: any) => void,
        restoreDataAttributes?: (itemId: string, dataAttributes: any) => void,
        restoreBlockLayouts?: (blockId: string, layouts: any) => void // ✅ NEW callback
    ): void {
        console.log("🔄 Restoring original state...");

        if (!this.state.originalState.size) {
            console.warn("⚠️ No original state to restore");
            return;
        }

        let restoredCount = 0;

        // ✅ Restore layout items với complete data
        this.state.originalState.forEach((originalState, itemId) => {
            if (itemId === "sectionHeight") return; // Skip height data

            console.log(`🔄 Restoring ${itemId}:`, originalState);

            // ✅ 1. Restore block layouts data (CRITICAL)
            if (restoreBlockLayouts && originalState.blockLayouts) {
                restoreBlockLayouts(itemId, originalState.blockLayouts);
                console.log(`📋 Restored block layouts for ${itemId}`);
            }

            // ✅ 2. Restore data attributes
            if (restoreDataAttributes && originalState.dataAttributes) {
                restoreDataAttributes(itemId, originalState.dataAttributes);
                console.log(`🏷️ Restored data attributes for ${itemId}`);
            }

            // ✅ 3. Emit grid item restore với COMPLETE original data
            emitUpdateGridItem({
                id: itemId,
                left: originalState.left,
                top: originalState.top,
                width: originalState.originalWidth,
                height: originalState.height,
                zindex: originalState.zindex,
                rotation: originalState.rotation || 0,
                isRestore: true // Flag để grid biết đây là restore
            });

            restoredCount++;
        });

        console.log(`✅ Restored ${restoredCount} items to original state`);
    }

    /**
     * Reset state
     */
    reset(): void {
        console.log("🧹 Resetting auto layout state manager...");

        const itemCount = this.state.originalState.size;

        this.state = {
            isProcessing: false,
            isPreviewing: false,
            originalState: new Map(),
            previewChanges: null,
            heightPreview: null
        };

        console.log(`✅ Reset complete. Cleared ${itemCount} original states.`);
    }
    // ✅ NEW: Validate original state
    validateOriginalState(): boolean {
        if (!this.state.originalState.size) {
            console.error("❌ No original state found");
            return false;
        }

        let validCount = 0;
        this.state.originalState.forEach((state, itemId) => {
            if (itemId === "sectionHeight") return;

            if (
                state.left !== undefined &&
                state.top !== undefined &&
                state.width !== undefined &&
                state.height !== undefined
            ) {
                validCount++;
            } else {
                console.error(`❌ Invalid original state for ${itemId}:`, state);
            }
        });

        console.log(`✅ Validated ${validCount} original states`);
        return validCount > 0;
    }

    // ✅ NEW: Get original state for specific item
    getOriginalStateForItem(itemId: string) {
        return this.state.originalState.get(itemId);
    }
}

export class AutoLayoutProcessor {
    private config: AutoLayoutConfig;
    private readonly DEFAULT_CONFIG = {
        minGapPx: 20,
        minWidthPx: 50,
        maxWidthPercent: 95,
        minHeightPx: 30,
        verticalOverlapThreshold: 10,
        horizontalGapThreshold: 20,
        // Config mới cho mobile
        centerSingleItemsOnMobile: true,
        mobileWidthThreshold: 768,
        // Config mới cho full-width items - SỬA: Tính toán động dựa trên screen
        fullWidthItemsSpacing: 15,
        enableFullWidthOptimization: true
    };

    constructor(config: AutoLayoutConfig) {
        // SỬA: Tính toán fullWidthItemsSpacing dựa trên screen nếu không được cung cấp
        const isMobileScreen =
            config.screen === "mobile" ||
            config.screen === "sm" ||
            config.gridContainerWidth <= (config.mobileWidthThreshold || 768);

        const dynamicConfig = {
            ...this.DEFAULT_CONFIG,
            // Tính fullWidthItemsSpacing dựa trên screen và minGapPx
            fullWidthItemsSpacing:
                config.fullWidthItemsSpacing ||
                (config.minGapPx
                    ? Math.max(3, Math.floor(config.minGapPx * 0.6))
                    : isMobileScreen
                    ? 6
                    : 15),
            ...config
        };

        this.config = dynamicConfig;
    }

    /**
     * Kiểm tra có phải đang ở chế độ mobile không
     */
    private isMobileScreen(): boolean {
        return (
            this.config.screen === "mobile" ||
            this.config.screen === "sm" ||
            this.config.gridContainerWidth <= this.config.mobileWidthThreshold
        );
    }

    /**
     * Kiểm tra item có phải full-width không
     */
    private isFullWidthItem(item: LayoutItem): boolean {
        const widthPercent = (item.width / this.config.gridContainerWidth) * 100;
        return widthPercent >= 98 || item.width >= this.config.gridContainerWidth;
    }

    /**
     * Kiểm tra item có width vượt quá container không
     */
    private isOversizedItem(item: LayoutItem): boolean {
        const widthPercent = (item.width / this.config.gridContainerWidth) * 100;
        return widthPercent > 100 || item.width > this.config.gridContainerWidth;
    }

    /**
     * Hàm chính để thực hiện auto layout - CẢI TIẾN
     */
    public processAutoLayout(itemsData: LayoutItem[]): AutoLayoutResult {
        //console.log(`🎯 Starting enhanced auto layout for ${itemsData.length} items`);

        const layoutChanges = new Map<string, LayoutChange>();
        const fullWidthItems = new Set<string>();
        let maxBottomPosition = 0; // THÊM: Track vị trí bottom cuối cùng

        // **1. Xử lý items tràn ra ngoài container**
        this.fixOutOfBoundsItems(itemsData, layoutChanges);

        // **2. Xử lý items có kích thước bất thường**
        this.fixAbnormalSizedItems(itemsData, layoutChanges);

        // **3. XỬ LÝ FULL-WIDTH ITEMS TRƯỚC (TÍNH NĂNG MỚI) - SỬA**
        if (this.config.enableFullWidthOptimization) {
            maxBottomPosition = this.processFullWidthItems(
                itemsData,
                layoutChanges,
                fullWidthItems
            );
        }

        // **4. Reset z-index conflicts**
        //this.resetZIndexConflicts(itemsData, layoutChanges);

        // Sắp xếp theo top, sau đó theo left - NHƯNG XEP FULL-WIDTH ITEMS RIENG
        const regularItems = itemsData.filter((item) => !fullWidthItems.has(item.id));
        const fullWidthItemsList = itemsData.filter((item) => fullWidthItems.has(item.id));

        regularItems.sort((a, b) => {
            if (Math.abs(a.top - b.top) < 10) {
                return a.left - b.left;
            }
            return a.top - b.top;
        });

        // **5. Tìm các nhóm item bị đè lên nhau (overlap) - CHỈ CHO REGULAR ITEMS**
        const groups = this.findOverlapGroups(regularItems, fullWidthItemsList);
        const processedInGroups = new Set<string>();

        // Xử lý từng nhóm regular items
        groups.forEach((group) => {
            if (group.length > 1) {
                group.forEach((item) => processedInGroups.add(item.id));
                this.processItemGroup(group, layoutChanges, fullWidthItemsList);
            }
        });

        // **6. Xử lý các regular items có width >= 50% hoặc item đơn lẻ trên mobile**
        regularItems.forEach((item) => {
            if (processedInGroups.has(item.id) || fullWidthItems.has(item.id)) return;

            const widthPercent = (item.width / this.config.gridContainerWidth) * 100;

            // Logic căn giữa cho regular items
            const shouldCenter =
                widthPercent >= 50 ||
                (this.isMobileScreen() && this.config.centerSingleItemsOnMobile);

            if (shouldCenter) {
                const newLeft = (100 - widthPercent) / 2;
                // Kiểm tra không conflict với full-width items
                if (!this.conflictsWithFullWidthItems(item, newLeft, fullWidthItemsList)) {
                    this.addLayoutChange(layoutChanges, item.id, { left: Math.max(0, newLeft) });
                    // console.log(
                    //     `📱 Centering regular item ${item.id} on ${
                    //         this.config.screen
                    //     }: left=${newLeft.toFixed(2)}%`
                    // );
                }
            }
        });

        // **7. Optimize spacing và compact layout - CHỈ CHO REGULAR ITEMS**
        this.optimizeSpacing(regularItems, layoutChanges, processedInGroups, fullWidthItemsList);

        // **8. Kiểm tra và điều chỉnh conflicts cuối cùng**
        this.resolveConflictsWithFullWidthItems(itemsData, layoutChanges, fullWidthItems);

        // SỬA: Tính toán lại maxBottomPosition sau khi xử lý tất cả items
        itemsData.forEach((item) => {
            const changes = layoutChanges.get(item.id);
            const finalTop = changes?.top !== undefined ? changes.top : item.top;
            const finalHeight = changes?.height !== undefined ? changes.height : item.height;
            const itemBottom = finalTop + finalHeight;
            maxBottomPosition = Math.max(maxBottomPosition, itemBottom);
        });
        /*
        console.log(`🎯 Enhanced auto layout completed:`);
        console.log(`   - Total changes: ${layoutChanges.size}`);
        console.log(`   - Full-width items: ${fullWidthItems.size}`);
        console.log(`   - Regular items processed in groups: ${processedInGroups.size}`);
        console.log(`   - Max bottom position: ${maxBottomPosition}px`);
        */
        return {
            changes: layoutChanges,
            processedInGroups,
            fullWidthItems,
            maxBottomPosition // THÊM: Trả về max bottom position
        };
    }

    /**
     * XỬ LÝ FULL-WIDTH ITEMS - TÍNH NĂNG MỚI - SỬA
     */
    private processFullWidthItems(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: Set<string>
    ): number {
        //console.log("🔧 Processing full-width items...");

        // Tìm các full-width items
        const fullWidthItemsList = itemsData.filter(
            (item) => this.isFullWidthItem(item) || this.isOversizedItem(item)
        );

        if (fullWidthItemsList.length === 0) {
            //console.log("   No full-width items found");
            return 0;
        }

        // Sắp xếp full-width items theo top position
        fullWidthItemsList.sort((a, b) => a.top - b.top);

        let currentTop = 0;
        let maxBottomPosition = 0; // THÊM: Track vị trí bottom cuối cùng

        fullWidthItemsList.forEach((item, index) => {
            // Đánh dấu là full-width item
            fullWidthItems.add(item.id);

            // Tính toán vị trí mới
            const updates: LayoutChange = {
                left: 0, // Luôn để left = 0
                width: "100%" // Luôn set width = 100%
            };

            // Xử lý top position để tránh overlap - SỬA: Sử dụng spacing từ config
            if (index === 0) {
                // Item đầu tiên: giữ nguyên top hoặc set về 0 nếu âm
                currentTop = Math.max(0, item.top);
                updates.top = currentTop;
            } else {
                // Các items tiếp theo: đặt sau item trước đó với khoảng cách từ config
                const prevItem = fullWidthItemsList[index - 1];
                const prevItemHeight = this.getItemHeight(prevItem, layoutChanges);
                const spacing = this.config.fullWidthItemsSpacing; // SỬA: Lấy từ config
                currentTop = currentTop + spacing;
                updates.top = currentTop;

                //console.log(`   📏 Item ${item.id}: spacing=${spacing}px, prevHeight=${prevItemHeight}px, newTop=${currentTop}px`);
            }

            // Cập nhật currentTop cho item tiếp theo
            const currentItemHeight = this.getItemHeight(item, layoutChanges);
            currentTop = updates.top + currentItemHeight;

            // SỬA: Cập nhật maxBottomPosition
            maxBottomPosition = Math.max(maxBottomPosition, currentTop);

            this.addLayoutChange(layoutChanges, item.id, updates);

            // console.log(
            //     `   📏 Full-width item ${item.id}: left=0%, width=100%, top=${updates.top}px, height=${currentItemHeight}px`
            // );
        });

        //console.log(`✅ Processed ${fullWidthItemsList.length} full-width items, maxBottom=${maxBottomPosition}px`);
        return maxBottomPosition; // THÊM: Trả về vị trí bottom cuối cùng
    }

    /**
     * Lấy height của item (có thể từ layoutChanges hoặc original)
     */
    private getItemHeight(item: LayoutItem, layoutChanges: Map<string, LayoutChange>): number {
        const changes = layoutChanges.get(item.id);
        if (changes && changes.height !== undefined) {
            return typeof changes.height === "number" ? changes.height : item.height;
        }
        return item.height;
    }

    /**
     * Kiểm tra xem regular item có conflict với full-width items không
     */
    private conflictsWithFullWidthItems(
        item: LayoutItem,
        newLeft: number,
        fullWidthItems: LayoutItem[]
    ): boolean {
        for (const fullWidthItem of fullWidthItems) {
            // Kiểm tra overlap theo chiều dọc
            const itemBottom = item.top + item.height;
            const fullWidthBottom = fullWidthItem.top + fullWidthItem.height;

            const hasVerticalOverlap = item.top < fullWidthBottom && itemBottom > fullWidthItem.top;

            if (hasVerticalOverlap) {
                // console.log(
                //     `⚠️ Item ${item.id} conflicts with full-width item ${fullWidthItem.id}`
                // );
                return true;
            }
        }
        return false;
    }

    /**
     * Tìm các nhóm item bị đè lên nhau - CẢI TIẾN để tránh full-width items
     */
    private findOverlapGroups(
        regularItems: LayoutItem[],
        fullWidthItems: LayoutItem[]
    ): LayoutItem[][] {
        const rows = this.groupItemsByVerticalOverlap(regularItems, fullWidthItems);
        const groups: LayoutItem[][] = [];
        const processed = new Set<string>();

        // console.log(
        //     `🔍 Found ${rows.length} rows for regular items:`,
        //     rows.map((row) => row.length)
        // );

        rows.forEach((row, rowIndex) => {
            if (row.length > 1) {
                groups.push(row);
                row.forEach((item) => processed.add(item.id));
                //console.log(`📦 Row ${rowIndex + 1}: Created group with ${row.length} items`);
            } else {
                groups.push(row);
                processed.add(row[0].id);
                //console.log(`📦 Row ${rowIndex + 1}: Single item group`);
            }
        });

        regularItems.forEach((item) => {
            if (!processed.has(item.id)) {
                groups.push([item]);
                //console.log(`📦 Isolated item: ${item.id}`);
            }
        });

        return groups.filter((group) => group.length > 0);
    }

    /**
     * Nhóm items theo vertical overlap - CẢI TIẾN để tránh full-width items
     */
    private groupItemsByVerticalOverlap(
        regularItems: LayoutItem[],
        fullWidthItems: LayoutItem[]
    ): LayoutItem[][] {
        const rows: LayoutItem[][] = [];

        regularItems.forEach((item) => {
            // Kiểm tra xem item có conflict với full-width items không
            const conflictsWithFullWidth = this.conflictsWithFullWidthItems(
                item,
                item.left,
                fullWidthItems
            );

            if (conflictsWithFullWidth) {
                // Nếu conflict, tạo row riêng để xử lý đặc biệt
                rows.push([item]);
                // console.log(
                //     `⚠️ Item ${item.id} conflicts with full-width items, creating separate row`
                // );
                return;
            }

            let foundRow = false;

            for (let row of rows) {
                const hasVerticalOverlap = row.some((rowItem) => {
                    const item1Bottom = item.top + item.height;
                    const item2Bottom = rowItem.top + rowItem.height;

                    const overlapY = item.top < item2Bottom && item1Bottom > rowItem.top;
                    const nearbyY =
                        Math.abs(item.top - rowItem.top) <= this.config.verticalOverlapThreshold;

                    return overlapY || nearbyY;
                });

                if (hasVerticalOverlap) {
                    // Kiểm tra xem việc thêm item này vào row có gây conflict với full-width items không
                    const wouldConflictIfAdded = this.wouldRowConflictWithFullWidth(
                        [...row, item],
                        fullWidthItems
                    );

                    if (!wouldConflictIfAdded) {
                        row.push(item);
                        foundRow = true;
                        break;
                    }
                }
            }

            if (!foundRow) {
                rows.push([item]);
            }
        });

        return rows;
    }

    /**
     * Kiểm tra xem một row có conflict với full-width items không
     */
    private wouldRowConflictWithFullWidth(
        row: LayoutItem[],
        fullWidthItems: LayoutItem[]
    ): boolean {
        const rowTopMin = Math.min(...row.map((item) => item.top));
        const rowBottomMax = Math.max(...row.map((item) => item.top + item.height));

        return fullWidthItems.some((fullWidthItem) => {
            const fullWidthBottom = fullWidthItem.top + fullWidthItem.height;
            return rowTopMin < fullWidthBottom && rowBottomMax > fullWidthItem.top;
        });
    }

    /**
     * Xử lý một nhóm items - CẢI TIẾN để xem xét full-width items
     */
    private processItemGroup(
        group: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: LayoutItem[] = []
    ): void {
        if (group.length <= 1) return;

        const sortedGroup = [...group].sort((a, b) => a.left - b.left);
        //console.log(`🔧 Processing group of ${group.length} items`);

        // Kiểm tra xem group có conflict với full-width items không
        const groupConflictsWithFullWidth = this.wouldRowConflictWithFullWidth(
            sortedGroup,
            fullWidthItems
        );

        if (groupConflictsWithFullWidth) {
            //console.log(`⚠️ Group conflicts with full-width items, repositioning...`);
            this.repositionGroupAwayFromFullWidth(sortedGroup, layoutChanges, fullWidthItems);
            return;
        }

        const canFitInOneRow = this.canItemsFitInOneRow(sortedGroup);

        if (canFitInOneRow) {
            const avgTop = group.reduce((sum, item) => sum + item.top, 0) / group.length;
            this.distributeItemsEvenlyInRow(sortedGroup, avgTop, layoutChanges);
            //console.log(`✅ Distributed ${group.length} items in one row`);
        } else {
            const subRows = this.divideIntoSubRowsOptimal(sortedGroup);
            // console.log(
            //     `📊 Divided into ${subRows.length} sub-rows:`,
            //     subRows.map((row) => row.length)
            // );

            let currentTop = Math.min(...group.map((item) => item.top));

            // Đảm bảo currentTop không conflict với full-width items
            currentTop = this.findSafeTopPosition(currentTop, fullWidthItems);

            subRows.forEach((subRow, rowIndex) => {
                if (subRow.length === 1) {
                    const item = subRow[0];
                    const widthPercent = (item.width / this.config.gridContainerWidth) * 100;

                    let newLeft: number;
                    if (this.isMobileScreen() && this.config.centerSingleItemsOnMobile) {
                        newLeft = Math.max(0, (100 - widthPercent) / 2);
                        // console.log(
                        //     `📱 Mobile: Centering single item ${
                        //         item.id
                        //     }, width=${widthPercent.toFixed(1)}%, left=${newLeft.toFixed(2)}%`
                        // );
                    } else {
                        newLeft = widthPercent >= 50 ? (100 - widthPercent) / 2 : item.left;
                    }

                    this.addLayoutChange(layoutChanges, item.id, {
                        left: newLeft,
                        top: currentTop
                    });
                } else {
                    this.distributeItemsEvenlyInRow(subRow, currentTop, layoutChanges);
                }

                if (rowIndex < subRows.length - 1) {
                    const maxHeightInRow = Math.max(...subRow.map((item) => item.height));
                    currentTop += maxHeightInRow + this.config.minGapPx;
                    // Đảm bảo top position tiếp theo không conflict với full-width items
                    currentTop = this.findSafeTopPosition(currentTop, fullWidthItems);
                }
            });
        }
    }

    /**
     * Tìm vị trí top an toàn không conflict với full-width items
     */
    private findSafeTopPosition(preferredTop: number, fullWidthItems: LayoutItem[]): number {
        let safeTop = preferredTop;

        for (const fullWidthItem of fullWidthItems) {
            const fullWidthBottom = fullWidthItem.top + fullWidthItem.height;

            // Nếu preferredTop nằm trong vùng của full-width item
            if (preferredTop >= fullWidthItem.top && preferredTop <= fullWidthBottom) {
                safeTop = Math.max(safeTop, fullWidthBottom + this.config.fullWidthItemsSpacing);
            }
        }

        return safeTop;
    }

    /**
     * Repositioning group để tránh conflict với full-width items
     */
    private repositionGroupAwayFromFullWidth(
        group: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: LayoutItem[]
    ): void {
        // Tìm vị trí an toàn cho group
        const groupTop = Math.min(...group.map((item) => item.top));
        const safeTop = this.findSafeTopPosition(groupTop, fullWidthItems);

        // console.log(`🔄 Repositioning group from top=${groupTop} to safe top=${safeTop}`);

        // Di chuyển toàn bộ group đến vị trí an toàn
        const topOffset = safeTop - groupTop;

        group.forEach((item) => {
            this.addLayoutChange(layoutChanges, item.id, {
                top: item.top + topOffset
            });
        });

        // Sau đó xử lý group bình thường
        this.distributeItemsEvenlyInRow(group, safeTop, layoutChanges);
    }

    /**
     * Resolve conflicts cuối cùng giữa các items với full-width items
     */
    private resolveConflictsWithFullWidthItems(
        allItems: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: Set<string>
    ): void {
        // console.log("🔍 Resolving final conflicts with full-width items...");

        const regularItems = allItems.filter((item) => !fullWidthItems.has(item.id));
        const fullWidthItemsList = allItems.filter((item) => fullWidthItems.has(item.id));

        regularItems.forEach((item) => {
            const changes = layoutChanges.get(item.id);
            const currentTop = changes?.top !== undefined ? changes.top : item.top;
            const currentLeft = changes?.left !== undefined ? changes.left : item.left;

            // Kiểm tra conflict với từng full-width item
            for (const fullWidthItem of fullWidthItemsList) {
                const fullWidthChanges = layoutChanges.get(fullWidthItem.id);
                const fullWidthTop =
                    fullWidthChanges?.top !== undefined ? fullWidthChanges.top : fullWidthItem.top;
                const fullWidthHeight = this.getItemHeight(fullWidthItem, layoutChanges);
                const fullWidthBottom = fullWidthTop + fullWidthHeight;

                const itemBottom = currentTop + item.height;

                // Nếu có conflict
                if (currentTop < fullWidthBottom && itemBottom > fullWidthTop) {
                    // console.log(
                    //     `⚠️ Resolving conflict: ${item.id} vs full-width ${fullWidthItem.id}`
                    // );

                    // Di chuyển regular item xuống dưới full-width item
                    const newTop = fullWidthBottom + this.config.fullWidthItemsSpacing;
                    this.addLayoutChange(layoutChanges, item.id, { top: newTop });

                    console.log(`   Moved ${item.id} to top=${newTop}`);
                    break; // Chỉ cần resolve với full-width item đầu tiên gặp conflict
                }
            }
        });

        // console.log("✅ Resolved all conflicts with full-width items");
    }

    /**
     * Xử lý items tràn ra ngoài container
     */
    private fixOutOfBoundsItems(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>
    ): void {
        itemsData.forEach((item) => {
            const widthPercent = (item.width / this.config.gridContainerWidth) * 100;
            let updates: LayoutChange = {};

            // Fix left < 0
            if (item.left < 0) {
                updates.left = 0;
            }

            // Fix left + width > 100%
            if (item.left + widthPercent > 100) {
                const calculatedLeft = 100 - widthPercent;
                updates.left = Math.max(0, calculatedLeft);

                if (calculatedLeft < 0) {
                    const maxWidthPercent = this.config.maxWidthPercent;
                    const isPercent =
                        typeof item.originalWidth === "string" && item.originalWidth.includes("%");
                    const newWidth = isPercent
                        ? `${maxWidthPercent}%`
                        : `${(maxWidthPercent / 100) * this.config.gridContainerWidth}px`;

                    updates.width = newWidth;
                    updates.left = (100 - maxWidthPercent) / 2;
                }
            }

            // Fix top < 0
            if (item.top < 0) {
                updates.top = 0;
            }

            if (Object.keys(updates).length > 0) {
                this.addLayoutChange(layoutChanges, item.id, updates);
            }
        });
    }

    /**
     * Xử lý items có kích thước bất thường
     */
    private fixAbnormalSizedItems(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>
    ): void {
        itemsData.forEach((item) => {
            let updates: LayoutChange = {};

            // Fix width quá nhỏ
            if (item.width < this.config.minWidthPx) {
                const isPercent =
                    typeof item.originalWidth === "string" && item.originalWidth.includes("%");
                updates.width = isPercent
                    ? `${(this.config.minWidthPx / this.config.gridContainerWidth) * 100}%`
                    : `${this.config.minWidthPx}px`;
            }

            // Fix width quá lớn - NHƯNG KHÔNG XỬ LÝ CHO FULL-WIDTH ITEMS
            const widthPercent = (item.width / this.config.gridContainerWidth) * 100;
            if (widthPercent > this.config.maxWidthPercent && !this.isFullWidthItem(item)) {
                const isPercent =
                    typeof item.originalWidth === "string" && item.originalWidth.includes("%");
                const newWidth =
                    (this.config.maxWidthPercent / 100) * this.config.gridContainerWidth;
                updates.width = isPercent ? `${this.config.maxWidthPercent}%` : `${newWidth}px`;
                updates.left = (100 - this.config.maxWidthPercent) / 2;
            }

            // Fix height quá nhỏ
            if (item.height < this.config.minHeightPx) {
                updates.height = this.config.minHeightPx;
            }

            if (Object.keys(updates).length > 0) {
                this.addLayoutChange(layoutChanges, item.id, updates);
            }
        });
    }

    /**
     * Reset z-index conflicts
     */
    private resetZIndexConflicts(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>
    ): void {
        const highZIndexItems = itemsData.filter((item) => Number(item.zindex) > 10);

        if (highZIndexItems.length > 1) {
            highZIndexItems.sort((a, b) => Number(b.zindex) - Number(a.zindex));

            highZIndexItems.forEach((item, index) => {
                if (index > 0) {
                    this.addLayoutChange(layoutChanges, item.id, { zindex: "auto" });
                }
            });
        }
    }

    /**
     * Kiểm tra xem items có thể fit trong 1 hàng không
     */
    private canItemsFitInOneRow(items: LayoutItem[]): boolean {
        const totalItemWidthPx = items.reduce((sum, item) => sum + item.width, 0);
        const totalGapWidthPx = (items.length - 1) * this.config.minGapPx;
        const totalRequiredWidthPx = totalItemWidthPx + totalGapWidthPx;

        return totalRequiredWidthPx <= this.config.gridContainerWidth * 0.95;
    }

    /**
     * Chia items thành các hàng tối ưu
     */
    private divideIntoSubRowsOptimal(items: LayoutItem[]): LayoutItem[][] {
        const subRows: LayoutItem[][] = [];
        let remainingItems = [...items];

        while (remainingItems.length > 0) {
            let currentRow: LayoutItem[] = [];
            let currentRowWidthPx = 0;
            let i = 0;

            while (i < remainingItems.length) {
                const item = remainingItems[i];
                const gapWidthPx = currentRow.length > 0 ? this.config.minGapPx : 0;
                const requiredWidthPx = currentRowWidthPx + item.width + gapWidthPx;

                if (requiredWidthPx <= this.config.gridContainerWidth * 0.95) {
                    currentRow.push(item);
                    currentRowWidthPx = requiredWidthPx;
                    remainingItems.splice(i, 1);
                } else {
                    i++;
                }
            }

            if (currentRow.length === 0 && remainingItems.length > 0) {
                currentRow.push(remainingItems.shift()!);
            }

            if (currentRow.length > 0) {
                subRows.push(currentRow);
            }
        }

        return subRows;
    }

    /**
     * Dãn đều các items trong 1 hàng - CẢI TIẾN CHO MOBILE
     */
    private distributeItemsEvenlyInRow(
        items: LayoutItem[],
        topPosition: number,
        layoutChanges: Map<string, LayoutChange>
    ): void {
        if (items.length === 0) return;

        if (items.length === 1) {
            const item = items[0];
            const widthPercent = (item.width / this.config.gridContainerWidth) * 100;

            let centerLeft: number;
            if (this.isMobileScreen() && this.config.centerSingleItemsOnMobile) {
                centerLeft = Math.max(0, (100 - widthPercent) / 2);
                // console.log(
                //     `📱 Mobile single item: centering ${item.id} at ${centerLeft.toFixed(2)}%`
                // );
            } else {
                centerLeft = (100 - widthPercent) / 2;
            }

            this.addLayoutChange(layoutChanges, item.id, {
                left: centerLeft,
                top: topPosition
            });
            return;
        }

        // Xử lý nhiều items trong 1 hàng
        const totalItemWidthPx = items.reduce((sum, item) => sum + item.width, 0);
        const availableSpacePx = this.config.gridContainerWidth * 0.95 - totalItemWidthPx;
        const optimalGapPx = Math.max(this.config.minGapPx, availableSpacePx / (items.length - 1));

        const totalWidthWithGapsPx = totalItemWidthPx + (items.length - 1) * optimalGapPx;
        const startLeftPx = (this.config.gridContainerWidth - totalWidthWithGapsPx) / 2;
        const startLeftPercent = Math.max(0, (startLeftPx / this.config.gridContainerWidth) * 100);

        let currentLeftPercent = startLeftPercent;

        items.forEach((item, index) => {
            this.addLayoutChange(layoutChanges, item.id, {
                left: currentLeftPercent,
                top: topPosition
            });

            if (index < items.length - 1) {
                const itemWidthPercent = (item.width / this.config.gridContainerWidth) * 100;
                const gapPercent = (optimalGapPx / this.config.gridContainerWidth) * 100;
                currentLeftPercent += itemWidthPercent + gapPercent;
            }
        });
    }

    /**
     * Optimize spacing - CẢI TIẾN để tránh full-width items
     */
    private optimizeSpacing(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        processedInGroups: Set<string>,
        fullWidthItems: LayoutItem[]
    ): void {
        const unprocessedItems = itemsData.filter((item) => !processedInGroups.has(item.id));

        console.log(`🔧 Optimizing spacing for ${unprocessedItems.length} unprocessed items...`);

        // ✅ SỬA: Thay vì group theo rows, sắp xếp theo reading order và tìm vị trí optimal
        this.redistributeByReadingOrder(unprocessedItems, layoutChanges, fullWidthItems);
    }

    /**
     * MỚI: Phân bố lại items theo reading order
     */
    private redistributeByReadingOrder(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: LayoutItem[]
    ): void {
        console.log("📖 Redistributing items by reading order...");

        // 1. Sắp xếp items theo reading order (top-to-bottom, left-to-right)
        const sortedItems = [...itemsData].sort((a, b) => {
            const topDiff = a.top - b.top;
            if (Math.abs(topDiff) < this.config.verticalOverlapThreshold) {
                return a.left - b.left; // Cùng hàng: sắp xếp theo left
            }
            return topDiff; // Khác hàng: sắp xếp theo top
        });

        console.log(
            "📖 Sorted items by reading order:",
            sortedItems.map((item) => ({
                id: item.id,
                top: item.top,
                left: item.left
            }))
        );

        // 2. Tạo layout grid để track occupied spaces
        const layoutGrid = this.createLayoutGrid(fullWidthItems, layoutChanges);

        // 3. Đặt từng item theo thứ tự reading order
        let currentRow = 0;
        const processedItemsInOrder: LayoutItem[] = [];

        sortedItems.forEach((item, index) => {
            const optimalPosition = this.findOptimalPosition(
                item,
                layoutGrid,
                currentRow,
                processedItemsInOrder,
                fullWidthItems
            );

            if (optimalPosition) {
                // Cập nhật position cho item
                this.addLayoutChange(layoutChanges, item.id, {
                    left: optimalPosition.left,
                    top: optimalPosition.top
                });

                // Cập nhật layout grid
                this.markOccupiedSpace(layoutGrid, item, optimalPosition);

                // Track processed items
                processedItemsInOrder.push({
                    ...item,
                    left: optimalPosition.left,
                    top: optimalPosition.top
                });

                // Update current row if needed
                currentRow = Math.max(currentRow, optimalPosition.row);

                console.log(
                    `📖 Item ${item.id} placed at row ${
                        optimalPosition.row
                    }, left: ${optimalPosition.left.toFixed(1)}%, top: ${optimalPosition.top}px`
                );
            }
        });

        console.log("✅ Reading order redistribution completed");
    }

    /**
     * MỚI: Tạo layout grid để track occupied spaces
     */
    private createLayoutGrid(
        fullWidthItems: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>
    ) {
        const grid = {
            rows: new Map<
                number,
                { items: any[]; maxBottom: number; occupied: { left: number; right: number }[] }
            >(),
            fullWidthRows: new Set<number>()
        };

        // Thêm full-width items vào grid
        fullWidthItems.forEach((item) => {
            const changes = layoutChanges.get(item.id);
            const top = changes?.top !== undefined ? changes.top : item.top;
            const height = changes?.height !== undefined ? changes.height : item.height;
            const bottom = top + height;

            const rowIndex = Math.floor(top / 100); // Rough row calculation

            if (!grid.rows.has(rowIndex)) {
                grid.rows.set(rowIndex, { items: [], maxBottom: 0, occupied: [] });
            }

            const row = grid.rows.get(rowIndex)!;
            row.items.push({ item, top, bottom, isFullWidth: true });
            row.maxBottom = Math.max(row.maxBottom, bottom);

            // Mark entire row as occupied for full-width items
            grid.fullWidthRows.add(rowIndex);

            console.log(
                `🗂️ Added full-width item ${item.id} to row ${rowIndex}, bottom: ${bottom}px`
            );
        });

        return grid;
    }

    /**
     * MỚI: Tìm vị trí optimal cho item
     */
    private findOptimalPosition(
        item: LayoutItem,
        layoutGrid: any,
        currentRow: number,
        processedItems: LayoutItem[],
        fullWidthItems: LayoutItem[]
    ) {
        const itemWidthPercent = (item.width / this.config.gridContainerWidth) * 100;
        const minGap = this.config.minGapPx;
        const minGapPercent = (minGap / this.config.gridContainerWidth) * 100;

        console.log(
            `🔍 Finding optimal position for item ${item.id}, width: ${itemWidthPercent.toFixed(
                1
            )}%`
        );

        // 1. Thử fit vào current row trước
        for (let row = currentRow; row >= 0; row--) {
            const position = this.tryFitInRow(item, row, layoutGrid, processedItems, minGapPercent);
            if (position) {
                console.log(`   ✅ Found space in existing row ${row}`);
                return { ...position, row };
            }
        }

        // 2. Tìm row mới phù hợp (ưu tiên gần current row nhất)
        let targetRow = currentRow + 1;
        let targetTop = this.calculateNewRowTop(targetRow, layoutGrid, processedItems);

        // Kiểm tra conflict với full-width items
        while (this.conflictsWithFullWidthItemsAtPosition(targetTop, item.height, fullWidthItems)) {
            targetRow++;
            targetTop = this.calculateNewRowTop(targetRow, layoutGrid, processedItems);
        }

        // 3. Tính toán left position trong row mới
        let targetLeft: number;

        if (this.isMobileScreen() && this.config.centerSingleItemsOnMobile) {
            // Mobile: center single items
            targetLeft = Math.max(0, (100 - itemWidthPercent) / 2);
        } else if (itemWidthPercent >= 50) {
            // Large items: center
            targetLeft = Math.max(0, (100 - itemWidthPercent) / 2);
        } else {
            // Small items: start from left
            targetLeft = 0;
        }

        console.log(
            `   ✅ Creating new row ${targetRow} at top: ${targetTop}px, left: ${targetLeft.toFixed(
                1
            )}%`
        );

        return {
            left: targetLeft,
            top: targetTop,
            row: targetRow
        };
    }

    /**
     * MỚI: Thử fit item vào một row cụ thể
     */
    private tryFitInRow(
        item: LayoutItem,
        rowIndex: number,
        layoutGrid: any,
        processedItems: LayoutItem[],
        minGapPercent: number
    ) {
        const itemWidthPercent = (item.width / this.config.gridContainerWidth) * 100;

        // Không fit vào full-width rows
        if (layoutGrid.fullWidthRows.has(rowIndex)) {
            return null;
        }

        // Lấy các items đã được đặt trong row này
        const itemsInRow = processedItems.filter((processedItem) => {
            const rowTop = rowIndex * 100; // Rough calculation
            const rowBottom = (rowIndex + 1) * 100;
            return processedItem.top >= rowTop && processedItem.top < rowBottom;
        });

        if (itemsInRow.length === 0) {
            // Row trống - đặt item vào giữa hoặc trái tùy theo config
            const targetLeft =
                this.isMobileScreen() && this.config.centerSingleItemsOnMobile
                    ? Math.max(0, (100 - itemWidthPercent) / 2)
                    : itemWidthPercent >= 50
                    ? Math.max(0, (100 - itemWidthPercent) / 2)
                    : 0;

            const targetTop = this.calculateRowTop(rowIndex, layoutGrid, processedItems);

            return { left: targetLeft, top: targetTop };
        }

        // Kiểm tra xem có thể fit thêm item vào row không
        const occupiedSpaces = itemsInRow
            .map((processedItem) => {
                const processedWidthPercent =
                    (processedItem.width / this.config.gridContainerWidth) * 100;
                return {
                    left: processedItem.left,
                    right: processedItem.left + processedWidthPercent
                };
            })
            .sort((a, b) => a.left - b.left);

        // Tìm gap phù hợp
        let availableLeft = 0;

        for (const occupied of occupiedSpaces) {
            const availableWidth = occupied.left - availableLeft;

            if (availableWidth >= itemWidthPercent + minGapPercent) {
                // Tìm thấy gap phù hợp
                const targetTop = this.calculateRowTop(rowIndex, layoutGrid, processedItems);
                return { left: availableLeft, top: targetTop };
            }

            availableLeft = occupied.right + minGapPercent;
        }

        // Kiểm tra space cuối row
        const remainingWidth = 100 - availableLeft;
        if (remainingWidth >= itemWidthPercent) {
            const targetTop = this.calculateRowTop(rowIndex, layoutGrid, processedItems);
            return { left: availableLeft, top: targetTop };
        }

        return null; // Không fit được
    }

    /**
     * MỚI: Tính toán top position cho row
     */
    private calculateRowTop(
        rowIndex: number,
        layoutGrid: any,
        processedItems: LayoutItem[]
    ): number {
        if (rowIndex === 0) return 0;

        // Tìm item có bottom cao nhất trong row trước đó
        let maxBottom = 0;

        // Kiểm tra processed items
        processedItems.forEach((item) => {
            const itemBottom = item.top + item.height;
            const itemRowIndex = Math.floor(item.top / 100);

            if (itemRowIndex < rowIndex) {
                maxBottom = Math.max(maxBottom, itemBottom);
            }
        });

        // Kiểm tra full-width items
        if (layoutGrid.rows.has(rowIndex - 1)) {
            const prevRow = layoutGrid.rows.get(rowIndex - 1);
            maxBottom = Math.max(maxBottom, prevRow.maxBottom);
        }

        return maxBottom + this.config.minGapPx;
    }

    /**
     * MỚI: Tính toán top cho row mới
     */
    private calculateNewRowTop(
        rowIndex: number,
        layoutGrid: any,
        processedItems: LayoutItem[]
    ): number {
        let maxBottom = 0;

        // Tìm bottom cao nhất từ tất cả items và full-width items
        processedItems.forEach((item) => {
            const itemBottom = item.top + item.height;
            maxBottom = Math.max(maxBottom, itemBottom);
        });

        // Kiểm tra full-width items
        layoutGrid.rows.forEach((row: any) => {
            maxBottom = Math.max(maxBottom, row.maxBottom);
        });

        return maxBottom + this.config.minGapPx;
    }

    /**
     * MỚI: Mark occupied space trong layout grid
     */
    private markOccupiedSpace(
        layoutGrid: any,
        item: LayoutItem,
        position: { left: number; top: number; row: number }
    ) {
        const { row } = position;
        const itemWidthPercent = (item.width / this.config.gridContainerWidth) * 100;

        if (!layoutGrid.rows.has(row)) {
            layoutGrid.rows.set(row, { items: [], maxBottom: 0, occupied: [] });
        }

        const gridRow = layoutGrid.rows.get(row)!;
        gridRow.items.push({
            item,
            left: position.left,
            right: position.left + itemWidthPercent,
            top: position.top,
            bottom: position.top + item.height
        });

        gridRow.maxBottom = Math.max(gridRow.maxBottom, position.top + item.height);

        gridRow.occupied.push({
            left: position.left,
            right: position.left + itemWidthPercent
        });
    }

    /**
     * Nhóm items theo hàng
     */
    private groupItemsByRows(itemsData: LayoutItem[]): LayoutItem[][] {
        const rows: LayoutItem[][] = [];
        const SAME_ROW_THRESHOLD = 20;

        itemsData.forEach((item) => {
            let foundRow = false;

            for (let row of rows) {
                const avgRowTop = row.reduce((sum, r) => sum + r.top, 0) / row.length;
                if (Math.abs(item.top - avgRowTop) <= SAME_ROW_THRESHOLD) {
                    row.push(item);
                    foundRow = true;
                    break;
                }
            }

            if (!foundRow) {
                rows.push([item]);
            }
        });

        return rows;
    }

    /**
     * Phân bố lại spacing trong một hàng
     */
    private redistributeRowSpacing(
        row: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>
    ): void {
        if (row.length <= 2) return;

        const GAP = this.isMobileScreen() ? 10 : 15;
        const totalItemWidth = row.reduce((sum, item) => sum + item.width, 0);
        const totalGapWidth = (row.length - 1) * GAP;
        const totalRequiredWidth = totalItemWidth + totalGapWidth;

        if (totalRequiredWidth <= this.config.gridContainerWidth) {
            const startLeft =
                ((this.config.gridContainerWidth - totalRequiredWidth) /
                    2 /
                    this.config.gridContainerWidth) *
                100;
            let currentLeft = Math.max(0, startLeft);

            row.forEach((item) => {
                this.addLayoutChange(layoutChanges, item.id, { left: currentLeft });
                const itemWidthPercent = (item.width / this.config.gridContainerWidth) * 100;
                const gapPercent = (GAP / this.config.gridContainerWidth) * 100;
                currentLeft += itemWidthPercent + gapPercent;
            });
        }
    }

    /**
     * Compact vertical spacing - CẢI TIẾN để tránh full-width items
     */
    private compactVerticalSpacing(
        itemsData: LayoutItem[],
        layoutChanges: Map<string, LayoutChange>,
        fullWidthItems: LayoutItem[]
    ): void {
        console.log("📏 Compacting vertical spacing with reading order...");

        // Lấy tất cả items sau khi đã có changes
        const allItemsWithChanges = itemsData.map((item) => {
            const changes = layoutChanges.get(item.id);
            return {
                ...item,
                left: changes?.left !== undefined ? changes.left : item.left,
                top: changes?.top !== undefined ? changes.top : item.top,
                width:
                    changes?.width !== undefined
                        ? typeof changes.width === "string" && changes.width.includes("%")
                            ? (parseFloat(changes.width) / 100) * this.config.gridContainerWidth
                            : parseFloat(changes.width.toString())
                        : item.width,
                height: changes?.height !== undefined ? changes.height : item.height
            };
        });

        // Sắp xếp theo reading order
        const sortedItems = allItemsWithChanges.sort((a, b) => {
            const topDiff = a.top - b.top;
            if (Math.abs(topDiff) < this.config.verticalOverlapThreshold) {
                return a.left - b.left;
            }
            return topDiff;
        });

        // Compact từ trên xuống dưới
        let currentTop = 0;
        const minGap = this.config.minGapPx;

        // Group items by approximate rows first
        const rows: LayoutItem[][] = [];
        let currentRowItems: LayoutItem[] = [];
        let currentRowTop = -1;

        sortedItems.forEach((item) => {
            if (
                currentRowTop === -1 ||
                Math.abs(item.top - currentRowTop) <= this.config.verticalOverlapThreshold
            ) {
                // Same row
                currentRowItems.push(item);
                currentRowTop = currentRowTop === -1 ? item.top : currentRowTop;
            } else {
                // New row
                if (currentRowItems.length > 0) {
                    rows.push([...currentRowItems]);
                }
                currentRowItems = [item];
                currentRowTop = item.top;
            }
        });

        // Add last row
        if (currentRowItems.length > 0) {
            rows.push(currentRowItems);
        }

        // Compact each row
        rows.forEach((row, rowIndex) => {
            // Tìm safe top position cho row này
            const safeTop = this.findSafeTopPosition(currentTop, fullWidthItems);
            const actualTop = Math.max(currentTop, safeTop);

            // Đặt tất cả items trong row tại top position này
            row.forEach((item) => {
                if (item.top !== actualTop) {
                    this.addLayoutChange(layoutChanges, item.id, { top: actualTop });
                }
            });

            // Cập nhật currentTop cho row tiếp theo
            const maxHeightInRow = Math.max(...row.map((item) => item.height));
            currentTop = actualTop + maxHeightInRow + minGap;

            console.log(
                `📏 Row ${rowIndex + 1}: ${
                    row.length
                } items at top ${actualTop}px, next top: ${currentTop}px`
            );
        });

        console.log("✅ Vertical spacing compacted with reading order preserved");
    }

    /**
     * Helper function để thêm thay đổi layout
     */
    private addLayoutChange(
        layoutChanges: Map<string, LayoutChange>,
        itemId: string,
        changes: LayoutChange
    ): void {
        if (!layoutChanges.has(itemId)) {
            layoutChanges.set(itemId, {});
        }
        // console.log('Adding layout change for item:', itemId, changes);

        const existingChanges = layoutChanges.get(itemId)!;
        Object.assign(existingChanges, changes);
    }
}

/**
 * Hàm chính để gọi từ component
 */
export function processAutoLayout(
    itemsData: LayoutItem[],
    config: AutoLayoutConfig
): AutoLayoutResult {
    const processor = new AutoLayoutProcessor(config);
    return processor.processAutoLayout(itemsData);
}
