{
    "en": {
        "no_results": "No results",
        "load_more": "Load more",
        "the_uploaded_file_is_being_processed_in_the_background": "The uploaded file is being processed in the background",
        "they_may_take_a_few_minutes": "They may take a few minutes to appear in your file list. Refresh to fetch new items"
    },
    "fr": {
        "no_results": "Pas de résultats",
        "load_more": "Charger plus",
        "the_uploaded_file_is_being_processed_in_the_background": "Le fichier téléchargé est en cours de traitement en arrière-plan",
        "they_may_take_a_few_minutes": "Ils peuvent prendre quelques minutes pour apparaître dans votre liste de fichiers. Actualisez pour obtenir de nouveaux éléments"
    },
    "de": {
        "no_results": "Keine Ergebnisse",
        "load_more": "Mehr laden",
        "the_uploaded_file_is_being_processed_in_the_background": "Die hochgeladene Datei wird im Hintergrund verarbeitet",
        "they_may_take_a_few_minutes": "Es kann einige Minuten dauern, bis sie in Ihrer Dateiliste angezeigt werden. Aktualisieren Sie, um neue Elemente abzurufen"
    },
    "ja": {
        "no_results": "結果がありません",
        "load_more": "さらに読み込む",
        "the_uploaded_file_is_being_processed_in_the_background": "アップロードされたファイルはバックグラウンドで処理中です",
        "they_may_take_a_few_minutes": "数分かかる場合があります。新しいアイテムを取得するには更新してください"
    }
}
</i18n>
<template>
  <template v-if="type == 'image' && tab == 'ai'">
    <AIContent
      :list="getlist"
      :selected-images="value"
      :initial-mode="options?.aiMode"
      @upload="upload"
      @switchTab="$emit('switchTab', $event)"
    />
  </template>
  <template v-else>
    <Loading v-if="isLoading && type === 'product'" type="products" class="bg-white   p-3 rounded text-gray-700 bg-opacity-90" />
    <div
        v-else-if="isLoading"
        class="block z-1"
    >
        <Loading type="spin" class="bg-white   p-3 rounded text-gray-700 bg-opacity-90" />
  </div>
    <ul
        v-else
        ref="list"
        class="flex flex-wrap w-full max-h-full overflow-y-auto text-sm px-1"
        :class="{'py-2 px-2.5' : layout == 'grid', 'list-items' : layout == 'list'}"
        @scroll.passive="eventChange"
    >
        <component
            :is="type === 'icon' ? 'IconContent' : (['language', 'country'].includes(type) ? 'ItemContent' : (isFreeImgCat ? 'ItemCategory' : 'ItemContent'))"
            v-for="item in getlist"
            :key="item.id"
            :item="item"
            :value="value"
            :layout="['language', 'country'].includes(type) ? 'list' : layout"
            :type="type"
            :options="options"
            v-model:compress="compress"
            @replace-image="replaceImage"
            @upload="upload"
            @remove="remove"
            @toggleItem="toggleItem"
            @reload="reloadPicker"
            @clickSelect="$emit('clickSelect')"
            @loadFreeImg="loadFreeImg"
            @closePopup="$emit('closePopup')"
        />
        <li v-if="isEmpty" class="w-full text-center text-xs my-4">
            <span class="text-xs">{{ $t('no_results') }}</span>
        </li>
        <li
            v-if="isNext && !isLoading && !isEmpty"
            class="w-full mx-auto mt-3 mb-5 text-center"
            :class="{'px-1': layout == 'grid'}"
        >
            <s-button
                variant="secondary"
                @click="getData(true)"
                :loading="isLoadingMore"
            >
                {{ $t('load_more') }}
            </s-button>
        </li>
        <link
            v-if="url.length"
            :href="url"
            rel="stylesheet"
        >
    </ul>
  </template>
</template>

<script lang="ts">
    import { mapGetters } from 'vuex';

    import ItemContent from './PickerItemContent.vue';
    import IconContent from './PickerIconContent.vue';
    import ItemCategory from './PickerCategory.vue';
    import AIContent from './PickerAIContent.vue';
    import { fileMixin } from '../../mixins';
    import { upload, remove } from '../../utils';
    export default {
        name: 'PickerContent',
        components: {
            ItemContent,
            IconContent,
            ItemCategory,
            AIContent,
        },
        mixins: [ fileMixin ],
        emits: ['clickSelect', 'closePopup', 'switchTab', 'toggleItem'],
        props: {
            show: {
                type: Boolean,
                default: false,
            },
            search: {
                type: String,
                default: '',
            },
            filter: {
                type: Object,
                default: () => ({})
            },
            sort: {
                type: String,
                default: 'asc',
            },
            value: {
                type: Array,
                default () {
                    return [];
                },
            },
            multiple: {
                type: Boolean,
                default: false,
            },
            responsive: {
                type: Boolean,
                default: false,
            },
            type: {
                type: String,
                default: 'menu',
            },
            layout: {
                type: String,
                default: 'grid',
            },
            tab: {
                type: String,
                default: '',
            },
            options: {
                type: Object,
                default() {
                    return {};
                }
            },
            values: {
                type: Array,
                default() {
                    return [];
                }
            }
        },
        data () {
            return {
                init: false,
                data: {
                    init: false,
                    list: [] as any[]
                },
                compress: false,
                // Own loading state. The picker store keeps a single global
                // `loading` object shared by every picker, and whichever fetch
                // resolves first wipes it for all of them (ImagePickerFilter
                // fetches products in parallel with this list) — which would
                // flash "No results" here while our own fetch is still running.
                localLoading: false,
                localLoadingMore: false,
                processingPoll: null,
                processingTries: 0,
                no_replace_image: false,
                $list: null,
                aiUploadings: {} as Record<string, number>
            };
        },
        computed: {
            ...mapGetters('global', ['configIcons']),
            ...mapGetters('picker', { 'pickerData': 'data' }),
            ...mapGetters('picker', ['isLoadmore', 'scrollTop', 'loading', 'freeImgCat']),
            ...mapGetters('builder', ['screen']),
            isTinify() {
                return !!this.$store.getters['global/configs']?.tinify?.enable;
            },
            isLoading() {
                return this.localLoading;
            },
            isLoadingMore() {
                return this.localLoadingMore;
            },
            getlist() {
                return this.data.list.filter(item => item != null);
            },
            isNext () {
                if (['language', 'country'].includes(this.type)) {
                    return false; // Language type không có loadmore
                }
                return this.isFreeImgCat ? false : this.isLoadmore(this.type, this.tab);
            },
            isFreeImgCat () {
                return !this.freeImgCat && this.tab == 'free' && !this.search
            },
            valueComp () {
                return this.value;
            },
            url () {
                if (this.type == 'font' && this.tab == 'google') {
                    if (this.data.list.length) {
                        return 'https://fonts.googleapis.com/css2?' +
                            this.data.list
                                .map(item => {
                                    return 'family=' + item.name.replace(/\s/g, '+');
                                }).join('&');
                    }
                }
                return '';
            },
            isEmpty(){
                // The "uploaded" tab always carries a synthetic upload tile, so
                // the list is never literally empty there — a search with no
                // match still leaves that one item behind. Count real entries
                // only, otherwise the empty state never shows.
                return !this.getlist.filter(item => item.fn !== 'upload').length;
            }
        },
        watch: {
            show: function (val) {
                if (val) {
                    if (!this.init && !this.localLoading) {
                        this.getData();
                    }
                    this.setScroll();
                    this.eventChange();

                }
            },
            search: function (val) {
                if(val === '') {
                    this.reloadPicker();
                } else {
                    this.getData();
                }

            },
            filter: {
                handler: function (val) {
                    this.getData(false, true);
                },
                deep: true
            },
            sort: function (val) {
                if(val === '') {
                    this.reloadPicker();
                } else {
                    this.getData();
                }
            },
            isLoading: function (val) {
                if (!val) {
                    this.reinitScroll();
                }
            },
            tab: function () {
                this.reinitScroll();
            },
            isTinify: {
                immediate: true,
                handler(val) {
                    this.compress = val;
                }
            },
        },
        created () {
            if (this.show && !this.init) {
                this.getData();
                this.init = true;
            }
        },
        beforeUnmount () {
            clearTimeout(this.processingPoll);
        },
        methods: {
            replaceImage(data) {
                this.no_replace_image = data;
            },
            loadFreeImg(cat) {
                this.$store.commit('picker/freeImgCat', cat);
                this.getData(false, false);
            },
            loadFreeCat() {
                this.getData(false, false);
            },
            fileName (data) {
                let name = this.$helpers.file.name(data);
                return name ? name : data;
            },
            reinitScroll () {
                this.$nextTick(() => {
                    this.$list = this.$refs.list;
                    this.setScroll();
                    this.eventChange();
                });
            },
            isActive (value) {
                return this.value.findIndex(v => {
                    v = this.type === 'image' ?
                                this.currentImage(this.type, v, false) :
                                v.value;
                    return v === value;
                });
            },
            setScroll () {
                this.$list &&
                    (this.$list.scrollTop = this.scrollTop({
                        type: this.type,
                        subtype: this.tab,
                        layout: this.layout
                    }));
            },
            reload () {
                // this.$list &&
                //     (this.$list.scrollTop = 0);

                this.getData(false, true);
            },
            /**
             * Shopify finishes a file after the upload call returns — a video has
             * to transcode first — and there is no webhook for it here, so the
             * only way to learn it is ready is to ask again. Back off between
             * tries and give up after a minute; the reload button is still there.
             */
            pollWhileProcessing() {
                clearTimeout(this.processingPoll);

                const processing = this.data.list.some(item => item && item.processing);
                if (!processing) {
                    this.processingTries = 0;
                    return;
                }
                // 2s, 4s, 8s then 15s each — about two and a half minutes, which
                // covers a large video transcoding. One cheap request per tick,
                // and it stops the moment nothing is processing.
                if (this.processingTries >= 12) {
                    return;
                }

                const delay = Math.min(2000 * Math.pow(2, this.processingTries), 15000);
                this.processingTries++;
                this.processingPoll = setTimeout(() => {
                    // same reset as reloadPicker(), so the refetch starts from the
                    // first page where a just-uploaded file sits, but without the
                    // spinner taking the grid away mid-look
                    this.$store.dispatch('picker/reload', {
                        type: this.type,
                        subtype: this.tab
                    });
                    this.getData(false, true, true);
                }, delay);
            },
            reloadPicker() {
                this.$store.dispatch('picker/reload', {
                    type: this.type,
                    subtype: this.tab
                });
                this.reload();
            },
            getData (loadmore = false, reload = false, silent = false) {
                if (silent) {
                    // a background poll must not pull the list out from under
                    // the merchant while they are looking at it
                } else if (loadmore) {
                    this.localLoadingMore = true;
                } else {
                    this.localLoading = true;
                }
                let subtype = this.tab;
                if (this.type === 'icon' && this.tab === 'system') {
                    subtype = {
                        system: Object.keys(this.configIcons)
                    };
                }

                if(this.isFreeImgCat && !this.search) {
                    subtype = 'freeImgCat';
                }

                if (this.type === 'image' && this.tab === 'ai') {
                    subtype = 'uploaded';
                }

                if (this.type === 'language') {
                    subtype = 'language';
                }
                if (this.type === 'country') {
                    subtype = 'country';
                }

                // language type không cần fetch, chỉ lấy từ values
                if (['language', 'country'].includes(this.type)) {
                    // Format values thành cấu trúc phù hợp
                    const languageItems = this.values.map((item: any, index) => ({
                        id: item.value || `language_${index}`,
                        fn: 'item',
                        name: item.label || item.name || `Item ${index + 1}`,
                        value: item.value || `language_${index}`,
                        thumbnail: item.flag || '',
                        url: '',
                        brand: 'language',
                        cate: 'default'
                    }));
                    // Filter theo search nếu có
                    const filteredItems = this.search ?
                        languageItems.filter(item =>
                            item.name.toLowerCase().includes(this.search.toLowerCase())
                        ) : languageItems;

                    this.data.list = [...filteredItems];
                    this.localLoading = false;
                    this.localLoadingMore = false;
                    this.$store.dispatch('picker/removeLoading');
                    this.init = true;
                    this.eventChange();
                    return;
                }

                let res = this
                    .pickerData(
                        this.type,
                        subtype,
                        this.search,
                        this.filter,
                        loadmore,
                        reload,
                        this.sort
                    );

                res.then((data) => {
                    if(data.status === 'error')
                    {
                        throw new Error(data.message);
                    }
                    if (loadmore) {
                        this.data.list
                            .splice(
                                this.data.list.length,
                                0,
                                ...data
                            );
                    } else {
                        this.data.list
                            .splice(
                                0,
                                this.data.list.length,
                                ...data
                            );
                    }
                    if(reload && this.$list) {
                        setTimeout(() => {
                            this.$list.scrollTop = 0;
                        });
                    }
                    this.localLoading = false;
                    this.localLoadingMore = false;
                    this.$store.dispatch('picker/removeLoading');
                    this.init = true;
                    this.eventChange();
                    this.pollWhileProcessing();

                })
                .catch(e=>{
                    this.localLoading = false;
                    this.localLoadingMore = false;
                    this.$store.commit('global/setToast', {
                        isError: true,
                        message: e.message,
                        data: e,
                        duration: 4000
                    });
                })

            },
            removeItem (value) {
                let res = this.valueComp.filter((x) => {
                    return x.value != value;
                });
                this.valueComp = res;
            },
            searchItem (id) {
                return this.getlist.filter(x => x.id == id)?.[0] ?? false;
            },
            toggleItem (data) {
                // Nếu data là object {item, tab} từ AI, chúng ta truyền tiếp lên cho Picker.vue xử lý chuyển tab
                if (data && data.item && data.tab === 'ai-edit') {
                    this.$emit('toggleItem', data);
                    return;
                }

                // Các trường hợp khác xử lý như chọn ảnh bình thường
                const targetItem = data.item || data;
                let { id, name, ext, cate, thumbnail, value, reload, loading, url, width, height, alt } = targetItem;

                // A file Shopify is still transcoding has no URL behind it yet,
                // and one it failed on never will.
                if (reload || loading || targetItem.processing || targetItem.failed) {
                    return;
                }
                let kValue = 'value',
                    kThumb = 'thumbnail';
                let item = { id, name };
                if(ext) {
                    item.ext = ext;
                }
                if(cate) {
                    item.cate = cate;
                }
                if(url) {
                    item.url = url;
                }
                item.width = width;
                item.height = height;
                item.alt = alt;
                if(this.responsive && !this.multiple) {
                    console.log('PickerContent.vue - Normal selection: Entering responsive mode');
                    if (this.screen !== 'desktop') {
                        kValue += '__' + this.screen;
                        kThumb += '__' + this.screen;
                    }
                    let v = this.valueComp[0];
                    console.log('PickerContent.vue - Current valueComp[0]:', v);
                    if(v) {
                        console.log('PickerContent.vue - Updating existing responsive item');
                        if(width) {
                            v.width = width;
                        }
                        if(height) {
                            v.height = height;
                        }
                        if(v[kValue] === value) {
                            delete v[kValue];
                            delete v[kThumb];
                        }
                        else {
                            if(this.screen === 'desktop') {
                                v.name = name;
                                v.alt = alt;
                            }
                            v[kValue] = value;
                            v[kThumb] = value;
                        }
                    }
                    else {
                        console.log('PickerContent.vue - Adding new responsive item');
                        item[kValue] = value;
                        item[kThumb] = value;
                        this.valueComp.push(item);
                    }
                }
                else {
                    console.log('PickerContent.vue - Normal selection: Entering default mode (non-responsive or multiple)');
                    item.value = value;
                    item.thumbnail = thumbnail;
                    let isActive = this.isActive(value);
                    console.log('PickerContent.vue - isActive result:', isActive);
                    if (isActive > -1) {
                        console.log('PickerContent.vue - Normal selection: Removing active item at index', isActive);
                        this.valueComp.splice(isActive, 1);
                    } else {
                        if (this.multiple) {
                            console.log('PickerContent.vue - Normal selection: Adding item (multiple mode)');
                            this.valueComp.push(item);
                        } else {
                            this.valueComp.splice(0, this.valueComp.length, item);
                        }
                    }
                }
            },
            deleteItem (id) {
                this.data.list = this.getlist
                    .filter(x => x.id != id);
            },
            editItem (id, data, add = false) {
                let items = this.getlist.filter(x => x.id == id);
                if (items.length) {
                    items.forEach(el => {
                        Object.keys(data).forEach(key => {
                            el[key] = data[key];
                        });
                        if (add) {
                            this.toggleItem(el);
                        }
                    });
                }
            },
            async upload (e, payload?: {id?: string, from?: string}, onComplete?: () => void, onError?: () => void) {
                let edit = false, files = [];
                if(e.dest) {
                    edit = true;
                    files = [e.dest];
                }
                else {
                    files = Array.from(e.target.files);
                }

                if (files.length) {
                    for (let i = 0; i < files.length; i++) {
                        let file = files[i] as File;
                        let id = this.$helpers.makeId(10);
                        if ('string' === typeof payload?.id && payload.id.trim()) {
                            id = payload.id;
                        }

                        let newItem = {
                            id,
                            fn: 'item',
                            loading: true,
                            name: file.name,
                            value: URL.createObjectURL(file),
                            thumbnail: URL.createObjectURL(file),
                        };
                        this.data.list.splice(1, 0, newItem);
                        this.eventChange();
                        let onUploadProgress = (e) => {
                            let { loaded, total } = e;
                            let per = Math.round(loaded / total * 100) + '%';
                            this.editItem(id, { per });
                        };
                        // check no replace image (admin) and replace name
                        let newFile = null;
                        if(this.no_replace_image && !edit) {
                            let id1 = this.$helpers.makeId(10);
                            const newName = 'ecom-no-replace-' + id1 + file.name; // Set the new file name here
                            newFile = new File([file], newName, { type: file.type });
                        }
                        // Rename image eidt
                        if(edit) {
                            let id2 = this.$helpers.makeId(10);
                            const newName = 'ecom-edit-image' + id2 + file.name; // Set the new file name here
                            newFile = new File([file], newName, { type: file.type });
                        }
                        let fileUpload = newFile ? newFile : file;
                        let res = await upload({type: this.type, file:fileUpload, compress: payload?.from === 'ai' ? true : this.compress}, onUploadProgress, this);
                        if (res.status === 'success') {
                            let subtype = this.tab;
                            if (payload?.from === 'ai') {
                                subtype = 'uploaded';
                            }
                            setTimeout(()=>{
                                // `reload` still drives the icon and category
                                // refresh paths; `processing` is what the item
                                // grid and the poll below read, so the tile shows
                                // "processing" and refreshes itself until Shopify
                                // hands back the real file.
                                this.editItem(id,
                                    {
                                        loading: false,
                                        reload: true,
                                        processing: true
                                    }
                                );
                                this.pollWhileProcessing();
                                this.$store
                                    .dispatch(
                                        'picker/addFirst',
                                        {
                                            type: this.type,
                                            subtype,
                                            item: this.searchItem(id)
                                        }
                                    );
                                if(res.status === 'success') {
                                    this.$store.commit('global/setToast', {
                                        message: this.type != 'image' ? this.$t('they_may_take_a_few_minutes') : res.message,
                                        data: res,
                                        duration: 4000
                                    }, { root: true });
                                    if (payload?.from === 'ai') {
                                        this.getData(false, true);
                                    }
                                    if (i === files.length - 1 && 'function' === typeof onComplete) {
                                        onComplete();
                                    }
                                }
                                else {
                                    if ('function' === typeof onError) {
                                        onError();
                                    }
                                    throw new Error(res.message ?? this.$t("unknown_error"));
                                }
                            },3000)
                        } else {
                            if ('function' === typeof onError) {
                                onError();
                            }
                            if(res.message) {
                                this.$store.commit('global/setToast', {
                                    isError: true,
                                    message: res.message,
                                    data: res,
                                    duration: 4000
                                },{ root: true });
                            }
                            this.deleteItem(id);
                        }
                    }
                    if(!edit) e.target.value = '';
                }
            },
            remove(item) {
                const checkID = this.value.some(el=>el.id === item.id);
                if(checkID){
                    this.toggleItem(item.id);
                }
                let { id, removing } = item;
                if(removing) {
                    return;
                }
                item.removing = true;
                remove(id, this).then(res => {
                    if(res.status === 'success') {
                        let i = this.data.list.findIndex(d => d.id === id);
                        this.data.list.splice(i, 1);
                        this.$store.dispatch('picker/removeItem',
                            {
                                type: this.type,
                                id
                            }
                        );
                    }
                    else {
                        item.removing = false;
                    }
                });
            },
            eventChange () {
                let itv = null;
                clearTimeout(itv);

                itv = setTimeout(() => {
                    let top = this.$list?.scrollTop ?? 0;
                    this.$store.dispatch('picker/setScrollTop', {
                        type: this.type,
                        subtype: this.tab,
                        layout: this.layout,
                        top
                    });
                }, 50)
            }
        }
    };
</script>
