<template>
    <!-- `pb-3` chứ KHÔNG `mb-3`: `Popup.calculatePopupPosition()` trừ chiều cao khối này
         khỏi maxHeight của phần cuộn bằng `offsetHeight`, mà offsetHeight KHÔNG tính margin.
         Dùng padding thì khoảng cách đó nằm trong phép đo và popup không bị cao dôi ra. -->
    <div class="ecom-scroll-preview pb-3 flex flex-col gap-1.5">
        <!-- Khung mô phỏng khung nhìn. Ô chạy từ đáy lên đỉnh đúng như element đi qua
             viewport thật, đồng thời mang hiệu ứng của giá trị đang chỉnh. -->
        <div
            class="relative overflow-hidden rounded-lg bg-white border border-secondary"
            :style="{ height: STAGE_H + 'px' }"
        >
            <div
                class="absolute left-1/2 rounded bg-primary"
                :style="boxStyle"
            />
        </div>

        <!-- Thanh vị trí cuộn 0→100%, có tô đậm cửa sổ trigger nếu merchant đặt. -->
        <div class="relative h-1 w-full overflow-hidden rounded-full bg-surface-tertiary">
            <div
                v-if="trigger"
                class="absolute inset-y-0 bg-gray-300"
                :style="{ left: trigger.left + '%', width: trigger.width + '%' }"
            />
            <div class="absolute inset-y-0 w-[3px] rounded bg-primary" :style="{ left: percent + '%' }" />
        </div>

        <div class="flex items-center justify-between text-[11px] leading-4 text-text-secondary">
            <span>{{ $t('scroll_position') }}</span>
            <span>{{ Math.round(percent) }}%</span>
        </div>

        <p
            v-if="!playable"
            class="text-[11px] leading-4 text-text-secondary"
            v-html="$helpers.markdown($t('needs_start_and_end'))"
        />
    </div>
</template>

<script lang="ts">
import {
    scrollingValueAt,
    isPlayable,
    toInt,
    getUnit,
    CSS_BY_SCROLLING_TYPE,
    PIXEL_SCALE
} from '@/utils/scrolling-animation';

/** Chiều cao khung mô phỏng và cạnh ô, px. */
const STAGE_H = 104;
const BOX = 26;

/** 0→100% mất ngần này, rồi giữ ở 100% một nhịp cho mắt kịp bắt trạng thái cuối. */
const SWEEP_MS = 3200;
const HOLD_MS = 700;

/** `PIXEL_SCALE` dùng chung với tooltip preview của dropdown preset — xem
 * `utils/scrolling-animation.ts`. */

export default {
    name: 'ScrollingPreview',
    props: {
        /** Object merchant đang chỉnh: {start, middle, end, trigger_start, trigger_end}. */
        value: {
            type: [Object, Array],
            default() { return {}; }
        },
        /** `field.options.type`, vd 'scrolling-animation-px'. */
        type: {
            type: String,
            default: ''
        }
    },
    data() {
        return {
            STAGE_H,
            percent: 0,
            raf: 0,
            startedAt: 0,
            /**
             * Ba giá trị này ĐƯỢC TÍNH LẠI MỖI FRAME trong `loop()`, không phải computed.
             *
             * Lý do: `value` đến từ `Popup.valuesType`, mà `<Fields>` bên dưới sửa object đó
             * bằng cách MUTATE SÂU (thêm/đổi key `start`, `end`…). Computed chỉ đọc
             * `this.value` sẽ không nhất thiết invalidate khi mutation xảy ra sâu như vậy,
             * nên `playable` kẹt ở `false`, cảnh báo "Enter both Start and End" không chịu
             * tắt, và vì `current` phụ thuộc `playable` nên preview đứng im luôn.
             *
             * Đọc thẳng `this.value` trong vòng rAF thì không phụ thuộc reactivity nào cả —
             * mỗi frame lấy đúng giá trị hiện tại. Chi phí bằng 0 vì vòng lặp vẫn chạy sẵn.
             */
            playable: false,
            cssValue: undefined as string | undefined,
            trigger: null as { left: number; width: number } | null
        };
    },
    computed: {
        cssKey(): string {
            return CSS_BY_SCROLLING_TYPE[this.type] ?? '';
        },
        /** Vị trí dọc: 0% = vừa nhô lên từ đáy khung, 100% = vừa rời khỏi đỉnh. */
        offsetTop(): number {
            return STAGE_H - (this.percent / 100) * (STAGE_H + BOX);
        },
        boxStyle(): Record<string, string> {
            const transforms = [`translateY(${this.offsetTop}px)`, 'translateX(-50%)'];
            const style: Record<string, string> = {
                width: BOX + 'px',
                height: BOX + 'px',
                top: '0px'
            };

            const v = this.cssValue;
            if (v !== undefined) {
                const n = toInt(v);
                const unit = getUnit(v);
                if (!Number.isNaN(n)) {
                    switch (this.cssKey) {
                        case 'translateX':
                            transforms.push(`translateX(${n * PIXEL_SCALE}${unit || 'px'})`);
                            break;
                        case 'rotate':
                            transforms.push(`rotate(${n}${unit || 'deg'})`);
                            break;
                        case 'scale':
                            transforms.push(`scale(${n})`);
                            break;
                        case 'opacity':
                            style.opacity = String(n);
                            break;
                        case 'blur':
                            style.filter = `blur(${n * PIXEL_SCALE}${unit || 'px'})`;
                            break;
                    }
                }
            }

            style.transform = transforms.join(' ');
            return style;
        }
    },
    mounted() {
        this.sync();
        this.loop();
    },
    unmounted() {
        // Tiêu chí ANIM-04: đóng popup là vòng lặp phải chết. Popup.vue teleport dưới
        // `v-if="isopen"` nên đóng popup = unmount component này.
        cancelAnimationFrame(this.raf);
        this.raf = 0;
    },
    methods: {
        /**
         * Đọc lại giá trị merchant đang chỉnh và tính mọi thứ phụ thuộc nó.
         *
         * Gọi mỗi frame. Chỉ GÁN KHI GIÁ TRỊ THỰC SỰ ĐỔI, nếu không `trigger` sẽ là object
         * mới mỗi frame và kéo theo một lần re-render thừa 60 lần/giây.
         */
        sync() {
            const v: any = this.value;

            const playable = isPlayable(v);
            if (playable !== this.playable) {
                this.playable = playable;
            }

            const cssValue = playable ? scrollingValueAt(this.percent, v) : undefined;
            if (cssValue !== this.cssValue) {
                this.cssValue = cssValue;
            }

            // Cửa sổ trigger, tự swap khi merchant nhập ngược (80 → 20) đúng như runtime.
            let next: { left: number; width: number } | null = null;
            if (v && (v.trigger_start || v.trigger_end)) {
                let start = Number(v.trigger_start) || 0;
                let end = Number(v.trigger_end) || 100;
                if (start > end) {
                    [start, end] = [end, start];
                }
                next = { left: start, width: Math.max(0, end - start) };
            }
            const cur = this.trigger;
            if ((next === null) !== (cur === null) ||
                (next && cur && (next.left !== cur.left || next.width !== cur.width))) {
                this.trigger = next;
            }
        },
        loop() {
            const step = (now: number) => {
                if (!this.startedAt) this.startedAt = now;
                const elapsed = (now - this.startedAt) % (SWEEP_MS + HOLD_MS);
                this.percent = elapsed >= SWEEP_MS ? 100 : (elapsed / SWEEP_MS) * 100;
                this.sync();
                this.raf = requestAnimationFrame(step);
            };
            this.raf = requestAnimationFrame(step);
        }
    }
};
</script>
