/**
 * Xin optional scope cần để đọc metaobject.
 *
 * `read_metaobjects` và `write_metaobject_definitions` nằm ở `optional_scopes`
 * trong `shopify.app.*.toml`, nghĩa là merchant hiện tại chưa chắc đã cấp.
 *
 * Promise ở cấp module để MỌI nơi trong builder dùng chung một request: panel
 * Insert Dynamic Source và element Metafields đều gọi hàm này. Nếu mỗi bên giữ
 * promise riêng thì merchant bị Shopify hỏi quyền hai lần.
 *
 * Commit `ccdea44bd` đã chốt là xin lúc merchant thực sự mở nhánh metaobject,
 * không phải lúc mount — giữ đúng hành vi đó, đừng gọi hàm này ở `mounted()`.
 */
const REQUIRED_METAOBJECT_SCOPES: string[] = ['read_metaobjects', 'write_metaobject_definitions'];

let scopesPromise: Promise<void> | null = null;
let grantedPromise: Promise<boolean> | null = null;

/**
 * CHỈ hỏi Shopify xem scope đã cấp chưa — không bao giờ bật popup xin quyền.
 *
 * Dùng ở những lúc merchant chưa yêu cầu gì, điển hình là element vừa mount
 * trên canvas: cần biết có nạp được metaobject hay không, mà không được phép
 * chặn màn hình merchant bằng hộp thoại quyền.
 *
 * Ngoài Admin (preview, export, dev local) không có `window.shopify` thì trả
 * `true` để luồng nạp vẫn chạy như trước.
 */
export function hasMetaobjectScopes(): Promise<boolean> {
    if (grantedPromise) return grantedPromise;

    const scopes = (window as any).shopify?.scopes;
    if (!scopes) return Promise.resolve(true);

    grantedPromise = scopes.query()
        .then(({ granted }: { granted: string[] }) =>
            REQUIRED_METAOBJECT_SCOPES.every((scope) => granted.includes(scope))
        )
        .catch((error: unknown) => {
            // Không cache thất bại: lần sau còn hỏi lại được.
            grantedPromise = null;
            console.error('Failed to query metaobject scopes', error);
            return false;
        });

    return grantedPromise;
}

export function ensureMetaobjectScopes(): Promise<void> {
    if (scopesPromise) return scopesPromise;
    if (!(window as any).shopify?.scopes) return Promise.resolve();

    scopesPromise = (async () => {
        const { granted } = await (window as any).shopify.scopes.query();
        const missingScopes = REQUIRED_METAOBJECT_SCOPES.filter(
            (scope) => !granted.includes(scope)
        );
        if (!missingScopes.length) return;
        await (window as any).shopify.scopes.request(missingScopes);
        // Merchant vừa cấp xong → kết quả query cũ đã cũ, phải bỏ cache đi.
        grantedPromise = Promise.resolve(true);
    })().catch((error) => {
        // Reset để lần sau thử lại được; merchant từ chối thì lần mở sau vẫn hỏi.
        scopesPromise = null;
        console.error('Failed to request metaobject scopes', error);
    });

    return scopesPromise;
}
