        async handleSwitchToFlexbox() {
            try {
                // Show loading popup
                this.$store.commit("builder/setPopup", {
                    show: true,
                    loading: true,
                    message: "Please wait while we process your request...",
                    closeable: false
                });

                // Send request to switch layout
                const response = await this.$worker.fetch(
                    window.route("builder.switch-layout"),
                    { enable: true },
                    "POST"
                );

                if (response && response.data && response.data.status === "success") {
                    // Show success message briefly before reload
                    this.$store.commit("builder/setPopup", {
                        type: "warning",
                        title: "Congratulations",
                        show: true,
                        loading: false,
                        loading_btn: true,
                        message:
                            "Welcome to the beta 🎉 <br />Your registration was successful. Simply reload the page to access and add the Flexbox section.",
                        closeable: true
                    });
                } else {
                    // Show error message
                    this.$store.commit("builder/setPopup", {
                        show: true,
                        loading: false,
                        title: "Error",
                        message:
                            response?.data?.message || "Failed to switch layout. Please try again.",
                        closeable: true
                    });
                }
            } catch (error) {
                console.error("Error switching to flexbox layout:", error);
                // Show error message
                this.$store.commit("builder/setPopup", {
                    show: true,
                    loading: false,
                    title: "Error",
                    message: "An error occurred while switching layout. Please try again.",
                    closeable: true,
                    action: {
                        title: "OK"
                    }
                });
            }
        },
        setStructure(st) {
            if (typeof st[0] == "string" && typeof st[1] == "object") {
                if (st[1].grid) {
                    this.$parent.section.blocks = st[1].blocks;
                    this.$parent.section.settings = st[1].settings;
                    // Active new section when add
                    // const currentSection = this.$parent.section;
                    // if (!currentSection.id) {
                    //     currentSection.id = this.$helpers.randid();
                    // }
