<template>
    <div class="ecom-element ecom-base-elements ecom-element__countdown" :class="{'ecom-ingrid-full-height': data.inGrid}">
        <div class="ecom-element__countdown-wrapper ecom-flex" :class="{'ecom-ingrid-full-height': data.inGrid}">
            <div class="ecom-element__countdown-container">
                <div
                    class="ecom-element__countdown--time"
                    :data-countdown-to="countdown_to"
                    :data-countdown-from="countdown_from"
                    :data-evergreen-cd-time="evergreen_cd_time"
                    :data-evergreen-expiry-actions="data.settings?.evergreen_expiry_actions"
                    :data-evergreen-redirect-url="evergreen_redirect_url"
                    :data-evergreen-action-messages="data.settings?.evergreen_action_messages"
                    :data-evergreen-restart="evergreen_restart"
                    :data-evergreen-version="data.settings?.evergreen_version"
                    :data-countdown-restart="data.settings?.countdown_restart"
                    :data-countdown-type="data.settings?.typeCountdown"
                    :data-trans-week="lang(data.settings?.text_week, 'text_week')"
                    :data-trans-day="lang(data.settings?.text_day, 'text_day')"
                    :data-trans-hour="lang(data.settings?.text_hour, 'text_hour')"
                    :data-trans-minute="lang(data.settings?.text_minute, 'text_minute')"
                    :data-trans-second="lang(data.settings?.text_second, 'text_second')"
                    :data-show-fields="shows"
                />
                <div>
                    <div v-if="data.settings.enable_progress_bar" class="ecom-countdown-progress-bar">
                        <div class="ecom-countdown-progress-bar--timer" />
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { Element, Javascript } from "@/mixins";
import { $t } from '@/plugins/i18n';
export default {
    name: "Countdown",
    linkVideo: "https://youtu.be/5Bp3mpjaVnk?si=mAmOPlxypS9RW7aL",
    presets:true,
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/countdown/',
    mixins: [Element, Javascript],
    vendors: ["countdown_js"],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives: ["week", "day", "hour", "minute", "second"]
                .map((show) => "show_" + show)
                .concat(["week", "day", "hour", "minute", "second"].map((show) => "text_" + show))
                .concat(['countdown','countdown_from', "typeCountdown", "countdown_restart", "evergreen_cd_day", "evergreen_cd_hour", "evergreen_cd_minute","evergreen_restart_when", "evergreen_expiry_actions"])
        };
    },
    computed: {
        css() {
            return `
                .ecom-element__countdown--time{
                    display:flex;
                    flex-wrap:wrap;
                    justify-content:inherit;
                }
                [class*="ecom-element__countdown-item--"]{
                    display:flex;
                }
                .ecom-element__countdown-container{
                    display:inline-flex;
                    justify-content:inherit;
                    flex-direction: column;
                    align-items:inherit
                }
                .ecom-countdown-progress-bar{
                    display:block;
                    width:100%;
                    background:green;
                    border-radius:5px;
                    overflow:hidden;
                }
                .ecom-countdown-progress-bar .ecom-countdown-progress-bar--timer{
                    width:100%;
                    height:8px;
                    background-color:red;
                    display:block;
                    border-radius:5px;
                }

                .ecom-countdown-progress-bar--timer {
                        background-image: -webkit-linear-gradient(45deg,rgba(255,255,255,.15) 25%,transparent 25%,transparent 50%,rgba(255,255,255,.15) 50%,rgba(255,255,255,.15) 75%,transparent 75%,transparent);
                        background-image: linear-gradient(45deg,rgba(255,255,255,.15) 25%,rgba(0,0,0,0) 25%,rgba(0,0,0,0) 50%,rgba(255,255,255,.15) 50%,rgba(255,255,255,.15) 75%,rgba(0,0,0,0) 75%,rgba(0,0,0,0));
                        -webkit-animation: 2s linear infinite ecom_progress_bar;
                        animation: 2s linear infinite ecom_progress_bar;
                        background-size: 60px 60px;
                        transition: width 1s;
                        -webkit-transition: width 1s;
                }

                @-webkit-keyframes ecom_progress_bar {
                    from {
                        background-position: 0 0
                    }

                    to {
                        background-position: 40px 0
                    }
                }

                @keyframes ecom_progress_bar {
                    from {
                        background-position: 0 0
                    }

                    to {
                        background-position: 40px 0
                    }
                }
            `;
        },

        javascript() {
            return function () {
                const $el = this.$el;
                const _isLive = this.isLive;
                const $staleWarning = $el.querySelector('.ecom-countdown-date-warning');
                if ($staleWarning) $staleWarning.remove();
                if (!window.EComCountdown) return;
                if (window.EComCountdown) {
                    const $dom = $el.querySelector(".ecom-element__countdown--time");
                    let $progressbar = $el.querySelector('.ecom-countdown-progress-bar'),
                        $timer =  $el.querySelector('.ecom-countdown-progress-bar--timer'),
                        from = $dom ? $dom.dataset.countdownFrom : 0,
                        type = $dom ? ($dom.dataset.countdownType ? $dom.dataset.countdownType : 'visit') : 'visit',
                        restart = $dom ? ($dom.dataset.countdownRestart ? $dom.dataset.countdownRestart : false) : false;

                    let cookieName  = 'ecomposer_evergreen';
                    let cookie = getCookie(cookieName);
                    let cookieObject = cookie?JSON.parse(cookie):'';
                    let countdownTo = $dom.dataset.countdownTo;
                    const evergreenRestartObj = $dom.dataset.evergreenRestart?JSON.parse($dom.dataset.evergreenRestart):'';
                    const evergreenType = evergreenRestartObj?evergreenRestartObj.type:'';
                    const evergreenExpiryAction = $dom.dataset.evergreenExpiryActions?$dom.dataset.evergreenExpiryActions:'';
                    const evergreenRedirectUrl = $dom.dataset.evergreenRedirectUrl?$dom.dataset.evergreenRedirectUrl:'';
                    const evergreenActionMessages = $dom.dataset.evergreenActionMessages?$dom.dataset.evergreenActionMessages:'';
                    function setCookie(cname, cvalue, exdays) {
                        let expires = "expires="+exdays.toUTCString();
                        document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";
                    }

                    function getCookie(cname) {
                    let name = cname + "=";
                    let decodedCookie = decodeURIComponent(document.cookie);
                    let ca = decodedCookie.split(';');
                        for(let i = 0; i <ca.length; i++) {
                            let c = ca[i];
                            while (c.charAt(0) == ' ') {
                            c = c.substring(1);
                            }
                            if (c.indexOf(name) == 0) {
                            return c.substring(name.length, c.length);
                            }
                        }
                        return "";
                    }

                    function evergreenGetTime(evergreenTime) {
                        const [day, hour, minute] = evergreenTime.split(':');
                        const dayToMiliSecond = day * 24 * 60 * 60 * 1000;
                        const hourToMiliSecond = hour * 60 * 60 * 1000;
                        const minuteToMiliSecond = minute * 60 * 1000;
                        return dayToMiliSecond + hourToMiliSecond + minuteToMiliSecond;
                    }
                    function doAction(action,dom,useCookie) {
                        let cookie = getCookie(cookieName);
                        let cookieObject = cookie?JSON.parse(cookie):'';
                        if (!_isLive) return;
                        if (action === 'hideTimer') {
                            dom.style.display = 'none';
                        }else if(action === 'hideSection'){
                            _isLive?dom.closest('.ecom-section').style.display = 'none':'';
                        }else if(action === 'redirect'){
                            if (useCookie){
                                cookieObject?.redirect_url ?  window.location.href =  cookieObject.redirect_url : null;
                                // let UrlObj = cookieObject?.redirect_url?cookieObject.redirect_url:'';
                                // UrlObj.href ? UrlObj.target ? window.open(UrlObj.href) : window.location.href = UrlObj.href : null;

                            }else{
                                evergreenRedirectUrl ? window.location.href = evergreenRedirectUrl : null;
                                // UrlObj.href ? UrlObj.target ? window.open(UrlObj.href) : window.location.href = UrlObj.href : null;

                            }

                        }else if(action === 'toast' && evergreenActionMessages){
                            if(useCookie){
                                cookieObject.messages ?  EComposer.showToast(cookieObject.messages) : null;
                            }else{
                                EComposer.showToast(evergreenActionMessages);
                            }
                        }
                    }

                    if($dom && $dom.dataset.evergreenCdTime && $dom.dataset.countdownType === 'evergreen'){
                        const nowTime = new Date().getTime();
                        countdownTo = new Date(nowTime + evergreenGetTime($dom.dataset.evergreenCdTime));
                    }
                    if ($dom && countdownTo) {
                        const fields = $dom.dataset.showFields ? $dom.dataset.showFields : "";
                        const params = $dom.dataset;
                        var format = "";
                        const regex = /\[([^\]]+)\]/gm;

                        if (fields.includes("week") && params.transWeek.length > 0) {

                            let number = '';
                            let text = params.transWeek.replace(regex,(...m)=>{
                                  number =  m[1];
                                  return '';
                            });
                            format += `
                                        <div class="ecom-element__countdown-item--weeks">
                                            <span class="ecom-element__countdown-number">${number}</span>
                                            <span class="ecom-element__countdown-text">
                                                 ${text}
                                            </span>
                                        </div>`;
                        }
                        if (fields.includes("day") && params.transDay.length > 0) {
                            let number = '';
                            let text = params.transDay.replace(regex,(...m)=>{
                                  number =  m[1];
                                  return '';
                            });
                            format += `
                                        <div class="ecom-element__countdown-item--days">
                                            <span class="ecom-element__countdown-number">
                                                ${number}
                                            </span>
                                            <span class="ecom-element__countdown-text">
                                                ${text}
                                            </span>
                                        </div>`;
                        }
                        if (fields.includes("hour") && params.transHour.length > 0) {
                            let number = '';
                            let text = params.transHour.replace(regex,(...m)=>{
                                  number =  m[1];
                                  return '';
                            });
                            format += `
                                        <div class="ecom-element__countdown-item--hours">
                                            <span class="ecom-element__countdown-number">
                                                 ${number}
                                            </span>
                                            <span class="ecom-element__countdown-text">
                                                ${text}
                                            </span>
                                        </div>`;
                        }
                        if (fields.includes("minute") && params.transMinute.length > 0) {
                            let number = '';
                            let text = params.transMinute.replace(regex,(...m)=>{
                                  number =  m[1];
                                  return '';
                            });
                            format += `
                                        <div class="ecom-element__countdown-item--minutes">
                                            <span class="ecom-element__countdown-number">
                                                ${number}
                                            </span>
                                            <span class="ecom-element__countdown-text">
                                                ${text}
                                            </span>
                                        </div>`;
                        }
                        if (fields.includes("second") && params.transSecond.length > 0) {
                            let number = '';
                            let text = params.transSecond.replace(regex,(...m)=>{
                                  number =  m[1];
                                  return '';
                            });
                            format += `
                                        <div class="ecom-element__countdown-item--seconds">
                                            <span class="ecom-element__countdown-number">
                                                ${
                                                    number
                                                }
                                            </span>
                                            <span class="ecom-element__countdown-text">
                                                ${
                                                    text
                                                }
                                            </span>
                                    </div>`;
                        }

                        function countdownCallback(event) {
                            this.innerHTML = event.strftime(format);
                            if ($progressbar && from) {
                                let now_time = new Date().getTime(),
                                    start = new Date(from),
                                    start_time = start.getTime(),
                                    end_time = event.finalDate.getTime();
                                if (start_time < now_time && end_time > start_time) {
                                    $progressbar.style.display = 'inherit';;
                                    let total = end_time - start_time;
                                    let elapse = end_time - now_time;
                                    let result = Math.round((elapse * 100) / total);
                                    $timer.style.width = result + '%';
                                } else {
                                    $progressbar.style.display = 'none';
                                }
                            }
                        }

                        if (from && new Date().getTime() < new Date(from).getTime() && type == 'time') {
                            // countdown_from is in the future, not yet time to start
                        } else {

                            let date = new Date(countdownTo)

                            if (!_isLive && type !== 'evergreen' && date < new Date()) {
                                const $warning = document.createElement('div');
                                $warning.className = 'ecom-countdown-date-warning';
                                $warning.style.cssText = 'position:absolute;inset:0;background:rgba(251,191,36,.1);border:2px dashed #f59e0b;display:flex;align-items:center;justify-content:center;z-index:10;pointer-events:none;font-size:13px;color:#b45309;font-weight:600;text-align:center;padding:8px;border-radius:4px;box-sizing:border-box;';
                                $warning.textContent = '⚠ Countdown date has expired. Please update to a future date.';
                                $el.style.position = 'relative';
                                $el.appendChild($warning);
                            }

                            if( window.EComCountdown )
                            {
                                //evergreen countdown
                                if(type === 'evergreen'){
                                    let cookie = getCookie(cookieName);
                                    let cookieObject = cookie?JSON.parse(cookie):'';
                                    if (evergreenType !== "nextVisit" && evergreenType!== "immediately"){
                                        const version = $dom.dataset.evergreenVersion?$dom.dataset.evergreenVersion:'';
                                        let newCookieValue = {
                                        action: $dom.dataset.evergreenExpiryActions?$dom.dataset.evergreenExpiryActions:'',
                                        evergreen_ver: version,
                                        creation_date : new Date(),
                                        countdown_time: countdownTo,
                                        expiration_date:'',
                                        redirect_url: evergreenRedirectUrl,
                                        messages:evergreenActionMessages

                                        };

                                        if (typeof(cookieObject) === "object" && cookieObject.evergreen_ver && cookieObject.evergreen_ver === version) {
                                            let now = new Date();
                                            let countdownTime = new Date(cookieObject.countdown_time);
                                            if (countdownTime>now) {
                                                date = countdownTime;
                                                from = cookieObject.creation_date?cookieObject.creation_date:0;
                                            }else  {
                                                $el.style.display = 'none';
                                                doAction(cookieObject.action,$el,true)
                                                return;
                                            }
                                        }else if  (evergreenType === "specificTime"){
                                                const now = new Date();
                                                from= now;
                                                let expirationDate = typeof evergreenGetTime(evergreenRestartObj.data) === 'number'? new Date(now.getTime() + evergreenGetTime(evergreenRestartObj.data)) : 0 ;
                                                newCookieValue.expiration_date= expirationDate;
                                                setCookie(cookieName,JSON.stringify(newCookieValue),expirationDate);
                                        }else if(evergreenType === "none"){
                                                const now = new Date();
                                                from= now;
                                                let expirationDate = new Date(now);
                                                expirationDate.setDate(now.getDate() + 365);
                                                newCookieValue.expiration_date= expirationDate;
                                                setCookie(cookieName,JSON.stringify(newCookieValue),expirationDate);
                                        }
                                    }else{
                                        from = new Date();
                                    }


                                }

                                let date_diff =  new Date(countdownTo).getTime() - new Date($dom.dataset.countdownFrom).getTime(),

                                    new_date = new Date(countdownTo).getTime() + date_diff;

                                if(date_diff == 0) return;
                                while(new_date < new Date().getTime()){
                                    new_date += date_diff;
                                }
                                window
                                .EComCountdown($dom,date, {});
                                $dom.addEventListener('update.ecom.countdown', countdownCallback);
                                $dom.addEventListener('finish.ecom.countdown', function(event) {
                                    if(restart == 'true' && type == 'time') {
                                        window.EComCountdown($dom,new Date(new_date), countdownCallback)
                                    }
                                    if (type === "evergreen"){
                                        if (evergreenType === 'none' || evergreenType === 'specificTime'){
                                            let cookie = getCookie(cookieName);
                                            let cookieObject = cookie?JSON.parse(cookie):'';
                                            doAction(cookieObject.action, $el,true);
                                        }else if(evergreenType === "immediately" && evergreenRestartObj.data){
                                            let newTime = evergreenGetTime($dom.dataset.evergreenCdTime);
                                            if  ( typeof newTime  === 'number' && newTime > 0){
                                                let now = new Date().getTime();
                                                from = new Date();
                                                doAction(evergreenExpiryAction, $el);
                                                window.EComCountdown($dom,new Date(now + newTime), countdownCallback);
                                            }
                                        }else if (evergreenType === "nextVisit") {
                                            doAction(evergreenExpiryAction, $el);
                                        }
                                    }

                                });

                            }
                        }

                    }
                }
            };
        },
        countdown_to() {
            return this.data && this.data.settings && "countdown" in this.data.settings
                ? this.data.settings.countdown
                : "";
        },
        countdown_from() {
            return this.data && this.data.settings && "countdown_from" in this.data.settings
                ? this.data.settings.countdown_from
                : "";
        },
        evergreen_cd_time() {
            let day = this.data?.settings?.evergreen_cd_day?this.data.settings.evergreen_cd_day:'0';
            let hour = this.data?.settings?.evergreen_cd_hour?this.data.settings.evergreen_cd_hour:'0';
            let minute = this.data?.settings?.evergreen_cd_minute?this.data.settings.evergreen_cd_minute:'0';
            return `${day}:${hour}:${minute}`;
        },
        evergreen_redirect_url() {
            let url = this.data?.settings?.evergreen_url?this.data.settings.evergreen_url:'';
            if (url){
                url = url.trim();
                if (!url.match(/^https?:\/\//i)) {
                    url = 'http://' + url;
                }
                let normalizedURL = new URL(url);
                return normalizedURL.href;
            }
            return '';
        },
        evergreen_restart(){
            let day = this.data?.settings?.evergreen_restart_day?this.data.settings.evergreen_restart_day:'0';
            let hour = this.data?.settings?.evergreen_restart_hour?this.data.settings.evergreen_restart_hour:'0';
            let minute = this.data?.settings?.evergreen_restart_minute?this.data.settings.evergreen_restart_minute:'0';
            let evergreen_restart_obj={
                type: this.data?.settings?.evergreen_restart_when?this.data.settings.evergreen_restart_when:'',
                data: `${day}:${hour}:${minute}`
            };
            return JSON.stringify(evergreen_restart_obj);
        },
        shows() {
            const shows = ["week", "day", "hour", "minute", "second"];
            return shows.filter((show) => this.data.settings["show_" + show]);
        },

        // Lower bound of the end-date picker: never before the start date, and never in the
        // past, so an expired date can't be picked in the first place. Skipped when the saved
        // value is already expired — the field clamps a value below `min`, which would rewrite
        // the merchant's date just by opening the panel and hide the expired warning.
        countdownEndMin() {
            const from = this.data?.settings?.countdown_from || '';
            const now = new Date();
            const current = new Date(this.data?.settings?.countdown);
            if (!isNaN(current) && current < now) {
                return from;
            }
            const fromDate = new Date(from);
            return !isNaN(fromDate) && fromDate > now ? from : this.formatDateTime(now);
        },

        default() {
            const now = new Date();
            // End at 12:30 on the 1st of next month; start at the beginning of the current
            // month so the progress bar always has elapsed time. Date arithmetic instead of
            // string concat, so December/January and short months can't produce invalid dates.
            const endDate = new Date(now.getFullYear(), now.getMonth() + 1, 1, 12, 30);
            const startDate = new Date(now.getFullYear(), now.getMonth(), 1, 0, 0);
            return {
                settings: {
                    title: "Hurry up! The sale will end on",
                    countdown_from: this.formatDateTime(startDate),
                    countdown: this.formatDateTime(endDate),
                    evergreen_cd_day: '1',
                    evergreen_cd_hour: '12',
                    evergreen_cd_minute: '30',
                    show_week: true,
                    show_day: true,
                    show_hour: true,
                    show_minute: true,
                    show_second: true,
                    text_week: "[%-w] week%!w",
                    text_day: "[%-d] day%!D",
                    text_hour: "[%-H] hour%!H",
                    text_minute: "[%-M] minute%!M",
                    text_second: "[%-S] second%!S",
                    styleCountdown: "column",
                    typeCountdown: "time",
                },
                "style": {
                    "progess_bar": {
                        "tab": "normal",
                        "maxWidth": "96%",
                        "background": {
                            "classic": {
                                "background-color": "#deb4b4"
                            }
                        },
                        "height": "14px",
                        "borderRadius": {
                            "top": "8px",
                            "left": "8px",
                            "bottom": "8px",
                            "right": "8px"
                        }
                    },
                    "general": {
                        "justify-content": "center"
                    },
                    "items": {
                        "spacing": {
                            "padding": {
                                "left": "10px",
                                "top": "5px",
                                "bottom": "5px",
                                "right": "10px"
                            },
                            "margin": {
                                "top": "5px",
                                "left": "10px",
                                "bottom": "5px",
                                "right": "10px"
                            }
                        },
                        "boxBackground": "rgba(255, 255, 255, 0.05)",
                        "spacing__mobile": {
                            "padding": {
                                "left": "10px",
                                "top": "10px",
                                "bottom": "10px",
                                "right": "10px"
                            },
                            "margin": {}
                        },
                        "boxBorder": {
                            "border-style": "solid",
                            "border-color": "#f0f0f0",
                            "border-width": {
                                "bottom": "1px",
                                "top": "1px",
                                "left": "1px",
                                "right": "1px"
                            }
                        },
                        "boxBorderRadius": {
                            "top": "3px",
                            "left": "3px",
                            "bottom": "3px",
                            "right": "3px"
                        },
                        "boxShadow": {
                            "box-shadow": {
                                "color": "rgba(0, 0, 0, 0.06)",
                                "horizontal": "1px",
                                "vertical": "1px",
                                "blur": "5px",
                                "spread": "1px"
                            }
                        }
                    },
                    "countdown_number": {
                        "buttonColor": "#333",
                        "spacing": {
                            "margin": {
                                "right": "8px"
                            }
                        },
                        "spacing__mobile": {
                            "margin": {
                                "bottom": "0px",
                                "top": "0px",
                                "left": "0px",
                                "right": "0px"
                            },
                            "padding": {
                                "bottom": "0px",
                                "top": "0px",
                                "left": "0px",
                                "right": "0px"
                            }
                        },
                        "buttonTypography": {
                            "font-family": {
                                "name": "Jost",
                                "value": "https://fonts.googleapis.com/css?family=Jost:100,200,300,400,500,600,700,800,900",
                                "thumbnail": "Jost"
                            },
                            "font-size": "26px",
                            "font-weight": "700",
                            "line-height": "42px"
                        },
                        "text-align": "center",
                        "buttonWidth": "52px"
                    },
                    "countdown_label": {
                        "spacing__mobile": {
                            "margin": {
                                "bottom": "0px",
                                "top": "0px",
                                "left": "0px",
                                "right": "0px"
                            },
                            "padding": {
                                "bottom": "0px",
                                "top": "0px",
                                "left": "0px",
                                "right": "0px"
                            }
                        },
                        "buttonTypography": {
                            "global-typography": "m5lJMKLv"
                        },
                        "text-align": "center"
                    }
                }
            };
        }
    },
    methods:{
        quickToolBar() {
            //return ['countdown', 'typeCountdown'];
            return [];
        },
        // Offset of the given date, so a future date keeps the right offset across DST changes.
        timeZoneOffset(date) {
            const offset = date.getTimezoneOffset(),
                o = Math.abs(offset);
            // UTC must render as "+0000" — "-0000" is not in the GMT dropdown list.
            return (
                (offset <= 0 ? "+" : "-") +
                ("00" + Math.floor(o / 60)).slice(-2) +
                ("00" + (o % 60)).slice(-2)
            );
        },
        // "YYYY/MM/DD hh:mm GMT+0700" — the format the datetime field parses.
        formatDateTime(date) {
            const pad = (n) => ("00" + n).slice(-2);
            return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ` +
                `${pad(date.getHours())}:${pad(date.getMinutes())} GMT${this.timeZoneOffset(date)}`;
