<template>
    <div class="ecom__element ecom-element element__divi">
        <div class="ecom__element-divi" :class="diviLine" :style="diviLineStyle">
            <div class="divi-line divi-style" :style="styleDivider" />
            <div class="divi-cont" :style="styleDivider2">
                <div
                    v-if="divi.icon || divi.text || divi.image"
                    class="divi-cont-before divi-style"
                    :style="diviLeft"
                />
                <span v-if="divi.icon && divi.type == 'icon'" v-html="divi.icon" />
                <span v-if="divi.text && divi.type == 'text'" class="divi-text">
                    {{ lang(divi.text) }}
                </span>
                <div
                    data-stopdrag
                    class="ecom-image-default ecom-flex ecom-fl_center ecom-base-image"
                    v-if="divi.image && divi.type == 'image'"
                >
                    <picture
                        v-if="!link.href"
                        class="ecom-image-picture"
                        ref="image"
                        v-html="$helpers.renImageResponsive(image, screens, lazyload, focalPoint)"
                    >
                    </picture>

                    <a
                        v-else
                        v-bind="link"
                        class="ecom-image-picture-link ecom-image-picture ecom-base-image-container-overlay"
                    >
                        <picture
                            ref="image"
                            v-html="
                                $helpers.renImageResponsive(image, screens, lazyload, focalPoint)
                            "
                        ></picture>
                    </a>
                </div>
                <div
                    v-if="divi.icon || divi.text || divi.image"
                    class="divi-cont-after divi-style"
                    :style="diviRight"
                />
            </div>
        </div>
    </div>
</template>

<script>
import { Element } from '@/mixins';
export default {
    name: 'Divider',
    docs: 'https://help.ecomposer.io/docs/elements/basic-elements/divider/',
    mixins: [Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        settings() {
            return [
                {
                    group_title: this.$t('divider'),
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('style'),
                            name: 'borderStyle',
                            options: {
                                type: 'dropdown',
                                default:false,
                                preview: 'title',
                                values: {
                                    solid: this.$t('solid'),
                                    dotted: this.$t('dotted'),
                                    dashed: this.$t('dashed'),
                                    double: this.$t('double'),
                                    zigzag: this.$t('zigzag'),
                                    curly: this.$t('curly')
                                }
                            },
                            css: {
                                selector: ' div.divi-style',
                                properties: {
                                    'border-style': ''
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('select_type'),
                            name: 'type',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    none: this.$t('none'),
                                    text: this.$t('text'),
                                    icon: this.$t('icon'),
                                    image: this.$t('image')
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },

                        {
                            type: 'picker',
                            label: this.$t('icon'),
                            name: 'icon',
                            options: {
                                type: 'icon',
                                layout: 'grid',
                                output: 'value',
                                multiple: false,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['type'] == 'icon';
                                    }
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('choose_image'),
                            name: 'image',
                            options: {
                                responsive: true,
                                type: 'image',
                                editAlt: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['type'] == 'image';
                                    }
                                }
                            }
                        },
                        {
                            type: 'popup',
                            name: 'link',
                            label: this.$t('link'),
                            value: 'lightbox',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                default: false,
                                values: {
                                    none: this.$t('none'),
                                    lightbox: this.$t('media_file'),
                                    custom: this.$t('custom_url')
                                },
                                visible: (data) => {
                                    return data['type'] == 'image';
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'link',
                            name: 'custom-link',
                            options: {
                                visible: (data) => {
                                    return data['type'] == 'image' && data['link'] == 'custom';
                                }
                            }
                        },
                        {
                            name: 'position',
                            label: this.$t('text_icon_image_position'),
                            type: 'choose',
                            options: {
                                type: 'text-align',
                                values: ['left', 'center', 'right'],
                                oneline: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['type'] && data['type'] !== 'none';
                                    }
                                }
                            }
                        },
                        {
                            alias: 'justify-content',
                            options: {
                                name: 'justifyContent',
                                label: this.$t('alignment'),
                                css: {
                                    selector: ' .ecom__element-divi, .divi-cont'
                                }
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('text'),
                            name: 'text',
                            options: {
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['type'] == 'text';
                                    }
                                }
                            }
                        },
                        {
                            name: 'gridColumnGap',
                            label: this.$t('spacing'),
                            type: 'number',
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 50,
                                        step: 1
                                    }
                                },
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['type'] && data['type'] !== 'none';
                                    }
                                }
                            },
                            css: {
                                selector: ' .divi-cont',
                                properties: {
                                    'grid-column-gap': ''
                                }
                            }
                        },
                        {
                            type: 'number',
                            label: this.$t('width'),
                            name: 'width',
                            options: {
                                responsive: true,
                                units: {
                                    '%': {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    },
                                    px: {
                                        min: 0,
                                        max: 1000,
                                        step: 1
                                    }
                                }
                            },
                            css: {
                                selector: ' .divi-line.divi-style',
                                properties: {
                                    width: ''
                                }
                            }
                        }
                    ]
                }
            ];
        },
        image() {
            if (!this.data.settings) {
                return;
            }
            let { image = {}, size, size_custom } = this.data.settings;
            if (Object.keys(image).length === 0) {
                return null;
            }
            if (size === 'custom') {
                size = size_custom;
            } else if (size) {
                size = { width: size.split('x')[0], height: size.split('x')[1] };
            }

            const img = {
                alt: image.alt || image.name,
                ...Object.keys(image)
                    .filter((k) => k.startsWith('value'))
                    .reduce((acc, cur) => {
                        acc[cur] = this.$helpers.resizeImage(image[cur], size);
                        return acc;
                    }, {})
            };
            if (image.top) {
                img.top = image.top;
            }
            if (image.left) {
                img.left = image.left;
            }
            if (image.width) {
                img.width = image.width;
            }
            if (image.height) {
                img.height = image.height;
            }

            return img;
        },
        screens() {
            return this.$store.getters['builder/screens'];
        },
        lazyload() {
            return this.data.settings?.lazyload ? this.data.settings?.lazyload === false : true;
        },
        focalPoint() {
            const style = {};
            if (this.image?.left && this.image?.top) {
                style['object-position'] = `${this.image?.left}% ${this.image?.top}%`;
            }
            return style;
        },
        divi() {
            return this.data.settings;
        },
        unit() {
            return this.divi.width ? this.divi.width.replace(/[0-9]/g, '') : 'px';
        },
        styleDivider() {
            return {
                // width: this.divi.width,
                display:
                    (this.divi.icon && this.divi.type == 'icon') ||
                    (this.divi.text && this.divi.type == 'text') ||
                    this.divi.type == 'image'
                        ? 'none'
                        : 'block'
            };
        },
        styleDivider2() {
            let isShow =
                (this.divi.icon && this.divi.type == 'icon') ||
                (this.divi.text && this.divi.type == 'text') ||
                this.divi.type == 'image'
                    ? 'flex'
                    : 'none';

            let widthUnit = this.divi.width ? this.divi.width.replace(/[0-9]/g, '') : '%';
            let tabletUnit = this.divi.width__tablet
                ? this.divi.width__tablet.replace(/[0-9]/g, '')
                : '%';
            let mobileUnit = this.divi.width__mobile
                ? this.divi.width__mobile.replace(/[0-9]/g, '')
                : '%';
            let widthValue = this.divi.width ? parseInt(this.divi.width) * 0.01 : '1';
            let widthTablet = this.divi.width__tablet
                ? parseInt(this.divi.width__tablet) * 0.01
                : '1';
            let widthMobile = this.divi.width__mobile
                ? parseInt(this.divi.width__mobile) * 0.01
                : '1';
            let resultObj = {
                '--flex-desktop': '',
                '--flex-tablet': '',
                '--flex-mobile': '',
                '--divider-width': '',
                '--divider-width-tablet': '',
                '--divider-width-mobile': '',
                display: isShow
            };
            if (this.divi?.position == 'left' || this.divi?.position == 'right') {
                if (this.divi.width) {
                    if (widthUnit == '%') {
                        resultObj['--flex-desktop'] = widthValue;
                        resultObj['--divider-width'] = 'auto';
                    } else {
                        resultObj['--flex-desktop'] = 'none';
                        resultObj['--divider-width'] = this.divi.width;
                    }
                }
                if (this.divi?.width__tablet) {
                    if (tabletUnit == '%') {
                        resultObj['--flex-tablet'] = widthTablet ?? widthValue;
                        resultObj['--divider-width-tablet'] = 'auto';
                    } else {
                        resultObj['--flex-tablet'] = 'none';
                        resultObj['--divider-width-tablet'] =
                            this.divi?.width__tablet ?? this.divi.width;
                    }
                } else {
                    resultObj['--flex-tablet'] = resultObj['--flex-desktop'];
                    resultObj['--divider-width-tablet'] = resultObj['--divider-width'];
                }
                if (this.divi?.width__mobile) {
                    if (mobileUnit == '%') {
                        resultObj['--flex-mobile'] = widthMobile ?? widthTablet ?? widthValue;
                        resultObj['--divider-width-mobile'] = 'auto';
                    } else {
                        resultObj['--flex-mobile'] = 'none';
                        resultObj['--divider-width-mobile'] =
                            this.divi?.width__mobile ?? this.divi?.width__tablet ?? this.divi.width;
                    }
                }
                else
                {
                    resultObj['--flex-mobile'] = resultObj['--flex-tablet'] ?? resultObj['--flex-desktop'];
                    resultObj['--divider-width-mobile'] =
                        resultObj['--divider-width-tablet'] ?? resultObj['--divider-width'];
                }
                return resultObj;
            } else {
                if (this.divi.width) {
                    if (widthUnit == '%') {
                        resultObj['--flex-desktop'] = widthValue / 2;
                        resultObj['--divider-width'] = 'auto';
                    } else {
                        resultObj['--flex-desktop'] = 'none';
                        resultObj['--divider-width'] = `${
                            parseInt(this.divi.width) / 2
                        }${widthUnit}`;
                    }
                }
                if (this.divi?.width__tablet) {
                    if (tabletUnit == '%') {
                        resultObj['--flex-tablet'] = widthTablet / 2 ?? widthValue / 2;
                        resultObj['--divider-width-tablet'] = 'auto';
                    } else {
                        resultObj['--flex-tablet'] = 'none';
                        resultObj['--divider-width-tablet'] = this.divi?.width__tablet
                            ? `${parseInt(this.divi.width__tablet) / 2}${tabletUnit}`
                            : `${parseInt(this.divi.width) / 2}${widthUnit}`;
                    }
                } else {
                    resultObj['--flex-tablet'] = resultObj['--flex-desktop'];
                    resultObj['--divider-width-tablet'] = resultObj['--divider-width'];
                }
                if (this.divi?.width__mobile) {
                    if (mobileUnit == '%') {
                        resultObj['--flex-mobile'] =
                            widthMobile / 2 ?? widthTablet / 2 ?? widthValue / 2;
                        resultObj['--divider-width-mobile'] = 'auto';
                    } else {
                        resultObj['--flex-mobile'] = 'none';
                        resultObj['--divider-width-mobile'] = this.divi?.width__mobile
                            ? `${parseInt(this.divi.width__mobile) / 2}${mobileUnit}`
                            : this.divi?.width__tablet
                            ? `${parseInt(this.divi.width__tablet) / 2}${tabletUnit}`
                            : `${parseInt(this.divi.width) / 2}${widthUnit}`;
                    }
                } else {
                    resultObj['--flex-mobile'] =
                        resultObj['--flex-tablet'] ?? resultObj['--flex-desktop'];
                    resultObj['--divider-width-mobile'] =
                        resultObj['--divider-width-tablet'] ?? resultObj['--divider-width'];
                }
                return resultObj;
            }
        },
        diviLine() {
            let result = { 'line-style-zigzag': false, 'line-style-curly': false };
            this.divi?.borderStyle === 'zigzag'
                ? (result['line-style-zigzag'] = true)
                : (result['line-style-zigzag'] = false);
            this.divi?.borderStyle === 'curly'
                ? (result['line-style-curly'] = true)
                : (result['line-style-curly'] = false);
            return result;
        },
        diviLeft() {
            return {
                display: this.divi?.position == 'left' ? 'none' : 'block'
            };
        },
        diviRight() {
            return {
                display: this.divi?.position == 'right' ? 'none' : 'block'
            };
        },
        diviLineStyle() {
            let backgroundURL = '';
            let isRgbTypeColor =
                this.data.style.divider?.borderColor &&
                Array.isArray(this.data.style.divider.borderColor) &&
                this.data.style.divider?.borderColor.includes('rgba');
            let color = '';
            if (!isRgbTypeColor) {
                color = this.data.style.divider?.borderColor
                    ? this.data.style.divider?.borderColor
                    : '#23818a91';
            } else {
                color = this.data.style.divider?.borderColor;
            }
            let zigzagSvg = `<svg xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none" overflow="visible" height="100%" viewBox="0 0 24 24" stroke="${color}" stroke-width="6px" fill="none" stroke-linecap="square" stroke-miterlimit="10"><polyline points="0,18 12,6 24,18"/></svg>`;
            let curlySvg = `<svg xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none" overflow="visible" height="100%" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="6px" stroke-linecap="square" stroke-miterlimit="10"><path d="M0,21c3.3,0,8.3-0.9,15.7-7.1c6.6-5.4,4.4-9.3,2.4-10.3c-3.4-1.8-7.7,1.3-7.3,8.8C11.2,20,17.1,21,24,21"/></svg>`;
            let zigzagUrl = `url(data:image/svg+xml;base64,${btoa(zigzagSvg)})`;
            let curlygUrl = `url(data:image/svg+xml;base64,${btoa(curlySvg)})`;

            if (!this.divi?.borderStyle === 'zigzag' && !this.divi?.borderStyle === 'curly') {
                return;
            } else {
                if (this.divi?.borderStyle === 'zigzag') backgroundURL = zigzagUrl;
                if (this.divi?.borderStyle === 'curly') backgroundURL = curlygUrl;
            }
            return {
                '--divi-background-url': backgroundURL,
                '--divi-line-height': this.data.style.divider?.borderBottomWidth
                    ? this.data.style.divider?.borderBottomWidth
                    : '2px'
            };
        },
        link() {
            let result = {};
            let settings = this.data.settings;
            let image = this.data.settings?.image;
            if (image?.value || image?.value__mobile || image?.value__tablet) {
                let { link, 'custom-link': customLink, lightbox } = settings;
                if (link === 'lightbox') {
                    if (lightbox === 'yes') {
                        result['ecom-modal'] = 'image';
                        result['ecom-modal-source'] = image.value;
                    }
                    result.href = image.value;
                } else if (link === 'custom' && customLink?.href) {
                    Object.assign(result, customLink);
                }
            }
            return result;
        },
        css() {
            return `
                .element__divi{
                    /*padding:10px 0;*/
                    overflow:hidden;
                }
                .ecom__element-divi{
                    display:flex;
                }
                .divi-line{
                    /*margin:10px 0;*/
                    border:0;
                    border-bottom: 1px solid #D1D5DB;
                }
                .divi-cont{
                    position:relative;
                    z-index:1;
                    display:flex;
                    align-items:center;
                    transition: all .3s;
                    color: #818a91;
                    width:100%;
                }
                .divi-cont span{
                    display:flex;
                    white-space:nowrap;
                }
                .divi-cont-before{
                    display:block;
                    border:0;
                }
                .divi-cont-after{
                    display:block;
                    border:0;
                }
                .divi-style{
                    padding:0 !important;
                    border-bottom: 2px solid #D1D5DB;
                }
                .divi-cont>*{
                    margin:0;
                }
                .divi-cont svg{
                    width:36px;
                    height:auto;
}
                .line-style-zigzag .divi-line, .line-style-zigzag .divi-cont-before,.line-style-zigzag .divi-cont-after {
                    height: var(--divi-line-height);
                    background-size: var(--divi-line-height) 100%;
                    background-repeat: repeat-x;
                    border: none;
                    background-image: var(--divi-background-url);
                }
                .line-style-curly .divi-line, .line-style-curly .divi-cont-before, .line-style-curly .divi-cont-after{
                    height: var(--divi-line-height);
                    background-size: var(--divi-line-height) 100%;
                    background-repeat: repeat-x;
                    border: none;
                    background-image: var(--divi-background-url);

                }
                .ecom__element-divi .ecom-image-default{
                    width:300px;
                    flex-shrink:0;

                }

                .ecom__element-divi .ecom-base-image .ecom-image-picture {
                    width: 100%;
                    max-width: 100%;
                }
                .ecom__element-divi .ecom-base-image picture{
                    overflow: hidden;
                    flex: 1 1 auto;
                    min-height: 1px;
                }
                .ecom__element-divi .ecom-base-image .ecom-image-picture img{
                    width: 100%;
                }
                .ecom__element-divi .ecom-image-default .ecom-image-picture img{
                    object-fit: contain;
                }

                .divi-cont-before.divi-style, .divi-cont-after.divi-style {
                    flex: var(--flex-desktop);
                    width: var(--divider-width);
                }
                @media(max-width: 1024px) {
                    .divi-cont-before.divi-style, .divi-cont-after.divi-style {
                        flex: var(--flex-tablet);
                        width: var(--divider-width-tablet);
                    }
                }
                @media(max-width: 767px) {
                    .divi-cont-before.divi-style, .divi-cont-after.divi-style {
                        flex: var(--flex-mobile);
                        width: var(--divider-width-mobile);
                    }
                }
            `;
        },

        default() {
            return {
                settings: {
                    add_element: 'text',
                    gridColumnGap: '7px',
                    width: '100%',
                    text: '+',
                    tag: 'h2',
                    position: 'center',
                    icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 496 512" fill="currentColor"><!-- Font Awesome Free 5.15.3 by @fontawesome - https://fontawesome.com License - https://fontawesome.com/license/free (Icons: CC BY 4.0, Fonts: SIL OFL 1.1, Code: MIT License) --><path d="M248 167.5l64.9 98.8H183.1l64.9-98.8zM496 256c0 136.9-111.1 248-248 248S0 392.9 0 256 111.1 8 248 8s248 111.1 248 248zm-99.8 82.7L248 115.5 99.8 338.7h30.4l33.6-51.7h168.6l33.6 51.7h30.2z"></path></svg>',
                    justifyContent: 'center',
                    image: {
                        value: '/images/placeholder.png'
                    },
                    imageWidth: '50%'
                },
                style: {
                    divider: {
                        borderBottomWidth: '1px'
                    },
                    dividerGap: {
                        dividerPadding: {
                            top: '10px',
                            bottom: '10px'
                        }
                    },
                    image: {
                        imageWidth: '300px'
                    }
                }
            };
        }
    },
    methods: {
        quickToolBar() {
            return ['borderColor', 'borderBottomWidth'];
        },
        style() {
            let style = [
                {
                    group_name: 'divider',
                    group_title: this.$t('divider'),
                    selector: ' .ecom__element-divi .divi-style',
                    params: [
                        {
                            name: 'borderColor',
                            label: this.$t('color'),
                            type: 'color',
                            options: {
                                global: {
                                    type: 'colors'
                                },
                                oneline: true
                            },
                            css: {
                                properties: {
                                    'border-color': ''
                                }
                            }
                        },
                        {
                            name: 'borderBottomWidth',
                            label: this.$t('size'),
                            type: 'number',
                            liteMode: true,
                            options: {
                                units: {
                                    px: {
                                        min: 0,
                                        max: 100,
                                        step: 1
                                    }
                                }
                            },
                            css: {
                                properties: {
                                    'border-bottom-width': ''
                                }
                            }
                        }
                    ]
                },
                {
                    group_name: 'dividerGap',
                    group_title: this.$t('gap'),
                    selector: ' .ecom__element-divi',
                    params: [
                        {
                            name: 'dividerPadding',
                            type: 'dimension',
                            label: this.$t('gap'),
                            options: {
                                simple: true,
                                responsive: true,
                                units: 'default'
                            },
                            css: {
                                properties: {
                                    padding: ''
                                }
                            }
                        }
                    ]
                }
            ];
            if (this.divi.image && this.divi.type == 'image') {
                style.unshift({
                    group_alias: 'image',
                    options: {
                        group_title: this.$t('image'),
                        selector: ' .element__divi .ecom-image-default'
                    },
                    modify: {
                        remove: [
                            {
                                index: 0,
                                length: 1
                            },
                            {
                                index: 9,
                                length: 1
                            },
                            {
                                index: 10,
                                length: 1
                            },
                            {
                                index: 14,
                                length: 1
                            },
                            {
                                index: 15,
                                length: 1
                            }
                        ],
                        params: [
                            {
                                position: 1,
                                fields: {
                                    type: 'number',
                                    name: 'imageWidth',
                                    liteMode: true,
                                    label: this.$t('width'),
                                    options: {
                                        responsive: true,
                                        reset: true,
                                        units: {
                                            px: {
                                                min: 0,
                                                max: 1000
                                            },
                                            vw: {
                                                min: 0,
                                                max: 100
                                            }
                                        }
                                    },
                                    css: {
                                        important: true,
                                        selector: 'root .ecom__element-divi .ecom-image-default',
                                        properties: {
                                            width: ''
                                        }
                                    }
                                }
                            },
                            {
                            position:8,
                            fields:{
                                name: "imageBorder",
                            label: this.$t('border'),
                            type: "popup",
                            options: {
                                oneline: true,
                                type: "border",
                                size: "small",
                                visible: (data) => {
                                    return data['tab'] === 'normal'
                                }
                            },
                            css: {
                                selector: "root .ecom__element-divi picture img"
                            }
                            }
                            },
                            {
                            position:11,
                            fields:{
                                name: "imageBorderRadius",
                                label: this.$t("border_radius"),
                                type: "dimension",
                                options: {
                                    type: "radius",
                                    responsive: true,
                                    units: "default",
                                    visible: (data) => {
                                    return data['tab'] === 'normal'
                                }
                                },
                                css: {
                                    selector: "root .ecom__element-divi .ecom-image-default picture img",
                                    properties: {
                                        "border-radius": "",
                                        overflow:'hidden',

                                    }
                                }
                                },
                            },

                            {
                            position:15,
                            fields:{
                            name: "imageHoverBorder",
                            label: this.$t('border'),
                            type: "popup",
                            options: {
                                oneline: true,
                                type: "border",
                                size: "small",
                                visible: (data) => {
                                    return data['tab'] === 'hover'
                                }
                            },
                            css: {
                                selector: "root .ecom__element-divi picture img:hover"
                            }
                            }
                            },
                            {
                                position:18,
                                fields:{
                                    name: "imageBorderRadiusHover",
                                    label: this.$t("border_radius"),
                                    type: "dimension",
                                    options: {
                                        type: "radius",
                                        responsive: true,
                                        units: "default",
                                        visible: (data) => {
                                        return data['tab'] === 'hover'
                                    }
                                    },
                                    css: {
                                        selector: "root .ecom__element-divi .ecom-image-default picture img:hover",
                                        properties: {
                                            "border-radius": "",
                                            overflow:'hidden',

                                        }
                                    }
                                    },
                            },
                        ]
                    }
                });
            }
            if (this.divi.icon && this.divi.type == 'icon') {
                style.unshift({
                    group_name: 'divider_icon',
                    group_title: this.$t('icon'),
                    selector: ' .ecom__element-divi .divi-cont svg',
                    params: [
                        {
                            type: 'number',
                            label: this.$t('size'),
                            name: 'dividerIconWidth',
                            options: {
                                units: {
                                    px: {
                                        min: 6,
                                        max: 300
                                    }
                                }
                            },
                            css: {
                                properties: {
                                    width: ''
                                }
                            }
                        },
                        {
                            name: 'dividerIconFill',
                            label: this.$t('color'),
                            type: 'color',
                            options: {
                                global: {
                                    type: 'colors'
                                },
                                oneline: true
                            },
                            css: {
                                properties: {
                                    color: ''
                                }
                            }
                        },
                        {
                            name: 'dividerIconTransform',
                            label: this.$t('rotate'),
                            type: 'number',
                            options: {
                                min: 0,
                                max: 360,
                                step: 1
                            },
                            css: {
                                properties: {
                                    transform: 'rotate(%value%deg)'
                                }
                            }
                        }
                    ]
                });
            }
            if (this.divi.text && this.divi.type == 'text') {
                style.unshift({
                    group_name: 'divider_text',
                    group_title: this.$t('text'),
                    selector: ' .ecom__element-divi .divi-cont .divi-text',
                    params: [
                        {
                            type: 'color',
                            label: this.$t('color'),
                            name: 'color',
                            options: {
                                global: {
                                    type: 'colors'
                                },
                                oneline: true
                            },
                            css: {
                                properties: {
                                    color: ''
                                }
                            }
                        },
                        {
                            name: 'dividerTypography',
                            label: this.$t('typography'),
                            type: 'popup',
                            options: {
                                responsive: true,
                                oneline: true,
                                global: {
                                    type: 'typography'
                                },
                                type: 'typography'
                            },
                            css: {
                                // properties: {
                                //     typography: ''
                                // }
                            }
                        }
                    ]
                });
            }

            return style;
        }
    }
};
</script>
