<template>
    <div class="relative flex h-8">
        <input
            v-model="values['href']"
            type="text"
            placeholder="https://your-link.com"
            class="text-text-primary block h-full w-full px-3 py-2.5 border border-input outline-none pr-10 truncate transition rounded-lg placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none"
        >
        <EcomIcon :source="icons.SettingsMajor" @click="showInsertLink" class="absolute top-0 right-0 h-full !w-10 flex justify-center text-gray-500  transition cursor-pointer hover:text-gray-600 " :size="'w-5'"></EcomIcon>
        <InsertLink
            ref="insert-link"
            :data="values"
            :position="field.options?.position || 'absolute'"
            :aipath="(aipath ? `${aipath}.` : '') + field.name"
            :aichangeable="aichangeable"
            type="field"
            @update:link="updateLink"
        />
    </div>
</template>

<script lang="ts">
    import InsertLink from '../../components/editor/InsertLink/InsertLink.vue';
    import {SettingsMajor} from '@/assets/icons';
     export default {
        name: 'LinkField',
        components: {
            InsertLink
        },
        props: {
            data: {
                type: Object,
                default(){
                    return {};
                }
            },
            field: {
                type: Object,
                default () {
                    return {};
                }
            },
            aipath: {
                type: String,
                default: ''
            },
            aichangeable: {
                type: Boolean,
                default: false
            }
        },
        emits: ['update:data'],
        data(){
            return {
                values: {},
                isWatch: true,
                icons: {SettingsMajor},
                isEmit: false
            };
        },
        watch: {
            data: {
                immediate: true,
                deep: true,
                handler: function(val){
                    if(this.isWatch){
                        this.isEmit = false;
                        this.values = this.$helpers.copy(val);
                    }
                    this.isWatch = true;
                }
            },
            values: {
                immediate: true,
                deep: true,
                handler: function(val){
                    if(this.isEmit){
                        this.isWatch = false;
                        this.$emit('update:data', val);
                    }
                    this.isEmit = true;
                }
            }
        },
        methods: {
            showInsertLink(){
                let $inserLink = this.$refs['insert-link'];
                if($inserLink){
                    $inserLink.show = true;
                }
            },
            updateLink(values){
                this.values = values;
            }
        }
    };
</script>
