<i18n>
  {
    "en": {
      "from_this_template": "From this template",
      "from_your_store": "From your store",
      "template": "Template",
      "metaobjects": "Metaobjects",
      "market": "Market",
      "choose_metaobject_type": "Choose the metaobject type for this field:",
      "current_source": "Current source",
      "metaobject_types_hint": "Insertable: text, number, date, measurement, rating, money, link. Nested: single metaobject reference only.",
      "external_app_data_title": "This field references data from another app.",
      "external_app_data_desc": "EComposer cannot read metaobject fields owned by third-party apps — Shopify restricts cross-app access. This dynamic source cannot be inserted here. Use Shopify Theme Editor, or configure the data in the app that owns this metaobject."
    }
  }
</i18n>
<template>
  <PickerFrame
    :show="show"
    :header="headerFrame"
    :position="position"
    @close="show = false"
  >
    <template #content>
      <Loading
        v-if="loading"
        type="spin"
        :size="8"
        class="text-gray-800 transition mt-10 min-h-[100px]"
      />
      <div v-else class="relative h-full flex flex-col">

        <!-- Nguồn đang gắn với tag (chỉ có khi mở bằng nút "Change source") -->
        <div v-if="currentSource" class="ds-current-source">
          <span class="ds-current-source__label">{{ $t('current_source') }}</span>
          <span class="ds-current-source__title" :title="currentSourceLabel">{{ currentSourceLabel }}</span>
          <span class="ds-current-source__path" :title="currentSource.path">{{ currentSource.path }}</span>
        </div>

        <!-- ROOT VIEW -->
        <div v-if="currentView === 'root'" class="flex flex-col flex-1 overflow-y-auto px-3 py-2">
          <!-- Section 1: From this template -->
          <p class="ds-section-label">{{ $t('from_this_template') }}</p>
          <ul class="ds-list">
            <li class="ds-list-item" @click="currentView = 'template_fields'">
              <span class="ds-item-icon">
                <svg width="18" height="18" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M3 4a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4zm0 6a1 1 0 0 1 1-1h5a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1v-6zm9 0a1 1 0 0 1 1-1h3a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1h-3a1 1 0 0 1-1-1v-2zm0 5a1 1 0 0 1 1-1h3a1 1 0 0 1 1 1v1a1 1 0 0 1-1 1h-3a1 1 0 0 1-1-1v-1z" fill="currentColor"/>
                </svg>
              </span>
              <span class="ds-item-label">
                {{ $t('template') }}
                <span class="ds-item-chevron-label"> &rsaquo; </span>
                <strong>{{ templateLabel }}</strong>
              </span>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
          </ul>

          <!-- Section 2: From your store -->
          <p class="ds-section-label mt-3">{{ $t('from_your_store') }}</p>
          <ul class="ds-list">
            <li class="ds-list-item" @click="currentView = 'metaobjects_list'">
              <span class="ds-item-icon">
                <svg width="18" height="18" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M2 4a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v1a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V4zm0 6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v1a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2v-1zm0 6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v1a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2v-1z" fill="currentColor"/>
                </svg>
              </span>
              <span class="ds-item-label">{{ $t('metaobjects') }}</span>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
            <li class="ds-list-item" @click="currentView = 'market'">
              <span class="ds-item-icon">
                <svg width="18" height="18" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path fill-rule="evenodd" clip-rule="evenodd" d="M10 2a8 8 0 1 0 0 16A8 8 0 0 0 10 2zm-1 14.93V15a1 1 0 1 1 2 0v1.93A6.01 6.01 0 0 0 15.93 13H15a1 1 0 1 1 0-2h.93A6.01 6.01 0 0 0 11 6.07V7a1 1 0 1 1-2 0v-.93A6.01 6.01 0 0 0 4.07 11H5a1 1 0 1 1 0 2h-.93A6.01 6.01 0 0 0 9 16.93z" fill="currentColor"/>
                </svg>
              </span>
              <span class="ds-item-label">{{ $t('market') }}</span>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
          </ul>
        </div>

        <!-- TEMPLATE FIELDS VIEW (DS-02 sẽ fill nội dung) -->
        <div v-else-if="currentView === 'template_fields'" class="flex flex-col flex-1">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="currentView = 'root'">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title">{{ $t('template') }} &rsaquo; {{ templateLabel }}</span>
          </div>
          <!-- Notice: chỉ support text type -->
          <div v-if="compatibleMetafields?.length" class="max-w-[250px] mx-auto mt-2 flex relative w-full py-3 px-3 text-xs rounded text-gray-600 border border-[#E1B878] shadow-sm bg-[#FFF5EA] font-normal">
            <span class="w-5 mr-3 flex-shrink-0">
              <EcomIcon :source="CircleAlertMajor" :color="'text-yellow-600'"></EcomIcon>
            </span>
            <div class="text-xs">
              <strong>{{ $t("notice") }}: </strong>{{ $t("the_dynamic_content_can_only_work_with_the_metafield_type_single_line_text_and_multi_line_text_and_rich_text") }}
            </div>
          </div>
          <div class="overflow-y-auto flex-1 px-3 pb-2 mt-2">
            <!-- Predefined sources -->
            <ul v-if="dynamicSource?.length">
              <li
                v-for="(item, index) in dynamicSource"
                :key="'src-' + index"
                class="py-2 cursor-pointer leading-4 text-xs line-clamp-2 grid item-source"
                :class="{ active: activeRowKey === 'tpl-src-' + index }"
                @click="insertSource($event, item, 'tpl-src-' + index)"
              >
                <span class="rounded-full w-4 h-4 block border border-black pointer-events-none relative radio"></span>
                <span class="ml-2 pointer-events-none">{{ item?.title }}</span>
              </li>
            </ul>
            <!-- Metafields from API — DS-05: đã lọc theo type tương thích (giống theme) -->
            <ul v-if="compatibleMetafields?.length">
              <li
                v-for="(item, index) in compatibleMetafields"
                :key="'meta-' + index"
                class="py-2 cursor-pointer leading-4 text-xs line-clamp-2 grid item-source"
                :class="{ active: activeRowKey === 'tpl-meta-' + index }"
                @click="insertMeta($event, item, 'tpl-meta-' + index)"
              >
                <span class="rounded-full w-4 h-4 block border border-black pointer-events-none relative radio"></span>
                <span class="ml-2 pointer-events-none">{{ item?.node?.name }}</span>
              </li>
            </ul>
          </div>
          <!-- Footer: type selector + select button -->
          <div class="px-3 pt-2 pb-3 border-t border-dashed border-gray-200">
            <div class="text-xs mb-2">
              <span class="block">{{ $t("type") }}: </span>
              <select
                :disabled="!show_choice"
                :class="!show_choice ? 'select-disable' : ''"
                class="text-xs border border-gray-600 mt-1 py-2 rounded px-2 w-full"
                ref="type"
              >
                <option value="text">{{ $t("text") }}</option>
                <option value="richtext">{{ $t("rich_text") }}</option>
              </select>
            </div>
            <button
              :disabled="typeDynamic === ''"
              @click="handleSelect"
              :class="typeDynamic === '' ? 'cursor-not-allowed opacity-60 bg-slate-50' : 'cursor-pointer !text-white !bg-dark'"
              class="outline-interactive-600 transition flex gap-1 px-3 inline-flex items-center justify-center font-medium text-xs rounded-lg h-7 hover:bg-gray-100 ecom-publish-buttton bg-gray-100 text-gray-400 rounded-lg shadow-button"
            >
              <span>{{ $t("select") }}</span>
            </button>
          </div>
        </div>

        <!-- METAOBJECTS LIST VIEW (DS-03) -->
        <div v-else-if="currentView === 'metaobjects_list'" class="flex flex-col flex-1 overflow-x-hidden min-h-[100px] ">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="currentView = 'root'">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title">{{ $t('metaobjects') }}</span>
          </div>
          <!-- Giới hạn của metaobject — bám sát đúng bộ lọc ở computed currentNavFields:
               field lá phải thuộc DYNAMIC_TEXT_COMPATIBLE_TYPES, còn field lồng nhau thì
               backend chỉ đánh dấu isReference cho đúng kiểu `metaobject_reference`.
               Để dạng gợi ý mờ thay vì khung cảnh báo: đây là thông tin tham khảo,
               không phải lỗi. Danh sách kiểu đầy đủ nằm ở tooltip. -->
          <p
            v-if="!metaobjectsLoading && metaobjects.length"
            class="ds-types-hint"
            :title="supportedFieldTypeLabels.join(', ')"
          >
            <!-- Icon cảnh báo tròn, cùng kiểu với khung notice ở view Template fields -->
            <svg width="16" height="16" viewBox="0 0 20 20" fill="currentColor" xmlns="http://www.w3.org/2000/svg">
              <path fill-rule="evenodd" clip-rule="evenodd" d="M10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16zM9 6a1 1 0 0 1 2 0v5a1 1 0 1 1-2 0V6zm2 8a1 1 0 1 1-2 0 1 1 0 0 1 2 0z"/>
            </svg>
            <span>{{ $t('metaobject_types_hint') }}</span>
          </p>
          <!-- Loading -->
          <div v-if="metaobjectsLoading" class="flex-1 flex items-center justify-center">
            <Loading type="spin" :size="6" class="text-gray-500" />
          </div>
          <!-- Empty state -->
          <div v-else-if="!metaobjects.length" class="flex-1 flex flex-col items-center justify-center px-4 text-center gap-2">
            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" class="text-gray-300">
              <path d="M20 7H4a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2zm-9 5H4V9h7v3zm9 0h-7V9h7v3z" fill="currentColor"/>
            </svg>
            <p class="text-xs text-gray-400">No metaobject definitions found in your store.</p>
          </div>
          <!-- List definitions -->
          <ul v-else class="overflow-y-auto flex-1 px-3 py-2">
            <li
              v-for="def in metaobjects"
              :key="def.type"
              class="ds-list-item ds-list-item--bordered"
              @click="selectMetaobjectDefinition(def)"
            >
              <span class="ds-item-icon">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M3 4a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4zm0 5a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9zm1 4a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2H4z" fill="currentColor"/>
                </svg>
              </span>
              <span class="ds-item-label">{{ def.name }}</span>
              <span class="text-xs text-gray-400 mr-1">{{ def.fieldDefinitions.length }}</span>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
          </ul>
        </div>

        <!-- METAOBJECT ENTRIES VIEW (DS-03 redesign) -->
        <div v-else-if="currentView === 'metaobject_entries'" class="flex flex-col flex-1 min-h-[100px]">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="handleEntriesBack">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title ds-breadcrumb">{{ metaobjectNavStack[0]?.defName || $t('metaobjects') }}</span>
          </div>

          <!-- Loading entries -->
          <div v-if="entriesLoading" class="flex-1 flex items-center justify-center gap-2 text-xs text-gray-400">
            <Loading type="spin" :size="5" class="text-gray-400" />
            <span>Loading entries…</span>
          </div>

          <!-- Entries list -->
          <ul v-else-if="currentEntries.length" class="overflow-y-auto flex-1 px-3 pt-2">
            <li
              v-for="entry in currentEntries"
              :key="entry.handle"
              class="ds-list-item ds-list-item--bordered"
              @click="selectEntry(entry)"
            >
              <span class="ds-item-icon">
                <svg width="14" height="14" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M10 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm-7 9a7 7 0 1 1 14 0H3z" fill="currentColor"/>
                </svg>
              </span>
              <span class="ds-item-label flex-1 flex flex-col">
                {{ entry.title }}
                <span class="block text-gray-400 font-mono text-[10px] mt-0.5">{{ entry.handle }}</span>
              </span>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
          </ul>

          <!-- Error state -->
          <div v-else-if="entriesError" class="flex-1 flex flex-col items-center justify-center px-4 text-center gap-2">
            <p class="text-xs text-red-500">{{ entriesError }}</p>
          </div>

          <!-- Empty state -->
          <div v-else class="flex-1 flex flex-col items-center justify-center px-4 text-center gap-2">
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" class="text-gray-300">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 0 1 0-5 2.5 2.5 0 0 1 0 5z" fill="currentColor"/>
            </svg>
            <p class="text-xs text-gray-400">No entries found for this type.</p>
          </div>

          <!-- Divider + via metafield option -->
          <!-- TEMPORARILY HIDDEN: manual "Connect via metafield reference" form.
               Requires deep Liquid/metafield knowledge and free-text namespace/key can
               produce invalid Liquid paths that only fail at publish time.
               Underlying logic kept intact (selectViaMetafield + via_metafield branch in
               buildMetaobjectPath) so this can be re-enabled easily. -->
          <!--
          <div class="px-3 pb-3 border-t border-dashed border-gray-200 pt-3">
            <button
              v-if="!showMetafieldForm"
              class="w-full text-xs text-indigo-600 hover:text-indigo-800 text-left flex items-center gap-1.5 py-1"
              @click="showMetafieldForm = true"
            >
              <svg width="14" height="14" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M2.003 5.884L10 9.882l7.997-3.998A2 2 0 0 0 16 4H4a2 2 0 0 0-1.997 1.884zM18 8.118l-8 4-8-4V14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8.118z" fill="currentColor"/>
              </svg>
              Connect via metafield reference
            </button>
            <div v-else class="flex flex-col gap-2  flex-col" >
              <p class="text-xs text-gray-500 font-medium">Connect via metafield reference</p>
              <p class="text-xs text-gray-400">The metafield whose value is this metaobject.</p>
