                <input
                  v-model="metaobjectRefKey"
                  placeholder="key"
                  class="ds-text-input flex-1"
                  spellcheck="false"
                />
              </div>
              <div class="flex gap-2">
                <button
                  class="text-xs text-gray-400 hover:text-gray-600 py-1"
