              </div>
            </div>
          </div>
          -->
        </div>

        <!-- METAOBJECT FIELDS VIEW (DS-03 redesign: instant insert, no select button) -->
        <div v-else-if="currentView === 'metaobject_fields'" class="flex flex-col flex-1 min-h-[100px]">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="handleMetaobjectBack">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title ds-breadcrumb" :title="metaobjectBreadcrumb">
              {{ metaobjectBreadcrumb || $t('metaobjects') }}
            </span>
          </div>

          <!-- Field list: leaf = instant insert, reference = drill into -->
          <div class="overflow-y-auto flex-1 px-3 pb-2 mt-2">
            <!-- Resolving spinner -->
            <div v-if="resolvingRefField" class="flex items-center justify-center py-6 gap-2 text-xs text-gray-400">
              <Loading type="spin" :size="4" class="text-gray-400" />
              <span>Resolving type…</span>
            </div>
            <ul v-else-if="currentNavFields.length">
              <li
                v-for="(field, index) in currentNavFields"
                :key="'mobj-' + index"
                :class="[
                  field.isReference ? 'ds-ref-item' : 'ds-leaf-item',
                  { active: !field.isReference && activeRowKey === 'mobj-' + index }
                ]"
                class="py-2 cursor-pointer leading-4 text-xs grid"
                @click="field.isReference ? drillIntoReferenceField(field) : selectMetaobjectField($event, field, 'mobj-' + index)"
              >
                <!-- Leaf: radio dot -->
                <span v-if="!field.isReference" class="rounded-full w-4 h-4 block border border-black pointer-events-none relative radio flex-shrink-0"></span>
                <!-- Reference: folder icon -->
                <span v-else class="ds-item-icon pointer-events-none flex-shrink-0">
                  <svg width="14" height="14" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M3 4a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4zm0 5a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9zm1 4a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2H4z" fill="currentColor"/>
                  </svg>
                </span>
                <span class="ml-2 pointer-events-none flex-1 flex flex-col">
                  {{ field.name }}
                  <span class="text-gray-400">({{ field.type }})</span>
                </span>
                <!-- Reference: chevron right -->
                <span v-if="field.isReference" class="ds-item-chevron pointer-events-none">
                  <svg width="14" height="14" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                  </svg>
                </span>
              </li>
            </ul>
            <p v-else class="text-xs text-gray-400 text-center mt-6">No fields found.</p>
          </div>

          <!-- Footer: base path + liquid preview + Select button -->
          <div class="px-3 pt-2 pb-3 border-t border-dashed border-gray-200 flex flex-col gap-2">
            <p class="ds-liquid-preview text-[10px] text-gray-400 font-mono truncate" :title="metaobjectBasePath">
              <span class="opacity-60">base: </span>{{ metaobjectBasePath }}
            </p>
            <!-- Liquid path preview for the currently selected leaf field -->
            <p v-if="typeDynamic === 'metaobject'" class="ds-liquid-preview" :title="metaobjectLiquidPreview">
              <span class="opacity-50">&#123;&#123;</span>
              {{ metaobjectLiquidPreview }}
              <span class="opacity-50">&#125;&#125;</span>
            </p>
            <button
              :disabled="typeDynamic !== 'metaobject'"
              @click="handleSelect"
              :class="typeDynamic !== 'metaobject' ? 'cursor-not-allowed opacity-60 bg-slate-50' : 'cursor-pointer !text-white !bg-dark'"
              class="outline-interactive-600 transition flex gap-1 px-3 inline-flex items-center justify-center font-medium text-xs rounded-lg h-7 hover:bg-gray-100 ecom-publish-buttton bg-gray-100 text-gray-400 rounded-lg shadow-button"
            >
              <span>{{ $t("select") }}</span>
            </button>
          </div>
        </div>

        <!-- SELECT REF DEFINITION VIEW (DS-03-1: fallback khi referencedType = null) -->
        <div v-else-if="currentView === 'select_ref_definition'" class="flex flex-col flex-1">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="currentView = 'metaobject_fields'; pendingRefField = null; pendingRefRawValue = null">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title ds-breadcrumb" :title="metaobjectBreadcrumb">
              {{ metaobjectBreadcrumb }} › <em class="text-gray-400 not-italic">{{ pendingRefField?.name }}</em>
            </span>
          </div>
          <!-- Hint -->
          <p class="text-xs text-gray-500 px-3 pt-2 pb-1">{{ $t('choose_metaobject_type') }}</p>
          <!-- List all definitions to choose from -->
          <ul class="overflow-y-auto flex-1 px-3 pb-2">
            <li
              v-for="def in metaobjects"
              :key="def.type"
              class="ds-list-item ds-list-item--bordered"
              @click="confirmRefDefinition(def)"
            >
              <span class="ds-item-icon">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M3 4a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4zm0 5a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9zm1 4a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2H4z" fill="currentColor"/>
                </svg>
              </span>
              <div class="flex items-start flex-1 gap-1 flex-col">
                <span class="ds-item-label">{{ def.name }}</span>
                <span class="text-xs text-gray-400">{{ def.type }}</span>
              </div>
              <span class="ds-item-chevron">
                <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M7.293 4.293a1 1 0 0 1 1.414 0l5 5a1 1 0 0 1 0 1.414l-5 5a1 1 0 0 1-1.414-1.414L11.586 10 7.293 5.707a1 1 0 0 1 0-1.414z" fill="currentColor"/>
                </svg>
              </span>
            </li>
          </ul>
        </div>

        <!-- DS-05-1: cảnh báo metaobject app-owned — EComposer không đọc được, không cho insert -->
        <div v-else-if="currentView === 'metaobject_unresolved_ref'" class="flex flex-col flex-1">
          <div class="ds-subview-header">
            <button
              class="ds-back-btn"
              @click="currentView = 'metaobject_fields'; pendingRefField = null; pendingRefRawValue = null"
            >
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title ds-breadcrumb" :title="metaobjectBreadcrumb">
              {{ metaobjectBreadcrumb }} › <em class="text-gray-400 not-italic">{{ pendingRefField?.name }}</em>
            </span>
          </div>

          <div class="overflow-y-auto flex-1 px-3 pt-2 pb-3">
            <div class="flex relative w-full py-3 px-3 text-xs rounded text-gray-600 border border-[#E1B878] shadow-sm bg-[#FFF5EA] font-normal gap-3">
              <span class="w-5 flex-shrink-0">
                <EcomIcon :source="CircleAlertMajor" :color="'text-yellow-600'"></EcomIcon>
              </span>
              <div class="text-xs leading-5">
                <strong>{{ $t('external_app_data_title') }}</strong>
                {{ $t('external_app_data_desc') }}
              </div>
            </div>
          </div>
        </div>

        <!-- MARKET VIEW (DS-04) -->
        <div v-else-if="currentView === 'market'" class="flex flex-col flex-1">
          <div class="ds-subview-header">
            <button class="ds-back-btn" @click="currentView = 'root'">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.707 4.293a1 1 0 0 1 0 1.414L8.414 10l4.293 4.293a1 1 0 0 1-1.414 1.414l-5-5a1 1 0 0 1 0-1.414l5-5a1 1 0 0 1 1.414 0z" fill="currentColor"/>
              </svg>
            </button>
            <span class="ds-subview-title">Market</span>
          </div>
          <!-- Flat list — không có loading (hardcoded) -->
          <div class="overflow-y-auto flex-1 px-3 pb-2 mt-2">
            <ul>
              <li
                v-for="(source, index) in marketSources"
                :key="'market-' + index"
                class="py-2 cursor-pointer leading-4 text-xs grid item-source"
                :class="{ active: activeRowKey === 'market-' + index }"
                @click="insertSource($event, source, 'market-' + index)"
              >
                <span class="rounded-full w-4 h-4 block border border-black pointer-events-none relative radio flex-shrink-0"></span>
                <span class="ml-2 pointer-events-none">
                  {{ source.title }}
                  <span class="block text-gray-400 font-mono text-[10px] mt-0.5">{{ source.key }}</span>
                </span>
              </li>
            </ul>
          </div>
          <!-- Footer: select button -->
          <div class="px-3 pt-2 pb-3 border-t border-dashed border-gray-200">
            <button
              :disabled="typeDynamic !== 'source'"
              @click="handleSelect"
              :class="typeDynamic !== 'source' ? 'cursor-not-allowed opacity-60 bg-slate-50' : 'cursor-pointer !text-white !bg-dark'"
              class="outline-interactive-600 transition flex gap-1 px-3 inline-flex items-center justify-center font-medium text-xs rounded-lg h-7 hover:bg-gray-100 ecom-publish-buttton bg-gray-100 text-gray-400 rounded-lg shadow-button"
            >
              <span>{{ $t("select") }}</span>
            </button>
          </div>
        </div>

      </div>
    </template>
  </PickerFrame>
</template>

<script lang="ts">
  import { mapGetters } from 'vuex';
  import { CircleAlertMajor } from '@/assets/icons';
  import PickerFrame from '../../picker/PickerFrame.vue';
  import PickerFooter from '../../picker/PickerFooter.vue';
  import { clickOutside } from '../../../directives';
  import { isDynamicFieldTypeCompatible, DYNAMIC_TEXT_COMPATIBLE_TYPES } from '@/store/modules/dynamicSources';
  import { ensureMetaobjectScopes } from '@/utils/metaobjectScopes';

  export default {
    name: 'InsertLink',
    directives: {
      clickOutside
    },
    components: {
      PickerFrame,
      PickerFooter
    },
    props: {
      data: {
        type: Object,
        default() {
          return {};
        }
      },
      type: {
        type: String,
        default: 'editor'
      },
      position: {
        type: String,
        default: 'absolute'
      }
    },
    emits: ['close_popup', 'update:metafield'],
    data() {
      return {
        show_choice: false,
        CircleAlertMajor,
        show: false,
        valueDynamic: null as any,
        typeDynamic: '',
        value: {},
        attributes: '',
        styleGroupTyles: {},
        // DS-01: state machine cho navigation
        currentView: 'root' as 'root' | 'template_fields' | 'metaobjects_list' | 'metaobject_entries' | 'metaobject_fields' | 'market' | 'select_ref_definition' | 'metaobject_unresolved_ref',
        // DS-03 redesign: nav stack — mỗi phần tử = 1 level đang xem
        // Level 0 (root): { defType, defName, fieldKey: '', fieldName: '' }
        // Level N (nested ref): { defType, defName, fieldKey, fieldName }
        metaobjectNavStack: [] as Array<{
          defType: string;
          defName: string;
          fieldKey: string;
          fieldName: string;
        }>,
        // DS-03 redesign: entry đang được chọn (null khi via-metafield mode)
        selectedEntry: null as { handle: string; title: string } | null,
        // DS-03 redesign: 'entry' = locked handle, 'via_metafield' = metafield ref
        metaobjectAccessMode: 'entry' as 'entry' | 'via_metafield',
        // Metafield ref path (via_metafield mode)
        metaobjectRefNamespace: '' as string,
        metaobjectRefKey: '' as string,
        // Entries list for the entry picker view
        currentEntries: [] as Array<{ handle: string; title: string }>,
        entriesLoading: false,
        entriesError: '' as string,
        // Toggle the via-metafield inline form in metaobject_entries view
        showMetafieldForm: false,
        // DS-03-1: field đang chờ user chọn definition (khi referencedType = null)
        pendingRefField: null as any,
        // DS-03-1: đang resolve referencedType từ actual entry
        resolvingRefField: false,

        // DS-05-1: raw value (string) của pendingRefField khi referencedType không resolve được
        // nhưng field vẫn có data thật (permission dead-end — metaobject app-owned của app khác)
        pendingRefRawValue: null as string | null,

        // Nguồn đang gắn với tag khi mở panel bằng nút "Change source".
        // Editor.vue gán TRỰC TIẾP vào đây trước khi bật `show` (xem eventAction).
        // null = đang chèn tag mới.
        currentSource: null as { title: string; fullTitle?: string; path: string; key: string } | null,
        // Tên đầy đủ dựng lại từ nguồn khớp được — chính xác hơn cả data-title-full
        // và áp dụng được cho cả tag cũ (vốn chỉ lưu bản đã cắt).
        resolvedTitle: '' as string,
        // Row đang được chọn — thay cho việc thêm class .active bằng DOM, để có thể
        // tick sẵn item ứng với currentSource ngay khi panel mở.
        activeRowKey: '' as string,
        // Đang dựng lại state metaobject (chờ API) — chặn chạy trùng.
        restoringSource: false,
      };
    },
    computed: {
      headerFrame() {
        return {
          title: this.$t("insert_dynamic_sources"),
          icon: `<svg width="16" height="14" viewBox="0 0 16 14" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><path d="M7.53846 5.38462C11.7018 5.38462 15.0769 4.17846 15.0769 2.69231C15.0769 1.20615 11.7018 0 7.53846 0C3.37508 0 0 1.20615 0 2.69231C0 4.17846 3.37508 5.38462 7.53846 5.38462ZM7.53846 7.53846C10.6292 7.53846 13.286 6.874 14.4502 5.92308C14.8529 6.25262 15.0769 6.61662 15.0769 7C15.0769 8.48615 11.7018 9.69231 7.53846 9.69231C3.37508 9.69231 0 8.48615 0 7C0 6.61662 0.224 6.25262 0.626769 5.92308C1.78985 6.874 4.44769 7.53846 7.53846 7.53846ZM7.53846 11.8462C10.6292 11.8462 13.286 11.1817 14.4502 10.2308C14.8529 10.5603 15.0769 10.9243 15.0769 11.3077C15.0769 12.7938 11.7018 14 7.53846 14C3.37508 14 0 12.7938 0 11.3077C0 10.9243 0.224 10.5603 0.626769 10.2308C1.78985 11.1817 4.44769 11.8462 7.53846 11.8462Z" fill="currentColor"/></svg>`,
          search: {
            show: false,
            value: ''
          },
          alignLeft: true
        };
      },
      params() {
        return this.$store.getters['page/params'];
      },
      templateLabel(): string {
        const labels: Record<string, string> = {
          product: 'Product',
          collection: 'Collection',
          page: 'Page',
          article: 'Article',
          blog: 'Blog',
          post: 'Article',
          shop: 'Shop',
        };
        if (this.normalizedShopifyType === 'shop') return 'Shop';
        return labels[this.shopifyType] || (this.shopifyType ? this.shopifyType.charAt(0).toUpperCase() + this.shopifyType.slice(1) : 'Template');
      },
      // DS-03 redesign: fields của definition tại đỉnh stack hiện tại
      // DS-05: lọc theo bảng tương thích type của Shopify — field reference (isReference)
      // luôn hiện (để drill-down), field lá phải nằm trong DYNAMIC_TEXT_COMPATIBLE_TYPES.
      currentNavFields(): any[] {
        const stack = (this as any).metaobjectNavStack as any[];
        if (!stack.length) return [];
        const top = stack[stack.length - 1];
        const fields = (this as any).definitionsByType?.[top.defType]?.fieldDefinitions ?? [];
        return fields.filter((f: any) => f.isReference || isDynamicFieldTypeCompatible(f.type));
      },
      /** Tên nguồn hiện tại cho banner, ưu tiên bản đầy đủ nhất có được:
       *  dựng lại từ nguồn khớp → data-title-full (tag mới) → data-title (tag cũ). */
      currentSourceLabel(): string {
        const self = this as any;
        return self.resolvedTitle || self.currentSource?.fullTitle || self.currentSource?.title || '';
      },
      /** Nhãn dễ đọc của các kiểu field chèn được. Lấy thẳng từ
       *  DYNAMIC_TEXT_COMPATIBLE_TYPES để notice không bao giờ lệch với bộ lọc thật;
       *  kiểu mới chưa có nhãn thì hiện luôn key gốc thay vì biến mất. */
      supportedFieldTypeLabels(): string[] {
        const labels: Record<string, string> = {
          single_line_text_field: 'Single line text',
          'list.single_line_text_field': 'List of single line text',
          multi_line_text_field: 'Multi-line text',
          rich_text_field: 'Rich text',
          number_integer: 'Integer',
          number_decimal: 'Decimal',
          date: 'Date',
          date_time: 'Date and time',
          weight: 'Weight',
          volume: 'Volume',
          dimension: 'Dimension',
          rating: 'Rating',
          money: 'Money',
          link: 'Link',
        };
        return DYNAMIC_TEXT_COMPATIBLE_TYPES.map((type) => labels[type] || type);
      },
      // DS-05: metafields từ API — lọc theo type tương thích (giống theme)
      compatibleMetafields(): any[] {
        const list = (this as any).metafileds || [];
        return list.filter((item: any) => isDynamicFieldTypeCompatible(item?.node?.type?.name));
      },
      // DS-03 redesign: breadcrumb — "Podcast › vanh3452 › Schedule › Day"
      // Includes entry title (entry mode) or metafield ref (via_metafield mode) after root def
      metaobjectBreadcrumb(): string {
        const stack = (this as any).metaobjectNavStack as any[];
        if (!stack.length) return '';
        const parts: string[] = [stack[0].defName];
        const entry = (this as any).selectedEntry as { handle: string; title: string } | null;
        if ((this as any).metaobjectAccessMode === 'entry' && entry?.title) {
          parts.push(entry.title);
        } else if ((this as any).metaobjectAccessMode === 'via_metafield') {
          const ns = (this as any).metaobjectRefNamespace;
          const k  = (this as any).metaobjectRefKey;
          if (ns && k) parts.push(`${ns}.${k}`);
        }
        for (let i = 1; i < stack.length; i++) {
          parts.push((stack[i] as any).fieldName || (stack[i] as any).fieldKey);
        }
        return parts.join(' › ');
      },
      // DS-03 redesign: the "base" Liquid prefix for this metaobject context
      // entry mode:       metaobjects.TYPE['handle']
      // via_metafield:    owner.metafields.ns.key.value
      metaobjectBasePath(): string {
        const stack = (this as any).metaobjectNavStack as any[];
        if (!stack.length) return '';
        const rootDefType = stack[0].defType;
        if ((this as any).metaobjectAccessMode === 'entry') {
          const handle = (this as any).selectedEntry?.handle || '';
          const typeAccess = /^[a-zA-Z0-9_]+$/.test(rootDefType)
            ? `.${rootDefType}`
            : `['${rootDefType}']`;
          return `metaobjects${typeAccess}${(this as any).liquidBracketKey(handle)}`;
        }
        const ns    = (this as any).metaobjectRefNamespace || '{namespace}';
        const k     = (this as any).metaobjectRefKey || '{key}';
        const owner = this.normalizedShopifyType || 'product';
        return `${owner}.metafields.${ns}.${k}.value`;
      },
      // Live preview of the Liquid path for the currently selected metaobject field
      metaobjectLiquidPreview(): string {
        if (this.typeDynamic !== 'metaobject' || !(this.valueDynamic as any)?.field) return '';
        return (this as any).buildMetaobjectPath((this.valueDynamic as any).field.key);
      },
      ...mapGetters('dynamicSources', [
        'metafileds', 'dynamicSource', 'loading', 'shopifyType', 'normalizedShopifyType',
        'metaobjects', 'metaobjectsLoaded', 'metaobjectsLoading',
        'definitionsByType',
        'marketSources',
      ]),
    },
    watch: {
      show(val) {
        if (val) {
          // Chỉ xin scope metaobject khi user thực sự mở panel — component này được
          // mount sẵn cùng Editor (để giữ $refs), nên nếu gọi trong mounted() thì chỉ
          // cần chọn 1 element text là đã bật dialog xin quyền.
          (this as any).ensureMetaobjectScopes();
          // Mở bằng "Change source" → nhảy thẳng tới nguồn đang dùng và tick sẵn.
          (this as any).applyCurrentSource();
        } else {
          this.currentView = 'root';
          this.valueDynamic = null;
          this.typeDynamic = '';
          this.show_choice = false;
          (this as any).metaobjectNavStack = [];
          (this as any).selectedEntry = null;
          (this as any).metaobjectAccessMode = 'entry';
          (this as any).metaobjectRefNamespace = '';
          (this as any).metaobjectRefKey = '';
          (this as any).currentEntries = [];
          (this as any).entriesLoading = false;
          (this as any).entriesError = '';
          (this as any).showMetafieldForm = false;
          (this as any).pendingRefField = null;
          (this as any).resolvingRefField = false;
          (this as any).pendingRefRawValue = null;
          (this as any).currentSource = null;
          (this as any).resolvedTitle = '';
          (this as any).activeRowKey = '';
          (this as any).restoringSource = false;
        }
      },
      // Metafields load bất đồng bộ. Nếu panel mở trước khi API trả về thì lần dò đầu
      // không khớp được — thử lại khi có data, nhưng chỉ khi user chưa tự điều hướng.
      metafileds() {
        const self = this as any;
        if (self.show && self.currentSource && !self.typeDynamic && self.currentView === 'root') {
          self.applyCurrentSource();
        }
      },
      async currentView(val) {
        // DS-03: tự động load metaobjects khi vào view (lazy load)
        if (val === 'metaobjects_list') {
          // Chờ scope xong rồi mới query, tránh gọi API khi quyền chưa được cấp.
          await (this as any).ensureMetaobjectScopes();
          this.$store.dispatch('dynamicSources/loadMetaobjects');
        }
      },
    },
    methods: {
      /**
       * Chuyển sang helper dùng chung `utils/metaobjectScopes` để element Metafields
       * và panel này chia sẻ CÙNG một promise — nếu mỗi bên giữ promise riêng thì
       * merchant bị Shopify hỏi quyền hai lần.
       */
      ensureMetaobjectScopes(): Promise<void> {
        return ensureMetaobjectScopes();
      },
      truncateTitle(title: string) {
        return title.length <= 10 ? title : title.slice(0, 10) + '...';
      },
      toLiquidVarKey(value: string) {
        const key = value.replace(/[^a-zA-Z0-9_]/g, '_').replace(/^[0-9]/, '_$&');
        return key || 'meta';
      },
      /** Bracket key for Liquid — single quotes avoid breaking HTML double-quoted attributes. */
      liquidBracketKey(key: string) {
        return `['${String(key).replace(/'/g, "\\'")}']`;
      },
      /** Build ecom-meta-editor wrapper with a dynamic-meta child (safe attribute encoding). */
      createDynamicMetaSpan(metaKey: string, liquidPath: string, title: string) {
        const metaSpan = document.createElement('span');
        metaSpan.className = 'ecom-dynamic-meta';
        metaSpan.setAttribute('data-meta-key', metaKey);
        metaSpan.setAttribute('data-meta', liquidPath);
        const shortTitle = this.truncateTitle(title);
        metaSpan.setAttribute('data-title', shortTitle);
        // Nhãn trên chip buộc phải ngắn (CSS dùng attr(data-title)), nhưng panel
        // "Current source" cần tên đầy đủ → lưu riêng, chỉ khi thực sự bị cắt.
        // Export bỏ nguyên span này nên attribute thừa không lọt ra trang live.
        if (shortTitle !== title) {
          metaSpan.setAttribute('data-title-full', title);
        }
        const wrapper = document.createElement('span');
        wrapper.classList.add('ecom-meta-editor');
        wrapper.setAttribute('contenteditable', 'false');
        wrapper.appendChild(document.createTextNode(' '));
        wrapper.appendChild(metaSpan);
        wrapper.appendChild(document.createTextNode(' '));
        return wrapper;
      },
      /** Derive stable Liquid var key from data-meta path (avoids i18n title collisions). */
      resolveDynamicMetaKey(rawKey: string, liquidPath = '') {
        const basePath = liquidPath.split('|')[0].trim();
        const metafieldMatch = basePath.match(/\.metafields\.([^.]+)\.([^.\s|]+)/);
        if (metafieldMatch) {
          return this.toLiquidVarKey(`${metafieldMatch[1]}_${metafieldMatch[2]}`);
        }
        const objectMatch = basePath.match(/^([a-zA-Z_][a-zA-Z0-9_]*)\.(.+)$/);
        if (objectMatch) {
          return this.toLiquidVarKey(`${objectMatch[1]}_${objectMatch[2].replace(/\./g, '_')}`);
        }
        if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(basePath)) {
          return this.toLiquidVarKey(basePath);
        }
        return this.toLiquidVarKey(rawKey);
      },
      insertMeta(event: Event, meta: any, rowKey = '') {
        (this as any).activeRowKey = rowKey;
        this.valueDynamic = meta;
        this.typeDynamic = 'meta';
        this.show_choice = true;
      },
      insertSource(event: Event, source: any, rowKey = '') {
        (this as any).activeRowKey = rowKey;
        this.valueDynamic = source;
        this.typeDynamic = 'source';
        this.show_choice = false;
      },
      /** Dò ngược liquid path của tag đang sửa → mở đúng view và tick sẵn item.
       *  Chỉ xử lý Template / Metafield / Market vì 3 loại này khớp được bằng so chuỗi.
       *  Metaobject cần load definitions + entries mới dựng lại được đường dẫn nên chỉ
       *  hiện banner, user tự điều hướng. */
      /** Tìm index theo liquid path. `marketSources` có 2 dòng trùng key
       *  (Market name / Country name đều là localization.country.name) nên khi trùng
       *  thì so thêm data-title để tick đúng dòng. */
      findSourceIndex(list: any[], path: string, title: string): number {
        const matches: number[] = [];
        (list || []).forEach((item: any, index: number) => {
          if (item?.key === path) matches.push(index);
        });
        if (!matches.length) return -1;
        if (matches.length === 1 || !title) return matches[0];
        const exact = matches.find(
          (index) => this.truncateTitle(String(list[index]?.title ?? '')) === title
        );
        return exact === undefined ? matches[0] : exact;
      },
      applyCurrentSource() {
        const self = this as any;
        const path = self.currentSource?.path ? String(self.currentSource.path).trim() : '';
        if (!path) return;
        const title = String(self.currentSource?.title ?? '');

        // 1. Nguồn có sẵn của template (product.title, page.content…) — khớp nguyên chuỗi key
        const tplIndex = self.findSourceIndex(self.dynamicSource, path, title);
        if (tplIndex > -1) {
          this.currentView = 'template_fields';
          this.valueDynamic = self.dynamicSource[tplIndex];
          this.typeDynamic = 'source';
          this.show_choice = false;
          self.activeRowKey = `tpl-src-${tplIndex}`;
          self.resolvedTitle = self.dynamicSource[tplIndex]?.title || '';
          return;
        }

        // 2. Market (localization.*)
        const marketIndex = self.findSourceIndex(self.marketSources, path, title);
        if (marketIndex > -1) {
          this.currentView = 'market';
          this.valueDynamic = self.marketSources[marketIndex];
          this.typeDynamic = 'source';
          this.show_choice = false;
          self.activeRowKey = `market-${marketIndex}`;
          self.resolvedTitle = self.marketSources[marketIndex]?.title || '';
          return;
        }

        // 3. Metaobject. Phải đặt TRƯỚC bước metafield vì path chế độ via_metafield
        //    ({owner}.metafields.ns.key.value.field.value) cũng chứa `.metafields.`,
        //    để không bị bước dưới nhận nhầm thành một metafield thường.
        const metaobject = self.parseMetaobjectPath(path);
        if (metaobject) {
          // via_metafield: path không chứa định nghĩa gốc nên không dựng lại được
          // → chỉ hiện banner. Vẫn return để không rơi xuống bước metafield.
          if (metaobject.accessMode === 'entry') {
            self.restoreMetaobjectSource(path);
          }
          return;
        }

        // 4. Metafield: {owner}.metafields.{ns}.{key}.value hoặc {…}.{key} | metafield_tag
        const matched = path.match(/\.metafields\.([^.\s|]+)\.([^.\s|]+)/);
        if (matched) {
          const namespace = matched[1];
          const key = matched[2];
          const list = self.compatibleMetafields || [];
          const index = list.findIndex(
            (item: any) => item?.node?.namespace === namespace && item?.node?.key === key
          );
          if (index > -1) {
            this.currentView = 'template_fields';
            this.valueDynamic = list[index];
            this.typeDynamic = 'meta';
            this.show_choice = true;
            self.activeRowKey = `tpl-meta-${index}`;
            // Đúng dạng title lúc tạo tag (xem handleSelect): "namespace.key"
            self.resolvedTitle = `${namespace}.${key}`;
            // Khôi phục đúng lựa chọn text/richtext lúc tag được tạo.
            this.$nextTick(() => {
              const select = this.$refs['type'] as HTMLSelectElement | undefined;
              if (select) select.value = /metafield_tag/.test(path) ? 'richtext' : 'text';
            });
            return;
          }
        }
        // 5. Path lạ → giữ nguyên root, chỉ hiện banner.
      },
      /** Tách liquid path metaobject thành các thành phần. Thuần xử lý chuỗi, không
       *  đụng state, không gọi API. Trả null nếu không phải path metaobject. */
      parseMetaobjectPath(path: string) {
        const unescape = (value: string) => value.replace(/\\'/g, "'");
        // "f1.value" hoặc "f1.value.f2.value…" → ['f1', 'f2', …]
        const toFieldKeys = (rest: string): string[] | null => {
          const parts = rest.split('.');
          if (!parts.length || parts.length % 2 !== 0) return null;
          const keys: string[] = [];
          for (let i = 0; i < parts.length; i += 2) {
            if (!parts[i] || parts[i + 1] !== 'value') return null;
            keys.push(parts[i]);
          }
          return keys;
        };

        // entry mode: metaobjects.TYPE['handle'].f.value | metaobjects['TYPE']['handle'].f.value
        const entry = path.match(
          /^metaobjects(?:\.([a-zA-Z0-9_]+)|\['((?:[^'\\]|\\.)*)'\])\['((?:[^'\\]|\\.)*)'\]\.(.+)$/
        );
        if (entry) {
          const fieldKeys = toFieldKeys(entry[4]);
          if (!fieldKeys) return null;
          return {
            accessMode: 'entry',
            defType: unescape(entry[1] ?? entry[2] ?? ''),
            handle: unescape(entry[3] ?? ''),
            fieldKeys,
          };
        }

        // via_metafield: {owner}.metafields.{ns}.{key}.value.f.value
        const viaMetafield = path.match(
          /^[a-zA-Z_][a-zA-Z0-9_]*\.metafields\.([^.\s|]+)\.([^.\s|]+)\.value\.(.+)$/
        );
        if (viaMetafield && toFieldKeys(viaMetafield[3])) {
          return { accessMode: 'via_metafield', defType: '', handle: '', fieldKeys: [] };
        }
        return null;
      },
      /** Dựng lại state điều hướng metaobject từ liquid path rồi mở tới đúng field lá.
       *  An toàn nhờ round-trip: chỉ áp dụng khi buildMetaobjectPath() dựng lại ĐÚNG
       *  path gốc. Lệch một ký tự là trả state về như cũ và chỉ còn banner — nên
       *  không có đường nào để một path sai lọt vào page của khách. */
      async restoreMetaobjectSource(path: string) {
        const self = this as any;
        if (self.restoringSource) return;
        const parsed = self.parseMetaobjectPath(path);
        if (!parsed || parsed.accessMode !== 'entry') return;

        self.restoringSource = true;
        try {
          await self.ensureMetaobjectScopes();
          await this.$store.dispatch('dynamicSources/loadMetaobjects');
        } catch {
          return;
        } finally {
          self.restoringSource = false;
        }

        // Trong lúc chờ API user có thể đã đóng panel / đổi tag / tự điều hướng.
        if (!this.show || self.currentSource?.path !== path || this.currentView !== 'root') return;

        const byType = self.definitionsByType || {};
        let def = byType[parsed.defType];
        if (!def) return; // definition đã bị xoá hoặc không có quyền đọc
        const stack: any[] = [
          { defType: parsed.defType, defName: def.name || parsed.defType, fieldKey: '', fieldName: '' },
        ];

        // Đi xuyên các field reference trung gian (mọi key trừ key cuối)
        for (let i = 0; i < parsed.fieldKeys.length - 1; i += 1) {
          const field = (def.fieldDefinitions || []).find((f: any) => f.key === parsed.fieldKeys[i]);
          const nextType = field?.referencedType;
          // referencedType rỗng = metaobject app-owned của app khác → không đọc được
          if (!nextType || !byType[nextType]) return;
          def = byType[nextType];
          stack.push({
            defType: nextType,
            defName: def.name || nextType,
            fieldKey: field.key,
            fieldName: field.name,
          });
        }

        const leafKey = parsed.fieldKeys[parsed.fieldKeys.length - 1];
        const leafField = (def.fieldDefinitions || []).find((f: any) => f.key === leafKey);
        if (!leafField) return; // field lá đã bị đổi tên/xoá

        // Gán tạm để buildMetaobjectPath() chạy được, giữ bản cũ để hoàn tác nếu lệch.
        const previous = {
          stack: self.metaobjectNavStack,
          entry: self.selectedEntry,
          mode: self.metaobjectAccessMode,
        };
        self.metaobjectNavStack = stack;
        self.selectedEntry = { handle: parsed.handle, title: parsed.handle };
        self.metaobjectAccessMode = 'entry';

        if (self.buildMetaobjectPath(leafKey) !== path) {
          self.metaobjectNavStack = previous.stack;
          self.selectedEntry = previous.entry;
          self.metaobjectAccessMode = previous.mode;
          return;
        }

        this.valueDynamic = { _type: 'metaobject', field: leafField };
        this.typeDynamic = 'metaobject';
        this.currentView = 'metaobject_fields';
        const visibleIndex = (self.currentNavFields || []).findIndex((f: any) => f.key === leafKey);
        if (visibleIndex > -1) self.activeRowKey = `mobj-${visibleIndex}`;
        // Dựng lại đúng công thức title lúc tạo tag (xem handleSelect)
        const crumb = self.metaobjectBreadcrumb;
        self.resolvedTitle = crumb ? `${crumb} › ${leafField.name}` : leafField.name;

        self.hydrateEntryTitle(parsed.defType, parsed.handle, path);
      },
      /** Đổi breadcrumb từ handle sang tên hiển thị của entry. Chỉ ảnh hưởng chữ hiển
       *  thị (buildMetaobjectPath chỉ dùng handle) nên lỗi thì im lặng giữ handle. */
      async hydrateEntryTitle(defType: string, handle: string, path: string) {
        const self = this as any;
        try {
          const entries = await this.$store.dispatch('dynamicSources/loadMetaobjectEntries', defType);
          // Đặt sẵn danh sách cho view entries: bấm Back từ view fields là có ngay,
          // không phải chờ fetch lại và không rơi vào empty state.
          if (self.show && self.metaobjectNavStack[0]?.defType === defType) {
            self.currentEntries = entries || [];
          }
          const found = (entries || []).find((item: any) => item.handle === handle);
          if (
            found?.title &&
            self.show &&
            self.currentSource?.path === path &&
            self.selectedEntry?.handle === handle
          ) {
            self.selectedEntry = { ...self.selectedEntry, title: found.title };
            // Breadcrumb vừa đổi theo tên entry → cập nhật lại tên hiển thị ở banner.
            const fieldName = self.valueDynamic?.field?.name;
            if (fieldName) {
              const crumb = self.metaobjectBreadcrumb;
              self.resolvedTitle = crumb ? `${crumb} › ${fieldName}` : fieldName;
            }
          }
        } catch {
          /* giữ nguyên handle */
        }
      },
      // ─── DS-03 redesign: METAOBJECTS FLOW ──────────────────────────────────────

      /** Nạp entries của 1 definition vào view entries (store đã cache theo defType).
       *  Dùng chung cho 3 đường vào: chọn definition, back từ view fields, và lúc dựng
       *  lại state từ liquid path — thiếu bước này thì back ra hiện "No entries found". */
      async fetchEntries(defType?: string | null) {
        const self = this as any;
        if (!defType) return;
        self.entriesLoading = true;
        self.entriesError = '';
        try {
          self.currentEntries = await this.$store.dispatch(
            'dynamicSources/loadMetaobjectEntries',
            defType,
          );
        } catch (error: any) {
          self.currentEntries = [];
          self.entriesError = error?.message || 'Failed to load metaobject entries';
        } finally {
          self.entriesLoading = false;
        }
      },

      /** Step 1: user picks a definition → go to entry picker */
      async selectMetaobjectDefinition(def: any) {
        (this as any).metaobjectNavStack = [{ defType: def.type, defName: def.name, fieldKey: '', fieldName: '' }];
        (this as any).selectedEntry = null;
        (this as any).metaobjectAccessMode = 'entry';
        (this as any).metaobjectRefNamespace = '';
        (this as any).metaobjectRefKey = '';
        (this as any).showMetafieldForm = false;
        this.valueDynamic = null;
        this.typeDynamic = '';
        this.currentView = 'metaobject_entries';
        await (this as any).fetchEntries(def.type);
      },

      /** Step 2a: user picks a specific entry → go to field picker */
      selectEntry(entry: { handle: string; title: string }) {
        (this as any).selectedEntry = entry;
        (this as any).metaobjectAccessMode = 'entry';
        this.currentView = 'metaobject_fields';
        this.valueDynamic = null;
        this.typeDynamic = '';
      },

      /** Step 2b: user chooses to connect via metafield reference → go to field picker */
      selectViaMetafield() {
        const ns = ((this as any).metaobjectRefNamespace || '').trim();
        const k  = ((this as any).metaobjectRefKey || '').trim();
        if (!ns || !k) return;
        (this as any).selectedEntry = null;
        (this as any).metaobjectAccessMode = 'via_metafield';
        this.currentView = 'metaobject_fields';
        this.valueDynamic = null;
        this.typeDynamic = '';
      },

      /** Back from entries → list */
      handleEntriesBack() {
        this.currentView = 'metaobjects_list';
        (this as any).metaobjectNavStack = [];
        (this as any).selectedEntry = null;
        (this as any).metaobjectAccessMode = 'entry';
        (this as any).showMetafieldForm = false;
        (this as any).metaobjectRefNamespace = '';
        (this as any).metaobjectRefKey = '';
      },

      /** Back from fields:
       *  depth > 1 → pop one level (stay in metaobject_fields)
       *  depth = 1 → back to metaobject_entries
       */
      handleMetaobjectBack() {
        const stack = (this as any).metaobjectNavStack as any[];
        if (stack.length > 1) {
          stack.pop();
        } else {
          this.currentView = 'metaobject_entries';
          (this as any).selectedEntry = null;
          (this as any).metaobjectAccessMode = 'entry';
          // Vào view fields bằng đường "mở lại nguồn đang dùng" thì entries chưa từng
          // được nạp → back ra sẽ hiện empty state sai. Nạp lại (store có cache).
          if (!(this as any).currentEntries.length && !(this as any).entriesLoading) {
            (this as any).fetchEntries(stack[0]?.defType);
          }
        }
        this.valueDynamic = null;
        this.typeDynamic = '';
      },

      /** Drill into a reference field (auto-resolve type, fallback to manual picker / smart raw-value suggestion) */
      async drillIntoReferenceField(field: any) {
        if (!field.isReference) return;
        // Clear any selected leaf when drilling deeper
        this.valueDynamic = null;
        this.typeDynamic = '';

        let resolvedType: string | null = field.referencedType || null;
        let rawValue: string | null = null;

        if (!resolvedType) {
          const stack = (this as any).metaobjectNavStack as any[];
          const currentDefType = stack.length ? stack[stack.length - 1].defType : null;
          const handle =
            (this as any).metaobjectAccessMode === 'entry'
              ? (this as any).selectedEntry?.handle || null
              : null;
          if (currentDefType) {
            (this as any).resolvingRefField = true;
            try {
              const result: { fieldRefs: Record<string, string>; fieldValues: Record<string, string> } =
                await this.$store.dispatch('dynamicSources/loadMetaobjectEntryFieldData', {
                  defType: currentDefType,
                  handle,
                });
              resolvedType = result?.fieldRefs?.[field.key] || null;
              rawValue = result?.fieldValues?.[field.key] ?? null;
            } catch {
              resolvedType = null;
            } finally {
              (this as any).resolvingRefField = false;
            }
          }
        }

        if (resolvedType) {
          let refDef = (this as any).definitionsByType?.[resolvedType];
          if (!refDef) refDef = { type: resolvedType, name: resolvedType, fieldDefinitions: [] };
          (this as any).metaobjectNavStack.push({
            defType: resolvedType,
            defName: refDef.name || resolvedType,
            fieldKey: field.key,
            fieldName: field.name,
          });
          this.valueDynamic = null;
          this.typeDynamic = '';
          return;
        }

        (this as any).pendingRefField = field;

        // DS-05-1: referencedType == null nhưng vẫn có value → metaobject app-owned của app khác.
        // Chỉ hiện cảnh báo — EComposer không thể đọc/insert dynamic source cho field này.
        if (rawValue !== null && rawValue !== undefined && rawValue !== '') {
          (this as any).pendingRefRawValue = rawValue;
          this.currentView = 'metaobject_unresolved_ref';
        } else {
          (this as any).pendingRefRawValue = null;
          this.currentView = 'select_ref_definition';
        }
        this.valueDynamic = null;
        this.typeDynamic = '';
      },

      /** Fallback: user manually selects a definition in select_ref_definition view */
      confirmRefDefinition(def: any) {
        const field = (this as any).pendingRefField;
        if (!field) return;
        (this as any).metaobjectNavStack.push({
          defType: def.type,
          defName: def.name,
          fieldKey: field.key,
          fieldName: field.name,
        });
        (this as any).pendingRefField = null;
        (this as any).pendingRefRawValue = null;
        this.currentView = 'metaobject_fields';
        this.valueDynamic = null;
        this.typeDynamic = '';
      },

      /** Build Liquid path for a leaf field using the nav stack + access mode.
       *  entry mode:      metaobjects.TYPE['handle'].field.value
       *  via_metafield:   owner.metafields.ns.key.value.field.value
       *  nested (N>1):    <base>.refField.value. … .leafField.value
       */
      buildMetaobjectPath(leafFieldKey: string): string {
        const stack = (this as any).metaobjectNavStack as any[];
        if (!stack.length) return '';
        // Intermediate segments: stack[1..] each contributes refField.value
        const intermediateParts = stack.slice(1).map((s: any) => `${s.fieldKey}.value`);
        const fullPath = [...intermediateParts, `${leafFieldKey}.value`].join('.');
        if ((this as any).metaobjectAccessMode === 'entry') {
          const handle  = (this as any).selectedEntry?.handle || '';
          const defType = stack[0].defType;
          const typeAccess = /^[a-zA-Z0-9_]+$/.test(defType) ? `.${defType}` : `['${defType}']`;
          return `metaobjects${typeAccess}${(this as any).liquidBracketKey(handle)}.${fullPath}`;
        }
        // via_metafield
        const ns    = (this as any).metaobjectRefNamespace || '{namespace}';
        const k     = (this as any).metaobjectRefKey || '{key}';
        const owner = this.normalizedShopifyType || 'product';
        return `${owner}.metafields.${ns}.${k}.value.${fullPath}`;
      },

      /** Select a leaf metaobject field — marks it as chosen, waits for Select button. */
      selectMetaobjectField(event: Event, field: any, rowKey = '') {
        (this as any).activeRowKey = rowKey;
        this.valueDynamic = { _type: 'metaobject', field };
        this.typeDynamic = 'metaobject';
      },

      // ─── END DS-03 redesign ─────────────────────────────────────────────────

      handleSelect() {
        // DS-03 redesign: metaobject field insert (new handle-based path, no for-loop)
        if (this.typeDynamic === 'metaobject') {
          const { field } = this.valueDynamic;
          const liquidPath = (this as any).buildMetaobjectPath(field.key);
          if (!liquidPath) return;
          const stack   = (this as any).metaobjectNavStack as any[];
          const allKeys = [...stack.slice(1).map((s: any) => s.fieldKey), field.key];
          const metaKey = this.toLiquidVarKey(`${stack[0].defType}_${allKeys.join('_')}`);
          const crumb   = (this as any).metaobjectBreadcrumb;
          const title   = crumb ? `${crumb} › ${field.name}` : field.name;
          const span = (this as any).createDynamicMetaSpan(metaKey, liquidPath, title);
          this.$emit('update:metafield', span);
          this.show = false;
          return;
        }
        if (this.typeDynamic === 'source') {
          const source = this.valueDynamic as { title: string; key: string };
          const metaKey = this.resolveDynamicMetaKey(source.title, source.key);
          const span = (this as any).createDynamicMetaSpan(metaKey, source.key, source.title);
          this.$emit('update:metafield', span);
          this.show = false;
        } else if (this.typeDynamic === 'meta') {
          const meta = this.valueDynamic as { node: { key: string; name: string; namespace: string } };
          const type = this.$refs['type'] && (this.$refs['type'] as HTMLSelectElement).value;
          const liquidOwner = this.normalizedShopifyType || 'page';
          const metaKey = this.toLiquidVarKey(`${meta?.node?.namespace}_${meta?.node.key}`);
          const displayTitle = `${meta?.node?.namespace}.${meta?.node?.key}`;
          let liquidPath = `${liquidOwner}.metafields.${meta?.node?.namespace}.${meta?.node.key}.value`;
          if (type === 'richtext') {
            liquidPath = `${liquidOwner}.metafields.${meta?.node?.namespace}.${meta?.node.key} | metafield_tag`;
          }
          const span = (this as any).createDynamicMetaSpan(metaKey, liquidPath, displayTitle);
          this.$emit('update:metafield', span);
          this.show = false;
        }
      }
    }
  };
</script>

