<template>
    <div class="ecom-element ecom-shopify-elements ecom__form">
        <div class="ecom__form-wrapper">
            <div class="ecom__form-container">
                <Liquid data="{% comment %}"/>
                <form :id="'ecom-password-form-' + data.id" class="ecom-password-form" method="post" action="/password" accept-charset="UTF-8">
                    <input type="hidden" name="form_type" value="storefront_password">
                    <input type="hidden" name="utf8" value="✓">
                <Liquid data="{% endcomment %}"/>
                <Liquid :data="liquids.form_start.code"/>
                    <div class="ecom-password-form--content ecom-flex">
                        <div class="ecom-el__password-input">
                            <div class="ecom-el__password-input--inner" v-html="liquid('input')">
                            </div>
                            <div v-if="!exporting && data.settings?.show_preview" class="ecom-el__password-error">
                                <span class="ecom-el__password-message ecom-db" v-html="data.settings?.error_message">
                                </span>
                            </div>
                            <div v-if="exporting" class="ecom-el__password-error" v-html="liquid('error')">

                            </div>
                        </div>

                        <div class="ecom-el__password-submit ecom-flex">
                            <button type="submit" class="ecom-flex ecom-fl_center ecom-al_center"><span v-html="lang(data.settings.button_label, 'button_label')"></span><span  v-if="data.settings?.icon" class="ecom-password--icon" v-html="data.settings?.icon"></span></button>
                        </div>
                    </div>
                <Liquid :data="liquids.form_end.code"/>
                <Liquid data="{% comment %}"/>
                </form> 
                <Liquid data="{% endcomment %}"/>
            </div>
        </div>
    </div>
</template>

<script>
    import { Liquid, Element, Javascript } from '@/mixins';
    export default {
        name: 'PasswordForm',
        presets: true,
        mixins: [Liquid, Element, Javascript],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            liquids () {
                return {
                    input: {
                        code: `
                            <label for="password">${this.lang(this.data.settings?.input_label, 'input_label')}</label>
                            <input type="password" name="password" placeholder="${this.lang(this.data.settings.input_placeholder, 'input_placeholder')}" {% if form.errors %}class="ecom-product__error"{% endif %}>
                        `
                    },
                    form_start: {
                        code: `
                            {% form 'storefront_password', class: 'ecom-password-form', id: 'ecom-password-form-${this.data.id}' %}
                        `
                    },
                    form_end: {
                        code: `
                            {% endform %}
                        `
                    },
                    error: {
                        code: `
                                {% if form.errors %}
                                    <span class="ecom-el__password-message ecom-db">
                                        ${this.lang(this.data.settings?.error_message, 'error_message')}
                                    </span>
                                {% endif %}
                        `
                    },
                };
            },

            settings () {
                return [
                    {
                        group_title: this.$t('general'),
                        params: [
                            {
                                type: 'textarea',
                                name: 'input_label',
                                label: this.$t('input_label'),
                                options: {
                                    toolbar: 'full',
                                    height: 50
                                }
                            },
                            {
                                name: 'input_placeholder',
                                label: this.$t('input_placeholder'),
                                type: 'text'
                            },
                            {
                                type: 'text',
                                name: 'button_label',
                                label: this.$t('button_label'),
                            },
                            {
                                type: 'picker',
                                name: 'icon',
                                label: this.$t('button_icon'),
                                options: {
                                    type: 'icon',
                                    layout: 'grid',
                                    output: 'value',
                                    multiple: false,
                                    simple: false
                                }
                            },
                            {
                                type: 'number',
                                name: 'gap_btn',
                                label: this.$t('icon_gap'),
                                options: {
                                    responsive: true,
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 50
                                        }
                                    },
                                    visible: function(data) {
                                        return data && data['icon']
                                    }
                                },
                                css: {
                                    selector: ' .ecom-el__password-submit button',
                                    properties: {
                                        gap: ''
                                    }
                                }
                            },
                            {
                                type: 'choose',
                                label: this.$t('icon_position'),
                                name: 'icon_position',
                                options: {
                                    type: 'align-x',
                                    values: [-1, 1],
                                    visible: {
                                        keep_data: false,
                                        condition: (data) => {
                                            return data['icon'];
                                        }
                                    }
                                },
                                css:{
                                    selector:' .ecom-password--icon',
                                    properties:{
                                        order:''
                                    }
                                }
                            },
                            {
                                type: 'line'
                            },
                            {
                                type: 'popup',
                                name: 'layout',
                                label: this.$t('layout'),
                                options: {
                                    type: 'dropdown',
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        column: this.$t('vertical'),
                                        row: this.$t('horizontal')
                                    }
                                },
                                css: {
                                    selector: ' .ecom-password-form--content',
                                    properties: {
                                        'flex-direction': ''
                                    }
                                }
                            },
                            {
                                type: 'number',
                                name: 'gap',
                                label: this.$t('gap'),
                                options: {
                                    responsive: true,
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 50
                                        }
                                    }
                                },
                                css: {
                                    selector: ' .ecom-password-form--content',
                                    properties: {
                                        gap: ''
                                    }
                                }
                            },
                            {
                                type: 'line'
                            },
                            {
                                type: 'toggle',
                                name: 'show_preview',
                                label: this.$t('show_preview_messages'),
                                options:{
                                     values: {
                                        on: {
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    }
                                }
                            },
                            {
                                type: 'textarea',
                                name: 'error_message',
                                value: 'Password incorrect, please try again.',
                                label: this.$t('error_message'),
                                options: {
                                    toolbar: 'full',
                                    height: 80
                                }
                            },
                        ]
                    },
                ]
            },
            style() {
                let modifyButton = {};
                if(this.data.settings.layout === 'column') {
                    modifyButton = {
                                    position: 0,
                                    fields: [
                                        {
                                            alias: 'justify-content',
                                            options: {
                                                label: this.$t('alignment'),
                                                css: {
                                                    selector: 'root .ecom-el__password-submit',
                                                    properties: {
                                                        'align-items': '',
                                                        'justify-content': ''
                                                    }
                                                }
                                            }
                                        }
                                    ]
                                }
                }
                return [
                    {
                        group_alias: 'box',
                        options: {
                            selector: ' .ecom-password-form'
                        },
                        modify: {
                            params: [
                                {
                                    position: 0,
                                    fields: [
                                        {
                                            alias: 'justify-content',
                                            options: {
                                                label: this.$t('alignment'),
                                                css: {
                                                    selector: 'root .ecom__form-container',
                                                    properties: {
                                                        'align-items': '',
                                                        'justify-content': ''
                                                    }
                                                }
                                            }
                                        }
                                    ]
                                },
                                {
                                    position: 20,
                                    fields: [
                                        {
                                            alias: 'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias: 'text',
                        options: {
                            group_title: this.$t('label_input'),
                            group_name: 'input_label',
                            selector: ' .ecom-el__password-input label'
                        },
                        modify: {
                            remove: {
                                index: 0,
                                length: 1
                            },
                            params: [
                            {
                                position: 20,
                                fields: [
                                    {
                                        alias: 'spacing'
                                    }
                                ]
                            }
                        ]
                        },
                    },
                    {
                        group_alias: 'input',
                        options: {
                            selector: ' .ecom-el__password-input input'
                        },
                        modify: {
                            remove: {
                                index: 1,
                                length: 1
                            }
                        }
                    },
                    {
                        group_alias: 'button',
                        options: {
                            selector: ' .ecom-el__password-submit button'
                        },
                        modify: {
                            params: [
                                modifyButton
                            ]
                        }
                    },
                    {
                        group_alias: 'icon',
                        options: {
                            group_title: this.$t('icon'),
                            group_name: 'icon',
                            selector: ' .ecom-password--icon',
                        },
                        modify:{
                            params:[
                                {
                                    position:15,
                                    fields:[
                                        {
                                            type:'line'
                                        },
                                        {
                                            alias:'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias: 'text',
                        options: {
                            group_title: this.$t('error_message'),
                            group_name: 'error_message',
                            selector: ' .ecom-el__password-message'
                        },
                        modify: {
                            remove: {
                                index: 0,
                                length: 1
                            },
                            params: [
                                {
                                    position: 20,
                                    fields: [
                                        {
                                            alias: 'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                ]
            },
            javascript() {
                return function (){
                }
            },
            css () {
                return `
                    /* Disable enter password theme */
                    password-modal {
                        display: none !important;
                    }
                    .ecom__form-container {
                        display: flex;
                    }
                    .ecom-password-form--content {
                        display: flex;
                        width: fit-content;
                        flex-wrap: wrap;
                    }
                    .ecom-password-form--content input.ecom-product__error {
                        background-color: #fbeae5;
                        border: 1px solid #bf0711;
                    }
                    .ecom-password--icon { 
                        display: flex;;
                        width: 15px;
                        height: 15px
                    }
                    .ecom-password--ico svg {
                        width: 100%;
                        height: 100%;
                    }
            `;
            },

            default () {
                return {
                    "settings": {
                        "error_message": "Password incorrect, please try again.",
                        "input_label": "Password <font color=\"#ff0000\">*</font>:",
                        "gap": "15px",
                        "input_placeholder": "Enter your password",
                        "button_label": "Enter",
                        "layout": "column",
                        "show_preview": true
                    },
                    "style": {
                        "button": {
                            "tab": "normal",
                            "buttonWidthnormalmode": "180px",
                            "buttonBackgroundnormalmode": {
                                "classic": {
                                    "background-color": "#000000"
                                }
                            },
                            "buttonBackgroundhovermode": {
                                "classic": {}
                            },
                            "buttonBordernormalmode": {
                                "border-style": "none"
                            },
                            "buttonBorderRadiusnormalmode": {
                                "right": "10px",
                                "top": "10px",
                                "left": "10px",
                                "bottom": "10px"
                            },
                            "buttonColornormalmode": "#ffffff",
                            "buttonHeightnormalmode": "40px",
                            "justify-content": "flex-start"
                        },
                        "icon": {
                            "iconFontSize": "15px"
                        },
                        "input": {
                            "tab": "normal",
                            "width": "350px",
                            "spacing": {
                                "margin": {
                                    "left": "10px"
                                },
                                "padding": {
                                    "top": "8px",
                                    "bottom": "8px",
                                }
                            },
                            "borderRadius": {
                                "right": "10px",
                                "top": "10px",
                                "left": "10px",
                                "bottom": "10px"
                            },
                            "border": {
                                "border-style": "solid",
                                "border-width": {
                                    "top": "1px",
                                    "left": "1px",
                                    "bottom": "1px",
                                    "right": "1px"
                                }
                            }
                        },
                        "error_message": {
                            "textColor": "#f01111",
                            "spacing": {
                                "margin": {
                                    "top": "10px"
                                }
                            }
                        },
                        "input_label": {
                            "textColor": "#000000"
                        }
                    }
                }
            }
        },
        methods: {
        }
    };
</script>