<i18n>
{
    "en": {
        "search": "Search",
        "categories": "Categories",
        "all_icons": "All icons"
    },
    "fr": {
        "search": "Rechercher",
        "categories": "Catégories",
        "all_icons": "Tous les icônes"
    },
    "de": {
        "search": "Suchen",
        "categories": "Kategorien",
        "all_icons": "Alle Symbole"
    },
    "ja": {
        "search": "検索",
        "categories": "カテゴリー",
        "all_icons": "すべてのアイコン"
    }
}
</i18n>
<template>
    <div
        class="relative text-sm"
        :class="id"
    >
        <EcomIcon  v-if="!searchData?.length" :source="icons.SearchMajor" :size="'w-5'" class="absolute w-4 p-px text-icon-secondary transition transform -translate-y-1/2 left-2 top-1/2 z-1"></EcomIcon>
        <EcomIcon v-else @click="searchData = ''" :source="icons.CancelMajor" :size="'w-5'" class="absolute w-4 text-icon transition transform -translate-y-1/2 rounded-full cursor-pointer hover:text-gray-600 left-2 top-1/2  "></EcomIcon>
        <button
            v-if="brands.length"
            class="absolute transition cursor-pointer right-3 top-0 h-8"
            :class="isopen ? 'text-primary' : 'text-gray-500   hover:text-gray-600'"
            @click="open"
        >
            <EcomIcon :source="icons.AdjustMinor" :size="'w-5'"></EcomIcon>
        </button>

        <input
            v-model="searchData"
            type="text"
            class="block h-8 w-full pl-8 pr-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input hover:border-input-hover placeholder-form-input text-xs font-normal focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40"
            :placeholder="$t('search')"
            @keydown.enter="submitSearch"
            :disabled="disabled"
        >
        <div
            v-if="isopen"
            class="absolute z-10 w-[calc(100%+1px)] px-3 pt-1 py-2 bg-white   rounded-lg shadow-lg"
            :class="largeScreen ? 'left-0 right-full top-full mt-2' : 'right-0 left-full top-0 ml-2' "
        >
            <div class="max-h-full-17 overflow-y-auto overflow-x-hidden">
                <div class="flex justify-between items-center py-[10px] text-gray-600 border-b border-gray-200 ">
                    <h3 class="text-sm font-semibold ">{{ $t('categories') }}</h3>
                    <EcomIcon @click="isopen=false" :source="icons.CancelMajor" :size="'w-5'" class="w-5 h-5 p-px text-gray-500  transition rounded-full cursor-pointer hover:text-gray-600 "></EcomIcon>
                </div>
                <ul class="inline-block w-full">
                    <li
                        class="relative p-1 py-2 text-sm capitalize cursor-pointer transition-search"
                        @click="toggleOpen('')"
                    >
                        <label
                            class="cursor-pointer"
                            :class="
                                selected.cate ? 'text-gray-600 hover:text-primary  ' : 'text-primary'
                            "
                        >
                            {{ $t('all_icons') }} ({{ cateCount }})
                        </label>
                    </li>
                    <li
                        v-for="(brand) in brands"
                        :key="brand"
                        class="relative py-1.5 text-sm capitalize transition-search border-t border-gray-200 "
                    >
                        <label
                            class="flex items-center p-1 text-gray-600 cursor-pointer hover:text-gray-800  "
                            @click="toggleOpen(brand)"
                        >
                            {{ brand.replace(/-/, ' ') }} ({{ catesComp[brand]['All'] }})
                            <EcomIcon :source="openComp === brand ? icons.MinusMajor : icons.MobilePlusMajor" :size="'w-5'" class="ml-auto text-gray-500  -mr-[5px]"></EcomIcon>
                            <!-- <EcomIcon :source="icons.ChevronDownMinor" :size="'w-5'" :class="{'transform rotate-180': openComp === brand}"></EcomIcon> -->
                        </label>
                        <ul
                            v-if="keys(catesComp[brand]).length && openComp === brand"
                            class="py-0.5 mt-1 -mb-1.5 pl-3 overflow-y-auto"
                        >
                            <li
                                v-for="(countCate, cate, iCate) in catesComp[brand]"
                                :key="cate"
                                class="relative p-1 cursor-pointer transition-search"
                                @click="setSelectedCatgory(brand + '|||' +cate)"
                            >
                                <label
                                    class="capitalize cursor-pointer text-xs"
                                    :class="(brand + '|||' +cate === selected.cate) ? 'text-primary' : 'text-gray-600   hover:text-gray-600'"
                                >
                                    {{ cate.replace(/-/, ' ') }} ({{ countCate }})
                                </label>
                            </li>
                        </ul>
                    </li>
                </ul>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
    import {CancelMajor, SearchMajor, AdjustMinor, ChevronDownMinor, MobilePlusMajor, MinusMajor} from '@/assets/icons';
    import { Popmenu } from '@/mixins';
    export default {

        props: {
            search: {
                type: String,
                default: ''
            },
            cates: {
                type: Object,
                default(){
                    return {};
                }
            },
            disabled: {
                type: Boolean,
                default: false
            }
        },
        mixins: [ Popmenu ],
        emits: ['update:search'],
        data() {
            return {
                searchData: this.search,
                selected: {
                    cate: null
                },
                openTab: '',
                itv: null,
                icons: {
                    CancelMajor, SearchMajor, AdjustMinor, ChevronDownMinor, MobilePlusMajor, MinusMajor
                }
            };
        },
        computed: {
            catesComp(){
                let cates = this.$helpers.copy(this.cates);
                for(let k in cates) {
                    let cate = cates[k];
                    let keys = this.keys(cate);
                    if(!keys['All']){
                        let count = this.sum(Object.values(cate));
                        cates[k] = Object.assign({All: count}, cate);
                    }
                }
                return cates;
            },
            brands(){
                return Object.keys(this.catesComp);
            },
            openComp: {
                get(){
                    return this.openTab ?? this.brands[0];
                },
                set(val){
                    this.openTab = val;
                }
            },
            cateCount(){
                return this.sum(this.brands.map(x => this.catesComp[x].All));
            },
            value(){
                return this.selected.cate ? (this.searchData + '|||' + this.selected.cate) : this.searchData;
            },
            largeScreen() {
                return this.$store.getters['builder/largeScreen'];
            }
        },
        watch: {
            search: function (val) {
                this.initData(val);
            },
            'selected.cate': function() {
                if(this.isEmit) {
                    this.$emit('update:search', this.value);
                }
                this.isEmit = true;
            },
            value: function (value) {

                clearTimeout(this.itv);

                this.itv = setTimeout(() => {
                    this.$emit('update:search', value);
                }, 500)
            },
            brands: {
                deep: true,
                handler: function(val){
                    if(!val.length) {
                        this.selected.cate = '';
                    }
                }
            }
        },
        created () {
            this.initData(this.search, true);
        },
        beforeUnmount () {
            clearTimeout(this.itv);
        },
        methods: {
            // Enter means "search now": drop the pending debounce and emit
            // straight away, instead of letting the keystroke restart the timer.
            submitSearch (event) {
                this.searchData = event.target.value.trim();
                this.$nextTick(() => {
                    clearTimeout(this.itv);
                    this.$emit('update:search', this.value);
                });
            },
            setSelectedCatgory(val){
                this.selected.cate = val;
                this.isopen = false;
            },
            keys(obj){
                if(typeof obj !== 'object'){
                    return [];
                }
                return Object.keys(obj);
            },
            sum(numbers){
                return numbers.reduce((a, b) => a + b, 0);
            },
            toggleOpen(brand){
                if(this.openTab === brand){
                    this.openTab = '';
                }
                else{
                    this.openTab = brand;
                    this.selected.cate = brand + '|||All';
                }
            },
            initData(val ,created){
                let qs = val.split('|||');
                if(qs.length >= 3){
                    this.searchData = qs.slice(0, -2).join('|||');
                    if(created) {
                        this.isEmit = false;
                    }
                    this.selected.cate = qs.slice(1).join('|||');
                    this.openTab = qs[1];
                }
                else{
                    this.searchData = val;
                }
            }
        }
    };
</script>
<style>
.component-fade-enter-active, .component-fade-leave-active {
    transition: all 0.5s cubic-bezier(0.47, -0.66, 0.18, 1.46);
}
.component-fade-enter, .component-fade-leave-to{
    transform: translateY(-20%);
    opacity: 0;
}
.transition-search {
    transition: all 0.5s cubic-bezier(0.47, -0.66, 0.18, 1.46)
}
.max-h-40{
    max-height: 10rem;
}
.max-h-full-17{
    max-height: calc(100vh - 17.3rem);
}
</style>
    