// store/modules/library/getters.ts
import type { LibraryState, MetaData } from './types';
import { LibraryCacheService } from './cache';
import { USER_TABS } from './constants';

/** Convert context.query → metaData format cũ, dùng cho getter `insert` (backward compat). */
function queryToMetaData(state: LibraryState): MetaData {
    const q = state.context.query;
    return {
        paged    : q.page,
        limit    : q.pageSize,
        search   : q.search,
        category : (q.categoryId ?? '') as string,
        filter   : q.filter,
        priceTier: q.priceTier ?? null,
        tags     : q.tags,
        sort     : q.sort || 'created_at',
    };
}

export default {
    // ── Top-level state slices ───────────────────────────────────────────────
    context : (state: LibraryState) => state.context,
    cache   : (state: LibraryState) => state.cache,
    status  : (state: LibraryState) => state.status,

    // ── Context ──────────────────────────────────────────────────────────────
    tab      : (state: LibraryState) => state.context.tab,
    sourceId : (state: LibraryState) => state.context.sourceId,
    query    : (state: LibraryState) => state.context.query,
    isOpen   : (state: LibraryState) => state.context.isOpen,
    mode     : (state: LibraryState) => state.context.mode,

    // ── Cache – meta ─────────────────────────────────────────────────────────
    categories  : (state: LibraryState) => state.cache.meta.categories,
    sources     : (state: LibraryState) => state.cache.meta.sources,
    favorites   : (state: LibraryState) => state.cache.meta.favorites,
    tags        : (state: LibraryState) => state.cache.meta.tags,
    partners    : (state: LibraryState) => state.cache.meta.partners,
    optionsPromo: (state: LibraryState) => state.cache.meta.optionsPromo,
    currentNiche: (state: LibraryState) => state.cache.meta.currentNiche ?? {},

    // ── Cache – lists ─────────────────────────────────────────────────────────
    lists      : (state: LibraryState) => state.cache.lists,

    /** activeKeys map (tab → cache key). */
    activeKeys : (state: LibraryState) => state.activeKeys,

    // ── Status ───────────────────────────────────────────────────────────────
    loading    : (state: LibraryState) => state.status.loading || state.status.initializing,
    initializing: (state: LibraryState) => state.status.initializing,
    error      : (state: LibraryState) => state.status.error,
    firstLoad  : (state: LibraryState) => state.status.firstLoad,
    preview    : (state: LibraryState) => state.status.preview,
    showSaveForm: (state: LibraryState) => !!state.status.showSaveForm,
    detailTask  : (state: LibraryState) => !!state.status.detailTask,
    detailPost  : (state: LibraryState) => state.status.detailPost,
    loadingSave : (state: LibraryState) => !!state.status.loadingSave,

    // ── Computed helpers ─────────────────────────────────────────────────────
    /** Source đang active (theo context.sourceId). */
    activeSource: (state: LibraryState) =>
        state.cache.meta.sources.find((s) => s.id === state.context.sourceId),

    /** Có đang search hay không. */
    hasSearch: (state: LibraryState) => !!state.context.query.search,

    /** Map categoryBySource cho component dùng `currentCat`. */
    currentCat: (state: LibraryState) => state.context.query.categoryBySource ?? {},

    // ── Backward-compat getters (tương thích component cũ) ──────────────────
    /** `open` tương thích cú pháp cũ: trả { index: 0 } khi đang mở. */
    open: (state: LibraryState) => (state.context.isOpen ? { index: 0 } : null),

    /** `current` = tab đang active. */
    current: (state: LibraryState) => state.context.tab,

    /** `insert` giữ shape cũ: { isOpen, type, current, metaData }. */
    insert: (state: LibraryState) => ({
        isOpen  : state.context.isOpen,
        type    : state.context.mode,
        current : state.context.tab,
        metaData: queryToMetaData(state),
    }),

    /**
     * `listOfData` — nguồn dữ liệu chính cho tất cả list component.
     *
     * Kiến trúc mới (không giữ data lớn trong Vuex):
     *  1. Base = cache.lists (backward-compat, chứa detail / my_templates / routes đặc biệt).
     *  2. Overlay = LibraryCacheService (memory + localStorage) theo activeKeys.
     *     → Data từ CacheService luôn ưu tiên hơn cache.lists cho cùng một tab.
     *
     * `state.cacheVersion` được dùng làm reactive dependency để getter
     * re-compute khi CacheService cập nhật (không reactive natively).
     */
    listOfData: (state: LibraryState): Record<string, any> => {
        // Tạo reactive dependency — getter sẽ re-compute mỗi khi cacheVersion tăng.
        void state.cacheVersion;

        // 1. Start from cache.lists (detail views, special routes, my_templates…)
        const result: Record<string, any> = { ...state.cache.lists };

        // 2. Overlay CacheService chỉ cho tab thư viện (sections, all_pages…).
        // USER_TABS (my_templates, …) luôn lấy từ cache.lists — API nhánh `routes` / mergeLists
        // không ghi CacheService; overlay sẽ che dữ liệu mới → listOfData không đổi sau response.
        const userTabs = USER_TABS as readonly string[];
        for (const [tab, key] of Object.entries(state.activeKeys)) {
            if (userTabs.includes(tab)) continue;
            const cached = LibraryCacheService.get(key);
            if (cached) result[tab] = cached.data;
        }

        return result;
    },

    /** `detailScreen` tương thích cũ: { id } nếu có detailKey, null nếu không. */
    detailScreen: (state: LibraryState) =>
        state.context.query.detailKey
            ? { id: state.context.query.detailKey }
            : null,

    /** `loadingMoreData` = đang load thêm data (infinite scroll). */
    loadingMoreData: (state: LibraryState) => state.status.loadingMore,
};
