            ]
        };
    },
    computed: {
        isChooseOne(){
            return this.field?.options?.chooseOne;
        },
        refresh(){
            return this.$store.getters.REFRESH;
        },
        values() {
            return this.fieldValues;
        },
        field() {
            return this.data;
        },
        /**
         * Optional props forwarded to the field component, only when the field definition
         * actually sets them. Must stay empty by default: binding `zIndex: undefined` would
         * still create the key in $attrs, and components rendering a fragment root
         * (e.g. textarea/Textarea.vue) would log "Extraneous non-props attributes".
         *
         * zIndex — lets whoever hosts the field lift a teleported popup above its container.
         * popup/Popup.vue and background/Background.vue hardcode 61 otherwise, which sits
         * below a Popover panel (505).
         */
        extraFieldProps() {
            const zIndex = this.field?.options?.zIndex;
            return zIndex === undefined ? {} : { zIndex };
        },
        /**
         * `field.tooltip` chấp nhận 2 dạng:
         *   - string  -> hành vi mặc định của Tooltip.vue: popup `bottom`, không interactive.
         *                Dạng có sẵn, đang dùng ở `constants/confirm.ts` — KHÔNG được đổi.
         *   - object  -> {content, location, interactive}, cho tooltip dài cần đặt vị trí
         *                và cho phép rê chuột vào (panel Animation, xem constants/animation-tooltips.ts).
         */
        tooltipContent() {
            const t = this.field?.tooltip;
            return typeof t === 'string' ? t : (t?.content ?? '');
        },
        tooltipLocation() {
            const t = this.field?.tooltip;
            // undefined -> không render attr -> Tooltip.vue tự dùng 'bottom' như trước.
            return (t && typeof t === 'object' && t.location) ? t.location : undefined;
        },
        tooltipInteractive() {
            const t = this.field?.tooltip;
            return (t && typeof t === 'object' && t.interactive) ? 'true' : undefined;
        },
        getCanResets() {
            return this.canResets;
        },
        canReset() {
            return (this.field?.options?.reset ?? false) === true ||
                    (
                        ['number', 'dimension'].indexOf(this.field?.type) > -1 &&
                        this.field?.options?.reset !== false
                    ) ||
                    (
                        this.field?.type == 'picker' &&
                        this.field?.options?.type == 'icon' &&
                        this.field?.options?.reset !== false
                    )||
                    (this.field?.type === 'choose' &&
                    !this.isChooseOne &&
                    this.field?.options?.reset !== false)
                    ;
        },
        isAIChangeable() {
            let post_id = this.$store.getters['page/params']?.post_id ?? null;
            if (!post_id) {
                return false;
            }
            return ['text', 'textarea', 'link','picker'].includes(this.field?.type) &&
                !['css', 'js', 'id', 'classes', 'custom-css', 'attributes'].includes(this.field.name) &&
                ['admin','manager','designer','supporter'].includes(this.$store.getters['global/user']?.roleName ?? '');
        },
        ctrfields() {
            return ['choose', 'toggle', 'popup', 'color', 'background', 'icon'];
        },
        isOneLine() {
            return this.field?.options?.oneline || this.ctrfields.indexOf(this.field.type) > -1 || this.field.options?.type === 'icon';
        },
        isReverse() {
            return this.isOneLine &&
            (this.ispop !== true || this.ctrfields.indexOf(this.field.type) > -1 || (this.field.type === 'picker' && !this.field.options?.multiple && this.field.options?.type === 'icon')) &&
            (this.field?.type == 'choose' && !this.field?.options?.chooseOne? false:true  );
        },
        isGlobalColorField() {
            return this.field?.class === 'ecom-global-color-field' && this.field?.type === 'color';
        },
        isGlobalTypographyField() {
            return this.field?.class === 'ecom-global-typography-field' &&
                this.field?.type === 'popup' &&
                this.field?.options?.type === 'typography';
        },
        currentScreen(){
            return this.$store.getters['builder/currentScreen'];
        },
        ...mapGetters('builder', ['editingElement']),
        ...mapGetters('settings', [ 'globalData' ]),
        ...mapGetters('settings', [ 'isLiteMode' ]),
    },
    // created() {

    //     if(this.data?.params?.length) {
    //         const checkBgField = this.data.params.find(field => field.type === 'background' && field?.options?.toNative);
    //         if(checkBgField) {
    //             this.fieldValues[this.data?.name].forEach((field, index) => {
    //                 if(checkBgField?.name && field[checkBgField?.name] && !field[checkBgField?.name]?.native) {

    //                     this.fieldValues[this.data?.name][index]['value'].native = this.convertNativeColor(field);
    //                 }
    //             })
    //         }
    //     }
    //     console.log(this.fieldValues);
    // },
    methods: {
        setFieldRef(el) {
            this.fieldComponentRef = el;
        },
        onFieldLabelClick(event) {
            const type = this.field?.type;
            if (['color', 'background', 'popup'].includes(type)) {
                this.doOpenPopup(event);
            }
        },
        findPickerButton(cmp) {
            if (!cmp?.$el?.querySelector) {
                return null;
            }
            return cmp.$el.querySelector('.color-picker-btn, .popup__button, .popupBtn');
        },
        doOpenPopup(event) {
            const refKey = this.field.type + 'Field';
            let cmp = this.fieldComponentRef ?? this.$refs[refKey];
            if (Array.isArray(cmp)) {
                cmp = cmp[0];
            }

            const triggerBtn = (btn) => {
                if (!btn) {
                    return false;
                }
                const el = btn instanceof HTMLElement ? btn : btn.$el;
                if (!el?.click) {
                    return false;
                }
                this.$nextTick(() => el.click());
                return true;
            };

            if (cmp && typeof cmp.openPicker === 'function') {
                this.$nextTick(() => cmp.openPicker());
                return;
            }

            if (cmp && triggerBtn(this.findPickerButton(cmp))) {
                return;
            }

            const scope =
                event?.currentTarget?.closest?.('.ecom-field') ||
                event?.currentTarget?.closest?.('.inline-flex');
            const btn = scope?.querySelector?.('.color-picker-btn, .popup__button, .popupBtn');
            if (triggerBtn(btn)) {
                return;
            }

            if (cmp && typeof cmp.open === 'function') {
                this.$nextTick(() => {
                    cmp.open.call(cmp, event);
                });
            }
        },
        // convertNativeColor(val) {
        //     return Object.keys(val.value?.gradient).length
        //     ? convertBg({
        //             gradient: val?.value?.gradient
        //         })
        //     : "";
        // },
        changeLabel(e){
            this.$emit('update:label', [e.target.dataset.name, e.target.innerText])
        },
        valueGlobal(values, field) {
            let k;
            let v;
            delete field?.options?.global?.value;
            for (k in values) {
                if (k.startsWith('global-')) {
                    let value = values[k];
                    let type = /^global-([\w]+)/g.exec(k)?.[1];
                    let globalValue = this.globalData(type)?.[value]?.value;
                    if (globalValue) {
                        if (typeof globalValue === 'object') {
                            v = globalValue;
                        } else if (typeof globalValue === 'string') {
                            v = globalValue;
                        }
                        field.options.global.value = value;
                    }
                }
            }
            return v ?? values;
        },
        descs (g, f) {
            let descs = f.description;
            let rs = [];
            if(descs) {
                if(typeof descs === 'object') {
                    let p = this.pathField(g, f, false),
                        v = this.$helpers.valueByKey(p, this.values, '||');
                    if(descs.constructor === Object) {
                        descs = [descs];
                    }
                    descs.forEach(wn => {
                        let {content, condition} = wn;
                        if(content) {
                            if(!condition || condition(v, this.values)) {
                                rs.push(content);
                            }
                        }
                    });
                }
                else if(typeof descs === 'string') {
                    rs.push(descs);
                }
            }
            return rs;
        },
        checkDataEmpty(group, field) {
            function isEmpty(obj) {
                for(let key in obj) {
                //if the value is 'object'
                if(obj[key] instanceof Object === true) {
                    if(isEmpty(obj[key]) === false) return false;
                }
                //if value is string/number
                else {
                    //if array or string have length is not 0.
                    if(obj[key].length !== 0) return false;
                }
                }
                return true;
            }
            let name = this.fieldName(field);
            let v = group?.group_name ?
                    this.values?.[group.group_name]?.[name] :
                    this.values?.[name];
            const data = this.valueGlobal(v, field);
            if(typeof data === 'string' && data !== '' || typeof data === 'number') {
                return false;
            }

            if(data && typeof data === 'object') {
                return isEmpty(data);
            }

            return true;
        },
        getData(group, field) {
            let name = this.fieldName(field);
            let v = group?.group_name ?
                    this.values?.[group.group_name]?.[name] :
                    this.values?.[name];
            return this.valueGlobal(v, field);
        },
        getResponsiveData(group, field) {
            let name = this.fieldName(field);
            let value_desktop = {};
            let v = group?.group_name ?
                    this.values?.[group.group_name]?.[name] :
                    this.values?.[name];
            if(name.includes('__tablet') || name.includes('__mobile')) {
                 let name_desktop = name.replace('__tablet', '').replace('__mobile', '');

                value_desktop = group?.group_name ? this.values?.[group.group_name]?.[name_desktop] : this.values?.[name_desktop];
                return v ?  mergeDeep(this.$helpers.copy(value_desktop), this.$helpers.copy(v)) : this.$helpers.copy(value_desktop);
            }

            return v;

            function isObject(item) {
                return (item && typeof item === 'object' && !Array.isArray(item));
            }

            function mergeDeep(target, ...sources) {
                if (!sources.length) return target;
                const source = sources.shift();

                if (isObject(target) && isObject(source)) {
                    for (const key in source) {
                    if (isObject(source[key])) {
                        if (!target[key]) Object.assign(target, { [key]: {} });
                        mergeDeep(target[key], source[key]);
                    } else {
                        Object.assign(target, { [key]: source[key] });
                    }
                    }
                }

                return mergeDeep(target, ...sources);
            }

        },
        // getData(group, field) {
        //     let name = this.fieldName(field);
        //     let value_desktop = {};
        //     let v = group?.group_name ?
        //             this.values?.[group.group_name]?.[name] :
        //             this.values?.[name];
        //     if(name.includes('__tablet') || name.includes('__mobile')) {
        //          let name_desktop = name.replace('__tablet', '');

        //         value_desktop = group?.group_name ? this.values?.[group.group_name]?.[name_desktop] : this.values?.[name_desktop];
        //         console.log(value_desktop, v);
        //         let vn = Object.assign(value_desktop, v);

        //         console.log(vn);

        //     }
        //     //console.log(this.values, group?.group_name);

        //     return this.valueGlobal(v, field);
        // },
        deleteObj(group, fieldName) {
            let values = {};
            if(group.group_name) {
                values = this.values[group.group_name]?.data;
                if(values) {
                    delete values[fieldName];
                    if(Object.keys(values).length === 0) {
                        delete this.values[group.group_name];
                    }
                }
            }else {
                values = this.values;
                delete values?.[fieldName];
            }
        },
        isValidValue(value) {
            return  !(value == '__delete__' ||
                value == '__empty__' ||
                value === '' ||
                (!(value instanceof File) && typeof value === 'object' && Object.keys(value).length === 0)
            );
        },
        updateData(group, field, value) {
            let { group_name } = group;
            let field_name = this.fieldName(field);
            if(!field_name) {
                return ;
            }
            let values = null;
            if(group_name) {
                this.values[group_name] = this.values[group_name] ?? {};
                values = this.values[group_name];
            }
            else {
                values = this.values;
            }
            if(this.isValidValue(value)) {
                values[field_name] = value;
            }
            else {
                delete values?.[field_name];
            }
            this.$emit('update:data', field, values);

        },
        deleteItem(field) {
            if(field.options?.delete !== false) {
                this.$emit('update:delete', field.name);
            }
        },
        colorPreviewValue(group, field) {
            const value = this.getData(group, field);
            if (typeof value === 'string' && value.trim()) {
                return value.toUpperCase();
            }
            return '#FFFFFF';
        },
        typographyPreviewValue(group, field) {
            
            const value = this.getData(group, field);
            if (!value || typeof value !== 'object') {
                return 'Select font family';
            }
       
            const ff = value['font-family'] ?? value.fontFamily;
      
            if (ff != null && String(ff?.name).trim()) {
                return String(ff?.name)
                    .replace(/^["']|["']$/g, '')
                    .split(',')[0]
                    .trim()
                    .slice(0, 32);
            }
            const fs = value['font-size'] ?? value.fontSize;
            if (fs != null && String(fs).trim()) {
                return String(fs).trim();
            }
            return 'Select font family';
        },
        valuePopup(group, field) {
            if(field.type === 'popup' && field.options?.type === 'dropdown') {
                let { preview = 'title' } = field.options;
                let optionsValues = field.options?.values;

                let values = {};

                if(typeof optionsValues === 'string') {
                    values = valuesDropdown[optionsValues] ?? [];
                }
                else if(typeof optionsValues === 'object'){
                    values = optionsValues;
                }
                let value = this.getData(group, field);

                if(value === undefined) {
                    return this.$t('default');
                }
                let isArrValues = values.constructor === Array;
                value = isArrValues?
                        values.filter(it => it.name === value)[0] :
                        value;
                let rs;

                if(preview === 'value'){
                    rs = value?.name ?? value;
                }
                else {
                    rs = isArrValues ? value?.title : values[value];
                }
                return typeof rs === 'string' ? rs.replace(/_/g, ' ') : rs;
            }
        }
    }
};
</script>
