<template>
    <div class="">
        <div class="relative flex items-center">
            <EcomIcon :source="SearchMajor" :size="'w-5 h-8'" class="absolute z-[51] top-0 left-3 flex items-center text-icon-primary" :class="iconClass"></EcomIcon>
            <input
                :id="id"
                v-model="getvalue"
                v-focus="autofocus ? 'select' : false"
                type="search"
                :placeholder="placeholder"
                class="input-search block z-50 w-full pl-9 pr-9 border bg-white border-input hover:border-input-hover focus:border-input-hover focus:outline-focus rounded-lg outline-none outline-offset-1 h-8 text-[13px] font-[450] leading-[20px] sm:text-sm  !leading-10"
                :class="[shortkey !== '' ? 'pr-10' : 'pr-2 ' , borderDark ? ' ' : '  '] + classList"
                @keyup="$emit('keyup', $event.target.value)"
                @keydown="$emit('keydown', $event.target.value)"
                @blur="$emit('blur', $event.target.value)"
                @change="$emit('change', $event.target.value)"
            >
            <div
                v-if="shortkey !== ''"
                class="absolute z-[51] inset-y-0 right-0 flex py-1.5 pr-1.5 shortkey"
            >
                <kbd class="inline-flex items-center px-2 font-sans text-sm text-icon-primary font-medium ">
                    {{ shortkey }}
                </kbd>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
    import { SearchMajor } from "@/assets/icons";
    export default {
        data() {
            return {
                SearchMajor
            }
        },
        props: {
            classList: {
                type: String,
                default: ''
            },
            shortkey: {
                type: String,
                default: ''
            },
            placeholder: {
                type: String,
                default: ''
            },
            id: {
                type: String,
                default: null
            },
            value: {
                type: String,
                default: ''
            },
            borderDark: {
                type: Boolean,
                default: false
            },
            autofocus: {
                type: Boolean,
                default: false
            },
            iconClass: {
                type: String,
                default: ''
            }
        },
        emits: ['keydown', 'keyup', 'blur', 'change'],
        computed: {
            getvalue() {
                return this.value;
            }
        }
    };
</script>

