</i18n>
<template>
    <div  :style="shadowList" class="fixed z-10 py-2 flex flex-col bg-white    rounded-md shadow-list overflow-hidden">
        <div v-show="showFull" ref="list" class="flex-1 flex-grow h-full w-64 overflow-x-hidden overflow-y-auto">
            <ul
                v-show="show"
                class="w-full"
            >
                <li
                    v-for="item in list"
                    :key="item.name"
                >
                    <button
                        type="button"
                        class="w-full px-4 py-2.5 flex items-center text-gray-600 text-xs border-0 transition hover:bg-gray-100 focus:outline-none   "
                        @click="selectItem(item.name)"
                    >
                        <EcomIcon :source="item.icon" class="mr-3 text-gray-500 "></EcomIcon>
                        <span class="text-gray-600 ">
                            {{ item.text }}
                        </span>
                        <template v-if="item.count > -1">
                            ({{ item.count }})
                        </template>
                    </button>
                </li>
            </ul>
            <ContentLink
                ref="content"
                :type="type"
                :src="src"
                :scrolled-bottom="scroll.bottom"
                @hide="hide"
                @update:select="$emit('update:select', urlType + $event, type)"
            />
        </div>
    </div>
</template>

<script lang="ts">
    import ContentLink from './Content.vue';
    import { CollectionsMajor, ProductsMajor, NoteMajor, BlogMajor, EmailMajor, PhoneMajor } from '@/assets/icons';
    export default {
        name: 'GroupsTypes',
        components: {
            ContentLink
        },
        props: {
            src: {
                type: String,
                default: ''
            }
        },
        emits: ['update:select'],
        data(){
            return {
                show: false,
                showFull: false,
                type: '',
                list: [
                    {
                        name: 'collection',
                        text: this.$t('collections'),
                        icon: CollectionsMajor,
                        count: -1
                    },
                    {
                        name: 'product',
                        text: this.$t('products'),
                        icon: ProductsMajor,
                        count: -1
                    },
                    {
                        name: 'page',
                        text: this.$t('pages'),
                        icon: NoteMajor,
                        count: -1
                    },
                    {
                        name: 'blog',
                        text: this.$t('blogs'),
                        icon: BlogMajor,
                        count: -1
                    },
                    {
                        name: 'article',
                        text: this.$t('blog_posts'),
                        icon: BlogMajor,
                        count: -1
                    },
                    {
                        name: 'email',
                        text: this.$t('email'),
                        icon: EmailMajor,
                        count: -1
                    },
                    {
                        name: 'phone',
                        text: this.$t('phone_number'),
                        icon: PhoneMajor,
                        count: -1
                    },
                ],
                scroll: {
                    has: false,
                    top: true,
                    bottom: false
                },
            };
        },
        computed: {
            shadowList(){
                let boxShadow = '-1px 0px 20px rgb(23 24 24 / 5%), 0px 1px 5px rgb(0 0 0 / 15%)';
                if(this.scroll.has){
                    if(this.scroll.top) {
                        boxShadow += ',inset 0 -2rem 2rem -2rem rgba(0, 0, 0, 0.15)';
                    }
                    else if(this.scroll.bottom) {
                        boxShadow += ',inset 0 2rem 2rem -2rem rgba(0, 0, 0, 0.15)';
                    }
                    else {
                        boxShadow += ',inset 0 2rem 2rem -2rem rgba(0, 0, 0, 0.15),inset 0 -2rem 2rem -2rem rgba(0, 0, 0, 0.15)';
                    }

                }
                return { boxShadow };
            },
            urlType(){
                if(this.type === 'article'){
                    return 'blogs/';
                }
                else if (this.type === 'email' || this.type === 'phone') {
                    return '';
                }
                else{
                    return this.type + 's/';
                }
            },
        },
        watch: {
            showFull: function(val){
                this.$nextTick(() => {
                    this.scroll.has = this.hasScroll();
                });
                if(!val){
                    this.$refs.content.show = false;
                }
            },
        },
        mounted () {
            this.$nextTick(() => {
                this.$list = this.$refs.list;
                window.addEventListener('resize', this.eventChange);
                this.$list.addEventListener('scroll', this.eventChange);
                this.eventChange();
            });
        },
        unmounted(){
            window.removeEventListener('resize', this.eventChange);
        },
        methods: {
            hasScroll(){
                let $el = this.$refs['list'];
                if($el) {
                    return $el.scrollHeight > $el.clientHeight;
                }
                return false;
            },
            selectItem(name){
                this.type = name;
                this.$refs['content'].show = true;
                this.show = false;
            },
            hide(){
                this.show = true;
            },
            eventChange(e){
                if(!e) {
                    return;
                }
                let target = e.target;
                this.scroll.top = target.scrollTop == 0;
                this.scroll.bottom = target.scrollTop + target.clientHeight >= target.scrollHeight;
            }
        }
    };
</script>
