<template>
    <div class="ecom-element ecom-collection ecom-collection__filter-values">
      <div v-if="showInitialSkeleton" class="ecom-skeleton-item">
        <div>
          <div class="ecom-skeleton-row">
            <div class="ecom-skeleton-col-4"></div>
            <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
            <div class="ecom-skeleton-col-6"></div>
            <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
            <div class="ecom-skeleton-col-2"></div>
            <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
          </div>
        </div>
      </div>
      <div v-else v-html="liquid('filter_values')"></div>
    </div>
</template>

<script>
import { Liquid, Element } from '@/mixins';
export default {
    name: 'CollectionFilterValue',
    docs: 'https://help.ecomposer.io/docs/elements/collection-elements/applied-filters/',
    presets:false,
    mixins: [Liquid, Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        csrContext() {
            const section = this.shopifyWrapper;
            const type = section?.shopify_type;

            if (!type) return null;

            return {
                type,
                handle: section?.data?.settings?.[type]?.value || null,
                withFilters: true
            };
            
        },
        liquids() {
            return {
                'filter_values': {
                    code: `
                    <!--EComposer-custom-liquid-filters-${this.data.id.split('-').pop()}-->
                      {% capture close_icon %}
                      ${this.data.settings?.general?.icon ?
                        `<span class="ecom-colletion-filter-value--close-icon ecom-flex">
                            ${this.data.settings?.general?.icon}
                          </span>
                        `
                        : ``
                      }
                       {% endcapture %}

                      <ul class="ecom-collection-filter-values-list" role="list">
                        {%- if EComBuilderMode -%}
                          {% for filter in collection.filters %}
                              {% if filter.type == 'list' %}
                                  {% for value in filter.values  %}
                                      <li class="ecom-collection-filter-values-list__item ecom-al_center">
                                          <a
                                            href="{{value.url_to_remove}}" title="{{value.label}}"
                                            class="ecom-w__full ecom-flex ecom-al_center"
                                          >
                                              {{ value.label | escape }} {{close_icon}}
                                          </a>
                                      </li>
                                  {% endfor %}
                                  {% break %}
                              {% endif %}
                          {% endfor %}
                        {%- else -%}
                          {%- for filter in collection.filters -%}
                              {%- if  filter.active_values.size > 0 or filter.min_value.value != nil or filter.max_value.value != nil -%}
                                  {%- assign has_filter = true -%}
                                  {%- break -%}
                              {%- endif -%}
                          {%- endfor -%}
                          {%- if has_filter -%}
                            {%- for filter in collection.filters -%}
                              {%- if filter.active_values.size > 0 or filter.min_value.value != nil or filter.max_value.value != nil -%}
                                  {% for value in filter.active_values  %}
                                      <li class="ecom-collection-filter-values-list__item ecom-al_center">
                                          <a
                                            href="{{value.url_to_remove}}" title="{{value.label}}"
                                            class="ecom-w__full ecom-flex ecom-al_center"
                                          >
                                              {{ value.label | escape }} {{close_icon}}
                                          </a>
                                      </li>
                                  {% endfor %}
                                  {% if filter.type == "price_range" %}
                                      {%- if filter.min_value.value != nil or filter.max_value.value != nil -%}
                                          <li class="ecom-collection-filter-values-list__item ecom-al_center">
                                              <a class="ecom-w__full ecom-flex ecom-al_center" href="{{filter.url_to_remove}}">
                                                  {%- if filter.min_value.value -%}{{ filter.min_value.value | money }}{%- else -%}{{ 0 | money }}{%- endif -%}-{%- if filter.max_value.value -%}{{ filter.max_value.value | money }}{%- else -%}{{ filter.range_max | money }}{%- endif -%}
                                                  {{close_icon}}
                                              </a>
                                          </li>
                                      {%- endif -%}
                                  {% endif %}
                              {% endif %}
                            {% endfor %}
                            <li class="ecom-collection-filter-values-list__item ecom-al_center">
                                <a href="{{collection.url}}" title="${this.lang(this.data.settings?.general?.clear_text ? this.data.settings.general.clear_text :'Clear all', 'clear_all_title' )}" class="ecom-flex ecom-al_center">${this.lang(this.data.settings?.general?.clear_text ? this.data.settings.general.clear_text :'Clear all', 'clear_all_title' )}{{close_icon}}</a>
                            </li>
                            {% endif %}
                        {%- endif -%}
                      </ul>
                    <!--/EComposer-custom-liquid-filters-${this.data.id.split('-').pop()}-->
                    `,
                    preview:
                      `<div class="ecom-skeleton-item">
                          <div>
                              <div class="ecom-skeleton-row">
                                  <div class="ecom-skeleton-col-4"></div>
                                  <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                  <div class="ecom-skeleton-col-6"></div>
                                  <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                  <div class="ecom-skeleton-col-2"></div>
                                  <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                              </div>
                          </div>
                      </div>`
                }
            };
        },

        settings() {
            return [
              {
                group_name: 'general',
                group_title: this.$t('general'),
                params: [
                    {
                      type: 'paragraph',
                      options: {
                        warnings: {
                          content: 'This element will not work if you enable the <b>Ajax filter</b> option on the <b>Filter</b> element'
                        }
                      }
                    },
                    {
                        type: 'popup',
                        label: this.$t('layout'),
                        values: '',
                        name: 'layout_type',
                        options: {
                            type: 'dropdown',
                            default: false,
                            icon_type: 'alignment',
                            preview: 'title',
                            values: {
                                'inline-flex': this.$t('horizontal'),
                                'block': this.$t('vertical')
                            }
                        },
                        css:{
                            selector:' .ecom-collection-filter-values-list',
                            properties:{
                                'display':''
                            }
                        }
                    },
                    {
                      type: 'picker',
                      label: this.$t('icon'),
                      name: 'icon',
                      options: {
                          type: 'icon',
                          layout: 'grid',
                          output: 'value',
                          multiple: false,
                          simple: false
                      }
                    },
                    {
                      type: 'text',
                      name: 'clear_text',
                      label: this.$t('clear_filter'),
                      value: 'Clear all'
                    }
                ]
              }
            ];
        },
        requestShopifyType() {
            return {
                shopify_type: 'collection'
            };
        },
        showInitialSkeleton() {
            if (!this.canUseCustomLiquidForCSR) return false;
            return this.isClientRendering || !this.hasFinishedInitialLiquidCssSync;
        },

        default() {
          return {
            "settings": {
              "general": {
                "clear_text": "Clear all",
                "layout_type": "inline-flex",
                "icon": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 512\" fill=\"currentColor\"><defs><style>.fa-secondary{opacity:.4}</style></defs><path class=\"fa-secondary\" d=\"M310.6 361.4c12.5 12.5 12.5 32.75 0 45.25C304.4 412.9 296.2 416 288 416s-16.38-3.125-22.62-9.375L160 301.3L54.63 406.6C48.38 412.9 40.19 416 32 416S15.63 412.9 9.375 406.6c-12.5-12.5-12.5-32.75 0-45.25l105.4-105.4L9.375 150.6c-12.5-12.5-12.5-32.75 0-45.25s32.75-12.5 45.25 0L160 210.8l105.4-105.4c12.5-12.5 32.75-12.5 45.25 0s12.5 32.75 0 45.25l-105.4 105.4L310.6 361.4z\"></path></svg>"
              }
            },
            "style": {
              "filter_value": {
                "tab": "hover",
                "buttonColornormalmode": "#737070",
                "buttonTypography": {
                  "text-transform": "uppercase",
                  "text-decoration": "none",
                  "font-size": "14px"
                },
                "spacing": {
                  "margin": {
                    "right": "20px"
                  }
                },
                "buttonBackgroundnormalmode": {
                  "classic": {
                    "background-color": "#cfcccc"
                  }
                },
                "margin_item": {
                  "top": "0px",
                  "left": "0px",
                  "bottom": "12.5px",
                  "right": "12.5px"
                },
                "padding": {
                  "right": "5px",
                  "top": "5px",
                  "left": "5px",
                  "bottom": "5px"
                }
              },
              "filter_icon": {
                "iconFontSize": "12px",
                "iconPrimaryColor": "#858383",
                "spacing": {
                  "margin": {
                    "right": "0px",
                    "left": "6px"
                  }
                }
              }
            }
          }
        },
        css() {
          return `
            .ecom-collection-filter-values-list,
            .ecom-collection-filter-values-list li {
              list-style: none;
            }
            .ecom-collection-filter-values-list {
              flex-wrap: wrap;
            }
          `;
        }
    },
    methods: {
        style() {
            return [
              {
                group_alias: 'box',
                options: {
                    group_title: this.$t('general'),
                    group_name: 'general',
                    selector: ' .ecom-collection-filter-values-list'
                },
              },
              {
                group_alias: 'button',
                options: {
                    group_title: this.$t('filter_value'),
                    group_name: 'filter_value',
                    selector: ' .ecom-collection-filter-values-list__item a'
                },
                modify: {
                  remove: {
                      index: 18, length: 1
                  },
                  params: [
                    {
                      position: 19,
                      fields: [
                        {
                          alias: 'padding'
                        },
                        {
                          alias: 'margin',
                          options: {
                            name: 'margin_item',
                            css: {
                              selector: 'root .ecom-collection-filter-values-list__item'
                            }
                          }
                        }
                      ]
                    }
                  ]
                }
              },
              {
                group_alias: 'icon',
                options: {
                    group_title: this.$t('icon'),
                    group_name: 'filter_icon',
                    selector: 'root .ecom-colletion-filter-value--close-icon',
                },
                modify:{
                    params:[
                        {
                            position:15,
                            fields:[
                                {
                                    type:'line'
                                },
                                {
                                    alias:'spacing',
                                    options: {
                                      label:  this.$t('spacing'),
                                    }
                                }
                            ]
                        }
                    ]
                  }
              }
            ];
        },
    }
};
</script>
