

export default {
    data() {
        return {
            dragResize: {
                isActive: false,
                direction: null,
                startX: 0,
                initialWidth: 0,
                element: null,
                finalWidth: 0,
                isResize: false,
                unit: '%',
                minWidth: 0,
                maxWidth: 100
            },
            _dragEndHandler: null,
        }
    },
    methods: {
        toPx(el, value) {
            if (value.endsWith('px')) return parseFloat(value);
            if (value.endsWith('em')) {
                const em = parseFloat(value);
                const fontSize = parseFloat(getComputedStyle(el).fontSize);
                return em * fontSize;
            }
            if (value.endsWith('rem')) {
                const rem = parseFloat(value);
                const rootFontSize = parseFloat(getComputedStyle(document.documentElement).fontSize);
                return rem * rootFontSize;
            }
            if (value.endsWith('%')) {
                const parent = el.parentElement;
                const parentWidth = parent.clientWidth;
                return (parseFloat(value) / 100) * parentWidth;
            }
            return parseFloat(value);
        },
        startDragResize(e, key, element, type = 'block', dir = 'right') {
            // Ngăn sự kiện lan truyền
            let keyx = key;
            e.preventDefault();
            e.stopPropagation();
            let className = '.core__blocks--body, .ecom-content-item__container, .core__group--body, .ecom-inner, .ec-flex-wp';
            if(type != 'block') {
                className = `.core__blocks--body, .ecom-content-item__container, .core__group--body, .ecom-inner, .ec-flex-wp:not(.${this.data.id})`;
            }
            // Lưu vị trí ban đầu
            let initialWidth = element.offsetWidth,
                parent = element.closest(className),
                unit = '%',
                minWidth = 0,
                maxWidth = 100;
            const widthParent = parent.offsetWidth - this.toPx(parent, getComputedStyle(parent).paddingLeft) - this.toPx(parent, getComputedStyle(parent).paddingRight);
            // Tính toán width mới dựa theo hướng kéo
            if(this.screen !== 'desktop') {
                keyx +='__' + this.screen;
            }
            if(type == 'blockFlex') {
                if(this.data.settings[keyx] && this.data.settings[keyx].toString().includes('px')){
                    unit = 'px';
                    maxWidth = 1600;
                }
                else{
                    initialWidth = ((initialWidth) / widthParent) * 100;
                }  
            }
            else {
                if(this.data?.advanced[keyx] && this.data.advanced[keyx].toString().includes('px')){
                    unit = 'px';
                    maxWidth = 1600;
                }
                else{
                    initialWidth = ((initialWidth) / widthParent) * 100;
                }  
            }
            
            this.dragResize = {
                isActive: true,
                startX: e.clientX,
                initialWidth: element.offsetWidth,
                element: element,
                widthParent: widthParent,
                finalWidth: Math.round(initialWidth) + unit,
                unit: unit,
                minWidth: minWidth,
                maxWidth: maxWidth,
                direction: dir
            };
            // Bind các event handlers
            this._dragEndHandler = (ev) => this.onDragResizeEnd(ev, keyx, type);

            this.idoc().addEventListener('mousemove', this.onDragResizeMove);
            this.idoc().addEventListener('mouseup', this._dragEndHandler);
            
        },

        onDragResizeMove(e) {
            if (!this.dragResize?.isActive) return;
            this.dragResize.isResize = true;
            const { unit, minWidth, maxWidth, direction } = this.dragResize;
            
            let deltaX = e.clientX - this.dragResize.startX;
            if (direction === 'left') {
                deltaX = this.dragResize.startX - e.clientX;
            }
            
            let newWidth = this.dragResize.initialWidth
            const widthParent = this.dragResize.widthParent;
            // Tính toán width mới dựa theo hướng kéo
            newWidth = this.dragResize.initialWidth + deltaX;
            if(unit === 'px'){
                newWidth = this.dragResize.initialWidth + deltaX;
            }
            else{
                newWidth = ((this.dragResize.initialWidth + deltaX) / widthParent) * 100;
            }    

           
            newWidth = Math.max(minWidth, Math.min(maxWidth, newWidth));

            // Áp dụng width mới
            if (this.dragResize.element) {
                this.dragResize.element.style.width = newWidth + unit;
                this.dragResize.element.style.maxWidth = newWidth + unit;
                if (this.isParentRow) {
                    this.dragResize.element.style.flex = '0 0 ' + newWidth + unit;
                }
                this.dragResize.finalWidth = Math.round(newWidth) + unit;
            }

        },

        onDragResizeEnd(e, key, type = 'block') {
            if (!this.dragResize?.isActive) return;
            // Remove event listeners
            this.idoc().removeEventListener('mousemove', this.onDragResizeMove);
            this.idoc().removeEventListener('mouseup', this._dragEndHandler);

            // Lưu giá trị cuối cùng vào data
            // Cập nhật settings nếu cần
            if (this.dragResize.isResize && this.dragResize.finalWidth) {
                if(type == 'block' && this.data.advanced) {
                    this.data.advanced['width-max'] = 'custom';
                    this.data.advanced[key] = this.dragResize.finalWidth;
                }
                else if(type == 'blockFlex' && this.data.settings) {
                    this.data.settings['content-width'] = 'boxed';
                    this.data.settings[key] = this.dragResize.finalWidth
                }
            }
            setTimeout(() => {
                this.dragResize.element.style.width = '';
                this.dragResize.element.style.maxWidth = '';
                this.dragResize.element.style.flex = '';
                this.dragResize = {
                    isActive: false,
                    direction: null,
                    startX: 0,
                    initialWidth: 0,
                    element: null
                };
            }, 100);
            // Reset drag state
        }
    }
};
