export type ContentEditableValueMode = 'text' | 'html';

/**
 * Read contenteditable value for syncing to element settings.
 * - `text`: plain sidebar fields (type:text) — avoids &nbsp; leaking into inputs
 * - `html`: rich fields — keeps formatting; figmeta content uses innerText
 */
export function getContentEditableValue(
    el: HTMLElement | null | undefined,
    mode: ContentEditableValueMode = 'html'
): string {
    if (!el) return '';
    if (mode === 'text') {
        return el.innerText;
    }
    if (el.innerText.includes('figmeta') || el.innerHTML.includes('figmeta')) {
        return el.innerText;
    }
    return el.innerHTML;
}

/**
 * INLINE-08: focus a contenteditable region and place the caret at the end.
 * Isolated from dom.ts — only used by inline-edit element components.
 *
 * @param el - the contenteditable element
 * @param doc - builder iframe document (e.g. idoc()); falls back to el.ownerDocument
 */
export function placeCaretAtEnd(
    el: HTMLElement | null | undefined,
    doc?: Document | null
): void {
    if (!el) return;
    const ownerDoc = doc || el.ownerDocument;
    if (!ownerDoc) return;

    const apply = () => {
        el.focus();
        const selection = ownerDoc.getSelection?.();
        if (!selection) return;

        const range = ownerDoc.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        selection.removeAllRanges();
        selection.addRange(range);
    };

    const win = ownerDoc.defaultView;
    if (win?.requestAnimationFrame) {
        win.requestAnimationFrame(apply);
    } else {
        apply();
    }
}

const META_WRAPPER_SELECTOR = '.ecom-meta-editor';

/**
 * Dynamic source tag nằm ngay ở RÌA nội dung (đầu hoặc cuối).
 * Trả null khi rìa là text/br/img — lúc đó browser tự đặt được con trỏ.
 */
function findEdgeMetaWrapper(root: Element, edge: 'first' | 'last'): Element | null {
    let node: Node | null = root;
    while (node) {
        let child: Node | null = edge === 'last' ? node.lastChild : node.firstChild;
        // Bỏ qua text node trắng ở rìa (xuống dòng, thụt lề…)
        while (child && child.nodeType === Node.TEXT_NODE && !child.textContent?.trim()) {
            child = edge === 'last' ? child.previousSibling : child.nextSibling;
        }
        if (!child || child.nodeType !== Node.ELEMENT_NODE) return null;
        const el = child as Element;
        if (el.classList?.contains('ecom-meta-editor')) return el;
        node = el;
    }
    return null;
}

/**
 * Chỗ bấm có nằm ngoài tag về phía đang xét không.
 * 'after'  = dưới tag, hoặc cùng dòng nhưng bên phải tag.
 * 'before' = trên tag, hoặc cùng dòng nhưng bên trái tag.
 */
function isClickPastMeta(
    event: { clientX: number; clientY: number },
    wrapper: Element,
    side: 'before' | 'after'
): boolean {
    const rect = wrapper.getBoundingClientRect();
    // Tag không được render (không có CSS/ẩn) → không suy ra được vị trí, để browser tự lo.
    if (!rect.width && !rect.height) return false;
    if (side === 'after') {
        return event.clientY > rect.bottom
            || (event.clientY >= rect.top && event.clientX > rect.right);
    }
    return event.clientY < rect.top
        || (event.clientY <= rect.bottom && event.clientX < rect.left);
}

/**
 * Dynamic source tag là contenteditable="false". Khi nó nằm ở rìa nội dung thì KHÔNG
 * có vị trí gõ được sau (hoặc trước) nó, nên browser hit-test không đặt được con trỏ —
 * user bấm vào vùng trống mà không thấy caret nhấp nháy, không gõ thêm được.
 *
 * Trả về Range đã collapse cạnh tag rìa khi chỗ bấm nằm ngoài phạm vi tag đó, ngược lại
 * trả null để browser xử lý như bình thường. KHÔNG sửa DOM và KHÔNG tự áp selection —
 * caller quyết định, để mỗi nơi tự đồng bộ state của mình.
 *
 * @param root - vùng contenteditable (body của editor iframe, hoặc element inline-edit)
 * @param event - sự kiện click
 * @param doc - document chứa `root`
 */
export function resolveMetaEdgeCaret(
    root: HTMLElement | null | undefined,
    event: { clientX: number; clientY: number } | null | undefined,
    doc?: Document | null
): Range | null {
    if (!root || !event) return null;
    const ownerDoc = doc || root.ownerDocument;
    if (!ownerDoc) return null;
    // Không có tag → browser tự lo.
    if (!root.querySelector(META_WRAPPER_SELECTOR)) return null;
    // Đang bôi đen bằng chuột → giữ nguyên vùng chọn của user.
    const selection = ownerDoc.getSelection?.();
    if (selection?.rangeCount && !selection.getRangeAt(0).collapsed) return null;

    const trailing = findEdgeMetaWrapper(root, 'last');
    if (trailing && isClickPastMeta(event, trailing, 'after')) {
        const range = ownerDoc.createRange();
        range.setStartAfter(trailing);
        range.collapse(true);
        return range;
    }
    const leading = findEdgeMetaWrapper(root, 'first');
    if (leading && isClickPastMeta(event, leading, 'before')) {
        const range = ownerDoc.createRange();
        range.setStartBefore(leading);
        range.collapse(true);
        return range;
    }
    return null;
}

/** Áp Range vào selection của document tương ứng. Trả false nếu không áp được. */
export function applyCaretRange(range: Range | null, doc?: Document | null): boolean {
    if (!range) return false;
    const ownerDoc = doc || range.startContainer?.ownerDocument;
    const selection = ownerDoc?.getSelection?.();
    if (!selection) return false;
    selection.removeAllRanges();
    selection.addRange(range);
    return true;
}
