                        let date_format  = $el.querySelector('.ecom-product-single__inventory-status').dataset.format || 'DoW_dd_mm_style_1';
                        let hide_day_of_the_week = $el.querySelector('.ecom-product-single__inventory-status').dataset.hide_day_of_the_week || false;
                        hide_day_of_the_week = (hide_day_of_the_week === 'true');
                        let day_of_week = date.split(',')[0];
                        hide_day_of_the_week ? day_of_week = '' : day_of_week += ', ';
                        console.log('%cECOM DEBUG - VAR: date', 'color: #6dec6d', date)
                        let day = date.split(',')[1];
                        let month = date.split(',')[2];
                        date = date.split(',')[3];
                        let year = date.split(' ')[0];
                        switch(date_format){
                            case "DoW_dd_mm_style_1":
                                switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${day}st ${month}`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${day}nd ${month}`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${day}rd ${month}`;
                                    default:
                                        return `${day_of_week}${day}th ${month}`;
                                }

                            case "DoW_dd_mm_style_2":
                                return `${day_of_week}${day} ${month}`;
                                break;
                            case "DoW_mm_dd_style_1":
                                return `${day_of_week}${month} ${day}`;
                                break;
                            case "DoW_mm_dd_style_2":
                                switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${month} ${day}st`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${month} ${day}nd`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${month} ${day}rd`;
                                    default:
                                        return `${day_of_week}${month} ${day}th`;
                                }

                            case "DoW_dd_mm_yyyy_style_1":
                                switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${day}st ${month} ${year}`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${day}nd ${month} ${year}`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${day}rd ${month} ${year}`;
                                    default:
                                        return `${day_of_week}${day}th ${month} ${year}`;
                                }
                            case "DoW_dd_mm_yyyy_style_2":

                                switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${day}st ${month}, ${year}`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${day}nd ${month}, ${year}`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${day}rd ${month}, ${year}`;
                                    default:
                                        return `${day_of_week}${day}th ${month}, ${year}`;
                                }
                            case "DoW_mm_dd_yyyy_style_1":
                                switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${month} ${day}st, ${year}`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${month} ${day}nd, ${year}`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${month} ${day}rd, ${year}`;
                                    default:
                                        return `${day_of_week}${month} ${day}th, ${year}`;
                                }
                            case "DoW_mm_dd_yyyy_style_2":
                                return `${day_of_week}${month} ${day}, ${year}`;
                                break;
                            case "DoW_dd_mm_yyyy_style_3":
                                return `${day_of_week}${day}/${month}/${year}`;
                                break;
                            case "DoW_mm_dd_yyyy_style_3":
                                return `${day_of_week}${month}/${day}/${year}`;
                                break;
                            case "DoW_yyyy_mm_dd":
                                return `${day_of_week}${year}/${month}/${day}`;
                                break;
                            default:
                            switch(day){
                                    case 1:
                                    case 21:
                                    case 31:
                                        return `${day_of_week}${day}st ${month}`;
                                    case 2:
                                    case 22:
                                        return `${day_of_week}${day}nd ${month}`;
                                    case 3:
                                    case 23:
                                        return `${day_of_week}${day}rd ${month}`;
                                    default:
                                        return `${day_of_week}${day}th ${month}`;
                                }
                        }
                    }
                    function updateInventory(variant) {
                        const $dom = $el.querySelector('.ecom-product-single__inventory-status');
                        const $container = $el.querySelector('.ecom-product-single__inventory-container');
                        if ($dom) {
                            if (!variant) {
                                $dom.innerHTML = $dom.dataset.unavailableText;
                                $container.classList.add('ecom-unavailable');
                                $container.classList.remove('ecom-instock', 'ecom-outstock', 'ecom-preorder');
                                $dom.classList.add('ecom-product-single-status--unavailable');
                                $dom.classList.remove('ecom-product-single-status--outstock', 'ecom-product-single-status--instock','ecom-product-single-status--preorder');
                            } else if (!variant.available) {
                                if (
                                    variant.next_incoming_date &&
                                    $dom.dataset.showNextIncomingDate &&
                                    $dom.dataset.showNextIncomingDate === 'true' &&
                                    $dom.dataset.incomingDateText
                                ) {
                                    const tempDiv = document.createElement('div');
                                    tempDiv.innerHTML = variant.next_incoming_date;
                                    let incoming_date = tempDiv.querySelector('time').getAttribute('datetime');
                                    if(incoming_date) {
                                        const date = new Date(incoming_date);
                                        const format_date = $dom.dataset.format;
                                        const formattedDate = formatDate(convertFullDate(date.toUTCString(), format_date));
                                        // const formattedDate = date.toLocaleDateString(window.Shopify.locale ?? 'default', { month: 'long', day: 'numeric' });
                                        $dom.innerHTML = $dom.dataset.incomingDateText.replace(/\{.*\}/g, formattedDate);
                                    }
                                } else {
                                    $dom.innerHTML = $dom.dataset.outstockText;
                                }
                                $container.classList.add('ecom-outstock');
                                $container.classList.remove('ecom-instock', 'ecom-unavailable', 'ecom-preorder');
                                $dom.classList.add('ecom-product-single-status--outstock');
                                $dom.classList.remove('ecom-product-single-status--instock', 'ecom-product-single-status--unavailable','ecom-product-single-status--preorder');
                            } else {
                                if (variant.inventory_policy === 'continue' && variant.inventory_quantity < 1) {
                                    $dom.innerHTML = $dom.dataset.preorderText;
                                    $container.classList.add('ecom-preorder');
                                    $container.classList.remove('ecom-instock', 'ecom-outstock', 'ecom-unavailable');
                                    $dom.classList.add('ecom-product-single-status--preorder');
                                    $dom.classList.remove('ecom-product-single-status--outstock', 'ecom-product-single-status--unavailable','ecom-product-single-status--instock');
                                    if (
                                        variant.next_incoming_date &&
                                        $dom.dataset.showNextIncomingDate &&
                                        $dom.dataset.showNextIncomingDate === 'true' &&
                                        $dom.dataset.incomingDateText
                                    ) {
                                        const tempDiv = document.createElement('div');
                                        tempDiv.innerHTML = variant.next_incoming_date;
                                        let incoming_date = tempDiv.querySelector('time').getAttribute('datetime');
                                        if(incoming_date) {
                                            const date = new Date(incoming_date);
                                            const format_date = $dom.dataset.format;
                                            const formattedDate = formatDate(convertFullDate(date.toUTCString(), format_date));
                                            // const formattedDate = date.toLocaleDateString(window.Shopify.locale ?? 'default', { month: 'long', day: 'numeric' });
                                            $dom.innerHTML = $dom.dataset.incomingDateText.replace(/\{.*\}/g, formattedDate);
                                        }
                                    }

                                } else {
                                    if ($dom.dataset.showLessThan && variant.inventory_management) {
                                        const less = parseInt($dom.dataset.showLessThan);
                                        if (less && variant.inventory_quantity <= less) {
                                            $dom.innerHTML = $dom.dataset.inventoryText.replace(
                                                /\{.*\}/g,
                                                variant.inventory_quantity
                                            );
                                        } else {
                                            $dom.innerHTML = $dom.dataset.instockText;
                                        }
                                    } else {
                                        $dom.innerHTML = $dom.dataset.instockText;
                                    }
                                    $container.classList.add('ecom-instock');
                                    $container.classList.remove('ecom-unavailable', 'ecom-outstock', 'ecom-preorder');
                                    $dom.classList.add('ecom-product-single-status--instock');
                                    $dom.classList.remove('ecom-product-single-status--outstock', 'ecom-product-single-status--unavailable','ecom-product-single-status--preorder');
                                }

                            }
                        }
                    }
                    if(!$wrapper) {
                        return;
                    }
                    let selector = $wrapper.querySelector('[name=id]');
                    const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                    const isHighVariantProduct = this.isLive && (variantCount > 250 || $wrapper.querySelector('[data-high-variant-product]'));
                    const inventory = $el.querySelector('.ecom-product-single__inventory-status');
                    if(!inventory) return;
                    const product_id = inventory.dataset.product_id;
                    if(!product_id) return;
                    const variant_selected = inventory.dataset.variant;

                    let product = null;
                    let json = $wrapper.querySelector('[id^=product-json-' + product_id + ']');
                    if(!json) json = $wrapper.querySelector('[id^=inventory-product-json-' + product_id + ']') || !isLive ? $el?.querySelector('[id^=inventory-product-json]') : null;
                    if (!json) {
                        return;
                    }
                    try {
                        product = JSON.parse(json.innerHTML);
                    } catch (e) {
                        return;
                    }
                    if(variant_selected) {
                        let variant = null;
                        if(isHighVariantProduct) {
                            variant = product;
                        } else {
                            variant = product.variants.find(function(item){
                                if(item.id == variant_selected) return item;
                            });
                        }
                        updateInventory(variant);
                        progressbar(variant);
                    }
                    // updateInventory(variant);
                    // progressbar(variant);
                    $wrapper.addEventListener('ecomVariantChange', function(event) {
                        updateInventory(event.detail.variant);
                        progressbar(event.detail.variant);
                    })
                };
            },
            page_type () {
                return this.$store.getters['page/params'].page;
            },

            default() {
                return {
                    "settings": {
                        "enable_progress_bar": true,
                        "instock_text": "Instock",
                        "outstock_text": "Outstock",
                        "inventory_text": "{quantity} in stock",
                        "when_less_than": 100,
                        "show_next_incoming_date": true,
                        "preorder_text": "Preorder text",
                        "unavailable_text": "Unavailable",
                        "incoming_date_text": "Variant is out of stock. The product will available at: {next_incoming_date}",
                        "icon": {value: this.defaultIcon, cate: 'Regular'}
                    },
                    "style": {
                        "progess_bar": {
                            "tab": "normal",
                            "height": "15px",
                            "background": {
                                "classic": {
                                    "background-color": "#c7b1b1"
                                }
                            },
                            "backgroundActive": {
                                "classic": {
                                    "background-color": "#e34949"
                                }
                            }
                        },
                        "genetal": {
                            "justify-content": "flex-start"
                        },
                        "iconGeneral": {
                            "tab": "normal",
                            "iconFontSize": "20px",
                            "iconPrimaryColornormalmode": "#ED1E26",
                            "justify-content": "flex-start",
                            "spacing": {
                                "margin": {
                                    "right": "10px"
                                }
			                }
                        }
                    }
                }
            }
        },
    };
</script>
