<i18n>
{
    "en": {
        "tooltip_color": "Tooltip color",
        "tooltip_typo": "Tooltip typography",
        "global_colors": "Global Colors",
        "global_typo": "Global typography",
        "primary": "Primary",
        "secondary": "Secondary",
        "text": "Text",
        "accent": "Accent"
    },
    "fr": {
        "tooltip_color": "Couleur de l'info-bulle",
        "tooltip_typo": "Typographie de l'info-bulle",
        "global_colors": "Couleurs globales",
        "global_typo": "Typographie globale"
    },
    "de": {
        "tooltip_color": "Tooltip-Farbe",
        "tooltip_typo": "Tooltip-Typografie",
        "global_colors": "Globale Farben",
        "global_typo": "Globale Typografie"
    },
    "ja": {
        "tooltip_color": "ツールチップの色",
        "tooltip_typo": "ツールチップのタイポグラフィ",
        "global_colors": "グローバルカラー",
        "global_typo": "グローバルタイポグラフィ",
        "primary": "プライマリー",
        "secondary": "セカンダリー",
        "text": "テキスト",
        "accent": "アクセント"
    }
}
</i18n>
<template>
    <div class="inline-block w-full bg-white  text-black  rounded">
        <ul
            v-if="Object.keys(valueTypeFiltered).length > 0"
            class="overflow-auto max-h-60"
        >
            <button
                v-for="(item, key) in valueTypeFiltered"
                :key="key"
                as="li"
                type="button"
                class="
                    cursor-pointer
                    w-full
                    hover:bg-gray-50
                    mb-0.5
                    rounded-sm
                    transition
                    text-sm
                    select-none
                    relative
                    p-2 
                    py-1
                    flex
                    items-center
                    justify-between
                "
                :class="{ 'bg-gray-100 ': selected === key || (!selected && global.value == key) }"
                @click="$emit('update:selected', key)"
            >
                <span class="flex items-center w-full max-w-[170px]">
                    <span
                        class="min-w-[16px] w-4 h-4 flex items-center justify-center rounded border transition-colors"
                        :class="
                            selected === key || (!selected && global.value == key)
                                ? 'bg-primary border-primary text-white'
                                : 'bg-white border-[#8A8A8A] text-transparent'
                        "
                    >
                        <EcomIcon
                            v-if="selected === key || (!selected && global.value == key)"
                            :source="icons.TickSmallMinor"
                            :size="'w-5'"
                            class="-mt-[1px]"
                        ></EcomIcon>
                    </span>
                    <span class="text-xs leading-5 font-normal text-left truncate max-w-[calc(100%-50px)] w-full ml-2 text-gray-600 " :style="styleTitle(item.value)">{{ titleTranslate(item.title)}}</span>
                </span>
                <span
                    v-if="type === 'colors'"
                    class="text-sm text-black  font-normal py-0.5 px-1 rounded-sm ml-2"
                >
                    {{ item.value }}
                </span>
            </button>
        </ul>
        <div v-else class="block py-5 pt-0 m-auto text-sm text-center text-gray-400">Empty</div>
    </div>
</template>

<script lang="ts">
import { TickSmallMinor } from "@/assets/icons";
import { mapGetters } from 'vuex';
export default {
    name: 'Global',

    props: {
        global: {
            type: Object,
            default() {
                return {};
            }
        },
        selected: {
            type: String,
            default: ''
        }
    },
    emits: ['update:selected'],
    computed: {
        type() {
            return this.global?.type ?? '';
        },
        icons(){
            return {
                TickSmallMinor
            }
        },
        tooltip() {
            if (this.type === 'colors') {
                return this.$t('tooltip_color');
            } else if (this.type === 'typography') {
                return this.$t('tooltip_typo');
            }
            return '';
        },
        title() {
            if (this.type === 'colors') {
                return this.$t('global_colors');
            } else if (this.type === 'typography') {
                return this.$t('global_typo');
            }
            return '';
        },
        ...mapGetters('settings', ['globalData']),
        valueType() {
            return this.globalData(this.type);
        },
        valueTypeFiltered() {
            let values = {};
            for (let k in this.valueType) {
                let d = this.valueType[k];
                if (
                    (typeof d.value === 'string' && d.value) ||
                    (typeof d.value === 'object' && Object.keys(d.value).length)
                ) {
                    values[k] = d;
                }
            }
            return values;
        }
    },
    methods: {
        titleTranslate(title){
                if (title) {
                    let key = title.trim().toLowerCase().replace(/[\s&-/]+/g, '_');
                    const translateKey = ['primary','secondary','text','accent'];
                    const matchedKey = translateKey.find(item => item === key);
                    if (matchedKey) {
                        return this.$t(matchedKey);
                    }
                }
                return title;
            },
        styleTitle(value: any) {
            if (!value || typeof value !== 'object') {
                return {};
            }

            const style: Record<string, string | number> = {};

            if (typeof value['font-weight'] === 'string' || typeof value['font-weight'] === 'number') {
                style['font-weight'] = value['font-weight'];
            }

            if (typeof value['font-family'] === 'string') {
                style['font-family'] = value['font-family'];
            } else if (typeof value['font-family'] === 'object' && value['font-family']?.name) {
                style['font-family'] = value['font-family'].name;
            }

            return style;
        },

    }
};
</script>
