/**
 * ! Need define params type
 * @param obj
 * @param objs
 * @returns
 */
export const mergeObj = (obj: any, ...objs: any) => {
    const setValue = (root: any, obj: any) => {
        if (obj && typeof obj === 'object') {
            let k;
            for (k in obj) {
                if (typeof obj[k] === 'object') {
                    root[k] = root[k] ?? (Array.isArray(obj[k]) ? [] : {});
                    setValue(root[k], obj[k]);
                } else {
                    if (root[k] === undefined) {
                        root[k] = obj[k];
                    }
                }
            }
        }
    };
    objs.forEach((item: any) => {
        setValue(obj, item);
    });
    return obj;
}

const isPlainObject = (v: any) => !!v && typeof v === 'object' && !Array.isArray(v);

/**
 * Deep merge, source ghi đè target.
 *
 * Khác `mergeObj` ở trên: `mergeObj` chỉ set khi `root[k] === undefined` (defaults merge),
 * nên không dùng được để apply preset. `mergeDeep` đi sâu vào plain object và ghi đè,
 * nhưng KHÔNG chạm những key mà source không nhắc tới — đó là lý do tồn tại của nó:
 * data lồng 2 tầng như `scolling_horizontal['scrolling-animation-px']` nếu dùng
 * `Object.assign` phẳng sẽ thay nguyên object và xoá mất `trigger_start`/`trigger_end`.
 *
 * Array và giá trị vô hướng được thay nguyên, không nối mảng.
 */
export const mergeDeep = (target: any, ...sources: any[]) => {
    sources.forEach((source: any) => {
        if (!isPlainObject(source)) {
            return;
        }
        Object.keys(source).forEach((k: string) => {
            const value = source[k];
            if (isPlainObject(value)) {
                if (!isPlainObject(target[k])) {
                    target[k] = {};
                }
                mergeDeep(target[k], value);
            } else {
                target[k] = value;
            }
        });
    });
    return target;
}
