<template>
    <div class="ecom-element ecom-collection ecom-collection__sorting">
        <Liquid v-if="exporting && page_type == 'search'" :data="conditionSearchPage.start" />
        <div class="ecom-collection__sorting-wrapper" :data-page="page_type">
            <div class="ecom-collection__sorting-container">
                <div
                    v-if="data.settings.title"
                    class="ecom-collection__filters-heading"
                    v-html="lang(data.settings.title, 'sortting_title')"
                />
                <select
                    name="sort_by"
                    class="ecom-collection__sorting-select"
                    aria-describedby="a11y-refresh-page-message"
                    v-html="liquid('sorting')"
                />
            </div>
        </div>
        <Liquid v-if="exporting && page_type == 'search'" :data="conditionSearchPage.end" />
    </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'CollectionSort',
    docs: 'https://help.ecomposer.io/docs/elements/collection-elements/sorting/',
    presets:false,
    mixins: [Liquid, Javascript, Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        page_type () {
            return this.$store.getters['page/params'].page;
        },
        conditionSearchPage() {
            return {
                start: `{% if request.page_type == 'search' %}
                            {% liquid 
                                assign has_products = false

                                for item in search.results
                                    if item.object_type == 'product'
                                        assign has_products = true
                                        break
                                    endif
                                endfor
                            %}
                            {% if has_products %}
                `,
                end: `{% endif %} {% endif %}`
            }
        },
        liquids() {
            return {
                sorting: {
                    code: `
                        {% if request.page_type == 'search' %}
                            {% assign results = search %}
                        {% else %}
                            {% assign results = collection %}
                        {% endif %}
                        {%- assign sort_by = results.sort_by | default: results.default_sort_by -%}
                        {%- for option in results.sort_options -%}
                            <option value="{{ option.value | escape }}"{% if option.value == sort_by %} selected="selected"{% endif %}>{{ option.name | escape }}</option>
                        {%- endfor -%}
                    `,
                    preview: ''
                }
            };
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: 'text',
                            name: 'title',
                            label: this.$t('label'),
                            // value: this.$t('sort_by'),
                            options: {
                                placeholder: this.$t('sort_by')
                            }
                        },
                        {
                            type: 'switch',
                            name: 'enable_ajax',
                            label: this.$t('enable_ajax_sorting'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            name: 'sortStyle',
                            label: this.$t('layout'),
                            type: 'popup',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                values: {
                                    column: this.$t('vertical'),
                                    row: this.$t('horizontal')
                                }
                            },
                            css: {
                                selector: ' .ecom-collection__sorting-container',
                                properties: {
                                    'flex-direction': ''
                                }
                            }
                        },
                        {
                            type: 'paragraph',
                            name: 'para_notice',
                            options: {
                                warnings: {
                                    content: this.$t('editor_data_is_demo_for_preview_purposes')
                                }
                            }
                        }
                    ]
                }
            ];
        },

        javascript() {
            return function () {
                const $el = this.$el;
                if(!$el) return;
                if (this.isLive) {
                    const _this = this, enable_ajax = this.settings.enable_ajax;
                    const el_sort = $el.querySelector('.ecom-collection__sorting-wrapper');
                    if(!el_sort) return;
                    const page_type = el_sort.dataset.page ?? 'collection';
                    const class_wrapper = `.ecom-collection__product-main.ecom-collection_product_template_${page_type}`;
                     const ecomAjaxSorting = (function() {
                        return {
                            searchParamsInitial: window.location.search.slice(1),
                            searchParamsPrev: window.location.search.slice(1),
                            init() {
                                const selected = _this.$el.querySelector('.ecom-collection__sorting-select');
                                if(selected.length == 0) return;

                                const wrapper = selected.closest('.ecom-sections[data-section-id]');
                                const wrapper_products = wrapper.querySelectorAll('.ecom-collection__product-wrapper');
                                if(!wrapper || !wrapper.dataset.sectionId || wrapper_products.length === 0) return;
                                this.selected = selected;
                                this.wrapper = wrapper;
                                this.sectionId = wrapper.dataset.sectionId;
                                this.wrapper_products = wrapper_products;
                                const $this = this;
                                this.selected.addEventListener('change', function(e){
                                    const params = window.location.search.replace('?', '').replace(/&sort_by=[^&]+/, '') + "&sort_by=" + e.target.value;
                                    const url = `${window.location.pathname}?section_id=${$this.sectionId}&${params}`;
                                    $this.handleLoadProduct(url, params);
                                });
                                this.setListeners();
                            },

                            setListeners() {
                                const onHistoryChange = (event) => {
                                const searchParams = event.state ? event.state.searchParams : this.searchParamsInitial;
                                if (searchParams === this.searchParamsPrev) return;
                                const url = `${window.location.pathname}?section_id=${this.sectionId}&${searchParams}`;
                                this.handleLoadProduct(url, searchParams, false)
                                }
                                window.addEventListener('popstate', onHistoryChange);
                            },

                            handleLoadProduct(fetch_url, searchParams, updateURLHash = true) {
                                this.searchParamsPrev = searchParams;
                                const _this = this;
                                const loadProduct = async function(url) {
                                const response = await fetch(url, {
                                    method: 'GET',
                                    headers: {
                                    'Content-Type': 'text/html'
                                    },
                                });
                                return response.text();
                                }
                                
                                // Add loading class to all wrapper products
                                _this.wrapper_products.forEach(wrapper_product => {
                                    wrapper_product.classList.add('ecom-doing-filter');
                                });

                                loadProduct(fetch_url).then(function(data) {
                                    const dom = document.createElement('div');
                                    dom.innerHTML = data;

                                    // Update all wrapper products
                                    _this.wrapper_products.forEach(wrapper_product => {
                                        const product_wrapper = wrapper_product.querySelector(class_wrapper);
                                        if(!product_wrapper) return;

                                        //product_wrapper.scrollIntoView({behavior: "smooth"});
                                        //Update product
                                        product_wrapper.innerHTML = dom.querySelector(class_wrapper).innerHTML;
                                        //update filter
                                        //Render filter values

                                        product_wrapper.querySelector('.ecom-collection__product--wrapper-items') &&
                                        product_wrapper.dispatchEvent(new CustomEvent('ecom-products-init',{
                                            detail: {
                                                wrapper: product_wrapper
                                            }
                                        }));
                                        const container = document.querySelector(`.ecom-collection__product-container`);
                                        if(container) {
                                            container.dispatchEvent(new CustomEvent('ecom-products-init-slider',{
                                            detail: {
                                                wrapper: container
                                            }
                                            }));
                                        }
                                    });
                                    
                                    //Update URL
                                    if(updateURLHash) _this.updateURLHash(searchParams)
                                })
                                .finally(function() {
                                    // Remove loading class from all wrapper products
                                    _this.wrapper_products.forEach(wrapper_product => {
                                        wrapper_product.classList.remove('ecom-doing-filter');
                                    });
                                })
                            },

                            updateURLHash(searchParams) {
                                history.pushState({ searchParams }, '', `${window.location.pathname}${searchParams && '?'.concat(searchParams)}`);
                            },


                        }
                    })();

                    if(enable_ajax) {
                        ecomAjaxSorting.init();
                    }
                    else {
                        this.$el
                        .querySelector('[name="sort_by"]')
                        .addEventListener('change', function (e) {
                            const urlParams = new URLSearchParams(new URL(window.location).search);
                            const desiredParams = ['q', 'type', 'options'];
                            const filteredParams = {};

                            for (const [key, value] of urlParams) {
                                if (desiredParams.includes(key)) {
                                    filteredParams[key] = value;
                                }
                            }
                            for (const key in filteredParams) {
                                window.EComposer.queryParams[key] = filteredParams[key];
                            }
                            window.EComposer.queryParams.sort_by = e.target.value;
                            window.location.search = new URLSearchParams(
                                window.EComposer.queryParams
                            ).toString();
                        });
                    }
                }
            };
        },
        requestShopifyType() {
            return {
                shopify_type: 'collection'
            };
        },
        css() {
            return `
            .ecom-collection__sorting-wrapper{
                display:flex
            }
                .ecom-collection__filters-heading {
                    display: block;
                    white-space:nowrap;
                }
                .ecom-collection__sorting-select {
                    overflow: hidden;
                    text-overflow: ellipsis;
                    white-space: nowrap;
                    outline:none;
                }
                .ecom-collection__sorting-container{
                    display:inline-flex;
                    flex-direction:column;
                    width: 100%;
                }
            `;
        },
        default() {
            return {
                settings: {
                    title: "Sort by",
                    sortStyle: "column"
                }
            }
        }
    },
    methods: {
        style() {
            let modify = {}
            if(this.data.settings.sortStyle == 'row'){
                modify = {
                    remove:{
                        index:0,
                        length:1
                    },
                    params:[
                        {
                            position:1,
                            fields:{
                                alias:'align-items',
                                options:{
                                    label: this.$t('alignment'),
                                    options:{
                                        values:['start','center','end']
                                    },
                                    css:{
                                        properties:{
                                            display:'flex',
                                            'align-items':''
                                        }
                                    }
                                }
                            }
                        }
                    ]
                }
            }
            let style = [
                {
                    group_alias: 'box',
                    options: {
                        group_name: 'general',
                        group_title: this.$t('general'),
                        selector: ' .ecom-collection__sorting-container',
                    },
                    modify: {
                        params: [
                            {
                                fields: {
                                    name: 'alignment',
                                    label: this.$t('alignment'),
                                    type: 'choose',
                                    options: {
                                        type: 'text-align',
                                        values: ['flex-start', 'center', 'flex-end']
                                    },
                                    css: {
                                        properties: {
                                            display: 'flex',
                                            'align-items': '',
                                            'justify-content': ''
                                        }
                                    }
                                }
                            },
                            {
                                position: 20,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            }
                        ]

                    }
                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_name: 'label',
                        group_title: this.$t('label'),
                        selector: ' .ecom-collection__filters-heading'
                    },
                    modify
                },
                {
                    group_alias: 'input',
                    options: {
                        group_name: 'sorting',
                        group_title: this.$t('sorting'),
                        selector: ' .ecom-collection__sorting-select'
                    },

                }
            ]
            return style;
        }
    }
};
</script>
