<template>
    <div class="relative flex switchdevice" :class="id">
        <button
            class="text-gray-500 hover:text-primary-700 transition"
            :data-tooltip="screens[current].title"
            data-tooltip-location="left"
            @click="doOpen"
            type="button"
        >
            <EcomIcon :source="icons[screens[current]?.icon]" :size="'w-5'" color="text-icon-primary" class="flex items-center"></EcomIcon>
        </button>
        <div
            v-if="open"
            class="switch__content shadow-md flex gap-1 py-1 px-1 top-full translate-y-1 absolute bg-white   rounded transition z-20"
            :class="popupSide == 'right' ? 'left-0' : 'right-0'"
        >
            <div
                v-for="(value, name) in screens"
                :key="name"
                class="flex"
            >
                <button
                    type="button"
                    class="w-8 h-8 text-gray-500 transition flex items-center justify-center hover:bg-gray-100 rounded"
                    :data-tooltip="value.title"
                    data-tooltip-location="bottom"
                    :class="{ 'bg-gray-100 ': current === value.name }"
                    @click="choose(name)"
                >
                    <EcomIcon :source="icons[value.icon]" :size="'w-5'" color="text-icon-primary" class="flex items-center" />
                </button>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
// Reduce time render by remove listOptions
import {DesktopMajor, TabletMajor, MobileMajor} from '@/assets/icons';
export default {
    props: {
        popupSide: {
            type: String,
            default: 'left'
        }
    },
    data() {
        return {
            open: false,
            id: this.$helpers.randid(),
            icons: {
                'DesktopMajor': DesktopMajor, 'MobileMajor': MobileMajor, 'TabletMajor': TabletMajor
            }
        }
    },
    computed: {
        current() {
            return this.screen;
        },
        classContent() {
            let index = Object.keys(this.screens).indexOf(this.current);
            if (index == 1) {
                return '-mt-6';
            } else if (index == 2) {
                return '-mt-12';
            }
            return '';
        },
        screens() {
            return this.$store.getters['builder/screens'];
        },
        screen() {
            return this.$store.getters['builder/screen'];
        }
    },
    methods: {
        choose(val) {
            this.$store.commit('builder/setScreen', val);
            this.doClose();
        },
        doOpen(e) {
            this.open = true;
            document.addEventListener('click', this.doClose);
        },

        doClose(e) {
            if (
                e === undefined ||
                !e.target.closest('.'+this.id)
            ) {
                this.open = false;
                document.removeEventListener('click', this.doClose);
            }
        }
    }
};
</script>
