<template>
    <div class="w-full">
        <!-- Đang tải definitions -->
        <div v-if="loading" class="flex items-center gap-2 py-3 text-xs text-gray-500">
            <svg class="w-3.5 h-3.5 animate-spin" viewBox="0 0 24 24" fill="none">
                <circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="3" opacity=".25" />
                <path d="M22 12a10 10 0 0 0-10-10" stroke="currentColor" stroke-width="3" stroke-linecap="round" />
            </svg>
            <span>{{ $t('loading_metafields') }}</span>
        </div>

        <!-- Store chưa có definition nào: hướng dẫn thay vì dropdown rỗng -->
        <div
            v-else-if="!items.length"
            class="px-3 py-3 text-xs leading-5 border rounded border-[#E1B878] bg-[#FFF5EA] text-gray-600"
        >
            <p class="font-medium">{{ $t('no_metafield_definition_found') }}</p>
            <p class="mt-1">{{ $t('create_a_metafield_definition_in_shopify_settings_metafields_or_switch_to_custom_liquid') }}</p>
        </div>

        <template v-else>
            <!-- Ô search: chỉ hiện khi danh sách đủ dài để cần tìm -->
            <div v-if="items.length > SEARCH_THRESHOLD" class="relative mb-2">
                <input
                    v-model="search"
                    type="text"
                    class="w-full h-8 pl-7 pr-2 text-xs transition border rounded border-default text-text-primary focus:ring-offset-1 focus:border-gray-100 focus:ring-2 focus:ring-primary-400"
                    :placeholder="$t('search_metafield')"
                >
                <svg
                    class="absolute w-3.5 h-3.5 text-gray-400 -translate-y-1/2 left-2 top-1/2"
                    viewBox="0 0 20 20" fill="currentColor"
                >
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M8 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM2 8a6 6 0 1 1 10.89 3.476l4.817 4.817-1.414 1.414-4.817-4.817A6 6 0 0 1 2 8z" />
                </svg>
            </div>

            <!-- Không khớp search -->
            <p v-if="!filteredGroups.length" class="py-3 text-xs text-center text-gray-500">
                {{ $t('no_metafield_matches_your_search') }}
            </p>

            <!-- Danh sách, nhóm theo namespace -->
            <div ref="list" v-else class="overflow-y-auto border rounded border-default max-h-[280px]">
                <div v-for="group in filteredGroups" :key="group.namespace">
                    <p class="sticky top-0 px-2 py-1 font-medium text-[11px] tracking-wider uppercase text-gray-500 bg-gray-50 border-b border-default z-50 first:border-t">
                        {{ group.namespace }}
                    </p>
                    <button
                        v-for="item in group.items"
                        :key="item.namespace + '.' + item.key"
                        type="button"
                        class="flex items-start w-full gap-2 px-2 py-2 text-left border-b border-default last:border-b-0"
                        :class="rowClass(item)"
                        :disabled="!item.supported"
                        :data-mf-selected="isSelected(item) ? '1' : null"
                        @click="select(item)"
                    >
                        <span class="flex-shrink-0 w-3.5 h-3.5 mt-0.5 border rounded-full relative" :class="isSelected(item) ? 'border-primary' : 'border-gray-400'">
                            <span v-if="isSelected(item)" class="absolute inset-[2px] rounded-full bg-primary"></span>
                        </span>
                        <span class="min-w-0 flex-1">
                            <span class="block text-xs leading-4 break-words" :class="item.supported ? 'text-gray-700' : 'text-gray-400'">
                                {{ item.name }}
                            </span>
                            <span class="block mt-0.5 font-normal text-[10px] text-gray-400 break-all">
                                {{ item.namespace }}.{{ item.key }}
                            </span>
                            <span v-if="!item.supported" class="block mt-1 text-[10px] leading-3 text-[#9A5410]">
                                {{ $t('this_metafield_type_is_not_supported_yet') }}
                            </span>
                        </span>
                        <span
                            class="flex-shrink-0 px-1.5 py-0.5 font-normal text-[10px] tracking-wide capitalize rounded"
                            :class="item.supported ? 'bg-[#E0EEEC] text-[#064E4C]' : 'bg-gray-100 text-gray-400'"
                        >{{ item.typeLabel }}</span>
                    </button>
                </div>
            </div>

            <!-- Q7: backend lấy first:250 không phân trang → nói rõ khi bị cắt -->
            <p v-if="isTruncated" class="mt-1.5 text-[10px] leading-4 text-[#9A5410]">
                {{ $t('showing_the_first_n_metafields_use_search_to_narrow_down', { n: items.length }) }}
            </p>
        </template>
    </div>
</template>

<script lang="ts">
    import { isElementMetafieldSupported } from '@/store/modules/dynamicSources';

    /** Backend query `metafieldDefinitions(first: 250)` — đạt trần thì coi như bị cắt. */
    const DEFINITION_FETCH_LIMIT = 250;
    const SEARCH_THRESHOLD = 8;

    /**
     * Nhãn ngắn cho badge type. Chỉ để merchant nhận ra kiểu dữ liệu, không phải
     * bản dịch đầy đủ — type lạ sẽ tự prettify từ chính chuỗi type.
     */
    const TYPE_LABELS: Record<string, string> = {
        single_line_text_field: 'Text',
        multi_line_text_field: 'Multi-line',
        rich_text_field: 'Rich text',
        number_integer: 'Integer',
        number_decimal: 'Decimal',
        id: 'ID',
        json: 'JSON',
        boolean: 'True/False',
        date: 'Date',
        date_time: 'Date & time',
        money: 'Money',
        rating: 'Rating',
        color: 'Color',
        url: 'URL',
        link: 'Link',
        file_reference: 'File',
        product_reference: 'Product',
        collection_reference: 'Collection',
        page_reference: 'Page',
        article_reference: 'Article',
        variant_reference: 'Variant',
        metaobject_reference: 'Metaobject',
        mixed_reference: 'Mixed',
    };

    function typeLabel(type?: string | null): string {
        if (!type) return '—';
        if (TYPE_LABELS[type]) return TYPE_LABELS[type];
        if (type.startsWith('list.')) {
            return 'List · ' + typeLabel(type.slice(5));
        }
        // dimension, weight, volume và ~35 measurement type khác
        return type.replace(/_/g, ' ');
    }

    export default {
        name: 'MetafieldField',
        props: {
            data: {
                type: Object,
                default: null
            },
            field: {
                type: Object,
                default() {
                    return {};
                }
            }
        },
        emits: ['update:data'],
        data() {
            return {
                search: '',
                SEARCH_THRESHOLD,
                // Chỉ tự cuộn MỘT lần cho mỗi lần mở panel. Cuộn lại mỗi khi
                // `filteredGroups` đổi sẽ giật danh sách ngay dưới tay merchant
                // đang gõ search.
                hasScrolledToSelected: false
            };
        },
        computed: {
            loading() {
                return this.$store.getters['dynamicSources/loading'];
            },
            /** Owner do element chỉ định qua `field.options.owner`. */
            owner() {
                return this.field?.options?.owner || '';
            },
            /** Definitions của owner đang áp dụng, đã chuẩn hoá về shape phẳng. */
            items() {
                const raw = this.owner
                    ? this.$store.getters['dynamicSources/metafieldsByOwner'](this.owner)
                    : this.$store.getters['dynamicSources/metafileds'];
                if (!Array.isArray(raw)) return [];

                return raw
                    .map((edge: any) => {
                        const node = edge?.node ?? edge;
                        if (!node?.namespace || !node?.key) return null;
                        const type = node?.type?.name ?? null;
                        return {
                            name: node.name || `${node.namespace}.${node.key}`,
                            namespace: node.namespace,
                            key: node.key,
                            type,
                            typeLabel: typeLabel(type),
                            supported: isElementMetafieldSupported(type)
                        };
                    })
                    .filter(Boolean);
            },
            isTruncated() {
                return this.items.length >= DEFINITION_FETCH_LIMIT;
            },
            /**
             * Nhóm theo namespace, giữ nguyên thứ tự backend trả về.
             * Type chưa hỗ trợ vẫn hiện nhưng disable — merchant thấy metafield của
             * mình tồn tại, chỉ là element chưa render được (Q6).
             */
            filteredGroups() {
                const q = this.search.trim().toLowerCase();
                const groups: Array<{ namespace: string; items: any[] }> = [];
                const index: Record<string, number> = {};

                for (const item of this.items) {
                    if (q &&
                        !item.name.toLowerCase().includes(q) &&
                        !item.namespace.toLowerCase().includes(q) &&
                        !item.key.toLowerCase().includes(q)
                    ) {
                        continue;
                    }
                    if (index[item.namespace] === undefined) {
                        index[item.namespace] = groups.length;
                        groups.push({ namespace: item.namespace, items: [] });
                    }
                    groups[index[item.namespace]].items.push(item);
                }
                return groups;
            }
        },
        watch: {
            owner: 'load',
            // Definitions load async nên lúc `mounted` danh sách thường còn rỗng —
            // đợi nó có nội dung rồi mới cuộn được.
            filteredGroups: {
                immediate: true,
                handler() {
                    if (this.hasScrolledToSelected) return;
                    this.$nextTick(() => this.scrollToSelected());
                }
            }
        },
        mounted() {
            this.load();
        },
        methods: {
            load() {
                // Action cache theo owner — gọi lại không tốn thêm request.
                this.$store.dispatch('dynamicSources/loadDynamicSources',
                    this.owner ? { owner: this.owner } : undefined);
            },
            isSelected(item) {
                return this.data?.namespace === item.namespace && this.data?.key === item.key;
            },
            rowClass(item) {
                if (!item.supported) return 'cursor-not-allowed bg-gray-50';
                return this.isSelected(item)
                    ? 'cursor-pointer bg-[#E0EEEC]'
                    : 'cursor-pointer bg-white hover:bg-gray-50';
            },
            /**
             * Cuộn tới metafield đang chọn khi mở panel.
             *
             * Đặt `scrollTop` bằng tay chứ KHÔNG dùng `scrollIntoView`: hàm đó cuộn
             * mọi khung scroll tổ tiên, tức kéo luôn cả sidebar setting — merchant mở
             * panel ra là thấy nó nhảy.
             */
            scrollToSelected() {
                const list = this.$refs.list;
                if (!list || !this.data?.namespace) return;

                const el = list.querySelector('[data-mf-selected]');
                if (!el) return;

                this.hasScrolledToSelected = true;

                // Header namespace là `sticky top-0` nên nó che dòng đầu tiên nằm
                // dưới nó — trừ đúng chiều cao của nó ra.
                const sticky = list.querySelector('p.sticky');
                const stickyHeight = sticky ? sticky.offsetHeight : 0;

                const listRect = list.getBoundingClientRect();
                const elRect = el.getBoundingClientRect();

                // Đã nhìn thấy trọn dòng rồi thì đừng cuộn cho có.
                if (elRect.top >= listRect.top + stickyHeight && elRect.bottom <= listRect.bottom) {
                    return;
                }

                const offset = elRect.top - listRect.top + list.scrollTop - stickyHeight;
                list.scrollTop = Math.max(0, offset);
            },
            select(item) {
                if (!item.supported) return;
                if (this.isSelected(item)) return;
                // Lưu cả `type` và `name`: nếu merchant xoá definition trên Shopify thì
                // element vẫn biết mình đã cấu hình gì để render fallback, không crash.
                this.$emit('update:data', {
                    namespace: item.namespace,
                    key: item.key,
                    type: item.type,
                    name: item.name
                });
            }
        }
    };
</script>
