<template>
    <div
        ref="vcolors"
        @mousedown="onDragStart"
        class="relative flex flex-1 w-full h-[190px] overflow-hidden rounded ecom-color-palette"
    >
        <div
            v-if="textColor?.hex"
            class="absolute w-5 h-5 rounded-full pointer-events-none ecom-picker-color z-1"
            :style="pointerPosition"
        />
        <div
            class="relative flex-1 h-[190px] border rounded ecom-color-palette"
            :class="hueString"
            :style="{ background: hueString }"
        />
        <div class="absolute top-0 bottom-0 left-0 right-0 ecom-brightness-light" />
        <div class="absolute top-0 bottom-0 left-0 right-0 ecom-brightness-dark" />
    </div>
</template>
<script>
import { getTinyColor, getElSizePosition, getValInRange, throttle } from "./untility.ts";
export default {
    props: {
        data: {
            type: Object,
            default: () => ({})
        },
        hue: {
            type: Number,
            default: 0
        }
    },
    data() {
        return {
            textColor: {},
            saturation: 0,
            itv: null
        };
    },
    computed: {
        pointerPosition() {
            const left = `calc(${this.saturation}% - 0px)`;
            const top = `calc(${100 - this.textColor.hsv.v}% - 0px)`;
            return { left, top };
        },
        hueString() {
            const { hex } = getTinyColor(`hsv(${this.hue}, 100%, 100%)`);
            return hex;
        }
    },
    methods: {
        syncFromData(val) {
            if (!val?.hsv) {
                return;
            }
            this.textColor = {
                hex: val.hex,
                rgb: { ...val.rgb },
                hsv: { ...val.hsv },
                alpha: val.alpha
            };
            this.saturation = val.hsv.s ?? 0;
        },
        emitChange() {
            this.$nextTick(() => {
                this.$emit("change", this.textColor);
            });
        },
        onDragStart(e) {
            this.isDragging = true;
            this.sizeInfo = getElSizePosition(this.$refs.vcolors);
            this.onDragging(e);
            this.registerGlobalEvent("bind");
        },
        onDragging(e) {
            if (!this.isDragging && e) {
                return;
            }
            const { pageX, pageY } = e;
            const { width, height, left, top } = this.sizeInfo;

            const l = pageX - left - window.scrollX;
            const t = pageY - top - window.scrollY;

            const alpha = this.textColor.alpha;
            let saturation = (l / width) * 100;
            let value = ((height - t) / height) * 100;

            saturation = Math.round(getValInRange(saturation, 0, 100));
            value = Math.round(getValInRange(value, 0, 100));
            if (value != 0) {
                this.saturation = saturation;
            }
            this.textColor = getTinyColor(`hsva(${this.hue}, ${saturation}%, ${value}%, ${alpha})`);

            clearTimeout(this.itv);
            this.itv = setTimeout(this.emitChange, 300);
        },
        onDragEnd() {
            this.isDragging = false;
            this.registerGlobalEvent("unbind");
        },
        registerGlobalEvent(type) {
            type = type === "bind" ? "addEventListener" : "removeEventListener";
            window[type]("mousemove", throttle(this.onDragging, 16.7));
            window[type]("mouseup", this.onDragEnd);
            window[type]("contextmenu", this.onDragEnd);
        }
    },
    watch: {
        data: {
            handler(val) {
                this.syncFromData(val);
            },
            deep: true,
            immediate: true
        }
    }
};
</script>
