<template>
    <div class="ecom-element ecom-product-single ecom-product-single__price">
        <div class="ecom-product-single__price-wrapper">
            <div class="ecom-product-single__price-container">
                <div class="ecom-product-single__price-container-grid">
                    <div
                        class="ecom-product-single ecom-product-single__price--prices"
                        v-html="liquid('prices')"
                    />

                    <div
                        v-if="show_badges" class="ecom-product-single__price--badges-wrapper"
                        v-html="liquid('badge')"
                    />
                    <div
                        v-if="show_sale_pecent" class="ecom-product-single__price--badges-pecent-wrapper"
                        :data-label-type="data.settings.sale_badge_type"
                        v-html="liquid('badge_pecent')"
                    />
                </div>
                <div
                    v-if="show_groundprice"
                    class="ecom-product_ground-price" v-html="liquid('ground_price')"
                />
                <div
                    v-if="data.settings?.show_payment_terms"
                    class="ecom-product-single ecom-product-single__price--payment-terms"
                    v-html="liquid('payment_terms')"
                />
                <div class="ecom-product-single-afterpay" v-html="liquid('afterpay')" />
            </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
    name: 'productPrice',

    presets:true,
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives: ['sale_text', 'show_badges', 'sold_text']
        };
    },
    computed: {
        assignTargetVariant() {
            return `
                {%- liquid
                    if product.has_only_default_variant
                        assign target = product
                    else
                        assign target = product.selected_or_first_available_variant
                    endif
                -%}`;
        },
        taxesTextAndShipingPolicySnippet() {
            if (!this.canUseCustomLiquidForCSR) {
                return `
                    {%- if cart.taxes_included or shop.shipping_policy.body != blank -%}
                        {% if taxes_text %}
                            <div class="ec-product__tax caption rte">
                                {%- if shop.taxes_included -%}
                                    ${this.lang(this.data.settings.include_taxes, 'include_taxes')}
                                {%- endif -%}
                                {%- if shop.shipping_policy.body != blank -%}
                                    ${this.lang(this.data.settings.shipping_policy, 'shipping_policy', { link: 'shop.shipping_policy.url' })}
                                {%- endif -%}
                            </div>
                        {%- endif -%}
                    {%- endif -%}
                `;
            }

            if (!this.data?.settings?.show_preview_taxes_and_shipping_policy) return "";
            return `
                <div class="ec-product__tax caption rte">
                    ${this.lang(this.data.settings.include_taxes, 'include_taxes')}
                    ${this.lang(this.data.settings.shipping_policy, 'shipping_policy', { link: 'shop.shipping_policy.url' })}
                </div>
            `
        },
        liquids() {
            return {
                prices: {
                    code: `
                    ${this.assignTargetVariant}
                    <div class="ecom-product-single__price--sale {% if target.compare_at_price == nil or target.compare_at_price <=  target.price %} ecom-product-single__price-normal {% endif %}"${this.show_bss_b2b_wholesale ? ` bss-b2b-product-price bss-b2b-variant-price bss-b2b-featured-product bss-b2b-product-id="{{ product.id }}" bss-b2b-variant-id="{{ product.selected_or_first_available_variant.id }}"` : ''} data-price="{{target.price}}">
                        {%- if settings.currency_code_enabled -%}
                            {{target.price | money_with_currency}}
                        {%- else -%}
                            {{target.price| money }}
                        {%- endif -%}
                    </div>
                    ${this.show_bss_b2b_wholesale ? `<div class="bss-b2b-qb-table"></div>` : ``}
                    ${!this.data.settings?.show_total_price
                            ? `
                        <div class="ecom-product-single__price--regular" {%- if target.compare_at_price == nil or target.compare_at_price <=  target.price -%}  style="display:none" {% endif %}>
                            {%- if settings.currency_code_enabled -%}
                                {{target.compare_at_price | money_with_currency}}
                            {%- else -%}
                                {{target.compare_at_price | money }}
                            {%- endif -%}
                        </div>
                        `
                            : ``
                        }
                    {%- capture taxes_text -%}${this.lang(this.data.settings.include_taxes, 'include_taxes')}{%- endcapture -%}
                    ${this.taxesTextAndShipingPolicySnippet}
                `,
                    preview: `
                    <div class="ecom-skeleton-item" style="min-width: 180px">
                        <div class="ecom-skeleton-col-12">
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-8"></div>
                            </div>
                        </div>
                        <div class="ecom-skeleton-col-12">
                        <div class="ecom-skeleton-row">
                            <div class="ecom-skeleton-col-10"></div>
                        </div>
                        </div>
                    </div>
                `
                },
                payment_terms: {
                    code: `
                        ${this.data.settings?.show_payment_terms ?
                            `
                            <div class="ec-form-payment_terms">
                                {{ form | payment_terms}}
                            </div>
                            `
                            : ``
                        }
                    `,
                    preview: ``
                },
                badge: {
                    code: `
                    ${this.canUseCustomLiquidForCSR ? this.assignTargetVariant : ""}
                    <div class="ecom-product-single__price--badges">
                        {%- assign savings = target.compare_at_price | minus: target.price | times: 100.0 | divided_by: target.compare_at_price | round -%}
                        ${this.data.settings?.sale_badge_type === 'amount'
                            ?  `{%- if settings.currency_code_enabled -%}
                                    {%- assign savings = target.compare_at_price | minus: target.price | money_with_currency -%}
                                {%- else -%}
                                    {%- assign savings = target.compare_at_price | minus: target.price | money -%}
                                {%- endif -%}
                            `
                            :''}
                        <span class="ecom-product-single__price--badges-sale" data-have-sale="{%- unless target.compare_at_price == nil or target.compare_at_price <=  target.price or target.available != true -%}true{%endunless%}" data-text=" ${this.lang(this.sale_text, 'product_single_sale_text')}" data-sale="{{savings}}" data-type="${this.data.settings?.sale_badge_type ? this.data.settings?.sale_badge_type : 'percent'}" style="{%- unless target.compare_at_price == nil or target.compare_at_price <=  target.price or target.available != true -%} display: none;{% endunless %}">
                            ${this.lang(this.sale_text,'product_single_sale_text')}
                        </span>
                        <span class="ecom-product-single__price--badges-sold-out" {% if target.available %} style="display:none" {% endif %}>
                            ${this.lang(this.sold_text, 'product_single_sold_text')}
                        </span>
                    </div>
                    `,
                    preview: ``
                },
                badge_pecent: {
                    code: `
                    <div class="ecom-product-single__price--badges_pecent">
                        <span class="ecom-product-single__price--badges-sale-pecent" {%- if target.compare_at_price == nil or target.compare_at_price <=  target.price -%}  style="display:none" {% endif %}>
                            {%- assign savings = target.compare_at_price | minus: target.price | times: 100.0 | divided_by: target.compare_at_price | round | append: '%' | prepend: '-' -%}
                            ${this.data.settings?.sale_badge_type === 'amount'
                            ?  `
                                {%- if settings.currency_code_enabled -%}
                                    {%- assign savings = target.compare_at_price | minus: target.price | money_with_currency -%}
                                {%- else -%}
                                    {%- assign savings = target.compare_at_price | minus: target.price | money -%}
                                {%- endif -%}
                            `
                            :''}
                            {{ savings }}
                        </span>
                    </div>
                    `,
                    preview: ``
                },
                ground_price: {
                    code: `
                        {%- assign selected_available_variant = product.selected_or_first_available_variant.unit_price_measurement -%}
                        <small class="ecom-unit-price" {% if selected_available_variant == nil %}style="display: none;" {% endif %}">
                            <span class="price-item price-item--last">
                                <span class="ecom-ground-price_unit-price">{{- product.selected_or_first_available_variant.unit_price | money -}}</span>
                                ${this.data.settings?.show_unit_price_slash ? `<span class="ecom-ground-price_unit-price-separator">/</span>` : ''}
                                <span class="ecom-ground-price_unit-price-measurement">
                                {%- if selected_available_variant.reference_value >= 1 -%}
                                    {{- selected_available_variant.reference_value -}}
                                {%- endif -%}
                                {{- selected_available_variant.reference_unit | downcase -}}
                                </span>
                            </span>
                        </small>
                    `,
                    preview: `
                        <div class="ecom-skeleton-item" style="max-width: 100px; width: 100%">
                            <div class="ecom-skeleton-col-12">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-12"></div>
                                </div>
                            </div>
                        </div>
                    `
                },

                afterpay: {
                    code: `
                    ${
                        this.enable_afterpay ? `
                         <afterpay-placement class="ecom-afterpay-integrate"
                            data-show-interest-free="true"
                            ${ this.afterpay_theme !== 'none' ? `data-badge-theme="${this.afterpay_theme}"` : '' }
                            data-modal-theme="${this.modal_theme}"
                            data-locale="{{country.iso_code}}"
                            data-currency="{{shop.currency}}"
                            data-prefix=""
                            data-logo-type="${this.afterpay_logo_type}"
                            data-lockup-theme="${this.afterpay_logo_color}"
                            data-show-lower-limit="${ this.data.settings?.show_lower_limit ?? 'false' }"
                            data-show-upper-limit="${ this.data.settings?.show_upper_limit ?? 'false' }"
                            data-amount="{{product.price | divided_by: 100}}">
                        </afterpay-placement>
                    `
                            : ''
                        }
                    `,
                    preview:''
                }
            };
        },

        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'popup',
                            name: 'sale_badge_type',
                            label: this.$t('type'),
                            value: 'percent',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                default: false,
                                values: {
                                    percent: this.$t('percent'),
                                    amount: this.$t('amount_label')
                                }
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('badge_sale_text'),
                            placeholder: 'Sale {price}%',
                            value: 'Sale {price}%',
                            name: 'sale_text',
                            description: this.$t('badge_sale_off_will_replace_in_block_price'),
                        },
                        {
                            type: 'paragraph',
                            content: this.$t("elevate_your_sales_with_premium_badges_&_labels", {link: `https://apps.shopify.com/product-badges-label-design?utm_source=co_marketing&utm_medium=ecomposer&utm_campaign=inapp_settings`})
                        },
                        {
                            type: 'text',
                            label: this.$t('badge_sold_out_text'),
                            value: 'Sold out',
                            name: 'sold_text'
                        },
                        {
                            type: 'text',
                            label: `${this.$t('tax_included_text')} ${this.canUseCustomLiquidForCSR ? this.$t('live_page_only') : ''}`,
                            value: '',
                            name: 'include_taxes'
                        },
                        {
                            type: 'text',
                            label: `${this.$t('shipping_policy')} ${this.canUseCustomLiquidForCSR ? this.$t('live_page_only') : ''}`,
                            value: "",
                            name: 'shipping_policy'
                        },
                        ...(this.canUseCustomLiquidForCSR 
                            ? [{
                            type: 'toggle',
                            name: 'show_preview_taxes_and_shipping_policy',
                            label: this.$t('show_preview_taxes_and_shipping_policy'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        }] : []
                        ),
                        {
                            type: 'toggle',
                            name: 'show_groundprice',
                            label: this.$t('enable_ground_price'),
                            description: this.$t('see_detailed_guide_https_help_shopify_com_en_manual_intro_to_shopify_initial_setup_sell_in_germany_price_per_unit_to_enable_ground_price'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_unit_price_slash',
                            label: this.$t('show_unit_price_separator'),
                            description: this.$t('add_a_slash_before_the_unit_measurement_e_g_100_1pcs'),
                            options: {
                                visible(data) {
                                    return data['show_groundprice'];
                                },
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_total_price',
                            label: this.$t('enable_total_price'),
                            description: this.$t('total_price_when_customer_change_quantity_product_price_quantity'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_payment_terms',
                            label: this.$t('show_payment_terms'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_badges',
                            value: true,
                            label: this.$t('show_sale_sold_out_badge'),
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'show_sale_pecent',
                            value: true,
                            label: this.$t('show_sale_percent_badge'),
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: function(data) {
                                    return false
                                }
                            },
                        },
                        {
                            type: 'toggle',
                            name: 'show_bss_b2b_wholesale',
                            value: false,
                            label: this.$t('show_bss_b2b_wholesale'),
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            },
                        }
                    ]
                },
                {
                    group_title: this.$t('after_pay_settings'),
                    params: [
                        {
                            type: 'paragraph',
                            content: this.$t('afterpay_is_fully_integrated_with_all_of_your_favorite_stores_shop_as_usual_then_choose_afterpay_as_your_payment_method_at_checkout_to_integrate_afterpay_to_your_theme_you_can_follow_these_instruction_https_developers_afterpay_com_afterpay_online_docs_shopify_getting_started'),
                        },
                        {
                            type: 'toggle',
                            name: 'enable_afterpay',
                            label: this.$t('show_afterpay'),
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('show'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('hide'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_minimum_price'),
                            name: 'show_lower_limit',
                            description: this.$t('determines_whether_to_show_the_minimum_amount_e_g_1_00_1_000_for_products_outside_of_the_provided_minimum_maximum_threshold_n_learn_more_here_https_developers_afterpay_com_afterpay_online_docs_advanced_configuration_data_show_lower_limit'),
                            options: {
                                visible(data) {
                                    return data['enable_afterpay'];
                                },
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: 'true'
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: 'false'
                                    }
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'lower_limit',
                            label: this.$t('minimum_price'),
                            options: {
                                min: 1,
                                slider: false,
                                visible(data) {
                                    return data['enable_afterpay'];
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_maximum_price'),
                            name: 'show_upper_limit',
                            description: this.$t('determines_whether_to_show_the_lower_amount_e_g_1_00_1_000_for_products_outside_of_the_provided_minimum_maximum_threshold_n_learn_more_here_https_developers_afterpay_com_afterpay_online_docs_advanced_configuration_data_show_lower_limit'),
                            options: {
                                visible(data) {
                                    return data['enable_afterpay'];
                                },
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: 'true'
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: 'false'
                                    }
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'upper_limit',
                            label: this.$t('maximum_price'),
                            options: {
                                min: 1,
                                slider: false,
                                visible(data) {
                                    return data['enable_afterpay'];
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('logo_type'),
                            name: 'afterpay_logo_type',
                            description: this.$t('learn_more_here_https_developers_afterpay_com_afterpay_online_docs_afterpayjs_glossary_logo_type'),
                            options: {
                                type: 'dropdown',
                                preview: "title",
                                values: {
                                    badge: this.$t('badge'),
                                    lockup: this.$t('lockup'),
                                    'compact-badge': this.$t('compact_badge'),
                                },
                                visible(data) {
                                    return data['enable_afterpay'];
                                }
                            }
                        },

                        {
                            type: 'popup',
                            label: this.$t('lockup_theme'),
                            name: 'afterpay_logo_color',
                            options: {
                                type: 'dropdown',
                                visible(data) {
                                    return (
                                        data['enable_afterpay'] &&
                                        data['afterpay_logo_type'] === 'lockup'
                                    );
                                },
                                preview: "title",
                                values: {
                                    black: this.$t('black'),
                                    white: this.$t('white'),
                                    mint: this.$t('mint'),
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('afterpay_badge_theme'),
                            description: this.$t('learn_more_about_badge_theme_https_developers_afterpay_com_afterpay_online_docs_afterpayjs_glossary_badge_theme'),
                            name: 'afterpay_theme',
                            options: {
                                type: 'dropdown',
                                visible(data) {
                                    return (
                                        data['enable_afterpay'] &&
                                        data['afterpay_logo_type'] === 'badge'
                                    );
                                },
                                preview: "title",
                                values: {
                                    none: this.$t('none'),
                                    'black-on-mint': this.$t('black_on_mint'),
                                    'mint-on-black': this.$t('mint_on_black'),
                                    'white-on-black': this.$t('white_on_black'),
                                }
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('modal_themes'),
                            name: 'modal_theme',

                            options: {
                                type: 'dropdown',
                                visible(data) {
                                    return data['enable_afterpay'];
                                },
                                preview: "title",
                                values: {
                                    mint: this.$t('mint'),
                                    white: this.$t('white'),
                                }
                            }
                        }
                    ]
                }
            ];
        },

        show_badges() {
            return this.data && this.data.settings && 'show_badges' in this.data.settings
                ? this.data.settings.show_badges
                : false;
        },

        show_sale_pecent() {
            return this.data && this.data.settings && 'show_sale_pecent' in this.data.settings
                ? this.data.settings.show_sale_pecent
                : false;
        },
        show_bss_b2b_wholesale() {
            return this.data && this.data.settings && 'show_bss_b2b_wholesale' in this.data.settings
                ? this.data.settings.show_bss_b2b_wholesale
                : false;
        },

        show_groundprice() {
            return this.data && this.data.settings && 'show_groundprice' in this.data.settings
                ? this.data.settings.show_groundprice
                : false;
        },

        sale_text() {
            return this.data && this.data.settings && 'sale_text' in this.data.settings
                ? this.data.settings.sale_text
                : '';
        },
        sold_text() {
            return this.data && this.data.settings && 'sold_text' in this.data.settings
                ? this.data.settings.sold_text
                : '';
        },
        enable_afterpay() {
            return this.data?.settings?.enable_afterpay ?? false;
        },
        afterpay_theme() {
            return this.data?.settings?.afterpay_theme ?? 'none';
        },
        modal_theme() {
            return this.data?.settings?.modal_theme ?? 'white';
        },
        afterpay_logo_type() {
            return this.data?.settings?.afterpay_logo_type ?? 'badge';
        },
        afterpay_logo_color() {
            return this.data?.settings?.afterpay_logo_color ?? 'black';
        },
        css() {
            return `
                    .ecom-product-single__price-container-grid {
                        display: flex;
                    }
                    .ecom-product-single__price--sale{
                        font-size: 30px;
                        color: rgb(26, 27, 24);
                        display:inline-flex;
                    }
                    .ecom-product-single__price--regular{
                        text-decoration: line-through;
                        color: #6B7280;
                        display:inline-flex;
                    }
                    .ecom-product-single__price--badges-sale{
                        display: none;
                        color:red;
                    }
                    .ecom-product-single__price--badges-sale-pecent{
                        display: block;
                    }
                    .ecom-product-single__price-container .ecom-product-single__price--prices{
                        display:inline-flex;
                        align-items:center;
                        justify-content:center;
                        gap:10px;
                        flex-wrap: wrap;
                    }
                    .ecom-product-single__price-container {
                        display: flex;
                        flex-direction: column;
                        /* gap: 5px; */
                    }
                    .ecom-product-single-afterpay afterpay-placement{
                        margin:0;
                        padding: 0;
                    }
                `;
        },

        javascript() {
            return function () {
                let $el = this.$el;

                if(!$el) {
                    return;
                }

                let $afterpay_element = $el.querySelector(
                    'afterpay-placement.ecom-afterpay-integrate'
                );

                let $wrapper = this.$el.closest('.ecom-product-form--single');
                if ($wrapper) {
                    let selector = $wrapper.querySelector('[name="id"]');
                    if (selector) {
                        selector.dispatchEvent(new window.Event('ecomUpdate'));
                    }
                    if(this.settings.show_total_price) {
                        const quantity = $wrapper.querySelector('.ecom-product-single__quantity-input');
                        const priceWrapper = $el.querySelector('.ecom-product-single__price--sale');
                        if(!priceWrapper) return;

                        if(quantity) {
                            quantity.addEventListener('change', function() {
                                priceWrapper.innerHTML = window.EComposer.formatMoney(parseInt(priceWrapper.getAttribute('data-price')) * parseInt(this.value));
                            })
                        }

                        $wrapper.addEventListener('ecomVariantChange', function(event) {
                            if(event.detail.variant) {
                                const variant = event.detail.variant;
                                const qty = quantity ? parseInt(quantity.value) : 1;
                                priceWrapper.setAttribute('data-price', variant.price);

                                if(qty > 1) {
                                    priceWrapper.innerHTML = window.EComposer.formatMoney(variant.price * parseInt(qty));
                                }
                            }
                        })
                    }

                }
                if(this.settings.enable_afterpay) {
                    let $afterPayScript = window.document.querySelector('#ecom-after-pay-script');
                    window.afterpay_min = this.settings.lower_limit || 1;
                    if (!$afterPayScript) {
                        let script = window.document.createElement('script');
                        script.id = 'ecom-after-pay-script';
                        script.dataset.analyticsEnabled = true;

                        script.dataset.min = this.settings.lower_limit || 1;
                        script.dataset.max = this.settings.upper_limit || 1000;
                        script.src = 'https://js.afterpay.com/afterpay-1.x.js';
                        window.document.head.appendChild(script);
                    }
                    else
                    {
                        $afterPayScript.dataset.analyticsEnabled = true;

                        $afterPayScript.dataset.min = this.settings.lower_limit ?? 1;
                        $afterPayScript.dataset.max = this.settings.upper_limit ?? 1000;
                    }
                    if ($afterpay_element && this.isLive && window.jQuery) {
                        if (window.Afterpay && window.Afterpay.initProductPage) {
                            window.Afterpay.initProductPage(window.jQuery);
                        }
                    }
                }


                let sale_text = $el.querySelector('.ecom-product-single__price--badges-sale');
                if(sale_text && sale_text.dataset.haveSale == 'true'){
                    let percent = sale_text.dataset.sale;
                    let text = sale_text.dataset.text;
                    text = text.replace(/\{.*\}/g, percent);
                    sale_text.innerHTML = text;
                    sale_text.style.display = 'block';
                }
            };
        },
        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },
        default() {
            return {
