                },
                {
                    group_alias: ['text:spacing', 'box'],
                    options: {
                        group_title: this.$t('tax'),
                        group_name: 'tax',
                        selector: ' .ec-product__tax'
                    },
                    modify: {
                        remove: [
                            {
