                            },
                        ],
                        // params : {
                        //     position: 30,
                        //     fields: {
                        //         alias: 'spacing'
                        //     }
                        // }
                    }
                },
            ];
            if(this.data.settings?.show_sale_pecent) {
                style.push({
                    group_alias: ['text:spacing', 'box'],
                    options: {
                        group_title: this.$t('sale_percent_badge'),
                        group_name: 'price_pecent_badge',
                        selector: ' .ecom-product-single__price--badges-sale-pecent'
                    },
                    modify: {
