                        //         }
                        //     }
                        // ]
                    }
                },);
            }
            if(this.data?.settings?.show_groundprice) {
                style.push({
                    group_alias: 'text',
                    options:{
                        group_title: this.$t('ground_price'),
                        selector: ' .ecom-product_ground-price',
                    }
                });
            }

            return style;
        }
    }
};
