<template>
    <div ref="wrapper" class="ecom__element ecom-element__shape"
        :class="{ 'ecom-shape-line-item': shapes?.type === 'line', 'ecom-builder-structure': data.inGrid !== true }"
        :data-stopdrag="isEditingThisElement ? true : null">
        <Liquid :data="getMetaLiquid" />
        <div v-if="!shapes?.name" class="ecom-element__shape__item relative ecom-flex ecom-shape-empty">
            <div class="ecom-shape-item shape-item relative ecom-image-default ecom-shape-i" ref="shapeItem"
                @dblclick="edit" style="width: 100%;">
                <div class="item-content">
                    <div class="ec-svg-fake square-full background-black" style="background-color: #000;"><span
                            style="opacity: 0">x</span></div>
                </div>
                <component :is="shape_link !== '' ? 'a' : shape_text_tag" v-if="shape_text && shape_link !== ''"
                    class="ecom-shape-text absolute top-50 transform color-white text-center" :href="shape_link.href"
                    ref="content" :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
                    spellcheck="false" @keyup="update" @blur="handleBlur"
                    v-html="isEditingThisElement ? editingValue : shape_text">
                </component>
                <component :is="shape_text_tag ?? 'h3'" v-else
                    class="ecom-shape-text absolute top-50 transform color-white text-center" ref="content"
                    :contenteditable="!isFullScreen && isEditingThisElement ? true : null" spellcheck="false"
                    @keyup="update" @blur="handleBlur" v-html="isEditingThisElement ? editingValue : shape_text">
                </component>
            </div>
        </div>
        <div v-else class="ecom-element__shape__item relative ecom-flex">
            <div class="ecom-shape-item shape-item relative ecom-image-default ecom-shape-i" ref="shapeItem"
                @dblclick="edit" :data-width="elementWidth" style="width: 100%;">
                <div class="item-content" v-html="callShapeElement">
                </div>
                <template v-if="shapes?.type !== 'line'">
                    <component :is="shape_link !== '' ? 'a' : shape_text_tag" v-if="shape_text && shape_link !== ''"
                        ref="content" class="ecom-shape-text absolute top-50 transform color-white text-center"
                        :href="shape_link.href" :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
                        spellcheck="false" @keyup="update" @blur="handleBlur"
                        v-html="isEditingThisElement ? editingValue : shape_text">
                    </component>
                    <component :is="shape_text_tag ?? 'h3'" v-else
                        class="ecom-shape-text absolute top-50 transform color-white text-center" ref="content"
                        :contenteditable="!isFullScreen && isEditingThisElement ? true : null" spellcheck="false"
                        @keyup="update" @blur="handleBlur" :data-content="shape_text"
                        v-html="isEditingThisElement ? editingValue : shape_text">
                    </component>
                </template>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import { Element, Javascript, Liquid } from '@/mixins';

export default {
    name: 'Shape',
    presets: false,
    docs: '',
    mixins: [Element, Javascript, Liquid],
    inject: ['eventBus'],
    props: {
        data: {
            type: [Object, Array, Boolean],
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            editing: false,
            lastUpdate: 0,
            editingValue: '',
            metaLang: {},
            metaLiquid: '',
            convertedContent: '',
            elementWidth: '' as string | number,
            isBlur: false,
            resizeObserver: null as ResizeObserver | null,
            shapeWidthDesktop: 0,
            shapeWidthTablet: 0,
            shapeWidthMobile: 0
        };
    },
    computed: {
        shapes() {
            return this.data?.settings?.shapes?.shape || {};
        },
        shape_text() {
            return this.data?.settings?.shapes?.name || ' ';
        },
        shape_text_tag() {
            return this.data?.settings?.shapes?.tag_text || 'h3';
        },
        shape_link() {
            return this.data?.settings?.shapes?.url || '';
        },
        strokeStyle() {
            // Đảm bảo strokeStyle luôn tồn tại với các giá trị mặc định
            if (!this.data?.style?.strokeStyle) {
                if (!this.data.style) {
                    this.data.style = {};
                }
                this.data.style.strokeStyle = {
                    name: 'solid',
                    value: '',
                    roundedTail: false,
                    strokeThickness: 4,
                    strokeColor: '#000'
                };
            }
            return this.data?.style?.strokeStyle;
        },
        shadowStyle() {
            return this.data?.style?.image?.boxShadow;
        },
        isEditingThisElement() {
            return this.editing;
        },
        settings() {
            return [
                {
                    group_title: this.$t('shapes'),
                    group_name: 'shapes',
                    params: [
                        {
                            type: 'geometry',
                            label: '',
                            name: 'shape',
                            options: {
                                line: true,
                            },
                        },
                        {
                            type: 'text',
                            label: this.$t('shape_text'),
                            name: 'name',
                            options: {
                                placeholder: this.$t('enter_shape_text'),
                            },
                            default: 'Text default'
                        },
                        {
                            type: 'choose',
                            label: this.$t('span_class_uppercase_html_span_tag'),
                            name: 'tag_text',
                            options: {
                                chooseOne: true,
                                type: 'heading',
                                modify: {
                                }
                            },
                            activeQuickToolBar: true
                        },
                        {
                            type: 'link',
                            label: this.$t('shape_url'),
                            name: 'url',
                            options: {
                                placeholder: this.$t('enter_shape_url'),
                            },
                            activeQuickToolBar: true
                        },
                    ]
                },
            ];
        },
        css() {
            return `
            .ecom-element__shape__item {
                align-items: center;
                justify-content: center;
            }
            .ecom-element__shape,
            .ecom-element__shape__item,
            .ecom-shape-item {
                height: 100%;
            }
            .ecom-shape-item,
            .ecom-element__shape__item {
                position: relative;
            }
            .ecom-shape-item svg {
                height: 100%;
                width: 100%;
                fill: currentColor !important;
                color: #000;
            }
            .ecom-shape-item .ecom-shape-text {
                transform: translateY(-50%);
                width: 100%;
                padding: 0 15px;
                text-align: center;
                position: absolute;
                top: 50%;
                color: #fff;
            }
            .ec-line-section {
                cursor: auto;
                outline: none;
            }
            .ecom-image-default.ecom-shape-i {
                margin: 0 auto;
            }
            .ec-group-line {
                -webkit-touch-callout: none;
                -webkit-user-drag: none;
                -webkit-tap-highlight-color: transparent;
            }
            .ec-shape-line {
                touch-action: pan-x pan-y pinch-zoom;
                width: 100%;
                height: 20px;
                display: flex;
                align-items: center;
                justify-content: center;
            }
            .ec-shape-line-inner {
                transform-origin: 0 0;
            }
            .ecom-shape-item .ec-line-svg {
                display: block;
                min-height: 1px;
                min-width: 1px;
                overflow: visible;
                scale: 1;
            }
            .ecom-shape-item .item-content {
                display: flex;
                align-items: center;
                justify-content: center;
                width: 100%;
            }
            .ecom-shape-line-item .ecom-shape-item .item-content {
                width: 100%;
            }
            .ec-svg-fake {
                width: 100%;
                height: 100%;
            }
            .ec-svg-fake span {
                opacity: 0;
                visibility: hidden;
                font-size: 0;
            }
            .background-black {
                background-color: #000;
            }
            .border-r-25 {
                border-radius: 25px;
            }
            .ecom-element__shape__item,
            .ecom-shape-item .item-content,
            .ecom-shape-item svg {
                overflow: unset !important;
            }
            .ecom-shape-empty .ec-svg-fake {
                aspect-ratio: 1 / 1;
            }
            .ecom-builder-structure svg {
                max-width: 100%;
            }
            `;
        },
        javascript() {
            return function () {
                if (!this.$el) {
                    return false;
                }
                const $el = this.$el;
                //Kiểm tra xem $el có class ecom-builder-structure không?
                const builderStructure = $el.classList.contains('ecom-builder-structure') || $el.querySelector('.ecom-builder-structure');

                if (builderStructure) {
                    const $shape = $el.querySelector('.ecom-shape-item').getBoundingClientRect();
                    if ($shape) {
                        //Dựa vào getLine tìm data-desktop-width, data-tablet-width, data-mobile-width
                        let width = $shape.width;
                        width = Math.round(width);

                        //Sau đó điền data vào các attribute của shape
                        const lineSvg = $el.querySelector('.ec-line-svg');
                        if (lineSvg) {

                            const containerShape = $el.querySelector('.ecom-shape-i');
                            if (containerShape) {
                                let containerShapeWidth = containerShape.getBoundingClientRect().width;
                                containerShapeWidth = Math.round(containerShapeWidth);
                                if (containerShapeWidth < width) {
                                    width = containerShapeWidth;
                                }
                            }
                            lineSvg.setAttribute('viewBox', '0 0 ' + width + ' 1');

                            let stroke_width = 4;
                            if (lineSvg.style.height !== undefined && lineSvg.style.height !== null) {
                                stroke_width = lineSvg.style.height.replace('px', '');
                            }

                            let pathsGroupEcx = lineSvg.querySelectorAll('.ec-group-ecx');

                            pathsGroupEcx.forEach(path => {
                                if (path) {
                                    let dPath = path.getAttribute('d');
                                    if (dPath) {
                                        let pathsArrow = lineSvg.querySelectorAll('.ec-arrow');

                                        if (pathsArrow.length > 0) {
                                            dPath = 'M0,' + (stroke_width / 2) + 'L' + (width - Math.round(stroke_width / 2)) + '.96000000000004,' + (stroke_width / 2);
                                        } else {
                                            dPath = 'M0,' + (stroke_width / 2) + 'L' + (width - 1) + '.96000000000004,' + (stroke_width / 2);
                                        }

                                        let pathsArrowLeft = lineSvg.querySelectorAll('.ec-arrow-left');
                                        if (pathsArrowLeft.length > 0) {
                                            dPath = 'M' + (stroke_width / 2) + ',' + (stroke_width / 2) + 'L' + (width - Math.round(stroke_width / 2)) + '.96000000000004,' + (stroke_width / 2);
                                        }

                                        path.setAttribute('d', dPath);
                                    }
                                }
                            });

                            let Zstring = '';
                            let pathsArrow = lineSvg.querySelectorAll('.ec-arrow');
                            pathsArrow.forEach(path => {
                                if (path) {
                                    let dPath = path.getAttribute('d');
                                    if (dPath) {
                                        let arrowDArray = dPath.split(',');
                                        let arrowDArrayY = arrowDArray[arrowDArray.length - 1];
                                        if (arrowDArrayY.includes('Z')) {
                                            Zstring = 'Z';
                                        }
                                        dPath = 'M' + Math.round((width - (stroke_width / 2)) - (stroke_width * 2)) + '.96,-' + stroke_width + 'L' + (width - Math.round(stroke_width / 2)) + '.96,' + (stroke_width / 2) + 'L' + ((width - Math.round(stroke_width / 2)) - (stroke_width * 2)) + '.96,' + (stroke_width * 2) + Zstring;
                                        path.setAttribute('d', dPath);
                                    }
                                }
                            });

                            let pathsArrowLeft = lineSvg.querySelectorAll('.ec-arrow-left');
                            pathsArrowLeft.forEach(path => {
                                if (path) {
                                    let dPath = path.getAttribute('d');
                                    if (dPath) {
                                        let arrowDArray = dPath.split(',');
                                        let arrowDArrayY = arrowDArray[arrowDArray.length - 1];
                                        if (arrowDArrayY.includes('Z')) {
                                            Zstring = 'Z';
                                        }
                                        dPath = 'M' + ((stroke_width / 2) + (stroke_width * 2)) + ',-' + stroke_width + 'L' + (stroke_width / 2) + ',' + (stroke_width / 2) + 'L' + ((stroke_width / 2) + (stroke_width * 2)) + ',' + (stroke_width * 2) + Zstring;
                                        path.setAttribute('d', dPath);
                                    }
                                }
                            });

                            let pathsCircle = lineSvg.querySelectorAll('.circle-p');
                            if (pathsCircle.length > 0) {
                                pathsCircle.forEach(path => {
                                    if (path) {
                                        path.setAttribute('r', (stroke_width * 2).toString());
                                        path.setAttribute('cx', (stroke_width * 2).toString());
                                        path.setAttribute('cy', (stroke_width / 2).toString());
                                    }
                                });
                            }

                            let pathsCircleRight = lineSvg.querySelectorAll('.circle-right');
                            if (pathsCircleRight.length > 0) {
                                pathsCircleRight.forEach(path => {
                                    if (path) {
                                        path.setAttribute('cx', (width - (stroke_width * 2)).toString());
                                    }
                                });
                            }
                        }
                    }
                }
            }
        },
        shape() {
            return this.data;
        },
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.shape.id;
        },
        getMetaLiquid() {
            return this.metaLiquid;
        },
        currentScreen() {
            return this.$store.getters["builder/screen"];
        },
        callShapeElement() {

            let svg = this.shapes?.url;
            if (!svg) return '';

            let svgType = this.shapes?.type;
            // Create a temporary div to parse the SVG
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = svg;

            if (svgType === 'line') {
                if (this.currentScreen === 'desktop') {
                    this.elementWidth = this.shapeWidthDesktop;
                } else if (this.currentScreen === 'tablet') {
                    this.elementWidth = this.shapeWidthTablet;
                } else if (this.currentScreen === 'mobile') {
                    this.elementWidth = this.shapeWidthMobile;
                }

                if (this.elementWidth !== 0) {
                    const svgElement = tempDiv.querySelector('.ec-line-svg');
                    const ecShapeLine = tempDiv.querySelector('.ec-shape-line-inner');

                    if (svgElement) {

                        let width = this.elementWidth;
                        width = String(width);

                        if (width.includes('%') || width.includes('vw')) {
                            let itemShape = this.elementWidth;
                            const percentage = parseFloat(width.replace('%', ''));
                            width = (itemShape * percentage) / 100;

                        } else {
                            width = width.replace('px', '');
                            width = parseFloat(width) || 0;
                        }
                        (svgElement as HTMLElement).style.width = width + 'px';

                        svgElement.setAttribute('viewBox', "0 0 " + width + " 1");

                        let stroke_width = 4;
                        if (this.strokeStyle?.strokeThickness !== undefined && this.strokeStyle?.strokeThickness !== null) {
                            stroke_width = this.strokeStyle?.strokeThickness;
                        }

                        if (ecShapeLine) {
                            (ecShapeLine as HTMLElement).style.height = stroke_width + 'px';
                            (svgElement as HTMLElement).style.height = stroke_width + 'px';
                        }

                        let pathsStrokeWidth = svgElement.querySelectorAll('.ec-stroke-width');

                        pathsStrokeWidth.forEach(path => {
                            if (path) {
                                path.setAttribute('stroke-width', stroke_width.toString());
                            }
                        });

                        let pathsGroupEcx = svgElement.querySelectorAll('.ec-group-ecx');
                        pathsGroupEcx.forEach(path => {
                            if (path) {
                                let dPath = path.getAttribute('d');
                                if (dPath) {
                                    let pathsArrow = svgElement.querySelectorAll('.ec-arrow');
                                    if (pathsArrow.length > 0) {
                                        dPath = 'M0,' + (stroke_width / 2) + 'L' + (width - Math.round(stroke_width / 2)) + '.96000000000004,' + (stroke_width / 2);
                                    } else {
                                        dPath = 'M0,' + (stroke_width / 2) + 'L' + (width - 1) + '.96000000000004,' + (stroke_width / 2);
                                    }

                                    let pathsArrowLeft = svgElement.querySelectorAll('.ec-arrow-left');
                                    if (pathsArrowLeft.length > 0) {
                                        dPath = 'M' + (stroke_width / 2) + ',' + (stroke_width / 2) + 'L' + (width - Math.round(stroke_width / 2)) + '.96000000000004,' + (stroke_width / 2);
                                    }
                                    path.setAttribute('d', dPath);
                                    path.setAttribute('stroke', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '');
                                    path.setAttribute('fill', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '');
                                }
                            }
                        });

                        let Zstring = '';
                        let pathsArrow = svgElement.querySelectorAll('.ec-arrow');
                        pathsArrow.forEach(path => {
                            if (path) {
                                let dPath = path.getAttribute('d');
                                if (dPath) {
                                    let arrowDArray = dPath.split(',');
                                    let arrowDArrayY = arrowDArray[arrowDArray.length - 1];
                                    if (arrowDArrayY.includes('Z')) {
                                        Zstring = 'Z';
                                    }
                                    dPath = 'M' + Math.round((width - (stroke_width / 2)) - (stroke_width * 2)) + '.96,-' + stroke_width + 'L' + (width - Math.round(stroke_width / 2)) + '.96,' + (stroke_width / 2) + 'L' + ((width - Math.round(stroke_width / 2)) - (stroke_width * 2)) + '.96,' + (stroke_width * 2) + Zstring;
                                    path.setAttribute('d', dPath);
                                }
                            }
                        });

                        let pathsArrowLeft = svgElement.querySelectorAll('.ec-arrow-left');
                        pathsArrowLeft.forEach(path => {
                            if (path) {
                                let dPath = path.getAttribute('d');
                                if (dPath) {
                                    let arrowDArray = dPath.split(',');
                                    let arrowDArrayY = arrowDArray[arrowDArray.length - 1];
                                    if (arrowDArrayY.includes('Z')) {
                                        Zstring = 'Z';
                                    }
                                    dPath = 'M' + ((stroke_width / 2) + (stroke_width * 2)) + ',-' + stroke_width + 'L' + (stroke_width / 2) + ',' + (stroke_width / 2) + 'L' + ((stroke_width / 2) + (stroke_width * 2)) + ',' + (stroke_width * 2) + Zstring;
                                    path.setAttribute('d', dPath);
                                }
                            }
                        });

                        let pathsCircle = svgElement.querySelectorAll('.circle-p');
                        if (pathsCircle.length > 0) {
                            pathsCircle.forEach(path => {
                                if (path) {
                                    path.setAttribute('r', (stroke_width * 2).toString());
                                    path.setAttribute('cx', (stroke_width * 2).toString());
                                    path.setAttribute('cy', (stroke_width / 2).toString());
                                }
                            });
                        }

                        let pathsCircleRight = svgElement.querySelectorAll('.circle-right');
                        if (pathsCircleRight.length > 0) {
                            pathsCircleRight.forEach(path => {
                                if (path) {
                                    path.setAttribute('cx', (width - (stroke_width * 2)).toString());
                                }
                            });
                        }

                        if (this.strokeStyle?.value) {
                            let pathsLine = svgElement.querySelectorAll('.ec-line');
                            pathsLine.forEach(path => {
                                if (path) {
                                    if (stroke_width) {
                                        let dashArray = this.strokeStyle.value.split(',');
                                        let newDashArray_1 = dashArray[0] * stroke_width;
                                        let newDashArray_2 = dashArray[1] * stroke_width;
                                        path.setAttribute('stroke-dasharray', newDashArray_1 + ',' + newDashArray_2);
                                    } else {
                                        path.setAttribute('stroke-dasharray', this.strokeStyle.value);
                                    }
                                }
                            });
                        }

                        if (this.strokeStyle?.roundedTail) {
                            let pathsLine = svgElement.querySelectorAll('.ec-line');
                            pathsLine.forEach(path => {
                                if (path) {
                                    path.setAttribute('stroke-linecap', 'round');
                                }
                            });

                            let pathsGroupEcx = svgElement.querySelectorAll('.ec-group-ecx');
                            pathsGroupEcx.forEach(path => {
                                if (path) {
                                    let dPath = path.getAttribute('d');
                                    if (dPath) {
                                        dPath = 'M' + (stroke_width / 2) + ',' + (stroke_width / 2) + 'L' + ((width - 1) - Math.round(stroke_width / 2)) + '.96000000000004,' + (stroke_width / 2);
                                        path.setAttribute('d', dPath);
                                    }
                                }
                            });
                        }

                        let pathsLine = svgElement.querySelectorAll('g *');
                        pathsLine.forEach(path => {
                            if (path) {
                                path.setAttribute('stroke', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '#000');
                                path.setAttribute('fill', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '#000');
                            }
                        });

                    }

                    // Return the modified SVG
                    return tempDiv.innerHTML;
                }
            } else {
                const svgElementPath = tempDiv.querySelector('path');
                if (svgElementPath) {
                    let stroke_array_merge = '', new_stroke_width = '';
                    if (this.strokeStyle?.value) {
                        let stroke_array = String(this.strokeStyle.value).split(',');
                        let stroke_array_1 = stroke_array[0] * (parseInt(this.strokeStyle?.strokeThickness) / 2);
                        let stroke_array_2 = stroke_array[1] * (parseInt(this.strokeStyle?.strokeThickness) / 2);
                        stroke_array_merge = stroke_array_1 + ',' + stroke_array_2;
                    }

                    if (this.strokeStyle?.strokeThickness !== undefined && this.strokeStyle?.strokeThickness !== null) {
                        new_stroke_width = (this.strokeStyle?.strokeThickness);
                    }

                    if (new_stroke_width != '') {
                        svgElementPath.setAttribute('stroke-dasharray', stroke_array_merge);
                        svgElementPath.setAttribute('stroke', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : 'currentColor');
                        svgElementPath.setAttribute('stroke-width', new_stroke_width);
                        svgElementPath.setAttribute('vector-effect', 'non-scaling-stroke');
                        const svgWithStrokeWidth = tempDiv.querySelector('svg');
                        if (svgWithStrokeWidth) {
                            if (this.shapes?.name == 'shape-triangle') {
                                svgWithStrokeWidth.style.padding = (parseInt(new_stroke_width) + (parseInt(new_stroke_width) / 11)) + ' 0 ' + (parseInt(new_stroke_width) / 2);
                            } else {
                                svgWithStrokeWidth.style.padding = parseInt(new_stroke_width) / 2;
                            }
                        }
                    }


                    if (this.shadowStyle?.urlShadow) {
                        //Trong this.shadowStyle?.urlShadow có id ở tag filter hãy lấy giá trị id đó và gắn vào filter của svgElementPath
                        const filterId = this.shadowStyle?.urlShadow.split('id="')[1].split('"')[0];
                        svgElementPath.setAttribute('filter', 'url(#' + filterId + ')');
                        //Lấy giá trị của shadowStyle?.urlShadow và gắn vào svg của tempDiv
                        const svgElement = tempDiv.querySelector('svg');
                        if (svgElement) {
                            //append HTML giá trị của shadowStyle?.urlShadow vào svg của tempDiv
                            svgElement.innerHTML += this.shadowStyle?.urlShadow;
                        }
                    }

                    // Return the modified SVG
                    return tempDiv.innerHTML;


                } else {
                    const svgElementFake = tempDiv.querySelector('.ec-svg-fake');
                    if (svgElementFake) {
                        let borderStyle = '';
                        const shapeColor = this.data?.style?.image?.shapeColor;
                        let bgColor = '#000';
                        if (typeof shapeColor === 'object' && shapeColor !== null) {
                            // Adjust the property name as needed (e.g., .value, .color, etc.)
                            bgColor = 'var(--ecom-global-colors-' + shapeColor["global-colors"] + ')';
                        } else {
                            bgColor = shapeColor;
                        }
                        if (this.strokeStyle?.name) {
                            let strokeColor = this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '#000';
                            let strokeWidth = this.strokeStyle?.strokeThickness !== undefined && this.strokeStyle?.strokeThickness !== null ? this.strokeStyle?.strokeThickness : 4;
                            borderStyle = strokeWidth + 'px ' + this.strokeStyle.name + ' ' + strokeColor;
                            svgElementFake.style.border = borderStyle;
                        }
                        svgElementFake.style.backgroundColor = bgColor;

                        //svgElementFake.setAttribute('style', 'background-color: ' + bgColor + ';' + borderStyle);

                        if (this.elementWidth !== 0) {
                            if (this.shapes?.name == 'shape-square-full' || this.shapes?.name == 'shape-square') {
                                svgElementFake.style.aspectRatio = '1 / 1';
                            } else if (this.shapes?.name == 'shape-rectangle') {
                                svgElementFake.style.aspectRatio = '1 / 0.5';
                            }

                        }

                        if (this.shadowStyle?.cssShadow) {
                            svgElementFake.style.boxShadow = this.shadowStyle?.cssShadow;
                        }
                    }

                    let pathsCircle = tempDiv.querySelectorAll('.circle-p');
                    if (pathsCircle.length > 0) {
                        let stroke_width = 4;
                        let stroke_dasharray = '';
                        if (this.strokeStyle?.strokeThickness !== undefined && this.strokeStyle?.strokeThickness !== null) {
                            stroke_width = this.strokeStyle?.strokeThickness;
                        }
                        if (this.strokeStyle?.value) {
                            let stroke_array = String(this.strokeStyle.value).split(',');
                            stroke_dasharray = (stroke_array[0] * stroke_width) + ',' + (stroke_array[1] * stroke_width);
                        }
                        pathsCircle.forEach(path => {
                            if (path) {
                                path.setAttribute('stroke-dasharray', stroke_dasharray);
                                path.setAttribute('stroke-width', stroke_width * 2);
                                path.setAttribute('stroke', this.strokeStyle?.strokeColor ? this.strokeStyle?.strokeColor : '#000');
                            }
                        });
                    }

                    return tempDiv.innerHTML;
                }



            }

            return svg;
        },
        default() {
            return {
                settings: {
                    shapes: {
                        shape: {
                            name: "shape-square-full",
                            url: "<div class='ec-svg-fake square-full background-black ecom-image-default ecom-shape-i'><span style='opacity: 0'>x</span></div>",
                            shapeActive: "shape-square-full"
                        },
                        name: "Text default",
                        tag_text: "h3"
                    }
                }
            };
        },
        strokeTypes() {
            const types = [
                { value: 'solid', label: 'Solid' },
                { value: 'dashed', label: 'Dashed' },
            ];

            // Only add dot and dashdot options for line type shapes
            if (this.data.type === 'line') {
                types.push(
                    { value: 'dot', label: 'Dot' },
                    { value: 'dashdot', label: 'Dash Dot' }
                );
            }

            return types;
        },

    },
    watch: {
        data: {
            handler(val) {
                // Kiểm tra ref có tồn tại không trước khi sử dụng
                let width = 1161;
                if (val.inGrid === true) {
                    this.shapeWidthDesktop = val.style?.size_grid?.width_grid || width;
                    this.shapeWidthTablet = val.style?.size_grid?.width_grid__tablet || width;
                    this.shapeWidthMobile = val.style?.size_grid?.width_grid__mobile || width;
                } else {
                    if (this.$el) {
                        const $el = this.$el;
                        const $shape = $el.getBoundingClientRect();
                        if ($shape) {
                            width = $shape.width;
                            width = Math.round(width);

                            const containerShape = $el.querySelector('.ecom-shape-i');
                            if (containerShape) {
                                let containerShapeWidth = containerShape.getBoundingClientRect().width;
                                containerShapeWidth = Math.round(containerShapeWidth);
                                if (containerShapeWidth < width) {
                                    width = containerShapeWidth;
                                }
                            }
                        }

                    }
                    this.shapeWidthDesktop = width;
                    this.shapeWidthTablet = width;
                    this.shapeWidthMobile = width;
                }
            },
            deep: true,
            immediate: true
        },
        activeMe: {
            handler(val) {
                if (this.editing) {
                    this.editing = false;

                    const content = this.$refs.content as HTMLElement;
                    if (content.innerText.includes('figmeta') || content.innerHTML.includes('figmeta')) {
                        this.data.settings.shapes.name = content.innerText;
                    } else {
                        this.data.settings.shapes.name = content.innerHTML;
                    }
                }
            },
            immediate: true
        },
        isEditingThisElement(val) {
            if (val) {
                this.editingValue = this.data.settings.shapes.name;
                this.processContent();
                this.$nextTick(() => {
                    (this.$refs.content as HTMLElement).focus();
                });
            }
        },
        'data.settings.shapes.name': {
            handler() {
                this.processContent();
            },
            immediate: true
        },

        'data.settings.shapes.shape': {
            handler(val) {
                if (val?.type === 'line') {
                    // Đảm bảo strokeStyle tồn tại trước khi set thuộc tính
                    if (!this.data.style.strokeStyle) {
                        this.data.style.strokeStyle = {};
                    }
                    this.data.style.strokeStyle.strokeThickness = this.data.style.strokeStyle.strokeThickness || 4;
                }
            },
            deep: true,
            immediate: true
        }
    },
    mounted() {
    },
    methods: {
        quickToolBar() {
            return ['shapeColor', 'textColor'];
        },

        processContent() {
            const text = this.data.settings?.shapes?.name;
            if (!text) return '';

            const dom = document.createElement('div');
            dom.innerHTML = text;
            const meta_nodes = dom.querySelectorAll('span[data-meta]');

            // Reset state
            this.metaLiquid = '';
            this.metaLang = {};

            if (meta_nodes) {
                meta_nodes.forEach((el) => {
                    const rawKey = el.dataset.metaKey || '';
                    const meta_key = rawKey.replace(/[^a-zA-Z0-9_]/g, '_').replace(/^[0-9]/, '_$&') || 'meta';
                    const metafield = el.dataset.meta;
                    const meta = document.createTextNode(`{{${meta_key}}}`);

                    const metaAssign = el.dataset.metaAssign;
                    this.metaLiquid += metaAssign || `{%- assign ${meta_key} = ${metafield}-%}`;
                    this.metaLang[meta_key] = meta_key;

                    el.replaceWith(meta);
                });
            }

            this.convertedContent = dom.innerHTML;
        },
        style() {
            let style = [
                {
                    group_alias: 'image',
                    options: {
                        group_title: 'Shape',
                        selector: ' .ecom-element__shape .ecom-element__shape__item'
                    },
                    modify: {
                        remove: [
                            {
                                index: 10,
                                length: 1
                            },
                            {
                                index: 12,
                                length: 3
                            },
                            {
                                index: 14,
                                length: 3
                            },
                            {
                                index: 8,
                                length: 1
                            },
                            // Remove imageBorderRadius if shape name is not "shape-square, shape-square-full, shape-rectangle, shape-triangle"
                            ...(this.shapes?.name !== 'shape-square' && this.shapes?.name !== 'shape-square-full' && this.shapes?.name !== 'shape-rectangle' && this.shapes?.name !== 'shape-triangle' ? [{
                                index: 11,
                                length: 1
                            },
                            {
                                index: 12,
                                length: 1
                            }] : []),

                        ],
                        params: [
                            {
                                position: 0,
                                fields: [
                                    {
                                        type: 'choose',
                                        label: this.$t('alignment'),
                                        name: 'imageAlign',
                                        options: {
                                            oneline: true,
                                            responsive: true,
                                            type: 'text-align',
                                            values: ['0 auto 0 0', '0 auto', '0 0 0 auto'],
                                            visible: {
                                                keep_data: false,
                                                condition: data => data.imageWidth !== '100%'
                                            }
                                        },
                                        css: {
                                            selector: 'root .ecom-shape-item',
                                            properties: {
                                                'margin': ''
                                            },
                                        }
                                    },
                                    {
                                        type: "color",
                                        label: this.$t('shape_color'),
                                        name: "shapeColor",
                                        activeQuickToolBar: true,
                                        options: {
                                            oneline: true,
                                            global: {
                                                type: "colors"
                                            }
                                        },
                                        css: {
                                            important: true,
                                            selector: "root .ecom-shape-item svg, .ec-svg-fake",
                                            properties: {
                                                "color": "",
                                            }
                                        }
                                    },
                                    {
                                        type: "color",
                                        label: this.$t('text_color'),
                                        name: "textColor",
                                        activeQuickToolBar: true,
                                        options: {
                                            oneline: true,
                                            global: {
                                                type: "colors"
                                            }
                                        },
                                        css: {
                                            selector: " h1, h2, h3, h4, h5, h6, a",
                                            properties: {
                                                color: ""
                                            }
                                        }
                                    },
                                    {
                                        type: "choose",
                                        label: this.$t('text_align'),
                                        name: "textAlign",
                                        options: {
                                            type: "text-align",
                                            values: ["left", "center", "right"]
                                        },
                                        css: {
                                            selector: 'root .ecom-shape-text',
                                            properties: {
                                                "text-align": "",
                                            }
                                        }
                                    },
                                    {
                                        type: 'popup',
                                        label: this.$t('typography'),
                                        name: 'textTypography',
                                        activeQuickToolBar: true,
                                        options: {
                                            global: {
                                                type: 'typography'
                                            },
                                            oneline: true,
                                            responsive: true,
                                            type: 'typography'
                                        },
                                        css: {
                                            selector: " h1, h2, h3, h4, h5, h6, a",
                                        }
                                    },
                                    {
                                        name: 'padding',
                                        type: 'dimension',
                                        label: this.$t('padding'),
                                        options: {
                                            responsive: true,
                                            simple: true,
                                            units: 'default'
                                        },
                                        css: {
                                            selector: "root .ecom-shape-text",
                                            properties: {
                                                padding: ''
                                            }
                                        }
                                    },
                                    {
                                        name: 'boxShadow',
                                        type: 'geometry',
                                        label: this.$t('box_shadow'),
                                        options: {
                                            type: 'box-shadow'
                                        }
                                    },
                                ]
                            }
                        ]
                    },

                },
            ];

            return style;
        },
        edit() {
            this.editing = true;
        },
        update(e: Event) {
            //Get text content from the element
            const now = Date.now();
            if (now - this.lastUpdate > 300) {
                const target = e.target as HTMLElement;
                const newContent = target.innerText.includes('figmeta') || target.innerHTML.includes('figmeta')
                    ? target.innerText
                    : target.innerHTML;

                if (this.shape.settings.shapes.name !== newContent) {
                    this.shape.settings.shapes.name = newContent;
                    this.lastUpdate = now;
                    this.$nextTick(() => {
                        this.processContent();
                    });
                }
            }
        },
        handleBlur() {
            if (!this.isBlur) return;
            setTimeout(() => {
                this.editing = false;
            }, 200);
        }
    }
};
</script>