<template>
    <div
        class="ec-block-spacer"
        :class="{ 'ec-block-spacer--dragging': isDragging }"
        @mouseenter="handleMouseEnter"
        @mouseleave="handleMouseLeave"
    >
        <!-- Background highlight -->
        <div class="ec-block-spacer__background"></div>

        <!-- Drag handle -->
        <div class="ec-block-spacer__handle" @mousedown.stop="startDrag">
            <span class="ecom-group-gap-resizer__icon"></span>
            <!-- Value display khi drag -->
            <div v-if="isDragging" class="ec-block-spacer__value">{{ spacingValue }}px</div>
        </div>
    </div>
</template>

<script lang="ts">
export default {
    name: "BlockSpacer",
    props: {
        index: {
            type: Number,
            required: true
        },
        dragSensitivity: {
            type: Number,
            default: 0.5 // Giá trị từ 0.1 (rất chậm) đến 1 (bình thường)
        },
        dragThreshold: {
            type: Number,
            default: 5 // Số pixel cần di chuyển để bắt đầu drag
        }
    },

    emits: ["update-space", "update-space-value"],

    data() {
        return {
            spacingValue: 0,
            isDragging: false,
            isPreparing: false, // Trạng thái chuẩn bị drag
            startY: 0,
            startSpacing: 0,
            minSpacing: 0,
            maxSpacing: 1000
        };
    },
    mounted() {
        // Sync giá trị spacing từ column settings
        this.syncSpacingValue();
    },
    computed: {
        idoc() {
            try {
                return window.EComposerBuilder?.contentDocument || document;
            } catch (e) {
                return document;
            }
        },
        column() {
            return this.$parent.column;
        },
        siteSettings() {
            return this.$store.getters["settings/themeSettings"] || {};
        }
    },
    watch: {
        // Theo dõi thay đổi trong column settings để sync spacingValue
        'column.data.settings.margin-top'(newValue) {
            if (newValue && !this.isDragging && !this.isPreparing) {
                this.spacingValue = this.keepOnlyNumber(newValue);
            }
        }
    },
    methods: {
        handleMouseEnter() {
            if (!this.isDragging && !this.isPreparing) {
                this.$emit("update-space", true);
            }
        },

        handleMouseLeave() {
            if (!this.isDragging && !this.isPreparing) {
                this.$emit("update-space", false);
            }
        },

        startDrag(event) {
            event.preventDefault();

            // Chỉ chuẩn bị drag, chưa drag thực sự
            this.isPreparing = true;
            this.startY = event.clientY;

            // Lấy giá trị hiện tại từ column settings (ưu tiên) hoặc spacingValue hiện tại
            this.startSpacing = this.getCurrentSpacing();

            // Add global event listeners ngay từ khi prepare
            this.idoc.addEventListener("mousemove", this.handleDrag);
            this.idoc.addEventListener("mouseup", this.endDrag);
        },

        handleDrag(event) {
            if (!this.isPreparing && !this.isDragging) return;

            const deltaY = Math.abs(event.clientY - this.startY);

            // Nếu đang prepare và chưa vượt threshold thì return
            if (this.isPreparing && deltaY < this.dragThreshold) {
                return;
            }

            // Nếu đang prepare và đã vượt threshold thì bắt đầu drag thật
            if (this.isPreparing && deltaY >= this.dragThreshold) {
                this.isPreparing = false;
                this.isDragging = true;
                this.$emit("update-space-value", this.startSpacing);
                this.idoc.body.style.cursor = "ns-resize";
                this.idoc.body.style.userSelect = "none";
            }

            // Chỉ tính toán spacing khi đã drag thật
            if (this.isDragging) {
                const actualDeltaY = event.clientY - this.startY;
                // Áp dụng hệ số giảm tốc độ
                let newSpacing = this.startSpacing + (actualDeltaY * this.dragSensitivity);

                // Clamp value between min and max
                newSpacing = Math.max(this.minSpacing, Math.min(this.maxSpacing, newSpacing));

                this.spacingValue = Math.round(newSpacing);
                this.$emit("update-space-value", Math.round(newSpacing));
            }
        },

        endDrag() {
            const wasDragging = this.isDragging;

            // Reset trạng thái
            this.isDragging = false;
            this.isPreparing = false;

            // Remove global event listeners
            this.idoc.removeEventListener("mousemove", this.handleDrag);
            this.idoc.removeEventListener("mouseup", this.endDrag);

            // Chỉ update settings nếu thực sự đã drag
            if (wasDragging) {
                this.column.data.settings["margin-top"] = this.spacingValue + 'px';
                // Sync lại spacingValue để lần drag tiếp theo đúng
                this.syncSpacingValue();
                setTimeout(() => {
                    this.$emit("update-space", false);
                }, 100);
            } else {
                // Nếu chỉ click mà không drag thì emit ngay
                this.$emit("update-space", false);
            }

            this.idoc.body.style.cursor = "";
            this.idoc.body.style.userSelect = "";
        },

        getCurrentSpacing() {
            // Ưu tiên lấy từ column settings (giá trị đã lưu)
            if (this.column.data && this.column.data.settings && this.column.data.settings["margin-top"]) {
                return this.keepOnlyNumber(this.column.data.settings["margin-top"]);
            }
            // Nếu không có thì lấy từ spacingValue hiện tại
            if (this.spacingValue) {
                return this.spacingValue;
            }
            // Cuối cùng mới lấy từ siteSettings
            return this.keepOnlyNumber(this.siteSettings["margin-top"]) || 0;
        },

        syncSpacingValue() {
            // Đồng bộ spacingValue với giá trị đã lưu trong settings
            if (this.column.data && this.column.data.settings && this.column.data.settings["margin-top"]) {
                this.spacingValue = this.keepOnlyNumber(this.column.data.settings["margin-top"]);
            }
        },

        keepOnlyNumber(value) {
            if (value === null || value === undefined || value === "") {
                return 0;
            }

            // Convert to string and remove all non-numeric characters except decimal point
            const cleanValue = String(value).replace(/[^\d.-]/g, "");

            // Parse as float and return as integer
            const numValue = parseFloat(cleanValue);

            // Return 0 if NaN, otherwise return the integer value
            return isNaN(numValue) ? 0 : Math.round(numValue);
        }
    },

    beforeUnmount() {
        // Cleanup nếu component bị destroy khi đang drag hoặc prepare
        if (this.isDragging || this.isPreparing) {
            this.endDrag();
        }
    }
};
</script>