
export default {
    methods: {
        $t(key, data = {}) {
            const currentLocale = window.ECOM_INIT?.locale || 'en';
            let translatedString = this.i18n && this.i18n[currentLocale]
                ? this.i18n[currentLocale][key]?.replace(/\{(.*?)\}/g, (match, p1) => data[p1] || match)
                : key;
            return translatedString;
        }
    }
};
