/**
 * Collection Product CSR Mixin
 *
 * Provides client-side rendering for Collection/Product element in builder mode.
 * Uses ShopifyDataService to fetch products and renders them as HTML.
 *
 * In export mode, falls back to Liquid templates.
 */

import type { ProductData, ProductsQuery, ProductsQueryType } from '@/types/shopify.d';
import liquidMixin from './liquid';

type ConditionType = "vendor" | "type" | "collection"
interface ProductSource {
    type: ProductsQueryType;
    handle?: string;
    handles?: string[];
    limit: number;
    conditions?: ConditionType[]
}

export default {
    data() {
        return {
            // CSR products loaded from $shopifyData
            csrProducts: [] as ProductData[],
            csrLoading: false,
            // False until the first load attempt settles. Lets components tell "nothing loaded yet"
            // apart from "loaded, and there really are no products" during the initial debounce.
            csrInitialized: false,
            csrError: null as string | null,
            debounceTimer: null as any
        };
    },
    computed: {
        /**
         * Determine if CSR should be used (builder mode only)
         */
        shouldUseCSR(): boolean {
            // Only use CSR in builder mode, not when exporting
            return this.exporting !== true && !!this.$shopifyData;
        },

        /**
         * Build product source configuration from element settings
         */
        productSource(): ProductSource {
            const settings = this.data?.settings || {};
            const template = this.data?.template;
            const limit = 20; // Number(settings?.limit || 10);

            // 1. Check for Recommendations override (specific to product/cart templates)
            if ((template === 'product' || template === 'cart') && settings.show_product_by === 'recommendations') {

                // Recommendations only work when exporting, use sample data in builder
                return {
                    type: 'sample_products',
                    limit: Math.min(limit, 10)
                };
            }

            // 2. Check for explicit product source settings
            const source = settings.product_source;

            if (source === 'products' && settings.products?.length) {
                // Specific products
                // Handle objects with value property or raw strings
                const handles = settings.products
                    .map((p: any) => p?.value || p)
                    .filter((h: any) => h && typeof h === 'string');

                return {
                    type: 'products_batch',
                    handles,
                    limit
                };
            }

            if (source === 'vendor' && settings.product_vendor) {
                // Handle object with value or string
                const handle = settings.product_vendor.value || settings.product_vendor;
                if (typeof handle === 'string' && handle) {
                    return {
                        type: 'vendor_products',
                        handle,
                        limit
                    };
                }
            }

            if (source === 'type' && settings.product_type) {
                // Handle object with value or string
                const handle = settings.product_type.value || settings.product_type;
                if (typeof handle === 'string' && handle) {
                    return {
                        type: 'type_products',
                        handle,
                        limit
                    };
                }
            }

            // Default for explicit source is usually collection if not specified otherwise in 'source'
            // or if source IS 'collection'
            if (settings.collection) {
                // Collection setting might be an object with handle/value or just a string handle
                const handle = settings.collection.handle || settings.collection.value || settings.collection;

                if (typeof handle === 'string' && handle) {
                    return {
                        type: 'collection_products',
                        handle,
                        limit
                    };
                }
            }

            // 3. Fallback to sample products
            return {
                type: 'sample_products',
                limit: Math.min(limit, 10)
            };
        },

        /**
         * Cache key for watching product source changes
         */
        productSourceKey(): string {
            const source = this.productSource;
            if (source.handles) {
                // Product order is part of the picker value. Keep it in the key so
                // rearranging specific products triggers a fresh canvas render.
                return `${source.type}:${source.handles.join(',')}:${source.limit}`;
            }
            return `${source.type}:${source.handle || ''}:${source.limit}`;
        },

        // csrRenderedHtml removed as we use Liquid mixin for rendering
    },
    watch: {
        /**
         * Watch product source changes to reload products
         */
        productSourceKey: {
            immediate: true,
            handler() {
                this.debouncedLoadProducts();
            }
        },
        /**
         * Deep watch settings for changes that might not trigger computed updates immediately
         * or when specific nested properties are mutated.
         */
        "data.settings": {
            deep: true,
            handler() {
                // Force reload when settings change deeply
                this.debouncedLoadProducts();
            }
        }
    },
    methods: {
        /**
         * Load products from ShopifyDataService
         */
        async loadProducts(): Promise<void> {
            if (!this.shouldUseCSR) {
                this.csrInitialized = true;
                return;
            }

            this.csrLoading = true;
            this.csrError = null;

            try {
                const source = this.productSource;
                const query: ProductsQuery = {
                    type: source.type,
                    limit: source.limit
                };

                if (source.handle) {
                    query.handle = source.handle;
                }
                if (source.handles) {
                    query.handles = source.handles;
                }

                const products =
                    query.type !== "collection_products"
                        ? await this.$shopifyData.getProducts(query)
                        : (await this.$shopifyData.getCollection(query.handle || ""))?.products;

                this.csrProducts = products || [];
                this.$forceUpdate();
                // Check if we need to manually trigger liquid render if using the mixin
                // @ts-ignore
                if (typeof this.renderAllLiquidsClientSide === 'function') {
                    // @ts-ignore
                    this.renderAllLiquidsClientSide();
                }
            } catch (error: any) {
                this.csrError = error.message || 'Failed to load products';
                this.csrProducts = [];
            } finally {
                this.csrLoading = false;
                this.csrInitialized = true;
            }
        },

        debouncedLoadProducts() {
            const template = (this as any).data?.template;
            // Only bail out for the 'collection' template — it uses the collection context directly.
            // 'featured' and others still need to load their own products even on a collection page.
            if (this.shopifyContext?.type === 'collection' && template === 'collection') {
                this.csrInitialized = true;
                return;
            }
            if (this.debounceTimer) clearTimeout(this.debounceTimer);
            this.debounceTimer = setTimeout(() => {
                this.loadProducts();
            }, 300);
        },

        /**
         * Build Liquid context with CSR products.
         *
         * For `collection` shopify type: delegates to liquid.ts's buildLiquidContext
         * so we get the full context (shop, collection object, linklists, etc.),
         * then overwrites `products` with the CSR-fetched products.
         *
         * For other types: builds a minimal context as before.
         */
        async buildLiquidContext(): Promise<any> {
            const shopifyType = (this as any).shopifyContext?.type;
            const template = (this as any).data?.template;

            if (shopifyType === 'collection' && template === 'collection') {
                // 'collection' template: reuse liquid.ts's full buildLiquidContext
                // (collection, shop, linklists...) then override products with CSR-fetched list.
                const context = await (liquidMixin.methods as any).buildLiquidContext.call(this);

                // Override products with the CSR-fetched list (more reliable for builder)
                // @ts-ignore
                context.products = (this as any).csrProducts?.length ? (this as any).csrProducts : (context.products || []);

                return context;
            }

            // Non-collection: minimal context same as before
            const context: any = {
                request: {
                    host: window.location.host,
                    path: window.location.pathname
                }
            };

            try {
                // @ts-ignore
                let shopData = await (this as any).$shopifyData.get('shop');
                if (shopData?.status === 'success' && shopData?.data) {
                    shopData = shopData.data;
                }
                context.shop = shopData;
            } catch {}

            // @ts-ignore
            context.products = (this as any).csrProducts?.length ? (this as any).csrProducts : [];

            return context;
        },
    }
};
