<template>
    <div class="ecom-element ecom-product-single ecom-product-single__metafield">
        <div class="ecom-product-single__metafield-wrapper">
            <div
                class="ecom-product-single__metafield-container"
            >
                <div v-if="showPlaceholder" class="metafield-placeholder">
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                        <path d="M20 14.66V20a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5.34"></path>
                        <polygon points="18 2 22 6 12 16 8 16 8 12 18 2"></polygon>
                    </svg>
                    <span>{{ placeholderText }}</span>
                </div>
                <div v-else v-html="renderedLiquid" />
            </div>
        </div>
    </div>
</template>

<script>
    import { Liquid, Element } from '@/mixins';
    import { isElementMetafieldSupported } from '@/store/modules/dynamicSources';
    import {
        baseTypeOf,
        buildMetafieldLiquid,
        isListType,
        isReferenceType,
        referenceHasImage,
        wrapEmptyState
    } from '@/utils/metafieldLiquid';
    import { ensureMetaobjectScopes, hasMetaobjectScopes } from '@/utils/metaobjectScopes';

    /** Suy chế độ từ data — dùng được cả trong closure `visible` (không có `this`). */
    const readSource = (data) => data?.source ?? (data?.code ? 'custom' : 'picker');

    const rawFieldType = (data) => data?.field?.type ?? '';

    /**
     * Type GỐC của metafield đang chọn.
     *
     * `list.color` dùng chung toàn bộ option riêng của `color`, `list.date` dùng
     * chung của `date`… nên mọi điều kiện `visible` theo type đều so với type gốc.
     * Chỉ nhóm option về cách bày danh sách mới hỏi `isListMode`.
     */
    const fieldType = (data) => baseTypeOf(rawFieldType(data));
    const isListMode = (data) => isListType(rawFieldType(data));
    const isReferenceMode = (data) => isReferenceType(fieldType(data));
    const listLayout = (data) => data?.list_layout || 'inline';
    const isPickerMode = (data) => readSource(data) === 'picker';
    const isDateType = (data) => ['date', 'date_time'].includes(fieldType(data));
    const isFileType = (data) => fieldType(data) === 'file_reference';
    const isMetaobjectType = (data) => fieldType(data) === 'metaobject_reference';

    /**
     * Ba chế độ mà merchant cần được cảnh báo về loại file thật, vì chúng CHỌN
     * cách hiển thị theo loại.
     *
     * `link`/`download` cũng đọc loại file (`buildFileHref` phân nhánh theo
     * `media_type` — ảnh không có `.url`), nhưng chúng ra kết quả dùng được với
     * mọi loại nên không cần cảnh báo.
     */
    const FILE_MEDIA_MODE = (data) => isPickerMode(data) && isFileType(data)
        && ['auto', 'image', 'video'].includes(data?.file_display ?? 'auto');

    /** Có sinh thẻ img → mới có ý nghĩa cho các option về ảnh. */
    const IMAGE_MODE = (data) => isPickerMode(data) && (
        (isFileType(data) && ['auto', 'image'].includes(data?.file_display ?? 'auto'))
        || (isReferenceMode(data) && data?.ref_display === 'image')
    );

    /** Option video hiện cho cả `auto` (file có thể là video) và `video`. */
    const VIDEO_VISIBLE = (data) => isPickerMode(data) && isFileType(data)
        && ['auto', 'video'].includes(data?.file_display ?? 'auto');

    /**
     * Marker chỉ có nghĩa với layout Danh sách. Loại trừ `color` theo PageFly:
     * ô swatch đi kèm bullet trông vô lý (edge case 15).
     */
    const MARKER_VISIBLE = (data) => isPickerMode(data) && isListMode(data)
        && listLayout(data) === 'list' && fieldType(data) !== 'color';

    /** Backend query `metaobjectDefinitions(first: 50)` — đạt trần thì coi như bị cắt. */
    const METAOBJECT_FETCH_LIMIT = 50;

    /** Tag mà nhìn thấy được kể cả khi không có một chữ nào. */
    const RENDERED_MEDIA = /<(img|video|iframe|audio|svg|picture|canvas|embed|object)[>\s/]/i;

    /**
     * HTML mà SSR trả về có gì để NHÌN không — quyết định preview hay placeholder.
     *
     * Không thể chỉ hỏi `!html`: metafield ảnh, video, màu render ra markup không
     * có chữ nào mà vẫn hiện rõ trên canvas. Cũng không thể coi "có tag là có nội
     * dung": metafield rỗng vẫn để lại wrapper `<span class="...__list">` và đống
     * khoảng trắng do các dấu `{%- -%}` sinh ra.
     */
    const hasRenderedContent = (html) => {
        const out = String(html ?? '');
        if (!out.trim()) return false;
        if (RENDERED_MEDIA.test(out)) return true;
        // Swatch màu là <span> rỗng, chỉ thấy được nhờ background-color inline.
        if (out.includes('__swatch')) return true;
        return out.replace(/<[^>]*>/g, '').replace(/&nbsp;/gi, ' ').trim().length > 0;
    };

    /** Text merchant nhập đi thẳng vào HTML/Liquid nên phải escape. */
    const escapeHtml = (str) => String(str ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');

    /**
     * `defaultOn` PHẢI khớp với cách code đọc setting khi khoá còn thiếu.
     *
     * `Toggle.vue:86` (`getEnable`) không tìm được option nào khớp `undefined` nên
     * rơi về `options.default ?? false` — tức toggle vẽ OFF. Toggle khai `value: true`
     * mà không đặt `default` thì panel hiện OFF trong khi `?? true` / `!== false` coi
     * là ON: Date format hiện ra dù Show date trông như chưa bật, và trang publish thì
     * vẫn in ngày. Khoá thiếu là chuyện thường vì `fieldRelation` xoá khoá của field
     * đang ẩn, rồi merchant đổi sang metafield type khác lúc runtime.
     */
    const ON_OFF = (onLabel, offLabel, defaultOn = false) => ({
        default: defaultOn,
        values: {
            on: { label: onLabel, value: true },
            off: { label: offLabel, value: false }
        }
    });

    export default {
        name: 'shopifyMetafield',

        mixins: [Liquid, Element],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {

            /**
             * `skipClientRender` = render bằng SSR, KHÔNG bằng LiquidEngine phía client.
             *
             * Đây là điều kiện để preview trong builder đúng bằng trang publish.
             * Đường CSR (`mixins/liquid.ts`) dựng context product từ API của app, mà
             * context đó chỉ có sẵn `product.metafields.ecomposer.countdown` —
             * hardcode trong product fragment phía backend. Mọi metafield khác ra
             * chuỗi rỗng, và những thứ Liquid thật tự resolve (`.value` của
             * reference, field của metaobject, filter `metafield_tag` cho rich text)
             * thì client không có gì để resolve cả.
             *
             * SSR đẩy chính đoạn Liquid này sang storefront thật (`builder.scripts`
             * → `ShopifyCrawl`) nên Shopify render, không phải mình mô phỏng lại —
             * mọi data type đều đúng, kể cả type mình chưa từng nghĩ tới.
             *
             * Đánh đổi: mỗi lần đoạn Liquid đổi là một request crawl (đã debounce +
             * gộp 5 element/request ở `mixins/processLiquid.ts`), và Safe Mode thì
             * không có SSR — lúc đó `showPlaceholder` chịu trách nhiệm nói ra.
             *
             * `preview` để rỗng: rỗng = chưa render xong, và placeholder (luôn hiện
             * đúng tên metafield) làm luôn vai trò khung chờ. Đặt skeleton vào đây
             * thì không phân biệt được "đang tải" với "metafield rỗng" nữa, vì cả
             * hai đều là giá trị của `content.metafields`.
             */
            liquids () {
                return {
                    metafields: {
                        code: `${this.code}`,
                        skipClientRender: true,
                        preview: ''
                    }
                };
            },

            /**
             * ⚠️ `visible` của hai field dưới PHẢI là function trần, không phải
             * `{ condition, keep_data: false }`.
             *
             * `plugins/fields/mixins/relation.ts:82` mặc định `keepData = true` khi
             * `visible` là function, nên field bị ẩn vẫn giữ nguyên giá trị. Đó chính
             * là cơ chế làm yêu cầu Q1 của PO chạy được: merchant switch qua lại giữa
             * Custom Liquid và Chọn từ danh sách mà không mất `settings.code` lẫn
             * `settings.field`. Thêm `keep_data: false` vào đây sẽ xoá data của khách.
             */
            settings () {
                const data = this.data?.settings ?? {};

                /**
                 * Group chỉ xuất hiện khi bên trong còn field hiện được.
                 *
                 * `Groups.vue` KHÔNG có `visible` ở cấp group, nên phải lọc ở đây —
                 * để cứng thì metafield text sẽ hiện tiêu đề group rỗng không có gì
                 * bên dưới. Và điều kiện lấy từ chính `visible` của field chứ không
                 * khai lại theo type: khai lại là sớm muộn lệch nhau.
                 *
                 * ⚠️ `Groups.vue:85` mở group theo INDEX (`activeGroup === index`), nên
                 * group giữa xuất hiện/mất đi sẽ dịch index của group sau. Đổi metafield
                 * type lúc đang mở một group là có thể thấy group khác mở ra.
                 */
                const shown = (field) => {
                    const visible = field?.options?.visible;
                    if (typeof visible !== 'function') return true;
                    try {
                        return visible(data, this) !== false;
                    } catch (e) {
                        return true;
                    }
                };
                const group = (title, params) => (
                    params.some(shown) ? [{ group_title: title, params }] : []
                );

                return [
                    ...group(this.$t('metafield'), [
                        {
                            type: 'popup',
                            label: this.$t('metafield_source'),
                            name: 'source',
                            // Mặc định = chế độ SUY RA, không phải hằng 'picker'.
                            //
                            // `defaultValues` (utils/helpers.ts:588) ghi `value` khai báo vào
                            // mọi key còn thiếu, và `firstinit` bị xoá trước khi lưu
                            // (helpers.ts:1666) nên nó chạy lại mỗi lần mở page cũ. Để hằng
                            // 'picker' ở đây là ghi `source: 'picker'` vào element cũ chỉ có
                            // `settings.code` → element chuyển sang chế độ picker chưa chọn gì
                            // → trang đã publish MẤT nội dung. Bám theo `readSource` thì giá
                            // trị ghi vào luôn khớp với chế độ element đang thực sự chạy.
                            value: this.source,
                            options: {
                                type: 'dropdown',
                                // Không thêm entry "Default" — element luôn ở một trong hai chế độ.
                                default: false,
                                values: {
                                    picker: this.$t('select_from_list'),
                                    custom: this.$t('custom_liquid')
                                }
                            }
                        },
                        {
                            type: 'metafield',
                            label: this.$t('select_metafield'),
                            name: 'field',
                            options: {
                                owner: 'product',
                                visible: function (data) {
                                    return readSource(data) === 'picker';
                                }
                            }
                        },
                        // ── Metaobject: definition suy ra từ metafield, chỉ chọn field ──
                        {
                            // ĐƯỜNG RƠI, không phải bước bình thường.
                            //
                            // Shopify đã ghi metafield trỏ tới metaobject definition nào
                            // trong `validations`, nên bình thường ô này ẩn. Chỉ hiện khi
                            // suy không ra: definitions chưa nạp xong, hoặc metafield
                            // không giới hạn về một definition duy nhất. Bỏ hẳn ô này thì
                            // những ca đó thành bế tắc, không có cách nào cấu hình.
                            type: 'popup',
                            label: this.$t('metaobject_definition'),
                            name: 'mo_definition',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: this.metaobjectDefinitionValues,
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !this.derivedMetaobjectDefinition
                            }
                        },
                        {
                            type: 'paragraph',
                            name: 'mo_limit_notice',
                            content: this.$t('showing_the_first_n_metaobject_definitions', { n: METAOBJECT_FETCH_LIMIT }),
                            options: {
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !this.derivedMetaobjectDefinition
                                    && this.metaobjectDefinitions.length >= METAOBJECT_FETCH_LIMIT
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('metaobject_field'),
                            name: 'mo_field',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: this.metaobjectFieldValues,
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !!this.metaobjectDefinition
                            }
                        },
                        {
                            // Không có definition thì dropdown field không có gì để liệt
                            // kê nên bị ẩn. Ẩn im lặng là chỗ tester báo "option biến
                            // mất" (`86eyuvu9j`) — nói ra thì merchant biết phải làm gì.
                            type: 'paragraph',
                            name: 'mo_need_definition_notice',
                            content: this.$t('pick_the_metaobject_definition_first_to_see_its_fields'),
                            options: {
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !this.metaobjectDefinition
                            }
                        },
                        {
                            type: 'paragraph',
                            name: 'mo_empty_notice',
                            content: '**' + this.$t('no_renderable_field_in_this_metaobject') + '**',
                            options: {
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !!this.metaobjectDefinition
                                    && Object.keys(this.metafieldFieldValuesFor(this.metaobjectDefinition)).length === 0
                            }
                        },
                        {
                            // Cấp 2: chỉ hiện khi field vừa chọn lại là một metaobject khác.
                            type: 'popup',
                            label: this.$t('nested_metaobject_field'),
                            name: 'mo_field_2',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: this.metaobjectNestedFieldValues,
                                visible: (data) => isPickerMode(data) && isMetaobjectType(data)
                                    && !!this.nestedDefinitionTypeFor(data)
                            }
                        },
                        {
                            type: 'textarea',
                            label: this.$t('metafield_namespace_and_key'),
                            name: 'code',
                            value: '{{ product.metafields.ecomposer.countdown }}',
                            options: {
                                toolbar: false,
                                height: 350,
                                editor: true,
                                language: 'liquid',
                                visible: function (data) {
                                    return readSource(data) === 'custom';
                                }
                            },
                            placeholder: '{{ product.metafields.ecomposer.countdown }}',
                        }
                    ]),
                    ...group(this.$t('display'), [
                        {
                            type: 'text',
                            label: this.$t('true_value'),
                            name: 'true_text',
                            value: this.$t('yes'),
                            options: {
                                visible: (data) => isPickerMode(data) && fieldType(data) === 'boolean'
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('false_value'),
                            name: 'false_text',
                            value: this.$t('no'),
                            options: {
                                visible: (data) => isPickerMode(data) && fieldType(data) === 'boolean'
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_date'),
                            name: 'show_date',
                            value: true,
                            options: {
                                ...ON_OFF(this.$t('yes'), this.$t('no'), true),
                                visible: (data) => isPickerMode(data) && isDateType(data)
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('date_format'),
                            name: 'date_format',
                            value: '%d/%m/%Y',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: {
                                    '%d/%m/%Y': '31/12/2026',
                                    '%m/%d/%Y': '12/31/2026',
                                    '%Y-%m-%d': '2026-12-31',
                                    '%B %d, %Y': 'December 31, 2026',
                                    '%d %B %Y': '31 December 2026'
                                },
                                visible: (data) => isPickerMode(data) && isDateType(data) && (data?.show_date ?? true)
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_time'),
                            name: 'show_time',
                            value: false,
                            options: {
                                ...ON_OFF(this.$t('yes'), this.$t('no')),
                                visible: (data) => isPickerMode(data) && isDateType(data)
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('time_format'),
                            name: 'time_format',
                            value: '%H:%M',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: {
                                    '%H:%M': '23:59',
                                    '%I:%M %p': '11:59 PM'
                                },
                                visible: (data) => isPickerMode(data) && isDateType(data) && data?.show_time === true
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_time_zone'),
                            name: 'show_time_zone',
                            value: false,
                            options: {
                                ...ON_OFF(this.$t('yes'), this.$t('no')),
                                // Múi giờ chỉ bổ nghĩa cho một mốc thời gian. Tắt cả ngày
                                // lẫn giờ mà bật cái này thì trang chỉ in "EDT" trơ.
                                // `?? true` vì `show_date` mặc định bật, khớp với
                                // `ON_OFF(..., true)` và với cách `liquidOptions` đọc.
                                visible: (data) => isPickerMode(data) && isDateType(data)
                                    && ((data?.show_date ?? true) || data?.show_time === true)
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('rating_style'),
                            name: 'rating_style',
                            value: 'stars',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: {
                                    stars: this.$t('stars'),
                                    number: this.$t('number'),
                                    both: this.$t('both')
                                },
                                visible: (data) => isPickerMode(data) && fieldType(data) === 'rating'
                            }
                        },

                        {
                            type: 'popup',
                            label: this.$t('display_as'),
                            name: 'file_display',
                            // `auto` là mặc định vì nhóm Media của Shopify (File /
                            // Image / Video) dùng CHUNG type `file_reference` — merchant
                            // chọn metafield Video thì phải ra player, không phải link
                            // tải về. Data cũ đã ghi 'image' nên không bị đổi hành vi.
                            value: 'auto',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: {
                                    auto: this.$t('auto'),
                                    image: this.$t('image'),
                                    video: this.$t('video'),
                                    link: this.$t('link'),
                                    // KHÔNG gọi là "Download button": thuộc tính
                                    // `download` bị bỏ qua với URL khác origin, mà file
                                    // Shopify luôn ở cdn.shopify.com. Nó là một button
                                    // mở file, không phải button tải về.
                                    download: this.$t('button')
                                },
                                visible: (data) => isPickerMode(data) && isFileType(data)
                            }
                        },
                        {
                            // Merchant KHÔNG thể biết trước file là ảnh, video hay file
                            // thường: Shopify gộp cả ba vào một type và definition không
                            // nói ra, nên badge trong picker chỉ ghi "File". Không nói rõ
                            // thì họ chọn chế độ cố định rồi thấy ra link tải về mà không
                            // hiểu vì sao.
                            type: 'paragraph',
                            name: 'file_type_notice',
                            content: this.$t('shopify_stores_file_image_and_video_as_one_metafield_type'),
                            options: {
                                visible: FILE_MEDIA_MODE
                            }
                        },
                        {
                            type: 'paragraph',
                            name: 'file_fallback_notice',
                            content: '**' + this.$t('if_the_uploaded_file_is_a_different_kind_this_mode_falls_back_to_a_download_link') + '**',
                            options: {
                                // Chỉ cảnh báo ở chế độ CỐ ĐỊNH — `auto` không có gì để rơi.
                                visible: (data) => FILE_MEDIA_MODE(data)
                                    && ['image', 'video'].includes(data?.file_display ?? 'auto')
                            }
                        },
                        {
                            // Chữ của LINK. Button có field riêng bên dưới — nhãn button
                            // và chữ trong câu là hai loại copy khác nhau ("Size chart
                            // (PDF)" so với "Tải về"), gộp một key thì đổi chế độ là
                            // copy của chế độ kia tự nhảy sang.
                            type: 'text',
                            label: this.$t('link_text'),
                            name: 'file_link_text',
                            description: this.$t('leave_blank_to_use_the_file_name'),
                            options: {
                                // Auto cũng rơi về nhánh link khi file là PDF/doc, nên
                                // merchant phải đặt được chữ ở đó, không chỉ ở Link.
                                visible: (data) => isPickerMode(data) && isFileType(data)
                                    && ['auto', 'link'].includes(data?.file_display ?? 'auto')
                            }
                        },
                        {
                            type: 'text',
                            label: this.$t('button_text'),
                            name: 'file_button_text',
                            description: this.$t('leave_blank_to_use_the_file_name'),
                            options: {
                                visible: (data) => isPickerMode(data) && isFileType(data)
                                    && data?.file_display === 'download'
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_controls'),
                            name: 'video_controls',
