import { Module } from 'vuex';
import { $t } from '@/plugins/i18n';
import { trackUpgradeEvent, UPGRADE_EVENTS } from '@/utils/upgradeTracking';

// ── AI Credit Tiers (must match BuyCustomPlan.jsx / OneTimePurchaseController.php) ──
export const AI_CREDIT_TIERS = [
    { tier: 0, credits: 0, price: 0, name: '' },
    { tier: 1, credits: 500, price: 9, name: 'Starter Pack' },
    { tier: 2, credits: 1500, price: 19, name: 'Essential Pack' },
    { tier: 4, credits: 5000, price: 49, name: 'Growth Pack' },
    { tier: 5, credits: 10000, price: 99, name: 'Professional' },
];

// ── Types ──────────────────────────────────────────────────────────────

export interface UpgradeRecommendedPlan {
    plan_id: number;
    name: string;
    price: string;
    interval: string;
    features: string[];
}

export interface UpgradeCurrentPlan {
    id: number;
    name: string;
    tier: string;
    max_limit: number | null;
    limit: number | null;
}

export interface AvailablePlan {
    tier: string;
    name: string;
    monthly: { plan_id: number; price: number };
    annual: { plan_id: number; price: number; monthly_equivalent: number } | null;
    permissions: Record<string, any>;
    features: string[];
}

export interface DiscountInfo {
    code: string;
    name: string;
    type: 'amount' | 'percent' | 'trial';
    value: number;
    interval: number | null;
}

/**
 * Promo hint resolved from a real Discount record (referenced by
 * admin/pricing.json → builder_promo). All fields derive from the discount:
 * expires_at = discount end date, plan_types mirrors discount.plan_type
 * (e.g. ['all'] | ['monthly'] | ['annual', 'pro_monthly']).
 */
export interface BuilderPromo {
    code: string;
    text: string | null;
    expires_at: string | null;
    type?: 'percent' | 'amount' | 'trial' | string;
    value?: number;
    /** Billing cycles the discount repeats for (0 = one-time) */
    interval?: number;
    plan_types?: string[];
}

// Feature keys that open the popup in AI-credits mode
const CREDIT_FEATURE_KEYS = ['ai_credits', 'ai_tokens', 'ai_image_tokens'];

// Feature keys that represent numeric quota limits (auto-detected as quota triggers)
const QUOTA_FEATURE_KEYS = [
    'max_limit', 'limit', 'pages', 'templates', 'ai_credits', 'ai_tokens',
    'ai_image_tokens', 'drafts', 'presets', 'lead_contact_limit',
    'post', 'blog_limit', 'ab_testing',
];

export interface UpgradePopupPayload {
    /** Permission key that triggered the popup, e.g. 'max_limit', 'ai_credits' */
    feature_key: string;
    /** Specific page type when feature_key='pages' (e.g. 'block', 'popup') */
    page_type?: string;
    /** Where in the app the popup was triggered, e.g. 'publish', 'ai_assistant', 'template' */
    source_location?: string;
    /** Optional custom title override */
    title?: string;
    /** Optional custom message override */
    message?: string;
}

/** Which billing flow the popup is showing */
export type UpgradeMode = 'plan' | 'credits';

export interface UpgradeState {
    show: boolean;
    loading: boolean;
    mode: UpgradeMode;
    /** Auto-derived: 'quota' or 'feature' — kept for analytics backward compat */
    trigger_type: string;
    feature_key: string;
    source_location: string;
    title: string;
    message: string;
    current_plan: UpgradeCurrentPlan | null;
    /** Backend-generated feature descriptions for the current plan (used in current-plan card) */
    current_plan_features: string[];
    recommended_plan: UpgradeRecommendedPlan | null;
    billing_url: string | null;

    // Mode 1: Plan Upgrade (recurring)
    available_plans: AvailablePlan[];
    recommended_tier: string | null;
    selected_tier: string | null;
    billing_cycle: 'monthly' | 'annual';

    // Enhanced: discount
    discount_code_input: string;
    discount_loading: boolean;
    discount: DiscountInfo | null;
    discount_error: string;
    discount_plan: any | null;
    /** Admin-configured promo hint (pricing.json → builder_promo), null = hidden */
    promo: BuilderPromo | null;

    // Add-ons (matching CheckoutModal)
    buy_blog: boolean;
    range_value: number; // extra publishable pages (Pro plan only, 0-100)
    active_addon: 'blog' | 'pages' | null;

    // Mode 2: AI Credits (one-time)
    selected_credit_tier: number; // index into AI_CREDIT_TIERS (0 = no purchase)
    pending_ai_credit_checkout: boolean;
    pending_ai_credit_checkout_snapshot: Record<string, any> | null;
    pending_ai_credit_checkout_started_at: number;

    /** Cache the API response to avoid re-fetching */
    _cachedData: any | null;
}

const BLOG_PRICE = 39;

/**
 * Auto-generate contextual message based on feature_key.
 * Quota features get limit-specific messages; feature gates get generic upgrade messages.
 */
function buildAutoMessage(featureKey: string, isQuota: boolean, data: any, globalMaxLimit: number, planName: string, pageType?: string): string {
    if (!isQuota) {
        return $t('this_feature_is_available_on_higher_plans') || 'This feature is available on higher plans.';
    }

    // Quota-specific messages
    if (featureKey === 'limit') {
        const publishLimit = data?.current_plan?.limit ?? globalMaxLimit;
        return $t('you_have_reached_the_publish_limit', {
            limit: publishLimit,
        }) || `You have reached the limit of ${publishLimit} published page(s) on your current plan. Upgrade to publish more page(s).`;
    }

    if (featureKey === 'pages') {
        const pType = pageType || data?.page_type || '';
        const pageKey = pType.toLowerCase().replace(' ', '_');
        const pageLabel = pageKey === 'block' ? ($t('global_blocks') || 'Global Blocks') : ($t(pageKey) || pType);
        return $t('please_notice_that_you_cannot_publish', {
            page: pageLabel,
        }) || `${pageLabel} is not available on your current plan. Upgrade to unlock this page type.`;
    }

    if (featureKey === 'max_limit') {
        const maxLimit = data?.current_plan?.max_limit ?? globalMaxLimit;
        return $t('you_have_reached_the_limit_of_pages', {
            limit: maxLimit,
        }) || `You have reached the limit of ${maxLimit} pages (published and draft) for your current plan. Upgrade to create more pages.`;
    }

    if (featureKey === 'drafts') {
        return $t('you_have_reached_the_drafts_limit') || "You've reached your plan's history/revision limit. Upgrade to save more drafts and revisions.";
    }

    if (featureKey === 'lead_contact_limit') {
        const limit = data?.current_plan?.lead_contact_limit ?? globalMaxLimit;
        return $t('you_have_reached_the_lead_contact_limit', {
            limit,
        }) || `You have reached the limit of ${limit} lead/contact submissions on your current plan. Upgrade to collect more leads and contacts.`;
    }

    // Generic quota message for other numeric limits
    return $t('you_have_reached_the_limit_of_pages', {
        limit: data?.current_plan?.max_limit ?? globalMaxLimit,
    }) || `You have reached the limit on your current plan. Upgrade for more.`;
}

const defaultState = (): UpgradeState => ({
    show: false,
    loading: false,
    mode: 'plan',
    trigger_type: '',
    feature_key: '',
    source_location: '',
    title: '',
    message: '',
    current_plan: null,
    current_plan_features: [],
    recommended_plan: null,
    billing_url: null,

    available_plans: [],
    recommended_tier: null,
    selected_tier: null,
    billing_cycle: 'annual',

    discount_code_input: '',
    discount_loading: false,
    discount: null,
    discount_error: '',
    discount_plan: null,
    promo: null,

    buy_blog: false,
    range_value: 0,
    active_addon: null,

    selected_credit_tier: 0,
    pending_ai_credit_checkout: false,
    pending_ai_credit_checkout_snapshot: null,
    pending_ai_credit_checkout_started_at: 0,

    _cachedData: null,
});

const module: Module<UpgradeState, any> = {
    namespaced: true,

    state: defaultState(),

    getters: {
        isVisible(state): boolean {
            return state.show;
        },
        /** Current popup mode: 'plan' for recurring upgrades, 'credits' for one-time AI purchases */
        popupMode(state): UpgradeMode {
            return state.mode;
        },
        isLoading(state): boolean {
            return state.loading;
        },
        currentPlan(state): UpgradeCurrentPlan | null {
            return state.current_plan;
        },
        currentPlanFeatures(state): string[] {
            return state.current_plan_features;
        },
        recommendedPlan(state): UpgradeRecommendedPlan | null {
            return state.recommended_plan;
        },
        billingUrl(state): string | null {
            return state.billing_url;
        },
        popupTitle(state): string {
            return state.title;
        },
        popupMessage(state): string {
            return state.message;
        },
        availablePlans(state): AvailablePlan[] {
            return state.available_plans;
        },
        selectedPlan(state): AvailablePlan | null {
            if (!state.selected_tier) return null;
            return state.available_plans.find(p => p.tier === state.selected_tier) || null;
        },
        selectedPlanPrice(state, getters): number {
            const plan = getters.selectedPlan as AvailablePlan | null;
            if (!plan) return 0;
            if (state.billing_cycle === 'annual' && plan.annual) {
                return plan.annual.price;
            }
            return plan.monthly.price;
        },
        selectedPlanMonthlyPrice(state, getters): number {
            const plan = getters.selectedPlan as AvailablePlan | null;
            if (!plan) return 0;
            if (state.billing_cycle === 'annual' && plan.annual) {
                return plan.annual.monthly_equivalent;
            }
            return plan.monthly.price;
        },
        selectedPlanId(state, getters): number | null {
            const plan = getters.selectedPlan as AvailablePlan | null;
            if (!plan) return null;
            if (state.billing_cycle === 'annual' && plan.annual) {
                return plan.annual.plan_id;
            }
            return plan.monthly.plan_id;
        },
        discountedPrice(state, getters): number | null {
            if (!state.discount) return null;
            const basePrice = getters.totalPrice as number;
            if (state.discount.type === 'percent') {
                return Math.round((basePrice * (1 - state.discount.value / 100)) * 100) / 100;
            }
            if (state.discount.type === 'amount') {
                return Math.max(0, basePrice - state.discount.value);
            }
            // trial → no price change, just trial days
            return basePrice;
        },
        billingCycle(state): string {
            return state.billing_cycle;
        },
        discountInfo(state): DiscountInfo | null {
            return state.discount;
        },
        isDiscountLoading(state): boolean {
            return state.discount_loading;
        },
        discountError(state): string {
            return state.discount_error;
        },
        promo(state): BuilderPromo | null {
            const promo = state.promo;
            if (!promo || !promo.code) return null;
            // Hide client-side if it expired while the builder session was open
            if (promo.expires_at && new Date(promo.expires_at).getTime() <= Date.now()) return null;
            // NOTE: promo.plan_types is intentionally NOT checked against the selected
            // billing cycle yet — the hint shows for all cycles for now.
            return promo;
        },
        // Add-on getters
        buyBlog(state): boolean {
            return state.buy_blog;
        },
        rangeValue(state): number {
            return state.range_value;
        },
        blogPrice(): number {
            return BLOG_PRICE;
        },
        /** Is the selected plan a Pro tier (supports extra pages)? Checks tier name + plan IDs 4,5 */
        isProPlan(state, getters): boolean {
            const plan = getters.selectedPlan as AvailablePlan | null;
            if (!plan) return false;
            // Primary: check tier name from API
            if (plan.tier === 'pro') return true;
            // Fallback: check plan IDs
            const planId = state.billing_cycle === 'annual' && plan.annual
                ? plan.annual.plan_id
                : plan.monthly.plan_id;
            return [4, 5].includes(planId);
        },
        /** Is the selected plan a Premium tier (ultimate plan, no add-ons needed)? */
        isPremiumPlan(state, getters): boolean {
            const plan = getters.selectedPlan as AvailablePlan | null;
            if (!plan) return false;
            if (plan.tier === 'premium') return true;
            const planId = state.billing_cycle === 'annual' && plan.annual
                ? plan.annual.plan_id
                : plan.monthly.plan_id;
            return [6, 7].includes(planId);
        },
        /** Blog add-on price based on billing cycle */
        addOnBlogPrice(state): number {
            if (!state.buy_blog) return 0;
            return state.billing_cycle === 'annual' ? BLOG_PRICE * 10 : BLOG_PRICE;
        },
        /** Extra pages add-on price based on billing cycle ($0.8/page) */
        addOnExtraPrice(state): number {
            if (state.range_value <= 0) return 0;
            const perPage = state.billing_cycle === 'annual' ? state.range_value * 10 : state.range_value;
            return Number((perPage * 0.8).toFixed(1));
        },
        /** Total price = plan + add-ons (before discount) */
        totalPrice(state, getters): number {
            const planPrice = getters.selectedPlanPrice as number;
            return planPrice + (getters.addOnBlogPrice as number) + (getters.addOnExtraPrice as number);
        },
        /** Which add-on accordion is expanded */
        activeAddon(state): 'blog' | 'pages' | null {
            return state.active_addon;
        },

        // ── Mode 2: AI Credits getters ──

        /** Current selected credit tier index (0 = no purchase) */
        selectedCreditTierIndex(state): number {
            return state.selected_credit_tier;
        },
        /** The AI_CREDIT_TIERS entry for the selected tier */
        selectedCreditPack(state) {
            return AI_CREDIT_TIERS[state.selected_credit_tier] || AI_CREDIT_TIERS[0];
        },
        /** Total price for AI credits (one-time) */
        creditTotal(state): number {
            const tier = AI_CREDIT_TIERS[state.selected_credit_tier];
            return tier?.price || 0;
        },
        /** All AI credit tiers (for slider rendering) */
        allCreditTiers(): typeof AI_CREDIT_TIERS {
            return AI_CREDIT_TIERS;
        },
        pendingAiCreditCheckout(state): boolean {
            return state.pending_ai_credit_checkout;
        },
        /** Only the 2 nearest upgrade plans for compact display */
        nearestTwoPlans(state): AvailablePlan[] {
            return (state.available_plans || []).slice(0, 2);
        },
    },

    mutations: {
        setShow(state, show: boolean) {
            state.show = show;
        },
        setLoading(state, loading: boolean) {
            state.loading = loading;
        },
        setPopupData(state, payload: Partial<UpgradeState>) {
            Object.assign(state, payload);
        },
        reset(state) {
            Object.assign(state, defaultState());
        },
        setCachedData(state, data: any) {
            state._cachedData = data;
        },
        setSelectedTier(state, tier: string) {
            state.selected_tier = tier;
            // Clear discount when changing plan
            state.discount = null;
            state.discount_error = '';
            state.discount_plan = null;
            // Reset add-ons when switching to premium (no add-ons needed)
            if (tier === 'premium') {
                state.buy_blog = false;
                state.range_value = 0;
            }
        },
        setBillingCycle(state, cycle: 'monthly' | 'annual') {
            state.billing_cycle = cycle;
            // Clear discount when changing cycle
            state.discount = null;
            state.discount_error = '';
            state.discount_plan = null;
        },
        setDiscountCodeInput(state, code: string) {
            state.discount_code_input = code;
        },
        setDiscountLoading(state, loading: boolean) {
            state.discount_loading = loading;
        },
        setDiscount(state, payload: { discount: DiscountInfo | null; plan?: any }) {
            state.discount = payload.discount;
            state.discount_plan = payload.plan || null;
            state.discount_error = '';
        },
        setDiscountError(state, error: string) {
            state.discount_error = error;
            state.discount = null;
            state.discount_plan = null;
        },
        clearDiscount(state) {
            state.discount = null;
            state.discount_error = '';
            state.discount_plan = null;
            state.discount_code_input = '';
        },
        setBuyBlog(state, value: boolean) {
            state.buy_blog = value;
        },
        setRangeValue(state, value: number) {
            state.range_value = value;
        },
        setMode(state, mode: UpgradeMode) {
            state.mode = mode;
        },
        setActiveAddon(state, addon: 'blog' | 'pages' | null) {
            state.active_addon = addon;
        },
        setSelectedCreditTier(state, index: number) {
            state.selected_credit_tier = Math.max(0, Math.min(index, AI_CREDIT_TIERS.length - 1));
        },
        setPendingAiCreditCheckout(state, payload: { pending: boolean; snapshot?: Record<string, any> | null }) {
            state.pending_ai_credit_checkout = !!payload.pending;
            state.pending_ai_credit_checkout_snapshot = payload.pending ? (payload.snapshot || null) : null;
            state.pending_ai_credit_checkout_started_at = payload.pending ? Date.now() : 0;
        },
    },

    actions: {
        markAiCreditCheckoutPending({ commit, rootState }) {
            const credits = rootState?.ai?.aiTokens?.credits || {};
            commit('setPendingAiCreditCheckout', {
                pending: true,
                snapshot: {
                    used: credits.used,
                    max: credits.max,
                    plan_used: credits.plan_used,
                    plan_max: credits.plan_max,
                    custom_used: credits.custom_used,
                    custom_max: credits.custom_max,
                },
            });
        },
        clearAiCreditCheckoutPending({ commit }) {
            commit('setPendingAiCreditCheckout', { pending: false });
        },
        /**
         * Main entry point: show the upgrade popup.
         * Fetches recommendation data from API (cached), then displays popup.
         */
        async showUpgradePopup({ commit, state, dispatch, rootGetters }, payload: UpgradePopupPayload) {
            // Auto-detect mode based on feature_key
            const isCreditsMode = CREDIT_FEATURE_KEYS.includes(payload.feature_key);
            const mode: UpgradeMode = isCreditsMode ? 'credits' : 'plan';

            // Auto-derive trigger_type from feature_key (for analytics backward compat)
            const isQuota = QUOTA_FEATURE_KEYS.includes(payload.feature_key);
            const triggerType = isQuota ? 'quota' : 'feature';

            // Get actual limit from global store (most reliable source)
            const globalMaxLimit = rootGetters['global/getPermission']('max_limit', 10);
            const globalUser = rootGetters['global/user'];
            const globalPlanName = globalUser?.plan?.name || 'Free';

            const sourceLocation = payload.source_location || '';
            // Caller truyền message: '' một cách có chủ đích => không tự sinh message
            // (vd. static upgrade card ở sidebar: upsell chứ không phải cảnh báo chạm giới hạn)
            const hasExplicitMessage = Object.prototype.hasOwnProperty.call(payload, 'message');

            commit('setLoading', true);
            commit('setPopupData', {
                show: true,
                mode,
                trigger_type: triggerType,
                feature_key: payload.feature_key,
                source_location: sourceLocation,
            });

            // Credits mode: minimal setup, no plan fetch needed
            if (isCreditsMode) {
                const title = payload.title || $t('buy_extra_ai_credits') || 'Buy Extra AI Credits';
                const message = payload.message || $t('you_have_run_out_of_ai_credits') || 'You have run out of AI credits.';
                commit('setPopupData', { title, message });
                commit('setSelectedCreditTier', 1); // Pre-select first tier
                commit('setLoading', false);

                // Track impression
                trackUpgradeEvent({
                    event_type: UPGRADE_EVENTS.IMPRESSION,
                    trigger_type: triggerType,
                    feature_key: payload.feature_key,
                    source_location: sourceLocation,
                    popup_mode: mode,
                });
                return;
            }

            // Plan mode: auto-expand relevant add-on
            if (payload.feature_key === 'blog_limit' || payload.feature_key === 'post') {
                commit('setActiveAddon', 'blog');
            } else if (payload.feature_key === 'max_limit' || payload.feature_key === 'limit') {
                commit('setActiveAddon', 'pages');
            }

            try {
                // Invalidate cache if feature_key or page_type changed (different context = different features/plans)
                const cacheKey = `${payload.feature_key || ''}:${payload.page_type || ''}`;
                const cachedKey = state._cachedData?._cacheKey || '';
                let data = state._cachedData;
                if (!data || cachedKey !== cacheKey) {
                    data = await dispatch('fetchRecommendation', { featureKey: payload.feature_key || '', pageType: payload.page_type || '' });
                }

                if (!data || (!data.recommended_plan && (!data.available_plans || data.available_plans.length === 0))) {
                    // No plans available — show fallback popup
                    const title = payload.title || $t('upgrade_plan');
                    const planName = data?.current_plan?.name || globalPlanName;
                    let message = payload.message || '';

                    if (!message && !hasExplicitMessage) {
                        message = buildAutoMessage(payload.feature_key, isQuota, data, globalMaxLimit, planName, payload.page_type);
                    }

                    commit('setPopupData', {
                        title,
                        message,
                        current_plan: data?.current_plan || null,
                        current_plan_features: data?.current_plan_features || [],
                        billing_url: data?.billing_url || (window as any).ECOM_INIT?.pricing_url || null,
                        available_plans: [],
                        recommended_tier: null,
                        selected_tier: null,
                        promo: data?.promo || null,
                    });
                    return;
                }

                // Build contextual title and message
                const title = payload.title || $t('upgrade_plan');
                const planName = data.current_plan?.name || globalPlanName;
                let message = payload.message || '';

                if (!message && !hasExplicitMessage) {
                    message = buildAutoMessage(payload.feature_key, isQuota, data, globalMaxLimit, planName, payload.page_type);
                }

                commit('setPopupData', {
                    title,
                    message,
                    current_plan: data.current_plan,
                    current_plan_features: data.current_plan_features || [],
                    recommended_plan: data.recommended_plan,
                    billing_url: data.billing_url,
                    available_plans: data.available_plans || [],
                    recommended_tier: data.recommended_tier || null,
                    selected_tier: data.recommended_tier || (data.available_plans?.[0]?.tier || null),
                    promo: data.promo || null,
                });
            } catch (e) {
                console.error('[Upgrade] Failed to fetch recommendation:', e);
                // Fallback: still show popup with getPricingUrl
                commit('setPopupData', {
                    title: payload.title || $t('upgrade_plan'),
                    message: payload.message || $t('please_upgrade_your_plan'),
                    billing_url: (window as any).ECOM_INIT?.pricing_url || null,
                });
            } finally {
                commit('setLoading', false);

                // Track impression after loading completes and popup is actually visible
                if (state.show) {
                    trackUpgradeEvent({
                        event_type: UPGRADE_EVENTS.IMPRESSION,
                        trigger_type: state.trigger_type,
                        feature_key: state.feature_key,
                        source_location: state.source_location,
                        popup_mode: state.mode,
                    });
                }
            }
        },

        /**
         * Fetch upgrade recommendation from backend API.
         */
        async fetchRecommendation({ commit }, params: { featureKey: string; pageType: string } | string = '') {
            // Support both string (legacy) and object params
            const featureKey = typeof params === 'string' ? params : params.featureKey;
            const pageType = typeof params === 'string' ? '' : params.pageType;

            try {
                const route = (window as any).route;
                let url = route
                    ? route('builder.upgrade-recommendation')
                    : '/builder/ajax/upgrade-recommendation';

                // Append query parameters for context-aware results
                const qp: string[] = [];
                if (featureKey) qp.push(`feature_key=${encodeURIComponent(featureKey)}`);
                if (pageType) qp.push(`page_type=${encodeURIComponent(pageType)}`);
                if (qp.length) {
                    const separator = url.includes('?') ? '&' : '?';
                    url += separator + qp.join('&');
                }

                const response = await fetch(url, {
                    headers: {
                        'Accept': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                    },
                });

                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}`);
                }

                const json = await response.json();
                const data = json.data || null;

                // Tag cached data for cache invalidation
                if (data) {
                    data._cacheKey = `${featureKey}:${pageType}`;
                }

                // Cache the response
                commit('setCachedData', data);
                return data;
            } catch (e) {
                console.error('[Upgrade] API error:', e);
                return null;
            }
        },

        /**
         * Select a plan tier.
         */
        selectPlan({ commit, getters }, tier: string) {
            commit('setSelectedTier', tier);
            // Reset extra pages add-on when switching to a plan that doesn't support it
            const isProNow = (getters as any).isProPlan;
            if (!isProNow) {
                commit('setRangeValue', 0);
            }
        },

        /**
         * Toggle billing cycle.
         */
        toggleBillingCycle({ commit, state }) {
            commit('setBillingCycle', state.billing_cycle === 'monthly' ? 'annual' : 'monthly');
        },

        /**
         * Set billing cycle explicitly.
         */
        setBillingCycle({ commit }, cycle: 'monthly' | 'annual') {
            commit('setBillingCycle', cycle);
        },

        /**
         * Validate discount code against the selected plan.
         */
        async applyDiscount({ commit, state, getters }) {
            const code = state.discount_code_input?.trim();
            if (!code) {
                commit('setDiscountError', $t('discount_code_missing') || 'Please enter a discount code');
                return;
            }

            const planId = getters.selectedPlanId;
            if (!planId) {
                commit('setDiscountError', $t('please_select_a_plan') || 'Please select a plan first');
                return;
            }

            commit('setDiscountLoading', true);
            commit('setDiscountError', '');

            try {
                const routeFn = (window as any).route;
                const url = routeFn
                    ? routeFn('builder.discount-check', {
                        code,
                        plan_id: planId,
                        plan_type: state.billing_cycle === 'monthly' ? 'monthly' : 'yearly',
                    })
                    : `/builder/ajax/discount-check?code=${encodeURIComponent(code)}&plan_id=${planId}&plan_type=${state.billing_cycle === 'monthly' ? 'monthly' : 'yearly'}`;

                const headers: Record<string, string> = {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                };

                const sessionToken = (window as any).sessionToken;
                if (sessionToken) {
                    headers['Authorization'] = `Bearer ${sessionToken}`;
                }

                const response = await fetch(url, {
                    method: 'POST',
                    headers,
                });

                const json = await response.json();

                if (json.status === 'success') {
                    commit('setDiscount', {
                        discount: {
                            code,
                            name: json.discount?.name || code,
                            type: json.discount?.type || 'percent',
                            value: json.discount?.value || 0,
                            interval: json.discount?.interval || null,
                        },
                        plan: json.plan || null,
                    });
                    commit('setDiscountCodeInput', '');
                } else {
                    const raw = json.message || 'invalid_discount_code';
                    const translateKey = raw.startsWith('$t|') ? raw.replace('$t|', '').trim() : raw;
                    commit('setDiscountError', $t(translateKey) || translateKey);
                }
            } catch (e: any) {
                console.error('[Upgrade] Discount validation error:', e);
                commit('setDiscountError', e.message || 'Error validating discount code');
            } finally {
                commit('setDiscountLoading', false);
            }
        },

        /**
         * Remove applied discount.
         */
        removeDiscount({ commit }) {
            commit('clearDiscount');
        },

        /**
         * Close the upgrade popup and reset state (keep cache).
         * @param isDismiss — true when user actively dismisses (Cancel/close button).
         *                    false when popup hides after a successful upgrade redirect.
         */
        hideUpgradePopup({ commit, state }, isDismiss = true) {
            // Track dismiss only when user actively closes (not after upgrade click)
            if (isDismiss && state.show) {
                trackUpgradeEvent({
                    event_type: UPGRADE_EVENTS.DISMISS,
                    trigger_type: state.trigger_type,
                    feature_key: state.feature_key,
                    source_location: state.source_location,
                    popup_mode: state.mode,
                });
            }

            const cachedData = state._cachedData;
            const pendingAiCreditCheckout = state.pending_ai_credit_checkout;
            const pendingAiCreditCheckoutSnapshot = state.pending_ai_credit_checkout_snapshot;
            const pendingAiCreditCheckoutStartedAt = state.pending_ai_credit_checkout_started_at;

            // Popup was triggered from the AI Product Import flow (out of credits) —
            // dismissing it should also close the import modal underneath, not leave it stuck open.
            if (isDismiss && (state.source_location || '').startsWith('product_import')) {
                commit('productImport/setIsOpen', false, { root: true });
            }

            commit('reset');
            // Preserve cache so we don't re-fetch
            commit('setCachedData', cachedData);
            commit('setPopupData', {
                pending_ai_credit_checkout: pendingAiCreditCheckout,
                pending_ai_credit_checkout_snapshot: pendingAiCreditCheckoutSnapshot,
                pending_ai_credit_checkout_started_at: pendingAiCreditCheckoutStartedAt,
            });
        },

        /**
         * Open Shopify billing for one plan, discount included.
         *
         * Shared by the upgrade popup and the static card in the sidebar so both
         * build the checkout URL the same way: the billing route is wrapped in
         * the `redirect` route to carry the session (matching Pricing.jsx), and
         * `discount` is only attached when there is actually a code.
         *
         * Falls back to the pricing page when the route helper is unavailable —
         * the standalone dev server does not register `billing`/`redirect`.
         */
        openPlanCheckout(_ctx, payload: {
            planId: number;
            discountCode?: string;
            unlimitedBlog?: boolean;
            extraPages?: number;
        }) {
            const planId = payload?.planId;
            const routeFn = (window as any).route;

            if (!planId || typeof routeFn !== 'function') {
                const fallback = (window as any).ECOM_INIT?.pricing_url || '';
                if (fallback) window.open(fallback, '_blank');
                return false;
            }

            const sessionToken = (window as any).sessionToken;
            const shopName = (window as any).ECOM_INIT?.shop;

            const billingParams: Record<string, any> = {
                plan: planId,
                unlimited_blog: payload.unlimitedBlog ? 1 : 0,
                step: payload.extraPages || 0,
            };
            if (payload.discountCode) billingParams.discount = payload.discountCode;
            if (sessionToken) billingParams.token = sessionToken;

            try {
                const billingUrl = routeFn('billing', billingParams);
                const url = routeFn('redirect', {
                    shop: shopName,
                    token: sessionToken,
                    url: billingUrl,
                });
                window.open(url, '_blank');
                return true;
            } catch (e) {
                console.error('[Upgrade] Cannot build checkout URL:', e);
                const fallback = (window as any).ECOM_INIT?.pricing_url || '';
                if (fallback) window.open(fallback, '_blank');
                return false;
            }
        },

        /**
         * Handle the upgrade CTA click — redirect to billing with selected plan + add-ons.
         */
        handleUpgrade({ state, getters, dispatch }) {
            const planId = getters.selectedPlanId;
            const discountCode = state.discount?.code || '';
            const isAiCreditFeature = ['ai_credits', 'ai_tokens', 'ai_image_tokens'].includes(state.feature_key);

            // Track click event
            trackUpgradeEvent({
                event_type: UPGRADE_EVENTS.CLICK,
                trigger_type: state.trigger_type,
                feature_key: state.feature_key,
                source_location: state.source_location,
                popup_mode: state.mode,
                plan_id: planId,
                billing_cycle: state.billing_cycle,
                to_plan: state.selected_tier || undefined,
                from_plan: state.current_plan?.tier || undefined,
            });

            if (planId) {
                dispatch('openPlanCheckout', {
                    planId,
                    discountCode,
                    unlimitedBlog: state.buy_blog,
                    extraPages: state.range_value,
                });
                if (isAiCreditFeature) {
                    dispatch('markAiCreditCheckoutPending');
                }
                return;
            }

            // Fallback: pricing page
            const url = state.billing_url
                || (window as any).ECOM_INIT?.pricing_url
                || '';

            if (url) {
                window.open(url, '_blank');
                if (isAiCreditFeature) {
                    dispatch('markAiCreditCheckoutPending');
                }
            }
        },

        /**
         * Open the subscription/pricing comparison page in a new tab.
         */
        comparePlans() {
            const routeFn = (window as any).route;
            let url: string;
            if (routeFn) {
                url = routeFn('app.settings', { type: 'subscription' });
            } else {
                url = '/settings/subscription';
            }
            window.open(url, '_blank');
        },

        /**
         * Toggle buy blog add-on.
         */
        toggleBuyBlog({ commit, state }) {
            commit('setBuyBlog', !state.buy_blog);
        },

        /**
         * Set extra pages range value.
         */
        setRangeValue({ commit }, value: number) {
            commit('setRangeValue', value);
        },

        /**
         * Toggle which add-on accordion is expanded.
         */
        toggleAddon({ commit, state }, addon: 'blog' | 'pages') {
            commit('setActiveAddon', state.active_addon === addon ? null : addon);
        },

        /**
         * Set selected AI credit tier.
         */
        setSelectedCreditTier({ commit }, index: number) {
            commit('setSelectedCreditTier', index);
        },

        /**
         * Handle AI Credits one-time purchase CTA.
         */
        handleBuyCredits({ state, dispatch }) {
            const tier = AI_CREDIT_TIERS[state.selected_credit_tier];
            if (!tier || tier.credits <= 0) return;

            // Track click event for credits purchase
            trackUpgradeEvent({
                event_type: UPGRADE_EVENTS.CLICK,
                trigger_type: state.trigger_type,
                feature_key: state.feature_key,
                source_location: state.source_location,
                popup_mode: state.mode,
                credit_tier: tier.tier,
                credit_amount: tier.credits,
            });

            const routeFn = (window as any).route;
            const sessionToken = (window as any).sessionToken;
            const shopName = (window as any).ECOM_INIT?.shop;
            const planId = (window as any).ECOM_INIT?.plan_id || state.current_plan?.id || 0;

            const billingParams: Record<string, any> = {
                plan: planId,
                type: 'ai_credits',
                credits: tier.credits,
                price: tier.price,
                total_price: tier.price,
            };
            if (sessionToken) billingParams.token = sessionToken;

            const billingUrl = routeFn('billing', billingParams);

            // Wrap through redirect route for authentication (matching Pricing.jsx)
            const url = routeFn('redirect', {
                shop: shopName,
                token: sessionToken,
                url: billingUrl,
            });

            const billingWindow = window.open(url, '_blank');
            dispatch('markAiCreditCheckoutPending');
        },

        /**
         * Switch popup to Plan Upgrade mode (e.g. from credits cross-sell link).
         */
        async switchToPlanMode({ commit, state, dispatch }) {
            commit('setMode', 'plan');
            // Keep the original feature_key (e.g. 'ai_credits') so the plan cards
            // can highlight the correct feature row (matched by keyword in feature text)
            // Fetch plan data if not cached
            if (!state._cachedData) {
                commit('setLoading', true);
                const data = await dispatch('fetchRecommendation', { featureKey: state.feature_key || '', pageType: '' });
                if (data) {
                    commit('setPopupData', {
                        title: $t('upgrade_plan'),
                        message: '',
                        current_plan: data.current_plan,
                        current_plan_features: data.current_plan_features || [],
                            recommended_plan: data.recommended_plan,
                        billing_url: data.billing_url,
                        available_plans: data.available_plans || [],
                        recommended_tier: data.recommended_tier || null,
                        selected_tier: data.recommended_tier || (data.available_plans?.[0]?.tier || null),
                        promo: data.promo || null,
                    });
                }
                commit('setLoading', false);
            } else {
                const data = state._cachedData;
                commit('setPopupData', {
                    title: $t('upgrade_plan'),
                    message: '',
                    current_plan: data.current_plan,
                    current_plan_features: data.current_plan_features || [],
                    available_plans: data.available_plans || [],
                    recommended_tier: data.recommended_tier || null,
                    selected_tier: data.recommended_tier || (data.available_plans?.[0]?.tier || null),
                    promo: data.promo || null,
                });
            }
        },

        /**
         * Switch popup to AI Credits mode (e.g. from plan cross-sell link).
         */
        switchToCreditsMode({ commit, state }) {
            commit('setMode', 'credits');
            // Restore the out-of-credits message when the popup was originally
            // triggered by an AI-credit quota (it was overwritten by plan mode).
            // For other triggers (cross-sell from plan mode) show no banner —
            // the user isn't necessarily out of credits.
            const isCreditTrigger = CREDIT_FEATURE_KEYS.includes(state.feature_key);
            commit('setPopupData', {
                title: $t('buy_extra_ai_credits') || 'Buy Extra AI Credits',
                message: isCreditTrigger
                    ? ($t('you_have_run_out_of_ai_credits') || 'You have run out of AI credits.')
                    : '',
            });
            commit('setSelectedCreditTier', 1);
        },
    },
};

export default module;
