// DragDropHandler.ts
import type {
  GridItemInstance,
  DragDropOptions,
  DragDropEvents,
  DragStartPosition,
  DragMouseStartPosition,
  DragPosition,
  DifferenceMouseItem,
  DragEventData
} from './types';
import { ensureNumericValue, addUnit, isPercentWidth } from '../../helpers/utils';
import { beginGridDebugTrace, endGridDebugTrace, gridDebug, gridDebugError } from '../../helpers/debug';

export class DragDropHandler {
  private instance: GridItemInstance;
  private options: DragDropOptions;
  private events: DragDropEvents;

  constructor(instance: GridItemInstance, options: DragDropOptions = {}, events: DragDropEvents = {}) {
    this.instance = instance;
    this.options = {
      enableDrag: true,
      enableDrop: true,
      snapToGrid: false,
      snapThreshold: 5,
      ...options
    };
    this.events = events;

    this.bindMethods();
  }

  private bindMethods(): void {
    this.handleElementMouseDown = this.handleElementMouseDown.bind(this);
    this.handleDragMove = this.handleDragMove.bind(this);
    this.endDrag = this.endDrag.bind(this);
  }

  public handleElementMouseDown(e: MouseEvent): void {
    // Kiểm tra nếu click vào các element không được kéo
    if (this.instance.$store?.getters?.["builder/isFullScreen"] || this.instance.isItemLocked) return;

    this.instance.setEditingElement(e);

    if (this.instance.shouldIgnoreDrag(e) || !this.instance.canDrag) {
      return;
    }

    // Xử lý nhiều item được chọn
    if (
      this.instance.isInSelection &&
      this.instance.parent.hasSelection &&
      this.instance.parent.selectedItems.length > 1
    ) {
      this.instance.parent.startDragSelection(e);
      return;
    }

    if (this.instance.inGroup) {
      this.instance.$parent.handleGroupMouseDown(e);
      return;
    }

    gridDebug('drag', 'mousedown', {
      itemId: this.instance.i,
      sectionId: this.instance.sectionId,
      clientX: e.clientX,
      clientY: e.clientY,
      stateLeft: this.instance.innerLeft,
      stateTop: this.instance.innerTop,
      stateWidth: this.instance.innerWidth,
      stateHeight: this.instance.innerHeight
    }, this.instance as any);

    if (
      this.instance.$refs.item.getBoundingClientRect().height != this.instance.innerHeight &&
      this.instance.options?.autoHeight
    ) {
      (this.instance as any).handleUpdateItemHeightAuto('drag-mousedown-precheck');
    }

    this.startDrag(e);
  }

  public startDrag(e: MouseEvent): void {
    if (this.instance.static || !this.instance.isNormalZoom) return;

    const itemElement = this.instance.$refs.item as HTMLElement;
    const itemRectBefore = itemElement.getBoundingClientRect();
    const containerElementBefore =
      (itemElement.closest('.ecom-grid-layout') as HTMLElement | null) ||
      (itemElement.offsetParent as HTMLElement | null);
    const containerRectBefore = containerElementBefore?.getBoundingClientRect();
    const renderedLeftPercentBefore =
      containerRectBefore?.width
        ? ((itemRectBefore.left - containerRectBefore.left) / containerRectBefore.width) * 100
        : null;
    const renderedTopPxBefore =
      containerRectBefore
        ? itemRectBefore.top - containerRectBefore.top
        : null;
    const stateLeftBefore = ensureNumericValue(this.instance.innerLeft);
    const stateTopBefore = ensureNumericValue(this.instance.innerTop);
    const leftDiffBefore =
      renderedLeftPercentBefore === null ? null : renderedLeftPercentBefore - stateLeftBefore;
    const topDiffBefore = renderedTopPxBefore === null ? null : renderedTopPxBefore - stateTopBefore;
    const hasStartPositionMismatch =
      (leftDiffBefore !== null && Math.abs(leftDiffBefore) > 0.35) ||
      (topDiffBefore !== null && Math.abs(topDiffBefore) > 1.5);

    const dragAnchorLeft = hasStartPositionMismatch && renderedLeftPercentBefore !== null
      ? renderedLeftPercentBefore
      : stateLeftBefore;
    const dragAnchorTop = hasStartPositionMismatch && renderedTopPxBefore !== null
      ? renderedTopPxBefore
      : stateTopBefore;

    beginGridDebugTrace(this.instance as any, 'drag', {
      itemId: this.instance.i,
      sectionId: this.instance.sectionId,
      initialLeft: this.instance.innerLeft,
      initialTop: this.instance.innerTop,
      containerWidth: this.instance.gridContainerWidth,
      scaleRatio: this.instance.scaleRatio,
      renderedLeftPercentBefore,
      renderedTopPxBefore,
      leftDiffBefore,
      topDiffBefore
    });

    gridDebug('drag', 'start:preflight', {
      itemId: this.instance.i,
      sectionId: this.instance.sectionId,
      renderedLeftPercentBefore,
      renderedTopPxBefore,
      stateLeftBefore,
      stateTopBefore,
      leftDiffBefore,
      topDiffBefore,
      containerRectBefore: containerRectBefore
        ? {
            left: containerRectBefore.left,
            top: containerRectBefore.top,
            width: containerRectBefore.width,
            height: containerRectBefore.height
          }
        : null
    }, this.instance as any);

    if (hasStartPositionMismatch) {
      gridDebug('drag', 'start:position-mismatch', {
        itemId: this.instance.i,
        sectionId: this.instance.sectionId,
        leftDiffBefore,
        topDiffBefore,
        renderedLeftPercentBefore,
        renderedTopPxBefore,
        stateLeftBefore,
        stateTopBefore,
        dragAnchorLeft,
        dragAnchorTop
      }, this.instance as any);

      gridDebug('drag', 'start:anchor-corrected', {
        itemId: this.instance.i,
        sectionId: this.instance.sectionId,
        reason: 'state-render-mismatch',
        fromState: {
          left: stateLeftBefore,
          top: stateTopBefore
        },
        toRendered: {
          left: dragAnchorLeft,
          top: dragAnchorTop
        }
      }, this.instance as any);
    }

    // Cập nhật tỷ lệ scale một lần khi bắt đầu drag
    this.instance.updateScaleRatio();
    this.instance.updateContainerSize();

    // Thiết lập style để vô hiệu hóa việc chọn văn bản
    this.instance.idoc.body.style.userSelect = "none";
    this.instance.idoc.body.style.webkitUserSelect = "none";
    this.instance.idoc.body.style.cursor = "pointer";

    // Lưu vị trí trước khi kéo
    this.instance.previousLeft = dragAnchorLeft;
    this.instance.previousTop = dragAnchorTop;

    // Lưu vị trí chuột ban đầu
    this.instance.dragMouseStartPosition = {
      x: e.clientX,
      y: e.clientY
    };

    this.instance.isMouseMoved = false;
    this.instance.isDraggingPrepared = true;

    try {
      // QUAN TRỌNG: Thay vì tính toán phức tạp, chỉ sử dụng giá trị hiện tại
      // Điều này đảm bảo không có sự "nhảy" khi bắt đầu kéo
      this.instance.dragStartPosition = {
        left: this.instance.previousLeft,
        top: this.instance.previousTop
      };

      // Vẫn cần tính toán differenceMouseItem để di chuyển chính xác
      // Lấy thông tin kích thước và vị trí thực của phần tử hiện tại (với rotation)
      const containerElement =
        (this.instance.$refs.item.closest('.ecom-grid-layout') as HTMLElement | null) ||
        (this.instance.$refs.item.offsetParent as HTMLElement | null);

      // FIX: Điều chỉnh vị trí theo tỷ lệ scale một cách nhất quán
      // Vị trí thực của phần tử sau khi loại bỏ ảnh hưởng của scale
      const itemRect = this.instance.$refs.item.getBoundingClientRect();
      const actualLeft = itemRect.left / this.instance.scaleRatio;
      const actualTop = itemRect.top / this.instance.scaleRatio;

      // FIX: Lấy chiều rộng container thực tế không bị scale
      const containerWidth = containerElement && (containerElement as HTMLElement).offsetWidth
        ? (containerElement as HTMLElement).offsetWidth / this.instance.scaleRatio
        : this.instance.gridContainerWidth / this.instance.scaleRatio;

      // FIX: Tính toán điểm khác biệt giữa vị trí chuột và phần tử một cách chính xác
      // Đảm bảo điều chỉnh vị trí chuột theo tỷ lệ scale
      this.instance.differenceMouseItem = {
        left: e.clientX / this.instance.scaleRatio - actualLeft,
        top: e.clientY / this.instance.scaleRatio - actualTop
      };

      // Emit sự khác biệt này cho eventBus
      const differenceMouseItemPercent = {
        left: (this.instance.differenceMouseItem.left / containerWidth) * 100,
        top: this.instance.differenceMouseItem.top,
        containerWidth: containerWidth
      };
      this.instance.eventBus.emit("difference-mouse-item", differenceMouseItemPercent);

      // Cập nhật vị trí ban đầu cho dragging
      this.instance.dragging = {
        left: this.instance.previousLeft,
        top: this.instance.previousTop
      };
      gridDebug('drag', 'difference-mouse-item', {
        itemId: this.instance.i,
        differenceMouseItem: this.instance.differenceMouseItem,
        differenceMouseItemPercent
      }, this.instance as any);

      gridDebug('drag', 'start:prepared-position', {
        itemId: this.instance.i,
        sectionId: this.instance.sectionId,
        previousLeft: this.instance.previousLeft,
        previousTop: this.instance.previousTop,
        dragStartPosition: this.instance.dragStartPosition,
        dragging: this.instance.dragging,
        scaleRatio: this.instance.scaleRatio
      }, this.instance as any);
    } catch (e) {
      gridDebugError('drag', 'calculate-start-position:failed', e, {
        itemId: this.instance.i,
        previousLeft: this.instance.previousLeft,
        previousTop: this.instance.previousTop
      }, this.instance as any);
      this.instance.dragStartPosition = {
        left: this.instance.previousLeft,
        top: this.instance.previousTop
      };
    }

    // Đăng ký drag với store
    const inst = this.instance.instanceStore.get(this.instance.i);
    try {
      this.instance.$store.commit("builder/setDragging", {
        current: inst.is != "block" ? inst.$parent : inst,
        dropTo: null,
        dropPos: "top"
      });
    } catch (err) {
      console.error("Failed to register drag instance:", err);
    }

    // Thêm event listeners
    this.instance.idoc.addEventListener("mousemove", this.handleDragMove);
    this.instance.idoc.addEventListener("mouseup", this.endDrag);

    e.preventDefault();
    e.stopPropagation();
  }

  public handleDragMove(e: MouseEvent): void {
    if (!this.instance.isDraggingPrepared) return;

    try {
      if (this.instance.$store) {
        this.instance.$store.commit("global/setCloseBlockSt", true);
      }
    } catch (e) {
      console.error("Error setting close block handleDragMove:", e);
    }

    // Tính toán khoảng cách di chuyển
    const deltaX = e.clientX - this.instance.dragMouseStartPosition!.x;
    const deltaY = e.clientY - this.instance.dragMouseStartPosition!.y;

    // Nếu di chuyển hơn 3px, coi như đã drag thực sự
    const hasMoved = Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3;
    if (this.instance.locked && hasMoved) {
      this.instance.$store.commit("builder/setShowNoticeLockmode", true);
      return;
    }

    // Bắt đầu drag nếu chuột di chuyển đủ xa
    if (hasMoved && !this.instance.isMouseMoved) {
      this.instance.isMouseMoved = true;
      this.instance.isDragging = true;

      gridDebug('drag', 'start:first-move-threshold-crossed', {
        itemId: this.instance.i,
        sectionId: this.instance.sectionId,
        deltaX,
        deltaY,
        dragStartPosition: this.instance.dragStartPosition,
        dragging: this.instance.dragging,
        currentInnerLeft: this.instance.innerLeft,
        currentInnerTop: this.instance.innerTop
      }, this.instance as any);

      // Bỏ center flag khi thực sự bắt đầu kéo để kéo thả mượt mà
      if (this.instance.center) {
        const layoutItem = this.instance.parent.layout.find((item: any) => item.i === this.instance.i);
        if (layoutItem) {
          layoutItem.center = false;
        }
        const block = this.instance.parent.data.blocks.find((b: any) => b.id === this.instance.i);
        if (block && block.layouts && block.layouts[this.instance.currentScreen]) {
          block.layouts[this.instance.currentScreen].center = false;
        }
      }
      this.instance.emitDragEvent("dragstart", this.instance.dragging!.left, this.instance.dragging!.top);
    }

    if (!this.instance.isMouseMoved) return;

    // Hủy animation frame nếu đang có
    if (this.instance._dragRAF) {
      cancelAnimationFrame(this.instance._dragRAF);
    }

    // Thực hiện cập nhật trong animation frame tiếp theo
    this.instance._dragRAF = requestAnimationFrame(() => {
      this.performDragMove(e, deltaX, deltaY);
    });
  }

  private performDragMove(e: MouseEvent, deltaX: number, deltaY: number): void {
    // Xác định rõ ràng chiều rộng container thực - không bị ảnh hưởng bởi scale
    const containerElement =
      (this.instance.$refs.item.closest('.ecom-grid-layout') as HTMLElement | null) ||
      (this.instance.$refs.item.offsetParent as HTMLElement | null);
    const containerWidth = (containerElement as HTMLElement)?.offsetWidth || this.instance.gridContainerWidth;

    // Tính toán cách di chuyển tương đối theo điểm ảnh đã adjusted cho scale
    const scaledDeltaX = deltaX / this.instance.scaleRatio;
    const scaledDeltaY = deltaY / this.instance.scaleRatio;

    // Chuyển đổi thẳng từ pixel sang phần trăm
    const deltaXPercent = (scaledDeltaX / containerWidth) * 100;

    // Cập nhật vị trí đang kéo (KHÔNG giới hạn theo container)
    const newPosition = {
      left: this.instance.dragStartPosition!.left + deltaXPercent,
      top: this.instance.dragStartPosition!.top + scaledDeltaY
    };

    gridDebug('drag', 'move', {
      itemId: this.instance.i,
      deltaX,
      deltaY,
      scaledDeltaX,
      scaledDeltaY,
      deltaXPercent,
      newLeft: newPosition.left,
      newTop: newPosition.top,
      scaleRatio: this.instance.scaleRatio
    }, this.instance as any);

    // Kiểm tra vị trí chuột có nằm trong container hợp lệ không
    const elementUnderMouse = this.instance.idoc.elementFromPoint(e.clientX, e.clientY);

    // Grid container gốc (container hiện tại)
    const currentGridContainer = this.instance.$refs.item.closest(".ecom-grid-layout");
    let isMouseInsideValidContainer = false;

    if (elementUnderMouse) {
      // Kiểm tra xem chuột có nằm trong grid container gốc không
      if (currentGridContainer) {
        isMouseInsideValidContainer =
          currentGridContainer.contains(elementUnderMouse) ||
          elementUnderMouse === currentGridContainer ||
          elementUnderMouse.closest(".ecom-grid-layout") === currentGridContainer;
      }

      // Nếu không nằm trong container gốc, kiểm tra xem có nằm trong container khác không
      if (!isMouseInsideValidContainer) {
        // Kiểm tra grid container khác
        const otherGridContainer = elementUnderMouse.closest(".ecom-grid-layout");
        if (otherGridContainer && otherGridContainer !== currentGridContainer) {
          isMouseInsideValidContainer = true;
        }

        // Kiểm tra .core__column--wrapper khác
        if (!isMouseInsideValidContainer) {
          const columnWrapper = elementUnderMouse.closest(".core__column--wrapper");
          if (columnWrapper) {
            // Kiểm tra xem column wrapper này có khác với column wrapper hiện tại không
            const currentColumnWrapper = this.instance.$refs.item.closest(".core__column--wrapper");
            if (!currentColumnWrapper || columnWrapper !== currentColumnWrapper) {
              isMouseInsideValidContainer = true;
            }
          }
        }
      }
    }

    // Fallback: kiểm tra theo container rect nếu cần
    if (!isMouseInsideValidContainer && currentGridContainer) {
      const containerRect = currentGridContainer.getBoundingClientRect();
      isMouseInsideValidContainer =
        e.clientX >= containerRect.left &&
        e.clientX <= containerRect.right &&
        e.clientY >= containerRect.top &&
        e.clientY <= containerRect.bottom;
    }

    // Chỉ cảnh báo khi chuột không nằm trong bất kỳ container hợp lệ nào
    if (!isMouseInsideValidContainer) {
      this.instance.isOutsideContainer = true;
      this.instance.$refs.item.classList.add("ecom-grid-item-returning");
    } else {
      this.instance.isOutsideContainer = false;
      this.instance.$refs.item.classList.remove("ecom-grid-item-returning");
    }

    // Kiểm tra section đích
    const newSectionId = (e.target as Element).closest(".ecom-section")?.getAttribute("data-id");

    // Cập nhật vị trí đang kéo (cho phép kéo ra ngoài)
    this.instance.dragging = newPosition;

    // Áp dụng vị trí mới vào phần tử
    this.instance.innerLeft = addUnit(newPosition.left, "%");
    this.instance.innerTop = addUnit(newPosition.top, "px");

    // Xử lý khi kéo qua section khác
    if (newSectionId && newSectionId !== this.instance.sectionId) {
      const newSection = (e.target as Element).closest(".ecom-grid-layout") as HTMLElement;
      if (newSection) {
        const newSectionWidth = newSection.offsetWidth;
        const widthRatio = containerWidth / newSectionWidth;

        // Tính toán offset để căn giữa
        const centerOffset = (((newSectionWidth - containerWidth) / 2) * 100) / newSectionWidth;

        // Điều chỉnh vị trí left dựa trên tỷ lệ và offset
        newPosition.left = newPosition.left * widthRatio + centerOffset;
      }
    }

    // Phát sự kiện dragmove
    this.instance.emitDragEvent("dragmove", newPosition.left, newPosition.top);

    this.instance._dragRAF = null;
  }

  public endDrag(e: MouseEvent): void {
    // Xóa event listeners
    this.instance.idoc.removeEventListener("mousemove", this.handleDragMove);
    this.instance.idoc.removeEventListener("mouseup", this.endDrag);

    // Khôi phục style
    this.instance.idoc.body.style.userSelect = "";
    this.instance.idoc.body.style.webkitUserSelect = "";
    this.instance.idoc.body.style.cursor = "";
    document.body.style.userSelect = "";
    document.body.style.webkitUserSelect = "";

    // Hủy animation frame nếu đang có
    if (this.instance._dragRAF) {
      cancelAnimationFrame(this.instance._dragRAF);
      this.instance._dragRAF = null;
    }

    // Nếu chưa bắt đầu drag thực sự (chuột không di chuyển đủ xa)
    if (!this.instance.isMouseMoved) {
      this.resetDragState();
      return;
    }

    // Xác định vị trí cuối cùng
    let finalPosition = {
      left: this.instance.dragging!.left,
      top: this.instance.dragging!.top
    };

    // Kiểm tra xem chuột có ra ngoài container không (chỉ dựa vào vị trí chuột)
    let wasMouseOutside = this.instance.isOutsideContainer;

    try {
      finalPosition = this.calculateFinalPosition(finalPosition, wasMouseOutside);
    } catch (error) {
      console.error("Error calculating final drag position:", error);

      // Xử lý lỗi - nếu chuột ra ngoài thì khôi phục vị trí
      if (wasMouseOutside) {
        finalPosition.left = this.instance.previousLeft;
        finalPosition.top = this.instance.previousTop;
      }
    }

    this.finalizeDrag(e, finalPosition, wasMouseOutside);
  }

  private calculateFinalPosition(finalPosition: DragPosition, wasMouseOutside: boolean): DragPosition {
    // Nếu chuột đã ra ngoài container, quay về vị trí ban đầu
    if (wasMouseOutside) {
      finalPosition.left = this.instance.previousLeft;
      finalPosition.top = this.instance.previousTop;

      // Thêm hiệu ứng animation trở về
      if (this.instance.$refs.item) {
        this.instance.$refs.item.style.transition = "all 0.3s ease-out";

        // Xóa class và transition sau khi hiệu ứng kết thúc
        setTimeout(() => {
          this.instance.$refs.item.classList.remove("ecom-grid-item-returning");
          this.instance.$refs.item.style.transition = "";
        }, 300);
      }
    } else {
      // Xử lý snap và các logic khác khi chuột vẫn trong container
      const containerWidth = this.instance.parent.$el.offsetWidth || this.instance.parent.width || 1200;
      const itemWidth = ensureNumericValue(this.instance.innerWidth);
      const itemWidthPercent = isPercentWidth(this.instance.innerWidth)
        ? ensureNumericValue(itemWidth)
        : (itemWidth / containerWidth) * 100;
      const itemHeight = ensureNumericValue(this.instance.innerHeight);

      // Áp dụng auto snap nếu được bật
      if (this.instance.autoSnap) {
        finalPosition = this.applyAutoSnap(finalPosition, itemWidthPercent, itemHeight, containerWidth);
      }
    }

    return finalPosition;
  }

  private applyAutoSnap(finalPosition: DragPosition, itemWidthPercent: number, itemHeight: number, containerWidth: number): DragPosition {
    if (
      this.instance.parent &&
      this.instance.parent.centerV &&
      (this.instance.parent.isDraggingGrid || this.instance.parent.isResizing) &&
      this.instance.parent.over
    ) {
      finalPosition.left = (100 - itemWidthPercent) / 2;
    }

    if (
      this.instance.parent &&
      this.instance.parent.centerH &&
      (this.instance.parent.isDraggingGrid || this.instance.parent.isResizing) &&
      this.instance.parent.over
    ) {
      const containerHeight = this.instance.parent.gridHeight() || this.instance.parent.$refs.item.offsetHeight;
      finalPosition.top = (containerHeight - itemHeight) / 2;
    }

    // Snap theo cạnh trái/phải của cột
    const leftGuideVisible =
      this.instance.parent &&
      this.instance.parent.placeholder.snapEdge &&
      this.instance.parent.guideLineLeft >= 0 &&
      (this.instance.parent.isDraggingGrid || this.instance.parent.isResizing) &&
      this.instance.parent.over;

    if (leftGuideVisible) {
      const newLeft = this.instance.parent.snapToColLeft(finalPosition.left, itemWidthPercent);
      finalPosition.left = newLeft;
    }

    const rightGuideVisible =
      this.instance.parent &&
      this.instance.parent.placeholder.snapEdgeRight &&
      this.instance.parent.guideLineRight > 0 &&
      (this.instance.parent.isDraggingGrid || this.instance.parent.isResizing) &&
      this.instance.parent.over;

    if (rightGuideVisible) {
      const currentRightPosition = finalPosition.left + itemWidthPercent;
      const newLeft = this.instance.parent.snapToColRight(currentRightPosition, itemWidthPercent);
      finalPosition.left = newLeft;
    }

    // Snap theo các items khác
    if (
      this.instance.parent &&
      this.instance.parent.sameV.length > 0 &&
      (this.instance.parent.isDraggingGrid || this.instance.parent.isResizing) &&
      this.instance.parent.over
    ) {
      let closestV = null;
      let minVDistance = Infinity;
      let snapType = null;

      for (const guide of this.instance.parent.sameV) {
        const leftDistance = Math.abs(finalPosition.left - guide.x);
        if (leftDistance < minVDistance) {
          minVDistance = leftDistance;
          closestV = guide;
          snapType = "left";
        }

        const rightDistance = Math.abs(finalPosition.left + itemWidthPercent - guide.x);
        if (rightDistance < minVDistance) {
          minVDistance = rightDistance;
          closestV = guide;
          snapType = "right";
        }
      }

      if (closestV && minVDistance <= 5) {
        if (snapType === "left") {
          finalPosition.left = closestV.x;
        } else if (snapType === "right") {
          finalPosition.left = closestV.x - itemWidthPercent;
        }
      }
    }

    return finalPosition;
  }

  private finalizeDrag(e: MouseEvent, finalPosition: DragPosition, wasMouseOutside: boolean): void {
    gridDebug('drag', 'finalize', {
      itemId: this.instance.i,
      finalLeft: finalPosition.left,
      finalTop: finalPosition.top,
      wasMouseOutside,
      changed: {
        left: finalPosition.left !== this.instance.previousLeft,
        top: finalPosition.top !== this.instance.previousTop
      },
      dropTo: this.instance.dropTo?.data?.id || null
    }, this.instance as any);

    // Hiển thị lại grid item gốc
    this.instance.isVisible = true;

    // Chỉ cập nhật vị trí trong data khi KHÔNG thả vào container khác
    if (
      !this.instance.dropTo ||
      !this.instance.dropTo.canDrop ||
      (typeof this.instance.dropTo !== "string" && this.instance.dropTo?.data?.id === this.instance.parent?.data?.id)
    ) {
      this.instance.innerLeft = addUnit(finalPosition.left, "%");
      this.instance.innerTop = addUnit(finalPosition.top, "px");
    }

    // Đánh dấu kết thúc dragging
    this.instance.isDragging = false;
    this.instance.isOutsideContainer = false;

    // Xử lý drop vào container khác
    if (
      (this.instance.dropTo &&
        this.instance.dropTo.canDrop &&
        this.instance.dropTo?.data?.id !== this.instance.parent?.data?.id) ||
      typeof this.instance.dropTo == "string" ||
      this.instance.dropTo?.is === "structure"
    ) {
      this.handleDropToContainer(e, this.instance.parent);
    }

    // Reset state
    this.resetDragState();

    this.instance.parent.$parent.setDragEnded(true);

    setTimeout(() => {
      this.instance.parent.$parent.setDragEnded(false);
    }, 100);

    // Reset trạng thái kéo trong store
    try {
      if (this.instance.$store) {
        this.instance.$store.commit("builder/resetDragging");
        this.instance.$store.commit("builder/setActiveElement", null);
        this.instance.$store.commit("builder/sectionDrag", null);
        this.instance.$store.commit("builder/setDropTo", null);
      }
    } catch (e) {
      gridDebugError('drag', 'finalize:reset-store-failed', e, {
        itemId: this.instance.i
      }, this.instance as any);
    }

    // Phát sự kiện dragend và moved
    this.instance.emitDragEvent("dragend", finalPosition.left, finalPosition.top);
    setTimeout(() => {
      if(this.instance.parent?.isDraggingGrid) {
        this.instance.emitDragEvent("dragend", finalPosition.left, finalPosition.top);
      }
    }, 500);
    // Emit events
    this.emitFinalEvents(finalPosition, wasMouseOutside);
    endGridDebugTrace(this.instance as any, 'drag', 'trace:end', {
      itemId: this.instance.i,
      finalPosition,
      wasMouseOutside
    });
  }

  private emitFinalEvents(finalPosition: DragPosition, wasMouseOutside: boolean): void {
    // Tính toán xem element có còn ở center không
    const calculateIsCenter = (left: number): boolean => {
      const containerWidth = this.instance.gridContainerWidth || this.instance.parent.containerWidth || 1200;
      const itemWidth = ensureNumericValue(this.instance.innerWidth);
      const itemWidthPx = isPercentWidth(this.instance.innerWidth)
        ? (ensureNumericValue(itemWidth) / 100) * containerWidth
        : itemWidth;
      const elementCenterX = left + (itemWidthPx / containerWidth) * 100 / 2;
      return Math.abs(elementCenterX - 50) < 1; // tolerance 1%
    };

    // Chỉ emit moved event nếu chuột không ra ngoài container
    if (
      !wasMouseOutside &&
      (this.instance.previousLeft !== ensureNumericValue(this.instance.innerLeft) ||
        this.instance.previousTop !== ensureNumericValue(this.instance.innerTop))
    ) {
      const isCenter = calculateIsCenter(finalPosition.left);
      this.instance.$emit("moved", this.instance.i, finalPosition.left, finalPosition.top, isCenter);
      this.instance.leftOld = finalPosition.left;
      this.instance.topOld = finalPosition.top;

      // Call events callback
      if (this.events.onMoved) {
        this.events.onMoved(this.instance.i, finalPosition.left, finalPosition.top);
      }
    } else if (wasMouseOutside) {
      // Nếu chuột ra ngoài và quay về vị trí ban đầu, emit moved với vị trí cũ
      const isCenter = calculateIsCenter(this.instance.leftOld);
      this.instance.$emit("moved", this.instance.i, this.instance.leftOld, this.instance.topOld, isCenter);

      if (this.events.onMoved) {
        this.events.onMoved(this.instance.i, this.instance.leftOld, this.instance.topOld);
      }
    }
  }

  private resetDragState(): void {
    this.instance.dragging = null;
    this.instance.dragStartPosition = null;
    this.instance.dragMouseStartPosition = null;
    this.instance.isMouseMoved = false;
    this.instance.isDraggingPrepared = false;

    try {
      if (this.instance.$store) {
        this.instance.$store.commit("builder/resetDragging");
        this.instance.$store.commit("builder/setActiveElement", null);
        this.instance.$store.commit("builder/sectionDrag", null);
        this.instance.$store.commit("builder/setDropTo", null);
      }
    } catch (e) {
      gridDebugError('drag', 'reset-state:store-failed', e, {
        itemId: this.instance.i
      }, this.instance as any);
    }
  }

  private handleDropToContainer(e: MouseEvent, _this: any): void {
    if (this.instance.idoc) {
      this.instance.idoc.body.style.userSelect = "";
      this.instance.idoc.body.style.webkitUserSelect = "";
      this.instance.idoc.body.style.cursor = "";
    }

    document.body.style.userSelect = "";
    document.body.style.webkitUserSelect = "";
    document.body.style.cursor = "";

    let inst = _this.dropTo;
    if (typeof inst == "string") {
      inst = this.instance.instanceStore.get(inst);
    }

    if (
      typeof inst !== "string" &&
      inst?.control !== false &&
      _this.dragCurrent &&
      inst &&
      _this.dragCurrent !== inst
    ) {
      _this.dragCurrent.over = false;
      inst.over = false;

      if (typeof inst.dropIn === "function") {
        let pos = inst.dropPos == "bottom" || inst.dropPos == "right" ? 1 : 0;
        if (
          (inst.dragCurrent.$parent === inst.dropTo.$parent ||
            inst.dragCurrent.$parent.$parent.$parent === inst.dropTo.$parent) &&
          inst.dragCurrent.index < inst.dropTo.index
        ) {
          pos -= 1;
        }
        inst.dropIn(_this.dragCurrent, pos);
      }
    }

    _this.dragging = false;
  }

  public destroy(): void {
    // Cleanup event listeners if needed
    if (this.instance._dragRAF) {
      cancelAnimationFrame(this.instance._dragRAF);
      this.instance._dragRAF = null;
    }

    // Remove any remaining event listeners
    this.instance.idoc.removeEventListener("mousemove", this.handleDragMove);
    this.instance.idoc.removeEventListener("mouseup", this.endDrag);

    // Reset drag state
    this.resetDragState();
  }
}