        />
        <a
          v-else-if="data?.settings?.image?.image_link?.href && data?.settings?.image?.image?.value"
          :href="data?.settings?.image.image_link?.href"
          :target="data?.settings?.image.image_link?.target"
          :rel="data?.settings?.image.image_link?.target === '_blank' ? 'noopener' : null"
