<script>
import { Element } from '@/mixins';
import { getContentEditableValue, placeCaretAtEnd } from '@/utils/contentEditable';
export default {
    name: 'Banner',
    presets: false,
    docs: '',
    mixins: [Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            editingValue: "",
            isBlur: false,
            /** 'heading' | 'subheading' | 'content' | 'button' */
            inlineField: null,
            currentEditEl: null
        };
    },
    computed: {
        image() {
          return this.data?.settings?.image.image;
        },
        screens() {
            return this.$store.getters['builder/screens'];
        },
        attrLink() {
            return this.data?.settings?.button?.link;
        },
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.data.id;
        },
        isContentEditable() {
            return this.$store.getters["builder/isContentEditable"];
        },
        editingElementId() {
            return this.$store.getters["builder/editingElementId"];
        },
        isEditingThisElement() {
            if (this.exporting) return false;
            return this.editingElementId === this.data.id && this.isContentEditable;
        },
        isEditingAnyBannerInline() {
            return !!this.inlineField && this.isEditingThisElement;
        },
        lazyload() {
          return this.data.settings?.disable_lazyload === true ? false : true;
        },
        horizontal_style() {
          const classes = [];

          const horizontal = this.data?.settings?.horizontal;
          if (horizontal) {
            classes.push(`ecom-horizontal-${horizontal}`);
          }

          const alignment = this.data?.settings?.content_alignment;
          if (alignment) {
            classes.push(`ecom-horizontal-align-${alignment}`);
          }

          return classes.join(' ');
        },
        vertical_style() {
          let style = {};
          if(this.data?.settings?.vertical) {
            style.alignItems = this.data?.settings?.vertical;
          }
          return style;
        },
        focalPoint() {
          // focal point
          let style = {};
          let { image = {} } = this.data.settings.image;
          if (Object.keys(image).length === 0) {
              return null;
          }
          if(image?.left && image?.top) {
            style['object-position'] = `${image?.left}% ${image?.top}%`;
          }
          return style;
          // end focal point
        },
        settings() {
            return [
              {
                group_title: this.$t('image'),
                group_name: 'image',
