                        responsive: true,
                        type: 'image',
                        editAlt: true
                    }
                  },
                  {
                    type: 'link',
                    label: this.$t('image_link'),
                    name: 'image_link'
                  }
                ]
              },
              {
                group_title: this.$t('content'),
                params: [
                    {
                    type: "textarea",
                    label: this.$t('heading'),
                    name: "heading",
                    options: {
                        toolbar: 'full',
                        height: 150
                    }
                  },
                  {
                    type: 'choose',
                    label: this.$t('span_class_uppercase_html_span_tag'),
                    name: 'tag_heading',
                    options: {
                        chooseOne:true,
                        type: 'heading',
                        modify: {
                          remove: [
                            {
                              value: 'a'
                            }
                          ]
                        }
                    }
                  },
                  {
                    type: 'line'
                  },
                  {
                    type: "textarea",
                    label: this.$t('sub_heading'),
                    name: "subheading",
                    options: {
                        toolbar: 'full',
                        height: 150,
                    }
                  },
                  {
                    type: 'choose',
                    label: this.$t('span_class_uppercase_html_span_tag'),
                    name: 'tag_sub_heading',
                    options: {
                        chooseOne:true,
                        type: 'heading',
                        modify: {
                          remove: [
                            {
                              value: 'a'
                            }
                          ]
                        }
                    }
                  },
                  {
                    type: 'line'
                  },
                  {
                    type: "textarea",
                    label: this.$t('content'),
                    name: "content",
                    options: {
                        toolbar: 'full',
                        height: 250,
                    }
                  },
                ]
              },
              {
                group_alias:'button:settings',
                options:{
                    group_name:'button',
                    group_title: this.$t('button'),
                },
                modify: {

                }
              },
              {
                group_title: this.$t('settings'),
                params: [
                  // {
                  //   type: 'choose',
                  //   label: this.$t('content_alignment'),
                  //   name: 'content_alignment',
                  //   value: '',
                  //   options: {
                  //     type: 'text-align',
                  //     values: [
