                      }
                  },
                  {
                      type: 'popup',
                      label: this.$t('fetch_priority'),
                      name: 'fetch_priority',
                      value: '',
                      options: {
                          type: 'dropdown',
                          default: false,
                          preview: "title",
                          values: {
                              'auto': this.$t('auto'),
                              'low': this.$t('low'),
