                z-index: 1;
                opacity: 0.3;
                display: flex;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                pointer-events: none;
              }
              .ecom-banner__image-picture {
                display: block;
              }

              .ecom-banner__picture-link,
              .ecom-banner__image-picture {
                width: 100%;
