              }
            `;
        },
        default(){
          return {
            "settings": {
              "image": {
                "image": {
                  "name": "Deal-Banner",
                  "ext": "jpg",
                  "value": "https://cdn.shopify.com/s/files/1/0629/7318/2186/files/Deal-Banner.jpg?v=1652079644",
                  "thumbnail": "https://cdn.shopify.com/s/files/1/0629/7318/2186/files/Deal-Banner.jpg?v=1652079644&width=250&height=250&crop=center"
                }
              },
              "animation": "grow",
              "transition": {
                "transitions": {
                  "duration": "1400ms",
                  "delay": "0ms"
                }
              },
              "overlay_use": true,
              "horizontal": "center",
              "vertical": "center",
              "button": {
                "link": {
                  "href": ""
                }
              }
            },
            "style": {
              "button": {
                "buttonBackgroundnormalmode": {
                  "classic": {
                    "background-color": "rgba(5, 150, 105, 0.8)"
                  }
                },
                "buttonColornormalmode": "#000",
                "spacing": {
                  "padding": {
                    "bottom": "10px",
                    "top": "10px",
                    "left": "24px",
                    "right": "24px"
                  }
                }
              },
              "heading": {
                "textColor": "#ffffff",
                "textTypography": {
                  "font-weight": "500",
                  "font-family": {
                    "name": "Be Vietnam Pro",
                    "value": "https://fonts.googleapis.com/css?family=Be+Vietnam+Pro:100,200,300,400,500,600,700,800,900",
                    "thumbnail": "Be Vietnam Pro"
                  },
                  "font-size": "16px",
                  "line-height": "56px"
                },
                "textTextAlign": "center"
              },
              "Image": {
                "tab": "normal",
                "imageWidth": "100%"
              },
              "subheading": {
                "textColor": "#ffffff",
                "textTypography": {
                  "font-family": {
                    "name": "Be Vietnam Pro",
                    "value": "https://fonts.googleapis.com/css?family=Be+Vietnam+Pro:100,200,300,400,500,600,700,800,900",
                    "thumbnail": "Be Vietnam Pro"
                  },
                  "font-size": "68px",
                  "line-height": "60px",
                  "font-weight": "600"
                }
              },
              "content": {
                "textColor": "#ffffff",
                "spacing": {
                  "margin": {
                    "top": "75px",
                    "bottom": "25px"
                  }
                },
                "textTypography": {
                  "font-family": {
                    "name": "Be Vietnam Pro",
                    "value": "https://fonts.googleapis.com/css?family=Be+Vietnam+Pro:100,200,300,400,500,600,700,800,900",
                    "thumbnail": "Be Vietnam Pro"
                  }
                }
              },
              "banner_image": {
                "tab": "normal"
              },
              "banner_heading": {
                "textTypography": {
                  "font-family": {
                    "name": "Be Vietnam Pro",
                    "value": "https://fonts.googleapis.com/css?family=Be+Vietnam+Pro:100,200,300,400,500,600,700,800,900",
                    "thumbnail": "Be Vietnam Pro"
                  },
                  "font-size": "16px",
                  "line-height": "58px",
                  "font-weight": "400"
                },
                "textColor": "#ffffff",
                "textTextAlign": "center"
              },
              "banner_subheading": {
                "textColor": "#ffffff",
                "textTextAlign": "center",
                "textTypography": {
                  "font-family": {
                    "name": "Be Vietnam Pro",
                    "value": "https://fonts.googleapis.com/css?family=Be+Vietnam+Pro:100,200,300,400,500,600,700,800,900",
                    "thumbnail": "Be Vietnam Pro"
                  },
                  "font-size": "68px"
                }
              },
              "banner_content": {
                "textTextAlign": "center",
                "textColor": "#ffffff"
              },
              "overlay": {
                "tab": "normal",
                "imageOpacity": 0.15
              },
              "banner_button": {
                "tab": "normal",
                "buttonColornormalmode": "#ffffff",
                "buttonBackgroundnormalmode": {
                  "classic": {
                    "background-color": "#0691b1"
                  }
                },
                "spacing": {
                  "margin": {
                    "top": "15px",
                    "left": "0px",
                    "bottom": "0px",
                    "right": "0px"
                  },
                  "padding": {
                    "top": "10px",
                    "left": "10px",
                    "bottom": "10px",
                    "right": "10px"
                  }
                },
                "buttonWidthnormalmode": "50%",
                "button_alignment": "center",
                "text_alignment": "center"
              },
              "icon": {
                "iconFontSize": "24px",
                "spacing": {
                  "margin": {
                    "left": "0px"
                  }
                }
              }
            }
          }
        }
    },
    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit("builder/setIsContentEditable", false);
                this.$store.commit("builder/setEditingElementId", "");
                if (this.currentEditEl && this.inlineField) {
                    const el = this.currentEditEl;
                    const next = getContentEditableValue(
                        el,
                        this.inlineField === "button" ? "text" : "html"
                    );
                    const s = this.data.settings;
                    if (this.inlineField === "heading") {
                        s.heading = next;
                    } else if (this.inlineField === "subheading") {
                        s.subheading = next;
                    } else if (this.inlineField === "content") {
                        s.content = next;
                    } else if (this.inlineField === "button") {
                        if (!s.button) s.button = {};
                        s.button.content = next;
                    }
                }
                this.inlineField = null;
                this.currentEditEl = null;
            }
            if (val) {
                this.$store.commit("builder/setEditingElementId", this.data.id);
            }
        },
        isContentEditable() {
            this.isBlur = false;
        },
        isEditingThisElement(val) {
            if (val && this.inlineField) {
                this.editingValue = this.getBannerFieldRaw(this.inlineField) || "";
                this.$nextTick(() => {
                    if (!this.currentEditEl || !this.isEditingThisElement) return;
                    placeCaretAtEnd(this.currentEditEl, this.idoc());
                });
            }
        }
    },
    methods: {
        isEditingBannerField(field) {
            return this.inlineField === field && this.isEditingThisElement;
        },
        getBannerFieldRaw(field) {
            const s = this.data?.settings;
            if (!s) return "";
            if (field === "heading") return s.heading;
            if (field === "subheading") return s.subheading;
            if (field === "content") return s.content;
            if (field === "button") return s.button?.content;
            return "";
        },
        textLooksDynamic(text) {
            const str = String(text || "");
            return str.includes("{{") || str.includes("{%");
        },
        editBannerField(field, e) {
            if (this.exporting) return;
            const raw = this.getBannerFieldRaw(field);
            if (field === "button") {
                if (!this.data.settings?.button?.link?.href) return;
                if (raw && this.textLooksDynamic(raw)) return;
            } else {
                if (!raw) return;
                if (this.textLooksDynamic(raw)) return;
            }
            this.inlineField = field;
            this.editingValue = raw != null ? String(raw) : "";
            this.currentEditEl = e.currentTarget;
            this.$store.commit("builder/setIsContentEditable", true);
        },
        onBannerInlineInput(ev) {
            if (this.exporting) return;
            if (!this.inlineField || !this.isEditingThisElement) return;
            const source = this.getBannerFieldRaw(this.inlineField);
            if (this.textLooksDynamic(source)) return;
            const target = ev?.target;
            if (!target) return;
            const next = getContentEditableValue(
                target,
                this.inlineField === "button" ? "text" : "html"
            );
            const s = this.data.settings;
            if (this.inlineField === "heading" && s.heading !== next) {
                s.heading = next;
            } else if (this.inlineField === "subheading" && s.subheading !== next) {
                s.subheading = next;
            } else if (this.inlineField === "content" && s.content !== next) {
                s.content = next;
            } else if (this.inlineField === "button") {
                if (!s.button) s.button = {};
                if (s.button.content !== next) {
                    s.button.content = next;
                }
            }
        },
        handleBannerInlineBlur() {
            if (this.exporting) return;
            if (!this.isBlur) return;
            setTimeout(() => {
                this.$store.commit("builder/setIsContentEditable", false);
            }, 200);
        },
        quickToolBar() {
            return ['image', 'imageObjectFit', 'imageAlign'];
        },
        style() {
          const imageGroup = this.$helpers.formatFields([
            {
              group_alias:'image',
              options:{
                  group_name: 'banner_image',
                  group_title: this.$t('image'),
                  selector: ' .ecom-image-default'
              },
              modify: {
                remove: {
                  index: 16,
                  length: 2
                },
                params:[
                  {
                      position:0,
                      fields:[
                          {
                              type: 'choose',
                              label: this.$t('alignment'),
                              name: 'imageAlign',
                              options: {
                                  oneline: true,
                                  responsive: true,
                                  type: 'text-align',
                                  values: ['flex-start', 'center', 'flex-end'],
                                  visible: {
                                      keep_data: false,
                                      condition: data => data.imageWidth !== '100%'
                                  }
                              },
                              css: {
                                  selector:'root .ecom-element__banner',
                                  properties: {
                                      'justify-items':''
                                  },
                              }
                          }
                      ]
                  }
              ]
              }
            }
          ])[0];

          // When an image link is set, Banner renders <picture> inside the link tag, so the
          // shared image alias direct-child branches (> picture, > img) stop matching and the
          // border / border-radius disappear. Extend those selectors here instead of editing
          // the shared alias, which other elements rely on as-is.
          const linkWrapper = '.ecom-banner__picture-link';
          const linkWrapperSelectors = {
            iamgeBordernormalmode: `, > ${linkWrapper} > picture, > ${linkWrapper} > img`,
            iamgeBorderhovermode: `,:hover > ${linkWrapper} > picture,:hover > ${linkWrapper} > img`,
            imageBorderRadiusnormalmode: `, > ${linkWrapper} > picture, > ${linkWrapper} > img`,
            imageBorderRadiushovermode: `,:hover > ${linkWrapper} > picture,:hover > ${linkWrapper} > img`
          };
          imageGroup?.params?.forEach(field => {
            const extra = linkWrapperSelectors[field.name];
            if (extra && typeof field?.css?.selector === 'string') {
              field.css.selector += extra;
            }
          });

          let style = [
            imageGroup,
            {
              group_alias: 'box',
              options:{
                group_title: this.$t('content_wrapper'),
                group_name: 'content_wrapper',
                selector: ' .ecom-banner_wrap_html_block'
              },
              modify: {
                params: [
                  {
                    position: 0,
                    fields: [
                      {
                        alias: 'width',
                        options: {
                          label: this.$t('width')
                        }
                      }
                    ]
                  },
                  {
                    position: 5,
                    fields: [
                      {
                        alias: 'spacing',
                        options: {
                          label: this.$t('spacing')
                        }
                      }
                    ]
                  }
                ]
              }
            },
            {
              group_alias: 'text',
              options:{
                group_title: this.$t('heading'),
                group_name: 'banner_heading',
                selector: ' .ecom-banner__heading'
              },
              modify: {
                params: [
                  {
                    position: 5,
                    fields: [
                      {
                        alias:'spacing'
                      }
                    ]
                  }
                ]
              }
            },
            {
              group_alias: 'text',
              options:{
                group_title: this.$t('sub_heading'),
                group_name: 'banner_subheading',
                selector: ' .ecom-banner__subheading'
              },
              modify: {
                params: [
                  {
                    position: 5,
                    fields: [
                      {
                        alias:'spacing'
                      }
                    ]
                  }
                ]
              }
            },
            {
              group_alias: 'text',
              options:{
                group_title: this.$t('content'),
                group_name: 'banner_content',
                selector: ' .ecom-banner__content'
              },
              modify: {
                params: [
                  {
                    position: 5,
                    fields: [
                      {
                        alias:'spacing'
                      }
                    ]
                  }
                ]
              }
            },
            {
              group_alias: 'button',
              options:{
                group_title: this.$t('button'),
                group_name: 'banner_button',
                selector: ' .ecom-banner__button'
              },
              modify:{
                  params:[
                    {
                        position:0,
                        fields: [
                            {
                              alias:'align-items',
                              options:{
                                  label: this.$t('alignment'),
                                  name: 'button_alignment',
                                  css:{
                                      properties:{
                                          'align-self':''
                                      }
                                  }
                              }
                            },
                            {
                              alias:'align-items',
                              options:{
                                  label: this.$t('text_alignment'),
                                  name: 'text_alignment',
                                  css:{
                                      properties:{
                                          'justify-content':''
                                      }
                                  }
                              }
                            }
                        ]
                    },
                  ]
              }
            },
            {
                group_alias:'icon:hover',
                options:{
                    group_title: this.$t('icon'),
                    group_name:'icon',
                    selector:' .ecom-elements__banner-button-icon',
                },
                modify:{
                    params:{
                        position:20,
                        fields:{
                            alias:'spacing'
                        }
                    },

                }
            }
          ];
          if(this.data.settings.overlay_use) {
            style.push(
              {
                group_alias: 'background:overlay',
                options:{
                    group_name:'overlay',
                    group_title: this.$t('overlay'),
                    selector: ' .ecom-banner__hzoom'
                }
              }
            )
          }
          return style;
        }
    }
};
</script>