<template>
    <Liquid v-if="conditionLiquid?.start && exporting && is !== 'section'" :data="conditionLiquid.start"></Liquid>
    <component
        :is="data?.settings?.tag ?? (is == 'section' ? 'section' : 'div')"
        :data-deep="exporting===false ? deep : null"
        class="ec-flex-wp"
        v-bind="flexContainerAttrs"
        @mouseenter="overFlexContainer"
        @mouseleave="outFlexContainer"
        @mousemove="onFlexMouseMove"
        @contextmenu.stop="rightClickMenu" @click.stop="editFlexContainer"
        v-on="!inGrid ? { mousedown: startDrag } : {}"
        :class="[
            !exporting ? 'dom-relative' : '',
            needReplaceBg ? is == 'section' ? 'ecom-replace-notice' : 'ecom-replace-notice-column' : '',
            parallaxBgImage ? 'ecom-use-parallax' : '',
            (!exporting && ['row','row-reverse'].includes(data?.settings?.['flex-direction'])) ? 'flexbox-row' : '',
            ((isFullWidth && deep == 1) || deep != 1) && isNoWrapMobile ? 'ecom-nowrap-mb' : '',
            ((isFullWidth && deep == 1) || deep != 1) && isNoWrapTablet ? 'ecom-nowrap-tb' : '',
            ((isFullWidth && deep == 1) || deep != 1) && isPerItemsMobile ? 'ecom_items-per-mb' : '',
            ((isFullWidth && deep == 1) || deep != 1) && isPerItemsTablet ? 'ecom_items-per-tb' : '',
            ((isFullWidth && deep == 1) || deep != 1) && flex_items_per_row ? 'ecom_items-per-row' : '',
            isParentRow && !exporting ? 'ecom-drag-flexbox-row' : '',
            data.settings?.overflow && !exporting ? 'ec-flex-overflow-hidden' : '',
        ]"
        :data-notice-content="!exporting ? $t('this_image_is_for_preview_only') : null"
        v-show="data.visibility !== false" >
        <div v-if="parallaxBgImage" class="ecom-parallax-background" :data-image="parallaxBgImage">
            <img :src="parallaxBgImage" />
        </div>
        <transition
            enter-active-class="transition duration-300 ease-out"
            enter-from-class="opacity-0"
            enter-to-class="opacity-100"
            leave-active-class="transition duration-300 ease-in"
            leave-from-class="opacity-100"
            leave-to-class="opacity-0"
            v-if="!inGrid && !exporting"
        >
            <div v-if="isActiveSettings && is === 'section'" class="ecom-box-hover" style="z-index: 100;">
                <div class="label-section ecom-label-section" :title="$t('edit') + ' ' + $t(is)" :class="[isEditing ? 'active' : '', locked ? 'cursor-default' : '']" @mousedown="startDrag" @mouseup="editFlexContainer">
                    <EcomIcon v-if="is == 'section'" :source="icons.SectionMajor" class="icon-builder ec-opacity-50"></EcomIcon>
                    <span :title= "$t('back_to_parent')" v-else class="core--settings__back core__block--settings__back" @click.prevent.stop="handleBack2Parent">
                        <EcomIcon :source="icons.backIcon" class="icon-back"></EcomIcon>
                    </span>
                    <span class="label-truncate" :title="data?.title" v-if="data?.title && data?.title !== ''">{{ data.title }}</span>
                    <span v-else>{{ is === 'blockFlex' ? $t('blockFlex') : $t('section') }}</span>
                </div>
            </div>
        </transition>
        <div
            v-if="showResizeHandle"
            class="ecom-resize-flexbox"
            @mousedown.stop="startDragResize($event, 'width', $refs.wrapper, 'blockFlex')"
        >
            <span v-if="dragResize.isActive">
                {{ dragResize.finalWidth }}
            </span>
        </div>
        <div v-if="!exporting && !inGrid" class="mark-box" :class="[isActiveSettings || over ? 'active' : '', isEditing ? 'ecom_current-edit' : '']">
            <span @mouseup="editRow" class="mask-dom left"></span>
            <span class="line-border top" :class="classSectionActive"></span>
            <span class="line-border right"></span>
            <span class="line-border bottom" :class="classSectionActive"></span>
            <span class="line-border left"></span>
        </div>
        <div
            v-if="!exporting && is != 'section' && placeholderTop && canDrop && !inGrid"
            class="drop__block--placeholder ecom-placeholder-top"
            :class="[
                'drop__block_' + index,
                { 'ecom-current-block-drag': placeholderTop, 'ecom-drag-current': currentDrag },
                checkInGridDrop ? 'ecom-cant-drop' : ''
            ]"
            @mouseenter="overFlexContainer"
            @mouseleave="outFlexContainer"
        >
            <div class="drop__block--placeholder-body drop__block--placeholder__top"></div>
        </div>
        <div
            v-if="is == 'section' && data?.settings?.['content-width'] !== 'full'"
            class="ecom-inner"
            :class="[
                (!exporting && ['row','row-reverse'].includes(data?.settings?.['flex-direction'])) ? 'flexbox-row' : '',
                isNoWrapMobile ? 'ecom-nowrap-mb' : '',
                isNoWrapTablet ? 'ecom-nowrap-tb' : '',
                isPerItemsMobile ? 'ecom_items-per-mb' : '',
                isPerItemsTablet ? 'ecom_items-per-tb' : '',
                flex_items_per_row ? 'ecom_items-per-row' : '',
            ]"
        >
            <Blocks
                :data="flexContainerBlocks"
                :deep="deep+1"
                :index="index"
                :section_id="section_id"
                :breadcrumb="`${breadcrumb}/${data?.id}`"
                :dragParent="false"
                :isFlexContainer="true"
                :direction="direction"
            />
        </div>
        <Blocks
            v-else
            :data="flexContainerBlocks"
            :deep="deep+1"
            :index="index"
            :section_id="section_id"
            :breadcrumb="`${breadcrumb}/${data?.id}`"
            :dragParent="false"
            :isFlexContainer="true"
            :direction="direction"
        />
        <div
            v-if="!exporting && is != 'section' && (placeholderBottom || isPlaceholderVisible) && canDrop && !inGrid"
            class="drop__block--placeholder ecom-placeholder-bottom"
            :class="[
                'drop__block_' + index,
                { 'ecom-current-block-drag': (placeholderBottom || (isPlaceholderVisible && !exporting)), 'ecom-drag-current': currentDrag },
                checkInGridDrop ? 'ecom-cant-drop' : ''
            ]"
            @mouseenter="overFlexContainer"
            @mouseleave="outFlexContainer"
        >
            <div class="drop__block--placeholder-body drop__block--placeholder__bottom"></div>
        </div>
        <div class="ecom-section__overlay">
            <video
                class="ecom-video-background"
                :muted="true"
                defaultmuted
                playsinline
                preload="true"
                v-if="show_video_background && ['upload','external'].includes(data?.settings?.source)"
                :data-play-pause-inview="data.settings?.inview_playpause"
                :loop="data.settings.loop"
                :autoplay="data.settings.autoplay"
                :data-source="data.settings?.source"
                :src="video_url"
                ref="video"
            />
            <div
                class="ecom-video-background-youtube-wrapper"
                v-if="show_video_background && ['youtube','vimeo'].includes(data?.settings?.source)"
            >
                <div
                    class="ecom-video-background-youtube"
                >
                    <iframe
                        class="ecom-video-background"
                        frameborder="0"
                        allowfullscreen="1"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        style="border: 0; width: 100%; height: 100% !important"
                        :src="data?.settings?.source == 'vimeo' ? linkVimeo : linkYoutube"
                        :data-play-pause-inview="data.settings?.inview_playpause"
                        :data-source="data.settings?.source"
                    />
                </div>
            </div>
            <div class="ecom-overlay" />
        </div>

        <template v-if="canDrop">
            <div
                class="placeholder__top"
                style="z-index:11"
                @mouseenter="placehover"
            />
            <div
                class="placeholder__bottom"
                style="z-index:11"
                @mouseenter="placehover"
            />
        </template>
        <transition
            enter-active-class="transition duration-400 ease-out"
            enter-from-class="opacity-0"
            enter-to-class="opacity-100"
            leave-active-class="transition duration-400 ease-in"
            leave-from-class="opacity-100"
            leave-to-class="opacity-0"
        >
            <div
                v-if="is == 'section' && !exporting && !isFullScreen && !isDragging"
                class="core__row--padding-bottom transition"
                :class="classSectionActive"
                @mousedown.stop="startDragPadding($event, 'bottom')"
            >
                <span
                    v-if="isDragPadding"
                    class="core__block--padding-value"
                    v-html="paddingCurrentVal + 'px'"
                />
                <span
                    v-if="isDragPadding"
                    class="core__block--padding-markup"
                    :style="{height: paddingCurrentVal + 'px'}"
                />
            </div>
        </transition>

    </component>
    <Liquid v-if="conditionLiquid?.end && exporting && is !== 'section'" :data="conditionLiquid.end"></Liquid>
</template>

<script>
import { Core, Element, Liquid, DragResize } from '@/mixins';
import Blocks from '@/components/Builder/Components/Core/Layout/Blocks.vue';
import { mapGetters } from 'vuex';
import { getIdParentAndIndex } from '@/utils/helpers';
import { SectionMajor, DeleteMajor, ArrowUpMinor, ArrowDownMinor, CirclePlusMajor, backIcon } from '@/assets/icons';
import { widthPxCalculate } from "@/plugins/vue-grid-layout/helpers/utils";

export default {
    name: 'flexContainer',
    components: {
        Blocks
    },
    props: {
        data: {
            type: Object,
            default() {
                return {
                    blocks: []
                };
            }
        },
        section_id: {
            type: String,
            default: ''
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        },
        breadcrumb: {
            type: String,
            default: ''
        },
        dragParent: {
            type: Boolean,
            default: false
        },
        inGrid: {
            type: Boolean,
            default: false
        },
        isParentRow: {
            type: Boolean,
            default: false
        },
        control: {
            type: Boolean,
            default: true
        }
    },
    data() {
        return {
            over: false,
            timmer: 0,
            timmerInsert: 0,
            rand: '094',
            placeholder: '',
            shouldApplyMarginBottom: false,
            is: this.deep == 1 && !this.inGrid && this.$parent?.is === 'rootSection' ? 'section' : 'blockFlex',
            name: this.deep == 1 ? this.$t('section') : this.$t('flex_container'),
            needReplaceBg: false,
            isDragPadding: false,
            isMuted: this.data?.settings?.muted,
            space: 0,
            position: 0,
            paddingPosition: '',
            paddingCurrentVal: 0,
            mouseOver: false,
            dragPosition: "top", // 'top' hoặc 'bottom'
            blockRect: null
        };
    },
    mixins: [Core, Element, Liquid, DragResize],
    inject: ['exporting'],
    computed: {
        flex_align_items() {
            if (this.currentScreen === 'desktop') {
                return this.data?.settings['align-items'] && this.data?.settings['align-items'] !== 'stretch';
            } else if (this.currentScreen === 'tablet') {
                return this.data?.settings['align-items__tablet'] && this.data?.settings['align-items__tablet'] !== 'stretch';
            } else if (this.currentScreen === 'mobile') {
                return this.data?.settings['align-items__mobile'] && this.data?.settings['align-items__mobile'] !== 'stretch';
            }
        },
        locked() {
            return this.$store.getters['builder/editorConfigs']?.locked;
        },
        icons() {
            return {
                SectionMajor,
                DeleteMajor,
                ArrowUpMinor,
                ArrowDownMinor,
                CirclePlusMajor,
                backIcon
            };
        },
        blocks() {
            return this.data.blocks
        },
        checkInGridDrop() {
            return !this.$helpers.checkGridDrop(this.dragCurrent, this);
        },
        canShowPlaceholder() {
            if(this.dragCurrent?.is === 'column' && this.dragCurrent?.section_id === this.section_id) return false
            return (
                this.dragCurrent &&
                ((this.dropTo === this &&
                    this.dragCurrent !== this &&
                    this.dragCurrent.$parent.$parent !== this) ||
                    (!this.dropTo &&
                        (this.dragCurrent === this || this.dragCurrent.$parent.$parent === this)))

            );
        },
        placeholderTop() {
            return this.canShowPlaceholder && this.dragPosition === "top";
        },
        placeholderBottom() {
            return this.canShowPlaceholder && this.dragPosition === "bottom";
        },
        isPlaceholderVisible() {
            return this.isLast && this.$parent.$parent?.$parent?.is == 'section' && this?.dropTo?.data.id === this.section_id && this.dropTo?.is === 'section';
        },
        currentScreen() {
            return this.$store.getters["builder/screen"];
        },
        direction() {
            switch(this.$store.getters['builder/screen']) {
                case 'desktop':
                    return this.data?.settings?.['flex-direction'];
                case 'tablet':
                    return this.data?.settings?.['flex-direction__tablet'] || this.data?.settings?.['flex-direction'];
                case 'mobile':
                    return this.data?.settings?.['flex-direction__mobile'] || this.data?.settings?.['flex-direction__tablet'] || this.data?.settings?.['flex-direction'];

            }
            return 'column';
        },
        isFullWidth() {
            return this.data?.settings?.['content-width'] === 'full';
        },
        isNoWrapMobile() {
            return this.data.settings?.['flex-wrap__mobile'] === 'nowrap';
        },
        isNoWrapTablet() {
            return this.data.settings?.['flex-wrap__tablet'] === 'nowrap';
        },
        isPerItemsMobile() {
            return this.data.settings?.['items_per_row__mobile'];
        },
        isPerItemsTablet() {
            return this.data.settings?.['items_per_row__tablet'];
        },
        flex_items_per_row() {
            return this.data.settings['items_per_row'];
        },
        parallaxBgImage() {
            const bg = this.data.style?.background;
            if (!bg?.enable_parallax) return null;
            const desktopImg = bg.backgroundnormalmode?.classic?.['background-image'];
            const tabletImg = bg['backgroundnormalmode__tablet']?.classic?.['background-image'];
            const mobileImg = bg['backgroundnormalmode__mobile']?.classic?.['background-image'];
            if (this.currentScreen === 'mobile') {
                return mobileImg || tabletImg || desktopImg || null;
            }
            if (this.currentScreen === 'tablet') {
                return tabletImg || desktopImg || null;
            }
            return desktopImg || null;
        },
        checkEdit() {
            return this.$store.getters['builder/editingElement']?.data?.id == this.data.id;
        },
        ...mapGetters('settings', [ 'isLiteMode' ]),
        width_mb() {
            return this.data?.settings?.width__mobile;
        },
        stack() {
            return this.is == 'section'
                ? this.$parent.$parent.sections
                : this.inGrid ? this.$parent?.$parent?.$parent?.$parent?.$parent.stack : this.$parent?.$parent?.blocks ? this.$parent?.$parent?.blocks : this._column ? this._column.blocks : [];
        },
        isFirst() {
            return this.index == 0;
        },
        isLast() {
            if(this.is == 'section') return this.index === 0;
            return this.stack && this.index === this.stack.length - 1;
        },
        flexContainerAttrs() {
            // SR wins over Entrance Animation on the same node (priority: SR > Entrance)
            // srPreview lets the builder canvas emit the same attrs as export.
            const hasSR = (this.exporting === true || this.srPreview) && this.is === 'section' && !!(
                this.data?.settings?.scroll_reveal || this.$store.getters['page/settings']?.scroll_reveal
            );
            const attrs = {
                ref: 'wrapper',
                style: this.styleattr.wrapper,
                'data-placeholder': this.placeholder ? this.placeholder : null,
                key: this.flexContainer.refresh,
                class: {
                    'ecom-current-section-drag': this.sectionDrag,
                    'ecom-animation': !hasSR && this.data?.advanced?.animation_type,
                    'ecom-animated': !hasSR && this.data?.advanced?.animation_type && !this.exporting,
                    'ecom-row ecom-core': true,
                    //  'ecom-ingrid-full-height': this.inGrid,
                    drop__placeholder: this.isDropTo,
                    drag__placeholder: this.isDragMe,
                    'core__block': this.deep > 1,
                    "ecom-width-mb": this.width_mb,
                    'ecom-section': this.deep === 1,
                    "ecom-width-desktop": this.data.settings?.width,
                    elmspace: !this.data?.advanced?.spacing?.margin?.top && this._column,
                    'ecom-section__video-bg' : this.show_video_background && ['youtube','vimeo'].includes(this.data?.settings?.source),
                    'ec-flex-full-height': this.data?.settings?.height === '100vh',
                    'ec-have-item': !this.exporting && this.flexContainerBlocks.length == 0,
                    ...this.classes
                },
                // "data-stopdrag": !this.exporting && this.inGrid ? "true" : null,
                ...this.attributes
            };
            if (!this.exporting) {
                attrs['data-id'] = this.data.id;
            }
            if (this.scrollingAnimation) {
                attrs['ecom-scrolling-animation'] = this.scrollingAnimation;
            }

            if (hasSR) {
                const sectionSR = this.data?.settings?.scroll_reveal;
                const src = sectionSR ? this.data.settings : this.$store.getters['page/settings'];
                attrs['data-ec-sr']       = src.scroll_reveal_type  || 'fade-up';
                attrs['data-ec-sr-delay'] = String(src.scroll_reveal_delay || 100);
            }

            if (!hasSR) {
                const delay = this.data?.advanced?.animation_delay;
                if (delay) {
                    const delayValue = delay.toString().replace(/ms$/, '');
                    attrs["ec-delay"] = delayValue || 0;
                }
            }
            return attrs;
        },
        currentDrag() {
            return this.dropTo !== this && this.dragCurrent === this;
        },
        styleattr() {
            let bg = null;
            if (this.exporting && this.data?.settings?.dynamic_background && ['product', 'collection', 'article'].includes(this.params.page)) {
                bg = "{{" + this.params.page + " | image_url: width: 2048 }}";
                bg = 'url(\'liquid[[' + encodeURIComponent(bg) + ']]\')';
            }
            return {
                wrapper: {
                    zIndex: this.exporting ? '' : (this.isActive || this.isEditing ? 3 : 1),
                    backgroundImage: bg,
                    height: this.flexContainerBlocks.length === 0 && !this.exporting ? 'auto' : '',
                },
                settings: `display: ${this.isActive ? 'inline-block' : 'none'}, margin-bottom: ${this.shouldApplyMarginBottom ? '-28px' : '0'}`
            };
        },
        isActive() {
            return (
                !this.exporting &&
                !this.isFullScreen &&
                (this.over) && !this.dragCurrent);
        },
        sectionDrag() {
            const sectionDrag = this.$store.getters['builder/sectionDrag'];
            return sectionDrag === this.section_id && this.dragCurrent?.is !== 'blocks';
        },
        isDropTo() {
            return this.dropTo === this && this.canDrop && this.dragCurrent !== this;
        },
        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this);
        },
        conditionLiquid() {
            if(!this.condition) return {}
            let liquids = {
                start: `
                        {% assign condition = true %}
                        ${this.condition ? this.condition : ''}
                        {% if condition %}
                    `,
                end: `
                        {% endif %}
                    `
            };
            return liquids;
        },
        isActiveSettings() {
            return (
                !this.exporting &&
                !this.isFullScreen &&
                (this.over && this?.deep === 1 || this.isEditing) && !this.dragCurrent);
        },
        isEditing() {
            return this.editingElement?.data?.id === this.data.id;
        },
        showResizeHandle() {
            return !this.inGrid && this.is !== 'section' && this.isEditing && !this.exporting && !this.isFullScreen;
        },
        show_video_background(){
            return ['section', 'blockFlex'].includes(this.is) && ['upload','external', 'youtube', 'vimeo'].includes(this.data.settings?.source) && this.hasVideoLink;
        },
        flexContainer() {
            if (!this.data.flexContainer) {
                this.data.flexContainer = {
                    refresh: this.$helpers.randid()
                };
            }
            return this.data.flexContainer;
        },
        flexContainerBlocks() {
            if (!this.data.blocks || typeof this.data.blocks != "object") {
                this.data.blocks = [];
            }
            return this.data.blocks;
        },
        classSectionActive() {
            if(this.editingElement) {
                const sections = this.sections.filter(section => section.visibility);
                const index = sections.findIndex(section => section.id === this.editingElement?.data?.id);
                if (index === -1) return "";
                if(this.index - index == 1) {
                    return ['ecom-section-below']
                } else if(this.index - index == -1) {
                    return ['ecom-section-above']
                }
                return "";
            }
        },
        blockElement() {
            return this.editingElement.$parent?.is ? this.editingElement.$parent : this.editingElement.$parent?.$parent;
        },
        sections(){
            return this.$store.getters['page/sections'];
        },
        video_url(){
            let source = this.data?.settings?.source;
            if(!['upload','external'].includes(source))
            {
                return '';
            }
            if(source === 'upload')
            {
                return this.data?.settings.video?.value??'';
            }
            return this.data?.settings?.url??'';
        },
        hasVideoLink() {
            let source = this.data?.settings?.source || null;
            switch (source) {
                case 'upload':
                    return this.data?.settings.video?.value;
                case 'external':
                    return this.data?.settings?.url;
                case 'youtube':
                    return this.data?.settings.srcYoutube;
                default:
                    return this.data?.settings.srcVimeo;
            }
        },
        linkYoutube() {
            if (this.data?.settings?.srcYoutube) {
                const regExpYt = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
                let val = this.data?.settings?.srcYoutube.match(regExpYt);
                let videoIdYt = val && val[2].length === 11 ? val[2] : null;
                return `${location.protocol}//www.youtube.com/embed/${videoIdYt}?version=3${
                    this.data?.settings?.start_time ? "&start=" + this.data?.settings?.start_time : ""
                }${this.data?.settings?.end_time ? "&end=" + this.data?.settings?.end_time : ""}&controls=0&mute=${
                    this.data?.settings?.muted ? 1 : 0
                }&showinfo=0&enablejsapi=1&iv_load_policy=3&playlist=${videoIdYt}&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },
        linkVimeo() {
            if (this.data?.settings?.srcVimeo) {
                const regExpVm = /(?:http?s?:\/\/)?(?:www\.)?(?:vimeo\.com)\/?(.+)/;
                let vals = this.data?.settings?.srcVimeo.match(regExpVm);
                let videoIdVm = vals ? vals[1] : null;
                return `${
                    location.protocol
                }//player.vimeo.com/video/${videoIdVm}?controls=0&api=1&autoplay=${this.data?.settings?.autoplay ? 1 : 0}&muted=${this.data?.settings?.muted || this.data?.settings?.autoplay ? 1 : 0}${
                    this.data?.settings?.start_time ? "&byline=1#t=00h00m" + this.data?.settings?.start_time + "ss" : ""
                }&showinfo=0&loop=${this.data?.settings?.loop ? 1 : 0}`;
            } else {
                return "";
            }
        },
        params(){
            return this.$store.getters['page/params'];
        },
        gridLayoutStyle() {
            const ensureNumber = (value) => {
                if (typeof value === "string") {
                    return parseFloat(value.replace(/[^\d.-]/g, "")) || 0;
                }
                return typeof value === "number" ? value : 0;
            };
            const idoc =  window.EComposerBuilder.contentDocument;
            const screenWidth = idoc?.defaultView?.innerWidth || 1440;
            const section = this.sections.find((section) => section.id === this.sectionId);
            const activePreset = this.$store.getters['page/activePreset'];
            const widthSettings = activePreset?.theme_settings["max-width"] || 1200;
            let sectionWidth = section?.settings["content-width"] === "full" ? screenWidth : (parseFloat(section?.settings["max-width"]) || parseFloat(widthSettings));

            const containerWidths = {
                desktop: sectionWidth,
                tablet: 767,
                mobile: 338
            };
            // Breakpoints
            const breakpoints = {
                desktop: 1025,
                tablet: 1023,
                mobile: 767
            };
            const hasValue = (value) => {
                // Nếu là undefined hoặc null
                if (value === undefined || value === null) return false;

                // Nếu là chuỗi rỗng
                if (typeof value === "string" && value.trim() === "") return false;

                // Chuyển đổi sang số và kiểm tra
                const num = parseFloat(String(value).replace(/[^\d.-]/g, ""));

                // Trả về false nếu NaN, nhưng true nếu là 0
                return !isNaN(num);
            };
            const layouts = this.$parent?.data?.layouts;
            if (!layouts) return "";
            const sectionId = this?.$parent?.section_id || this?.$parent?.$parent?.section_id || '';
            const blockId =  this?.$parent?.data?.id;

            // CSS Rules
            let cssRules = "";

            // Tạo CSS cho các breakpoints
            if (layouts.desktop) {
