    methods: {
        quickToolBar() {
            return ['content-width', 'flex-direction', 'flex-wrap', 'align-items'];
        },
        // Method mới để cập nhật vị trí placeholder
        updatePlaceholderPosition() {
            if (this.blockRect) {
                if (this.isParentRow) {

                    const relativeX = this.mousePosition.x / this.blockRect.width;

                    if (relativeX <= 0.5) {
                        this.dragPosition = "top";
                        this.placeholder = "top";
                    } else {
                        this.dragPosition = "bottom";
                        this.placeholder = "bottom";
                    }
                } else {
                    const relativeY = this.mousePosition.y / this.blockRect.height;
                    if (relativeY <= 0.5) {
                        this.dragPosition = "top";
                        this.placeholder = "top";
                    } else {
                        this.dragPosition = "bottom";
                        this.placeholder = "bottom";
                    }
                }
                this.$store.commit("builder/setDragging", {
                    dropPos: this.placeholder
                });
            }
        },
        calculateMousePosition(e) {
            if (this.$refs.wrapper) {
                this.blockRect = this.$refs.wrapper.getBoundingClientRect();
                this.mousePosition = {
                    x: e.clientX - this.blockRect.left,
                    y: e.clientY - this.blockRect.top
                };
            }
        },
        onFlexMouseMove(e) {
            if (!this.isFullScreen && this.over && this.isDragging) {
                this.calculateMousePosition(e);
                this.updatePlaceholderPosition();
            }
        },
        overFlexContainer(e) {
            if (!this.isFullScreen) {
                this.over = true;
                this.calculateMousePosition(e);
                this.updatePlaceholderPosition();
                // this.parentsOut();
                clearTimeout(this.timmer);
                if (this.isDragging && !this.isFullScreen && this.dragCurrent?.is !== "column") {
                    this.$store.commit("builder/setDropTo", this);
                    if (this.section_id) {
                        this.$store.commit("builder/sectionDrag", this.section_id);
                    }
                }
            }

        },
        outFlexContainer() {
            if (!this.isFullScreen) {
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    this.over = false;
                }, 50);
            }
        },
        editFlexContainer() {
            const editingElement = this.$store.getters['builder/editingElement'];
            if (!editingElement || (editingElement.data.id !== this.data.id)) {
                this.$store.commit('builder/setActiveElement', this);
                this.$store.commit('builder/setEditingElement', this);
                let rect = this.$el;
                if(rect.getBoundingClientRect) {
                    rect = rect.getBoundingClientRect();
                } else {
                    rect = this.$refs.wrapper.getBoundingClientRect();
                }
                const isNearTop = rect.top <= 50; // Kiểm tra nút có sát mép trên màn hình không
                this.shouldApplyMarginBottom = isNearTop;
            }

            // Determine instance to set as editing. Use parent only for inGrid / special cases.
            let inst = this;
            if (this.is === 'blockFlex' && this.inGrid && this.$parent) {
               inst = this.$parent;
            } else if (this.is === 'section') {
               inst = this;
            }
            this.$store.commit('builder/setActiveElement', this);
           this.$store.commit('builder/setEditingElement', this);

            // Safe getBoundingClientRect
            let rectTop = 0;
            try {
                const rect = (this.$el && this.$el.getBoundingClientRect) ? this.$el.getBoundingClientRect() : (this.$refs.wrapper ? this.$refs.wrapper.getBoundingClientRect() : null);
                rectTop = rect ? rect.top : 0;
            } catch (err) {
                rectTop = 0;
            }
            this.shouldApplyMarginBottom = rectTop <= 50;
        },
        handleBack2Parent() {
            const breacumbsPath = this?.breadcrumb || this?.$attrs?.breadcrumb;
            if(breacumbsPath) {
                const breacumbs = breacumbsPath.split('/');
                if(breacumbs.length > 0) {
                    const parent = breacumbs.slice(-2, -1);
                    const stack = this.instanceStore.get(parent[0]);
                    //const stackItem = this.stacks[parent];
                    if(stack) {
                        if(stack.isFlexContainer) {
                            this.$store.commit('builder/setActiveElement', stack.$refs.blockElement);
                            this.$store.commit('builder/setEditingElement', stack.$refs.blockElement);
                        }
                        else {
                            this.$store.commit('builder/setActiveElement', stack);
                            this.$store.commit('builder/setEditingElement', stack);
                        }
                    }
                }
            }
        },
        refresh() {
            this.data.refresh = this.$helpers.randid();
            this.flexContainer.refresh = this.$helpers.randid();
        },
        addSection() {
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.$parent.sections.splice(index, 0, {
                config: {},
                columns: []
            });

            this.$parent.indexofnew = index;
            this.over = false;
        },
        moveSection(e, position) {
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            const sections = this.$parent.sections.splice(index, 1);
            const newIndex = position === 'prev' ? index -1 : index + 1;
            this.$parent.sections.splice(newIndex, 0, sections[0]);
            const section = this.sections.find((section) => section.id == this.data.id);
            this.$store.dispatch("history/addStack", {
                type: "section",
                index: index,
                data: section,
                section_id: this.data.id,
                action: "delete"
            });
            setTimeout(() => {
                const html = this.idoc().querySelector('html');
                const element =  this.$refs.wrapper;
                const elementRect = element.getBoundingClientRect();
                const absoluteElementTop = elementRect.top + window.pageYOffset;
                const middle = absoluteElementTop - (html.offsetHeight / 2);

                this.scroll(middle);
            }, 100)

        },
        dropIn(current, pos) {
            if(['section', 'grid'].includes(current.is)) {
                const index = this.stack.findIndex((s) => s.id == this.section_id);
                const dropData = current.dropOut();
                if (dropData?.isLibrarySection) {
                    const insertOffset = this.dropPos === 'bottom' ? 1 : 0;
                    this.$store.dispatch('library/insertPost', {
                        id: dropData.id,
                        dragInsertIndex: index + insertOffset
                    });
                } else {
                    this.stack.splice(index + pos, 0, dropData);
                }
                return;
            }
            if(this.is == 'blockFlex') {
                let { parent_id, index } = getIdParentAndIndex(current);

                let indexAdd = this.stack.findIndex((s) => s.id == this.data.id);
                if(this.dragPosition == 'bottom'){
                    indexAdd +=1;
                }
                if(!current.data.id) {
                    current.data.id = this.$helpers.randid();
                    current.data.IDInit = true;
                }
                this.$store.dispatch('history/addStack', {
                    type: 'block',
                    index: index,
                    data:  current.data,
                    section_id: this.section_id,
                    parent_id,
                    action: 'moved'
                });
                this.stack.splice(indexAdd, 0, current.dropOut());
            }
            else {
                if (this.section_id && this.sections?.length) {
                    const { parent_id, index } = getIdParentAndIndex(current);
                    if(!current.data.id) {
                        current.data.id = this.$helpers.randid();
                        current.data.IDInit = true;
                    }
                    this.$store.commit('builder/setStatusDuplicate', true);
                    let payload = {
                        type: 'block',
                        data: current.data,
                        section_id: this.section_id,
                        action: "moved",
                        parent_id: parent_id,
                        index: index
                    }
                    this.timmerInsert = setTimeout(() => {
                        this.$store.commit('builder/setStatusDuplicate', false);
                    }, 500);
                    this.$store.dispatch('history/addStack', payload);
                }
                this.data.blocks.splice(this.data.blocks.length, 0, current.dropOut());
            }
        },
        dropOut() {
            if (this.data.id == this.editingElement?.data?.id) {
                setTimeout(() => {
                    this.$store.dispatch('builder/setEditingElement', null);
                }, 50);
            }
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                new_index = realIndex > -1 ? realIndex : this.index;
            if (this.is == 'section') {
                const section = this.sections.find((section) => section.id == this.data.id);
                this.$store.dispatch("history/addStack", {
                    type: "section",
                    index: new_index,
                    data: section,
                    section_id: this.data.id,
                    action: "delete"
                });
            }
            return this.stack.splice(new_index, 1)[0];
        },
        startDragPadding(e, name) {
            this.position = e['clientY'];
            this.paddingPosition = name;
            this.idoc().onmouseup = this.onMouseUp;
            this.idoc().onmousemove = this.onMouseMove;
        },
        handleEnterAdd() {
            const form = this.$refs.settingsAdd.closest('form.ecom-row');
            if(form) form.style.zIndex = 3;
        },
        handleLeaveAdd() {
            const form = this.$refs.settingsAdd.closest('form.ecom-row');
            if(form) form.style.zIndex = 1;
        },
        addSectionAfter() {
            // if(this.isLiteMode){
            //     this.openLibrarySection();
            // }else{
            // }
            let realIndex= this.stack.findIndex((s) => s.id == this.data.id),
                index = realIndex > -1 ? realIndex : this.index;
            this.$parent.sections.splice(realIndex + 1, 0, {
                config: {},
                columns: []
            });

            this.$parent.indexofnew = realIndex + 1;
            this.over = false;
        },
        createStyle() {
            if(this.$refs?.wrapper) {
                this.$helpers.addStyle2Component(this.$refs?.wrapper, this.data);
            }
        },
        insertCol() {
            let payload;
            if (this.data.blocks.length < 1) {
                let id1 = this.$helpers.randid(),
                    id2 = this.$helpers.randid();
                this.data.blocks.push(
                    {
                        name: 'flexContainer',
                        title: this.$t('flex_container'),
                        id: id1,
                    }
                );
                this.data.blocks.push(
                    {
                        name: 'flexContainer',
                        title: this.$t('flex_container'),
                        id: id2,
                    }
                );
                payload = {
                    type: 'blockFlex',
                    multiple: true,
                    ids: [id1, id2],
                    section_id: this.section_id,
                    action: "insertColumn"
                }
            }
            else {
                let id = this.$helpers.randid();
                let data = {
                    name: 'flexContainer',
                    title: this.$t('flex_container'),
                    id: id,
                }
                this.data.blocks.push(data);
                payload = {
                    type: 'blockFlex',
                    multiple: false,
                    id: id,
                    section_id: this.section_id,
                    action: "insertColumn"
                }
            }
            this.$store.commit('builder/setStatusDuplicate', true);

            this.timmerInsert = setTimeout(() => {
                this.$store.commit('builder/setStatusDuplicate', false);
            }, 500);
            this.$store.dispatch('history/addStack', payload);
        },
        placehover(e) {
            if (this.isFullScreen || !this.canDrop || !this.isDragging || this.inGroup) {
                return;
            }
            let pos = e.target.classList.contains('placeholder__top') ? 'top' : 'bottom';
            this.$store.commit('builder/setDropTo', this);
            this.$store.commit('builder/setDropPos', pos);
            this.placeholder = pos;
        },
        edit(){
            this.editFlexContainer();
        },
        duplicate() {
            let data = this.$helpers.generateElementId(this.cloneData());

            let height = this.$refs.wrapper.offsetHeight;
            if (this.is == 'section') {
                const index = this.stack.findIndex((s) => s.id == this.section_id);
                this.stack.splice(index + 1, 0, data);
                this.$store.dispatch('history/addStack', {
                    type: 'section',
                    index: index + 1,
                    data:  data,
                    section_id: data.id,
                    action: 'add'
                });
            } else if (this.is == 'blockFlex') {
                if(this.inGrid) {
                    let clone = this.$helpers.generateElementId(this.cloneData());
                    const grid = this.findGridParent();
                    if (!grid || !grid.data || !grid.data.blocks) {
                        return;
                    }
                    try {

                        // Cập nhật title nếu có
                        if (clone.title) {
                            clone.title = clone.title.replace(/(\([\d]*\))|$/, (...m) => {
                                if (m[1]) return "(" + (parseInt(m[1]) + 1) + ")";
                                else return "(1)";
                            });
                        }
                        const containerWidth = grid?.containerWidth || grid?.width || 1200;

                        // Cập nhật layout cho tất cả breakpoints với vị trí hợp lý
                        if (clone.layouts) {
                            Object.keys(clone.layouts).forEach((breakpoint) => {
                                if (["desktop", "tablet", "mobile"].includes(breakpoint) && clone.layouts[breakpoint])  {
                                    // Lấy giá trị hiện tại
                                    const currentLeft = parseFloat(clone.layouts[breakpoint].left); // %
                                    const currentWidth = parseFloat(clone.layouts[breakpoint].width); // px
                                    const currentTop = parseFloat(clone.layouts[breakpoint].top); // px

                                    // Tính phần trăm chiếm dụng của width
                                    const widthPercent = (currentWidth / containerWidth) * 100;

                                    // Tính không gian còn lại bên phải
                                    const spaceRight = 100 - (currentLeft + widthPercent);

                                    // Kiểm tra không gian và quyết định dịch chuyển
                                    if (spaceRight >= 2) {
                                        // Nếu bên phải đủ không gian, dịch sang phải 2%
                                        clone.layouts[breakpoint].left = currentLeft + 2;
                                    } else if (currentLeft >= 2) {
                                        // Nếu bên trái đủ không gian, dịch sang trái 2%
                                        clone.layouts[breakpoint].left = currentLeft - 2;
                                    }
                                    // Nếu không đủ không gian bên nào, giữ nguyên vị trí ngang

                                    // Luôn dịch chuyển xuống dưới 20px
                                    clone.layouts[breakpoint].top = currentTop + 20;
                                }
                            });
                        }
                        // Thêm vào blocks
                        const index = grid.data.blocks.findIndex((b) => b.id === this.data.id);
                        if (index > -1) {
                            grid.data.blocks.splice(index + 1, 0, clone);
                        } else {
                            grid.data.blocks.push(clone);
                        }

                        // Emit sự kiện để cập nhật grid
                        this.eventBus.emit("update-grid-layout", {
                            sectionId: this.section_id,
                            blocks: grid.data.blocks
                        });
                    } catch (error) {
                        console.error("Lỗi khi duplicate:", error);
                    }
                }
                else {
                    this.stack.splice(this.index + 1, 0, data);
                }
                const {parent_id} = getIdParentAndIndex(this)
                this.$store.dispatch('history/addStack', {
                    type: 'block',
                    index: this.index + 1,
                    data:  data,
                    section_id: this.section_id,
                    parent_id: parent_id,
                    action: 'duplicated',
                });
            }
            this.scroll(height);
        },
        paste(clipboard) {
            if(!clipboard) {
                return;
            }
            let index = this.stack.findIndex((s) => s.id == this.section_id);
            let data = this.$helpers.copy(clipboard.data);
            data = this.$helpers.generateElementId(data);
            switch (clipboard.is) {
                case 'section':
                case 'grid':
                    if (this.is == 'section') {
                        this.stack.splice(index + 1, 0, data);
                        this.$store.dispatch('history/addStack', {
                            type: 'section',
                            index: index + 1,
                            data:  data,
                            section_id: data.id,
                            action: 'add'
                        });
                        this.scroll(this.$refs.wrapper.offsetHeight);
                    }
                    break;
                case 'blockFlex':
                case 'block':
                    index = this.data.blocks.length;
                    this.$store.dispatch('history/addStack', {
                        type: 'block',
                        index: index,
                        data:  data,
                        section_id: this.section_id,
                        parent_id: this.data.id,
                        action: 'duplicated',
                    });
                    if ((data.row || data.group) && this.is == 'blockFlex') {
                        this.$parent.$parent.blocks.splice(this.$parent.index + 1, 0, data);
                    } else {
                        this.data.blocks.push(data);
                    }
                    this.scroll(this.$refs.wrapper.offsetHeight / 2);
                    break;
            }
        },
    },
    watch: {
        "data.settings.items_per_row": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val) {
                    const direction = this.data.settings['flex-direction'];
                    if(!direction || direction === 'column' || direction === 'column-reverse') {
                        this.data.settings['flex-direction'] = 'row';
                    }
                    this.data.settings['flex-wrap'] = 'wrap';
                }
            }
        },
        "data.settings.items_per_row__tablet": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val) {
                    const direction = this.data.settings['flex-direction__tablet'];
                    if(!direction || direction === 'column' || direction === 'column-reverse') {
                        this.data.settings['flex-direction__tablet'] = 'row';
                    }
                    this.data.settings['flex-wrap__tablet'] = 'wrap';
                }
            }
        },
        "data.settings.items_per_row__mobile": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val) {
                    const direction = this.data.settings['flex-direction__mobile'];
                    if(!direction || direction === 'column' || direction === 'column-reverse') {
                        this.data.settings['flex-direction__mobile'] = 'row';
                    }
                    this.data.settings['flex-wrap__mobile'] = 'wrap';
                }
            }
        },
        "data.settings.flex-direction": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val) {
                    if(val === 'column' || val === 'column-reverse') {
                        this.data.settings.items_per_row = '';
                    }
                }
            }
        },
        "data.settings.flex-direction__tablet": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val === 'column' || val === 'column-reverse') {
                    this.data.settings.items_per_row__tablet = '';
                }
            }
        },
        "data.settings.flex-direction__mobile": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val === 'column' || val === 'column-reverse') {
                    this.data.settings.items_per_row__mobile = '';
                }
            }
        },
        "data.settings.flex-wrap": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val && val === 'nowrap') {
                    this.data.settings.items_per_row = '';
                }
            }
        },
        "data.settings.flex-wrap__tablet": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val === 'nowrap') {
                    this.data.settings.items_per_row__tablet = '';
                }
            }
        },
        "data.settings.flex-wrap__mobile": {
            deep: true,
            immediate: true,
            handler(val) {
                if(val === 'nowrap') {
                    this.data.settings.items_per_row__mobile = '';
                }
            }
        }
    },
    mounted() {
        if(this.$refs.video && this.data?.settings?.autoplay) {
            this.$refs.video.setAttribute('muted', '');
        }
        if (this.exporting === false) {
            //this.stacks[this.data.id] = this;
            this.instanceStore.register(this.data.id, this);
        }

        if(this.data.style?.background?.backgroundnormalmode?.classic && this.data.style?.background?.backgroundnormalmode?.classic['background-image']) {
            const img_bg = this.data.style.background.backgroundnormalmode.classic['background-image'];
           if(img_bg.includes('ecom-need-replace')) {
            this.needReplaceBg = true;
           }
        }
        if(this.data?.inGrid && this.exporting) {
            const target = this.data;

            if (!target.css) {
                target.css = {};
            }
            if (!target.css.style) {
                target.css.style = {};
            }
            if (!target.css.style.style) {
                target.css.style.style = '';
            }
            target.css.style.style += this.gridLayoutStyle;
        }


    },
}
</script>
