<template>
    <!-- compact variant: single line — cost + usage badge -->
    <div v-if="variant === 'compact'" class="flex items-center gap-1.5 min-w-0" :class="align === 'right' ? 'justify-end' : 'justify-start'">
        <span v-if="estCost > 0" class="inline-flex items-center gap-1 text-[11px] leading-none font-medium text-[#616161] whitespace-nowrap">
            <svg width="10" height="10" viewBox="0 0 18 18" fill="none" class="flex-none"><path d="M9 1.6l1.9 4.5 4.9.4-3.7 3.2 1.1 4.8L9 12l-4.2 2.5 1.1-4.8L2.2 6.5l4.9-.4L9 1.6z" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/></svg>
            {{ $t(estCost > 1 ? 'credits_count' : 'credit_count', {count: estCost}) }}
        </span>
        <span v-if="estCost > 0" class="text-[#c9c9c9] text-[10px] leading-none">·</span>
        <span
            class="rounded-md px-1.5 py-0.5 text-[10px] leading-none font-medium cursor-default whitespace-nowrap"
            :data-tooltip="tooltip ? $t(type === 'image' ? 'image_credits_used_limit' : 'ai_credits_used_limit') + ' ' + $helpers.formatNumber(aiCredits.used) + ' / ' + $helpers.formatNumber(aiCredits.max) : undefined"
            :data-tooltip-location="tooltipPosition"
            :data-tooltip-zindex="tooltipZIndex || undefined"
            :class="{
                'bg-green-100 text-[#29845A]': creditUsagePercentage < 0.75,
                'bg-yellow-100 text-[#996F00]': creditUsagePercentage >= 0.75 && creditUsagePercentage < 0.85,
                'bg-orange-200 text-[#8A4B0F]': creditUsagePercentage >= 0.85 && creditUsagePercentage < 0.95,
                'bg-red-100 text-[#D72C0D]': creditUsagePercentage >= 0.95,
            }"
        >{{ $helpers.formatNumberAbbreviated(aiCredits.used) }}/{{ $helpers.formatNumberAbbreviated(aiCredits.max) }}</span>
        <button v-if="creditUsagePercentage >= 0.95" @click.prevent="openPricing" class="text-[#D72C0D] text-[10px] leading-none font-medium hover:underline transition shrink-0">{{ $t('buy_more') }}</button>
    </div>

    <!-- minimal variant: cost only + info icon (usage in tooltip) -->
    <div v-else-if="variant === 'minimal'" class="flex items-center gap-1 min-w-0" :class="align === 'right' ? 'justify-end' : 'justify-start'">
        <template v-if="creditUsagePercentage < 0.95">
            <span v-if="estCost > 0" class="text-[11px] leading-none font-medium text-[#616161] whitespace-nowrap">
                {{ $t(estCost > 1 ? 'ai_est_credits' : 'ai_est_credit', {count: estCost}) }}
            </span>
            <span
                v-if="tooltip"
                class="w-3.5 h-3.5 flex items-center justify-center rounded-full text-[#8a8a8a] hover:text-[#616161] cursor-default flex-none"
                :data-tooltip="$t(type === 'image' ? 'image_credits_used_limit' : 'ai_credits_used_limit') + ' ' + $helpers.formatNumber(aiCredits.used) + ' / ' + $helpers.formatNumber(aiCredits.max)"
                :data-tooltip-location="tooltipPosition"
                :data-tooltip-zindex="tooltipZIndex || undefined"
            >
                <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="6.25" stroke="currentColor" stroke-width="1.2"/><path d="M8 7.2v3.3" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/><circle cx="8" cy="5.1" r="0.8" fill="currentColor"/></svg>
            </span>
        </template>
        <template v-else>
            <span class="text-[11px] leading-none font-medium text-[#D72C0D] whitespace-nowrap">{{ $t('low_credits') }}</span>
            <button @click.prevent="openPricing" class="text-[#D72C0D] text-[11px] leading-none font-medium hover:underline transition shrink-0">{{ $t('buy_more') }}</button>
        </template>
    </div>

    <!-- bar variant: compact estimate + mini progress bar -->
    <div v-else-if="variant === 'bar'" class="flex flex-col gap-1 min-w-0" :class="align === 'right' ? 'items-end' : 'items-start'">
        <div v-if="estCost > 0" class="text-[11px] leading-none font-medium text-[#616161]">
            {{ $t(estCost > 1 ? 'ai_est_credits' : 'ai_est_credit', {count: estCost}) }}
        </div>
        <div class="flex items-center gap-1.5">
            <div
                class="w-[72px] h-[4px] rounded-full bg-[#e3e3e3] overflow-hidden cursor-default"
                :data-tooltip="tooltip ? $t(type === 'image' ? 'image_credits_used_limit' : 'ai_credits_used_limit') + ' ' + $helpers.formatNumber(aiCredits.used) + ' / ' + $helpers.formatNumber(aiCredits.max) : undefined"
                :data-tooltip-location="tooltipPosition"
                :data-tooltip-zindex="tooltipZIndex || undefined"
            >
                <div
                    class="h-full rounded-full transition-all"
                    :style="{ width: Math.min(creditUsagePercentage * 100, 100) + '%' }"
                    :class="{
                        'bg-[#29845A]': creditUsagePercentage < 0.75,
                        'bg-[#B98900]': creditUsagePercentage >= 0.75 && creditUsagePercentage < 0.85,
                        'bg-[#E07B39]': creditUsagePercentage >= 0.85 && creditUsagePercentage < 0.95,
                        'bg-[#D72C0D]': creditUsagePercentage >= 0.95,
                    }"
                ></div>
            </div>
            <span class="text-[10px] leading-none text-[#8a8a8a] whitespace-nowrap">
                {{ $helpers.formatNumberAbbreviated(aiCredits.used) }}/{{ $helpers.formatNumberAbbreviated(aiCredits.max) }}
            </span>
            <button v-if="creditUsagePercentage >= 0.95" @click.prevent="openPricing" class="text-[#D72C0D] text-[10px] leading-none font-medium hover:underline transition shrink-0">{{ $t('buy_more') }}</button>
        </div>
    </div>

    <div v-else class="flex flex-col gap-0.5" :class="align === 'right' ? 'items-end' : 'items-start'">
        <div v-if="estCost > 0" class="flex items-center gap-1 text-[10px] leading-none opacity-80 font-normal">
            <span>{{ $t(estCost > 1 ? 'ai_est_credits' : 'ai_est_credit', {count: estCost}) }}{{ costUnit ? '/' + costUnit : '' }}</span>
            <span
                v-if="costInfo"
                class="w-3.5 h-3.5 flex items-center justify-center rounded-full border border-current text-[9px] leading-none font-semibold opacity-70 hover:opacity-100 transition cursor-help shrink-0"
                :data-tooltip="costInfo"
                :data-tooltip-location="tooltipPosition"
                :data-tooltip-zindex="tooltipZIndex || undefined"
            >?</span>
        </div>
        <div class="flex items-center gap-2" :class="align === 'right' ? 'justify-end' : 'justify-start'">
            <div class="flex items-center gap-1 text-[0.625rem] leading-[1] opacity-50 transition hover:opacity-100" :class="align === 'right' ? 'justify-end' : 'justify-start'">
                <span>{{ $t(type === 'image' ? 'image_credits_used_limit' : 'ai_credits_used_limit') }}</span>
                <span class="rounded-md px-1.5 py-0.5 font-medium cursor-pointer"
                    :data-tooltip="tooltip ? $helpers.formatNumber(aiCredits.used) + ' / ' + $helpers.formatNumber(aiCredits.max) : undefined"
                    :data-tooltip-location="tooltipPosition"
                    :data-tooltip-zindex="tooltipZIndex || undefined"
                    :class="{
                        'bg-green-100': creditUsagePercentage < 0.75,
                        'bg-yellow-100': creditUsagePercentage >= 0.75 && creditUsagePercentage < 0.85,
                        'bg-orange-200': creditUsagePercentage >= 0.85 && creditUsagePercentage < 0.95,
                        'bg-red-100': creditUsagePercentage >= 0.95,
                    }">
                    <span>
                        {{ numberFormat === 'abbreviated' ? $helpers.formatNumberAbbreviated(aiCredits.used) : $helpers.formatNumber(aiCredits.used) }}
                    </span> / <span>
                        {{ numberFormat === 'abbreviated' ? $helpers.formatNumberAbbreviated(aiCredits.max) : $helpers.formatNumber(aiCredits.max) }}
                    </span>
                </span>
            </div>
            <button v-if="creditUsagePercentage >= 0.95" @click.prevent="openPricing" class="text-red-500 text-[10px] font-normal hover:underline transition shrink-0">{{ $t('buy_more') }} </button>
        </div>
    </div>
</template>

<script lang="ts">
import { PropType } from 'vue';

export default {
    props: {
        type: {
            type: String as PropType<'assistant' | 'image'>,
            default: 'assistant'
        },
        numberFormat: {
            type: String as PropType<'abbreviated' | 'full'>,
            default: 'abbreviated'
        },
        tooltip: {
            type: Boolean,
            default: true
        },
        tooltipPosition: {
            type: String as PropType<'top' | 'bottom'>,
            default: 'bottom'
        },
        estCost: {
            type: Number,
            default: 0
        },
        align: {
            type: String as PropType<'left' | 'right'>,
            default: 'left'
        },
        costUnit: {
            type: String,
            default: ''
        },
        variant: {
            type: String as PropType<'default' | 'bar' | 'compact' | 'minimal'>,
            default: 'default'
        },
        // opt-in: short tooltip explaining what the credits of this action are spent on
        costInfo: {
            type: String,
            default: ''
        },
        // raise the shared tooltip above a custom stacking context (e.g. inside a modal)
        tooltipZIndex: {
            type: [String, Number],
            default: ''
        }
    },
    computed: {
        aiCredits() {
            switch (this.type) {
                case 'image':
                    return this.$store.getters['ai/aiImageTokens'];
                default:
                    return this.$store.getters['ai/aiAssistantTokens'];
            }
        },
        creditUsagePercentage() {
            return this.aiCredits.max > 0 ? this.aiCredits.used / this.aiCredits.max : 1;
        }
    },
    methods: {
        openPricing() {
            this.$store.dispatch('upgrade/showUpgradePopup', {
                feature_key: 'ai_credits',
                source_location: 'ai_tokens_widget',
            });
        }
    }
}
</script>
