/**
 *
 *  Handle Editor funtion
 *
 */
import { store } from "@/store";
import { htmlTags, unwrapNode } from "@/utils/dom";

export const textHelper = {
    insertHtmlTag: function (selection, inline = false, oldHeadingTag = "") {
        const action = selection.action;
        const range = selection.range;
        if (!range) return;
        let tag = "";

        if (!selection.range || !action) return;

        switch (action) {
            case "p":
                tag = "p";
                break;
            case "bold":
                tag = "strong";
                break;
            case "italic":
                tag = "em";
                break;
            case "underline":
                tag = "u";
                break;
            case "h1":
                tag = "h1";
                break;
            case "h2":
                tag = "h2";
                break;
            case "h3":
                tag = "h3";
                break;
            case "h4":
                tag = "h4";
                break;
            case "h5":
                tag = "h5";
                break;
            case "h6":
                tag = "h6";
                break;
            case "code":
                tag = "code";
                break;
            default:
                break;
        }

        if (!tag) return;

        if (htmlTags.isBlockSpecial(tag)) {
            let node = range.commonAncestorContainer
                ? range.commonAncestorContainer
                : range.parentElement
                ? range.parentElement()
                : range.item(0);
            let inside = false;

            if (
                !node ||
                node.nodeName == "BODY" ||
                (node.nodeType == Node.ELEMENT_NODE &&
                    node.getAttribute("contenteditable") == "true")
            ) {
                let content = range.cloneContents();
                if (
                    content.childNodes.length == 1 &&
                    content.childNodes[0].nodeType == Node.ELEMENT_NODE &&
                    htmlTags.isBlockSpecial(content.childNodes[0].tagName)
                ) {
                    node = content.childNodes[0];
                    inside = true;
                } else {
                    return;
                }
            }

            let refNode = node;
            while (node.nodeType == 3 || htmlTags.isInline(node.nodeName)) {
                node = node.parentNode;
            }
            if (
                refNode.nodeType == Node.TEXT_NODE &&
                (node.nodeName == "BODY" || node.getAttribute("contenteditable") == "true")
            ) {
                const tagDom = document.createElement(tag);
                node.insertBefore(tagDom, refNode);
                tagDom.appendChild(refNode);
                range.selectNode(refNode);
                return;
            }
            if (node.nodeName.toLowerCase() == tag) {
                return;
            }
            // Replace the node
            const tagDom = document.createElement(tag);
            while (node.childNodes[0]) {
                tagDom.appendChild(node.childNodes[0]);
            }
            if (inside) {
                range.deleteContents();
                range.insertNode(tagDom);
            } else {
                let nodeParent = node.parentNode;
                nodeParent.insertBefore(tagDom, node);
                nodeParent.removeChild(node);
            }
            range.selectNode(tagDom);
        } else if (htmlTags.isInline(tag)) {
            let content = range.cloneContents();
            if (range.startContainer == range.endContainer) {
                const node = range.startContainer;
                let refNode = node.nodeType == Node.ELEMENT_NODE ? node : node.parentNode;

                if (refNode.nodeName.toLowerCase() != tag) {
                    refNode = refNode.closest(tag);
                }

                // Check the parent
                if (refNode) {
                    // unwrap the node
                    unwrapNode(refNode, range, false);
                } else {
                    let cnode = content.querySelector(tag);
                    if (cnode) {
                        if (content.childNodes.length == 1) {
                            let directChild = content.childNodes[0];

                            if (
                                directChild.nodeType == Node.ELEMENT_NODE &&
                                directChild.nodeName.toLowerCase() == tag
                            ) {
                                range.deleteContents();
                                unwrapNode(directChild, range, false);
                            } else {
                                let parentBlockNode;
                                if (
                                    htmlTags.isBlock(directChild.nodeName) ||
                                    htmlTags.isBlockSpecial(directChild.nodeName)
                                ) {
                                    parentBlockNode = directChild;
                                }
                                while (directChild.childNodes.length == 1) {
                                    directChild = directChild.childNodes[0];
                                    if (
                                        directChild.nodeType != Node.ELEMENT_NODE ||
                                        directChild.nodeName.toLowerCase() == tag
                                    ) {
                                        break;
                                    }
                                }
                                if (
                                    directChild.nodeType == Node.ELEMENT_NODE &&
                                    directChild.nodeName.toLowerCase() == tag
                                ) {
                                    let descendantParent = directChild.parentNode;
                                    let descendant = unwrapNode(directChild, range, true);
                                    descendantParent.insertBefore(descendant, directChild);
                                    descendantParent.removeChild(directChild);
                                    content.normalize();
                                    let outerEl = document.createDocumentFragment();
                                    while (content.childNodes[0]) {
                                        outerEl.appendChild(content.childNodes[0]);
                                    }
                                    range.deleteContents();
                                    range.insertNode(outerEl);
                                } else {
                                    let descendantParent = cnode.parentNode;
                                    let descendant = unwrapNode(cnode, range, true);
                                    descendantParent.insertBefore(descendant, cnode);
                                    descendantParent.removeChild(cnode);
                                    content.normalize();

                                    let outerEl = document.createElement(tag);
                                    if (parentBlockNode) {
                                        while (parentBlockNode.childNodes[0]) {
                                            outerEl.appendChild(parentBlockNode.childNodes[0]);
                                        }
                                    } else {
                                        while (content.childNodes[0]) {
                                            outerEl.appendChild(content.childNodes[0]);
                                        }
                                    }

                                    range.deleteContents();
                                    if (parentBlockNode) {
                                        parentBlockNode.replaceChildren(outerEl);
                                        range.insertNode(parentBlockNode);
                                    } else {
                                        range.insertNode(outerEl);
                                    }

                                    range.setStartBefore(outerEl);
                                    range.setEndAfter(outerEl);
                                }
                            }
                        } else {
                            let outerEl = document.createElement(tag);
                            while (content.childNodes[0]) {
                                let _cnode = content.childNodes[0];
                                if (_cnode.nodeType == Node.ELEMENT_NODE) {
                                    if (_cnode.nodeName.toLowerCase() == tag) {
                                        outerEl.appendChild(unwrapNode(_cnode, range, true));
                                    } else {
                                        let innerEls = _cnode.querySelectorAll(tag);
                                        innerEls.forEach((innerEl) => {
                                            let _pnode = innerEl.parentNode;
                                            _pnode.insertBefore(
                                                unwrapNode(innerEl, range, true),
                                                innerEl
                                            );
                                            _pnode.removeChild(innerEl);
                                        });
                                        outerEl.appendChild(_cnode.cloneNode(true));
                                    }
                                } else {
                                    outerEl.appendChild(_cnode.cloneNode(true));
                                }
                                content.removeChild(_cnode);
                            }
                            range.deleteContents();
                            range.insertNode(outerEl);
                            let outerParent = outerEl.parentNode;
                            while (outerParent?.nodeType != Node.ELEMENT_NODE) {
                                outerParent = outerParent.parentNode;
                            }
                            outerEl.parentNode.normalize();
                        }
                    } else if (content.childNodes.length) {
                        const el = document.createElement(tag);
                        let _content = range.extractContents();
                        while (_content.childNodes[0]) {
                            el.appendChild(_content.childNodes[0]);
                        }
                        range.insertNode(el);
                    } else {
                        // Empty selection
                    }
                }
            } else {
                let pnode =
                    range.commonAncestorContainer.nodeType == Node.ELEMENT_NODE
                        ? range.commonAncestorContainer
                        : range.commonAncestorContainer.parentNode;

                if (pnode.nodeName.toLowerCase() == tag) {
                    unwrapNode(pnode, range, false);
                } else if (pnode.closest(tag)) {
                    let ancestorNode = pnode.closest(tag);
                    unwrapNode(ancestorNode, range, false);
                } else {
                    let content = range.cloneContents();
                    let outerEl = document.createElement(tag);
                    let blockInc = false;
                    while (content.childNodes[0]) {
                        let cnode = content.childNodes[0];
                        if (cnode.nodeType == Node.ELEMENT_NODE) {
                            if (
                                htmlTags.isBlock(cnode.nodeName) ||
                                htmlTags.isBlockSpecial(cnode.nodeName)
                            ) {
                                if (!blockInc) {
                                    blockInc = true;
                                }
                                let xBlock = unwrapNode(cnode, range, true);
                                let xFragment = document.createDocumentFragment();
                                let unwrapedTags = htmlTags.block;
                                unwrapedTags.push(...htmlTags.blockSpecial);
                                unwrapedTags.push(tag);
                                if (xBlock.querySelector(unwrapedTags.join(","))) {
                                    if (!blockInc) {
                                        blockInc = true;
                                    }
                                    let _outerEl = document.createDocumentFragment();
                                    while (xBlock.childNodes[0]) {
                                        let _cnode = xBlock.childNodes[0];
                                        if (_cnode.nodeType == Node.ELEMENT_NODE) {
                                            if (
                                                unwrapedTags.indexOf(
                                                    _cnode.nodeName.toLowerCase()
                                                ) >= 0
                                            ) {
                                                _outerEl.appendChild(
                                                    unwrapNode(_cnode, range, true)
                                                );
                                            } else {
                                                let innerEls = _cnode.querySelectorAll(
                                                    unwrapedTags.join(",")
                                                );
                                                innerEls.forEach((innerEl) => {
                                                    let _pnode = innerEl.parentNode;
                                                    _pnode.insertBefore(
                                                        unwrapNode(innerEl, range, true),
                                                        innerEl
                                                    );
                                                    _pnode.removeChild(innerEl);
                                                });
                                                _outerEl.appendChild(_cnode.cloneNode(true));
                                            }
                                        } else {
                                            _outerEl.appendChild(_cnode.cloneNode(true));
                                        }
                                        xBlock.removeChild(_cnode);
                                    }
                                    xFragment.appendChild(_outerEl);
                                } else {
                                    xFragment.appendChild(xBlock);
                                }
                                outerEl.appendChild(xFragment);
                            } else {
                                if (cnode.nodeName.toLowerCase() == tag) {
                                    outerEl.appendChild(unwrapNode(cnode, range, true));
                                } else {
                                    let innerEls = cnode.querySelectorAll(tag);
                                    innerEls.forEach((innerEl) => {
                                        let _pnode = innerEl.parentNode;
                                        _pnode.insertBefore(
                                            unwrapNode(innerEl, range, true),
                                            innerEl
                                        );
                                        _pnode.removeChild(innerEl);
                                    });
                                    outerEl.appendChild(cnode.cloneNode(true));
                                }
                            }
                        } else {
                            outerEl.appendChild(cnode.cloneNode(true));
                        }
                        content.removeChild(cnode);
                    }

                    range.deleteContents();
                    if (blockInc) {
                        let autop = document.createElement("p");
                        autop.appendChild(outerEl);
                        range.insertNode(autop);
                    } else {
                        range.insertNode(outerEl);
                    }
                }
            }
        } else if (selection?.state[action] || oldHeadingTag) {
            // Un tag
            const domFragement = range.cloneContents();
            if (oldHeadingTag) {
                tag = oldHeadingTag;
            }
            let node = domFragement.querySelectorAll(tag);

            if (node.length === 0) {
                // If selection range inside node tag
                let currentNode = selection.selection.focusNode;

                //Find node of tag
                while (currentNode && currentNode !== "BODY") {
                    if (currentNode?.tagName === tag.toUpperCase()) {
                        node = currentNode;
                        break;
                    }

                    currentNode = currentNode?.parentNode;
                }

                if (!currentNode) return;

                if (oldHeadingTag && currentNode) {
                    const parent = node.parentNode;
                    const tagDom = document.createElement(action);
                    tagDom.innerHTML = currentNode.innerHTML;

                    parent.insertBefore(tagDom, node);

                    parent.removeChild(node);
                    //range.deleteContents();
                    if (inline) {
                        store.commit("builder/setTextEditor", {
                            open: false
                        });
                    }
                    return;
                }

                if (domFragement.textContent.trim() === currentNode?.textContent.trim()) {
                    const parent = node.parentNode;
                    while (node.firstChild) parent.insertBefore(node.firstChild, node);
                    parent.removeChild(node);
                    range.deleteContents();
                    if (inline) {
                        store.commit("builder/setTextEditor", {
                            open: false
                        });
                    }
                } else {
                    const temp = document.createElement("span"),
                        nodeHTML = currentNode.innerHTML; //var temp: can not get innerHTML of domFragment, need insert to dom then get innerHTML.
                    temp.appendChild(range.cloneContents());

                    let before = nodeHTML.slice(0, range.startOffset),
                        after = nodeHTML.slice(
                            range.startOffset + temp.innerHTML.length,
                            nodeHTML.length
                        );
                    let html = `<${tag}>${before}</${tag}>${temp.innerHTML}<${tag}>${after}</${tag}>`;

                    const span = document.createElement("span");
                    span.innerHTML = html;

                    //Replace node with new node
                    const parent = node.parentNode;

                    while (span.firstChild) parent.insertBefore(span.firstChild, node);
                    parent.removeChild(node);
                    range.deleteContents();
                    if (inline) {
                        store.commit("builder/setTextEditor", {
                            open: false
                        });
                    }
                }
            } else {
                const parent = node[0].parentNode;
                if (oldHeadingTag) {
                    const tagDom = document.createElement(action);
                    tagDom.innerHTML = node[0].innerHTML;
                    parent.insertBefore(tagDom, node[0]);
                    parent.removeChild(node[0]);
                } else {
                    node.forEach((el) => {
                        while (el.firstChild) parent.insertBefore(el.firstChild, el);
                        parent.removeChild(el);
                    });
                }

                range.deleteContents();
                range.insertNode(parent);
            }
        } else {
            //Inser Tag
            const tagDom = document.createElement(tag);
            tagDom.appendChild(range.extractContents());
            range.insertNode(tagDom);
        }
    },

    inserColor: function (selection, color) {
        const range = selection.range;
        if (!range) return;
        const domFragement = range.cloneContents();
        let node = domFragement.querySelectorAll("font");

        if (node.length == 1 && node[0]?.tagName === "FONT") {
            // node[0].setAttribute("color", color);
            if (!node[0]?.style?.color) {
                node[0].setAttribute("style", `color: ${color};`);
            } else {
                node[0].style.color = color;
            }
            range.deleteContents();
            range.insertNode(node[0]);
        } else {
            let currentNode = selection.selection.focusNode;

            //Find node of tag
            while (currentNode && currentNode !== "BODY") {
                if (currentNode?.tagName === "FONT") {
                    node = currentNode;
                    break;
                }

                currentNode = currentNode?.parentNode;
            }

            if (currentNode && currentNode?.tagName === "FONT") {
                // currentNode.setAttribute("color", color);
                if (!currentNode.style.color) {
                    currentNode.setAttribute("style", `color: ${color};`);
                } else {
                    currentNode.style.color = color;
                }
                // const span = document.createElement('span');
                // span.innerHTML = currentNode.outerHTML;

                // //Replace node with new node
                // const parent = currentNode.parentNode

                // parent.insertBefore(span.firstChild, currentNode);
                // parent.removeChild(currentNode);
            } else {
                const tagDom = document.createElement("font");
                // tagDom.setAttribute("color", color);
                tagDom.setAttribute("style", `color: ${color};`);

                tagDom.appendChild(range.extractContents());
                range.insertNode(tagDom);
            }
        }
    },

    inserBackground: function (selection, color) {
        const range = selection.range;
        if (!range) return;
        const domFragement = range.cloneContents();
        let node = domFragement.querySelectorAll('span[style*="background-color"]');

        if (node.length == 1 && node[0]?.tagName === "SPAN") {
            node[0].style.backgroundColor = color;
            range.deleteContents();
            range.insertNode(node[0]);
        } else {
            let currentNode = selection.selection.focusNode;

            //Find node of tag
            while (currentNode && currentNode !== "BODY") {
                if (currentNode?.tagName === "SPAN" && currentNode?.style?.backgroundColor) {
                    node = currentNode;
                    break;
                }

                currentNode = currentNode?.parentNode;
            }

            if (currentNode && currentNode?.tagName === "SPAN") {
                currentNode.style.backgroundColor = color;
            } else {
                const tagDom = document.createElement("span");
                tagDom.style.backgroundColor = color;

                tagDom.appendChild(range.extractContents());
                range.insertNode(tagDom);
            }
        }
    },

    insertOrderedlist: function (selection, content, action) {
        const range = selection.range;
        if (!range) return;
        const tag = action === "insertorderedlist" ? "ol" : "ul",
            domFragement = range.cloneContents();

        if (selection?.state[action]) {
            let node = domFragement.querySelector(tag);
            let currentNode = selection.selection.focusNode;
            if (node) {
                let html = "";
                const childrens = node.querySelectorAll("li");
                childrens.length > 0 &&
                    childrens.forEach((li) => {
                        html += li.innerHTML + " ";
                    });

                const span = document.createElement("span");
                span.innerHTML = html;

                //Replace node with new node
                const parent = node.parentNode;

                while (span.firstChild) parent.insertBefore(span.firstChild, node);
                parent.removeChild(node);
                range.deleteContents();
            } else {
                //Find node of tag
                while (currentNode && currentNode !== "BODY") {
                    if (currentNode?.tagName === tag.toUpperCase()) {
                        node = currentNode;
                        break;
                    }

                    currentNode = currentNode?.parentNode;
                }
                if (currentNode) {
                    let html = "";
                    const childrens = currentNode.querySelectorAll("li");
                    childrens.length > 0 &&
                        childrens.forEach((li) => {
                            html += li.innerHTML + " ";
                        });

                    const span = document.createElement("span");
                    span.innerHTML = html;

                    //Replace node with new node
                    const parent = currentNode.parentNode;

                    while (span.firstChild) parent.insertBefore(span.firstChild, currentNode);
                    parent.removeChild(currentNode);
                    range.deleteContents();
                }
            }
        } else {
            const tagDom = document.createElement(tag),
                li = document.createElement("li");

            li.appendChild(range.extractContents());
            tagDom.appendChild(li);

            range.insertNode(tagDom);
        }
    },

    removeList: function (selection) {
        const range = selection.range;
        if (!range) return;
        let ancestor = range.commonAncestorContainer;
        if (ancestor.nodeType === Node.TEXT_NODE) {
            ancestor = ancestor.parentElement;
        }
        console.log(ancestor);
        if (ancestor) {
            const listElements = ancestor.querySelectorAll('ul, ol');

            listElements.forEach(list => {
                const liElements = list.querySelectorAll('li');
                
                liElements.forEach(li => {
                    const text = li.textContent;
                    const textNode = document.createTextNode(text);
                    list.parentNode.insertBefore(textNode, list);
                    li.remove();
                });
        
                list.remove();
            });
        }
    },

    removeFormat: function (selection) {
        const range = selection.range;
        if (!range) return;
        let ancestor = range.commonAncestorContainer;
        let content = range.cloneContents();
        // this.removeList(selection);
        const formatList = ["STRONG", "B", "EM", "I", "U", "FONT", "SPAN", "STRIKE", "SUB", "SUP", 'A'];

        if (
            ancestor.nodeType == Node.ELEMENT_NODE &&
            (ancestor.nodeName == "BODY" || ancestor.hasAttribute("contenteditable"))
        ) {
            if (content.childNodes.length == 1) {
                ancestor = content.childNodes[0];
            }
        }

        if (range.startContainer == range.endContainer) {
            let _found = false;
            if (
                content.childNodes.length == 1 &&
                content.childNodes[0].nodeType == Node.ELEMENT_NODE
            ) {
                let newContent;
                if (
                    htmlTags.isBlock(content.childNodes[0].nodeName) ||
                    htmlTags.isBlockSpecial(content.childNodes[0].nodeName)
                ) {
                    newContent = content.childNodes[0];
                    let xContent = document.createDocumentFragment();
                    newContent.childNodes.forEach((xnode) => {
                        let _xcontent = document.createTextNode(xnode.textContent);
                        xContent.appendChild(_xcontent);
                    });
                    xContent.normalize();
                    newContent.replaceChildren(...xContent.childNodes);
                } else {
                    newContent = document.createTextNode(content.childNodes[0].textContent);
                }
                range.deleteContents();
                range.insertNode(newContent);
            } else {
                while (
                    ancestor.nodeType != Node.ELEMENT_NODE ||
                    (ancestor.nodeName != "BODY" && ancestor.hasAttribute("contenteditable"))
                ) {
                    ancestor = ancestor.parentNode;
                    if (formatList.indexOf(ancestor.nodeName) >= 0) {
                        _found = true;
                        break;
                    }
                }
                if (_found) {
                    // Continue traverse to the top;
                    while (formatList.indexOf(ancestor.parentNode.nodeName) >= 0) {
                        ancestor = ancestor.parentNode;
                    }
                    let newContent = document.createTextNode(ancestor.textContent);
                    ancestor.parentNode.removeChild(ancestor);
                    range.deleteContents();
                    range.insertNode(newContent);
                }
            }
        } else {
            let content = range.extractContents();
            let newContent = document.createDocumentFragment();
            while (content.childNodes[0]) {
                let innerContent = document.createTextNode(content.childNodes[0].textContent);
                newContent.appendChild(innerContent);
                content.removeChild(content.childNodes[0]);
            }
            newContent.normalize();
            range.insertNode(newContent);
        }
        ["bold", "italic", "underline"].forEach((action) => {
            if (selection?.state[action]) {
                selection.state[action] = false;
            }
        });
        selection.selection.removeAllRanges();
    },

    insertLink: function (selection, link) {
        const range = selection.range;
        if (!range) return;
    
        const currentNode = selection.selection.focusNode;
        if (currentNode && ['A', 'I', 'U', 'B'].includes(currentNode.nodeName)) {
            currentNode.remove();
        }
    
        const isFirstCharacter = range.startOffset === 0;
            if (!isFirstCharacter) {
            range.insertNode(document.createTextNode(' '));
        }
            range.insertNode(link);
    
        const textAfter = range.startContainer.textContent.slice(range.startOffset + 1, range.startOffset + 2);
        if (textAfter !== ' ' && textAfter !== ',' && textAfter !== '.') {
            range.insertNode(document.createTextNode(' '));
        }
    
        range.setStartBefore(link);
        range.setEndAfter(link);
        selection.selection.removeAllRanges();
        selection.selection.addRange(range);
        
    },
    

    removeLink: function (selection) {
        const range = selection.range;
        if (!range) return;
        const domFragement = range.cloneContents(),
            tag = "a";

        let node = domFragement.querySelector(tag);
        let currentNode = selection.selection.focusNode;
        if (node) {
            const span = document.createElement("span");
            span.innerHTML = node.textContent;

            //Replace node with new node
            const parent = node.parentNode;

            parent.insertBefore(span.firstChild, node);
            parent.removeChild(node);
            range.deleteContents();
        } else {
            //Find node of tag
            while (currentNode && currentNode !== "BODY") {
                if (currentNode?.tagName === tag.toUpperCase()) {
                    node = currentNode;
                    break;
                }

                currentNode = currentNode?.parentNode;
            }
            if (currentNode) {
                const span = document.createElement("span");
                span.innerHTML = currentNode.textContent;

                //Replace node with new node
                const parent = currentNode.parentNode;

                parent.insertBefore(span.firstChild, currentNode);
                parent.removeChild(currentNode);
                range.deleteContents();
            }
        }
    },

    insertHTML: function (selection, html) {
        const range = selection.range;
        if (!range) return;
        range.insertNode(html);
    },

    insertText: function (selection, text) {
        const range = selection.range;
        if (!range) return;
        const tagDom = document.createTextNode(text);
        range.deleteContents();
        range.insertNode(tagDom);
    },
    autop(containerEl: Node) {
        for (const node of containerEl.childNodes) {
            let wrap = false;
            if (node.nodeType == 3) {
                wrap = true;
            } else {
                if (!htmlTags.isBlock(node.nodeName) && !htmlTags.isBlockSpecial(node.nodeName)) {
                    wrap = true;
                }
            }
            if (wrap) {
                let tmp = document.createElement("p");
                tmp.appendChild(node.cloneNode());
                containerEl.insertBefore(tmp, node);
                containerEl.removeChild(node);
            }
        }
        return containerEl;
    }
};
