import type { ShopifyType, ProductData, CollectionData, ProductsQuery, ProductsQueryType, FilterData } from '@/types/shopify.d';
import { getMetafieldCodeParts, unwrapResponse } from '@/utils/shopifyDataHelper';
import SORT_OPTIONS from '@/services/liquid/mocks/sort_option.json';
import PRODUCT_FILTER_PREVIEW from '@/services/liquid/mocks/product-filter.json';
import ShopifyCacheStorage from '@/services/ShopifyCacheStorage';

/**
 * Ném ra khi merchant từ chối scope cần cho một call CSR. Liquid mixin bắt lỗi này
 * ở buildLiquidContext để chuyển element sang render SSR.
 */
export class ScopePermissionDeniedError extends Error {
    constructor(public scopes: string[]) {
        super(`Scope not granted: ${scopes.join(', ')}`);
        this.name = 'ScopePermissionDeniedError';
    }
}

/**
 * Shopify Data Service
 *
 * Fetches and caches Shopify data from backend Storefront API proxy.
 * Uses IndexedDB for persistent caching with 1-day TTL.
 */
class ShopifyDataService {
    private pendingRequests: Map<string, Promise<any>>;
    private worker: any;
    private cache: ShopifyCacheStorage;
    private grantedScopes: Set<string> = new Set();
    private deniedScopes: Set<string> = new Set();
    private scopeBatch: {
        scopes: Set<string>;
        waiters: Array<{ scopes: string[]; resolve: (granted: boolean) => void }>;
        timer: ReturnType<typeof setTimeout>;
    } | null = null;
    private scopeFlush: Promise<void> | null = null;
    private static readonly SCOPE_BATCH_WINDOW_MS = 120;

    private confirmScopeHandler?: (scopes: string[]) => Promise<boolean>;

    private static readonly PREVIEW_PRODUCT_LIMIT = 20;

    // Types excluded from cache (change too frequently)
    private static CACHE_EXCLUDE: Set<string> = new Set([]);

    /**
     * @param worker   Worker instance for HTTP requests
     * @param shopName Shop identifier used to isolate IndexedDB per store.
     * Resolved by the caller (plugin) from window.Shopify.shop,
     * ?shop= query param, or Vuex global/user.name.
     */
    constructor(worker: any, shopName: string = '') {
        this.worker = worker;
        this.pendingRequests = new Map();
        this.cache = new ShopifyCacheStorage(shopName);
    }

    setConfirmScopeHandler(handler: (scopes: string[]) => Promise<boolean>): void {
        this.confirmScopeHandler = handler;
    }

    private async shopifyScopeRequest(scopes: string[]): Promise<boolean> {
        if (scopes.every(scope => this.grantedScopes.has(scope))) return true;

        if (scopes.some(scope => this.deniedScopes.has(scope))) return false;

        if (typeof window.shopify === "undefined") return false;

        if (this.scopeFlush) {
            await this.scopeFlush;
            if (scopes.every(scope => this.grantedScopes.has(scope))) return true;
            if (scopes.some(scope => this.deniedScopes.has(scope))) return false;
        }

        return new Promise<boolean>(resolve => {
            if (!this.scopeBatch) {
                this.scopeBatch = {
                    scopes: new Set(),
                    waiters: [],
                    timer: setTimeout(() => this.runScopeFlush(), ShopifyDataService.SCOPE_BATCH_WINDOW_MS),
                };
            }
            scopes.forEach(scope => this.scopeBatch!.scopes.add(scope));
            this.scopeBatch.waiters.push({ scopes, resolve });
        });
    }

    private runScopeFlush(): void {
        const batch = this.scopeBatch;
        this.scopeBatch = null;
        if (!batch) return;
        this.scopeFlush = this.flushScopeBatch(batch).finally(() => { this.scopeFlush = null; });
    }

    private async flushScopeBatch(batch: {
        scopes: Set<string>;
        waiters: Array<{ scopes: string[]; resolve: (granted: boolean) => void }>;
    }): Promise<void> {
        try {
            const { granted } = await window.shopify.scopes.query();
            granted.forEach((scope: string) => this.grantedScopes.add(scope));

            const missing = [...batch.scopes].filter(scope => !this.grantedScopes.has(scope));
            if (missing.length) {
                const accepted = this.confirmScopeHandler ? await this.confirmScopeHandler(missing) : true;

                if (accepted) {
                    const response = await window.shopify.scopes.request(missing);
                    if (response?.result === "granted-all") {
                        missing.forEach((scope: string) => this.grantedScopes.add(scope));
                    } else {
                        (response?.detail?.granted || []).forEach((scope: string) => this.grantedScopes.add(scope));
                    }

                    if (missing.some(scope => this.grantedScopes.has(scope))) {
                        await this.refreshServerScopes();
                    }
                }

                missing.filter(scope => !this.grantedScopes.has(scope)).forEach(scope => this.deniedScopes.add(scope));
            }
        } catch (error) {
            console.error("Failed to request Storefront scopes", error);
        }

        for (const waiter of batch.waiters) {
            waiter.resolve(waiter.scopes.every(scope => this.grantedScopes.has(scope)));
        }
    }

    private async refreshServerScopes(): Promise<void> {
        try {
            const url = (window as any).route('builder.refresh-scopes');
            await this.worker.fetch(url, {}, 'POST');
        } catch (error) {
            console.error('Failed to refresh server scopes', error);
        }
    }

    /**
     * Get Shopify data by type and handle
     *
     * @param type Resource type
     * @param handle Resource handle (optional - fetches first available if not provided)
     * @returns Promise resolving to resource data
     */
    async get(type: ShopifyType, handle?: string, options?: Record<string, any>, useCache: boolean = true, cacheSuffix: string = ''): Promise<any> {
        const key = this.getCacheKey(type + cacheSuffix, handle);

        if (useCache && !ShopifyDataService.CACHE_EXCLUDE.has(type)) {
            const cached = await this.cache.get(key);
            if (cached) {
                return cached;
            }
        }

        // Check if request is already pending (deduplication)
        if (this.pendingRequests.has(key)) {
            return this.pendingRequests.get(key);
        }

        // Fetch from backend
        const promise = this.fetchFromBackend(type, handle, options);
        this.pendingRequests.set(key, promise);

        try {
            const data = await promise;

            if (useCache && !ShopifyDataService.CACHE_EXCLUDE.has(type)) {
                this.cache.set(key, data);
                if (!handle && data?.handle) {
                    this.cache.set(this.getCacheKey(type, data.handle), data);
                }
            }

            return data;
        } catch (error) {
            throw error;
        } finally {
            this.pendingRequests.delete(key);
        }
    }

    /**
     * Fetch data from backend Storefront API proxy
     *
     * @param type Resource type
     * @param handle Resource handle
     * @returns Promise resolving to resource data
     */
    private async fetchFromBackend(type: ShopifyType, handle?: string, options?: Record<string, any>): Promise<any> {
        try {
            const params: any = { type };
            if (handle) {
                params.handle = handle;
            }

            if (options) {
                Object.keys(options).forEach((key) => {
                    params[key] = options[key];
                });
            }

            // Use window.route and worker pattern like rest of the app
            const url = (window as any).route('builder.builder-data', params);
            const response = await this.worker.fetch(url, {}, 'GET');

            if (response.status === 'error') {
                throw new Error(response.error || response.message || 'Unknown error');
            }

            // Unwrap data từ response wrapper
            let data = response.data;

            // Backend response structure: {status: 'success', data: {...}}
            // Unwrap để lấy actual data
            if (data && typeof data === 'object' && 'data' in data) {
                data = data.data;
            }

            return data;

        } catch (error) {
            throw error;
        }
    }

    getFilterData() {
        return PRODUCT_FILTER_PREVIEW;
    }

    async getBlogs(handles: string[]): Promise<any[] | null> {
        const normalizedHandles = !Array.isArray(handles)
            ? []
            : handles.reduce<string[]>((acc, handle) => {
                if (typeof handle !== 'string') return acc;

                const normalizedHandle = handle.trim();
                if (normalizedHandle && !acc.includes(normalizedHandle)) {
                    acc.push(normalizedHandle);
                }

                return acc;
            }, []).slice(0, 20);
        if (!normalizedHandles.length) return null;

        const cachedBlogsByHandle = new Map<string, any>();
        const missingHandles: string[] = [];

        for (const handle of normalizedHandles) {
            const cachedBlog = await this.getCached('blog', handle);
            if (cachedBlog?.handle === handle) {
                cachedBlogsByHandle.set(handle, cachedBlog);
            } else {
                missingHandles.push(handle);
            }
        }

        const orderBlogsByHandles = (handles: string[], blogsByHandle: Map<string, any>): any[] => handles.map((handle) => blogsByHandle.get(handle)).filter((blog) => Boolean(blog));

        if (!missingHandles.length) {
            return orderBlogsByHandles(normalizedHandles, cachedBlogsByHandle);
        }

        const pendingKey = `blog:${missingHandles.slice(0.3).join(',')}`;
        let fetchPromise = this.pendingRequests.get(pendingKey);

        if (!fetchPromise) {
            fetchPromise = this.fetchFromBackend('blog' as ShopifyType, undefined, { handles: missingHandles });
            this.pendingRequests.set(pendingKey, fetchPromise);
        }

        try {
            const fetchedBlogs = await fetchPromise;
            const validBlogs = Array.isArray(fetchedBlogs)
                ? fetchedBlogs.filter((blog): blog is any => Boolean(blog?.handle))
                : [];

            await Promise.all(validBlogs
                .filter((blog) => blog?.handle)
                .map((blog) => this.cache.set(this.getCacheKey('blog', blog.handle), blog)));

            for (const blog of validBlogs) {
                cachedBlogsByHandle.set(blog.handle, blog);
            }

            return orderBlogsByHandles(normalizedHandles, cachedBlogsByHandle);
        } catch {
            return orderBlogsByHandles(normalizedHandles, cachedBlogsByHandle);
        } finally {
            this.pendingRequests.delete(pendingKey);
        }
    }

    async getCollectionsByContext(context: Record<string, any>): Promise<CollectionData[] | null> {
        const { dataSource, collectionHandles, id, handle, menu, menuName } = context;

        if (!["metafield", "menu", "collections"].includes(dataSource)) return null;

        if (["metafield", "menu"].includes(dataSource)) {
            if (dataSource === "menu" && (!menu || !menuName)) return null;
            if (dataSource === "menu") {
                const scopes = ['read_online_store_navigation'];
                if (!await this.shopifyScopeRequest(scopes)) throw new ScopePermissionDeniedError(scopes);
            }

            const paramKey = dataSource === "menu" ? menu : handle;
            const cacheKey = dataSource === "menu"
                ? `collections:menu:${menu}:${menuName}`
                : `collections:${dataSource}:${paramKey || '__default__'}`;

            const cached = await this.cache.get(cacheKey);
            if (cached) return cached;

            if (this.pendingRequests.has(cacheKey)) {
                return this.pendingRequests.get(cacheKey);
            }

            const promise = this.fetchFromBackend("collections", paramKey, dataSource === "menu"
                ? { dataSource, name: menuName }
                : { dataSource });
            this.pendingRequests.set(cacheKey, promise);

            try {
                const collections = await promise;
                if (Array.isArray(collections) && collections.length > 0) {
                    const validCollections = collections.filter((c): c is CollectionData => Boolean(c && c.handle));
                    await Promise.all([
                        this.cache.set(cacheKey, collections as CollectionData[]),
                        this.cacheCollectionsForContext(validCollections)
                    ]);
                    return collections as CollectionData[];
                }

                return null;
            } finally {
                this.pendingRequests.delete(cacheKey);
            }
        }

        if (!Array.isArray(collectionHandles) || !collectionHandles.length) return null;

        const cachedCollectionsByHandle = new Map<string, CollectionData>();
        const missingCollectionHandles: string[] = [];

        for (const h of collectionHandles) {
            const cached = await this.getCachedCollectionForContext(h);
            if (cached?.handle === h) {
                cachedCollectionsByHandle.set(h, cached);
            } else {
                missingCollectionHandles.push(h);
            }
        }

        if (missingCollectionHandles.length > 0) {
            const dedupeKey = `collections:batch:${id || missingCollectionHandles.slice().sort().join(',')}`;

            let fetchPromise = this.pendingRequests.get(dedupeKey);
            if (!fetchPromise) {
                fetchPromise = this.fetchFromBackend("collections", undefined, { handles: missingCollectionHandles });
                this.pendingRequests.set(dedupeKey, fetchPromise);
            }

            try {
                const fetched = await fetchPromise;
                if (Array.isArray(fetched) && fetched.length > 0) {
                    const validFetched = fetched.filter((c): c is CollectionData => Boolean(c && c.handle));
                    await this.cacheCollectionsForContext(validFetched);
                    validFetched.forEach((collection: CollectionData) => {
                        cachedCollectionsByHandle.set(collection.handle, collection);
                    });
                }
            } catch { }
            finally {
                this.pendingRequests.delete(dedupeKey);
            }
        }

        const cachedCollections = collectionHandles
            .map((h: string) => cachedCollectionsByHandle.get(h))
            .filter((collection: CollectionData | undefined): collection is CollectionData => Boolean(collection));

        return cachedCollections.length > 0 ? cachedCollections : null;
    }

    private getContextCollectionCacheKey(handle: string): string {
        return this.getCacheKey('context_collection', handle);
    }

    private async getCachedCollectionForContext(handle: string): Promise<CollectionData | null> {
        const cachedCollection = await this.getCached('collection', handle);
        if (cachedCollection?.handle === handle) {
            return cachedCollection;
        }

        const cachedContextCollection = await this.cache.get(this.getContextCollectionCacheKey(handle));
        return cachedContextCollection?.handle === handle ? cachedContextCollection : null;
    }

    private async cacheCollectionsForContext(collections: CollectionData[]): Promise<void> {
        await Promise.all(collections
            .filter((collection) => collection.handle)
            .map((collection) => this.cache.set(this.getContextCollectionCacheKey(collection.handle), collection)));
    }

    async getCollection(handle?: string): Promise<CollectionData | null> {
        const collection = unwrapResponse(await this.get('collection', handle));

        const isNotEmptyArray = <T>(arr: T[] | undefined | null): arr is T[] => Array.isArray(arr) && arr.length > 0;

        const tagsFromFilters = collection?.filters?.find((filter: FilterData) => filter.id === 'filter.p.tag')?.values
            ?.map((value: any) => value.label)
            ?.filter(Boolean);

        const all_tags = isNotEmptyArray(tagsFromFilters)
            ? tagsFromFilters
            : isNotEmptyArray(collection?.products)
                ? [...new Set(collection.products.flatMap((product: any) => isNotEmptyArray(product.tags) ? product.tags : []))]
                : null;

        const normalizedCollection = {
            ...collection,
            // Thu tu sort thuc te cua collection do backend map tu Admin `sortOrder`.
            // Hardcode 'created-descending' truoc day lam dropdown sort trong builder
            // lech voi live o moi collection khong sort theo ngay tao.
            default_sort_by: collection?.default_sort_by || 'manual',
            sort_by: '',
            sort_options: SORT_OPTIONS,
            all_tags
        };

        await this.cacheCollectionPreviewProducts(normalizedCollection);

        return normalizedCollection;
    }

    async getMenu(handle: string, name: string): Promise<any>{
        if (!handle || !name) return null;

        const scopes = ['read_online_store_navigation'];
        if (!await this.shopifyScopeRequest(scopes)) throw new ScopePermissionDeniedError(scopes);
        return unwrapResponse(await this.get("menu", handle, { name }));
    }

    /**
     * Localization đọc qua Storefront API ở server; server chỉ mint được storefront token
     * khi app có ít nhất một scope unauthenticated_*. Nếu chưa sẵn sàng (storefrontAvailable
     * = false), xin tạm unauthenticated_read_product_listings để mở khoá token rồi mới gọi.
     * Bản thân localization không cần dữ liệu product — scope chỉ để phát được token.
     */
    async getLocalization(storefrontAvailable: boolean = true): Promise<any> {
        if (!storefrontAvailable) {
            const scopes = ['unauthenticated_read_product_listings'];
            if (!await this.shopifyScopeRequest(scopes)) throw new ScopePermissionDeniedError(scopes);
        }

        return this.get('localization');
    }

    /**
     * Fetch collection filters on demand (separate `collection_filter` builderData entry).
     *
     * Filters are no longer bundled into the collection payload, so filter-related
     * elements (Collection Filter / FilterValue) request them explicitly when rendering
     * client-side. Returns an empty array when the collection has no filters.
     */
    async getCollectionFilter(handle?: string): Promise<FilterData[]> {
        if (!handle) return [];

        const scopes = ['unauthenticated_read_product_listings'];
        if (!await this.shopifyScopeRequest(scopes)) {
            throw new ScopePermissionDeniedError(scopes);
        }

        const data = unwrapResponse(await this.get('collection_filter', handle));

        return Array.isArray(data) ? data : [];
    }

    async getMetafield(code: string, options?: Record<string, any>): Promise<any> {
        const { resource, namespace, key } = getMetafieldCodeParts(code);

        const useCache = options?.useCache !== false;

        const metafieldSuffix = `:${resource}.${namespace}.${key}` + (options?.productHandle ? `.${options.productHandle}` : '');
        const cacheKey = `metafield${metafieldSuffix}`;

        if (useCache) {
            const cached = await this.cache.get(cacheKey);
            if (cached) {
                return cached;
            }
        }

        const response = await this.get('metafield', undefined, {
            key,
            resource,
            namespace,
            productHandle: options?.productHandle,
        }, false, metafieldSuffix);

        const metafield = response?.status === 'success' && response?.data
            ? response.data
            : response;

        if (useCache) {
            await this.cache.set(cacheKey, metafield);
        }

        return metafield;
    }

    /**
     * Get products list by query
     * Supports: collection_products, vendor_products, type_products, products_batch, sample_products
     */
    async getProducts(query: ProductsQuery): Promise<ProductData[]> {
        const normalizedQuery = this.normalizePreviewProductsQuery(query);
        const cacheKey = this.buildProductsListCacheKey(normalizedQuery);

        const cached = await this.cache.get(cacheKey);
        if (cached) {
            if (normalizedQuery.type === 'products_batch') {
                // Batch cache keys intentionally ignore handle order so the same
                // products can share a cache entry. Restore the order requested by
                // the picker before returning the cached list.
                const handles = this.normalizeProductHandles(normalizedQuery.handles);
                const productsByHandle = new Map(
                    cached.map((product: ProductData) => [product.handle, product])
                );
                const orderedProducts = this.orderProductsByHandles(handles, productsByHandle);

                return this.applyRequestedProductsLimit(orderedProducts, query.limit);
            }

            return this.applyRequestedProductsLimit(cached, query.limit);
        }

        if (normalizedQuery.type === 'products_batch') {
            return this.getProductsBatch(normalizedQuery, cacheKey, query.limit);
        }

        // Check if request is already pending (deduplication)
        if (this.pendingRequests.has(cacheKey)) {
            const pendingRequest = this.pendingRequests.get(cacheKey) as Promise<ProductData[]>;
            return pendingRequest.then((products) => this.applyRequestedProductsLimit(products, query.limit));
        }

        // Fetch from backend
        const promise = this.fetchProductsFromBackend(normalizedQuery);
        this.pendingRequests.set(cacheKey, promise);

        try {
            const products = await promise;

            // Cache the result
            await this.cache.set(cacheKey, products);

            // Also cache individual products
            await this.cacheProductsByHandle(products);

            return this.applyRequestedProductsLimit(products, query.limit);
        } catch {
            return [];
        } finally {
            this.pendingRequests.delete(cacheKey);
        }
    }

    async getCartContext(): Promise<any> {
        const products = await this.getProducts({ type: "sample_products", limit: 3, has_only_default_variant: true });

        return {
            products,
            cart: this.buildCartContextFromProducts(products)
        }
    }

    private buildCartContextFromProducts(products: ProductData[]): any {
        const items = products
            .map((product, index) => this.buildCartItemFromProduct(product, index))
            .filter(Boolean);
        const itemCount = items.reduce((total, item) => total + item.quantity, 0);
        const itemsSubtotalPrice = items.reduce((total, item) => total + item.final_line_price, 0);
        const originalTotalPrice = items.reduce((total, item) => total + item.original_line_price, 0);
        const totalDiscount = items.reduce((total, item) => total + item.total_discount, 0);
        const totalWeight = items.reduce((total, item) => total + item.grams * item.quantity, 0);

        return {
            attributes: {},
            cart_level_discount_applications: [],
            currency: 'USD',
            discount_applications: [],
            discount_codes: [],
            empty: itemCount === 0,
            item_count: itemCount,
            items,
            items_subtotal_price: itemsSubtotalPrice,
            note: '',
            original_total_price: originalTotalPrice,
            requires_shipping: items.length > 0,
            taxes_included: false,
            total_discount: totalDiscount,
            total_price: itemsSubtotalPrice,
            total_weight: totalWeight
        };
    }

    private buildCartItemFromProduct(product: ProductData, index: number): any {
        const variant = product.selected_or_first_available_variant || product.variants?.[0] || null;
        const variantId = variant?.id || product.id;
        const productId = product.id;
        const quantity = 1;
        const price = this.toSafeNumber(variant?.price ?? product.price ?? product.price_min);
        const compareAtPrice = this.toNullableNumber(variant?.compare_at_price ?? product.compare_at_price ?? product.compare_at_price_min);
        const originalPrice = price;
        const finalPrice = price;
        const originalLinePrice = originalPrice * quantity;
        const finalLinePrice = finalPrice * quantity;
        const image = this.getCartItemImage(product, variant);
        const url = product.url || `/products/${product.handle}`;
        const line = index + 1;
        const key = `${variantId}:${line}`;

        return {
            barcode: (variant as any)?.barcode || (product as any)?.barcode || '',
            compare_at_price: compareAtPrice,
            discounts: [],
            featured_image: image,
            final_line_price: finalLinePrice,
            final_price: finalPrice,
            grams: this.toSafeNumber((variant as any)?.grams ?? (variant as any)?.weight ?? (product as any)?.grams ?? (product as any)?.weight),
            handle: product.handle,
            has_only_default_variant: (product as any)?.has_only_default_variant !== false,
            id: variantId,
            image,
            index,
            key,
            line,
            line_price: finalLinePrice,
            options: (variant as any)?.options || [],
            options_with_values: (product as any)?.options_with_values || [],
            original_line_price: originalLinePrice,
            original_price: originalPrice,
            price,
            product,
            product_id: productId,
            product_title: product.title,
            properties: [],
            quantity,
            requires_shipping: true,
            sku: (variant as any)?.sku || (product as any)?.sku || '',
            taxable: true,
            title: product.title,
            total_discount: originalLinePrice - finalLinePrice,
            url,
            url_to_remove: `/cart/change?line=${line}&quantity=0`,
            variant: {
                ...variant,
                compare_at_price: compareAtPrice,
                id: variantId,
                price
            },
            variant_id: variantId,
            variant_title: variant?.title || ''
        };
    }

    private getCartItemImage(product: ProductData, variant: ProductData['selected_or_first_available_variant']): any {
        return variant?.image
            || (variant as any)?.featured_image
            || product.featured_image
            || product.featured_media?.preview_image
            || product.images?.[0]
            || null;
    }

    private toSafeNumber(value: any): number {
        const numberValue = Number(value);
        return Number.isFinite(numberValue) ? numberValue : 0;
    }

    private toNullableNumber(value: any): number | null {
        if (value === null || value === undefined || value === '') return null;

        const numberValue = Number(value);
        return Number.isFinite(numberValue) ? numberValue : null;
    }

    private async getProductsBatch(query: ProductsQuery, cacheKey: string, requestedLimit?: number): Promise<ProductData[]> {
        const handles = this.normalizeProductHandles(query.handles);
        if (!handles.length) return [];

        const cachedProductsByHandle = new Map<string, ProductData>();
        const missingHandles: string[] = [];

        for (const handle of handles) {
            const cached = await this.getCached('product', handle);
            if (cached?.handle === handle) {
                cachedProductsByHandle.set(handle, cached);
            } else {
                missingHandles.push(handle);
            }
        }

        if (!missingHandles.length) {
            const products = this.orderProductsByHandles(handles, cachedProductsByHandle);
            await this.cache.set(cacheKey, products);
            return this.applyRequestedProductsLimit(products, requestedLimit);
        }

        const missingQuery: ProductsQuery = {
            ...query,
            handles: missingHandles,
            limit: ShopifyDataService.PREVIEW_PRODUCT_LIMIT
        };
        const missingCacheKey = this.buildProductsListCacheKey(missingQuery);

        let fetchPromise = this.pendingRequests.get(missingCacheKey);
        if (!fetchPromise) {
            fetchPromise = this.fetchProductsFromBackend(missingQuery);
            this.pendingRequests.set(missingCacheKey, fetchPromise);
        }
        try {
            const fetchedProducts = await fetchPromise;
            await this.cache.set(missingCacheKey, fetchedProducts);
            await this.cacheProductsByHandle(fetchedProducts);

            for (const product of fetchedProducts) {
                if (product.handle) {
                    cachedProductsByHandle.set(product.handle, product);
                }
            }

            const products = this.orderProductsByHandles(handles, cachedProductsByHandle);
            await this.cache.set(cacheKey, products);

            return this.applyRequestedProductsLimit(products, requestedLimit);
        } catch {
            return this.applyRequestedProductsLimit(
                this.orderProductsByHandles(handles, cachedProductsByHandle),
                requestedLimit
            );
        } finally {
            this.pendingRequests.delete(missingCacheKey);
        }
    }

    private normalizeProductHandles(handles?: string[]): string[] {
        if (!Array.isArray(handles)) return [];

        const normalizedHandles = handles.reduce<string[]>((acc, handle) => {
            if (typeof handle !== 'string') return acc;

            const normalizedHandle = handle.trim();
            if (normalizedHandle && !acc.includes(normalizedHandle)) {
                acc.push(normalizedHandle);
            }

            return acc;
        }, []);

        return normalizedHandles.slice(0, ShopifyDataService.PREVIEW_PRODUCT_LIMIT);
    }

    private normalizePreviewProductsQuery(query: ProductsQuery): ProductsQuery {
        return {
            ...query,
            handles: this.normalizeProductHandles(query.handles),
            limit: ShopifyDataService.PREVIEW_PRODUCT_LIMIT
        };
    }

    private applyRequestedProductsLimit(products: ProductData[], requestedLimit?: number): ProductData[] {
        if (!requestedLimit || requestedLimit >= ShopifyDataService.PREVIEW_PRODUCT_LIMIT) {
            return products;
        }

        return products.slice(0, requestedLimit);
    }

    private orderProductsByHandles(handles: string[], productsByHandle: Map<string, ProductData>): ProductData[] {
        return handles
            .map((handle) => productsByHandle.get(handle))
            .filter((product): product is ProductData => Boolean(product));
    }

    private async cacheProductsByHandle(products: ProductData[]): Promise<void> {
        await Promise.all(products
            .filter((product) => product.handle)
            .map((product) => this.cache.set(this.getCacheKey('product', product.handle), product)));
    }

    private async cacheCollectionPreviewProducts(collection?: CollectionData | null): Promise<void> {
        if (!collection?.handle || !Array.isArray(collection.products) || !collection.products.length) return;

        const products = collection.products.slice(0, ShopifyDataService.PREVIEW_PRODUCT_LIMIT);
        await Promise.all([
            this.cache.set(this.buildProductsListCacheKey({
                type: 'collection_products',
                handle: collection.handle,
                limit: ShopifyDataService.PREVIEW_PRODUCT_LIMIT
            }), products),
            this.cacheProductsByHandle(products)
        ]);
    }

    /**
     * Build cache key for products list query
     */
    private buildProductsListCacheKey(query: ProductsQuery): string {
        const parts = [`products_list:${query.type}`];
        if (query.handle) parts.push(query.handle);
        const handles = this.normalizeProductHandles(query.handles);
        if (handles.length) parts.push(handles.slice().sort().join(','));
        if (query.sort) parts.push(`sort:${query.sort}`);
        if (query.available) parts.push('available:true');
        if (query.has_only_default_variant) parts.push('has_only_default_variant:true');
        return parts.join(':');
    }

    /**
     * Fetch products list from backend
     */
    private async fetchProductsFromBackend(query: ProductsQuery): Promise<ProductData[]> {
        try {
            const params: Record<string, any> = {
                type: query.type,
                limit: ShopifyDataService.PREVIEW_PRODUCT_LIMIT
            };

            if (query.handle) params.handle = query.handle;
            if (query.handles?.length) params.handles = query.handles;
            if (query.sort) params.sort = query.sort;
            if (query.available) params.available = true;
            if (query.has_only_default_variant) params.has_only_default_variant = true;

            const baseUrl = (window as any).route('builder.builder-data');
            const url = new URL(baseUrl, window.location.origin);

            Object.entries(params).forEach(([key, value]) => {
                if (Array.isArray(value)) {
                    value.forEach((v, i) => url.searchParams.append(`${key}[${i}]`, v));
                } else {
                    url.searchParams.append(key, String(value));
                }
            });

            const response = await this.worker.fetch(url.toString(), {}, 'GET');

            if (response.status === 'error') {
                throw new Error(response.error || 'Unknown error');
            }

            let data = response.data;
            if (data && typeof data === 'object' && 'data' in data) {
                data = data.data;
            }

            if (!Array.isArray(data)) return [];

            return data;
        } catch (error) {
            throw error;
        }
    }

    /**
     * Get cached products list
     */
    async getCachedProducts(query: ProductsQuery): Promise<ProductData[] | null> {
        const cacheKey = this.buildProductsListCacheKey(this.normalizePreviewProductsQuery(query));
        const cached = await this.cache.get(cacheKey);
        return cached ? this.applyRequestedProductsLimit(cached, query.limit) : null;
    }

    /**
     * Clear products list cache
     */
    clearProductsCache(queryType?: ProductsQueryType): void {
        if (queryType) {
            this.cache.deleteByPrefix(`products_list:${queryType}`);
        } else {
            this.cache.deleteByPrefix('products_list:');
        }
    }

    /**
     * Clear cache for specific resource or all
     *
     * @param type Optional resource type to clear
     * @param handle Optional resource handle to clear
     */
    clearCache(type?: ShopifyType, handle?: string): void {
        if (type && handle) {
            this.cache.delete(this.getCacheKey(type, handle));
        } else if (type) {
            this.cache.deleteByPrefix(`${type}:`);
        } else {
            this.cache.clear();
        }
    }

    /**
     * Invalidate specific resource
     *
     * @param type Resource type
     * @param handle Resource handle
     */
    invalidate(type: ShopifyType, handle: string): void {
        this.clearCache(type, handle);
    }

    /**
     * Set cache TTL in milliseconds
     *
     * @param ttl TTL in milliseconds
     */
    setCacheTtl(ttl: number): void {
        this.cache.setTtl(ttl);
    }

    /**
     * Get cache statistics for debugging
     *
     * @returns Cache statistics
     */
    async getCacheStats(): Promise<any> {
        return {
            pendingRequests: this.pendingRequests.size,
        };
    }

    private getCacheKey(type: ShopifyType | string, handle?: string): string {
        return `${type}:${handle || '__first__'}`;
    }

    /**
     * Get cached data (without fetching)
     * Useful for accessing already-fetched data
     *
     * @param type Resource type
     * @param handle Resource handle (optional)
     * @returns Cached data or null if not cached
     */
    async getCached(type: ShopifyType, handle?: string): Promise<any> {
        const key = this.getCacheKey(type, handle);
        return await this.cache.get(key) || null;
    }
}

export default ShopifyDataService;
