    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit("builder/setIsContentEditable", false);
                this.$store.commit("builder/setEditingElementId", "");
                if (this.currentEditEl && this.inlineItemIndex !== null && this.inlineEditField) {
                    const content = this.currentEditEl;
                    const row = this.data.settings.items[this.inlineItemIndex];
                    if (row) {
                        const next = getContentEditableValue(
                            content,
                            this.inlineEditField === "label" ? "text" : "html"
                        );
                        if (this.inlineEditField === "label") {
                            row.label = next;
                        } else if (this.inlineEditField === "desc") {
                            row.desc = next;
                        }
                    }
                }
                this.inlineItemIndex = null;
                this.inlineEditField = null;
                this.currentEditEl = null;
            }
            if (val) {
                this.$store.commit("builder/setEditingElementId", this.data.id);
            }
        },
        isContentEditable() {
            this.isBlur = false;
        },
        isEditingThisElement(val) {
            if (val && this.inlineItemIndex !== null && this.inlineEditField) {
                const row = this.data.settings.items[this.inlineItemIndex];
                this.editingValue =
                    this.inlineEditField === "label" ? row?.label || "" : row?.desc || "";
                this.$nextTick(() => {
                    if (!this.currentEditEl || !this.isEditingThisElement) return;
                    placeCaretAtEnd(this.currentEditEl, this.idoc());
                });
            }
        }
    },
    methods: {
        isEditingLabel(i) {
            return (
                this.inlineItemIndex === i &&
                this.inlineEditField === "label" &&
                this.isEditingThisElement
            );
        },
        isEditingDesc(i) {
            return (
                this.inlineItemIndex === i &&
                this.inlineEditField === "desc" &&
                this.isEditingThisElement
            );
        },
        textLooksDynamic(text) {
            const s = String(text || "");
            return s.includes("{{") || s.includes("{%");
        },
        editLabel(i, e) {
            if (this.exporting) return;
            const row = this.data.settings.items[i];
            if (!row?.label || this.textLooksDynamic(row.label)) return;
            this.inlineItemIndex = i;
            this.inlineEditField = "label";
            this.editingValue = row.label || "";
            this.currentEditEl = e.currentTarget;
            this.$store.commit("builder/setIsContentEditable", true);
        },
        editDesc(i, e) {
            if (this.exporting) return;
            const row = this.data.settings.items[i];
            if (!row?.desc || row.desc === "<br>" || this.textLooksDynamic(row.desc)) return;
            this.inlineItemIndex = i;
            this.inlineEditField = "desc";
            this.editingValue = row.desc || "";
            this.currentEditEl = e.currentTarget;
            this.$store.commit("builder/setIsContentEditable", true);
        },
        onIconlistInlineInput(i, ev) {
            if (this.exporting) return;
            if (this.inlineItemIndex !== i || !this.inlineEditField || !this.isEditingThisElement) return;
            const row = this.data.settings.items[i];
            if (!row) return;
            const source =
                this.inlineEditField === "label"
                    ? row.label
                    : row.desc;
            if (this.textLooksDynamic(source)) return;
            const target = ev?.target;
            if (!target) return;
            const next = getContentEditableValue(
                target,
                this.inlineEditField === "label" ? "text" : "html"
            );
            if (this.inlineEditField === "label") {
                if (row.label !== next) row.label = next;
            } else if (this.inlineEditField === "desc") {
                if (row.desc !== next) row.desc = next;
            }
        },
        handleIconlistInlineBlur() {
            if (this.exporting) return;
            if (!this.isBlur) return;
            setTimeout(() => {
                this.$store.commit("builder/setIsContentEditable", false);
            }, 200);
        },
        quickToolBar() {
            return ["items", "layout", "flexDirection"];
        },
        hasTitle() {
            return this.data.settings.items?.some((x) => x.label);
        },
        hasDesc() {
            return this.data.settings.items?.some((x) => x.desc);
        },

        style() {
            let style = [];
            if (this.data.settings?.items) {
                style.push(
                    {
                        group_name: "iconListGeneral",
                        group_title: this.$t('general'),
                        selector: " .ecom-base-iconlist .ecom-iconlist--list",
                        params: [
                            this.data.settings.layout == "inline"
                                ? {
                                      type: "choose",
                                      label: this.$t('alignment'),
                                      name: "listJustifyContent",
                                      options: {
                                          oneline: true,
                                          type: "text-align",
                                          values: ["flex-start", "center", "flex-end"]
                                      },
                                      css: {
                                          properties: {
                                              display: "flex",
                                              "justify-content": ""
                                          }
                                      }
                                  }
                                : {
                                      type: "choose",
                                      label: this.$t('alignment'),
                                      name: "listJustifyContent",
                                      options: {
                                          oneline: true,
                                          type: "text-align",
                                          values: ["flex-start", "center", "flex-end"]
                                      },
                                      css: {
                                          selector: " .ecom-iconlist--item",
                                          properties: {
                                              display: "flex",
                                              "align-items": ""
                                          }
                                      }
                                  },
                            {
                                alias: 'width',
                                options: {
                                    label: this.$t('width'),
                                    css: {
                                        selector: 'root .ecom-iconlist--item'
                                    }
                                }
                            },
                            {
                                type: "background",
                                label: this.$t('background_type'),
                                name: "background",
                                options: {
                                    responsive: true,
                                    types: ["classic", "gradient"]
                                },
                                css: {
                                    selector: " .ecom-iconlist--item",
                                    properties: {
                                        background: ""
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                label: this.$t('border'),
                                name: 'boxBorder',
                                options: {
                                    type: 'border',
                                    oneline: true
                                },
                                css:{
                                    selector : " .ecom-iconlist--item",
                                    properties : {
                                        border : ""
                                    }
                                },
                            },
                            {
                                name: 'boxBorderRadius',
                                label: this.$t('border_radius'),
                                type: 'dimension',
                                options: {
                                    responsive: true,
                                    type: 'radius',
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 1000
                                        },
                                        '%': {
                                            min: 0,
                                            max: 100
                                        }
                                    }
                                },
                                css:{
                                    selector : " .ecom-iconlist--item",
                                    properties:{
                                        overflow:'hidden',
                                        'border-radius': ''
                                    }
                                }
                            },
                            {
                                alias: "spacing",
                                options: {
                                    label: this.$t('spacing'),
                                    css: {
                                        selector: " .ecom-iconlist--item"
                                    }
                                }
                            }
                        ]
                    },
                    {
                        group_alias:'image',
                        options:{
                            group_name: 'iconListImage',
                            group_title: this.$t('image'),
                            selector: ' .ecom-iconlist--image'
                        },
                        modify: {
                            remove: {
                                index: 15,
                                length: 2
                            },
                            params: [
                                {
                                    position: 40,
                                    fields: [
                                        {
                                            type: 'line'
                                        },
                                        {
                                            alias: 'spacing'
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_title: this.$t('icon'),
                        group_name: "iconListIcon",
                        selector: " .ecom-base-iconlist .ecom-iconlist--icon",
                        params: [
                            {
                                type: "choose",
                                label: this.$t('alignment'),
                                name: "itemAlignSelf",
                                options: {
                                    oneline: true,
                                    type: ['row', 'row-reverse'].includes(this.data?.settings?.flexDirection) ? 'align-y-full' : 'align-x-full',
                                    values: ["flex-start", "center", "flex-end"]
                                },
                                css: {
                                    properties: {
                                        "align-self": ""
                                    }
                                }
                            },
                            ...this.$helpers.copy(
                                iconHover("root .ecom-iconlist--container:hover .ecom-iconlist--icon").params
                            ),
                            {
                                type: "line"
                            },
                            {
                                alias: "spacing",
                                options: {
                                    label: this.$t('spacing')
                                }
                            }
                        ]
                    }
                );
            }
            if (this.hasTitle()) {
                style.push({
                    group_alias: "text:spacing",
                    options: {
                        group_title: this.$t('label'),
                        group_name: "iconListText",
                        selector: " .ecom-base-iconlist .ecom-iconlist--title"
                    }
                });
            }
            if (this.hasDesc()) {
                style.push({
                    group_alias: "text:spacing",
                    options: {
                        group_title: this.$t('description'),
                        group_name: "iconListDescription",
                        selector: " .ecom-base-iconlist .ecom-iconlist--des"
                    }
                });
            }
            return style;
        }
    }
};
