<template>
    <PickerFrame
    :show="show"
    :header="headerFrame"
    :position="position"
    @close="show = false"
>
    <template #content>
        <div class="w-full h-full bg-white   overflow-y-auto overflow-x-hidden pb-0.5">
            <div class="p-4">
                <label
                    v-if="isEditor"
                    class="block mb-3.5 text-xs text-gray-700 "
                >
                    <span class="block mb-[6px] leading-5 font-[450]">{{ $t('text') }}</span>
                    <input
                        v-model="value.text"
                        type="text"
                        class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                        tabindex="0"
                    >
                </label>
                <label class="relative block mb-3.5 text-xs text-text-primary">
                    <span class="block mb-[6px] leading-5 font-[450]">{{ $t('link') }}</span>
                    <span class="flex items-center relative">
                        <span
                            v-clickOutside="blurGroupTypes"
                            class="w-full"
                        >
                            <input
                                v-model="value.href"
                                type="text"
                                class="block w-full pl-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                                :class="!disabled ? 'pr-10' : 'pr-3'"
                                :placeholder="$t('paste_a_link')"
                                tabindex="1"
                                @focus="focusInputLink"
                            >
                            <GroupTypes
                                ref="group-type"
                                :style="styleGroupTyles"
                                :src="value?.href ?? ''"
                                @update:select="updateSelect"
                            />
                        </span>
                        <button
                            v-if="!disabled"
                            type="button"
                            tabindex="2"
                            @click="value.href = ''"
                            class="absolute right-0 top-0 w-8 h-8 bg-transparent flex items-center justify-center"
                        >
                            <EcomIcon :source="icons.CircleCancelMajor" :size="'w-5'" color="text-icon-primary" class="flex items-center "></EcomIcon>
                        </button>
                    </span>
                    <p class="mt-1.5 text-text-primary-300 text-xs">{{ $t('http_is_required_for_external_links') }}</p>
                </label>
                <label class="relative block mb-3.5 text-xs text-text-primary">
                    <span class="block mb-[6px] leading-5 font-[450]">{{ $t('link_title') }}</span>
                    <input
                        v-model="value.title"
                        type="text"
                        class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                        tabindex="3"
                    >
                    <p class="mt-1.5 text-text-primary-300 text-xs">{{ $t('used_for_accessibility_and_seo') }}</p>
                </label>
                <label class="flex items-center py-1 cursor-pointer select-none">
                    <span class="relative mr-1.5 min-w-5 h-5 flex items-center justify-center">
                        <input
                            v-model="value.target"
                            class="h-4 w-4 cursor-pointer opacity-0 absolute z-10 peer"
                            type="checkbox"
                            true-value="_blank"
                            false-value=""
                            tabindex="4"
                        >
                        <span class="w-4 h-4 border border-input rounded flex justify-center items-center peer-checked:bg-dark peer-checked:border-transparent text-transparent peer-checked:text-white">
                            <EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" class="w-5 h-5 flex"></EcomIcon>
                        </span>
                    </span>

                    <span class="text-xs font-[450] text-text-primary">{{ $t('open_this_link_in_a_new_tab') }}</span>
                </label>
                <label class="flex items-center py-1 cursor-pointer select-none" v-if="isTargetIcon">
                    <span class="relative mr-1.5 min-w-5 h-5 flex items-center justify-center">
                        <input
                            v-model="value.targetIcon"
                            class="h-4 w-4 cursor-pointer opacity-0 absolute z-10 peer"
                            type="checkbox"
                            true-value="1"
                            false-value=""
                            :tabindex="newTab ? 4 : -1"
                        >
                        <span class="w-4 h-4 border border-input rounded flex justify-center items-center peer-checked:bg-dark peer-checked:border-transparent text-transparent peer-checked:text-white">
                            <EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" class="w-5 h-5 flex"></EcomIcon>
                        </span>
                    </span>

                    <span class="text-xs font-[450] text-text-primary">{{ $t('show_external_link_icon') }}</span>
                </label>
                <label class="flex items-center py-1 mb-3.5 cursor-pointer select-none">
                    <span class="relative mr-1.5 min-w-5 h-5 flex items-center justify-center">
                        <input
                            v-model="value.rel"
                            class="h-4 w-4 cursor-pointer opacity-0 absolute z-10 peer"
                            type="checkbox"
                            true-value="nofollow"
                            false-value=""
                            :tabindex="newTab ? 5 : 4"
                        >
                        <span class="w-4 h-4 border border-input rounded flex justify-center items-center peer-checked:bg-dark peer-checked:border-transparent text-transparent peer-checked:text-white">
                            <EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" class="w-5 h-5 flex"></EcomIcon>
                        </span>
                    </span>

                    <span class="text-xs font-[450] text-text-primary">{{ $t('add_nofollow') }}</span>
                </label>
                <label class="relative block mb-3.5 text-xs text-text-primary ">
                    <span class="block mb-[6px] leading-5 font-[450]">{{ $t('custom_attributes') }}</span>
                    <input
                        v-model="attributes"
                        type="text"
                        :placeholder="`${$t('key')}|${$t('value')}, ${$t('key')}|${$t('value')}2`"
                        class="block w-full px-3 py-1.5 leading-5 transition rounded-lg text-text-primary border border-input placeholder-form-input text-xs font-normal hover:border-input-hover focus:border-input-hover focus:outline-focus outline-offset-1 outline-none disabled:opacity-40 h-8"
                        :tabindex="newTab ? 4 : 3"
                    >
                </label>
            </div>
            <div
                v-if="isShowRemoveLink"
                class="mx-4 my-5"
            >
                <Button
                    :text="$t('remove_link')"
                    @click="removeLink"
                />
            </div>
        </div>
    </template>
    <template #footer>
      <PickerFooter
        :is-change="isChange"
        :text-select="textSelect"
        @clickCancel="cancelLink"
        @clickSelect="updateLink"
      />
    </template>
  </PickerFrame>
</template>

<script lang="ts">

    import PickerFrame from '../../picker/PickerFrame.vue';
    import PickerFooter from '../../picker/PickerFooter.vue';
    import GroupTypes from './Types.vue';
    import { clickOutside } from '../../../directives';
    import { CancelMajor, MobileAcceptMajor, TickSmallMinor, CircleCancelMajor, link_icon} from "@/assets/icons";
    import { defineAsyncComponent } from 'vue';

    export default {
        name: 'InsertLink',
        directives: {
            clickOutside
        },
        components: {
            PickerFrame,
            PickerFooter,
            GroupTypes,
            AIDesc: defineAsyncComponent(() => import('../../molecules/AIDesc/AIDesc.vue'))
        },
        props: {
            data: {
                type: Object,
                default(){
                    return  {};
                }
            },
            type: {
                type: String,
                default: 'editor'
            },
            position: {
                type: String,
                default: 'absolute'
            },
            targetIcon: false,
            aipath: {
                type: String,
                default: ''
            },
            aichangeable: {
                type: Boolean,
                default: false
            }
        },
        emits: ['close_popup', 'update:link', 'update:remove-link'],
        data(){
            return {
                show: false,
                value: {},
                attributes: '',
                styleGroupTyles: {},
                icons: {
                    CancelMajor, MobileAcceptMajor, TickSmallMinor, CircleCancelMajor
                }
            };
        },
        computed: {
            isEditor(){
                return this.type === 'editor';
            },
            headerFrame(){
                return {
                    title: this.isEditor ? this.$t('insert_link') : this.$t('link_settings'),
                    alignLeft: true,
                    search: {
                        show: false,
                        value: ''
                    },
                    type: 'link'
                };
            },
            textSelect(){
                if(this.isEditor ){
                    if(this.data.href){
                        return this.$t('update');
                    }
                    return this.$t('insert');
                }
                return this.$t('done');
            },
            disabled(){
                return !this.value?.href?.trim();
            },
            newTab(){
                return this.value?.target == '_blank';
            },
            isTargetIcon() {
                return this.newTab && this.targetIcon;
            },
            nofollow(){
                return this.value?.rel == 'nofollow';
            },
            objAttributes(){
                let result = {};
                if(this.attributes){
                    let p = this.attributes.split(',');
                    p.forEach(item => {
                        let [key, value] = item.split('|');
                        if(key && value){
                            result[key.trim()] = value.trim();
                        }
                    });
                }
                return result;
            },
            valueFinal(){
                let v = {...this.value, ...this.objAttributes};
                let igroneKey = ['href','title','rel','target','text', ...Object.keys(this.objAttributes)];
                let deleteKey = Object.keys(v).filter(k => igroneKey.indexOf(k) === -1);
                deleteKey.forEach(k => delete v[k]);
                return v;
            },
            html(){
                let node = document.createElement('a');
                let value = this.valueFinal;
                let key;
                for(key in value){
                    if(value[key] != '' && key != 'text' && key != 'targetIcon') {
                        node.setAttribute(key, value[key]);
                    }
                }
                node.innerText = this.value['text'];
                if (this.value?.targetIcon) {
                    let _tmp = document.createElement('span');
                    _tmp.innerHTML = link_icon;
                    let iconEl = _tmp.firstElementChild;
                    if (iconEl) {
                        iconEl.setAttribute('width', '1em');
                        iconEl.setAttribute('data-ecom-role', 'external-link-icon');
                        iconEl.style.display = 'inline-block';
                        iconEl.style.width = '1em';
                        iconEl.style.margin = '0 0.125em';
                        iconEl.style.verticalAlign = 'middle';
                        iconEl.style.transform = 'translateY(-0.09375em)';
                        node.appendChild(iconEl);
                    }
                }
                return node;
            },
            isShowRemoveLink(){
                return this.data?.href && this.isEditor;
            },
            isChange(){
                let isChange = ('href' in this.value &&
                        this.value.href.trim() != '');
                if(this.isEditor){
                    isChange &= ('text' in this.value &&
                        this.value.text.trim() != '');
                }

                return !!isChange;
            }
        },
        watch: {
            show: function(val){
                if(val){
                    this.value = this.copy(this.data);
                }else{
                    this.$emit('close_popup');
                }
            },
            data: {
                deep: true,
                immediate: true,
                handler: function(val){
                    this.attributes = this.getAttrCustom(val);
                }
            }
        },
        methods: {
            copy(obj){
                return JSON.parse(JSON.stringify(obj));
            },
            getAttrCustom(data){
                let keysIgrone = ['title', 'href', 'rel', 'target', 'text', 'targetIcon'],
                    keys = Object.keys(data),
                    keyAccept = keys.filter(key => keysIgrone.indexOf(key) === -1);
                return keyAccept.map(key => key + '|' + data[key]).join(',');
            },
            blurGroupTypes(){
                this.$refs['group-type'].showFull = false;
            },
            focusInputLink(e){
                let $groupType = this.$refs['group-type'];
                if(!$groupType.showFull){
                    let target = e.target;
                    let { top, height } = target.getBoundingClientRect(),
                        sh = window.innerHeight,
                        t = sh - top - height - 10,
                        mh;
                    console.log('top', top, 'height', height, 'sh', sh, 't', t);
                    if(top < t) {
                        mh = sh - (top + height ) - 90;
                        mh = mh < 0 ? 0 : (mh > 350 ? 350 : mh);
                        this.styleGroupTyles = {
                            top: `calc(${ top + height + 5 - 52 - 12}px)`, // 52 is the height of the Top bar, 12 is the padding, cuz this popup fixed based on the settings side bar
                            maxHeight: `${ mh }px`
                        };
                    }
                    else {
                        mh = top - 82;
                        mh = mh < 0 ? 0 : (mh > 350 ? 350 : mh);
                        this.styleGroupTyles = {
                            bottom: `calc(100vh - ${ top - 10 }px)`,
                            maxHeight: `${ mh }px`
                        };
                    }
                    $groupType.show = true;
                    $groupType.showFull = true;
                }

            },
            updateSelect(value, type){
                if(type == 'email'){
                    this.value.href = 'mailto:' + value;
                    this.$refs['group-type'].showFull = false;
                    return;
                }
                if(type == 'phone'){
                    this.value.href = 'tel:' + value;
                    this.$refs['group-type'].showFull = false;
                    return;
                }
                this.value.href = '/' + value;
                this.$refs['group-type'].showFull = false;
            },
            cancelLink() {
                if (this.$refs['aidesc']) {
                    this.$refs['aidesc'].onCancel();
                }
                this.show = false;
            },
            updateLink(){
                if(this.isEditor){
                    this.$emit('update:link', {
                        data: this.html,
                        update: 'href' in this.data
                    });
                }
                else {
                    this.$emit('update:link', this.valueFinal);
                }
                if (this.$refs['aidesc']) {
                    this.$refs['aidesc'].onUpdate();
                }

                this.show = false;
            },
            removeLink(){
                this.$emit('update:remove-link');
                this.show = false;
            }
        }

    };
</script>
