export const isValidMetafieldCode = (code?: any): boolean => {
    if (!code || typeof code !== "string") return false
    const regex = /^(app|article|blog|collection|customer|location|order|page|product|shop|variant)\.metafields\.[a-zA-Z0-9_]+\.[a-zA-Z0-9_]+(\..+)?$/;
    return regex.test(code);
};
    
export const safeMetafieldCode = (code: any) => isValidMetafieldCode(code) ? code : "";

export const getMetafieldCodeParts = (code: string) => {
    const parts = code.split(".");

    return {
        resource: parts[0],
        handle: parts[1] || "metafields",
        namespace: parts[2],
        key: parts[3],
        path: parts.slice(4).join(".")
    }
};

export const stringToObject = (path: string, value: any = null) => {
    if (typeof path !== "string" || !path.length) return {};

    return path.split(".").reduceRight((acc: any, key: string) => {
        return { [key]: acc };
    }, value);
}

export const debounce = (func: Function, wait: number) => {
    let timeout: any;
    return (...args: any[]) => {
        clearTimeout(timeout);
        timeout = setTimeout(() => func(...args), wait);
    }
}

export const mergeMetafieldToContext = (context: any, resource: string, namespace: string, key: string, metafield: any) => {
    if (!context) return;

    if (!context[resource] || typeof context[resource] !== 'object') {
        context[resource] = {};
    }

    if (!context[resource].metafields || typeof context[resource].metafields !== 'object') {
        context[resource].metafields = {};
    }

    if (!context[resource].metafields[namespace] || typeof context[resource].metafields[namespace] !== 'object') {
        context[resource].metafields[namespace] = {};
    }

    context[resource].metafields[namespace][key] = metafield;

    return context;
}

export const unwrapResponse = (data: any) => data?.status === "success" && data?.data ? data.data : data;