<template>
    <div class="ecom-element  ecom__progress ecom-html">
        <div class="element__progress-wrapper">
            <div v-if="progressStyle == 'circle'" 
                class="el-progress__pie-circle">
                <div class="el-progress__percent-wrapper"
                    :data-percent="percent"
                >
                    <div class="el-progress__percent-chart">
                        <div class="el-progress__percent-outner" 
                        :style="{
                            backgroundColor:track
                        }">
                            <div class="el-progress__percent-inner">
                                <div v-if="percent" class="el-progress__pie-label">
                                    {{ percent }}
                                </div>
                                <div v-else class="el-progress__pie-label">
                                    0%
                                </div>
                            </div>
                        </div>
                        <svg>
                            <circle class="el-progress__circle" 
                            cx="50%" cy="50%" r="50%"
                            :style="{
                                '--stroke':progressColor
                                }"
                            >

                            </circle>
                        </svg>
                    </div>
                </div>
            </div>
            <div v-else class="el-progress__line">
                <div class="el-porgress__line-wrapper"
                    :style="{backgroundColor:track}"
                >   
                    <div class="el-progress__line-inner"
                        :style="{width:percent,'--progress-line':progressColor, '--progress-line-width': percent}"
                        :data-width-line="percent"
                    >
                        <div class="el-porgress__percent-line "
                            :class="[striped ? 'el-porgress__percent-line--striped': '', animated ? 'el-porgress__percent-line--animated' : '' ]"
                        >
                            <div v-if="percent" class="el-progress__pie-label">
                                {{ percent }}
                            </div>
                            <div v-else class="el-progress__pie-label">
                                0%
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import {Element, Javascript } from '@/mixins';
export default {
    name: 'Progress',
    presets:false,
    linkVideo: 'https://www.youtube.com/watch?v=_x6oFbfVKHw',
    mixins: [Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives:[
                
            ]
        };
    },
    methods: {
        quickToolBar() {
            return ['percent', 'progress', 'track'];
        },
        revokeProgressTimers() {
            if (this.exporting !== false || !this.data?.id) {
                return;
            }
            try {
                window.EComposerBuilder?.contentWindow?.Function(
                    'if(window.__ectimmers && window.__ectimmers["' +
                        this.data.id +
                        '"]) { for(let i in window.__ectimmers["' +
                        this.data.id +
                        '"]) { clearInterval(window.__ectimmers["' +
                        this.data.id +
                        '"][i]); clearTimeout(window.__ectimmers["' +
                        this.data.id +
                        '"][i]); } window.__ectimmers["' +
                        this.data.id +
                        '"] = {}; }'
                ).call({});
            } catch {
                /* noop */
            }
        },
        resetProgressDomState() {
            const $el = this.$el;
            if (!$el) {
                return;
            }
            const lineInner = $el.querySelector('.el-progress__line-inner');
            if (lineInner) {
                lineInner.classList.remove('el-progress__percent-line-animation');
                const lineLabel = lineInner.querySelector('.el-progress__pie-label');
                if (lineLabel) {
                    lineLabel.innerHTML = '';
                }
            }
            const circle = $el.querySelector('.el-progress__circle');
            if (circle) {
                circle.classList.remove('element__progress--percent-circle-animated');
                circle.style.removeProperty('--stroke-dasharray');
                circle.style.removeProperty('--stroke-dashoffset');
                circle.style.removeProperty('stroke-dasharray');
                circle.style.removeProperty('stroke-dashoffset');
                circle.style.removeProperty('stroke');
            }
        },
        syncProgressPreview() {
            if (this.exporting !== false) {
                return;
            }
            this.revokeProgressTimers();
            this.resetProgressDomState();
            this.$nextTick(() => {
                if (typeof this.runJavascript === 'function') {
                    this.runJavascript();
                }
            });
        }
    },
    computed: {

        striped(){
            return this.data.settings?.striped;
        },
        animated(){
            return this.data.settings.animated;
        },
        track() {
            if(typeof this.data.settings?.track === 'object'){
                return `var(--ecom-global-colors-${this.data.settings?.track['global-colors']})`
            }
            return this.data.settings?.track;
        },
        progressColor() {
            if(typeof this.data.settings?.progress === 'object'){
                return `var(--ecom-global-colors-${this.data.settings?.progress['global-colors']})`
            }
            return this.data.settings?.progress;
        },
        percent(){
            return this.data.settings?.percent;
        },
        progressStyle(){
            return this.data.settings?.progress_style;
        },
        getThicknessLine(){
            return this.data.settings?.thickness_line;
        },
        progress() {
            return this.data;
        },
        settings() {
            return [
                {
                    params: [
                        {
                            type: 'popup',
                            name: 'progress_style',
                            label: this.$t('progress_style'),
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: "title",
                                values: {
                                    circle: this.$t('circle'),
                                    line: this.$t('line')
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('show_striped'),
                            name: 'striped',
                            value: true,
                            options: {
                                values:{
                                    on:{
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['progress_style'] === 'line'
                                    );
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            label: this.$t('animation_striped'),
                            name: 'animated',
                            value: true,
                            options: {
                                values:{
                                    on:{
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['progress_style'] === 'line' &&
                                        data['striped'] === true
                                    );
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "percent",
                            label: this.$t('percent'),
                            "options": {
                                "responsive": false,
                                "units": {
                                    "%": {
                                    "min": 0,
                                    "max": 100
                                    }
                                }
                            },
                            "slider": true,
                            "input": true,
                            "min": 0,
                            "max": 100
                        },
                        {
                            type: "color",
                            name: "progress",
                            label: this.$t('progress'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            }
                        },
                        {
                            type: "color",
                            name: "track",
                            label: this.$t('track'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            }
                        },
                        {
                            type: "number",
                            name: "thickness",
                            label: this.$t('thickness'),
                            "options": {
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['progress_style'] === 'circle'
                                    );
                                },
                                "responsive": true,
                                "units": {
                                    "px": {
                                        "min": 5,
                                        "max": 50
                                    }
                                }
                            },
                            "slider": true,
                            "input": true,
                            "min": 5,
                            "max": 50,
                            css: {
                                selector: "root .el-progress__percent-chart svg circle, root .el-progress__percent-outner",
                                properties: {
                                    "stroke-width": "%value%",
                                    "padding": "%value%",
                                    "r": "calc(50% - %value%/2)"
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "thickness_line",
                            label: this.$t('thickness'),
                            "options": {
                                visible: function (data) {
                                    return (
                                        data &&
                                        data['progress_style'] === 'line'
                                    );
                                },
                                "responsive": true,
                                "units": {
                                    "px": {
                                        "min": 5,
                                        "max": 50
                                    }
                                }
                            },
                            "slider": true,
                            "input": true,
                            "min": 5,
                            "max": 50,
                            css: {
                                selector: "root .el-porgress__line-wrapper",
                                properties: {
                                    "height": "%value%"
                                }
                            }
                        }
                        
                    ]
                }
            ];
        },
        style() {
            return [
                {
                    group_alias: "text",
                    options: {
                        group_name: "progress_percent",
                        group_title: this.$t('percent_text'),
                        selector: "root .el-progress__pie-label"
                    }
                }
            ];
        },
        css() {
            return `
                    .el-progress__percent-chart svg{
                        inset: 0;
                        transform: rotate(-90deg);
                        width: 100%;
                        height: 100%;
                        position: absolute;
                    }
                    .el-progress__percent-chart svg circle{
                        fill:none;
                        stroke-width: 10px;
                        cx: 50%;
                        cy: 50%;
                        r: calc(50% - 5px);
                        stroke-linecap: round;
                        box-sizing: border-box;
                        stroke-dashoffset: var(--stroke-dasharray);
                        stroke-dasharray: var(--stroke-dasharray);
                        animation-duration: 1s;
                        animation-timing-function: linear;
                        animation-fill-mode: forwards;
                    }
                    .element__progress--percent-circle-animated{
                        -webkit-animation: progress-circle-anim linear 1s forwards;
                        animation: progress-circle-anim linear 1s forwards;
                    }
                    @keyframes progress-circle-anim{
                        0%{
                            stroke: var(--stroke);
                        }
                        100%{
                            stroke: var(--stroke);
                            stroke-dashoffset: var(--stroke-dashoffset);
                            stroke-dasharray: var(--stroke-dasharray);
                        }
                    }
                    @-webkit-keyframes progress-circle-anim{
                        0%{
                            stroke-dashoffset: var(--stroke-dasharray);

                        }
                        100%{
                            stroke-dashoffset: var(--stroke-dashoffset);
                        }
                    }
                    .el-progress__percent-chart{
                        width: 100%;
                        position: relative;
                        height: 100%;
                        padding-bottom: 100%;
                    }
                    .el-progress__percent-outner{
                        background-color: #f2f2f2;
                        position: absolute;
                        width: 100%;
                        height: 100%;
                        border-radius: 50%;
                        padding: 10px;
                    }
                    .el-progress__percent-inner{
                        background-color: white;
                        width:100%;
                        height: 100%;
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        border-radius: 50%;
                    }
                    .el-progress__pie-label{
                        width: 100%;
                    }
                    .el-porgress__line-wrapper{
                        background-color: rgba(0 0 0 /.1);
                        width: 100%;
                        height: 20px;
                        border-top-left-radius: 10px;
                        border-top-right-radius: 4px;
                        border-bottom-right-radius: 4px;
                        border-bottom-left-radius: 10px;
                    }
                    .el-progress__line-inner{
                        width: 0%;
                        transition: width ease 1s;
                        height: 100%;
                        display: flex;
                        flex-direction: column;
                        justify-content: center;
                        overflow: hidden;
                        color: #fff;
                        text-align: center;
                        white-space: nowrap;
                        border-top-left-radius: 4px;
                        border-top-right-radius: 4px;
                        border-bottom-right-radius: 4px;
                        border-bottom-left-radius: 4px;
                    }
                    .el-porgress__percent-line{
                        width:100%;
                        height: 100%;
                        display: flex;
                        align-items: center;
                    }
                    .el-progress__percent-line-animation{
                        animation: progress-percent-line ease 1s forwards;
                    }
                    @keyframes progress-percent-line{
                        0%{
                            background-color: var(--progress-line);
                            width: 0%;
                        }
                        100%{
                            background-color: var(--progress-line);
                            width: var(--progress-line-width);
                        }
                    }
                    .el-porgress__percent-line--striped{
                        background-image: linear-gradient(
                            -45deg, 
                            rgba(255, 255, 255, .2) 25%, 
                            transparent 25%, 
                            transparent 50%, 
                            rgba(255, 255, 255, .2) 50%, 
                            rgba(255, 255, 255, .2) 75%, 
                            transparent 75%, 
                            transparent
                        );
                        background-size: 20px 20px;
                    }
                    .el-porgress__percent-line--animated{
                        animation: progress-pie-move 2s linear infinite;
                    }
                    .ecom-animation.ecom-visibility--visible{
                        opacity: 1;
                    }
                    @keyframes progress-pie-move {
                        0% {
                            background-position: 0 0;
                        }
                        100% {
                            background-position: 50px 50px;
                        }
                    }
                `;
        },
        default() {
            return {
                    "settings": {
                        "progress_style": "circle",
                        "thickness": "20px",
                        "thickness__tablet": "15px",
                        "thickness__mobile": "10px",
                        "thickness_line": "30px",
                        "progress": "#ff2400",
                        "percent": "34%",
                        "track": "#f2f2f2",
                        "striped": true,
                        "animated": true
                        },
                        "style": {
                            "progress_percent": {
                            "textTextAlign": "center",
                            "textTypography": {
                                "font-size": "30px",
                                "font-weight": "600"
                            },
                            "textColor": "#403c3c"
                            }
                        }
                    }
        },

        javascript(){
            return function(){
                if(!this.$el)
                {
                    return false;
                }
                const $el = this.$el;
                const progressId = this.id;
                if (window.__ecomProgressRO?.[progressId]) {
                    window.__ecomProgressRO[progressId].disconnect();
                    delete window.__ecomProgressRO[progressId];
                }
                $el.style.opacity = 0;
                setTimeout(function() {
                    $el.style.opacity = 1;
                },100);
                function renderLine(){
                    const element_percent_wrapper = $el.querySelector('.el-porgress__line-wrapper');
                    const element_percent_line = $el.querySelector('.el-progress__line-inner');
                    if(!element_percent_line) return false;
                    element_percent_line.classList.remove("el-progress__percent-line-animation");
                    let element_label = element_percent_line.querySelector('.el-progress__pie-label');
                    element_label.innerHTML = '';
                    createObserver(element_percent_line);
                    function createObserver(element){
                        let options = {
                            root: null,
                            rootMargin: "0px",
                            threshold: 0.5
                        };
                        let observer = new IntersectionObserver(handleIntersect, options);
                        observer.observe(element);
                    }
                    function handleIntersect(entries, observer){
                        entries.forEach(function(entry){
                            if(entry.intersectionRatio > 0.0) {
                                function countUp(element) {
                                    let x = 0;
                                    let y = parseFloat(element_percent_line.dataset.widthLine)||0; 
                                    if(y==0) return;
                                    function addNum() {
                                        element.innerHTML = `${x}%`;
                                        x += 1;
                                        if (x > y) {
                                            element.innerHTML = `${y}%`;
                                        clearInterval(timer);
                                        }
                                    }
                                    let timer = window.setInterval(addNum, 1000/parseFloat(element_percent_line.dataset.widthLine));
                                }
                                element_percent_line.classList.add('el-progress__percent-line-animation');
                                if(element_percent_line.dataset.widthLine=='100%'){
                                    element_percent_wrapper.style.borderTopRightRadius = '10px';
                                    element_percent_wrapper.style.borderBottomRightRadius = '10px';
                                }
                                countUp(element_label);
                                observer.unobserve(element_percent_line);
                            }
                        });
                    }
                }
                function renderCircle() {
                    const elements_progress = $el.querySelector(".el-progress__percent-wrapper");
                    const elements_circle = $el.querySelector(".el-progress__circle");
                    if(!elements_progress || !elements_circle) return false;
                    elements_circle.classList.remove("element__progress--percent-circle-animated");
                    function handleIntersect(entries, observer) {
                        entries.forEach((entry) => {
                            if (entry.intersectionRatio > 0.0) {
                                function countUp(element) {
                                    let x = 0;
                                    let y = parseFloat(entry.target.dataset.percent)||0; 
                                    if(y==0) return;
                                    function addNum() {
                                        element.innerHTML = `${x}%`;
                                        x += 1;
                                        if (x > y) {
                                            element.innerHTML = `${y}%`;
                                        clearInterval(timer);
                                        }
                                    }
                                    let timer = window.setInterval(addNum, 1000/parseFloat(entry.target.dataset.percent));
                                }
                                let element_circle = entry.target.querySelector(".el-progress__circle");
                                let elements_label = entry.target.querySelector(".el-progress__pie-label");
                                let width = parseFloat(elements_circle.getBoundingClientRect().width);
                                    let dasharray = (width)*Math.PI;
                                    let dashoffset = dasharray;
                                    if(elements_progress){
                                        dashoffset = (width)*Math.PI - (width)*Math.PI*parseFloat(elements_progress.dataset.percent)/100;
                                    }
                                    const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent) || 
                                                    /iPad|iPhone|iPod/.test(navigator.platform) ||
                                                    (navigator.maxTouchPoints && navigator.maxTouchPoints > 2 && /MacIntel/.test(navigator.platform)); // Hỗ trợ iPad Pro đời mới chạy iPadOS

                                    if (isSafari) {
                                    // setTimeout(function(){
                                        elements_circle.style.setProperty('stroke-dasharray',dasharray);
                                        elements_circle.style.setProperty('stroke-dashoffset',dasharray);
                                        elements_circle.style.setProperty('stroke','var(--stroke)');
                                        let a = (dasharray - dashoffset)/50;
                                        let b = 0;  
                                        const interval = setInterval(function() {
                                            b += a;
                                            elements_circle.style.setProperty('stroke-dashoffset',dasharray - b);
                                            if(b > dasharray - dashoffset || dasharray - dashoffset == 0) {
                                                elements_circle.style.setProperty('stroke-dashoffset',dashoffset);
                                                clearInterval(interval);
                                            }
                                        }, 20);
                                        countUp(elements_label);
                                    // }, 2000);
                                }
                                else {
                                    element_circle.classList.add("element__progress--percent-circle-animated");
                                    elements_circle.style.setProperty('--stroke-dasharray',dasharray);
                                    elements_circle.style.setProperty('--stroke-dashoffset',dashoffset);
                                    countUp(elements_label);
                                }
                                observer.unobserve(entry.target);
                                
                            } 
                        });
                    }
                    function createObserver() {
                        let options = {
                            root: null,
                            rootMargin: "0px",
                            threshold: 0.5
                        };
                        let observer = new IntersectionObserver(handleIntersect, options);
                        observer.observe(elements_progress);
                    }
                    createObserver();
                }
                
                const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent) || 
                                /iPad|iPhone|iPod/.test(navigator.platform) ||
                                (navigator.maxTouchPoints && navigator.maxTouchPoints > 2 && /MacIntel/.test(navigator.platform)); // Hỗ trợ iPad Pro đời mới chạy iPadOS

                if (isSafari) {
                    setTimeout(renderCircle, 2000);
                    setTimeout(renderLine, 2000);
                }
                else {
                    // dont work in safari
                    let ro = new ResizeObserver(function(entries) {
                        entries.forEach(function(entry){
                            if(entry.contentBoxSize){
                                setTimeout(renderCircle,150);
                                setTimeout(renderLine, 150);
                            }
                        });
                    });
                    window.__ecomProgressRO = window.__ecomProgressRO || {};
                    window.__ecomProgressRO[progressId] = ro;
                    ro.observe($el);
                }
                
                
            }
        }
    },
    watch: {
        'data.settings.percent'() {
            this.syncProgressPreview();
        },
        'data.settings.progress'() {
            this.syncProgressPreview();
        },
        'data.settings.track'() {
            this.syncProgressPreview();
        },
        'data.settings.progress_style'() {
            this.syncProgressPreview();
        }
    },
    beforeUnmount() {
        this.revokeProgressTimers();
        const progressId = this.data?.id;
        if (progressId && window.__ecomProgressRO?.[progressId]) {
            window.__ecomProgressRO[progressId].disconnect();
            delete window.__ecomProgressRO[progressId];
        }
    },
    mounted() {
    }
};
</script>

