<template>
    <div class="ecom-element ecom-shopify-elements ecom-shopify__blog--count">
        <div class="ecom-shopify__blog--count-wrapper">
            <div class="ecom-shopify__blog--count-inner" v-html="liquid('blogArticlesCount')" />
        </div>
    </div>
</template>

<script>
import { Liquid, Element } from '@/mixins';

export default {
    name: 'BlogArticlesCount',
    mixins: [Liquid, Element],

    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        liquids() {
            return {
                blogArticlesCount: {
                    code: `
                        {%- if  blog != blank -%}
                            {% assign count = blog.articles_count%}
                            {% if count == 1 %}
                                {% assign article_count = count %}
                                ${this.lang(this.data?.settings?.articleCountText ?? '', 'articles_count_text', {article_count: 'article_count'})}
                            {% else %}
                                {% assign articles_count = count %}
                                ${this.lang(this.data?.settings?.articlesCountText ??'','articles_count_text', {articles_count: 'articles_count'})} 
                            {% endif %}
                        {%- else -%}
                            <div>Please select the blog in settings</div>
                        {%- endif -%}
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-col-12">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-9 ecom-skeleton-big"></div>
                                </div>
                            </div>
                        </div>
                    `
                }
            };
        },

        requestShopifyType() {
            return {
                shopify_type: 'blog'
            };
        },

        settings() {
            return [
                {
                    group_title: '',
                    params: [
                        {
                            type: 'text',
                            name: 'articleCountText',
                            label: this.$t('article_text_count'),
                            placeholder: '{{article_count}}',
                            description: this.$t('use_article_count_to_show_article_count'),
                        },
                        {
                            type: 'text',
                            name: 'articlesCountText',
                            label: this.$t('articles_text_count'),
                            placeholder: '{{articles_count}}',
                            description: this.$t('use_articles_count_to_show_blog_posts_count'),
                        },
                    ]
                }
            ];
        },

        style() {
            return [
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: '',
                        selector: ' .ecom-shopify__blog--count-inner',
                        group_name: 'blog_artilces_count'
                    }
                }
            ];
        },

        default() {
            return {
                settings: {
                    articleCountText: "{{ article_count }} article",
                    articlesCountText: "{{ articles_count }} blog posts"
                },
                style: {
                    blog_artilces_count: {
                        textTextAlign: "left"
                    }
                }
            }
        }
    }
};
</script>
