        javascript() {
            return function () {
                // if (this.isLive) {
                    const $el = this.$el;
                    const buttons = $el.querySelectorAll('.ecom-collection__layout-switch-item button');
                    const productGrids = $el.closest(".ecom-sections").querySelectorAll('.ecom-collection__product--wrapper-items.ecom-collection-product__layout-grid');
                    if(buttons.length && productGrids.length) {
                        const firstProductGrid = productGrids[0];
                        buttons.forEach(function(button) {
                            button.classList.remove('ecom-active-item');
                            if (button.dataset.col == firstProductGrid.dataset.gridColumn && window.screen.width > 1024) {
                                button.classList.add('ecom-active-item');
                            }
                            if (button.dataset.col == firstProductGrid.dataset.gridColumnTablet && window.screen.width > 767 && window.screen.width <= 1024) {
                                button.classList.add('ecom-active-item');
                            }
                            if (button.dataset.col == firstProductGrid.dataset.gridColumnMobile && window.screen.width <= 767) {
                                button.classList.add('ecom-active-item');
                            }
                            button.addEventListener('click', function (e) {
                                const productGridsNew = $el.closest(".ecom-sections").querySelectorAll('.ecom-collection__product--wrapper-items.ecom-collection-product__layout-grid');
                                buttons.forEach(function(button) {
                                    button.classList.remove('ecom-active-item');
                                });
                                const col = this.dataset.col;
                                productGridsNew.forEach(function(productGrid) {
                                    productGrid.style.gridTemplateColumns = `repeat(${col}, minmax(0, 1fr))`;
                                });
                                this.classList.add('ecom-active-item');
                            });
                        })
                    }
                        
                // }
            };
        },
        requestShopifyType() {
