/**
 * Resolve một đường dẫn dạng "columns[0].blocks[0].row.columns[0]" thành object
 */
export const resolvePath = (obj: any, path: string): any => {
    if (!path) return obj;
    const parts = path.match(/([a-zA-Z_]+)|\[(\d+)\]/g);
    if (!parts) return undefined;

    let current = obj;
    for (const part of parts) {
        if (!current) return undefined;
        if (part.startsWith("[")) {
            const idx = parseInt(part.slice(1, -1));
            current = current[idx];
        } else {
            current = current[part];
        }
    }
    return current;
};

const findNodeById = (node: any, id?: string): any => {
    if (!node || typeof node !== 'object' || !id) return undefined;
    if (node.id === id) return node;

    for (const key of ['rows', 'columns', 'blocks']) {
        if (Array.isArray(node[key])) {
            for (const child of node[key]) {
                const found = findNodeById(child, id);
                if (found) return found;
            }
        }
    }
    if (node.row) {
        const found = findNodeById(node.row, id);
        if (found) return found;
    }
    if (node.group?.settings?.items && Array.isArray(node.group.settings.items)) {
        for (const child of node.group.settings.items) {
            const found = findNodeById(child, id);
            if (found) return found;
        }
    }

    return undefined;
};

const resolveBackgroundTarget = (sectionJSON: any, el: ExtractedElement): any => {
    const pathTarget = resolvePath(sectionJSON, el.path);
    if (pathTarget?.style?.background?.backgroundnormalmode?.classic) {
        return pathTarget;
    }

    const idTarget = findNodeById(sectionJSON, el.id);
    if (idTarget?.style?.background?.backgroundnormalmode?.classic) {
        return idTarget;
    }

    return undefined;
};

/**
 * URL media hợp lệ = đã được resolve thành URL thật:
 * không còn placeholder <!--...-->, không còn ref IMG_x/VIDEO_x chưa resolve,
 * và không phải sentinel "KEEP" (AI trả về khi quyết định giữ nguyên ảnh gốc).
 */
const isResolvedMediaUrl = (val: any): boolean =>
    typeof val === 'string'
    && !!val.trim()
    && !val.includes('<!--')
    && !/^(IMG|VIDEO)_\d+$/.test(val.trim())
    && val.trim().toUpperCase() !== 'KEEP';

/**
 * Token động trong label template: `{price}`, `{{sale}}`, `{_start}`, `[%-W]`, `%!W`.
 * Mất token là label hiển thị sai số/giá → phải giữ bản gốc.
 */
const PLACEHOLDER_TOKEN = /\{\{[^}]+\}\}|\{[^}\s]+\}|\[%[^\]]*\]|%![A-Za-z]/g;

/**
 * Đếm số thẻ `<a>` (mở + đóng) trong chuỗi, vd `<a href="...">Shipping</a>` → 2.
 * CHỈ xét thẻ `<a>` — thẻ có href chức năng (mất là hỏng link), không xét các thẻ
 * trình bày như `<span>`, `<strong>`, `<br>`: AI dịch xong đổi nhẹ markup trình bày là
 * bình thường, revert nhầm những field đó sẽ tái tạo lại đúng bug "chưa dịch" đang fix.
 */
const countAnchorTags = (val: string): number => (val.match(/<\/?a\b/gi) || []).length;
// true nếu `val` bị mất thẻ <a> so với `source` (link bị hỏng/rớt khi AI dịch).
const isMissingHtmlTags = (source: string, val: string): boolean => {
    const sourceCount = countAnchorTags(source);
    if (!sourceCount) return false;
    return countAnchorTags(val) < sourceCount;
};

/**
 * Bỏ các field mà AI làm mất placeholder hoặc làm hỏng thẻ HTML so với bản gốc → nhánh
 * merge thấy undefined và giữ nguyên giá trị template. Nhờ guard này mới dám whitelist
 * các label chứa placeholder/thẻ HTML (sale_text, bage_sale, text_week, shipping_policy...)
 * để chúng được dịch.
 */
const dropBrokenPlaceholders = (edited: any, original: any) => {
    if (!edited || typeof edited !== 'object' || !original || typeof original !== 'object') return;
    for (const [key, val] of Object.entries(edited)) {
        if (typeof val !== 'string') continue;
        const source = original[key];
        if (typeof source !== 'string') continue;

        const tokens = source.match(PLACEHOLDER_TOKEN);
        if (tokens?.length && tokens.some(token => !val.includes(token))) {
            console.warn('[AI-Import][merge] bỏ field vì AI làm mất placeholder', { key, source, ai: val });
            delete edited[key];
            continue;
        }

        if (isMissingHtmlTags(source, val)) {
            console.warn('[AI-Import][merge] bỏ field vì AI làm hỏng thẻ HTML', { key, source, ai: val });
            delete edited[key];
        }
    }
};

const getVideoSourceType = (url: string): 'youtube' | 'vimeo' | 'hosted' => {
    if (/youtu\.be|youtube\.com/i.test(url)) return 'youtube';
    if (/vimeo\.com/i.test(url)) return 'vimeo';
    return 'hosted';
};

/**
 * Xác nhận node resolve từ path đúng là element AI đang trả về.
 * AI đôi khi gán nhầm id (mượn id của element khác trong section) → không được
 * dựa vào id một mình. Path là toạ độ tin cậy; id khớp HOẶC name khớp với node
 * tại path đó là đủ để merge — id lệch + name lệch mới coi là path sai.
 */
const isSameElement = (target: any, el: ExtractedElement): boolean =>
    target?.id === el.id
    || (typeof target?.name === 'string' && typeof el.name === 'string'
        && target.name.toLowerCase() === el.name.toLowerCase());

/**
 * Merge các settings đã chỉnh sửa bởi AI ngược lại vào section JSON gốc.
 * Tìm element theo path + id match, Object.assign chỉ các key đã thay đổi.
 */
export const mergeEditedContent = (sectionJSON: any, editedElements: ExtractedElement[]): number => {
    let merged = 0;
    for (const el of editedElements) {
        const target = resolvePath(sectionJSON, el.path);
        if (!target) continue;

        // AI trả "KEEP" = cố ý giữ nguyên nội dung template (không liên quan sản phẩm).
        // Xoá key trước khi vào các nhánh merge → nhánh thấy undefined và bỏ qua field đó.
        const keepCtx = { sectionId: sectionJSON?.id || '-', elementName: `${el.name}#${el.id}`, scope: 'settings' };
        stripKeepFields(el.settings, keepCtx);
        stripKeepFields((el as any).style, { ...keepCtx, scope: 'style' });

        // Giữ nguyên label gốc khi AI làm mất placeholder ({price}, {{sale}}, [%-W]...).
        // `target.settings` cho element thường, `target` cho các *-item (field ở root).
        dropBrokenPlaceholders(el.settings, target.settings || target);

        // Text drop-cap đánh số: số dẫn đầu đã bị tách trước khi gửi AI (xem extractElements).
        // Lấy lại prefix từ content GỐC (target chưa bị ghi đè ở thời điểm này) và gắn vào
        // đầu content mới, để badge :first-letter vẫn ra đúng số thứ tự.
        if (el.name === 'text' && typeof el.settings?.content === 'string' && target.settings?.dropcap) {
            const dropcap = splitDropcapNumber(target.settings.content);
            if (dropcap) el.settings.content = restoreDropcapPrefix(el.settings.content, dropcap.prefix);
        }

        if (el.name === 'iconlist-item') {
            // iconlist-item: target IS the item object directly (no .settings sub-object)
            // AI may return path as id, so skip id check — trust path resolution
            // Only merge text-editable fields, preserve original icon SVG
            // Loại `type` ra khỏi phần merge: nếu AI trả `type: 'image'` cho item vốn
            // là icon SVG, item bị lật sang dạng ảnh → render <img> rỗng, phá spacing
            // (block dính nhau / block rỗng chen giữa).
            const { icon, id, image, type, ...editableFields } = el.settings;
            Object.assign(target, editableFields);
            // Ảnh của item (type === 'image'): chỉ merge khi AI trả về URL đã resolve,
            // nếu không thì giữ nguyên ảnh gốc (tránh ghi placeholder làm vỡ ảnh).
            if (image?.value && isResolvedMediaUrl(image.value)) {
                target.image = {
                    ...(target.image || {}),
                    value: image.value,
                    thumbnail: isResolvedMediaUrl(image.thumbnail) ? image.thumbnail : image.value,
                    ...(image.alt && !image.alt.includes('<!--') ? { name: image.alt } : {}),
                };
            }
            merged++;
        } else if (el.name === 'featuredbox-item') {
            // FeaturedBox item: target IS the item object directly
            // Merge text-editable fields + thumbnail image, preserve box_icon/link
            const { subTitle, title, text, content, tag, thumbnail } = el.settings;
            if (subTitle !== undefined) target.subTitle = subTitle;
            if (title !== undefined) target.title = title;
            if (text !== undefined) target.text = text;
            if (content !== undefined) target.content = content;
            if (tag !== undefined) target.tag = tag;
            // Thumbnail: chỉ merge khi AI trả URL đã resolve (hỗ trợ cả dạng object và string cũ)
            const fbThumbValue = typeof thumbnail === 'string' ? thumbnail : thumbnail?.value;
            if (fbThumbValue && isResolvedMediaUrl(fbThumbValue)) {
                const fbThumbPreview = isResolvedMediaUrl(thumbnail?.thumbnail) ? thumbnail.thumbnail : fbThumbValue;
                target.thumbnail = {
                    ...(typeof target.thumbnail === 'object' ? target.thumbnail : {}),
                    value: fbThumbValue,
                    // Giữ `thumbnail` đồng bộ với `value`, nếu không nó còn trỏ ảnh template cũ
                    thumbnail: fbThumbPreview,
                    ...(thumbnail?.alt && !thumbnail.alt.includes('<!--') ? { name: thumbnail.alt } : {}),
                };
            }
            merged++;
        } else if (el.name === 'timeline-item') {
            // Timeline item: target IS the item object directly
            // Only merge text-editable fields, preserve image/link/icon
            const { title, content, date } = el.settings;
            if (title !== undefined) target.title = title;
            if (content !== undefined) target.content = content;
            if (date !== undefined) target.date = date;
            merged++;
        } else if (el.name === 'textmarquee-item') {
            // TextMarquee item: target IS the item object directly
            // Only merge text field, preserve icon/image/link
            const { text } = el.settings;
            if (text !== undefined) target.text = text;
            merged++;
        } else if (el.name === 'accordion-item') {
            // Accordion item: only merge title, preserve icon/image/tag/content_type
            const { title } = el.settings;
            if (title !== undefined) target.title = title;
            merged++;
        } else if (el.name === 'testimonial-item') {
            // Testimonial item: merge name, title, text; preserve image/rating/quote/icon
            const { name, title, text } = el.settings;
            if (name !== undefined) target.name = name;
            if (title !== undefined) target.title = title;
            if (text !== undefined) target.text = text;
            merged++;
        } else if (el.name === 'banner' && isSameElement(target, el) && target.settings) {
            // Banner: merge generated copy and product image while preserving overlay/link settings.
            if (el.settings.heading !== undefined) target.settings.heading = el.settings.heading;
            if (el.settings.subheading !== undefined) target.settings.subheading = el.settings.subheading;
            if (el.settings.content !== undefined) target.settings.content = el.settings.content;
            if (el.settings.tag_sub_heading !== undefined) target.settings.tag_sub_heading = el.settings.tag_sub_heading;
            if (el.settings.button?.content !== undefined) {
                if (!target.settings.button) target.settings.button = {};
                target.settings.button.content = el.settings.button.content;
            }
            // Payload gửi lên là dạng lồng `image.image.{value,thumbnail}`, nhưng AI hay
            // trả phẳng `image.{value,thumbnail}` (giống element image). Nhận cả 2 dạng,
            // nếu không ảnh banner trong slider/carousel không bao giờ được merge.
            const aiImage = isResolvedMediaUrl(el.settings?.image?.image?.value)
                ? el.settings.image.image
                : el.settings?.image;
            if (isResolvedMediaUrl(aiImage?.value)) {
                const imageSettings = target.settings.image || {};
                target.settings.image = {
                    ...imageSettings,
                    image: {
                        ...(imageSettings.image || {}),
                        value: aiImage.value,
                        thumbnail: aiImage.thumbnail || aiImage.value,
                        alt: aiImage.alt || imageSettings.image?.alt,
                    }
                };
            }
            merged++;
        } else if ((el.name === 'video' || el.name === 'Video') && isSameElement(target, el) && target.settings) {
            const aiVideoUrl = [el.settings?.link, el.settings?.srcYoutube, el.settings?.srcVimeo]
                .find((url: any) => isResolvedMediaUrl(url));
            const aiPoster = el.settings?.poster_image;
            if (aiVideoUrl) {
                const source = getVideoSourceType(aiVideoUrl);
                target.settings = {
                    ...target.settings,
                    source,
                    ...(source === 'youtube' ? { srcYoutube: aiVideoUrl } : {}),
                    ...(source === 'vimeo' ? { srcVimeo: aiVideoUrl } : {}),
                    ...(source === 'hosted' ? { link: aiVideoUrl } : {}),
                };
                merged++;
            }
            if (isResolvedMediaUrl(aiPoster?.value)) {
                target.settings = {
                    ...target.settings,
                    poster_image: {
                        ...(target.settings.poster_image || {}),
                        value: aiPoster.value,
                        thumbnail: aiPoster.thumbnail || aiPoster.value,
                        alt: aiPoster.alt || target.settings.poster_image?.alt,
                    }
                };
                merged++;
            }
        } else if (el.name === 'image' && isSameElement(target, el) && target.settings) {
            // Image element: AI returns { image: { thumbnail, value }, caption }
            // Map to builder's format: settings.src = { value, thumbnail }, settings.alt = caption
            const aiImage = el.settings?.image || {};

            // Chỉ ghi đè khi URL đã resolve — placeholder/IMG_x chưa resolve thì giữ ảnh gốc
            if (isResolvedMediaUrl(aiImage.value)) {
                target.settings.image = {
                    ...(target.settings?.image || {}),
                    value: aiImage.value,
                    thumbnail: isResolvedMediaUrl(aiImage.thumbnail) ? aiImage.thumbnail : aiImage.value,
                };
            }
            if (el.settings.caption && !String(el.settings.caption).includes('<!--')) {
                target.settings.alt = el.settings.caption;
            }
            merged++;

        } else if (el.name === 'wheelspin' && isSameElement(target, el) && target.settings) {
            // WheelSpin parent: only merge text heading fields
            if (el.settings.heading_win !== undefined) target.settings.heading_win = el.settings.heading_win;
            if (el.settings.heading_lose !== undefined) target.settings.heading_lose = el.settings.heading_lose;
            if (el.settings.heading_center !== undefined) target.settings.heading_center = el.settings.heading_center;
            merged++;
        } else if (el.name === 'wheelspin-item') {
            // WheelSpin option item: only merge title
            const { title } = el.settings;
            if (title !== undefined) target.title = title;
            merged++;
        } else if (el.name === 'testimonial-item') {
            // Testimonial item: fields are at root level, not inside .settings
            const { name, title, text } = el.settings;
            if (name !== undefined) target.name = name;
            if (title !== undefined) target.title = title;
            if (text !== undefined) target.text = text;
            merged++;
        } else if (el.name === 'accordion-item') {
            // Accordion item: title is at root level
            const { title } = el.settings;
            if (title !== undefined) target.title = title;
            merged++;
        } else if (el.name === 'timeline-item') {
            // Timeline item: fields are at root level
            const { title, content, date } = el.settings;
            if (title !== undefined) target.title = title;
            if (content !== undefined) target.content = content;
            if (date !== undefined) target.date = date;
            merged++;
        } else if (el.name === 'textmarquee-item') {
            // TextMarquee item: text is at root level
            const { text } = el.settings;
            if (text !== undefined) target.text = text;
            merged++;
        } else if (el.name === 'tab-item') {
            // Tab item: title and sub_title are at root level
            const { title, sub_title } = el.settings;
            if (title !== undefined) target.title = title;
            if (sub_title !== undefined) target.sub_title = sub_title;
            merged++;
        } else if (el.name === 'mediaaccordion-item') {
            // MediaAccordion item: heading/subheading in .content, button text in .button
            const { heading, subheading, button_content } = el.settings;
            if (!target.content) target.content = {};
            if (heading !== undefined) target.content.heading = heading;
            if (subheading !== undefined) target.content.subheading = subheading;
            if (button_content !== undefined) {
                if (!target.button) target.button = {};
                target.button.content = button_content;
            }
            merged++;
        } else if (el.name === 'masonry-item') {
            // Masonry item: heading/subheading/content in .content, button text in .button
            const { heading, subheading, content, button_content } = el.settings;
            if (!target.content) target.content = {};
            if (heading !== undefined) target.content.heading = heading;
            if (subheading !== undefined) target.content.subheading = subheading;
            if (content !== undefined) target.content.content = content;
            if (button_content !== undefined) {
                if (!target.button) target.button = {};
                target.button.content = button_content;
            }
            merged++;
        } else if (el.name === 'storelocator-item') {
            // StoreLocator item: name, location, detail at root level
            const { name, location, detail } = el.settings;
            if (name !== undefined) target.name = name;
            if (location !== undefined) target.location = location;
            if (detail !== undefined) target.detail = detail;
            merged++;
        } else if (el.name === 'contactform' && isSameElement(target, el) && target.settings) {
            // ContactForm main: button_title, success_message at settings root
            if (el.settings.button_title !== undefined) target.settings.button_title = el.settings.button_title;
            if (el.settings.success_message !== undefined) target.settings.success_message = el.settings.success_message;
            merged++;
        } else if (el.name === 'contactform-field') {
            // ContactForm field: label/placeholder inside field.settings
            if (!target.settings) target.settings = {};
            if (el.settings.label !== undefined) target.settings.label = el.settings.label;
            if (el.settings.placeholder !== undefined) target.settings.placeholder = el.settings.placeholder;
            merged++;
        } else if (el.name === 'lightbox' && isSameElement(target, el) && target.settings) {
            // Lightbox: button_title, custom_heading_content, custom_content at settings root
            if (el.settings.button_title !== undefined) target.settings.button_title = el.settings.button_title;
            if (el.settings.custom_heading_content !== undefined) target.settings.custom_heading_content = el.settings.custom_heading_content;
            if (el.settings.custom_content !== undefined) target.settings.custom_content = el.settings.custom_content;
            merged++;
        } else if (el.name === 'imageComparison' && isSameElement(target, el) && target.settings) {
            if (el.settings.beforeText !== undefined) target.settings.beforeText = el.settings.beforeText;
            if (el.settings.afterText !== undefined) target.settings.afterText = el.settings.afterText;
            // Chỉ ghi ảnh đã resolve — placeholder/KEEP thì giữ ảnh gốc của template
            if (isResolvedMediaUrl(el.settings.beforeImage?.value)) {
                target.settings.beforeImage = {
                    ...(target.settings.beforeImage || {}),
                    value: el.settings.beforeImage.value,
                    thumbnail: isResolvedMediaUrl(el.settings.beforeImage.thumbnail) ? el.settings.beforeImage.thumbnail : el.settings.beforeImage.value,
                };
            }
            if (isResolvedMediaUrl(el.settings.afterImage?.value)) {
                target.settings.afterImage = {
                    ...(target.settings.afterImage || {}),
                    value: el.settings.afterImage.value,
                    thumbnail: isResolvedMediaUrl(el.settings.afterImage.thumbnail) ? el.settings.afterImage.thumbnail : el.settings.afterImage.value,
                };
            }
            merged++;
        } else if (el.name === 'imageHotSpots' && isSameElement(target, el) && target.settings) {
            // Ảnh nền chính của hotspot (settings.image) — cùng format với element image thường.
            const aiImage = el.settings?.image || {};
            if (isResolvedMediaUrl(aiImage.value)) {
                target.settings.image = {
                    ...(target.settings?.image || {}),
                    value: aiImage.value,
                    thumbnail: isResolvedMediaUrl(aiImage.thumbnail) ? aiImage.thumbnail : aiImage.value,
                };
            }
            merged++;
        } else if (el.name === 'imagehotspot-item') {
            // ImageHotSpots item: text fields at root level of each item
            if (el.settings.hotspotLabel !== undefined) target.hotspotLabel = el.settings.hotspotLabel;
            if (el.settings.titleCard !== undefined) target.titleCard = el.settings.titleCard;
            if (el.settings.textCard !== undefined) target.textCard = el.settings.textCard;
            if (el.settings.button_label !== undefined) target.button_label = el.settings.button_label;
            merged++;
        } else if (el.name === 'table') {
            // Table: settings keys are "heading:column-X" và "data:column-XY". Chỉ merge
            // đúng key đã tồn tại trong schema gốc (table_heading/table_data) và giá trị là
            // chuỗi không rỗng — tránh AI trả về key lạ/cấu trúc khác làm vỡ bảng spec.
            const tableTarget = resolvePath(sectionJSON, el.path);
            if (tableTarget?.settings) {
                const originalHeading = tableTarget.settings.table_heading || {};
                const originalData = tableTarget.settings.table_data || {};
                Object.entries(el.settings).forEach(([key, val]) => {
                    if (typeof val !== 'string' || !val.trim()) return;
                    if (key.startsWith('heading:')) {
                        const realKey = key.replace('heading:', '');
                        if (!(realKey in originalHeading)) return;
                        if (!tableTarget.settings.table_heading) tableTarget.settings.table_heading = {};
                        tableTarget.settings.table_heading[realKey] = val;
                    } else if (key.startsWith('data:')) {
                        const realKey = key.replace('data:', '');
                        if (!(realKey in originalData)) return;
                        if (!tableTarget.settings.table_data) tableTarget.settings.table_data = {};
                        tableTarget.settings.table_data[realKey] = val;
                    }
                });
                merged++;
            }
        } else if (el.name === 'breadcrumbs') {
            // Breadcrumb: home_text, cart_page_title in settings.general
            if (!target.settings) target.settings = {};
            if (!target.settings.general) target.settings.general = {};
            if (el.settings.home_text !== undefined) target.settings.general.home_text = el.settings.home_text;
            if (el.settings.cart_page_title !== undefined) target.settings.general.cart_page_title = el.settings.cart_page_title;
            merged++;
        } else if (el.name === 'shopifyProductFilter' && isSameElement(target, el) && target.settings) {
            // ProductFilter: button_title at settings root
            if (el.settings.button_title !== undefined) target.settings.button_title = el.settings.button_title;
            merged++;
        } else if (el.name === 'productfilter-item') {
            // ProductFilter filter item: label, placeholder inside filter.settings
            if (!target.settings) target.settings = {};
            if (el.settings.label !== undefined) target.settings.label = el.settings.label;
            if (el.settings.placeholder !== undefined) target.settings.placeholder = el.settings.placeholder;
            merged++;
        } else if (el.name === 'couponcode-item') {
            // CouponCodes item: text fields at root level of each item
            if (el.settings.sale_value_badge !== undefined) target.sale_value_badge = el.settings.sale_value_badge;
            if (el.settings.label !== undefined) target.label = el.settings.label;
            if (el.settings.coupon_code !== undefined) target.coupon_code = el.settings.coupon_code;
            if (el.settings.copy_label !== undefined) target.copy_label = el.settings.copy_label;
            if (el.settings.copied_label !== undefined) target.copied_label = el.settings.copied_label;
            merged++;
        } else if (el.name === 'productPaymentMethod' && isSameElement(target, el) && target.settings) {
            // PaymentMethod: message at settings root
            if (el.settings.message !== undefined) target.settings.message = el.settings.message;
            merged++;
        } else if (el.name === 'search' && isSameElement(target, el) && target.settings) {
            // Search: placeholder, search_button_title at settings root
            if (el.settings.placeholder !== undefined) target.settings.placeholder = el.settings.placeholder;
            if (el.settings.search_button_title !== undefined) target.settings.search_button_title = el.settings.search_button_title;
            merged++;
        } else if (el.name === 'productDeliveryTime' && isSameElement(target, el) && target.settings) {
            if (el.settings.delivery_text !== undefined) target.settings.delivery_text = el.settings.delivery_text;
            if (el.settings.delivery_text_hours !== undefined) target.settings.delivery_text_hours = el.settings.delivery_text_hours;
            if (el.settings.delivery_text_minutes !== undefined) target.settings.delivery_text_minutes = el.settings.delivery_text_minutes;
            if (el.settings.delivery_custom_dow !== undefined) target.settings.delivery_custom_dow = el.settings.delivery_custom_dow;
            if (el.settings.delivery_custom_month !== undefined) target.settings.delivery_custom_month = el.settings.delivery_custom_month;
            merged++;
        } else if (el.name === 'productBuyItNow' && isSameElement(target, el) && target.settings) {
            if (el.settings.label !== undefined) target.settings.label = el.settings.label;
            merged++;
        } else if (el.name === 'productBuyNow' && isSameElement(target, el) && target.settings) {
            if (el.settings.label !== undefined) target.settings.label = el.settings.label;
            merged++;
        } else if (el.name === 'productQuantity' && isSameElement(target, el) && target.settings) {
            if (el.settings.title !== undefined) target.settings.title = el.settings.title;
            merged++;
        } else if (el.name === 'productVariantAttribute' && isSameElement(target, el) && target.settings) {
            if (el.settings.sku_text !== undefined) target.settings.sku_text = el.settings.sku_text;
            if (el.settings.barcode_text !== undefined) target.settings.barcode_text = el.settings.barcode_text;
            merged++;
        } else if (el.name === 'productInventory' && isSameElement(target, el) && target.settings) {
            if (el.settings.instock_text !== undefined) target.settings.instock_text = el.settings.instock_text;
            if (el.settings.outstock_text !== undefined) target.settings.outstock_text = el.settings.outstock_text;
            if (el.settings.unavailable_text !== undefined) target.settings.unavailable_text = el.settings.unavailable_text;
            if (el.settings.preorder_text !== undefined) target.settings.preorder_text = el.settings.preorder_text;
            if (el.settings.inventory_text !== undefined) target.settings.inventory_text = el.settings.inventory_text;
            if (el.settings.incoming_date_text !== undefined) target.settings.incoming_date_text = el.settings.incoming_date_text;
            merged++;
        } else if (el.name === 'productSellingPlan' && isSameElement(target, el) && target.settings) {
            if (el.settings.title !== undefined) target.settings.title = el.settings.title;
            if (el.settings.one_time_text !== undefined) target.settings.one_time_text = el.settings.one_time_text;
            if (el.settings.subscription_text !== undefined) target.settings.subscription_text = el.settings.subscription_text;
            if (el.settings.frequency_header !== undefined) target.settings.frequency_header = el.settings.frequency_header;
            merged++;
        } else if (el.name === 'productProperty-item') {
            // ProductProperty: label, placeholder inside properties[idx].settings
            const idx = el.settings._index;
            if (target.settings?.properties?.[idx]?.settings) {
                const propTarget = target.settings.properties[idx].settings;
                if (el.settings.label !== undefined) propTarget.label = el.settings.label;
                if (el.settings.description !== undefined) propTarget.description = el.settings.description;
                if (el.settings.placeholder !== undefined) propTarget.placeholder = el.settings.placeholder;
                merged++;
            }
        } else if (el.name === 'articlePrevNext' && isSameElement(target, el) && target.settings) {
            if (el.settings.prev_title !== undefined) target.settings.prev_title = el.settings.prev_title;
            if (el.settings.next_title !== undefined) target.settings.next_title = el.settings.next_title;
            merged++;
        } else if (el.name === 'articleCommentForm' && isSameElement(target, el) && target.settings) {
            if (el.settings.name_label !== undefined) target.settings.name_label = el.settings.name_label;
            if (el.settings.name_placeholder !== undefined) target.settings.name_placeholder = el.settings.name_placeholder;
            if (el.settings.message_label !== undefined) target.settings.message_label = el.settings.message_label;
            if (el.settings.message_placeholder !== undefined) target.settings.message_placeholder = el.settings.message_placeholder;
            if (el.settings.email_label !== undefined) target.settings.email_label = el.settings.email_label;
            if (el.settings.email_placeholder !== undefined) target.settings.email_placeholder = el.settings.email_placeholder;
            if (el.settings.submit_label !== undefined) target.settings.submit_label = el.settings.submit_label;
            if (el.settings.success_message !== undefined) target.settings.success_message = el.settings.success_message;
            if (el.settings.success_moderated !== undefined) target.settings.success_moderated = el.settings.success_moderated;
            if (el.settings.error_heading !== undefined) target.settings.error_heading = el.settings.error_heading;
            if (el.settings.moderated !== undefined) target.settings.moderated = el.settings.moderated;
            merged++;
        } else if (el.name === 'shopifyNewsletter' && isSameElement(target, el) && target.settings) {
            if (el.settings.email_placeholder !== undefined) target.settings.email_placeholder = el.settings.email_placeholder;
            if (el.settings.button_title !== undefined) target.settings.button_title = el.settings.button_title;
            if (el.settings.success_message !== undefined) target.settings.success_message = el.settings.success_message;
            if (el.settings.error_title !== undefined) target.settings.error_title = el.settings.error_title;
            if (el.settings.error_already !== undefined) target.settings.error_already = el.settings.error_already;
            if (el.settings.uncheckbox_message !== undefined) target.settings.uncheckbox_message = el.settings.uncheckbox_message;
            if (el.settings.checkbox_label !== undefined) target.settings.checkbox_label = el.settings.checkbox_label;
            merged++;
        } else if (el.name === 'blogCategories' && isSameElement(target, el) && target.settings) {
            if (el.settings.articlesCountText !== undefined) target.settings.articlesCountText = el.settings.articlesCountText;
            merged++;
        } else if (isSameElement(target, el) && target.settings && typeof target.settings === typeof el.settings) {
            Object.assign(target.settings, el.settings);
            merged++;
        }

        // Handle style.background-image for section/row/column
        // Chốt chặn cuối: kể cả khi AI tự bịa ra style['background-image'] thì cũng không ghi.
        if (REPLACE_BACKGROUND_IMAGES && el.style && el.style['background-image']) {
            const bgValue = el.style['background-image'];
            // Chỉ merge khi là URL đã resolve — placeholder, IMG_x chưa resolve
            // hoặc "KEEP" (AI quyết định giữ bg gốc) thì bỏ qua
            const bgResolved = isResolvedMediaUrl(bgValue)
                || (typeof bgValue === 'string' && /^url\(/.test(bgValue.trim()) && isResolvedMediaUrl(bgValue.trim().replace(/^url\((['"]?)(.*)\1\)$/, '$2')));
            if (bgResolved) {
                const bgTarget = resolveBackgroundTarget(sectionJSON, el);
                if (bgTarget) {
                    bgTarget.style.background.backgroundnormalmode.classic['background-image'] = bgValue;
                    merged++;
                } else {
                    console.warn('[AI-Import][merge] bỏ qua background: không tìm thấy target', { elementId: el.id });
                }
            }
        }
    }
    return merged;
};

/**
 * Dữ liệu trích xuất cho 1 section trong page editor
 */
export type SectionExtract = {
    sectionId: string;
    sectionIndex: number;
    elements: ExtractedElement[];
    // Tóm tắt text của section — gửi kèm để AI hiểu ngữ cảnh vị trí ảnh/text
    context?: string[];
};

/**
 * Trích xuất elements từ TẤT CẢ sections của page.
 * Trả về mảng SectionExtract, chỉ bao gồm sections có editable elements.
 */
export const extractAllSections = (
    sections: any[],
    settingsMap: Record<string, string[] | "*"> = ELEMENT_SETTINGS_MAP,
    extractImage: boolean = false
): SectionExtract[] => {
    const result: SectionExtract[] = [];
    frozenTextLog = [];
    sections.forEach((sec: any, idx: number) => {
        if (!sec || !sec.id) return;
        const slotLogFrom = imageSlotLog.length;
        // Text cạnh ảnh avatar / cạnh element rating: bỏ khỏi payload để AI không viết lại
        // (ảnh avatar và dải sao giữ nguyên nên text đi kèm phải giữ nguyên theo).
        const { frozen: frozenTextIds, nearMiss } = collectIdentityTextIds(sec);
        frozenTextIds.forEach(info => frozenTextLog.push({ sectionId: sec.id, ...info }));
        nearMiss.forEach(info => frozenTextLog.push({ sectionId: sec.id, ...info }));
        const elements = extractElements(sec, settingsMap, '', extractImage)
            .filter(el => !frozenTextIds.has(el.id));
        const rowBg = sec.row?.style?.background?.backgroundnormalmode?.classic?.['background-image'];
        const sectionBg = sec.style?.background?.backgroundnormalmode?.classic?.['background-image'];
        const bgUrl = sectionBg || rowBg;
        // Section bg không cần điều kiện heading (section luôn là khối nội dung chính)
        if (shouldExtractBackground(bgUrl, true, sec)) {
            elements.push({
                id: sec.id,
                name: sec.name || 'Section',
                path: '',
                settings: {
                    original: buildOriginalImageInfo({ value: bgUrl }, undefined, { owner: sec, kind: 'background' }),
                },
                style: {
                    'background-image': '<!--LINK_TO_IMAGE-->'
                }
            })
        }
        stampImageSlotSection(slotLogFrom, sec.id);
        if (elements.length > 0) {
            result.push({
                sectionId: sec.id,
                sectionIndex: idx,
                elements,
                context: extractImage ? extractSectionSummary(sec).slice(0, 12) : undefined,
            });
        }
    });
    return result;
};

/**
 * Merge kết quả AI đã chỉnh sửa ngược lại vào tất cả sections.
 * editedData là mảng { sectionId, elements[] } từ AI response.
 * Trả về tổng số elements đã merge thành công.
 */
export const mergeAllSections = (
    sections: any[],
    editedData: { sectionId: string; elements: ExtractedElement[] }[]
): number => {
    let totalMerged = 0;
    for (const item of editedData) {
        const section = sections.find((s: any) => s.id === item.sectionId);
        if (section && item.elements?.length) {
            totalMerged += mergeEditedContent(section, item.elements);
        }
    }
    return totalMerged;
};
