import { PropType } from 'vue';

export default {
    emits: ['open', 'close'],
    data() {
        return {
            id: '',
            timeout: undefined as ReturnType<typeof setTimeout> | undefined,
            workspaceWrap: null as HTMLElement | null,
            spacing: 12,
            isAnimating: false,
            isOpen: false
        }
    },
    props: {
        canOpen: {
            type: Boolean,
            default: true
        },
        canClose: {
            type: Boolean,
            default: true
        },
        open: {
            type: Boolean,
            default: false
        },
        triggerClass: {
            type: String,
            default: ''
        },
        contentClass: {
            type: String,
            default: 'w-[20rem] flex bg-white rounded-lg shadow-lg'
        },
        arrowClass: {
            type: String,
            default: 'bg-white h-2 w-2 border top-1 left-1'
        },
        preferredPosition: {
            type: String as PropType<'top' | 'right' | 'bottom' | 'left'>,
            default: 'bottom'
        },
        preferredAlignment: {
            type: String as PropType<'start' | 'middle' | 'end'>,
            default: 'middle'
        },
        baseZIndex: {
            type: Number,
            default: 500
        },
        closeOnOutsideClick: {
            type: Boolean,
            default: true
        }
    },
    computed: {
        zIndex() {
            const index = this.$store.getters['ai/popoverIndex'](this.id);
            if (index < 0) {
                return this.baseZIndex
            }
            return this.baseZIndex + 5 * (index * 1);
        },
        positionStyle() {
            return {
                top: 'px',
                left: 'px'
            }
        }
    },
    methods: {
        /** Không dùng computed cho $refs: Vue không track ref → có thể cache node DOM cũ sau khi v-if tắt/bật (lần 2+ mở popover đo sai, --ec-popover-offset-x không set). */
        triggerEl(): HTMLElement | undefined {
            return this.$refs.triggerRef as HTMLElement | undefined;
        },
        popoverEl(): HTMLElement | undefined {
            return this.$refs.popoverRef as HTMLElement | undefined;
        },
        mainEl(): HTMLElement | undefined {
            return this.$refs.main as HTMLElement | undefined;
        },
        onOpen() {
            if (this.isOpen || !this.canOpen || this.isAnimating) {
                return;
            }
            this.isAnimating = true;
            this.isOpen = true;
            this.$emit('open', this.id);
            this.$store.commit('ai/addPopover', this.id);
            this.$nextTick(() => {
                this.resetPositionVariables();
                this.setPosition();
                window.addEventListener('resize', this.onWindowResize);

                clearTimeout(this.timeout);
                this.timeout = setTimeout(() => {
                    this.isAnimating = false;
                }, 200);
            });
        },
        onClose() {
            if (!this.isOpen || !this.canClose || this.isAnimating) {
                return;
            }
            this.isAnimating = true;
            this.popoverEl()?.classList.remove('ec-popover--opened');
            window.removeEventListener('resize', this.onWindowResize);

            clearTimeout(this.timeout);
            this.timeout = setTimeout(() => {
                this.$emit('close', this.id);
                this.$store.commit('ai/removePopover', this.id);
                this.isAnimating = false;
                this.isOpen = false;
            }, 200);
        },
        onWindowResize() {
            this.resetPositionVariables();
            clearTimeout(this.timeout);
            this.timeout = setTimeout(() => {
                this.setPosition();
            }, 200);
        },
        setPosition() {
            const baseRect = this.setBasePosition();
            const popover = this.popoverEl();
            const main = this.mainEl();
            const docWidth = document.documentElement.clientWidth,
                docHeight = document.documentElement.clientHeight;
            if (!baseRect || !popover || !main) {
                return;
            }
            popover.style.zIndex = `${this.zIndex + 5}`;

            let space = {
                left: baseRect.x - this.spacing,
                right: docWidth - baseRect.x - baseRect.width - this.spacing,
                top: baseRect.y - this.spacing,
                bottom: docHeight - baseRect.y - baseRect.height - this.spacing,
                x: 0,
                y: 0
            };
            space.x = Math.max(space.left, space.right);
            space.y = Math.max(space.top, space.bottom);
            let pos = this.$props.preferredPosition;

            const mainRect = main.getBoundingClientRect();
            if (pos === 'top' || pos === 'bottom') {
                if (mainRect.x + mainRect.width > docWidth) {
                    popover.style.setProperty('--ec-popover-offset-x', `${docWidth - mainRect.x - mainRect.width - 5}px`);
                } else if (mainRect.x < 0) {
                    popover.style.setProperty('--ec-popover-offset-x', `${-1 * mainRect.x + 5}px`);
                } else {
                    popover.style.setProperty('--ec-popover-offset-x', '0px');
                }
                popover.style.setProperty('--ec-popover-max-height', `${space.y - 5}px`);
                if (pos === 'top') {
                    if (mainRect.y < 0 && space.top < space.bottom) {
                        popover.classList.add('ec-popover--reverse-y');
                    }
                } else {
                    if (mainRect.y + mainRect.height > docHeight && space.bottom < space.top) {
                        popover.classList.add('ec-popover--reverse-y');
                    }
                }
            }
            if (pos === 'left' || pos === 'right') {
                if (mainRect.y + mainRect.height > docHeight) {
                    popover.style.setProperty('--ec-popover-offset-y', `${docHeight - mainRect.y - mainRect.height - 5}px`);
                } else if (mainRect.y < 0) {
                    popover.style.setProperty('--ec-popover-offset-y', `${-1 * mainRect.y + 5}px`);
                } else {
                    popover.style.setProperty('--ec-popover-offset-y', '0px');
                }
                if (mainRect.x + mainRect.width > docWidth || mainRect.x < 0) {
                    popover.classList.add('ec-popover--reverse-x');
                }
            }
            popover.classList.add('ec-popover--opened');
        },
        setBasePosition() {
            const trigger = this.triggerEl(),
                popover = this.popoverEl();
            if (!trigger || !popover) {
                return;
            }
            const triggerRect = trigger.getBoundingClientRect();
            popover.style.left = `${triggerRect.left}px`;
            popover.style.top = `${triggerRect.top}px`;
            popover.style.setProperty('--ec-popover-trigger-width', `${triggerRect.width}px`);
            popover.style.setProperty('--ec-popover-trigger-height', `${triggerRect.height}px`);
            return {
                x: triggerRect.left,
                y: triggerRect.top,
                width: triggerRect.width,
                height: triggerRect.height
            }
        },
        resetPositionVariables() {
            const popover = this.popoverEl();
            if (!popover) {
                return;
            }
            popover.classList.remove('ec-popover--opened');
            popover.style.removeProperty('--ec-popover-offset-x');
            popover.style.removeProperty('--ec-popover-offset-y');
            popover.style.removeProperty('--ec-popover-max-width');
            popover.style.removeProperty('--ec-popover-max-height');
            popover.classList.remove('ec-popover--reverse-x');
            popover.classList.remove('ec-popover--reverse-y');
        }
    },
    mounted() {
        if (!this.id.length) {
            this.id = `popover-${this.$helpers.randid()}`;
        }
    },
    watch: {
        open: {
            handler(newVal) {
                newVal ? this.onOpen() : this.onClose();
            },
            immediate: true
        }
    }
}
