<template>
    <div
        class="ecom-element ecom-product-single ecom-product-single__countdown"
        :style="show_countdown_on_sale && exporting ? 'display:none' : null"
    >
        <div
            v-if="!exporting"
            class="ecom-product-single__countdown__placeholder"
            :data-text-on-sale="placeholderOnSaleText"
            :data-text-finished="placeholderFinishedText"
            style="display: none;"
        />
        <div class="ecom-product-single__countdown-wrapper">
            <div class="ecom-product-countdown-layout" :class="data.settings.layout == 'row'?'ecom-product-countdown-layout-horizontal':'ecom-product-countdown-layout-vertical'">
                <div
                    v-if="title"
                    class="ecom-product-single__countdown-title ecom-html"
                    v-html="lang(title, 'countdown_title')"
                />
                <div
                    class="ecom-product-single__countdown-container"
                    :class="
                        data.settings.styleCountdown == 'column'
                            ? 'ecom-product-single__countdown-block'
                            : ''
                    "
                    :data-week="lang(data.settings.text_week, 'text_week')"
                    :data-day="lang(data.settings.text_day, 'text_day')"
                    :data-hour="lang(data.settings.text_hour, 'text_hour')"
                    :data-minute="lang(data.settings.text_minute, 'text_minute')"
                    :data-second="lang(data.settings.text_second, 'text_second')"
                    :data-shows="shows"
                    v-html="liquid('countdown')"
                />
            </div>
            <div v-if="enable_progress_bar" class="ecom-product-single__countdown-progress-bar">
                <div class="ecom-product-single__countdown-progress-bar--timer" />
            </div>
            <div v-if="!exporting" class="ecom-product-count-down--json" v-html="liquid('product_json')" />
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
    name: 'productCountdown',
    docs: 'https://help.ecomposer.io/docs/elements/product-elements/countdown/',
    presets:true,
    mixins: [Liquid, Element, Javascript],
    vendors: ['countdown_js'],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives: [
                'text_week',
                'text_day',
                'text_hour',
                'text_minute',
                'text_second',
                'enable_progress_bar',
                'show_countdown_on_sale',
                'show_week',
                'show_day',
                'show_hour',
                'show_minute',
                'show_second',
                'countdown_restart'
            ]
        };
    },
    computed: {

        _data() {
            return this.data;
        },
        liquids() {
            let finalDate = new Date();
            finalDate.setDate(new Date().getDate() + 3);
            finalDate = `${finalDate.getFullYear()}/${
                finalDate.getMonth() + 1
            }/${finalDate.getDate()}`;

            const tag = "script";
            return {
                countdown: {
                    code: `
                    {% if product != empty %}
                        ${  this.type === 'metafields' || this.type === 'metafield_or_custom'  ?
                        `
                        {%- assign countdown = product.metafields.ecomposer.countdown -%}
                        {%- assign countdown_from = product.metafields.ecomposer.countdown_from -%}
                        ${this.type === 'metafield_or_custom'?
                                `
                                    {%- unless countdown -%}
                                        {% capture countdown%}${this.countdown}{% endcapture %}
                                    {%- endunless -%}
                                    {%- unless countdown_from -%}
                                        {% capture countdown_from%}${this.countdown_from}{% endcapture %}
                                    {%- endunless -%}
                                `
                                : ''
                             }
                            `
                            : `
                            {%- assign countdown = '${this.countdown}' -%}
                            {%- assign countdown_from = '${this.countdown_from}' -%}
                            `
                        }
                        <div data-product-id="{{product.id}}" class="ecom-product-single__countdown-time"  data-ecom-countdown="{{countdown}}"  data-ecom-countdown-from="{{countdown_from}}"></div>
                    {% endif%}
                `,
                preview: `<div data-product-id="0" class="ecom-product-single__countdown-time" data-ecom-countdown="${finalDate}"></div>`
                },
                product_json: {
                    code: `
                        <${tag} type="application/json" id="product-json-{{product.id}}">
                            {%- ${this.page_type === 'block' ? 'render': 'render'} "ecom_product_json", product: product  -%}
                        </${tag}>
                    `,
                    preview: `<${tag} id="product-json-preview">{}</${tag}>`
                },
            };
        },
        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'text',
                            label: this.$t('title'),
                            name: 'title',
                            value: '',
                            options: {
                                toolbar: true
                            },
                            placeholder: this.$t('hurry_up_sale_ends_in'),
                        },
                        {
                            type: 'popup',
                            label: this.$t('type'),
                            name: 'type',
                            options: {
                                type: 'dropdown',
                                default: false,
                                values: {
                                    metafields: this.$t('metafields'),
                                    custom: this.$t('custom'),
                                    metafield_or_custom: this.$t('metafield_custom'),
                                },
                                preview: 'title'
                            }
                        },
                        {
                            name: 'layout',
                            label: this.$t('layout'),
                            type: 'popup',
                            value: 'column',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                default: false,
                                preview: "title",
                                values: {
                                    column: this.$t('vertical'),
                                    row: this.$t('horizontal')
                                }
                            },
                            css: {
                                selector: ' [class*="ecom-product-single__countdown-time--"]',
                                properties: {
                                    'flex-direction': ''
                                }
                            }
                        },
                        {
                            name: 'styleCountdown',
                            label: this.$t('countdown_layout'),
                            type: 'popup',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                default: false,
                                preview: "title",
                                values: {
                                    column: this.$t('vertical'),
                                    row: this.$t('horizontal')
                                }
                            },
                            css: {
                                selector: ' [class*="ecom-product-single__countdown-time--"]',
                                properties: {
                                    'flex-direction': ''
                                }
                            }
                        },
                        {
                            name: 'countdown_from',
                            type: 'datetime',
                            placeholder: 'YYYY/MM/DD hh:mm',
                            label: this.$t('countdown_start_from'),
                            options: {
                                type: 'datetime',
                                format: 'YYYY/MM/DD hh:mmZ',
                                visible: function (data) {
                                    return data['type'] !== 'metafields'
                                }
                            }
                        },
                        {
                            name: 'countdown',
                            options: {
                                toolbar: false,
                                type: 'datetime',
                                format: 'YYYY/MM/DD hh:mmZ',
                                visible: function (data) {
                                    return (
                                        (data && data['type'] === 'custom') ||
                                        data['type'] === 'metafield_or_custom'
                                    );
                                }
                            },
                            type: 'datetime',
                            placeholder: 'YYYY/MM/DD hh:mmZ',
                            label: this.$t('countdown_end_at'),
                        },
                        {
                            type: 'toggle',
                            name: 'show_countdown_on_sale',
                            label: this.$t('only_show_when_on_sale'),
                            value: false,
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            name: "countdown_restart",
                            label: this.$t('restart_on_finish'),
                            type: "toggle",
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        {
                            name: 'enable_progress_bar',
                            label: this.$t('show_progress_bar'),
                            value: true,
                            type: 'toggle',
                            options: {
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            }
                        },
                        ...['week','day','hour','minute','second'].map(value => {
                            return {
                                name: 'show_' + value,
                                label: this.$t('show') + ' ' + this.$t(value),
                                value: true,
                                type: 'toggle',
                                options: {
                                    values: {
                                        on: {
                                            value: true
                                        },
                                        off: {
                                            value: false
                                        }
                                    }
                                }
                            }
                        })
                    ]
                },
                {
                    group_title: this.$t('change_text'),
                    options: {
                        visible: (data) => {
                            return data.show_week ||
                                data.show_day ||
                                data.show_hour ||
                                data.show_minute ||
                                data.show_second
                        }
                    },
                    params: [
                        {
                            type: 'text',
                            name: 'text_week',
                            value: '[%-W] week%!W',
                            description: this.$t('example')+'[%-W] week%!W',
                            label: this.$t('week'),
                            options: {
                                visible: (data) =>
                                    data.show_week
                            }
                        },
                        {
                            type: 'text',
                            name: 'text_day',
                            value: '[%d] day%!d',
                            description: this.$t('example')+'[%-d] day%!d',
                            label: this.$t('days'),
                            options: {
                                visible: (data) =>
                                    data.show_day
                            }
                        },
                        {
                            type: 'text',
                            name: 'text_hour',
                            value: '[%-H] hour%!H',
                            description: this.$t('example')+' [%-H] hour%!H',
                            label: this.$t('hours'),
                            options: {
                                visible: (data) =>
                                    data.show_hour
                            }
                        },
                        {
                            type: 'text',
                            name: 'text_minute',
                            value: '[%-M] minute%!M',
                            description: this.$t('example')+'[%-M] minute%!M',
                            label: this.$t('minutes'),
                            options: {
                                visible: (data) =>
                                    data.show_minute
                            }
                        },
                        {
                            type: 'text',
                            name: 'text_second',
                            value: '[%-S] second%!S',
                            description: this.$t('example')+'[%-S] second%!S',
                            label: this.$t('seconds'),
                            options: {
                                visible: (data) =>
                                    data.show_second
                            }
                        }
                    ]
                }
            ];
        },
        title() {
            return this.data && this.data.settings && this.data.settings.title
                ? this.data.settings.title
                : '';
        },
        countdown() {
            return this.data && this.data.settings && 'countdown' in this.data.settings
                ? this.convertDateFormat(this.data.settings.countdown)
                : '';
        },
        countdown_from() {
            return this.data && this.data.settings && 'countdown_from' in this.data.settings
                ? this.convertDateFormat(this.data.settings.countdown_from)
                : '';
        },
        show_countdown_on_sale() {
            return this.data && this.data.settings && 'show_countdown_on_sale' in this.data.settings
                ? this.data.settings.show_countdown_on_sale
                : false;
        },
        placeholderOnSaleText() {
            return this.$t('countdown_only_show_on_sale');
        },
        placeholderFinishedText() {
            return this.$t('countdown_has_ended');
        },
        enable_progress_bar() {
            return this.data && this.data.settings && 'enable_progress_bar' in this.data.settings
                ? this.data.settings.enable_progress_bar
                : false;
        },

        type() {
            return this.data?.settings?.type ?? '';
        },
        shows() {
            let shows = ['week','day','hour','minute','second'];
            return shows.filter(show => this.data?.settings?.['show_' + show]);
        },
        javascript() {
            return function () {
                var $el = this.$el,
                    isLive = this.isLive,
                    $countdown = $el.querySelector('.ecom-product-single__countdown-time'),
                    $progressbar = $el.querySelector('.ecom-product-single__countdown-progress-bar'),
                    $timer = $el.querySelector('.ecom-product-single__countdown-progress-bar--timer'),
                    from = $countdown ? $countdown.getAttribute('data-ecom-countdown-from') : 0,
                    $container = $el.querySelector('.ecom-product-single__countdown-container'),
                    showCountDownOnSale = this.settings.show_countdown_on_sale,
                    countdownRestart = !!this.settings.countdown_restart,
                    $wrapper = $el.closest('.ecom-product-form--single');

                let trans = $countdown
                    ? $container.dataset
                    : {};
                let shows = $container.dataset.shows.split(',');

                const $root = $el.matches('.ecom-product-single__countdown')
                    ? $el
                    : $el.querySelector('.ecom-product-single__countdown');
                const $block = $el.closest('.ecom-block.ecom-core');

                const setCountdownHidden = (hidden, reason) => {
                    if (isLive) {
                        if ($block) $block.style.display = hidden ? 'none' : '';
                        if (!hidden && $root) $root.style.display = '';
                        return;
                    }
                    
                    if (!$root) return;
                    const $contentWrapper = $root.querySelector('.ecom-product-single__countdown-wrapper');
                    const $placeholder = $root.querySelector('.ecom-product-single__countdown__placeholder');
                    if ($contentWrapper) $contentWrapper.style.display = hidden ? 'none' : '';
                    if ($placeholder) {
                        $placeholder.style.display = hidden ? '' : 'none';
                        if (hidden) {
                            $placeholder.textContent = reason === 'finished'
                                ? ($placeholder.dataset.textFinished || '')
                                : ($placeholder.dataset.textOnSale || '');
                        }
                    }
                };

                let hiddenByOnSale = false;
                const handleCountdownVisibility = (variant) => {
                    if (!variant || !$root) return;
                    const isSale = variant.available && variant.compare_at_price > variant.price;
                    hiddenByOnSale = showCountDownOnSale && !isSale;
                    setCountdownHidden(hiddenByOnSale, 'on_sale');
                }

                const initCountdownVisibility = () => {
                    const productJson = (() => {
                        const form = $el.closest('form');
                        const productId = form && form.dataset.product_id;

                        let productJsonElement = null;

                        if (productId) {
                            productJsonElement = form.querySelector('[id^=product-json-' + productId + ']');
                        }

                        if (!productJsonElement && !isLive) {
                            productJsonElement = $el && $el.querySelector('[id^=product-json]');
                        }
                        
                        try {
                            return JSON.parse( (productJsonElement && productJsonElement.innerHTML) || "{}" );
                        } catch {
                            return {};
                        }
                    })();

                    const variants = productJson.variants || [];
                    const idElement = $wrapper && $wrapper.querySelector('[name="id"]');
                    const selectedId = idElement && idElement.value;

                    const variant =
                        variants.find(v => String(v && v.id) === String(selectedId)) ||
                        productJson.selected_or_first_available_variant ||
                        variants[0];

                    handleCountdownVisibility(variant);
                };

                if ($wrapper) {
                    initCountdownVisibility();
                    $wrapper.addEventListener('ecomVariantChange', (event) => handleCountdownVisibility(event.detail.variant));
                }

                const regex = /\[([^\]]+)\]/gm;
                var format = "";
                if(shows.indexOf('week')  >=0 && trans.week)
                {
                    let number = '';
                    let text = trans.week.replace(regex,(...m)=>{
                            number =  m[1];
                            return '';
                    });
                    format += `<div class="ecom-product-single__countdown-time--week"><span class="ecom-product-single__countdown-number">
                            ${ number }
                        </span>
                        <span class="ecom-product-single__countdown-text">
                            ${ text}
                        </span>
                    </div>`;
                }
                if(shows.indexOf('day')  >=0 && trans.day)
                {
                    let number = '';
                    let text = trans.day.replace(regex,(...m)=>{
                            number =  m[1];
                            return '';
                    });
                    format += `<div class="ecom-product-single__countdown-time--day">
                                    <span class="ecom-product-single__countdown-number">${number}</span>
                                    <span class="ecom-product-single__countdown-text">
                                        ${text}
                                    </span>
                                </div> `;
                }
                if(shows.indexOf('hour')  >=0 && trans.hour)
                {
                    let number = '';
                    let text = trans.hour.replace(regex,(...m)=>{
                            number =  m[1];
                            return '';
                    });
                    format +=`<div class="ecom-product-single__countdown-time--hour">
                                    <span class="ecom-product-single__countdown-number">
                                        ${ number}
                                    </span>
                                    <span class="ecom-product-single__countdown-text">
                                        ${text}
                                    </span>
                            </div>  `
                }
                if(shows.indexOf('minute')  >=0 && trans.minute)
                {
                    let number = '';
                    let text = trans.minute.replace(regex,(...m)=>{
                            number =  m[1];
                            return '';
                    });
                    format +=  `<div class="ecom-product-single__countdown-time--minute">
                                    <span class="ecom-product-single__countdown-number">
                                        ${ number }
                                    </span>
                                    <span class="ecom-product-single__countdown-text">
                                        ${text}
                                    </span>
                                </div>`
                }
                if(shows.indexOf('second')  >=0 && trans.second)
                {
                    let number = '';
                    let text = trans.second.replace(regex,(...m)=>{
                            number =  m[1];
                            return '';
                    });
                    format +=  `<div class="ecom-product-single__countdown-time--second">
                                    <span class="ecom-product-single__countdown-number">
                                        ${ number }
                                    </span>
                                    <span class="ecom-product-single__countdown-text">
                                        ${text}
                                    </span>
                                </div>`
                }

                function countdownCallback(event) {
                    this.innerHTML = event.strftime(format);
                    if ($progressbar && from) {
                        let now_time = new Date().getTime(),
                            start = new Date(from),
                            start_time = start.getTime(),
                            end_time = event.finalDate.getTime();
                        if (start_time < now_time && end_time > start_time) {
                            $progressbar.style.display = 'inherit';
                            let total = end_time - start_time;
                            let elapse = end_time - now_time;
                            let result = Math.round((elapse * 100) / total);
                            $timer.style.width = result + '%' ;
                        } else {
                            $progressbar.style.display = 'none';
                        }
                    }
                }
                
                if ($countdown) {
                    if ($countdown.getAttribute('data-ecom-countdown')) {
                        let from = $countdown.getAttribute('data-ecom-countdown-from');
                        if (from && new Date().getTime() < new Date(parseInt(from)).getTime()) {
                            // console.info('Countdown will run on: ',new Date(parseInt(from)));
                        } else {
                            let stringDate = $countdown.getAttribute('data-ecom-countdown');
                            let date = new Date(stringDate);
                            if(window.EComCountdown )
                            {
                                let date_diff =  new Date(stringDate).getTime() - new Date(from).getTime(),
                                    new_date = new Date(stringDate).getTime() + date_diff;
                                if(date_diff == 0 ) return;

                                window.EComCountdown($countdown,date, {});
                                $countdown.addEventListener('update.ecom.countdown', countdownCallback);
                                $countdown.addEventListener('finish.ecom.countdown', function(event) {
                                    if(countdownRestart) {
                                        while(new_date < new Date().getTime()){
                                            new_date += date_diff;
                                        }
                                        window.EComCountdown($countdown,new Date(new_date), countdownCallback);
                                    } else if (!hiddenByOnSale) {
                                        // Hết giờ -> ẩn. Bỏ qua nếu đã ẩn sẵn do điều kiện show-on-sale.
                                        setCountdownHidden(true, 'finished');
                                    }
                                });
                            }
                        }
                    }
                }
            };
        },
        css() {
            return `
                    .ecom-product-single__countdown__placeholder {
                        display: flex;
                        flex-direction: row;
                        flex-wrap: nowrap;
                        position: relative;
                        justify-content: center;
                        align-items: center;
                        border-radius: 8px;
                        border: 1px dashed #91D0FF;
                        color: #00527C;
                        font-size: 13px;
                        line-height: 20px;
                        font-weight: 650;
                        opacity: 1;
                        padding: 6px;
                    }
                    .ecom-product-single__countdown-container{
                        display:flex;
                    }
                    .ecom-product-single__countdown-progress-bar{
                        display:block;
                        width:100%;
                    }
                    .ecom-product-single__countdown-progress-bar .ecom-product-single__countdown-progress-bar--timer{
                        width:100%;
                        display:block;
                    }
                    .ecom-product-single__countdown-time{
                        display: inline-flex;
                        flex-wrap: wrap;
                        justify-content:inherit;
                    }
                    .ecom-product-single__countdown-time > div{
                        display:inline-flex;
                        row-gap: 6px;
                        padding:10px;
                        border:1px solid #eee;
                        justify-content: center;
                        align-items: center;
                    }
                    .ecom-product-single__countdown-block .ecom-product-single__countdown-time > div span{
                        width:100%;
                    }

                    .ecom-product-single__countdown-progress-bar--timer {
                            background-image: -webkit-linear-gradient(45deg,rgba(255,255,255,.15) 25%,transparent 25%,transparent 50%,rgba(255,255,255,.15) 50%,rgba(255,255,255,.15) 75%,transparent 75%,transparent);
                            background-image: linear-gradient(45deg,rgba(255,255,255,.15) 25%,rgba(0,0,0,0) 25%,rgba(0,0,0,0) 50%,rgba(255,255,255,.15) 50%,rgba(255,255,255,.15) 75%,rgba(0,0,0,0) 75%,rgba(0,0,0,0));
                            -webkit-animation: 2s linear infinite ecom_progress_bar;
                            animation: 2s linear infinite ecom_progress_bar;
                            background-size: 60px 60px;
                            transition: width 1s;
                            -webkit-transition: width 1s;
                    }
                    .ecom-product-countdown-layout{
                        display: block;
                    }
                    .ecom-product-countdown-layout.ecom-product-countdown-layout-horizontal{
                        display: flex;
                        flex-wrap: wrap;
                    }
                    .ecom-product-countdown-layout.ecom-product-countdown-layout-horizontal .ecom-product-single__countdown-title,
                    .ecom-product-countdown-layout.ecom-product-countdown-layout-horizontal .ecom-product-single__countdown-container{
                        display: inline-flex;
                    }
                    .ecom-product-countdown-layout.ecom-product-countdown-layout-vertical .ecom-product-single__countdown-title{
                        display: block;
                    }
                    .ecom-product-single__countdown-number{
                        text-align: center;
                    }
                    @-webkit-keyframes ecom_progress_bar {
                        from {
                            background-position: 0 0
                        }

                        to {
                            background-position: 40px 0
                        }
                    }

                    @keyframes ecom_progress_bar {
                        from {
                            background-position: 0 0
                        }

                        to {
                            background-position: 40px 0
                        }
                    }

                `;
        },

        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },

        default() {
            // End 6 days from now at 12:30; start on the 1st of the month before it, so the
            // progress bar always has elapsed time. Date arithmetic instead of string concat,
            // so December/January and short months can't produce invalid dates.
            const endDate = new Date();
            endDate.setDate(endDate.getDate() + 6);
            endDate.setHours(12, 30, 0, 0);
            const startDate = new Date(endDate.getFullYear(), endDate.getMonth() - 1, 1, 12, 30);

            return {
                "settings": {
                    "title": "Hurry up! Sale ends in",
                    "layout": "column",
                    "show_countdown_on_sale": false,
                    "enable_progress_bar": true,
                    "show_week": true,
                    "show_day": true,
                    "show_hour": true,
                    "show_minute": true,
                    "show_second": true,
                    "text_week": "[%-W] week%!W",
                    "text_day": "[%d] day%!d",
                    "text_hour": "[%-H] hour%!H",
                    "text_minute": "[%-M] minute%!M",
                    "text_second": "[%-S] second%!S",
                    "type": "custom",
                    countdown_from: this.formatDateTime(startDate),
                    countdown: this.formatDateTime(endDate),
                    "styleCountdown": "column"
                },
                "style":   {
                "progess_bar": {
                    "background": {
                        "classic": {
                            "background-color": "rgba(17, 24, 39, 0.1)"
                        }
                    },
                    "backgroundActive": {
                        "classic": {
                            "background-color": "rgba(166, 0, 11, 0.97)"
                        }
                    },
                    "tab": "active",
                    "maxWidth": "100%",
                    "height": "20px",
                    "borderRadius": {
                        "top": "5px",
                        "left": "5px",
                        "bottom": "5px",
                        "right": "5px"
                    },
                    "spacing": {
                        "margin": {
                            "right": "2px",
                            "top": "2px",
                            "left": "2px",
                            "bottom": "2px"
                        },
                        "padding": {}
                    },
                    "borderRadiusActive": {
                        "right": "0px",
                        "top": "5px",
                        "left": "5px",
                        "bottom": "0px"
                    }
                },
                "title": {
                    "textTextAlign": "center",
                    "spacing": {
                        "margin": {
                            "bottom": "8px"
                        }
                    }
                },
                "countdown_number": {
                    "buttonColor": "#dc2626",
                    "text-align": "center"
                },
                "items": {
                    "spacing": {
                        "margin": {
                            "right": "8px",
                            "bottom": "8px"
                        }
                    },
                    "justify-content": "center"
                },
                "countdown_label": {
                    "text-align": "center"
                }
            }
            }



        }
    },
    watch: {
        shows: {
            deep: true,
            handler(){
                this._data.refresh = this.$helpers.randid();
            }
        }
    },
    methods: {
        // Offset of the given date, so a future date keeps the right offset across DST changes.
        timeZoneOffset(date) {
            const offset = date.getTimezoneOffset(),
                o = Math.abs(offset);
            // UTC must render as "+0000" — "-0000" is not in the GMT dropdown list.
            return (
                (offset <= 0 ? '+' : '-') +
                ('00' + Math.floor(o / 60)).slice(-2) +
                ('00' + (o % 60)).slice(-2)
            );
        },
        // "YYYY/MM/DD hh:mm GMT+0700" — the format the datetime field parses.
        formatDateTime(date) {
            const pad = (n) => ('00' + n).slice(-2);
            return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ` +
                `${pad(date.getHours())}:${pad(date.getMinutes())} GMT${this.timeZoneOffset(date)}`;
        },
        // Begin fix date format in safari
        convertDateFormat(dateStr) {
            // Validate input format
            const regex = /^(\d{4})\/(\d{1,2})\/(\d{1,2})\s(\d{1,2}):(\d{2})(?:\s*GMT)?([+-])(\d{2})(\d{2})$/;
            const match = dateStr.match(regex);
            if (!match) {
                return dateStr;
            }

            const [_, year, month, day, hour, minute, tzSign, tzHours, tzMinutes] = match;

            // add number 0
            const paddedMonth = month.padStart(2, '0');
            const paddedDay = day.padStart(2, '0');
            const paddedHour = hour.padStart(2, '0');

            // format ISO
            const dateString = `${year}-${paddedMonth}-${paddedDay}`;
            const timeString = `${paddedHour}:${minute}:00`;
            const timezone = `${tzSign}${tzHours}:${tzMinutes}`;

                // Combine all parts with 'T' and add seconds
            return `${dateString}T${timeString}${timezone}`;


        },
        // End fix date format in safari
        style() {
            let params = {
                title:{
                    remove: {
                        index: 0,
                        length: 1
                    }
                },
                items:{
                    remove: {
                        index: 3,
                        length: 1
                    },
                    params: [
                        {
                        position:2,
                        fields:{
                            alias:'justify-content',
                            options:{
                                label: this.$t('alignment'),
                                css:{
                                    selector:'root .ecom-product-countdown-layout'
                                }
                            }
                        }
                        },
                    ]
                }
            };
            let style = [
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_name: 'title',
                        group_title: this.$t('title'),
                        selector: ' .ecom-product-single__countdown-title'
                    }
                },
                {
                    group_alias: 'box',
                    options: {
                        group_title: this.$t('items'),
                        group_name: 'items',
                        selector: ' [class*="ecom-product-single__countdown-time--"]'
                    },
                    modify: {
                        params: [
                            {
                                position:0,
                                fields:[
                                    {
                                        type:'number',
                                        label: this.$t('width'),
                                        name:'width',
                                        options:{
                                            units:{
                                                px:{
                                                    min:20,
                                                    max:200
                                                }
                                            },
                                            reset:false,
                                            responsive:true
                                        },
                                        css:{
                                            properties:{
                                                width:''
                                            }
                                        }
                                    },
                                    {
                                        type:'number',
                                        label: this.$t('height'),
                                        name:'height',
                                        options:{
                                            units:{
                                                px:{
                                                    min:20,
                                                    max:200
                                                }
                                            },
                                            reset:false,
                                            responsive:true
                                        },
                                        css:{
                                            properties:{
                                                height:''
                                            }
                                        }
                                    }
                                ]
                            },
                            {
                                position:2,
                                fields:{
                                    alias:'justify-content',
                                    options:{
                                        label: this.$t('alignment'),
                                        css:{
                                            selector:'root .ecom-product-single__countdown-container'
                                        }
                                    }
                                }
                            },
                            {
                                position: 10,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            }
                        ]
                    }
                },
                {
                    group_alias: 'button:label',
                    options: {
                        group_name: 'countdown_number',
                        group_title: this.$t('number'),
                        selector: ' .ecom-product-single__countdown-number'
                    },
                    modify:this.data.settings.styleCountdown == 'column' ? {
                        params:{
                            alias:'text-align',
                            options:{
                                label: this.$t('alignment'),
                            }
                        }
                    } : {}
                },
                {
                    group_alias: 'button:label',
                    options: {
                        group_name: 'countdown_label',
                        group_title: this.$t('label'),
                        selector: ' .ecom-product-single__countdown-text'
                    },
                    modify:this.data.settings.styleCountdown == 'column' ? {
                        params:{
                            alias:'text-align',
                            options:{
                                label: this.$t('alignment'),
                            }
                        }
                    } : {}
                }
            ];
            if (this.data.settings.layout === 'row') {
                style = style.map(item => {
                    if (item.options.group_name === 'title') {
                        return { ...item, modify: params.title };
                    }
                    if (item.options.group_name === 'items') {
                        return {
                            ...item,
                            modify: {
                                ...item.modify,
                                ...params.items,
                                params: [
                                    ...(item.modify?.params || []),
                                    ...(params.items.params || [])
                                ]
                            }
                        };
                    }
                    return item;
                });
            }
            if (this.data.settings.enable_progress_bar) {
                style.push({
                    group_name: 'progess_bar',
                    group_title: this.$t('progress_bar'),
                    selector: ' .ecom-product-single__countdown-progress-bar',
                    params: [
                        {
                            type: 'number',
                            name: 'maxWidth',
                            label: this.$t('width'),
                            options: {
                                responsive: true,
                                reset: true,
                                units: {
                                    '%': {
                                        min: 0,
                                        max: 100
                                    },
                                    px: {
                                        min: 0,
                                        max: 1000
                                    },
                                    vw: {
                                        min: 0,
                                        max: 100
                                    }
                                }
                            },
                            css:{
                                properties:{
                                    'max-width':''
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'height',
                            label: this.$t('height'),
                            options: {
                                responsive: true,
                                reset: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 1000
                                    },
                                    vh: {
                                        min: 0,
                                        max: 100
                                    }
                                }
                            },
                            css:{
                                selector: ' .ecom-product-single__countdown-progress-bar--timer',
                                properties:{
                                    'height':'',
                                    '--ecom-countdown-max-height':''
                                }
                            }
                        },
                        {
                            name: 'tab',
                            type: 'tab',
                            value: 'normal',
                            options: {
                                tabs: [
                                    {
                                        name: 'normal',
                                        title: this.$t('normal'),
                                    },
                                    {
                                        name: 'active',
                                        title: this.$t('active'),
                                    }
                                ]
                            },
                            css: {
                                isCss: false,
                            }
                        },
                        {
                            type: 'background',
                            label: this.$t('background'),
                            name: 'background',
                            options: {
                                oneline: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['tab'] === 'normal';
                                    }
                                }
                            },
                            css:{
                                properties:{
                                    'background':''
                                }
                            }
                        },
                        {
                            type: 'dimension',
                            name: 'borderRadius',
                            label: this.$t('border_radius'),
                            options: {
                                type: 'radius',
                                units: 'default',
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['tab'] === 'normal';
                                    }
                                }
                            },
                            css:{
                                properties:{
                                    'border-radius':''
                                }
                            }
                        },
                        {
                            type: 'background',
                            label: this.$t('background'),
                            name: 'backgroundActive',
                            options: {
                                oneline: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['tab'] === 'active';
                                    }
                                }
                            },
                            css:{
                                selector: ' .ecom-product-single__countdown-progress-bar--timer',
                                properties:{
                                    'background':''
                                }
                            }
                        },

                        {
                            type: 'dimension',
                            name: 'borderRadiusActive',
                            label: this.$t('border_radius'),
                            options: {
                                type: 'radius',
                                units: 'default',
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data['tab'] === 'active';
                                    }
                                }
                            },
                            css:{
                                selector: ' .ecom-product-single__countdown-progress-bar--timer',
                                properties:{
                                    'border-radius':''
                                }
                            }
                        },
                        {
                            alias:'spacing',
                            options: {
                                label: this.$t('spacing')
                            }
                        }
                    ]
                });
            }
            return style;
        }
    }
};
</script>
