<template>
    <div class="ecom-element ecom-product-single ecom-product-single__payment-method">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 or request.page_type != 'cart' -%}" />
        <div class="ecom-product-single__playment-method-wrapper">
            <div class="ecom-product-single-payment-method-container">
                <div>
                    <ul
                        v-if="data.settings?.type !== 'custom'"
                        class="ecom-product-single__payment-method-list"
                        role="list"
                        :class="!exporting ? 'ecom-placeholder-on-builder-mode ecom-element__placeholder' : ''"
                        :data-ecom-placeholder="exporting ? '' : 'Your site don\'t have any payment methods'"
                        v-html="liquid('payment_methods')"
                    />
                    <ul
                        v-if="data.settings?.type === 'custom' && data.settings?.source_img !== 'img'"
                        class="ecom-product-single__payment-method-list"
                        role="list"
                        :class="!exporting ? 'ecom-placeholder-on-builder-mode ecom-element__placeholder' : ''"
                        :data-ecom-placeholder="exporting ? '' : 'Your site don\'t have any payment methods'"
                        v-html="liquid('payment_methods_custom')"
                    />
                    <div class="ecom-product-single__payment-method-img--wrapper">
                        <img
                            v-if="data.settings?.type === 'custom' && data.settings?.source_img === 'img'"
                            class="ecom-product-single__payment-method-img"
                            :src="data.settings?.image?.value"
                        />
                    </div>
                </div>
                <p
                    class="ecom-product-single-payment-method-content"
                    v-html="lang(message, 'payment_methods_message')"
                />
            </div>
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
import { Liquid, Element } from '@/mixins';
export default {
    name: 'productPaymentMethod',

    mixins: [Liquid, Element],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        getArrPaymentMethod() {
            if(this.data.settings?.custom_payment) {
                let arr_payment = this.data.settings.custom_payment.split(',');
                return `
                    {%- capture arrPayment -%}
                        ${arr_payment}
                    {%- endcapture -%}
                    {% assign arrPayment = arrPayment | split: ',' %}
                `
            }
            return ''
        },
        liquids() {
            return {
                payment_methods: {
                    code: `
                        {%- for type in shop.enabled_payment_types -%}
                            <li class="ecom-product-single__payment-method-item">
                            {{ type | payment_type_svg_tag: class: 'ecom-product-single__payment-method-svg' }}
                            </li>
                        {%- endfor -%}
                    `,
                    preview: `
                    <div class="ecom-skeleton-item">
                        <div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                        </div>
                    </div>
                `
                },
                payment_methods_custom: {
                    code: `
                        ${this.getArrPaymentMethod}
                        {% if arrPayment %}
                            {%- for type in arrPayment -%}
                                <li class="ecom-product-single__payment-method-item">
                                    {{ type | payment_type_svg_tag: class: 'ecom-product-single__payment-method-svg' }}
                                </li>
                            {%- endfor -%}
                        {% endif %}
                    `,
                    preview: `
                    <div class="ecom-skeleton-item">
                        <div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                        </div>
                    </div>
                `
                }
            };
        },

        settings() {
            return [
                {
                    params: [
                        {
                            type: 'popup',
                            name: 'type',
                            label: this.$t('choose_type'),
                            values: 'available',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    available: this.$t('store_payment_method'),
                                    custom: this.$t('custom'),
                                }
                            }
                        },
                        {
                            type: 'popup',
                            name: 'source_img',
                            label: this.$t('source_img'),
                            values: 'svg',
                            options: {
                                type: 'dropdown',
                                default: false,
                                preview: 'title',
                                values: {
                                    img: this.$t('image'),
                                    svg: 'SVG'
                                },
                                visible: (data) => {
                                    return data['type'] === 'custom'
                                }
                            }
                        },
                        {
                            type: 'typograph',
                            name: 'typograph_img',
                            content: '<b>'+this.$t('image')+'</b>',
                            options: {
                                visible: (data) => {
                                    return data['type'] === 'custom' && data['source_img'] === 'img'
                                }
                            }
                        },
                        {
                            type: 'picker',
                            label: this.$t('choose_image'),
                            name: 'image',
                            options: {
                                responsive: true,
                                type: 'image',
                                editAlt: true,
                                visible: (data) => {
                                    return data['type'] === 'custom' && data['source_img'] === 'img'
                                }
                            }
                        },
                        {
                            type: 'typograph',
                            name: 'typograph_svg',
                            content: '<b>SVG</b>',
                            options: {
                                visible: (data) => {
                                    return data['type'] === 'custom' && data['source_img'] === 'svg'
                                }
                            }
                        },
                        {
                            type: 'textarea',
                            name: 'custom_payment',
                            label: this.$t('svg_list'),
                            description: 'Ex: amazon_payments,american_express,<br>apple_pay,bitcoin,dankort,diners_club,<br>discover,dogecoin,dwolla,<br>forbrugsforeningen,interac,google_pay,<br>jcb,klarna,klarna-pay-later,<br>litecoin,maestro,master,paypal,<br>shopify_pay,sofort,visa,cartes_bancaires...[see more method](https://github.com/activemerchant/payment_icons/tree/master/app/assets/images/payment_icons)',
                            options: {
                                visible: (data) => {
                                    return data['type'] === 'custom' && data['source_img'] === 'svg'
                                }
                            }
                        },
                        {
                            type: 'number',
                            name:'spacing',
                            label: this.$t('spacing'),
                            options:{
                                responsive: true,
                                units:{
                                    px:{
                                        min:0,
                                        max:50
                                    }
                                },
                                visible: (data) => {
                                    return data['source_img'] !== 'img'
                                }
                            },
                            css:{
                                selector: ' .ecom-product-single__payment-method-list',
                                properties: {
                                    gap: ''
                                }
                            }
                        },
                        {
                            type: 'textarea',
                            name: 'message',
                            label: this.$t('message'),
                            options: {
                                height: 80,
                                toolbar: 'short'
                            }
                        }
                    ]
                }
            ];
        },
        message() {
            return this.data && this.data.settings && this.data.settings.message
                ? this.data.settings.message
                : '';
        },

        style() {
            let style = [
                {
                    group_title: this.$t('payment'),
                    group_name: 'payment_group',
                    selector:
                        ' .ecom-product-single__playment-method-wrapper .ecom-product-single__payment-method-list',
                    params: [
                        {
                            type: "number",
                            name: "svg_width",
                            label: this.$t("width"),
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 200
                                    }
                                }
                            },
                            css: {
                                selector: " .ecom-product-single__payment-method-svg",
                                properties: {
                                    width: ""
                                }
                            }
                        },
                        {
                            type: "number",
                            name: "svg_height",
                            label: this.$t("height"),
                            options: {
                                responsive: true,
                                units: {
                                    px: {
                                        min: 0,
                                        max: 200
                                    }
                                }
                            },
                            css: {
                                selector: " .ecom-product-single__payment-method-svg",
                                properties: {
                                    height: ""
                                }
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('alignment'),
                            name: 'justify-content',
                            value: 'left',
                            options: {
                                oneline: true,
                                responsive: true,
                                type: 'text-align',
                                values: ['flex-start', 'center', 'flex-end']
                            }
                        },
                        {
                            name: 'spacing',
                            type: 'dimension',
                            label: this.$t('spacing'),
                            options: {
                                responsive: true,
                                units: 'default'
                            }
                        },
                    ]
                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('label'),
                        group_name: 'payment_text',
                        selector:
                            ' .ecom-product-single__playment-method-wrapper .ecom-product-single-payment-method-content'
                    }
                }
            ];
            if(this.data.settings?.type === 'custom' && this.data.settings?.source_img === 'img') {
                style.push({
                    group_alias: 'image',
                    options: {
                        group_title: this.$t('image'),
                        selector: 'root .ecom-product-single__payment-method-img--wrapper'
                    },
                    modify: {
                        remove: {
                            index: 0,
                            length: 2
                        },
                        params: [
                            {
                                position: 2,
                                fields: [
                                    {
                                        type: 'number',
                                        name: 'width',
                                        label: this.$t('width'),
                                        options: {
                                            units: {
                                                '%': {
                                                    min: 0,
                                                    max: 100
                                                },
                                                'px': {
                                                    min: 0,
                                                    max: 1000
                                                },
                                                'vw': {
                                                    min: 0,
                                                    max: 100
                                                }
                                            }
                                        },
                                        css: {
                                            properties: {
                                                width: ''
                                            }
                                        }
                                    },
                                    {
                                        type: 'number',
                                        name: 'max_width',
                                        label: this.$t('max_width'),
                                        options: {
                                            units: {
                                                '%': {
                                                    min: 0,
                                                    max: 100
                                                },
                                                'px': {
                                                    min: 0,
                                                    max: 1000
                                                },
                                                'vw': {
                                                    min: 0,
                                                    max: 100
                                                }
                                            }
                                        },
                                        css: {
                                            properties: {
                                                'max-width': ''
                                            }
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                })
            }
            return style;
        },

        css() {
            return `
                .ecom-placeholder-on-builder-mode.ecom-element__placeholder:empty::before{
                    display: flex;
                    flex-direction: row;
                    flex-wrap: nowrap;
                    position: relative;
                    justify-content: center;
                    align-items: center;
                    border-radius: 8px;
                    border: 1px dashed #91D0FF;
                    color: #00527C;
                    font-size: 13px;
                    line-height: 20px;
                    font-weight: 650;
                    opacity: 1;
                    padding: 6px;
                }
                .ecom-product-single__payment-method-list{
                    padding:0;
                    display:flex;
                    flex-wrap:wrap;
                }
                .ecom-product-single__payment-method-list li{
                    display:inline-flex;
                }

            `;
        },

        default() {
            return {
                settings: {
                    type: 'available',
                    source_img: 'svg',
                    custom_payment: 'amazon_payments,american_express,apple_pay,bitcoin,dankort,diners_club,discover,dogecoin,dwolla,forbrugsforeningen,interac,google_pay,jcb,klarna,klarna-pay-later,litecoin,maestro,master,paypal,shopify_pay,sofort,visa',
                    message: "Guarantee safe & secure checkout"
                },
                style: {
                    payment_group: {
                        "justify-content": "flex-start"
                    }
                }
            }
        }
    },
    methods: {}
};
</script>
