<template>
    <div class="ecom-element ecom-product-single ecom-product-single__selling-plan">
        <div class="ecom-product-single__selling-plan-wrapper">
            <div class="ecom-product-single__selling-plan-container" :class="!exporting ? 'ecom-placeholder-on-builder-mode ecom-element__placeholder': ''" :data-ecom-placeholder="exporting? '': 'This product don\'t have selling plans'"
                v-html="liquid('selling_plans')"
            />
        </div>
    </div>
</template>

<script>
import { Liquid, Element,Javascript } from '@/mixins';
import SELLING_PLAN_GROUPS from '@/services/liquid/mocks/selling-plan-groups.json';
export default {
    name: 'productSellingPlan',
    presets:true,
    mixins: [Liquid, Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {


        css() {
            return `
                .ecom-placeholder-on-builder-mode.ecom-element__placeholder:empty::before{
                    display: flex;
                    flex-direction: row;
                    flex-wrap: nowrap;
                    position: relative;
                    justify-content: center;
                    align-items: center;
                    border-radius: 8px;
                    border: 1px dashed #91D0FF;
                    color: #00527C;
                    font-size: 13px;
                    line-height: 20px;
                    font-weight: 650;
                    opacity: 1;
                    padding: 6px;
                }
                .ecom-product-single__selling-plan-fieldset{
                    display: block;
                    margin-inline-start: 2px;
                    margin-inline-end: 2px;
                    padding-block-start: 0.35em;
                    padding-inline-start: 0.75em;
                    padding-inline-end: 0.75em;
                    padding-block-end: 0.625em;
                    min-inline-size: min-content;
                    border-width: 2px;
                    border-style: groove;
                    border-color: threedface;
                    border-image: initial;
                }
                .ec-purchase-options{
                    margin-left:15px;
                }
                .ecom-product-single__selling-plan-fieldset--input {
                    display: block
                }
                .ecom-product-single__selling-plan-fieldset--input input[type="radio"]{
                        -webkit-appearance: none;
                        -moz-appearance: none;
                        appearance: none;
                        padding: 0;
                        -webkit-print-color-adjust: exact;
                        color-adjust: exact;
                        display: inline-block;
                        vertical-align: middle;
                        background-origin: border-box;
                        -webkit-user-select: none;
                        -moz-user-select: none;
                        -ms-user-select: none;
                        user-select: none;
                        flex-shrink: 0;
                        position:relative;
                    }
                .ecom-product-single__selling-plan-fieldset--input input[type="radio"]:checked::after{
                        position:absolute;
                        content:'';
                        left:50%;
                        top:50%;
                        transform:translate(-50%,-50%)
                    }
            `;
        },

        heading() {
            return this.data && this.data.settings && this.data.settings.tag
                ? this.data.settings.tag
                : 'h3';
        },

        mock() {
            return `
                <fieldset class="ecom-product-single__selling-plan-fieldset">
                    <legend class="ecom-product-single__selling-plan-fieldset-header">${this.lang(this.data.settings?.title??'','selling_plan_title')}</legend>
                    <input type="hidden" name="selling_plan" value="{{ current_selling_plan_allocation.selling_plan.id | default: '' }}">
                    <label class="ecom-product-single__selling-plan-fieldset--input">
                        <input type="radio" name="purchase_option" value="onetime">
                        ${this.lang(this.data.settings?.one_time_text,'one_time_text')}
                    </label>
                    ${SELLING_PLAN_GROUPS.map(group => {
                        const subscription_text = this.lang(this.data.settings?.subscription_text,'subscription_text');
                        return `
                            <div  class="ecom-product-single__selling-plan-fieldset--input">
                                <label class="ecom-product-single__selling-plan-fieldset-frequency-header" for="purchase_option">
                                <input type="radio" name="purchase_option" value="${group.id}">
                                   ${subscription_text != "" ? subscription_text : group.name}
                                </label>
                            </div>
                            <div class="ec-purchase-options">
                                ${group.options.map(option => {
                                    const frequency_header = this.lang(this.data.settings?.frequency_header,'frequency_header');
                                    return `
                                        <label class="ec-selling-plan-frequency-label">
                                            ${frequency_header != "" ? frequency_header : option.name}
                                        </label>
                                        <select class="ecom-product-single__selling-plan-select" name="group-option-{{group.id}}" data-group-id="{{group.id}}"  data-position="{{ option.position }}">
                                            ${option.values.map(value => {
                                                const indexSelling = option.values.indexOf(value);
                                                return `
                                                    <option value="${value}">${group.selling_plans[indexSelling].name}</option>
                                                `;
                                            }).join('')}
                                        </select>
                                `
                                }).join('')}
                            </div>
                    `
                    }).join('')}
                </fieldset>
            `;
        },

        liquids() {
            return {
                'selling_plans': {
                    code: this.canUseCustomLiquidForCSR
                    ? this.mock
                    : `
                        {%- liquid
                            assign current_variant = product.selected_or_first_available_variant | default: product.variants.first
                            assign current_selling_plan_allocation = current_variant.selected_selling_plan_allocation
                            if current_selling_plan_allocation == nil and current_variant.requires_selling_plan
                                assign current_selling_plan_allocation = current_variant.selling_plan_allocations | first
                            endif
                            assign offer = current_selling_plan_allocation | default: current_variant
                            assign hide_when_dont_have = ${this.data.settings?.hide_when_dont_have} | default: false
                        -%}
                         {% comment %}
                            {{ offer.price | money }}
                            {% if offer.compare_at_price > offer.price %}
                            <s>{{ offer.compare_at_price | money }}</s>
                            <span>{% if offer.selling_plan %}Subscription{% else %}Sale{% endif %}</span>
                        {% endif %}
                        {% endcomment %}
                        {% if hide_when_dont_have == false or product.requires_selling_plan or product.selling_plan_groups != blank %}
                        <fieldset class="ecom-product-single__selling-plan-fieldset">
                            <legend class="ecom-product-single__selling-plan-fieldset-header">${this.lang(this.data.settings?.title??'','selling_plan_title')}</legend>
                            <input type="hidden" name="selling_plan" value="{{ current_selling_plan_allocation.selling_plan.id | default: '' }}">
                            {% unless product.requires_selling_plan %}
                                <label class="ecom-product-single__selling-plan-fieldset--input">
                                    <input type="radio" name="purchase_option" value="onetime">
                                    ${this.lang(this.data.settings?.one_time_text,'one_time_text')}
                                </label>
                            {% endunless %}
                            {% for group in product.selling_plan_groups %}
                                <div  class="ecom-product-single__selling-plan-fieldset--input">
                                    <label class="ecom-product-single__selling-plan-fieldset-frequency-header" for="purchase_option">
                                    <input type="radio"  {% if product.requires_selling_plan %} required {% endif %} name="purchase_option" value="{{group.id}}">
                                        {%- capture ec_text -%}${this.lang(this.data.settings?.subscription_text,'subscription_text')}{% endcapture%}
                                        {%- if ec_text != "" -%}{{- ec_text -}}{%- else -%}{{ group.name}}{%- endif -%}
                                    </label>
                                </div>
                                <div class="ec-purchase-options">
                                    {% for option in group.options %}
                                        <label class="ec-selling-plan-frequency-label">
                                            {%- capture ec_text -%}${this.lang(this.data.settings?.frequency_header,'frequency_header')}{% endcapture%}
                                            {%- if ec_text != "" -%}{{- ec_text -}}{%- else -%}{{ option.name  }}{%- endif -%}
                                        </label>
                                        <select class="ecom-product-single__selling-plan-select" name="group-option-{{group.id}}" data-group-id="{{group.id}}"  data-position="{{ option.position }}">
                                        {% for value in option.values %}
                                            {% assign indexSelling = forloop.index | minus: 1 %}
                                            <option value="{{value}}">{{ group.selling_plans[indexSelling].name }}</option>
                                        {% endfor %}
                                        </select>
                                    {% endfor %}
                                </div>

                            {% endfor %}

                        </fieldset>
                        {% endif %}
                    `,
                    preview: `
                    <div class="ecom-skeleton-item">
                        <div>
                            <div class="ecom-skeleton-row">
                                <div class="ecom-skeleton-col-4"></div>
                                <div class="ecom-skeleton-col-8 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-6"></div>
                                <div class="ecom-skeleton-col-6 ecom-skeleton-empty"></div>
                                <div class="ecom-skeleton-col-2"></div>
                                <div class="ecom-skeleton-col-10 ecom-skeleton-empty"></div>
                            </div>
                        </div>
                    </div>`
                }
            };
        },
        javascript(){
            return function(){
                if(!this.$el) return;
                let $el = this.$el,
                    parentEl = $el.querySelector('.ecom-product-single__selling-plan-container');
                if(parentEl && parentEl.innerHTML.trim() == '' && window.EComposer.TEMPLATE_ID) {
                    if($el.closest('.ecom-core')) $el.closest('.ecom-core').style.margin = '0';
                    return;
                }
                var sellingPlanContainer = $el.querySelector('.ecom-product-single__selling-plan-fieldset');
                var productForm =$el.closest('form.ecom-product-form--single');
                if(!productForm || !sellingPlanContainer)
                {
                    return ;
                }
                let selector = productForm.querySelector('[name="id"]');
                const variantCount = selector ? parseInt(selector.getAttribute('ec-variants')) : 0;
                const isHighVariantProduct = this.isLive && (variantCount > 250 || productForm.querySelector('[data-high-variant-product]'));
                if (!selector) { return; }
                let json = productForm.querySelector('#' + selector.dataset.jsonProduct);
                if (!json) { return; }
                let product = null;
                try {
                    product = JSON.parse(json.innerHTML);
                } catch (e) {
                    console.warn(e.message);
                    return;
                }

                var findSelectedVariant = function() {
                    var selectedVariantId = parseInt(selector.value);
                    var selectedVariant;

                    if(isHighVariantProduct) {
                        selectedVariant = product
                    }
                    else {
                        for (var i = 0; i < product.variants.length; i++) {
                            if (product.variants[i].id === selectedVariantId) {
                            selectedVariant = product.variants[i];
                            break;
                            }
                        }
                    }

                    return selectedVariant;
                };

                // Watch for variant selection to update selling plan option selectors
                productForm.addEventListener('change', function() {
                var selectedVariant = findSelectedVariant();
                var availableSellingPlanAllocations = selectedVariant.selling_plan_allocations;
                // Update the selling plan option selectors based on the available selling plan allocations
                // for the selected variant
                });

                // Watch for selling plan option change to update the selected selling plan
                sellingPlanContainer.querySelectorAll('select').forEach(function(optionSelector) {
                optionSelector.addEventListener('change', function(e) {
                    var selectedVariant = findSelectedVariant();
                    var availableSellingPlanAllocations = selectedVariant.selling_plan_allocations;
                    var selectedSellingPlanId;
                    for (var i = 0; i < availableSellingPlanAllocations.length; i++) {
                    var sellingPlan = availableSellingPlanAllocations[i].selling_plan;
                    var matchingSellingPlan = e.target.value === sellingPlan.name || sellingPlan.name.startsWith(e.target.value);
                    if(!matchingSellingPlan) {
                        const options = sellingPlan.options;
                        if(options) {
                            for(var j = 0; j < options.length; j++) {
                                if(options[j].value === e.target.value) {
                                    matchingSellingPlan = true;
                                    break;
                                }
                            }
                        }
                    }
                    // Logic to find matching selling plan

                        if (matchingSellingPlan) {
                            selectedSellingPlanId = sellingPlan.id;
                        }
                    }

                    selectedSellingPlanId = (typeof selectedSellingPlanId === 'undefined') ? '' : selectedSellingPlanId;
                    productForm.querySelector('[name="selling_plan"]').value = selectedSellingPlanId;
                    let id = e.target.dataset.groupId;
                    productForm.querySelector('[name="purchase_option"][value="'+id+'"]').checked = true;

                });
                });
                sellingPlanContainer.querySelectorAll('[name="purchase_option"]').forEach(function(optionSelector) {
                    optionSelector.addEventListener('change', function(e) {
                        if(e.target.value == 'onetime')
                        {
                            productForm.querySelector('[name="selling_plan"]').value = '';
                        }
                        else
                        {
                            let defaultOption = productForm.querySelector('[name="group-option-'+e.target.value+'"]');
                            if(defaultOption)
                            {
                                defaultOption.dispatchEvent(new Event('change'))
                            }

                        }
                    });
                });

            };
        },
        requestShopifyType() {
            return {
                shopify_type: 'product'
            };
        },

        settings() {
            return [{
                params: [


                    {
                        type: 'text',
                        name: 'title',
                        label: this.$t('title'),
                        options: {
                            placeholder: this.$t('purchase_options'),
                        }
                    },
                    {
                        type: 'text',
                        name: 'one_time_text',
                        label: this.$t('one_time_title'),
                        options: {
                            placeholder: this.$t('one_time_purchase'),
                        }
                    },
                    {
                        type: 'text',
                        name: 'subscription_text',
                        label: this.$t('subscription_text'),
                        options: {
                            placeholder: this.$t('subscribe_and_save'),
                        }
                    },
                    {
                        type: 'text',
                        name: 'frequency_header',
                        label: this.$t('frequency_header'),
                        options: {
                            placeholder: this.$t('delivery_frequency'),
                        }
                    },
                    {
                        type: 'switch',
                        name: 'hide_when_dont_have',
                        label: this.$t('hide_element_when_product_don_t_have_purchase_options'),
                        options: {
                            values: {
                                on: {
                                    label: this.$t('yes'),
                                    value: true
                                },
                                off: {
                                    label: this.$t('no'),
                                    value: false
                                }
                            }
                        }
                    },
                    {
                        type: 'paragraph',
                        content: this.$t('to_see_information_about_your_subscriptions_you_must_be_using_a_subscription_app_from_the_shopify_app_store_https_apps_shopify_com_collections_checkout_subscription')
                    },
                ]
            }];
        },

        style() {
            return [
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('header_text'),
                        group_name: 'title',
                        selector: ' .ecom-product-single__selling-plan-fieldset-header'
                    },
                    modify: {
                        params: {
                            position: 4,
                            fields: {
                                alias: 'border',
                                options: {
                                    label: this.$t('border'),
                                    css: {
                                        selector: 'root .ecom-product-single__selling-plan-fieldset'
                                    }
                                }
                            }
                        }
                    }
                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('frequency_header'),
                        group_name: 'frequency_header',
                        selector: ' .ecom-product-single__selling-plan-fieldset-frequency-header'
                    },

                },
                {
                    group_alias: 'text:spacing',
                    options: {
                        group_title: this.$t('frequency_text'),
                        group_name: 'frequency_text',
                        selector: ' .ec-selling-plan-frequency-label'
                    },

                },
                {
                    group_title: this.$t('radio'),
                    group_name: 'radio',
                    selector: ' .ecom-product-single__selling-plan-fieldset--input input[type="radio"]',
                    params: [
                          {
                                    alias: 'spacing',
                                    options: {
                                        name: 'spacingLabel'
                                    }
                                },
                                {
                                        type: 'tab',
                                        name: 'tab',
                                        value: 'normal',
                                        options: {
                                            tabs: [
                                                {
                                                    name: 'normal',
                                                    title: this.$t('normal'),
                                                },
                                                {
                                                    name: 'hover',
                                                    title: this.$t('hover'),
                                                },
                                                {
                                                    name: 'active',
                                                    title: this.$t('active'),
                                                }
                                            ]
                                        },
                                        css: false
                                    },
                                     {
                                        alias: 'background',
                                        options: {
                                            css: {
                                            },
                                            options: {
                                                visible: data => data['tab'] === 'normal'
                                            }
                                        }
                                    },
                                    {
                                        alias: 'background',
                                        options: {
                                            name: 'backgroundHover',
                                            css: {
                                                selector:':hover',
                                                properties: {
                                                    background: ''
                                                },
                                            },
                                            options: {
                                                visible: data => data['tab'] === 'hover'
                                            }
                                        }
                                    },
                                    {
                                        alias: 'background',
                                        options: {
                                            name: 'backgroundActive',
                                            css: {
                                                properties: {
                                                    background: ''
                                                },
                                                selector:':checked',
                                                important: true,
                                            },
                                            options: {
                                                visible: data => data['tab'] === 'active'
                                            }
                                        }
                                    },
                                    {
                                        type: 'popup',
                                        label: this.$t('border'),
                                        name: 'popup',
                                        options: {
                                            type: 'border',
                                            visible: data => data['tab'] === 'normal'
                                        },
                                        css: {
                                        }
                                    },
                                    {
                                        type: 'popup',
                                        label: this.$t('border'),
                                        name: 'popupHover',
                                        options: {
                                            type: 'border',
                                            visible: data => data['tab'] === 'hover'
                                        },
                                        css: {
                                            selector:':hover',
                                            properties: {
                                                border: ''
                                            },
                                        }
                                    },
                                    {
                                        type: 'popup',
                                        label: this.$t('border'),
                                        name: 'popupActive',
                                        options: {
                                            type: 'border',
                                            visible: data => data['tab'] === 'active'
                                        },
                                        css: {
                                            properties: {
                                                border: ''
                                            },
                                            selector:':checked',
                                            important: true,
                                        }
                                    },
                                    {
                                        type: 'dimension',
                                        label: this.$t('border_radius'),
                                        name: 'border-radius',
                                        options: {
                                            units: 'default',
                                            type: 'radius',
                                            visible: data => data['tab'] === 'normal'
                                        },
                                        css: {
                                            important:true,
                                        }
                                    },
                                    {
                                        type: 'dimension',
                                        label: this.$t('border_radius'),
                                        name: 'border-radiusHover',
                                        options: {
                                            units: 'default',
                                            type: 'radius',
                                            visible: data => data['tab'] === 'hover'
                                        },
                                        css: {
                                            important:true,
                                            selector:':hover',
                                            properties: {
                                                'border-radius': ''
                                            },
                                        }
                                    },
                                    {
                                        type: 'dimension',
                                        label: this.$t('border_radius'),
                                        name: 'border-radiusActive',
                                        options: {
                                            units: 'default',
                                            type: 'radius',
                                            visible: data => data['tab'] === 'active'
                                        },
                                        css: {
                                            selector:':checked',
                                            properties: {
                                                'border-radius': ''
                                            },
                                            important: true,
                                        }
                                    },
                                    {
                                        name: "transition",
                                        type: "number",
                                        label: this.$t('transition_duration_span_class_lowercase_ms_span'),
                                        options: {
                                            min: 0,
                                            max: 5000,
                                            visible: {
                                                keep_data: true,
                                                condition: (data) => {
                                                    return data["tab"] === "hover";
                                                }
                                            }
                                        },
                                        css: {
                                            properties: {
                                                transition: "all %value%ms ease"
                                            }
                                        }
                                    },
                                    {
                                        type: 'line'
                                    },
                                    { alias: 'spacing', options: {css: { }}}

                        ],

                }

            ];
        },

        default() {
            return  {
                "settings": {
                    "title": "Purchase options",
                    "one_time_text": "One-time purchase"
                },
                "style": {
                    "radio": {
                        "tab": "hover",
                        "popup": {
                            "border-style": "solid",
                            "border-width": {
                                "top": "2px",
                                "left": "2px",
                                "bottom": "2px",
                                "right": "2px"
                            },
                            "border-color": "#8c8c8c"
                        },
                        "border-radius": {
                            "right": "50%",
                            "top": "50%",
                            "left": "50%",
                            "bottom": "50%"
                        },
                        "spacing": {
                            "margin": {
                                "right": "5px",
                                "top": "5px",
                                "left": "5px",
                                "bottom": "5px"
                            },
                            "padding": {
                                "top": "6px",
                                "left": "6px",
                                "bottom": "6px",
                                "right": "6px"
                            }
                        },
                        "popupHover": {
                            "border-style": "solid",
                            "border-width": {
                                "right": "2px",
                                "top": "2px",
                                "left": "2px",
                                "bottom": "2px"
                            },
                            "border-color": "#0e7490"
                        },
                        "backgroundActive": {
                            "classic": {
                                "background-color": "#0e7490"
                            }
                        },
                        "transition": 300
                    },
                    "title": {
                        "textTextAlign": "left"
                    },
                    "Radio": {
                        "textTextAlign": "left"
                    }
                }
            }
        }
    },
};
</script>
