const QR_GENERATOR_BASE = 'https://qr.ecomposer.app/generator';

/** Max encoded content length per Worker API. */
export const QR_DATA_MAX_LENGTH = 2000;

export type QrContentSource = 'static_text' | 'custom_liquid';

export type QrcodeSettingsInput = {
    content_source?: QrContentSource | string;
    content_type?: string;
    content?: string;
    qr_size?: number | string;
    margin_size?: number | string;
    logo?: string | { value?: string; url?: string; src?: string };
    logo_size?: number | string;
    qr_foreground_color?: string;
    qr_background_color?: string;
    /** Shopify CDN URL of the uploaded static QR image (static_text only). */
    qr_image?: string;
    /** Shopify File GID used for replace/delete on re-upload. */
    qr_file_id?: string;
};

/** Settings keys in `data.settings` that map to Worker GET `/generator` query params. */
export const QR_API_SETTINGS_KEYS = [
    'content_source',
    'content_type',
    'content',
    'qr_size',
    'margin_size',
    'logo',
    'logo_size',
    'qr_foreground_color',
    'qr_background_color',
] as const;

/** @deprecated Colors live in `data.settings`; kept for legacy pages stored in `data.style`. */
export const QR_API_STYLE_KEYS = [
    'qr_foreground_color',
    'qr_background_color',
] as const;

export const QR_DEFAULT_ECC = 'M';
export const QR_DEFAULT_QUALITY = 92;

/** Normalized params sent to qr.ecomposer.app/generator (GET). */
export type QrGeneratorApiParams = {
    data: string;
    size: number;
    fg: string;
    bg: string;
    ecc: string;
    margin: number;
    quality: number;
    logo?: string;
    logoRatio?: number;
};

/** Error codes from Worker JSON `{ "error": "<code>", "details": {} }`. */
export const QR_API_ERROR_CODES = {
    VALIDATION: 'validation',
    LOGO_TOO_LARGE: 'logo_too_large',
    LOGO_INVALID: 'logo_invalid',
    RATE_LIMIT: 'rate_limit',
    LOGO_UPSTREAM: 'logo_upstream',
    INTERNAL: 'internal',
    NOT_FOUND: 'not_found',
    METHOD_NOT_ALLOWED: 'method_not_allowed',
} as const;

export type QrApiErrorCode = (typeof QR_API_ERROR_CODES)[keyof typeof QR_API_ERROR_CODES] | string;

export type QrGeneratorErrorPayload = {
    error: string;
    httpStatus: number;
    retryAfterSeconds?: number;
    details?: Record<string, unknown>;
};

export type QrGeneratorValidateResult =
    | { ok: true }
    | ({ ok: false } & QrGeneratorErrorPayload);

export function normalizeQrContent(settings: QrcodeSettingsInput): string {
    const s = settings || {};
    let content = (s.content || '').trim();
    if (!content) {
        return '';
    }
    switch (s.content_type) {
        case 'phone':
            content = 'tel:' + content;
            break;
        case 'email':
            content = 'mailto:' + content;
            break;
        case 'whatsapp':
            content = 'https://wa.me/' + String(content).replace(/\D/g, '');
            break;
        case 'link':
        case 'text':
        default:
            break;
    }
    return content;
}

/** Query string for generator URL excluding `data` (used with Liquid `append`). */
export function buildQrStaticQueryString(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean } = {}
): string {
    const params = buildQrGeneratorApiParams(settings, style, options);
    if (!params) {
        return '';
    }
    return buildQrQueryStringFromParams(params, { includeData: false });
}

/**
 * Extract only Worker API params from element settings/style.
 * Display-only fields (alignment, link_wrap, download_button, wrapper CSS, …) are ignored.
 */
export function buildQrGeneratorApiParams(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean; rawContent?: string } = {}
): QrGeneratorApiParams | null {
    const s = settings || {};
    let data =
        options.rawContent !== undefined
            ? options.rawContent
            : isQrCustomLiquidSource(s)
                ? (s.content || '').trim()
                : normalizeQrContent(s);

    if (!data || !data.trim()) {
        return null;
    }
    if (!hasLiquidInContent(data)) {
        data = normalizeQrPayloadText(data);
    }
    if (!data) {
        return null;
    }

    const sizeParsed = parseInt(String(s.qr_size), 10);
    const size = isNaN(sizeParsed) ? 200 : Math.min(2048, Math.max(64, sizeParsed));

    const marginParsed = parseInt(String(s.margin_size), 10);
    const margin = isNaN(marginParsed) ? 4 : Math.min(16, Math.max(0, marginParsed));

    const fg = hexForApi(style?.qr_foreground_color || s.qr_foreground_color || '#000000');
    const bg = hexForApi(style?.qr_background_color || s.qr_background_color || '#ffffff');

    const params: QrGeneratorApiParams = {
        data,
        size,
        fg,
        bg,
        ecc: QR_DEFAULT_ECC,
        margin,
        quality: QR_DEFAULT_QUALITY,
    };

    const logoUrl = resolveLogoUrl(s.logo);
    if (logoUrl && !options.omitLogo && isValidQrLogoUrl(logoUrl)) {
        params.logo = logoUrl;
        params.logoRatio = logoRatioFromPercent(s.logo_size);
    }

    return params;
}

/** Stable fingerprint — only changes when Worker API params change. */
export function buildQrApiFingerprint(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean; rawContent?: string } = {}
): string {
    const params = buildQrGeneratorApiParams(settings, style, options);
    return params ? JSON.stringify(params) : '';
}

function buildQrQueryStringFromParams(
    params: QrGeneratorApiParams,
    options: { includeData?: boolean } = {}
): string {
    const qs = new URLSearchParams();
    if (options.includeData) {
        qs.set('data', params.data);
    }
    qs.set('size', String(params.size));
    qs.set('margin', String(params.margin));
    qs.set('fg', params.fg);
    qs.set('bg', params.bg);
    qs.set('ecc', params.ecc);
    qs.set('quality', String(params.quality));
    if (params.logo) {
        qs.set('logo', params.logo);
        qs.set('logoRatio', String(params.logoRatio ?? 0.2));
    }
    return qs.toString();
}

/** Build GET URL from normalized API params. */
export function buildQrGeneratorUrlFromParams(params: QrGeneratorApiParams): string {
    const query = buildQrQueryStringFromParams(params, { includeData: false });
    return `${QR_GENERATOR_BASE}?data=${encodeURIComponent(params.data)}&${query}`;
}

/** Normalize Liquid content for absolute QR payload on product templates. */
export function normalizeQrLiquidCaptureContent(content: string): string {
    const raw = (content || '').trim();
    if (/^\{\{\s*product\.url\s*\}\}$/i.test(raw)) {
        return '{{ shop.url }}{{ product.url }}';
    }
    return raw;
}

/**
 * Liquid block: capture QR payload from settings.content (supports `{{ product.url }}`).
 */
export function buildQrDataLiquidCapture(settings: QrcodeSettingsInput): string {
    const raw = normalizeQrLiquidCaptureContent((settings.content || '').trim());
    return `{% capture ecom_qr_data %}${raw}{% endcapture %}`;
}

/**
 * Liquid output for img `src` — only `data` is url_encode'd (not the whole generator URL).
 * Requires `{% capture ecom_qr_data %}…{% endcapture %}` to run earlier on the page.
 */
export function buildQrGeneratorLiquidImgSrc(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean } = {}
): string {
    const query = buildQrStaticQueryString(settings, style, options);
    return `https://qr.ecomposer.app/generator?data={{ ecom_qr_data | strip_html | strip | url_encode }}&${query}`;
}

/** Full Liquid snippet for builder processLiquid (capture + absolute generator URL). */
export function buildQrLiquidProcessCode(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean } = {}
): string {
    return `${buildQrDataLiquidCapture(settings)}\n${buildQrGeneratorLiquidImgSrc(settings, style, options)}`;
}

/** Builder preview: Worker URL with literal Liquid in `data`, or resolved product URL after processLiquid. */
export function buildQrBuilderPreviewSrc(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean; resolvedData?: string } = {}
): string {
    let resolved = options.resolvedData;
    if (resolved) {
        resolved = ensureAbsoluteQrData(resolved);
    }
    const params = buildQrGeneratorApiParams(settings, style, {
        omitLogo: options.omitLogo,
        rawContent: resolved
    });
    return params ? buildQrGeneratorUrlFromParams(params) : '';
}

/** Relative Shopify paths → absolute URL for QR encoding. */
export function ensureAbsoluteQrData(data: string): string {
    const value = (data || '').trim();
    if (!value || /^https?:\/\//i.test(value) || hasLiquidInContent(value)) {
        return value;
    }
    if (value.startsWith('//')) {
        return `https:${value}`;
    }
    if (value.startsWith('/')) {
        return value;
    }
    return value;
}

/**
 * Join shop origin + relative path for builder preview fallback.
 * @param shopOrigin e.g. https://shop.myshopify.com (no trailing slash)
 */
export function absoluteUrlFromShopPath(shopOrigin: string, path: string): string {
    const base = (shopOrigin || '').replace(/\/$/, '');
    const p = (path || '').trim();
    if (!p) {
        return '';
    }
    if (/^https?:\/\//i.test(p)) {
        return p;
    }
    if (p.startsWith('//')) {
        return `https:${p}`;
    }
    if (!base) {
        return p.startsWith('/') ? p : `/${p}`;
    }
    return `${base}${p.startsWith('/') ? p : `/${p}`}`;
}

export function hasLiquidInContent(content: string): boolean {
    if (!content || typeof content !== 'string') return false;
    return /\{\{|\{%/.test(content);
}

/**
 * Plain text for QR `data` / img alt — strip HTML from Liquid output (metafields, rich text, etc.).
 */
export function stripHtmlForQrPayload(value: string): string {
    if (!value || typeof value !== 'string') {
        return '';
    }
    let text = value
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&amp;/gi, '&')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'");
    text = text.replace(/<[^>]*>/g, '');
    text = text.replace(/[\u0000-\u001F\u007F]+/g, '');
    return text.replace(/\s+/g, ' ').trim();
}

/** Normalize resolved QR payload — keep URLs/schemes; strip HTML from plain text. */
export function normalizeQrPayloadText(value: string): string {
    const trimmed = (value || '').trim();
    if (!trimmed || hasLiquidInContent(trimmed)) {
        return trimmed;
    }
    if (/^https?:\/\//i.test(trimmed) || trimmed.startsWith('tel:') || trimmed.startsWith('mailto:')) {
        return trimmed;
    }
    return stripHtmlForQrPayload(trimmed);
}

/** Liquid for img `alt` on export (requires `ecom_qr_data` capture). */
export function buildQrLiquidAltMarkup(): string {
    return 'QR Code: {{ ecom_qr_data | strip_html | strip | truncate: 120 | escape }}';
}

export type QrLiquidSyntaxResult =
    | { ok: true }
    | { ok: false; message: string };

/**
 * Lightweight client-side Liquid syntax guard before processLiquid / generator API.
 * Does not replace server render — catches obvious unclosed tags while typing.
 */
export function validateQrLiquidSyntax(content: string): QrLiquidSyntaxResult {
    try {
        const raw = (content || '').trim();
        if (!raw) {
            return { ok: false, message: 'QR Liquid content is empty.' };
        }
        const openLogic = (raw.match(/\{%-?/g) || []).length;
        const closeLogic = (raw.match(/-?%\}/g) || []).length;
        if (openLogic !== closeLogic) {
            return {
                ok: false,
                message: 'Invalid Liquid syntax: unclosed {% %} tags.',
            };
        }
        const openOutput = (raw.match(/\{\{-?/g) || []).length;
        const closeOutput = (raw.match(/-?\}\}/g) || []).length;
        if (openOutput !== closeOutput) {
            return {
                ok: false,
                message: 'Invalid Liquid syntax: unclosed {{ }} tags.',
            };
        }
        return { ok: true };
    } catch (e) {
        return {
            ok: false,
            message: e instanceof Error ? e.message : 'Invalid Liquid syntax.',
        };
    }
}

/** True when resolved QR payload is non-empty after trim. */
export function isQrResolvedDataValid(data: string | null | undefined): boolean {
    return !!(data && String(data).trim());
}

/**
 * Normalize processLiquid / qrProcess output into encoded QR `data` string.
 * Returns '' when still unresolved Liquid or empty.
 */
export function extractQrPayloadFromLiquidResult(resolved: string): string {
    const trimmed = (resolved || '').trim();
    if (!trimmed || hasLiquidInContent(trimmed)) {
        return '';
    }
    if (trimmed.startsWith('https://qr.ecomposer.app/')) {
        try {
            const u = new URL(trimmed);
            const data = u.searchParams.get('data');
            if (!data) {
                return '';
            }
            return normalizeQrPayloadText(ensureAbsoluteQrData(data).trim());
        } catch {
            return '';
        }
    }
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
        return trimmed;
    }
    return normalizeQrPayloadText(ensureAbsoluteQrData(trimmed).trim());
}

/**
 * Whether QR payload is rendered via Shopify Liquid (export + builder processLiquid).
 * `static_text`: content is encoded as plain text even if it contains `{{ }}`.
 */
export function isQrCustomLiquidSource(settings: QrcodeSettingsInput): boolean {
    const source = settings?.content_source;
    if (source === 'custom_liquid') {
        return true;
    }
    if (source === 'static_text') {
        return false;
    }
    return hasLiquidInContent(settings?.content || '');
}

export function usesQrLiquidContent(settings: QrcodeSettingsInput): boolean {
    return isQrCustomLiquidSource(settings) && !!(settings?.content || '').trim();
}

export function resolveLogoUrl(logo: QrcodeSettingsInput['logo']): string {
    if (!logo) return '';
    if (typeof logo === 'string') return logo;
    return logo.value || logo.url || logo.src || '';
}

/** Stable key for same asset across picker updates (?v= cache buster, etc.). */
export function normalizeLogoUrlForCompare(url: string): string {
    const raw = (url || '').trim();
    if (!raw) {
        return '';
    }
    try {
        const parsed = new URL(raw);
        return `${parsed.origin}${parsed.pathname}`.toLowerCase();
    } catch {
        return raw.split('?')[0].split('#')[0].toLowerCase();
    }
}

function hexForApi(color: unknown, fallback = '#000000'): string {
    if (typeof color !== 'string') {
        return normalizeHexColor(fallback);
    }
    const c = (color || fallback).trim();
    if (!c) {
        return normalizeHexColor(fallback);
    }
    return c.startsWith('#') ? c : `#${c}`;
}

function normalizeHexColor(color: string): string {
    const c = String(color || '').trim();
    if (!c) {
        return '#000000';
    }
    return c.startsWith('#') ? c : `#${c}`;
}

function logoRatioFromPercent(logoSizePercent: number | string | undefined): number {
    const pct = parseFloat(String(logoSizePercent)) || 20;
    const ratio = pct / 100;
    return Math.min(0.3, Math.max(0.1, ratio));
}

/** Raster formats supported by qr.ecomposer.app Worker (not SVG). */
const QR_LOGO_RASTER_EXT = /\.(png|jpe?g|webp|gif)(\?|#|$)/i;
const QR_LOGO_SVG_EXT = /\.svg(\?|#|$)/i;

/** Worker API max logo payload (1 MB). */
export const QR_LOGO_MAX_BYTES = 1024 * 1024;

export type QrLogoValidationReason =
    | 'https_required'
    | 'unsupported_format'
    | 'max_size'
    | 'unreachable';

/** Returns a validation reason, or null when the logo URL is acceptable. */
export function getQrLogoValidationReason(url: string): QrLogoValidationReason | null {
    if (!url || typeof url !== 'string') {
        return null;
    }
    try {
        const parsed = new URL(url.trim());
        if (parsed.protocol !== 'https:') {
            return 'https_required';
        }
        const path = parsed.pathname.toLowerCase();
        if (QR_LOGO_SVG_EXT.test(path)) {
            return 'unsupported_format';
        }
        if (!QR_LOGO_RASTER_EXT.test(path)) {
            return 'unsupported_format';
        }
        return null;
    } catch {
        return 'https_required';
    }
}

/** Logo must be HTTPS raster image (PNG/JPEG/WebP/GIF) for Worker API. */
export function isValidQrLogoUrl(url: string): boolean {
    return getQrLogoValidationReason(url) === null;
}

/** Read `logo` query param from a generator preview URL. */
export function extractLogoFromGeneratorUrl(generatorUrl: string): string {
    try {
        const logo = new URL(generatorUrl).searchParams.get('logo');
        return logo ? decodeURIComponent(logo) : '';
    } catch {
        return '';
    }
}

/** Probe logo byte size via HEAD, then Range GET fallback (Shopify CDN is CORS-friendly). */
async function probeLogoByteSize(logoUrl: string): Promise<number | null> {
    try {
        const head = await fetch(logoUrl, {
            method: 'HEAD',
            mode: 'cors',
            credentials: 'omit',
        });
        if (head.ok) {
            const len = parseInt(head.headers.get('content-length') || '', 10);
            if (!isNaN(len) && len > 0) {
                return len;
            }
        } else if (head.status === 404 || head.status === 403) {
            return -1;
        }
    } catch {
        /* try GET fallback */
    }

    try {
        const res = await fetch(logoUrl, {
            method: 'GET',
            mode: 'cors',
            credentials: 'omit',
            headers: {
                Range: `bytes=0-${QR_LOGO_MAX_BYTES}`,
            },
        });
        if (res.status === 404 || res.status === 403) {
            return -1;
        }
        if (!res.ok && res.status !== 206) {
            return null;
        }
        const contentRange = res.headers.get('content-range');
        if (contentRange) {
            const match = /\/(\d+)\s*$/.exec(contentRange);
            if (match) {
                return parseInt(match[1], 10);
            }
        }
        const len = parseInt(res.headers.get('content-length') || '', 10);
        if (!isNaN(len) && len > 0) {
            return len;
        }
        const blob = await res.blob();
        if (res.status === 206 && blob.size >= QR_LOGO_MAX_BYTES) {
            return QR_LOGO_MAX_BYTES + 1;
        }
        return blob.size;
    } catch {
        return null;
    }
}

/**
 * In-flight de-dupe: multiple Vue watchers (mount + debounced settings change) can
 * fire near-simultaneously and request the same asset/URL before the first resolves.
 * Coalescing avoids bursts of duplicate network requests to qr.ecomposer.app,
 * which is especially costly on a cold/production connection (see Qrcode.vue mount race).
 */
const _qrLogoValidationInFlight = new Map<string, Promise<QrGeneratorValidateResult>>();
const _qrGeneratorValidationInFlight = new Map<string, Promise<QrGeneratorValidateResult>>();

/**
 * Validate logo format + reachability + size before calling generator API.
 * Avoids mis-mapping CORS-blocked generator errors to LOGO_UPSTREAM.
 * Coalesces concurrent calls for the same logo URL (see _qrLogoValidationInFlight).
 */
export function validateQrLogoAsset(logoUrl: string): Promise<QrGeneratorValidateResult> {
    const key = logoUrl || '';
    const pending = _qrLogoValidationInFlight.get(key);
    if (pending) {
        return pending;
    }
    const promise = validateQrLogoAssetUncached(logoUrl).finally(() => {
        _qrLogoValidationInFlight.delete(key);
    });
    _qrLogoValidationInFlight.set(key, promise);
    return promise;
}

async function validateQrLogoAssetUncached(logoUrl: string): Promise<QrGeneratorValidateResult> {
    const formatReason = getQrLogoValidationReason(logoUrl);
    if (formatReason) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.LOGO_INVALID,
            httpStatus: 422,
            details: { field: 'logo', reason: formatReason },
        };
    }

    const byteSize = await probeLogoByteSize(logoUrl);
    if (byteSize === -1) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.LOGO_UPSTREAM,
            httpStatus: 502,
            details: { field: 'logo', reason: 'unreachable' },
        };
    }
    if (byteSize !== null && byteSize > QR_LOGO_MAX_BYTES) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.LOGO_TOO_LARGE,
            httpStatus: 413,
            details: {
                field: 'logo',
                reason: 'max_size',
                max: QR_LOGO_MAX_BYTES,
                size: byteSize,
            },
        };
    }

    return { ok: true };
}

/** Logo-related errors: retry QR generation without `logo` query param. */
export function isQrLogoRecoverableError(code: string): boolean {
    return (
        code === QR_API_ERROR_CODES.LOGO_TOO_LARGE ||
        code === QR_API_ERROR_CODES.LOGO_INVALID ||
        code === QR_API_ERROR_CODES.LOGO_UPSTREAM
    );
}

/** Client-side validation before calling Worker (400 validation). */
export function validateQrSettingsInput(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string }
): QrGeneratorValidateResult {
    const isLiquid = isQrCustomLiquidSource(settings);
    const data = isLiquid
        ? (settings.content || '').trim()
        : normalizeQrContent(settings);

    if (!isLiquid && (!data || data.length < 1)) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'data', reason: 'empty' }
        };
    }
    if (isLiquid && !data) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'data', reason: 'empty_liquid' }
        };
    }
    if (!isQrCustomLiquidSource(settings) && data.length > QR_DATA_MAX_LENGTH) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'data', reason: 'max_length', max: QR_DATA_MAX_LENGTH }
        };
    }

    const size = parseInt(String(settings.qr_size), 10);
    if (!isNaN(size) && (size < 64 || size > 2048)) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'size', min: 64, max: 2048 }
        };
    }

    const margin = parseInt(String(settings.margin_size), 10);
    if (!isNaN(margin) && (margin < 0 || margin > 16)) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'margin', min: 0, max: 16 }
        };
    }

    const fg = hexForApi(style?.qr_foreground_color || settings.qr_foreground_color || '#000000');
    const bg = hexForApi(style?.qr_background_color || settings.qr_background_color || '#ffffff');
    if (!/^#[0-9A-Fa-f]{6}$/.test(fg) || !/^#[0-9A-Fa-f]{6}$/.test(bg)) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.VALIDATION,
            httpStatus: 400,
            details: { field: 'fg|bg', reason: 'invalid_hex' }
        };
    }

    const logo = resolveLogoUrl(settings.logo);
    const logoReason = logo ? getQrLogoValidationReason(logo) : null;
    if (logoReason) {
        return {
            ok: false,
            error: QR_API_ERROR_CODES.LOGO_INVALID,
            httpStatus: 422,
            details: { field: 'logo', reason: logoReason }
        };
    }

    return { ok: true };
}

/**
 * Map HTTP status → error code when JSON body omits `error`.
 * @see https://qr.ecomposer.app — Error Responses
 */
export function mapQrHttpStatusToError(httpStatus: number, hasLogoInRequest: boolean): string {
    switch (httpStatus) {
        case 400:
            return QR_API_ERROR_CODES.VALIDATION;
        case 404:
            return QR_API_ERROR_CODES.NOT_FOUND;
        case 405:
            return QR_API_ERROR_CODES.METHOD_NOT_ALLOWED;
        case 413:
            return QR_API_ERROR_CODES.LOGO_TOO_LARGE;
        case 422:
            return QR_API_ERROR_CODES.LOGO_INVALID;
        case 429:
            return QR_API_ERROR_CODES.RATE_LIMIT;
        case 502:
            return hasLogoInRequest
                ? QR_API_ERROR_CODES.LOGO_UPSTREAM
                : QR_API_ERROR_CODES.INTERNAL;
        case 500:
            return QR_API_ERROR_CODES.INTERNAL;
        default:
            if (httpStatus >= 500) return QR_API_ERROR_CODES.INTERNAL;
            if (httpStatus >= 400) return QR_API_ERROR_CODES.VALIDATION;
            return QR_API_ERROR_CODES.INTERNAL;
    }
}

export function parseRetryAfterSeconds(res: Response): number | undefined {
    const raw = res.headers.get('retry-after');
    if (!raw) return undefined;
    const seconds = parseInt(raw, 10);
    if (!isNaN(seconds) && seconds > 0) return seconds;
    const date = Date.parse(raw);
    if (!isNaN(date)) {
        const diff = Math.ceil((date - Date.now()) / 1000);
        return diff > 0 ? diff : undefined;
    }
    return undefined;
}

export async function readQrGeneratorErrorBody(
    res: Response
): Promise<{ error?: string; details?: Record<string, unknown> }> {
    try {
        const text = await res.text();
        if (!text.trim()) {
            return {};
        }
        const body = JSON.parse(text);
        return {
            error: typeof body?.error === 'string' ? body.error : undefined,
            details:
                body?.details && typeof body.details === 'object' && !Array.isArray(body.details)
                    ? (body.details as Record<string, unknown>)
                    : undefined
        };
    } catch {
        return {};
    }
}

/**
 * Resolve API error code: HTTP status wins for well-known logo/status codes
 * (Worker may return mismatched body.error on 413, etc.).
 */
export function resolveQrApiErrorCode(
    httpStatus: number,
    bodyError: string | undefined,
    hasLogoInRequest: boolean
): string {
    switch (httpStatus) {
        case 413:
            return QR_API_ERROR_CODES.LOGO_TOO_LARGE;
        case 422:
            return QR_API_ERROR_CODES.LOGO_INVALID;
        case 429:
            return QR_API_ERROR_CODES.RATE_LIMIT;
        case 400:
            return bodyError === QR_API_ERROR_CODES.VALIDATION
                ? bodyError
                : bodyError || QR_API_ERROR_CODES.VALIDATION;
        case 404:
            return QR_API_ERROR_CODES.NOT_FOUND;
        case 405:
            return QR_API_ERROR_CODES.METHOD_NOT_ALLOWED;
        case 502:
            return hasLogoInRequest
                ? QR_API_ERROR_CODES.LOGO_UPSTREAM
                : bodyError || QR_API_ERROR_CODES.INTERNAL;
        case 500:
            return QR_API_ERROR_CODES.INTERNAL;
        default:
            return bodyError || mapQrHttpStatusToError(httpStatus, hasLogoInRequest);
    }
}

export function buildQrGeneratorErrorPayload(
    res: Response,
    body: { error?: string; details?: Record<string, unknown> },
    hasLogoInRequest: boolean
): QrGeneratorErrorPayload {
    const httpStatus = res.status;
    const error = resolveQrApiErrorCode(httpStatus, body.error, hasLogoInRequest);
    const payload: QrGeneratorErrorPayload = {
        error,
        httpStatus,
        details: body.details
    };
    if (body.error && body.error !== error) {
        payload.details = {
            ...(payload.details || {}),
            api_error: body.error
        };
    }
    if (error === QR_API_ERROR_CODES.RATE_LIMIT || httpStatus === 429) {
        payload.retryAfterSeconds = parseRetryAfterSeconds(res) ?? 60;
    }
    return payload;
}

/** User-facing toast copy for every Worker error code. */
export const QR_API_ERROR_MESSAGES: Record<string, string> = {
    [QR_API_ERROR_CODES.VALIDATION]:
        'Invalid QR settings (content, size, colors, or margin). Please check your settings.',
    [QR_API_ERROR_CODES.LOGO_TOO_LARGE]:
        'QR logo is too large (max 1 MB). Showing QR without logo.',
    [QR_API_ERROR_CODES.LOGO_INVALID]:
        'QR logo must be a PNG, JPEG, WebP, or GIF image (HTTPS). SVG is not supported. Showing QR without logo.',
    [QR_API_ERROR_CODES.RATE_LIMIT]:
        'Too many QR generation requests. Please wait and try again.',
    [QR_API_ERROR_CODES.LOGO_UPSTREAM]:
        'Could not load QR logo from URL. Showing QR without logo.',
    [QR_API_ERROR_CODES.INTERNAL]:
        'QR service is temporarily unavailable. Please try again later.',
    [QR_API_ERROR_CODES.NOT_FOUND]:
        'QR service endpoint was not found. Please try again or contact support.',
    [QR_API_ERROR_CODES.METHOD_NOT_ALLOWED]:
        'QR service rejected the request method. Please try again.',
};

export function qrApiErrorMessage(
    errorCode: string | undefined,
    options: { logoFallbackApplied?: boolean; details?: Record<string, unknown> } = {}
): string {
    const code = errorCode || QR_API_ERROR_CODES.INTERNAL;
    const reason = options.details?.reason;

    if (code === QR_API_ERROR_CODES.LOGO_INVALID) {
        if (reason === 'https_required') {
            return 'QR logo URL must use HTTPS. Showing QR without logo.';
        }
        if (reason === 'unsupported_format') {
            return QR_API_ERROR_MESSAGES[QR_API_ERROR_CODES.LOGO_INVALID];
        }
    }

    if (code === QR_API_ERROR_CODES.LOGO_TOO_LARGE) {
        return QR_API_ERROR_MESSAGES[QR_API_ERROR_CODES.LOGO_TOO_LARGE];
    }

    let message =
        QR_API_ERROR_MESSAGES[code] ||
        QR_API_ERROR_MESSAGES[QR_API_ERROR_CODES.INTERNAL];

    if (options.logoFallbackApplied && isQrLogoRecoverableError(code)) {
        return message;
    }
    if (isQrLogoRecoverableError(code)) {
        return (
            QR_API_ERROR_MESSAGES[code] ||
            'Could not apply QR logo. Showing QR without logo.'
        );
    }
    if (code === QR_API_ERROR_CODES.RATE_LIMIT) {
        return message;
    }
    return message;
}

/** @deprecated Use qrApiErrorMessage */
export function qrLogoErrorMessage(errorCode: string | undefined): string {
    return qrApiErrorMessage(errorCode, { logoFallbackApplied: true });
}

/** @deprecated Use QR_API_ERROR_MESSAGES */
export const QR_LOGO_ERROR_MESSAGES = QR_API_ERROR_MESSAGES;

/**
 * Worker returns image/jpeg on success; errors are JSON `{ error, details }`.
 * Coalesces concurrent calls for the same URL + logo options (see _qrGeneratorValidationInFlight).
 */
export function validateQrGeneratorUrl(
    url: string,
    options: { hasLogoInRequest?: boolean; logoUrl?: string } = {}
): Promise<QrGeneratorValidateResult> {
    const key = `${url}|${options.hasLogoInRequest ? '1' : '0'}|${options.logoUrl || ''}`;
    const pending = _qrGeneratorValidationInFlight.get(key);
    if (pending) {
        return pending;
    }
    const promise = validateQrGeneratorUrlUncached(url, options).finally(() => {
        _qrGeneratorValidationInFlight.delete(key);
    });
    _qrGeneratorValidationInFlight.set(key, promise);
    return promise;
}

async function validateQrGeneratorUrlUncached(
    url: string,
    options: { hasLogoInRequest?: boolean; logoUrl?: string } = {}
): Promise<QrGeneratorValidateResult> {
    const hasLogo = !!options.hasLogoInRequest;
    const logoUrl = options.logoUrl || (hasLogo ? extractLogoFromGeneratorUrl(url) : '');

    if (logoUrl && hasLogo) {
        const logoCheck = await validateQrLogoAsset(logoUrl);
        if (!logoCheck.ok) {
            return logoCheck;
        }
    }

    try {
        const res = await fetch(url, { method: 'GET', mode: 'cors' });
        const contentType = (res.headers.get('content-type') || '').toLowerCase();

        if (res.ok && contentType.includes('image/jpeg')) {
            return { ok: true };
        }

        const body = await readQrGeneratorErrorBody(res);
        if (!res.ok) {
            return {
                ok: false,
                ...buildQrGeneratorErrorPayload(res, body, hasLogo),
            };
        }

        if (contentType.includes('json')) {
            return {
                ok: false,
                ...buildQrGeneratorErrorPayload(res, body, hasLogo),
            };
        }

        return {
            ok: false,
            error: mapQrHttpStatusToError(res.status, hasLogo),
            httpStatus: res.status,
        };
    } catch {
        if (hasLogo) {
            return {
                ok: false,
                error: QR_API_ERROR_CODES.LOGO_UPSTREAM,
                httpStatus: 502,
                details: { field: 'logo', reason: 'generator_fetch_failed' },
            };
        }
        return {
            ok: false,
            error: QR_API_ERROR_CODES.INTERNAL,
            httpStatus: 500,
        };
    }
}

/**
 * Validate settings locally, then GET generator URL (with optional logo retry path).
 */
export async function resolveQrGeneratorUrlWithValidation(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean; forceOmitLogo?: boolean } = {}
): Promise<{
    url: string;
    validation: QrGeneratorValidateResult;
    logoFallbackApplied: boolean;
    lastError?: QrGeneratorErrorPayload;
}> {
    const logo = resolveLogoUrl(settings.logo);
    const skipLogo = options.omitLogo || options.forceOmitLogo || !logo;

    let settingsForLocal = settings;
    if (skipLogo && logo) {
        settingsForLocal = { ...settings, logo: '' };
    }

    const localCheck = validateQrSettingsInput(settingsForLocal, style);
    if (!localCheck.ok) {
        if (
            !skipLogo &&
            logo &&
            localCheck.error === QR_API_ERROR_CODES.LOGO_INVALID
        ) {
            return resolveQrGeneratorUrlWithValidation(settings, style, {
                ...options,
                forceOmitLogo: true
            }).then((retry) => ({
                ...retry,
                logoFallbackApplied: true,
                lastError: localCheck
            }));
        }
        const url = buildQrGeneratorUrl(settingsForLocal, style, { omitLogo: true });
        return { url, validation: localCheck, logoFallbackApplied: false, lastError: localCheck };
    }

    const tryWithLogo = logo && !skipLogo;

    if (tryWithLogo) {
        const withLogo = buildQrGeneratorUrl(settings, style);
        const check = await validateQrGeneratorUrl(withLogo, { hasLogoInRequest: true });
        if (check.ok) {
            return { url: withLogo, validation: check, logoFallbackApplied: false };
        }
        if (isQrLogoRecoverableError(check.error)) {
            const withoutLogo = buildQrGeneratorUrl(settings, style, { omitLogo: true });
            const retry = await validateQrGeneratorUrl(withoutLogo, { hasLogoInRequest: false });
            return {
                url: withoutLogo,
                validation: retry,
                logoFallbackApplied: true,
                lastError: check
            };
        }
        const withoutLogo = buildQrGeneratorUrl(settings, style, { omitLogo: true });
        return {
            url: withoutLogo,
            validation: check,
            logoFallbackApplied: false,
            lastError: check
        };
    }

    const url = buildQrGeneratorUrl(settings, style, { omitLogo: true });
    const check = await validateQrGeneratorUrl(url, { hasLogoInRequest: false });
    return { url, validation: check, logoFallbackApplied: false, lastError: check.ok ? undefined : check };
}

/**
 * Build GET URL for qr.ecomposer.app (JPEG). Use raw content when it contains Liquid.
 */
export function buildQrGeneratorUrl(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { rawContent?: string; omitLogo?: boolean } = {}
): string {
    const params = buildQrGeneratorApiParams(settings, style, options);
    if (!params) {
        return '';
    }
    return buildQrGeneratorUrlFromParams(params);
}

/** @deprecated Prefer buildQrApiFingerprint for change detection. */
export function buildQrcodeFingerprint(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string },
    options: { omitLogo?: boolean } = {}
): string {
    return buildQrApiFingerprint(settings, style, options);
}

/** Generator URL without logo overlay (fallback when logo params fail). */
export function buildQrGeneratorUrlWithoutLogo(
    settings: QrcodeSettingsInput,
    style?: { qr_foreground_color?: string; qr_background_color?: string }
): string {
    return buildQrGeneratorUrl(settings, style, { omitLogo: true });
}

export function resolveQrImageSrc(imageSetting: unknown): string {
    if (!imageSetting) return '';
    if (typeof imageSetting === 'string') return imageSetting;
    const obj = imageSetting as { value?: string; url?: string; src?: string };
    return obj.value || obj.url || obj.src || '';
}
