<i18n>
{
    "en": {
        "upload_font": "Upload Font",
        "upload_image": "Upload Image",
        "add_image": "Add image",
        "upload_video": "Upload Video",
        "compress": "Compress",
        "compress_image": "Compress image",
        "processing_on_shopify": "Processing on Shopify",
        "video_processing_failed": "Shopify could not process this video"
    },
    "fr": {
        "upload_font": "Télécharger la police",
        "upload_image": "Télécharger une image",
        "add_image": "Ajouter une image",
        "upload_video": "Télécharger une vidéo",
        "compress": "Compresser",
        "compress_image": "Compresser l'image"
    },
    "de": {
        "upload_font": "Schriftart hochladen",
        "upload_image": "Bild hochladen",
        "add_image": "Bild hinzufügen",
        "upload_video": "Video hochladen",
        "compress": "Komprimieren",
        "compress_image": "Bild komprimieren"
    },
    "ja": {
        "upload_font": "フォントをアップロード",
        "upload_image": "画像をアップロード",
        "add_image": "画像を追加",
        "upload_video": "ビデオをアップロード",
        "compress": "圧縮",
        "compress_image": "画像を圧縮",
        "processing_on_shopify": "Shopifyで処理中",
        "video_processing_failed": "Shopifyがこの動画を処理できませんでした"
    }
}
</i18n>
<template>
	<li v-detectVisible="detectVisible" class="relative p-4 transition cursor-pointer select-none item bg-white hover:bg-gray-50" :class="[classItem(item), item.fn == 'upload' ? 'w-full' : '', type === 'font' ? item.fn == 'upload' ? 'pb-5' : 'px-4 py-2' : '']">
		<div class="relative" :class="[layout == 'grid' ? 'pb-100p' : '', item.fn == 'upload' ? 'pb-10' : 'pb-6', item.fn == 'upload' ? isdev ? '!pb-0 h-32 flex flex-col' : '!pb-0 h-28 flex flex-col' : '']">
			<div v-if="show" class="inset-0 group" :class="item.fn == 'upload' ? 'relative flex-grow' : 'absolute'">
				<template v-if="item.fn == 'upload'">
					<span class="absolute top-0 left-0 flex gap-2 flex-col items-center justify-center w-full h-full font-medium text-gray-500 transition border border-input border-dashed rounded-md group-hover:text-primary-700 group-hover:border-primary ">
						<s-button variant="secondary">
							{{ type === 'font' ? $t('upload_font') : type === 'image' ?  $t('add_image') : $t('upload_video') }}
						</s-button>
						<span v-if="type !== 'video'" class="text-xs font-light text-text-secondary">Drag and drop images</span>
						<label v-if="item.fn == 'upload' && type === 'image'" class="absolute bottom-0 right-[13px] flex items-center my-2 z-50" @click="checkCompress" :style="isdev ? { bottom: '0px' } : {}">
							<Toggle :field="{
									label: $t('compress'),
									name: 'compress',
									type: 'toggle',
									options: {
										values: {
											on: { value: true },
											off: { value: false },
										}
									}
								}" v-model:data="_compress" class="scale-90" />
							<EcomText :as="'span'" class="ml-2 cursor-pointer text-xs">{{ $t('compress_image') }}</EcomText>
						</label>
					</span>
					<input class="absolute top-0 left-0 z-10 w-full h-full opacity-0 cursor-pointer " type="file" :accept="acceptInput" :multiple="options.multiple" @change="$emit('upload', $event)">

					<label v-if="isdev && item.fn == 'upload' && type === 'image'" class="flex items-center my-2 absolute left-1/2 -translate-x-1/2 bottom-2 z-50">
						<Toggle :field="{
								label: 'No replace',
								name: 'no_replace_image',
								type: 'toggle',
								options: {
									values: {
										on: { value: true },
										off: { value: false },
									}
								}
							}" v-model:data="_replaceImage" class="scale-90" />
						<EcomText :as="'span'" class="ml-2 cursor-pointer text-xs">No replace image</EcomText>
					</label>
				</template>
				<div v-else class="flex items-center h-full group">
					<div class="flex items-center w-full h-full" :class="{ 'opacity-30': item.loading}" @click="$emit('toggleItem',item)">
						<div v-if="type == 'font'" class="flex items-center w-full h-full rounded" :class="{ 'bg-img-default': layout == 'grid' }">
							<link rel="stylesheet" :href="fontURL(item)">
							<EcomText :size="'large'" :truncate="true" :class=" [layout == 'grid' ? 'text-center' : '', isActive(item.value) > -1 && layout != 'grid' ? 'text-primary' : 'text-gray-800 ' ]" :style="{ fontFamily:item.name }">
								{{ item.name }}
							</EcomText>
						</div>
						<div v-else-if="type == 'product_type' || type == 'product_vendor'" class="flex items-center w-full h-full rounded" :class="{ 'bg-img-default': layout == 'grid' }">
							<EcomText :size="'small'" :truncate="true" :class="{ 'text-center': layout == 'grid', 'text-xs': true }">
								{{ item.name }}
							</EcomText>
						</div>
						<template v-else>
							<template v-if="layout == 'list'">
								<span class="block w-10 h-10 p-1 mr-2" v-if="showThumb" :class="{'w-10 h-8': ['language', 'country'].includes(type)}">
									<span v-if="type === 'icon'" v-html="item.thumbnail" />
									<img v-else class="block object-cover w-full h-full rounded-sm"  :src="item.thumbnail ?? '/images/placeholder.png'" :alt="item.name">
								</span>
								<EcomText :truncate="true" :class="{'pl-2': !showThumb, 'text-xs': true}">
									{{ item.name }}
								</EcomText>
							</template>
							<div v-else class="relative flex items-center justify-center w-full h-full overflow-hidden transition duration-100 rounded bg-img-default group" :title="item.name" :class="{ 'scale-90 transform': isActive(item.value) > -1 && layout == 'grid' && type != 'image'}">
								<span v-if="type === 'icon'" class="block w-10 h-10" v-html="item.thumbnail" />
								<div v-else class="p-1 relative w-full h-full">
									<img class="w-full h-full block object-cover max-w-full max-h-full rounded group-hover:brightness-75" :class="{'h-full': !item.thumbnail, 'opacity-0': item.loading && type == 'video' }" :src="item.thumbnail ?? '/images/placeholder.png'" :alt="item.name">
									<!-- Shopify is still transcoding this file: it has no playable
									     URL yet, so say so instead of leaving a blank placeholder
									     that looks like a broken upload. -->
									<div
										v-if="item.processing || item.failed"
										class="absolute inset-1 flex flex-col items-center justify-center gap-1 rounded bg-black/60 px-2 text-center text-white"
									>
										<Loading v-if="item.processing" :size="layout === 'grid' ? 12 : 10" type="spin" />
										<EcomIcon v-else :source="icons.CircleAlertMajor" :size="'w-5'" class="flex items-center" />
										<span class="text-[10px] leading-tight">
											{{ item.processing ? $t('processing_on_shopify') : $t('video_processing_failed') }}
										</span>
									</div>
								</div>
								<p v-if="type != 'image'" class="bg-white   absolute bottom-0 left-0 w-full text-sm truncate px-2 py-0.5">
									{{ item.name }}
								</p>
							</div>
						</template>
					</div>
					<span v-if="isActive(item.value) > -1 && !['font', 'image'].includes(type)" class="absolute flex items-center justify-center w-5 h-5 p-px transition   rounded-full opacity-0 bg-primary" :class="[isActive(item.value) > -1 ? 'opacity-100' : '', layout == 'grid' ? 'right-0 bottom-0 z-10' : 'top-1/2 right-0 transform -translate-y-1/2',]">
						<EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" :color="'text-white'" class="flex items-center"></EcomIcon>
					</span>
					<div v-if="type == 'image'" class="absolute left-[11px] top-[11px]" @click="$emit('toggleItem',item)">
						<span class="w-4 h-4 border border-input rounded flex justify-center items-center bg-white peer-checked:bg-dark peer-checked:border-transparent text-transparent peer-checked:text-white">
							<EcomIcon :source="icons.TickSmallMinor" :size="'w-5'" class="w-5 h-5 flex" :class="isActive(item.value) > -1 ? 'text-icon' : 'text-transparent'"></EcomIcon>
						</span>
					</div>
					<button type="button" v-if="isActive(item.value) > -1 && type == 'font'" class="absolute right-0 inline-flex justify-center items-center font-medium smoothing h-7 text-xs px-2 ecom-save-settings gap-1 text-white bg-primary hover:bg-primary-500 focus:outline-none rounded  smoothing" @click.prevent="$emit('clickSelect')">
						Select
					</button>
					<span v-if="item.loading" class="absolute transform -translate-x-1/2 -translate-y-1/2 top-1/2 left-1/2">
						<Loading :size="layout === 'grid' ? 12 : 10" type="spin" />
						<EcomText size="'small'" class="absolute transform -translate-x-1/2 -translate-y-1/2 top-1/2 left-1/2">
							{{ item.per }}
						</EcomText>
					</span>
					<div class="absolute right-2.5 bottom-2.5 flex gap-[3px]">
						<span v-if="isActive(item.value) === -1 && (item.id + '').startsWith('gid://')" class="flex gap-[3px] items-center transition z-10" :class="[item.removing ? '' : 'opacity-0 group-hover:opacity-100', layout == 'grid' ? 'top-3 right-3' : 'top-1/2 right-10 transform -translate-y-1/2']">
							<template v-if="!item.removing">
								<EcomIcon
									v-if="type == 'image' && !item.value.includes('.svg')"
									:source="icons.MagicIcon"
									:size="'w-5'"
									class="bg-primary rounded flex text-white p-1 hover:brightness-110"
									title="Edit with AI"
									@click.stop="editWithAI(item)"
								/>
							</template>
							<Loading v-else :size="5" type="spin" class="w-full h-full text-current"></Loading>
						</span>
						<span v-if="isActive(item.value) === -1 && (item.id + '').startsWith('gid://')" class="block w-5 h-5 text-gray-500 transition z-1 group/button" :class="[item.removing ? '' : 'hover:text-red-600 opacity-0 group-hover:opacity-100', layout == 'grid' ? 'bottom-3 right-3' : 'top-1/2 right-0 transform']">
							<template v-if="!item.removing">
								<span class="bg-danger rounded flex text-white p-0.5 group-hover/button:bg-danger-700 transition-all" @click="$emit('remove', item)">
									<svg class="w-full h-full text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
										<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
											d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16">
										</path>
									</svg>
								</span>
							</template>
							<Loading v-else :size="5" type="spin" class="w-full h-full text-current"></Loading>
						</span>
					</div>
					<div v-if="show_edit" class="z-100">
						<ImageEditor
							:show="show_edit"
							:data="imageEdit(item.value)"
							@close="show_edit=false"
							@upload="upload"
						/>
					</div>
				</div>
			</div>
		</div>
	</li>
</template>

<script lang="ts">
import Toggle from '../../fields/toggle/Toggle.vue';
import { detectVisible } from '../../directives';
import { fileMixin  } from '../../mixins';
import { Popmenu  } from '@/mixins';
import ImageEditor from '@/components/atomics/ImageEditor.vue';
import { FolderUpMajor, SettingsMajor, TickSmallMinor, EditMajor, CircleAlertMajor } from "@/assets/icons";
import { MagicIcon } from "@/assets/icons/ai";
export default {
    name: 'ItemContent',
	directives: {
		detectVisible
	},
    components: {
		Toggle,ImageEditor
    },
	mixins: [ Popmenu, fileMixin ],
    props: {
        type: {
            type: String,
            default: 'menu'
        },
        value: {
            type: Array,
			default(){
				return [];
			}
        },
		compress: {
			type: Boolean,
			default: false
		},
        item: {
            type: Object,
			default(){
				return {};
			}
        },
        layout: {
            type: String,
			default: ''
        },
		options: {
			type: Object,
			default() {
                return {};
            }
		}
    },
	emits: ['update:compress', 'upload', 'remove', 'toggleItem', 'reload', 'clickSelect', 'closePopup', 'replace-image'],

    data(){
        return {
			image_edit: {
				size: {
                    width: 1000,
                    height: 1000
                },
                // mode: 'crop',
                src: ''
			},
            show: false,
			show_edit: false,
			no_replace_image: false,
            info: {},
            icons: {
				FolderUpMajor, SettingsMajor, TickSmallMinor, EditMajor, MagicIcon, CircleAlertMajor
			}
        };
    },

    computed: {
		checkPermissions() {
            const user = this.$store.getters['global/user'];
            return user?.plan_permissions?.permissions?.image_editor??false;
        },
		isdev() {
                return ['admin','manager','designer','supporter'].includes(this.$store.getters['global/user']?.roleName??'');
		},
        acceptInput(){
            if(this.type.indexOf('image') > -1){
				return '.jpg,.jpeg,.png,.gif,.webp,.svg';
			}
			if(this.type.indexOf('font') > -1){
				return '.woff,.woff2,.ttf,.otf';
			}
			if(this.type.indexOf('video') > -1){
				return '.mp4,.mov,.webm';
			}
			if(this.type.indexOf('audio') > -1){
				return 'audio/*';
			}
            return '';
        },
        hasReload() {
            return this.item.reload;
        },
		isTinify() {
            let cfg = this.$store.getters['global/configs']
			return cfg.tinify && cfg.tinify.enable;
		},
		_compress: {
			get() {
				return this.compress;
			},
			set(val : any) {
				this.$emit('update:compress', val);
			}
		},
		_replaceImage: {
			get() {
				return this.no_replace_image;
			},
			set(val : any) {
				this.$emit('replace-image', val);
			}
		},
        showThumb(){
            return this.type === 'icon' || this.layout !=='list' || ['language', 'country'].includes(this.type);
        }
    },
    watch: {
        hasReload(val) {
            if (val) {
                setTimeout(() => {
                    this.$emit('reload');
                }, 1000);
            }
        }
    },
    methods: {
		upload(e) {
			// if(e.dest) {
				this.$emit('upload', e);
				this.show_edit = false;
			// }
		},
		editWithAI(item) {
			this.$emit('toggleItem', { item: item, tab: 'ai-edit' });
		},
		imageEdit(src) {
			this.image_edit.src = src;
			return this.image_edit;
		},
		handleClickTitle(param) {
			if(param) {
				this.$emit('reload');
			}
			return;
		},
         fontURL({name, value:src}){
                return this.$helpers.getLinkFont(name, src);
        },
        isActive(value) {
			return this.value.findIndex(v => {
				v = this.type === 'image' ?
							this.currentImage(this.type, v, false) :
							v.value;
				//Upload file from edit image and selected
				if(this.type === 'image' && v && this.isURL(v)) {
					const parsedUrl1 = new URL(v), parsedUrl2 = new URL(value);

					const fileName1 = parsedUrl1.pathname.split("/").pop(),
							fileName2 = parsedUrl2.pathname.split("/").pop();
					return fileName1 === fileName2;
				}
				return v === value;
			});
        },
		isURL(data) {
			try {
				const parsedUrl = new URL(data);
				return true;
			} catch (e) {
				return false;
			}
		},
		checkCompress(e) {
			if (!this.isTinify) {
				e.preventDefault();
				window.location.hash = '#extensions/2';
				this.$emit('closePopup');
			}
		},
		classItem(item){
            // return this.layout == 'grid' ?
            //         'w-1/2 pt-0 px-1' :
            //         'py-2.5 pl-4 w-full border-b border-gray-100 bg-white ' +
            //         ((item.fn == 'item') ?
            //             'h-15' : 'h-25');
			let cl = '';
			if(this.layout == 'grid'){
				cl += ' w-1/2 pt-0 px-2 ';
			}else{
				cl += 'px-4 w-full border-b border-gray-100  bg-white  ';
				if(item.fn === 'item'){
					cl += ' py-2';
				}else{
					cl += ' py-2';
				}
				if(!item.reload){
					cl += ' cursor-pointer';
				}
			}
			if(this.type == 'image'){
				cl += ' w-1/5 ';
			}
			if(item.reload){
				cl += ' cursor-pointer';
			}
			return cl;

        },
		detectVisible(){
			this.show = true;
		}
    }
};
</script>
<style>
    .bg-img-default{
        background-position: 0 0,.6rem .6rem;
        background-size: 1.2rem 1.2rem;
        /* background-image: linear-gradient( 45deg ,#dfe3e8 25%,transparent 0,transparent 75%,#dfe3e8 0,#dfe3e8),linear-gradient( 45deg ,#dfe3e8 25%,#fff 0,#fff 75%,#dfe3e8 0,#dfe3e8); */
        box-shadow: inset 0 0 0 0 transparent, 0 0 0 1px #c4cdd5;
    }
		.dark .bg-img-default{
        box-shadow: inset 0 0 0 0 transparent, 0 0 0 1px #4c4e50;
    }
</style>
