<template>
    <div
        ref="wrapper"
        class="ecom__element element__heading ecom-element ecom-html"
        :class="[
            getType !== '' ? getType : ''
        ]"
        :data-stopdrag="isEditingThisElement ? true : null"
    >
        <Liquid :data="getMetaLiquid" />
        <component
            :is="data?.settings?.tag ?? 'h2'"
            v-if="data.settings?.link && data.settings?.link.href"
            class="ecom__heading ecom-db"
        >
            <a
                v-bind="data.settings?.link"
                ref="content"
                :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
                spellcheck="false"
                @dblclick="edit"
                @click="handleContentClick"
                @keyup="update"
                @blur="handleBlur"
                v-html="isEditingThisElement ? editingValue : exporting
                ?
                ( data.settings.enable_tooltip
                    ?
                    (data.settings.position_icon == 'before' ? tooltip + lang(convertedContent, 'heading-text', metaLang as any) : lang(convertedContent, 'heading-text', metaLang as any) + tooltip)
                    :
                    lang(convertedContent, 'heading-text', metaLang as any)

                )
                : content"
            />
        </component>
        <component
            :is="data?.settings?.tag ?? 'h2'"
            v-else
            ref="content"
            class="ecom__heading ecom-db"
             :contenteditable="!isFullScreen && isEditingThisElement ? true : null"
            spellcheck="false"
            @dblclick="edit"
            @click="handleContentClick"
            @keyup="update"
            @blur="handleBlur"
            v-html="isEditingThisElement ? editingValue : exporting
            ?
            ( data.settings.enable_tooltip
                ?
                (data.settings.position_icon == 'before' ? tooltip + lang(convertedContent, 'heading-text', metaLang as any) : lang(convertedContent, 'heading-text', metaLang as any) + tooltip)
                :
                lang(convertedContent, 'heading-text', metaLang as any)

            )
            : content"
        />
    </div>
</template>

<script lang="ts">
    import { Element, Javascript, Liquid } from '@/mixins';
    import { placeCaretAtEnd, resolveMetaEdgeCaret, applyCaretRange } from '@/utils/contentEditable';
    export default {
        name: 'Heading',
        presets:true,
        docs: 'https://help.ecomposer.io/docs/elements/basic-elements/heading/',
        mixins: [Element, Javascript, Liquid],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        data () {
            return {
                wrapper: null as HTMLElement | null,
                editing: false,
                is: 'heading',
                editingValue: '',
                metaLang: {} as Record<string, string>,
                metaLiquid: '',
                lastUpdate: 0,
                convertedContent: '',
                convertedTooltip: '',
                isBlur: false,
                isTyping: false
            };
        },
        computed: {
            getColor() {
                return this.data?.style?.text?.textTextShadow["text-shadow"];
            },
            getType() {
                return this.data?.style?.text?.textTextShadow?.type ? 'ecom-type-' + this.data?.style?.text?.textTextShadow?.type : 'ecom-type-deffault';
            },
            isContentEditable() {
                return this.$store.getters["builder/isContentEditable"];
            },
            editingElementId() {
                return this.$store.getters["builder/editingElementId"];
            },
            isEditingThisElement() {
                return this.editingElementId === this.heading.id && this.isContentEditable;
            },
            tooltip(){
                let icon_tooltip = this.data.settings?.icon_tooltip,
                    // Export: dùng bản đã đổi chip thành `{{key}}` (xem convertMetaNodes).
                    // Builder giữ nguyên chip để user còn thấy và bấm vào được.
                    content_tooltip = this.exporting
                        ? this.convertedTooltip
                        : this.data.settings?.content_tooltip,
                    enable_arrow = this.data.settings?.enable_arrow,
                    position_tooltip = this.data.settings?.position_tooltip,
                    position_tooltip__tablet = this.data.settings?.position_tooltip__tablet,
                    position_tooltip__mobile = this.data.settings?.position_tooltip__mobile
                    ;
                if(!icon_tooltip && !content_tooltip) return "";
                return `<div class="el__heading--tooltip-wrapper">
                                        ${icon_tooltip ? icon_tooltip.value : ''}
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-desktop el__heading--tooltip-${position_tooltip ? position_tooltip : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-tablet el__heading--tooltip-${position_tooltip__tablet ? position_tooltip__tablet : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-mobile el__heading--tooltip-${position_tooltip__mobile ? position_tooltip__mobile : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                    </div>`
            },
            content(){
                let contentHtml = this.data.settings?.content;
                let enable_tooltip = this.data.settings?.enable_tooltip,
                    icon_tooltip = this.data.settings?.icon_tooltip,
                    content_tooltip = this.data.settings?.content_tooltip,
                    position_tooltip = this.data.settings?.position_tooltip,
                    position_tooltip__tablet = this.data.settings?.position_tooltip__tablet,
                    position_tooltip__mobile = this.data.settings?.position_tooltip__mobile,
                    enable_arrow = this.data.settings?.enable_arrow,
                    position_icon = this.data.settings?.position_icon;
                if(enable_tooltip==true && icon_tooltip && content_tooltip){
                    if(position_icon == 'before'){
                        contentHtml = `<div class="el__heading--tooltip-wrapper">
                                        ${icon_tooltip.value}
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-desktop el__heading--tooltip-${position_tooltip ? position_tooltip : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-tablet el__heading--tooltip-${position_tooltip__tablet ? position_tooltip__tablet : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-mobile el__heading--tooltip-${position_tooltip__mobile ? position_tooltip__mobile : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                    </div>` + contentHtml;
                    }
                    else{
                        contentHtml += `<div class="el__heading--tooltip-wrapper">
                                        ${icon_tooltip.value}
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-desktop el__heading--tooltip-${position_tooltip ? position_tooltip : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-tablet el__heading--tooltip-${position_tooltip__tablet ? position_tooltip__tablet : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                        <div class="el__heading--tooltip-content ${enable_arrow==true ? 'tooltip__arrow' : ''} el__tooltip-mobile el__heading--tooltip-${position_tooltip__mobile ? position_tooltip__mobile : 'bottom'}">
                                            ${content_tooltip}
                                        </div>
                                    </div>`
                    }
                }
                return contentHtml;
            },
            settings () {
                return [
                    {
                        params: [
                            {
                                type: 'textarea',
                                label: this.$t('heading_text'),
                                name: 'content',
                                options: {
                                    toolbar: 'short',
                                    dynamic: true,
                                    height: 80
                                }
                            },

                            {
                                type: 'link',
                                label: this.$t('insert_link'),
                                name: 'link'
                            },
                            {
                                type: 'choose',
                                label: this.$t('span_class_uppercase_html_span_tag'),
                                name: 'tag',
                                options: {
                                    chooseOne:true,
                                    type: 'heading'
                                }
                            },
                            {
                                type: 'switch',
                                name: 'enable_tooltip',
                                label: this.$t('use_tooltip'),
                                value: false,
                                options: {
                                    values: {
                                        on: {
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    }
                                }
                            },
                            {
                                type: 'textarea',
                                name: 'content_tooltip',
                                label: this.$t('tooltip_content'),
                                options: {
                                    visible: (data: any) => {
                                        return data['enable_tooltip'] === true;
                                    },
                                    toolbar: 'short',
                                    dynamic: true,
                                    height: 80

                                }
                            },
                            {
                                type: 'switch',
                                name: 'enable_arrow',
                                label: this.$t('use_arrow'),
                                value: false,
                                options: {
                                    values: {
                                        on: {
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    },
                                    visible: (data: any) => {
                                            return data['enable_tooltip'] === true;
                                    }
                                }
                            },
                            {
                                type: 'picker',
                                label: this.$t('tooltip_icon'),
                                name: 'icon_tooltip',
                                options: {
                                    type: 'icon',
                                    multiple: false,
                                    oneline: true,
                                    visible: (data: any) => {
                                            return data['enable_tooltip'] === true;
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                name: 'position_icon',
                                label: this.$t('icon_position'),
                                options: {
                                    visible: (data: any) => {
                                            return data['enable_tooltip'] === true;
                                    },
                                    type: 'dropdown',
                                    default: false,
                                    preview: 'title',
                                    values: {
                                        before: this.$t('before_the_heading'),
                                        after: this.$t('after_the_heading'),
                                    }
                                }
                            },
                            {
                                type: 'popup',
                                name: 'position_tooltip',
                                label: this.$t('tooltip_position'),
                                options: {
                                    visible: (data: any) => {
                                            return data['enable_tooltip'] === true;
                                    },
                                    type: 'dropdown',
                                    default: false,
                                    preview: 'title',
                                    responsive: true,
                                    values: {
                                        top: this.$t('top'),
                                        bottom: this.$t('bottom'),
                                        left: this.$t('left'),
                                        right: this.$t('right'),
                                    }
                                }
                            }
                        ]
                    }
                ];
            },
            css(){
                return `
                    .el__heading--tooltip-wrapper{
                        position: relative;
                        display: inline-block;
                    }
                    .el__heading--tooltip-wrapper svg{
                        width: 18px;
                        cursor: pointer;
                    }
                    .el__heading--tooltip-content{
                        line-height: 16px;
                        max-width: 200px;
                        position: absolute;
                        display: block;
                        width: max-content;
                        opacity: 0;
                        padding: 5px;
                        visibility: hidden;
                        font-size: 14px;
                        background-color: #545454;
                        color: #ffffff;
                        border-radius: 5px;
                        transition: .5s ease all;
                        z-index: 999;
                    }
                    .el__heading--tooltip-content.el__tooltip-tablet, .el__heading--tooltip-content.el__tooltip-mobile {
                        display: none;
                    }
                    .el__heading--tooltip-bottom{
                        left: 50%;
                        transform: translate(-50%, 10px);
                    }

                    .el__heading--tooltip-left{
                        transform: translate(-20px, -50%);
                        right: 100%;
                        top: 50%;
                    }
                    .el__heading--tooltip-top{
                        left: 50%;
                        bottom: 100%;
                        transform: translate(-50%, -10px);
                    }
                    .el__heading--tooltip-right {
                        top: 50%;
                        left: 100%;
                        transform: translate(20px, -50%);
                    }
                    .tooltip__arrow:before{
                        position: absolute;
                        content: '';
                        width: 8px;
                        height: 8px;
                        background: inherit;
                        z-index: -1;
                    }
                    .tooltip__arrow.el__heading--tooltip-bottom:before{
                        top: 0;
                        transform: translate(-50%, -50%) rotate(45deg);
                        left: 50%;
                    }
                    .tooltip__arrow.el__heading--tooltip-top:before{
                        transform: translate(-50%,50%) rotate(45deg);
                        bottom: 0%;
                        left: 50%;
                    }
                    .tooltip__arrow.el__heading--tooltip-right:before{
                        transform: translate(-50%,50%) rotate(45deg);
                        bottom: 50%;
                        left: 0%;
                    }
                    .tooltip__arrow.el__heading--tooltip-left:before{
                        transform: translate(50%,50%) rotate(45deg);
                        bottom: 50%;
                        right: 0%;
                    }
                    .el__heading--tooltip-wrapper svg:hover~.el__heading--tooltip-bottom, .el__heading--tooltip-wrapper svg:hover~.el__heading--tooltip-top {
                        opacity: 1;
                        visibility: visible;
                        transform: translate(-50%, 0);
                    }
                    .el__heading--tooltip-wrapper svg:hover~.el__heading--tooltip-left {
                        opacity: 1;
                        visibility: visible;
                        transform: translate(-15px, -50%);
                    }
                    .el__heading--tooltip-wrapper svg:hover~.el__heading--tooltip-right {
                        opacity: 1;
                        visibility: visible;
                        transform: translate(15px, -50%);
                    }
                    .ecom-type-hollow .ecom__heading {
                        text-shadow: var(--stroke) !important;
                        background: transparent !important;
                        -webkit-background-clip: unset !important;
                        -webkit-text-fill-color: unset !important;
                    }
                    .ecom-type-text_3d .ecom__heading {
                        text-shadow: var(--text_3d) !important;
                    }
                    .ecom-type-gradient .ecom__heading {
                        animation: var(--animation);
                    }
                    @keyframes gradientMove {
                        0% { background-position: 100% 100%; }
                        100% { background-position: 0% 0%; }
                    }
                    @media screen and (max-width: 1024px) {
                        .el__heading--tooltip-content.el__tooltip-desktop {
                            display: none;
                        }
                        .el__heading--tooltip-content.el__tooltip-tablet {
                            display: block;
                        }
                    }
                    @media screen and (max-width: 767px) {
                        .el__heading--tooltip-content.el__tooltip-tablet {
                            display: none;
                        }
                        .el__heading--tooltip-content.el__tooltip-mobile {
                            display: block;
                        }
                    }
                `;
            },

            heading () {
                return this.data;
            },
            checkTooltip() {
                return this.data.settings.enable_tooltip;
            },
            activeMe () {
                return (this.editingElement?.data?.id ?? 0) === this.heading.id;
            },
            getMetaLiquid() {
                return this.metaLiquid;
            },
            default() {
                return  {
                    "settings": {
                        "enable_tooltip": false,
                        "content": "Enter your heading",
                        "tag": "h3",
                        "icon_width": "30px",
                        "content_tooltip": "Tooltip",
                        "icon_tooltip": {
                            "id": "qSmBN5zG",
                            "name": "circle-question",
                            "cate": "Duotone",
                            "url": "https://local.ecomposer.app/storage/icons/font-awesome/duotone/circle-question.svg",
                            "value": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" fill=\"currentColor\"><!--! Font Awesome Pro 6.1.1 by @fontawesome - https://fontawesome.com License - https://fontawesome.com/license (Commercial License) Copyright 2022 Fonticons, Inc. --><defs><style>.fa-secondary{opacity:.4}</style></defs><path class=\"fa-primary\" d=\"M256 336c-18 0-32 14-32 32c0 18 13.1 32 32 32c17.1 0 32-13.1 32-32C288 350 273.1 336 256 336zM289.1 128h-51.1C198.1 128 168 158.1 168 198c0 12.1 11 24 24 24s24-11 24-24C216 186 225.1 176 237.1 176h51.1C301.1 176 312 186 312 198c0 8-4 14.1-11 18.1L244 251C236 256 232 264 232 272V288c0 13 11 24 24 24S280 301 280 288V286l45.1-28c21-13 34-36 34-60C360 158.1 328.1 128 289.1 128z\"></path><path class=\"fa-secondary\" d=\"M256 0C114.6 0 0 114.6 0 256s114.6 256 256 256s256-114.6 256-256S397.4 0 256 0zM256 400c-18 0-32-14-32-32s13.1-32 32-32c17.1 0 32 14 32 32S273.1 400 256 400zM325.1 258L280 286V288c0 13-11 24-24 24S232 301 232 288V272c0-8 4-16 12-21l57-34C308 213 312 206 312 198C312 186 301.1 176 289.1 176h-51.1C225.1 176 216 186 216 198c0 13-11 24-24 24s-24-11-24-24C168 159 199 128 237.1 128h51.1C329 128 360 159 360 198C360 222 347 245 325.1 258z\"></path></svg>",
                            "thumbnail": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" fill=\"currentColor\"><!--! Font Awesome Pro 6.1.1 by @fontawesome - https://fontawesome.com License - https://fontawesome.com/license (Commercial License) Copyright 2022 Fonticons, Inc. --><defs><style>.fa-secondary{opacity:.4}</style></defs><path class=\"fa-primary\" d=\"M256 336c-18 0-32 14-32 32c0 18 13.1 32 32 32c17.1 0 32-13.1 32-32C288 350 273.1 336 256 336zM289.1 128h-51.1C198.1 128 168 158.1 168 198c0 12.1 11 24 24 24s24-11 24-24C216 186 225.1 176 237.1 176h51.1C301.1 176 312 186 312 198c0 8-4 14.1-11 18.1L244 251C236 256 232 264 232 272V288c0 13 11 24 24 24S280 301 280 288V286l45.1-28c21-13 34-36 34-60C360 158.1 328.1 128 289.1 128z\"></path><path class=\"fa-secondary\" d=\"M256 0C114.6 0 0 114.6 0 256s114.6 256 256 256s256-114.6 256-256S397.4 0 256 0zM256 400c-18 0-32-14-32-32s13.1-32 32-32c17.1 0 32 14 32 32S273.1 400 256 400zM325.1 258L280 286V288c0 13-11 24-24 24S232 301 232 288V272c0-8 4-16 12-21l57-34C308 213 312 206 312 198C312 186 301.1 176 289.1 176h-51.1C225.1 176 216 186 216 198c0 13-11 24-24 24s-24-11-24-24C168 159 199 128 237.1 128h51.1C329 128 360 159 360 198C360 222 347 245 325.1 258z\"></path></svg>"
                        },
                        "position_icon": "after",
                        "position_tooltip": "bottom",
                        "position_tooltip__tablet": "bottom",
                        "position_tooltip__mobile": "bottom"
                    },
                    "style": {
                        // "text": {
                        //     "textTextAlign": "left",
                        //     "textColor": "#000000",
                        //     "textTypography": {
                        //         "font-weight": "500",
                        //         "font-size": "30px"
                        //     },
                        // },
                        "tooltip": {
                            "textColor": "#ffffff",
                            "background_color": "#545454",
                            "textTypography": {
                                "font-size": "14px",
                                "line-height": "16px",
                                "font-style": "normal",
                                "text-transform": "none"
                            },
                            "borderRadius": {
                                "right": "5px",
                                "top": "5px",
                                "left": "5px",
                                "bottom": "5px"
                            }
                        },
                        // "heading": {
                        //     "textTypography": {
                        //         "font-size": "24px"
                        //     }
                        // },
                        "icon_tooltip": {
                            "iconFontSize": "18px"
                        }
                    }
                }
            }
        },
        watch: {
            activeMe (val) {
                if (!val && this.isContentEditable) {
                    this.$store.commit("builder/setIsContentEditable", false);
                    this.$store.commit("builder/setEditingElementId", "");

                    const content = this.$refs.content as HTMLElement;
                    if(content.innerText.includes('figmeta') || content.innerHTML.includes('figmeta')) {
                        this.heading.settings.content = content.innerText;
                    } else {
                        this.heading.settings.content = content.innerHTML;
                    }
                }
                if (val) {
                    this.$store.commit("builder/setEditingElementId", this.heading.id);
                }
            },
            checkTooltip(val) {
                this.handleZindex(this.wrapper,val);
            },
            'data.settings.content': {
                handler(newVal) {
                    this.processContent();
                    if (!this.isEditingThisElement || (!this.isTyping && newVal !== this.editingValue)) {
                        this.editingValue = newVal;
                    }
                },
                immediate: true
            },
            // Tooltip cũng chèn được dynamic source → đổi nội dung phải parse lại,
            // watcher của `content` không bao được path này.
            'data.settings.content_tooltip'() {
                this.processContent();
            },
            isContentEditable() {
                this.isBlur = false;
            },
            isEditingThisElement(val) {
                if(val) {
                    this.editingValue = this.data.settings.content;
                    this.processContent();
                    this.focusContentEditor();
                }
            }
        },
        created() {
            setTimeout(()=>{
                this.wrapper = this.$refs.wrapper as HTMLElement;
                this.handleZindex(this.wrapper,this.data.settings.enable_tooltip);

            },1000);
        },
        methods: {
            handleBlur() {
                // setTimeout(() => {
                //     this.$refs.content.focus();
                // }, 50);
                if(!this.isBlur) return;
                setTimeout(() => {
                    this.$store.commit("builder/setIsContentEditable", false);
                }, 200);
            },
            style () {
                let style: any[] = [
                    {
                        group_alias:'text',
                        options: {
                            group_title: this.$t('text'),
                            selector: ' .element__heading .ecom__heading'
                        },
                        modify: {
                            remove: {
                                index: 2, length: 1
                            },
                            params: [
                                {
                                    position: 3,
                                    fields: {
                                    name: 'textColor',
                                    label: this.$t('text_color'),
                                    type: 'color',
                                    options: {
                                        oneline: true,
                                        global: {
                                            type: 'colors'
                                        }
                                    },
                                    css: {
                                        properties: {
                                            'color': ''
                                        },
                                        selector: 'root  .element__heading .ecom__heading,root  .element__heading .ecom__heading a'
                                    }
                                },
                                },
                                {
                                    position: 5,
                                    fields: {
                                        alias: 'border',
                                        options: {
                                            label: this.$t('border')
                                        }
                                    }
                                },
                                {
                                    position: 10,
                                    fields: {
                                        alias: 'spacing',
                                        options: {
                                            label: this.$t('spacing')
                                        }
                                    }
                                }
                            ]
                        }
                    },
                ];
                let styleTooltip: any[] = [
                {
                        group_alias:'text',
                        options: {
                            group_title: this.$t('tooltip'),
                            group_name: 'tooltip',
                            selector: ' .el__heading--tooltip-content'
                        },
                        modify: {
                            remove:
                                {
                                    index: [0,3], length: 1
                                },
                            params: [
                                {
                                    position: 3,
                                    fields: {
                                        name: 'background_color',
                                        label: this.$t('background_color'),
                                        type: 'color',
                                        options: {
                                            oneline: true,
                                            global: {
                                                type: 'colors'
                                            }
                                        },
                                        css: {
                                            properties: {
                                                'background-color': ''
                                            },
                                            selector: 'root  .el__heading--tooltip-content'
                                        }
                                    },
                                },
                                {
                                    position: 8,
                                    fields: {
                                        type: 'dimension',
                                        name: 'borderRadius',
                                        label: this.$t('border_radius'),
                                        options: {
                                            type: 'radius',
                                            units: 'default',
                                        },
                                        css:{
                                            properties:{
                                                'border-radius':''
                                            }
                                        }
                                    }
                                },
                                {
                                    position: 10,
                                    fields: {
                                        alias: 'spacing',
                                        options: {
                                            label: this.$t('spacing'),
                                        }
                                    }
                                }
                            ]
                        }
                    },
                    {
                        group_alias:'icon',
                        options: {
                            group_title: this.$t('tooltip_icon'),
                            group_name: 'icon_tooltip',
                            selector: ' .el__heading--tooltip-wrapper'
                        },
                        modify: {

                        }
                    }
                ];
                if(this.data.settings?.enable_tooltip){
                    style = style.concat(styleTooltip);
                }
                return style;
            },
            /** Đổi chip dynamic source thành `{{key}}` và dồn `{%- assign -%}` vào `acc`.
             *  Tách riêng để dùng cho CẢ `content` lẫn `content_tooltip`: field tooltip cũng
             *  bật `dynamic: true` nên chip chèn vào đó phải sinh liquid — trước đây chỉ
             *  `content` được parse, chip trong tooltip export ra span rỗng (builder vẫn
             *  hiện chip nên lỗi chỉ lộ sau khi publish).
             *  Ghi vào `acc` (biến local của caller) chứ không ghi thẳng vào state: `+=`
             *  vào `this.metaLiquid` là một lần ghi reactive cho MỖI chip. */
            convertMetaNodes(text: string | undefined, acc: { liquid: string; lang: Record<string, string> }): string {
                if(!text) return '';
                // Không có chip → khỏi createElement + parse innerHTML. Đây là đường nóng:
                // update() gọi processContent mỗi lần gõ, mà đa số heading không dùng
                // dynamic source (và tooltip mặc định chỉ là chữ "Tooltip").
                if(text.indexOf('data-meta') === -1) return text;

                const dom = document.createElement('div');
                dom.innerHTML = text;

                dom.querySelectorAll('span[data-meta]').forEach((el) => {
                    const rawKey = (el as HTMLElement).dataset.metaKey || '';
                    const meta_key = rawKey.replace(/[^a-zA-Z0-9_]/g, '_').replace(/^[0-9]/, '_$&') || 'meta';
                    const metafield = (el as HTMLElement).dataset.meta || '';
                    const metaAssign = (el as HTMLElement).dataset.metaAssign;

                    acc.liquid += metaAssign || `{%- assign ${meta_key} = ${metafield}-%}`;
                    acc.lang[meta_key] = meta_key;

                    el.replaceWith(document.createTextNode(`{{${meta_key}}}`));
                });

                return dom.innerHTML;
            },
            processContent() {
                const acc = { liquid: '', lang: {} as Record<string, string> };

                // Gán thẳng kết quả mới thay vì reset rồi mới parse: bản cũ return sớm khi
                // content rỗng nên xoá hết chữ xong vẫn còn assign + HTML của lần trước.
                this.convertedContent = this.convertMetaNodes(this.data.settings?.content, acc);
                this.convertedTooltip = this.convertMetaNodes(this.data.settings?.content_tooltip, acc);

                // Chỉ ghi khi thật sự đổi — gõ 1 chữ mà gán lại object/string y hệt là
                // ép các consumer (template ở nhánh export) re-render vô ích.
                if(this.metaLiquid !== acc.liquid) {
                    this.metaLiquid = acc.liquid;
                }
                if(Object.keys(acc.lang).length || Object.keys(this.metaLang).length) {
                    this.metaLang = acc.lang;
                }
            },
            handleZindex(element: HTMLElement | null, check: boolean) {
                // if(!element) return;
                // const block = element.closest('.ecom-block');
                // check && block ? block.style.zIndex = 2 : block.style.zIndex = 1;
            },
            edit() {
                this.$store.commit("builder/setIsContentEditable", true);
            },
            /** Dynamic source tag là contenteditable="false"; khi nó nằm cuối nội dung thì
             *  bấm vào vùng trống phía sau không ra con trỏ, không gõ thêm được.
             *  Chỉ can thiệp lúc đang inline-edit, còn lại để builder xử lý click như cũ. */
            handleContentClick(e: MouseEvent) {
                if (!this.isEditingThisElement) return;
                const el = this.$refs.content as HTMLElement | undefined;
                const range = resolveMetaEdgeCaret(el, e, this.idoc());
                applyCaretRange(range, this.idoc());
            },
            focusContentEditor() {
                this.$nextTick(() => {
                    const el = this.$refs.content as HTMLElement | undefined;
                    if (!el || !this.isEditingThisElement) return;
                    placeCaretAtEnd(el, this.idoc());
                });
            },
            update(e: Event) {
                const now = Date.now();
                if (now - this.lastUpdate > 300) {
                    const target = (e.target as HTMLElement);
                    const newContent = target.innerText.includes('figmeta') || target.innerHTML.includes('figmeta')
                        ? target.innerText
                        : target.innerHTML;

                    if (this.heading.settings.content !== newContent) {
                        this.isTyping = true;
                        this.heading.settings.content = newContent;
                        this.lastUpdate = now;
                        this.$nextTick(() => {
                            this.processContent();
                            this.isTyping = false;
                        });
                    }
                }
            }
        },

    };
</script>