<template>
    <div class="color-panel inline-block bg-white rounded-xl 3xl:w-[267px] w-[270px] ec-shadow-popup-3 border border-popup">
        <!-- <svg
            viewBox="0 0 213.3 213.3"
            class="absolute w-4 h-4 -mt-3 transform fill-current text-white"
            :class="[!posArrow ? 'mr-1 left-3' : '-translate-x-1/2', showColorPopupAtBottom ? 'top-0 rotate-180' : '-bottom-[11px] rotate-0']"
            :style="posArrow ? {left: posArrow} : null"
        >
            <polygon
                class="shadow-xxl"
                points="0,53.333 106.667,160 213.333,53.333"
            />
        </svg> -->
        <Tabs
            v-if="global && global.type"
            :title="$t('color_picker')"
            :tabs="['customize', 'global']"
            :has-delete="hasDelete"
            :value="value"
            :type="global?.type"
            :selected="globalSelected"
            :idTeleport="idTeleport"
            @addglobal="addNewGlobalColor"
            @update:delete="$emit('update:delete')"
            @refesh="$emit('refeshColor')"
            @selectedTab="$emit('selectedTab', $event)"
        >
            <template #global>
                <GlobalColor :data="globalSelected" @update="(value,key)=>$emit('update:global-selected', key)" />
            </template>
            <template #customize>
                <Solid :data="value" @update="$emit('update:value', $event)" />
            </template>
        </Tabs>
        <div v-else>
            <div
                class="flex items-center justify-between px-4 py mb-2 border-b  "
            >
                <span class="text-sm font-medium text-gray-600  truncate w-full">{{ field?.label ? field?.label : $t('color_picker') }}</span>
                <span class="flex items-center py-1.5">
                    <button
                        class="p-2 transition rounded text-gray-600 hover:bg-gray-200 hover:text-gray-500  "
                        :data-tooltip="$t('reset_to_default')"
                        data-tooltip-location="bottom"
                        type="button"
                        @click="$emit('refeshColor')"
                    >
                        <EcomIcon :source="icons.ecRefresh" :size="'w-5'"  class="text-gray-500  flex items-center"></EcomIcon>
                    </button>
                </span>
            </div>
            <div class="mt-1.5 px-3.5 py-3">
                <Solid :data="value" @update="$emit('update:value', $event)" />
            </div>
        </div>
    </div>
</template>

<script lang="ts">

    import Tabs from '../Tabs/Tabs.vue';
    import Global from '../GlobalPanel/GlobalPanel.vue';
    import ColorPicker from './ColorPicker.vue';
    import {ecRefresh} from '@/assets/icons';
    import Solid from '@/components/Builder/Components/Utils/TextEditorBar/Color/SolidColor.vue';
    import GlobalColor from '@/components/Builder/Components/Utils/TextEditorBar/Color/GlobalColor.vue';
    export default {
        name: 'ColorComponent',
        components: {
            Tabs,
            Global,
            ColorPicker,
            Solid,
            GlobalColor
        },
        props: {
            value: {
                type: String,
                default: ''
            },
            field: {
                type: Object,
                default() {
                    return {};
                }
            },
            globalSelected: {
                type: String,
                default: ''
            },
            global: {
                type: Object,
                default() {
                    return {};
                }
            },
            posArrow: {
                type: String,
                default: ''
            },
            hasDelete: {
                type: Boolean,
                default: false
            },
            showColorPopupAtBottom: {
                type: Boolean,
                default: true
            },
            idTeleport: {
                type: String,
                default: ''
            }
        },
        data(){
            return {
                icons: {
                    ecRefresh,
                }
            }
        },
        emits: ['refeshColor', 'update:value', 'update:global-selected', 'update:delete', 'selectedTab'],
        methods: {
            addNewGlobalColor(title) {
                let key = this.$helpers.makeId(8);
                this.$store.dispatch('settings/addDataGlobal', {
                    key,
                    type: this.global?.type,
                    data: {
                        title: title,
                        value: this.$helpers.copy(this.value)
                    }
                });
                this.$emit('update:global-selected', key);
                this.$store.commit('global/setToast', {
                    message: this.$t('add_global')+' ' +
                            (this.global?.type === 'colors' ? this.$t('color') : this.$t('font')) +
                            ' '+this.$t('success'),
                    duration: 4000
                },{ root: true });
            },
        }
    };
</script>

