<template>
  <div class="tab">
        <div class="flex items-center justify-between pl-4 pr-2 py-2 mb-2 h-9 bg-surface-tertiary rounded-t-xl relative">
            <div v-show="!showInput" class="flex items-center justify-between w-full">
                <span class="text-xs font-[550] text-text-primary capitalize ">{{ title }}</span>
                <span class="flex items-center">
                    <button
                        v-if="!hasDelete"
                        type="button"
                        class="h-6 px-1 transition rounded text-gray-500 hover:bg-gray-200   "
                        :disabled="check"
                        :data-tooltip="$t('reset_to_default')"
                        data-tooltip-location="top-right"
                        @click="$emit('refesh')"
                    >
                        <EcomIcon :source="icons.resetIcon" :size="'w-5'" class="flex items-center justify-center"></EcomIcon>
                    </button>

                    <button
                        v-if="tabSelected !== 'global'"
                        type="button"
                        :data-tooltip="$t('add_new_global')"
                        data-tooltip-location="top-right"
                        class="h-6 w-7 flex items-center justify-center px-1 transition rounded text-gray-500 hover:bg-gray-200   "
                        :class="{'opacity-50 pointer-events-none': check}"
                        @click="changeShowInput"
                    >
                        <EcomIcon :source="icons.CirclePlusMajor" :size="'w-3.5'" class="icon-scale flex items-center justify-center"></EcomIcon>
                    </button><template v-else />
                    <button
                        v-if="hasDelete && tabSelected !== 'global'"
                        type="button"
                        :data-tooltip="$t('delete_item')"
                        data-tooltip-location="top-right"
                        class="h-6 px-1 transition rounded text-gray-500 hover:bg-gray-200 hover:text-primary   "
                        @click="handelDelete"
                    >
                        <EcomIcon :source="icons.DeleteMinor" :size="'w-5'" class="flex items-center justify-center"></EcomIcon>
                    </button><template v-else />
                    <button
                        v-if="tabSelected == 'global'"
                        type="button"
                        class="h-6 px-1 transition rounded  text-gray-500 hover:bg-gray-200 hover:text-primary "
                        :data-tooltip="$t('manage_global_settings')"
                        data-tooltip-location="top-right"
                        @click="openSiteSettings"
                    >
                        <EcomIcon :source="icons.SettingsMajor" :size="'w-5'" class="flex items-center justify-center"></EcomIcon>
                    </button>
                </span>
            </div>
            <div :class="showInput ? 'flex' : 'hidden'" class=" w-full h-13 absolute inset-0">
                <input
                    v-model="valueInput"
                    type="text"
                    class="w-full pl-2 transition outline-none shadow-sm h-9 text-xs text-text-primary rounded-tl-7"
                    :placeholder="$t('new_item')"
                    @keypress.enter="updateValue"
                    @keypress.esc="showInput = false"
                >
                <button type="button" class="inline-flex h-9 items-center px-2 rounded-tr-7 text-gray-500 transition cursor-pointer w-9 hover:bg-gray-200     ">
                    <EcomIcon v-if="valueInput.trim() != ''" :source="icons.MobileAcceptMajor" :size="'w-5'" @click="updateValue" class="flex items-center text-gray-500"></EcomIcon>
                    <EcomIcon v-else :source="icons.MobileCancelMajor" :size="'w-5'" @click="updateValue" class="flex items-center text-gray-500"></EcomIcon>
                </button>
            </div>
        </div>
        <div class="tab__heading border-gray-250-input">
            <ul class="flex bg-surface-tertiary p-1 rounded-lg mt-3.5 mx-3">
                <li
                    v-for="(tab, i) in tabs"
                    :key="i"
                    class="flex-1 min-w-0 ecom-item-tab-hover rounded"
                    :class="tabSelected === tab ? 'bg-white' : 'bg-transparent'"
                >
                    <button
                        type="button"
                        class="flex h-6 w-full items-center justify-center whitespace-nowrap text-center align-middle px-1 text-xs font-medium leading-5 text-text-primary"
                        :class="tabSelected === tab ? 'rounded bg-white shadow-[0px_8px_20px_-4px_#1718181F,0px_3px_6px_-3px_#17181814]': 'hover:text-primary-700 transition-all'"
                        @click="setTabSelected(tab)"
                    >
                        {{ $t(``+tab) }}
                    </button>
                </li>
            </ul>
        </div>
        <div
            class="mt-1.5 px-3.5 py-3"
            >
            <div
                v-for="(tab, i) in tabs"
                :key="i"
            >
                <slot v-if="tabSelected === tab" :name="tab" />
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import {resetIcon, CirclePlusMajor, SettingsMajor, MobileAcceptMajor, MobileCancelMajor, DeleteMinor} from '@/assets/icons';
import InstanceStore from '@/utils/instance-store';
export default {
    name:'SubcomponentTabs',

    props:{
        tabs:{
            type:Array,
            default() {
                return [];
            }
        },
        title:{
            type:String,
            default:''
        },
        type:{
            type:String,
            default:''
        },
        // eslint-disable-next-line vue/require-default-prop
        value:[String,Object],
        selected:{
            type:String,
            default:''
        },
        hasDelete: {
            type: Boolean,
            default: false
        },
        idTeleport: {
            type: String,
            default: ''
        }
    },
    emits:['refesh','addglobal','activecolor', 'update:delete', 'selectedTab'],
    data(){
        return{
            showInput: false,
            valueInput: '',
            tabSelected:this.selected ? this.tabs[1] : this.tabs[0],
            icons: {
                resetIcon,
                CirclePlusMajor,
                SettingsMajor,
                MobileAcceptMajor,
                MobileCancelMajor,
                DeleteMinor
            }
        };
    },
    computed:{
        isPopupOpen() {
            return this.$store.getters["builder/isPopupOpen"];
        },
        check(){
            if(this.value){
                return typeof(this.value) == 'string' ? !this.value : !Object.keys(this.value).length;
            }else{
                return true;
            }
        },
        /** Maps `global.type` from Color/Popup (colors | typography) → siteStyleParams group_name */
        siteSettingsOpenGroupName() {
            const raw = String(this.type || '').trim().toLowerCase();
            if (raw === 'colors' || raw === 'color') return 'global-colors';
            if (raw === 'typography') return 'global-typography';
            if (raw.startsWith('global-')) return raw;
            return raw ? `global-${raw}` : 'global-typography';
        }
    },
    methods:{
        setTabSelected(tab){
            this.tabSelected = tab;
            this.$emit('selectedTab', this.tabSelected);
        },
        openSiteSettings() {
            this.$store.commit("builder/setIsPopupOpen", false);
            // Same entry as sidebar "Site settings" (Paint brush tab), not the gear App Settings popup.
            this.$store.commit('settings/setSiteSettingsOpenGroup', this.siteSettingsOpenGroupName);
            const sidebar = InstanceStore().get('SideBar') as {
                setSidebarTab?: (id: string) => void;
                sidebarTabSelected?: string;
                controls?: { isTempHide?: boolean };
            } | null;
            // setSidebarTab toggles the tab closed when it's already the active one,
            // so skip the call entirely if the Settings sidebar is already open.
            const isSettingsAlreadyOpen = sidebar?.sidebarTabSelected === 'settings' && !sidebar?.controls?.isTempHide;
            if (!isSettingsAlreadyOpen) {
                sidebar?.setSidebarTab?.('settings');
            }
        },

        updateValue() {
            if(this.valueInput.trim() != '') {
                this.$emit('addglobal', this.valueInput);
            }
            this.showInput = false;
        },
        changeShowInput(){
            this.showInput = true
        },
        handelDelete(){
            this.$emit('update:delete')
        }
    }
};
</script>

