<template>
    <div class="ecom__element ecom-element element__counter">
        <div class="ecom__element-counter--align">
            <div
                v-if="counter?.icon"
                class="element__counter--icon"
                data-ecom-setting-key="counter-icon"
                v-html="counter?.icon.value"
            />
            <div class="element__counter--default">
                <div class="element__counter--wrapper">
                    <span class="element__counter--prefix">{{ counter?.numberPrefix }}</span>
                    <span
                        class="element__counter--number"
                        :data-duration="
                            counter?.animationDuration ? counter?.animationDuration : 1000
                        "
                        :data-to-value="counter?.endingNumber ? counter?.endingNumber : 0"
                        :data-from-value="counter?.startingNumber ? counter?.startingNumber : 0"
                        :data-step="counter?.step ? counter?.step : 1"
                        data-delimiter=","
                        >{{ initialNumber }}</span
                    >
                    <span class="element__counter--suffix">{{ counter?.numberSuffix }}</span>
                </div>
                <div class="element__counter--title" data-ecom-setting-key="counter-title" v-html="lang(counter?.title, 'counter_title')"/>
            </div>
        </div>
    </div>
</template>

<script>
import { Element, Javascript } from "@/mixins";

export default {
    name: "Counter",
    presets:true,
    linkVideo: 'https://youtu.be/NKq-s5MYNs4',
    mixins: [Element, Javascript],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    computed: {
        css() {
            return `
                .ecom-element.element__counter {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                }
                .element__counter--wrapper {
                    display: flex;
                }
                .element__counter--default {
                    display: flex;
                    flex-direction: column;
                    align-items: inherit;
                }
                .element__counter .element__counter--number {
                    font-variant-numeric: tabular-nums;
                    font-feature-settings: "tnum";
                }
                .element__counter .element__counter--prefix,
                .element__counter .element__counter--suffix {
                    flex-grow: 1;
                    white-space: pre-wrap;
                }
                .element__counter .element__counter--prefix {
                    text-align: right;
                }
                .element__counter .element__counter--suffix {
                    text-align: left;
                }
                .ecom__element-counter--align{
                    display: inline-flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    gap:12px 20px;
                }
                .element__counter--icon{
                    display:inline-flex;
                }
                .element__counter--icon svg{
                    fill:currentColor;
                    width:24px;
                    height:auto
                }

            `;
        },
        counter() {
            return this.data.settings;
        },
        // Settings that change how the counter animates; watched to re-run javascript().
        counterInputs() {
            const s = this.data?.settings || {};
            return [
                s.startingNumber,
                s.endingNumber,
                s.step,
                s.animationDuration,
                s.thousandSeparator,
                s.smoothCount
            ].join('|');
        },
        // Static text rendered by Vue. The counter animation is owned by javascript()
        // so this value only has to be the resting/initial state.
        initialNumber() {
            const value = this.counter?.startingNumber;
            const text = String(value === undefined || value === null || value === '' ? 0 : value);
            return this.counter?.thousandSeparator
                ? text.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                : text;
        },
        javascript() {
            return function () {
                const $el = this.$el;
                // A stale run (element already replaced/not inserted yet) must not fire:
                // a detached node reports an all-zero rect and would look "visible".
                if (!$el || !$el.isConnected) return;

                const elements = $el.querySelectorAll(".element__counter--number");
                if (!elements.length) return;

                const win = window;
                const thousandSeparator = this.settings?.thousandSeparator ?? false;
                const smoothCount = this.settings?.smoothCount !== false;
                const format = function (value) {
                    const text = String(value);
                    return thousandSeparator
                        ? text.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                        : text;
                };

                const animate = function (item) {
                    if (item.ecomCounterRaf) {
                        win.cancelAnimationFrame(item.ecomCounterRaf);
                        item.ecomCounterRaf = null;
                    }

                    const duration = Math.max(0, +item.getAttribute("data-duration") || 1000);
                    const from = +item.getAttribute("data-from-value") || 0;
                    const to = +item.getAttribute("data-to-value") || 0;
                    const step = Math.abs(+item.getAttribute("data-step")) || 1;
                    const range = to - from;
                    const decimals = Math.max(
                        (String(from).split(".")[1] || "").length,
                        (String(to).split(".")[1] || "").length,
                        (String(step).split(".")[1] || "").length
                    );
                    const render = function (value) {
                        // textContent over innerText: no forced reflow on every frame.
                        item.textContent = format(decimals ? +value.toFixed(decimals) : value);
                    };

                    if (!range || typeof win.requestAnimationFrame !== "function") {
                        render(to);
                        return;
                    }

                    // Time driven instead of tick driven: the run always lasts `duration`,
                    // however wide the range is.
                    const distance = Math.abs(range);
                    const direction = range < 0 ? -1 : 1;

                    // Values are snapped to `step`. A step that is coarse next to the range
                    // (1 -> 30 by 5 = 7 values in 2s) reads as stuttering, so when smoothCount
                    // is on the granularity drops to about one change per frame instead.
                    const targetTicks = Math.min(120, Math.max(24, Math.round(duration / 16)));
                    let unit = step;
                    if (smoothCount && distance / step < targetTicks) {
                        const smallest = decimals ? Math.pow(10, -decimals) : 1;
                        const raw = distance / targetTicks;
                        unit = raw > smallest
                            ? (decimals ? +raw.toFixed(decimals) : Math.round(raw))
                            : smallest;
                    }

                    let startedAt = null;

                    const frame = function (now) {
                        // The node is gone (element re-rendered / unmounted) -> stop, no leak.
                        if (!item.isConnected) {
                            item.ecomCounterRaf = null;
                            return;
                        }
                        if (startedAt === null) {
                            startedAt = now;
                        }
                        const progress = duration > 0 ? Math.min(1, (now - startedAt) / duration) : 1;
                        if (progress >= 1) {
                            item.ecomCounterRaf = null;
                            render(to);
                            return;
                        }
                        // ease-out cubic: quick off the mark, settles into the final number.
                        // Only with a fine granularity — easing a coarse step would dump every
                        // value in the first half and then hold the last one for a full second.
                        const eased = smoothCount ? 1 - Math.pow(1 - progress, 3) : progress;
                        render(from + direction * Math.floor(distance * eased / unit) * unit);
                        item.ecomCounterRaf = win.requestAnimationFrame(frame);
                    };

                    render(from);
                    item.ecomCounterRaf = win.requestAnimationFrame(frame);
                };

                const fire = function (item) {
                    if (item.ecomCounterFired) return;
                    item.ecomCounterFired = true;
                    animate(item);
                };

                // Tracked on the node itself, not on a window registry keyed by element id:
                // the exporter calls this once per node matching .<id>, so several roots can
                // share one id and must not disconnect each other.
                if ($el.ecomCounterObserver) {
                    $el.ecomCounterObserver.disconnect();
                    $el.ecomCounterObserver = null;
                }

                if (typeof win.IntersectionObserver !== "function") {
                    elements.forEach(fire);
                    return;
                }

                // Root defaults to the viewport of the document owning the elements,
                // so this works both inside the builder iframe and on the storefront.
                let pending = elements.length;
                const observer = new win.IntersectionObserver(
                    function (entries) {
                        entries.forEach(function (entry) {
                            if (!entry.isIntersecting) return;
                            observer.unobserve(entry.target);
                            pending--;
                            fire(entry.target);
                        });
                        if (pending <= 0) {
                            observer.disconnect();
                            $el.ecomCounterObserver = null;
                        }
                    },
                    { threshold: 0 }
                );

                $el.ecomCounterObserver = observer;
                elements.forEach(function (item) {
                    item.ecomCounterFired = false;
                    observer.observe(item);
                });
            };
        },
        settings() {
            return [
                {
                    params: [
                        {
                            type: "text",
                            label: this.$t('title'),
                            name: "title",
                            options: {
                                toolbar: false
                            }
                        },
                        {
                            name: "counterOrder",
                            label: this.$t('title_position'),
                            type: "choose",
                            options: {
                                oneline: true,
                                type: "align-y",
                                values: ["-1", "0"]
                            },
                            css: {
                                selector: " .element__counter--title",
                                properties: {
                                    order: ""
                                }
                            }
                        },
                        {
                            type: "picker",
                            label: this.$t('icon'),
                            name: "icon",
                            options: {
                                type: "icon"
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            name: "flexDirection",
                            label: this.$t('icon_position'),
                            type: "choose",
                            options: {
                                oneline: true,
                                type: "align-position",
                                values: ["row", "column", "column-reverse", "row-reverse"]
                            },
                            css: {
                                selector: " .ecom__element-counter--align",
                                properties: {
                                    "flex-direction": ""
                                }
                            }
                        },
                        {
                            name: "startingNumber",
                            type: "number",
                            label: this.$t('start'),
                            value: 1,
                            options: {
                                min: 0,
                                slider: false,
                                half: true
                            }
                        },
                        {
                            name: "endingNumber",
                            type: "number",
                            label: this.$t('end'),
                            value: 100,
                            options: {
                                min: 0,
                                slider: false,
                                half: true
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            name: "step",
                            type: "number",
                            label: this.$t('step'),
                            value: 10,
                            options: {
                                min: 1,
                                slider: false,

                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: "toggle",
                            label: this.$t('smooth_count'),
                            name: "smoothCount",
                            value: true,
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            },
                            description: this.$t('count_through_every_number_instead_of_jumping_by_step_turn_off_to_count_in_exact_multiples_of_step'),
                        },
                        {
                            type: "toggle",
                            label: this.$t('thousand_separator'),
                            name: "thousandSeparator",
                            value: false,
                            options: {
                                oneline: true,
                                values: {
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    },
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    }
                                },
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data["endingNumber"] > 999;
                                    }
                                }
                            },
                            description: this.$t('when_ending_number_is_greater_than_999_it_works_br_e_g_1000_1000'),
                        },
                        {
                            name: "numberPrefix",
                            type: "text",
                            label: this.$t('number_prefix'),
                            options: {
                                half: true
                            }
                        },
                        {
                            name: "numberSuffix",
                            type: "text",
                            label: this.$t('number_suffix'),
                            options: {
                                half: true
                            }
                        },
                        {
                            name: "animationDuration",
                            type: "number",
                            label: this.$t('duration_ms'),
                            value: 2000,
                            options: {
                                min: 1,
                                max: 10000
                            }
                        }
                    ]
                }
            ];
        },
        default() {
            return {
                "settings": {
                    "startingNumber": 1,
                    "endingNumber": 9500,
                    "animationDuration": 2000,
                    "title": "Happy Customers",
                    "icon": {
                        "name": "happy",
                        "cate": "Emoji",
                        "value": "<svg version=\"1.1\" id=\"lni_lni-happy\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" viewBox=\"0 0 64 64\" style=\"enable-background:new 0 0 64 64;\" xml:space=\"preserve\" fill=\"currentColor\">\n<g>\n\t<path d=\"M32,1.3C15,1.3,1.3,15,1.3,32C1.3,49,15,62.8,32,62.8C49,62.8,62.8,49,62.8,32C62.8,15,49,1.3,32,1.3z M32,59.3\n\t\tC17,59.3,4.8,47,4.8,32C4.8,17,17,4.8,32,4.8C47,4.8,59.3,17,59.3,32C59.3,47,47,59.3,32,59.3z\"></path>\n\t<path d=\"M45.6,35.5H18.4c-0.9,0-1.7,0.4-2.3,1.1c-0.5,0.7-0.8,1.5-0.6,2.4C17,46.8,23.9,52.6,32,52.6c8.1,0,15-5.7,16.5-13.6\n\t\tc0.2-0.8-0.1-1.7-0.6-2.4C47.4,35.9,46.5,35.5,45.6,35.5z M32,49.1c-6.1,0-11.4-4.2-12.9-10.1h25.9C43.4,44.9,38.1,49.1,32,49.1z\"></path>\n\t<path d=\"M20.1,26.7c2.2,0,4-1.8,4-4c0-2.2-1.8-4-4-4c-2.2,0-4,1.8-4,4C16.2,25,18,26.7,20.1,26.7z\"></path>\n\t<circle cx=\"43.9\" cy=\"22.8\" r=\"4\"></circle>\n</g>\n</svg>",
                        "thumbnail": "<svg version=\"1.1\" id=\"lni_lni-happy\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" viewBox=\"0 0 64 64\" style=\"enable-background:new 0 0 64 64;\" xml:space=\"preserve\" fill=\"currentColor\">\n<g>\n\t<path d=\"M32,1.3C15,1.3,1.3,15,1.3,32C1.3,49,15,62.8,32,62.8C49,62.8,62.8,49,62.8,32C62.8,15,49,1.3,32,1.3z M32,59.3\n\t\tC17,59.3,4.8,47,4.8,32C4.8,17,17,4.8,32,4.8C47,4.8,59.3,17,59.3,32C59.3,47,47,59.3,32,59.3z\"></path>\n\t<path d=\"M45.6,35.5H18.4c-0.9,0-1.7,0.4-2.3,1.1c-0.5,0.7-0.8,1.5-0.6,2.4C17,46.8,23.9,52.6,32,52.6c8.1,0,15-5.7,16.5-13.6\n\t\tc0.2-0.8-0.1-1.7-0.6-2.4C47.4,35.9,46.5,35.5,45.6,35.5z M32,49.1c-6.1,0-11.4-4.2-12.9-10.1h25.9C43.4,44.9,38.1,49.1,32,49.1z\"></path>\n\t<path d=\"M20.1,26.7c2.2,0,4-1.8,4-4c0-2.2-1.8-4-4-4c-2.2,0-4,1.8-4,4C16.2,25,18,26.7,20.1,26.7z\"></path>\n\t<circle cx=\"43.9\" cy=\"22.8\" r=\"4\"></circle>\n</g>\n</svg>"
                    },
                    "thousandSeparator": true,
                    "numberSuffix": "+",
                    "flexDirection": "column"
                },
                "style": {
                    "counter_general": {
                        "alignItems": "flex-start",
                        "justify-content": "center"
                    },
                    "counter_icon": {
                        "iconFontSize": "54px",
                        "iconPrimaryColornormalmode": "#333",
                        "iconPrimaryColorhovermode": "#047857",
                        "tab": "normal"
                    },
                    "counter_number": {
                        "textTypography": {
                            "font-family": {
                                "name": "Jost",
                                "value": "https://fonts.googleapis.com/css?family=Jost:100,200,300,400,500,600,700,800,900",
                                "thumbnail": "Jost"
                            },
                            "font-size": "38px",
                            "font-weight": "600",
                            "line-height": "42px"
                        },
                        "textColor": "#333"
                    },
                    "counter_number_surfix": {
                        "textTypography": {
                            "font-family": {
                                "name": "Jost",
                                "value": "https://fonts.googleapis.com/css?family=Jost:100,200,300,400,500,600,700,800,900",
                                "thumbnail": "Jost"
                            },
                            "font-size": "38px",
                            "font-weight": "500",
                            "line-height": "42px"
                        },
                        "textColor": "#333"
                    },
                    "counter_title": {
                        "textTypography": {
                            "global-typography": "AbgUXj49"
                        }
                    }
                }
            }
        }
    },
    watch: {
        // Re-run the animation in place instead of letting jsreactives remount the
        // block (which closes the quick toolbar popup while editing).
        counterInputs() {
            if (this.exporting !== false) {
                return;
            }
            this.$nextTick(this.runJavascript);
        }
    },
    beforeUnmount() {
        this.cleanupCounterObserver();
    },
    methods: {
        quickToolBar() {
            return ['startingNumber', 'endingNumber'];
        },
        cleanupCounterObserver() {
            if (this.$el?.ecomCounterObserver) {
                this.$el.ecomCounterObserver.disconnect();
                this.$el.ecomCounterObserver = null;
            }
        },
        style() {
            let style = [
                {
                    group_alias: "box",
                    options: {
                        group_name: "counter_general",
                        group_title: this.$t('general'),
                        selector: " .element__counter"
                    },
                    modify: {
                        params: [
                            {
                            position : 0,
                            fields: [
                                {
                                    alias:'justify-content',
                                    options:{
                                        label: this.$t('alignment'),
                                    }
                                },
                                {
                                    alias:'align-items',
                                    options:{
                                        label: this.$t('content_alignment'),
                                        name: 'content_alignment',
                                        css:{
                                            selector: 'root .element__counter--title, root .element__counter--wrapper, root .element__counter--icon',
                                            properties:{
                                                'align-self':''
                                            }
                                        }
                                    }
                                },
                            ]
                        },
                        {
                            position : 4,
                            fields : {
                                alias: "spacing",
                                options: {
                                css: {
                                    selector: " .ecom__element-counter--align"
                                }
                            }
                            }

                        }
                        ]
                    }
                },
                {
                    group_alias: "text:spacing",
                    options: {
                        group_name: "counter_number",
                        group_title: this.$t('number'),
                        selector: " .element__counter .element__counter--number"
                    },
                    modify: {
                        remove: {
                            index: 0,
                            length: 1
                        }
                    }
                },
                {
                    group_alias: "text:spacing",
                    options: {
                        group_name: "counter_title",
                        group_title: this.$t('title'),
                        selector: " .element__counter .element__counter--title"
                    },
                    modify: {
                        remove: {
                            index: 0,
                            length: 1
                        },

                    }
                }
            ];
            if (this.counter?.numberSuffix) {
                style.push({
                    group_alias: "text:spacing",
                    options: {
                        group_name: "counter_number_surfix",
                        group_title: this.$t('number_surfix'),
                        selector: " .element__counter .element__counter--suffix"
                    },
                    modify: {
                        remove: { index:0, length: 1}
                    }
                });
            }
            if (this.counter?.numberPrefix) {
                style.push({
                    group_alias: "text:spacing",
                    options: {
                        group_name: "counter_number_prefix",
                        group_title: this.$t('number_prefix'),
                        selector: " .element__counter .element__counter--prefix"
                    }
                });
            }
            if (this.counter?.icon) {
                style.splice(2, 0,{
                    group_alias: "icon:hover",
                    options: {
                        group_name: "counter_icon",
                        group_title: this.$t('icon'),
                        selector: " .element__counter .element__counter--icon"
                    },
                    modify:{
                        params: [
                            {
                                position:2,
                                fields: {
                                    alias: 'spacing',
                                    options: {
                                        label: this.$t('spacing')
                                    }
                                }
                            }
                        ]
                    }

                });
            }

            return style;
        }
    }
};
</script>
