<template>
    <div
        :class="[
            'text-xs text-gray-500',
            { 'ec-keys': isKeysLayout }
        ]"
        v-html="renderedContent"
        @click="handleClick"
    />
</template>

<script lang="ts">
    export default {
        name: 'ParagraphField',
        props: {
            field: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            isKeysLayout(){
                return this.field?.options?.layout === 'keys';
            },
            content(){
                return this.$helpers.markdown(this.field?.content ?? '');
            },
            renderedContent(){
                if (this.isKeysLayout) {
                    return this.parseKeysLayout(this.content);
                }
                return this.content;
            }
        },
        methods: {
            parseKeysLayout(html){
                if (typeof document === 'undefined') return html;
                const list = document.createElement('div');

                html.split(/<br\s*\/?>/i).forEach((line) => {
                    if (!line.trim()) return;
                    const rest = document.createElement('div');
                    rest.innerHTML = line.trim();

                    const keys = document.createElement('span');
                    keys.className = 'ec-keys__keys';
                    while (rest.firstChild) {
                        const node = rest.firstChild;
                        if (node.nodeType === 1 && node.tagName === 'CODE') {
                            keys.appendChild(node);
                            continue;
                        }
                        if (node.nodeType === 3) {
                            const text = (node.textContent || '').trim();
                            if (!text) {
                                rest.removeChild(node);
                                continue;
                            }
                            const next = node.nextSibling;
                            const joins = !!next && next.nodeType === 1 && next.tagName === 'CODE';
                            if (joins && text.length <= 12 && !/\s/.test(text)) {
                                const word = document.createElement('span');
                                word.className = 'ec-keys__join';
                                word.textContent = text;
                                keys.appendChild(word);
                                rest.removeChild(node);
                                continue;
                            }
                        }
                        break;
                    }

                    const label = document.createElement('span');
                    label.className = 'ec-keys__label';
                    while (rest.firstChild) label.appendChild(rest.firstChild);
                    if (label.firstChild && label.firstChild.nodeType === 3) {
                        label.firstChild.textContent = (label.firstChild.textContent || '').replace(/^\s+/, '');
                    }

                    const row = document.createElement('div');
                    row.className = keys.childNodes.length ? 'ec-keys__row' : 'ec-keys__head';
                    if (keys.childNodes.length) row.appendChild(keys);
                    row.appendChild(label);
                    list.appendChild(row);
                });

                return list.innerHTML;
            },
            handleClick(e) {
                const link = e.target.closest('a[href="#upgrade-plan"]');
                if (link) {
                    e.preventDefault();
                    this.$store.dispatch('upgrade/showUpgradePopup', {
                        feature_key: link.dataset.featureKey || 'publish_schedule',
                        source_location: 'paragraph_link',
                        message: link.dataset.message || undefined,
                    });
                    return;
                }
                // Support generic onClick callback from field config
                if (typeof this.field?.onClick === 'function') {
                    this.field.onClick(e);
                }
            }
        }
    };
</script>

