<template>
    <div class="flex gap-2.5 w-full mb-2.5">
        <!-- Palette -->
        <ColorPallet :data="textColor" :hue="hue" @change="changePallet" />

        <!-- Color hue -->
        <ColorHue :value="hueSlideValue" @change="changeHue" />
    </div>

    <!-- Opacity -->
    <div class="ecom-color-opacity rounded-2xl">
        <ColorOpacity
            :style="opacityStyle"
            :value="textColor.alpha * 100"
            @change="changeOpacity"
        />
    </div>
    <!-- Color input -->
    <div class="flex gap-[20px] border-b border-default border-dashed pb-2.5 mb-2.5">
        <div class="group/item" :class="{ 'w-full': textColor.alpha != 1 }">
            <input
                type="text"
                id="ec_hex"
                @change="changeHex"
                :class="{ '!w-full': textColor.alpha != 1 }"
                class="border border-default group-hover/item:border-primary rounded-[0.25rem] w-[72px] h-6 text-center text-xs px-1.5 py-1.5 focus:outline-none focus:border-primary transition"
                :value="finalColor"
            />
            <label
                for="ec_hex"
                class="block text-center pt-2.5 text-xs cursor-pointer"
                v-html="textColor.alpha != 1 ? 'RGBA' : 'HEX'"
            />
        </div>
        <!-- Rgb -->
        <div class="flex gap-2.5 w-full" v-if="textColor.alpha == 1">
            <template v-for="([key, value], index) in Object.entries(textColor.rgb)" :key="index">
                <div v-if="key != 'A'" class="w-1/3 group/item">
                    <input
                        type="number"
                        :id="'ec_' + key"
                        class="border border-default group-hover/item:border-primary rounded-[0.25rem] w-full h-6 text-xs px-1 text-center py-1.5 focus:outline-none focus:border-primary transition"
                        @change="changeRgba(key, $event.target.value)"
                        :value="!isNaN(value) ? value : ''"
                    />
                    <label
                        :for="'ec_' + key"
                        class="block text-center pt-2.5 text-xs cursor-pointer"
                        >{{ key.toUpperCase() }}</label
                    >
                </div>
            </template>
        </div>
    </div>
    <!-- Preset -->
    <div v-if="showPreset" class="flex gap-1.5 flex-wrap">
        <div
            v-for="item in solidPresets"
            @click="changePreset(item)"
            :title="item"
            class="border border-default rounded-full w-[22px] h-[22px] cursor-pointer hover:border-hover transition"
            :style="`background: ${item}`"
        />
    </div>
</template>
<script>
import ColorHue from './ColorHue.vue';
import ColorPallet from './ColorPallet.vue';
import ColorOpacity from './ColorOpacity.vue';
import { getTinyColor } from './untility.ts';
export default {
    components: {
        ColorHue,
        ColorPallet,
        ColorOpacity,
    },
    emits: ['update'],
    props: {
        data: {
            type: String,
            default: '',
        },
        showPreset: {
            type: Boolean,
            default: true
        }
    },
    emits: ['update'],
    data() {
        return {
            textColor: { hex: '', rgb: { r: NaN, g: NaN, b: NaN }, hsv: { h: 0, s: 0, v: 0 }, alpha: 1 },
            hue: 0,
            solidPresets: ["#000000", "#ffffff", "rgb(0 82 124)", "#599C5C", "#f70202", "#0703fc", "#f8fc03", "#03fc07", "#441818", "#7F5093", "#FBB7B7", "#AF4747"],
        };
    },
    computed: {
        hueSlideValue() {
            // const hue = this.textColor.hsv.h;
            return Math.round((this.hue / 360) * 100);
        },
        opacityStyle() {
            const {
                rgb: { r, g, b }
            } = this.textColor;
            return {
                background: `linear-gradient(to right, transparent 0%, rgba(${isNaN(r) ? 255 : r}, ${g || 0}, ${b || 0}, 1) 100%)`
            };
        },
        finalColor() {
            if(this.textColor.alpha != 1) {
                const {
                    rgb: { r, g, b },
                    alpha
                } = this.textColor;
                return `rgba(${r}, ${g}, ${b}, ${alpha})`;
            } else {
                return this.textColor.hex;
            }
        },
        colorSelected() {
            return {
                background: this.textColor.hex ||
                    'linear-gradient(to left top, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0) calc(50% - 0.8px), red 50%, rgba(0, 0, 0, 0) calc(50% + 0.8px), rgba(0, 0, 0, 0) 100%)'
            };
        }
    },
    methods: {
        syncFromData(val) {
            this.textColor = val
                ? getTinyColor(val)
                : { hex: '', rgb: { r: NaN, g: NaN, b: NaN }, hsv: { h: 0, s: 0, v: 0 }, alpha: 1 };
            this.hue = this.textColor.hsv?.h ?? 0;
        },
        changePreset(color) {
            this.textColor = getTinyColor(color);
        },
        changeHex(e) {
            let color = `#${e.target.value.replace(/#/g, "")}`;
            if(color.length == 5 || color.length == 6 || color.length == 8) return;

            this.textColor = getTinyColor(color);
        },
        changeRgba(key, value) {
            let newValue = parseInt(value, 10);
            if (isNaN(newValue)) newValue = 0;
                newValue = Math.min(255, Math.max(0, newValue));
            this.textColor.rgb[key] = newValue;
            this.textColor = getTinyColor(this.textColor.rgb);
        },
        changeHue(val) {
            const h = Math.round((val / 100) * 360);
            const { alpha, hsv } = this.textColor;
            let s = hsv?.s ?? 0;
            let v = hsv?.v ?? 0;
            // Chưa kéo palette (s=0) hoặc màu đen (v=0): gán mặc định để hue có hiệu lực ngay lần click đầu
            if (s === 0) s = 100;
            if (v === 0) v = 100;
            this.textColor = getTinyColor(`hsva(${h}, ${s}%, ${v}%, ${alpha})`);
            this.hue = h;
        },
        changeOpacity(val) {
            const {
                hsv: { h, s, v }
            } = this.textColor;
            this.textColor = getTinyColor(`hsva(${h}, ${s}%, ${v}%, ${Math.round(val) / 100})`);
        },
        changePallet(color) {
            this.textColor = color;
        }
    },
    watch: {
        data: {
            handler(val) {
                this.syncFromData(val);
            },
            immediate: true
        },
        textColor: {
            handler(val) {
                // Chỉ sync hue từ textColor khi có saturation; s=0 thì tinycolor luôn trả h=0
                // và sẽ ghi đè vị trí hue user vừa chọn (cần kéo palette sau để áp dụng hue).
                if (val?.hsv && val.hsv.s != 0) {
                    this.hue = val.hsv.h ?? 0;
                }
                this.$emit('update', this.finalColor);
            },
            deep: true
        }
    },
}
</script>
<style scoped>
input::-webkit-outer-spin-button,
input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type=number] {
  -moz-appearance: textfield;
  appearance: textfield;
}
</style>
