// ResizeHandler.ts
import type {
  GridItemInstance,
  Options,
  ResizeEvents,
} from './types';
import { ensureNumericValue } from '../../helpers/utils';
import { beginGridDebugTrace, endGridDebugTrace, gridDebug } from '../../helpers/debug';

export class ResizeHandler {
  private instance: GridItemInstance;
  private options: Options;
  private events: ResizeEvents;

  constructor(instance: GridItemInstance, options: Options = {}, events: ResizeEvents = {}) {
    this.instance = instance;
    this.options = {
      ratioSize: true,
      autoHeight: false,
      changeFontSize: undefined,
      ...options
    };
    this.events = events;

    this.bindMethods();
  }

  private bindMethods(): void {
    this.startResize = this.startResize.bind(this);
    this.handleResize = this.handleResize.bind(this);
    this.endResize = this.endResize.bind(this);
  }

  public startResize(e: MouseEvent, direction: string): void {
    if (this.instance.static || !this.instance.isNormalZoom || this.instance.isItemLocked) return;
    // Nếu đang resize thì kết thúc resize cũ trước (tránh leak listener khi mouse release ngoài iframe)
    if (this.instance.isResizing) {
      this.endResize(e);
    }

    beginGridDebugTrace(this.instance as any, 'resize', {
      itemId: this.instance.i,
      sectionId: this.instance.sectionId,
      direction,
      initialLeft: this.instance.innerLeft,
      initialTop: this.instance.innerTop,
      initialWidth: this.instance.innerWidth,
      initialHeight: this.instance.innerHeight,
      scaleRatio: this.instance.scaleRatio
    });

    // Cập nhật tỷ lệ scale
    this.instance.updateScaleRatio();

    // Lưu hướng resize
    this.instance.resizeDirection = direction;

    // Lấy vị trí chuột ban đầu (đã điều chỉnh theo scale)
    const mouseStartX = e.clientX / this.instance.scaleRatio;
    const mouseStartY = e.clientY / this.instance.scaleRatio;

    // Sử dụng offset parent và getBoundingClientRect để có tọa độ chính xác
    const rect = this.instance.$refs.item.getBoundingClientRect();

    // Điều chỉnh kích thước và vị trí rect theo tỷ lệ scale
    const actualRect = {
      left: rect.left / this.instance.scaleRatio,
      top: rect.top / this.instance.scaleRatio,
      width: rect.width / this.instance.scaleRatio,
      height: rect.height / this.instance.scaleRatio,
      right: rect.right / this.instance.scaleRatio,
      bottom: rect.bottom / this.instance.scaleRatio
    };

    // QUAN TRỌNG: Sử dụng giá trị hiện tại từ innerLeft/innerTop thay vì tính toán lại
    let currentLeft = ensureNumericValue(this.instance.innerLeft);
    let currentTop = ensureNumericValue(this.instance.innerTop);
    let currentWidth = ensureNumericValue(this.instance.innerWidth);
    let currentHeight = ensureNumericValue(this.instance.innerHeight);

    // Nếu item đang trong group, kiểm tra data-original-left và data-original-top
    if (this.instance.inGroup && this.instance.$refs.item) {
      const originalLeft = this.instance.$refs.item.getAttribute("data-original-left");
      const originalTop = this.instance.$refs.item.getAttribute("data-original-top");
      const originalWidth = this.instance.$refs.item.getAttribute("data-original-width");
      const originalHeight = this.instance.$refs.item.getAttribute("data-original-height");

      if (originalLeft && !isNaN(parseFloat(originalLeft))) {
        currentLeft = parseFloat(originalLeft);
      }

      if (originalTop && !isNaN(parseFloat(originalTop))) {
        currentTop = parseFloat(originalTop);
      }

      if (originalWidth && !isNaN(parseFloat(originalWidth))) {
        currentWidth = parseFloat(originalWidth);
      }

      if (originalHeight && !isNaN(parseFloat(originalHeight))) {
        currentHeight = parseFloat(originalHeight);
      }
    }

    // Chuyển đổi width về pixel nếu đang là %
    let actualCurrentWidth = currentWidth;
    if (typeof this.instance.innerWidth === "string" && this.instance.innerWidth.includes("%")) {
      actualCurrentWidth = (currentWidth / 100) * this.instance.gridContainerWidth;
    }

    // Lưu trữ state ban đầu với giá trị CHÍNH XÁC từ component state
    this.instance.resizeInitialState = {
      width: actualCurrentWidth, // Width thực tế tính bằng px
      height: currentHeight, // Height luôn tính bằng px
      left: currentLeft, // Left theo % hoặc giá trị hiện tại
      top: currentTop, // Top tính bằng px
      mouseX: mouseStartX, // Đã điều chỉnh scale
      mouseY: mouseStartY, // Đã điều chỉnh scale
      rect: actualRect, // Rect thực tế sau khi điều chỉnh scale
      aspectRatio: actualCurrentWidth / currentHeight, // Tỷ lệ khung hình
      containerWidth: this.instance.gridContainerWidth, // Container width gốc
      scaleRatio: this.instance.scaleRatio, // Scale ratio hiện tại
      // Thêm originalInnerWidth để biết đơn vị gốc
      originalInnerWidth: this.instance.innerWidth,
      originalInnerHeight: this.instance.innerHeight
    };

    this.instance.isResizing = true;

    // Add event listeners
    const iframeDoc = this.instance.idoc;
    iframeDoc.addEventListener("mousemove", this.handleResize);
    iframeDoc.addEventListener("mouseup", this.endResize);
    // Fallback: catch mouseup khi mouse release ngoài boundary của iframe
    document.addEventListener("mouseup", this.endResize);

    // Disable text selection
    iframeDoc.body.style.userSelect = "none";
    iframeDoc.body.style.webkitUserSelect = "none";
    document.body.style.userSelect = "none";
    document.body.style.webkitUserSelect = "none";

    e.preventDefault();
    e.stopPropagation();

    // Emit resize start event
    this.instance.eventBus.emit("resizeEvent", {
      eventType: "resizestart",
      i: this.instance.i,
      section_id: this.instance.sectionId
    });
  }

  public handleResize(e: MouseEvent): void {
    if (this.instance.locked) {
      this.instance.$store.commit("builder/setShowNoticeLockmode", true);
      return;
    }
    if (!this.instance.isResizing) return;

    // Hủy animation frame nếu đang có
    if (this.instance._resizeRAF) {
      cancelAnimationFrame(this.instance._resizeRAF);
    }

    // Thực hiện cập nhật trong animation frame tiếp theo
    this.instance._resizeRAF = requestAnimationFrame(() => {
      this.performResize(e);
    });
  }

  private performResize(e: MouseEvent): void {
    const initial = this.instance.resizeInitialState!;
    const containerW = initial.containerWidth; // Sử dụng container width gốc
    const currentScale = this.instance.scaleRatio;

    // Xác định đơn vị width ban đầu
    const initialWidthStr =
      typeof this.instance.innerWidth === "string" ? this.instance.innerWidth : String(this.instance.innerWidth);
    const isPercentWidth = initialWidthStr.includes("%");

    // Tính toán chuyển động chuột (điều chỉnh theo scale)
    const currentMouseX = e.clientX / currentScale;
    const currentMouseY = e.clientY / currentScale;
    const deltaX = currentMouseX - initial.mouseX;
    const deltaY = currentMouseY - initial.mouseY;

    // Khởi tạo kích thước và vị trí mới - ĐẢM BẢO KHÔNG BỊ RESET
    let newWidth = initial.width;
    let newHeight = initial.height;
    let newLeft = initial.left; // Giữ nguyên giá trị từ initial state
    let newTop = initial.top;

    // Lấy các giới hạn kích thước - chuyển đổi theo đơn vị (không cần điều chỉnh scale)
    const { minW, maxW, minH, maxH } = this.instance;
    const minWidthPx = (minW / 100) * containerW;
    const maxWidthPx = Math.min((maxW / 100) * containerW, containerW);
    const minHeightPx = minH;
    const maxHeightPx = maxH === Infinity ? 10000 : maxH;

    // Xử lý resize theo hướng
    if (this.instance.resizeDirection!.includes("e")) {
      // Resize từ phải - BỎ kiểm tra container bounds
      newWidth = initial.width + deltaX;
      newWidth = Math.max(minWidthPx, Math.min(maxWidthPx, newWidth));
    } else if (this.instance.resizeDirection!.includes("w")) {
      // Resize từ trái - BỎ kiểm tra container bounds
      const widthDelta = -deltaX;
      let newWidthPx = initial.width + widthDelta;

      newWidth = Math.max(minWidthPx, Math.min(maxWidthPx, newWidthPx));

      // Tính toán vị trí cạnh phải theo % - CHÍNH XÁC HÓA
      const initialLeftPercent = parseFloat(String(initial.left)); // Đảm bảo là số
      const initialWidthPercent = (initial.width / containerW) * 100;
      const rightEdgePercent = initialLeftPercent + initialWidthPercent;

      // Tính left mới dựa vào cạnh phải (cố định) và width mới
      const newWidthPercent = (newWidth / containerW) * 100;
      newLeft = rightEdgePercent - newWidthPercent;
    }

    if (this.instance.resizeDirection!.includes("s")) {
      // Resize từ dưới
      newHeight = initial.height + deltaY;
      newHeight = Math.max(minHeightPx, Math.min(maxHeightPx, newHeight));
    } else if (this.instance.resizeDirection!.includes("n")) {
      // Resize từ trên - BỎ kiểm tra container bounds
      const newHeightPx = initial.height - deltaY;
      newHeight = Math.max(minHeightPx, Math.min(maxHeightPx, newHeightPx));

      // Tính toán sự thay đổi chiều cao để từ đó tính top
      const heightDiff = initial.height - newHeight;
      newTop = initial.top + heightDiff;
    }

    // Xử lý giữ tỷ lệ nếu cần
    if (
      this.options.ratioSize &&
      (this.instance.resizeDirection === "se" ||
        this.instance.resizeDirection === "sw" ||
        this.instance.resizeDirection === "ne" ||
        this.instance.resizeDirection === "nw")
    ) {
      const aspectRatio = initial.aspectRatio;

      // Lưu lại giá trị trước khi áp dụng tỷ lệ
      const widthBeforeRatio = newWidth;
      const heightBeforeRatio = newHeight;

      // Quyết định sử dụng chiều rộng hay chiều cao làm gốc tính toán
      const useWidth =
        this.instance.resizeDirection!.includes("e") || this.instance.resizeDirection!.includes("w");

      if (useWidth) {
        newHeight = newWidth / aspectRatio;
      } else {
        const calculatedWidth = newHeight * aspectRatio;
        if (
          Math.abs(calculatedWidth - widthBeforeRatio) <
          Math.abs(newWidth - widthBeforeRatio)
        ) {
          newWidth = calculatedWidth;
        }
      }

      // Giới hạn lại sau khi áp dụng tỷ lệ
      newWidth = Math.max(minWidthPx, Math.min(maxWidthPx, newWidth));
      newHeight = Math.max(minHeightPx, Math.min(maxHeightPx, newHeight));

      // Điều chỉnh top/left khi giữ tỷ lệ
      if (this.instance.resizeDirection!.includes("n")) {
        if (newHeight !== heightBeforeRatio) {
          const heightDiff = initial.height - newHeight;
          newTop = initial.top + heightDiff;
        }
      }

      if (this.instance.resizeDirection!.includes("w")) {
        if (newWidth !== widthBeforeRatio) {
          const initialLeftPercent = parseFloat(String(initial.left)); // Đảm bảo là số
          const initialWidthPercent = (initial.width / containerW) * 100;
          const rightEdgePercent = initialLeftPercent + initialWidthPercent;

          const newWidthPercent = (newWidth / containerW) * 100;
          newLeft = rightEdgePercent - newWidthPercent;
        }
      }
    }

    // Xử lý thay đổi font-size khi resize ở các góc
    if (
      this.options.changeFontSize &&
      (this.instance.resizeDirection === "se" ||
        this.instance.resizeDirection === "sw" ||
        this.instance.resizeDirection === "ne" ||
        this.instance.resizeDirection === "nw")
    ) {
      this.handleFontSizeChange(newWidth, newHeight, currentScale);
    }

    // Chuyển đổi width về đơn vị ban đầu nếu cần
    const finalWidth = isPercentWidth
      ? `${((newWidth / containerW) * 100).toFixed(4)}%`
      : `${Math.round(newWidth)}px`;

    // Log resize move
    gridDebug('resize', 'move', {
      itemId: this.instance.i,
      direction: this.instance.resizeDirection,
      deltaX,
      deltaY,
      newWidth: isPercentWidth ? finalWidth : newWidth,
      newHeight,
      newLeft,
      newTop,
      scaleRatio: currentScale
    }, this.instance as any);

    this.applyResizeStyle(newWidth, newHeight, newLeft, newTop, finalWidth, isPercentWidth);

    // Lưu giá trị hiện tại cho việc sử dụng trong endResize
    this.instance._currentResizeValues = {
      width: isPercentWidth ? finalWidth : newWidth,
      height: newHeight,
      left: newLeft,
      top: newTop
    };

    // Emit sự kiện resize cho grid
    if (this.options.autoHeight) {
      newHeight = this.instance.$refs.item.offsetHeight / currentScale;
    }

    this.emitResizeEvent(newWidth, newHeight, newLeft, newTop, finalWidth, isPercentWidth);

    this.instance._resizeRAF = null;
  }

  private handleFontSizeChange(newWidth: number, newHeight: number, currentScale: number): void {
    const textEl = this.instance.$refs.item.querySelector(
      this.options.changeFontSize!.className
    ) as HTMLElement;

    if (textEl) {
      if (!this.instance._initialTextData) {
        const computedStyle = window.getComputedStyle(textEl);
        const initialFontSize = parseFloat(computedStyle.fontSize);
        const initialWidth = textEl.offsetWidth / currentScale;
        const initialHeight = textEl.offsetHeight / currentScale;
        const lineHeight = parseFloat(computedStyle.lineHeight);
        const isMultiLine = textEl.offsetHeight > lineHeight * 1.5;

        this.instance._initialTextData = {
          textEl,
          fontSize: initialFontSize,
          width: initialWidth,
          height: initialHeight,
          isMultiLine
        };
      }

      if (this.instance._initialTextData) {
        const { fontSize, width, isMultiLine } = this.instance._initialTextData;
        let newFontSize = 16;
        if (isMultiLine) {
          const widthRatio = newWidth / width;
          const heightRatio = newHeight / this.instance._initialTextData.height;
          const scaleFactor = Math.min(widthRatio, heightRatio);
          newFontSize = Math.max(
            parseFloat((fontSize * scaleFactor).toFixed(2)),
            8
          );
          textEl.style.fontSize = `${newFontSize}px`;
        } else {
          const widthRatio = ensureNumericValue(newWidth) / ensureNumericValue(width);
          newFontSize = Math.max(
            parseFloat((fontSize * widthRatio).toFixed(2)),
            8
          );
          textEl.style.fontSize = `${newFontSize}px`;
        }
        this.instance._initialTextData.newFontSize = newFontSize;
      }
    }
  }

  private applyResizeStyle(newWidth: number, newHeight: number, newLeft: number, newTop: number, finalWidth: string, isPercentWidth: boolean): void {
    if (this.instance.inGroup) {
      // Xử lý cho item trong group
      let groupWrapper = this.instance.$parent;
      while (groupWrapper && groupWrapper.$options.name !== "GroupWrapper") {
        groupWrapper = groupWrapper.$parent;
      }

      if (groupWrapper && groupWrapper.bounds) {
        const containerWidth = this.instance.parent.containerWidth;
        const groupX = groupWrapper.bounds.x;
        const groupY = groupWrapper.bounds.y;

        const groupXPx = (groupX / 100) * containerWidth;
        let leftPx = (newLeft * containerWidth) / 100 - groupXPx;

        if (
          this.instance.resizeDirection!.includes("w") &&
          !this.instance.resizeDirection!.includes("e")
        ) {
          const initial = this.instance.resizeInitialState!;
          const initialLeft = initial.left;
          const initialWidth = initial.width;
          const rightEdgePercent =
            initialLeft + (initialWidth / containerWidth) * 100;
          const newWidthPercent = (newWidth / containerWidth) * 100;

          newLeft = rightEdgePercent - newWidthPercent;
          leftPx = (newLeft * containerWidth) / 100 - groupXPx;
        }

        this.instance.dragResizeStyle = {
          position: "absolute",
          left: `${leftPx}px`,
          top: `${newTop - groupY}px`,
          width: isPercentWidth ? finalWidth : `${newWidth}px`,
          height: this.options.autoHeight ? "auto" : `${newHeight}px`,
          transform: `rotate(${this.instance.innerRotation}deg)`,
          WebkitTransform: `rotate(${this.instance.innerRotation}deg)`,
          transformOrigin: "center center",
          zIndex: this.instance.innerZindex || "inherit"
        };
      }
    } else {
      // Xử lý cho item thông thường
      const justifySelf = newLeft < 50 ? "start" : "end";
      let marginLeft, marginRight;

      if (justifySelf === "start") {
        marginLeft = `${newLeft}%`;
        marginRight = "auto";
      } else {
        marginLeft = "auto";
        const rightMarginPercent =
          100 - parseFloat(String(newLeft)) - (newWidth / this.instance.resizeInitialState!.containerWidth) * 100;
        marginRight = isNaN(rightMarginPercent) ? "0%" : `${rightMarginPercent}%`;
      }

      const marginTop = `${newTop}px`;
      const margin = `${marginTop} ${marginRight} 0 ${marginLeft}`;

      this.instance.dragResizeStyle = {
        justifySelf: justifySelf,
        alignSelf: "start",
        width: isPercentWidth ? finalWidth : `${newWidth}px`,
        height: this.options.autoHeight ? "auto" : `${newHeight}px`,
        margin: margin,
        transform: `rotate(${this.instance.innerRotation}deg)`,
        WebkitTransform: `rotate(${this.instance.innerRotation}deg)`,
        transformOrigin: "center center",
        zIndex: this.instance.innerZindex || "inherit",
      };
    }
  }

  private emitResizeEvent(newWidth: number, newHeight: number, newLeft: number, newTop: number, finalWidth: string, isPercentWidth: boolean): void {
    this.instance.eventBus.emit("resizeEvent", {
      eventType: "resizemove",
      section_id: this.instance.sectionId,
      i: this.instance.i,
      x: newLeft,
      y: newTop,
      h: Math.ceil(newHeight),
      w: isPercentWidth ? finalWidth : Math.ceil(newWidth),
      edges: {
        left: this.instance.resizeDirection!.includes("w"),
        right: this.instance.resizeDirection!.includes("e"),
        top: this.instance.resizeDirection!.includes("n"),
        bottom: this.instance.resizeDirection!.includes("s")
      },
      rotation: this.instance.innerRotation
    });

    if (this.instance.hasImgElement) {
      this.instance.eventBus.emit("grid-item-resized", {
        gridItemId: this.instance.i,
        sectionId: this.instance.sectionId,
        newSize: {
          width: this.instance.$refs.item.getBoundingClientRect().width,
          height: this.instance.$refs.item.getBoundingClientRect().height
        },
        newPosition: {
          left: this.instance.innerLeft,
          top: this.instance.innerTop
        }
      });
    }
  }

  public endResize(e: MouseEvent): void {
    // Guard idempotency: có thể fire từ cả iframeDoc lẫn document ngoài
    if (!this.instance.isResizing) return;
    gridDebug('resize', 'end', {
      itemId: this.instance.i,
      finalLeft: this.instance.innerLeft,
      finalTop: this.instance.innerTop,
      finalWidth: this.instance.innerWidth,
      finalHeight: this.instance.innerHeight,
      changed: {
        left: this.instance.innerLeft !== this.instance.previousLeft,
        top: this.instance.innerTop !== this.instance.previousTop,
        width: this.instance.innerWidth !== this.instance.widthOld,
        height: this.instance.innerHeight !== this.instance.heightOld
      }
    }, this.instance as any);

    // Hủy animation frame nếu đang có
    if (this.instance._resizeRAF) {
      cancelAnimationFrame(this.instance._resizeRAF);
      this.instance._resizeRAF = null;
    }

    // Remove event listeners
    const iframeDoc = this.instance.idoc;
    iframeDoc.removeEventListener("mousemove", this.handleResize);
    iframeDoc.removeEventListener("mouseup", this.endResize);
    document.removeEventListener("mouseup", this.endResize);

    // Re-enable text selection
    document.body.style.userSelect = "";
    document.body.style.webkitUserSelect = "";
    iframeDoc.body.style.userSelect = "";
    iframeDoc.body.style.webkitUserSelect = "";

    // Reset resize state
    this.instance.parent.$parent.setDragEnded(true);

    setTimeout(() => {
      this.instance.parent.$parent.setDragEnded(false);
    }, 100);

    // Lấy giá trị cuối cùng từ kết quả resize - ĐẢM BẢO KHÔNG BỊ RESET
    const { width, height, left, top } = this.instance._currentResizeValues || {
      width: this.instance.innerWidth,
      height: this.instance.innerHeight,
      left: this.instance.innerLeft,
      top: this.instance.innerTop
    };

    // Cập nhật state nội bộ khi kết thúc resize - ĐẢM BẢO GIÁ TRỊ ĐÚNG
    this.instance.innerWidth = width;
    this.instance.innerHeight = height;
    this.instance.innerLeft = left;
    this.instance.innerTop = top;

    // Đặc biệt xử lý cho item trong group sau khi resize xong
    if (this.instance.inGroup && this.instance.$refs.item) {
      // Cập nhật data-original-left và data-original-top để lưu vị trí mới sau resize
      this.instance.$refs.item.setAttribute("data-original-left", String(left));
      this.instance.$refs.item.setAttribute("data-original-top", String(top));
      this.instance.$refs.item.setAttribute("data-original-width", String(width));
      this.instance.$refs.item.setAttribute("data-original-height", String(height));

      // Emit sự kiện để thông báo cho GroupWrapper biết có thay đổi
      this.instance.eventBus.emit("item-resized-in-group", {
        itemId: this.instance.i,
        section_id: this.instance.sectionId,
        groupId: (this.instance as any).groupId,
        left: left,
        top: top,
        width: width,
        height: height
      });
    }

    // Xóa dragResizeStyle để chuyển về computedStyle
    this.instance.dragResizeStyle = null;

    // Update instance store with new dimensions
    // Finalize resize
    this.instance.isResizing = false;
    this.instance._currentResizeValues = null;

    // Chỉ cập nhật innerHeight nếu cần (height luôn tính bằng px)
    if (this.instance.$refs.item && !this.options.autoHeight) {
      const rect = this.instance.$refs.item.getBoundingClientRect();
      const calculatedHeight = Math.ceil(rect.height / this.instance.scaleRatio);

      // Chỉ cập nhật height nếu khác biệt đáng kể
      if (Math.abs(calculatedHeight - ensureNumericValue(this.instance.innerHeight)) > 1) {
        this.instance.innerHeight = calculatedHeight;
      }
    }

    if (
      this.instance.widthOld !== this.instance.innerWidth ||
      parseFloat(String(this.instance.heightOld)) !== parseFloat(String(this.instance.innerHeight))
    ) {
      this.instance.widthOld = this.instance.innerWidth;
      this.instance.heightOld = this.instance.innerHeight;

      // Nếu đang center, tính lại left để giữ element ở center sau khi resize
      let finalLeft = parseFloat(String(this.instance.innerLeft));
      if ((this.instance as any).center) {
        const containerWidth = this.instance.gridContainerWidth || this.instance.parent.containerWidth || 1200;
        const newWidth = ensureNumericValue(this.instance.innerWidth);
        const isPercent = typeof this.instance.innerWidth === "string" && String(this.instance.innerWidth).includes("%");
        const widthPercent = isPercent
          ? newWidth
          : (newWidth / containerWidth) * 100;
        finalLeft = (100 - widthPercent) / 2;
        this.instance.innerLeft = finalLeft;
      }

      // Emit final resized event
      this.instance.updateGridSize();
      // Preserve % unit in width so Grid.vue stores it correctly as a percentage
      const emitWidth =
        typeof this.instance.innerWidth === "string" && this.instance.innerWidth.includes("%")
          ? this.instance.innerWidth
          : parseFloat(String(this.instance.innerWidth));
      this.instance.$emit(
        "resized",
        this.instance.i,
        parseFloat(String(this.instance.innerHeight)),
        emitWidth,
        finalLeft,
        parseFloat(String(this.instance.innerTop)),
        true
      );

      // Call events callback
      if (this.events.onResized) {
        this.events.onResized(
          this.instance.i,
          parseFloat(String(this.instance.innerHeight)),
          parseFloat(String(this.instance.innerWidth)),
          parseFloat(String(this.instance.innerLeft)),
          parseFloat(String(this.instance.innerTop)),
          true
        );
      }
    }

    // FIX: resizeend phải LUÔN được emit khi resize kết thúc, bất kể dimensions có
    // thay đổi hay không. Nếu để trong khối if ở trên, khi item đã ở 100% width
    // (bị clamp) và resize lại không thay đổi dimensions, Layout sẽ không bao giờ
    // nhận được resizeend → stuck ở trạng thái "đang resize" → block click interactions.
    setTimeout(() => {
      this.instance.eventBus.emit("resizeEvent", {
        eventType: "resizeend",
        i: this.instance.i,
        section_id: this.instance.sectionId
      });
    }, 100);

    // Cập nhật computed style sau khi resize xong
    this.instance.createStyle();

    // Reset resizeDirection after use
    this.instance.resizeDirection = null;

    // Update font size in instance store if needed
    this.updateFontSizeInStore();
    endGridDebugTrace(this.instance as any, 'resize', 'trace:end', {
      itemId: this.instance.i,
      finalLeft: this.instance.innerLeft,
      finalTop: this.instance.innerTop,
      finalWidth: this.instance.innerWidth,
      finalHeight: this.instance.innerHeight
    });
  }

  private updateFontSizeInStore(): void {
    if (
      this.instance._initialTextData &&
      this.instance._initialTextData.textEl &&
      this.instance._initialTextData.newFontSize &&
      this.options.changeFontSize?.nameStyle
    ) {
      const inst = this.instance.instanceStore.get(this.instance.i);
      if (inst) {
        const name =
          this.instance.currentScreen === "desktop"
            ? "textTypography"
            : "textTypography__" + this.instance.currentScreen;
        if (!inst.data.style) {
          inst.data.style = {};
        }
        if (!inst.data.style[this.options.changeFontSize.nameStyle]) {
          inst.data.style[this.options.changeFontSize.nameStyle] = {};
        }
        if (!inst.data.style[this.options.changeFontSize.nameStyle][name]) {
          inst.data.style[this.options.changeFontSize.nameStyle][name] = {};
        }
        inst.data.style[this.options.changeFontSize.nameStyle][name][
          "font-size"
        ] = `${this.instance._initialTextData.newFontSize}px`;

        setTimeout(() => {
          if (this.instance._initialTextData?.textEl) {
            this.instance._initialTextData.textEl.style.fontSize = ``;
            this.instance._initialTextData = null;
          }
        }, 200);
      }
    }
  }

  public destroy(): void {
    // Cleanup event listeners if needed
    if (this.instance._resizeRAF) {
      cancelAnimationFrame(this.instance._resizeRAF);
      this.instance._resizeRAF = null;
    }

    // Remove any remaining event listeners
    this.instance.idoc.removeEventListener("mousemove", this.handleResize);
    this.instance.idoc.removeEventListener("mouseup", this.endResize);

    // Reset resize state
    this.instance.isResizing = false;
    this.instance.resizeDirection = null;
    this.instance.resizeInitialState = null;
    this.instance._currentResizeValues = null;
    this.instance.dragResizeStyle = null;
    this.instance._initialTextData = null;
  }
}