// store/modules/library/actions.ts
import { $t as _$t } from "@/plugins/i18n";
import { confirmExit } from "@/utils/helpers";

// vue-i18n exports a union type that TS can't directly call – cast once here.
const $t = _$t as unknown as (key: string, ...args: any[]) => string;
import type { ActionContext } from 'vuex';
import type {
    LibraryState,
    LoadPayload,
    InsertPayload,
    FavoritePayload,
    SaveTaskPayload,
    RemoveTemplatePayload,
    ProcessedTags,
} from './types';
import { buildRequestPayload, metaDataToQuery } from './types';
import { LIBRARY_ROUTES, API_ROUTES, USER_TABS, ECOM_TABS } from './constants';
import { LibraryCacheService, generateCacheKey } from './cache';

type Ctx = ActionContext<LibraryState, any>;
type CtxW = Ctx & { $worker: any };

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Chuyển mảng tags từ API thành object { groupKey: Tag[] }. */
function processTags(tags: any[]): ProcessedTags {
    if (!tags?.length) return {};
    return tags.reduce((acc: ProcessedTags, item: any) => {
        if (!item.name) return acc;
        const parts = item.name.split('|');
        const key = parts.length === 2 ? parts[0].toLowerCase() : 'tags';
        const label = parts.length === 2 ? parts[1] : item.name;
        if (!acc[key]) acc[key] = [];
        acc[key].push({ id: item.id, label });
        return acc;
    }, {});
}

/** Tiện ích mở/đóng popup builder. */
function setPopup(commit: Ctx['commit'], show: boolean, loading = true, message = '') {
    commit('builder/setPopup', { show, loading, message: message || $t('processing'), closeable: true }, { root: true });
}

/** Toast thành công. */
function toastOk(dispatch: Ctx['dispatch'], message: string) {
    dispatch('global/setToast', { message, duration: 4000 }, { root: true });
}

/** Toast lỗi. */
function toastErr(dispatch: Ctx['dispatch'], e: Error | any) {
    dispatch('global/setToast', { isError: true, message: e.message ?? e, data: e, duration: 4000 }, { root: true });
}

/** Kiểm tra và inject partner item vào list nếu đủ điều kiện promo. */
function injectPartner(list: any[], tab: string, key: string, partners: any, optionsPromo: any) {
    if (!optionsPromo || !partners?.[tab]?.[key]) return;
    const promo = optionsPromo[`${tab}_library`]?.[key];
    if (!promo) return;
    if (promo.expiry && new Date().getTime() <= parseInt(promo.expiry)) return;
    if (!list.length) return;
    const already = list.find((i: any) => i.type === 'partner');
    if (already) return;
    const item = { ...partners[tab][key], type: 'partner' };
    list.splice(4, 0, item);
}

// ── Race-condition guard ──────────────────────────────────────────────────────
// Mỗi lần bắt đầu một foreground fetch mới, tăng counter này.
// _doMainFetch chụp giá trị hiện tại; khi response về mà counter đã đổi
// (tức là đã có fetch mới hơn được khởi chạy) → bỏ qua response cũ.
let _fetchGeneration = 0;

// ── initAsync deduplication guard ────────────────────────────────────────────
// Khi nhiều component (App.vue, Section.vue, TemplateExpand.vue…) gọi initAsync
// cùng lúc, chỉ bắn 1 HTTP request duy nhất. Các lần gọi sau nhận chung Promise.
let _initAsyncInFlight: Promise<boolean> | null = null;

// ── Cache-aware fetch helper ──────────────────────────────────────────────────

/**
 * Thực hiện gọi API chính và cập nhật cache + Vuex sau khi thành công.
 * Tách ra ngoài object actions để có thể gọi cả trong load() thường lẫn
 * background revalidation mà không lặp code.
 *
 * @param worker        - this.$worker (worker/axios instance)
 * @param ctx           - ActionContext (state, getters, commit, dispatch)
 * @param payload       - LoadPayload gốc
 * @param cacheKey      - key để ghi vào LibraryCacheService (null = không cache)
 * @param isBackground  - nếu true, KHÔNG set loading/loadingMore, KHÔNG clear list
 * @param generation    - giá trị _fetchGeneration tại thời điểm gọi (null = background, bỏ qua check)
 */
function _doMainFetch(
    worker: any,
    ctx: { state: LibraryState; getters: any; commit: Function; dispatch: Function },
    payload: LoadPayload,
    cacheKey: string | null,
    isBackground = false,
    generation: number | null = null,
): void {
    const { state, getters, commit, dispatch } = ctx;
    const insert       = getters['insert'];
    const isDetail     = getters['detailScreen'];
    const isChangeCat  = payload?.isChangeCat || false;
    const isLoadmore   = payload?.isLoadmore   || false;

    const dt           = buildRequestPayload(state.context);
    const meta         = dt.metadata;
    const paged        = meta.paged || 1;
    const optionsPromo = state.cache.meta.optionsPromo;
    const partners     = state.cache.meta.partners;

    // Dữ liệu hiện có: ưu tiên CacheService, fallback sang cache.lists
    const cachedEntry  = cacheKey ? LibraryCacheService.get(cacheKey) : null;
    const datas        = cachedEntry?.data != null ? { [insert.current]: cachedEntry.data } : state.cache.lists;

    worker
        .fetch(window.route(LIBRARY_ROUTES[insert.current], { page: paged }), dt, 'POST')
        .then((res: any) => {
            // Nếu đã có request mới hơn được khởi chạy, bỏ qua response này (race condition guard)
            if (generation !== null && generation !== _fetchGeneration) return;

            if (res.data?.status !== 'success') throw new Error(res.data?.message);

            let newData: any = {};
            const replace = (isChangeCat || !getters['firstLoad']) && !isLoadmore;

            if (isDetail?.id) {
                // ── Detail mode (niche / category) ────────────────────────────
                const data = res.data?.items || {};

                // Tab pages/sections lưu detail lồng trong entry của tab (Template.vue và
                // handleLoadMore đọc [tab][detailKey]); các trường hợp còn lại lưu phẳng
                // theo detailKey như cũ.
                const isNestedTab = ['pages', 'sections'].includes(insert.current) && isDetail.id !== 'theme_pages';
                const tabData     = isNestedTab ? ((datas as any)?.[insert.current] || {}) : null;
                const prev        = isNestedTab
                    ? (tabData[isDetail.id]?.list || [])
                    : ((datas as any)?.[isDetail.id]?.list || []);
                const list = replace ? data?.data : prev.concat(data?.data || []);
                if (!isNestedTab) injectPartner(list, insert.current, isDetail.id, partners, optionsPromo);

                const entry = {
                    id      : isDetail.id,
                    list,
                    loading : false,
                    paged,
                    loadMore: data?.current_page < data?.last_page,
                    searching: meta?.search !== '',
                };

                if (isNestedTab) {
                    newData = {
                        [insert.current]: {
                            ...tabData,
                            [isDetail.id]: entry,
                            // Flat: grid của TemplateExpand đọc [tab].list. Tab `pages` đặt detailKey
                            // theo sort (setCurrent/applySortBy) nhưng vẫn render flat grid — thiếu
                            // shape này thì list không bao giờ đổi theo filter/search.
                            ...entry,
                        },
                    };
                } else {
                    newData = { [isDetail.id]: entry };
                    // Tab thư viện (all_pages…) render grid theo tên tab. Nếu chỉ ghi vào
                    // [detailKey] thì listOfData[tab] giữ nguyên data cũ và list "đứng yên"
                    // dù response đã đúng filter.
                    if ((ECOM_TABS as readonly string[]).includes(insert.current) && insert.current !== isDetail.id) {
                        // Bản sao riêng: hai key trong cache.lists không dùng chung 1 object
                        // để code cũ patch entry này không vô tình sửa entry kia.
                        newData[insert.current] = { ...entry };
                    }
                }
            } else {
                // ── Top-level mode ─────────────────────────────────────────────
                if (getters['firstLoad'] === true) dispatch('initAsync');

                if (res.data?.templates !== undefined) {
                    // Grouped response: { trending: {...}, popular: {...}, newest: {...} }
                    const templates = res.data.templates;
                    newData[insert.current] = { searching: meta?.search !== '' };
                    Object.keys(templates).forEach((key) => {
                        const list = [...(templates[key]?.data || [])];
                        injectPartner(list, insert.current, key, partners, optionsPromo);
                        newData[insert.current] = {
                            id      : key,
                            list,
                            loading : false,
                            paged,
                            loadMore: templates[key]?.current_page < templates[key]?.last_page,
                            total   : templates[key]?.total,
                        };
                    });
                } else {
                    // Simple list (sections, all_pages, my_templates…)
                    const data    = res.data?.items;
                    const prevList = (datas as any)?.[insert.current]?.list || [];
                    newData[insert.current] = {
                        list    : replace ? data?.data : prevList.concat(data?.data || []),
                        loading : false,
                        paged,
                        loadMore: data?.current_page < data?.last_page,
                        total   : data?.total,
                    };
                }
            }

            // Ghi vào cache.lists (backward-compat + detail views)
            commit('mergeLists', newData);

            // Detail mode không ghi CacheService (cacheKey = null) → phải bỏ activeKey của tab,
            // nếu không listOfData vẫn overlay entry cache của lần fetch top-level trước đó đè
            // lên data vừa merge và list sẽ không đổi dù filter/search đã khác.
            if (isDetail?.id) commit('clearActiveKey', insert.current);

            // Ghi vào CacheService cho top-level tabs (sections, all_pages, …)
            if (cacheKey && !isDetail?.id) {
                LibraryCacheService.set(cacheKey, newData[insert.current]);
                commit('setActiveKey', { tab: state.context.tab, key: cacheKey });
            } else if (isBackground) {
                // Background revalidate: cacheVersion đã được mergeLists tăng,
                // không cần thêm gì, listOfData getter sẽ tự re-compute.
                commit('incrementCacheVersion');
            }
        })
        .catch((e: Error) => {
            if (generation !== null && generation !== _fetchGeneration) return;
            if (!isBackground) toastErr(dispatch, e);
        })
        .finally(() => {
            if (!isBackground && (generation === null || generation === _fetchGeneration)) {
                commit('setStatus', { loading: false, loadingMore: false });
            }
        });
}

// ── Actions ───────────────────────────────────────────────────────────────────

export default {
    // ── Context helpers ───────────────────────────────────────────────────────

    /** Tương thích cú pháp cũ: setInsert({ isOpen, current, type, metaData }). */
    setInsert({ commit, state }: Ctx, payload: Partial<LibraryState['context']> & { current?: string; type?: string; metaData?: Record<string, any> }): void {
        const { current, type, metaData, query: payloadQuery, ...rest } = payload as any;
        const tab = current !== undefined ? current : rest.tab;
        const mode = type !== undefined ? type : rest.mode;
        const queryFromMeta = metaData ? metaDataToQuery(metaData) : null;

        // Khi chuyển tab, tự động xóa detailKey cũ để tránh gửi type/detail sai lên API
        const isTabSwitch = tab !== undefined && tab !== state.context.tab;

        const mergedQuery = payloadQuery
            ? payloadQuery
            : queryFromMeta
                ? queryFromMeta
                : null;

        const query = mergedQuery !== null || isTabSwitch
            ? {
                ...state.context.query,
                ...(isTabSwitch && { detailKey: null }),
                ...(mergedQuery ?? {}),
              }
            : undefined;

        commit('setContext', {
            ...rest,
            ...(tab !== undefined && { tab }),
            ...(mode !== undefined && { mode }),
            ...(query !== undefined && { query }),
        });
    },

    /** Đặt category hiện tại và lưu theo source (categoryBySource). */
    setCurrentCat({ commit, state }: Ctx, payload: Record<string, any>): void {
        const q = state.context.query;
        const val = typeof payload === 'object' && !Array.isArray(payload)
            ? Object.values(payload)[0] ?? payload?.id ?? q.categoryId
            : payload ?? q.categoryId;
        commit('setQuery', {
            categoryId: val,
            categoryBySource: { ...(q.categoryBySource ?? {}), ...payload },
        });
    },

    close({ commit }: Ctx): void {
        commit('setContext', { isOpen: false });
        if (window.location.hash.includes('extensions')) {
            window.location.hash = '';
        }
    },

    // ── Loading helpers

    /** Đặt loading (filter/category/sort change) — ẩn list, chỉ show placeholder. */
    setLoading({ commit }: Ctx, payload: boolean): void {
        commit('setStatus', { loading: payload });
    },

    /** Đặt loadingMore (infinite scroll) — giữ list, thêm placeholder phía dưới. */
    setLoadingMoreData({ commit }: Ctx, payload: boolean): void {
        commit('setStatus', { loadingMore: payload });
    },

    // ── Promo ─────────────────────────────────────────────────────────────────

    updatePromo({ state }: Ctx): void {
        try {
            const optionsPromo = state.cache.meta.optionsPromo;
            if (optionsPromo) {
                localStorage.setItem('optionsPromo', JSON.stringify(optionsPromo));
            }
        } catch (e) {
            console.error('Update promo error:', e);
        }
    },

    // ── Init ─────────────────────────────────────────────────────────────────

    initAsync(this: CtxW, { commit, state }: Ctx): Promise<boolean> {
        // Nếu categories đã có → không cần gọi lại
        if (Array.isArray(state.cache.meta.categories) && state.cache.meta.categories.length > 0 && !state.status.firstLoad) {
            return Promise.resolve(true);
        }
        // Deduplication: nếu đang có request bay → trả về chung Promise để tránh duplicate HTTP call
        if (_initAsyncInFlight) {
            return _initAsyncInFlight;
        }

        _initAsyncInFlight = new Promise((resolve, reject) => {
            this.$worker
                .fetch(window.route(API_ROUTES.INIT, { library: encodeURIComponent(state.context.sourceId) }), null)
                .then((response: any) => {
                    if (response?.data?.status === 'success') {
                        const data = response.data.data;
                        commit('setMeta', {
                            categories : data.categories ?? state.cache.meta.categories,
                            favorites  : data.favorites  ?? state.cache.meta.favorites,
                            tags       : processTags(data.tags || []),
                            ...(data.partners?.library && { partners: data.partners.library }),
                        });
                        commit('setStatus', { initializing: false, firstLoad: false });
                        resolve(true);
                    } else {
                        throw new Error(response?.message ?? $t('unknown_error'));
                    }
                })
                .catch((e: Error) => {
                    commit('setStatus', { initializing: false, error: e.message });
                    reject(e.message);
                })
                .finally(() => {
                    _initAsyncInFlight = null;
                });
        });

        return _initAsyncInFlight;
    },

    // ── Source ────────────────────────────────────────────────────────────────

    changeLibrary({ commit, state, dispatch }: Ctx, payload: string): void {
        commit('setContext', {
            sourceId: payload,
            query: {
                ...state.context.query,
                page: 1, search: '', categoryId: null, nicheId: null, tags: [], detailKey: null,
            },
        });
        dispatch('load');
    },

    // ── Load list ─────────────────────────────────────────────────────────────

    load(this: CtxW, { state, getters, commit, dispatch }: Ctx, payload: LoadPayload = {}): void {
        const isChangeCat = payload?.isChangeCat || false;
        const isLoadmore  = payload?.isLoadmore   || false;

        // ── 1. Cập nhật context.query nếu payload có metadata ─────────────────
        if (payload?.metadata) {
            const q = state.context.query;
            commit('setQuery', {
                page      : payload.metadata.paged    ?? q.page,
                pageSize  : payload.metadata.limit    ?? q.pageSize,
                search    : payload.metadata.search   ?? q.search,
                categoryId: payload.metadata.category ?? q.categoryId,
                tags      : payload.metadata.tags     ?? q.tags,
                sort      : payload.metadata.sort     ?? q.sort,
                filter    : payload.metadata.filter   ?? q.filter,
                detailKey : payload.metadata.detail   ?? payload?.type ?? q.detailKey,
            });
        }

        const insert   = getters['insert'];
        const isDetail = getters['detailScreen'];
        const datas    = state.cache.lists;

        // ── 2. Nhánh: special routes (my_favorites, my_templates…) ────────────
        //    Không dùng CacheService vì data cá nhân, ngắn hạn, cần tươi.
        if (payload?.routes) {
            const dt        = buildRequestPayload(state.context);
            const paged     = dt.metadata.paged || 1;
            const routeName = LIBRARY_ROUTES[payload.routes];
            // Tăng generation để invalidate các fetch routes đang bay
            const gen = !isLoadmore ? ++_fetchGeneration : _fetchGeneration;
            // Loadmore phải giữ list cũ trên màn hình: bật `loading` sẽ làm component
            // render placeholder thay cho list (my_favorites, my_templates…).
            commit('setStatus', { loading: !isLoadmore, loadingMore: isLoadmore });
            this.$worker
                .fetch(window.route(routeName, { page: paged }), dt, 'POST')
                .then((res: any) => {
                    if (gen !== _fetchGeneration) return;
                    if (res.data?.status !== 'success') throw new Error(res.data?.message);
                    const data     = res.data.items.data;
                    const newEntry: any = {
                        id      : payload.type,
                        list    : data,
                        loading : false,
                        paged,
                        loadMore: res.data.items.current_page < res.data.items.last_page,
                        total   : res.data.items.total,
                    };
                    // Chỉ nối list khi đúng luồng infinite scroll — không dùng res.metadata.paged
                    // (API thường không trả hoặc trả sai → refresh trang 1 vẫn bị concat / list lệch).
                    if (isLoadmore) {
                        const prev = (datas as any)?.[payload.routes!]?.list || [];
                        newEntry.list = prev.concat(data);
                    }
                    commit('mergeLists', { [payload.routes!]: newEntry });
                })
                .catch((e: Error) => { if (gen === _fetchGeneration) toastErr(dispatch, e); })
                .finally(() => { if (gen === _fetchGeneration) commit('setStatus', { loading: false, loadingMore: false }); });
            return;
        }

        // ── 3. Nhánh: skip nếu detail data đã có và không cần reload ──────────
        if (!isChangeCat && datas && Object.keys(datas).length && isDetail?.id) {
            const isBySource = !!state.context.query.detailKey;
            const alreadyCached = isBySource
                ? (datas as any)[isDetail.id]?.list?.length && !(datas as any)['theme_pages']?.searching
                : (datas as any)[insert.current]?.list?.length && !(datas as any)[insert.current]?.searching;
            if (alreadyCached) {
                commit('setStatus', { loading: false, loadingMore: false });
                return;
            }
        }

        // ── 4. Stale-while-revalidate cho top-level tabs (sections, all_pages) ─
        //    Chỉ áp dụng khi:
        //    - Không phải loadMore (loadMore luôn fetch tươi)
        //    - Không phải isChangeCat (thay đổi filter thì cần fetch ngay, nhưng key mới
        //      vẫn được check cache vì query hash khác)
        //    - Không phải detail view
        const isTopLevel = !isDetail?.id;
        const isUserTab  = USER_TABS.includes(state.context.tab as (typeof USER_TABS)[number]);

        // ── 4a. Bỏ qua loadMore tính từ list CŨ ───────────────────────────────
        // Khi merchant đổi sort/category, request page-1 của query mới đã bay nhưng list cũ
        // vẫn còn trên màn hình. Scroll đúng lúc đó → handleScroll đọc entry CŨ, tính
        // paged = entryPaged + 1 rồi gửi đi; response về sẽ nối data trang N của query MỚI
        // vào list CŨ → list lai, `paged` nhảy cóc (mất trang 2..N-1 của query mới).
        //
        // `_fetchGeneration` không chặn được: loadMore cố ý không tăng generation nên nó
        // thừa hưởng đúng generation của request đổi-filter đang bay → cả hai response đều
        // qua được guard.
        //
        // activeKey (entry đang hiển thị) khác key của context hiện tại = entry đã cũ.
        // Không cần fetch: request đổi-filter đang bay sẽ thay toàn bộ list.
        if (isLoadmore && isTopLevel && !isUserTab) {
            const activeKey = state.activeKeys[state.context.tab];
            if (activeKey && activeKey !== generateCacheKey(state.context)) {
                commit('setStatus', { loadingMore: false });
                return;
            }
        }

        // Tab cá nhân: không dùng SWR CacheService (data sống ở cache.lists + nhánh routes).
        // Tránh setActiveKey + return sớm với entry localStorage cũ làm listOfData “đứng”.
        if (isTopLevel && !isLoadmore && !isUserTab) {
            const cacheKey = generateCacheKey(state.context);
            const cached   = LibraryCacheService.get(cacheKey);

            if (cached) {
                // Phục vụ từ cache vẫn là một "lần load" mới: phải tăng generation, nếu không
                // response của request cũ đang bay (filter trước đó) về sau vẫn setActiveKey và
                // đè lên filter hiện tại.
                const gen = ++_fetchGeneration;

                // Đặt activeKey → listOfData getter trả data từ CacheService
                commit('setActiveKey', { tab: state.context.tab, key: cacheKey });
                commit('setStatus', { loading: false, loadingMore: false });

                if (!cached.stale) {
                    // ✅ Fresh: phục vụ ngay, không gọi API
                    return;
                }

                // ⏳ Stale: phục vụ data cũ ngay lập tức (không loading), đồng thời revalidate
                //    ngầm ở background. Truyền `gen` để nếu user đổi filter trong lúc revalidate
                //    thì response cũ bị bỏ qua thay vì ghi đè list mới.
                _doMainFetch(this.$worker, { state, getters, commit, dispatch }, payload, cacheKey, true /* isBackground */, gen);
                return;
            }
        }

        // ── 5. Không có cache (hoặc loadMore / detail): fetch bình thường ─────
        // Tăng generation cho mọi foreground non-loadmore fetch để invalidate request cũ đang bay.
        const gen = !isLoadmore ? ++_fetchGeneration : _fetchGeneration;

        if (isLoadmore) {
            commit('setStatus', { loadingMore: true, loading: false });
        } else {
            commit('setStatus', { loading: true, loadingMore: false });
        }

        const cacheKey = isTopLevel ? generateCacheKey(state.context) : null;
        _doMainFetch(this.$worker, { state, getters, commit, dispatch }, payload, cacheKey, false, gen);
    },

    // ── Preview ───────────────────────────────────────────────────────────────

    setPreview({ commit }: Ctx, payload: Partial<LibraryState['status']['preview']>): void {
        commit('setPreview', payload);
    },

    // ── Insert template ───────────────────────────────────────────────────────

    insertTemplates(this: CtxW, { commit, dispatch, getters, rootGetters }: Ctx, payload: InsertPayload): void {
        commit('global/setProgress', { show: true, percent: 10 }, { root: true });
        setPopup(commit, true);

        const target = payload?.target ?? getters['open'];
        dispatch('setInsert', { isOpen: false });

        this.$worker
            .fetch(window.route(API_ROUTES.TEMPLATE, payload.id))
            .then((response: any) => {
                if (response.data.status !== 'success') throw new Error(response.data.message ?? $t('unknown_error'));

                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                setPopup(commit, false);

                const regex = /\{([^\{]+)?\"font-family\"\:\{([^\}]+)\}([^\}]+)\}/gm;
                let tmpl = response.data?.data?.options?.data;
                let dataLayout: any;

                if (typeof tmpl === 'string') {
                    dataLayout = tmpl.replace(/"tab":"(active|hover)"/gm, '"tab":"normal"');
                    if (payload?.params?.remove_typo) dataLayout = dataLayout.replace(regex, '{}');
                    try { dataLayout = JSON.parse(dataLayout); } catch { dataLayout = JSON.parse(tmpl); }
                }

                if (payload?.params?.overwrite) {
                    commit('page/setSections', { data: dataLayout.sections, settings: dataLayout.settings }, { root: true });
                } else {
                    commit('page/insertSections', { sections: dataLayout.sections, index: target?.index, settings: dataLayout.settings }, { root: true });
                }

                if (rootGetters['page/params']?.template_id) {
                    commit('page/setSettings', { title: response.data?.data?.title, layout: 'theme', custom_code: {} }, { root: true });
                }

                dispatch('setInsert', { isOpen: false });
            })
            .catch((e: Error) => {
                dispatch('setInsert', { isOpen: false });
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                setPopup(commit, false);
                toastErr(dispatch, e);
            });
    },

    // ── Insert post (EComposer / Theme post) ──────────────────────────────────

    insertPost(this: CtxW, { state, commit, dispatch, getters, rootGetters }: Ctx, payload: InsertPayload): void {
        commit('global/setProgress', { show: true, percent: 100 }, { root: true });
        commit('ai/setIsOpen', false, { root: true });
        setPopup(commit, true, true, $t('creating_preview'));

        const target   = payload?.target ?? getters['open'];
        const endpoint = state.context.sourceId === 'theme' ? API_ROUTES.POST_THEME : API_ROUTES.POST;

        dispatch('setInsert', { isOpen: false });
        dispatch('setPreview', { open: false });

        if ((window as any).mixpanel) {
            (window as any).mixpanel.track('Insert_this_template', {
                event_name : 'Insert this template',
                event_value: payload.id,
            });
        }

        this.$worker
            .fetch(window.route(endpoint, payload.id))
            .then((response: any) => {
                if (!response.data || response.data.status !== 'success') throw new Error(response.data?.message ?? $t('unknown_error'));

                if (!response.data.post.options) return;

                const regex = /(\,?)\s*?"\s*?font-family\s*?\"\:.+?\}(,?)/gm;
                let tmpl = response.data?.post?.options?.data;
                let dataLayout: any;

                if (typeof tmpl === 'string') {
                    dataLayout = tmpl.replace(/"tab":"(active|hover)"/gm, '"tab":"normal"');
                    if (payload?.params?.remove_typo) {
                        dataLayout = dataLayout.replace(regex, (...args: string[]) => args[1] && args[2] ? args[2] : '');
                    }
                    try { dataLayout = JSON.parse(dataLayout); } catch { dataLayout = JSON.parse(tmpl); }
                }

                const data = { sections: dataLayout.sections, index: target?.index, settings: dataLayout.settings };
                setPopup(commit, false);
                dispatch('setInsert', { isOpen: false });

                if (data.settings?.style_popup) {
                    const pageSettings = rootGetters['page/settings'];
                    if (pageSettings?.slug) {
                        data.settings.slug  = pageSettings.slug;
                        data.settings.title = pageSettings.title;
                    }
                }

                if (payload?.params?.overwrite) {
                    commit('page/setSections', { data: data.sections, settings: data.settings }, { root: true });
                } else if (payload?.dragInsertIndex !== undefined) {
                    commit('page/insertSectionAt', { sections: data.sections, index: payload.dragInsertIndex }, { root: true });
                } else {
                    data.index = undefined;
                    commit('page/insertSections', data, { root: true });
                }

                (data.sections ?? []).forEach((sec: any) => {
                    sec.stats = { type: response.data.post.type, id: response.data.post.id };
                });

                if (dataLayout?.custom_code) {
                    const s = { ...rootGetters['page/settings'], custom_code: dataLayout.custom_code };
                    commit('page/setSettings', s, { root: true });
                }

                commit('global/setProgress', { show: false, percent: 100 }, { root: true });

                if (window.location.hash.includes('library')) window.location.hash = '';
                if (rootGetters['builder/editorConfigs']?.locked) {
                    commit('builder/setShowNoticeLockmode', true, { root: true });
                }

                confirmExit(false);
            })
            .catch((e: Error) => {
                dispatch('setInsert', { isOpen: false });
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                setPopup(commit, false);
                commit('builder/setPopup', {
                    show: true, loading: false, title: $t('notice'), message: e.message, closeable: true,
                }, { root: true });
            });
    },

    // ── Task ──────────────────────────────────────────────────────────────────

    handleEditTask(this: CtxW, { commit, dispatch, rootGetters }: Ctx, payload: string | number): void {
        commit('global/setProgress', { show: true, percent: 10 }, { root: true });
        setPopup(commit, true);
        dispatch('setInsert', { isOpen: false });

        this.$worker
            .fetch(window.route(API_ROUTES.TASK, payload))
            .then((response: any) => {
                dispatch('setInsert', { isOpen: false });
                if (response.data.status !== 'success') throw new Error(response.data.message ?? $t('unknown_error'));

                const params = rootGetters['page/params'];
                dispatch('page/setQueryParams', { post_id: payload, page: params.page }, { root: true });
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                setPopup(commit, false);

                const opts = response.data.task?.options;
                if (opts?.data) {
                    let dataLayout: any = JSON.parse(opts.data);
                    if (typeof dataLayout === 'string') dataLayout = JSON.parse(dataLayout);

                    commit('page/setSections', { data: dataLayout.sections, keepId: true }, { root: true });

                    if (dataLayout.global_css) {
                        delete dataLayout.global_css.themeSettings;
                        dispatch('page/setDataGlobal', dataLayout.global_css, { root: true });
                    }

                    if (dataLayout.settings) {
                        commit('page/setSettings', dataLayout.settings, { root: true });
                    } else if (dataLayout.custom_code) {
                        commit('page/setSettings', { custom_code: dataLayout.custom_code }, { root: true });
                    }

                    if (opts.ai_fields) {
                        try {
                            const aiFields = JSON.parse(opts.ai_fields || '{}');
                            if (aiFields) commit('ai/setFields', aiFields, { root: true });
                        } catch { /* ignore */ }
                    }
                } else {
                    commit('page/setSections', { data: [] }, { root: true });
                }
            })
            .catch((e: Error) => {
                dispatch('setInsert', { isOpen: false });
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                toastErr(dispatch, e);
            });
    },

    saveAsTask(this: CtxW, { commit, dispatch }: Ctx, payload: string | number): void {
        dispatch('setInsert', { isOpen: false });
        dispatch('setInsert', { isOpen: true, current: 'my_task', type: 'library' });
        commit('showSaveForm', true);
        commit('detailTask', false);
        commit('setStatus', { success: null, error: null });
        commit('global/setProgress', { show: false, percent: 10 }, { root: true });

        this.$worker
            .fetch(window.route(API_ROUTES.TASK, payload))
            .then((response: any) => {
                if (response.data.status !== 'success') throw new Error(response.data.message ?? $t('unknown_error'));
                commit('setDetailPost', response.data.task);
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                confirmExit(false);
            })
            .catch((e: Error) => {
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                toastErr(dispatch, e);
            });
    },

    updateTask(this: CtxW, { commit, getters, dispatch }: Ctx, payload: SaveTaskPayload): void {
        if (getters['loadingSave']) return;
        commit('setStatus', { loadingSave: true });
        commit('global/setProgress', { show: false, percent: 10 }, { root: true });

        this.$worker
            .fetch(window.route(API_ROUTES.TASK_UPDATE, payload.id), payload.formData, 'POST')
            .then((response: any) => {
                if (response.data.code !== 200) throw new Error(response.data.message ?? $t('unknown_error'));
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                commit('setDetailPost', response.data.task);
                commit('setStatus', { success: response.data.status, loadingSave: false });
                if (typeof payload.callback === 'function') payload.callback();
                toastOk(dispatch, $t('update_layout_successfully'));
            })
            .catch((e: any) => {
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                commit('setStatus', { errors: e.response, loadingSave: false });
                toastErr(dispatch, e);
            });
    },

    // ── Template CRUD ─────────────────────────────────────────────────────────

    updateTemplate(this: CtxW, { commit, dispatch }: Ctx, payload: SaveTaskPayload): void {
        commit('global/setProgress', { show: false, percent: 10 }, { root: true });

        this.$worker
            .fetch(window.route(API_ROUTES.TEMPLATE, payload.id), payload.formData, 'POST')
            .then((response: any) => {
                if (response.data.code !== 200) throw new Error(response.data.message ?? $t('unknown_error'));
                commit('setStatus', { success: response.data.message });
                confirmExit(false);
            })
            .catch((e: Error) => {
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                toastErr(dispatch, e);
            });
    },

    createTemplate(this: CtxW, { commit, dispatch, rootGetters }: Ctx, payload: SaveTaskPayload): void {
        commit('global/setProgress', { show: true, percent: 10 }, { root: true });

        this.$worker
            .fetch(window.route(API_ROUTES.TEMPLATE_CREATE), payload.formData, 'POST')
            .then((response: any) => {
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
                if (response.data.status !== 'success') {
                    const msg = response.data?.message;
                    const translateData = response.data?.translate_data || {};
                    // Ensure plan_title is present for i18n interpolation
                    if (!translateData.plan_title) {
                        const globalUser = rootGetters['global/user'];
                        console.log(globalUser);

                        translateData.plan_title = globalUser?.plan?.name || 'Free';
                    }
                    dispatch(
                        "upgrade/showUpgradePopup",
                        {
                            feature_key: "templates",
                            source_location: "save_template",
                            message: msg ? $t(msg, translateData) : "",
                        },
                        { root: true }
                    );
                    toastErr(dispatch, { message: response.data?.message });
                    throw new Error(
                        response.data.message ? response.data.message : $t("unknown_error")
                    );
                }
                commit('showSaveForm', false);
                toastOk(dispatch, $t('your_template_has_been_created'));
                if (typeof payload.callback === 'function') payload.callback();
            })
            .catch(() => {
                commit('global/setProgress', { show: false, percent: 100 }, { root: true });
            });
    },

    handleRemoveTemplate(this: CtxW, { dispatch }: Ctx, payload: RemoveTemplatePayload): void {
        const ids = Array.isArray(payload.values) ? payload.values : [payload.values];

        this.$worker
            .fetch(window.route(API_ROUTES.TEMPLATES_DELETE), { ids }, 'DELETE')
            .then((res: any) => {
                if (res.data.status !== 'success') return;
                toastOk(dispatch, $t('templates_deleted_successfully'));
                if (typeof payload.callback === 'function') payload.callback();
            });
    },

    // ── Save form ─────────────────────────────────────────────────────────────

    saveAsLibrary({ dispatch, commit }: Ctx): void {
        dispatch('initAsync');
        dispatch('setInsert', { isOpen: false, tab: 'my_templates', mode: 'library' });
        dispatch('load', { routes: 'my_templates' });
        commit('showSaveForm', true);
        commit('detailTask', false);
    },

    closeSaveForm({ commit }: Ctx): void {
        commit('showSaveForm', false);
    },

    // ── Favorite ─────────────────────────────────────────────────────────────

    handleFavorite(this: CtxW, { commit, dispatch }: Ctx, payload: FavoritePayload) {
        commit('global/setProgress', { show: true, percent: 100 }, { root: true });

        return this.$worker
            .fetch(window.route(API_ROUTES.FAVORITE), { id: payload.value, status: payload.status }, 'POST')
            .then((res: any) => {
                if (res.data.status === 'success') {
                    commit('global/setProgress', { show: true, percent: 100 }, { root: true });
                    commit('favorites', res.data.favorites);
                    toastOk(dispatch, payload.status === 'active' ? $t('added_to_favorites') : $t('removed_from_favorites'));
                } else if (res.data.status === 'error') {
                    toastErr(dispatch, { message: $t(res.data.message) });
                }
            })
            .catch((e: Error) => toastErr(dispatch, e));
    },
};